INSERT INTO "drug_dosage_form" VALUES(128, 'Pen Cartridge', 'Pen Cartridge, Penfill', 'insulin-device.svg', 'INJ.', 'INJECTION', '(Pen Cartridge)', 'pen cartridge', 1, 1, 'INJ. [NAME] strength (Pen Cartridge)', 'INJECTION [NAME] strength (Pen Cartridge)', '[Generic_name] strength pen cartridge', 6);
INSERT INTO "drug_dosage_form" VALUES(129, 'Raw Materials', 'Raw Materials', 'fallback.svg', '', '', '', '', 1, 1, '[NAME] strength', '[NAME] strength', '[Generic_name] strength', 999);
INSERT INTO "drug_generic" VALUES(1, '5-Fluorouracil (5-FU)', 'Fluorouracil', 'L01BC02', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Fatal Toxicity Risk", "severity": "High", "trigger_condition": "Patients with Dihydropyrimidine Dehydrogenase (DPD) deficiency", "message": "STOP: Severe and potentially fatal toxicity (mucositis, diarrhea, neutropenia, neurotoxicity) can occur in patients with complete or partial DPD deficiency. Withhold or permanently discontinue."}, {"alert_type": "Cardiotoxicity", "severity": "High", "trigger_condition": "Development of chest pain, arrhythmias, or heart failure", "message": "STOP: Fluorouracil can cause severe cardiotoxicity, including myocardial infarction and ischemia. Withhold therapy immediately if cardiac symptoms occur."}]', '**Dihydropyrimidine Dehydrogenase (DPD) Deficiency:** Patients with certain homozygous or compound heterozygous variants in the DPYD gene are at increased risk for acute early-onset toxicity and serious, including fatal, adverse reactions (e.g., mucositis, diarrhea, neutropenia, and neurotoxicity). Withhold or permanently discontinue based on clinical assessment.
INSERT INTO "drug_generic" VALUES(2, 'Niacin (nicotinic acid)', 'Niacin', 'C10AD02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "High doses or substitution of sustained-release for immediate-release formulations", "message": "STOP: Severe hepatic toxicity, including fulminant hepatic necrosis, has occurred in patients substituting sustained-release niacin for immediate-release niacin at equivalent doses. Do not substitute formulations without dose adjustment and monitoring."}]', '- **Hepatic Impairment:** Use with extreme caution in patients with a history of jaundice, hepatobiliary disease, or unexplained transaminase elevations. Monitor LFTs frequently.
INSERT INTO "drug_generic" VALUES(3, 'Hydrocortisone 1% + Miconazole Nitrate 2% Topical', 'Hydrocortisone and Miconazole', 'D01AC20', 0, 0, 0, 0, 0, 1, 1, 0, '[]', 'For external use only. Discontinue therapy if sensitization or severe irritation occurs. Use with caution when applied to extensive surface areas or under occlusive dressings (including baby napkins/diapers), as this increases the risk of systemic corticosteroid absorption. Application to the face should be avoided to prevent steroid-induced rosacea or perioral dermatitis. Prolonged use may lead to skin atrophy or overgrowth of non-susceptible organisms.', '- **Inflammatory Fungal Infections:** Topical treatment of inflammatory skin conditions where a susceptible fungal infection (dermatophyte or Candida) is present or suspected, such as intertrigo, athlete''s foot (tinea pedis), jock itch (tinea cruris), and ringworm (tinea corporis) accompanied by severe inflammation or pruritus.', '**Viral Skin Infections:** Contraindicated in viral diseases of the skin such as herpes simplex, vaccinia, and varicella (chickenpox). Rationale: Corticosteroids suppress local immunity and can cause severe exacerbation of viral infections.
INSERT INTO "drug_generic" VALUES(4, 'Evolocumab', 'Evolocumab', 'C10AX13', 0, 0, 0, 1, 0, 1, 1, 0, '[]', '**Hypersensitivity Reactions:** Serious hypersensitivity reactions, including rash, urticaria, and anaphylaxis, have been reported. If signs or symptoms of a serious allergic reaction occur, discontinue treatment immediately, treat according to standard of care, and monitor until signs and symptoms resolve.
INSERT INTO "drug_generic" VALUES(5, 'Apis mellifica + Gelsemium sempervirens + Gnaphalium', 'Apis mellifica, Gelsemium sempervirens, and Gnaphalium', 'V03AX', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Low", "trigger_condition": "Application to compromised skin", "message": "For external use only. Do not use on open wounds, cuts, damaged, or infected skin. Avoid contact with eyes."}]', '**Symptom Persistence:** If symptoms persist for more than 7 days or worsen, consult a physician, as this may indicate a more serious underlying condition (e.g., severe diabetic neuropathy requiring systemic treatment).
INSERT INTO "drug_generic" VALUES(6, 'Mesna Disulfide', 'Mesna', 'V03AF01', 0, 0, 1, 0, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Administration of Mesna", "message": "Severe hypersensitivity reactions, including anaphylaxis, have been reported. Patients with autoimmune disorders may be at increased risk. Discontinue immediately if a severe reaction occurs."}]', 'Mesna provides protection only to the urinary tract against oxazaphosphorine-induced toxicity; it does not prevent other toxicities (e.g., myelosuppression, neurotoxicity) associated with ifosfamide or cyclophosphamide. Maintain adequate hydration (at least 1 liter of oral or IV fluid daily) to ensure adequate urine output. Monitor urine for erythrocytes and hematuria daily. The IV formulation may contain benzyl alcohol as a preservative; avoid use in neonates or infants due to the risk of fatal ''gasping syndrome''. If a patient vomits within 2 hours of an oral dose, the dose must be repeated or administered intravenously.', '- **Urothelial Toxicity Prophylaxis:** Prevention of ifosfamide-induced hemorrhagic cystitis.
INSERT INTO "drug_generic" VALUES(7, 'Estradiol topical', 'Estradiol', 'G03CA03', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Cardiovascular and Malignancy Risk", "severity": "High", "trigger_condition": "Use of unopposed estrogen in women with an intact uterus or history of cardiovascular disease", "message": "STOP: Estrogens increase the risk of endometrial cancer, deep vein thrombosis (DVT), stroke, and myocardial infarction. Do not use for the prevention of cardiovascular disease or dementia."}]', '**Endometrial Cancer:** Increased risk with unopposed estrogen therapy in women with a uterus. Add a progestogen to reduce the risk of endometrial hyperplasia. Perform diagnostic measures for undiagnosed abnormal genital bleeding.
INSERT INTO "drug_generic" VALUES(8, 'Methyldopa', 'Methyldopa', 'C02AB01', 0, 0, 1, 1, 1, 0, 1, 1, '[{"alert_type": "Hematologic and Hepatic Toxicity", "severity": "High", "trigger_condition": "Prolonged therapy or pre-existing liver disease", "message": "STOP: Positive Coombs test, hemolytic anemia, and severe hepatic necrosis can occur. Perform baseline and periodic blood counts and liver function tests."}]', 'Monitor complete blood count (CBC), direct Coombs test, and liver enzymes prior to initiation and periodically during the first 6 to 12 weeks of therapy or if unexplained fever occurs. Discontinue immediately if hemolytic anemia or hepatic dysfunction develops. Use with extreme caution in patients with a history of depression, as it may precipitate severe depressive episodes. Caution is advised in patients with Parkinsonism, as it may exacerbate extrapyramidal symptoms. May cause significant sedation and orthostatic hypotension; advise patients to avoid driving or operating heavy machinery until the effects are known. Not recommended for the treatment of pheochromocytoma. Taper dose gradually upon discontinuation to prevent rebound hypertension.', '- Management of moderate to severe essential hypertension.
INSERT INTO "drug_generic" VALUES(9, 'Carbonyl Iron + Folic Acid', 'Carbonyl Iron / Folic Acid', 'B03AD', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Fatal Pediatric Poisoning", "severity": "High", "trigger_condition": "Accidental ingestion by children under 6 years", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Iron Overload:** Care should be taken in patients who may develop iron overload, such as those with hemochromatosis, hemolytic anemia, or red cell aplasia.
INSERT INTO "drug_generic" VALUES(10, 'Lurbinectedin', 'Lurbinectedin', 'L01CX', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Myelosuppression", "severity": "High", "trigger_condition": "Prior to each administration", "message": "STOP: Can cause severe myelosuppression. Initiate treatment only if baseline absolute neutrophil count (ANC) is ≥1,500 cells/mm3 and platelet count is ≥100,000/mm3. Monitor blood counts prior to each dose."}, {"alert_type": "Extravasation Risk", "severity": "High", "trigger_condition": "During IV infusion", "message": "Extravasation resulting in severe tissue necrosis can occur. Consider use of a central venous catheter. If extravasation occurs, immediately discontinue the infusion."}]', '**Hepatotoxicity:** Can cause hepatotoxicity. Monitor liver function tests (ALT, AST, bilirubin) prior to initiating, periodically during treatment, and as clinically indicated. Withhold, reduce the dose, or permanently discontinue based on severity.
INSERT INTO "drug_generic" VALUES(11, 'Erenumab', 'Erenumab-aooe', 'N02CD01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "Moderate", "trigger_condition": "Administration of injection", "message": "Hypersensitivity reactions (e.g., rash, angioedema, anaphylaxis) have been reported. These may occur within hours or up to one week following administration. Discontinue if a serious reaction occurs."}]', '**Hypersensitivity Reactions:** Hypersensitivity reactions, including rash, angioedema, and anaphylaxis, have been reported. These reactions may occur within hours or up to one week following administration. If a serious or severe hypersensitivity reaction occurs, discontinue administration and initiate appropriate medical therapy.
INSERT INTO "drug_generic" VALUES(12, 'Disodium Hydrogen Phosphate Dodecahydrate 24% + Sodium Dihydrogen Phosphate Dihydrate 54.22%', 'Sodium Phosphate, Dibasic and Sodium Phosphate, Monobasic', 'A06AD17', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Acute Phosphate Nephropathy and Fatal Electrolyte Shifts", "severity": "High", "trigger_condition": "Inadequate hydration, renal impairment, or concurrent use of ACEI/ARB/NSAIDs", "message": "STOP: Rare but fatal cases of acute phosphate nephropathy, severe electrolyte abnormalities (hypocalcemia, hyperphosphatemia), and cardiac arrhythmias have occurred. Aggressive oral hydration is absolutely mandatory before, during, and after administration."}]', '- **Hydration is Critical:** Patients must consume adequate clear liquids (at least 2 quarts) during the bowel preparation process. Inadequate fluid intake can lead to excessive fluid loss, hypovolemia, and severe dehydration.
INSERT INTO "drug_generic" VALUES(13, 'Latanoprost .005% + Timolol 0.5% Eye prep', 'Latanoprost and Timolol Ophthalmic', 'S01ED51', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Systemic Beta-Blocker Effects", "severity": "High", "trigger_condition": "Patients with reactive airway disease or severe cardiac disease", "message": "STOP: Contains timolol, a non-selective beta-blocker. Systemic absorption can cause fatal bronchospasm in asthma/COPD patients and severe bradycardia/heart block in cardiac patients."}]', '**Systemic Absorption:** Timolol can be absorbed systemically, leading to severe cardiovascular (bradycardia, heart block) and pulmonary (bronchospasm) reactions.
INSERT INTO "drug_generic" VALUES(14, 'Vitamin A + D + C + Vitamin B-complex Paediatric prep', 'Multivitamin Pediatric Drops', 'A11BA', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'When multivitamin preparations are prescribed, allowance must be made for vitamins obtained from other dietary or supplemental sources to prevent cumulative toxicity. Monitor for signs of hypervitaminosis A and D, especially in infants receiving fortified formulas. Use with caution in patients with malabsorption syndromes, as absorption of fat-soluble vitamins (A and D) may be impaired.', '- **Vitamin Deficiency:** Prevention and treatment of multivitamin deficiencies in infants and children.
INSERT INTO "drug_generic" VALUES(15, 'Quinupristin + Dalfopristin', 'Quinupristin/Dalfopristin', 'J01FG02', 1, 0, 1, 0, 0, 0, 0, 0, '[{"alert_type": "Drug Interaction Risk", "severity": "High", "trigger_condition": "Concurrent use of CYP3A4 substrates", "message": "Quinupristin/Dalfopristin is a potent inhibitor of CYP3A4. Concurrent use with drugs metabolized by CYP3A4 that prolong the QT interval (e.g., cisapride, astemizole) is contraindicated due to the risk of life-threatening ventricular arrhythmias."}]', '**Hepatic Impairment:** Use with caution in patients with hepatic impairment. Dose reduction may be necessary, and liver function tests (bilirubin, AST, ALT) should be monitored, as hyperbilirubinemia is a common adverse effect.
INSERT INTO "drug_generic" VALUES(16, 'Treosulfan', 'Treosulfan', 'L01AB02', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Profound Myelosuppression", "severity": "High", "trigger_condition": "Standard conditioning regimen administration", "message": "STOP: Treosulfan causes profound, irreversible myelosuppression. It must only be administered as a conditioning regimen prior to allogeneic hematopoietic stem cell transplantation (alloHSCT). Stem cell rescue is mandatory."}]', '**Profound Myelosuppression:** Treosulfan causes severe, intentional, and irreversible bone marrow suppression (pancytopenia). It must only be used in the context of conditioning prior to stem cell rescue. Monitor blood counts continuously until hematopoietic recovery occurs. Provide aggressive supportive care (transfusions, broad-spectrum antimicrobials) during the aplastic phase.
INSERT INTO "drug_generic" VALUES(17, 'Fenticonazole Nitrate 2%', 'Fenticonazole', 'G01AF12', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '**Sensitization:** Prolonged use of topical products may cause sensitization or local irritation. Discontinue treatment if sensitization, severe irritation, or an allergic reaction occurs.
INSERT INTO "drug_generic" VALUES(18, 'Eptacog Alfa', 'Coagulation Factor VIIa (Recombinant)', 'B02BD08', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Thrombotic Events", "severity": "High", "trigger_condition": "Use in patients with advanced atherosclerotic disease, crush injury, septicemia, or concomitant use of aPCCs", "message": "STOP: Serious arterial and venous thrombotic events have been reported following the administration of recombinant Factor VIIa. Monitor patients closely for signs of myocardial infarction, stroke, pulmonary embolism, or deep vein thrombosis."}]', '**Thrombotic Risk:** Use with extreme caution in patients with a history of coronary artery disease, severe liver disease, postoperative status, or those at risk for disseminated intravascular coagulation (DIC). 
INSERT INTO "drug_generic" VALUES(19, 'Naphazoline Nitrate 0.005% + Zinc Sulphate 0.02% Eye prep', 'Naphazoline / Zinc Sulfate Ophthalmic', 'S01GA51', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Rebound Congestion and Systemic Absorption", "severity": "Moderate", "trigger_condition": "Prolonged use (>72 hours) or use in young children", "message": "STOP: Prolonged use of topical ocular decongestants can lead to rebound hyperemia (redness). Systemic absorption, particularly in infants and young children, can cause severe central nervous system depression, hypothermia, and coma. Do not use in infants."}]', '- **Cardiovascular Disease:** Use with caution in patients with hypertension, cardiovascular diseases, or arrhythmias, as systemic absorption of naphazoline can cause sympathomimetic effects.
INSERT INTO "drug_generic" VALUES(20, 'Folic Acid + Vitamin B6 + Vitamin B12', 'Folic Acid, Pyridoxine, and Cyanocobalamin', 'B03BA51', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Masking of Pernicious Anemia:** Folic acid in doses above 0.1 mg daily may obscure pernicious anemia. Hematologic remission can occur while neurological manifestations remain progressive. The inclusion of Vitamin B12 in this combination helps mitigate this risk.
INSERT INTO "drug_generic" VALUES(21, 'Lamivudine', 'Lamivudine', 'J05AF05', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Hepatomegaly and Lactic Acidosis", "severity": "High", "trigger_condition": "Development of clinical or laboratory findings suggestive of lactic acidosis or pronounced hepatotoxicity", "message": "Lactic acidosis and severe hepatomegaly with steatosis, including fatal cases, have been reported. Discontinue immediately if these occur."}, {"alert_type": "Hepatitis B Exacerbation", "severity": "High", "trigger_condition": "Discontinuation of therapy in patients co-infected with Hepatitis B", "message": "Severe acute exacerbations of Hepatitis B have been reported in patients who discontinue lamivudine. Monitor hepatic function closely for at least several months after stopping treatment."}]', 'Discontinue use if there is a rapid increase in aminotransferase levels, progressive hepatomegaly, or metabolic/lactic acidosis of unknown origin. Discontinue use if clinical signs, symptoms, or laboratory abnormalities suggestive of pancreatitis develop (especially in pediatric patients). Use with caution in patients with hepatomegaly or other risk factors for hepatic impairment. Exclude HIV infection prior to initiating monotherapy for Hepatitis B, as lower doses used for HBV can lead to HIV resistance. Dosage adjustment is required in renal impairment.', '- **HIV-1 Infection:** Treatment of HIV-1 infection in combination with other antiretroviral agents.
INSERT INTO "drug_generic" VALUES(22, 'Glycerine .75 ml + Liquid Sugar 1.93 ml', 'Glycerin and Sucrose', 'Data not available', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Diabetic Patients:** This preparation contains a significant amount of liquid sugar (carbohydrates). Blood glucose levels should be monitored, and the carbohydrate content must be factored into the patient''s daily dietary allowance.
INSERT INTO "drug_generic" VALUES(23, 'Clotrimazole Eye prep', 'Clotrimazole Ophthalmic', 'Data not available', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Local Intolerance", "severity": "Medium", "trigger_condition": "Development of severe ocular irritation or hypersensitivity", "message": "If local intolerance, severe burning, or hypersensitivity develops, discontinue the medication immediately and institute appropriate alternative antifungal therapy."}]', '**Pediatric Use:** Safety and efficacy have not been established in children under 3 years of age.
INSERT INTO "drug_generic" VALUES(24, 'Deutetrabenazine', 'Deutetrabenazine', 'N07XX11', 0, 1, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Depression and Suicidality", "severity": "High", "trigger_condition": "Patients with Huntington''s disease", "message": "STOP: Increases the risk of depression and suicidal thoughts/behavior in patients with Huntington''s disease. Contraindicated in patients who are suicidal or have untreated/inadequately treated depression."}]', '**Depression and Suicidality:** Increases the risk of depression and suicidal thoughts and behavior in patients with Huntington''s disease. Balance the risks with the clinical need for chorea treatment. Monitor closely for emergence or worsening of depression or suicidality.
INSERT INTO "drug_generic" VALUES(25, 'Rabies Immunoglobulin USP', 'Rabies Immune Globulin', 'J06BB05', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Administration to patients with IgA deficiency or history of hypersensitivity to human immune globulins", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, can occur. Epinephrine must be immediately available during administration."}]', '**Hypersensitivity:** Hypersensitivity to human immune globulin preparations can occur. Patients with specific IgA deficiency are at increased risk of developing antibodies to IgA and experiencing anaphylactic reactions. Epinephrine should be available for the management of possible anaphylaxis.
INSERT INTO "drug_generic" VALUES(26, 'Docusate Sodium ear prep', 'Docusate Sodium otic solution', 'S02DC', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Local Irritation:** If pain, inflammation, or severe stinging is experienced upon application, treatment should be discontinued immediately and the ear evaluated by a physician.
INSERT INTO "drug_generic" VALUES(27, 'Rifaximin', 'Rifaximin', 'A07AA11', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Inefficacy in Invasive Infection", "severity": "High", "trigger_condition": "Patient presenting with fever or bloody diarrhea", "message": "STOP: Rifaximin is not effective for diarrhea complicated by fever or blood in the stool, or diarrhea caused by pathogens other than E. coli. Discontinue and use alternative systemic antibiotics."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Has been reported with nearly all antibacterial agents, including rifaximin. Evaluate patients who present with diarrhea subsequent to administration.
INSERT INTO "drug_generic" VALUES(28, 'Zolmitriptan Nasal prep', 'Zolmitriptan Nasal Spray', 'N02CC03', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cardiovascular Events", "severity": "High", "trigger_condition": "Patients with underlying cardiovascular disease or risk factors", "message": "STOP: Serious and potentially fatal cardiac events, including myocardial infarction and arrhythmias, have occurred following triptan use. Contraindicated in patients with ischemic heart disease or uncontrolled hypertension."}]', '**Cardiovascular Risk:** Evaluate patients with cardiovascular risk factors prior to initiation. Administer the first dose under medical supervision if risk factors are present.
INSERT INTO "drug_generic" VALUES(29, 'Benzyl Alcohol topical', 'Benzyl Alcohol', 'P03AX06', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Neonatal Toxicity (Gasping Syndrome)", "severity": "High", "trigger_condition": "Use in infants <6 months of age", "message": "STOP: Systemic exposure to benzyl alcohol has been associated with fatal ''Gasping Syndrome'' in neonates and low birth-weight infants. Do NOT use in children under 6 months of age."}]', '**Eye Irritation:** Avoid eye exposure. May cause severe eye irritation. If the lotion comes into contact with the eyes, flush immediately with water.
INSERT INTO "drug_generic" VALUES(30, 'Cyanocobalamin (Vitamin B12)', 'Cyanocobalamin', 'B03BA01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Hypokalemia and Sudden Death", "severity": "High", "trigger_condition": "Intensive treatment of severe megaloblastic anemia", "message": "Intensive treatment of B12-deficient megaloblastic anemia can cause a rapid intracellular shift of potassium, leading to severe hypokalemia and sudden death. Monitor serum potassium closely during early therapy."}]', '**Leber''s Optic Atrophy:** Cyanocobalamin is contraindicated in early Leber''s disease (hereditary optic nerve atrophy), as it can cause severe and swift optic atrophy. Hydroxocobalamin is the preferred form of B12 in these patients.
INSERT INTO "drug_generic" VALUES(31, 'Dextrose 10% + Sodium Chloride 0.225%', 'Dextrose 10% and 0.225% Sodium Chloride', 'B05BB02', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hyponatremia and Hyperglycemia", "severity": "High", "trigger_condition": "Prolonged infusion or use in neonates", "message": "STOP: This solution is hypotonic with respect to sodium. Prolonged use can cause severe hyponatremia and water intoxication. High dextrose content risks hyperglycemia, especially in neonates."}]', '**Hyponatremia Risk:** Contains only 38.5 mEq/L of sodium (hypotonic relative to plasma sodium). Excessive administration can lead to dilutional hyponatremia, water intoxication, and cerebral edema.
INSERT INTO "drug_generic" VALUES(32, 'Latanoprostene bunod eye prep', 'Latanoprostene bunod', 'S01EE06', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Pigmentation Changes", "severity": "Medium", "trigger_condition": "Long-term use", "message": "WARNING: Gradual and potentially permanent increased pigmentation of the iris and periorbital tissue (eyelid) can occur. Patients should be informed of this possibility before initiating therapy."}]', '**Pigmentation Changes:** Increased pigmentation of the iris and periorbital tissue (eyelid) may occur. Iris pigmentation changes may be permanent. Regularly examine patients who develop noticeably increased iris pigmentation.
INSERT INTO "drug_generic" VALUES(33, 'Tetanus (Human Anti-tetanus) Immunoglobulin', 'Tetanus Immune Globulin (Human)', 'J06BB02', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Administration Route", "severity": "High", "trigger_condition": "Preparation for administration", "message": "STOP: Do NOT administer intravenously (IV). Administer strictly via intramuscular (IM) injection to avoid severe systemic reactions, including anaphylaxis."}]', '**Coagulation Disorders:** Administer with caution in patients with thrombocytopenia or severe coagulation disorders due to the risk of bleeding/hematoma following IM injection.
INSERT INTO "drug_generic" VALUES(34, 'Nateglinide', 'Nateglinide', 'A10BX03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hypoglycemia Risk", "severity": "High", "trigger_condition": "Skipped meals, excessive exercise, or concurrent use of other hypoglycemic agents", "message": "STOP: Nateglinide stimulates insulin secretion and can cause hypoglycemia. Patients must take the dose immediately before a meal. If a meal is skipped, the corresponding dose of nateglinide MUST be skipped to avoid severe hypoglycemia."}]', '- **Hypoglycemia:** All patients are at risk for hypoglycemia. Proper patient selection, dosage, and instructions are important. Geriatric, debilitated, or malnourished patients, and those with adrenal or pituitary insufficiency are particularly susceptible.
INSERT INTO "drug_generic" VALUES(35, 'Paracetamol + Caffeine', 'Acetaminophen and Caffeine', 'N02BE51', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Exceeding maximum daily dose or concurrent alcohol use", "message": "STOP: Severe liver damage may occur if the patient takes more than the maximum daily dose, takes it with other paracetamol-containing products, or consumes 3 or more alcoholic drinks daily."}]', '**Hepatotoxicity:** Paracetamol can cause severe, potentially fatal liver damage. The risk is increased in patients with underlying liver disease, chronic alcoholism, or malnutrition. Do not exceed the maximum daily dose.
INSERT INTO "drug_generic" VALUES(36, 'Aminophylline', 'Aminophylline', 'R03DA05', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Narrow Therapeutic Index and Toxicity", "severity": "High", "trigger_condition": "Rapid IV administration or excessive dosing", "message": "STOP: Aminophylline has a narrow therapeutic index. Rapid IV injection can cause fatal cardiac arrhythmias, severe hypotension, and intractable seizures. MUST be given slowly (over at least 20-30 minutes) and serum levels must be monitored."}]', '**Cardiac Disease:** Use with extreme caution in patients with cardiac arrhythmias, coronary artery disease, or severe hypertension, as it can exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(37, 'Cobimetinib', 'Cobimetinib', 'L01EE02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiomyopathy", "severity": "High", "trigger_condition": "Decreased Left Ventricular Ejection Fraction (LVEF)", "message": "Risk of cardiomyopathy is increased. Evaluate LVEF before treatment, after one month, and every 3 months thereafter. Withhold or discontinue for significant LVEF drops."}, {"alert_type": "Hemorrhage", "severity": "High", "trigger_condition": "Signs of major bleeding", "message": "Major hemorrhagic events, including intracranial and gastrointestinal bleeding, can occur. Monitor for signs of bleeding and discontinue if severe."}]', '**New Primary Malignancies:** Cutaneous and non-cutaneous malignancies can occur, especially when used in combination with vemurafenib. Monitor patients for new malignancies prior to initiation of therapy, while on therapy, and for up to 6 months following the last dose.
INSERT INTO "drug_generic" VALUES(38, 'Cefadroxil', 'Cefadroxil', 'J01DB05', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(39, 'Methoxy Polyethyelene Glycol-Epoetin Beta (Pegylated Erythropoietin)', 'Methoxy Polyethylene Glycol-Epoetin Beta', 'B03XA03', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Cardiovascular and Thromboembolic Risk", "severity": "High", "trigger_condition": "Targeting hemoglobin levels >11 g/dL", "message": "STOP: Erythropoiesis-stimulating agents (ESAs) increase the risk of death, myocardial infarction, stroke, venous thromboembolism, and thrombosis of vascular access. Use the lowest dose sufficient to reduce the need for RBC transfusions."}]', 'Control hypertension adequately prior to initiation and monitor blood pressure closely during therapy; hypertensive encephalopathy and seizures have occurred. Monitor hemoglobin levels frequently (e.g., every 2 weeks) until stable. Do not increase the dose more frequently than once every 4 weeks. If severe anemia and low reticulocyte count develop, withhold the drug and evaluate for pure red cell aplasia (PRCA) due to neutralizing antibodies. ESAs may increase the risk of tumor progression and mortality in patients with cancer; this drug is not indicated for anemia due to cancer chemotherapy. Monitor for signs of deep vein thrombosis or pulmonary embolism.', '- Treatment of anemia associated with chronic kidney disease (CKD) in adult patients on dialysis and patients not on dialysis.', '- **Uncontrolled Hypertension:** Contraindicated as ESAs can cause a rapid rise in blood pressure, leading to hypertensive crisis or encephalopathy.
INSERT INTO "drug_generic" VALUES(40, 'Venlafaxine', 'Venlafaxine', 'N06AX16', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Suicidality Risk", "severity": "High", "trigger_condition": "Initiation of therapy or dose changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults (<24 years). Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '**Serotonin Syndrome:** Potentially life-threatening serotonin syndrome can occur, especially with concurrent use of other serotonergic drugs (e.g., SSRIs, SNRIs, triptans, tramadol). Monitor for mental status changes, autonomic instability, and neuromuscular abnormalities.
INSERT INTO "drug_generic" VALUES(41, 'Ritodrine Hydrochloride', 'Ritodrine', 'G02CA01', 0, 1, 1, 0, 1, 0, 0, 0, '[{"alert_type": "Maternal Pulmonary Edema", "severity": "High", "trigger_condition": "Intravenous infusion, especially with concurrent corticosteroids or fluid overload", "message": "STOP: Fatal maternal pulmonary edema has been reported. Monitor maternal hydration status, heart rate, and respiratory function continuously. Discontinue immediately if signs of pulmonary edema develop."}]', '**Cardiovascular Effects:** Can cause significant maternal tachycardia, palpitations, and hypotension. Monitor maternal pulse and blood pressure continuously during IV infusion. Adjust the infusion rate to keep the maternal heart rate below 140 beats/minute.
INSERT INTO "drug_generic" VALUES(42, 'Sodium Hyaluronate 0.1%, 0.2% Eye prep', 'Sodium Hyaluronate', 'S01KA01', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Intraocular Pressure (IOP):** Monitor intraocular pressure closely, especially when used as a surgical aid, as transient postoperative spikes in IOP can occur due to mechanical blockage of the trabecular meshwork.
INSERT INTO "drug_generic" VALUES(43, 'Selpercatinib', 'Selpercatinib', 'L01EX22', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hepatotoxicity and Interstitial Lung Disease", "severity": "High", "trigger_condition": "During therapy", "message": "STOP: Severe hepatotoxicity and life-threatening interstitial lung disease (ILD)/pneumonitis can occur. Monitor AST/ALT and pulmonary symptoms closely. Withhold, dose reduce, or permanently discontinue based on severity."}]', '**Hepatotoxicity:** Can cause hepatotoxicity, including increased AST/ALT. Evaluate AST/ALT prior to therapy, every 2 weeks for 3 months, then monthly thereafter. Withhold, dose reduce, or permanently discontinue based on severity.
INSERT INTO "drug_generic" VALUES(44, 'Esomeprazole + Amoxicillin + Clarithromycin Kit', 'Esomeprazole + Amoxicillin + Clarithromycin', 'A02BD06', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Macrolide hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}, {"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Concomitant use with QT-prolonging drugs or history of arrhythmias", "message": "STOP: Clarithromycin has been associated with prolongation of the QT interval and infrequent cases of arrhythmia, including torsades de pointes."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported in patients on penicillin therapy. Cross-reactivity with cephalosporins may occur.
INSERT INTO "drug_generic" VALUES(45, 'Trypan Blue 0.06%', 'Trypan Blue', 'S01JA01', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Excess Dye Removal:** It is critical that after injection, all excess trypan blue be immediately and thoroughly removed from the eye by irrigating the anterior chamber. Failure to do so may result in unintended staining of ocular structures.
INSERT INTO "drug_generic" VALUES(46, 'Polyvinyl Alcohol', 'Polyvinyl Alcohol', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Contact Lenses:** Do not use while wearing soft contact lenses unless the specific product is explicitly labeled as safe for use with them, as preservatives in the drops may be absorbed by the lenses.
INSERT INTO "drug_generic" VALUES(47, 'Palbociclib', 'Palbociclib', 'L01EF01', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Severe Neutropenia", "severity": "High", "trigger_condition": "Initiation of therapy and throughout treatment cycles", "message": "STOP: Severe, life-threatening neutropenia can occur. Monitor complete blood counts (CBC) prior to starting therapy, at the beginning of each cycle, on Day 14 of the first 2 cycles, and as clinically indicated."}]', '- **Neutropenia:** Frequently observed in clinical trials, including grade 3 or 4 neutropenia and febrile neutropenia. Dose interruption, reduction, or delay in starting treatment cycles is recommended for patients who develop severe neutropenia.
INSERT INTO "drug_generic" VALUES(48, 'Lactase', 'Lactase', 'A09AA04', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Phenylketonuria (PKU):** Some chewable or orally disintegrating lactase products may contain aspartame, which is metabolized to phenylalanine. Patients with PKU should avoid these specific formulations or consult their physician.
INSERT INTO "drug_generic" VALUES(49, 'Pranlukast hydrate', 'Pranlukast', 'R03DC02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Churg-Strauss Syndrome", "severity": "High", "trigger_condition": "Development of eosinophilia, vasculitic rash, worsening pulmonary symptoms, cardiac complications, or neuropathy", "message": "STOP: Withdraw treatment immediately if patients show signs consistent with Churg-Strauss syndrome (eosinophilic granulomatosis with polyangiitis). Evaluate and manage promptly."}]', 'Monitor for possible elevations in liver enzymes during therapy. Use with caution in patients with renal impairment. Not indicated for the reversal of acute bronchospasm or acute asthma attacks; patients must be provided with appropriate rescue medication (e.g., short-acting beta-agonists).', '- **Asthma:** Indicated for the prophylaxis and chronic treatment of asthma.
INSERT INTO "drug_generic" VALUES(50, 'Chloramphenicol 5% + Lidocaine Hydrochloride 1%  Ear drops', 'Chloramphenicol and Lidocaine Otic', 'S02AA30', 1, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Ototoxicity Risk", "severity": "High", "trigger_condition": "Perforated tympanic membrane", "message": "STOP: Contraindicated in patients with a perforated eardrum. Introduction of these agents into the middle ear can cause severe ototoxicity and permanent hearing loss."}]', '**Systemic Absorption:** Although rare with otic use, systemic absorption of chloramphenicol can occur, leading to severe blood dyscrasias (aplastic anemia). Avoid prolonged or repeated courses of treatment.
INSERT INTO "drug_generic" VALUES(51, 'Dalfampridine', 'Dalfampridine', 'N07XX07', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Seizure Risk", "severity": "High", "trigger_condition": "History of seizures or moderate-to-severe renal impairment", "message": "STOP: Dalfampridine can cause seizures. It is strictly contraindicated in patients with a history of seizures or moderate-to-severe renal impairment (CrCl \u226450 mL/min). Permanently discontinue if a seizure occurs."}, {"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "Signs of severe allergic reaction", "message": "WARNING: Anaphylaxis and severe allergic reactions (respiratory compromise, urticaria, angioedema) have been reported. Discontinue immediately and do not restart."}]', '**Seizures:** Seizures have been reported, often within days to weeks of starting therapy, even in patients without a prior history. The risk is dose-dependent and significantly increased in renal impairment. Permanently discontinue if a seizure occurs.
INSERT INTO "drug_generic" VALUES(52, 'Bupivacaine + Dextrose', 'Bupivacaine and Dextrose', 'N01BB51', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Spinal Anesthesia Risks", "severity": "High", "trigger_condition": "Administration for spinal anesthesia", "message": "WARNING: Must be administered only by clinicians experienced in spinal anesthesia. Resuscitative equipment and drugs must be immediately available. High spinal block can cause severe hypotension, bradycardia, and respiratory arrest."}]', 'Use with caution in patients with hepatic disease, cardiovascular disease, or the elderly and debilitated, as they are more susceptible to systemic toxicity and hemodynamic instability.
INSERT INTO "drug_generic" VALUES(53, 'Podophyllotoxin 0.15%', 'Podofilox 0.15%', 'D06BB04', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Severe Local Reactions", "severity": "High", "trigger_condition": "Application to mucous membranes or excessive application", "message": "STOP: Do not apply to eyes, urethral, or cervical warts. Excessive application can lead to severe local tissue necrosis and systemic toxicity."}]', '**Application Site Reactions:** Avoid excessive application to prevent severe local tissue necrosis and potential systemic absorption.
INSERT INTO "drug_generic" VALUES(54, 'Palivizumab', 'Palivizumab', 'J06BB16', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Administration of monoclonal antibodies", "message": "Severe hypersensitivity reactions, including anaphylaxis, have been reported following palivizumab administration. Medications for the treatment of severe hypersensitivity reactions should be readily available."}]', '**Hypersensitivity Reactions:** Anaphylaxis and other acute hypersensitivity reactions have been reported. Permanently discontinue palivizumab if a severe hypersensitivity reaction occurs.
INSERT INTO "drug_generic" VALUES(55, 'Amphotericin B (Liposomal)', 'Amphotericin B Liposomal', 'J02AA01', 1, 1, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Infusion Reactions", "severity": "High", "trigger_condition": "Intravenous infusion", "message": "STOP: Severe infusion-related reactions (fever, chills, rigors, hypotension, hypoxia) can occur, usually 1-3 hours after starting. Premedication (antipyretics, antihistamines, corticosteroids) and slow infusion rates are recommended."}, {"alert_type": "Nephrotoxicity", "severity": "High", "trigger_condition": "Prolonged therapy or concurrent nephrotoxic drugs", "message": "STOP: Although less nephrotoxic than conventional amphotericin B deoxycholate, liposomal amphotericin B can still cause severe renal impairment and hypokalemia. Monitor serum creatinine and electrolytes frequently."}]', '**Appropriate Use:** Indicated for progressive and potentially fatal fungal infections. Do not use for noninvasive fungal infections (e.g., oral thrush, vaginal candidiasis) in patients with normal neutrophil counts.
INSERT INTO "drug_generic" VALUES(56, 'Mupirocin 2% Topical', 'Mupirocin', 'D06AX09', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Toxicity Risk", "severity": "Moderate", "trigger_condition": "Application of ointment formulation to extensive burns or open wounds in patients with renal impairment", "message": "WARNING: The ointment formulation contains polyethylene glycol (PEG). Absorption of large quantities of PEG through open wounds or burns can cause renal toxicity in patients with pre-existing moderate to severe renal impairment."}]', '**Prolonged Use:** As with other antibacterial products, prolonged use may result in the overgrowth of non-susceptible organisms, including fungi.
INSERT INTO "drug_generic" VALUES(57, 'Vonoprazan + Amoxicillin', 'Vonoprazan and Amoxicillin', 'A02BD', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur due to the amoxicillin component. Verify patient allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** May occur with amoxicillin therapy. Evaluate patients who present with severe diarrhea during or after treatment.
INSERT INTO "drug_generic" VALUES(58, 'Trandolapril + Verapamil', 'Trandolapril/Verapamil', 'C09BB10', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy", "message": "STOP: When pregnancy is detected, discontinue trandolapril/verapamil as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}]', '**Hypotension:** Excessive hypotension may occur, especially in patients with volume depletion, hyponatremia, or those on concomitant diuretics. Monitor blood pressure closely during initiation.
INSERT INTO "drug_generic" VALUES(59, 'Nitrofurantoin', 'Nitrofurantoin', 'J01XE01', 1, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Pulmonary Toxicity", "severity": "High", "trigger_condition": "Prolonged therapy (e.g., >6 months for prophylaxis)", "message": "STOP: Acute, subacute, or chronic pulmonary toxicity (including interstitial pneumonitis and pulmonary fibrosis) can occur. Monitor pulmonary function closely during prolonged therapy. Discontinue immediately if unexplained pulmonary symptoms develop."}]', 'Use with caution in the elderly due to age-related declines in renal function. Monitor hepatic and pulmonary function closely during prolonged therapy. Caution is advised in patients with pre-existing pulmonary, hepatic, or neurological disorders. Patients with conditions predisposing them to peripheral neuropathy (e.g., renal impairment, anemia, diabetes mellitus, electrolyte imbalance, debility, vitamin B deficiency) are at higher risk; withdraw the drug immediately if signs of peripheral neuropathy (numbness, tingling) occur.', '- **Acute Uncomplicated Urinary Tract Infections (Cystitis):** Treatment of acute cystitis caused by susceptible strains of *Escherichia coli*, *Enterococci*, *Staphylococcus aureus*, *Staphylococcus saprophyticus*, and certain susceptible strains of *Klebsiella* and *Enterobacter* species.
INSERT INTO "drug_generic" VALUES(60, 'Menthol 1% + Pramoxine Hydrochloride 1% Topical', 'Menthol / Pramoxine Topical', 'D04AB', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'For external use only. Avoid contact with eyes and mucous membranes. Do not apply to large areas of the body, deep or puncture wounds, animal bites, or serious burns. Not intended for prolonged use. Discontinue use and consult a healthcare provider if symptoms persist for more than 7 days, or if they clear up and occur again within a few days. Discontinue immediately if redness, irritation, swelling, or pain persists or increases.', '- **Pruritus and Pain:** Temporary relief of pain and itching associated with minor skin irritations, minor cuts, minor burns, minor sunburns, scrapes, or insect bites.
INSERT INTO "drug_generic" VALUES(61, 'Azelaic Acid 20% topical', 'Azelaic Acid', 'D10AX03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Hypopigmentation", "severity": "Medium", "trigger_condition": "Use in patients with dark complexions", "message": "STOP: Isolated cases of hypopigmentation have been reported. Monitor patients with dark complexions closely for early signs of skin lightening."}]', '**Skin Irritation:** Pruritus, burning, and stinging are common, especially during the first few weeks of treatment. If severe irritation persists, reduce the frequency of application to once daily or discontinue treatment temporarily.
INSERT INTO "drug_generic" VALUES(62, 'Tenoxicam', 'Tenoxicam', 'M01AC02', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Prolonged use or history of cardiovascular/GI disease", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation of the stomach or intestines."}]', '**Cardiovascular Risk:** May increase the risk of serious and potentially fatal cardiovascular thrombotic events, MI, and stroke. Risk increases with duration of use and in patients with underlying CV disease.
INSERT INTO "drug_generic" VALUES(63, 'Hydroquinone', 'Hydroquinone', 'D11AX11', 0, 0, 0, 0, 0, 1, 0, 0, '[]', 'Hydroquinone is a skin bleaching agent that may produce unwanted cosmetic effects if not used as directed. Test for skin sensitivity before use by applying a small amount to an unbroken patch of skin and checking in 24 hours. Minor redness is acceptable, but if itching, vesicle formation, or excessive inflammation occurs, discontinue use. Avoid contact with eyes and lips. Do not apply to cut, abraded, or sunburned skin. Limit sun exposure during and after treatment to prevent repigmentation; use a broad-spectrum sunscreen and protective clothing. Discontinue if no bleaching effect is noted after 2 months of treatment.', '- **Hyperpigmentation:** Gradual bleaching of hyperpigmented skin conditions such as chloasma, melasma, freckles, senile lentigines, and other unwanted areas of melanin hyperpigmentation.', '**Hypersensitivity:** Contraindicated in patients with a prior history of hypersensitivity or allergic reaction to hydroquinone or any ingredients in the preparation.
INSERT INTO "drug_generic" VALUES(64, 'Colchicine', 'Colchicine', 'M04AC01', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Fatal Toxicity and Drug Interactions", "severity": "High", "trigger_condition": "Concurrent use with strong CYP3A4 or P-gp inhibitors, especially in renal/hepatic impairment", "message": "WARNING: Fatal colchicine toxicity has occurred when co-administered with strong CYP3A4 or P-gp inhibitors (e.g., clarithromycin, cyclosporine). Reduce dose or interrupt therapy. Contraindicated in patients with renal or hepatic impairment taking these inhibitors."}]', '**Neuromuscular Toxicity and Rhabdomyolysis:** Colchicine-induced myoneuropathy and rhabdomyolysis have been reported, especially with long-term use, in the elderly, in patients with renal dysfunction, or when used concurrently with myotoxic drugs (e.g., statins, fibrates). Monitor for muscle pain or weakness.
INSERT INTO "drug_generic" VALUES(65, 'Cinchocaine HCI + Hydrocortisone + Framycetin Sulphate + Esculin (Rectal prep)', 'Dibucaine + Hydrocortisone + Framycetin + Esculin', 'C05AA01', 1, 0, 0, 0, 0, 1, 0, 0, '[]', '**Prolonged Use:** Avoid application for prolonged periods and to extensive areas. Long-term continuous treatment with topical corticosteroids may cause atrophic changes in the skin, leading to thinning, loss of elasticity, dilatation of superficial blood vessels, telangiectasia, and ecchymoses.
INSERT INTO "drug_generic" VALUES(66, 'Dimethicone topical', 'Dimethicone', 'D02AA01', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Ocular Exposure:** For external use only. Keep out of eyes. If contact occurs, rinse thoroughly with water.
INSERT INTO "drug_generic" VALUES(67, 'Aclidinium Bromide+ Formoterol Fumarate inhaler', 'Aclidinium bromide/Formoterol fumarate', 'R03AL05', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Asthma-Related Death and Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Use in asthma without an inhaled corticosteroid or use during acute bronchospasm", "message": "STOP: LABA monotherapy increases the risk of asthma-related death. This drug is NOT indicated for asthma. Do not use for acute bronchospasm. Discontinue immediately if paradoxical bronchospasm occurs."}]', '**Asthma-Related Death:** Use of LABAs as monotherapy (without inhaled corticosteroids) for asthma is associated with an increased risk of asthma-related death. This medication is not indicated for asthma.
INSERT INTO "drug_generic" VALUES(68, 'Vitamin C (Ascorbic Acid)', 'Ascorbic Acid', 'A11GA01', 0, 0, 1, 1, 1, 1, 1, 0, '[]', 'Use with caution in patients with a history of hyperoxaluria or renal calculi, as high doses of ascorbic acid can precipitate oxalate stones. Caution is advised in patients with G6PD deficiency, as large intravenous doses have been associated with hemolysis. May alter the results of blood and urine glucose tests.', '- **Scurvy:** Treatment and prevention of Vitamin C deficiency.
INSERT INTO "drug_generic" VALUES(69, 'Penicillamine', 'Penicillamine', 'M01CC01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Toxicity and Monitoring", "severity": "High", "trigger_condition": "Initiation of Penicillamine therapy", "message": "STOP: Penicillamine has a high incidence of severe and potentially fatal toxicities (aplastic anemia, agranulocytosis, Goodpasture''s syndrome, myasthenia gravis). Routine monitoring of blood counts and renal function is mandatory."}]', '**Hematologic Toxicity:** Can cause severe bone marrow depression, including aplastic anemia and agranulocytosis, which may be fatal. Perform complete blood counts (CBC) with differential and platelet counts twice weekly for the first month, then monthly.
INSERT INTO "drug_generic" VALUES(70, 'Dapsone', 'Dapsone', 'J04BA02', 1, 0, 1, 0, 0, 1, 1, 0, '[{"alert_type": "Hemolytic Anemia and Methemoglobinemia", "severity": "High", "trigger_condition": "Dose-dependent, or use in patients with G6PD deficiency", "message": "WARNING: Dapsone causes dose-related hemolysis and methemoglobinemia. Patients with G6PD deficiency are at high risk for severe hemolytic anemia. Monitor CBC and reticulocyte counts closely."}, {"alert_type": "Agranulocytosis and Severe Skin Reactions", "severity": "High", "trigger_condition": "Any patient on therapy", "message": "WARNING: Fatal agranulocytosis, toxic epidermal necrolysis (TEN), and Stevens-Johnson syndrome (SJS) have occurred. Discontinue immediately if a severe rash or signs of bone marrow suppression develop."}]', '**Dapsone Syndrome:** A hypersensitivity reaction characterized by fever, rash, lymphadenopathy, and hepatic involvement can occur, usually within the first 6 weeks of therapy. Discontinue immediately.
INSERT INTO "drug_generic" VALUES(71, 'Citric Acid + Potassium Citrate', 'Potassium Citrate and Citric Acid', 'G04BC', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Hyperkalemia Risk", "severity": "High", "trigger_condition": "Use in patients with renal impairment or concurrent use of potassium-sparing drugs", "message": "Can cause severe, potentially fatal hyperkalemia. Contraindicated in severe renal impairment, oliguria, or anuria. Monitor serum potassium closely."}]', '**Hyperkalemia:** Potassium intoxication can occur rapidly and may be asymptomatic. Use with extreme caution in patients with conditions predisposing to hyperkalemia (e.g., chronic renal failure, heart failure, severe tissue trauma).
INSERT INTO "drug_generic" VALUES(72, 'Selenium Sulfide topical', 'Selenium Sulfide', 'D01AE13', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Systemic Toxicity Risk", "severity": "Moderate", "trigger_condition": "Application to broken, inflamed, or exudative skin", "message": "Avoid application to broken or severely inflamed skin. Systemic absorption can occur, leading to selenium toxicity (tremors, weakness, abdominal pain)."}]', '**Mucous Membrane Exposure:** Avoid contact with all mucous membranes, including the eyes and lips. If contact occurs, rinse thoroughly with water.
INSERT INTO "drug_generic" VALUES(73, 'Dyclonine', 'Dyclonine', 'R02AD04', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Choking Hazard", "severity": "High", "trigger_condition": "Administration to young children", "message": "STOP: Lozenges are considered a severe choking hazard in young children. Do not use in children under 2 years of age."}]', 'Lozenges are considered a choking hazard in young children. Advise patients to discontinue use and seek medical advice if a sore throat is severe, lasts for more than 2 days, or occurs with (or is followed by) fever, headache, rash, nausea, or vomiting. Advise patients to discontinue use and seek medical advice if sore mouth symptoms last more than 7 days, or if irritation, pain, or redness continues or worsens.', '- **Pharyngitis and Sore Throat:** Indicated for the temporary relief of occasional mouth and throat symptoms, including minor irritation, pain, sore mouth, and sore throat.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to dyclonine or any component of the formulation, due to the risk of severe allergic reactions or contact dermatitis.', '- Local irritation
INSERT INTO "drug_generic" VALUES(74, 'Desflurane', 'Desflurane', 'N01AB07', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Malignant Hyperthermia", "severity": "High", "trigger_condition": "Genetic susceptibility to malignant hyperthermia", "message": "STOP: Fatal malignant hyperthermia may occur. Discontinue triggering agents immediately, administer IV dantrolene sodium, and initiate supportive therapy."}, {"alert_type": "Pediatric Respiratory Adverse Reactions", "severity": "High", "trigger_condition": "Induction of anesthesia in pediatric patients", "message": "STOP: Contraindicated for induction of anesthesia in pediatric patients due to a high incidence of severe respiratory adverse reactions, including laryngospasm, coughing, breath-holding, and oxygen desaturation."}]', '- **Malignant Hyperthermia:** Can trigger a hypermetabolic state of skeletal muscle leading to high oxygen demand and clinical syndrome known as malignant hyperthermia. 
INSERT INTO "drug_generic" VALUES(75, 'Daratumumab', 'Daratumumab', 'L01FC01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Infusion Reactions", "severity": "High", "trigger_condition": "During or within 4 hours of completing the infusion", "message": "Severe and potentially fatal infusion reactions (bronchospasm, hypoxia, pulmonary edema) can occur. Pre-medicate with antihistamines, antipyretics, and corticosteroids."}, {"alert_type": "Interference with Blood Cross-matching", "severity": "High", "trigger_condition": "Pre-transfusion blood typing and cross-matching", "message": "Daratumumab binds to CD38 on RBCs, causing a false-positive indirect Coombs test. Type and screen patients BEFORE starting treatment."}]', '**Infusion Reactions:** Severe and/or serious infusion reactions have occurred, including bronchospasm, hypoxia, dyspnea, hypertension, tachycardia, headache, laryngeal edema, and pulmonary edema. Nearly all reactions occur during the infusion or within 4 hours of completing it. Pre-medicate with antihistamines, antipyretics, and corticosteroids prior to treatment. Administer oral corticosteroids following infusions. Consider post-infusion medications (e.g., inhaled corticosteroids, short- and long-acting bronchodilators) in patients with a history of COPD.
INSERT INTO "drug_generic" VALUES(76, 'Butenafine 1 % topical', 'Butenafine', 'D01AE23', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Application Site Reactions:** Discontinue use if irritation, severe redness, itching, or sensitization develops at the application site.
INSERT INTO "drug_generic" VALUES(77, 'Tildrakizumab', 'Tildrakizumab-asmn', 'L04AC17', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hypersensitivity and Infection Risk", "severity": "Moderate", "trigger_condition": "Signs of anaphylaxis or active infection", "message": "Discontinue immediately if a serious hypersensitivity reaction occurs. Evaluate for tuberculosis before initiating. Do not administer to patients with active TB or severe active infections."}]', '**Hypersensitivity Reactions:** Cases of angioedema and urticaria have occurred. If a serious hypersensitivity reaction occurs, discontinue treatment immediately and initiate appropriate therapy.
INSERT INTO "drug_generic" VALUES(78, 'Valacyclovir', 'Valacyclovir', 'J05AB11', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Thrombotic Microangiopathy", "severity": "High", "trigger_condition": "Use in immunocompromised patients (e.g., advanced HIV, bone marrow or solid organ transplant recipients)", "message": "STOP: Cases of Thrombotic Thrombocytopenic Purpura (TTP) and Hemolytic Uremic Syndrome (HUS), some fatal, have been reported in patients with advanced HIV disease and in allogeneic bone marrow transplant and renal transplant recipients."}]', '**Renal Impairment:** Acute renal failure and central nervous system symptoms have been reported in patients with underlying renal disease or those receiving supratherapeutic doses. Adjust dosage based on creatinine clearance.
INSERT INTO "drug_generic" VALUES(79, 'Piroxicam', 'Piroxicam', 'M01AC01', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, MI, and stroke. They also increase the risk of serious GI adverse events including bleeding, ulceration, and perforation."}]', '**Cardiovascular Thrombotic Events:** NSAIDs cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke, which can be fatal. Risk may occur early in treatment and may increase with duration of use.
INSERT INTO "drug_generic" VALUES(80, 'Solriamfetol', 'Solriamfetol', 'N06BA14', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Preexisting hypertension or cardiovascular disease", "message": "STOP: Solriamfetol dose-dependently increases blood pressure and heart rate. Assess and control blood pressure before initiation. Monitor regularly during treatment."}]', '**Blood Pressure and Heart Rate Increase:** Increases systolic and diastolic blood pressure and heart rate in a dose-dependent manner. Assess and control hypertension before initiating. Monitor regularly. Use with caution in patients at higher risk of major adverse cardiovascular events (MACE).
INSERT INTO "drug_generic" VALUES(81, 'Diphenhydramine + Allantoin topical', 'Diphenhydramine and Allantoin', 'D04AA32', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Systemic Toxicity Risk", "severity": "High", "trigger_condition": "Application to large body areas or concurrent use with oral diphenhydramine", "message": "STOP: Concurrent use with oral diphenhydramine or application over large, blistered, or broken skin areas can lead to severe systemic anticholinergic toxicity."}]', '- **Systemic Absorption:** Avoid application to large areas of the body, deep or puncture wounds, animal bites, or serious burns due to the risk of systemic anticholinergic absorption.
INSERT INTO "drug_generic" VALUES(82, 'Dydrogesterone', 'Dydrogesterone', 'G03DB01', 0, 0, 1, 0, 1, 0, 0, 1, '[{"alert_type": "Cardiovascular and Thromboembolic Risk", "severity": "High", "trigger_condition": "Patients with a history of thromboembolic disorders or severe cardiovascular disease", "message": "STOP: Progestogens can increase the risk of thromboembolic events. Monitor closely for signs of deep vein thrombosis, pulmonary embolism, or cerebrovascular accidents."}]', 'Monitor patients closely for visual disturbances, including loss of vision, proptosis, or diplopia, as well as onset of migraines, which may indicate embolic or vascular complications.
INSERT INTO "drug_generic" VALUES(83, 'Calcium Chloride  + Dextrose Anhydrous + Magnessium Chloride  + Sodium Acetate + Sodium Chloride  (Peritoneal Dialysis solutions)', 'Peritoneal Dialysis Solution', 'B05DB', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Administration Route Safety", "severity": "High", "trigger_condition": "Intravenous administration", "message": "STOP: This solution is for INTRAPERITONEAL USE ONLY. Do not administer intravenously."}]', '**Peritonitis Risk:** Strict aseptic technique must be maintained during the connection and disconnection of the dialysis bags to prevent bacterial peritonitis, a severe and common complication.
INSERT INTO "drug_generic" VALUES(84, 'Sodium Chloride + Sodium Lactate + Calcium chloride + Magnesium chloride (CAPD solutions)', 'Peritoneal Dialysis Solution', 'B05DB', 0, 1, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Peritonitis Risk", "severity": "High", "trigger_condition": "Breach of aseptic technique during exchange", "message": "STOP: Strict aseptic technique must be maintained during all exchanges. Cloudy effluent is a sign of peritonitis and requires immediate medical evaluation and culture."}]', '- **Fluid and Electrolyte Balance:** Monitor closely for signs of fluid overload, dehydration, and electrolyte imbalances (e.g., hypokalemia, hypercalcemia, hypomagnesemia).
INSERT INTO "drug_generic" VALUES(85, 'Metformin Hydrochloride + Rosiglitazone', 'Metformin and Rosiglitazone', 'A10BD03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Heart Failure and Lactic Acidosis Risk", "severity": "High", "trigger_condition": "Patient with NYHA Class III/IV heart failure or severe renal impairment (eGFR < 30 mL/min)", "message": "STOP: Rosiglitazone can cause or exacerbate congestive heart failure. Metformin can cause fatal lactic acidosis. Contraindicated in severe heart failure and severe renal impairment."}]', '**Congestive Heart Failure:** Rosiglitazone causes fluid retention, which can exacerbate or lead to heart failure. Monitor for signs of heart failure (dyspnea, edema, rapid weight gain). Discontinue if heart failure develops.
INSERT INTO "drug_generic" VALUES(86, 'Hydrochlorothiazide + Losartan Potassium', 'Losartan Potassium and Hydrochlorothiazide', 'C09DA01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Fetal Toxicity:** Can cause fetal harm when administered to a pregnant woman. Discontinue as soon as pregnancy is detected.
INSERT INTO "drug_generic" VALUES(87, 'Desmopressin', 'Desmopressin', 'H01BA02', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hyponatremia Risk", "severity": "High", "trigger_condition": "Excessive fluid intake or concomitant use of hyponatremia-inducing drugs", "message": "STOP: Desmopressin can cause severe, life-threatening hyponatremia and water intoxication. Strict fluid restriction is mandatory, and serum sodium must be monitored regularly."}]', 'Extreme caution is required to prevent water intoxication and severe hyponatremia, which can lead to seizures, coma, and death. Fluid intake must be strictly limited, especially in the elderly and children. Monitor serum sodium levels at baseline and periodically during treatment. Use with caution in patients with conditions characterized by fluid and electrolyte imbalance, such as cystic fibrosis or heart failure. Periodic blood pressure and weight checks are necessary to monitor for fluid overload.', '- **Central Diabetes Insipidus:** Used as replacement therapy for antidiuretic hormone deficiency to control polyuria and polydipsia.
INSERT INTO "drug_generic" VALUES(88, 'Methyl Salicylate 30% + Menthol 10% + Camphor 4% Topical', 'Methyl Salicylate, Menthol, and Camphor Topical', 'M02AC', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Severe Skin Burns", "severity": "High", "trigger_condition": "Application with heat pads or tight bandages", "message": "STOP: Do not apply a heating pad or tight bandage to the treated area. Severe, blistering skin burns have been reported with the use of topical counterirritants."}]', '**Application Site Reactions:** Avoid contact with the eyes, mucous membranes, wounds, or damaged/irritated skin. Do not bandage tightly, wrap, or cover the treated area until it has been washed. 
INSERT INTO "drug_generic" VALUES(89, 'Ceritinib', 'Ceritinib', 'L01ED02', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Severe Gastrointestinal Toxicity", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "STOP: Severe diarrhea, nausea, vomiting, or abdominal pain occurs in a vast majority of patients. Monitor and manage proactively with antidiarrheals, antiemetics, and fluid replacement. Withhold or reduce dose for severe reactions."}, {"alert_type": "Hepatotoxicity and Pneumonitis", "severity": "High", "trigger_condition": "During therapy", "message": "Can cause severe hepatotoxicity and fatal interstitial lung disease (ILD)/pneumonitis. Monitor liver function tests monthly. Monitor for pulmonary symptoms and discontinue permanently if ILD is diagnosed."}]', '**QT Interval Prolongation:** Can cause QTc prolongation leading to ventricular tachyarrhythmia. Avoid in patients with congenital long QT syndrome. Monitor ECGs and electrolytes periodically in patients with heart failure, bradyarrhythmias, or those taking QT-prolonging medications.
INSERT INTO "drug_generic" VALUES(90, 'Ferric maltol', 'Ferric maltol', 'B03AB10', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Pediatric Toxicity", "severity": "High", "trigger_condition": "Accidental ingestion by children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6 years of age. Keep strictly out of reach of children."}]', '**Inflammatory Bowel Disease (IBD) Flare:** Avoid use in patients experiencing an active IBD flare, as unabsorbed iron in the gastrointestinal tract may exacerbate mucosal inflammation and oxidative stress.
INSERT INTO "drug_generic" VALUES(91, 'Lefamulin', 'Lefamulin', 'J01XX12', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Patients with prolonged QT interval, arrhythmias, or concurrent use of QT-prolonging drugs", "message": "STOP: Lefamulin can prolong the QT interval. Avoid use in patients with known QT prolongation, arrhythmias, or those taking antiarrhythmic agents."}]', '**QT Prolongation:** Lefamulin has the potential to prolong the QT interval. Avoid use in patients with known prolongation of the QT interval, patients with arrhythmias (e.g., atrial fibrillation, ventricular tachycardia), patients receiving antiarrhythmic agents (Class IA or III), and patients receiving other drugs that prolong the QT interval.
INSERT INTO "drug_generic" VALUES(92, 'Nitrofurazone 0.2% Topical', 'Nitrofurazone', 'D08AF01', 1, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Polyethylene Glycol Toxicity", "severity": "High", "trigger_condition": "Application to large burn areas in patients with renal impairment", "message": "STOP: The polyethylene glycol base can be absorbed through denuded skin, leading to severe renal toxicity and increased blood urea nitrogen (BUN). Avoid use in large burns with concurrent renal failure."}]', 'Prolonged or repeated application may result in the overgrowth of non-susceptible organisms, including fungi and Pseudomonas species. If superinfection occurs, or if severe irritation, sensitization, or contact dermatitis develops, therapy must be discontinued immediately and appropriate alternative treatment instituted. Caution is advised when applying to large areas of denuded skin or severe burns, particularly in patients with pre-existing renal impairment, due to the risk of systemic absorption of the polyethylene glycol base, which can exacerbate renal dysfunction.', '- **Burns (Second and Third Degree):** Used as adjunctive therapy for the prevention and treatment of bacterial infections in severe burns.
INSERT INTO "drug_generic" VALUES(93, 'Fluvoxamine Maleate', 'Fluvoxamine', 'N06AB08', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Suicidality Risk", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes in children, adolescents, and young adults (<24 years)", "message": "Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', 'Monitor closely for clinical worsening, suicidality, or unusual changes in behavior, especially during the initial months of therapy or at times of dose changes. Use with caution in patients with a history of mania, hypomania, or seizure disorders. Fluvoxamine may increase the risk of bleeding events; use caution in patients taking NSAIDs, aspirin, or other drugs affecting coagulation. Monitor for signs of serotonin syndrome, especially when co-administered with other serotonergic drugs. Abrupt discontinuation may lead to withdrawal symptoms (dizziness, sensory disturbances, agitation, anxiety); taper the dose gradually. Use with caution in patients with hepatic impairment; a lower starting dose and slower titration are recommended. Smokers may require higher doses due to increased metabolism via CYP1A2 induction.', '- **Obsessive-Compulsive Disorder (OCD):** Treatment of obsessions and compulsions in adults and pediatric patients (8 years and older).
INSERT INTO "drug_generic" VALUES(94, 'Bempedoic acid', 'Bempedoic acid', 'C10AX15', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Tendon Rupture", "severity": "High", "trigger_condition": "Patient reports joint pain, swelling, or inflammation", "message": "STOP: Bempedoic acid is associated with an increased risk of tendon rupture or injury. Discontinue immediately if tendon rupture occurs. Consider discontinuing if joint pain, swelling, or inflammation develops."}]', '**Hyperuricemia:** Inhibits renal tubular OAT2 and may increase blood uric acid levels. Elevated uric acid levels usually occur within the first 4 weeks of treatment initiation and persist throughout treatment, potentially leading to gout. Monitor uric acid levels periodically.
INSERT INTO "drug_generic" VALUES(95, 'Enalapril Maleate', 'Enalapril Maleate', 'C09AA02', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: When pregnancy is detected, discontinue Enalapril as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}]', '- **Hypotension:** Symptomatic hypotension may occur, especially in volume-depleted patients (e.g., those on diuretic therapy). Monitor blood pressure closely during initiation.
INSERT INTO "drug_generic" VALUES(96, 'Cefuroxime', 'Cefuroxime', 'J01DC02', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(97, 'Zinc Oxide + Avobenzone + Octinoxate + Enzacamene', 'Zinc Oxide / Avobenzone / Octinoxate / Enzacamene', 'D02BA', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Application Site Reactions:** Application to broken, blistered, or severely excoriated skin should be avoided to prevent systemic absorption and severe irritation.
INSERT INTO "drug_generic" VALUES(98, 'Benzalkonium + Benzocaine oral prep', 'Benzalkonium chloride and Benzocaine', 'A01AB11', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Methemoglobinemia", "severity": "High", "trigger_condition": "Excessive or prolonged use of benzocaine-containing products", "message": "STOP: Benzocaine can cause rare but potentially fatal methemoglobinemia. Do not use in children under 2 years of age. Seek immediate medical attention if pale, gray, or blue-colored skin, headache, rapid heart rate, or shortness of breath occurs."}]', '**Methemoglobinemia:** Benzocaine has been associated with a rare but serious condition called methemoglobinemia. Symptoms include pale, gray, or blue-colored skin, lips, and nail beds, shortness of breath, fatigue, confusion, headache, and rapid heart rate. 
INSERT INTO "drug_generic" VALUES(99, 'Ethacrynic acid', 'Ethacrynic acid', 'C03CC01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Profound Diuresis", "severity": "High", "trigger_condition": "High doses or rapid intravenous administration", "message": "STOP: Ethacrynic acid is a potent diuretic that, if given in excessive amounts, can lead to profound diuresis with water and electrolyte depletion. Careful medical supervision is required."}]', '**Electrolyte Imbalance:** Can cause severe hypokalemia, hyponatremia, hypochloremic alkalosis, and hypomagnesemia. Monitor serum electrolytes regularly.
INSERT INTO "drug_generic" VALUES(100, 'Lomefloxacin 0.3% Eye or Ear prep', 'Lomefloxacin Ophthalmic/Otic', 'S01AE04', 1, 0, 0, 0, 0, 1, 1, 0, '[]', '**Superinfection:** Prolonged use of topical antibiotics may result in the overgrowth of non-susceptible organisms, including fungi. If superinfection occurs, discontinue use and institute alternative therapy.
INSERT INTO "drug_generic" VALUES(101, 'Terconazole 0.4% Vag prep', 'Terconazole', 'G01AF04', 1, 0, 0, 0, 0, 1, 0, 0, '[]', 'Discontinue therapy immediately if sensitization, irritation, fever, chills, or flu-like symptoms develop during use. The base contained in the vaginal formulation may interact with and weaken latex or rubber products, such as condoms or vaginal contraceptive diaphragms; concurrent use is not recommended within 72 hours following treatment. Clinical efficacy and safety have not been established in patients under 18 years of age.', '- **Vulvovaginal Candidiasis:** Indicated for the local treatment of vulvovaginal candidiasis (moniliasis). It is effective in eradicating the fungal infection and alleviating associated symptoms such as pruritus, burning, and discharge.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to terconazole or any structural analogs (other azole antifungals), as severe allergic reactions may occur.
INSERT INTO "drug_generic" VALUES(102, 'Bromazepam', 'Bromazepam', 'N05BA08', 0, 1, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Concomitant Use with CNS Depressants", "severity": "High", "trigger_condition": "Co-prescription with opioids, alcohol, or other CNS depressants", "message": "STOP: Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death. Reserve concomitant prescribing for patients with inadequate alternative treatment options."}, {"alert_type": "Dependence and Withdrawal Risk", "severity": "High", "trigger_condition": "Long-term use or abrupt discontinuation", "message": "WARNING: Prolonged use can lead to physical and psychological dependence. Abrupt discontinuation may precipitate severe withdrawal symptoms, including seizures. Taper dose gradually."}]', 'Use is strictly reserved for severe anxiety disorders; it is not indicated for the primary treatment of depressive disorders or psychosis. Higher doses carry a significant risk of anterograde amnesia, which may be associated with inappropriate behavior.
INSERT INTO "drug_generic" VALUES(103, 'Oxybuprocaine Hydrochloride 0.4% Eye prep', 'Benoxinate Hydrochloride', 'S01HA02', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Corneal Toxicity", "severity": "High", "trigger_condition": "Prolonged or repeated use", "message": "STOP: Prolonged use of topical ocular anesthetics can produce permanent corneal opacification, ulceration, and visual loss. Not for patient self-administration."}]', '**Corneal Protection:** The anesthetized eye must be protected from dust, foreign bodies, and rubbing, as the patient will not feel pain and could cause severe corneal abrasion.
INSERT INTO "drug_generic" VALUES(104, 'Desvenlafaxine', 'Desvenlafaxine', 'N06AX23', 0, 1, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Suicidality and Antidepressant Drugs", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '- **Serotonin Syndrome:** Increased risk when co-administered with other serotonergic agents. Discontinue immediately if symptoms occur.
INSERT INTO "drug_generic" VALUES(105, 'Paracetamol + Phenylephrine', 'Acetaminophen and Phenylephrine', 'N02BE51', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Exceeding maximum daily dose of paracetamol or concurrent alcohol use", "message": "STOP: Severe hepatotoxicity can occur if the maximum daily dose of paracetamol (4000 mg) is exceeded. Verify all concurrent medications to ensure no other paracetamol-containing products are being used."}, {"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Patients with severe hypertension or severe coronary artery disease", "message": "WARNING: Phenylephrine is a potent vasoconstrictor. Use is contraindicated in patients with severe hypertension or severe coronary artery disease."}]', '**Cardiovascular Effects:** Phenylephrine can cause significant increases in blood pressure and reflex bradycardia. Use with extreme caution in elderly patients, and those with hyperthyroidism, myocardial disease, bradycardia, partial heart block, or severe arteriosclerosis.
INSERT INTO "drug_generic" VALUES(106, 'Cyclizine', 'Cyclizine', 'R06AE03', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "CNS Depression", "severity": "High", "trigger_condition": "Concomitant use with alcohol, sedatives, or opioids", "message": "STOP: Significant risk of profound CNS depression. Avoid concurrent use with alcohol or other central nervous system depressants."}]', '**Anticholinergic Effects:** Use with caution in patients with angle-closure glaucoma, urinary retention, prostatic hypertrophy, and pyloroduodenal obstruction due to the drug''s antimuscarinic properties.
INSERT INTO "drug_generic" VALUES(107, 'Cefiderocol', 'Cefiderocol sulfate tosylate', 'J01DI04', 1, 0, 1, 1, 1, 1, 0, 0, '[{"alert_type": "Increased Mortality", "severity": "High", "trigger_condition": "Treatment of carbapenem-resistant Gram-negative bacterial infections", "message": "STOP: An increase in all-cause mortality was observed in patients treated with cefiderocol compared to alternative treatments for carbapenem-resistant infections. Reserve use for patients with limited or no alternative treatment options."}]', '**Increased All-Cause Mortality:** An increase in all-cause mortality was observed in patients treated with cefiderocol compared to best available therapy in a clinical trial of patients with carbapenem-resistant Gram-negative bacterial infections. Reserve use for patients who have limited or no alternative treatment options.
INSERT INTO "drug_generic" VALUES(108, 'Riboflavin', 'Riboflavin', 'A11HA04', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Riboflavin is generally recognized as safe. High doses may cause a harmless bright yellow discoloration of the urine, which can interfere with certain laboratory tests (e.g., urinalysis, urinary catecholamines). Use with caution in pregnancy only if doses exceed the Recommended Dietary Allowance (RDA).', '- **Riboflavin Deficiency (Ariboflavinosis):** Prevention and treatment of vitamin B2 deficiency, characterized by cheilosis, angular stomatitis, glossitis, keratitis, and seborrheic dermatitis.
INSERT INTO "drug_generic" VALUES(109, 'Miconazole Nitrate', 'Miconazole', 'A01AB09, D01AC02, G01AF04', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hepatic Toxicity", "severity": "High", "trigger_condition": "Patient with pre-existing hepatic impairment", "message": "STOP: Miconazole is contraindicated in patients with hepatic impairment due to the risk of severe hepatotoxicity and impaired drug clearance."}]', 'Discontinue therapy immediately if clinical signs of sensitization, severe irritation, or hypersensitivity occur.
INSERT INTO "drug_generic" VALUES(110, 'Betamethasone 0.1% + Neomycin Sulphate 0.5% Topical', 'Betamethasone and Neomycin', 'D07CC01', 1, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Ototoxicity and Nephrotoxicity", "severity": "Medium", "trigger_condition": "Application to large areas of damaged skin", "message": "STOP: Neomycin can be absorbed systemically from large wounds or severely damaged skin, leading to irreversible ototoxicity (deafness) and nephrotoxicity. Avoid use on large areas of denuded skin."}]', '**Systemic Absorption:** Systemic absorption of topical corticosteroids can produce reversible HPA axis suppression, Cushing''s syndrome, and hyperglycemia. Risk increases with prolonged use, application to large surface areas, or use of occlusive dressings.
INSERT INTO "drug_generic" VALUES(111, 'Amrinone (inamrinone)', 'Inamrinone', 'C01CE01', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Thrombocytopenia and Arrhythmias", "severity": "High", "trigger_condition": "Prolonged infusion or high cumulative doses", "message": "STOP: Inamrinone can cause severe, dose-dependent thrombocytopenia and potentially fatal supraventricular and ventricular arrhythmias. Continuous ECG monitoring and frequent platelet counts are mandatory."}]', '**Thrombocytopenia:** Dose-dependent thrombocytopenia has been reported. Monitor platelet counts frequently. If platelets fall significantly, consider decreasing the dose or discontinuing the drug.
INSERT INTO "drug_generic" VALUES(112, 'Dorzolamide 2% + Timolol 0.5% Eye prep', 'Dorzolamide and Timolol Ophthalmic', 'S01ED51', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Systemic Beta-Blockade", "severity": "High", "trigger_condition": "Patients with reactive airway disease or severe cardiac disease", "message": "STOP: Timolol is a non-selective beta-blocker. Systemic absorption can cause fatal bronchospasm in asthmatics and severe cardiac failure in susceptible patients. Verify cardiac and respiratory history before prescribing."}]', '**Systemic Absorption:** Even though applied topically, both dorzolamide (a sulfonamide) and timolol (a beta-blocker) are absorbed systemically. Severe respiratory and cardiac reactions, including death due to bronchospasm or cardiac failure, have been reported.
INSERT INTO "drug_generic" VALUES(113, 'Ceftolozane + Tazobactam', 'Ceftolozane and Tazobactam', 'J01DI54', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Decreased Efficacy in Renal Impairment", "severity": "Moderate", "trigger_condition": "Baseline CrCl of 30 to 50 mL/min", "message": "Clinical cure rates were lower in patients with baseline CrCl of 30 to 50 mL/min compared to those with normal renal function. Monitor clinical response closely in this population."}]', '**Decreased Efficacy in Renal Impairment:** In clinical trials for cIAI, clinical cure rates were lower in patients with baseline CrCl of 30 to 50 mL/min. Monitor these patients closely for treatment failure.
INSERT INTO "drug_generic" VALUES(114, 'Benzylpenicillin Sodium (Penicillin G Sodium)', 'Penicillin G Sodium', 'J01CE01', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}, {"alert_type": "Neurotoxicity", "severity": "High", "trigger_condition": "High doses in patients with severe renal impairment", "message": "STOP: Administration of massive doses (e.g., >20 million units/day), especially in patients with renal failure, can cause severe neurotoxicity, including myoclonus, intractable seizures, and coma. Adjust dose based on creatinine clearance."}]', '**Sodium Load:** Penicillin G Sodium contains approximately 1.68 mEq (39 mg) of sodium per 1 million units. High doses can cause significant sodium overload, leading to hypernatremia, fluid retention, and exacerbation of congestive heart failure.
INSERT INTO "drug_generic" VALUES(115, 'Halometasone', 'Halometasone', 'D07AC12', 0, 0, 0, 0, 0, 1, 0, 1, '[]', '**Systemic Absorption:** High risk of systemic absorption leading to reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, and hyperglycemia when applied to large surface areas, broken skin, or under occlusive dressings.
INSERT INTO "drug_generic" VALUES(116, 'Rabeprazole', 'Rabeprazole', 'A02BC04', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Patient history of hypersensitivity to Rabeprazole or other proton pump inhibitors (PPIs)", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, have been reported. Verify patient allergy history before prescribing."}]', 'Gastric malignancy must be ruled out prior to initiating therapy, as symptomatic response to rabeprazole does not preclude the presence of gastric cancer. Use with caution in patients with severe hepatic impairment. Prolonged use (typically >1 year) may increase the risk of hypomagnesemia, vitamin B12 deficiency, and osteoporosis-related fractures of the hip, wrist, or spine. Monitor magnesium levels prior to initiation and periodically during prolonged therapy. Observational studies suggest an increased risk of *Clostridioides difficile*-associated diarrhea (CDAD) with PPI use; consider this diagnosis in patients presenting with persistent diarrhea. Cutaneous and systemic lupus erythematosus have been reported as rare adverse events; discontinue if signs or symptoms occur.', '- **Gastroesophageal Reflux Disease (GERD):** Treatment of symptomatic GERD, healing of erosive esophagitis, and maintenance of healed erosive esophagitis.
INSERT INTO "drug_generic" VALUES(117, 'Anthrax immune globulin', 'Anthrax immune globulin', 'J06BB19', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hypersensitivity and Anaphylaxis", "severity": "High", "trigger_condition": "Patient history of severe systemic reactions to human immune globulin preparations", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Have epinephrine and supportive care immediately available during infusion."}]', '**Thrombosis Risk:** Thrombosis may occur following treatment with immune globulin products. Risk factors include advanced age, prolonged immobilization, hypercoagulable conditions, history of venous or arterial thrombosis, use of estrogens, indwelling vascular catheters, hyperviscosity, and cardiovascular risk factors. Administer at the minimum infusion rate practicable and ensure adequate hydration before administration.
INSERT INTO "drug_generic" VALUES(118, 'Etelcalcetide', 'Etelcalcetide', 'H05BX04', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Hypocalcemia", "severity": "High", "trigger_condition": "Baseline corrected serum calcium below the lower limit of normal", "message": "STOP: Do not initiate etelcalcetide if corrected serum calcium is below the lower limit of normal. Severe hypocalcemia can cause QT prolongation, ventricular arrhythmias, and seizures."}]', '**Hypocalcemia:** Etelcalcetide lowers serum calcium and can lead to severe hypocalcemia. Measure serum calcium levels prior to treatment, within 1 week of initiation or dose adjustment, and every 4 weeks during treatment. 
INSERT INTO "drug_generic" VALUES(119, 'Rupatadine', 'Rupatadine', 'R06AX28', 0, 0, 0, 0, 1, 0, 1, 0, '[]', 'Use with caution in patients with renal or hepatic insufficiency, as safety and efficacy have not been fully established in these populations. Although non-sedating, it may impair the ability to drive or operate machinery in susceptible individuals. Caution is advised in the elderly. Avoid concurrent consumption of grapefruit juice.', '- **Allergic Rhinitis:** Symptomatic relief of nasal and non-nasal symptoms of seasonal and perennial allergic rhinitis.
INSERT INTO "drug_generic" VALUES(120, 'Voriconazole', 'Voriconazole', 'J02AC03', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity and QT Prolongation", "severity": "High", "trigger_condition": "Initiation of therapy or concurrent use of QT-prolonging drugs", "message": "STOP: Severe hepatic toxicity and QT prolongation can occur. Monitor LFTs and electrolytes. Review medication profile for severe CYP3A4 interactions before prescribing."}]', 'Monitor hepatic function (ALT, AST, bilirubin) prior to and during treatment; severe hepatotoxicity has occurred. Monitor renal function and serum electrolytes; correct hypokalemia, hypomagnesemia, and hypocalcemia prior to initiation to reduce the risk of QT prolongation. Visual disturbances (photophobia, blurred vision, color vision changes) are common; patients should avoid driving or operating machinery if affected. Avoid intense or prolonged exposure to direct sunlight due to the risk of severe photosensitivity and squamous cell carcinoma with long-term use. Monitor pancreatic function in patients at risk for acute pancreatitis.', '- **Invasive Aspergillosis:** Primary treatment.
INSERT INTO "drug_generic" VALUES(121, 'Omeprazole', 'Omeprazole', 'A02BC01', 0, 0, 1, 1, 0, 0, 1, 1, '[{"alert_type": "Clostridium difficile-Associated Diarrhea (CDAD)", "severity": "High", "trigger_condition": "Development of severe, persistent diarrhea during or after therapy", "message": "Proton pump inhibitors (PPIs) may increase the risk of CDAD. Evaluate patients who develop persistent diarrhea for C. difficile infection."}, {"alert_type": "Bone Fracture Risk", "severity": "Moderate", "trigger_condition": "Long-term or high-dose therapy", "message": "Long-term and multiple daily dose PPI therapy may be associated with an increased risk for osteoporosis-related fractures of the hip, wrist, or spine."}]', '**Gastric Malignancy:** Symptomatic response to therapy does not preclude the presence of gastric malignancy. Rule out malignancy before initiating treatment for gastric ulcers.
INSERT INTO "drug_generic" VALUES(122, 'Pridinol', 'Pridinol', 'M03BX03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Anticholinergic Toxicity", "severity": "High", "trigger_condition": "Concomitant use with other anticholinergic agents or in elderly patients", "message": "STOP: High risk of severe anticholinergic effects (e.g., urinary retention, closed-angle glaucoma exacerbation, severe tachycardia). Monitor closely."}]', '**Anticholinergic Effects:** Exhibits significant antimuscarinic activity. Use with extreme caution in the elderly, as they are more susceptible to adverse effects such as confusion, urinary retention, and constipation.
INSERT INTO "drug_generic" VALUES(123, 'Valsartan', 'Valsartan', 'C09CA03', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue valsartan as soon as pregnancy is detected."}]', '**Hypotension:** Symptomatic hypotension may occur, particularly in volume- or salt-depleted patients (e.g., those treated with high doses of diuretics). Correct volume depletion prior to administration or initiate at a lower dose.
INSERT INTO "drug_generic" VALUES(124, 'Lusutrombopag', 'Lusutrombopag', 'B02BX07', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Thrombotic Risk", "severity": "High", "trigger_condition": "Patients with known risk factors for thromboembolism", "message": "STOP: Thrombopoietin (TPO) receptor agonists have been associated with thrombotic and thromboembolic complications (e.g., portal vein thrombosis). Do not use to normalize platelet counts."}]', '**Thrombotic or Thromboembolic Complications:**
INSERT INTO "drug_generic" VALUES(125, 'Adhatoda vasica + Centella asiatica', 'Adhatoda vasica and Centella asiatica Extract', 'R05CA', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Symptom Persistence", "severity": "Low", "trigger_condition": "Cough persisting >7 days", "message": "If cough persists for more than 7 days, tends to recur, or is accompanied by a fever, rash, or persistent headache, consult a physician to rule out serious underlying conditions."}]', '**Diabetes:** Herbal syrups often contain sugar or honey as a base. Diabetic patients should use with caution and monitor blood glucose levels.
INSERT INTO "drug_generic" VALUES(126, 'Ocrelizumab', 'Ocrelizumab', 'L04AG08', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Infusion Reactions and Hepatitis B Reactivation", "severity": "High", "trigger_condition": "Administration of ocrelizumab or history of HBV", "message": "STOP: Life-threatening infusion reactions can occur; premedicate and monitor closely. Hepatitis B virus (HBV) reactivation, sometimes fatal, has been reported; screen all patients for HBV prior to initiation."}]', '**Infusion-Related Reactions:** Life-threatening infusion reactions can occur. Premedicate with methylprednisolone and an antihistamine. Observe patients during and for at least 1 hour after the infusion.
INSERT INTO "drug_generic" VALUES(127, 'Famciclovir INN', 'Famciclovir', 'J05AB09', 0, 0, 1, 0, 1, 1, 0, 0, '[{"alert_type": "Acute Renal Failure", "severity": "High", "trigger_condition": "Failure to adjust dosage in patients with underlying renal impairment", "message": "Acute renal failure has been reported in patients with underlying renal disease who received inappropriately high doses of famciclovir. Dosage reduction is mandatory in patients with decreased renal function."}]', '**Renal Impairment:** Dosage adjustment is required in patients with renal impairment (CrCl <60 mL/min). Acute renal failure may occur if the dose is not appropriately reduced.
INSERT INTO "drug_generic" VALUES(128, 'Cetalkonium Chloride + Choline Salicylate oral prep', 'Cetalkonium Chloride and Choline Salicylate', 'A01AD11', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Reye''s Syndrome Risk", "severity": "High", "trigger_condition": "Use in children under 12 years of age", "message": "STOP: Contraindicated in children under 12 years of age due to the risk of Reye''s syndrome associated with salicylate exposure, especially during viral infections."}]', '**Systemic Absorption:** Although applied topically, systemic absorption of salicylates can occur. Use with caution in patients with peptic ulcers, erosive gastritis, asthma, or allergic disorders.
INSERT INTO "drug_generic" VALUES(129, 'Hepatitis A Virus (Inactivated) Vaccine', 'Hepatitis A Vaccine, Inactivated', 'J07BC02', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe allergic reaction to any component of the vaccine", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history (including neomycin or alum, depending on the formulation) before administration. Ensure epinephrine and appropriate medical support are immediately available."}]', '**Hypersensitivity Reactions:** Appropriate medical treatment and supervision must be readily available in case of a rare anaphylactic event following the administration of the vaccine.
INSERT INTO "drug_generic" VALUES(130, 'Isoniazid + Rifampicin', 'Isoniazid and Rifampin', 'J04AM02', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Hepatotoxicity", "severity": "High", "trigger_condition": "Combination therapy with hepatotoxic agents", "message": "STOP: Both isoniazid and rifampicin are hepatotoxic. Severe and sometimes fatal hepatitis can occur. Monitor liver function tests strictly at baseline and periodically. Discontinue immediately if clinical signs of hepatitis develop."}]', '**Hepatotoxicity:** The risk of liver damage is increased when these two drugs are used together. Monitor AST, ALT, and bilirubin at baseline and periodically. Risk is higher in older adults, daily alcohol users, and those with pre-existing liver disease.
INSERT INTO "drug_generic" VALUES(131, 'Abiraterone', 'Abiraterone Acetate', 'L02BX03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated AST/ALT or signs of liver failure", "message": "STOP: Severe and fatal hepatotoxicity has occurred. Monitor liver function tests prior to starting, every 2 weeks for the first 3 months, and monthly thereafter. Interrupt or discontinue if significant elevations occur."}]', '**Mineralocorticoid Excess:** Abiraterone causes hypertension, hypokalemia, and fluid retention due to mineralocorticoid excess resulting from CYP17 inhibition. Closely monitor patients with cardiovascular disease. Control hypertension and correct hypokalemia before initiating treatment. Co-administration with a corticosteroid (prednisone/prednisolone) is required to suppress adrenocorticotropic hormone (ACTH) drive and mitigate these effects.
INSERT INTO "drug_generic" VALUES(132, 'Doravirine', 'Doravirine', 'J05AG06', 0, 0, 0, 0, 0, 1, 0, 0, '[]', 'Immune reconstitution syndrome has been reported in patients treated with combination antiretroviral therapy; patients may develop an inflammatory response to indolent or residual opportunistic infections (such as *Mycobacterium avium* infection, cytomegalovirus, *Pneumocystis jirovecii* pneumonia (PCP), or tuberculosis), which may necessitate further evaluation and treatment.
INSERT INTO "drug_generic" VALUES(133, 'Lactobacillus Rhamnosus GG', 'Lactobacillus rhamnosus GG', 'A07FA01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Infection Risk in Immunocompromised", "severity": "High", "trigger_condition": "Severely immunocompromised patients or those with central venous catheters", "message": "STOP: Rare but serious risk of bacteremia or sepsis in severely ill, immunocompromised, or organ transplant recipients. Avoid opening probiotic capsules near patients with an indwelling central venous catheter to prevent airborne line contamination."}]', '**Severe Pancreatitis:** Use with caution or avoid in acute severe gastrointestinal structural defects or severe acute pancreatitis, as probiotic translocation has been reported in critical illness.
INSERT INTO "drug_generic" VALUES(134, 'Nebivolol + Valsartan', 'Nebivolol and Valsartan', 'C09DX05', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: Discontinue immediately upon detection of pregnancy. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}]', '**Fetal Toxicity:** Use of drugs that act on the renin-angiotensin system during the second and third trimesters of pregnancy reduces fetal renal function and increases fetal and neonatal morbidity and death. Discontinue as soon as pregnancy is detected.
INSERT INTO "drug_generic" VALUES(135, 'Abciximab', 'Abciximab', 'B01AC13', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Bleeding Risk", "severity": "High", "trigger_condition": "Concomitant use of anticoagulants, thrombolytics, or presence of active bleeding", "message": "STOP: Abciximab profoundly inhibits platelet aggregation and significantly increases the risk of major, potentially fatal bleeding. Discontinue immediately in the event of serious uncontrolled bleeding."}]', '**Bleeding Events:** Has the potential to increase the risk of bleeding events, rarely including those with a fatal outcome, particularly in the presence of anticoagulation (e.g., heparin, other anticoagulants, or thrombolytics). Risk of major bleeds is increased in patients receiving thrombolytics and should be weighed against anticipated benefits. Should serious bleeding occur that is not controllable with pressure, the infusion of abciximab and any concomitant heparin must be stopped immediately.
INSERT INTO "drug_generic" VALUES(136, 'Emtricitabine + Tenofovir alafenamide', 'Emtricitabine and Tenofovir alafenamide', 'J05AR17', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Hepatitis B Exacerbation", "severity": "High", "trigger_condition": "Co-infection with Hepatitis B Virus (HBV)", "message": "STOP: Severe acute exacerbations of hepatitis B have been reported in patients who are co-infected with HBV and HIV-1 and have discontinued products containing emtricitabine and/or tenofovir. Monitor hepatic function closely."}]', '**Lactic Acidosis and Hepatomegaly:** Lactic acidosis and severe hepatomegaly with steatosis, including fatal cases, have been reported with the use of nucleoside analogs. Suspend treatment if clinical or laboratory findings suggest lactic acidosis or pronounced hepatotoxicity.
INSERT INTO "drug_generic" VALUES(137, 'Zinc Sulphate Monohydrate', 'Zinc Sulfate', 'A12CB01', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Renal Impairment:** Accumulation of zinc may occur in cases of severe renal failure; use with caution.
INSERT INTO "drug_generic" VALUES(138, 'Glucose Anhydrous + Fructose + Potassium Chloride + Sodium Bicarbonate + Sodium Chloride + Sucrose (Fruity/Tasty ORS)', 'Oral Rehydration Salts (ORS)', 'A07CA', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Severe Dehydration", "severity": "High", "trigger_condition": "Patient presents with severe continuing diarrhea, depressed renal function, or critical fluid losses", "message": "Oral rehydration alone is insufficient for severe dehydration or shock. Immediate intravenous fluid resuscitation is required."}]', '**Severe Dehydration:** Depressed renal function, severe continuing diarrhea, or other critical fluid losses may require supplementation with parenteral (intravenous) fluids along with oral saline.
INSERT INTO "drug_generic" VALUES(139, 'Apalutamide', 'Apalutamide', 'L02BB05', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Seizure Risk", "severity": "High", "trigger_condition": "Development of seizure during therapy", "message": "STOP: Seizures have occurred in patients receiving apalutamide. Permanently discontinue the drug in patients who develop a seizure during treatment."}]', '**Cerebrovascular and Ischemic Cardiovascular Events:** Events have occurred in patients receiving apalutamide. Monitor for signs and symptoms of cerebrovascular disorders and ischemic heart disease. Optimize management of cardiovascular risk factors.
INSERT INTO "drug_generic" VALUES(140, 'Norgestrel', 'Norgestrel', 'G03AC01', 0, 0, 0, 1, 1, 0, 1, 0, '[{"alert_type": "Ectopic Pregnancy Risk", "severity": "High", "trigger_condition": "Patient presenting with lower abdominal pain while taking norgestrel", "message": "STOP: Progestin-only pills are associated with a higher relative risk of ectopic pregnancy if contraceptive failure occurs. Evaluate promptly for ectopic pregnancy in any patient presenting with lower abdominal pain or suspected pregnancy."}]', 'Use with caution in patients with a history of depression; discontinue if severe depression recurs. Caution is advised in patients with conditions aggravated by fluid retention (e.g., asthma, epilepsy, migraine, cardiac or renal dysfunction). Monitor diabetic patients closely as progestins may alter glucose tolerance. Patients with a history of functional ovarian cysts or malabsorption syndromes should be monitored. Discontinue if jaundice, significant hypertension, or severe migraine-type headaches develop.', '- **Contraception:** Used as a progestogen-only oral contraceptive (mini-pill) to prevent pregnancy.
INSERT INTO "drug_generic" VALUES(141, 'Hydrochlorothiazide + Captopril', 'Captopril/Hydrochlorothiazide', 'C09BA01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy", "message": "STOP: When pregnancy is detected, discontinue captopril/hydrochlorothiazide as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}]', '**Neutropenia/Agranulocytosis:** Captopril has been associated with neutropenia and agranulocytosis, particularly in patients with renal impairment or collagen vascular disease (e.g., SLE). Monitor CBC periodically.
INSERT INTO "drug_generic" VALUES(142, 'Triclosan + Benzalkonium Chloride + Light Liquid Paraffin', 'Triclosan, Benzalkonium Chloride, and Mineral Oil', 'D08AE', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Dilution Requirement and Fall Risk", "severity": "High", "trigger_condition": "Use as a bath additive", "message": "STOP: Must be diluted in water before use; undiluted application can cause chemical burns. The high oil content makes bathtubs extremely slippery - exercise extreme caution to prevent falls."}]', '**Dilution Required:** Products containing this combination are typically concentrated and must be diluted in bathwater or washed off as directed. Applying undiluted forms can cause severe skin irritation or chemical burns.
INSERT INTO "drug_generic" VALUES(143, 'Paracetamol + Phenylephrine + Guaifenesin', 'Acetaminophen, Phenylephrine, and Guaifenesin', 'N02BE51', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Exceeding maximum daily dose or concurrent alcohol use", "message": "STOP: Paracetamol (acetaminophen) can cause severe, potentially fatal hepatotoxicity. Do not exceed 4,000 mg per day from all sources. Avoid concurrent use of other paracetamol-containing products."}]', '**Hepatotoxicity:** Paracetamol has been associated with cases of acute liver failure, at times resulting in liver transplant and death. Most cases involve the use of paracetamol at doses that exceed 4,000 mg per day, and often involve more than one paracetamol-containing product. Caution is advised in chronic alcoholics or patients with underlying hepatic disease.
INSERT INTO "drug_generic" VALUES(144, 'Pramoxine + Menthol + Petrolatum topical', 'Pramoxine, Menthol, and Petrolatum', 'D04AB', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Skin Integrity:** Do not use on blistered, broken, or severely denuded skin.
INSERT INTO "drug_generic" VALUES(145, 'Potassium Chloride + Rice powder + Sodium Chloride + Trisodium Citrate (Rice ORS)', 'Oral Rehydration Salts (Rice-based)', 'A07CA', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Preparation Accuracy:** Must be mixed with the exact recommended volume of clean, safe drinking water. Incorrect dilution can lead to hypernatremia or hyponatremia.
INSERT INTO "drug_generic" VALUES(146, 'Vortioxetine', 'Vortioxetine', 'N06AX26', 0, 1, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Suicidality Risk", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes in pediatric and young adult patients", "message": "STOP: Antidepressants increase the risk of suicidal thoughts and behaviors in pediatric and young adult patients. Closely monitor for clinical worsening or emergence of suicidality."}]', '**Suicidal Thoughts and Behaviors:** Antidepressants increase the risk of suicidal thoughts and behavior in pediatric and young adult patients in short-term studies. Closely monitor all antidepressant-treated patients for clinical worsening and the emergence of suicidal thoughts and behaviors. Not approved for use in pediatric patients.
INSERT INTO "drug_generic" VALUES(147, 'Tetanus toxoid (Absorbed Tetanus) Vaccine', 'Tetanus Toxoid Adsorbed', 'J07AM01', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Febrile Illness:** Withhold vaccination in patients with moderate or severe acute febrile illness until they recover, to avoid confusing the signs of the illness with vaccine side effects.
INSERT INTO "drug_generic" VALUES(148, 'Azithromycin 1%  Eye drop', 'Azithromycin Ophthalmic', 'S01AA26', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Severe Skin Reactions", "severity": "High", "trigger_condition": "Hypersensitivity to macrolides", "message": "STOP: Serious allergic reactions, including anaphylaxis, Stevens-Johnson Syndrome, and Toxic Epidermal Necrolysis, have been reported with systemic and topical azithromycin. Discontinue immediately if a rash or allergic symptoms occur."}]', '**Superinfection:** Prolonged use of antibacterial agents may result in the overgrowth of non-susceptible organisms, including fungi. If superinfection occurs, discontinue use and institute appropriate therapy.
INSERT INTO "drug_generic" VALUES(149, 'Pembrolizumab', 'Pembrolizumab', 'L01FF02', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Immune-Mediated Adverse Reactions", "severity": "High", "trigger_condition": "Patients presenting with new-onset respiratory, gastrointestinal, hepatic, or endocrine symptoms", "message": "STOP: Severe and fatal immune-mediated adverse reactions (pneumonitis, colitis, hepatitis, endocrinopathies, nephritis) can occur. Withhold therapy and initiate high-dose corticosteroids promptly if suspected."}]', '**Immune-Mediated Pneumonitis:** Severe, life-threatening, or fatal pneumonitis can occur. Monitor patients for signs and symptoms of pneumonitis. Evaluate suspected pneumonitis with radiographic imaging. Administer corticosteroids for Grade 2 or greater pneumonitis.
INSERT INTO "drug_generic" VALUES(150, 'Amitriptyline Hydrochloride', 'Amitriptyline', 'N06AA09', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Suicidality and Antidepressant Drugs", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults (up to age 24). Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '**Anticholinergic Effects:** Use with caution in patients with a history of urinary retention, benign prostatic hyperplasia (BPH), narrow-angle glaucoma, or increased intraocular pressure due to potent anticholinergic properties.
INSERT INTO "drug_generic" VALUES(151, 'Raltegravir', 'Raltegravir', 'J05AJ01', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Severe Skin Reactions", "severity": "High", "trigger_condition": "Development of severe rash with systemic symptoms", "message": "STOP: Severe, potentially life-threatening, and fatal skin reactions (e.g., Stevens-Johnson syndrome, toxic epidermal necrolysis) have been reported. Discontinue immediately if signs occur."}]', '**Myopathy and Rhabdomyolysis:** Cases of myopathy and rhabdomyolysis have been reported. Use with caution in patients with a history of myopathy or those taking other medications associated with these conditions (e.g., statins).
INSERT INTO "drug_generic" VALUES(152, 'Aliskiren + Amlodipine', 'Aliskiren and Amlodipine', 'C09DB05', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Fetal Toxicity:** Use of drugs that act on the renin-angiotensin system during the second and third trimesters of pregnancy reduces fetal renal function and increases fetal and neonatal morbidity and death. Discontinue immediately upon detection of pregnancy.
INSERT INTO "drug_generic" VALUES(153, 'Adenosine + Cytochrome C + Sodium succinate + Nicotinamide eye prep', 'Cytochrome C, Adenosine, Nicotinamide, Sodium Succinate Ophthalmic Solution', 'S01XA', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Administration Route Warning", "severity": "Low", "message": "For topical ophthalmic use only. Do not inject or swallow."}]', '**Ophthalmic Use Only:** Strictly for topical application to the eye.
INSERT INTO "drug_generic" VALUES(154, 'Aztreonam inhalation', 'Aztreonam inhalation', 'J01DF01', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Bronchospasm", "severity": "High", "trigger_condition": "Administration of inhaled aztreonam", "message": "WARNING: Severe bronchospasm can occur. Measure lung function (FEV1) before and after the initial dose. Always administer a bronchodilator prior to each dose of aztreonam inhalation."}]', '**Bronchospasm:** Can cause severe bronchospasm. Stop treatment if chest tightness or a significant drop in FEV1 develops during nebulizer use. Always administer a short-acting or long-acting bronchodilator prior to dosing.
INSERT INTO "drug_generic" VALUES(155, 'Tizanidine', 'Tizanidine', 'M03BX02', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Severe Hypotension and Hepatotoxicity", "severity": "High", "trigger_condition": "Concurrent use with potent CYP1A2 inhibitors or underlying hepatic impairment", "message": "STOP: Coadministration with potent CYP1A2 inhibitors (e.g., fluvoxamine, ciprofloxacin) is contraindicated due to profound hypotension and increased systemic exposure. Monitor liver function tests closely."}]', 'Use with extreme caution in patients with hepatic or renal insufficiency; monitor liver function tests (aminotransferases) at baseline, 1 month, 3 months, 6 months, and periodically thereafter. Discontinue treatment if liver enzymes persistently exceed 3 times the upper limit of normal. Avoid abrupt withdrawal of therapy to prevent rebound hypertension, tachycardia, and hypertonia; taper the dose gradually. Exercise caution in the elderly due to decreased clearance and increased risk of adverse effects. May cause significant sedation and hypotension; patients should be cautioned against driving or operating heavy machinery.', '- **Muscle Spasticity:** Management of spasticity associated with multiple sclerosis, spinal cord injury, or other central nervous system disorders.
INSERT INTO "drug_generic" VALUES(156, 'Betamethasone valerate 0.1% Topical', 'Betamethasone Valerate Topical', 'D07AC01', 0, 0, 1, 1, 0, 1, 1, 1, '[{"alert_type": "HPA Axis Suppression", "severity": "High", "trigger_condition": "Prolonged use, use over large surface areas, or use under occlusion", "message": "STOP: Systemic absorption of topical corticosteroids can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, and hyperglycemia. Avoid prolonged use and occlusive dressings."}]', '**Skin Atrophy:** Prolonged use can cause severe skin atrophy, striae, and telangiectasia, especially on the face, axillae, and groin. Avoid use in these areas if possible.
INSERT INTO "drug_generic" VALUES(157, 'Folic Acid  +  Vitamin C  +  Vitamin D3', 'Folic Acid, Ascorbic Acid, and Cholecalciferol', NULL, 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "Moderate", "trigger_condition": "Excessive intake or use in patients with renal impairment or hyperparathyroidism", "message": "Vitamin D3 supplementation can lead to hypercalcemia and hypercalciuria. Monitor serum calcium levels in susceptible patients to prevent renal damage and ectopic calcification."}]', 'Exercise caution in patients with a history of renal calculi, as high doses of Vitamin C can increase urinary oxalate excretion and the risk of kidney stones. Vitamin D should be used with caution in patients with renal impairment, hyperparathyroidism, or sarcoidosis due to the increased risk of hypercalcemia. Folic acid doses above 0.1 mg daily may obscure pernicious anemia by producing hematologic remission while neurological manifestations remain progressive; ensure vitamin B12 deficiency is ruled out.', '- **Nutritional Deficiency:** Prevention and treatment of Folic acid, Vitamin C, and Vitamin D deficiencies.
INSERT INTO "drug_generic" VALUES(158, 'Homatropine Hydrobromide Eye prep', 'Homatropine Hydrobromide', 'S01FA05', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Systemic Absorption:** Can cause systemic anticholinergic effects. To minimize absorption, apply pressure to the lacrimal sac for 1-2 minutes following instillation.
INSERT INTO "drug_generic" VALUES(159, 'Ampicillin', 'Ampicillin', 'J01CA01', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}, {"alert_type": "Clostridioides difficile-Associated Diarrhea (CDAD)", "severity": "High", "trigger_condition": "Development of severe diarrhea during or after therapy", "message": "STOP: CDAD, ranging from mild diarrhea to fatal colitis, has been reported. If suspected, discontinue ampicillin immediately and evaluate."}]', '**Infectious Mononucleosis:** A high percentage of patients with mononucleosis who receive ampicillin develop an erythematous, maculopapular skin rash. Avoid use in these patients.
INSERT INTO "drug_generic" VALUES(160, 'Levobupivacaine Hydrochloride', 'Levobupivacaine Hydrochloride', 'N01BB10', 0, 1, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Local Anesthetic Systemic Toxicity (LAST)", "severity": "High", "trigger_condition": "Inadvertent intravascular injection or excessive dosing", "message": "STOP: Inadvertent intravascular injection can cause severe Local Anesthetic Systemic Toxicity (LAST), leading to seizures, cardiac arrest, and death. Resuscitative equipment and lipid emulsion therapy must be immediately available."}]', '**Systemic Toxicity Risk:** Resuscitative equipment, oxygen, and resuscitative drugs must be immediately available whenever local anesthetics are administered.
INSERT INTO "drug_generic" VALUES(161, 'Desloratadine', 'Desloratadine', 'R06AX27', 0, 0, 1, 0, 1, 1, 1, 0, '[]', '**Slow Metabolizers:** Caution in patients who are poor metabolizers of desloratadine, as they may experience a higher incidence of side effects.
INSERT INTO "drug_generic" VALUES(162, 'Gramicidin  + Neomycin Sulphate  + Nystatin  + Triamcinolone Acetonide (Topical)', 'Gramicidin / Neomycin / Nystatin / Triamcinolone', 'D07CB01', 1, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Ototoxicity and Nephrotoxicity", "severity": "High", "trigger_condition": "Application to large surface areas, damaged skin, or prolonged use", "message": "STOP: Systemic absorption of neomycin can cause irreversible ototoxicity and nephrotoxicity. Avoid use on extensive burns, trophic ulcers, or under occlusive dressings."}]', '**Hypothalamic-Pituitary-Adrenal (HPA) Axis Suppression:** Systemic absorption of topical corticosteroids can produce reversible HPA axis suppression, manifestations of Cushing''s syndrome, hyperglycemia, and glucosuria. Risk increases with application to large surface areas, prolonged use, or use of occlusive dressings.
INSERT INTO "drug_generic" VALUES(163, 'Tirofiban', 'Tirofiban', 'B01AC17', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Bleeding Risk", "severity": "High", "trigger_condition": "Concomitant use of anticoagulants or presence of active bleeding", "message": "STOP: Tirofiban profoundly inhibits platelet aggregation and significantly increases the risk of major bleeding. Monitor platelet counts and coagulation parameters closely."}]', '**Bleeding Risk:** Tirofiban increases the risk of bleeding. Use with extreme caution in patients with anemia, active peptic ulcer disease (within the past 3 months), uncontrolled hypertension, acute pericarditis, active or history of vasculitis, suspected aortic dissection, hemorrhagic retinopathy, occult blood in stool or hematuria, or a known history of platelet function disturbance.
INSERT INTO "drug_generic" VALUES(164, 'Duvelisib', 'Duvelisib', 'L01EM04', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Fatal Infections and Toxicity", "severity": "High", "trigger_condition": "Initiation of therapy or presence of active infection", "message": "STOP: Serious, including fatal, infections, cutaneous reactions, and pneumonitis can occur. Treat active infections prior to initiation and monitor closely."}]', '**Serious Infections:** Serious and fatal infections (e.g., pneumonia, sepsis, lower respiratory tract infections) have occurred in up to 31% of patients. Cytomegalovirus (CMV) reactivation and Pneumocystis jirovecii pneumonia (PJP) have also been reported. Consider prophylactic antivirals and PJP prophylaxis during treatment. Treat any active infections prior to initiating therapy.
INSERT INTO "drug_generic" VALUES(165, 'Sodium Bicarbonate ear preparation', 'Sodium Bicarbonate Otic', 'S02DC', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Ear Damage:** Do not use if the patient has a history of ear problems, such as a damaged or perforated eardrum, or recent ear surgery, as the solution may enter the middle ear and cause irritation or infection.
INSERT INTO "drug_generic" VALUES(166, 'Loteprednol Etabonate Eye prep', 'Loteprednol Etabonate Ophthalmic', 'S01BA14', 0, 0, 0, 0, 0, 1, 1, 1, '[]', '**Intraocular Pressure (IOP) Increase:** Prolonged use of corticosteroids may result in glaucoma with damage to the optic nerve, defects in visual acuity, and fields of vision. Monitor IOP if used for 10 days or longer.
INSERT INTO "drug_generic" VALUES(167, 'Filgotinib', 'Filgotinib', 'L04AF04', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Serious Infections and Malignancy Risk", "severity": "High", "trigger_condition": "Active infection or history of malignancy", "message": "STOP: Increased risk of serious infections leading to hospitalization or death, including tuberculosis. Increased risk of malignancies and thrombosis. Use only if no suitable alternatives exist in patients >65 years, smokers, or those with cardiovascular/malignancy risk factors."}]', '**High-Risk Populations:** Should only be used if no suitable treatment alternatives are available in patients 65 years of age and older, patients with a history of atherosclerotic cardiovascular disease or other cardiovascular risk factors (e.g., current or past long-time smokers), and patients with malignancy risk factors.
INSERT INTO "drug_generic" VALUES(168, 'Pertuzumab + Trastuzumab + Hyaluronidase', 'Pertuzumab/Trastuzumab/Hyaluronidase-zzxf', 'L01XY02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiomyopathy and Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Initiation of therapy or use during pregnancy", "message": "STOP: Can cause subclinical and clinical cardiac failure. Evaluate LVEF prior to and during treatment. Exposure during pregnancy can result in oligohydramnios and fatal fetal pulmonary hypoplasia."}]', '**Cardiomyopathy:** Can cause subclinical and clinical cardiac failure manifesting as decreased left ventricular ejection fraction (LVEF) and congestive heart failure. Evaluate LVEF prior to initiation and at regular intervals during treatment. Withhold dosing for significant LVEF decline.
INSERT INTO "drug_generic" VALUES(169, 'Pentosan Polysulphate Sodium', 'Pentosan Polysulfate Sodium', 'G04BX15', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Bleeding Risk", "severity": "High", "trigger_condition": "Concurrent use of anticoagulants or presence of bleeding disorders", "message": "STOP: Pentosan polysulfate sodium has weak anticoagulant properties. Monitor for bleeding, especially in patients with coagulopathies or those undergoing surgery."}, {"alert_type": "Macular Toxicity", "severity": "High", "trigger_condition": "Long-term use", "message": "STOP: Pigmentary maculopathy has been reported with long-term use. Regular ophthalmic examinations are required."}]', 'Regular ophthalmic examinations are strongly recommended for early detection of pigmentary maculopathy, particularly in patients with prolonged exposure. Monitor platelet counts closely during treatment; therapy must be discontinued immediately if thrombocytopenia develops. Exercise extreme caution in patients with a history of hemorrhagic blood disorders, thrombocytopenia, peptic ulcer disease, cerebrovascular disorders, bacterial endocarditis, severe hypertension, or esophageal varices due to the drug''s weak anticoagulant properties. Avoid use immediately following recent surgery at sites where hemorrhage poses a significant risk. Patients with hepatic or renal impairment require careful monitoring. Clinical evaluation should be performed every 3 months; the risks and benefits of continuing treatment beyond 6 months must be carefully weighed if no symptomatic improvement is observed.', '- **Interstitial Cystitis:** Relief of bladder pain or discomfort associated with interstitial cystitis.
INSERT INTO "drug_generic" VALUES(170, 'Cyclosporine', 'Cyclosporine', 'L04AD01', 0, 1, 0, 0, 1, 1, 1, 1, '[{"alert_type": "Immunosuppression and Malignancy", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "WARNING: Increased risk of developing lymphomas and other malignancies, particularly of the skin. Increased susceptibility to severe, potentially fatal infections. Must be prescribed by physicians experienced in immunosuppressive therapy."}, {"alert_type": "Bioequivalence Warning", "severity": "High", "trigger_condition": "Switching between formulations", "message": "WARNING: Cyclosporine modified (e.g., Neoral, Gengraf) and non-modified (e.g., Sandimmune) formulations are NOT bioequivalent. Do not interchange without physician approval and strict blood level monitoring."}, {"alert_type": "Nephrotoxicity and Hypertension", "severity": "High", "trigger_condition": "Dose-dependent", "message": "WARNING: Can cause severe nephrotoxicity and hypertension. Monitor renal function and blood pressure closely. Dose reduction may be required."}]', '**Nephrotoxicity:** Dose-related nephrotoxicity is common. Monitor serum creatinine and BUN regularly. Differentiate from organ rejection in transplant patients. Reduce dose if creatinine increases significantly.
INSERT INTO "drug_generic" VALUES(171, 'Sodium Chloride + Potassium Chloride  + Calcium Chloride + Magnesium Chloride + Glacial Acetic Acid (Hemodialysis solutions)', 'Hemodialysis Concentrate (Acidified)', 'B05ZA', 0, 1, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Administration Route Safety", "severity": "High", "trigger_condition": "Direct intravenous injection or use without bicarbonate", "message": "STOP: This is an ACID concentrate for HEMODIALYSIS ONLY. It must be diluted with purified water AND mixed with a bicarbonate concentrate via a hemodialysis machine before use. Direct injection will cause fatal cardiac arrest."}]', '**Two-Part System:** This is typically the "Acid" (Part A) component of a two-part hemodialysis system. It MUST be used in conjunction with the "Bicarbonate" (Part B) component and purified water. Do not use Solution A or B alone.
INSERT INTO "drug_generic" VALUES(172, 'Nicotine', 'Nicotine', 'N07BA01', 0, 0, 0, 0, 1, 0, 0, 1, '[]', 'Use with caution in patients with severe cardiovascular disease (e.g., history of myocardial infarction, angina, heart failure, or arrhythmias), as nicotine is a sympathomimetic that increases heart rate and blood pressure. Caution is advised in patients with hyperthyroidism, pheochromocytoma, or insulin-dependent diabetes mellitus (monitor blood glucose closely, as smoking cessation may alter insulin requirements). Use cautiously in patients with hepatic or severe renal impairment. For specific formulations: avoid patches on broken skin; use gum/lozenges cautiously in active temporomandibular joint (TMJ) disease, esophagitis, or peptic ulcer disease; use inhalers/sprays cautiously in reactive airway disease.', '- **Smoking Cessation:** Indicated as an aid to smoking cessation for the relief of nicotine withdrawal symptoms and cravings, ideally used in conjunction with a comprehensive behavioral support program.', '- **Non-smokers and Occasional Smokers:** Contraindicated as they are naive to nicotine tolerance and may experience severe toxicity.
INSERT INTO "drug_generic" VALUES(173, 'Pivmecillinam', 'Pivmecillinam', 'J01CA08', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Carnitine Deficiency Risk", "severity": "Moderate", "trigger_condition": "Prolonged use or concomitant use with Valproate", "message": "STOP: Prolonged use of pivmecillinam can induce secondary carnitine deficiency. Avoid long-term continuous treatment and concurrent use with valproic acid."}]', '**Carnitine Deficiency:** Pivmecillinam is a prodrug containing a pivaloyloxymethyl ester. Excretion of pivalic acid can deplete systemic carnitine. Avoid prolonged or repeated courses, and avoid concurrent use with other pivalate-generating drugs (e.g., valproate).
INSERT INTO "drug_generic" VALUES(174, 'Lesinurad', 'Lesinurad', 'M04AX02', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Acute Renal Failure Risk", "severity": "High", "trigger_condition": "Use as monotherapy or in patients with severe renal impairment", "message": "STOP: Acute renal failure has occurred with lesinurad. It MUST be used in combination with a xanthine oxidase inhibitor (XOI). Do not use as monotherapy. Contraindicated in severe renal impairment (CrCl <30 mL/min)."}]', '- **Renal Function:** Acute renal failure has occurred, particularly when used as monotherapy or at doses exceeding 200 mg/day. Monitor renal function (serum creatinine/CrCl) at initiation and periodically during therapy. Evaluate for signs of acute uric acid nephropathy.
INSERT INTO "drug_generic" VALUES(175, 'Calcium Lactate Gluconate + Calcium Carbonate (elemental calcium) + Vitamin D3 (cholecalciferol)', 'Calcium Lactate Gluconate + Calcium Carbonate + Cholecalciferol', 'A12AX', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Renal Impairment and Hypercalciuria:** Patients with mild to moderate renal failure or mild hypercalciuria should be supervised carefully, including periodic checks of plasma calcium levels and urinary calcium excretion. In patients with a history of renal stones, urinary calcium excretion should be measured to exclude hypercalciuria.
INSERT INTO "drug_generic" VALUES(176, 'Molnupiravir', 'Molnupiravir', 'J05EX14', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Use in pregnant individuals or individuals of childbearing potential not using effective contraception", "message": "STOP: Molnupiravir is not recommended during pregnancy due to the risk of embryo-fetal toxicity. Verify pregnancy status before prescribing."}, {"alert_type": "Bone and Cartilage Toxicity", "severity": "High", "trigger_condition": "Use in pediatric patients (<18 years of age)", "message": "STOP: Molnupiravir is not authorized for use in patients less than 18 years of age because it may affect bone and cartilage growth."}]', '- **Contraception Requirements:** Females of childbearing potential must use effective contraception correctly and consistently during treatment and for 4 days after the last dose. Males with female partners of childbearing potential should use reliable contraception during treatment and for at least 3 months after the last dose.
INSERT INTO "drug_generic" VALUES(177, 'Sulfacetamide Sodium 10% Eye prep', 'Sulfacetamide Sodium', 'S01AB04', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Severe Hypersensitivity", "severity": "High", "trigger_condition": "History of sulfonamide allergy", "message": "Fatalities have occurred, although rarely, due to severe reactions to sulfonamides including Stevens-Johnson syndrome, toxic epidermal necrolysis, and fulminant hepatic necrosis, even with ophthalmic administration."}]', '**Hypersensitivity Reactions:** Severe allergic reactions, including Stevens-Johnson syndrome, can occur even with topical ophthalmic use due to systemic absorption. Discontinue immediately if rash or signs of hypersensitivity develop.
INSERT INTO "drug_generic" VALUES(178, 'Imatinib', 'Imatinib', 'L01EA01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Fluid Retention and Edema", "severity": "High", "trigger_condition": "Patients with underlying cardiac disease or elderly patients", "message": "STOP: Severe fluid retention (pleural effusion, pericardial effusion, pulmonary edema, and ascites) can occur. Monitor weights regularly and manage with diuretics or dose reduction."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Patients with pre-existing hepatic impairment or concurrent hepatotoxic medications", "message": "STOP: Severe and potentially fatal hepatotoxicity may occur. Monitor liver function tests (LFTs) prior to initiation and monthly thereafter."}]', 'Monitor closely for signs of severe fluid retention, including unexpected rapid weight gain, pleural effusion, or pulmonary edema; weigh patients regularly. Use with extreme caution in patients with cardiac disease or risk factors for congestive heart failure (CHF); monitor left ventricular ejection fraction (LVEF) in patients with cardiac comorbidities. Severe cytopenias (neutropenia, thrombocytopenia, anemia) are common; perform complete blood counts (CBC) weekly for the first month, biweekly for the second month, and periodically thereafter. Hepatotoxicity, occasionally severe or fatal, has been reported; monitor liver function tests (bilirubin, AST, ALT, alkaline phosphatase) before initiation and monthly. Gastrointestinal perforation, sometimes fatal, has occurred; evaluate promptly if severe abdominal pain presents. Tumor lysis syndrome (TLS) may occur in patients with rapidly growing tumors or high tumor burden; correct dehydration and treat high uric acid levels prior to initiation. Dermatologic toxicities, including Stevens-Johnson syndrome (SJS) and erythema multiforme, require immediate discontinuation if severe. Growth retardation has been reported in children and prepubertal adolescents; monitor growth closely in pediatric patients.', '- **Chronic Myeloid Leukemia (CML):** Treatment of newly diagnosed adult and pediatric patients with Philadelphia chromosome-positive (Ph+) CML in chronic phase, or patients in chronic, accelerated, or blast crisis phase after failure of interferon-alpha therapy.
INSERT INTO "drug_generic" VALUES(179, 'Tranexamic Acid', 'Tranexamic Acid', 'B02AA02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "Concomitant use with hormonal contraceptives or factor IX complex concentrates", "message": "STOP: Increased risk of severe and potentially fatal thrombotic events. Evaluate patient for active intravascular clotting or history of thromboembolic disease before administration."}]', 'Monitor closely in patients with disseminated intravascular coagulation (DIC), as use may require concomitant heparin therapy. Exercise caution in patients with mild to moderate renal impairment; dose reduction is necessary to prevent accumulation. Conduct regular liver function tests and comprehensive eye examinations (including visual acuity, slit lamp, and fundoscopy) during long-term therapy. Discontinue immediately if any disturbance in color vision occurs. When administering intravenously, avoid injection rates exceeding 1 mL/minute to mitigate the risk of severe hypotension. Use with caution in patients with a history of thromboembolic disease or upper urinary tract bleeding (risk of ureteral obstruction due to clot formation).', '- **Hemorrhage Management**: Prophylaxis and treatment of hemorrhage associated with excessive fibrinolysis, including hemoptysis, gastrointestinal bleeding, and hemorrhagic syndromes in leukemia, cirrhosis, and hemophilia.
INSERT INTO "drug_generic" VALUES(180, 'Defibrotide', 'Defibrotide', 'B01AX01', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Severe Bleeding Risk", "severity": "High", "trigger_condition": "Concurrent use of systemic anticoagulants or active bleeding", "message": "STOP: Defibrotide increases the activity of fibrinolytic enzymes and significantly increases the risk of bleeding. Do not initiate in patients with active bleeding. Coadministration with systemic anticoagulants or fibrinolytic therapy is strictly contraindicated."}]', '**Bleeding Risk:** Defibrotide increases the activity of fibrinolytic enzymes in vitro and may increase the risk of bleeding in patients with veno-occlusive disease (VOD). Do not initiate in patients with active bleeding. Monitor patients closely for signs of bleeding. If bleeding occurs, discontinue the drug, treat the underlying cause, and provide supportive care.
INSERT INTO "drug_generic" VALUES(181, 'Nivolumab', 'Nivolumab', 'L01FF01', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Immune-Mediated Adverse Reactions", "severity": "High", "trigger_condition": "Patients presenting with new-onset respiratory, gastrointestinal, hepatic, or endocrine symptoms", "message": "STOP: Severe and fatal immune-mediated adverse reactions (pneumonitis, colitis, hepatitis, endocrinopathies, nephritis, encephalitis) can occur. Withhold therapy and initiate high-dose corticosteroids promptly if suspected."}]', '**Immune-Mediated Pneumonitis:** Severe, life-threatening, or fatal pneumonitis can occur. Monitor patients for signs and symptoms of pneumonitis. Evaluate suspected pneumonitis with radiographic imaging. Administer corticosteroids for Grade 2 or greater pneumonitis.
INSERT INTO "drug_generic" VALUES(182, 'Aspirin', 'Aspirin', 'B01AC06', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Reye''s Syndrome", "severity": "High", "trigger_condition": "Use in children or teenagers with viral infections", "message": "STOP: Aspirin is contraindicated in children and teenagers with viral illnesses (e.g., chickenpox, influenza) due to the risk of Reye''s syndrome, a rare but often fatal condition causing encephalopathy and liver damage."}, {"alert_type": "Gastrointestinal Bleeding", "severity": "High", "trigger_condition": "History of peptic ulcer disease or concurrent NSAID/anticoagulant use", "message": "STOP: Aspirin increases the risk of severe gastrointestinal bleeding and ulceration. Use with extreme caution in patients with a history of GI bleeds."}]', '**Bleeding Disorders:** Use with extreme caution in patients with bleeding disorders, severe hepatic impairment, or vitamin K deficiency.
INSERT INTO "drug_generic" VALUES(183, 'Lomefloxacin', 'Lomefloxacin', 'J01MA07', 1, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Fluoroquinolone Toxicity", "severity": "High", "trigger_condition": "Prescription of systemic fluoroquinolones", "message": "STOP: Fluoroquinolones are associated with disabling and potentially irreversible serious adverse reactions, including tendinitis, tendon rupture, peripheral neuropathy, and central nervous system effects."}]', '**Tendinitis and Tendon Rupture:** Fluoroquinolones are associated with an increased risk of tendinitis and tendon rupture in all ages. This risk is further increased in older patients (usually over 60 years of age), in patients taking corticosteroid drugs, and in patients with kidney, heart, or lung transplants.
INSERT INTO "drug_generic" VALUES(184, 'Zidovudine', 'Zidovudine', 'J05AF01', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Hematologic Toxicity and Myopathy", "severity": "High", "trigger_condition": "Prolonged use or pre-existing bone marrow suppression", "message": "STOP: Zidovudine is associated with severe hematologic toxicity (neutropenia and severe anemia) and symptomatic myopathy with prolonged use. Monitor CBC closely."}, {"alert_type": "Lactic Acidosis and Hepatomegaly", "severity": "High", "trigger_condition": "Use of nucleoside analogues", "message": "STOP: Lactic acidosis and severe hepatomegaly with steatosis, including fatal cases, have been reported with the use of nucleoside analogues alone or in combination."}]', '**Hematologic Toxicity:** Frequent blood counts are strongly recommended in patients with advanced HIV disease. Cautious use is advised in patients with compromised bone marrow function.
INSERT INTO "drug_generic" VALUES(185, 'Sufentanil', 'Sufentanil', 'N01AH03', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Profound Respiratory Depression and Addiction Risk", "severity": "High", "trigger_condition": "Initiation of therapy or concomitant use with CNS depressants", "message": "STOP: Sufentanil is 5 to 10 times more potent than fentanyl. It causes profound, life-threatening respiratory depression. It must only be administered by personnel trained in airway management. Concomitant use with CNS depressants can result in coma and death."}]', '**Respiratory Depression:** Serious, life-threatening, or fatal respiratory depression may occur. Sufentanil is highly potent. Monitor closely. Use with extreme caution in patients with asthma, pulmonary disease, or decreased respiratory reserve.
INSERT INTO "drug_generic" VALUES(186, 'Poly (0-2 hydroxyethyl) Starch (Molar Substitution)', 'Hydroxyethyl Starch (HES)', 'B05AA07', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Mortality and Renal Injury", "severity": "High", "trigger_condition": "Critically ill patients, including sepsis or ICU admission", "message": "STOP: Do not use HES solutions in critically ill adult patients, including those with sepsis, due to increased risk of mortality and severe renal injury requiring renal replacement therapy."}, {"alert_type": "Anaphylactoid Reactions", "severity": "High", "trigger_condition": "During intravenous infusion", "message": "STOP: Severe anaphylactoid reactions can occur. Discontinue immediately if hypersensitivity develops."}]', 'Fluid status and the rate of infusion must be assessed regularly during treatment to prevent fluid overload, especially in patients with cardiac insufficiency or severe kidney dysfunction. In cases of severe dehydration, a crystalloid solution should be administered first. Monitor coagulation parameters closely, as HES can cause dilutional coagulopathy and affect platelet function. Exercise extreme caution in patients with severe liver disease or severe bleeding disorders (e.g., von Willebrand''s disease). Discontinue use at the first sign of renal injury or coagulopathy.', '- **Hypovolemia and Shock:** Treatment and prophylaxis of hypovolemia and shock due to acute blood loss (e.g., surgery, trauma, burns) when crystalloids alone are not considered sufficient.
INSERT INTO "drug_generic" VALUES(187, 'Eluxadoline', 'Eluxadoline', 'A07DA06', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Sphincter of Oddi Spasm and Pancreatitis", "severity": "High", "trigger_condition": "Patients without a gallbladder or heavy alcohol users", "message": "STOP: Contraindicated in patients without a gallbladder due to a high risk of severe sphincter of Oddi spasm and pancreatitis. Evaluate alcohol intake; contraindicated in patients who drink >3 alcoholic beverages/day."}]', '- **Sphincter of Oddi Spasm:** Can cause sphincter of Oddi spasm, resulting in pancreatitis or hepatic enzyme elevation associated with acute abdominal pain. Risk is significantly higher in patients without a gallbladder.
INSERT INTO "drug_generic" VALUES(188, 'Probiotic + Prebiotic + Vitamin K2-7', 'Probiotic, Prebiotic, and Menaquinone-7', 'A07FA', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anticoagulant Interaction", "severity": "High", "trigger_condition": "Concurrent use of Warfarin", "message": "STOP: Vitamin K2-7 directly opposes the mechanism of Vitamin K antagonists (like Warfarin/Coumadin), leading to subtherapeutic INR levels and a high risk of thrombosis. Avoid concurrent use."}]', '**Immunocompromised Patients:** While generally safe, probiotics carry a rare risk of bacteremia or fungemia in severely ill, immunocompromised, or organ transplant recipients. Use under medical supervision.
INSERT INTO "drug_generic" VALUES(189, 'Dexpanthenol topical', 'Dexpanthenol', 'D03AX03', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **External Use Only:** Do not ingest. Avoid contact with the eyes and mucous membranes.
INSERT INTO "drug_generic" VALUES(190, 'Dextrose 10%', 'Dextrose 10% in Water (D10W)', 'B05BA03', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hyperosmolar Coma and Fluid Overload", "severity": "High", "trigger_condition": "Rapid infusion or use in severe renal/cardiac impairment", "message": "STOP: Rapid administration of hypertonic dextrose can cause hyperglycemia, hyperosmolar syndrome, and fluid overload. Monitor blood glucose and electrolytes closely."}]', '**Hyperglycemia & Osmotic Diuresis:** Rapid administration may result in significant hyperglycemia, hyperosmolar syndrome, and osmotic diuresis leading to dehydration. Monitor blood glucose frequently, especially in diabetic patients.
INSERT INTO "drug_generic" VALUES(191, 'Fosfomycin Sodium', 'Fosfomycin Sodium', 'J01XX01', 1, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of hypersensitivity", "message": "STOP: Acute, potentially life-threatening hypersensitivity reactions (anaphylactic shock) may occur. At the first signs (sweating, nausea, cyanosis), immediately discontinue the infusion."}, {"alert_type": "High Sodium Load", "severity": "Moderate", "trigger_condition": "Patients with heart failure, hypertension, or renal impairment", "message": "Caution: Intravenous fosfomycin contains a high sodium load. Monitor serum electrolytes (especially potassium) and fluid balance closely. A low-sodium diet may be required."}]', 'Monitor serum electrolytes and fluid balance regularly during therapy, as the high sodium load associated with intravenous fosfomycin can lead to hypernatremia and secondary hypokalemia. Potassium supplementation may be necessary. Exercise caution in patients with cardiac insufficiency, hypertension, hyperaldosteronism, hypernatremia, or pulmonary edema.
INSERT INTO "drug_generic" VALUES(192, 'Citicoline', 'Citicoline', 'N06BX06', 0, 0, 0, 0, 0, 0, 0, 0, '[]', '**Parasympathetic Hypertonia:** Use with caution in patients with hypertonia of the parasympathetic nervous system, as citicoline may exacerbate symptoms.
INSERT INTO "drug_generic" VALUES(193, 'COVID-19 mRNA Vaccine (Pfizer-Biontech)', 'COVID-19 Vaccine, mRNA (Pfizer-BioNTech)', 'J07BN01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe allergic reaction to any component of the vaccine", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history, specifically to polyethylene glycol (PEG), before administration."}]', '**Anaphylaxis and Hypersensitivity:** Appropriate medical treatment used to manage immediate allergic reactions must be immediately available in the event an acute anaphylactic reaction occurs following administration.
INSERT INTO "drug_generic" VALUES(194, 'Darunavir + Cobicistat', 'Darunavir and Cobicistat', 'J05AR14', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Underlying chronic hepatitis or elevated transaminases", "message": "Caution: Drug-induced hepatitis, including fatal cases, can occur. Monitor liver function closely before and during therapy."}, {"alert_type": "Severe Skin Reactions", "severity": "High", "trigger_condition": "Development of severe rash with systemic symptoms", "message": "STOP: Severe skin reactions (SJS, TEN, DRESS, AGEP) can occur. Discontinue treatment immediately if a severe reaction develops."}]', '**Sulfa Allergy:** Darunavir contains a sulfonamide moiety. Use with caution in patients with a known sulfonamide allergy.
INSERT INTO "drug_generic" VALUES(195, 'Simethicone', 'Simethicone', 'A03AX13', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Underlying Conditions:** Simethicone provides symptomatic relief of gas but does not treat the underlying cause. If symptoms persist, worsen, or are accompanied by severe abdominal pain, changes in bowel habits, or weight loss, a thorough medical evaluation is required to rule out serious gastrointestinal pathology.
INSERT INTO "drug_generic" VALUES(196, 'Dextrose 25%', 'Dextrose 25% in Water', 'B05BA03', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hyperosmolar Coma and Tissue Necrosis", "severity": "High", "trigger_condition": "Peripheral administration or rapid infusion", "message": "STOP: Highly hyperosmolar solution. Must be administered via a central venous catheter for continuous infusion to prevent severe phlebitis and tissue necrosis. Rapid infusion can cause fatal hyperosmolar syndrome."}]', '**Hyperglycemia & Osmotic Diuresis:** Rapid administration may result in significant hyperglycemia, hyperosmolar syndrome, and osmotic diuresis leading to dehydration. Monitor blood glucose frequently.
INSERT INTO "drug_generic" VALUES(197, 'Arsenic Trioxide', 'Arsenic Trioxide', 'L01XX27', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "APL Differentiation Syndrome", "severity": "High", "trigger_condition": "During induction therapy", "message": "STOP: Can cause APL differentiation syndrome, which can be fatal. Symptoms include fever, dyspnea, weight gain, pulmonary infiltrates, and pleural/pericardial effusions. Treat immediately with high-dose corticosteroids."}, {"alert_type": "Cardiac Conduction Abnormalities", "severity": "High", "trigger_condition": "During therapy", "message": "STOP: Can cause QT interval prolongation and complete atrioventricular block. Monitor ECG and electrolytes (potassium, magnesium) frequently. Correct electrolyte abnormalities before and during treatment."}]', '**Hepatotoxicity:** Elevated AST, alkaline phosphatase, and bilirubin have occurred, especially when combined with tretinoin. Monitor hepatic function tests at least twice weekly during induction and once weekly during consolidation. Withhold and resume at a reduced dose upon resolution.
INSERT INTO "drug_generic" VALUES(198, 'Tamsulosin + Dutasteride', 'Tamsulosin and Dutasteride', 'G04CA52', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Teratogenicity Risk", "severity": "High", "trigger_condition": "Handling by pregnant women or women of childbearing potential", "message": "Dutasteride can be absorbed through the skin and cause severe fetal harm (feminization of male fetuses). Women who are pregnant or may become pregnant must not handle leaking capsules."}]', 'Rule out prostate carcinoma and other urological conditions before initiating therapy, as BPH and prostate cancer share similar symptoms. Dutasteride reduces serum prostate-specific antigen (PSA) levels by approximately 50% within 3-6 months; establish a new baseline PSA after 6 months of treatment to accurately monitor for prostate cancer. Use caution in patients with a history of orthostatic hypotension or sulfa allergy. Patients should not donate blood during therapy and for at least 6 months following discontinuation to prevent administration to a pregnant transfusion recipient. Intraoperative Floppy Iris Syndrome (IFIS) has been observed during cataract surgery in patients treated with alpha-1 blockers; advise ophthalmologists of current or prior use.', '- Treatment of symptomatic benign prostatic hyperplasia (BPH) in men with an enlarged prostate.
INSERT INTO "drug_generic" VALUES(199, 'Progesterone vaginal prep', 'Progesterone', 'G03DA04', 0, 0, 1, 0, 0, 0, 0, 1, '[{"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "Patient presenting with sudden vision loss, severe headache, or signs of DVT/PE", "message": "STOP: Discontinue immediately if signs of thrombotic disorders (thrombophlebitis, cerebrovascular disorders, pulmonary embolism, retinal thrombosis) occur."}]', '**Thromboembolic Disorders:** The physician should be alert to the earliest manifestations of thrombotic disorders (thrombophlebitis, cerebrovascular disorders, pulmonary embolism, and retinal thrombosis). Discontinue the drug immediately if any of these occur or are suspected.
INSERT INTO "drug_generic" VALUES(200, 'Amoxicillin', 'Amoxicillin', 'J01CA04', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}, {"alert_type": "Clostridioides difficile-Associated Diarrhea (CDAD)", "severity": "High", "trigger_condition": "Development of severe diarrhea during or after therapy", "message": "STOP: CDAD, ranging from mild diarrhea to fatal colitis, has been reported. If suspected, discontinue amoxicillin immediately and evaluate."}]', '**Severe Cutaneous Adverse Reactions (SCAR):** Stevens-Johnson syndrome (SJS), toxic epidermal necrolysis (TEN), DRESS, and AGEP have been reported. Discontinue immediately if a progressive skin rash occurs.
INSERT INTO "drug_generic" VALUES(201, 'Ipratropium Bromide + Salbutamol', 'Ipratropium Bromide and Albuterol', 'R03AL02', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Inhalation of the drug", "message": "STOP: Inhaled medicines can cause life-threatening paradoxical bronchospasm. If this occurs, discontinue immediately and institute alternative therapy."}]', '- Caution in patients with cardiovascular disease (coronary insufficiency, arrhythmias, hypertension), as beta-agonists can increase heart rate, blood pressure, and precipitate angina or arrhythmias.
INSERT INTO "drug_generic" VALUES(202, 'Benzocaine', 'Benzocaine', 'N01BA05', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Methemoglobinemia", "severity": "High", "trigger_condition": "Use of oral benzocaine products", "message": "STOP: Benzocaine can cause fatal methemoglobinemia. The FDA strongly warns against using oral benzocaine products for teething in children under 2 years of age. Advise adults to seek immediate medical attention if cyanosis, headache, or shortness of breath occurs."}]', '**Application Site:** Avoid contact with the eyes. Avoid prolonged use or application over extensive areas of the body or on severely traumatized mucosa, as this increases systemic absorption and the risk of methemoglobinemia.
INSERT INTO "drug_generic" VALUES(203, 'Imipenem + Cilastatin + Relebactam', 'Imipenem, Cilastatin, and Relebactam', 'J01DH56', 1, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Carbapenem, Penicillin, or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}, {"alert_type": "Neurological Toxicity", "severity": "High", "trigger_condition": "Patients with underlying CNS disorders or compromised renal function", "message": "WARNING: Increased risk of seizures and other CNS adverse reactions. Adjust dose strictly according to renal function and monitor closely."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. Cross-reactivity among beta-lactam antibiotics can occur. Carefully assess allergy history prior to initiation.
INSERT INTO "drug_generic" VALUES(204, 'Pirfenidone', 'Pirfenidone', 'L04AX05', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated liver transaminases (AST/ALT)", "message": "STOP: Drug-induced liver injury, including severe and fatal cases, has been reported. Monitor liver function tests (ALT, AST, and bilirubin) prior to initiation, monthly for the first 6 months, and every 3 months thereafter."}]', '**Hepatic Impairment and Hepatotoxicity:** Severe drug-induced liver injury can occur. Monitor liver function tests (ALT, AST, bilirubin) before starting, monthly for the first 6 months, and then every 3 months. Adjust dose or discontinue if significant elevations occur.
INSERT INTO "drug_generic" VALUES(205, 'Sunitinib', 'Sunitinib', 'L01EX01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Routine therapy", "message": "STOP: Severe hepatotoxicity, including liver failure and death, has been observed. Monitor liver function tests before initiation, during each cycle, and as clinically indicated."}, {"alert_type": "Cardiovascular Events", "severity": "High", "trigger_condition": "Patients with a history of cardiac disease or QT prolongation", "message": "STOP: Sunitinib can cause severe cardiovascular events, including heart failure, myocardial ischemia, and QT interval prolongation. Monitor LVEF and ECG periodically."}]', 'Monitor closely for signs of congestive heart failure (CHF), hypertension, and hemorrhagic events. Perform baseline and periodic evaluations of left ventricular ejection fraction (LVEF). Monitor ECG for QT interval prolongation, especially in patients with a history of arrhythmias, bradycardia, or electrolyte disturbances. Monitor thyroid function at baseline and periodically, as hypothyroidism may occur. Perform complete blood counts (CBC) and comprehensive metabolic panels regularly. May cause impaired wound healing; withhold treatment prior to elective surgery. Monitor for signs of tumor lysis syndrome and thrombotic microangiopathy.', '- **Gastrointestinal Stromal Tumor (GIST):** Treatment of GIST after disease progression on or intolerance to imatinib mesylate.
INSERT INTO "drug_generic" VALUES(206, 'Pimecrolimus 1% Topical', 'Pimecrolimus Topical', 'D11AH02', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Malignancy Risk", "severity": "High", "trigger_condition": "Long-term continuous use", "message": "STOP: Long-term safety is not established. Rare cases of malignancy (e.g., skin cancer and lymphoma) have been reported. Avoid continuous long-term use and limit application to areas of involvement."}]', 'Avoid application to areas affected by active cutaneous viral infections (e.g., herpes simplex, varicella). Avoid contact with eyes and mucous membranes. Due to the theoretical risk of immunosuppression and subsequent malignancies (lymphoma, skin cancer), limit exposure to natural or artificial sunlight (UV light) during treatment. A mild to moderate sensation of warmth or burning may occur at the application site within the first 1-5 days of therapy; this is usually transient. Safety of continuous usage beyond 1 year is not established. Use with caution in patients with severe hepatic impairment. Monitor renal, hepatic, cardiac, and visual functions, as well as blood pressure, serum glucose, and electrolytes regularly in patients with extensive disease or prolonged use.', '- **Atopic Dermatitis (Eczema):** Short-term and intermittent long-term treatment of mild to moderate atopic dermatitis in non-immunocompromised patients who have failed to respond adequately to other topical prescription treatments, or when those treatments are not advisable.', '- **Hypersensitivity:** Contraindicated in patients with a history of hypersensitivity to pimecrolimus or any component of the formulation.
INSERT INTO "drug_generic" VALUES(207, 'Zolpidem Tartrate', 'Zolpidem', 'N05CF02', 0, 1, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Complex Sleep Behaviors", "severity": "High", "trigger_condition": "Use of sedative-hypnotics", "message": "STOP: Complex sleep behaviors including sleep-walking, sleep-driving, and engaging in other activities while not fully awake may occur. Some of these events have resulted in severe injuries or death. Discontinue immediately if a patient experiences a complex sleep behavior."}]', '**CNS Depression:** Causes CNS depression and impairs daytime function. Risk increases with dose and concurrent use of other CNS depressants.
INSERT INTO "drug_generic" VALUES(208, 'Indomethacin', 'Indomethacin', 'M01AB01', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "All patients, especially those with a history of CV disease or peptic ulcer disease", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events (MI, stroke) and serious gastrointestinal adverse events (bleeding, ulceration, perforation), which can be fatal. Contraindicated for CABG perioperative pain."}]', 'Use with extreme caution in patients with a history of cardiovascular disease, hypertension, or heart failure, as NSAIDs can cause fluid retention and exacerbate these conditions. High risk of severe gastrointestinal toxicity (bleeding, ulceration, perforation); use cautiously in patients with a history of peptic ulcer disease or GI bleeding, and consider concurrent use of a PPI. Can cause acute renal failure; monitor renal function closely in patients with pre-existing renal impairment, heart failure, liver dysfunction, or those taking diuretics/ACE inhibitors. May mask signs of infection (fever, inflammation). Use cautiously in patients with psychiatric disorders, epilepsy, or Parkinsonism, as indomethacin can aggravate these conditions. Monitor for hepatotoxicity; discontinue if abnormal LFTs persist or worsen. Can inhibit platelet aggregation; use cautiously in patients with bleeding disorders.', '- **Rheumatoid Arthritis & Osteoarthritis:** Symptomatic treatment of moderate to severe rheumatoid arthritis, ankylosing spondylitis, and osteoarthritis.
INSERT INTO "drug_generic" VALUES(209, 'L-Ornithine + L-Aspartate', 'L-Ornithine L-Aspartate', 'A05BA06', 0, 0, 0, 0, 1, 1, 0, 0, '[]', '**Renal Function:** Monitor renal function closely. The drug is excreted via the kidneys, and accumulation can occur in patients with renal impairment.
INSERT INTO "drug_generic" VALUES(210, 'Acyclovir 3% Eye prep', 'Acyclovir Ophthalmic', 'S01AD03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Contact Lens Warning", "severity": "High", "trigger_condition": "Patient wearing contact lenses during active infection", "message": "STOP: Patients must NOT wear contact lenses if they have signs or symptoms of herpetic keratitis or during the entire course of ophthalmic acyclovir therapy."}]', '**Ophthalmic Use Only:** This preparation is strictly for topical application to the eye. Do not swallow or inject.
INSERT INTO "drug_generic" VALUES(211, 'Degarelix Acetate', 'Degarelix', 'L02BX02', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Administration of dose", "message": "Severe hypersensitivity reactions, including anaphylaxis, urticaria, and angioedema, have been reported. Discontinue immediately if a severe reaction occurs and manage clinically."}]', 'Use with caution in patients with moderate to severe renal impairment (CrCl <50 mL/min) and severe hepatic impairment, as data are limited in these populations.
INSERT INTO "drug_generic" VALUES(212, 'Roflumilast topical', 'Roflumilast', 'D05AX06', 0, 0, 0, 0, 0, 0, 1, 0, '[]', '**Hepatic Impairment:** Systemic exposure to roflumilast and its active metabolite is significantly increased in patients with hepatic impairment. Use is contraindicated in patients with moderate-to-severe liver impairment (Child-Pugh B or C).
INSERT INTO "drug_generic" VALUES(213, 'Clascoterone topical', 'Clascoterone topical cream', 'D10AX06', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Local Skin Irritation:** May induce local irritation, including erythema, pruritus, scaling, and dryness. Limit concomitant use with other potentially irritating topical products (e.g., those with high alcohol content, astringents, or strong drying agents).
INSERT INTO "drug_generic" VALUES(214, 'Bacitracin + Lidocaine topical', 'Bacitracin and Lidocaine', 'D06AX', 1, 0, 0, 0, 0, 0, 0, 0, '[]', '**External Use Only:** For topical external use only. Avoid contact with the eyes, nose, or mouth.
INSERT INTO "drug_generic" VALUES(215, 'Ferrous Sulphate + Folic Acid + Zinc', 'Ferrous Sulfate, Folic Acid, and Zinc', 'B03AD03', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Iron Toxicity Risk", "severity": "High", "trigger_condition": "Accidental overdose in pediatric patients", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep out of reach of children."}]', '- **Iron Overload:** Care should be taken in patients who may develop iron overload, such as those with hemochromatosis, hemolytic anemia, or red cell aplasia.
INSERT INTO "drug_generic" VALUES(216, 'Atropine + Pralidoxime', 'Atropine and Pralidoxime', 'V03AB', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Life-Threatening Emergency Use", "severity": "High", "trigger_condition": "Organophosphate nerve agent or insecticide poisoning", "message": "STOP: This combination is intended strictly for life-threatening organophosphate poisoning. Administer immediately upon recognition of severe symptoms. Do not delay treatment."}]', '**Cardiovascular Risks:** May induce tachycardia, palpitations, premature ventricular contractions, flutter, or fibrillation. Exercise extreme caution in individuals with known cardiovascular disease or conduction abnormalities.
INSERT INTO "drug_generic" VALUES(217, 'Acyclovir 5% + Hydrocortisone 1%  Topical', 'Acyclovir and Hydrocortisone Topical', 'D06BB53', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Application Site Restrictions:** Do not apply to the eye, inside the mouth or nose, or on the genitals. For external use on the lips and face only.
INSERT INTO "drug_generic" VALUES(218, 'Perindopril + Amlodipine', 'Perindopril and Amlodipine', 'C09BB04', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Discontinue immediately if pregnancy is detected. Drugs that act directly on the renin-angiotensin system can cause fetal injury and death during the second and third trimesters."}, {"alert_type": "Angioedema Risk", "severity": "High", "trigger_condition": "Swelling of face, lips, tongue, or airway", "message": "ACE inhibitors can cause severe angioedema. Discontinue immediately and secure the airway if angioedema occurs. Contraindicated in patients with a history of idiopathic or ACE-inhibitor-induced angioedema."}]', 'Use with caution in patients with salt or volume depletion, as severe symptomatic hypotension may occur. Correct volume depletion prior to initiation.
INSERT INTO "drug_generic" VALUES(219, 'Cetrorelix', 'Cetrorelix', 'H01CC02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "First injection or history of severe allergic reactions", "message": "STOP: Severe anaphylactic reactions have been reported. The first injection should be administered under direct medical supervision, and patients must be monitored closely for hypersensitivity."}]', '**Hypersensitivity:** Severe anaphylactic reactions can occur. Monitor closely following the first injection. Use with caution in patients with active allergic conditions or a history of severe allergies.
INSERT INTO "drug_generic" VALUES(220, 'Travoprost 0.004% Eye prep', 'Travoprost Ophthalmic', 'S01EE04', 0, 0, 0, 0, 0, 1, 0, 0, '[]', 'May cause permanent changes to the eye, including increased pigmentation of the iris, periorbital tissue (eyelid), and eyelashes. Eyelash changes include increased length, thickness, and number of lashes. Use with caution in patients with active intraocular inflammation (e.g., uveitis, iritis) as it may exacerbate the condition. Caution is advised in aphakic patients, pseudophakic patients with a torn posterior lens capsule, or patients with known risk factors for macular edema. Contains benzalkonium chloride, which may be absorbed by soft contact lenses; remove lenses prior to administration and wait at least 15 minutes before reinserting.', '- **Elevated Intraocular Pressure (IOP)**: Reduction of elevated IOP in patients with open-angle glaucoma or ocular hypertension.', '- **Hypersensitivity**: Contraindicated in patients with known hypersensitivity to travoprost or any excipients in the formulation.
INSERT INTO "drug_generic" VALUES(221, 'Paracetamol + Diphenhydramine + Dextromethorphan', 'Acetaminophen, Diphenhydramine, and Dextromethorphan', 'N02BE51', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Exceeding maximum daily dose of paracetamol or concurrent alcohol use", "message": "STOP: Severe hepatotoxicity can occur if the maximum daily dose of paracetamol (4000 mg) is exceeded. Verify all concurrent medications to ensure no other paracetamol-containing products are being used."}]', '**Hepatotoxicity:** Paracetamol can cause severe, potentially fatal liver damage. Risk is increased in chronic alcoholics, patients with underlying hepatic impairment, or when combined with other paracetamol-containing products.
INSERT INTO "drug_generic" VALUES(222, 'Iron Hydroxide Polymaltose', 'Iron Polymaltose', 'B03AB05', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Anaphylaxis Risk (Parenteral)", "severity": "High", "trigger_condition": "Intravenous or Intramuscular administration", "message": "STOP: Parenteral iron administration carries a risk of severe and potentially fatal anaphylactoid reactions. Facilities for cardiopulmonary resuscitation must be available during administration."}]', '**Parenteral Administration Risks:** Intravenous or intramuscular administration should only be used when oral therapy is unacceptable or ineffective. Excessive IV infusion rates may cause nausea, epigastric upset, and hypotension. Ensure resuscitation equipment is readily available.
INSERT INTO "drug_generic" VALUES(223, 'Efinaconazole topical', 'Efinaconazole', 'D01AC19', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**For Topical Use Only:** Not for oral, ophthalmic, or intravaginal use. Avoid contact with eyes, mouth, and vagina.
INSERT INTO "drug_generic" VALUES(224, 'Lasmiditan', 'Lasmiditan', 'N02CC08', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Driving Impairment and CNS Depression", "severity": "High", "trigger_condition": "Administration of any dose", "message": "STOP: Significant driving impairment may occur. Advise patients NOT to engage in potentially hazardous activities requiring complete mental alertness (e.g., driving, operating machinery) for at least 8 hours after each dose, even if they feel well enough to do so."}]', '**CNS Depression:** May cause significant central nervous system depression, including dizziness and sedation. Use with caution in combination with alcohol or other CNS depressants.
INSERT INTO "drug_generic" VALUES(225, 'Varicella Zoster Virus Vaccine (Live Attenuated OKA Strain)', 'Varicella Virus Vaccine Live', 'J07BK01', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Immunocompromised Status", "severity": "High", "trigger_condition": "Administration to severely immunocompromised patients or those with a history of anaphylaxis to vaccine components", "message": "STOP: Contraindicated in patients with severe primary or acquired immunodeficiency (e.g., leukemia, lymphoma, severe HIV, high-dose corticosteroids) due to the risk of fatal disseminated vaccine virus infection. Ensure epinephrine is available to treat potential anaphylaxis."}]', '**Recent Blood Products:** Vaccination should be deferred for at least 5-11 months following blood or plasma transfusion, or administration of immune globulin, as passive antibodies can interfere with the immune response.
INSERT INTO "drug_generic" VALUES(226, 'Formoterol Fumarate + Glycopyrrolate + Budesonide inhaler', 'Budesonide + Glycopyrrolate + Formoterol Fumarate', 'R03AL11', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Asthma-Related Death Risk", "severity": "High", "trigger_condition": "Use in asthma patients without appropriate ICS therapy", "message": "STOP: Long-acting beta2-adrenergic agonists (LABAs) increase the risk of asthma-related death. This triple combination is NOT indicated for the treatment of asthma. It is indicated ONLY for the maintenance treatment of COPD."}, {"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediately following inhalation", "message": "STOP: Inhaled medicines can cause life-threatening paradoxical bronchospasm. If this occurs, discontinue immediately and treat with a short-acting inhaled bronchodilator."}]', '- **Acute Deterioration:** Do not initiate in patients with acutely deteriorating COPD. This medication is for maintenance therapy only and should not be used as a rescue inhaler for acute bronchospasm.
INSERT INTO "drug_generic" VALUES(227, 'Allopurinol', 'Allopurinol', 'M04AA01', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Severe Cutaneous Adverse Reactions (SCAR)", "severity": "High", "trigger_condition": "Appearance of skin rash or mucosal lesions", "message": "STOP: Allopurinol can cause fatal dermatological reactions, including Stevens-Johnson syndrome (SJS) and toxic epidermal necrolysis (TEN). Discontinue IMMEDIATELY at the first sign of a skin rash."}, {"alert_type": "Drug Interaction Toxicity", "severity": "High", "trigger_condition": "Concurrent use with Azathioprine or Mercaptopurine", "message": "STOP: Allopurinol severely inhibits the metabolism of azathioprine and mercaptopurine, leading to fatal bone marrow suppression. The dose of these drugs MUST be reduced to 25-33% of the usual dose if co-administered."}]', '**Gout Flares:** Initiation of allopurinol can mobilize urate stores and precipitate acute gout attacks. Concurrent prophylactic treatment with colchicine or an NSAID is recommended for the first 3 to 6 months of therapy.
INSERT INTO "drug_generic" VALUES(228, 'Metronidazole + Neomycin Sulphate + Nystatin + Polmyxin B Vag prep', 'Metronidazole, Neomycin, Nystatin, and Polymyxin B', 'G01AA51', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Systemic Absorption and Toxicity", "severity": "Moderate", "trigger_condition": "Use in patients with renal impairment or mucosal damage", "message": "STOP: Although applied vaginally, systemic absorption of neomycin and polymyxin B can occur, especially if the vaginal mucosa is inflamed or damaged. This can lead to nephrotoxicity and ototoxicity. Use with caution in patients with renal impairment."}]', 'For intravaginal use only. Discontinue use if severe local irritation, sensitization, or allergic reactions occur. Caution should be exercised when giving to patients with renal impairment due to the potential for systemic absorption of the aminoglycoside (neomycin) and polymyxin B components, which are nephrotoxic and ototoxic. Systemic absorption of metronidazole may occur; observe precautions related to oral metronidazole (e.g., avoid alcohol). May damage latex contraceptives; advise alternative methods.', '- Treatment of vaginal trichomoniasis.
INSERT INTO "drug_generic" VALUES(229, 'Calcium Chloride + Dextrose Anhydrous + Potassium', 'Calcium Chloride, Dextrose, and Potassium', 'B05BB', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Intravenous Administration Safety", "severity": "High", "trigger_condition": "Rapid infusion or improper administration technique", "message": "STOP: Do not administer rapidly. Rapid infusion of potassium and calcium can cause fatal cardiac arrhythmias. Ensure proper IV line placement to avoid severe tissue necrosis from extravasation."}]', '**Visual Inspection:** Do not use if the solution is cloudy, contains particles, or if the expiration date has passed. Discard any unused portion.
INSERT INTO "drug_generic" VALUES(230, 'Lovastatin', 'Lovastatin', 'C10AA02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Concomitant use with strong CYP3A4 inhibitors or high doses", "message": "STOP: Lovastatin can cause severe myopathy and rhabdomyolysis leading to acute renal failure. Concomitant use with strong CYP3A4 inhibitors (e.g., itraconazole, clarithromycin, protease inhibitors) is strictly contraindicated."}]', '**Myopathy and Rhabdomyolysis:** Risk increases with higher doses, advanced age (>65 years), renal impairment, and inadequately controlled hypothyroidism. Monitor creatine kinase (CK) if muscle symptoms occur.
INSERT INTO "drug_generic" VALUES(231, 'Poly (0-2-hydroxyethyl) starch 60g + Sodium Chloride', 'Hydroxyethyl Starch 6% in Sodium Chloride', 'B05AA07', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Mortality and Renal Injury", "severity": "High", "trigger_condition": "Critically ill patients, including sepsis or ICU admission", "message": "STOP: Do not use HES solutions in critically ill adult patients, including those with sepsis, due to increased risk of mortality and severe renal injury requiring renal replacement therapy."}, {"alert_type": "Anaphylactoid Reactions", "severity": "High", "trigger_condition": "During intravenous infusion", "message": "STOP: Severe anaphylactoid reactions can occur. Discontinue immediately if hypersensitivity develops."}]', 'Fluid status and the rate of infusion must be assessed regularly during treatment to prevent fluid overload, especially in patients with cardiac insufficiency or severe kidney dysfunction. In cases of severe dehydration, a crystalloid solution should be administered first. Monitor coagulation parameters closely, as HES can cause dilutional coagulopathy and affect platelet function. Exercise extreme caution in patients with severe liver disease or severe bleeding disorders (e.g., von Willebrand''s disease). Discontinue use at the first sign of renal injury or coagulopathy.', '- **Hypovolemia and Shock:** Prophylaxis and treatment of hypovolemia and shock due to acute blood loss (e.g., surgery, trauma, burns) when crystalloids alone are not considered sufficient.
INSERT INTO "drug_generic" VALUES(232, 'Erlotinib', 'Erlotinib', 'L01EB02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Pulmonary Toxicity", "severity": "High", "trigger_condition": "Development of unexplained pulmonary symptoms (dyspnea, cough, fever)", "message": "STOP: Severe and potentially fatal Interstitial Lung Disease (ILD) can occur. Interrupt therapy immediately if new or worsening pulmonary symptoms develop. Discontinue permanently if ILD is diagnosed."}]', '**Interstitial Lung Disease (ILD):** Cases of ILD, including fatalities, have been reported. Interrupt therapy for acute onset of new or progressive unexplained pulmonary symptoms (e.g., dyspnea, cough, fever). Discontinue permanently if ILD is confirmed.
INSERT INTO "drug_generic" VALUES(233, 'Pefloxacin', 'Pefloxacin', 'J01MA03', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Tendon Rupture and CNS Effects", "severity": "High", "trigger_condition": "Concurrent use of corticosteroids, advanced age, or underlying CNS disorders", "message": "STOP: Fluoroquinolones are associated with an increased risk of tendinitis, tendon rupture, and severe CNS reactions (including seizures). Use with extreme caution in high-risk patients."}]', 'Use with extreme caution in patients with known or suspected CNS disorders (e.g., severe cerebral arteriosclerosis, epilepsy) or other risk factors that predispose to seizures or lower the seizure threshold.
INSERT INTO "drug_generic" VALUES(234, 'Betamethasone + Clotrimazole + Gentamicin Topical', 'Betamethasone, Clotrimazole, and Gentamicin Topical', 'D07CC01', 1, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Systemic Absorption", "severity": "Moderate", "trigger_condition": "Prolonged use, application to large areas, or use of occlusive dressings", "message": "STOP: Systemic absorption of topical corticosteroids can cause reversible HPA axis suppression and Cushing''s syndrome. Systemic absorption of gentamicin can cause nephrotoxicity and ototoxicity."}]', '**HPA Axis Suppression:** Similar effects to systemic steroid therapy may occur with the use of large amounts or long-term therapy, especially under occlusive dressings. Monitor for signs of Cushing''s syndrome or adrenal suppression.
INSERT INTO "drug_generic" VALUES(235, 'Etamsylate', 'Ethamsylate', 'B02BX01', 0, 0, 0, 0, 1, 0, 1, 0, '[]', 'Use with caution in patients with a history of thrombosis or thromboembolic disease.
INSERT INTO "drug_generic" VALUES(236, 'Ferric Pyrophosphate Citrate', 'Ferric Pyrophosphate Citrate', 'B03AB', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "During or after administration", "message": "STOP: Serious hypersensitivity reactions, including anaphylactic-type reactions, shock, and hypotension, can occur. Monitor patients closely during and after hemodialysis until clinically stable."}]', '**Hypersensitivity:** Personnel and therapies should be immediately available for the treatment of serious hypersensitivity reactions. Discontinue immediately if signs of hypersensitivity occur.
INSERT INTO "drug_generic" VALUES(237, 'Argatroban', 'Argatroban', 'B01AE03', 0, 1, 1, 0, 0, 0, 1, 0, '[{"alert_type": "High Alert Medicine", "severity": "High", "trigger_condition": "Prescribing or administering anticoagulant therapy", "message": "Argatroban is a high-alert medication. Errors in dosing or administration can lead to severe, life-threatening bleeding. Strict monitoring of aPTT or ACT is required."}]', '**Risk of Hemorrhage:** Hemorrhage can occur at any site in the body. Unexplained falls in hematocrit or blood pressure should lead to a search for a bleeding site. Use with extreme caution in disease states with an increased risk of hemorrhage (e.g., severe hypertension, major surgery, lumbar puncture, spinal anesthesia, gastrointestinal ulcerations).
INSERT INTO "drug_generic" VALUES(238, 'Primaquine', 'Primaquine Phosphate', 'P01BA03', 1, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hemolytic Anemia Risk", "severity": "High", "trigger_condition": "G6PD deficiency", "message": "STOP: Primaquine can cause severe, potentially fatal hemolytic anemia in patients with Glucose-6-Phosphate Dehydrogenase (G6PD) deficiency. G6PD testing is mandatory before initiating therapy."}]', '- **G6PD Deficiency:** Must screen all patients for G6PD deficiency prior to use. In mild-to-moderate deficiency, specialized dosing regimens under expert guidance are required. Discontinue immediately if signs of hemolysis (dark urine, sudden drop in hemoglobin) occur.
INSERT INTO "drug_generic" VALUES(239, 'Miconazole Nitrate 2% Topical', 'Miconazole', 'D01AC02', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'For external use only. Avoid contact with the eyes and mucous membranes.
INSERT INTO "drug_generic" VALUES(240, 'Hydrocortisone butyrate 0.1% topical', 'Hydrocortisone butyrate topical', 'D07AB02', 0, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "HPA Axis Suppression", "severity": "Moderate", "trigger_condition": "Prolonged use, application to large surface areas, or use of occlusive dressings", "message": "Caution: Systemic absorption of topical corticosteroids can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing syndrome, hyperglycemia, and glycosuria. Pediatric patients are particularly susceptible."}]', '**HPA Axis Suppression:** Systemic absorption may cause reversible HPA axis suppression, Cushing syndrome, hyperglycemia, and glycosuria. Risk increases with prolonged use, application to large surface areas, use on denuded skin, or use of occlusive dressings.
INSERT INTO "drug_generic" VALUES(241, 'Adapalene 0.3% Topical', 'Adapalene', 'D10AD03', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Photosensitivity and Skin Irritation", "severity": "Medium", "trigger_condition": "Exposure to sunlight or UV light", "message": "STOP: Adapalene increases sensitivity to UV light. Minimize sun exposure, avoid tanning beds, and use sunscreen daily. Do not apply to sunburned, cut, or eczematous skin."}]', '**Skin Irritation:** Erythema, scaling, dryness, and stinging/burning may occur, most commonly during the first 2 to 4 weeks of treatment. The 0.3% concentration has a higher potential for irritation than the 0.1% concentration. If severe, reduce application frequency or discontinue temporarily.
INSERT INTO "drug_generic" VALUES(242, 'Doxophylline', 'Doxofylline', 'R03DA11', 0, 0, 0, 0, 0, 0, 1, 0, '[]', '**Cardiovascular Disease:** Use with caution in patients with hypoxemia, hyperthyroidism, cardiac disease, arrhythmias, or a history of peptic ulcer disease. Doxofylline can exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(243, 'Bambuterol Hydrochloride', 'Bambuterol', 'R03CC12', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hypokalemia Risk", "severity": "Medium", "trigger_condition": "Concurrent use with diuretics, corticosteroids, or xanthines", "message": "STOP: Beta-2 agonists can cause potentially serious hypokalemia. Risk is increased with concurrent use of diuretics, steroids, or in severe asthma. Monitor serum potassium levels."}]', '**Cardiovascular Disease:** Use with caution in patients with myocardial insufficiency, arrhythmias, or susceptibility to QT-interval prolongation, as beta-2 agonists can cause cardiovascular stimulation.
INSERT INTO "drug_generic" VALUES(244, 'Amlodipine', 'Amlodipine', 'C08CA01', 0, 0, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Worsening Angina or Myocardial Infarction", "severity": "Medium", "trigger_condition": "Initiation of therapy or dosage increase in patients with severe obstructive coronary artery disease", "message": "STOP: Worsening of angina and acute myocardial infarction can develop after starting or increasing the dose of amlodipine, particularly in patients with severe obstructive coronary artery disease."}]', '**Symptomatic Hypotension:** Can occur, particularly in patients with severe aortic stenosis. Because of the gradual onset of action, acute hypotension is unlikely but should be monitored.
INSERT INTO "drug_generic" VALUES(245, 'Dupilumab', 'Dupilumab', 'D11AH05', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Administration of dupilumab", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, serum sickness, and generalized urticaria, can occur. Discontinue immediately if a clinically significant reaction develops."}]', '**Hypersensitivity:** Severe hypersensitivity reactions, including anaphylaxis, generalized urticaria, rash, erythema nodosum, and serum sickness or serum sickness-like reactions, have been reported. Institute appropriate therapy and discontinue the drug if a clinically significant hypersensitivity reaction occurs.
INSERT INTO "drug_generic" VALUES(246, 'Chloramphenicol 1% Eye prep', 'Chloramphenicol Ophthalmic Ointment', 'S01AA01', 1, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Systemic Absorption Risk", "severity": "Moderate", "trigger_condition": "Prolonged ocular use", "message": "Rare cases of fatal aplastic anemia and bone marrow hypoplasia have been reported following topical ophthalmic use of chloramphenicol due to systemic absorption. Avoid prolonged use."}]', '**Systemic Absorption:** Although rare, systemic absorption from ophthalmic administration can occur, leading to severe blood dyscrasias (aplastic anemia). Avoid prolonged or repeated courses of treatment.
INSERT INTO "drug_generic" VALUES(247, 'Ferric Citrate', 'Ferric Citrate', 'V03AE08', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Iron Overload Risk", "severity": "High", "trigger_condition": "Concomitant use of intravenous iron or underlying iron overload syndromes", "message": "STOP: Ferric citrate increases systemic iron absorption. Monitor ferritin and transferrin saturation (TSAT) regularly. Patients may require a reduction in dose or discontinuation of intravenous iron to prevent iron toxicity."}]', '**Iron Overload:** Iron absorption from ferric citrate may lead to excessive iron storage. Assess iron parameters (ferritin and TSAT) prior to initiating therapy and monitor regularly. Adjust or discontinue concurrent intravenous iron therapy as necessary.
INSERT INTO "drug_generic" VALUES(248, 'Cloxacillin', 'Cloxacillin', 'J01CF02', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported in patients on penicillin therapy. Cross-sensitivity with cephalosporins may occur.
INSERT INTO "drug_generic" VALUES(249, 'Deucravacitinib', 'Deucravacitinib', 'L04AA56', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Serious Infections and Malignancy", "severity": "High", "trigger_condition": "Presence of active infection or history of malignancy", "message": "STOP: Increased risk of serious infections and malignancies. Evaluate for active tuberculosis and resolve any serious infections prior to initiation."}]', '**Infections:** May increase the risk of infections. Avoid use in patients with active or serious infections, including localized infections. Closely monitor for signs and symptoms of infection during and after treatment. If a serious infection develops, interrupt therapy until the infection resolves or is adequately treated.
INSERT INTO "drug_generic" VALUES(250, 'Artesunate', 'Artesunate', 'P01BE03', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Post-Artemisinin Delayed Hemolysis (PADH)", "severity": "High", "trigger_condition": "1 to 4 weeks after treatment of severe malaria", "message": "STOP: Delayed, severe hemolytic anemia can occur weeks after treatment with IV artesunate. Monitor hemoglobin and reticulocyte counts weekly for up to 4 weeks post-treatment."}]', '**Hepatic and Renal Insufficiency:** Use with caution in patients with severe hepatic or renal impairment, though dose adjustments are generally not required for the acute treatment of severe malaria.
INSERT INTO "drug_generic" VALUES(251, 'Ubrogepant', 'Ubrogepant', 'N02CD01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Drug Interaction", "severity": "High", "trigger_condition": "Coadministration with strong CYP3A4 inhibitors", "message": "STOP: Coadministration with strong CYP3A4 inhibitors (e.g., ketoconazole, clarithromycin) is contraindicated due to a significant increase in ubrogepant exposure, which may lead to severe toxicity."}]', '**CYP3A4 Interactions:** Ubrogepant exposure is significantly increased when coadministered with strong CYP3A4 inhibitors. Dose adjustments are required for moderate CYP3A4 inhibitors or strong CYP3A4 inducers.
INSERT INTO "drug_generic" VALUES(252, 'Synthetic human angiotensin II', 'Angiotensin II', 'C01CX09', 0, 1, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Thromboembolism Risk", "severity": "High", "trigger_condition": "Administration of synthetic human angiotensin II", "message": "STOP: A significant risk of arterial and venous thromboembolic events (including deep vein thrombosis and peripheral ischemia) was observed in clinical trials. Concurrent venous thromboembolism (VTE) prophylaxis must be used unless strictly contraindicated."}]', 'Monitor blood pressure continuously during infusion to prevent severe hypertension. Due to the high risk of thromboembolic events (12.9% in clinical trials), initiate concurrent venous thromboembolism (VTE) prophylaxis (e.g., pharmacological prophylaxis with heparin or low molecular weight heparin) in all patients receiving this drug, unless contraindicated by active bleeding or severe coagulopathy. Monitor for signs of peripheral ischemia, as profound vasoconstriction can compromise perfusion to the extremities and splanchnic organs. Extravasation may cause severe local tissue necrosis; administer via a central venous line. Downward titration must be done gradually to avoid profound rebound hypotension.', '- Indicated to increase blood pressure in adults with septic shock or other distributive shock.', '- **None Absolute in Distributive Shock:** There are no absolute contraindications for the use of synthetic human angiotensin II in the setting of life-threatening distributive shock. However, it should be used with extreme caution in patients with acute coronary syndrome, severe peripheral vascular disease, or mesenteric ischemia due to its potent vasoconstrictive properties.', '- **Thromboembolic events** (Deep vein thrombosis, pulmonary embolism; requires VTE prophylaxis)
INSERT INTO "drug_generic" VALUES(253, 'Frusemide + Amiloride', 'Furosemide/Amiloride', 'C03EB01', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fluid and Electrolyte Imbalance", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "STOP: Profound diuresis can lead to severe fluid and electrolyte depletion, including hyponatremia, hypokalemia (from furosemide), or hyperkalemia (from amiloride). Fatalities have occurred. Strict monitoring of serum electrolytes and renal function is mandatory."}]', '**Electrolyte Imbalance:** May cause hyperkalemia (due to amiloride) or hypokalemia (due to furosemide). Monitor serum potassium closely, especially in the elderly, diabetics, or those with renal impairment.
INSERT INTO "drug_generic" VALUES(254, 'Dextromethorphan + Pseudoephedrine HCL +Triprolidine HCL', 'Dextromethorphan / Pseudoephedrine / Triprolidine', 'R05DA20', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Drug Interaction", "severity": "High", "trigger_condition": "Concurrent use of MAOIs", "message": "STOP: Contraindicated in patients receiving Monoamine Oxidase Inhibitors (MAOIs) or within 14 days of stopping MAOI therapy due to the risk of fatal hypertensive crisis and serotonin syndrome."}]', '**Cardiovascular & Endocrine Disease:** Use with extreme caution in patients with hypertension, ischemic heart disease, diabetes mellitus, or hyperthyroidism due to the sympathomimetic effects of pseudoephedrine.
INSERT INTO "drug_generic" VALUES(255, 'Linezolid', 'Linezolid', 'J01XX08', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Serotonin Syndrome Risk", "severity": "High", "trigger_condition": "Concomitant use with serotonergic agents (e.g., SSRIs, SNRIs, MAOIs)", "message": "STOP: Linezolid is a reversible, non-selective MAOI. Co-administration with serotonergic drugs can cause fatal Serotonin Syndrome. Discontinue serotonergic agents if possible, or monitor closely for altered mental status, autonomic instability, and neuromuscular abnormalities."}]', '- **Myelosuppression:** Reversible myelosuppression (anemia, leukopenia, pancytopenia, and thrombocytopenia) has been reported, particularly in patients receiving therapy for >14 days. Monitor complete blood counts (CBC) weekly.
INSERT INTO "drug_generic" VALUES(256, 'Miconazole + Petrolatum + Zinc oxide topical', 'Miconazole Nitrate, White Petrolatum, and Zinc Oxide', 'D01AC20', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Appropriate Use", "severity": "Moderate", "trigger_condition": "Preventive use or unconfirmed candidiasis", "message": "Do not use to prevent diaper dermatitis. This product is indicated ONLY for the adjunctive treatment of diaper dermatitis complicated by documented candidiasis. Preventive use may result in fungal resistance."}]', '**Not a Substitute for Hygiene:** This medication is not a substitute for frequent diaper changes. Proper diaper hygiene must be maintained.
INSERT INTO "drug_generic" VALUES(257, 'Betamethasone 0.1% + Clotrimazole 1% Topical', 'Betamethasone and Clotrimazole', 'D01AC20', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Inappropriate Use Warning", "severity": "Medium", "trigger_condition": "Use for diaper dermatitis or prolonged use", "message": "STOP: Do NOT use for diaper dermatitis. Occlusive environments (like diapers) significantly increase systemic absorption of betamethasone, leading to severe HPA axis suppression and growth retardation in children."}]', '**Systemic Absorption:** Systemic absorption of topical corticosteroids can produce reversible HPA axis suppression, Cushing''s syndrome, and hyperglycemia. Risk increases with prolonged use, application to large surface areas, or use of occlusive dressings.
INSERT INTO "drug_generic" VALUES(258, 'Dolutegravir + Rilpivirine', 'Dolutegravir and rilpivirine', 'J05AR21', 1, 0, 0, 0, 0, 0, 0, 0, '[]', '**Depressive Disorders:** Depressive disorders, including depressed mood, depression, dysphoria, major depression, mood altered, negative thoughts, suicide attempt, and suicidal ideation, have been associated with rilpivirine. Monitor patients for depressive symptoms.
INSERT INTO "drug_generic" VALUES(259, 'Meningococcal group A C Y and W-135 Oligosaccharide Diphtheria Conjugate Vaccine', 'Meningococcal (Groups A, C, Y and W-135) Oligosaccharide Diphtheria CRM197 Conjugate Vaccine', 'J07AH08', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe allergic reaction to a previous dose or to diphtheria toxoid", "message": "STOP: Severe allergic reactions, including anaphylaxis, can occur. Ensure epinephrine and other emergency resuscitation equipment are immediately available."}]', 'Appropriate medical treatment and supervision must be available to manage possible anaphylactic reactions following administration. Carefully consider the benefits and risks in individuals with a history of Guillain-Barré syndrome (GBS). Immunocompromised persons, including those receiving immunosuppressive therapy, may have a diminished immune response to the vaccine. Use with caution in individuals with thrombocytopenia or any coagulation disorder, as bleeding may occur following intramuscular administration. Syncope (fainting) can occur in association with administration of injectable vaccines; procedures should be in place to avoid injury from falling.', '- Active immunization to prevent invasive meningococcal disease caused by *Neisseria meningitidis* serogroups A, C, Y, and W-135.
INSERT INTO "drug_generic" VALUES(260, 'Ustekinumab', 'Ustekinumab', 'L04AC05', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Serious Infections and Malignancy", "severity": "High", "trigger_condition": "Initiation of therapy or presence of active infection", "message": "STOP: May increase the risk of infections and reactivation of latent infections (e.g., tuberculosis). Evaluate for TB infection before initiating. Increased risk of malignancy, including nonmelanoma skin cancer, has been reported."}]', '**Infections:** Treatment may increase the risk of infections and reactivation of latent infections. Serious bacterial, fungal, mycobacterial, and viral infections have been observed. Do not administer to patients with active tuberculosis (TB). Initiate treatment for latent TB prior to administering ustekinumab.
INSERT INTO "drug_generic" VALUES(261, 'Paracetamol + Tramadol Hydrochloride', 'Acetaminophen and Tramadol', 'N02AJ13', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Respiratory Depression and Hepatotoxicity", "severity": "High", "trigger_condition": "Overdose, concurrent use with CNS depressants, or use in severe hepatic impairment", "message": "STOP: Contains an opioid (tramadol) and paracetamol. Risk of profound respiratory depression, coma, and death with CNS depressants. Risk of fatal hepatotoxicity if paracetamol dose exceeds 4g/day."}]', '**Seizure Risk:** Tramadol increases the risk of seizures, especially at doses above the recommended range, or when co-administered with SSRIs, SNRIs, TCAs, or other seizure-threshold-lowering drugs. Use with extreme caution in patients with a history of epilepsy or head trauma.
INSERT INTO "drug_generic" VALUES(262, 'Hydrochlorothiazide + Metoprolol', 'Hydrochlorothiazide and Metoprolol', 'C07BB02', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Abrupt Withdrawal Risk", "severity": "High", "trigger_condition": "Discontinuation of therapy", "message": "STOP: Abrupt withdrawal of beta-blockers can exacerbate angina, precipitate myocardial infarction, or cause ventricular arrhythmias. Taper dose gradually over 1 to 2 weeks."}]', '**Cardiovascular Risk:** Gradual withdrawal is mandatory to prevent exacerbation of angina or precipitation of myocardial infarction.
INSERT INTO "drug_generic" VALUES(263, 'Glucosamine + Chondroitin + Camphor + Peppermint Oil topical', 'Glucosamine + Chondroitin + Camphor + Peppermint Oil topical', 'M02AX', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '- **Skin Integrity:** Do not apply to broken, irritated, or damaged skin, or open wounds.
INSERT INTO "drug_generic" VALUES(264, 'Nitrous Oxide 98 % Gas', 'Nitrous Oxide', 'N01AX13', 0, 1, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Hypoxia Risk", "severity": "High", "trigger_condition": "Administration without supplemental oxygen", "message": "STOP: 98% Nitrous Oxide MUST NEVER be administered alone. It must always be blended with at least 21% (preferably 30% or more) oxygen to prevent fatal asphyxia and hypoxia."}]', 'Must only be administered by personnel trained in the administration of general anesthesia. Prolonged inhalation can result in vitamin B12 inactivation, leading to megaloblastic anemia and severe neurological deficits (myeloneuropathy). Hematological monitoring is required if used for extended periods. Post-operative nausea and vomiting are common. Diffusion hypoxia can occur upon discontinuation; administration of 100% oxygen for several minutes after cessation is recommended. Ensure adequate scavenging systems to protect healthcare workers from chronic exposure.', '- **General Anesthesia:** Used as an adjunct to other inhalational or intravenous anesthetic agents for the induction and maintenance of general anesthesia.
INSERT INTO "drug_generic" VALUES(265, 'Pramipexol', 'Pramipexole', 'N04BC05', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Sudden Sleep Onset", "severity": "High", "trigger_condition": "Initiation or dose escalation", "message": "STOP: Patients may fall asleep while engaged in activities of daily living, including driving, without prior warning signs. Assess for sleep disorders and caution patients."}]', 'Risk of sudden sleep onset during activities of daily living. May cause orthostatic hypotension, especially during dose escalation. Hallucinations and psychotic-like behavior may occur. Impulse control disorders (e.g., pathological gambling, hypersexuality, binge eating) have been reported; consider dose reduction or discontinuation if these develop. Risk of neuroleptic malignant syndrome (NMS) or withdrawal-emergent hyperpyrexia and confusion with abrupt withdrawal; taper dose gradually. May cause augmentation (earlier onset, increase, and spread of symptoms) in Restless Legs Syndrome. Perform periodic skin examinations due to a potential increased risk of melanoma. Regular ophthalmological testing is recommended due to the risk of visual disorders.', '- **Parkinson''s Disease:** Used as monotherapy for the initial symptomatic management of idiopathic Parkinson''s disease, or as an adjunct to levodopa in advanced disease to manage motor deficits and "off" episodes.
INSERT INTO "drug_generic" VALUES(266, 'Rifampicin', 'Rifampin', 'J04AB02', 1, 0, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Hepatotoxicity Risk", "severity": "High", "trigger_condition": "Concurrent use with other hepatotoxic agents or pre-existing liver disease", "message": "STOP: Severe and potentially fatal hepatotoxicity can occur. Monitor liver function tests closely, especially in patients with pre-existing hepatic impairment or those taking concurrent hepatotoxic medications."}]', '**Hepatotoxicity:** Severe and potentially fatal liver injury can occur. Monitor liver function tests (AST, ALT, bilirubin) prior to therapy and every 2-4 weeks during treatment. Use with extreme caution in patients with pre-existing hepatic impairment, alcoholism, or malnutrition.
INSERT INTO "drug_generic" VALUES(267, 'Atenolol', 'Atenolol', 'C07AB03', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Abrupt Discontinuation", "severity": "High", "trigger_condition": "Sudden cessation of therapy", "message": "STOP: Severe exacerbation of angina, myocardial infarction, and ventricular arrhythmias have occurred following the abrupt discontinuation of beta-blockers. Taper the dose gradually over 1 to 2 weeks."}]', '**Bronchospastic Disease:** Atenolol is a cardioselective beta-blocker, but selectivity is not absolute. Use with caution in patients with asthma or COPD; use the lowest possible dose.
INSERT INTO "drug_generic" VALUES(268, 'Iopamidol', 'Iopamidol', 'V08AB04', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Intrathecal Administration Errors", "severity": "High", "trigger_condition": "Use of incorrect formulation for intrathecal injection", "message": "STOP: Ensure the specific formulation is approved for intrathecal use. Inadvertent intrathecal administration of formulations not approved for this route can cause severe neurotoxicity, seizures, coma, and death."}]', '- Maintain adequate hydration before and after administration to minimize the risk of contrast-induced nephropathy, especially in patients with severe renal impairment, combined renal and hepatic disease, or anuria.
INSERT INTO "drug_generic" VALUES(269, 'Budesonide rectal', 'Budesonide rectal', 'A07EA06', 0, 0, 1, 1, 0, 1, 0, 1, '[{"alert_type": "Flammable Contents", "severity": "Moderate", "trigger_condition": "Administration of rectal foam", "message": "The contents of Budesonide rectal foam are flammable. Instruct the patient to avoid fire, flame, and smoking during and immediately following administration."}]', '**Hypercorticism and Adrenal Suppression:** Systemic absorption can occur. Monitor for signs of hypercorticism and HPA axis suppression, especially in patients with hepatic impairment where first-pass metabolism is reduced.
INSERT INTO "drug_generic" VALUES(270, 'Tucatinib', 'Tucatinib', 'L01EX22', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Hepatotoxicity and Diarrhea", "severity": "High", "trigger_condition": "Initiation and ongoing therapy", "message": "STOP: Severe hepatotoxicity and severe diarrhea (including dehydration, acute kidney injury, and death) can occur. Monitor ALT, AST, and bilirubin prior to initiation and every 3 weeks. Administer antidiarrheals promptly at the onset of diarrhea."}]', '**Hepatotoxicity:** Severe hepatotoxicity has been reported. Monitor ALT, AST, and bilirubin prior to initiation, every 3 weeks during treatment, and as clinically indicated. Interrupt, reduce the dose, or permanently discontinue based on severity.
INSERT INTO "drug_generic" VALUES(271, 'Eflornithine Hydrochloride Monohydrate', 'Eflornithine', 'D11AX16', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '**Skin Irritation:** Discontinue use if severe skin hypersensitivity or irritation occurs. Transient stinging or burning may occur upon application.
INSERT INTO "drug_generic" VALUES(272, 'Brinzolamide + Timolol eye prep', 'Brinzolamide and Timolol Ophthalmic', 'S01ED51', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Systemic Beta-Blockade", "severity": "High", "trigger_condition": "Patients with severe reactive airway disease or severe cardiac disease", "message": "STOP: Timolol is systemically absorbed. Severe respiratory reactions and cardiac reactions, including death due to bronchospasm in patients with asthma, and rarely death in association with cardiac failure, have been reported."}]', '**Cardiovascular and Respiratory Effects:** Due to the timolol component, systemic beta-adrenergic blockade can occur. Use with extreme caution in patients with a history of severe cardiac disease or reactive airway disease. Control cardiac failure prior to initiating therapy.
INSERT INTO "drug_generic" VALUES(273, 'Ertugliflozin + Metformin', 'Ertugliflozin and Metformin', 'A10BD23', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Lactic Acidosis and Diabetic Ketoacidosis", "severity": "High", "trigger_condition": "Symptoms of severe metabolic acidosis, hypoxemia, or renal impairment", "message": "STOP: Postmarketing cases of metformin-associated lactic acidosis have resulted in death, hypothermia, hypotension, and resistant bradyarrhythmias. Risk factors include renal impairment, concomitant use of certain drugs, age >65, radiological studies with contrast, surgery, hypoxic states, excessive alcohol intake, and hepatic impairment. Discontinue immediately if lactic acidosis or diabetic ketoacidosis (DKA) is suspected."}]', 'Metformin-associated lactic acidosis is a medical emergency; monitor for symptoms such as malaise, myalgias, respiratory distress, somnolence, and abdominal pain. Temporarily discontinue prior to intravascular radiocontrast imaging in patients with an eGFR between 30 and 60 mL/min/1.73 m², a history of hepatic impairment, alcoholism, or heart failure. Necrotizing fasciitis of the perineum (Fournier gangrene) has been reported with SGLT2 inhibitors; discontinue and initiate broad-spectrum antibiotics and surgical debridement if suspected. Ertugliflozin causes intravascular volume contraction; symptomatic hypotension may occur. Ketoacidosis requires urgent hospitalization; consider predisposing factors before initiating and temporarily discontinue during prolonged fasting or surgery. Serious urinary tract infections and genital mycotic infections may occur. Metformin may lower vitamin B12 levels; monitor hematologic parameters annually.', '- Adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus who are not adequately controlled on a regimen containing ertugliflozin or metformin, or in patients who are already treated with both ertugliflozin and metformin.', '- **Severe Renal Impairment:** Contraindicated in patients with severe renal impairment (eGFR <30 mL/min/1.73 m²), end-stage renal disease (ESRD), or those on dialysis, due to the risk of metformin accumulation/lactic acidosis and lack of ertugliflozin efficacy.
INSERT INTO "drug_generic" VALUES(274, 'Inositol (Myo-inositol)', 'Myo-inositol', 'A11HA07', 0, 0, 1, 1, 0, 1, 0, 0, '[]', '**Hypoglycemia Risk:** Myo-inositol improves insulin sensitivity. Patients with diabetes mellitus or those taking antidiabetic medications should monitor their blood glucose levels closely, as concurrent use may increase the risk of hypoglycemia.
INSERT INTO "drug_generic" VALUES(275, 'Sarecycline', 'Sarecycline', 'J01AA14', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Intracranial Hypertension", "severity": "High", "trigger_condition": "Development of severe headache or visual disturbances", "message": "STOP: Intracranial hypertension (pseudotumor cerebri) can occur. Discontinue immediately if headache, blurred vision, or papilledema develop."}]', '**Intracranial Hypertension:** Pseudotumor cerebri has been associated with tetracycline use. Clinical manifestations include headache, blurred vision, diplopia, and papilledema. Discontinue sarecycline immediately if these symptoms occur.
INSERT INTO "drug_generic" VALUES(276, 'Etanercept', 'Etanercept', 'L04AB01', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Serious Infections and Malignancy", "severity": "High", "trigger_condition": "Signs of infection or history of malignancy", "message": "STOP: Increased risk of serious, potentially fatal infections (e.g., TB, invasive fungal infections) and malignancies (e.g., lymphoma). Screen for latent TB and Hepatitis B prior to initiation."}]', '**Serious Infections:** High risk of bacterial, mycobacterial, invasive fungal, and viral infections. Discontinue if a serious infection or sepsis develops. Screen for latent TB and treat before starting therapy.
INSERT INTO "drug_generic" VALUES(277, 'Clobetasone butyrate 0.05% Topical', 'Clobetasone Butyrate Topical', 'D07AB01', 0, 0, 0, 0, 0, 1, 1, 1, '[]', '**HPA Axis Suppression:** Manifestations of hypercortisolism (Cushing''s syndrome) and reversible hypothalamic-pituitary-adrenal (HPA) axis suppression can occur, particularly with prolonged use, extensive application, or use under occlusion. Children are more susceptible.
INSERT INTO "drug_generic" VALUES(278, 'Triamcinolone Acetonide', 'Triamcinolone Acetonide', 'H02AB08', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Adrenal Insufficiency", "severity": "High", "trigger_condition": "Abrupt withdrawal after prolonged systemic use", "message": "STOP: Rapid withdrawal of systemic corticosteroids can precipitate acute, potentially fatal adrenal insufficiency. Taper the dose gradually."}]', 'Use with extreme caution in patients with diabetes mellitus (may cause hyperglycemia), hypertension, heart failure, recent myocardial infarction, or thromboembolic disorders. May mask signs of infection or exacerbate untreated systemic fungal, bacterial, viral, or parasitic infections. Caution in patients with peptic ulcer disease, osteoporosis, glaucoma, cirrhosis, or a history of psychiatric disorders (may induce psychosis). Prolonged use in children requires close monitoring of growth and development due to the risk of growth retardation. Avoid rapid withdrawal after prolonged therapy to prevent hypothalamic-pituitary-adrenal (HPA) axis suppression and acute adrenal crisis.', '- **Allergic States**: Control of severe or incapacitating allergic conditions intractable to adequate trials of conventional treatment (e.g., seasonal/perennial allergic rhinitis, asthma, contact/atopic dermatitis).
INSERT INTO "drug_generic" VALUES(279, 'Cisplatin', 'Cisplatin', 'L01XA01', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Severe Toxicity (Nephrotoxicity, Ototoxicity, Myelosuppression, Nausea/Vomiting)", "severity": "High", "trigger_condition": "Administration of Cisplatin", "message": "WARNING: Cisplatin causes severe, cumulative nephrotoxicity and ototoxicity. Ensure vigorous IV hydration before and after administration. It causes severe nausea/vomiting requiring aggressive antiemetic prophylaxis. Severe myelosuppression and anaphylactic reactions can also occur."}]', '**Nephrotoxicity:** Dose-related and cumulative renal insufficiency is the major dose-limiting toxicity. Ensure adequate hydration (1-2 L of IV fluid) prior to and following administration. Monitor serum creatinine, BUN, and electrolytes (magnesium, potassium, calcium) closely.
INSERT INTO "drug_generic" VALUES(280, 'Pidotimod', 'Pidotimod', 'L03AX05', 0, 0, 0, 0, 1, 1, 1, 0, '[]', '**Pediatric Use:** Not recommended for use in children less than 3 years of age (or 2 years depending on local guidelines) since the safety and efficacy are not clinically established. Use with caution in patients less than 18 years of age under the supervision of a qualified healthcare professional.
INSERT INTO "drug_generic" VALUES(281, 'Neomycin Sulphate 0.35% + Polymixin B Sulphate 0.127% + Prednisolone 0.5% Eye prep', 'Neomycin / Polymyxin B / Prednisolone Ophthalmic', 'S01CA02', 1, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Ocular Toxicity", "severity": "High", "trigger_condition": "Prolonged use beyond 10 days", "message": "STOP: Prolonged use of ophthalmic corticosteroids may result in glaucoma, optic nerve damage, visual acuity defects, and posterior subcapsular cataract formation. Monitor intraocular pressure routinely."}]', '- **Intraocular Pressure (IOP):** Prolonged use may result in elevated IOP. If used for 10 days or longer, IOP should be routinely monitored.
INSERT INTO "drug_generic" VALUES(282, 'Sodium Cromoglycate (Cromoglicic acid)', 'Cromolyn Sodium', 'R03BC01', 0, 0, 1, 1, 1, 1, 1, 1, '[{"alert_type": "Acute Asthma Exacerbation", "severity": "High", "trigger_condition": "Use during an acute asthma attack", "message": "STOP: Sodium cromoglycate is a prophylactic agent and has NO role in the treatment of acute asthma attacks or status asthmaticus. Use a short-acting beta-agonist for acute relief."}]', '- **Eosinophilic Pneumonia:** Pulmonary infiltrates with eosinophilia have been reported; discontinue if this occurs.
INSERT INTO "drug_generic" VALUES(283, 'Necitumumab', 'Necitumumab', 'L01FE03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiopulmonary Arrest", "severity": "High", "trigger_condition": "During or shortly after administration", "message": "Cardiopulmonary arrest and/or sudden death occurred in 3% of patients. Closely monitor serum electrolytes and correct abnormalities prior to and during treatment."}, {"alert_type": "Severe Hypomagnesemia", "severity": "High", "trigger_condition": "Routine electrolyte monitoring", "message": "Severe hypomagnesemia occurs frequently. Monitor electrolytes before each dose and for at least 8 weeks after completion. Replete aggressively."}]', '**Cardiopulmonary Arrest and Sudden Death:** Cardiopulmonary arrest and/or sudden death occurred in 3% of patients treated with necitumumab in combination with gemcitabine and cisplatin. Closely monitor serum electrolytes, including serum magnesium, potassium, and calcium, with aggressive replacement when warranted during and after treatment.
INSERT INTO "drug_generic" VALUES(284, 'Typhoid Conjugate Vaccine', 'Typhoid Vi Conjugate Vaccine', 'J07AP03', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Administration of vaccine", "message": "Caution: As with all injectable vaccines, appropriate medical treatment and supervision must always be readily available in case of a rare anaphylactic event following administration."}]', '**Route of Administration:** Do not administer intravenously, intradermally, or subcutaneously. Must be given intramuscularly.
INSERT INTO "drug_generic" VALUES(285, 'Methenamine + Sodium salicylate  Benzoic acid', 'Methenamine, Sodium Salicylate, and Benzoic Acid', 'J01XX05', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Salicylate Toxicity", "severity": "High", "trigger_condition": "Use in pediatric patients with viral infections", "message": "STOP: Risk of Reye''s syndrome due to the sodium salicylate component. Avoid use in children and teenagers with varicella or influenza-like illnesses."}]', '**Hepatic Impairment:** Monitor liver function tests (LFTs) closely, especially in patients with a history of liver impairment, as metabolism may be altered.
INSERT INTO "drug_generic" VALUES(286, 'Thiotepa', 'Thiotepa', 'L01AC01', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Administration of Thiotepa", "message": "Thiotepa is highly toxic to the hematopoietic system. Profound and potentially fatal myelosuppression (leukopenia, thrombocytopenia, anemia) is expected. Monitor complete blood counts frequently."}]', 'Monitor complete blood counts (CBC) with differential and platelets prior to each dose, at least weekly during therapy, and for at least 3 weeks after discontinuation. Withhold or reduce the dose if severe myelosuppression occurs. Monitor hepatic and renal function periodically. Thiotepa is highly emetogenic; administer appropriate antiemetic prophylaxis. Monitor for signs of hemorrhagic cystitis, especially with intravesical administration. Thiotepa is a known human carcinogen; secondary malignancies (e.g., leukemia) have been reported. Avoid concurrent administration of live vaccines.', '- **Hematopoietic Progenitor Cell Transplantation (HPCT) Conditioning:** Used in combination with other chemotherapy agents (with or without total body irradiation) as a conditioning regimen prior to allogeneic or autologous HPCT in hematological diseases and solid tumors.
INSERT INTO "drug_generic" VALUES(287, 'Ticarcillin + Clavulanate', 'Ticarcillin and Clavulanate Potassium', 'J01CR03', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Patient history of penicillin or cephalosporin allergy", "message": "STOP: Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. Verify patient allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Reported with use of nearly all antibacterial agents. Evaluate patients if severe diarrhea occurs.
INSERT INTO "drug_generic" VALUES(288, 'Clindamycin Vaginal prep', 'Clindamycin Vaginal', 'G01AA10', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Severe Colitis", "severity": "High", "trigger_condition": "Development of severe diarrhea or abdominal cramps during therapy", "message": "Systemic absorption occurs with vaginal use. Discontinue immediately if significant diarrhea, bloody diarrhea, or severe abdominal cramps occur, as this may indicate Clostridioides difficile-associated diarrhea (CDAD)."}]', '**Systemic Absorption:** Approximately 5% of the vaginal dose is absorbed systemically. Cases of severe diarrhea and pseudomembranous colitis have been reported. Discontinue use if significant diarrhea occurs.
INSERT INTO "drug_generic" VALUES(289, 'Sodium Hyaluronate + Sodium Chondroitin Sulfate Eye drop', 'Sodium Hyaluronate and Chondroitin Sulfate', 'S01KA51', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Monitor intraocular pressure (IOP) closely during the early postoperative period, as transient increases in IOP may occur due to mechanical blockage of the trabecular meshwork by the viscoelastic material. Ensure complete removal of the viscoelastic solution from the anterior chamber at the end of the surgical procedure to mitigate this risk. Exercise caution in patients with a history of hypersensitivity to avian proteins, as sodium hyaluronate may be extracted from rooster combs and carries a theoretical risk of allergic reactions. Avoid overfilling the anterior chamber to prevent excessive postoperative pressure spikes.', '- **Cataract Extraction and Intraocular Lens (IOL) Implantation:** Used as a surgical aid to maintain a deep anterior chamber, protect the corneal endothelium from mechanical trauma, and facilitate the safe implantation of the IOL.
INSERT INTO "drug_generic" VALUES(290, 'Trimipramine', 'Trimipramine', 'N06AA06', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Suicidality and Antidepressant Drugs", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '**Suicide Risk:** Monitor closely for clinical worsening and suicidal ideation, especially during the initial months of therapy.
INSERT INTO "drug_generic" VALUES(291, 'Dequalinium Chloride vaginal prep', 'Dequalinium Chloride', 'G01AC05', 1, 0, 1, 1, 0, 1, 0, 0, '[]', 'Intravaginal use of soaps, spermicides, and vaginal douches is not recommended during treatment, as these may antagonize the antimicrobial action of the drug.
INSERT INTO "drug_generic" VALUES(292, 'Isoflurane', 'Isoflurane', 'N01AB06', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Malignant Hyperthermia", "severity": "High", "trigger_condition": "Administration to susceptible individuals", "message": "STOP: Isoflurane can trigger malignant hyperthermia, a potentially fatal hypermetabolic state of skeletal muscle. Ensure dantrolene and resuscitation equipment are immediately available."}]', '**Perioperative Hyperkalemia:** Use of inhaled anesthetic agents has been associated with rare increases in serum potassium levels that have resulted in cardiac arrhythmias and death in pediatric patients during the postoperative period. Patients with latent or overt neuromuscular disease (e.g., Duchenne muscular dystrophy) are particularly vulnerable.
INSERT INTO "drug_generic" VALUES(293, 'Brompheniramine + Dextromethorphan + Pseudoephedrine', 'Brompheniramine, Dextromethorphan, and Pseudoephedrine', 'R05DA20', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Respiratory Depression and CNS Toxicity", "severity": "High", "trigger_condition": "Use in young children or concurrent use with CNS depressants", "message": "STOP: Do not use in premature or full-term neonates. Severe CNS depression, respiratory depression, and confusional symptoms can occur. Avoid concurrent use with MAOIs due to the risk of serotonin syndrome and hypertensive crisis."}]', '**CNS Depression and Anticholinergic Effects:** Brompheniramine may cause significant confusional symptoms, drowsiness, and pronounced sedation. It has significant antimuscarinic activity. Avoid concurrent use with alcohol or other CNS depressants.
INSERT INTO "drug_generic" VALUES(294, 'Amoxicillin + Clarithromycin + Lansoprazole Kit', 'Amoxicillin, Clarithromycin, and Lansoprazole', 'A02BD03', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "QT Prolongation and Arrhythmias", "severity": "High", "trigger_condition": "Concurrent use with QT-prolonging drugs or in patients with hypokalemia", "message": "STOP: Clarithromycin is associated with QT prolongation and fatal arrhythmias (Torsades de Pointes). Avoid in patients with uncorrected hypokalemia/hypomagnesemia or those taking Class IA/III antiarrhythmics."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Development of jaundice or elevated liver enzymes", "message": "STOP: Clarithromycin can cause severe, potentially fatal hepatic failure. Discontinue immediately if signs of hepatitis occur."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with nearly all antibacterial agents, including amoxicillin and clarithromycin. Evaluate patients who develop severe diarrhea.
INSERT INTO "drug_generic" VALUES(295, 'Aripiprazole', 'Aripiprazole', 'N05AX12', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Increased Mortality in Elderly with Dementia", "severity": "High", "trigger_condition": "Prescribing to elderly patients with dementia-related psychosis", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death (mostly cardiovascular or infectious). Aripiprazole is NOT approved for this use."}, {"alert_type": "Suicidality and Antidepressant Drugs", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults (up to age 24). Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '**Neuroleptic Malignant Syndrome (NMS):** A potentially fatal symptom complex (hyperpyrexia, muscle rigidity, altered mental status, autonomic instability). Manage with immediate discontinuation and intensive symptomatic treatment.
INSERT INTO "drug_generic" VALUES(296, 'Potassium Bicarbonate + Potassium Chloride', 'Potassium Bicarbonate and Potassium Chloride', 'A12BA30', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hyperkalemia Risk", "severity": "High", "trigger_condition": "Renal impairment or concomitant use of potassium-sparing diuretics", "message": "STOP: Life-threatening hyperkalemia can occur. Monitor serum potassium levels closely, especially in patients with renal insufficiency or those taking ACE inhibitors, ARBs, or potassium-sparing diuretics."}, {"alert_type": "Gastrointestinal Lesions", "severity": "High", "trigger_condition": "Use of solid oral dosage forms", "message": "STOP: Solid oral dosage forms can produce ulcerative or stenotic lesions of the GI tract. Discontinue immediately if severe vomiting, abdominal pain, or GI bleeding occurs."}]', '**Hyperkalemia:** The most severe risk is hyperkalemia, which can cause fatal cardiac arrhythmias. Monitor serum potassium, renal function, and ECG periodically.
INSERT INTO "drug_generic" VALUES(297, 'Capmatinib', 'Capmatinib', 'L01EX17', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Interstitial Lung Disease (ILD)/Pneumonitis", "severity": "High", "trigger_condition": "New or worsening pulmonary symptoms", "message": "STOP: Severe, life-threatening, and fatal ILD/pneumonitis can occur. Withhold therapy for suspected ILD/pneumonitis and permanently discontinue if confirmed."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated transaminases or bilirubin", "message": "STOP: Hepatotoxicity can occur. Monitor liver function tests prior to initiation, every 2 weeks for the first 3 months, and then monthly."}]', 'Monitor liver function tests (ALT, AST, and total bilirubin) prior to the start of therapy, every 2 weeks during the first 3 months of treatment, and then once monthly or as clinically indicated. Increase the frequency of testing in patients who develop elevated transaminases or bilirubin.
INSERT INTO "drug_generic" VALUES(298, 'Framycetin sulfate Eye prep', 'Framycetin', 'S01AA07', 1, 0, 0, 0, 0, 1, 1, 0, '[]', 'Prolonged use may result in the overgrowth of non-susceptible organisms, including fungi. If superinfection occurs, discontinue use and institute appropriate therapy.
INSERT INTO "drug_generic" VALUES(299, 'Phenylephrine + Mineral oil + Petrolatum rectal prep', 'Phenylephrine / Mineral oil / Petrolatum', 'C05AX', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Systemic Sympathomimetic Effects", "severity": "Low", "trigger_condition": "Excessive application or use in patients with severe cardiovascular disease", "message": "Contains phenylephrine. Systemic absorption can occur, potentially exacerbating hypertension, heart disease, or hyperthyroidism. Discontinue if symptoms worsen."}]', '**Cardiovascular and Endocrine Disease:** Contains phenylephrine, an alpha-adrenergic agonist. Use with caution in patients with heart disease, hypertension, hyperthyroidism, diabetes mellitus, or prostatic hypertrophy, as systemic absorption can exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(300, 'Timolol Maleate Eye prep', 'Timolol Ophthalmic', 'S01ED01', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Systemic Absorption Risk", "severity": "High", "trigger_condition": "Patients with a history of severe reactive airway disease or severe cardiac failure", "message": "STOP: Severe respiratory reactions and cardiac reactions, including death due to bronchospasm or cardiac failure, have been reported following ophthalmic administration due to systemic absorption."}]', 'Monitor patients receiving topical timolol and a systemic beta-adrenergic blocking agent concomitantly for potential additive effects on intraocular pressure (IOP) and systemic beta-blockade.
INSERT INTO "drug_generic" VALUES(301, 'Tegaserod', 'Tegaserod', 'A03AE02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Ischemic Events", "severity": "High", "trigger_condition": "Patients with a history of cardiovascular disease", "message": "STOP: Tegaserod is associated with an increased risk of myocardial infarction, stroke, and unstable angina. Contraindicated in patients with a history of these events."}, {"alert_type": "Ischemic Colitis", "severity": "High", "trigger_condition": "Development of rectal bleeding or sudden abdominal pain", "message": "STOP: Discontinue immediately if the patient develops rectal bleeding, bloody diarrhea, or new/sudden worsening of abdominal pain."}]', 'Assess cardiovascular risk before initiating therapy. Discontinue immediately if signs of ischemic colitis (rectal bleeding, bloody diarrhea, worsening abdominal pain) occur. Discontinue if severe diarrhea occurs, as it may lead to hypovolemia, hypotension, and syncope. Use with caution in patients with mild hepatic impairment. Not recommended for use in patients 65 years of age or older due to increased cardiovascular risk.', '- **Irritable Bowel Syndrome with Constipation (IBS-C):** Treatment of adult women less than 65 years of age with irritable bowel syndrome with constipation.', '- **Cardiovascular Disease:** Contraindicated in patients with a history of myocardial infarction, stroke, transient ischemic attack (TIA), or angina due to the increased risk of major adverse cardiovascular events.
INSERT INTO "drug_generic" VALUES(302, 'Digoxin immune FAB', 'Digoxin immune FAB', 'V03AB24', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hypokalemia and Heart Failure Exacerbation", "severity": "High", "trigger_condition": "Administration of Digoxin immune FAB", "message": "STOP: Rapid shift of potassium into cells can cause severe hypokalemia. Reversal of digoxin''s inotropic effect may exacerbate heart failure or cause rapid ventricular response in atrial fibrillation. Monitor potassium and ECG continuously."}]', '**Hypokalemia:** Digoxin toxicity causes a shift of potassium from intracellular to extracellular spaces, leading to hyperkalemia. Administration of Digoxin immune FAB reverses this, causing potassium to shift back into cells, which can result in rapid and severe hypokalemia. Monitor serum potassium levels closely, especially during the first several hours after administration.
INSERT INTO "drug_generic" VALUES(303, 'Halobetasol + Tazarotene topical', 'Halobetasol Propionate and Tazarotene', 'D05AX55', 0, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Teratogenicity Risk", "severity": "High", "trigger_condition": "Prescription to females of reproductive potential", "message": "STOP: Tazarotene is highly teratogenic. Obtain a negative pregnancy test within 2 weeks prior to initiating therapy and ensure effective contraception is used during treatment."}]', 'Avoid application on eczematous, broken, or sunburned skin until fully recovered, as severe irritation and systemic absorption may occur.
INSERT INTO "drug_generic" VALUES(304, 'Melphalan', 'Melphalan', 'L01AA03', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Initiation of therapy or concurrent use with other myelosuppressive agents", "message": "STOP: Melphalan causes severe bone marrow suppression resulting in profound leukopenia, thrombocytopenia, and anemia. Monitor complete blood counts frequently. Do not administer if absolute neutrophil count or platelet count is critically low."}, {"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Intravenous administration", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, have occurred with IV melphalan. Have resuscitation equipment and medications readily available during infusion."}]', 'Administer under the supervision of a qualified physician experienced in the use of cancer chemotherapeutic agents. Profound myelosuppression is the dose-limiting toxicity; monitor complete blood counts (CBC) with differential and platelets frequently. Delay or adjust subsequent doses until blood counts recover. Use with extreme caution in patients with compromised bone marrow reserve due to prior irradiation or chemotherapy. Patients with renal impairment require dosage reduction, as delayed excretion increases the risk of severe bone marrow toxicity. Melphalan is leukemogenic and has been associated with the development of secondary malignancies, including acute nonlymphocytic leukemia and myeloproliferative syndrome. Monitor for signs of pulmonary toxicity, including pulmonary fibrosis and interstitial pneumonitis. May cause temporary or permanent sterility in both male and female patients.', '- **Multiple Myeloma:** Palliative treatment of multiple myeloma.
INSERT INTO "drug_generic" VALUES(305, 'Fluorometholone 0.1 % Eye prep', 'Fluorometholone 0.1% Ophthalmic Suspension', 'S01BA07', 0, 0, 0, 0, 0, 0, 0, 1, '[]', 'Prolonged use may result in glaucoma, optic nerve damage, visual acuity defects, and posterior subcapsular cataract formation. Intraocular pressure (IOP) must be monitored routinely if used for 10 days or longer. Corticosteroids may mask, activate, or exacerbate ocular infections. May cause corneal and scleral thinning, leading to perforation in severe cases. Use of steroids after cataract surgery may prolong healing time and increase bleb formation. Not to be used in mustard gas keratitis and Sjogren''s keratoconjunctivitis.', '- **Allergic and Inflammatory Ocular Conditions:** Treatment of corticosteroid-responsive inflammation of the palpebral and bulbar conjunctiva, cornea, and anterior segment of the globe.', '- **Viral and Fungal Eye Infections:** Contraindicated in epithelial herpes simplex keratitis (dendritic keratitis), vaccinia, varicella, and other viral diseases of the cornea and conjunctiva, as well as mycobacterial and fungal infections of the eye.
INSERT INTO "drug_generic" VALUES(306, 'Mumps, Rubella, Measles (Live Attenuated) Vaccine', 'Measles, Mumps, and Rubella Virus Vaccine Live', 'J07BD52', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Immunocompromised Status", "severity": "High", "trigger_condition": "Administration to severely immunocompromised patients or those with a history of anaphylaxis to vaccine components", "message": "STOP: Contraindicated in patients with severe primary or acquired immunodeficiency (e.g., cellular immune deficiencies, severe HIV) due to the risk of fatal disseminated vaccine virus infection. Ensure epinephrine is available to treat potential anaphylaxis."}]', '**Febrile Illness:** Vaccination may be deferred in patients with moderate or severe acute illness to avoid confusing disease symptoms with vaccine adverse effects.
INSERT INTO "drug_generic" VALUES(307, 'Calcium (Algae Source) + Vitamin D3', 'Calcium + Cholecalciferol', 'A12AX', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "Moderate", "trigger_condition": "Concurrent use with thiazide diuretics or cardiac glycosides", "message": "Caution: Increased risk of hypercalcemia. Monitor serum calcium levels closely, as hypercalcemia can precipitate fatal cardiac arrhythmias in patients taking digitalis."}]', '**Renal Impairment and Nephrolithiasis:** Patients with mild to moderate renal failure or mild hypercalciuria require careful supervision, including periodic checks of plasma calcium levels and urinary calcium excretion. Measure urinary calcium excretion in patients with a history of renal stones to exclude hypercalciuria.
INSERT INTO "drug_generic" VALUES(308, 'Iron Polymaltose Complex (Elemental Iron) + Folic Acid + Zinc', 'Iron, Folic Acid, and Zinc Supplement', 'B03AD', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Accidental Overdose Risk", "severity": "High", "trigger_condition": "Accidental ingestion by children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product out of reach of children."}]', '**Iron Overload:** Care should be taken in patients who may develop iron overload, such as those with undiagnosed anemias. Iron should not be administered to patients receiving repeated blood transfusions.
INSERT INTO "drug_generic" VALUES(309, 'Obiltoxaximab', 'Obiltoxaximab', 'J06BB21', 0, 1, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "During or immediately following intravenous infusion", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, can occur. Administer in monitored settings equipped to manage anaphylaxis. Premedicate with diphenhydramine. Stop infusion immediately if anaphylaxis occurs."}]', '**Hypersensitivity Reactions and Anaphylaxis:** Hypersensitivity reactions, including anaphylaxis, were the most common adverse reactions in safety trials. Premedication with diphenhydramine is strongly recommended prior to administration. Note that diphenhydramine does not prevent anaphylaxis and may mask or delay the onset of hypersensitivity symptoms. Monitor patients closely during the infusion and for a period of time afterward.
INSERT INTO "drug_generic" VALUES(310, 'Amino Acids 7 % + Glucose + Electrolytes 10 %', 'Amino Acids with Glucose and Electrolytes', 'B05BA10', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Pulmonary Embolism", "severity": "High", "trigger_condition": "Precipitate formation in the IV line", "message": "STOP: Pulmonary vascular precipitates causing pulmonary embolism and death have occurred. Inspect solutions visually for particulate matter. If signs of pulmonary distress occur, stop the infusion immediately."}, {"alert_type": "Central Line Requirement", "severity": "High", "trigger_condition": "Infusion of hyperosmolar solutions", "message": "STOP: Solutions with an osmolarity of 900 mOsm/L or greater MUST be infused through a central venous catheter to prevent severe vein damage and thrombosis."}]', '**Refeeding Syndrome:** Refeeding severely undernourished patients can result in the refeeding syndrome, characterized by intracellular shift of potassium, phosphorus, and magnesium as the patient becomes anabolic. Thiamine deficiency and fluid retention may also develop. Monitor electrolytes closely.
INSERT INTO "drug_generic" VALUES(311, 'Rimexolone 1% Eye prep', 'Rimexolone', 'S01BA13', 0, 0, 0, 1, 0, 1, 0, 1, '[{"alert_type": "Ocular Toxicity", "severity": "High", "trigger_condition": "Prolonged use beyond 10 days", "message": "STOP: Prolonged use of ophthalmic corticosteroids can result in ocular hypertension, glaucoma, optic nerve damage, and posterior subcapsular cataract formation. Monitor intraocular pressure routinely."}]', '**Intraocular Pressure (IOP) Elevation:** Prolonged use may result in elevated IOP, potentially leading to glaucoma and optic nerve damage. Monitor IOP if used for more than 10 days.
INSERT INTO "drug_generic" VALUES(312, 'Remdesivir', 'Remdesivir', 'J05AB16', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Infusion-Related Reactions", "severity": "High", "trigger_condition": "During or immediately following IV infusion", "message": "STOP: Hypersensitivity and infusion-related reactions (hypotension, tachycardia, wheezing, angioedema) can occur. Discontinue immediately if a clinically significant reaction occurs."}]', '**Hypersensitivity and Infusion-Related Reactions:** Reactions including hypotension, hypertension, tachycardia, bradycardia, hypoxia, fever, dyspnea, wheezing, angioedema, rash, nausea, diaphoresis, and shivering have been observed. Consider slowing the infusion rate (up to 120 minutes) to prevent these. Discontinue immediately if a severe reaction occurs.
INSERT INTO "drug_generic" VALUES(313, 'Benzocaine 0.065% + Camphor 0.25% + Methanol 0.25%', 'Benzocaine, Camphor, and Menthol', 'N01BA55', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Methemoglobinemia", "severity": "High", "trigger_condition": "Use of oral benzocaine products", "message": "STOP: Benzocaine can cause fatal methemoglobinemia. The FDA strongly warns against using oral benzocaine products for teething in children under 2 years of age. Advise adults to seek immediate medical attention if cyanosis, headache, or shortness of breath occurs."}]', '**Application Site:** Do not use over deep or puncture wounds, severe infections, or lacerations. Avoid contact with the eyes.
INSERT INTO "drug_generic" VALUES(314, 'Betamethasone 0.1% + Fusidic Acid 2% Topical', 'Betamethasone and Fusidic Acid', 'D07CC01', 1, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Duration of Therapy", "severity": "Medium", "trigger_condition": "Prolonged use beyond 14 days", "message": "STOP: Do not use for more than 14 days. Prolonged use increases the risk of bacterial resistance to fusidic acid and severe skin atrophy/systemic absorption from betamethasone."}]', '**Systemic Absorption:** Systemic absorption of topical corticosteroids can produce reversible HPA axis suppression, Cushing''s syndrome, and hyperglycemia. Risk increases with prolonged use, application to large surface areas, or use of occlusive dressings.
INSERT INTO "drug_generic" VALUES(315, 'Gemcitabine', 'Gemcitabine', 'L01BC05', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Myelosuppression", "severity": "High", "trigger_condition": "Administration of gemcitabine therapy", "message": "STOP: Severe myelosuppression (anemia, leukopenia, thrombocytopenia) can occur. Monitor complete blood counts prior to each dose."}, {"alert_type": "Hemolytic Uremic Syndrome (HUS)", "severity": "High", "trigger_condition": "Signs of microangiopathic hemolytic anemia", "message": "STOP: Discontinue immediately at the first sign of microangiopathic hemolytic anemia. HUS and/or thrombocytopenic purpura may lead to irreversible renal failure."}]', '**Hematologic Toxicity:** May cause severe myelosuppression; monitor complete blood counts (CBC) with differential and platelet count prior to each dose.
INSERT INTO "drug_generic" VALUES(316, 'Coal Tar', 'Coal Tar', 'D05AA', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Photosensitivity Risk", "severity": "High", "trigger_condition": "Exposure to sunlight or UV radiation", "message": "WARNING: Coal tar significantly increases sensitivity to sunlight. Avoid direct sunlight and sunlamps for at least 24 to 72 hours after application to prevent severe sunburn."}]', '**Photosensitivity:** Increases susceptibility to sunburn. Patients must avoid direct sunlight and artificial UV exposure for 24-72 hours post-application unless undergoing supervised Goeckerman therapy.
INSERT INTO "drug_generic" VALUES(317, 'Levomenthol + Thymol + Terpineol + Chlorobutanol', 'Menthol, Thymol, Terpineol, and Chlorobutanol Inhalant', 'R05X', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Inhalation Only - Do Not Ingest", "severity": "High", "trigger_condition": "Improper administration", "message": "STOP: For inhalation only. Do NOT swallow or ingest the capsule or liquid. Oral ingestion can cause severe central nervous system depression, seizures, and systemic toxicity."}, {"alert_type": "Pediatric Respiratory Risk", "severity": "High", "trigger_condition": "Use in infants and young children", "message": "Avoid direct inhalation or application near the nostrils of children under 3 years old due to the risk of severe reflex laryngospasm, apnea, or respiratory distress."}]', '**Eye Contact:** Keep vapor and liquid away from eyes and mucous membranes to prevent severe burning and irritation. Keep eyes closed during steam inhalation.
INSERT INTO "drug_generic" VALUES(318, 'Astemizole', 'Astemizole', 'R06AX11', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Fatal Arrhythmias", "severity": "High", "trigger_condition": "Concomitant use with CYP3A4 inhibitors or exceeding recommended doses", "message": "STOP: Astemizole is associated with severe, potentially fatal ventricular arrhythmias, including torsades de pointes and QT prolongation. Do not exceed the recommended dose. Avoid concomitant use with macrolide antibiotics, azole antifungals, or in patients with hepatic dysfunction."}]', '**Cardiovascular Risk:** Extreme caution is required due to the risk of QT interval prolongation and potentially fatal ventricular arrhythmias (e.g., torsades de pointes). Do not exceed recommended doses.
INSERT INTO "drug_generic" VALUES(319, 'Fexofenadine Hydrochloride + Pseudoephedrine Hydrochloride', 'Fexofenadine and Pseudoephedrine', 'R01BA52', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Patient with severe hypertension or coronary artery disease", "message": "STOP: Pseudoephedrine is a sympathomimetic amine that can cause severe cardiovascular events. Contraindicated in severe hypertension and severe coronary artery disease."}, {"alert_type": "Drug Interaction", "severity": "High", "trigger_condition": "Concurrent use of MAOIs", "message": "STOP: Co-administration with Monoamine Oxidase Inhibitors (MAOIs) or use within 14 days of stopping an MAOI can cause a fatal hypertensive crisis."}]', '- **Cardiovascular Disease:** Use with caution in patients with ischemic heart disease, arrhythmias, tachycardia, or mild-to-moderate hypertension due to the sympathomimetic effects of pseudoephedrine.
INSERT INTO "drug_generic" VALUES(320, 'Beclomethasone + Neomycin Topical', 'Beclomethasone and Neomycin Topical', 'D07CC04', 1, 0, 0, 0, 0, 0, 0, 1, '[]', '**Neomycin Sensitization:** Neomycin is a known contact sensitizer. Prolonged use increases the risk of allergic contact dermatitis. If irritation or sensitization occurs, discontinue use immediately.
INSERT INTO "drug_generic" VALUES(321, 'Atracurium Besylate', 'Atracurium', 'M03AC04', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Respiratory Arrest", "severity": "High", "trigger_condition": "Administration without ventilatory support", "message": "STOP: Atracurium causes paralysis of the respiratory muscles. It MUST be administered by trained personnel with immediate availability of endotracheal intubation and mechanical ventilation."}]', '**Histamine Release:** Can cause significant histamine release leading to skin flushing, erythema, hypotension, tachycardia, and bronchospasm. Administer slowly or in divided doses in patients with significant cardiovascular disease or asthma.
INSERT INTO "drug_generic" VALUES(322, 'Nevirapine', 'Nevirapine', 'J05AG01', 0, 1, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity and Skin Reactions", "severity": "High", "trigger_condition": "Initiation of therapy or first 18 weeks of treatment", "message": "STOP: Severe, life-threatening, and in some cases fatal hepatotoxicity and skin reactions (e.g., Stevens-Johnson syndrome, toxic epidermal necrolysis) have occurred. The 14-day lead-in period is strictly required to reduce this risk. Monitor liver function intensively during the first 18 weeks."}]', '- **Hepatotoxicity:** Severe and life-threatening hepatotoxicity can occur, particularly during the first 18 weeks of treatment. Women with CD4+ counts >250 cells/mm³ and men with CD4+ counts >400 cells/mm³ are at higher risk. Monitor LFTs periodically.
INSERT INTO "drug_generic" VALUES(323, 'Fluocinolone 0.025% + Neomycin Sulphate 0.5% Topical', 'Fluocinolone Acetonide 0.025% and Neomycin Sulfate 0.5% Topical', 'D07CC02', 1, 0, 0, 0, 1, 0, 0, 1, '[]', 'Prolonged use or application over large surface areas, especially under occlusive dressings, can lead to systemic absorption of both the corticosteroid (causing HPA axis suppression, Cushing''s syndrome) and neomycin (causing ototoxicity and nephrotoxicity). Use with extreme caution in children, the elderly, and patients with hepatic or renal failure. Avoid prolonged use on the face and keep away from the eyes. If irritation or sensitization develops, discontinue treatment.', '- **Corticosteroid-Responsive Dermatoses with Secondary Infection:** Treatment of inflammatory skin conditions such as eczema, psoriasis, and dermatitis where secondary bacterial infection is present or suspected.
INSERT INTO "drug_generic" VALUES(324, 'Bacitracin Zinc + Neomycin Sulphate Eye prep', 'Bacitracin and Neomycin Ophthalmic', 'S01AA30', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Allergic Contact Dermatitis", "severity": "Medium", "trigger_condition": "Application to the eye", "message": "STOP: Neomycin is a potent sensitizer. Allergic contact dermatitis and conjunctival erythema occur frequently. Discontinue if redness, itching, or worsening of the eye condition occurs."}]', '**Superinfection:** Prolonged use of antibacterial preparations may cause overgrowth of non-susceptible organisms, including fungi. If superinfection occurs, discontinue use and institute appropriate therapy.
INSERT INTO "drug_generic" VALUES(325, 'Meropenem', 'Meropenem', 'J01DH02', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "History of beta-lactam allergy", "message": "Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. Cross-reactivity with penicillins and cephalosporins can occur. Discontinue immediately if an allergic reaction occurs."}, {"alert_type": "Seizure Risk", "severity": "High", "trigger_condition": "CNS disorders or renal impairment", "message": "Seizures and other adverse CNS experiences have been reported, particularly in patients with underlying CNS disorders (e.g., brain lesions, history of seizures) or with renal impairment. Adjust dose in renal impairment."}]', 'Use with caution in patients with a history of seizures or underlying CNS disorders. Monitor renal, hepatic, and hematopoietic functions periodically during prolonged therapy. Not recommended for the treatment of Methicillin-resistant Staphylococcus aureus (MRSA) infections. Prolonged use may result in overgrowth of nonsusceptible organisms, including C. difficile, leading to pseudomembranous colitis. Monitor for signs of anaphylaxis during the first dose.', '- **Intra-abdominal Infections:** Treatment of complicated appendicitis and peritonitis caused by susceptible isolates.
INSERT INTO "drug_generic" VALUES(326, 'Almotriptan', 'Almotriptan', 'N02CC05', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Myocardial Ischemia and Cardiac Events", "severity": "High", "trigger_condition": "Patients with underlying coronary artery disease or risk factors", "message": "STOP: Serious adverse cardiac events, including acute MI and life-threatening arrhythmias, have occurred. Contraindicated in patients with ischemic heart disease. Evaluate patients with cardiovascular risk factors before prescribing."}, {"alert_type": "Serotonin Syndrome", "severity": "High", "trigger_condition": "Concomitant use with SSRIs, SNRIs, or MAOIs", "message": "STOP: Potentially life-threatening serotonin syndrome can occur. Monitor for mental status changes, autonomic instability, and neuromuscular abnormalities."}]', '**Chest/Jaw/Neck Pain:** Sensations of tightness, pain, and pressure in the chest, throat, neck, and jaw commonly occur after treatment. While usually non-ischemic, patients with symptoms suggestive of angina must be evaluated for CAD.
INSERT INTO "drug_generic" VALUES(327, 'Ascorbic Acid + Biotin + Cholecalciferol (Vit. D3)', 'Ascorbic Acid, Biotin, and Cholecalciferol', 'A11JB', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "Low", "message": "Excessive intake of Vitamin D3 can lead to hypercalcemia. Do not exceed the recommended daily dosage."}]', '**Renal Impairment:** Use with caution in patients with mild to moderate renal failure. High doses of Vitamin C can increase the risk of oxalate kidney stones.
INSERT INTO "drug_generic" VALUES(328, 'Miltefosine', 'Miltefosine', 'P01CX04', 1, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Use in females of reproductive potential", "message": "STOP: Miltefosine can cause fetal harm. Obtain a negative pregnancy test before starting. Effective contraception is required during therapy and for 5 months after completion."}]', 'Monitor renal function (serum creatinine) and hepatic function (ALT, AST, bilirubin) weekly during treatment; elevations may require dose interruption or discontinuation. Monitor platelet counts, as thrombocytopenia has been reported. Severe dermatologic reactions, including Stevens-Johnson syndrome, have occurred; discontinue immediately if an exfoliative or bullous rash develops. Gastrointestinal toxicity (nausea, vomiting, diarrhea) is very common and can lead to dehydration; ensure adequate hydration and consider antiemetics. Avoid use in patients with Sjögren-Larsson-Syndrome.', '- **Visceral Leishmaniasis:** Treatment of visceral leishmaniasis caused by *Leishmania donovani*.
INSERT INTO "drug_generic" VALUES(329, 'Sulindac', 'Sulindac', 'M01AB02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke, which can be fatal. They also cause an increased risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation of the stomach or intestines."}]', '**Cardiovascular Risk:** May increase the risk of severe CV thrombotic events, MI, and stroke. Risk increases with duration of use and in patients with pre-existing CV disease.
INSERT INTO "drug_generic" VALUES(330, 'Olopatadine Oral', 'Olopatadine', 'R06AX27', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "CNS Depression", "severity": "Moderate", "trigger_condition": "Concurrent use with alcohol or other CNS depressants", "message": "Caution: May cause somnolence and impair the ability to drive or operate machinery. Avoid concurrent use with alcohol or other CNS depressants."}]', '**CNS Depression:** Olopatadine may cause somnolence and impair physical or mental abilities. Patients should be cautioned against engaging in hazardous occupations requiring complete mental alertness, such as driving or operating machinery.
INSERT INTO "drug_generic" VALUES(331, 'Ivosidenib', 'Ivosidenib', 'L01XX62', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Differentiation Syndrome", "severity": "High", "trigger_condition": "Treatment of Acute Myeloid Leukemia (AML)", "message": "Can cause severe or fatal differentiation syndrome. Monitor for fever, dyspnea, hypoxia, pulmonary infiltrates, and pleural/pericardial effusions. Initiate corticosteroids immediately if suspected."}]', '**Differentiation Syndrome:** Patients with AML treated with ivosidenib have experienced differentiation syndrome, which can be fatal if not treated promptly. Symptoms include fever, dyspnea, hypoxia, pulmonary infiltrates, pleural or pericardial effusions, rapid weight gain, and peripheral edema. If suspected, initiate systemic corticosteroids (e.g., dexamethasone 10 mg IV every 12 hours) and hemodynamic monitoring immediately until symptoms resolve.
INSERT INTO "drug_generic" VALUES(332, 'Lindane topical', 'Lindane topical', 'P03AB02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Neurotoxicity", "severity": "High", "trigger_condition": "Prolonged application, repeat application, or use in high-risk patients (infants, <50 kg, seizure history)", "message": "STOP: Lindane can cause severe neurotoxicity, including seizures and death. It is strictly a second-line treatment. Contraindicated in premature infants and patients with uncontrolled seizure disorders."}]', '- **Neurotoxicity Risk:** Severe neurologic toxicities, including seizures and death, have been reported with repeat or prolonged application, and rarely with a single application. 
INSERT INTO "drug_generic" VALUES(333, 'Sotagliflozin', 'Sotagliflozin', 'A10BK06', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Diabetic Ketoacidosis (DKA)", "severity": "High", "trigger_condition": "Patients presenting with nausea, vomiting, abdominal pain, malaise, or shortness of breath", "message": "STOP: Assess for ketoacidosis immediately, regardless of blood glucose levels. Discontinue therapy if DKA is suspected or confirmed."}]', '**Diabetic Ketoacidosis (DKA):** Risk of DKA is increased, particularly in patients with type 1 diabetes, acute illness, or caloric restriction. Monitor for ketones and assess volume status.
INSERT INTO "drug_generic" VALUES(334, 'Halothane', 'Halothane', 'N01AB01', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Malignant Hyperthermia and Hepatotoxicity", "severity": "High", "trigger_condition": "Susceptibility to malignant hyperthermia or history of halothane hepatitis", "message": "STOP: Halothane can trigger fatal malignant hyperthermia. It is also associated with severe, potentially fatal hepatotoxicity (halothane hepatitis), especially upon repeated exposure."}]', '**Hepatotoxicity (Halothane Hepatitis):** Severe, potentially fatal hepatic necrosis can occur, typically following repeated exposures. The risk is higher in adults, obese patients, and females. Avoid repeated use within a 3-month period.
INSERT INTO "drug_generic" VALUES(335, 'Tipranavir', 'Tipranavir', 'J05AE09', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Pre-existing liver disease or co-infection with Hepatitis B/C", "message": "STOP: Clinical hepatitis and hepatic decompensation, including some fatalities, have been reported. Extra vigilance is required in patients with chronic hepatitis B or C co-infection."}, {"alert_type": "Intracranial Hemorrhage", "severity": "High", "trigger_condition": "Patients at risk for bleeding or receiving anticoagulant/antiplatelet therapy", "message": "WARNING: Fatal and non-fatal intracranial hemorrhage have been reported. Use with extreme caution in patients with bleeding diatheses or those taking medications that increase bleeding risk."}]', '**Hepatotoxicity:** Severe, potentially fatal hepatotoxicity has occurred. Monitor LFTs before and frequently during treatment. Discontinue if liver enzymes exceed 10 times the upper limit of normal or if clinical signs of hepatitis develop. Not to be used in patients with pre-treatment liver enzymes >5 times the upper limit of normal.
INSERT INTO "drug_generic" VALUES(336, 'Dextromethorphan HBr + Phenylephrine HCl + Triprolidine HCl', 'Dextromethorphan/Phenylephrine/Triprolidine', 'R05DA20', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "MAOI Interaction", "severity": "High", "trigger_condition": "Concomitant use of MAOIs", "message": "STOP: Fatal drug interactions (hypertensive crisis, serotonin syndrome) can occur. Do not use within 14 days of stopping a monoamine oxidase inhibitor."}]', '**CNS Depression:** May cause significant drowsiness. Patients should avoid driving or operating machinery. Avoid concurrent use of alcohol or other CNS depressants.
INSERT INTO "drug_generic" VALUES(337, 'Labetalol Hydrochloride', 'Labetalol', 'C07AG01', 0, 1, 1, 0, 0, 0, 1, 1, '[{"alert_type": "Severe Hepatocellular Injury", "severity": "High", "trigger_condition": "Development of jaundice or laboratory evidence of liver injury", "message": "Severe hepatocellular injury, which may be fatal, has been reported rarely. Discontinue labetalol immediately if clinical signs of liver injury or jaundice occur."}]', 'Abrupt cessation of therapy may exacerbate angina or precipitate myocardial infarction; taper gradually over 1 to 2 weeks. Use with caution in patients with compensated heart failure, nonallergic bronchospasm (e.g., chronic bronchitis, emphysema), diabetes mellitus (may mask signs of hypoglycemia), and pheochromocytoma (paradoxical hypertensive responses may occur). Monitor liver function tests (LFTs) periodically. Use with caution in the elderly due to an increased risk of orthostatic hypotension.', '- **Hypertension:** Management of essential hypertension, either alone or in combination with other antihypertensive agents.
INSERT INTO "drug_generic" VALUES(338, 'Granisetron', 'Granisetron', 'A04AA02', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Concurrent use of QT-prolonging drugs or presence of congenital long QT syndrome", "message": "STOP: Granisetron can cause dose-dependent QT interval prolongation. Avoid or use with extreme caution in patients with congenital long QT syndrome, electrolyte abnormalities, or those taking other QT-prolonging medications."}]', '**QT Prolongation and Arrhythmias:** Granisetron can prolong the PR, QRS, and QT intervals. Use with caution in patients with pre-existing arrhythmias, cardiac conduction disorders, congenital long QT syndrome, or electrolyte abnormalities (e.g., hypokalemia, hypomagnesemia), and in patients receiving cumulative high-dose anthracycline therapy.
INSERT INTO "drug_generic" VALUES(339, 'Etrasimod', 'Etrasimod', 'L04AE04', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiac and Immunosuppressive Risk", "severity": "High", "trigger_condition": "Initiation of therapy or presence of underlying cardiac/infectious conditions", "message": "STOP: May cause significant bradycardia and atrioventricular conduction delays upon initiation. Increases the risk of serious infections. Avoid live vaccines during and for 4 weeks after treatment."}]', '**Infections:** Increases the risk of serious infections. Obtain a recent CBC before initiation. Monitor for infection during and for 4 weeks after stopping therapy.
INSERT INTO "drug_generic" VALUES(340, 'Tioconazole 1% Topical', 'Tioconazole Topical', 'D01AC07', 0, 0, 0, 0, 0, 1, 1, 0, '[]', 'For external use only. Avoid contact with the eyes, mouth, or other mucous membranes.
INSERT INTO "drug_generic" VALUES(341, 'Daptomycin', 'Daptomycin', 'J01XX09', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Concomitant use of statins or elevated baseline CPK", "message": "WARNING: Daptomycin can cause severe myopathy and rhabdomyolysis. Monitor CPK levels weekly. Consider temporarily suspending HMG-CoA reductase inhibitors (statins) during therapy."}, {"alert_type": "Eosinophilic Pneumonia", "severity": "High", "trigger_condition": "Development of new onset fever, dyspnea, and hypoxic respiratory failure", "message": "STOP: Eosinophilic pneumonia has been reported, typically 2 to 4 weeks after initiation. Discontinue daptomycin immediately and consider systemic steroids if suspected."}]', '**Myopathy and Rhabdomyolysis:** Monitor plasma creatine phosphokinase (CPK) before treatment and at least weekly during treatment. Monitor more frequently in patients at higher risk (e.g., renal impairment, taking statins, or baseline CPK >5x ULN). Discontinue if CPK is markedly elevated or if myopathy occurs.
INSERT INTO "drug_generic" VALUES(342, 'Mannitol 20%', 'Mannitol', 'B05BC01', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Fluid and Electrolyte Imbalance", "severity": "High", "trigger_condition": "Administration of high doses or rapid infusion", "message": "STOP: Severe fluid and electrolyte shifts can occur, leading to pulmonary edema, heart failure, or severe dehydration. Monitor serum osmolarity, electrolytes, and renal function closely."}]', '**Cardiovascular and Pulmonary Status:** Monitor closely for signs of hypervolemia, pulmonary congestion, or heart failure, as the osmotic shift of intracellular fluid into the extracellular space can precipitate acute volume overload.
INSERT INTO "drug_generic" VALUES(343, 'Clobetasol Propionate + Salicylic Acid topical', 'Clobetasol and Salicylic Acid Topical', 'D07XC01', 0, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "High Potency Corticosteroid Toxicity", "severity": "High", "trigger_condition": "Use exceeding 50 grams per week or duration > 2 consecutive weeks", "message": "Clobetasol is a super-high potency topical corticosteroid. Do not exceed 50 g/week or use for more than 2 consecutive weeks due to the high risk of hypothalamic-pituitary-adrenal (HPA) axis suppression and systemic toxicity."}]', '**HPA Axis Suppression:** Can produce reversible HPA axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria. Risk increases with prolonged use, application to large surface areas, or use of occlusive dressings.
INSERT INTO "drug_generic" VALUES(344, 'Carmustine', 'Carmustine', 'L01AD01', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Delayed Myelosuppression", "severity": "High", "trigger_condition": "Administration of standard or high doses", "message": "STOP: Carmustine causes severe, delayed bone marrow suppression (thrombocytopenia and leukopenia). Do not administer more frequently than every 6 weeks. Monitor CBC weekly for at least 6 weeks post-dose."}, {"alert_type": "Pulmonary Toxicity", "severity": "High", "trigger_condition": "Cumulative doses > 1400 mg/m2 or history of lung disease", "message": "STOP: Dose-related, potentially fatal pulmonary toxicity (fibrosis) can occur. Monitor pulmonary function closely. Delayed cases have been reported years after treatment."}]', '**Bone Marrow Suppression:** Severe and delayed myelosuppression (notably thrombocytopenia and leukopenia) is the most common dose-limiting toxicity. It typically occurs 4 to 6 weeks after administration and may contribute to fatal bleeding and infections. Monitor complete blood counts (CBC) weekly for at least 6 weeks after a dose. Do not administer more frequently than every 6 to 8 weeks.
INSERT INTO "drug_generic" VALUES(345, 'Cod Liver Oil (Vitamin A + D)', 'Cod Liver Oil', 'A11CB', 0, 0, 0, 1, 0, 0, 1, 0, '[]', '**Hypervitaminosis:** Excessive intake can lead to hypervitaminosis A and D, causing hypercalcemia, hepatotoxicity, and bone pain. Do not exceed recommended doses, especially when taking other vitamin supplements.
INSERT INTO "drug_generic" VALUES(346, 'Omeprazole 20mg + Sodium bicarbonate 1100mg', 'Omeprazole / Sodium Bicarbonate', 'A02BC01', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Sodium Load Warning", "severity": "High", "trigger_condition": "Patients with heart failure, cirrhosis, or severe renal impairment", "message": "Each dose contains a significant amount of sodium (from sodium bicarbonate). Use with extreme caution in patients on sodium-restricted diets or those with conditions exacerbated by fluid retention."}]', '**Gastric Malignancy:** Symptomatic response to therapy does not preclude the presence of gastric malignancy; evaluate for malignancy if symptoms persist.
INSERT INTO "drug_generic" VALUES(347, 'Clomipramine Hydrochloride', 'Clomipramine', 'N06AA04', 0, 1, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Suicidal Thoughts and Behaviors", "severity": "High", "trigger_condition": "Initiation of therapy or dose changes, especially in children, adolescents, and young adults (<24 years)", "message": "Antidepressants increase the risk of suicidal thoughts and behaviors in pediatric and young adult patients. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}, {"alert_type": "Seizure Risk", "severity": "High", "trigger_condition": "Doses >250 mg/day or rapid dose escalation", "message": "Clomipramine lowers the seizure threshold. The risk of seizures is dose-dependent. Do not exceed 250 mg/day in adults or 200 mg/day in children. Titrate doses gradually."}]', '**Serotonin Syndrome:** Potentially life-threatening serotonin syndrome can occur, especially with concomitant use of other serotonergic drugs (e.g., MAOIs, SSRIs, SNRIs, triptans). Monitor for mental status changes, autonomic instability, and neuromuscular abnormalities.
INSERT INTO "drug_generic" VALUES(348, 'Ranolazine', 'Ranolazine', 'C01EB18', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "QT Prolongation Risk", "severity": "High", "trigger_condition": "Concomitant use with strong CYP3A inhibitors or other QT-prolonging drugs", "message": "STOP: Ranolazine prolongs the QT interval. Co-administration with strong CYP3A inhibitors or other drugs known to prolong the QT interval increases the risk of Torsades de Pointes and fatal arrhythmias."}]', 'Use with caution in patients with a history of QT prolongation, family history of long QT syndrome, or those taking other QT-prolonging drugs. Correct hypokalemia and hypomagnesemia prior to initiation. Use with caution in patients with mild to moderate renal impairment (CrCl 30-80 mL/min) as blood pressure may increase and renal function may decline. Monitor renal function periodically. Use with caution in the elderly due to age-related decreases in renal function. Not indicated for the acute treatment of an angina attack.', '- **Chronic Angina:** Treatment of chronic angina pectoris. May be used as monotherapy or in combination with beta-blockers, calcium channel blockers, nitrates, anti-platelet therapy, lipid-lowering therapy, ACE inhibitors, and angiotensin receptor blockers. Reserved for patients who have not achieved an adequate response with other antianginal drugs due to its QT-prolonging effects.', '- **Strong CYP3A Inhibitors:** Contraindicated with ketoconazole, itraconazole, clarithromycin, nefazodone, nelfinavir, ritonavir, indinavir, and saquinavir. Rationale: Significantly increases ranolazine plasma concentrations, leading to severe QT prolongation.
INSERT INTO "drug_generic" VALUES(349, 'Lidocaine (Lignocaine) Hydrochloride', 'Lidocaine Hydrochloride', 'N01BB02', 0, 1, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Systemic Toxicity Risk", "severity": "High", "trigger_condition": "Intravenous administration or high-dose regional anesthesia", "message": "STOP: High alert medication. Inadvertent intravascular injection or excessive dosing can cause life-threatening Local Anesthetic Systemic Toxicity (LAST), characterized by seizures, respiratory arrest, and cardiovascular collapse. Resuscitative equipment and lipid emulsion must be immediately available."}]', '- **Hepatic Impairment:** Use with extreme caution; lidocaine is extensively metabolized by the liver. Severe hepatic disease significantly decreases clearance, increasing the risk of toxicity.
INSERT INTO "drug_generic" VALUES(350, 'Econazole Nitrate 1% topical', 'Econazole', 'D01AC03', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Local Irritation:** Discontinue use if sensitization, severe irritation, or chemical burns occur at the site of application.
INSERT INTO "drug_generic" VALUES(351, 'Salsalate', 'Salsalate', 'N02BA06', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Reye''s Syndrome Risk", "severity": "High", "trigger_condition": "Use in children or teenagers with viral infections", "message": "STOP: Salsalate is a salicylate. Do not use in children or teenagers with chickenpox or flu symptoms due to the risk of Reye''s syndrome, a rare but potentially fatal condition."}]', 'Use with caution in patients with a history of peptic ulcers, asthma, or allergic disorders. Caution is advised in patients with impaired hepatic or renal function, dehydration, or uncontrolled hypertension. May cause acute haemolytic anaemia in patients with G6PD deficiency. Monitor for signs of gastrointestinal bleeding.', '- **Rheumatoid Arthritis:** Relief of signs and symptoms.
INSERT INTO "drug_generic" VALUES(352, 'Difluprednate Eye prep', 'Difluprednate Ophthalmic', 'S01BA07', 0, 0, 0, 1, 0, 1, 1, 1, '[{"alert_type": "Ocular Toxicity", "severity": "High", "trigger_condition": "Prolonged use (>10 days)", "message": "STOP: Prolonged use of ophthalmic corticosteroids may result in glaucoma, optic nerve damage, visual acuity defects, and posterior subcapsular cataract formation. Intraocular pressure (IOP) must be monitored if used for 10 days or longer."}]', '**Intraocular Pressure (IOP) Increase:** Prolonged use may result in elevated IOP, leading to glaucoma and optic nerve damage. Monitor IOP routinely if used for ≥10 days.
INSERT INTO "drug_generic" VALUES(353, 'Rizatriptan', 'Rizatriptan', 'N02CC04', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Cardiovascular Ischemia", "severity": "High", "trigger_condition": "Patients with ischemic heart disease or uncontrolled hypertension", "message": "STOP: Rizatriptan can cause serious cardiovascular events, including myocardial infarction and coronary vasospasm. Contraindicated in patients with ischemic heart disease, history of MI, or uncontrolled hypertension."}]', '**Myocardial Ischemia and Infarction:** May cause coronary artery vasospasm. Evaluate patients with cardiovascular risk factors (e.g., hypertension, hypercholesterolemia, smoking, obesity, diabetes) prior to initiating therapy.
INSERT INTO "drug_generic" VALUES(354, 'Metronidazole + Diloxanide Furoate', 'Metronidazole and Diloxanide Furoate', 'P01AB51', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Disulfiram-Like Reaction", "severity": "High", "trigger_condition": "Consumption of alcohol during or within 3 days of therapy", "message": "STOP: Severe disulfiram-like reactions (abdominal cramps, nausea, vomiting, headaches, and flushing) can occur if alcohol is consumed. Strictly avoid alcohol during therapy and for at least 3 days after the last dose."}]', '**Neurological Toxicity:** Metronidazole can cause severe neurological disturbances, including seizures, encephalopathy, and peripheral neuropathy. Discontinue immediately if abnormal neurologic signs develop.
INSERT INTO "drug_generic" VALUES(355, 'Ertugliflozin + Sitagliptin', 'Ertugliflozin and Sitagliptin', 'A10BD24', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Pancreatitis and Diabetic Ketoacidosis", "severity": "High", "trigger_condition": "Severe abdominal pain or symptoms of metabolic acidosis", "message": "STOP: Acute pancreatitis (including fatal hemorrhagic/necrotizing forms) has been reported with sitagliptin. Discontinue immediately if suspected. Fatal cases of diabetic ketoacidosis (DKA) have occurred with ertugliflozin, sometimes with normal blood glucose. Discontinue if DKA is suspected."}]', 'Acute pancreatitis has been reported in patients taking sitagliptin; monitor for persistent severe abdominal pain (sometimes radiating to the back) and discontinue promptly if suspected. Necrotizing fasciitis of the perineum (Fournier gangrene) is a rare but life-threatening complication associated with SGLT2 inhibitors; discontinue and initiate broad-spectrum antibiotics and surgical debridement if suspected. Ertugliflozin causes intravascular volume contraction; symptomatic hypotension may occur, particularly in patients with renal impairment, the elderly, or those on diuretics. Ketoacidosis requires urgent hospitalization; consider predisposing factors (pancreatic insulin deficiency, caloric restriction, alcohol abuse) before initiating and temporarily discontinue during prolonged fasting or surgery. Serious urinary tract infections (urosepsis, pyelonephritis) and genital mycotic infections may occur. Sitagliptin has been associated with severe and disabling arthralgia and bullous pemphigoid; discontinue if these occur. Heart failure has been observed with DPP-4 inhibitors; consider risks before initiating in patients with a history of heart failure.', '- Adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus when treatment with both ertugliflozin and sitagliptin is appropriate.', '- **Hypersensitivity:** Contraindicated in patients with a history of serious hypersensitivity reaction to ertugliflozin or sitagliptin (e.g., anaphylaxis, angioedema, Stevens-Johnson syndrome).
INSERT INTO "drug_generic" VALUES(356, 'Gatifloxacin Eye prep', 'Gatifloxacin Ophthalmic', 'S01AE06', 1, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hypersensitivity", "severity": "High", "trigger_condition": "History of allergy to fluoroquinolones", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, have occurred with systemic quinolones. Discontinue immediately at the first sign of a skin rash or allergic reaction."}]', 'Prolonged use may result in the overgrowth of nonsusceptible organisms, including fungi. If superinfection occurs, discontinue use and institute alternative therapy.
INSERT INTO "drug_generic" VALUES(357, 'Valbenazine', 'Valbenazine', 'N07XX13', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Somnolence and CNS Depression", "severity": "Moderate", "trigger_condition": "Initiation of therapy", "message": "Can cause significant somnolence. Warn patients not to perform activities requiring mental alertness (e.g., driving or operating hazardous machinery) until they know how the drug affects them."}]', '**Somnolence:** Can cause significant sedation and somnolence. Caution patients against driving or operating hazardous machinery.
INSERT INTO "drug_generic" VALUES(358, 'Ofloxacin + Clotrimazole + Beclomethasone + Lidocaine ear prep', 'Ofloxacin, Clotrimazole, Beclomethasone, and Lidocaine Otic', 'S02CA', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Ophthalmic Contraindication", "severity": "High", "trigger_condition": "Accidental eye administration", "message": "STOP: For otic use only. Do NOT administer into the eyes. Severe ocular irritation and damage may occur."}]', '**Superinfection:** Prolonged use may result in the overgrowth of non-susceptible organisms, including fungi. If otorrhea persists after a full course, evaluate for underlying conditions (e.g., cholesteatoma, foreign body).
INSERT INTO "drug_generic" VALUES(359, 'Glucose (Dextrose) Anhydrous + Potassium Chloride + Tri-sodium citrate +  Sodium chloride (ORS)', 'Oral Rehydration Salts (ORS)', 'A07CA', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Severe Dehydration", "severity": "High", "trigger_condition": "Patients presenting with severe dehydration, shock, or inability to drink", "message": "STOP: Oral rehydration is insufficient for severe dehydration or shock. Immediate intravenous fluid resuscitation is required."}]', '**Renal Impairment:** Use with caution in patients with depressed renal function, as they are at higher risk for electrolyte imbalances (e.g., hyperkalemia, hypernatremia).
INSERT INTO "drug_generic" VALUES(360, 'Repaglinide', 'Repaglinide', 'A10BX02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Hypoglycemia Risk", "severity": "High", "trigger_condition": "Concomitant use with Gemfibrozil", "message": "STOP: Co-administration of Repaglinide and Gemfibrozil is strictly contraindicated. Gemfibrozil significantly inhibits the metabolism of Repaglinide, leading to profoundly elevated plasma concentrations and severe, prolonged hypoglycemia."}]', 'Use with caution in the elderly, malnourished, or debilitated patients, as they are more susceptible to hypoglycemia. Exercise caution in patients with hepatic or severe renal impairment; longer intervals between dose adjustments may be required. Hypoglycemia risk increases during periods of stress, such as infection, fever, trauma, or surgery; temporary transition to insulin may be necessary. Monitor blood glucose and HbA1c regularly. Skip the dose if a meal is skipped to prevent hypoglycemia.', '- **Type 2 Diabetes Mellitus:** Indicated as an adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus. Can be used as monotherapy or in combination with metformin or other oral antidiabetic agents (excluding sulfonylureas) when diet, exercise, and monotherapy do not result in adequate glycemic control.', '- **Concomitant Gemfibrozil Use:** Contraindicated due to severe inhibition of CYP2C8, leading to a massive increase in repaglinide exposure and severe hypoglycemia.
INSERT INTO "drug_generic" VALUES(361, 'Chlorothiazide', 'Chlorothiazide', 'C03AA04', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Electrolyte Depletion", "severity": "High", "trigger_condition": "Prolonged use or high doses", "message": "STOP: Thiazide diuretics can cause severe hypokalemia, hyponatremia, and hypochloremic alkalosis. Monitor serum electrolytes regularly."}]', '**Electrolyte Imbalance:** May cause hypokalemia, hyponatremia, hypochloremic alkalosis, and hypomagnesemia. Monitor electrolytes regularly.
INSERT INTO "drug_generic" VALUES(362, 'Elacestrant', 'Elacestrant', 'L02BA04', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Patient Selection", "severity": "High", "trigger_condition": "Prior to initiation", "message": "Select patients for treatment based on the presence of ESR1 mutation(s) in plasma or tumor specimens using an FDA-approved test."}]', '**Dyslipidemia:** Hypercholesterolemia and hypertriglyceridemia are common. Monitor lipid profiles periodically during treatment and manage according to clinical guidelines.
INSERT INTO "drug_generic" VALUES(363, 'Suvorexant', 'Suvorexant', 'N05AL03', 0, 1, 0, 0, 0, 0, 0, 1, '[{"alert_type": "CNS Depression and Daytime Impairment", "severity": "High", "trigger_condition": "Administration of dose >20 mg or co-administration with other CNS depressants", "message": "STOP: Can cause severe next-day impairment, including impaired driving skills. Risk increases with higher doses or if taken with less than a full night of sleep (at least 7 hours) remaining."}]', 'Monitor for signs of worsening depression, suicidal ideation, or any new-onset behavioral changes; immediately evaluate patients presenting with these symptoms.
INSERT INTO "drug_generic" VALUES(364, 'Risperidone', 'Risperidone', 'N05AX08', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Increased Mortality in Elderly Patients with Dementia-Related Psychosis", "severity": "High", "trigger_condition": "Prescribing to elderly patients with dementia", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Risperidone is not approved for the treatment of patients with dementia-related psychosis."}]', '**Neuroleptic Malignant Syndrome (NMS):** A potentially fatal symptom complex (hyperpyrexia, muscle rigidity, altered mental status, autonomic instability) has been reported. Discontinue immediately if NMS is suspected.
INSERT INTO "drug_generic" VALUES(365, 'Salbutamol + Budesonide', 'Albuterol and Budesonide', 'R03AK14', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediate worsening of wheezing or shortness of breath after inhalation", "message": "STOP: Inhaled medications can produce paradoxical bronchospasm, which may be life-threatening. If this occurs, discontinue immediately and treat with an alternative short-acting bronchodilator."}]', '**Deterioration of Asthma:** Asthma may deteriorate acutely over hours or chronically over days. If symptoms continue after using the inhaler or if the patient requires more doses than usual, re-evaluate the patient and their treatment regimen immediately.
INSERT INTO "drug_generic" VALUES(366, 'Vitamin C   +  Vitamin E  +  Zinc  +  Copper  + Lutein (Antioxidant and Anti Cataract Preparations)', 'Ascorbic Acid, Vitamin E, Zinc, Copper, and Lutein', 'S01XA', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Bleeding Risk", "severity": "Low", "message": "High doses of Vitamin E can potentiate the effects of anticoagulants. Caution should be taken during the concomitant use of warfarin or other blood thinners."}]', '**Anticoagulant Therapy:** High doses of Vitamin E may antagonize Vitamin K and increase the risk of bleeding. Monitor INR closely in patients taking warfarin.
INSERT INTO "drug_generic" VALUES(367, 'Sodium Dichloroisocyanurate', 'Troclosene Sodium', 'V07AV', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Toxicity via Direct Ingestion", "severity": "High", "trigger_condition": "Direct swallowing of the un-dissolved tablet", "message": "STOP: Tablets are harmful or fatal if swallowed directly. They must be dissolved in the specified volume of water before consumption or use."}]', '- Keep out of reach of children to prevent accidental direct ingestion.
INSERT INTO "drug_generic" VALUES(368, 'Dexlansoprazole', 'Dexlansoprazole', 'A02BC06', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Clostridioides difficile-Associated Diarrhea", "severity": "Medium", "trigger_condition": "Development of severe, persistent diarrhea during or after therapy", "message": "Proton Pump Inhibitor (PPI) therapy may be associated with an increased risk of Clostridioides difficile-associated diarrhea (CDAD). Evaluate patients who develop persistent diarrhea."}]', '**Gastric Malignancy:** Symptomatic response to dexlansoprazole does not preclude the presence of gastric malignancy. Consider additional follow-up and diagnostic testing in adult patients with suboptimal response or early symptomatic relapse.
INSERT INTO "drug_generic" VALUES(369, 'Lenograstim', 'Lenograstim', 'L03AA04', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Splenic Rupture", "severity": "High", "trigger_condition": "During therapy", "message": "STOP: Fatal splenic rupture has been reported. Evaluate patients who report left upper abdominal or shoulder tip pain for an enlarged spleen or splenic rupture."}, {"alert_type": "Acute Respiratory Distress Syndrome (ARDS)", "severity": "High", "trigger_condition": "During therapy", "message": "STOP: ARDS has been reported. Evaluate patients who develop fever, lung infiltrates, or respiratory distress. Discontinue lenograstim in patients with ARDS."}]', '**Leukocytosis:** Excessive increases in white blood cell (WBC) counts can occur. Monitor CBC twice weekly during therapy. Discontinue or reduce the dose if the absolute neutrophil count (ANC) exceeds target levels.
INSERT INTO "drug_generic" VALUES(370, 'Chlorhexidine Tulle gras Dressing 0.5% w/w', 'Chlorhexidine Acetate Dressing', 'D08AC02', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "Medium", "trigger_condition": "Patient history of chlorhexidine allergy", "message": "STOP: Rare but severe allergic reactions, including anaphylaxis, have been reported with topical chlorhexidine products. Verify allergy history before application."}]', '**Sensitive Areas:** Avoid contact with the eyes, middle ear, meninges, and brain tissue. Chlorhexidine can cause severe and permanent injury (e.g., deafness, corneal damage) if it contacts these areas.
INSERT INTO "drug_generic" VALUES(371, 'Rilpivirine', 'Rilpivirine', 'J05AG05', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Drug Interactions and Virologic Failure", "severity": "High", "trigger_condition": "Coadministration with PPIs or strong CYP3A inducers", "message": "STOP: Coadministration with proton pump inhibitors (PPIs) or strong CYP3A inducers (e.g., dexamethasone, carbamazepine, rifampin) is contraindicated as it significantly decreases rilpivirine levels, leading to virologic failure and resistance."}]', '**Depressive Disorders:** Severe depressive disorders (depressed mood, depression, dysphoria, major depression, altered mood, negative thoughts, suicide attempt, suicidal ideation) have been reported. Promptly evaluate patients with severe depressive symptoms to assess whether the symptoms are related to rilpivirine and if the risks of continuing therapy outweigh the benefits.
INSERT INTO "drug_generic" VALUES(372, 'Dyclonine + Menthol oral prep', 'Dyclonine + Menthol', 'R02AD04', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Choking Hazard", "severity": "High", "trigger_condition": "Administration to young children", "message": "STOP: Lozenges are considered a severe choking hazard in young children. Do not use in children under 2 years of age."}]', 'Lozenges are considered a choking hazard in young children. Advise patients to discontinue use and seek medical advice if a sore throat is severe, lasts for >2 days, or occurs with (or is followed by) fever, headache, rash, nausea, or vomiting. Advise patients to discontinue use and seek medical advice if sore mouth symptoms last more than 7 days, or if irritation, pain, or redness continues or worsens.', '- **Pharyngitis and Cough:** Indicated for the temporary relief of occasional mouth and throat symptoms, including minor irritation, pain, sore mouth, and sore throat. Also relieves cough associated with a cold or inhaled irritant.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to dyclonine, menthol, or any component of the formulation.', '- Local irritation
INSERT INTO "drug_generic" VALUES(373, 'Bromocriptine', 'Bromocriptine', 'N04BC01', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Cardiovascular and Neurological Toxicity", "severity": "High", "trigger_condition": "Postpartum use or uncontrolled hypertension", "message": "STOP: Severe and potentially fatal postpartum hypertension, seizures, strokes, and acute myocardial infarction have been reported. Contraindicated in uncontrolled hypertension and postpartum patients with a history of CAD."}]', '**Cardiovascular Disease:** Monitor blood pressure closely, especially during the first few days of therapy and following dosage increases. Symptomatic hypotension can occur.
INSERT INTO "drug_generic" VALUES(374, 'Iodixanol', 'Iodixanol', 'V08AB09', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Contrast-Induced Nephropathy & Hypersensitivity", "severity": "High", "trigger_condition": "Intravascular administration", "message": "STOP: Risk of severe, life-threatening anaphylactoid reactions and contrast-induced acute kidney injury. Ensure adequate hydration before and after administration. Resuscitation equipment must be immediately available."}]', '- Maintain adequate hydration before and after administration to minimize the risk of contrast-induced nephropathy.
INSERT INTO "drug_generic" VALUES(375, 'Epirubicin Hydrochloride', 'Epirubicin Hydrochloride', 'L01DB03', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Cardiotoxicity and Tissue Necrosis", "severity": "High", "trigger_condition": "Cumulative dosing or extravasation during IV administration", "message": "STOP: Epirubicin can cause severe, irreversible myocardial toxicity leading to congestive heart failure. Extravasation during IV administration causes severe local tissue necrosis. Administer only under the supervision of a physician experienced in cancer chemotherapy."}]', '**Cardiotoxicity:** Risk of irreversible congestive heart failure increases with cumulative doses. Assess left ventricular ejection fraction (LVEF) before, during, and after therapy. Use with extreme caution in patients with pre-existing cardiac disease or previous anthracycline exposure.
INSERT INTO "drug_generic" VALUES(376, 'Mometasone + Formoterol inhaler', 'Mometasone and Formoterol', 'R03AK09', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Asthma-Related Death Risk", "severity": "High", "trigger_condition": "Use as a rescue inhaler or monotherapy without ICS", "message": "STOP: Long-acting beta2-adrenergic agonists (LABA) increase the risk of asthma-related death. Do NOT use for acute bronchospasm or status asthmaticus."}]', '**Asthma-Related Death:** LABAs increase the risk of asthma-related death. This combination should only be used for patients not adequately controlled on a long-term asthma control medication.
INSERT INTO "drug_generic" VALUES(377, 'Beclomethasone Dipropionate Nasal prep', 'Beclomethasone Nasal', 'R01AD01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Nasal Septal Perforation", "severity": "Medium", "trigger_condition": "Improper administration technique or prolonged use", "message": "STOP: Nasal septal perforation and mucosal ulceration can occur. Instruct patients to direct the spray away from the nasal septum. Avoid use in patients with recent nasal trauma or surgery until healed."}]', '**Impaired Wound Healing:** Because of the inhibitory effect of corticosteroids on wound healing, patients who have experienced recent nasal septal ulcers, nasal surgery, or nasal trauma should not use a nasal corticosteroid until healing has occurred.
INSERT INTO "drug_generic" VALUES(378, 'Dinutuximab', 'Dinutuximab', 'L01FX06', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Severe Infusion Reactions and Neuropathy", "severity": "High", "trigger_condition": "During or shortly after intravenous infusion", "message": "STOP: Dinutuximab can cause severe, life-threatening infusion reactions and severe neuropathic pain. Premedicate with antihistamines, antipyretics, and analgesics (including IV opioids) prior to each infusion."}]', '**Neurological Disorders of the Eye:** Interrupt dinutuximab for dilated pupil with sluggish light reflex or other visual disturbances. Permanently discontinue for recurrent eye disorders or loss of vision.
INSERT INTO "drug_generic" VALUES(379, 'Ixazomib', 'Ixazomib', 'L01XG03', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Thrombocytopenia", "severity": "High", "trigger_condition": "Platelet nadir typically between days 14 and 21 of a 28-day cycle", "message": "Severe thrombocytopenia can occur. Monitor platelet counts at least monthly, and more frequently during the first 3 cycles. Adjust dose as necessary."}]', '**Thrombocytopenia:** Thrombocytopenia has been reported, with platelet nadirs typically occurring between days 14 and 21 of each 28-day cycle and recovery to baseline by the start of the next cycle. Monitor platelet counts at least monthly during treatment; consider more frequent monitoring during the first 3 cycles. Manage with dose modifications and platelet transfusions as clinically indicated.
INSERT INTO "drug_generic" VALUES(380, 'Iodine (Potassium Iodide)', 'Potassium Iodide', 'H03CA01', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Thyroid Dysfunction", "severity": "High", "trigger_condition": "Prolonged use or use in neonates", "message": "Repeated administration is not recommended in neonates due to the high risk of severe, irreversible hypothyroidism. Monitor thyroid function closely."}]', '- Monitor serum potassium levels, especially in patients with renal impairment or those taking potassium-sparing medications, to prevent hyperkalemia.
INSERT INTO "drug_generic" VALUES(381, 'Ramosetron hydrochloride', 'Ramosetron', 'A03AE06', 0, 0, 0, 0, 1, 0, 0, 0, '[]', '**Constipation Risk:** Use with extreme caution in patients with a history of constipation or bowel obstruction. Ramosetron can cause severe constipation and ischemic colitis. Discontinue immediately if severe constipation occurs.
INSERT INTO "drug_generic" VALUES(382, 'Eprosartan', 'Eprosartan', 'C09CA02', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue eprosartan as soon as pregnancy is detected."}]', '**Hypotension:** Symptomatic hypotension may occur in patients who are volume- or salt-depleted (e.g., those treated with high-dose diuretics). Correct volume depletion prior to administration.
INSERT INTO "drug_generic" VALUES(383, 'Eucalypytol 0.092% + Menthol 0.042% + Methyl Salicylate 0.06% + Thymol 0.064%', 'Eucalyptol, Menthol, Methyl Salicylate, and Thymol', 'A01AD11', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Ingestion Warning", "severity": "Moderate", "trigger_condition": "Accidental swallowing", "message": "STOP: This product is a topical oral rinse and must not be swallowed. Ingestion of large amounts, especially by children, can cause systemic toxicity including salicylate poisoning."}]', '**Age Restriction:** Not indicated for use in children below 12 years of age due to the risk of accidental swallowing.
INSERT INTO "drug_generic" VALUES(384, 'Ursodeoxycholic Acid', 'Ursodiol', 'A05AA02', 0, 0, 1, 1, 0, 0, 1, 0, '[]', '**Monitoring:** Liver function tests (AST, ALT, GGT) and bilirubin levels should be monitored every month for the first three months of therapy, and every 6 months thereafter.
INSERT INTO "drug_generic" VALUES(385, 'Dapagliflozin propanediol', 'Dapagliflozin', 'A10BK01', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Diabetic Ketoacidosis (DKA)", "severity": "High", "trigger_condition": "Presence of nausea, vomiting, abdominal pain, malaise, or shortness of breath", "message": "STOP: Assess for ketoacidosis regardless of blood glucose levels. If suspected, discontinue dapagliflozin immediately, evaluate, and treat promptly."}, {"alert_type": "Fournier''s Gangrene", "severity": "High", "trigger_condition": "Pain, tenderness, erythema, or swelling in the genital or perineal area", "message": "STOP: Serious, life-threatening necrotizing fasciitis of the perineum has occurred. Institute prompt surgical and antibiotic treatment if suspected."}]', '**Volume Depletion:** Can cause intravascular volume contraction. Assess volume status and renal function before initiating, especially in the elderly, patients with renal impairment, low systolic blood pressure, or those on diuretics.
INSERT INTO "drug_generic" VALUES(386, 'Etravirine', 'Etravirine', 'J05AG04', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Severe Skin and Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Development of severe rash or rash accompanied by systemic symptoms", "message": "STOP: Severe, potentially life-threatening, and fatal skin reactions (e.g., Stevens-Johnson Syndrome, Toxic Epidermal Necrolysis, DRESS) have been reported. Immediately discontinue etravirine if severe rash or hypersensitivity reactions occur."}]', '**Severe Skin Reactions:** Severe, potentially life-threatening, and fatal skin reactions have been reported. These include cases of Stevens-Johnson syndrome (SJS), toxic epidermal necrolysis (TEN), and erythema multiforme. Discontinue therapy immediately if signs or symptoms of severe skin reactions develop.
INSERT INTO "drug_generic" VALUES(387, 'Benzalkonium Chloride 0.5% topical', 'Benzalkonium Chloride', 'D08AJ01', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **External Use Only:** Do not ingest. Avoid contact with eyes, middle ear, and mucous membranes.
INSERT INTO "drug_generic" VALUES(388, 'Verteporfin', 'Verteporfin', 'S01LA01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Photosensitivity", "severity": "High", "trigger_condition": "Post-infusion exposure to direct sunlight or bright indoor light", "message": "STOP: Patients must avoid exposure of unprotected skin, eyes, or other body organs to direct sunlight or bright indoor light for 5 days post-treatment to prevent severe sunburn-like reactions."}]', '- **Photosensitivity:** Following infusion, the patient becomes highly photosensitive. Protect all parts of the skin and eyes with protective clothing and dark sunglasses for 5 days. Sunscreens are ineffective. Exposure to ambient indoor light is encouraged to help inactivate the drug.
INSERT INTO "drug_generic" VALUES(389, 'Mebeverine Hydrochloride', 'Mebeverine', 'A03AA04', 0, 0, 0, 0, 1, 0, 0, 0, '[]', '**Porphyria:** Caution should be exercised in patients with a history of porphyria, as mebeverine may theoretically exacerbate the condition.
INSERT INTO "drug_generic" VALUES(390, 'Bupropion Hydrochloride', 'Bupropion', 'N06AX12', 0, 1, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Suicidality and Seizure Risk", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "STOP: Antidepressants increase the risk of suicidal thoughts and behaviors in children, adolescents, and young adults. Bupropion also carries a dose-dependent risk of seizures. Do not exceed maximum recommended doses."}]', '**Suicidal Thoughts and Behaviors:** Increased risk of suicidal thinking and behavior in children, adolescents, and young adults taking antidepressants. Monitor closely for clinical worsening and emergence of suicidal thoughts. Advise families to observe the patient closely.
INSERT INTO "drug_generic" VALUES(391, 'Calcium Chloride + Potassium Chloride + Sodium Chloride + Sodium Lactate (Lactated Ringers solution)', 'Lactated Ringer''s Solution', 'B05BB01', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Drug Interaction", "severity": "High", "trigger_condition": "Concurrent administration with Ceftriaxone", "message": "STOP: Co-administration of Lactated Ringer''s with intravenous Ceftriaxone is contraindicated in neonates (\u226428 days) due to fatal calcium-ceftriaxone precipitation. In older patients, do not administer simultaneously through the same IV line."}]', '**Fluid Overload:** Should not be administered rapidly or for prolonged periods without monitoring. Risk of hypervolemia, pulmonary congestion, and heart failure, especially in elderly patients or those with cardiovascular disease.
INSERT INTO "drug_generic" VALUES(392, 'Ferrous Sulphate + Folic Acid', 'Ferrous Sulfate and Folic Acid', 'B03AD03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Iron Toxicity Risk", "severity": "High", "trigger_condition": "Accidental overdose in pediatric patients", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep out of reach of children."}]', 'Care should be taken in patients who may develop iron overload, such as those with hemochromatosis, hemolytic anemia, or red cell aplasia.
INSERT INTO "drug_generic" VALUES(393, 'Melatonin', 'Melatonin', 'N05CH01', 0, 0, 0, 0, 0, 0, 1, 0, '[]', 'Use with caution in patients with a history of seizure disorders, as it may lower the seizure threshold or increase seizure activity. Exercise caution in patients with autoimmune diseases, as immunostimulatory effects have been theorized. May cause drowsiness and impair the ability to drive or operate heavy machinery; patients should avoid these activities for several hours after administration. Use with caution in patients with hepatic impairment due to decreased clearance. May exacerbate symptoms in individuals with underlying clinical depression.', '- **Insomnia:** Short-term management of primary insomnia, particularly in patients with delayed sleep phase syndrome or disrupted circadian rhythms (e.g., shift work, visual impairment).
INSERT INTO "drug_generic" VALUES(394, 'Ticagrelor', 'Ticagrelor', 'B01AC24', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Bleeding Risk", "severity": "High", "trigger_condition": "Active bleeding, history of intracranial hemorrhage, or planned surgery", "message": "Ticagrelor can cause significant, sometimes fatal, bleeding. Do not use in patients with active pathological bleeding or a history of intracranial hemorrhage. Discontinue 5 days prior to elective surgery."}, {"alert_type": "Aspirin Interaction", "severity": "High", "trigger_condition": "Concomitant use of maintenance aspirin doses >100 mg/day", "message": "Maintenance doses of aspirin above 100 mg daily reduce the effectiveness of ticagrelor and should be avoided."}]', 'Use with extreme caution in patients at an increased risk of bleeding (e.g., recent trauma, recent surgery, active peptic ulcer disease). Ticagrelor can cause dyspnea, which is usually mild to moderate and self-limiting; evaluate to rule out underlying cardiopulmonary conditions if severe. Use caution in patients at risk for bradycardic events (e.g., sick sinus syndrome, 2nd or 3rd-degree AV block without a pacemaker), as ventricular pauses have been reported. Monitor for hyperuricemia, as ticagrelor can increase serum uric acid levels and precipitate gout. Premature discontinuation increases the risk of myocardial infarction, stent thrombosis, and death.', '- Prevention of atherothrombotic events (cardiovascular death, myocardial infarction, and stroke) in adult patients with acute coronary syndromes (ACS) (unstable angina, NSTEMI, or STEMI).
INSERT INTO "drug_generic" VALUES(395, 'Lornoxicam', 'Lornoxicam', 'M01AC05', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risks", "severity": "High", "trigger_condition": "Prolonged use, history of cardiovascular disease, or history of peptic ulcer disease", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation."}]', '**Cardiovascular Thrombotic Events:** May increase the risk of serious cardiovascular thrombotic events, MI, and stroke. Use the lowest effective dose for the shortest duration possible.
INSERT INTO "drug_generic" VALUES(396, 'Drospirenone + Estetrol', 'Drospirenone and Estetrol', 'G03AA18', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "Patients with a history of or high risk for VTE/ATE, or women over 35 who smoke", "message": "STOP: Combined oral contraceptives increase the risk of venous and arterial thromboembolic events. Discontinue immediately if a thrombotic event occurs."}]', '**Thromboembolic Disorders:** Increased risk of deep vein thrombosis, pulmonary embolism, myocardial infarction, and stroke. Stop use if an event occurs. Start no earlier than 4 weeks postpartum.
INSERT INTO "drug_generic" VALUES(397, 'Tetracycline Hydrochloride 1% Eye prep', 'Tetracycline Ophthalmic', 'S01AA09', 1, 0, 1, 1, 0, 1, 1, 0, '[]', 'Prolonged use may result in the overgrowth of nonsusceptible organisms, including fungi. If superinfection occurs, discontinue use and institute appropriate therapy. Avoid exposure to excessive sunlight during treatment. Periodic evaluation of renal, hepatic, and hematopoietic systems is recommended during prolonged therapy, although systemic absorption from ophthalmic use is minimal.', '- **Bacterial Conjunctivitis:** Indicated for the treatment of superficial ocular infections caused by susceptible strains of microorganisms.
INSERT INTO "drug_generic" VALUES(398, 'Sodium polystyrene sulfonate', 'Sodium polystyrene sulfonate', 'V03AE01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Intestinal Necrosis", "severity": "High", "trigger_condition": "Concomitant use with sorbitol or in patients with reduced gut motility", "message": "STOP: Cases of intestinal necrosis, which may be fatal, and other serious gastrointestinal adverse events have been reported. Avoid concomitant use with sorbitol. Do not use in patients with obstructive bowel disease or reduced gut motility."}]', '- **Intestinal Necrosis:** Cases of intestinal necrosis, some fatal, have been reported. Risk factors include prematurity, history of intestinal disease or surgery, hypovolemia, and concomitant use of sorbitol. Avoid use with sorbitol.
INSERT INTO "drug_generic" VALUES(399, 'Piperazine Citrate', 'Piperazine Citrate', 'P02CB01', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Neurotoxicity", "severity": "High", "trigger_condition": "Renal impairment or overdose", "message": "STOP: Piperazine can cause severe neurotoxicity (e.g., ataxia, myoclonic contractions, seizures), particularly in patients with renal impairment where the drug accumulates. Contraindicated in severe renal impairment and epilepsy."}]', 'Use with extreme caution in patients with mild to moderate renal impairment, hepatic impairment, or pre-existing neurological conditions. Monitor for signs of neurotoxicity (e.g., ataxia, confusion, muscle incoordination known as ''worm wobble''); discontinue treatment immediately if these occur. Prolonged or repeated courses should be avoided due to the risk of cumulative toxicity. Ensure strict hygiene measures are followed to prevent reinfection, especially in cases of enterobiasis.', '- **Ascariasis:** Treatment of roundworm (*Ascaris lumbricoides*) infections.
INSERT INTO "drug_generic" VALUES(400, 'Zoledronic Acid 4mg', 'Zoledronic Acid', 'M05BA08', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Hypocalcemia", "severity": "High", "trigger_condition": "Pre-existing hypocalcemia or inadequate calcium/vitamin D supplementation", "message": "STOP: Severe and occasionally fatal hypocalcemia has been reported. Pre-existing hypocalcemia must be corrected prior to initiation. Ensure adequate calcium and vitamin D supplementation."}, {"alert_type": "Renal Toxicity", "severity": "High", "trigger_condition": "Rapid infusion or pre-existing renal impairment", "message": "STOP: Zoledronic acid can cause acute renal failure. Do not infuse over less than 15 minutes. Monitor serum creatinine prior to each dose. Contraindicated in severe renal impairment (CrCl <35 mL/min)."}]', '**Osteonecrosis of the Jaw (ONJ):** Can occur spontaneously but is widely associated with tooth extraction and/or local infection with delayed healing. Perform a dental exam prior to therapy. Avoid invasive dental procedures during treatment.
INSERT INTO "drug_generic" VALUES(401, 'Diphenhydramine Hydrochloride', 'Diphenhydramine Hydrochloride', 'R06AA02', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "CNS Depression and Anticholinergic Toxicity", "severity": "High", "trigger_condition": "Concomitant use with alcohol, sedatives, or in elderly patients", "message": "STOP: Significant risk of profound CNS depression and severe anticholinergic effects (delirium, urinary retention). Use with extreme caution in the elderly and avoid concurrent CNS depressants."}]', '- **CNS Depression:** May cause significant drowsiness and impair physical or mental abilities. Patients should avoid performing tasks requiring mental alertness, such as driving or operating heavy machinery.
INSERT INTO "drug_generic" VALUES(402, 'Desogestrel + Ethinyl estradiol', 'Desogestrel and Ethinyl Estradiol', 'G03AA09', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk and Smoking", "severity": "High", "trigger_condition": "Women over 35 years old who smoke", "message": "STOP: Cigarette smoking increases the risk of serious cardiovascular events (MI, stroke, VTE) from combination oral contraceptives. This risk increases with age (>35 years) and heavy smoking. Contraindicated in women >35 who smoke."}]', '**Thromboembolic Disorders:** Increased risk of venous thromboembolism (VTE), deep vein thrombosis (DVT), pulmonary embolism (PE), myocardial infarction, and stroke. Risk is highest in the first year of use. Discontinue 4 weeks before major surgery or prolonged immobilization.
INSERT INTO "drug_generic" VALUES(403, 'Guaiphenesin + Pseudoephedrine Hydrochloride + Triprolidine Hydrochloride', 'Guaifenesin / Pseudoephedrine / Triprolidine', 'R05CA10', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hypertensive Crisis", "severity": "High", "trigger_condition": "Concomitant use with Monoamine Oxidase Inhibitors (MAOIs)", "message": "STOP: Contraindicated in patients taking MAOIs or within 14 days of stopping MAOI therapy. Concurrent use can precipitate a severe, potentially fatal hypertensive crisis."}]', '**Cardiovascular and Endocrine Effects:** Pseudoephedrine is a sympathomimetic that can elevate blood pressure and heart rate. Use with extreme caution in patients with mild to moderate hypertension, ischemic heart disease, hyperthyroidism, or diabetes mellitus.
INSERT INTO "drug_generic" VALUES(404, 'Sacubitril + Valsartan', 'Sacubitril/Valsartan', 'C09DX04', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected during therapy", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately upon detection of pregnancy."}]', '**Fetal Toxicity:** Use of drugs acting on the renin-angiotensin system during the second and third trimesters reduces fetal renal function and increases fetal and neonatal morbidity and death.
INSERT INTO "drug_generic" VALUES(405, 'Abemaciclib', 'Abemaciclib', 'L01EF03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Venous Thromboembolism", "severity": "High", "trigger_condition": "Development of shortness of breath, chest pain, or leg swelling", "message": "WARNING: Venous thromboembolic events (VTE), including deep vein thrombosis and pulmonary embolism, have been reported. Monitor for signs and symptoms and treat appropriately."}, {"alert_type": "Interstitial Lung Disease (ILD) / Pneumonitis", "severity": "High", "trigger_condition": "New or worsening respiratory symptoms", "message": "STOP: Severe, life-threatening, or fatal ILD/pneumonitis can occur. Interrupt or permanently discontinue therapy based on severity."}]', '**Venous Thromboembolism (VTE):** VTE (e.g., deep vein thrombosis, pulmonary embolism, cerebral venous sinus thrombosis) has been reported in patients receiving abemaciclib. Monitor for signs and symptoms of venous thrombosis and pulmonary embolism and treat appropriately.
INSERT INTO "drug_generic" VALUES(406, 'Dextromethorphan + Menthol', 'Dextromethorphan and Menthol', 'R05DA20', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Serotonin Syndrome Risk", "severity": "High", "trigger_condition": "Concurrent use or use within 14 days of Monoamine Oxidase Inhibitors (MAOIs)", "message": "STOP: Concomitant use with MAOIs can precipitate severe and potentially fatal serotonin syndrome. Verify patient medication history before prescribing."}]', '**Age Restrictions:** Do not use in children under 6 years of age unless explicitly directed by a physician due to the risk of toxicity and lack of proven efficacy.
INSERT INTO "drug_generic" VALUES(407, 'Ruxolitinib', 'Ruxolitinib', 'L01EJ01', 0, 1, 0, 0, 1, 1, 1, 1, '[{"alert_type": "Serious Infections and Cytopenias", "severity": "High", "trigger_condition": "Patients presenting with fever, signs of infection, or severe bleeding/bruising", "message": "STOP: Treatment is associated with severe cytopenias (thrombocytopenia, anemia, neutropenia) and serious, sometimes fatal infections (including TB and viral reactivations). Monitor CBC closely and evaluate for active/latent infections prior to therapy."}]', '**Hematologic Toxicity:** Severe thrombocytopenia, anemia, and neutropenia can occur. Monitor CBC with differential prior to therapy, every 2-4 weeks until doses are stabilized, and then as clinically indicated. Interrupt or reduce dosing for severe cytopenias.
INSERT INTO "drug_generic" VALUES(408, 'Oteseconazole', 'Oteseconazole', 'G01AF20', 1, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Females of reproductive potential", "message": "STOP: Oteseconazole is strictly contraindicated in females of reproductive potential, pregnant women, and lactating women due to severe risks of fetal harm (ocular abnormalities). The drug has a very long half-life; exposure window is ~690 days."}]', '**Embryo-Fetal Toxicity:** Based on animal studies, oteseconazole can cause significant fetal harm, specifically ocular abnormalities (cataracts, opacities, optic nerve atrophy). Because the drug has an exceptionally long half-life (approximately 138 days), the drug exposure window is estimated to be 690 days (nearly 2 years). Therefore, it is strictly contraindicated in females of reproductive potential.
INSERT INTO "drug_generic" VALUES(409, 'Doxofylline', 'Doxofylline', 'R03DA11', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiac and Neurological Toxicity", "severity": "Moderate", "trigger_condition": "Overdosage or rapid intravenous administration", "message": "Toxicity can manifest as severe arrhythmias and seizures. Monitor clinical response closely, especially in the elderly or those with congestive heart failure."}]', 'Use with caution in patients with hypoxemia, hyperthyroidism, liver disease, renal disease, and a history of peptic ulcer disease. Elderly patients and those with Congestive Heart Failure (CHF) or cor pulmonale have significantly reduced clearance of xanthine derivatives, leading to prolonged serum half-lives and increased risk of toxicity; dose reduction and careful monitoring are required. Do not exceed recommended doses, as the therapeutic index of xanthines is narrow. Monitor for signs of toxicity, such as persistent nausea, vomiting, or tachycardia.', '- Maintenance treatment of Chronic Obstructive Pulmonary Disease (COPD).
INSERT INTO "drug_generic" VALUES(410, 'Afamelanotide', 'Afamelanotide', 'D02BB02', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Skin Pigmentation Changes", "severity": "Medium", "trigger_condition": "Initiation of therapy", "message": "Caution: May lead to generalized increased skin pigmentation and darkening of preexisting nevi and ephelides. A twice-yearly full-body skin examination is recommended to monitor for malignant changes."}]', '**Skin Pigmentary Changes:** Owing to its pharmacologic effect as a melanocortin receptor agonist, afamelanotide may lead to generalized increased skin pigmentation and the darkening of preexisting nevi and ephelides. A twice-yearly full-body skin examination is highly recommended to monitor preexisting and new skin pigmentary lesions for signs of melanoma or other dysplastic changes.
INSERT INTO "drug_generic" VALUES(411, 'Mucopolysaccharide Polysulphate + Salicylic Acid', 'Mucopolysaccharide Polysulfate + Salicylic Acid', 'M02AC', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Fire Hazard", "severity": "High", "trigger_condition": "Application of topical gel near open flames or smoking", "message": "STOP: Fabric (clothing, bedding, dressings) that has been in contact with this product burns more easily and is a serious fire hazard. Instruct patients not to smoke or go near naked flames."}]', '**Fire Hazard:** Fabrics in contact with this product burn more easily. Advise patients to avoid smoking or approaching naked flames due to the risk of severe burns. Washing clothing and bedding may reduce, but not completely remove, product build-up.
INSERT INTO "drug_generic" VALUES(412, 'Ropinirole', 'Ropinirole', 'N04BC04', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Sudden Onset of Sleep", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "STOP: Patients treated with ropinirole have reported falling asleep while engaged in activities of daily living, including driving, sometimes without warning signs. Advise patients to exercise extreme caution when driving or operating machinery."}]', '**Somnolence and Sleep Attacks:** May cause severe daytime sleepiness or sudden episodes of falling asleep. Discontinue if significant daytime sleepiness occurs.
INSERT INTO "drug_generic" VALUES(413, 'Nelfinavir', 'Nelfinavir', 'J05AE04', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Drug Interactions", "severity": "High", "trigger_condition": "Coadministration with CYP3A4 substrates", "message": "STOP: Nelfinavir is a potent CYP3A4 inhibitor. Coadministration with drugs highly dependent on CYP3A4 for clearance (e.g., amiodarone, pimozide, midazolam) can result in life-threatening toxicities."}]', '- **Hepatic Impairment:** Use with caution in patients with mild hepatic impairment. Not recommended in moderate to severe hepatic impairment.
INSERT INTO "drug_generic" VALUES(414, 'Olopatadine 0.2% Eye prep', 'Olopatadine Hydrochloride', 'S01GX09', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Contact Lens Use:** Not intended for the treatment of contact lens-related irritation. Patients should be advised not to wear a contact lens if their eye is red. The preservative in the solution, benzalkonium chloride, may be absorbed by soft contact lenses. Patients who wear soft contact lenses and whose eyes are not red should be instructed to wait at least 10 minutes after instilling the drops before inserting their contact lenses.
INSERT INTO "drug_generic" VALUES(415, 'Fludarabin Phosphate', 'Fludarabine Phosphate', 'L01BB05', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Neurotoxicity", "severity": "High", "trigger_condition": "High doses or rapid infusion", "message": "STOP: Severe, sometimes fatal, central nervous system toxicity (including blindness, coma, and death) has occurred, particularly with high doses. Do not exceed recommended doses."}, {"alert_type": "Autoimmune Hemolytic Anemia", "severity": "High", "trigger_condition": "Development of sudden anemia or jaundice during therapy", "message": "STOP: Life-threatening and sometimes fatal autoimmune hemolytic anemia has been reported. Monitor for hemolysis; discontinue fludarabine if hemolysis occurs."}]', '**Myelosuppression:** Severe bone marrow suppression, notably anemia, thrombocytopenia, and neutropenia, is common and may be cumulative. Monitor complete blood counts routinely.
INSERT INTO "drug_generic" VALUES(416, 'Denosumab', 'Denosumab', 'M05BX04', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Hypocalcemia", "severity": "High", "trigger_condition": "Patients with advanced chronic kidney disease (CrCl <30 mL/min) or receiving dialysis", "message": "STOP: Severe, life-threatening, and fatal hypocalcemia can occur. Pre-existing hypocalcemia must be corrected prior to initiation. Monitor calcium levels closely and ensure adequate calcium and vitamin D supplementation."}]', '**Hypocalcemia:** Pre-existing hypocalcemia must be corrected before initiating therapy. Patients with severe renal impairment (CrCl <30 mL/min) or receiving dialysis are at extreme risk. Adequately supplement all patients with calcium and vitamin D. Monitor serum calcium, phosphorus, and magnesium closely.
INSERT INTO "drug_generic" VALUES(417, 'Voxelotor', 'Voxelotor', 'B06AX03', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Development of generalized rash, urticaria, or mild shortness of breath", "message": "STOP: Serious hypersensitivity reactions have occurred. Discontinue voxelotor immediately and institute appropriate medical therapy."}]', '**Hypersensitivity Reactions:** Serious hypersensitivity reactions have occurred in <1% of patients treated. Clinical manifestations may include generalized rash, urticaria, mild shortness of breath, mild facial swelling, and eosinophilia. Discontinue the drug if a hypersensitivity reaction occurs.
INSERT INTO "drug_generic" VALUES(418, 'Dextrose 20%', 'Dextrose 20% in Water', 'B05BA03', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hyperosmolar Coma and Tissue Necrosis", "severity": "High", "trigger_condition": "Peripheral administration or rapid infusion", "message": "STOP: Highly hyperosmolar solution. Must be administered via a central venous catheter to prevent severe phlebitis and tissue necrosis. Rapid infusion can cause fatal hyperosmolar syndrome."}]', '**Hyperglycemia & Osmotic Diuresis:** Rapid administration may result in significant hyperglycemia, hyperosmolar syndrome, and osmotic diuresis leading to dehydration. Monitor blood glucose frequently.
INSERT INTO "drug_generic" VALUES(419, 'Glycopyrronium Bromide (Glycopyrrolate) oral sol', 'Glycopyrrolate', 'A03AB02', 0, 0, 0, 0, 1, 0, 1, 0, '[]', '**Anticholinergic Effects:** Use with caution in patients with conditions exacerbated by anticholinergic activity, such as glaucoma, myasthenia gravis, obstructive uropathy, and paralytic ileus.
INSERT INTO "drug_generic" VALUES(420, 'Nisoldipine', 'Nisoldipine', 'C08CA07', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Initiation of therapy or upward dose titration", "message": "STOP: Increased angina and/or myocardial infarction has occurred with initiation or dosage titration of calcium channel blockers. Monitor blood pressure and heart rate closely."}]', '**Hypotension and Angina:** May cause symptomatic hypotension or exacerbate angina, particularly during initiation or dose escalation. Monitor blood pressure and heart rate closely.
INSERT INTO "drug_generic" VALUES(421, 'Talazoparib', 'Talazoparib', 'L01XK04', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Initiation of therapy or during routine blood monitoring", "message": "STOP: Severe myelosuppression (anemia, neutropenia, thrombocytopenia) is common. Do not start until recovery from previous hematological toxicity. Monitor CBC monthly."}]', '**Myelosuppression:** Severe anemia, leukopenia/neutropenia, and thrombocytopenia have been reported. Do not initiate talazoparib until patients have adequately recovered from hematological toxicity caused by previous therapy. Monitor complete blood counts (CBC) at baseline and monthly thereafter.
INSERT INTO "drug_generic" VALUES(422, 'Ivabradine', 'Ivabradine', 'C01EB17', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Bradycardia and Conduction Disturbances", "severity": "High", "trigger_condition": "Resting heart rate <60 bpm prior to treatment or development of symptomatic bradycardia", "message": "STOP: Ivabradine causes dose-dependent bradycardia. Do not initiate if resting HR is <60 bpm. Reduce dose or discontinue if HR drops persistently below 50 bpm or if symptoms of bradycardia occur."}]', '**Atrial Fibrillation (AF):** Ivabradine is not effective in patients with AF and increases the risk of developing AF. Monitor regularly for the occurrence of AF; discontinue if AF develops.
INSERT INTO "drug_generic" VALUES(423, 'Mexiletine', 'Mexiletine', 'C01BB02', 0, 1, 0, 1, 1, 1, 1, 0, '[{"alert_type": "High Alert Medicine", "severity": "High", "trigger_condition": "Prescribing or administering antiarrhythmic therapy", "message": "Mexiletine is a high-alert medication. It carries a risk of proarrhythmia and increased mortality in patients with non-life-threatening arrhythmias. Use should be restricted to life-threatening ventricular arrhythmias."}]', '**Mortality Risk:** In the Cardiac Arrhythmia Suppression Trial (CAST), patients with asymptomatic, non-life-threatening ventricular arrhythmias who had a recent myocardial infarction had an increased rate of mortality when treated with Class Ic antiarrhythmics. Mexiletine should be reserved for life-threatening ventricular arrhythmias.
INSERT INTO "drug_generic" VALUES(424, 'Temazepam', 'Temazepam', 'N05CD07', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Concomitant Use with Opioids", "severity": "High", "trigger_condition": "Co-prescription with opioid analgesics", "message": "STOP: Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death. Reserve concomitant prescribing for patients with inadequate alternative treatment options."}]', '**CNS Depression and Impairment:** Temazepam causes CNS depression. Patients should be cautioned against driving or operating heavy machinery. The effect may be additive with alcohol and other CNS depressants.
INSERT INTO "drug_generic" VALUES(425, 'Captopril', 'Captopril', 'C09AA01', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Hypotension:** Symptomatic hypotension may occur, especially in volume- or salt-depleted patients, or those treated with high-dose diuretics. Start with a lower dose (e.g., 6.25 mg) and monitor closely.
INSERT INTO "drug_generic" VALUES(426, 'Frusemide (Furosemide)', 'Furosemide', 'C03CA01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Profound Diuresis and Electrolyte Depletion", "severity": "High", "trigger_condition": "High doses or rapid intravenous administration", "message": "Furosemide is a potent diuretic that, if given in excessive amounts, can lead to a profound diuresis with water and electrolyte depletion. Careful medical supervision is required. Rapid IV injection (>4 mg/min) increases the risk of permanent ototoxicity."}]', 'Monitor fluid and electrolyte balance (especially potassium, sodium, calcium, and magnesium) and renal function regularly. Hypokalemia can increase the risk of digitalis toxicity. Use with caution in patients with prostatic hyperplasia or impaired micturition, as sudden diuresis can cause acute urinary retention. Use with caution in patients with gout (may elevate uric acid) or diabetes mellitus (may elevate blood glucose). In patients with hepatic cirrhosis and ascites, sudden alterations in fluid and electrolyte balance may precipitate hepatic encephalopathy; initiate therapy in the hospital. To prevent ototoxicity, the IV infusion rate should not exceed 4 mg/min.', '- **Edema:** Management of edema associated with congestive heart failure (CHF), liver cirrhosis, and renal disease, including nephrotic syndrome.
INSERT INTO "drug_generic" VALUES(427, 'Cabozantinib', 'Cabozantinib', 'L01EX07', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Severe Hemorrhage and GI Perforation", "severity": "High", "trigger_condition": "History of severe bleeding or GI perforation", "message": "STOP: High risk of fatal hemorrhage, gastrointestinal perforations, and fistulas. Do not administer if there is a recent history of severe hemorrhage or hemoptysis."}]', '**Hemorrhage:** Severe and fatal hemorrhages have occurred. Do not use in patients with a recent history of hemorrhage or hemoptysis.
INSERT INTO "drug_generic" VALUES(428, 'Pazopanib Hydrochloride', 'Pazopanib', 'L01EX03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated transaminases or bilirubin during therapy", "message": "STOP: Severe and fatal hepatotoxicity has been observed. Monitor hepatic function prior to initiation and regularly during treatment. Interrupt, reduce, or discontinue dosing as recommended based on LFT abnormalities."}]', '**Hepatotoxicity:** Severe and fatal hepatotoxicity can occur. Monitor serum liver tests before initiation, at weeks 3, 5, 7, and 9, at month 3 and 4, and periodically thereafter.
INSERT INTO "drug_generic" VALUES(429, 'Ponatinib', 'Ponatinib', 'L01EA05', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Arterial Occlusion and Hepatotoxicity", "severity": "High", "trigger_condition": "Signs of myocardial infarction, stroke, severe ischemia, or elevated liver enzymes", "message": "STOP: Fatal and life-threatening arterial occlusion (cardiovascular, cerebrovascular, peripheral) and hepatotoxicity have occurred. Interrupt or discontinue immediately for severe events."}]', '**Arterial Occlusion:** Severe, fatal, and life-threatening arterial occlusions (MI, stroke, peripheral arterial disease) have occurred. Monitor for evidence of arterial occlusion. Interrupt or discontinue based on severity.
INSERT INTO "drug_generic" VALUES(430, 'Potassium Chloride 0.003% + Sodium Chloride 0.004% + Sodium Lactate 0.007%', 'Potassium Chloride, Sodium Chloride, and Sodium Lactate Intravenous Solution', 'B05BB01', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Fluid Overload:** Should not be administered rapidly or for prolonged periods without monitoring, as it may cause fluid overload, pulmonary congestion, and edema.
INSERT INTO "drug_generic" VALUES(431, 'Acrivastine + Pseudoephedrine', 'Acrivastine and Pseudoephedrine', 'R01BA52', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Risk and CNS Depression", "severity": "High", "trigger_condition": "Concurrent use with MAOIs or severe cardiovascular disease", "message": "STOP: Contraindicated in severe hypertension, severe coronary artery disease, and within 14 days of MAOI use due to the risk of hypertensive crisis. May cause sedation; avoid concurrent use with alcohol or other CNS depressants."}]', '**CNS Effects:** Due to the potential for sedation, assess individual responses before engaging in any activity requiring mental alertness, such as driving a motor vehicle or operating machinery. Concurrent use with alcohol or other CNS depressants may cause additional reductions in alertness and impairment of CNS performance and should be avoided.
INSERT INTO "drug_generic" VALUES(432, 'Vitamin B complex + Vitamin C', 'Vitamin B Complex with Vitamin C', 'A11EB', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Diagnostic Masking", "severity": "Medium", "trigger_condition": "Use in patients with undiagnosed anemia", "message": "STOP: Folic acid in this preparation may mask the symptoms of pernicious anemia. Hematologic remission may occur while irreversible neurological damage progresses."}]', '**Pernicious Anemia:** Administering folic acid can obscure pernicious anemia. Ensure proper diagnosis before initiating therapy.
INSERT INTO "drug_generic" VALUES(433, 'Chloroxylenol 0.3% + Triclosan 0.3% topical', 'Chloroxylenol and Triclosan', 'D08AE05', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Moderate", "trigger_condition": "Application near sensitive areas", "message": "For external use only. Avoid contact with the eyes, mouth, and mucous membranes. If accidental contact occurs, rinse thoroughly with water."}]', '**Condition Worsening:** Discontinue use and consult a physician if the condition worsens, or if symptoms persist for more than 7 days, or clear up and occur again within a few days.
INSERT INTO "drug_generic" VALUES(434, 'Sildenafil', 'Sildenafil', 'G04BE03', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Fatal Hypotension", "severity": "High", "trigger_condition": "Concurrent use of organic nitrates", "message": "STOP: Coadministration with organic nitrates in any form (regular or intermittent) is strictly contraindicated due to the risk of profound, potentially fatal hypotension."}]', '**Cardiovascular Risk:** Sexual activity carries an inherent cardiac risk. Evaluate the cardiovascular status of patients prior to initiating treatment for erectile dysfunction.
INSERT INTO "drug_generic" VALUES(435, 'Gallamine Triethiodide', 'Gallamine Triethiodide', 'M03AA02', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Respiratory Paralysis", "severity": "High", "trigger_condition": "Administration without mechanical ventilation", "message": "STOP: This drug causes profound neuromuscular blockade and respiratory paralysis. It must ONLY be administered by trained anesthesia personnel with immediate availability of mechanical ventilation and resuscitative equipment."}]', 'Careful dose titration and continuous monitoring of the degree of neuromuscular blockade (using a peripheral nerve stimulator) are required to prevent overdosage and ensure adequate recovery.
INSERT INTO "drug_generic" VALUES(436, 'Iron +  Folic Acid  +   Vitamin B  +  Vitamin C', 'Iron, Folic Acid, B-Complex Vitamins, and Ascorbic Acid', 'B03AE02', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Iron Toxicity Risk", "severity": "High", "trigger_condition": "Accidental overdose in pediatric patients", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep out of reach of children."}]', '- **Iron Overload:** Care should be taken in patients who may develop iron overload, such as those with hemochromatosis, hemolytic anemia, or red cell aplasia.
INSERT INTO "drug_generic" VALUES(437, 'Benzoyl Peroxide 2.5% topical', 'Benzoyl Peroxide', 'D10AE01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Bleaching and Photosensitivity", "severity": "Medium", "trigger_condition": "Application of product", "message": "STOP: Benzoyl peroxide can bleach hair and colored fabrics (towels, pillowcases, clothing). It also increases sensitivity to sunlight; strict sun protection is required."}]', '**Skin Irritation:** Erythema, scaling, dryness, and stinging/burning are very common, especially during the first few weeks of use. If severe, patients should use a non-comedogenic moisturizer, reduce the frequency of application, or temporarily discontinue use.
INSERT INTO "drug_generic" VALUES(438, 'Nilotinib', 'Nilotinib', 'L01EA03', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "QT Prolongation and Sudden Death", "severity": "High", "trigger_condition": "Baseline QT prolongation, hypokalemia, hypomagnesemia, or concurrent use of strong CYP3A4 inhibitors", "message": "STOP: Nilotinib prolongs the QT interval. Sudden deaths have been reported. Correct hypokalemia or hypomagnesemia prior to administration. Obtain baseline ECG and monitor periodically. Avoid use with strong CYP3A4 inhibitors or other QT-prolonging drugs."}]', 'Monitor for signs of myelosuppression (neutropenia, thrombocytopenia, anemia); perform complete blood counts every 2 weeks for the first 2 months, then monthly. Monitor for cardiovascular events, including peripheral arterial occlusive disease, ischemic heart disease, and ischemic cerebrovascular events. Monitor serum lipase, glucose, and lipid profiles periodically. Use with caution in patients with a history of pancreatitis or total gastrectomy. Maintain adequate hydration and correct uric acid levels to prevent tumor lysis syndrome. Hepatic impairment requires dose reduction.', '- **Newly Diagnosed Ph+ CML:** Treatment of adult and pediatric patients (1 year of age and older) with newly diagnosed Philadelphia chromosome-positive chronic myeloid leukemia (Ph+ CML) in chronic phase.
INSERT INTO "drug_generic" VALUES(439, 'Cefotetan', 'Cefotetan Disodium', 'J01DC05', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Bleeding Risk and Disulfiram Reaction", "severity": "High", "trigger_condition": "Concomitant alcohol use or patients at risk for bleeding", "message": "Contains an N-methylthiotetrazole (NMTT) side chain. Can cause hypoprothrombinemia and severe bleeding. Monitor PT/INR. Causes a severe disulfiram-like reaction if alcohol is consumed during or within 72 hours of therapy."}]', '**Bleeding Risk:** The N-methylthiotetrazole (NMTT) side chain inhibits vitamin K epoxide reductase, leading to hypoprothrombinemia and bleeding. Monitor prothrombin time (PT) in patients at risk (e.g., renal/hepatic impairment, malnutrition) and administer exogenous vitamin K as indicated.
INSERT INTO "drug_generic" VALUES(440, 'Relugolix', 'Relugolix', 'L02BX04', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "QT/QTc Prolongation", "severity": "High", "trigger_condition": "Patients with congenital long QT syndrome, CHF, or taking QT-prolonging drugs", "message": "STOP: Androgen deprivation therapy may prolong the QT/QTc interval. Correct electrolyte abnormalities and consider periodic ECG monitoring."}]', '**QT/QTc Interval Prolongation:** Androgen deprivation therapy (ADT) can prolong the QT interval. Weigh benefits vs. risks in patients with congenital long QT syndrome, congestive heart failure, frequent electrolyte abnormalities, or those taking QT-prolonging drugs. Monitor ECG and electrolytes periodically.
INSERT INTO "drug_generic" VALUES(441, 'Sucroferric Oxyhydroxide', 'Sucroferric Oxyhydroxide', 'V03AE05', 0, 0, 1, 1, 0, 0, 0, 0, '[]', '**Iron Accumulation Risk:** Monitor iron homeostasis closely in patients with a history of hemochromatosis or other diseases associated with iron accumulation, as sucroferric oxyhydroxide contains iron.
INSERT INTO "drug_generic" VALUES(442, 'Phenytoin Sodium', 'Phenytoin Sodium', 'N03AB02', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Cardiovascular Risk with Rapid Infusion", "severity": "High", "trigger_condition": "Intravenous administration", "message": "STOP: Intravenous administration must not exceed 50 mg/min in adults (or 1-3 mg/kg/min in pediatrics). Too rapid administration can cause severe hypotension, cardiac arrhythmias, and cardiovascular collapse."}]', '**Cardiovascular Risk:** Severe cardiovascular events, including atrial and ventricular conduction depression and ventricular fibrillation, have occurred with IV administration. Monitor BP and ECG continuously during IV therapy.
INSERT INTO "drug_generic" VALUES(443, 'Coenzyme Q10 (Ubidecarenone)', 'Coenzyme Q10 (Ubiquinone)', 'C01EB09', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Use with caution in patients with biliary obstruction, as Coenzyme Q10 is primarily excreted via bile. Diabetics using supplemental Coenzyme Q10 may experience improved beta-cell function and glycemic control, which could necessitate a reduction in their antidiabetic medications to prevent hypoglycemia. Caution is advised when used concurrently with antihypertensives, as it may cause additive blood pressure lowering.', '- **Cardiovascular Conditions (Adjunct):** Used as an adjunct in congestive heart failure (CHF), angina, and hypertension.
INSERT INTO "drug_generic" VALUES(444, 'Oxycodone + Naloxone', 'Oxycodone and Naloxone', 'N02AA55', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Addiction, Abuse, and Misuse", "severity": "High", "trigger_condition": "Prescription of opioid analgesics", "message": "STOP: Exposes patients to risks of opioid addiction, abuse, and misuse, which can lead to overdose and death. Assess risk before prescribing and monitor regularly. Tablets must be swallowed whole; crushing or chewing releases a potentially fatal dose of oxycodone."}]', '**Life-Threatening Respiratory Depression:** Serious, life-threatening, or fatal respiratory depression may occur. Monitor closely, especially during initiation or dose escalation. Accidental ingestion by children can be fatal.
INSERT INTO "drug_generic" VALUES(445, 'Cyproheptadine HCI', 'Cyproheptadine Hydrochloride', 'R06AX02', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "CNS Depression", "severity": "High", "trigger_condition": "Concomitant use with alcohol or other CNS depressants", "message": "STOP: Cyproheptadine can cause significant CNS depression. Patients should be warned against engaging in activities requiring mental alertness, such as driving or operating machinery."}]', '**Anticholinergic Effects:** Use with caution in patients with increased intraocular pressure, history of asthma or chronic breathing disorders, hyperthyroidism, cardiovascular disease, or hypertension.
INSERT INTO "drug_generic" VALUES(446, 'Chlorpropamide', 'Chlorpropamide', 'A10BB02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Hypoglycemia Risk", "severity": "High", "trigger_condition": "Use in elderly patients or those with renal impairment", "message": "STOP: Chlorpropamide has a very long half-life and can cause severe, prolonged, and potentially fatal hypoglycemia. It should generally be avoided in elderly patients and those with renal impairment."}]', 'Use with extreme caution in elderly, debilitated, or malnourished patients, as they are highly susceptible to the hypoglycemic action of glucose-lowering drugs. Chlorpropamide is generally not recommended as a first-line agent in these populations due to its prolonged half-life.
INSERT INTO "drug_generic" VALUES(447, 'Piracetam', 'Piracetam', 'N06BX03', 0, 0, 0, 0, 1, 0, 1, 1, '[]', '**Abrupt Withdrawal:** Avoid abrupt discontinuation, particularly in patients treated for myoclonus, as this may induce myoclonic or generalized seizures.
INSERT INTO "drug_generic" VALUES(448, 'Human Fibrinogen + Human Thrombin +  Aprotinin (Fibrin Sealant) topical', 'Fibrin Sealant (Human)', 'B02BC30', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Intravascular Application Risk", "severity": "High", "trigger_condition": "Injection into blood vessels", "message": "STOP: For topical use only. Do not inject directly into the circulatory system. Intravascular application can lead to life-threatening thromboembolic events and severe anaphylaxis."}]', '**Intravascular Application:** Must not be injected into highly vascularized tissue or blood vessels. Doing so can cause severe, life-threatening intravascular coagulation and thromboembolic events.
INSERT INTO "drug_generic" VALUES(449, 'Diclofenac Diethylamine + Methyl Salicylate + Menthol +  Linseed Oil Topical', 'Diclofenac Diethylamine / Methyl Salicylate / Menthol / Linseed Oil Topical', 'M02AA15', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Application Site Reaction", "severity": "Moderate", "trigger_condition": "Application to broken or damaged skin", "message": "STOP: Do not apply to open wounds, irritated skin, or infections. Discontinue use if a severe skin rash develops."}]', '**External Use Only:** Avoid contact with the eyes and mucous membranes. Wash hands thoroughly after application unless the hands are the treated area.
INSERT INTO "drug_generic" VALUES(450, 'Diclofenac Sodium Eye prep', 'Diclofenac Ophthalmic', 'S01BC03', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Corneal Toxicity", "severity": "High", "trigger_condition": "Prolonged use or use in patients with compromised corneas", "message": "STOP: Continued use of topical NSAIDs may result in epithelial breakdown, corneal thinning, erosion, ulceration, or perforation. Discontinue immediately if evidence of corneal epithelial damage occurs."}]', '**Corneal Effects:** May slow or delay healing. Patients with complicated ocular surgeries, corneal denervation, epithelial defects, diabetes, or dry eye syndrome are at higher risk for severe corneal adverse events.
INSERT INTO "drug_generic" VALUES(451, 'Sorafenib', 'Sorafenib', 'L01EX02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiovascular and Hemorrhagic Toxicity", "severity": "High", "trigger_condition": "Patients presenting with chest pain, severe hypertension, or signs of active bleeding", "message": "STOP: Sorafenib can cause severe, potentially fatal cardiac ischemia/infarction, hypertensive crises, and major hemorrhagic events. Interrupt therapy immediately and evaluate."}]', 'Regularly monitor blood pressure weekly during the first 6 weeks of therapy and periodically thereafter; severe or persistent hypertension may require temporary or permanent discontinuation. Monitor complete blood count (CBC) and platelets regularly due to the risk of myelosuppression. Monitor INR and prothrombin time closely in patients taking warfarin, as bleeding risk is elevated. Interrupt treatment if the patient develops cardiac ischemia, infarction, or severe bleeding. Use with caution in patients with a history of QT prolongation; monitor ECG and electrolytes (magnesium, potassium, calcium). Monitor for dermatologic toxicities, particularly hand-foot skin reaction (palmar-plantar erythrodysesthesia) and severe rash, which may require dose modification. Adequate contraception must be used by both males and females during therapy and for at least 6 months (females) or 3 months (males) after the last dose.', '- **Hepatocellular Carcinoma (HCC):** Indicated for the treatment of patients with unresectable hepatocellular carcinoma.
INSERT INTO "drug_generic" VALUES(452, 'Amino Acids (5 % & 10%) + D-sorbitol + Electrolytes', 'Amino Acids with Electrolytes', 'B05BA10', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Pulmonary Embolism", "severity": "High", "trigger_condition": "Precipitate formation in the IV line", "message": "STOP: Pulmonary vascular precipitates causing pulmonary embolism and death have occurred. Inspect solutions visually for particulate matter. If signs of pulmonary distress occur, stop the infusion immediately."}, {"alert_type": "Central Line Requirement", "severity": "High", "trigger_condition": "Infusion of hyperosmolar solutions", "message": "STOP: Solutions with an osmolarity of 900 mOsm/L or greater MUST be infused through a central venous catheter to prevent severe vein damage and thrombosis."}]', '**Refeeding Syndrome:** Refeeding severely undernourished patients can result in the refeeding syndrome, characterized by intracellular shift of potassium, phosphorus, and magnesium as the patient becomes anabolic. Thiamine deficiency and fluid retention may also develop. Monitor electrolytes closely.
INSERT INTO "drug_generic" VALUES(453, 'Colestipol', 'Colestipol', 'C10AC02', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Gastrointestinal Obstruction", "severity": "High", "trigger_condition": "Patient history of bowel obstruction or administration of dry granules", "message": "STOP: Colestipol is contraindicated in bowel obstruction. Never consume the granules in their dry form, as this can cause esophageal distress, choking, or severe gastrointestinal impaction."}]', '**Bleeding Risk:** May interfere with the absorption of fat-soluble vitamins (A, D, E, K). Vitamin K deficiency can lead to hypoprothrombinemia and an increased risk of bleeding. Monitor coagulation parameters and supplement vitamins if necessary.
INSERT INTO "drug_generic" VALUES(454, 'Gemfibrozil', 'Gemfibrozil', 'C10AB04', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Concurrent use with HMG-CoA reductase inhibitors (statins)", "message": "STOP: Co-administration with statins significantly increases the risk of severe myopathy and potentially fatal rhabdomyolysis. Avoid concurrent use."}]', 'Secondary causes of hyperlipidemia (e.g., hypothyroidism, poorly controlled diabetes mellitus) must be treated before initiating therapy.
INSERT INTO "drug_generic" VALUES(455, 'Ketoconazole cream', 'Ketoconazole cream', 'D01AC08', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Topical Corticosteroid Withdrawal", "severity": "Medium", "trigger_condition": "Switching from prolonged topical corticosteroid therapy", "message": "STOP: To prevent a rebound effect, gradually withdraw prolonged topical corticosteroid therapy over 2 to 3 weeks while initiating ketoconazole cream."}]', '**Corticosteroid Withdrawal:** In patients who have been on prolonged treatment with topical corticosteroids, abruptly stopping the steroid can cause a rebound flare. Gradually withdraw the steroid therapy over 2 to 3 weeks while using ketoconazole cream.
INSERT INTO "drug_generic" VALUES(456, 'Ticarcillin', 'Ticarcillin', 'J01CA13', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Patient history of penicillin or cephalosporin allergy", "message": "STOP: Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. Verify patient allergy history before prescribing."}]', '**Sodium Load:** Ticarcillin contains a significant amount of sodium (approximately 5.2 mEq per gram). Use with extreme caution in patients on a restricted sodium diet or those with heart failure.
INSERT INTO "drug_generic" VALUES(457, 'Quinine Sulphate', 'Quinine Sulfate', 'P01BC01', 1, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Hematologic and Cardiovascular Toxicity", "severity": "High", "trigger_condition": "Use for nocturnal leg cramps", "message": "STOP: Quinine is NOT approved for the treatment or prevention of nocturnal leg cramps. Fatalities and severe adverse events (thrombocytopenia, hemolytic-uremic syndrome, arrhythmias) have occurred. Risk far outweighs any potential benefit."}]', 'Use with extreme caution in patients with cardiac conduction defects, heart block, or atrial fibrillation. Monitor for signs of cardiotoxicity. Monitor blood glucose levels frequently due to the risk of hyperinsulinemic hypoglycemia. Monitor CBC with platelet count (risk of severe, unpredictable thrombocytopenia), LFTs, and perform ophthalmologic exams if visual symptoms occur. Discontinue immediately if signs of hypersensitivity or severe cinchonism develop.', '- **Uncomplicated Malaria:** Treatment of uncomplicated *Plasmodium falciparum* malaria. Often used in combination with a second agent (e.g., doxycycline, tetracycline, or clindamycin) to shorten the course and prevent relapse.
INSERT INTO "drug_generic" VALUES(458, 'Levobunolol Hydrochloride', 'Levobunolol Hydrochloride', 'S01ED03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Systemic Absorption Risk", "severity": "High", "trigger_condition": "Patients with severe reactive airway disease or severe cardiac disease", "message": "STOP: Despite topical ophthalmic administration, systemic absorption can occur, leading to severe respiratory (bronchospasm) and cardiovascular (bradycardia, heart block) adverse events."}]', '**Systemic Absorption:** Even though administered topically, levobunolol can be absorbed systemically, producing the same adverse reactions seen with systemic beta-blockers.
INSERT INTO "drug_generic" VALUES(459, 'Netarsudil eye prep', 'Netarsudil ophthalmic', 'S01EX05', 0, 0, 1, 1, 0, 1, 0, 0, '[]', 'Bacterial keratitis has been associated with the use of multiple-dose containers of topical ophthalmic products; these containers can become inadvertently contaminated by patients who have a concurrent corneal disease or a disruption of the ocular epithelial surface. Instruct patients to avoid allowing the tip of the dispensing container to contact the eye, surrounding structures, fingers, or any other surface to prevent contamination. Netarsudil contains benzalkonium chloride, which may be absorbed by soft contact lenses. Remove contact lenses prior to instilling the ophthalmic solution; lenses may be reinserted 15 minutes following administration.', '- Reduction of elevated intraocular pressure (IOP) in patients with open-angle glaucoma or ocular hypertension.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to netarsudil or any of the excipients in the formulation, due to the risk of severe ocular inflammation or allergic conjunctivitis.', '- **Conjunctival hyperemia** (Very common, occurring in >50% of patients; usually mild)
INSERT INTO "drug_generic" VALUES(460, 'Moexipril + Hydrochlorothiazide', 'Moexipril hydrochloride and hydrochlorothiazide', 'C09BA13', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: When pregnancy is detected, discontinue this medication as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}]', '**Fetal Toxicity:** Use of drugs that act on the renin-angiotensin system during the second and third trimesters of pregnancy reduces fetal renal function and increases fetal and neonatal morbidity and death.
INSERT INTO "drug_generic" VALUES(461, 'Econazole Nitrate (Vaginal prep)', 'Econazole', 'G01AF05', 0, 0, 1, 1, 0, 1, 0, 0, '[]', '**Contraceptive Failure:** Vaginal formulations contain mineral oil or other excipients that may weaken latex condoms and diaphragms, leading to contraceptive failure or lack of protection against sexually transmitted infections. Advise alternative methods of contraception during treatment.
INSERT INTO "drug_generic" VALUES(462, 'Fluorometholone 0.1% + Gentamicin 0.3% Eye prep', 'Fluorometholone 0.1% and Gentamicin 0.3% Ophthalmic', 'S01CA07', 1, 0, 0, 0, 0, 0, 0, 1, '[]', 'Prolonged use of ophthalmic corticosteroids may result in glaucoma, optic nerve damage, visual acuity defects, and posterior subcapsular cataract formation. Intraocular pressure (IOP) must be monitored routinely. Corticosteroids may mask, activate, or exacerbate ocular infections. May cause corneal and scleral thinning, leading to perforation. If no improvement is observed after 7-8 days of treatment, alternative therapies should be considered. Patients experiencing blurred vision after application (especially with the ointment) should refrain from driving or operating machinery.', '- **Steroid-Responsive Inflammatory Ocular Conditions:** Treatment of allergic and inflammatory conditions of the eye where a superficial bacterial ocular infection exists or is expected.
INSERT INTO "drug_generic" VALUES(463, 'Elotuzumab', 'Elotuzumab', 'L01FX08', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Infusion Reactions", "severity": "High", "trigger_condition": "During or shortly after IV infusion", "message": "Severe infusion reactions can occur. Premedicate with dexamethasone, diphenhydramine, ranitidine, and acetaminophen. Interrupt infusion for Grade 2 or higher reactions."}]', '**Infusion Reactions:** Infusion reactions can occur and may include fever, chills, hypertension, bradycardia, and hypotension. Premedicate all patients prior to infusion. Interrupt the infusion for Grade 2 or higher reactions and manage symptoms appropriately. Upon resolution, resume at a reduced rate.
INSERT INTO "drug_generic" VALUES(464, 'Disopyramide', 'Disopyramide', 'C01BA03', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Proarrhythmic Effects and Heart Failure", "severity": "High", "trigger_condition": "Use in patients with structural heart disease, cardiomyopathy, or uncompensated heart failure", "message": "STOP: Disopyramide has profound negative inotropic effects and can precipitate or worsen congestive heart failure. It is also proarrhythmic and can cause fatal ventricular arrhythmias."}]', '- **Heart Failure:** Possesses significant negative inotropic properties. High risk of precipitating or exacerbating congestive heart failure, especially in patients with underlying cardiomyopathy or a history of heart failure.
INSERT INTO "drug_generic" VALUES(465, 'Gentamicin 0.1% Topical', 'Gentamicin', 'D06AX07', 1, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Systemic Toxicity Risk", "severity": "Moderate", "trigger_condition": "Application to large areas of denuded skin or severe burns", "message": "Systemic absorption can occur when applied to large areas of damaged skin, potentially leading to ototoxicity and nephrotoxicity. Monitor auditory and renal functions in high-risk patients."}]', 'Prolonged use of topical antibiotics may result in the overgrowth of nonsusceptible organisms, including fungi. If superinfection occurs, discontinue use and institute appropriate alternative therapy. Systemic absorption of topically applied gentamicin is generally minimal; however, application to large areas of denuded skin, severe burns, or prolonged use can lead to systemic accumulation. In such cases, monitor for signs of aminoglycoside-induced ototoxicity (auditory and vestibular) and nephrotoxicity, particularly in patients with pre-existing renal impairment, the elderly, or those receiving concurrent systemic nephrotoxic or ototoxic medications. Avoid concurrent use with neuromuscular blocking agents if significant systemic absorption is anticipated, as it may potentiate neuromuscular blockade.', '- **Primary Bacterial Skin Infections:** Treatment of impetigo contagiosa, superficial folliculitis, ecthyma, furunculosis, sycosis barbae, and pyoderma gangrenosum.
INSERT INTO "drug_generic" VALUES(466, 'Anastrozole', 'Anastrozole', 'L02BG03', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Ischemic Cardiovascular Events", "severity": "High", "trigger_condition": "Patients with pre-existing ischemic heart disease", "message": "STOP: Increased incidence of ischemic cardiovascular events (angina, myocardial infarction) has been reported. Use only if the benefits greatly outweigh the risks."}, {"alert_type": "Bone Mineral Density Reduction", "severity": "High", "trigger_condition": "Long-term therapy", "message": "STOP: Anastrozole significantly decreases bone mineral density, increasing the risk of osteoporosis and fractures. Monitor BMD and consider concurrent bisphosphonate therapy."}]', '**Hyperlipidemia:** Elevated serum cholesterol has been reported. Monitor lipid profiles closely and manage according to current guidelines.
INSERT INTO "drug_generic" VALUES(467, 'Neostigmine Methyl Sulphate', 'Neostigmine Methylsulfate', 'N07AA01', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Bradycardia and Cardiac Arrest", "severity": "High", "trigger_condition": "Intravenous administration without anticholinergic premedication", "message": "STOP: Neostigmine can cause severe bradycardia, AV block, and cardiac arrest. Always administer an anticholinergic agent (e.g., atropine or glycopyrrolate) prior to or concomitantly with IV neostigmine."}]', 'Use with extreme caution in patients with bronchial asthma, cardiovascular disorders (e.g., bradycardia, recent myocardial infarction, hypotension, arrhythmias), peptic ulcer disease, vagotonia, epilepsy, parkinsonism, or hyperthyroidism. Caution is required in patients with renal impairment, as neostigmine is primarily excreted by the kidneys. Continuous monitoring of ECG, blood pressure, and heart rate is mandatory, especially during intravenous administration. Have atropine and resuscitation equipment immediately available.', '- **Reversal of Nondepolarizing Neuromuscular Blockade:** Used postoperatively to reverse the effects of nondepolarizing muscle relaxants.
INSERT INTO "drug_generic" VALUES(468, 'Vilanterol + Umeclidinium', 'Umeclidinium and Vilanterol', 'R03AL03', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Asthma-Related Death Risk", "severity": "High", "trigger_condition": "Use in patients with asthma without a concomitant long-term asthma control medication", "message": "STOP: Long-acting beta2-adrenergic agonists (LABAs) increase the risk of asthma-related death. This combination is NOT indicated for the treatment of asthma."}, {"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Sudden wheezing or shortness of breath immediately after inhalation", "message": "STOP: Discontinue immediately and treat with a short-acting inhaled bronchodilator. Evaluate for alternative therapy."}]', '**Deteriorating Disease:** Do not initiate in patients with acutely deteriorating COPD or acute episodes of bronchospasm. It is not a rescue medication.
INSERT INTO "drug_generic" VALUES(469, 'Fezolinetant', 'Fezolinetant', 'G02CX06', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Initiation of therapy or presence of baseline hepatic impairment", "message": "STOP: Severe drug-induced liver injury has been reported. Obtain baseline LFTs before initiation. Do not start if ALT/AST or total bilirubin is >2x ULN. Monitor LFTs monthly for the first 3 months, then at 6 and 9 months."}]', '**Hepatotoxicity and Liver Enzyme Elevations**
INSERT INTO "drug_generic" VALUES(470, 'Trifluridine + Tipiracil', 'Trifluridine / Tipiracil', 'L01BC59', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Initiation of therapy or during treatment cycles", "message": "STOP: Severe and life-threatening myelosuppression (anemia, neutropenia, thrombocytopenia) can occur. Obtain CBC prior to and on Day 15 of each cycle. Withhold dose for severe cytopenias."}]', '**Myelosuppression:** Severe and life-threatening myelosuppression, including anemia, neutropenia, thrombocytopenia, and febrile neutropenia, has been reported. Obtain a complete blood count (CBC) prior to and on Day 15 of each cycle, or more frequently as clinically indicated. Withhold, reduce the dose, or permanently discontinue based on the severity of myelosuppression.
INSERT INTO "drug_generic" VALUES(471, 'Lamivudine + Nevirapine + Zidovudine', 'Lamivudine, Nevirapine, and Zidovudine', 'J05AR05', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Hepatotoxicity and Skin Reactions", "severity": "High", "trigger_condition": "First 18 weeks of therapy, especially in women with CD4 >250 cells/mm3 or men with CD4 >400 cells/mm3", "message": "Nevirapine can cause severe, life-threatening hepatotoxicity and skin reactions (e.g., Stevens-Johnson syndrome). Zidovudine can cause severe hematologic toxicity. Discontinue immediately if severe rash or hepatotoxicity occurs."}]', 'Intensive clinical and laboratory monitoring, including liver function tests (LFTs), is required during the first 18 weeks of treatment due to the high risk of nevirapine-induced hepatotoxicity. Monitor hematological parameters (CBC) frequently for zidovudine-induced anemia and neutropenia. Use with extreme caution in patients with poor bone marrow reserve, renal impairment, or hepatic impairment. Patients with low body weight should avoid this fixed-dose combination. Withdraw treatment if symptomatic hyperlactatemia, metabolic/lactic acidosis, progressive hepatomegaly, or rapidly elevating aminotransferase levels occur.', '- **HIV-1 Infection:** Treatment of HIV-1 infection in adults and adolescents whose viral load is suppressed or who have demonstrated tolerability to the individual components.', '- **Severe Bone Marrow Suppression:** Contraindicated in patients with abnormally low neutrophil counts (<0.75 x 10^9/L) or abnormally low hemoglobin levels (<7.5 g/dL or 4.65 mmol/L) due to zidovudine toxicity.
INSERT INTO "drug_generic" VALUES(472, 'Darifenacin', 'Darifenacin', 'G04BD10', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Urinary and Gastric Retention", "severity": "High", "trigger_condition": "Patients with clinically significant bladder outflow obstruction or severe gastrointestinal obstructive disorders", "message": "STOP: Darifenacin is contraindicated in patients with urinary retention or gastric retention due to its anticholinergic properties, which can severely exacerbate these conditions."}]', '**Central Nervous System Effects:** Therapy is associated with anticholinergic CNS effects, including headache, confusion, hallucinations, and somnolence. Monitor patients closely, particularly after initiating treatment or increasing the dose.
INSERT INTO "drug_generic" VALUES(473, 'Oseltamivir', 'Oseltamivir', 'J05AH02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Neuropsychiatric Events", "severity": "High", "trigger_condition": "Pediatric and adolescent patients", "message": "STOP: Patients with influenza may be at an increased risk of hallucinations, delirium, and abnormal behavior early in their illness. Monitor closely for signs of abnormal behavior."}]', '**Neuropsychiatric Events:** Patients, particularly children and adolescents, may experience abnormal behavior, delirium, and hallucinations. Monitor closely for behavioral changes.
INSERT INTO "drug_generic" VALUES(474, 'Nortriptyline', 'Nortriptyline', 'N06AA10', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Suicidality and Antidepressant Drugs", "severity": "High", "trigger_condition": "Initiation of therapy or dose changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Closely monitor for clinical worsening, suicidality, or unusual changes in behavior."}]', 'Avoid abrupt withdrawal to prevent discontinuation syndrome (nausea, headache, malaise). Use with extreme caution in patients with a history of cardiovascular disease, as TCAs can cause arrhythmias, sinus tachycardia, and prolong conduction time. Caution in patients with a history of seizures, narrow-angle glaucoma, urinary retention, prostatic hyperplasia, or chronic constipation due to potent anticholinergic effects. May unmask mania in patients with bipolar disorder. Monitor blood pressure and heart rate prior to and during therapy. May impair the ability to perform hazardous tasks such as driving.', '- **Depressive Illness:** Treatment of major depressive disorder.
INSERT INTO "drug_generic" VALUES(475, 'Hydrochlorothiazide + Fosinopril', 'Fosinopril and Hydrochlorothiazide', 'C09BA09', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Fetal Toxicity:** Use of drugs that act on the renin-angiotensin system during the second and third trimesters of pregnancy reduces fetal renal function and increases fetal and neonatal morbidity and death. Discontinue immediately upon detection of pregnancy.
INSERT INTO "drug_generic" VALUES(476, 'Tropicamide 1% Eye prep', 'Tropicamide', 'S01FA06', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Systemic Absorption:** To minimize systemic absorption, apply pressure to the lacrimal sac (nasolacrimal occlusion) for 1-2 minutes immediately following instillation.
INSERT INTO "drug_generic" VALUES(477, 'Allium cepa + Heparin + Allantoin', 'Onion Extract, Heparin, and Allantoin Gel', 'D03AX', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Low", "trigger_condition": "Application to unhealed wounds", "message": "For external use only. Do not apply to open or unhealed wounds. Treatment should only begin after the wound has completely closed and the scab has fallen off or stitches have been removed."}]', '**Environmental Exposure:** During treatment of fresh scars, avoid physical irritants such as extreme cold, UV light (sun exposure), and abrupt or harsh massage, as these can worsen scar formation.
INSERT INTO "drug_generic" VALUES(478, 'Dextrose 5% + Sodium Chloride 0.225%', 'Dextrose 5% and Sodium Chloride 0.225%', 'B05BB02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Fluid and Solute Overload", "severity": "Moderate", "trigger_condition": "Administration in patients with congestive heart failure or severe renal insufficiency", "message": "Caution: Can cause significant fluid overload, pulmonary edema, and electrolyte disturbances. Monitor fluid balance and electrolytes closely."}]', '**Fluid and Electrolyte Overload:** Administration can cause fluid and/or solute overload resulting in dilution of serum electrolyte concentrations, overhydration, congested states, or pulmonary edema. Use with caution in patients with congestive heart failure or severe renal insufficiency.
INSERT INTO "drug_generic" VALUES(479, 'Mix of 9 Trace Elements', 'Trace Elements Injection (Multiple)', 'B05XA31', 0, 0, 1, 1, 1, 1, 0, 0, '[{"alert_type": "Dilution Requirement", "severity": "High", "trigger_condition": "Preparation for administration", "message": "STOP: Must be diluted prior to administration. Do not inject directly into a peripheral or central vein undiluted, as it can cause severe phlebitis and toxicity."}]', '**Hepatic Impairment / Cholestasis:** Copper and manganese are primarily excreted in the bile. In patients with severe cholestasis or biliary obstruction, these elements can accumulate, leading to neurotoxicity (manganese) or hepatotoxicity (copper). Monitor blood levels and consider withholding if levels are elevated.
INSERT INTO "drug_generic" VALUES(480, 'Dextran 70 6% + Dextrose 5%', 'Dextran 70 in 5% Dextrose', 'B05AA05', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Fluid Overload", "severity": "High", "trigger_condition": "Initiation of IV infusion", "message": "STOP: Severe anaphylactoid reactions can occur. Monitor closely during the first minutes of infusion. High risk of circulatory overload; monitor central venous pressure and cardiac status continuously."}]', '**Circulatory Overload:** Rapid infusion or excessive volumes can precipitate pulmonary edema and congestive heart failure. Monitor central venous pressure (CVP) and clinical status closely.
INSERT INTO "drug_generic" VALUES(481, 'Metyrosine', 'Metyrosine', 'C02AW01', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Crystalluria and Sedation", "severity": "High", "trigger_condition": "Inadequate fluid intake or concurrent CNS depressants", "message": "STOP: Metyrosine can cause severe crystalluria and transient dysuria. Maintain adequate fluid intake. It also causes profound sedation; avoid concurrent CNS depressants."}]', '**Crystalluria:** Metyrosine is minimally metabolized and excreted largely unchanged in the urine. To prevent crystalluria and urolithiasis, maintain adequate fluid intake to achieve a daily urine volume of at least 2000 mL.
INSERT INTO "drug_generic" VALUES(482, 'Hydrocortisone Acetate 1% Topical', 'Hydrocortisone Acetate', 'D07AA02', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Systemic Absorption", "severity": "Moderate", "trigger_condition": "Prolonged use, application to large surface areas, or use of occlusive dressings", "message": "Systemic absorption of topical corticosteroids can produce reversible HPA axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria. Avoid prolonged use or occlusive dressings unless directed."}]', 'Chronic topical corticosteroid therapy may interfere with growth and development in children; use the lowest effective potency. Children may absorb proportionally larger amounts and are more susceptible to systemic toxicity. Application to large surface areas, denuded skin, or under occlusive dressings increases percutaneous absorption and the risk of systemic effects (e.g., Cushing syndrome, HPA axis suppression). Prolonged use may increase the risk of secondary infections, mask acute infections, and exacerbate viral infections. Avoid exposure to measles or chickenpox. Discontinue therapy if allergic contact dermatitis or local irritation occurs. Use with caution in patients with diabetes, cardiovascular disease, or hepatic impairment.', '- **Corticosteroid-Responsive Dermatoses:** Relief of inflammatory and pruritic manifestations of corticosteroid-responsive dermatoses.
INSERT INTO "drug_generic" VALUES(483, 'Acetazolamide', 'Acetazolamide', 'S01EC01', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Cutaneous Reactions and Blood Dyscrasias", "severity": "High", "trigger_condition": "Patient presenting with rash, fever, or signs of infection/bleeding", "message": "STOP: Fatalities have occurred due to severe reactions to sulfonamides, including Stevens-Johnson syndrome, toxic epidermal necrolysis, fulminant hepatic necrosis, agranulocytosis, and aplastic anemia."}]', '**Sulfonamide Hypersensitivity:** Acetazolamide is a sulfonamide derivative. Severe, potentially fatal reactions including Stevens-Johnson syndrome (SJS), toxic epidermal necrolysis (TEN), and blood dyscrasias can occur. Discontinue at the first sign of rash.
INSERT INTO "drug_generic" VALUES(484, 'Mometasone Furoate 0.1% Topical', 'Mometasone Furoate', 'D07AC13', 0, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Endocrine Risk", "severity": "Moderate", "trigger_condition": "Prolonged use over large surface areas or under occlusive dressings", "message": "WARNING: Systemic absorption of topical corticosteroids can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria."}]', '**Local Irritation:** If irritation develops, treatment should be discontinued and appropriate therapy instituted.
INSERT INTO "drug_generic" VALUES(485, 'Risedronate Sodium + Calcium', 'Risedronate and Calcium', 'M05BB04', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Upper Gastrointestinal Adverse Reactions", "severity": "High", "trigger_condition": "Inability to stand or sit upright for at least 30 minutes", "message": "STOP: Severe esophageal irritation, esophagitis, and esophageal ulcers can occur. Patients must be able to remain upright for at least 30 minutes after taking the risedronate component."}]', 'Use with extreme caution in patients with a history of upper gastrointestinal disorders (e.g., dysphagia, esophageal diseases, gastritis, ulcers). 
INSERT INTO "drug_generic" VALUES(486, 'Lemborexant', 'Lemborexant', 'N05CJ02', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "CNS Depression and Daytime Impairment", "severity": "High", "trigger_condition": "Taking the medication with less than 7 hours of planned sleep", "message": "STOP: Lemborexant can impair daytime wakefulness and driving ability. Ensure at least 7 hours of sleep are planned after taking the dose."}]', '**CNS Depression and Daytime Impairment:** Lemborexant is a CNS depressant that can impair daytime wakefulness even when used as prescribed. CNS depression may persist and affect next-day tasks, including driving ability. Coadministration with other CNS depressants (e.g., alcohol, benzodiazepines) increases this risk.
INSERT INTO "drug_generic" VALUES(487, 'Gliclazide', 'Gliclazide', 'A10BB09', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hypoglycemia Risk", "severity": "High", "trigger_condition": "Deficient caloric intake, severe renal/hepatic impairment, or concurrent use of other antidiabetics", "message": "All sulfonylureas can cause severe hypoglycemia. Proper patient selection, dosage, and instructions are important to avoid hypoglycemic episodes. Renal or hepatic insufficiency may cause elevated drug levels and increase the risk of serious hypoglycemic reactions."}]', 'Careful monitoring of blood glucose concentration is essential. Patients may require a temporary transition to insulin therapy during periods of metabolic stress (e.g., severe infection, trauma, surgery). There is an increased risk of severe hypoglycemia in the elderly, debilitated, or malnourished patients, and in those with hepatic or renal impairment. The risk of hypoglycemia is also elevated when caloric intake is deficient, after strenuous or prolonged exercise, when alcohol is ingested, or when more than one glucose-lowering drug is used. Caution is advised in patients with G6PD deficiency due to the risk of hemolytic anemia.', '- **Type 2 Diabetes Mellitus:** Indicated as an adjunct to diet, exercise, and weight loss to improve glycemic control in adults with type 2 diabetes mellitus when dietary measures alone are inadequate.', '- **Type 1 Diabetes Mellitus:** Contraindicated as it requires functioning pancreatic beta cells.
INSERT INTO "drug_generic" VALUES(488, 'Selinexor', 'Selinexor', 'L01XX62', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Cytopenias", "severity": "High", "trigger_condition": "Initiation of therapy or presence of baseline bone marrow suppression", "message": "STOP: Selinexor causes severe thrombocytopenia and neutropenia. Monitor complete blood counts (CBC) at baseline and frequently during treatment. Fatal hemorrhages and severe infections have occurred."}]', '**Thrombocytopenia:** High incidence of severe thrombocytopenia; median onset is 22 days. Bleeding events, including fatal hemorrhages, have been reported. Monitor platelet counts frequently and manage with dose modifications, platelet transfusions, or thrombopoietin receptor agonists as clinically indicated.
INSERT INTO "drug_generic" VALUES(489, 'Zafirlukast', 'Zafirlukast', 'R03DC01', 0, 0, 1, 0, 0, 0, 1, 0, '[]', 'Not indicated for the reversal of bronchospasm in acute asthma attacks (status asthmaticus). Do not abruptly substitute zafirlukast for oral or inhaled corticosteroids. Monitor closely for signs of hepatic injury (right upper quadrant pain, nausea, fatigue, jaundice); periodic monitoring of LFTs is recommended. Rare cases of eosinophilic conditions, including Churg-Strauss syndrome, have been reported, often following the reduction of oral corticosteroid therapy. Neuropsychiatric events (agitation, depression, suicidal ideation) have been reported with leukotriene modifiers.', '- **Chronic Asthma:** Prophylaxis and chronic treatment of asthma in adults and children 5 years of age and older.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to zafirlukast or any of its inactive ingredients.
INSERT INTO "drug_generic" VALUES(490, 'Atomoxetine', 'Atomoxetine', 'N06BA09', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Suicidal Ideation", "severity": "High", "trigger_condition": "Initiation of therapy in children and adolescents", "message": "STOP: Atomoxetine increases the risk of suicidal ideation in children and adolescents. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}, {"alert_type": "Severe Liver Injury", "severity": "High", "trigger_condition": "Development of jaundice or elevated liver enzymes", "message": "STOP: Severe liver injury, which may progress to liver failure, has been reported. Discontinue immediately and do not restart if jaundice or laboratory evidence of liver injury occurs."}]', '**Cardiovascular Events:** Sudden death, stroke, and MI have been reported. Avoid use in patients with known serious structural cardiac abnormalities, cardiomyopathy, or serious heart rhythm abnormalities. Assess cardiovascular status prior to initiation.
INSERT INTO "drug_generic" VALUES(491, 'Capsaicin 0.025% topical', 'Capsaicin', 'M02AB01', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Chemical Burns", "severity": "High", "trigger_condition": "Application with heat or on broken skin", "message": "STOP: First to third-degree chemical burns can occur. Do not apply immediately before/after bathing, swimming, or strenuous exercise. Do not use with heating pads."}]', '**Application Site Reactions:** Transient burning sensation is common but usually dissipates after several days of continuous use. Discontinue and seek medical attention if severe pain, blistering, or swelling occurs.
INSERT INTO "drug_generic" VALUES(492, 'Anthralin (Dithranol) topical', 'Anthralin', 'D05AC01', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Severe Skin Irritation", "severity": "High", "trigger_condition": "Application to normal skin or sensitive areas", "message": "STOP: Anthralin is a severe irritant. Apply ONLY to quiescent or chronic psoriasis plaques. Do not apply to the face, genitalia, or skin folds. Wash hands thoroughly immediately after application."}]', '**Severe Irritation:** Anthralin is a potent skin irritant. Avoid contact with eyes, mucous membranes, face, genitalia, and intertriginous areas (skin folds). If severe redness or blistering is observed on surrounding normal skin, reduce the frequency of application, decrease the concentration, or discontinue therapy.
INSERT INTO "drug_generic" VALUES(493, 'Olmesartan Medoxomil', 'Olmesartan Medoxomil', 'C09CA08', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue olmesartan as soon as pregnancy is detected."}]', '**Sprue-like Enteropathy:** Severe, chronic diarrhea with substantial weight loss has been reported months to years after drug initiation. Intestinal biopsies have demonstrated villous atrophy. If a patient develops these symptoms, exclude other etiologies and discontinue olmesartan if no other cause is found.
INSERT INTO "drug_generic" VALUES(494, 'Buprenorphine', 'Buprenorphine', 'N02AE01', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Life-Threatening Respiratory Depression", "severity": "High", "trigger_condition": "Initiation of therapy, dose increases, or concomitant use with CNS depressants", "message": "WARNING: Serious, life-threatening, or fatal respiratory depression may occur. Monitor closely. Concomitant use with benzodiazepines or alcohol significantly increases this risk."}, {"alert_type": "Addiction, Abuse, and Misuse", "severity": "High", "trigger_condition": "Prescribing for pain or opioid dependence", "message": "WARNING: Buprenorphine exposes patients to risks of opioid addiction, abuse, and misuse, which can lead to overdose and death. Assess risk prior to prescribing."}]', 'Accidental exposure, especially by children, to even one dose can result in a fatal overdose.
INSERT INTO "drug_generic" VALUES(495, 'Brivaracetam', 'Brivaracetam', 'N03AX23', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Suicidal Behavior and Ideation", "severity": "High", "trigger_condition": "Initiation or dose adjustment of antiepileptic therapy", "message": "STOP: Antiepileptic drugs increase the risk of suicidal thoughts or behavior. Monitor patients closely for the emergence or worsening of depression, suicidal thoughts or behavior, and any unusual changes in mood or behavior."}]', '**Suicidal Behavior and Ideation:** Antiepileptic drugs (AEDs) increase the risk of suicidal thoughts or behavior. Monitor for the emergence or worsening of depression, unusual changes in mood or behavior, or suicidal thoughts. Balance the risk of suicidal thoughts with the risk of untreated illness.
INSERT INTO "drug_generic" VALUES(496, 'Beclometasone + Formoterol + Glycopyrronium', 'Beclomethasone + Formoterol + Glycopyrrolate', 'R03AL09', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediately after inhalation", "message": "STOP: Paradoxical bronchospasm may occur with an immediate increase in wheezing and shortness of breath after dosing. Treat immediately with a fast-acting inhaled bronchodilator. Discontinue therapy and institute alternative treatment."}]', '**Not for Acute Use:** This medicinal product is not indicated for the treatment of acute episodes of bronchospasm or to treat an acute disease exacerbation (i.e., as a rescue therapy).
INSERT INTO "drug_generic" VALUES(497, 'Istradefylline', 'Istradefylline', 'N04BX04', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Dyskinesia and Impulse Control Disorders", "severity": "High", "trigger_condition": "Coadministration with levodopa or other Parkinson''s medications", "message": "STOP: May cause or exacerbate dyskinesia. Patients may also experience intense urges (e.g., gambling, sexual, spending) and the inability to control them. Monitor closely and consider dose reduction or discontinuation if these occur."}]', '**Dyskinesia:** Coadministration with levodopa may cause dyskinesia or exacerbate preexisting dyskinesia. Monitor patients closely and consider adjusting the dose of levodopa or istradefylline if dyskinesia becomes problematic.
INSERT INTO "drug_generic" VALUES(498, 'Zinc Acetate Dihydrate', 'Zinc Acetate', 'A16AX05', 0, 0, 1, 0, 1, 1, 1, 0, '[]', 'Use with caution in patients with acute renal failure, as zinc is primarily excreted via the feces but renal impairment may alter overall trace element balance.
INSERT INTO "drug_generic" VALUES(499, 'Oxyphenonium Bromide 1% Eye prep', 'Oxyphenonium Bromide 1% Ophthalmic Solution', 'S01FA06', 0, 0, 0, 0, 0, 0, 0, 0, '[]', '**Systemic Absorption:** Although applied topically to the eye, systemic absorption can occur, leading to anticholinergic side effects. Use with caution in patients with a history of high blood pressure, cardiovascular disease, or hyperthyroidism.
INSERT INTO "drug_generic" VALUES(500, 'Rasagiline', 'Rasagiline', 'N04BD02', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Serotonin Syndrome and Hypertensive Crisis", "severity": "High", "trigger_condition": "Concomitant use with other MAOIs, SSRIs, SNRIs, or pethidine", "message": "STOP: Concomitant use with other MAOIs, pethidine, or certain antidepressants can cause fatal serotonin syndrome or hypertensive crisis. A 14-day washout period is required."}]', '- **Hypertension:** May cause hypertension or exacerbate pre-existing hypertension. Monitor blood pressure regularly. Antihypertensive medications may require adjustment.
INSERT INTO "drug_generic" VALUES(501, 'Alverine Citrate', 'Alverine', 'A03AX08', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "Hypersensitivity to alverine", "message": "STOP: Severe allergic reactions, including anaphylaxis, have been reported. Discontinue immediately if signs of hypersensitivity occur."}]', '**Hepatic and Renal Impairment:** Use with caution in patients with hepatic or renal impairment, as the drug is metabolized in the liver and excreted by the kidneys.
INSERT INTO "drug_generic" VALUES(502, 'Benzocaine + Butamben + Tetracaine topical', 'Benzocaine, Butamben, and Tetracaine', 'N01BA52', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Methemoglobinemia Risk", "severity": "High", "trigger_condition": "Use of benzocaine-containing products", "message": "STOP: Benzocaine can cause methemoglobinemia, a serious and potentially fatal condition. Monitor for cyanosis, headache, rapid heart rate, shortness of breath, and lightheadedness. Do not use in children under 2 years of age without strict medical supervision."}]', '**Systemic Absorption:** Application to larger areas, application to inflamed or broken skin, or application for longer than recommended could result in sufficient systemic absorption to cause serious adverse reactions, including CNS toxicity and cardiovascular collapse.
INSERT INTO "drug_generic" VALUES(503, 'Tisagenlecleucel', 'Tisagenlecleucel', 'L01XL04', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cytokine Release Syndrome (CRS) and Neurological Toxicities", "severity": "High", "trigger_condition": "Post-infusion period (especially within the first 8 weeks)", "message": "STOP: Fatal or life-threatening Cytokine Release Syndrome (CRS) and severe neurological toxicities can occur. Ensure tocilizumab and emergency equipment are available prior to infusion. Monitor closely."}]', '**Cytokine Release Syndrome (CRS):** CRS, including fatal or life-threatening reactions, occurred following treatment in a majority of patients. Do not administer to patients with active infection or inflammatory disorders. Treat severe or life-threatening CRS with tocilizumab or tocilizumab and corticosteroids.
INSERT INTO "drug_generic" VALUES(504, 'Pregabalin', 'Pregabalin', 'N03AX16', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Suicidality and Angioedema", "severity": "High", "trigger_condition": "Initiation of therapy or dose changes", "message": "STOP: Antiepileptic drugs increase the risk of suicidal thoughts or behavior. Monitor for worsening depression or unusual mood changes. Life-threatening angioedema (face, tongue, glottis) can occur; discontinue immediately if respiratory compromise develops."}]', '- **Withdrawal Symptoms:** Abrupt discontinuation may cause insomnia, nausea, headache, anxiety, hyperhidrosis, and diarrhea. Taper gradually over a minimum of 1 week.
INSERT INTO "drug_generic" VALUES(505, 'Clobetasol + Ofloxacin + Ornidazole + Terbinafine topical', 'Clobetasol + Ofloxacin + Ornidazole + Terbinafine topical', 'D07CC01', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Skin Atrophy and Systemic Absorption", "severity": "High", "trigger_condition": "Prolonged use or application to large surface areas/face", "message": "STOP: Contains clobetasol, an ultra-high potency corticosteroid. Do not use on the face, groin, or axillae. Prolonged use can cause severe skin atrophy, striae, and systemic absorption leading to HPA axis suppression."}]', '**Skin Atrophy and Systemic Absorption:** Contains clobetasol, an ultra-high potency topical corticosteroid. Prolonged use can cause skin thinning, striae, and telangiectasia. Systemic absorption can lead to reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and weight gain. Limit use to short durations (e.g., 1-2 weeks).
INSERT INTO "drug_generic" VALUES(506, 'Promethazine Theoclate', 'Promethazine Teoclate', 'R06AD05', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fatal Respiratory Depression", "severity": "High", "trigger_condition": "Use in pediatric patients under 2 years of age", "message": "STOP: Promethazine is CONTRAINDICATED in children younger than 2 years due to the risk of fatal respiratory depression. Use with extreme caution in older children."}]', '- **Respiratory Conditions:** Use with caution in patients with asthma, bronchitis, or bronchiectasis, as anticholinergic effects may thicken secretions.
INSERT INTO "drug_generic" VALUES(507, 'Emtricitabine + Tenofovir DF + Efavirenz', 'Efavirenz, Emtricitabine, and Tenofovir Disoproxil Fumarate', 'J05AR06', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatitis B Exacerbation", "severity": "High", "trigger_condition": "Co-infection with Hepatitis B Virus (HBV)", "message": "STOP: Severe acute exacerbations of hepatitis B have been reported in patients who are co-infected with HBV and HIV-1 and have discontinued products containing emtricitabine and/or tenofovir. Monitor hepatic function closely."}, {"alert_type": "Psychiatric Symptoms", "severity": "High", "trigger_condition": "History of psychiatric disorders", "message": "Caution: Efavirenz is associated with severe psychiatric symptoms, including severe depression, suicidal ideation, and aggressive behavior. Monitor patients closely."}]', '**Psychiatric and Nervous System Symptoms:** Efavirenz frequently causes central nervous system symptoms (dizziness, insomnia, impaired concentration, somnolence, abnormal dreams) and severe psychiatric adverse events. Administering at bedtime may improve tolerability.
INSERT INTO "drug_generic" VALUES(508, 'Isotretinoin 0.05% Topical', 'Isotretinoin Topical', 'D10AD04', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Teratogenicity Risk", "severity": "High", "trigger_condition": "Use in pregnant women or women of childbearing potential without contraception", "message": "STOP: Although systemic absorption from topical application is low, isotretinoin is a known teratogen. Use is strictly contraindicated during pregnancy."}]', '**Photosensitivity:** Increased susceptibility to UV light. Avoid prolonged exposure to sunlight or artificial UV light. Use broad-spectrum sunscreen and protective clothing.
INSERT INTO "drug_generic" VALUES(509, 'Vitamin A, D, B1, B2, B6, C, E, Nicotinamide, Cod liver oil (Multivitamin with Cod Liver Oil)', 'Multivitamins with Cod Liver Oil', 'A11AB', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Vitamin A Toxicity", "severity": "Medium", "trigger_condition": "Overdosage or concurrent use of other Vitamin A supplements", "message": "STOP: Cod liver oil is naturally high in Vitamin A. Excessive intake can lead to hypervitaminosis A, which causes hepatotoxicity and is highly teratogenic in pregnancy. Do not exceed the recommended dose."}]', '**Accumulation Risk:** Fat-soluble vitamins (A, D, E) accumulate in the body. Do not use continuously at high doses without medical supervision.
INSERT INTO "drug_generic" VALUES(510, 'Etodolac', 'Etodolac', 'M01AB08', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke, which can be fatal. This risk may occur early in treatment and may increase with duration of use."}, {"alert_type": "Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "STOP: NSAIDs cause an increased risk of serious gastrointestinal (GI) adverse events including bleeding, ulceration, and perforation of the stomach or intestines, which can be fatal. These events can occur at any time during use and without warning symptoms."}]', '**Cardiovascular Disease:** Use with caution in patients with a history of congestive heart failure, hypertension, or cardiovascular disease due to the risk of fluid retention and edema.
INSERT INTO "drug_generic" VALUES(511, 'Magnesium Hydroxide', 'Magnesium Hydroxide', 'A02AA04', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypermagnesemia in Renal Failure", "severity": "High", "trigger_condition": "Severe renal impairment", "message": "STOP: Magnesium hydroxide is renally excreted. Use in patients with severe renal impairment can lead to fatal hypermagnesemia, characterized by hypotension, respiratory depression, and cardiac arrest."}]', '**Renal Impairment:** Use with caution in patients with mild to moderate renal impairment. Monitor for signs of magnesium toxicity.
INSERT INTO "drug_generic" VALUES(512, 'Recombinant Human Follicle Stimulating Hormone', 'Follitropin alfa / Follitropin beta', 'G03GA05', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Ovarian Hyperstimulation Syndrome (OHSS)", "severity": "High", "trigger_condition": "Rapid rise in serum estradiol or development of multiple large follicles", "message": "STOP: Severe, potentially life-threatening OHSS can occur. Monitor follicular development and estradiol levels closely. If OHSS is suspected, withhold hCG administration and advise the patient to avoid intercourse."}]', '**Ovarian Hyperstimulation Syndrome (OHSS):** Characterized by severe pelvic pain, abdominal distension, nausea, vomiting, weight gain, dyspnea, and oliguria. Can progress to hypovolemia, hemoconcentration, electrolyte imbalances, ascites, pleural effusions, and thromboembolic events. Withhold hCG if estradiol levels rise too rapidly or if multiple follicles develop.
INSERT INTO "drug_generic" VALUES(513, 'Relugolix + Estradiol + Norethindrone', 'Relugolix/Estradiol/Norethindrone acetate', 'H01CC54', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Thromboembolic Disorders", "severity": "High", "trigger_condition": "History of or high risk for arterial or venous thrombotic events", "message": "STOP: Estrogen and progestin combinations increase the risk of DVT, PE, stroke, and MI. Contraindicated in women with a high risk of arterial or venous thrombotic diseases."}]', '**Thromboembolic Disorders:** Increases the risk of thrombotic or thromboembolic disorders. Discontinue immediately if an event occurs or is suspected. Discontinue at least 4 to 6 weeks before surgery associated with an increased risk of thromboembolism.
INSERT INTO "drug_generic" VALUES(514, 'Piperacillin', 'Piperacillin', 'J01CA12', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Patient history of penicillin or cephalosporin allergy", "message": "STOP: Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. Verify patient allergy history before prescribing."}]', '**Hypersensitivity:** Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. Cross-reactivity with cephalosporins and other beta-lactams can occur. Discontinue immediately if an allergic reaction occurs.
INSERT INTO "drug_generic" VALUES(515, 'Ipratropium Bromide Nasal prep', 'Ipratropium Bromide Nasal Spray', 'R01AX03', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Ocular Complications", "severity": "Medium", "trigger_condition": "Accidental spraying into the eyes", "message": "Avoid spraying into the eyes. Contact can cause temporary blurred vision, pupillary dilation (mydriasis), and precipitate acute angle-closure glaucoma in susceptible individuals."}]', '**Glaucoma:** Use with caution in patients with narrow-angle glaucoma or those susceptible to glaucoma. Accidental ocular exposure or systemic absorption can precipitate acute angle-closure glaucoma.
INSERT INTO "drug_generic" VALUES(516, 'Prednisolone Acetate + Sulfacetamide Sodium Eye prep', 'Prednisolone Acetate and Sulfacetamide Sodium Ophthalmic', 'S01CA02', 1, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Severe Hypersensitivity", "severity": "High", "trigger_condition": "Patient history of sulfonamide allergy", "message": "STOP: Fatalities have occurred due to severe reactions to sulfonamides, including Stevens-Johnson syndrome and toxic epidermal necrolysis. Verify sulfa allergy before prescribing."}]', '**Prolonged Use:** Use for short-term therapy only. Prolonged use of corticosteroids may result in glaucoma with damage to the optic nerve, defects in visual acuity and fields of vision, and posterior subcapsular cataract formation. Intraocular pressure (IOP) must be monitored routinely if used for 10 days or longer.
INSERT INTO "drug_generic" VALUES(517, 'Oxymetazoline eye prep', 'Oxymetazoline ophthalmic', 'S01GA04', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "Moderate", "trigger_condition": "Patients with severe or unstable cardiovascular disease", "message": "Caution: Alpha-adrenergic agonists may impact blood pressure. Monitor patients with severe cardiovascular disease, orthostatic hypotension, or uncontrolled hypertension."}]', '**Cardiovascular Effects:** Alpha-adrenergic agonists may impact blood pressure. Use with caution in patients with severe or unstable cardiovascular disease, orthostatic hypotension, and uncontrolled hypertension or hypotension. Advise patients to seek medical care if signs of cardiovascular disease or vascular insufficiency develop.
INSERT INTO "drug_generic" VALUES(518, 'Kanamycin', 'Kanamycin', 'J01GB04', 1, 1, 0, 1, 1, 1, 1, 0, '[{"alert_type": "Ototoxicity and Nephrotoxicity", "severity": "High", "trigger_condition": "Prolonged use, high doses, or preexisting renal impairment", "message": "STOP: Aminoglycosides can cause severe, irreversible bilateral auditory and vestibular ototoxicity, as well as nephrotoxicity. Monitor renal function and auditory status regularly. Adjust dose in renal impairment."}]', '**Ototoxicity:** Auditory toxicity is more common with kanamycin than with other aminoglycosides. High-frequency deafness usually occurs first and may only be detected by audiometry. Vestibular toxicity (vertigo, ataxia) can also occur. Risk increases with prolonged therapy, high doses, and renal impairment. Monthly audiometry is recommended during prolonged treatment.
INSERT INTO "drug_generic" VALUES(519, 'Gramacidin + Neomycin + Polymixin B (Eye prep)', 'Gramicidin / Neomycin / Polymyxin B', 'S01AA30', 1, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity and Anaphylaxis", "severity": "High", "trigger_condition": "Patient history of aminoglycoside or polymyxin hypersensitivity", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with other aminoglycosides is possible."}]', '**Superinfection Risk:** Prolonged use may result in the overgrowth of nonsusceptible organisms, including fungi. If superinfection occurs, discontinue use and institute alternative therapy.
INSERT INTO "drug_generic" VALUES(520, 'Diclofenac + Lidocaine Hydrochloride', 'Diclofenac / Lidocaine', 'M01AB05', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use of NSAIDs, including diclofenac", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal bleeding, ulceration, and perforation. Contraindicated for CABG perioperative pain."}]', '**Gastrointestinal Risk:** Monitor for signs of GI bleeding or ulceration, especially in the elderly or those with a history of peptic ulcer disease.
INSERT INTO "drug_generic" VALUES(521, 'Nystatin', 'Nystatin', 'A07AA02', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Not for Systemic Infections", "severity": "High", "trigger_condition": "Prescription for systemic fungal infections", "message": "STOP: Nystatin is not absorbed systemically from the intact gastrointestinal tract or skin. It is strictly contraindicated for the treatment of systemic mycoses."}]', 'Use with caution in immunocompromised patients, as clinical cure of oral candidiasis may require prolonged therapy or alternative systemic antifungal agents. If irritation or sensitization develops, treatment should be discontinued. Vaginal tablets may damage latex contraceptives (condoms, diaphragms); alternative contraceptive measures should be used during treatment. Not indicated for the treatment of systemic fungal infections.', '- **Oral Candidiasis (Thrush):** Prevention and treatment of candidal infections of the oral cavity.
INSERT INTO "drug_generic" VALUES(522, 'Nalidixic Acid', 'Nalidixic Acid', 'J01MB02', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Tendon Rupture and Arthropathy", "severity": "High", "trigger_condition": "Use in pediatric patients or elderly", "message": "STOP: Fluoroquinolones and related quinolones are associated with an increased risk of tendinitis and tendon rupture. Use with extreme caution in elderly patients and avoid in children under 18 years due to the risk of cartilage damage."}]', 'Use with extreme caution in patients with hepatic or moderate renal impairment, severe cerebral arteriosclerosis, or glucose-6-phosphate dehydrogenase (G6PD) deficiency due to the risk of hemolytic anemia.
INSERT INTO "drug_generic" VALUES(523, 'Amlexanox', 'Amlexanox', 'A01AD07', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Application Site Warning", "severity": "Low", "message": "For topical use on oral mucous membranes only. Avoid contact with the eyes. Wash hands thoroughly before and after application."}]', '**Contact Mucositis:** Discontinue treatment if a rash or contact mucositis develops at the application site.
INSERT INTO "drug_generic" VALUES(524, 'Clobetasol Propionate + Neomycin Sulphate + Nystatin topical', 'Clobetasol + Neomycin + Nystatin Topical', 'D07CD01', 1, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "High Potency Corticosteroid Toxicity", "severity": "High", "trigger_condition": "Use exceeding 7 days or application under occlusion", "message": "Contains clobetasol, a super-high potency corticosteroid. Limit use to a maximum of 7 days without medical supervision. Do not use occlusive dressings due to the high risk of adrenal suppression."}]', '**HPA Axis Suppression:** Clobetasol can cause profound, reversible HPA axis suppression. Avoid long-term continuous therapy, especially in infants and children.
INSERT INTO "drug_generic" VALUES(525, 'Semaglutide for Obesity (Weight management)', 'Semaglutide', 'A10BJ06', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Thyroid C-cell Tumors Risk", "severity": "High", "trigger_condition": "Personal or family history of Medullary Thyroid Carcinoma (MTC) or Multiple Endocrine Neoplasia syndrome type 2 (MEN 2)", "message": "STOP: Contraindicated in patients with a personal or family history of MTC or MEN 2 due to the risk of thyroid C-cell tumors."}]', '**Acute Pancreatitis:** Has occurred in clinical trials. Discontinue promptly if pancreatitis is suspected. Do not restart if pancreatitis is confirmed.
INSERT INTO "drug_generic" VALUES(526, 'Pemetrexed', 'Pemetrexed', 'L01BA04', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Myelosuppression and Renal Failure", "severity": "High", "trigger_condition": "Failure to premedicate with folic acid and vitamin B12, or use in severe renal impairment", "message": "STOP: Pemetrexed causes severe myelosuppression and renal failure. Patients MUST be premedicated with folic acid and vitamin B12 to reduce toxicity. Do NOT administer if CrCl is <45 mL/min."}]', 'Monitor complete blood counts (CBC) with differential and platelet counts before each dose; do not initiate a cycle unless ANC is ≥1500/mm³ and platelets are ≥100,000/mm³. Monitor renal function (CrCl) prior to each dose. Premedication with folic acid and vitamin B12 is mandatory to reduce hematologic and gastrointestinal toxicity. Premedication with a corticosteroid (e.g., dexamethasone) is required to reduce the incidence and severity of cutaneous reactions. Use with caution in patients with hepatic impairment. Avoid concurrent use of NSAIDs in patients with mild to moderate renal impairment.', '- **Non-Squamous Non-Small Cell Lung Cancer (NSCLC):**
INSERT INTO "drug_generic" VALUES(527, 'Pramoxine topical', 'Pramoxine', 'D04AB07', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Application Limits:** Do not exceed the daily recommended dosage. Avoid application to large areas of the body to minimize the risk of systemic absorption.
INSERT INTO "drug_generic" VALUES(528, 'Axicabtagene Ciloleucel', 'Axicabtagene Ciloleucel', 'L01XL03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cytokine Release Syndrome (CRS) and Neurological Toxicities", "severity": "High", "trigger_condition": "Post-infusion period (especially within the first 8 weeks)", "message": "STOP: Fatal or life-threatening Cytokine Release Syndrome (CRS) and severe neurological toxicities can occur. Ensure tocilizumab and emergency equipment are available prior to infusion. Monitor closely."}]', '**Cytokine Release Syndrome (CRS):** CRS, including fatal or life-threatening reactions, occurred in patients receiving axicabtagene ciloleucel. Do not administer to patients with active infection or inflammatory disorders. Treat severe or life-threatening CRS with tocilizumab or tocilizumab and corticosteroids.
INSERT INTO "drug_generic" VALUES(529, 'Cetuximab', 'Cetuximab', 'L01FE01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Infusion Reactions and Cardiopulmonary Arrest", "severity": "High", "trigger_condition": "During or immediately following intravenous infusion", "message": "STOP: Severe infusion reactions (some fatal) and cardiopulmonary arrest can occur. Immediately interrupt and permanently discontinue cetuximab for serious infusion reactions. Closely monitor serum electrolytes during and after therapy."}]', '**Infusion Reactions:** Severe infusion reactions occurred in approximately 3% of patients, with fatal outcomes reported. Immediately interrupt and permanently discontinue cetuximab for serious infusion reactions. Monitor patients closely following infusion.
INSERT INTO "drug_generic" VALUES(530, 'Aspirin + Clopidogrel', 'Aspirin and Clopidogrel', 'B01AC30', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Bleeding Risk", "severity": "High", "trigger_condition": "Dual antiplatelet therapy", "message": "STOP: This combination significantly increases the risk of major, potentially fatal bleeding (GI, intracranial). Monitor closely for signs of bleeding. Discontinue 5-7 days prior to elective surgery."}, {"alert_type": "CYP2C19 Poor Metabolizers", "severity": "High", "trigger_condition": "Patients with genetic CYP2C19 deficiency", "message": "STOP: Clopidogrel is a prodrug requiring CYP2C19 for activation. Poor metabolizers will have reduced antiplatelet effect and higher rates of cardiovascular events. Consider alternative P2Y12 inhibitors (e.g., ticagrelor, prasugrel)."}]', '**Gastrointestinal Bleeding:** High risk of GI ulceration and bleeding. Use with caution in patients with a history of peptic ulcer disease. Consider concurrent use of a PPI (but avoid omeprazole/esomeprazole).
INSERT INTO "drug_generic" VALUES(531, 'Desoximetasone Topical', 'Desoximetasone', 'D07AC03', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "HPA Axis Suppression", "severity": "High", "trigger_condition": "Prolonged use, use over large surface areas, or use under occlusion", "message": "Systemic absorption of topical corticosteroids can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and unmask latent diabetes. Limit use of medium to high potency steroids to less than 2 weeks."}]', '- **Pediatric Patients:** Children have a larger skin surface area to body weight ratio, making them more susceptible to systemic toxicity, HPA axis suppression, and Cushing''s syndrome. Chronic use may interfere with growth and development.
INSERT INTO "drug_generic" VALUES(532, 'Hyoscine Butyl Bromide', 'Scopolamine Butylbromide', 'A03BB01', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Anaphylaxis and Severe Hypersensitivity", "severity": "High", "trigger_condition": "Parenteral administration", "message": "STOP: Severe hypersensitivity reactions, including anaphylactic shock, have been reported with parenteral administration. Ensure resuscitation equipment is available when administering IV/IM."}]', 'Use with caution in patients with cardiac conditions (e.g., coronary artery disease, tachyarrhythmias, heart failure, hypertension) as it may induce tachycardia.
INSERT INTO "drug_generic" VALUES(533, 'Carbidopa + Levodopa', 'Carbidopa / Levodopa', 'N04BA02', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Sudden Sleep Onset", "severity": "High", "trigger_condition": "During activities of daily living", "message": "STOP: Patients may fall asleep without warning during daily activities, including driving. Advise patients of this risk and consider dose reduction or discontinuation if it occurs."}, {"alert_type": "Withdrawal-Emergent Hyperpyrexia", "severity": "High", "trigger_condition": "Abrupt discontinuation or rapid dose reduction", "message": "STOP: Abrupt withdrawal can cause a symptom complex resembling Neuroleptic Malignant Syndrome (NMS), characterized by hyperpyrexia, muscle rigidity, and altered consciousness. Taper gradually."}]', '**Cardiovascular Ischemic Events:** Monitor patients with a history of cardiovascular disease or myocardial infarction who have residual arrhythmias. Initiate therapy in a facility with cardiac monitoring capabilities.
INSERT INTO "drug_generic" VALUES(534, 'Moxidectin', 'Moxidectin', 'P02CF03', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Severe Encephalopathy Risk", "severity": "High", "trigger_condition": "Co-infection with Loa loa", "message": "Patients co-infected with Loa loa may develop serious or fatal encephalopathy. Screen for loiasis prior to treatment in patients from endemic areas."}]', '**Orthostatic Hypotension:** Patients may develop symptomatic orthostatic hypotension with an inability to stand without support after lying down for 5 minutes. Advise patients experiencing dizziness or lightheadedness to lie down until symptoms resolve.
INSERT INTO "drug_generic" VALUES(535, 'Bendamustine', 'Bendamustine', 'L01AA09', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Myelosuppression", "severity": "High", "trigger_condition": "Baseline cytopenias or concurrent myelosuppressive therapy", "message": "STOP: Severe and potentially fatal myelosuppression (leukopenia, neutropenia, thrombocytopenia, anemia) can occur. Monitor complete blood counts frequently and delay or reduce dose as necessary."}, {"alert_type": "Infusion Reactions and Anaphylaxis", "severity": "High", "trigger_condition": "During or shortly after IV infusion", "message": "WARNING: Severe infusion reactions and anaphylaxis can occur. Monitor clinically during and after infusion. Premedicate in subsequent cycles for milder reactions; discontinue for severe reactions."}]', '**Myelosuppression:** Severe and potentially fatal myelosuppression may occur. Monitor complete blood counts (CBC) prior to each cycle and frequently during treatment. Delay or reduce the dose for severe cytopenias.
INSERT INTO "drug_generic" VALUES(536, 'Diphenhydramine + L-Menthol', 'Diphenhydramine + Levomenthol', 'R05CA10', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "CNS Depression and Anticholinergic Toxicity", "severity": "Moderate", "trigger_condition": "Concomitant use with other CNS depressants or in elderly patients", "message": "Caution: May cause significant drowsiness and anticholinergic effects. Avoid concurrent use with alcohol, sedatives, or MAOIs. Use with extreme caution in the elderly due to risk of confusion and urinary retention."}]', '**CNS Depression:** May cause significant drowsiness and impair the physical or mental abilities required for driving or operating machinery.
INSERT INTO "drug_generic" VALUES(537, 'Sertaconazole Topical', 'Sertaconazole', 'D01AC14', 0, 0, 1, 1, 0, 1, 0, 0, '[]', '**Local Irritation:** Discontinue use if irritation, severe redness, itching, or chemical sensitivity develops at the application site.
INSERT INTO "drug_generic" VALUES(538, 'Etomidate', 'Etomidate', 'N01AX07', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Adrenal Suppression", "severity": "High", "trigger_condition": "Administration of etomidate", "message": "STOP: Etomidate causes reversible, dose-dependent suppression of adrenal steroidogenesis (cortisol and aldosterone) lasting up to 24 hours after a single dose. It is not intended for prolonged infusion and should be used with extreme caution in critically ill patients (e.g., sepsis) where adrenal suppression can be fatal."}]', '**Adrenal Suppression:** Inhibits 11-beta-hydroxylase, leading to decreased cortisol and aldosterone production. Avoid continuous infusion. Consider prophylactic corticosteroids in critically ill patients.
INSERT INTO "drug_generic" VALUES(539, 'Ciclesonide', 'Ciclesonide', 'R03BA08', 0, 0, 1, 1, 0, 1, 1, 1, '[{"alert_type": "Acute Asthma Exacerbation", "severity": "High", "trigger_condition": "Use during acute bronchospasm", "message": "STOP: Ciclesonide is not a bronchodilator and is not indicated for the rapid relief of acute bronchospasm or status asthmaticus. Use a short-acting beta2-agonist for acute symptoms."}]', '**Oral Candidiasis:** Localized infections of the mouth and pharynx with Candida albicans can occur. Advise patients to rinse their mouth with water and spit it out after each inhalation to minimize risk.
INSERT INTO "drug_generic" VALUES(540, 'Azathioprine', 'Azathioprine', 'L04AX01', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Malignancy and Myelosuppression", "severity": "High", "trigger_condition": "Long-term use or concurrent use with other immunosuppressants", "message": "STOP: Chronic immunosuppression increases the risk of malignancy (e.g., lymphoma, skin cancer). Severe myelosuppression may occur, especially in patients with TPMT or NUDT15 deficiency. Monitor CBC closely."}]', '- **Malignancy Risk:** Increased risk of developing lymphomas (including rare, fatal hepatosplenic T-cell lymphoma in IBD patients) and skin cancers. Instruct patients to use high-factor sunscreen and wear protective clothing.
INSERT INTO "drug_generic" VALUES(541, 'Multivitamin-Multimineral A-Z preparations for Teen Boys', 'Multivitamin with Minerals', 'A11AA03', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Masking of Pernicious Anemia:** Folic acid in doses above 0.1 mg daily may obscure pernicious anemia; hematological remission can occur while neurological manifestations remain progressive.
INSERT INTO "drug_generic" VALUES(542, 'Zinc Oxide 40% Topical', 'Zinc Oxide Topical', 'D02AB', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**External Use Only:** Avoid contact with the eyes. Do not ingest.
INSERT INTO "drug_generic" VALUES(543, 'Betamethasone 0.05% + Salicylic Acid 2% topical', 'Betamethasone and Salicylic Acid', 'D07XC01', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Salicylate Toxicity", "severity": "Medium", "trigger_condition": "Application to large surface areas or under occlusion", "message": "STOP: Application to large areas of the body or under occlusive dressings can lead to systemic absorption of salicylic acid, causing salicylism (tinnitus, nausea, vomiting, dizziness)."}]', '**Systemic Absorption:** Systemic absorption of topical corticosteroids can produce reversible HPA axis suppression, Cushing''s syndrome, and hyperglycemia. Risk increases with prolonged use, application to large surface areas, or use of occlusive dressings.
INSERT INTO "drug_generic" VALUES(544, 'Gentamicin 0.3%  E/E prep', 'Gentamicin', 'S01AA11', 1, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Ototoxicity Risk", "severity": "High", "trigger_condition": "Administration into an ear with a perforated tympanic membrane", "message": "STOP: Do not administer gentamicin ear drops if the patient has a known or suspected perforated tympanic membrane. Direct exposure to the middle/inner ear can cause irreversible ototoxicity and deafness."}]', 'Prolonged use of topical ophthalmic or otic antibiotics may result in the overgrowth of nonsusceptible organisms, including fungi. If superinfection occurs, discontinue use and institute appropriate alternative therapy. Ophthalmic ointments may retard corneal healing. Systemic absorption is generally minimal; however, caution is advised in patients with severe renal impairment or those receiving systemic aminoglycosides, as additive toxicity (nephrotoxicity and ototoxicity) can theoretically occur. Do not use otic preparations if the tympanic membrane is perforated due to the high risk of irreversible ototoxicity. Patients should not wear contact lenses during treatment of an ocular infection.', '- **Superficial Ophthalmic Infections:** Treatment of conjunctivitis, keratitis, keratoconjunctivitis, corneal ulcers, blepharitis, blepharoconjunctivitis, acute meibomianitis, and dacryocystitis caused by susceptible strains of microorganisms.
INSERT INTO "drug_generic" VALUES(545, 'Sotalol Hydrochloride', 'Sotalol', 'C07AA07', 0, 1, 0, 0, 1, 1, 1, 1, '[{"alert_type": "Proarrhythmia and QT Prolongation", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "STOP: Sotalol can cause life-threatening ventricular arrhythmias, particularly Torsades de Pointes, due to QT prolongation. Initiate or titrate only in a facility with continuous ECG monitoring and cardiac resuscitation capabilities."}]', 'Initiation and dose titration must occur in a hospital setting with continuous ECG monitoring and assessment of creatinine clearance. Monitor QT interval closely; the risk of Torsades de Pointes is dose-related and increases with QT prolongation. Correct hypokalemia and hypomagnesemia prior to initiation and monitor electrolytes regularly. Use with extreme caution in patients with well-compensated heart failure, as beta-blockade may further depress myocardial contractility. May mask symptoms of hypoglycemia (e.g., tachycardia) in diabetic patients and symptoms of hyperthyroidism. Avoid abrupt withdrawal; taper gradually over 1-2 weeks to prevent exacerbation of angina, myocardial infarction, or thyroid storm. Use with caution in patients with myasthenia gravis or psoriasis, as symptoms may worsen. Adjust dose carefully in renal impairment.', '- **Life-Threatening Ventricular Arrhythmias:** Indicated for the treatment of documented, life-threatening ventricular arrhythmias, such as sustained ventricular tachycardia.
INSERT INTO "drug_generic" VALUES(546, 'Clevidipine', 'Clevidipine', 'C08CA16', 0, 1, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Severe Hypotension and Reflex Tachycardia", "severity": "High", "trigger_condition": "Rapid upward titration or administration in severe aortic stenosis", "message": "STOP: Rapid upward titration can cause severe hypotension and reflex tachycardia. Clevidipine is contraindicated in severe aortic stenosis due to the risk of cardiovascular collapse."}]', '**Hypotension and Reflex Tachycardia:** Rapid upward titration can lead to profound hypotension and reflex tachycardia. Titrate carefully and monitor blood pressure and heart rate continuously during infusion and until vital signs stabilize.
INSERT INTO "drug_generic" VALUES(547, 'Mitomycin', 'Mitomycin C', 'L01DC03', 1, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Systemic administration", "message": "STOP: Mitomycin causes severe, cumulative, and delayed bone marrow suppression (thrombocytopenia and leukopenia). Monitor CBC frequently. Do not administer if platelets <100,000/mm\u00b3 or WBC <4,000/mm\u00b3."}, {"alert_type": "Hemolytic Uremic Syndrome (HUS)", "severity": "High", "trigger_condition": "Cumulative doses >50 mg/m\u00b2", "message": "STOP: A severe, potentially fatal syndrome of microangiopathic hemolytic anemia, thrombocytopenia, and irreversible renal failure (HUS) can occur. Monitor renal function and for signs of hemolysis."}]', 'Administer under the supervision of a physician experienced in cancer chemotherapy. Extravasation during IV administration can cause severe local tissue necrosis and sloughing; ensure proper needle placement and monitor the infusion site closely. Pulmonary toxicity, including acute shortness of breath and severe bronchospasm, has been reported, particularly when used with vinca alkaloids. Monitor renal function (serum creatinine) before each dose; do not administer if serum creatinine is >1.7 mg/dL. Use with caution in patients with active infections, including varicella. May cause generalized weakness and lethargy; advise patients to avoid driving if affected.', '- **Solid Tumors:** Palliative treatment of disseminated adenocarcinoma of the stomach or pancreas, in combination with other approved chemotherapeutic agents.
INSERT INTO "drug_generic" VALUES(548, 'Doxercalciferol', 'Doxercalciferol', 'A11CC04', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "High", "trigger_condition": "Concomitant use with high-dose calcium preparations, thiazide diuretics, or other vitamin D compounds", "message": "STOP: Severe hypercalcemia can occur, leading to cardiac arrhythmias and seizures. Monitor serum calcium and intact PTH closely."}]', '**Hypercalcemia:** Elevated serum calcium levels can occur during treatment, potentially leading to life-threatening cardiac arrhythmias and seizures. The risk is significantly increased when administered concomitantly with high-dose calcium preparations, thiazide diuretics, or other vitamin D compounds. Severe hypercalcemia requires immediate emergency intervention.
INSERT INTO "drug_generic" VALUES(549, 'Lyophilized Bacterial Lysate', 'Lyophilized Bacterial Lysate', 'L03AX', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '- **Pneumonia Prevention:** No clinical data demonstrate that this drug prevents pneumonia. It is not recommended for the prevention of pneumonia.
INSERT INTO "drug_generic" VALUES(550, 'Inotuzumab', 'Inotuzumab ozogamicin', 'L01FB01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity and VOD", "severity": "High", "trigger_condition": "Development of rapid weight gain, right upper quadrant pain, hepatomegaly, or hyperbilirubinemia", "message": "STOP: Severe, life-threatening, and fatal hepatotoxicity, including veno-occlusive disease (VOD) / sinusoidal obstruction syndrome (SOS), has occurred. Monitor liver tests closely. Interrupt or discontinue therapy if VOD is suspected."}, {"alert_type": "Post-Transplant Mortality", "severity": "High", "trigger_condition": "Patients proceeding to hematopoietic stem cell transplant (HSCT)", "message": "WARNING: There is an increased risk of post-transplant non-relapse mortality, primarily due to VOD, in patients receiving inotuzumab prior to HSCT."}]', '**Hepatotoxicity and Veno-occlusive Disease (VOD):** Fatal and life-threatening VOD (also known as sinusoidal obstruction syndrome) has been reported. Risk factors include prior or ongoing liver disease, prior HSCT, and older age. Monitor liver function tests (ALT, AST, total bilirubin) prior to each dose. If VOD is suspected, withhold the drug and treat supportively.
INSERT INTO "drug_generic" VALUES(551, 'Dabigatran etexilate', 'Dabigatran Etexilate', 'B01AE07', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Premature Discontinuation Risk", "severity": "High", "trigger_condition": "Stopping therapy without alternative anticoagulation", "message": "Premature discontinuation of any oral anticoagulant, including dabigatran, increases the risk of thrombotic events. If discontinued for reasons other than pathological bleeding, consider coverage with another anticoagulant."}, {"alert_type": "Spinal/Epidural Hematoma", "severity": "High", "trigger_condition": "Neuraxial anesthesia or spinal puncture", "message": "Epidural or spinal hematomas may occur in patients treated with dabigatran who are receiving neuraxial anesthesia or undergoing spinal puncture. These hematomas may result in long-term or permanent paralysis."}]', 'Monitor patients frequently for signs and symptoms of neurological impairment if undergoing neuraxial intervention; treat urgently if observed.
INSERT INTO "drug_generic" VALUES(552, 'Meclizine Hydrochloride', 'Meclizine', 'R06AE05', 0, 0, 1, 0, 1, 0, 0, 0, '[]', '**CNS Depression:** Meclizine may impair the mental and physical abilities required for the performance of potentially hazardous tasks, such as driving a vehicle or operating machinery.
INSERT INTO "drug_generic" VALUES(553, 'Ibuprofen + Pseudoephedrine', 'Ibuprofen and Pseudoephedrine', 'M01AE51', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Patient with history of cardiovascular disease or peptic ulcer disease", "message": "STOP: NSAIDs increase the risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation."}]', '**Cardiovascular Risk:** NSAIDs, excluding aspirin, increase the risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke, which can be fatal. This risk may occur early in treatment and may increase with duration of use. Pseudoephedrine may exacerbate poorly controlled hypertension; use with caution in patients with underlying cardiovascular risks.
INSERT INTO "drug_generic" VALUES(554, 'Oxymorphone Hydrochloride', 'Oxymorphone Hydrochloride', 'N02AA02', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Addiction, Abuse, and Misuse", "severity": "High", "trigger_condition": "Prescription of opioid therapy", "message": "STOP: Oxymorphone exposes patients and other users to the risks of opioid addiction, abuse, and misuse, which can lead to overdose and death. Assess each patient''s risk prior to prescribing."}, {"alert_type": "Life-Threatening Respiratory Depression", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "Serious, life-threatening, or fatal respiratory depression may occur. Monitor closely, especially during initiation or following a dose increase."}]', '**Addiction, Abuse, and Misuse:** Risk of opioid addiction, abuse, and misuse, which can lead to overdose and death. Assess each patient''s risk prior to prescribing and monitor all patients regularly.
INSERT INTO "drug_generic" VALUES(555, 'Nedocromil sodium', 'Nedocromil sodium', 'R03BC03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Acute Bronchospasm", "severity": "High", "trigger_condition": "Administration during an acute asthma attack", "message": "STOP: Nedocromil is a prophylactic agent and is not indicated for the reversal of acute bronchospasm or status asthmaticus."}]', 'Nedocromil is intended for maintenance therapy and should not be used for the relief of acute bronchospasm or status asthmaticus. Patients must be advised to continue therapy even during asymptomatic periods to maintain efficacy. Eosinophilic pneumonia has been rarely reported; discontinue if pulmonary infiltrates with eosinophilia occur. Use with caution in children under 6 years of age as safety and efficacy are not fully established. Monitor patients for the development of local irritation or hypersensitivity reactions.', '- **Chronic Asthma:** Prophylactic management of mild to moderate persistent asthma in adults and pediatric patients.
INSERT INTO "drug_generic" VALUES(556, 'Halobetasol Propionate 0.05% Topical', 'Halobetasol Propionate', 'D07AD02', 0, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Ultra-High Potency Corticosteroid", "severity": "High", "trigger_condition": "Use exceeding 50g per week or duration longer than 2 weeks", "message": "STOP: Halobetasol is an ultra-high potency (Class I) topical corticosteroid. Do not exceed 50 g/week. Do not use for longer than 2 consecutive weeks due to the high risk of rapid HPA axis suppression and severe skin atrophy."}]', '**HPA Axis Suppression:** Systemic absorption of ultra-high potency topical corticosteroids rapidly causes reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria. Risk increases with application to large surface areas, prolonged use, or use of occlusive dressings.
INSERT INTO "drug_generic" VALUES(557, 'Povidone Iodine 7.5% Scrub', 'Povidone-Iodine Scrub', 'D08AG02', 1, 0, 0, 0, 1, 1, 0, 0, '[]', 'Avoid contact with eyes. Should not be used under occlusive dressings. Application to large areas of denuded skin may produce systemic adverse effects such as metabolic acidosis, hypernatremia, and impairment of renal function due to significant iodine absorption. Exercise special caution in patients with pre-existing renal insufficiency.', '- **Surgical Hand Scrub:** Pre-operative scrubbing and washing for healthcare professionals to reduce resident and transient skin flora.
INSERT INTO "drug_generic" VALUES(558, 'Ertapenem', 'Ertapenem', 'J01DH03', 1, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Hypersensitivity Risk", "severity": "High", "trigger_condition": "Patient history of severe hypersensitivity to penicillins, cephalosporins, or other beta-lactams", "message": "STOP: Severe and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. Cross-reactivity among beta-lactam antibiotics can occur. Verify allergy history before administration."}]', '**Central Nervous System Disorders:** Seizures and other CNS adverse experiences have been reported. Use with caution in patients with CNS disorders (e.g., brain lesions, history of seizures) or compromised renal function, as drug accumulation increases seizure risk.
INSERT INTO "drug_generic" VALUES(559, 'Mepyramine Maleate 2% Topical', 'Pyrilamine Maleate Topical', 'D04AA02', 0, 0, 0, 0, 0, 0, 1, 0, '[]', 'For external use only. Avoid application to broken, blistered, or oozing skin, as this increases systemic absorption. Prolonged use may lead to skin sensitization and contact dermatitis. Use with caution in the elderly and in patients with severe cardiovascular disorders, asthma, angle-closure glaucoma, urinary retention, prostatic hyperplasia, pyloroduodenal obstruction, epilepsy, or renal/hepatic impairment, particularly if applied over large areas where systemic absorption could occur. May cause drowsiness if absorbed systemically; caution is advised when driving or operating machinery.', '- **Pruritic Skin Disorders:** Symptomatic relief of itching, pain, and discomfort associated with insect bites, stings, nettle rash, and minor skin irritations.', '- **Hypersensitivity:** Contraindicated in patients with known hypersensitivity to mepyramine (pyrilamine) or any component of the formulation.
INSERT INTO "drug_generic" VALUES(560, 'Fluconazole', 'Fluconazole', 'J02AC01', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Drug Interaction / Arrhythmia Risk", "severity": "High", "trigger_condition": "Concurrent use of QT-prolonging drugs metabolized by CYP3A4", "message": "STOP: Fluclonazole is a potent CYP inhibitor. Co-administration with drugs like erythromycin, pimozide, or quinidine can cause fatal QT prolongation and Torsades de Pointes."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Patients with underlying liver disease", "message": "WARNING: Fluconazole has been associated with rare cases of serious hepatic toxicity, including fatalities. Monitor liver function tests closely."}]', '- **Hepatotoxicity:** Rare cases of serious hepatic toxicity, including fatalities, have occurred. Monitor LFTs; discontinue if clinical signs of liver disease develop.
INSERT INTO "drug_generic" VALUES(561, 'Brigatinib', 'Brigatinib', 'L01ED04', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Interstitial Lung Disease (ILD) / Pneumonitis", "severity": "High", "trigger_condition": "New or worsening respiratory symptoms", "message": "STOP: Severe, life-threatening, and fatal ILD/pneumonitis can occur, especially within the first week of treatment. Withhold drug for new or worsening respiratory symptoms and evaluate promptly."}]', '**Interstitial Lung Disease (ILD)/Pneumonitis:** Severe, life-threatening, and fatal ILD/pneumonitis can occur. Monitor for new or worsening respiratory symptoms, particularly during the first week of treatment. Withhold brigatinib and evaluate promptly; upon recovery, dose reduce or permanently discontinue.
INSERT INTO "drug_generic" VALUES(562, 'Ravuconazole', 'Fosravuconazole', 'D01BA03', 0, 0, 0, 0, 0, 0, 0, 0, '[]', '**Hepatotoxicity:** Liver dysfunction, including jaundice and elevated transaminases, has been reported. Monitor liver function tests periodically during treatment.
INSERT INTO "drug_generic" VALUES(563, 'Ceftaroline fosamil', 'Ceftaroline Fosamil', 'J01DI02', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypersensitivity and CDAD", "severity": "High", "trigger_condition": "History of severe beta-lactam allergy or development of severe diarrhea", "message": "Serious hypersensitivity reactions (anaphylaxis) can occur. Cross-reactivity with penicillins is possible. Clostridioides difficile-associated diarrhea (CDAD) has been reported; evaluate if diarrhea occurs."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. Use with caution in patients with a history of penicillin allergy.
INSERT INTO "drug_generic" VALUES(564, 'Benzoic Acid 6% + Salicylic Acid 3% topical', 'Benzoic Acid and Salicylic Acid (Whitfield''s Ointment)', 'D01AE20', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Low", "message": "For external use only. Avoid contact with the eyes, mouth, mucous membranes, and anogenital region. Do not apply to broken or inflamed skin."}]', '**Salicylism Risk:** Excessive, prolonged use of salicylic acid over large areas of the body can result in systemic absorption and symptoms of salicylism (tinnitus, nausea, vomiting, dizziness). Avoid prolonged use in high concentrations.
INSERT INTO "drug_generic" VALUES(565, 'Bimatoprost 0.03% + Timolol 0.5% eye prep', 'Bimatoprost and Timolol Ophthalmic', 'S01ED51', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Systemic Beta-Blocker Absorption", "severity": "High", "trigger_condition": "Administration in patients with cardiovascular or pulmonary disease", "message": "STOP: Timolol can be absorbed systemically. Severe respiratory reactions (including fatal bronchospasm in asthmatics) and cardiac reactions (fatalities in heart failure) have occurred. Contraindicated in asthma, severe COPD, sinus bradycardia, and overt heart failure."}]', '**Systemic Absorption of Beta-Blockers:** Timolol is a non-selective beta-blocker. Systemic absorption can occur, leading to cardiovascular and pulmonary adverse reactions similar to systemic beta-blockers. Use with extreme caution in patients with severe or unstable cardiovascular disease, and monitor for signs of cardiac failure or bronchospasm.
INSERT INTO "drug_generic" VALUES(566, 'Oxytocin', 'Oxytocin', 'H01BB02', 0, 1, 0, 1, 0, 1, 0, 0, '[{"alert_type": "Uterine Hyperstimulation and Fetal Distress", "severity": "High", "trigger_condition": "Intravenous infusion for labor induction", "message": "STOP: Oxytocin can cause uterine hypertonicity, spasm, tetanic contraction, or rupture of the uterus, leading to fetal bradycardia, hypoxia, and death. Continuous monitoring of uterine activity and fetal heart rate is mandatory."}, {"alert_type": "Water Intoxication", "severity": "High", "trigger_condition": "Prolonged IV infusion at high doses", "message": "Oxytocin has intrinsic antidiuretic effects. Prolonged IV infusion with large volumes of fluid can cause severe water intoxication, leading to seizures, coma, and maternal death."}]', '**Continuous Monitoring:** When used for labor induction or augmentation, continuous electronic monitoring of fetal heart rate and uterine contractions is mandatory. Discontinue immediately if uterine hyperactivity or fetal distress occurs.
INSERT INTO "drug_generic" VALUES(567, 'Dacomitinib', 'Dacomitinib', 'L01EB07', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Interstitial Lung Disease (ILD)", "severity": "High", "trigger_condition": "Development of unexplained pulmonary symptoms", "message": "STOP: Severe and fatal Interstitial Lung Disease (ILD)/pneumonitis can occur. Withhold treatment for suspected ILD and permanently discontinue if confirmed."}]', '**Interstitial Lung Disease (ILD):** Severe and fatal ILD/pneumonitis has occurred. Monitor patients for pulmonary symptoms indicative of ILD (e.g., dyspnea, cough, fever). Withhold dacomitinib and promptly investigate for ILD in any patient who presents with worsening of respiratory symptoms. Permanently discontinue if ILD is confirmed.
INSERT INTO "drug_generic" VALUES(568, 'Indapamide', 'Indapamide', 'C03BA11', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Electrolyte Imbalance", "severity": "High", "trigger_condition": "Concomitant use with QT-prolonging drugs or digitalis", "message": "STOP: Severe hypokalemia and hyponatremia can occur. Hypokalemia increases the risk of fatal arrhythmias (e.g., Torsades de Pointes) and digitalis toxicity. Monitor electrolytes regularly."}]', 'Monitor serum electrolytes (potassium, sodium, chloride) regularly, as indapamide can cause severe hypokalemia, hyponatremia, and hypochloremic alkalosis. Use with caution in patients with severe renal impairment; thiazide-like diuretics become ineffective when creatinine clearance falls below 30 mL/min. Caution in patients with hepatic impairment, as minor alterations in fluid and electrolyte balance may precipitate hepatic coma. May precipitate hyperuricemia and acute gout attacks. Can impair glucose tolerance; monitor blood glucose closely in diabetic patients. May exacerbate or activate systemic lupus erythematosus (SLE). Monitor for signs of hypersensitivity reactions, particularly in patients with a history of sulfonamide allergy.', '- **Essential Hypertension:** Treatment of hypertension, either as monotherapy or in combination with other antihypertensive agents.
INSERT INTO "drug_generic" VALUES(569, 'Allylestrenol', 'Allylestrenol', 'G03DX07', 0, 0, 1, 0, 0, 0, 0, 1, '[{"alert_type": "Withdrawal Bleeding", "severity": "Medium", "trigger_condition": "Sudden discontinuation of therapy", "message": "STOP: Sudden withdrawal of allylestrenol should be avoided as it leads to intermittent breakthrough bleeding and may precipitate abortion in susceptible patients."}]', '**Visual and Neurological Disturbances:** Discontinue medication immediately if there is a sudden partial or complete loss of vision, proptosis, diplopia, or onset of migraine.
INSERT INTO "drug_generic" VALUES(570, 'Gemtuzumab', 'Gemtuzumab ozogamicin', 'L01FX02', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hepatotoxicity and Veno-occlusive Disease (VOD)", "severity": "High", "trigger_condition": "During or following treatment, especially post-hematopoietic stem cell transplant (HSCT)", "message": "STOP: Severe and potentially fatal hepatotoxicity, including veno-occlusive disease (VOD) / sinusoidal obstruction syndrome (SOS), has been reported. Monitor liver tests frequently and assess for signs of VOD."}]', '**Hepatotoxicity and Veno-occlusive Disease (VOD):** Severe, life-threatening, and sometimes fatal hepatotoxicity, including VOD (also known as sinusoidal obstruction syndrome [SOS]), has occurred. Risk is higher in patients receiving gemtuzumab before or after hematopoietic stem cell transplantation (HSCT), or in those with moderate/severe hepatic impairment. Monitor ALT, AST, total bilirubin, and alkaline phosphatase prior to each dose. Assess frequently for signs of VOD (hepatomegaly, rapid weight gain, ascites).
INSERT INTO "drug_generic" VALUES(571, 'Calcium phosphate + Vitamin D3', 'Calcium phosphate + Cholecalciferol', 'A12AX', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '- **Achlorhydria:** Impaired calcium absorption occurs in achlorhydria, which is common in the elderly. Administer with meals to enhance absorption.
INSERT INTO "drug_generic" VALUES(572, 'Pancreatin', 'Pancreatin', 'A09AA02', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Fibrosing Colonopathy Risk", "severity": "High", "trigger_condition": "High doses (>10,000 lipase units/kg/day) in pediatric patients with cystic fibrosis", "message": "STOP: Fibrosing colonopathy, a rare but serious complication resulting in colonic strictures, has been reported in children with cystic fibrosis receiving high doses of pancreatic enzyme preparations. Do not exceed recommended weight-based dosing."}]', '**Fibrosing Colonopathy:** Colonic strictures have been reported in patients with cystic fibrosis taking high doses of pancreatic enzyme preparations. Doses exceeding 10,000 lipase units/kg/day should be used with extreme caution and only if clinically justified.
INSERT INTO "drug_generic" VALUES(573, 'Losartan Potassium', 'Losartan', 'C09CA01', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected during therapy", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue losartan as soon as pregnancy is detected."}]', '**Hypotension in Volume-Depleted Patients:** In patients who are intravascularly volume-depleted (e.g., those treated with high-dose diuretics), symptomatic hypotension may occur. Correct volume depletion prior to administration or use a lower starting dose.
INSERT INTO "drug_generic" VALUES(574, 'Ethinylestradiol + Drospirenone + Levomefolate Calcium', 'Ethinyl Estradiol, Drospirenone, and Levomefolate Calcium', 'G03AA12', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Women over 35 years old who smoke", "message": "STOP: Cigarette smoking increases the risk of serious cardiovascular events from combination oral contraceptives (COCs). This risk increases with age, particularly in women over 35 years of age, and with the number of cigarettes smoked. Contraindicated in women over 35 who smoke."}]', '**Thromboembolic Disorders:** Epidemiological studies associate the use of COCs with an increased risk of venous thromboembolism (VTE), arterial thromboembolism (ATE), myocardial infarction, and stroke. Drospirenone-containing COCs may have a higher risk of VTE compared to some other progestins. Discontinue immediately if an arterial or venous thrombotic event occurs.
INSERT INTO "drug_generic" VALUES(575, 'Vincristine Sulphate', 'Vincristine Sulfate', 'L01CA02', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Fatal Route of Administration", "severity": "High", "trigger_condition": "Intrathecal administration", "message": "STOP: Fatal if given intrathecally. For intravenous use ONLY. Intrathecal administration results in fatal ascending myeloencephalopathy."}, {"alert_type": "Vesicant Hazard", "severity": "High", "trigger_condition": "Extravasation during IV infusion", "message": "STOP: Severe tissue necrosis can occur. Ensure proper needle/catheter placement before and during infusion."}]', 'Use with extreme caution in patients with pre-existing neuromuscular disease, pulmonary dysfunction, or impaired liver function. Monitor closely for dose-limiting neurotoxicity (e.g., peripheral neuropathy, loss of deep tendon reflexes, paralytic ileus); a routine prophylactic laxative regimen is highly recommended to prevent severe constipation and ileus. Monitor complete blood count (CBC) prior to each dose to assess for leukopenia or complicating infections. Monitor serum uric acid levels frequently during the first 3-4 weeks of treatment to prevent uric acid nephropathy; ensure adequate hydration and consider allopurinol. Discontinue immediately if extravasation occurs; inject any remaining drug into another vein, apply local heat, and consider local injection of hyaluronidase to aid drug removal and reduce discomfort. Discontinue therapy in patients who develop progressive dyspnea or bronchospasm.', '- **Acute Lymphoblastic Leukemia (ALL):** Used as part of combination chemotherapy regimens for induction and maintenance.
INSERT INTO "drug_generic" VALUES(576, 'Atropine Sulphate', 'Atropine', 'A03BA01', 0, 1, 1, 0, 0, 1, 1, 0, '[{"alert_type": "Paradoxical Bradycardia", "severity": "High", "trigger_condition": "Administration of low doses (<0.5 mg in adults)", "message": "STOP: Doses lower than 0.5 mg in adults can cause paradoxical bradycardia due to central vagal stimulation. Always use appropriate weight-based or minimum recommended doses."}]', '**Tachycardia and Coronary Artery Disease:** Atropine increases heart rate, which increases myocardial oxygen demand. In patients with CAD, restrict the total dose to 2-3 mg (0.03-0.04 mg/kg) to avoid precipitating myocardial ischemia or infarction.
INSERT INTO "drug_generic" VALUES(577, 'Remifentanil', 'Remifentanil', 'N01AH06', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Rapid Offset of Action and Respiratory Depression", "severity": "High", "trigger_condition": "Discontinuation of infusion or initiation of therapy", "message": "STOP: Remifentanil has an extremely rapid offset of action (5-10 minutes). Alternative analgesia MUST be administered prior to discontinuation to prevent severe acute pain. Profound respiratory depression and muscle rigidity can occur during use."}]', '**Rapid Offset of Action:** Due to its rapid metabolism by blood and tissue esterases, the analgesic effects of remifentanil dissipate within 5 to 10 minutes after discontinuation. Patients must receive alternative analgesics prior to stopping the infusion to prevent severe postoperative pain.
INSERT INTO "drug_generic" VALUES(578, 'Bezlotoxumab', 'Bezlotoxumab', 'J06BD02', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Heart Failure Exacerbation", "severity": "High", "trigger_condition": "Patients with a history of congestive heart failure (CHF)", "message": "STOP: Heart failure was reported more commonly in bezlotoxumab-treated patients compared with placebo, primarily in those with underlying CHF. In patients with a history of CHF, reserve bezlotoxumab for use only when benefits clearly outweigh risks."}]', '**Heart Failure:** Heart failure was reported more commonly in clinical trials in bezlotoxumab-treated patients compared with placebo (12.7% vs 4.8%). These adverse reactions occurred primarily in patients with underlying congestive heart failure (CHF). In patients with a history of CHF, bezlotoxumab should be reserved for use when the benefits outweigh the risks.
INSERT INTO "drug_generic" VALUES(579, 'Nitazoxanide', 'Nitazoxanide', 'P01AX11', 1, 0, 1, 1, 0, 0, 1, 0, '[]', 'Use with caution in patients with renal and hepatic impairment, as the pharmacokinetics of nitazoxanide in these populations have not been fully studied. The oral suspension contains sucrose; use with caution in patients with diabetes mellitus. Safety and efficacy have not been established in children less than 1 year of age or in patients with immunodeficiency (e.g., HIV/AIDS) for the treatment of diarrhea caused by Cryptosporidium parvum.', '- **Giardiasis:** Treatment of diarrhea caused by *Giardia lamblia* in adults and pediatric patients 1 year of age and older.
INSERT INTO "drug_generic" VALUES(580, 'Perindopril Erbumine', 'Perindopril', 'C09AA04', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue perindopril as soon as pregnancy is detected."}]', '- **Angioedema:** May cause angioedema of the face, extremities, lips, tongue, glottis, or larynx at any time during treatment. Black patients have a higher incidence. Discontinue immediately if this occurs.
INSERT INTO "drug_generic" VALUES(581, 'Alfuzosin + Dutasteride', 'Alfuzosin + Dutasteride', 'G04CA51', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Teratogenicity Risk", "severity": "High", "trigger_condition": "Exposure to pregnant women", "message": "STOP: Dutasteride is highly teratogenic. Women who are pregnant or may become pregnant must not handle crushed or broken tablets, as absorption through the skin can cause abnormal development of male fetuses."}]', '**Postural Hypotension:** Alfuzosin can cause postural hypotension, with or without symptoms (dizziness, fatigue, sweating), particularly within a few hours following administration. Caution patients about driving or operating machinery.
INSERT INTO "drug_generic" VALUES(582, 'Menthol 10% + Methyl Salicylate 15% Topical', 'Menthol / Methyl Salicylate Topical', 'M02AC', 0, 0, 0, 1, 0, 1, 1, 0, '[]', 'For external use only. Avoid contact with the eyes, mucous membranes, and sensitive skin areas. Do not apply to wounds, damaged, or irritated skin. Do not bandage tightly, wrap, or cover the treated area with an occlusive dressing or heating pad, as this can increase systemic absorption and the risk of severe burns or salicylate toxicity. Do not use immediately before or after a bath or shower. Wash hands thoroughly after applying.', '- **Musculoskeletal Pain:** Symptomatic relief of minor aches and pains of muscles and joints associated with simple backache, arthritis, strains, bruises, and sprains.
INSERT INTO "drug_generic" VALUES(583, 'Primidone', 'Primidone', 'N03AA03', 0, 0, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Suicidal Ideation and Behavior", "severity": "High", "trigger_condition": "Initiation or dosage adjustment of antiepileptic drugs", "message": "STOP: Antiepileptic drugs increase the risk of suicidal thoughts or behavior. Monitor patients for emerging or worsening depression, suicidal thoughts or behavior, and/or any unusual changes in mood or behavior."}, {"alert_type": "Withdrawal Seizures", "severity": "High", "trigger_condition": "Abrupt discontinuation of therapy", "message": "STOP: Abrupt withdrawal of primidone may precipitate status epilepticus. Taper the dose gradually over at least 2 weeks."}]', '- **Bioequivalence Issues:** Do not interchange brands without close clinical monitoring, as bioequivalence issues may lead to loss of seizure control or toxicity.
INSERT INTO "drug_generic" VALUES(584, 'Salicylic Acid 10% + Urea 10% Topical', 'Salicylic Acid 10% + Urea 10% Topical', 'D02AE51', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'For external use only. Avoid contact with eyes, lips, and mucous membranes. Do not apply to open wounds, infected skin, or acutely inflamed areas. Discontinue use if severe irritation occurs. Use with caution in patients with peripheral neuropathy or impaired circulation (e.g., diabetes).', '- **Hyperkeratotic Conditions:** Treatment of psoriasis, eczema, keratosis, and severe xerosis.
INSERT INTO "drug_generic" VALUES(585, 'Glycopyrronium Bromide + Formoterol Fumarate', 'Glycopyrrolate and Formoterol Fumarate', 'R03AL04', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Asthma-Related Death Risk", "severity": "High", "trigger_condition": "Use in patients with asthma without a concomitant long-term asthma control medication", "message": "STOP: Long-acting beta2-adrenergic agonists (LABAs) increase the risk of asthma-related death. This combination is NOT indicated for the treatment of asthma."}, {"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediate worsening of wheezing or shortness of breath after inhalation", "message": "STOP: Can produce life-threatening paradoxical bronchospasm. Treat immediately with an inhaled, short-acting bronchodilator and discontinue therapy."}]', '- **Deteriorating Disease:** Do not initiate in patients with acutely deteriorating or potentially life-threatening episodes of COPD. Do not use as rescue therapy for acute bronchospasm.
INSERT INTO "drug_generic" VALUES(586, 'Tamoxifen', 'Tamoxifen', 'L02BA01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Uterine Malignancies", "severity": "High", "trigger_condition": "Routine therapy", "message": "STOP: Increased risk of uterine malignancies (endometrial cancer and uterine sarcoma). Promptly evaluate any abnormal vaginal bleeding, discharge, or pelvic pain."}, {"alert_type": "Thromboembolic Events", "severity": "High", "trigger_condition": "Routine therapy", "message": "STOP: Increased risk of serious and potentially fatal thromboembolic events, including DVT, pulmonary embolism, and stroke."}]', 'Monitor closely for signs of thromboembolism. Perform routine gynecological examinations to monitor for endometrial changes or malignancies. Monitor complete blood count (CBC), including platelet counts, and liver function tests (LFTs) periodically, as leukopenia, thrombocytopenia, and hepatotoxicity can occur. Monitor lipid profiles in patients with pre-existing hyperlipidemias. Ophthalmic examinations are recommended if visual disturbances occur, due to the risk of cataracts and retinal changes.', '- **Breast Cancer Treatment:** Treatment of estrogen receptor-positive (ER-positive) metastatic breast cancer in women and men. Adjuvant treatment of early-stage ER-positive breast cancer.
INSERT INTO "drug_generic" VALUES(587, 'Doxycycline', 'Doxycycline', 'J01AA02', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Tooth Discoloration and Bone Growth Inhibition", "severity": "High", "trigger_condition": "Use in children under 8 years of age or during the second/third trimester of pregnancy", "message": "STOP: Tetracyclines cause permanent tooth discoloration (yellow-gray-brown) and inhibit bone growth. Avoid use in children <8 years and pregnant women unless treating severe/life-threatening conditions (e.g., Anthrax, Rocky Mountain Spotted Fever) where alternatives are ineffective."}]', '**Photosensitivity:** Exaggerated sunburn reactions can occur. Advise patients to avoid excessive sunlight or artificial ultraviolet light and discontinue therapy at the first sign of skin erythema.
INSERT INTO "drug_generic" VALUES(588, 'Tiemonium Methylsulphate', 'Tiemonium Methylsulfate', 'A03AB17', 0, 0, 1, 0, 1, 1, 1, 0, '[]', 'Exercise caution in patients with prostatic hypertrophy, as anticholinergic effects may precipitate acute urinary retention.
INSERT INTO "drug_generic" VALUES(589, 'Mupirocin Calcium nasal prep', 'Mupirocin Calcium', 'R01AX06', 1, 0, 1, 1, 0, 1, 1, 0, '[]', 'Prolonged use of mupirocin may result in the overgrowth of non-susceptible organisms, including fungi. If sensitization or severe local irritation occurs, discontinue use immediately and institute appropriate alternative therapy. Avoid contact with the eyes; if contact occurs, rinse thoroughly with water. Do not use concurrently with other intranasal products.', '- **MRSA Eradication:** Indicated for the eradication of nasal colonization with methicillin-resistant *Staphylococcus aureus* (MRSA) in adult patients and healthcare workers to reduce the risk of infection transmission.
INSERT INTO "drug_generic" VALUES(590, 'Diflorasone Diacetate 0.05% Topical', 'Diflorasone Diacetate', 'D07AC10', 0, 0, 0, 1, 0, 1, 0, 1, '[{"alert_type": "Endocrine Toxicity", "severity": "High", "trigger_condition": "Prolonged use, application to large surface areas, or use of occlusive dressings", "message": "STOP: Substantial systemic absorption can lead to reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria. Avoid prolonged use or occlusive dressings."}]', '**HPA Axis Suppression:** Systemic absorption of topical corticosteroids can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression with the potential for glucocorticosteroid insufficiency after withdrawal of treatment. Risk factors include use over large surface areas, prolonged use, and the addition of occlusive dressings.
INSERT INTO "drug_generic" VALUES(591, 'Caffeine + Ergotamine Tartrate', 'Ergotamine and Caffeine', 'N02CA52', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Peripheral Ischemia", "severity": "High", "trigger_condition": "Concurrent use with potent CYP3A4 inhibitors", "message": "STOP: Coadministration with potent CYP3A4 inhibitors (e.g., protease inhibitors, macrolide antibiotics) is contraindicated. It elevates ergotamine levels, causing severe vasospasm leading to cerebral ischemia and/or ischemia of the extremities (gangrene)."}]', '**Ergotism:** Intense arterial vasoconstriction can produce signs of peripheral vascular ischemia (headache, intermittent claudication, muscle pains, numbness, coldness, and pallor of digits). If untreated, gangrene can result. Do not exceed recommended dosages.
INSERT INTO "drug_generic" VALUES(592, 'Naltrexone', 'Naltrexone', 'N07BB04', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hepatotoxicity and Precipitated Withdrawal", "severity": "High", "trigger_condition": "Use in patients with acute hepatitis or current opioid dependence", "message": "STOP: Naltrexone can cause dose-related hepatocellular injury. It is contraindicated in acute hepatitis or liver failure. Furthermore, it MUST NOT be given to patients currently dependent on opioids, as it will precipitate a severe, potentially life-threatening acute withdrawal syndrome. Patients must be opioid-free for at least 7-10 days before initiation."}]', '- **Hepatic Impairment:** Naltrexone is extensively metabolized by the liver. Use with caution in mild to moderate hepatic impairment; monitor liver function tests (LFTs) regularly. Discontinue if signs of acute hepatitis develop.
INSERT INTO "drug_generic" VALUES(593, 'Clostridium Botulinum Toxin Type A Neurotoxin (OnabotulinumtoxinA)', 'OnabotulinumtoxinA', 'M03AX01', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Distant Spread of Toxin Effect", "severity": "High", "trigger_condition": "Development of respiratory, speech, or swallowing difficulties after injection", "message": "STOP: The effects of botulinum toxin may spread from the injection area, causing life-threatening swallowing and breathing difficulties. Seek immediate medical attention if these symptoms occur."}]', '**Spread of Toxin Effects:** Postmarketing reports indicate that the effects of botulinum toxin may spread from the area of injection to produce symptoms consistent with botulinum toxin effects (e.g., asthenia, generalized muscle weakness, diplopia, ptosis, dysphagia, dysphonia, dysarthria, urinary incontinence, and breathing difficulties). These can occur hours to weeks after injection and can be life-threatening or fatal.
INSERT INTO "drug_generic" VALUES(594, 'Progesterone oral prep', 'Progesterone', 'G03DA04', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Cardiovascular and Thromboembolic Risk", "severity": "High", "trigger_condition": "Patients with a history of or current deep vein thrombosis (DVT), pulmonary embolism (PE), or arterial thromboembolic disease", "message": "STOP: Estrogen plus progestin therapy increases the risk of DVT, PE, stroke, and myocardial infarction. Discontinue immediately if any of these events occur or are suspected."}, {"alert_type": "Dementia Risk", "severity": "Moderate", "trigger_condition": "Postmenopausal women >65 years of age", "message": "WARNING: Increased risk of developing probable dementia in postmenopausal women >65 years of age. Do not use for the prevention of cardiovascular disease or dementia."}]', '- **Cardiovascular Disorders:** Use with caution in patients with conditions exacerbated by fluid retention (e.g., hypertension, heart failure).
INSERT INTO "drug_generic" VALUES(595, 'Lenvatinib', 'Lenvatinib', 'L01EX08', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hypertension and Hemorrhage", "severity": "High", "trigger_condition": "Elevated blood pressure or signs of bleeding", "message": "STOP: Severe and fatal hypertension and hemorrhagic events have occurred. Control blood pressure prior to initiation. Withhold, dose reduce, or discontinue for severe hypertension or severe bleeding."}, {"alert_type": "Gastrointestinal Perforation and Fistula", "severity": "High", "trigger_condition": "Severe abdominal pain", "message": "STOP: Fatal GI perforation and fistula formation can occur. Discontinue lenvatinib immediately if these occur."}]', '**Hypertension:** Control blood pressure prior to treatment. Monitor BP after 1 week, then every 2 weeks for the first 2 months, and at least monthly thereafter. Withhold and dose reduce for Grade 3 hypertension; permanently discontinue for life-threatening hypertension.
INSERT INTO "drug_generic" VALUES(596, 'Vitamin A + Vitamin-B complex + Vitamin-C + Vitamin-D + Vitamin E IV prep', 'Multivitamins, Intravenous', 'B05XC', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Rapid intravenous injection or hypersensitivity to thiamine", "message": "STOP: Severe anaphylactic reactions can occur, particularly due to the thiamine (Vitamin B1) component. Do not administer as a direct, undiluted IV push. Must be diluted and infused slowly."}]', 'Monitor for mild allergic reactions (sneezing, mild asthma), which are warning signs that further infusion may cause anaphylactic shock.
INSERT INTO "drug_generic" VALUES(597, 'Dasatinib', 'Dasatinib', 'L01EA02', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Severe Fluid Retention", "severity": "High", "trigger_condition": "Shortness of breath, dry cough, or weight gain", "message": "STOP: Severe fluid retention, including pleural effusions, pericardial effusions, and pulmonary edema, can occur. Evaluate promptly and manage with diuretics, dose interruption, or reduction."}, {"alert_type": "Myelosuppression", "severity": "High", "trigger_condition": "Routine CBC monitoring", "message": "WARNING: Severe thrombocytopenia, neutropenia, and anemia are common. Monitor CBC frequently and interrupt or reduce dose as indicated."}]', '**Myelosuppression and Bleeding Events:** Severe thrombocytopenia, neutropenia, and anemia frequently occur. Monitor complete blood counts (CBC) weekly for the first 2 months, then monthly. Severe CNS and gastrointestinal hemorrhages, including fatalities, have occurred. Use caution with concomitant antiplatelets or anticoagulants.
INSERT INTO "drug_generic" VALUES(598, 'Doxepin', 'Doxepin', 'N06AA12', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Suicidality and Antidepressant Drugs", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '**Anticholinergic Effects:** Use with extreme caution in patients with a history of urinary retention, benign prostatic hyperplasia (BPH), or angle-closure glaucoma due to potent anticholinergic properties.
INSERT INTO "drug_generic" VALUES(599, 'Posaconazole', 'Posaconazole', 'J02AC04', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Arrhythmia and QTc Prolongation", "severity": "High", "trigger_condition": "Coadministration with CYP3A4 substrates or in patients with proarrhythmic conditions", "message": "STOP: Posaconazole is a strong CYP3A4 inhibitor. Coadministration with certain drugs (e.g., pimozide, quinidine) can lead to fatal QTc prolongation and Torsades de Pointes. Verify all patient medications before prescribing."}]', '**Arrhythmias and QTc Prolongation:** Can prolong the QTc interval. Use with caution in patients with potentially proarrhythmic conditions. Correct electrolyte disturbances (K, Mg, Ca) before initiating therapy.
INSERT INTO "drug_generic" VALUES(600, 'Cidofovir', 'Cidofovir', 'J05AB12', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Nephrotoxicity", "severity": "High", "trigger_condition": "Administration without probenecid and prehydration, or preexisting renal impairment", "message": "STOP: Dose-dependent nephrotoxicity is the major dose-limiting toxicity. Acute renal failure resulting in dialysis or death has occurred with as few as 1 or 2 doses. Must administer with oral probenecid and IV saline prehydration."}]', '**Nephrotoxicity:** Acute renal failure can occur. Monitor serum creatinine and urine protein within 48 hours prior to each dose. Modify or discontinue the dose based on renal function changes.
INSERT INTO "drug_generic" VALUES(601, 'Risedronate Sodium (Risedronic acid)', 'Risedronate', 'M05BA07', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Esophageal Irritation", "severity": "High", "trigger_condition": "Inability to stand or sit upright for at least 30 minutes", "message": "STOP: Contraindicated in patients who cannot stand or sit upright for at least 30 minutes due to the risk of severe esophageal adverse experiences."}]', '**Upper Gastrointestinal Adverse Reactions:** Risedronate can cause severe esophageal irritation, esophagitis, esophageal ulcers, and gastric ulcers. Discontinue use if dysphagia, odynophagia, or retrosternal pain occurs.
INSERT INTO "drug_generic" VALUES(602, 'Cilostazol', 'Cilostazol', 'B01AC23', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Heart Failure Contraindication", "severity": "High", "trigger_condition": "Patients with heart failure of any severity", "message": "STOP: Cilostazol is contraindicated in patients with heart failure of any severity. Phosphodiesterase III inhibitors have caused decreased survival compared to placebo in patients with class III-IV heart failure."}]', '**Cardiovascular Effects:** May cause tachycardia, palpitations, tachyarrhythmias, or hypotension. Use with caution in patients with a history of ischemic heart disease, as it may exacerbate angina pectoris or precipitate myocardial infarction.
INSERT INTO "drug_generic" VALUES(603, 'Cefprozil', 'Cefprozil', 'J01DC04', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(604, 'Ceftibuten', 'Ceftibuten', 'J01DD14', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}]', '- **Hypersensitivity:** Cross-reactivity with penicillins can occur; use with caution in patients with a history of penicillin allergy.
INSERT INTO "drug_generic" VALUES(605, 'Tolvaptan', 'Tolvaptan', 'C03XA01', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Osmotic Demyelination Syndrome & Hepatotoxicity", "severity": "High", "trigger_condition": "Rapid correction of serum sodium or prolonged use", "message": "STOP: Too rapid correction of hyponatremia (e.g., >12 mEq/L/24 hours) can cause fatal osmotic demyelination syndrome. Initiate in a hospital setting. Tolvaptan can also cause severe, potentially fatal liver injury; monitor LFTs closely."}]', '**Osmotic Demyelination Syndrome (ODS):** Rapid correction of serum sodium can cause ODS, resulting in dysarthria, mutism, dysphagia, lethargy, affective changes, spastic quadriparesis, seizures, coma, and death. Monitor serum sodium closely.
INSERT INTO "drug_generic" VALUES(606, 'Neomycin Sulphate 0.5% + Prednisolone 0.5% E/E prep', 'Neomycin / Prednisolone Ophthalmic and Otic', 'S01CA02', 1, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Ocular and Otic Toxicity", "severity": "High", "trigger_condition": "Prolonged use or use in perforated tympanic membrane", "message": "STOP: Prolonged ophthalmic use may cause glaucoma and cataracts. Otic use is strictly contraindicated if the tympanic membrane is perforated due to the risk of severe ototoxicity and deafness."}]', '- **Intraocular Pressure (IOP):** Prolonged ophthalmic use may result in elevated IOP. Monitor IOP routinely if used for extended periods.
INSERT INTO "drug_generic" VALUES(607, 'Cefdinir', 'Cefdinir', 'J01DD15', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(608, 'Nitrazepam', 'Nitrazepam', 'N05CD02', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Concomitant Use with Opioids", "severity": "High", "trigger_condition": "Co-administration with opioids or other profound CNS depressants", "message": "STOP: Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death. Reserve concomitant prescribing for patients with inadequate alternative treatment options."}]', 'May induce anterograde amnesia; caution patients to ensure they have an uninterrupted sleep period of 7-8 hours after ingestion. May severely impair the ability to drive or operate machinery (hangover effect). Use with extreme caution in patients with depression, especially if suicidal risk is present, as it may unmask or exacerbate symptoms. Avoid in patients with a history of drug abuse or acute alcoholism due to the risk of dependence and potentiation of CNS depression. Use cautiously in the elderly, debilitated patients, and those at risk of falls due to muscle weakness and ataxia. Caution is advised in patients with respiratory disease or renal impairment.', '- **Insomnia:** Short-term management of insomnia of various etiologies, including neurotic insomnia, involutional restlessness, and sleep disturbances in cerebrosclerotic patients.
INSERT INTO "drug_generic" VALUES(609, 'Camphor + Menthol + Oil Eucalyptus + Thymol topical', 'Camphor / Menthol / Eucalyptus Oil / Thymol', 'M02AX10', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Pediatric Seizure Risk", "severity": "High", "trigger_condition": "Use in children under 3 years or patients with a history of convulsions", "message": "STOP: Camphor can cause severe neurotoxicity and seizures. Contraindicated in children under 3 years and patients with a history of convulsions."}]', '**Application Site Reactions:** Avoid contact with eyes, mucous membranes, and genitalia. Do not apply to wounds, damaged, or irritated skin.
INSERT INTO "drug_generic" VALUES(610, 'Atazanavir + Cobicistat', 'Atazanavir and Cobicistat', 'J05AR15', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiac Conduction Abnormalities", "severity": "High", "trigger_condition": "Preexisting conduction system disease or coadministration with PR-prolonging drugs", "message": "Caution: PR interval prolongation may occur. Consider ECG monitoring in patients with preexisting conduction system disease."}, {"alert_type": "Severe Skin Reactions", "severity": "High", "trigger_condition": "Development of severe rash", "message": "STOP: Discontinue therapy immediately if severe rash, Stevens-Johnson syndrome, erythema multiforme, or toxic skin eruptions develop."}]', '**Renal Toxicity:** When used in combination with a tenofovir disoproxil fumarate (TDF)-containing regimen, cases of acute renal failure and Fanconi syndrome have been reported. Chronic kidney disease has also been reported during postmarketing surveillance. Assess creatinine clearance (CrCl) before initiating and monitor renal function during therapy.
INSERT INTO "drug_generic" VALUES(611, 'Fluormetholone 0.1% + Neomycin Sulphate 0.5% Eye prep', 'Fluorometholone 0.1% and Neomycin Sulfate 0.5% Ophthalmic', 'S01CA07', 1, 0, 0, 0, 0, 0, 0, 1, '[]', 'Prolonged use may result in glaucoma, optic nerve damage, visual acuity defects, and posterior subcapsular cataract formation. Intraocular pressure (IOP) must be monitored routinely. Corticosteroids may mask, activate, or exacerbate ocular infections. May cause corneal and scleral thinning, leading to perforation in severe cases. Use of steroids after cataract surgery may prolong healing time and increase bleb formation. Not to be used in mustard gas keratitis and Sjogren''s keratoconjunctivitis.', '- **Steroid-Responsive Inflammatory Ocular Conditions:** Treatment of allergic and inflammatory conditions of the palpebral and bulbar conjunctiva, cornea, and anterior segment of the globe where the risk of superficial bacterial ocular infection exists or is expected.', '- **Viral and Fungal Eye Infections:** Contraindicated in epithelial herpes simplex keratitis (dendritic keratitis), vaccinia, varicella, and other viral diseases of the cornea and conjunctiva, as well as mycobacterial and fungal infections of the eye.
INSERT INTO "drug_generic" VALUES(612, 'Carboxymethylcellulose Sodium +  Glycerine  Eye prep', 'Carboxymethylcellulose Sodium / Glycerin', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Visual Disturbances:** May cause temporary blurred vision immediately after instillation. Patients should be advised not to drive or operate hazardous machinery until vision clears.
INSERT INTO "drug_generic" VALUES(613, 'Vitamin E  (Alpha-tocopherol)', 'Alpha-tocopherol', 'A11HA03', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Use with caution in patients taking anticoagulant or antiplatelet therapy, as high doses of Vitamin E can increase the risk of bleeding. Recent evidence suggests that high-dose Vitamin E supplementation may suppress the action of other antioxidants and has been associated with an increased risk of hemorrhagic stroke and all-cause mortality in some studies.', '- **Vitamin E Deficiency:** Treatment and prevention of deficiency, particularly in patients with malabsorption syndromes (e.g., cystic fibrosis, abetalipoproteinemia).
INSERT INTO "drug_generic" VALUES(614, 'Elemental Iron (carbonyl iron) + Folic Acid', 'Carbonyl Iron and Folic Acid', 'B03AD', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Accidental Overdose in Children", "severity": "High", "trigger_condition": "Unsecured storage accessible to children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Iron Overload:** Care should be taken in patients who may develop iron overload, such as those with hemochromatosis, hemosiderosis, hemolytic anemia, or red cell aplasia. Avoid prolonged use unless directed by a physician.
INSERT INTO "drug_generic" VALUES(615, 'Povidone Iodine 6% Topical', 'Povidone-Iodine Topical', 'D08AG02', 1, 0, 0, 0, 1, 1, 0, 0, '[]', 'Avoid contact with eyes. Should not be used under occlusive dressings unless directed by a physician. Application to large areas of denuded skin or severe burns may produce systemic adverse effects such as metabolic acidosis, hypernatremia, and impairment of renal function due to significant iodine absorption. Exercise special caution in patients with pre-existing renal insufficiency.', '- **Skin Infections:** Treatment of primary or secondary topical infections.
INSERT INTO "drug_generic" VALUES(616, 'Larotrectinib', 'Larotrectinib', 'L01EX12', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated transaminases during therapy", "message": "WARNING: Severe hepatotoxicity can occur. Monitor liver tests (AST/ALT) every 2 weeks during the first month, then monthly. Dose modification or discontinuation may be required."}, {"alert_type": "Neurologic Toxicity", "severity": "High", "trigger_condition": "Onset of dizziness, cognitive impairment, or mood disorders", "message": "WARNING: Neurologic adverse reactions (e.g., dizziness, cognitive impairment, mood disorders, sleep disturbances) are common. Advise patients against driving or operating hazardous machinery if affected."}]', '**Neurologic Adverse Reactions:** Neurologic events of any grade (including dizziness, cognitive impairment, mood disorders, and sleep disturbances) occur frequently, mostly within the first 3 months of treatment. Advise patients not to drive or operate hazardous machinery if they experience these symptoms. Dose modification may be necessary.
INSERT INTO "drug_generic" VALUES(617, 'Sulphamethoxazole + Trimethoprim (Co-trimoxazole)', 'Sulfamethoxazole and Trimethoprim', 'J01EE01', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Hypersensitivity and Blood Dyscrasias", "severity": "High", "trigger_condition": "History of sulfonamide allergy or development of rash", "message": "STOP: Fatalities associated with severe reactions (Stevens-Johnson syndrome, toxic epidermal necrolysis, fulminant hepatic necrosis, agranulocytosis, aplastic anemia) have occurred. Discontinue at the first sign of skin rash."}]', '**Blood Dyscrasias:** Can cause severe hematologic toxicity. Monitor CBC regularly, especially in the elderly or those with folate deficiency.
INSERT INTO "drug_generic" VALUES(618, 'Rimegepant', 'Rimegepant', 'N02CD02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Signs of dyspnea, severe rash, or delayed hypersensitivity", "message": "STOP: Hypersensitivity reactions, including dyspnea and severe rash, have been reported. These can occur days after administration. Discontinue rimegepant and initiate appropriate therapy if a reaction occurs."}]', '**Hypersensitivity:** Hypersensitivity reactions, including dyspnea and severe rash, have been reported. These reactions can occur days after administration, and delayed serious hypersensitivity has occurred. If a hypersensitivity reaction occurs, discontinue rimegepant and initiate appropriate medical therapy.
INSERT INTO "drug_generic" VALUES(619, 'Benzocaine + Menthol oral prep', 'Benzocaine and Menthol', 'N01BA05', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Methemoglobinemia", "severity": "High", "trigger_condition": "Excessive or prolonged use of benzocaine-containing products", "message": "STOP: Benzocaine can cause rare but potentially fatal methemoglobinemia. Do not use in children under 2 years of age. Seek immediate medical attention if pale, gray, or blue-colored skin, headache, rapid heart rate, or shortness of breath occurs."}]', '**Methemoglobinemia:** Benzocaine has been associated with a rare but serious condition called methemoglobinemia. Symptoms include pale, gray, or blue-colored skin, lips, and nail beds, shortness of breath, fatigue, confusion, headache, and rapid heart rate. 
INSERT INTO "drug_generic" VALUES(620, 'Human Menopausal Gonadotrophin', 'Menotropins', 'G03GA02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Ovarian Hyperstimulation Syndrome (OHSS)", "severity": "High", "trigger_condition": "Patients undergoing ovulation induction or assisted reproductive technologies", "message": "STOP: Severe and potentially fatal Ovarian Hyperstimulation Syndrome (OHSS) can occur. Monitor ovarian response with ultrasound and serum estradiol frequently."}]', '**Ovarian Hyperstimulation Syndrome (OHSS):** OHSS is a serious medical event characterized by massive ovarian enlargement, severe abdominal pain, ascites, pleural effusion, and potentially fatal thromboembolic events. Monitor patients closely with transvaginal ultrasound and serum estradiol levels. Withhold hCG administration if ovaries are abnormally enlarged or estradiol levels are excessively high.
INSERT INTO "drug_generic" VALUES(621, 'Vericiguat', 'Vericiguat', 'C01DX22', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Use in pregnant females", "message": "STOP: Vericiguat may cause fetal harm. Exclude pregnancy before starting treatment. Females of reproductive potential must use effective contraception during and for 1 month after treatment."}]', '**Embryo-Fetal Toxicity:** Based on animal data, vericiguat may cause fetal harm. Verify pregnancy status prior to initiation.
INSERT INTO "drug_generic" VALUES(622, 'Ketorolac Tromethamine', 'Ketorolac Tromethamine', 'M01AB15', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Gastrointestinal, Renal, and Bleeding Risks", "severity": "High", "trigger_condition": "Use exceeding 5 days or use in contraindicated populations", "message": "STOP: Ketorolac carries a high risk of severe GI bleeding, acute renal failure, and bleeding disorders. The total duration of use (combined IV/IM/PO/Nasal) MUST NOT exceed 5 days. It is contraindicated in patients with active peptic ulcer disease, advanced renal impairment, or high risk of bleeding."}]', '**Cardiovascular Thrombotic Events:** NSAIDs cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke, which can be fatal.
INSERT INTO "drug_generic" VALUES(623, 'Metronidazole 0.75% Vag prep', 'Metronidazole Vaginal Gel', 'G01AF01', 1, 0, 1, 0, 0, 0, 0, 0, '[{"alert_type": "Disulfiram-like Reaction", "severity": "High", "trigger_condition": "Concurrent alcohol consumption", "message": "STOP: Although applied vaginally, systemic absorption occurs (approx. 2-4% of oral dose). Concurrent use of alcohol can cause a disulfiram-like reaction. Avoid alcohol during and for at least 24-48 hours after therapy."}]', 'Use with caution in patients with a history of central nervous system diseases or seizures, as systemic metronidazole has been associated with encephalopathy and neuropathy. Caution in patients with severe hepatic impairment or a history of blood dyscrasias. Vaginal use may result in Candida overgrowth (vulvovaginal candidiasis), requiring antifungal treatment. Avoid contact with eyes. May weaken latex condoms and diaphragms; advise alternative contraception.', '- Treatment of bacterial vaginosis (formerly known as Haemophilus vaginitis, Gardnerella vaginitis, nonspecific vaginitis, or anaerobic vaginosis) in non-pregnant and pregnant women.', '**Hypersensitivity:** Contraindicated in patients with a history of hypersensitivity to metronidazole, other nitroimidazole derivatives, or any component of the formulation.
INSERT INTO "drug_generic" VALUES(624, 'Indapamide + Amlodipine', 'Indapamide + Amlodipine', 'C08GA02', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Hepatic Encephalopathy", "severity": "High", "trigger_condition": "Severe hepatic impairment", "message": "STOP: Thiazide-like diuretics can precipitate hepatic encephalopathy in patients with severe hepatic impairment. Contraindicated in this population."}]', '**Electrolyte Imbalances:** Continuous monitoring of plasma sodium, potassium, and calcium is required. Hypokalemia is a significant risk, particularly in the elderly, malnourished, or those on concomitant QT-prolonging drugs.
INSERT INTO "drug_generic" VALUES(625, 'Bimatoprost 0.03% Eye prep', 'Bimatoprost Ophthalmic', 'S01EE03', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Permanent Pigmentation Changes", "severity": "Medium", "trigger_condition": "Initiation of therapy", "message": "STOP: Bimatoprost can cause increased brown pigmentation of the iris, which is likely to be PERMANENT. It can also cause darkening of the eyelid skin and increased growth/thickness of eyelashes (which may be reversible upon discontinuation)."}]', '**Iris Pigmentation:** Increased brown pigmentation of the iris occurs frequently and is likely permanent. Patients must be informed of this risk before starting therapy.
INSERT INTO "drug_generic" VALUES(626, 'Flunarizine', 'Flunarizine', 'N07CA03', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Extrapyramidal Symptoms and Depression", "severity": "High", "trigger_condition": "Patients with a history of depression or Parkinson''s disease", "message": "STOP: Flunarizine can induce depressive illness and extrapyramidal symptoms (EPS). It is strictly contraindicated in patients with a history of depression or pre-existing Parkinson''s disease."}]', 'Flunarizine may cause significant drowsiness and sedation, which is exacerbated by alcohol or other central nervous system (CNS) depressants. Patients should be cautioned against driving or operating hazardous machinery. Monitor closely for signs of depression or extrapyramidal symptoms (EPS) such as bradykinesia, rigidity, or tremor, particularly in elderly patients. If these symptoms occur, treatment must be discontinued immediately. Use with caution in patients with hepatic impairment, as the drug is extensively metabolized in the liver.', '- **Migraine Prophylaxis:** Prevention of classic (with aura) or common (without aura) migraine attacks.
INSERT INTO "drug_generic" VALUES(627, 'Glycopyrronium bromide (Glycopyrrolate) Inhalation', 'Glycopyrrolate Inhalation', 'R03BB06', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediately following inhalation", "message": "STOP: Inhaled medicines can cause life-threatening paradoxical bronchospasm. If this occurs, discontinue immediately and treat with a short-acting bronchodilator."}]', '**Not for Acute Bronchospasm:** Glycopyrronium is a maintenance therapy and should not be used for the relief of acute episodes of bronchospasm (i.e., as rescue therapy).
INSERT INTO "drug_generic" VALUES(628, 'Icosapent', 'Icosapent ethyl', 'C10AX06', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Bleeding Risk and Atrial Fibrillation", "severity": "Moderate", "trigger_condition": "Concomitant use with antithrombotics or history of arrhythmias", "message": "Caution: Associated with an increased risk of bleeding, especially with concomitant antithrombotics. Also associated with an increased risk of atrial fibrillation or flutter requiring hospitalization."}]', '**Atrial Fibrillation/Flutter:** Associated with an increased risk of atrial fibrillation or atrial flutter requiring hospitalization. The risk is higher in patients with a previous history of atrial fibrillation or flutter.
INSERT INTO "drug_generic" VALUES(629, 'Levonorgestrel', 'Levonorgestrel', 'G03AC03', 0, 0, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Ectopic Pregnancy Risk", "severity": "High", "trigger_condition": "Pregnancy occurring despite levonorgestrel use", "message": "STOP: If a patient becomes pregnant or complains of lower abdominal pain after taking emergency contraception, evaluate immediately for ectopic pregnancy."}]', '**Ectopic Pregnancy:** A history of ectopic pregnancy is not an absolute contraindication for emergency contraception, but if pregnancy occurs after use, the risk of it being ectopic is increased. Evaluate severe lower abdominal pain promptly.
INSERT INTO "drug_generic" VALUES(630, 'Lidocaine + Betamethasone + Chloramphenicol ear prep', 'Lidocaine, Betamethasone, and Chloramphenicol Otic', 'S02CA', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Ototoxicity Risk", "severity": "High", "trigger_condition": "Tympanic membrane perforation", "message": "STOP: Do not use if the tympanic membrane (eardrum) is perforated or if perforation is suspected. Introduction of chloramphenicol and lidocaine into the middle ear can cause severe, irreversible ototoxicity and deafness."}]', 'Verify that the tympanic membrane is intact before initiating therapy. Use of this preparation in the presence of a perforated eardrum increases the risk of ototoxicity.
INSERT INTO "drug_generic" VALUES(631, 'Sofosbuvir +  Daclatasvir', 'Sofosbuvir and Daclatasvir', 'J05AP08, J05AP07', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Severe Bradycardia with Amiodarone", "severity": "High", "trigger_condition": "Co-administration with Amiodarone", "message": "STOP: Co-administration can result in serious, potentially fatal symptomatic bradycardia. Avoid concurrent use."}, {"alert_type": "Hepatitis B Virus (HBV) Reactivation", "severity": "High", "trigger_condition": "HCV/HBV co-infection", "message": "WARNING: Test all patients for evidence of current or prior HBV infection before initiating treatment. HBV reactivation has occurred, leading to fulminant hepatitis and death."}]', 'Screen all patients for evidence of current or prior Hepatitis B virus (HBV) infection by measuring HBsAg and anti-HBc before initiating treatment.
INSERT INTO "drug_generic" VALUES(632, 'Alpha Ketoanalogues & essential amino acids (Isoleucine, leucine, phenylalanine, valine, methionine, L-lysine, L-threonine, L-tryptophan, L-histidine, L-tyrosine, nitrogen)', 'Alpha Ketoanalogues and Essential Amino Acids', 'V06DD', 0, 0, 0, 0, 0, 0, 0, 0, '[]', '**Hypercalcemia Risk:** Serum calcium levels should be monitored regularly, as hypercalcemia may develop during treatment. If hypercalcemia occurs, vitamin D intake and other calcium sources should be reduced.
INSERT INTO "drug_generic" VALUES(633, 'Follitropin Alfa', 'Follitropin Alfa', 'G03GA05', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Ovarian Hyperstimulation Syndrome (OHSS)", "severity": "High", "trigger_condition": "Excessive ovarian response during ovulation induction or ART", "message": "STOP: Severe OHSS is a potentially life-threatening medical event characterized by massive ovarian enlargement, ascites, pleural effusion, and thromboembolism. Monitor ovarian response closely via ultrasound and serum estradiol."}, {"alert_type": "Thromboembolic Events", "severity": "High", "trigger_condition": "Patients with personal or family history of thromboembolic disorders", "message": "WARNING: Serious thromboembolic events, both in association with and separate from OHSS, have been reported. Use with extreme caution in patients with recognized risk factors."}]', '**Ovarian Hyperstimulation Syndrome (OHSS):** A severe, potentially life-threatening condition characterized by ovarian enlargement, ascites, hydrothorax, and weight gain. Monitor follicular development via transvaginal ultrasound and serum estradiol levels. Withhold hCG if ovaries are abnormally enlarged or estradiol levels are excessively high.
INSERT INTO "drug_generic" VALUES(634, 'Montelukast', 'Montelukast', 'R03DC03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Neuropsychiatric Risk", "severity": "High", "trigger_condition": "Any patient initiating or currently taking montelukast", "message": "WARNING: Serious neuropsychiatric events, including agitation, aggression, depression, sleep disturbances, suicidal thoughts, and completed suicide, have been reported. Evaluate the risks and benefits before prescribing."}]', '**Neuropsychiatric Events:** Monitor patients for neuropsychiatric symptoms (e.g., agitation, aggression, depression, sleep disturbances, suicidal ideation). Discontinue if these occur.
INSERT INTO "drug_generic" VALUES(635, 'Parecoxib', 'Parecoxib', 'M01AH04', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "History of ischemic heart disease, stroke, or CABG surgery", "message": "STOP: COX-2 inhibitors are associated with an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. Contraindicated immediately following CABG surgery."}, {"alert_type": "Severe Skin Reactions", "severity": "High", "trigger_condition": "History of sulfonamide allergy or onset of skin rash", "message": "STOP: Fatal cutaneous reactions (Stevens-Johnson syndrome, toxic epidermal necrolysis) can occur. Discontinue at the first sign of skin rash or mucosal lesions. Contraindicated in sulfonamide allergy."}]', 'Use with extreme caution in patients with a history of gastrointestinal disease (ulceration, bleeding), the elderly, or those taking concomitant aspirin, corticosteroids, or SSRIs due to increased GI bleeding risk.
INSERT INTO "drug_generic" VALUES(636, 'Dextran 40 10% + Sodium Chloride 0.9%', 'Dextran 40 in Sodium Chloride', 'B05AA05', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Renal Failure", "severity": "High", "trigger_condition": "Administration of Dextran 40", "message": "STOP: Severe and fatal anaphylactoid reactions can occur. Observe patients closely during the first minutes of infusion. Dextran 40 can also precipitate acute renal failure; contraindicated in severe oliguria or anuria."}]', '**Anaphylactoid Reactions:** Severe and fatal anaphylactoid reactions have been reported. Discontinue use immediately at the first sign of hypersensitivity (e.g., hypotension, wheezing, tightness of chest) and administer appropriate therapy.
INSERT INTO "drug_generic" VALUES(637, 'Colesevelam', 'Colesevelam', 'C10AC04', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Gastrointestinal Obstruction", "severity": "High", "trigger_condition": "Patient history of bowel obstruction or severe gastroparesis", "message": "STOP: Colesevelam is contraindicated in patients with a history of bowel obstruction. It can exacerbate severe constipation and cause fecal impaction."}]', '**Hypertriglyceridemia and Pancreatitis:** Colesevelam can increase serum triglyceride concentrations. Hypertriglyceridemia can cause acute pancreatitis. Seek prompt medical attention if symptoms of acute pancreatitis occur (e.g., severe abdominal pain with or without nausea and vomiting). Rule out secondary causes of hyperlipidemia before initiating therapy.
INSERT INTO "drug_generic" VALUES(638, 'Oxazepam', 'Oxazepam', 'N05BA04', 0, 1, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Concomitant Use with Opioids", "severity": "High", "trigger_condition": "Co-administration with opioid analgesics", "message": "STOP: Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death. Reserve concomitant prescribing for patients with inadequate alternative treatment options."}]', '**CNS Depression:** May cause significant CNS depression, impairing physical and mental abilities. Patients should be cautioned against operating hazardous machinery or driving.
INSERT INTO "drug_generic" VALUES(639, 'Ribociclib', 'Ribociclib', 'L01EF02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "QT Prolongation and Hepatotoxicity", "severity": "High", "trigger_condition": "Baseline and ongoing monitoring", "message": "STOP: Ribociclib can cause concentration-dependent QT prolongation and severe hepatotoxicity. Monitor ECG and liver function tests (LFTs) at baseline and periodically during treatment. Avoid concomitant use of strong CYP3A4 inhibitors or QT-prolonging drugs."}]', '**QT Interval Prolongation:** Ribociclib has been shown to prolong the QT interval in a concentration-dependent manner. Assess ECG prior to initiation, at Day 14 of the first cycle, at the beginning of the second cycle, and as clinically indicated. Correct hypokalemia, hypocalcemia, and hypomagnesemia prior to starting treatment.
INSERT INTO "drug_generic" VALUES(640, 'Bacitracin Zinc + Polymixin B Eye prep', 'Bacitracin and Polymyxin B Ophthalmic', 'S01AA30', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Ophthalmic Use Only", "severity": "Low", "message": "For topical ophthalmic use only. Do not inject into the eye or use systemically."}]', '**Visual Disturbances:** Ointment formulations may cause temporary blurred vision immediately after application. Patients should be cautioned against driving or operating machinery until vision clears.
INSERT INTO "drug_generic" VALUES(641, 'Anhydrous Glucose + Potassium Chloride + Sodium Chloride + Sodium Bicarbonate', 'Oral Rehydration Salts', 'A07CA', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Reconstitution Error", "severity": "High", "trigger_condition": "Improper dilution of powder", "message": "STOP: Use fresh drinking water ONLY to mix the formula. Never dilute with milk, soft drinks, or cordials. A stronger solution than recommended can cause fatal hypernatremia."}]', '**Severe Dehydration:** Oral rehydration is not sufficient for patients with severe dehydration, shock, very large stool losses, or severe vomiting. Intravenous fluid replacement is required in these cases.
INSERT INTO "drug_generic" VALUES(642, 'Nitrous Oxide 50 % + Oxygen 50 % Gas', 'Nitrous Oxide and Oxygen', 'N01AX13', 0, 1, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Expansion of Gas-Filled Spaces", "severity": "High", "trigger_condition": "Administration to patients with pneumothorax, bowel obstruction, or recent middle ear surgery", "message": "STOP: Nitrous oxide diffuses into closed, gas-filled body spaces faster than nitrogen diffuses out, causing a rapid and potentially fatal increase in pressure and volume. Strictly contraindicated in pneumothorax or bowel obstruction."}]', 'Prolonged or frequent use of nitrous oxide can interfere with vitamin B12 metabolism, leading to megaloblastic anemia, myeloneuropathy, and subacute combined degeneration of the spinal cord. It should be used with extreme caution in patients with pre-existing vitamin B12 deficiency, pernicious anemia, or those on a strict vegan diet. Hematological monitoring is required if used for more than 24 hours or more frequently than every 4 days. Prolonged inhalation may also cause significant dryness of the mucous membranes and oral discomfort. Ensure adequate scavenging systems are in place to prevent occupational exposure to healthcare workers.', '- **Procedural Sedation and Analgesia:** Used for short-term pain relief and anxiolysis during minor procedures such as wound debridement, suturing, burn dressings, and fracture or joint manipulation.
INSERT INTO "drug_generic" VALUES(643, 'Dextrose 30%', 'Dextrose 30%', 'B05BA03', 0, 1, 1, 1, 1, 0, 1, 1, '[{"alert_type": "Tissue Necrosis and Extravasation", "severity": "High", "trigger_condition": "Peripheral intravenous administration", "message": "STOP: Hypertonic dextrose solutions (>10%) can cause severe tissue necrosis if extravasation occurs. Must be administered via a central venous catheter."}, {"alert_type": "Hyperosmolar Syndrome", "severity": "High", "trigger_condition": "Rapid infusion rate", "message": "Rapid administration can lead to hyperosmolar coma, severe hyperglycemia, and osmotic diuresis. Monitor infusion rates strictly."}]', '**Central Venous Administration:** Hypertonic dextrose solutions (above 10%) must be administered via a central venous catheter to prevent venous thrombosis, phlebitis, and severe tissue necrosis from extravasation.
INSERT INTO "drug_generic" VALUES(644, 'Povidone Iodine 1%  Mouth-Wash/Gargle', 'Povidone-Iodine Oral', 'A01AB12', 1, 0, 0, 0, 1, 1, 0, 0, '[]', 'Avoid contact with eyes. Do not swallow the solution. Prolonged use may lead to systemic iodine absorption, which can interfere with thyroid function tests and cause thyroid dysfunction. Exercise caution in patients with pre-existing renal insufficiency. Discontinue use if local irritation or hypersensitivity occurs.', '- **Oral Candidiasis:** Treatment of fungal infections in the oral cavity.
INSERT INTO "drug_generic" VALUES(645, 'Emollient', 'Emollient', 'D02AX', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Route of Administration Error", "severity": "Low", "trigger_condition": "Accidental ingestion or ophthalmic application", "message": "WARNING: For external use only. Avoid contact with eyes. If accidental ocular exposure occurs, flush thoroughly with water."}]', '**Skin Irritation:** Formulations containing cetostearyl alcohol and potassium sorbate may cause localized skin irritation or contact dermatitis. Discontinue use if hypersensitivity or severe irritation occurs.
INSERT INTO "drug_generic" VALUES(646, 'Aflibercept', 'Aflibercept', 'L01SG01', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Ocular Toxicity and Thromboembolic Events", "severity": "High", "trigger_condition": "Intravitreal administration or systemic VEGF inhibitor therapy", "message": "STOP: Intravitreal injections can cause severe endophthalmitis, retinal detachment, and increased intraocular pressure. Systemic use carries a risk of fatal arterial thromboembolic events, hemorrhage, and gastrointestinal perforation."}]', '**Ocular Complications (Intravitreal Use)**
INSERT INTO "drug_generic" VALUES(647, 'Hydrochlorothiazide + Lisinopril', 'Lisinopril/Hydrochlorothiazide', 'C09BA03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy", "message": "STOP: When pregnancy is detected, discontinue lisinopril/hydrochlorothiazide as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}]', '**Angioedema:** ACE inhibitors can cause angioedema of the face, extremities, lips, tongue, glottis, and larynx. Discontinue immediately if this occurs. Coadministration with mTOR inhibitors or neprilysin inhibitors increases this risk.
INSERT INTO "drug_generic" VALUES(648, 'Glycerol', 'Glycerin', 'A06AX01', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Systemic Absorption Risks (Suppository):** Use with caution in patients with hypervolemia, cardiac failure, renal disease, or severe dehydration, as systemic absorption of glycerol can alter plasma osmolality.
INSERT INTO "drug_generic" VALUES(649, 'Sulfasalazine', 'Sulfasalazine', 'A07EC01', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Hypersensitivity and Blood Dyscrasias", "severity": "High", "trigger_condition": "History of sulfonamide or salicylate allergy", "message": "STOP: Severe hypersensitivity reactions (including Stevens-Johnson syndrome, toxic epidermal necrolysis) and fatal blood dyscrasias (agranulocytosis, aplastic anemia) can occur. Discontinue immediately if rash, fever, or signs of systemic illness develop."}]', '**Blood Dyscrasias:** Fatalities associated with severe reactions such as agranulocytosis, aplastic anemia, and other blood dyscrasias have occurred. Monitor complete blood counts (CBC) frequently.
INSERT INTO "drug_generic" VALUES(650, 'Tadalafil', 'Tadalafil', 'G04BE08', 0, 0, 1, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Hypotension", "severity": "High", "trigger_condition": "Concurrent use with nitrates or nitric oxide donors", "message": "STOP: Co-administration with any form of organic nitrates is strictly contraindicated due to the risk of profound, potentially fatal hypotension."}]', 'Use with caution in patients with cardiovascular disease, left ventricular outflow obstruction, uncontrolled hypertension, or hypotension. Evaluate cardiovascular status before initiating treatment for erectile dysfunction. Caution in patients with anatomical deformation of the penis (e.g., Peyronie''s disease) or conditions predisposing to priapism (e.g., sickle cell anemia, multiple myeloma, leukemia). Discontinue immediately and seek medical advice if sudden vision loss (NAION) or sudden hearing loss/tinnitus occurs. Caution in severe hepatic or renal impairment.', '- **Erectile Dysfunction (ED):** Treatment of erectile dysfunction in adult males.
INSERT INTO "drug_generic" VALUES(651, 'Pneumococcal polysaccharide conjugate vaccine 13-valent (adsorbed)', 'Pneumococcal 13-valent Conjugate Vaccine', 'J07AL02', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "History of severe allergic reaction to diphtheria toxoid or vaccine components", "message": "STOP: Severe allergic reactions, including anaphylaxis, can occur. Ensure immediate availability of epinephrine and appropriate medical treatment during administration."}]', 'Postpone administration in patients suffering from acute severe febrile illness.
INSERT INTO "drug_generic" VALUES(652, 'Methotrexate', 'Methotrexate', 'L01BA01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fatal Dosing Error", "severity": "High", "trigger_condition": "Prescribing for Rheumatoid Arthritis or Psoriasis", "message": "STOP: For autoimmune diseases (RA, Psoriasis), Methotrexate is dosed ONCE WEEKLY. Daily administration has resulted in fatal toxicity. Verify the dosing schedule explicitly."}, {"alert_type": "Severe Toxicity", "severity": "High", "trigger_condition": "Renal impairment, hepatic impairment, or concurrent use of NSAIDs", "message": "STOP: Methotrexate can cause fatal bone marrow suppression, hepatotoxicity, pulmonary toxicity, and nephrotoxicity. Monitor CBC, LFTs, and renal function closely."}]', 'Methotrexate must be used only by physicians experienced in antimetabolite therapy. Fatalities have occurred with daily administration intended for weekly dosing; ensure prescriptions clearly state "ONCE WEEKLY" for non-oncologic indications. Monitor complete blood counts, renal function, and liver function tests at baseline and periodically. Methotrexate can cause severe hepatotoxicity, including fibrosis and cirrhosis, particularly with prolonged use; avoid alcohol consumption. Pulmonary toxicity (e.g., acute or chronic interstitial pneumonitis) can occur at any dose and may be fatal; monitor for dry, nonproductive cough or dyspnea. Methotrexate clearance is reduced in patients with renal impairment, ascites, or pleural effusions, increasing the risk of severe toxicity. Use with extreme caution in patients with active infections or peptic ulcer disease.', '- **Neoplastic Diseases:** Treatment of gestational choriocarcinoma, chorioadenoma destruens, hydatidiform mole, acute lymphoblastic leukemia (ALL), advanced non-Hodgkin’s lymphomas, breast cancer, epidermoid cancers of the head and neck, advanced mycosis fungoides, and lung cancer.
INSERT INTO "drug_generic" VALUES(653, 'Phenoxymethyl Penicillin', 'Penicillin V Potassium', 'J01CE02', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported in patients on penicillin therapy. Cross-sensitivity with cephalosporins may occur. Discontinue immediately if an allergic reaction occurs.
INSERT INTO "drug_generic" VALUES(654, 'Midazolam', 'Midazolam', 'N05CD08', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Respiratory Depression and Arrest", "severity": "High", "trigger_condition": "Intravenous administration, especially rapid injection or use with other CNS depressants", "message": "STOP: Intravenous midazolam has been associated with severe respiratory depression and respiratory arrest. Continuous monitoring of respiratory and cardiac function is mandatory. Resuscitative equipment must be immediately available."}]', 'Use with extreme caution in patients with heart failure, impaired gag reflex, or chronic respiratory diseases (e.g., COPD) due to the heightened risk of respiratory depression.
INSERT INTO "drug_generic" VALUES(655, 'Galantamine', 'Galantamine', 'N06DA04', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Cardiovascular Effects", "severity": "High", "trigger_condition": "Pre-existing cardiac conduction abnormalities", "message": "STOP: Cholinesterase inhibitors can cause vagotonic effects on the sinoatrial and atrioventricular nodes, leading to severe bradycardia and heart block. Monitor heart rate closely."}]', 'Use with caution in patients with mild to moderate hepatic impairment; dosage adjustments are required.
INSERT INTO "drug_generic" VALUES(656, 'Oxyphencyclimine Hydrochloride', 'Oxyphencyclimine Hydrochloride', 'A03AA03', 0, 0, 0, 0, 1, 1, 0, 0, '[]', '**Cardiovascular Disease:** Use with caution in patients with congestive heart failure, coronary artery disease, tachyarrhythmias, or hypertension, as anticholinergic effects can exacerbate tachycardia.
INSERT INTO "drug_generic" VALUES(657, 'Finerenone', 'Finerenone', 'C03DA05', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hyperkalemia Risk", "severity": "High", "trigger_condition": "Baseline serum potassium >5.0 mEq/L or declining eGFR", "message": "STOP: Finerenone can cause severe hyperkalemia. Do not initiate if serum potassium is >5.0 mEq/L. Monitor potassium and eGFR regularly and adjust dose accordingly."}]', '**Hyperkalemia:** Can cause hyperkalemia. The risk increases with decreasing kidney function and is greater with higher baseline potassium levels or concomitant use of medications that impair potassium excretion. Measure serum potassium and eGFR before initiating. Periodically monitor during treatment.
INSERT INTO "drug_generic" VALUES(658, 'Hydroxocobalamin', 'Hydroxocobalamin', 'V03AB33', 0, 1, 1, 0, 0, 1, 1, 0, '[{"alert_type": "Diagnostic Interference", "severity": "Moderate", "trigger_condition": "Administration prior to laboratory testing", "message": "Hydroxocobalamin causes deep red discoloration of plasma and urine, which severely interferes with colorimetric laboratory tests (e.g., AST, ALT, bilirubin, creatinine, hemoglobin) for up to several days. Draw baseline labs before administration if possible."}]', 'The validity of diagnostic vitamin B12 or folic acid blood assays could be compromised by medications; consider this before relying on such tests. Vitamin B12 is not a substitute for folic acid; indiscriminate use could mask the true diagnosis of folic acid deficiency. Hypokalemia and thrombocytosis can occur upon conversion of severe megaloblastic anemia to normal erythropoiesis; monitor serum potassium and platelet counts carefully. May unmask polycythemia vera. In cyanide poisoning, do not delay treatment to obtain confirmatory labs. Caution when administering other cyanide antidotes simultaneously; do not mix in the same IV line.', '- **Cyanide Poisoning:** Treatment of known or suspected cyanide poisoning (e.g., from smoke inhalation in closed-space fires, industrial exposure, or ingestion of cyanogenic compounds).
INSERT INTO "drug_generic" VALUES(659, 'Vitamin B1 + Vitamin B2 + Nicotinamide + Vitamin B6 + Pantothenic Acid + Vitamin C + Biotin + Folic Acid + Vitamin B12 Inj', 'Multivitamin Infusion (Water-Soluble)', 'A11EB', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Intravenous administration in susceptible individuals", "message": "STOP: Severe allergic reactions, including anaphylaxis, can occur with intravenous vitamin administration. Administer slowly and monitor the patient closely during the infusion."}]', 'Administering folic acid may obscure the hematological signs of pernicious anemia while neurological damage progresses. In patients receiving total parenteral nutrition (TPN) for prolonged periods, periodic monitoring of blood vitamin levels is recommended to prevent deficiency or toxicity. Daily vitamin requirements must be calculated carefully, especially in pediatric patients. To prevent excessive renal excretion and ensure safety, the daily dosage should be infused slowly over several hours.', '- **Parenteral Nutrition Supplementation:** Indicated as a daily supplement for intravenous nutrition to meet the requirements of water-soluble vitamins in infants, children, and adults when oral intake is contraindicated, impossible, or insufficient.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to any of the vitamins or excipients in the preparation.', '- Rise in body temperature
INSERT INTO "drug_generic" VALUES(660, 'Amlodipine + Benazepril Hydrochloride', 'Amlodipine and Benazepril', 'C09BB07', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected during therapy", "message": "STOP: ACE inhibitors can cause injury and death to the developing fetus. Discontinue amlodipine/benazepril as soon as possible when pregnancy is detected."}, {"alert_type": "Angioedema", "severity": "High", "trigger_condition": "Swelling of the face, lips, tongue, or airway", "message": "STOP: Severe, life-threatening angioedema can occur at any time during treatment. Discontinue immediately and secure the airway if laryngeal edema occurs."}]', '**Hypotension:** Symptomatic hypotension can occur, especially in patients with severe volume or salt depletion (e.g., those treated with high-dose diuretics). Correct volume depletion prior to initiation.
INSERT INTO "drug_generic" VALUES(661, 'Chlorpromazine Hydrochloride', 'Chlorpromazine', 'N05AA01', 0, 1, 0, 0, 1, 1, 1, 1, '[{"alert_type": "Increased Mortality in Elderly Patients with Dementia-Related Psychosis", "severity": "High", "trigger_condition": "Use in elderly patients with dementia", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Chlorpromazine is not approved for the treatment of patients with dementia-related psychosis."}]', '**Tardive Dyskinesia (TD):** A syndrome of potentially irreversible, involuntary, dyskinetic movements may develop in patients treated with antipsychotic drugs. The risk appears to be highest among the elderly, especially elderly women. Discontinue if signs of TD appear.
INSERT INTO "drug_generic" VALUES(662, 'Benzydamine Mouth prep', 'Benzydamine Oral Rinse', 'A01AD02', 0, 0, 0, 0, 1, 0, 0, 0, '[]', '**Local Irritation:** The use of undiluted benzydamine hydrochloride may produce local irritation manifested by a burning or stinging sensation, particularly in patients with mucosal defects. If this occurs, the solution should be diluted (1:1) with lukewarm water.
INSERT INTO "drug_generic" VALUES(663, 'Tacrolimus 0.1%, 0.03% Topical', 'Tacrolimus Topical', 'D11AH01', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Malignancy Risk", "severity": "High", "trigger_condition": "Prolonged or continuous long-term use", "message": "STOP: Rare cases of malignancy (e.g., skin cancer and lymphoma) have been reported. Avoid continuous long-term use. Limit application to areas of involvement."}]', 'Use with caution on the face or neck, or over large areas of the body (do not exceed 50% of total body surface area). Do not use on broken skin or open wounds. Ensure clinical infections at the treatment site are cleared prior to initiating therapy. Delay use in patients with unknown causes of lymphadenopathy or acute infectious mononucleosis until resolution. Use in patients with Netherton''s syndrome or generalized erythroderma is not recommended due to the potential for increased systemic absorption. Minimize exposure to natural or artificial sunlight (UV light) during treatment.', '- **Atopic Dermatitis:** Indicated as second-line therapy for the short-term and non-continuous chronic treatment of moderate to severe atopic dermatitis in non-immunocompromised adults and children who have failed to respond adequately to other topical prescription treatments, or when those treatments are not advisable.
INSERT INTO "drug_generic" VALUES(664, 'Factor IX Complex', 'Factor IX Complex (Human)', 'B02BD04', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Thromboembolic Complications", "severity": "High", "trigger_condition": "High doses, rapid infusion, or use in patients with hepatic impairment", "message": "STOP: Factor IX Complex contains trace amounts of activated clotting factors. Use carries a significant risk of thromboembolism, disseminated intravascular coagulation (DIC), and myocardial infarction, especially in patients with liver disease or those undergoing major surgery."}]', '**Thromboembolic Risk:** High risk of thrombosis and disseminated intravascular coagulation (DIC). Use with extreme caution in patients with hepatic impairment, neonates, or patients undergoing major surgery. Monitor for signs of DIC or thrombosis (e.g., changes in blood pressure, pulse rate, respiratory distress, chest pain).
INSERT INTO "drug_generic" VALUES(665, 'Salmeterol +  Fluticasone', 'Salmeterol and Fluticasone', 'R03AK06', 0, 0, 1, 1, 0, 0, 1, 1, '[{"alert_type": "Asthma-Related Death Risk", "severity": "High", "trigger_condition": "Use as monotherapy or during acute bronchospasm", "message": "STOP: Long-acting beta2-adrenergic agonists (LABA) increase the risk of asthma-related death. This combination must NOT be used for acute bronchospasm or status asthmaticus."}]', '- **Infections:** Use with caution in patients with active or quiescent pulmonary tuberculosis, untreated systemic fungal, bacterial, viral, or parasitic infections, or ocular herpes simplex.
INSERT INTO "drug_generic" VALUES(666, 'Salicylic acid 2% Topical', 'Salicylic Acid Topical', 'D10AE', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Salicylate Toxicity", "severity": "Moderate", "trigger_condition": "Prolonged use over large body surface areas", "message": "Risk of systemic salicylate toxicity (salicylism). Avoid prolonged use in high concentrations over large areas, especially in children or patients with renal impairment."}]', 'Avoid contact with eyes, mouth, mucous membranes, and the anogenital region. Do not apply to broken, inflamed, or infected skin. Use with caution in patients with diabetes or impaired peripheral circulation due to the risk of severe tissue necrosis. Discontinue use if excessive burning, dryness, or severe irritation occurs. Not intended for prolonged use over large surface areas due to the risk of systemic absorption.', '- **Acne Vulgaris:** Topical treatment of mild to moderate acne to reduce comedones and inflammation.
INSERT INTO "drug_generic" VALUES(667, 'Sodium Cromoglycate 4%  Eye/Nasal prep', 'Cromolyn Sodium 4% Ophthalmic/Nasal', 'S01GX01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Contact Lens Precaution", "severity": "Low", "trigger_condition": "Use of eye drops containing benzalkonium chloride", "message": "This preparation contains benzalkonium chloride. Patients should not wear soft contact lenses during treatment, as the preservative can be absorbed and cause ocular irritation."}]', 'For ophthalmic use, patients should be advised not to wear soft contact lenses during treatment due to the presence of benzalkonium chloride. For nasal use, regular administration is required for optimal prophylactic effect; it is not effective for the acute relief of severe nasal congestion. If symptoms do not improve after 1-2 weeks of regular use, the clinical situation should be re-evaluated.', '- **Allergic Conjunctivitis:** Indicated for the prevention and treatment of acute and chronic allergic conjunctivitis, including vernal keratoconjunctivitis.
INSERT INTO "drug_generic" VALUES(668, 'Cariprazine', 'Cariprazine', 'N05AX15', 0, 1, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Increased Mortality in Elderly with Dementia", "severity": "High", "trigger_condition": "Elderly patients with dementia-related psychosis", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Cariprazine is not approved for the treatment of patients with dementia-related psychosis."}, {"alert_type": "Suicidal Thoughts and Behaviors", "severity": "High", "trigger_condition": "Pediatric and young adult patients", "message": "WARNING: Antidepressants and antipsychotics increase the risk of suicidal thoughts and behaviors in pediatric and young adult patients. Closely monitor for clinical worsening and emergence of suicidal thoughts."}]', '**Neuroleptic Malignant Syndrome (NMS):** A potentially fatal symptom complex. Monitor for hyperpyrexia, muscle rigidity, delirium, autonomic instability, and elevated CPK. Manage with immediate discontinuation and intensive symptomatic treatment.
INSERT INTO "drug_generic" VALUES(669, 'Sodium Fusidate (Fusidic Acid) 2% Topical', 'Fusidic Acid Topical', 'D06AX01', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Antimicrobial Resistance", "severity": "Moderate", "trigger_condition": "Prolonged or repeated use", "message": "STOP: Extended or recurrent use may increase the risk of contact sensitization and the development of antibiotic resistance. Limit treatment duration to the recommended period (usually 7-14 days)."}]', '- **Ocular Exposure:** Caution should be observed when applying near the eye region, as the preparation may cause severe irritation if it gets into the eye.
INSERT INTO "drug_generic" VALUES(670, 'Insulin Lispro', 'Insulin Lispro', 'A10AB04', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypoglycemia", "severity": "High", "trigger_condition": "Missed meals, excessive exercise, or incorrect dosing", "message": "STOP: Severe, life-threatening hypoglycemia can occur rapidly. Must be administered within 15 minutes before or immediately after a meal."}]', 'Monitor blood glucose frequently. Insulin requirements may change significantly during stress, illness, fever, trauma, infection, or surgery (requirements usually increase), or with diarrhea, nausea/vomiting, malabsorption, or hypothyroidism (requirements usually decrease). Hypokalemia may occur; monitor serum potassium in at-risk patients. Use with caution in patients with renal or hepatic impairment, as insulin requirements may be reduced. Monitor for injection site reactions, lipoatrophy, or lipohypertrophy; rotate injection sites. When used in an external insulin pump, do not mix with other insulins or dilute.', '- **Diabetes Mellitus:** Treatment of adult and pediatric patients with diabetes mellitus (Type 1 and Type 2) to improve glycemic control. Used as a rapid-acting prandial insulin to cover postprandial glucose spikes.', '- **Hypoglycemia:** Contraindicated during episodes of hypoglycemia.
INSERT INTO "drug_generic" VALUES(671, 'Levofloxacin 1.5% Eye prep', 'Levofloxacin Ophthalmic', 'S01AE05', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Administration Route Warning", "severity": "High", "trigger_condition": "Improper administration technique", "message": "STOP: For topical ophthalmic use only. This drug should NOT be injected subconjunctivally, nor should it be introduced directly into the anterior chamber of the eye."}]', '**Superinfection:** Prolonged use may result in the overgrowth of nonsusceptible organisms, including fungi. If superinfection occurs, discontinue use and institute alternative therapy.
INSERT INTO "drug_generic" VALUES(672, 'Caprylic + Capric Triglyceride topical', 'Caprylic/Capric Triglyceride', 'D02AX', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Local Irritation:** Discontinue use and consult a dermatologist if undue irritation, redness, or hypersensitivity develops or increases during application.
INSERT INTO "drug_generic" VALUES(673, 'Deferoxamine Mesylate (Desferrioxamine Mesylate)', 'Deferoxamine Mesylate', 'V03AC01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Rapid IV Infusion Risk", "severity": "High", "trigger_condition": "Rapid intravenous administration", "message": "STOP: Rapid intravenous injection can cause severe flushing, urticaria, hypotension, and shock. Administer via IM, slow SC, or slow IV infusion only. Do not exceed 15 mg/kg/hr for IV infusion."}]', '**Mucormycosis Risk:** Rare cases of mucormycosis, some fatal, have been reported. If suspected signs or symptoms occur, discontinue treatment immediately, perform mycological tests, and institute appropriate antifungal treatment.
INSERT INTO "drug_generic" VALUES(674, 'Diclofenac Sodium', 'Diclofenac Sodium', 'M01AB05', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal bleeding, ulceration, and perforation. Contraindicated for CABG perioperative pain."}]', '**Cardiovascular Risk:** May lead to new-onset hypertension or worsening of pre-existing hypertension. Use with caution in patients with heart failure or fluid retention.
INSERT INTO "drug_generic" VALUES(675, 'Morphine Sulphate', 'Morphine Sulfate', 'N02AA01', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Respiratory Depression Risk", "severity": "High", "trigger_condition": "High doses, rapid IV administration, or concurrent use with other CNS depressants", "message": "WARNING: Serious, life-threatening, or fatal respiratory depression may occur. Monitor closely, especially during initiation or dose escalation. Keep naloxone readily available."}]', '**Respiratory Depression:** Life-threatening respiratory depression can occur. Use with extreme caution in patients with COPD, cor pulmonale, or substantially decreased respiratory reserve.
INSERT INTO "drug_generic" VALUES(676, 'Methylprednisolone Sodium Succinate', 'Methylprednisolone Sodium Succinate', 'H02AB04', 0, 0, 0, 1, 0, 0, 1, 1, '[{"alert_type": "Rapid IV Administration Risk", "severity": "High", "trigger_condition": "High-dose intravenous pulse therapy (>250 mg)", "message": "STOP: High doses (>250 mg) must be administered slowly over at least 30 minutes. Rapid IV injection can cause fatal cardiac arrhythmias and cardiovascular collapse."}]', '**Cardiovascular Collapse:** Rapid intravenous administration of high doses (e.g., >250 mg) has been associated with cardiac arrhythmias, sudden cardiac arrest, and cardiovascular collapse. Always administer high doses slowly over at least 30 minutes.
INSERT INTO "drug_generic" VALUES(677, 'Ammonium lactate', 'Ammonium Lactate', 'D02AX', 0, 0, 1, 1, 0, 1, 0, 0, '[]', '**Local Irritation:** Stinging or burning may occur when applied to skin with fissures, erosions, or that is otherwise abraded (e.g., after shaving legs). Use caution when applying to the face, as it may cause significant irritation.
INSERT INTO "drug_generic" VALUES(678, 'Oxytetracycline', 'Oxytetracycline', 'J01AA06', 1, 0, 0, 0, 1, 0, 0, 0, '[]', '**Tooth Discoloration and Bone Growth:** Use during tooth development (last half of pregnancy, infancy, and childhood up to 8 years) may cause permanent discoloration of the teeth (yellow-gray-brown) and reversible inhibition of bone growth. Avoid use in this age group unless other drugs are ineffective or contraindicated.
INSERT INTO "drug_generic" VALUES(679, 'Eucalyptol + Menthol + Methyl Salicylate + Thymol + Sodium Fluoride', 'Antiseptic Mouthwash with Fluoride', 'A01AD11', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Ingestion Risk", "severity": "Moderate", "trigger_condition": "Accidental swallowing, especially by children", "message": "STOP: Do not swallow. Accidental ingestion of large amounts of fluoride and essential oils can cause systemic toxicity. Keep out of reach of children under 12 years of age."}]', '**Proper Use:** Do not swallow the mouthwash. It is intended for topical oral use only as a rinse.
INSERT INTO "drug_generic" VALUES(680, 'Glyceryl Trinitrate 0.4% (nitroglycerine) Rectal prep', 'Nitroglycerin (Rectal)', 'C05AE01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Hypotension Risk", "severity": "High", "trigger_condition": "Concurrent use of Phosphodiesterase type-5 (PDE-5) inhibitors", "message": "STOP: Absolute contraindication. Co-administration with PDE-5 inhibitors (e.g., sildenafil, tadalafil, vardenafil) can cause profound, life-threatening hypotension. Do not use this ointment if taking these medications."}]', '**Hypotension:** May cause severe orthostatic hypotension. Use with caution in patients with volume depletion, pre-existing hypotension, or those taking antihypertensive medications.
INSERT INTO "drug_generic" VALUES(681, 'Luliconazole 1% Topical', 'Luliconazole', 'D01AC18', 0, 0, 0, 1, 0, 1, 1, 0, '[]', '**Ophthalmic and Intravaginal Avoidance:** This formulation is strictly for topical dermatological use. Avoid contact with eyes, mucous membranes, or intravaginal areas to prevent severe local irritation.
INSERT INTO "drug_generic" VALUES(682, 'Hydroxyurea (Hydroxycarbamide)', 'Hydroxyurea', 'L01XX05', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "STOP: Severe and potentially fatal bone marrow suppression (leukopenia, neutropenia, thrombocytopenia, and anemia) can occur. Do not initiate if bone marrow function is markedly depressed. Monitor blood counts regularly."}, {"alert_type": "Carcinogenicity", "severity": "High", "trigger_condition": "Long-term therapy", "message": "STOP: Hydroxyurea is leukemogenic and carcinogenic. Secondary leukemias and skin cancers have been reported with long-term use. Advise sun protection and monitor for secondary malignancies."}]', 'Regular and frequent monitoring of complete blood counts (CBC), renal function, and hepatic function is mandatory during therapy.
INSERT INTO "drug_generic" VALUES(683, 'Sodium Hypochlorite 0.5% Topical', 'Sodium Hypochlorite', 'D08AX07', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **External Use Only:** This product is strictly for external topical use. Do not ingest or administer systemically.
INSERT INTO "drug_generic" VALUES(684, 'Levamisole', 'Levamisole', 'P02CE01', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Agranulocytosis", "severity": "High", "trigger_condition": "Prolonged use or pre-existing blood disorders", "message": "STOP: Severe and potentially fatal agranulocytosis can occur. Monitor complete blood counts if used for prolonged periods. Contraindicated in patients with pre-existing blood disorders."}]', '**Hematologic Toxicity:** Agranulocytosis, leukopenia, and thrombocytopenia have been reported, particularly with prolonged use or higher doses. Monitor CBC if used beyond a single dose.
INSERT INTO "drug_generic" VALUES(685, 'Cyclosporine Eye prep', 'Cyclosporine Ophthalmic', 'S01XA18', 0, 0, 1, 1, 0, 1, 0, 0, '[]', '**Contact Lenses:** Should not be administered while wearing contact lenses. Patients with decreased tear production typically should not wear contact lenses. If worn, remove them prior to administration and wait at least 15 minutes before reinserting.
INSERT INTO "drug_generic" VALUES(686, 'Afatinib', 'Afatinib', 'L01EB03', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Diarrhea", "severity": "High", "trigger_condition": "Onset of severe or prolonged diarrhea", "message": "STOP: Severe diarrhea can result in life-threatening dehydration and renal failure. Withhold Afatinib for severe diarrhea not responsive to antidiarrheal agents and initiate aggressive hydration."}]', '**Diarrhea:** Severe diarrhea occurs frequently and can result in dehydration and renal failure. Advise patients to have antidiarrheal agents (e.g., loperamide) readily available. Withhold afatinib for severe and prolonged diarrhea not responsive to antidiarrheals.
INSERT INTO "drug_generic" VALUES(687, 'Dorzolamide 2% eye prep', 'Dorzolamide', 'S01EC03', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Sulfonamide Hypersensitivity", "severity": "High", "trigger_condition": "Patient history of severe sulfonamide allergy", "message": "STOP: Dorzolamide is a sulfonamide. Systemic absorption can occur, leading to severe reactions like Stevens-Johnson syndrome or toxic epidermal necrolysis."}]', 'Monitor intraocular pressure periodically to ensure therapeutic efficacy.
INSERT INTO "drug_generic" VALUES(688, 'Fluocinolone Acetonide  + Clioquinol topical', 'Fluocinolone Acetonide / Clioquinol', 'D07CC02', 1, 0, 0, 0, 0, 1, 0, 1, '[]', '**Systemic Absorption:** Systemic absorption of topical corticosteroids can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria. Risk increases with application over large surface areas, prolonged use, or use under occlusive dressings.
INSERT INTO "drug_generic" VALUES(689, 'Macitentan', 'Macitentan', 'C02KX04', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Use in females of reproductive potential", "message": "STOP: Macitentan is highly teratogenic. Exclude pregnancy before starting, ensure highly effective contraception during and for 1 month after treatment, and perform monthly pregnancy tests."}]', '**Hepatotoxicity:** ERAs have caused elevations of aminotransferases, hepatotoxicity, and liver failure. Obtain liver enzyme tests prior to initiation and monitor as clinically indicated. Discontinue if aminotransferase elevations are accompanied by clinical symptoms of hepatotoxicity or elevated bilirubin.
INSERT INTO "drug_generic" VALUES(690, 'Aluminium Oxide + Magnesium Hydroxide', 'Aluminum Hydroxide and Magnesium Hydroxide', 'A02AD01', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Drug Interactions", "severity": "Medium", "trigger_condition": "Concurrent administration with other oral medications", "message": "STOP: Antacids significantly decrease the absorption of many drugs (e.g., tetracyclines, fluoroquinolones, bisphosphonates). Administer antacids at least 2 hours before or after other medications."}]', '**Renal Impairment:** Use with caution in patients with chronic renal impairment. Magnesium and aluminum can accumulate, leading to hypermagnesemia and aluminum toxicity.
INSERT INTO "drug_generic" VALUES(691, 'Flurbiprofen', 'Flurbiprofen', 'M01AE09', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also cause an increased risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation of the stomach or intestines."}]', '- **Cardiovascular Risk:** NSAIDs may cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke, which can be fatal. This risk may increase with duration of use. Patients with cardiovascular disease or risk factors for cardiovascular disease may be at greater risk.
INSERT INTO "drug_generic" VALUES(692, 'Barium Sulphate', 'Barium Sulfate', 'V08BA01', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Aspiration Risk", "severity": "High", "trigger_condition": "Patients with swallowing disorders or history of aspiration", "message": "STOP: Aspiration of barium sulfate into the lungs can cause severe pneumonitis or fatal complications. Discontinue administration immediately if aspiration is suspected."}, {"alert_type": "Bowel Perforation", "severity": "High", "trigger_condition": "Patients with known or suspected GI perforation", "message": "STOP: Leakage of barium into the peritoneal cavity causes severe, potentially fatal peritonitis. Contraindicated in known or suspected GI perforation."}]', '**Bowel Impaction:** Barium sulfate can cause severe constipation and bowel impaction. Rehydrate the patient quickly post-procedure. Mild laxatives (e.g., milk of magnesia) are routinely recommended following the exam.
INSERT INTO "drug_generic" VALUES(693, 'Ganciclovir', 'Ganciclovir', 'J05AB06', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Hematologic Toxicity", "severity": "High", "trigger_condition": "Absolute neutrophil count <500 cells/mm\u00b3 or platelet count <25,000/mm\u00b3", "message": "STOP: Severe leukopenia, neutropenia, anemia, thrombocytopenia, and bone marrow failure can occur. Do not initiate or continue therapy if severe cytopenias are present."}, {"alert_type": "Carcinogenicity and Teratogenicity", "severity": "High", "trigger_condition": "Pregnancy or reproductive potential", "message": "WARNING: Ganciclovir is considered a potential human carcinogen and teratogen. It may cause birth defects and temporary or permanent inhibition of spermatogenesis. Strict contraceptive measures are required."}]', '**Hematologic Toxicity:** Granulocytopenia (neutropenia), anemia, and thrombocytopenia are common and potentially severe. Monitor complete blood counts (CBC) with differential and platelet counts frequently, especially in patients with baseline cytopenias or those receiving other myelosuppressive drugs.
INSERT INTO "drug_generic" VALUES(694, 'Tetracaine + Oxymetazoline intranasal', 'Tetracaine and Oxymetazoline', 'N01BA53', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Methemoglobinemia", "severity": "High", "trigger_condition": "Use of tetracaine, especially with other methemoglobin-inducing agents", "message": "STOP: Tetracaine can cause methemoglobinemia. Monitor for cyanosis, headache, lethargy, and dyspnea. Do not use in patients with a history of congenital or idiopathic methemoglobinemia."}]', '**Methemoglobinemia:** Tetracaine may cause methemoglobinemia, especially if coadministered with other drugs that also cause it. Initial signs (slate grey cyanosis of lips/nail beds) may be delayed for hours. Severe cases present with central cyanosis, CNS depression, seizures, and shock.
INSERT INTO "drug_generic" VALUES(695, 'Undenatured Type II Collagen + Glucosamine sulfate + Boswellia serrata + Boron', 'Undenatured Type II Collagen, Glucosamine, Boswellia, and Boron', 'M01AX', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Allergy Warning", "severity": "High", "trigger_condition": "Patient history of shellfish allergy", "message": "STOP: Glucosamine is often derived from the exoskeletons of shellfish. Use with extreme caution or avoid in patients with a known shellfish allergy due to the risk of severe hypersensitivity reactions."}]', '**Diabetes Mellitus:** Glucosamine may theoretically increase insulin resistance and affect glucose tolerance. Diabetic patients should monitor their blood glucose levels more frequently when initiating therapy.
INSERT INTO "drug_generic" VALUES(696, 'Hydrocortisone', 'Hydrocortisone', 'H02AB09', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Adrenal Insufficiency", "severity": "High", "trigger_condition": "Abrupt withdrawal after prolonged systemic therapy", "message": "STOP: Abrupt discontinuation of prolonged systemic corticosteroid therapy can precipitate potentially fatal acute adrenal insufficiency. Taper the dose gradually."}]', 'Use with extreme caution in patients with congestive heart failure, hypertension, diabetes mellitus, epilepsy, and in the elderly. Prolonged therapy increases the risk of hypothalamic-pituitary-adrenal (HPA) axis suppression, osteoporosis, and secondary infections. Gradual withdrawal is mandatory following prolonged systemic use to prevent acute adrenal crisis. Monitor blood pressure, blood glucose, and electrolytes regularly. Caution is advised in patients with a history of peptic ulcer disease, severe gastrointestinal disorders, or psychiatric conditions, as corticosteroids may exacerbate these states. May mask signs of infection and decrease resistance to new infections.', '- **Adrenocortical Insufficiency:** Primary or secondary adrenocortical insufficiency, acute adrenocortical insufficiency, and congenital adrenal hyperplasia.
INSERT INTO "drug_generic" VALUES(697, 'Salicylic Acid 16.7% + Lactic Acid 16.7% Topical', 'Salicylic Acid and Lactic Acid Topical', 'D11AF', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Salicylate Toxicity", "severity": "Moderate", "trigger_condition": "Prolonged use over large surface areas", "message": "STOP: Prolonged application over large areas can lead to systemic salicylate toxicity (tinnitus, nausea, vomiting). Limit application strictly to the affected lesion."}]', '- Avoid application to broken, irritated, or infected skin.
INSERT INTO "drug_generic" VALUES(698, 'Leuprolide acetate', 'Leuprolide acetate', 'L02AE02', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Tumor Flare and Spinal Cord Compression", "severity": "High", "trigger_condition": "Initiation of therapy in patients with metastatic prostate cancer", "message": "STOP: Transient elevation of testosterone during the first 1-2 weeks of therapy can cause worsening of symptoms, including bone pain, neuropathy, hematuria, ureteral obstruction, and potentially fatal spinal cord compression. Monitor closely."}]', '**Tumor Flare:** Transient elevation of testosterone levels may occur during the first 1-2 weeks of treatment, potentially worsening symptoms (e.g., bone pain, neuropathy, hematuria) in prostate cancer patients. Closely monitor patients with urinary obstruction or metastatic vertebral lesions for ureteral obstruction and spinal cord compression.
INSERT INTO "drug_generic" VALUES(699, 'Timolol Maleate 0.5% Eye prep', 'Timolol Ophthalmic', 'S01ED01', 0, 0, 0, 0, 0, 1, 0, 0, '[]', 'Systemic absorption can occur following topical ophthalmic administration, leading to severe respiratory and cardiac reactions, including death due to bronchospasm or cardiac failure.
INSERT INTO "drug_generic" VALUES(700, 'Benzoyl Peroxide 5% + Erythromycin 3% topical', 'Erythromycin and Benzoyl Peroxide', 'D10AF52', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Bleaching and Photosensitivity", "severity": "Medium", "trigger_condition": "Application of product", "message": "STOP: Benzoyl peroxide can bleach hair and colored fabrics (towels, pillowcases, clothing). It also increases sensitivity to sunlight; strict sun protection is required."}]', '**Skin Irritation:** Erythema, scaling, dryness, and stinging/burning are very common. If severe, patients should use a non-comedogenic moisturizer, reduce the frequency of application, or temporarily discontinue use.
INSERT INTO "drug_generic" VALUES(701, 'Racecadotril', 'Racecadotril', 'A07CG04', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Invasive Diarrhea Warning", "severity": "High", "trigger_condition": "Presence of bloody/purulent stools or high fever", "message": "STOP: Racecadotril should not be used in dysentery (bloody or purulent stools accompanied by fever) or antibiotic-associated diarrhea, as these indicate an invasive bacterial infection requiring specific antimicrobial therapy."}]', 'Racecadotril is an adjunct therapy; it does not replace the need for adequate oral or intravenous rehydration. Rehydration must always be the primary treatment for acute diarrhea.
INSERT INTO "drug_generic" VALUES(702, 'Benzyl Benzoate 25% topical', 'Benzyl Benzoate', 'P03AX01', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Low", "message": "For external use only. Avoid contact with the eyes, face, and mucous membranes. Do not apply to broken, severely irritated, or secondarily infected skin."}]', '**Skin Irritation:** Benzyl benzoate is a strong skin irritant. It can cause severe burning, stinging, and contact dermatitis. Use with caution in patients with sensitive skin.
INSERT INTO "drug_generic" VALUES(703, 'Atovaquone + Proguanil', 'Atovaquone and Proguanil', 'P01BB51', 1, 0, 0, 0, 1, 0, 1, 0, '[]', 'This combination does not provide a radical cure for *Plasmodium vivax* or *Plasmodium ovale* and does not prevent delayed primary attacks; a tissue schizonticide (e.g., primaquine) is required for radical cure. It is not indicated for the treatment of severe or complicated malaria (e.g., cerebral malaria, hyperparasitemia, pulmonary edema, renal failure). Absorption is significantly reduced in patients with diarrhea or vomiting; monitor closely and consider antiemetics or alternative parenteral therapy. Elevated liver function tests and rare cases of hepatitis have been reported. Prophylaxis should not be prematurely discontinued and must be combined with protective measures (e.g., bednets, insect repellents).', '- **Malaria Prophylaxis:** Indicated for the prophylaxis of *Plasmodium falciparum* malaria, including in areas where chloroquine resistance has been reported.
INSERT INTO "drug_generic" VALUES(704, 'Dextrose 100 %', 'Dextrose (Oral)', 'V04CA02', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Diabetes Mellitus:** Use with caution in patients with known subclinical or overt diabetes mellitus, as it will cause a rapid spike in blood glucose levels.
INSERT INTO "drug_generic" VALUES(705, 'Dextrose 5%', 'Dextrose 5% in Water (D5W)', 'B05BA03', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hyponatremia and Water Intoxication", "severity": "High", "trigger_condition": "Prolonged infusion without electrolyte supplementation", "message": "Prolonged infusion of isotonic dextrose without electrolytes can cause severe dilutional hyponatremia and water intoxication, potentially leading to cerebral edema and seizures."}]', '**Water Intoxication and Hyponatremia:** Dextrose 5% is isotonic in the bag but becomes hypotonic in the body as dextrose is rapidly metabolized, leaving free water. Prolonged infusion can cause severe dilutional hyponatremia, water intoxication, and cerebral edema. Monitor serum sodium closely.
INSERT INTO "drug_generic" VALUES(706, 'Bempedoic acid + Ezetimibe', 'Bempedoic acid and Ezetimibe', 'C10BA10', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Tendon Rupture Risk", "severity": "High", "trigger_condition": "Patients over 60 years of age, taking corticosteroids or fluoroquinolones, or with a history of tendon disorders", "message": "STOP: Bempedoic acid is associated with an increased risk of tendon rupture. Discontinue immediately if joint pain, swelling, or inflammation occurs."}]', '**Hyperuricemia:** Bempedoic acid inhibits renal tubular OAT2, which may increase blood uric acid levels. Elevated uric acid levels usually occur within the first 4 weeks of treatment initiation and persist throughout treatment. This may lead to the development of gout. Monitor uric acid levels periodically and treat as clinically indicated.
INSERT INTO "drug_generic" VALUES(707, 'Atenolol + Chlorthalidone', 'Atenolol and Chlorthalidone', 'C07CB03', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Abrupt Discontinuation", "severity": "High", "trigger_condition": "Sudden cessation of therapy", "message": "STOP: Severe exacerbation of angina, myocardial infarction, and ventricular arrhythmias have occurred following the abrupt discontinuation of beta-blockers. Taper the dose gradually over 1 to 2 weeks."}]', '**Electrolyte Imbalance:** Chlorthalidone can cause hypokalemia, hyponatremia, and hypochloremic alkalosis. Monitor serum electrolytes regularly.
INSERT INTO "drug_generic" VALUES(708, 'Felbinac', 'Felbinac', 'M02AA08', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Application Site Warning", "severity": "Moderate", "trigger_condition": "Application to compromised skin", "message": "Do not use on broken or denuded skin, or in the presence of local infection. Avoid contact with eyes and mucous membranes."}]', '**Systemic Absorption:** Although systemic effects are low, use with caution in patients with severe renal, cardiac, or hepatic impairment, a history of peptic ulceration, inflammatory bowel disease, or bleeding diathesis.
INSERT INTO "drug_generic" VALUES(709, 'Bumetanide', 'Bumetanide', 'C03CA02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Profound Diuresis and Electrolyte Depletion", "severity": "High", "trigger_condition": "Excessive dosing or inadequate monitoring", "message": "WARNING: Bumetanide is a potent loop diuretic. Excessive amounts can lead to profound diuresis with water and electrolyte depletion. Careful medical supervision and dose adjustment are required."}]', 'Risk of severe electrolyte imbalance (hypokalemia, hyponatremia, hypochloremia, hypomagnesemia, hypocalcemia). Close medical supervision and regular monitoring of serum electrolytes are required. Potassium supplementation or potassium-sparing diuretics may be necessary.
INSERT INTO "drug_generic" VALUES(710, 'Aluminium Hydroxide', 'Aluminum Hydroxide', 'A02AB01', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Aluminum Toxicity", "severity": "High", "trigger_condition": "Prolonged use in patients with severe renal impairment", "message": "STOP: Accumulation of aluminum can lead to severe neurotoxicity (encephalopathy) and osteomalacia in patients with chronic renal failure."}]', 'Use with extreme caution in patients with chronic renal impairment due to the risk of aluminum accumulation and subsequent toxicity. Caution is advised in patients with congestive heart failure, edema, cirrhosis, or those on low-sodium diets, as some formulations may contain significant sodium. Use carefully in patients with recent gastrointestinal hemorrhage. To minimize drug interactions, administer this medication 2 to 3 hours before or after taking other oral medications.', '- **Peptic Ulcer Disease & Gastric Hyperacidity:** Used to neutralize gastric acid, providing symptomatic relief of heartburn, indigestion, and upset stomach.
INSERT INTO "drug_generic" VALUES(711, 'Precipitated Sulpher 10% + Salicylic Acid 3%', 'Sulfur and Salicylic Acid', 'D10AB52', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '- **Skin Irritation:** Excessive drying, peeling, and irritation may occur. Avoid simultaneous use with other topical acne preparations, peeling agents, alcohol-containing products, abrasive cleansers, or medicated cosmetics unless directed by a physician.
INSERT INTO "drug_generic" VALUES(712, 'Adapalene 0.1% + Benzoyl Peroxide 2.5% Topical', 'Adapalene and Benzoyl Peroxide', 'D10AD53', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Bleaching and Photosensitivity", "severity": "Medium", "trigger_condition": "Application of product", "message": "STOP: Benzoyl peroxide can bleach hair and colored fabrics (towels, pillowcases, clothing). Adapalene causes photosensitivity; strict sun protection is required."}]', '**Skin Irritation:** Erythema, scaling, dryness, and stinging/burning are very common, especially during the first 4 weeks. If severe, patients should use a non-comedogenic moisturizer, reduce the frequency of application, or temporarily discontinue use.
INSERT INTO "drug_generic" VALUES(713, 'Alosetron', 'Alosetron', 'A03AE01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Ischemic Colitis and Severe Constipation", "severity": "High", "trigger_condition": "Development of new or worsening abdominal pain, bloody diarrhea, or severe constipation", "message": "STOP: Infrequent but serious gastrointestinal adverse reactions, including ischemic colitis and severe complications of constipation (obstruction, perforation, toxic megacolon), have occurred. Discontinue immediately and evaluate."}]', '**Ischemic Colitis:** Ischemic colitis has been reported with alosetron use, sometimes requiring hospitalization, blood transfusion, surgery, or resulting in death. Discontinue treatment immediately in patients who develop signs of ischemic colitis (e.g., rectal bleeding, bloody diarrhea, new or worsening abdominal pain). Do not resume therapy in these patients.
INSERT INTO "drug_generic" VALUES(714, 'Torsemide', 'Torsemide', 'C03CA04', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Profound Diuresis", "severity": "High", "trigger_condition": "High doses or inadequate fluid intake", "message": "STOP: Torsemide is a potent loop diuretic. Excessive amounts can lead to profound diuresis with water and electrolyte depletion. Careful medical supervision is required."}]', '**Electrolyte Imbalance:** Can cause hypokalemia, hyponatremia, and hypomagnesemia. Monitor serum electrolytes regularly and correct disturbances before initiating therapy.
INSERT INTO "drug_generic" VALUES(715, 'Alemtuzumab', 'Alemtuzumab', 'L04AG06', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Cytopenias and Infusion Reactions", "severity": "High", "trigger_condition": "Initiation of therapy or during infusion", "message": "STOP: Serious, including fatal, pancytopenia, marrow hypoplasia, autoimmune idiopathic thrombocytopenia, and autoimmune hemolytic anemia can occur. Serious infusion reactions may also occur. Monitor CBC and vital signs closely."}]', '**Autoimmune Conditions:** Patients may develop severe autoimmune conditions, including immune thrombocytopenia (ITP), autoimmune thyroid disorders, and autoimmune cytopenias. Monitor complete blood counts (CBC) with differential, serum creatinine, and urinalysis with microscopy at baseline and monthly thereafter.
INSERT INTO "drug_generic" VALUES(716, 'Pamidronic acid (Pamidronate)', 'Pamidronate', 'M05BA03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Osteonecrosis of the Jaw (ONJ) and Renal Toxicity", "severity": "High", "trigger_condition": "Long-term use or rapid intravenous infusion", "message": "STOP: Severe and sometimes fatal renal toxicity can occur; do not exceed the recommended infusion rate (max 60 mg/hr). Osteonecrosis of the jaw (ONJ) has been reported, primarily in cancer patients receiving intravenous bisphosphonates. A dental exam is required prior to initiation."}]', '**Renal Impairment:** Pamidronate is excreted intact primarily via the kidney. Risk of renal toxicity increases with higher doses and faster infusion rates. Monitor serum creatinine prior to each dose.
INSERT INTO "drug_generic" VALUES(717, 'Hylan G-F 20', 'Hylan G-F 20', 'M09AX01', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Intra-Articular Injection Precaution", "severity": "Moderate", "trigger_condition": "Post-injection period", "message": "Avoid strenuous physical activities (e.g., jogging, tennis, heavy lifting) or prolonged weight-bearing activities for 48 hours following intra-articular injection to prevent joint swelling and pain."}]', '**Avian Allergy:** Hylan G-F 20 is derived from rooster combs. Use with caution in patients who are allergic to avian proteins, feathers, and egg products.
INSERT INTO "drug_generic" VALUES(718, 'Paliperidone', 'Paliperidone', 'N05AX13', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Increased Mortality in Elderly Patients with Dementia-Related Psychosis", "severity": "High", "trigger_condition": "Use in elderly patients with dementia", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Paliperidone is not approved for the treatment of patients with dementia-related psychosis."}]', '**QT Prolongation:** Avoid use with other drugs that prolong the QTc interval or in patients with congenital long QT syndrome, cardiac arrhythmias, or severe hypokalemia/hypomagnesemia.
INSERT INTO "drug_generic" VALUES(719, 'Sodium Fluoride 0.022% Mouth prep', 'Sodium Fluoride', 'A01AA01', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Toxicity via Ingestion", "severity": "Moderate", "trigger_condition": "Swallowing the mouthwash, especially in young children", "message": "Do not swallow. Continuous systemic ingestion may result in fluoride toxicity, dental fluorosis, or osseous changes. Supervise use in children."}]', '- **Systemic Absorption:** Not for systemic use; do not swallow. Instruct patients to expectorate completely after rinsing.
INSERT INTO "drug_generic" VALUES(720, 'Polygeline + Calcium Chloride + Potassium Chloride + Sodium Chloride', 'Polygeline + Calcium Chloride + Potassium Chloride + Sodium Chloride', 'B05AA06', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Histamine Release", "severity": "High", "trigger_condition": "Patients with a history of allergic reactions or recent use of histamine-releasing drugs", "message": "STOP: Severe hypersensitivity reactions, including anaphylactic shock due to histamine release, can occur. Prophylactic H1 and H2 receptor antagonists may be required in high-risk patients."}]', '**Fluid Overload Risk:** Use with extreme caution in conditions where increased intravascular volume could be hazardous, such as congestive heart failure, hypertension, esophageal varices, pulmonary edema, hemorrhagic diathesis, and renal/post-renal anuria.
INSERT INTO "drug_generic" VALUES(721, 'Pyrimethamine + Sulfadoxine', 'Sulfadoxine and Pyrimethamine', 'P01BD51', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fatal Cutaneous Reactions", "severity": "High", "trigger_condition": "Hypersensitivity to sulfonamides", "message": "STOP: Fatalities associated with sulfonamides, although rare, have occurred due to severe reactions including Stevens-Johnson syndrome (SJS), toxic epidermal necrolysis (TEN), and fulminant hepatic necrosis. Discontinue immediately at the first sign of skin rash."}]', 'Use with extreme caution in patients with impaired renal or hepatic function, folate deficiency, severe allergy, bronchial asthma, or G6PD deficiency (risk of hemolysis). Maintain adequate fluid intake to prevent crystalluria and stone formation. Avoid excessive exposure to sunlight due to the risk of photosensitization. Regular monitoring of CBC, LFTs, and urinalysis is required if administered for prolonged periods.', '- **Malaria Treatment:** Treatment of acute, uncomplicated *Plasmodium falciparum* malaria, particularly in areas with known chloroquine resistance. (Note: Often used in combination with artesunate as part of Artemisinin-based Combination Therapy [ACT]).
INSERT INTO "drug_generic" VALUES(722, 'Bismuth subsalicylate', 'Bismuth Subsalicylate', 'A07BB', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Reye''s Syndrome Risk", "severity": "High", "trigger_condition": "Use in children or teenagers with viral infections", "message": "STOP: Do not administer to children or teenagers recovering from viral infections (e.g., influenza, chickenpox) due to the risk of Reye''s syndrome, a rare but potentially fatal condition associated with salicylates."}]', '**Stool and Tongue Discoloration:** Bismuth reacts with sulfur in the GI tract to form bismuth sulfide, which causes temporary and harmless darkening (gray-black) of the tongue and stool. This should not be confused with melena (GI bleeding).
INSERT INTO "drug_generic" VALUES(723, 'Beclomethasone Dipropionate + Formoterol Fumarate', 'Beclomethasone Dipropionate + Formoterol Fumarate', 'R03AK08', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediately following inhalation", "message": "Paradoxical bronchospasm may occur with an immediate increase in wheezing and shortness of breath after dosing. Treat immediately with a fast-acting inhaled bronchodilator, discontinue this inhaler, and assess for alternative therapy."}]', '- **Cardiovascular Disorders:** Use with caution in patients with cardiac arrhythmias (especially 3rd-degree AV block), prolonged QTc interval, hypertrophic obstructive cardiomyopathy, severe ischemic heart disease, or severe hypertension. Formoterol can induce cardiovascular effects.
INSERT INTO "drug_generic" VALUES(724, 'Pitolisant', 'Pitolisant', 'N07XX11', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Patients with a history of cardiac arrhythmias, concurrent use of QT-prolonging drugs, or severe hepatic/renal impairment", "message": "STOP: Pitolisant prolongs the QT interval. Avoid use in patients with a history of prolonged QT, symptomatic bradycardia, or hypokalemia/hypomagnesemia."}]', '**QT Prolongation:** Pitolisant prolongs the QT interval. Avoid use in patients with a history of cardiac arrhythmias, congenital QT prolongation, or circumstances that increase the risk of torsades de pointes or sudden death (e.g., symptomatic bradycardia, hypokalemia, hypomagnesemia). Patients with hepatic or renal impairment are at a greater risk of QT prolongation due to higher systemic pitolisant concentrations; monitor these patients closely.
INSERT INTO "drug_generic" VALUES(725, 'Roxatidine', 'Roxatidine', 'A02BA06', 0, 0, 0, 0, 1, 0, 0, 0, '[]', 'Use with caution in patients with renal and hepatic impairment; dosage adjustments may be necessary. Treatment with H2-receptor antagonists like roxatidine may mask the symptoms of gastric malignancy; exclude malignancy before initiating therapy. Caution is advised during pregnancy.', '- **Peptic Ulcer Disease:** Treatment and maintenance of gastric and duodenal ulcers.
INSERT INTO "drug_generic" VALUES(726, 'Ciclopirox Topical', 'Ciclopirox', 'D01AE14', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'For external use only. Avoid contact with the eyes and mucous membranes.
INSERT INTO "drug_generic" VALUES(727, 'Vitamin A palmitate Carbomer 980 Eye prep', 'Vitamin A / Carbomer Ophthalmic Gel', 'S01XA', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Do not use this product during ocular surgery. Remove contact lenses prior to application and wait at least 15 to 30 minutes before reinserting them, as the gel may damage the lenses or trap preservatives against the cornea. Discontinue use if eye pain, vision changes, or persistent redness occurs.', '- **Severe Dry Eye Syndrome:** For the relief of severe dry eyes and ocular irritation.
INSERT INTO "drug_generic" VALUES(728, 'Almitrine Bismesylate + Raubasine', 'Almitrine and Raubasine', 'C04AX', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Peripheral Neuropathy", "severity": "High", "trigger_condition": "Long-term treatment", "message": "STOP: Long-term treatment may result in peripheral neuropathy (numbness, prickling, or formication in the lower limbs). Discontinue treatment immediately if these symptoms occur."}]', '**Peripheral Neuropathy:** Chronic administration is associated with sensory peripheral neuropathy, particularly in the lower limbs. Monitor patients for tingling, numbness, or weight loss, and withdraw treatment if these occur.
INSERT INTO "drug_generic" VALUES(729, 'Crotamiton topical', 'Crotamiton Topical', 'D04AX', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Application Site:** For external use only. Avoid contact with the eyes, mouth, mucous membranes, and urethral meatus. If contact occurs, flush thoroughly with water.
INSERT INTO "drug_generic" VALUES(730, 'Levomilnacipran', 'Levomilnacipran', 'N06AX28', 0, 1, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Suicidality and Antidepressant Drugs", "severity": "High", "trigger_condition": "Initiation of therapy or dosage adjustments, particularly in patients <24 years of age", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, unusual changes in behavior, or suicidal tendencies."}]', '**Suicidality:** Increased risk of suicidal thinking and behavior in patients <24 years old. Monitor closely for clinical worsening and suicidal tendencies during the initial 1-2 months of therapy and after dosage adjustments.
INSERT INTO "drug_generic" VALUES(731, 'Neratinib', 'Neratinib', 'L01EH02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Diarrhea", "severity": "High", "trigger_condition": "Initiation of therapy without antidiarrheal prophylaxis", "message": "STOP: Severe, potentially fatal diarrhea can occur. Antidiarrheal prophylaxis (e.g., loperamide) must be initiated with the first dose of Neratinib and continued for the first 56 days of treatment."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Development of Grade 3 or 4 liver abnormalities", "message": "STOP: Severe hepatotoxicity can occur. Monitor liver function tests regularly. Withhold or permanently discontinue therapy based on the severity of hepatic impairment."}]', '**Diarrhea Management:** Severe diarrhea is the most common dose-limiting toxicity. It must be managed proactively through either a structured dose escalation of neratinib or mandatory loperamide prophylaxis initiated with the first dose. If diarrhea occurs despite prophylaxis, treat aggressively with additional antidiarrheals, intravenous fluids, and electrolyte replacement. Withhold therapy for severe or persistent diarrhea, and permanently discontinue if Grade 4 diarrhea or Grade ≥2 diarrhea occurs after maximal dose reduction.
INSERT INTO "drug_generic" VALUES(732, 'Enalapril + Hydrochlorothiazide', 'Enalapril + Hydrochlorothiazide', 'C09BA02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: When pregnancy is detected, discontinue this medication as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}]', 'Begin combination therapy only after failed monotherapy.
INSERT INTO "drug_generic" VALUES(733, 'Lactulose', 'Lactulose', 'A06AD11', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Use with caution in patients with diabetes mellitus, as lactulose solutions contain small amounts of free galactose and lactose. Caution is also advised in patients with lactose intolerance. In elderly or debilitated patients receiving lactulose for more than 6 months, serum electrolytes (potassium, chloride, carbon dioxide) should be measured periodically due to the risk of hypokalemia and dehydration.', '- **Constipation:** Treatment of chronic constipation. Initial treatment should always include dietary modifications (fiber, fluids) and exercise.
INSERT INTO "drug_generic" VALUES(734, 'Mupirocin + Beclomethasone Dipropionate Topical', 'Mupirocin and Beclomethasone Dipropionate', 'D07CA', 1, 0, 0, 0, 1, 1, 1, 1, '[{"alert_type": "Systemic Absorption Risk", "severity": "Moderate", "trigger_condition": "Application to extensive burns, open wounds, or prolonged use", "message": "Avoid application to large areas of broken skin or extensive burns due to the risk of systemic absorption of polyethylene glycol (PEG) base, which can cause renal toxicity, and systemic corticosteroid absorption."}]', 'Use with extreme caution in patients with moderate to severe renal impairment, as the polyethylene glycol (PEG) base in the ointment can be absorbed from open wounds and damaged skin, leading to accumulation and potential nephrotoxicity.
INSERT INTO "drug_generic" VALUES(735, 'Givosiran', 'Givosiran', 'A16AX16', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "During subcutaneous administration", "message": "STOP: Anaphylaxis has been observed. Ensure medical support is available to appropriately manage anaphylactic reactions when administering."}]', '**Anaphylaxis:** Anaphylaxis has been observed during treatment. Ensure that appropriate medical support is available to manage anaphylactic reactions when administering givosiran. Monitor patients closely for signs and symptoms of hypersensitivity.
INSERT INTO "drug_generic" VALUES(736, 'Tecovirimat', 'Tecovirimat', 'J05AX21', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Hypoglycemia Risk", "severity": "Moderate", "trigger_condition": "Coadministration with repaglinide", "message": "Coadministration with repaglinide may cause mild-to-moderate hypoglycemia. Monitor blood glucose closely and watch for hypoglycemic symptoms."}]', '**Hypoglycemia with Repaglinide:** Coadministration of tecovirimat with repaglinide (an antidiabetic agent) may cause mild-to-moderate hypoglycemia. Monitor blood glucose levels closely and educate the patient on the signs and symptoms of hypoglycemia when administering these drugs concurrently.
INSERT INTO "drug_generic" VALUES(737, 'Sodium Carboxymethyl-cellulose eye prep', 'Carboxymethylcellulose Sodium Ophthalmic', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Ocular Evaluation:** Discontinue use and consult a physician if eye pain, changes in vision, continued redness, or irritation of the eye occurs, or if the condition worsens or persists for more than 72 hours.
INSERT INTO "drug_generic" VALUES(738, 'Sodium Valproate (valproic acid)', 'Valproic Acid / Divalproex Sodium', 'N03AG01', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "First 6 months of therapy, especially in children <2 years on multiple anticonvulsants", "message": "STOP: Hepatic failure resulting in fatalities has occurred. Monitor LFTs closely. Risk is highest in children under 2 years and those with mitochondrial disorders."}, {"alert_type": "Fetal Risk (Teratogenicity)", "severity": "High", "trigger_condition": "Use in women of childbearing potential", "message": "STOP: Can cause major congenital malformations (neural tube defects) and decreased IQ. Contraindicated for migraine prophylaxis in pregnancy. Use for epilepsy/bipolar only if alternatives fail."}, {"alert_type": "Pancreatitis", "severity": "High", "trigger_condition": "Development of abdominal pain, nausea, vomiting, or anorexia", "message": "STOP: Life-threatening acute pancreatitis has been reported in both children and adults. Discontinue immediately if pancreatitis is diagnosed."}]', '- **Hepatotoxicity:** Increased risk of fatal hepatotoxicity, particularly in children <2 years, patients with congenital metabolic disorders (e.g., mitochondrial disorders, POLG mutations), organic brain disease, or severe seizure disorders. Monitor LFTs before and during the first 6 months of therapy.
INSERT INTO "drug_generic" VALUES(739, 'Anti-Rho(D) Immunoglobulin', 'Rho(D) Immune Globulin', 'J06BB01', 0, 1, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Intravascular Hemolysis", "severity": "High", "trigger_condition": "Administration to Rh-positive individuals or for ITP in patients with compromised hemoglobin", "message": "STOP: Severe and potentially fatal intravascular hemolysis can occur. Do not administer to Rh-positive individuals for postpartum prophylaxis. Monitor ITP patients closely for signs of hemolysis."}]', '- **Administration Route:** Ensure correct route of administration. Most formulations are for intramuscular (IM) use only; do not inject intravenously unless specifically using an IV-approved formulation (e.g., for Idiopathic Thrombocytopenic Purpura).
INSERT INTO "drug_generic" VALUES(740, 'Drotaverine Hydrochloride', 'Drotaverine', 'A03AD02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular Collapse", "severity": "High", "trigger_condition": "Rapid intravenous administration", "message": "STOP: Rapid intravenous injection may cause severe hypotension, atrioventricular block, or fatal cardiac arrest. Administer IV doses slowly."}]', '**Cardiovascular Disease:** Exercise extreme caution in patients with pre-existing cardiac dysfunction, as the drug possesses mild beta-blocking and vasodilatory properties that may exacerbate hypotension or conduction delays.
INSERT INTO "drug_generic" VALUES(741, 'Cinnarizine', 'Cinnarizine', 'N07CA02', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Extrapyramidal Symptoms", "severity": "Moderate", "trigger_condition": "Prolonged use, especially in elderly patients", "message": "Cinnarizine can cause or aggravate extrapyramidal symptoms (e.g., parkinsonism, tremor, rigidity) and depression, particularly in the elderly during long-term therapy. Discontinue if these occur."}]', '**Parkinson''s Disease:** Use with extreme caution or avoid in patients with Parkinson''s disease, as it may aggravate symptoms.
INSERT INTO "drug_generic" VALUES(742, 'Nikethamide', 'Nikethamide', 'R07AB02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Seizure Risk", "severity": "High", "trigger_condition": "Overdose or rapid administration", "message": "STOP: Nikethamide has a narrow therapeutic index. High doses or rapid administration can precipitate severe central nervous system toxicity, including generalized convulsions."}]', 'Use with extreme caution due to the narrow margin of safety between the analeptic (stimulant) dose and the convulsant dose. Monitor patients continuously for signs of central nervous system hyperstimulation, including muscle twitching or tremors, which may precede generalized seizures. Caution is advised in patients with a history of epilepsy or seizure disorders.', '- **Acute Respiratory Failure:** Used historically as a respiratory stimulant in acute respiratory depression.
INSERT INTO "drug_generic" VALUES(743, 'Sodium sulfacetamide + Sulfur topical', 'Sulfacetamide Sodium and Sulfur', 'D10AF52', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Severe Cutaneous Adverse Reactions", "severity": "High", "trigger_condition": "Patient history of sulfonamide hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including Stevens-Johnson syndrome (SJS) and toxic epidermal necrolysis (TEN), have been reported with sulfonamides. Verify patient allergy history."}]', '**External Use Only:** Avoid contact with eyes, lips, and mucous membranes.
INSERT INTO "drug_generic" VALUES(744, 'Betamethasone oral', 'Betamethasone', 'H02AB01', 0, 1, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Adrenal Suppression and Withdrawal", "severity": "High", "trigger_condition": "Abrupt discontinuation after prolonged use", "message": "STOP: Abrupt withdrawal of systemic corticosteroids can cause acute adrenal insufficiency (Addisonian crisis), manifesting as severe weakness, hypotension, hypoglycemia, and death. Taper the dose gradually."}, {"alert_type": "Immunosuppression", "severity": "High", "trigger_condition": "Exposure to infections", "message": "STOP: Corticosteroids suppress the immune system. Patients are highly susceptible to severe infections. Chickenpox and measles can be fatal in non-immune patients on systemic steroids."}]', '**Endocrine/Metabolic:** Can cause Cushing''s syndrome, hyperglycemia, and unmask latent diabetes. Monitor blood glucose.
INSERT INTO "drug_generic" VALUES(745, 'Clobetasol Propionate 0.05% topical', 'Clobetasol Propionate Topical', 'D07AD01', 0, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "High Potency Corticosteroid Toxicity", "severity": "High", "trigger_condition": "Use exceeding 50 grams per week or duration > 2 consecutive weeks", "message": "Clobetasol is a super-high potency topical corticosteroid. Do not exceed 50 g/week or use for more than 2 consecutive weeks due to the high risk of hypothalamic-pituitary-adrenal (HPA) axis suppression and systemic toxicity."}]', '**HPA Axis Suppression:** Can produce reversible HPA axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria. Risk increases with prolonged use, application to large surface areas, use of occlusive dressings, and in pediatric patients.
INSERT INTO "drug_generic" VALUES(746, 'Dexibuprofen', 'Dexibuprofen', 'M01AE14', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use in patients with cardiovascular disease or history of GI bleeding", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events (MI, stroke) and serious gastrointestinal adverse events (bleeding, ulceration, perforation), which can be fatal. Contraindicated in the setting of CABG surgery."}]', '**Gastrointestinal Risk:** GI bleeding, ulceration, and perforation can occur at any time during treatment, with or without warning symptoms. Risk is higher with increasing doses, history of ulcers, alcoholism, and in the elderly.
INSERT INTO "drug_generic" VALUES(747, 'Telbivudine', 'Telbivudine', 'J05AF08', 0, 0, 1, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Exacerbation of Hepatitis B", "severity": "High", "trigger_condition": "Discontinuation of anti-hepatitis B therapy", "message": "Severe acute exacerbations of hepatitis B have been reported in patients who have discontinued anti-hepatitis B therapy. Hepatic function must be monitored closely for at least several months after stopping treatment."}, {"alert_type": "Lactic Acidosis and Hepatomegaly", "severity": "High", "trigger_condition": "Development of unexplained metabolic acidosis or hepatotoxicity", "message": "Lactic acidosis and severe hepatomegaly with steatosis, including fatal cases, have been reported with the use of nucleoside analogues."}]', 'Monitor hepatic function (ALT, AST) periodically during therapy and for several months following discontinuation to detect viral rebound or hepatitis exacerbation. Monitor for signs of myopathy or myositis; check serum creatine kinase (CK) levels if patients present with unexplained muscle pain, tenderness, or weakness. Monitor for symptoms of peripheral neuropathy. Assess renal function prior to initiation and periodically during therapy, adjusting the dose in patients with creatinine clearance <50 mL/min. Telbivudine is not recommended for patients with established lamivudine-resistant HBV due to cross-resistance.', '- **Chronic Hepatitis B:** Treatment of chronic hepatitis B in adult patients with evidence of viral replication and either persistent elevations in serum aminotransferases (ALT or AST) or histologically active disease. 
INSERT INTO "drug_generic" VALUES(748, 'Grass pollens allergen extract', 'Grass pollen allergen extract', 'V01AA02', 0, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Administration of allergen immunotherapy", "message": "STOP: Severe, life-threatening systemic allergic reactions, including anaphylaxis, can occur. The first dose must be administered in a healthcare setting under medical supervision. Patients must be prescribed auto-injectable epinephrine."}]', '**Systemic Allergic Reactions:** Can cause life-threatening systemic allergic reactions, including anaphylaxis. Observe patients in the office for at least 30 minutes after the initial dose. Prescribe auto-injectable epinephrine.
INSERT INTO "drug_generic" VALUES(749, 'Paracetamol', 'Acetaminophen', 'N02BE01', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity Risk", "severity": "High", "trigger_condition": "Exceeding maximum daily dose (4g/day in adults) or use in severe hepatic impairment", "message": "STOP: Severe, potentially fatal hepatotoxicity can occur if the maximum daily dose is exceeded. Verify all sources of paracetamol (including combination products) to prevent accidental overdose."}]', '**Hepatotoxicity:** Paracetamol can cause severe liver damage, including acute liver failure resulting in liver transplant or death. The risk increases with doses exceeding the maximum daily limit, concurrent use of other paracetamol-containing products, chronic alcohol consumption, and underlying hepatic disease.
INSERT INTO "drug_generic" VALUES(750, 'Light liquid paraffin', 'Mineral Oil', 'A06AA01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Aspiration Risk", "severity": "High", "trigger_condition": "Oral administration in high-risk patients", "message": "STOP: Do not give orally to patients with swallowing difficulties, bedridden individuals, young infants, or immediately before lying down. Aspiration into the lungs can cause severe and potentially fatal lipoid pneumonia."}]', '**Duration Limits (Oral):** Oral use should not exceed 7 consecutive days without medical advice. Prolonged use can lead to laxative dependence, impaired bowel tone, and chronic malabsorption of fat-soluble vitamins.
INSERT INTO "drug_generic" VALUES(751, 'Human Papilloma virus Bivalent (Types 16 and 18) Vaccine, Recombinant', 'Human Papillomavirus Bivalent (Types 16 and 18) Vaccine, Recombinant', 'J07BM02', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Syncope Risk", "severity": "Medium", "trigger_condition": "Administration of vaccine, particularly in adolescents", "message": "STOP: Syncope (fainting), sometimes associated with tonic-clonic movements, can occur. Observe patients for 15-30 minutes post-vaccination in a seated or supine position."}]', '**Syncope:** Fainting may occur, leading to falls and injuries. Ensure the patient is seated or lying down during administration and observe for at least 15-30 minutes afterward.
INSERT INTO "drug_generic" VALUES(752, 'Liraglutide', 'Liraglutide', 'A10BJ02', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Risk of Thyroid C-Cell Tumors", "severity": "High", "trigger_condition": "Personal or family history of Medullary Thyroid Carcinoma (MTC) or Multiple Endocrine Neoplasia syndrome type 2 (MEN 2)", "message": "STOP: Liraglutide causes dose-dependent and treatment-duration-dependent thyroid C-cell tumors in animals. It is contraindicated in patients with a personal or family history of MTC or MEN 2. Counsel patients regarding the risk and symptoms of thyroid tumors (e.g., neck mass, dysphagia, dyspnea, persistent hoarseness)."}]', '**Pancreatitis:** Acute pancreatitis, including fatal and non-fatal hemorrhagic or necrotizing pancreatitis, has been observed. Discontinue promptly if pancreatitis is suspected; do not restart if confirmed.
INSERT INTO "drug_generic" VALUES(753, 'Safinamide', 'Safinamide', 'N04BD03', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Serotonin Syndrome and Hypertensive Crisis", "severity": "High", "trigger_condition": "Concomitant use with MAOIs, opioids, SNRIs, or dextromethorphan", "message": "STOP: Coadministration with other MAOIs, certain opioids, SNRIs, or dextromethorphan is contraindicated due to the risk of life-threatening serotonin syndrome and hypertensive crisis."}]', '**Hypertension:** May cause or exacerbate hypertension. Monitor patients for new-onset hypertension or hypertension not adequately controlled after initiating therapy. Medication adjustment may be necessary if blood pressure elevation is sustained.
INSERT INTO "drug_generic" VALUES(754, 'Pholcodine', 'Pholcodine', 'R05DA08', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Anaphylaxis Risk with NMBAs", "severity": "High", "trigger_condition": "Recent use of pholcodine prior to general anesthesia", "message": "STOP: Pholcodine use is linked to a significant risk of severe, life-threatening anaphylactic reactions to Neuromuscular Blocking Agents (NMBAs) during general anesthesia. Verify patient history before surgery."}]', '**Anaphylaxis Risk with NMBAs:** Recent regulatory reviews (e.g., EMA) have identified a link between prior pholcodine use and an increased risk of anaphylaxis to neuromuscular blocking agents (NMBAs) used during general anesthesia. Use is restricted or withdrawn in many jurisdictions.
INSERT INTO "drug_generic" VALUES(755, 'Clomiphene Citrate', 'Clomiphene', 'G03GB02', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Ovarian Hyperstimulation Syndrome (OHSS)", "severity": "High", "trigger_condition": "During or immediately following ovulation induction therapy", "message": "OHSS is a rare but potentially life-threatening exaggerated response to ovulation induction. Symptoms include severe pelvic pain, abdominal distention, nausea, vomiting, and weight gain. Withhold therapy if ovaries are abnormally enlarged."}, {"alert_type": "Multiple Pregnancies", "severity": "Moderate", "trigger_condition": "Successful ovulation induction", "message": "There is an increased risk of multiple births (e.g., twins, triplets) associated with clomiphene therapy. Advise patients of this risk prior to initiating treatment."}]', '**Visual Symptoms:** Visual disturbances (blurring, spots, flashes, scotoma) may occur and can render driving or operating machinery hazardous. Discontinue treatment and perform a complete ophthalmological evaluation if visual symptoms occur.
INSERT INTO "drug_generic" VALUES(756, 'Paracetamol + Ibuprofen', 'Acetaminophen and Ibuprofen', 'M01AE51', 0, 0, 0, 1, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "History of cardiovascular disease or prolonged use", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke, which can be fatal."}, {"alert_type": "Gastrointestinal Risk", "severity": "High", "trigger_condition": "History of peptic ulcer disease or GI bleeding", "message": "STOP: NSAIDs cause an increased risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation of the stomach or intestines, which can be fatal."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Exceeding maximum daily dose of paracetamol", "message": "STOP: Paracetamol has been associated with cases of acute liver failure, at times resulting in liver transplant and death. Do not exceed the maximum daily dose."}]', 'Use with caution in patients with a history of bronchial asthma, allergic disease, hypertension, mild to moderate congestive heart failure, mixed connective tissue disorder, or systemic lupus erythematosus (SLE).
INSERT INTO "drug_generic" VALUES(757, 'Dexamethasone Sodium Phosphate Injections', 'Dexamethasone', 'H02AB02', 0, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Immunosuppression and Infection Risk", "severity": "High", "trigger_condition": "Systemic fungal infections or administration of live vaccines", "message": "STOP: Corticosteroids cause profound immunosuppression. Contraindicated in systemic fungal infections. Administration of live or live-attenuated vaccines is strictly contraindicated in patients receiving immunosuppressive doses."}]', '**HPA Axis Suppression:** Chronic use can cause hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, and hyperglycemia. Abrupt withdrawal may lead to acute adrenal insufficiency; tapering is required.
INSERT INTO "drug_generic" VALUES(758, 'Chlorhexidine Gluconate 1 % vag prep', 'Chlorhexidine Gluconate', 'G01AX', 1, 0, 1, 1, 0, 0, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of chlorhexidine hypersensitivity", "message": "STOP: Severe allergic reactions, including fatal anaphylaxis, have been reported with the use of chlorhexidine products. Verify allergy history before application."}]', '- **Tissue Toxicity:** Avoid contact with the brain, meninges, middle ear, or sensitive tissues and eyes. If accidental contact occurs, rinse thoroughly with water immediately.
INSERT INTO "drug_generic" VALUES(759, 'Telmisartan + Amlodipine', 'Telmisartan and Amlodipine', 'C09DB04', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected during therapy", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue telmisartan/amlodipine as soon as possible when pregnancy is detected."}]', '**Hepatic Impairment:** Telmisartan is primarily excreted in the bile. Patients with biliary obstructive disorders or hepatic insufficiency have significantly reduced clearance. Titrate slowly and use with caution.
INSERT INTO "drug_generic" VALUES(760, 'Methylprednisolone Acetate', 'Methylprednisolone Acetate', 'H02AB04', 0, 0, 0, 1, 0, 0, 1, 1, '[{"alert_type": "Route of Administration Error", "severity": "High", "trigger_condition": "Intravenous or Intrathecal administration", "message": "STOP: Methylprednisolone acetate is a suspension. It is strictly CONTRAINDICATED for intravenous (IV) or intrathecal administration. Severe, fatal events (arachnoiditis, stroke) have occurred."}]', '**Route Restrictions:** This formulation is a suspension and must NOT be administered intravenously or intrathecally. Intrathecal administration has been associated with severe medical events, including arachnoiditis, bowel/bladder dysfunction, headache, seizures, and death.
INSERT INTO "drug_generic" VALUES(761, 'Cefpodoxime', 'Cefpodoxime', 'J01DD13', 1, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(762, 'Diroximel Fumarate', 'Diroximel Fumarate', 'L04AX07', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Progressive Multifocal Leukoencephalopathy (PML)", "severity": "High", "trigger_condition": "New or worsening neurological symptoms", "message": "STOP: PML, an opportunistic viral infection of the brain caused by the JC virus that often leads to death or severe disability, has occurred. Withhold treatment immediately at the first sign or symptom suggestive of PML."}]', '**Progressive Multifocal Leukoencephalopathy (PML):** PML has occurred in patients treated with fumarates. Monitor for new or worsening neurological, cognitive, or psychiatric signs/symptoms. Withhold diroximel fumarate immediately if PML is suspected and perform appropriate diagnostic evaluations (e.g., MRI, CSF analysis for JC virus).
INSERT INTO "drug_generic" VALUES(763, 'Clotrimazole + Hydrocortisone Topical', 'Clotrimazole and Hydrocortisone Topical', 'D01AC20', 1, 0, 0, 0, 0, 1, 1, 0, '[]', '**HPA Axis Suppression:** Manifestations of hypercortisolism (Cushing''s syndrome) and reversible hypothalamic-pituitary-adrenal (HPA) axis suppression can occur, particularly with prolonged use, extensive application, or use under occlusion (including diapers in infants).
INSERT INTO "drug_generic" VALUES(764, 'Estradiol', 'Estradiol', 'G03CA03', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiovascular and Malignancy Risks", "severity": "High", "trigger_condition": "Use of systemic estrogens", "message": "STOP: Estrogens increase the risk of endometrial cancer, myocardial infarction, stroke, invasive breast cancer, pulmonary emboli, and deep vein thrombosis. Prescribe at the lowest effective dose for the shortest duration."}]', '**Endometrial Cancer:** Unopposed estrogen therapy in women with an intact uterus increases the risk of endometrial cancer. Addition of a progestin reduces this risk.
INSERT INTO "drug_generic" VALUES(765, 'Levosimendan', 'Levosimendan', 'C01CX08', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hypotension and Arrhythmia Risk", "severity": "High", "trigger_condition": "Administration in patients with low baseline blood pressure, severe hypovolemia, or hypokalemia", "message": "STOP: Severe hypotension and life-threatening arrhythmias (including ventricular tachycardia and atrial fibrillation) can occur. Correct severe hypovolemia and hypokalemia prior to administration. Monitor ECG and blood pressure continuously."}]', 'Use with extreme caution in patients with low baseline systolic or diastolic blood pressure, concurrent ischemic cardiovascular disease, anemia, tachycardia, atrial fibrillation with rapid ventricular response, or a prolonged QTc interval. Monitor ECG, blood pressure, and heart rate continuously during treatment and for at least 3 days (5 days in patients with mild to moderate renal/hepatic impairment) after the end of the infusion. Assess hemodynamic response immediately after the loading dose and within 30-60 minutes of any dosage adjustment.', '- **Acutely Decompensated Heart Failure (AHF):** Indicated for the short-term treatment of acutely decompensated severe congestive heart failure in situations where conventional therapy is not sufficient, and in cases where inotropic support is considered appropriate.', '- **Severe Hypotension and Tachycardia:** Contraindicated due to the vasodilatory and chronotropic effects of the drug.
INSERT INTO "drug_generic" VALUES(766, 'Ethyl Butylacetylaminopropionate topical', 'Ethyl Butylacetylaminopropionate', 'P03BX04', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Application Site Reactions:** Avoid contact with the eyes, lips, mouth, cuts, wounds, and irritated or sunburned skin. This product is strictly for external usage.
INSERT INTO "drug_generic" VALUES(767, 'Phenylephrine Hydrochloride 5% + Tropicamide 0.8% Eye prep', 'Phenylephrine / Tropicamide Ophthalmic', 'S01FA56', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Glaucoma Risk", "severity": "High", "trigger_condition": "Patient with narrow-angle glaucoma", "message": "STOP: This combination causes profound mydriasis and cycloplegia, which can precipitate an acute angle-closure glaucoma crisis. Contraindicated in narrow-angle glaucoma."}]', '**Systemic Absorption:** Significant systemic absorption can occur, leading to severe cardiovascular effects (hypertension, arrhythmias) and anticholinergic effects. Use with extreme caution in patients with severe arteriosclerotic cardiovascular disease, cerebrovascular disease, or hypertension.
INSERT INTO "drug_generic" VALUES(768, 'Vitamin B1 + Vitamin B2 + Vitamin B6 + Nicotinamide', 'Thiamine, Riboflavin, Pyridoxine, and Niacinamide', 'A11EA', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Use with caution in patients with a history of severe allergic reactions to any B-complex vitamins.
INSERT INTO "drug_generic" VALUES(769, 'Solifenacin Succinate', 'Solifenacin', 'G04BD08', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Anticholinergic Effects and Urinary Retention", "severity": "High", "trigger_condition": "Patients with bladder outflow obstruction or severe gastrointestinal obstructive disorders", "message": "STOP: Solifenacin can induce severe urinary retention and exacerbate gastrointestinal obstructive disorders. Evaluate patient for bladder outflow obstruction and gastric retention prior to initiation."}]', 'Exercise extreme caution in patients with clinically significant bladder outflow obstruction due to the increased risk of urinary retention. Use with caution in patients with decreased gastrointestinal motility or obstructive gastrointestinal diseases, as anticholinergic effects may exacerbate these conditions. Monitor closely in patients with controlled narrow-angle glaucoma, hepatic impairment, or renal impairment. Caution is advised in patients with a known history of QT prolongation or those taking medications known to prolong the QT interval. Patients should be warned about the potential for drowsiness and blurred vision, which may impair the ability to perform hazardous tasks. Maintain adequate hydration, as the drug reduces the ability to sweat, increasing susceptibility to heat prostration in hot environments. Monitor serum creatinine clearance and liver function tests periodically.', '- **Overactive Bladder (OAB):** Indicated for the symptomatic treatment of overactive bladder syndrome, specifically to manage urge urinary incontinence, increased urinary frequency, and urgency.', '- **Urinary Retention:** Contraindicated because anticholinergic blockade of the detrusor muscle further impairs bladder emptying, exacerbating retention.
INSERT INTO "drug_generic" VALUES(770, 'Carboxypolymethylene  + Hydroxy Ethyl Cellulose', 'Carbomer / Hydroxyethyl Cellulose', 'V07AY', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Local Irritation:** Discontinue use if local irritation, redness, or discomfort occurs.
INSERT INTO "drug_generic" VALUES(771, 'Vedolizumab', 'Vedolizumab', 'L04AA33', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Progressive Multifocal Leukoencephalopathy (PML)", "severity": "High", "trigger_condition": "New onset or worsening of neurological signs or symptoms", "message": "STOP: Although the risk is lower than with other integrin antagonists, monitor for signs of PML (e.g., cognitive decline, visual changes, motor deficits). Withhold dosing and evaluate immediately if suspected."}, {"alert_type": "Severe Infections", "severity": "High", "trigger_condition": "Patient presents with fever, chills, or signs of systemic infection", "message": "STOP: Vedolizumab increases the risk of serious infections. Do not initiate in patients with active, severe infections. Discontinue if a severe infection develops."}]', '**Infections:** Patients treated with vedolizumab are at an increased risk for developing infections. Do not initiate treatment in patients with active, severe infections until the infections are controlled. Consider withholding treatment if a patient develops a severe infection while on therapy.
INSERT INTO "drug_generic" VALUES(772, 'Romosozumab', 'Romosozumab', 'M05BX06', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "History of myocardial infarction or stroke within the preceding year", "message": "STOP: Romosozumab may increase the risk of myocardial infarction, stroke, and cardiovascular death. Do not initiate in patients who have had an MI or stroke within the preceding year."}]', '**Cardiovascular Risk:** A higher rate of major adverse cardiovascular events (MACE), including CV death, nonfatal MI, and nonfatal stroke, has been observed. Avoid use in patients with a recent history of MI or stroke.
INSERT INTO "drug_generic" VALUES(773, 'Rota Virus Live attenuated Oral Vaccine', 'Rotavirus Vaccine, Live, Oral', 'J07BH01', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Intussusception Risk", "severity": "High", "trigger_condition": "Post-vaccination monitoring in infants", "message": "STOP: Increased risk of intussusception following administration. Monitor for severe abdominal pain, persistent vomiting, bloody stools, or high fever."}]', '**Intussusception:** A small increased risk of intussusception has been observed, primarily within 7 days of the first or second dose. Educate parents to seek immediate medical attention if symptoms occur.
INSERT INTO "drug_generic" VALUES(774, 'Carisoprodol', 'Carisoprodol', 'M03BA02', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Abuse, Dependence, and Withdrawal", "severity": "High", "trigger_condition": "Prolonged use or history of substance abuse", "message": "STOP: Carisoprodol is a Schedule IV controlled substance. It carries a significant risk of abuse, dependence, and withdrawal (including seizures). Limit use to acute periods (2-3 weeks) and taper gradually upon discontinuation."}]', '**Abuse and Dependence:** Carisoprodol is metabolized to meprobamate, a controlled substance with known abuse potential. Prolonged use can lead to physical dependence. Abrupt cessation may precipitate withdrawal symptoms, including insomnia, vomiting, tremors, muscle twitching, and potentially life-threatening seizures.
INSERT INTO "drug_generic" VALUES(775, 'Plasma Volume Substitute', 'Plasma Volume Expander (e.g., Gelatin / Dextran)', 'B05AA', 0, 1, 0, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylactoid Reactions", "severity": "High", "trigger_condition": "During intravenous infusion", "message": "STOP: Severe anaphylactoid reactions can occur. Monitor the patient closely during the first 20-30 mL of infusion. Discontinue immediately if signs of hypersensitivity develop."}]', 'Use with extreme caution in patients with cardiac insufficiency, fixed hypertension, or cardiogenic shock due to the risk of circulatory overload and pulmonary edema. Monitor hemodynamic status, urine output, and electrolyte levels continuously. In cases of long-term maintenance of plasma volume, ensure the hematocrit does not fall below 30 vol % (absolute minimum 25 vol %); supplement with erythrocyte concentrate or whole blood if necessary. Monitor coagulation parameters, as dilutional coagulopathy may occur with large volumes.', '- **Hypovolemic Shock:** Treatment of shock due to loss of blood or plasma (e.g., trauma, burns, surgery).
INSERT INTO "drug_generic" VALUES(776, 'Insulin (Human) R', 'Insulin Regular, Human', 'A10AB01', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypoglycemia", "severity": "High", "trigger_condition": "Missed meals, excessive exercise, or incorrect dosing", "message": "STOP: Severe, life-threatening hypoglycemia can occur. Ensure the patient understands proper injection technique, meal timing, and signs of hypoglycemia."}]', 'Monitor blood glucose frequently. Insulin requirements may change significantly during stress, illness, fever, trauma, infection, or surgery (requirements usually increase), or with diarrhea, nausea/vomiting, malabsorption, or hypothyroidism (requirements usually decrease). Hypokalemia may occur, especially during IV administration for DKA or hyperkalemia; monitor serum potassium closely and replace as needed. Use with caution in patients with renal or hepatic impairment, as insulin requirements may be reduced. Monitor for injection site reactions, lipoatrophy, or lipohypertrophy; rotate injection sites.', '- **Diabetes Mellitus:** Treatment of adult and pediatric patients with diabetes mellitus (Type 1 and Type 2) to improve glycemic control. Used as a short-acting prandial insulin.
INSERT INTO "drug_generic" VALUES(777, 'Eszopiclone', 'Eszopiclone', 'N05CF04', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Complex Sleep Behaviors", "severity": "High", "trigger_condition": "Patient reports engaging in activities while not fully awake", "message": "STOP: Complex sleep behaviors (e.g., sleep-driving, sleep-eating, making phone calls) have been reported. Discontinue immediately if a patient experiences a complex sleep behavior."}]', 'Evaluate patients for primary psychiatric or medical illnesses if insomnia fails to remit after 7-10 days of treatment. May cause abnormal thinking and behavioral changes (e.g., agitation, hallucinations, decreased inhibition). Worsening of depression and emergence of suicidality have been reported; prescribe the lowest effective quantity. Use with caution in patients with a history of drug or alcohol abuse due to the risk of dependence. May impair the ability to drive or operate machinery the morning after use; advise patients to ensure they can dedicate a full night (7-8 hours) to sleep before taking the dose. Hypersensitivity reactions, including anaphylaxis and angioedema, can occur. Abrupt discontinuation may cause withdrawal symptoms (e.g., anxiety, abnormal dreams, nausea). Use lower doses in the elderly and those with severe hepatic impairment.', '- **Insomnia:** Treatment of insomnia, including difficulty falling asleep, difficulty maintaining sleep, and early morning awakenings.', '- **Complex Sleep Behaviors:** Contraindicated in patients who have experienced complex sleep behaviors (e.g., sleep-driving, sleep-eating) after taking eszopiclone.
INSERT INTO "drug_generic" VALUES(778, 'Dextromethorphan + Guaifenesin', 'Dextromethorphan and Guaifenesin', 'R05FA02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Serotonin Syndrome Risk", "severity": "High", "trigger_condition": "Concurrent use or use within 14 days of Monoamine Oxidase Inhibitors (MAOIs)", "message": "STOP: Concomitant use with MAOIs can precipitate severe and potentially fatal serotonin syndrome. Verify patient medication history before prescribing."}]', '**Age Restrictions:** Do not use in children under 12 years of age unless explicitly directed by a physician. Over-the-counter (OTC) use is strictly not recommended in children under 4 years of age due to the risk of severe toxicity and lack of proven efficacy.
INSERT INTO "drug_generic" VALUES(779, 'Pemafibrate', 'Pemafibrate', 'C10AB12', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Concomitant use with statins or presence of muscle symptoms", "message": "STOP: Increased risk of severe myopathy and rhabdomyolysis, especially when co-administered with statins. Discontinue if CK is >5 times ULN or if myopathy is diagnosed."}]', 'Use with caution in patients receiving HMG-CoA reductase inhibitors (statins) due to an increased risk of rhabdomyolysis. Monitor for diffuse myalgia, muscle cramps, and weakness. Stop treatment if creatine kinase (CK) levels exceed 5 times the upper limit of normal.
INSERT INTO "drug_generic" VALUES(780, 'Zanubrutinib', 'Zanubrutinib', 'L01EL03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hemorrhage Risk", "severity": "High", "trigger_condition": "Concomitant use of antiplatelet or anticoagulant therapies", "message": "STOP: Fatal and serious hemorrhagic events have occurred. Monitor for bleeding and manage appropriately."}, {"alert_type": "Infection Risk", "severity": "High", "trigger_condition": "History of recurrent infections or active infection", "message": "STOP: Fatal and serious infections, including opportunistic infections and hepatitis B reactivation, have been reported. Monitor closely."}]', '**Cytopenias:** Grade 3 or 4 cytopenias, including neutropenia, thrombocytopenia, and anemia, have been reported. Monitor complete blood counts (CBC) regularly during treatment and manage with growth factors or transfusions as clinically indicated.
INSERT INTO "drug_generic" VALUES(781, 'Dienogest', 'Dienogest', 'G03DB08', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "History of or active venous/arterial thromboembolism", "message": "STOP: Dienogest is contraindicated in patients with active venous thromboembolic disorders or a history of arterial/cardiovascular disease (e.g., MI, CVA). Discontinue immediately if a thromboembolic event occurs."}]', '**Cardiovascular Risk:** Epidemiological studies associate progestin-only preparations with a slightly increased risk of venous thromboembolism (DVT, pulmonary embolism) and arterial thromboembolism (MI, stroke). Use with extreme caution in patients with risk factors.
INSERT INTO "drug_generic" VALUES(782, 'Rucaparib', 'Rucaparib', 'L01XK03', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hematologic Toxicity", "severity": "High", "trigger_condition": "Initiation of therapy or ongoing treatment", "message": "STOP: Myelodysplastic syndrome (MDS) and acute myeloid leukemia (AML) have been reported. Do not initiate until patients recover from prior chemotherapy hematological toxicities. Monitor CBC monthly."}]', '**Myelodysplastic Syndrome/Acute Myeloid Leukemia (MDS/AML):** Rare but potentially fatal reports of MDS/AML have occurred. Measure complete blood count (CBC) at baseline and monthly thereafter. Do not initiate treatment until patients have recovered from hematological toxicities caused by previous chemotherapy (i.e., ≤ Grade 1). If MDS/AML is confirmed, discontinue therapy immediately.
INSERT INTO "drug_generic" VALUES(783, 'Terbinafine', 'Terbinafine', 'D01BA02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Initiation of oral therapy", "message": "STOP: Cases of liver failure, some leading to death or liver transplant, have occurred with oral terbinafine. Obtain baseline liver function tests (AST, ALT) prior to prescribing. Discontinue immediately if signs of liver injury develop."}]', '**Hepatotoxicity:** Severe hepatotoxicity, including fatal liver failure, has occurred in patients with and without preexisting liver disease. Perform baseline LFTs. Instruct patients to report symptoms of liver dysfunction (e.g., persistent nausea, anorexia, fatigue, jaundice, dark urine).
INSERT INTO "drug_generic" VALUES(784, 'Hydrocolloid + moisture-retentive wound dressing', 'Hydrocolloid Dressing', 'Data not available', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'During the body''s normal autolytic debridement process, unnecessary necrotic material is removed from the wound, which may make the wound appear larger after the first few dressing changes; this is normal. However, if the wound continues to enlarge significantly, consult a healthcare professional. Avoid frequent dressing changes on wounds with damaged or delicate surrounding skin to prevent epidermal stripping. Inspect the wound carefully during each dressing change for signs of clinical infection.', '- **Dermal Ulcers:** Management of full-thickness wounds, pressure ulcers (Stages II-IV), diabetic foot ulcers, and venous leg ulcers.
INSERT INTO "drug_generic" VALUES(785, 'Iohexol', 'Iohexol', 'V08AB02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Intrathecal Administration Errors", "severity": "High", "trigger_condition": "Use of incorrect formulation for intrathecal injection", "message": "STOP: Ensure the specific formulation is approved for intrathecal use. Inadvertent intrathecal administration of formulations not approved for this route can cause severe neurotoxicity, seizures, coma, and death."}]', '- Maintain adequate hydration before and after administration to minimize the risk of contrast-induced nephropathy, especially in patients with diabetes, multiple myeloma, or preexisting renal impairment.
INSERT INTO "drug_generic" VALUES(786, 'Lomustine', 'Lomustine', 'L01AD02', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Delayed Myelosuppression", "severity": "High", "trigger_condition": "Administration of Lomustine", "message": "STOP: Lomustine causes delayed, severe, and potentially fatal bone marrow suppression (thrombocytopenia and leukopenia), usually occurring 4 to 6 weeks after administration. Do not give more frequently than every 6 weeks. Monitor CBC weekly for at least 6 weeks post-dose."}]', '**Delayed Bone Marrow Suppression:** Bone marrow toxicity is cumulative and delayed. Thrombocytopenia occurs at about 4 weeks post-dose and persists for 1 to 2 weeks. Leukopenia occurs at 5 to 6 weeks and persists for 1 to 2 weeks. Do not administer repeat courses until marrow function has recovered (platelets >100,000/mm3, leukocytes >4,000/mm3).
INSERT INTO "drug_generic" VALUES(787, 'Hypromellose + Carbomer', 'Hypromellose and Carbomer Homopolymer', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Ocular Irritation", "severity": "Low", "trigger_condition": "Persistent symptoms after application", "message": "If eye pain, changes in vision, or continued redness and irritation occur, discontinue use immediately and consult an ophthalmologist."}]', '**Visual Disturbances:** May cause transient blurring of vision immediately after instillation. Patients should be advised not to drive or operate hazardous machinery until vision has cleared.
INSERT INTO "drug_generic" VALUES(788, 'Testosterone Decanoate + Testosterone Isocaproate + Testosterone Phenyl propionate  + Testosterone Propionate', 'Testosterone mixed esters', 'G03BA03', 0, 1, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Cardiovascular and Polycythemia Risk", "severity": "High", "trigger_condition": "Long-term use or high doses", "message": "Testosterone therapy increases the risk of polycythemia, myocardial infarction, stroke, and venous thromboembolism. Monitor hematocrit and hemoglobin periodically. Discontinue if severe cardiovascular events occur."}]', 'Use with caution in patients with cardiovascular disorders, skeletal metastases, renal or hepatic impairment, epilepsy, migraine, or diabetes, as fluid retention may exacerbate these conditions. Monitor for signs of virilization in females and priapism or excessive sexual stimulation in males. Perform periodic hemoglobin, hematocrit, lipid profile, and liver function tests. Regular rectal prostate examinations and PSA monitoring are required in older males to rule out prostate cancer. Not recommended for prepubertal boys due to the risk of premature epiphyseal closure.', '- **Male Hypogonadism:** Indicated for testosterone replacement therapy in adult males for conditions associated with a deficiency or absence of endogenous testosterone (e.g., primary or secondary hypogonadism).', '- **Prostate or Breast Carcinoma:** Contraindicated in males with known or suspected carcinoma of the breast or prostate due to the risk of tumor stimulation.
INSERT INTO "drug_generic" VALUES(789, 'Paracetamol + Doxylamine + Dextromethorphan', 'Acetaminophen + Doxylamine + Dextromethorphan', 'N02BE51', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity Risk", "severity": "High", "trigger_condition": "Exceeding maximum daily dose of paracetamol (acetaminophen)", "message": "STOP: Contains paracetamol. Severe liver damage may occur if the patient takes more than 4,000 mg of paracetamol in 24 hours, takes it with other paracetamol-containing drugs, or consumes 3 or more alcoholic drinks daily."}]', '**Hepatotoxicity:** Paracetamol hepatotoxicity is possible in chronic alcoholics or if the maximum daily dose (4 g/day) is exceeded. Combined use with other OTC products containing paracetamol may result in toxicity due to cumulative doses.
INSERT INTO "drug_generic" VALUES(790, 'Oral rehydration salt [glucose based]', 'Oral Rehydration Salts', 'A07CA', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Preparation Warning", "severity": "High", "trigger_condition": "Reconstitution of the powder", "message": "STOP: Must be mixed with the exact amount of clean drinking water specified on the packet (usually 500 mL or 1 Liter). Do not mix with milk, juice, or hot water. Improper dilution can cause dangerous electrolyte imbalances (hypernatremia)."}]', '**Severe Dehydration:** Patients with severe continuing diarrhea, depressed renal function, or critical fluid losses may require intravenous fluid supplementation alongside or instead of oral rehydration.
INSERT INTO "drug_generic" VALUES(791, 'Allantoin topical', 'Allantoin topical', 'D03AX', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'For external use only. Avoid contact with eyes, the inside of the nose or mouth, and other mucous membranes. Do not apply to open wounds or unhealed tissues; wait until any stitches have been removed and the wound has fully closed before initiating therapy.', '- Treatment of hypertrophic and keloid scars.
INSERT INTO "drug_generic" VALUES(792, 'Ibuprofen', 'Ibuprofen', 'M01AE01', 0, 0, 0, 1, 1, 1, 1, 0, '[{"alert_type": "Cardiovascular Thrombotic Events", "severity": "High", "trigger_condition": "Long-term use, high doses, or pre-existing cardiovascular disease", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke, which can be fatal. Contraindicated in the setting of CABG surgery."}, {"alert_type": "Gastrointestinal Bleeding, Ulceration, and Perforation", "severity": "High", "trigger_condition": "History of peptic ulcer disease, concurrent use of anticoagulants/corticosteroids, or elderly patients", "message": "STOP: NSAIDs cause an increased risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation of the stomach or intestines, which can be fatal. Monitor closely."}]', 'Use with caution in patients with a history of asthma, as NSAIDs can precipitate bronchospasm (aspirin-exacerbated respiratory disease).
INSERT INTO "drug_generic" VALUES(793, 'Levodopa + Benserazide', 'Levodopa + Benserazide', 'N04BA02', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Neuroleptic Malignant-Like Syndrome", "severity": "High", "trigger_condition": "Abrupt withdrawal or rapid dose reduction", "message": "STOP: Abrupt withdrawal or rapid dose reduction can precipitate a potentially fatal neuroleptic malignant-like syndrome (hyperpyrexia, muscle rigidity, altered consciousness). Taper the dose gradually under strict medical supervision."}]', '**Sudden Sleep Episodes:** Levodopa has been associated with somnolence and sudden onset of sleep without warning signs. Patients must be cautioned against driving or operating hazardous machinery.
INSERT INTO "drug_generic" VALUES(794, 'Flucytosine', 'Flucytosine', 'J02AX01', 1, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Bone Marrow Suppression and DPD Deficiency", "severity": "High", "trigger_condition": "Use in patients with renal impairment, pre-existing bone marrow depression, or DPD deficiency", "message": "STOP: Extreme caution required. Flucytosine can cause severe bone marrow suppression (fatal aplastic anemia). Co-administration with antiviral nucleoside drugs (e.g., brivudine) or use in patients with DPD deficiency can result in fatal 5-fluorouracil toxicity."}]', '**Hematologic Toxicity:** High risk of bone marrow suppression (leukopenia, thrombocytopenia, anemia). Monitor hematologic function frequently, especially in patients with pre-existing bone marrow depression or those receiving radiation therapy.
INSERT INTO "drug_generic" VALUES(795, 'Amlodipine + Atorvastatin', 'Amlodipine and Atorvastatin', 'C10BX03', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Unexplained muscle pain, tenderness, or weakness", "message": "STOP: Atorvastatin can cause severe myopathy and rhabdomyolysis, leading to acute renal failure. Discontinue immediately if markedly elevated CPK levels occur or myopathy is diagnosed/suspected."}]', '**Hepatic Transaminitis:** Statins can cause elevations in liver enzymes. Monitor LFTs before initiating treatment and as clinically indicated thereafter. Discontinue if persistent elevations >3 times the upper limit of normal occur.
INSERT INTO "drug_generic" VALUES(796, 'Drospirenone + Estradiol', 'Drospirenone and Estradiol', 'G03FA17', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Thromboembolic Risk", "severity": "High", "trigger_condition": "History of DVT, PE, stroke, MI, or severe hypertension", "message": "STOP: Estrogen-containing products increase the risk of deep vein thrombosis (DVT), pulmonary embolism (PE), stroke, and myocardial infarction. Contraindicated in patients with a history of these conditions."}]', '**Cardiovascular Disorders:** Increased risk of stroke, deep vein thrombosis (DVT), and pulmonary embolism (PE). Discontinue immediately if a thrombotic event occurs or is suspected.
INSERT INTO "drug_generic" VALUES(797, 'Pralidoxime Chloride', 'Pralidoxime Chloride', 'V03AB04', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Administration Warning", "severity": "High", "trigger_condition": "Rapid Intravenous Administration", "message": "STOP: Rapid IV administration can cause tachycardia, laryngospasm, and muscle rigidity. Administer slowly over at least 15-30 minutes."}]', 'Pralidoxime is most effective if administered immediately after poisoning; its efficacy declines significantly if given more than 36-48 hours post-exposure due to the ''aging'' of the phosphorylated enzyme. It must be used in conjunction with atropine. Use with caution in patients with myasthenia gravis, as it may precipitate a myasthenic crisis. Reduce dose in patients with renal impairment. Avoid the use of morphine, theophylline, aminophylline, succinylcholine, reserpine, and phenothiazine-type tranquilizers in patients with organophosphate poisoning.', '- **Organophosphate Poisoning:** Used as an antidote in the treatment of poisoning due to organophosphate pesticides and chemicals (e.g., nerve agents) that have anticholinesterase activity.
INSERT INTO "drug_generic" VALUES(798, 'Loperamide + Simethicone', 'Loperamide/Simethicone', 'A07DA53', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cardiac Toxicity Risk", "severity": "High", "trigger_condition": "Taking higher than recommended doses", "message": "STOP: Taking more than the directed dose can cause serious cardiac adverse events, including QT interval prolongation, Torsades de Pointes, syncope, and cardiac arrest, which may be fatal."}]', '**Cardiac Toxicity:** Use of higher than recommended doses or abuse of loperamide can result in serious cardiac adverse events, including QT interval prolongation, Torsades de Pointes, ventricular arrhythmias, syncope, and cardiac arrest. Do not exceed the maximum daily dose.
INSERT INTO "drug_generic" VALUES(799, 'Hydralazine', 'Hydralazine', 'C02DB02', 0, 1, 1, 1, 1, 0, 1, 1, '[{"alert_type": "Lupus-Like Syndrome", "severity": "High", "trigger_condition": "Prolonged use or high doses (>100 mg/day)", "message": "STOP: Hydralazine can induce a systemic lupus erythematosus (SLE)-like syndrome. Monitor for arthralgia, fever, and chest pain. Discontinue if antinuclear antibody (ANA) titers become positive."}]', '**Systemic Lupus Erythematosus (SLE):** May induce an SLE-like syndrome, especially in slow acetylators and at doses >100 mg/day. Perform baseline and periodic CBC and ANA titer checks. Withdraw the drug if SLE symptoms occur.
INSERT INTO "drug_generic" VALUES(800, 'Fluconazole 0.3%  Eye prep', 'Fluconazole 0.3% Ophthalmic Solution', NULL, 0, 0, 0, 0, 0, 1, 1, 0, '[]', 'Prolonged use of ophthalmic fluconazole may result in the overgrowth of non-susceptible organisms, including non-albicans strains of Candida and certain bacteria. Careful monitoring is required, and if superinfection occurs, appropriate alternative therapy should be instituted. Patients should be advised not to wear contact lenses during treatment for ocular fungal infections.', '- **Fungal Keratitis:** Treatment of corneal inflammation caused by susceptible fungal organisms.
INSERT INTO "drug_generic" VALUES(801, 'Trimethoprim', 'Trimethoprim', 'J01EA01', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hematologic Toxicity", "severity": "High", "trigger_condition": "Patients with pre-existing folate deficiency or concurrent methotrexate use", "message": "STOP: Trimethoprim can cause severe bone marrow suppression and megaloblastic anemia. Avoid in patients with severe folate deficiency or those taking methotrexate."}]', '**Hematologic Monitoring:** Perform regular complete blood counts (CBC) during prolonged therapy. Discontinue if significant reduction in any formed blood element occurs.
INSERT INTO "drug_generic" VALUES(802, 'Diclofenac Sodium Topical', 'Diclofenac Topical', 'M02AA15', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Systemic NSAID Risks", "severity": "Moderate", "trigger_condition": "Extensive application or concomitant use with oral NSAIDs", "message": "STOP: Although applied topically, systemic absorption occurs. Risks of cardiovascular thrombotic events and serious GI bleeding apply, especially with prolonged use over large areas or when combined with oral NSAIDs."}]', '**Application Site:** Do not apply to non-intact, damaged, or infected skin. Avoid contact with eyes and mucous membranes.
INSERT INTO "drug_generic" VALUES(803, 'Obinutuzumab', 'Obinutuzumab', 'L01FA03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatitis B Reactivation and PML", "severity": "High", "trigger_condition": "Prior exposure to Hepatitis B virus or JC virus", "message": "STOP: Fatal Hepatitis B virus (HBV) reactivation and Progressive Multifocal Leukoencephalopathy (PML) can occur. Screen all patients for HBV prior to initiation. Monitor closely for neurological changes."}]', '- **Hepatitis B Virus (HBV) Reactivation:** Can cause fatal HBV reactivation. Screen all patients for HBsAg and anti-HBc before starting. Monitor carriers closely during and for several months after therapy.
INSERT INTO "drug_generic" VALUES(804, 'Binimetinib', 'Binimetinib', 'L01EE03', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Cardiomyopathy and Venous Thromboembolism", "severity": "High", "trigger_condition": "Initiation of therapy or pre-existing cardiovascular disease", "message": "Can cause severe left ventricular dysfunction and venous thromboembolism (DVT/PE). Assess LVEF before and during treatment. Monitor for signs of thrombosis."}]', '**Cardiomyopathy:** The safety of binimetinib has not been established in patients with a baseline LVEF below 50%. Assess LVEF before initiating treatment, after one month, and then every 2 to 3 months thereafter. Withhold, reduce dose, or permanently discontinue based on severity.
INSERT INTO "drug_generic" VALUES(805, 'Triamcinolone Acetonide Mouth prep', 'Triamcinolone Acetonide', 'A01AC01', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Immunosuppression and Infection Risk", "severity": "High", "trigger_condition": "Presence of untreated oral infections", "message": "STOP: Corticosteroids can mask or exacerbate untreated bacterial, viral (e.g., herpes simplex), or fungal infections of the mouth. Ensure appropriate antimicrobial therapy is initiated if infection is present."}]', 'Monitor for signs of systemic absorption, especially with prolonged use or application over large areas, which can lead to hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria.
INSERT INTO "drug_generic" VALUES(806, 'Besifloxacin 0.6%  Eye prep', 'Besifloxacin Ophthalmic', 'S01AE08', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Ophthalmic Use Only", "severity": "Low", "message": "For topical ophthalmic use only. Do not inject subconjunctivally or introduce directly into the anterior chamber of the eye."}]', '**Superinfection:** As with other anti-infectives, prolonged use may result in the overgrowth of non-susceptible organisms, including fungi. If superinfection occurs, discontinue use and institute alternative therapy.
INSERT INTO "drug_generic" VALUES(807, 'Latanoprost 0.005% Eye prep', 'Latanoprost Ophthalmic', 'S01EE01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cosmetic Changes", "severity": "Low", "trigger_condition": "Long-term use", "message": "May cause gradual, potentially permanent changes to eye color (increased brown pigmentation of the iris) and reversible changes to eyelashes (increased length, thickness, and pigmentation)."}]', '**Pigmentation Changes:** Latanoprost may gradually increase brown pigmentation of the iris, eyelashes, and periorbital tissue. Iris color changes may be permanent.
INSERT INTO "drug_generic" VALUES(808, 'Tibolone', 'Tibolone', 'G03CX01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiovascular and Malignancy Risk", "severity": "High", "trigger_condition": "Long-term use in postmenopausal women", "message": "Tibolone increases the risk of stroke, venous thromboembolism (VTE), and breast/endometrial cancer. Discontinue immediately in the event of a thromboembolic event, sudden severe headache, or significant increase in blood pressure."}]', 'Use with caution in patients with a history of or risk factors for thromboembolic disorders, impaired glucose tolerance, hypercholesterolemia, hypertension, cholelithiasis, systemic lupus erythematosus (SLE), uterine fibroids, endometriosis, or a history of endometrial hyperplasia. Conditions worsened by fluid retention (e.g., renal dysfunction, migraine, epilepsy) require close monitoring. Not recommended in women within 1 year of natural menopause due to a high frequency of irregular vaginal bleeding. Stop tibolone 4 weeks before elective surgery if prolonged immobilization is expected. Antidiabetic medication dosages may need adjustment.', '- **Menopausal Vasomotor Symptoms:** Treatment of symptoms (e.g., hot flushes, sweating) resulting from natural or surgical menopause in postmenopausal women.
INSERT INTO "drug_generic" VALUES(809, 'Drospirenone + Ethinylestradiol', 'Drospirenone and Ethinyl Estradiol', 'G03AA12', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cigarette Smoking and Serious Cardiovascular Events", "severity": "High", "trigger_condition": "Women over 35 years of age who smoke", "message": "STOP: Cigarette smoking increases the risk of serious cardiovascular events from combination oral contraceptives. This risk increases with age, particularly in women over 35 years of age, and with the number of cigarettes smoked. Use is strictly contraindicated in this population."}]', '**Hyperkalemia Risk:** Drospirenone has antimineralocorticoid activity, which can lead to hyperkalemia. Use with caution in patients taking other drugs that increase potassium (e.g., ACE inhibitors, ARBs, potassium-sparing diuretics, NSAIDs).
INSERT INTO "drug_generic" VALUES(810, 'Benznidazole', 'Benznidazole', 'P01CA02', 1, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Disulfiram-like Reaction", "severity": "High", "trigger_condition": "Concurrent use of alcohol or propylene glycol", "message": "STOP: Severe disulfiram-like reactions (abdominal cramps, nausea, vomiting, headaches, flushing) can occur. Strictly avoid alcohol and propylene glycol during therapy and for at least 3 days after the last dose."}]', '**Genotoxicity and Carcinogenicity:** Benznidazole has demonstrated genotoxic and carcinogenic potential in animal studies. The clinical relevance to humans is unknown, but the drug should be used strictly for its approved indication.
INSERT INTO "drug_generic" VALUES(811, 'Dexamethasone + Neomycin + Polymixin B eye prep', 'Neomycin, Polymyxin B, and Dexamethasone Ophthalmic', 'S01CA01', 1, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Ocular Infections and Glaucoma", "severity": "High", "trigger_condition": "Prolonged use or presence of viral/fungal eye infections", "message": "STOP: Corticosteroids can mask, activate, or exacerbate ocular infections. Contraindicated in viral (herpes simplex) and fungal eye diseases. Prolonged use may cause elevated intraocular pressure (glaucoma) and cataracts."}]', '**Intraocular Pressure (IOP) Elevation:** Prolonged use (>10 days) may result in ocular hypertension and/or glaucoma, with damage to the optic nerve and defects in visual acuity. IOP should be monitored routinely.
INSERT INTO "drug_generic" VALUES(812, 'Bazedoxifene + Conjugated estrogens', 'Conjugated estrogens and Bazedoxifene', 'G03CC07', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Malignancy Risks", "severity": "High", "trigger_condition": "Use in postmenopausal women", "message": "STOP: Estrogens increase the risk of stroke, DVT, PE, and dementia. Do not use for the prevention of cardiovascular disease or dementia. Bazedoxifene reduces the risk of endometrial hyperplasia, but any abnormal bleeding must be evaluated."}]', '**Cardiovascular Disorders:** Estrogens increase the risk of deep vein thrombosis (DVT), pulmonary embolism (PE), stroke, and myocardial infarction. Discontinue 4-6 weeks before surgery associated with an increased risk of thromboembolism or during prolonged immobilization.
INSERT INTO "drug_generic" VALUES(813, 'Lactitol', 'Lactitol', 'A06AD12', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Use with caution in patients with lactose intolerance, as lactitol is a derivative of lactose and may cause similar gastrointestinal symptoms. Ensure adequate fluid intake during treatment to prevent dehydration and optimize the laxative effect. Prolonged use of laxatives should be avoided; investigate underlying causes of chronic constipation.', '- **Constipation:** Treatment of chronic or habitual constipation.
INSERT INTO "drug_generic" VALUES(814, 'Glutaraldehyde', 'Glutaraldehyde', 'D08AX09', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Occupational Hazard and Toxicity", "severity": "High", "trigger_condition": "Handling and preparation", "message": "STOP: Highly toxic if ingested or inhaled. Requires a well-ventilated space, personal protective equipment (PPE), nitrile gloves, and eye protection. High risk of occupational asthma and severe contact dermatitis."}]', '**Topical Use (Warts):** Protect healthy surrounding skin with petroleum jelly during topical use to prevent severe irritation and necrosis of normal tissue.
INSERT INTO "drug_generic" VALUES(815, 'Vitamin A (Retinol)', 'Vitamin A', 'A11CA01', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Teratogenicity", "severity": "High", "trigger_condition": "Doses exceeding the Recommended Dietary Allowance (RDA) during pregnancy", "message": "STOP: High doses of Vitamin A (>10,000 IU/day) are highly teratogenic and can cause severe fetal malformations (cranial, facial, cardiac defects). Do not exceed the RDA in pregnant women unless treating severe deficiency."}]', '**Hepatic Impairment:** Vitamin A is stored in the liver. Patients with hepatic disease are at increased risk of toxicity. Monitor liver function and clinical signs of hypervitaminosis A.
INSERT INTO "drug_generic" VALUES(816, 'Vorapaxar', 'Vorapaxar', 'B01AC26', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Intracranial Hemorrhage Risk", "severity": "High", "trigger_condition": "Patient history of stroke, TIA, or intracranial hemorrhage", "message": "STOP: Vorapaxar is strictly contraindicated in patients with a history of stroke, transient ischemic attack (TIA), or intracranial hemorrhage (ICH) due to a significantly increased risk of fatal ICH."}]', '**Bleeding Risk:** Antiplatelet agents, including vorapaxar, increase the risk of bleeding, including intracranial hemorrhage (ICH) and fatal bleeding. Discontinue immediately in patients who experience a stroke, TIA, or ICH during therapy.
INSERT INTO "drug_generic" VALUES(817, 'Entrectinib', 'Entrectinib', 'L01EX14', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Congestive Heart Failure", "severity": "High", "trigger_condition": "Patients with pre-existing cardiac dysfunction or those developing symptoms of heart failure", "message": "STOP: Entrectinib can cause new-onset or worsening congestive heart failure. Assess LVEF prior to initiation in patients with symptoms or known cardiac risk factors."}]', '**Congestive Heart Failure:** New-onset or worsening congestive heart failure (CHF) has been reported. Assess left ventricular ejection fraction (LVEF) prior to initiation in patients with symptoms or known cardiac risk factors. Monitor for clinical signs of CHF during treatment.
INSERT INTO "drug_generic" VALUES(818, 'Etonogestrel + Ethinylestradiol', 'Etonogestrel and Ethinyl Estradiol', 'G02BB01', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Women over 35 years of age who smoke", "message": "STOP: Cigarette smoking increases the risk of serious cardiovascular events from combination hormonal contraceptive use. This risk increases with age, particularly in women over 35 years of age, and with the number of cigarettes smoked. Contraindicated in women >35 years who smoke."}]', '**Thromboembolic Disorders:** Increased risk of deep vein thrombosis (DVT), pulmonary embolism (PE), myocardial infarction (MI), and stroke. Discontinue immediately if an arterial or venous thrombotic event occurs.
INSERT INTO "drug_generic" VALUES(819, 'Interferon Alfa-2a', 'Interferon Alfa-2a', 'L03AB04', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Life-Threatening Disorders", "severity": "High", "trigger_condition": "Initiation of therapy or preexisting autoimmune/neuropsychiatric conditions", "message": "STOP: Alpha interferons cause or aggravate fatal or life-threatening neuropsychiatric, autoimmune, ischemic, and infectious disorders. Monitor closely with periodic clinical and laboratory evaluations."}]', 'Monitor closely for signs of severe depression, suicidal ideation, or other neuropsychiatric disorders; perform regular psychiatric evaluations during therapy.
INSERT INTO "drug_generic" VALUES(820, 'Cilnidipine', 'Cilnidipine', 'C08CA14', 0, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Rebound Angina/Hypertension", "severity": "Moderate", "trigger_condition": "Sudden discontinuation of therapy", "message": "WARNING: Sudden withdrawal of calcium channel blockers may exacerbate angina or cause rebound hypertension. Dosage should be gradually decreased under close medical observation."}]', '**Hypotension:** May cause symptomatic hypotension, particularly in patients with poor cardiac reserve or those taking other antihypertensive agents. Monitor blood pressure closely during initiation and dose titration.
INSERT INTO "drug_generic" VALUES(821, 'Agomelatine', 'Agomelatine', 'N06AX22', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "STOP: Agomelatine can cause severe hepatotoxicity, including fatal liver failure. Liver function tests (LFTs) MUST be performed before starting, and at 3, 6, 12, and 24 weeks during treatment."}, {"alert_type": "Suicidal Ideation", "severity": "High", "trigger_condition": "Patients with major depressive disorder, especially young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '**Hepatic Monitoring:** Discontinue immediately if serum transaminases exceed 3 times the upper limit of normal, or if the patient develops symptoms of liver injury (dark urine, light-colored stools, yellow skin/eyes, upper right abdominal pain, sustained new-onset fatigue).
INSERT INTO "drug_generic" VALUES(822, 'Piperacillin + Tazobactam', 'Piperacillin and Tazobactam', 'J01CR05', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity (anaphylactic/anaphylactoid) reactions have been reported. Cross-reactivity with cephalosporins may occur.
INSERT INTO "drug_generic" VALUES(823, 'Recombinent Human Luteinising Hormone (Lutropin alpha)', 'Lutropin alfa', 'G03GA07', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Ovarian Hyperstimulation Syndrome (OHSS)", "severity": "High", "trigger_condition": "Excessive ovarian response", "message": "STOP: Withhold hCG and advise the patient to refrain from coitus or use barrier methods for at least 4 days if significant ovarian hyperstimulation occurs."}]', '**Ovarian Hyperstimulation Syndrome (OHSS):** Patients undergoing follicular growth stimulation are at increased risk of developing OHSS, characterized by large ovarian cysts prone to rupture, ascites, and pleural effusion. Careful monitoring of ovarian response via ultrasound and serum estradiol is mandatory.
INSERT INTO "drug_generic" VALUES(824, 'Antazoline 0.05% + Tetryzoline 0.04% eye prep', 'Antazoline and Tetrahydrozoline Ophthalmic', 'S01GA52', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Rebound Congestion", "severity": "Medium", "trigger_condition": "Prolonged use (>14 days)", "message": "STOP: Prolonged use of topical ophthalmic decongestants can cause rebound hyperemia (redness) and toxic follicular conjunctivitis. Do not use for longer than 14 days."}]', '**Systemic Absorption:** Although applied topically, systemic absorption can occur, leading to headache, hypertension, tremors, and sweating. Use with caution in patients with cardiovascular disease, hypertension, or hyperthyroidism.
INSERT INTO "drug_generic" VALUES(825, 'Bisoprolol', 'Bisoprolol', 'C07AB07', 0, 1, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Abrupt Cessation Risk", "severity": "High", "trigger_condition": "Sudden discontinuation of therapy", "message": "STOP: Do not abruptly discontinue therapy. Severe exacerbation of angina, myocardial infarction, and ventricular arrhythmias have occurred following abrupt withdrawal of beta-blockers. Taper gradually over 1 to 2 weeks."}]', '- **Ischemic Heart Disease:** Abrupt withdrawal can exacerbate angina or precipitate MI. Taper gradually over 1-2 weeks.
INSERT INTO "drug_generic" VALUES(826, 'Ampicillin + Sulbactam', 'Ampicillin + Sulbactam', 'J01CR01', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "History of cholestatic jaundice or hepatic dysfunction with prior use", "message": "STOP: Hepatic dysfunction, including hepatitis and cholestatic jaundice, has been reported. Deaths have occurred. Contraindicated if previous history exists with this drug."}]', 'Use with caution in patients with a history of cephalosporin or carbapenem allergy due to potential cross-reactivity.
INSERT INTO "drug_generic" VALUES(827, 'Potassium Bicarbonate + Sodium Alginate', 'Potassium Bicarbonate / Sodium Alginate', 'A02BX13', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Renal Impairment:** Prescribe with caution in patients with renal impairment due to the potassium content, which may lead to hyperkalemia.
INSERT INTO "drug_generic" VALUES(828, 'Mepolizumab', 'Mepolizumab', 'R03DX09', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Following administration", "message": "Acute and delayed systemic reactions, including anaphylaxis, can occur. Discontinue mepolizumab in the event of a hypersensitivity reaction."}]', '**Acute Asthma Exacerbations:** Mepolizumab should not be used to treat acute asthma symptoms or acute exacerbations. Do not use to treat acute bronchospasm or status asthmaticus.
INSERT INTO "drug_generic" VALUES(829, 'Urofollitropin', 'Urofollitropin', 'G03GA04', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Ovarian Hyperstimulation Syndrome (OHSS)", "severity": "High", "trigger_condition": "During or immediately following ovulation induction therapy", "message": "STOP: OHSS is a severe, potentially fatal complication characterized by rapid ovarian enlargement, ascites, pleural effusion, and thromboembolism. Monitor ovaries via ultrasound and serum estradiol closely."}]', '**Ovarian Hyperstimulation Syndrome (OHSS):** OHSS is a medical event distinct from uncomplicated ovarian enlargement. It can progress rapidly to a serious, life-threatening condition. Monitor patients closely with transvaginal ultrasound and serum estradiol levels. Withhold hCG if ovaries are abnormally enlarged or estradiol levels are excessively high.
INSERT INTO "drug_generic" VALUES(830, 'Proparacaine Hydrochloride 0.5% eye prep', 'Proparacaine', 'S01HA04', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Corneal Toxicity", "severity": "High", "trigger_condition": "Prolonged or unsupervised use", "message": "STOP: Prolonged use of topical ocular anesthetics can cause permanent corneal opacification, ulceration, and visual loss. This product is for professional use only and MUST NEVER be prescribed for the patient''s own use."}]', '- **Systemic Absorption:** Use with caution and sparingly in patients with known allergies, cardiac disease, or hyperthyroidism, as systemic absorption can occur.
INSERT INTO "drug_generic" VALUES(831, 'Entecavir', 'Entecavir', 'J05AF10', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Hepatitis B Exacerbation", "severity": "High", "trigger_condition": "Discontinuation of therapy", "message": "STOP: Severe acute exacerbations of hepatitis B have been reported in patients who have discontinued anti-hepatitis B therapy. Hepatic function should be monitored closely for at least several months after stopping treatment."}]', '- **Lactic Acidosis and Hepatomegaly:** Lactic acidosis and severe hepatomegaly with steatosis, including fatal cases, have been reported with the use of nucleoside analogues. Discontinue if clinical or laboratory findings suggest these conditions.
INSERT INTO "drug_generic" VALUES(832, 'Pioglitazone', 'Pioglitazone', 'A10BG03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Congestive Heart Failure Risk", "severity": "High", "trigger_condition": "Patient history of symptomatic heart failure or NYHA Class III/IV", "message": "STOP: Thiazolidinediones, including pioglitazone, can cause or exacerbate congestive heart failure. Contraindicated in patients with NYHA Class III or IV heart failure."}]', '**Congestive Heart Failure:** Thiazolidinediones can cause dose-related fluid retention, which may lead to or exacerbate heart failure. Monitor patients closely for signs and symptoms of heart failure (e.g., rapid weight gain, dyspnea, edema).
INSERT INTO "drug_generic" VALUES(833, 'Brimonidine topical', 'Brimonidine', 'D11AX21', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Accidental Ingestion", "severity": "High", "trigger_condition": "Accidental ingestion by children", "message": "STOP: Serious adverse reactions, including severe hypotension and coma, may occur following accidental ingestion of alpha-2 agonists by children. Keep strictly out of reach of children."}]', 'Caution in patients with depression, cerebral or coronary insufficiency, Raynaud''s phenomenon, orthostatic hypotension, thromboangiitis obliterans, scleroderma, or Sjögren’s syndrome. Alpha-2 adrenergic agents can lower blood pressure; use with caution in severe or unstable cardiovascular disease. Serious adverse reactions may occur following accidental ingestion by children. Erythema involving areas of the face previously not affected and areas outside treatment sites has been reported. Treatment effect may diminish hours after application. Increased frequency of flushing and/or erythema with flushing reported. Allergic contact dermatitis and hypersensitivity reactions (angioedema, throat tightening) have been reported.', '- **Rosacea:** Indicated for the topical treatment of persistent (nontransient) facial erythema of rosacea in adults.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to brimonidine or any component of the formulation.', '- Flushing
INSERT INTO "drug_generic" VALUES(834, 'Hydrochlorothiazide + Triamterene', 'Triamterene and Hydrochlorothiazide', 'C03EA01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hyperkalemia", "severity": "High", "trigger_condition": "Renal impairment, diabetes, or concurrent use of potassium supplements/ACE inhibitors", "message": "STOP: Abnormal elevation of serum potassium levels (\u22655.5 mEq/L) can occur and may be fatal. Monitor potassium closely. Contraindicated in patients with pre-existing hyperkalemia or severe renal impairment."}]', '**Hyperkalemia:** Can cause fatal hyperkalemia. Risk is highest in patients with renal impairment, diabetes mellitus, the elderly, or those taking ACE inhibitors, ARBs, or potassium supplements. Monitor serum potassium frequently.
INSERT INTO "drug_generic" VALUES(835, 'Vinblastine', 'Vinblastine Sulfate', 'L01CA01', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Fatal Intrathecal Administration", "severity": "High", "trigger_condition": "Intrathecal route", "message": "STOP: FOR INTRAVENOUS USE ONLY. Fatal if given intrathecally. Dispense in an overwrap stating ''Do not remove covering until moment of injection. For intravenous use only\u2014Fatal if given by other routes.''"}, {"alert_type": "Extravasation Risk", "severity": "High", "trigger_condition": "Intravenous administration", "message": "STOP: Vinblastine is a potent vesicant. Extravasation can cause severe tissue necrosis. Ensure proper needle placement before and during infusion."}]', '**Myelosuppression:** Causes severe, dose-related leukopenia and granulocytopenia. The nadir in leukocyte count occurs 4-10 days after administration, with recovery in 7-14 days. Do not administer if WBC is <4,000/mm³.
INSERT INTO "drug_generic" VALUES(836, 'Ticlopidine Hydrochloride', 'Ticlopidine', 'B01AC05', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hematologic Toxicity", "severity": "High", "trigger_condition": "Initiation of therapy or ongoing treatment", "message": "STOP: Ticlopidine can cause life-threatening neutropenia, agranulocytosis, thrombotic thrombocytopenic purpura (TTP), and aplastic anemia. Routine complete blood counts (CBC) with differentials must be performed every 2 weeks for the first 3 months of therapy."}]', 'Therapy requires strict hematologic monitoring; perform full blood counts (CBC) with differentials prior to initiation and every 2 weeks during the first 3 months of treatment due to the risk of severe neutropenia and TTP.
INSERT INTO "drug_generic" VALUES(837, 'Candesartan Cilexetil', 'Candesartan Cilexetil', 'C09CA06', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Hypotension:** Symptomatic hypotension may occur, especially in volume- or salt-depleted patients (e.g., those treated with high-dose diuretics). Correct volume depletion prior to administration or start at a lower dose.
INSERT INTO "drug_generic" VALUES(838, 'Pyridostigmine', 'Pyridostigmine Bromide', 'N07AA02', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Cholinergic Crisis", "severity": "High", "trigger_condition": "Overdosage or hypersensitivity", "message": "STOP: Overdosage can cause cholinergic crisis (severe muscle weakness, respiratory paralysis, bradycardia, excessive salivation). Differentiate from myasthenic crisis. Atropine must be readily available as an antidote."}]', 'Use with extreme caution in patients with bronchial asthma or COPD, as it increases bronchial secretions and bronchospasm. Caution in patients with bradycardia, cardiac arrhythmias, vagotonia, peptic ulcer disease, epilepsy, parkinsonism, or hyperthyroidism. Renal impairment requires dose reduction as the drug is primarily excreted unchanged by the kidneys. Monitor closely for signs of cholinergic crisis, especially when administered intravenously.', '- **Myasthenia Gravis:** Symptomatic treatment of muscle weakness.
INSERT INTO "drug_generic" VALUES(839, 'Fluticasone Furoate Nasal prep', 'Fluticasone Furoate', 'R01AD12', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Local Nasal Effects:** Epistaxis, nasal ulceration, and nasal septal perforation have been reported. Monitor patients periodically for signs of adverse effects on the nasal mucosa.
INSERT INTO "drug_generic" VALUES(840, 'Pretomanid', 'Pretomanid', 'J04AK07', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Concurrent use with bedaquiline and linezolid or pre-existing hepatic impairment", "message": "STOP: Severe hepatic adverse reactions can occur. Monitor ALT, AST, alkaline phosphatase, and bilirubin at baseline, at 2 weeks, and monthly thereafter."}]', '**Hepatotoxicity:** Hepatic adverse reactions have been reported when used in combination with bedaquiline and linezolid. Interruption of treatment may be necessary. Obtain ALT, AST, alkaline phosphatase, and bilirubin at a minimum at baseline, at 2 weeks, and then monthly.
INSERT INTO "drug_generic" VALUES(841, 'Oxytetracycline 3% + Polymixin B Sulphate 0.013% Topical', 'Oxytetracycline 3% / Polymyxin B Sulfate Topical Ointment', 'D06AA03', 1, 0, 0, 1, 0, 1, 1, 0, '[]', '**Superinfection:** Prolonged use may result in the overgrowth of nonsusceptible organisms, including fungi. If superinfection occurs, discontinue use and institute appropriate therapy.
INSERT INTO "drug_generic" VALUES(842, 'Maraviroc', 'Maraviroc', 'J05AX09', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Development of systemic allergic signs (rash, eosinophilia) or elevated liver enzymes", "message": "STOP: Severe and potentially fatal hepatotoxicity with allergic features (e.g., severe rash, fever, eosinophilia, elevated IgE) has been reported. Discontinue maraviroc immediately if signs of hepatitis or allergic reaction occur."}]', '**Hepatotoxicity:** Drug-induced hepatotoxicity with allergic features has been reported. Monitor liver function tests closely, especially in patients with pre-existing liver dysfunction or co-infection with viral hepatitis B or C.
INSERT INTO "drug_generic" VALUES(843, 'Botulism immune globulin', 'Botulism immune globulin', 'J06BA02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hypersensitivity and Anaphylaxis", "severity": "High", "trigger_condition": "Patient history of severe systemic reactions to human immune globulin or IgA deficiency", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, can occur. Contraindicated in patients with selective IgA deficiency. Have epinephrine immediately available."}]', '**Renal Dysfunction:** Acute renal dysfunction and acute renal failure may occur with immune globulin intravenous (IGIV) products. Assess renal function (BUN, serum creatinine, urine output) prior to and following administration. Minimize the rate of infusion and concentration in patients at risk.
INSERT INTO "drug_generic" VALUES(844, 'Cefazolin', 'Cefazolin', 'J01DB04', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify patient allergy history before prescribing."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. Cross-hypersensitivity may occur in up to 10% of patients with a history of penicillin allergy. Discontinue immediately if an allergic reaction occurs.
INSERT INTO "drug_generic" VALUES(845, 'Pancuronium Bromide', 'Pancuronium Bromide', 'M03AC01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Respiratory Paralysis", "severity": "High", "trigger_condition": "Administration without mechanical ventilation", "message": "STOP: Pancuronium causes complete respiratory muscle paralysis. It must ONLY be administered by trained personnel in settings where endotracheal intubation and mechanical ventilation are immediately available."}]', '**Ventilatory Support:** Pancuronium paralyzes the respiratory muscles. It must only be administered by clinicians experienced in airway management, and facilities for intubation and mechanical ventilation must be immediately available.
INSERT INTO "drug_generic" VALUES(846, 'Azilsartan Medoxomil', 'Azilsartan Medoxomil', 'C09CA09', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected during therapy", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue azilsartan as soon as pregnancy is detected."}]', '**Hypotension:** Symptomatic hypotension may occur after initiation of treatment in patients with an activated renin-angiotensin system, such as those who are volume- or salt-depleted (e.g., patients on high doses of diuretics). Correct volume depletion prior to administration.
INSERT INTO "drug_generic" VALUES(847, 'Salicylic Acid 6% & 12% Topical', 'Salicylic Acid 6% & 12% Topical', 'D02AF', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'For external use only. Avoid contact with eyes, face, genitals, and mucous membranes. Do not apply to moles, birthmarks, or warts with hair growing from them. Discontinue use if excessive irritation occurs. Caution in patients with diabetes or poor blood circulation.', '- **6% Salicylic Acid:** Management of psoriasis, seborrhoeic dermatitis, lichen simplex, chronic atopic dermatitis, and ichthyosis.
INSERT INTO "drug_generic" VALUES(848, 'Daprodustat', 'Daprodustat', 'B03XA07', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Cardiovascular and Thrombotic Events", "severity": "High", "trigger_condition": "Targeting hemoglobin >11 g/dL or rapid rise in hemoglobin (>1 g/dL over 2 weeks)", "message": "STOP: Increased risk of death, myocardial infarction, stroke, venous thromboembolism, and thrombosis of vascular access. Do not target a hemoglobin >11 g/dL. Use the lowest dose sufficient to reduce the need for red blood cell transfusions."}]', 'Avoid use in patients with a history of myocardial infarction, cerebrovascular event, or acute coronary syndrome within 3 months before starting. Hospitalization for heart failure has been reported; consider the patient''s history of heart failure before prescribing. Periodically monitor blood pressure and adjust or initiate antihypertensive therapy as needed. Consider the risk of gastrointestinal erosions, particularly in patients with a history of peptic ulcer disease, concurrent use of ulcerogenic medications, or alcohol/tobacco use. Not recommended in patients with active malignancies.', '- **Anemia of Chronic Kidney Disease:** Indicated for the treatment of anemia due to chronic kidney disease (CKD) in adults who have been receiving dialysis for at least four months.
INSERT INTO "drug_generic" VALUES(849, 'Raloxifene Hydrochloride', 'Raloxifene', 'G03XC01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Venous Thromboembolism Risk", "severity": "High", "trigger_condition": "Patient history of deep vein thrombosis (DVT), pulmonary embolism (PE), or retinal vein thrombosis", "message": "STOP: Increased risk of deep vein thrombosis and pulmonary embolism. Contraindicated in patients with active or past history of venous thromboembolism."}]', 'Use with caution in women with risk factors for venous thromboembolism (VTE), including congestive heart failure (CHF) or active malignancy. Discontinue at least 72 hours prior to and during prolonged immobilization. Use with caution in patients with risk factors for stroke (e.g., transient ischemic attack, atrial fibrillation). May cause estrogen-induced hypertriglyceridemia; monitor serum triglyceride concentrations in patients with a history of this condition. Use with caution in moderate renal impairment. Supplemental calcium and vitamin D should be added to the diet if daily intake is inadequate.', '- **Postmenopausal Osteoporosis:** Treatment and prevention of osteoporosis in postmenopausal women.
INSERT INTO "drug_generic" VALUES(850, 'Naphazoline nasal prep', 'Naphazoline', 'R01AA08', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Rebound Congestion Risk", "severity": "High", "trigger_condition": "Use exceeding 3 consecutive days", "message": "STOP: Prolonged use (greater than 3 days) can cause severe rebound nasal congestion (rhinitis medicamentosa). Limit therapy duration."}]', '**Rebound Congestion:** Overuse or prolonged use (typically >3 days) may cause rebound congestion (rhinitis medicamentosa), characterized by chronic swelling of the nasal mucosa and worsening of symptoms.
INSERT INTO "drug_generic" VALUES(851, 'Chlorpheniramine + Phenylephrine', 'Chlorpheniramine + Phenylephrine', 'R01BA53', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "MAOI Interaction", "severity": "High", "trigger_condition": "Concurrent use of Monoamine Oxidase Inhibitors (MAOIs)", "message": "STOP: Contraindicated during or within 14 days of stopping an MAOI due to the risk of severe, life-threatening hypertensive crisis."}]', '**Cardiovascular Disease:** Phenylephrine is a potent vasoconstrictor. Use with extreme caution in patients with hypertension, ischemic heart disease, bradycardia, or severe arteriosclerosis.
INSERT INTO "drug_generic" VALUES(852, 'Amino acids IV', 'Amino Acids, Intravenous', 'B05BA01', 0, 0, 1, 1, 1, 0, 1, 0, '[]', '**Pulmonary Embolism:** Risk of pulmonary vascular precipitates. If signs of pulmonary distress occur, stop the infusion and initiate a medical evaluation.
INSERT INTO "drug_generic" VALUES(853, 'Water for injection', 'Sterile Water for Injection', 'V07AB', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Fatal Hemolysis Risk", "severity": "High", "trigger_condition": "Direct intravenous administration without solutes", "message": "STOP: Never administer Sterile Water for Injection directly into a vein without first adding appropriate solutes. Intravenous infusion of pure water is strongly hypotonic and will cause rapid, massive, and potentially fatal intravascular hemolysis."}]', '**Isotonicity Requirement:** Must be made approximately isotonic prior to intravenous administration by adding suitable solutes (e.g., medications, electrolytes) to prevent red blood cell lysis.
INSERT INTO "drug_generic" VALUES(854, 'Sodium alginate + Magnesium alginate', 'Sodium alginate + Magnesium alginate', 'A02BX13', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Sodium Content:** Use with caution in conditions where restricted sodium intake is indicated. The sodium content may add to the risk of hypernatremia.
INSERT INTO "drug_generic" VALUES(855, 'Sonidegib', 'Sonidegib', 'L01XJ02', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Administration to pregnant women or females of reproductive potential", "message": "STOP: Sonidegib can cause severe birth defects or embryo-fetal death. Verify pregnancy status prior to initiation. Advise effective contraception during treatment and for at least 20 months after the last dose."}]', '- **Embryo-Fetal Toxicity:** Can cause embryo-fetal death or severe birth defects. Verify pregnancy status prior to initiation.
INSERT INTO "drug_generic" VALUES(856, 'Mephentermine', 'Mephentermine', 'C01CA11', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Hypertension and Arrhythmias", "severity": "High", "trigger_condition": "Concomitant use with MAOIs or in patients with severe cardiovascular disease", "message": "STOP: Severe, potentially fatal hypertensive crisis can occur if used with MAOIs. Risk of fatal arrhythmias in patients undergoing anesthesia with cyclopropane or halothane."}]', '**Hypovolemic Shock:** For shock due to loss of blood or fluid, mephentermine is not a substitute for fluid replacement. Give adequate fluid replacement therapy primarily before or concurrently with vasopressor administration.
INSERT INTO "drug_generic" VALUES(857, 'Imipenem + Cilastatin', 'Imipenem and Cilastatin', 'J01DH51', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Seizure Risk", "severity": "High", "trigger_condition": "Renal impairment or underlying CNS disorders", "message": "STOP: Imipenem is associated with a risk of seizures, particularly in patients with underlying CNS disorders (e.g., brain lesions, history of seizures) or compromised renal function when dosages are not properly adjusted."}, {"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Cross-reactivity with other beta-lactams (penicillins, cephalosporins) is possible."}]', '**Central Nervous System Effects:** Seizures, confusion, and myoclonic activity have been reported. Adhere strictly to recommended dosages, especially in patients with renal impairment or a history of seizures.
INSERT INTO "drug_generic" VALUES(858, 'Tazemetostat', 'Tazemetostat', 'L01XX69', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Secondary Malignancies", "severity": "High", "trigger_condition": "Development of new hematologic abnormalities", "message": "STOP: Tazemetostat increases the risk of developing secondary malignancies, including T-cell lymphoblastic lymphoma, myelodysplastic syndrome (MDS), and acute myeloid leukemia (AML). Monitor complete blood counts regularly."}]', '**Secondary Malignancies:** Increases the risk of developing secondary malignancies, including T-cell lymphoblastic lymphoma, myelodysplastic syndrome (MDS), and acute myeloid leukemia (AML). Monitor patients long-term for the development of secondary malignancies.
INSERT INTO "drug_generic" VALUES(859, 'Spiramycine', 'Spiramycin', 'J01FA02', 1, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "QT Prolongation and Arrhythmias", "severity": "High", "trigger_condition": "Patients with a history of arrhythmias, prolonged QT interval, or concurrent use of QT-prolonging drugs", "message": "STOP: Spiramycin can cause significant QT interval prolongation leading to life-threatening ventricular arrhythmias (e.g., Torsades de Pointes). Evaluate ECG and concurrent medications before use."}]', 'Use with caution in patients with hepatic impairment; monitor liver function tests periodically during prolonged therapy. Exercise extreme caution in patients with a history of arrhythmias, uncorrected hypokalemia or hypomagnesemia, or a predisposition to QT interval prolongation. Monitor for signs of superinfection or pseudomembranous colitis (Clostridioides difficile-associated diarrhea) with prolonged use. Use with caution in patients with a history of macrolide hypersensitivity.', '- **Toxoplasmosis:** Indicated for the treatment and prophylaxis of toxoplasmosis, particularly to prevent transplacental transmission of *Toxoplasma gondii* in pregnant women.
INSERT INTO "drug_generic" VALUES(860, 'Idarucizumab', 'Idarucizumab', 'V03AB37', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "Reversal of dabigatran anticoagulation", "message": "STOP: Reversing dabigatran exposes patients to the thrombotic risk of their underlying disease. Resume anticoagulant therapy as soon as medically appropriate."}]', '**Thromboembolic Risk:** Patients treated with dabigatran have underlying disease states that predispose them to thromboembolic events. Reversing dabigatran therapy exposes patients to the thrombotic risk of their underlying disease. To reduce this risk, resume anticoagulant therapy as soon as medically appropriate.
INSERT INTO "drug_generic" VALUES(861, 'Methenamine', 'Methenamine', 'J01XX05', 1, 0, 0, 1, 1, 0, 1, 0, '[]', '**Urine Acidification:** Methenamine is only effective in acidic urine (pH < 5.5). It is ineffective in conditions where urine acidification is unattainable, such as infections caused by urea-splitting bacteria (e.g., *Proteus*, *Pseudomonas*) which alkalinize the urine.
INSERT INTO "drug_generic" VALUES(862, 'Levamlodipine', 'Levamlodipine', 'C08CA01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Symptomatic Hypotension", "severity": "Medium", "trigger_condition": "Initiation of therapy in patients with severe aortic stenosis", "message": "Caution: Symptomatic hypotension is possible, particularly in patients with severe aortic stenosis. Monitor blood pressure closely during initiation and titration."}]', '**Hypotension:** Symptomatic hypotension is possible, particularly in patients with severe aortic stenosis. Because of the gradual onset of action, acute hypotension is unlikely, but caution is advised.
INSERT INTO "drug_generic" VALUES(863, 'Beclomethasone + Gentamicin + Miconazole Topical', 'Beclomethasone, Gentamicin, and Miconazole Topical', 'D07CC04', 1, 0, 0, 0, 0, 0, 0, 1, '[]', '**Systemic Absorption:** Prolonged use, application of large amounts, treatment of extensive areas, or use of occlusive dressings can result in sufficient systemic absorption to produce hypercortisonism and Hypothalamic-Pituitary-Adrenal (HPA) axis suppression. 
INSERT INTO "drug_generic" VALUES(864, 'Oxaprozin', 'Oxaprozin', 'M01AE12', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal bleeding, ulceration, and perforation."}]', '**Cardiovascular Risk:** May increase the risk of serious and potentially fatal cardiovascular thrombotic events, myocardial infarction, and stroke. Risk may increase with duration of use and in patients with underlying cardiovascular disease.
INSERT INTO "drug_generic" VALUES(865, 'Dioxybenzone 0.3% + Hydroquinone 0.4% + Octyldimet p-aminobenzoate 0.8% + Oxybenzone 0.2%', 'Dioxybenzone, Hydroquinone, Padimate O, and Oxybenzone', 'D11AX11', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Hypersensitivity and Severe Dermatitis", "severity": "High", "trigger_condition": "Application to broken, abraded, or sunburned skin", "message": "STOP: Do not apply to cut, abraded, or sunburned skin. Severe inflammatory responses and systemic absorption of hydroquinone can occur."}]', '- **Sensitivity Testing:** Always test for skin sensitivity before initiating full treatment by applying a small amount to an unbroken patch of skin and observing for 24 hours.
INSERT INTO "drug_generic" VALUES(866, 'Moexipril', 'Moexipril', 'C09AA13', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Fetal Toxicity:** Use of drugs that act on the renin-angiotensin system during the second and third trimesters of pregnancy reduces fetal renal function and increases fetal and neonatal morbidity and death. Discontinue immediately upon detection of pregnancy.
INSERT INTO "drug_generic" VALUES(867, 'Betaxolol 0.5%  Eye prep', 'Betaxolol Ophthalmic', 'S01ED02', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Systemic Beta-Blocker Effects", "severity": "High", "trigger_condition": "Systemic absorption following ocular administration", "message": "STOP: Topically applied beta-blockers can be absorbed systemically. Severe respiratory reactions (bronchospasm) and cardiac reactions (bradycardia, heart block, heart failure) can occur. Use with extreme caution in patients with asthma, COPD, or severe cardiac disease."}]', '**Cardiovascular Effects:** Can cause bradycardia, heart block, and worsen heart failure. Discontinue at the first sign of cardiac failure. Use with caution in patients with cerebrovascular insufficiency.
INSERT INTO "drug_generic" VALUES(868, 'Hyoscine Hydro Bromide', 'Scopolamine Hydrobromide', 'A04AD01', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Central Nervous System Depression", "severity": "High", "trigger_condition": "Concurrent use with alcohol or other CNS depressants", "message": "STOP: Additive sedative effects can lead to severe CNS depression, respiratory failure, and coma. Monitor closely and adjust dosages if concurrent use is unavoidable."}]', '**Cardiovascular Disease:** Use with caution in patients with coronary artery disease, tachyarrhythmias, heart failure, or hypertension, as anticholinergic effects can exacerbate tachycardia.
INSERT INTO "drug_generic" VALUES(869, 'Tacrolimus', 'Tacrolimus', 'L04AD02', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Malignancy and Serious Infections Risk", "severity": "High", "trigger_condition": "Initiation of therapy or prolonged use", "message": "STOP: Increased risk of developing lymphomas and other malignancies. Increased susceptibility to bacterial, viral, fungal, and protozoal infections, including opportunistic infections."}]', '**Lymphoma and Other Malignancies:** Risk of lymphomas, including post-transplant lymphoproliferative disorder (PTLD), appears related to the intensity and duration of immunosuppression. Avoid prolonged exposure to UV light and sunlight.
INSERT INTO "drug_generic" VALUES(870, 'Fluorescein Sodium 2% Eye prep', 'Fluorescein Sodium 2% Ophthalmic Solution', 'S01JA01', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'For topical ophthalmic use only. Do not inject. Soft contact lenses may absorb fluorescein and become permanently discolored; lenses should be removed prior to instillation and kept out for at least 15 minutes or until the dye is completely flushed from the eye. (Note: Severe local tissue damage from extravasation applies to intravenous formulations, not topical eye preparations).', '- **Diagnostic Ophthalmic Procedures:** Used as a diagnostic aid in evaluating corneal and conjunctival epithelial defects, abrasions, and ulcers.
INSERT INTO "drug_generic" VALUES(871, 'Gentamicin 0.3% + Hydrocortisone Acetate 1% Eye prep', 'Gentamicin and Hydrocortisone', 'S01CA01', 1, 0, 0, 1, 0, 1, 0, 1, '[{"alert_type": "Ocular Toxicity Risk", "severity": "High", "trigger_condition": "Prolonged use exceeding 10 days", "message": "Prolonged use of ophthalmic corticosteroids may result in glaucoma with damage to the optic nerve, defects in visual acuity and fields of vision, and posterior subcapsular cataract formation. Monitor intraocular pressure routinely if used for 10 days or longer."}]', 'Prolonged use of corticosteroids may suppress the host response and increase the hazard of secondary ocular infections. In acute purulent conditions of the eye, corticosteroids may mask infection or enhance existing infection. Prolonged use may also result in ocular hypertension and/or glaucoma, with damage to the optic nerve, and posterior subcapsular cataract formation. Intraocular pressure should be routinely monitored if this product is used for 10 days or longer. Use of corticosteroids after cataract surgery may delay healing and increase the incidence of bleb formation. Fungal infections of the cornea are particularly prone to develop coincidentally with long-term local corticosteroid application. Systemic absorption of gentamicin is minimal, but caution is advised in patients with severe renal impairment or those receiving systemic aminoglycosides.', '- **Corticosteroid-Responsive Ocular Inflammation with Infection:** Treatment of steroid-responsive inflammatory ocular conditions for which a corticosteroid is indicated and where superficial bacterial ocular infection or a risk of bacterial ocular infection exists.
INSERT INTO "drug_generic" VALUES(872, 'Insulin Glulisine', 'Insulin Glulisine', 'A10AB06', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypoglycemia", "severity": "High", "trigger_condition": "Changes in insulin regimen, missed meals, increased physical activity, or co-administration with other glucose-lowering agents", "message": "STOP: Severe, life-threatening hypoglycemia can occur. Monitor blood glucose closely when adjusting doses, changing diet, or altering physical activity."}, {"alert_type": "Hypokalemia", "severity": "High", "trigger_condition": "Intravenous administration or use with potassium-depleting drugs", "message": "STOP: Insulin shifts potassium intracellularly, which can lead to severe hypokalemia and fatal cardiac arrhythmias. Monitor serum potassium levels, especially in high-risk patients."}]', '**Hypoglycemia:** The most common adverse effect of insulin therapy. Risk increases with changes in meal patterns, physical activity, or co-administered medications. Early warning symptoms may be different or less pronounced in patients with long-standing diabetes, diabetic nerve disease, or those taking beta-blockers.
INSERT INTO "drug_generic" VALUES(873, 'Erythropoietin', 'Epoetin alfa', 'B03XA01', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Cardiovascular and Thromboembolic Risk", "severity": "High", "trigger_condition": "Targeting hemoglobin levels >11 g/dL or rapid rise in hemoglobin", "message": "STOP: Erythropoiesis-stimulating agents (ESAs) increase the risk of death, myocardial infarction, stroke, venous thromboembolism, and tumor progression. Use the lowest dose needed to avoid RBC transfusions. Do not target a hemoglobin level >11 g/dL."}]', '**Cardiovascular Events:** Increased risk of serious cardiovascular events, stroke, and mortality when targeting hemoglobin levels >11 g/dL. Monitor blood pressure closely; control hypertension prior to initiation and during therapy.
INSERT INTO "drug_generic" VALUES(874, 'Pipecuronium bromide', 'Pipecuronium bromide', 'M03AC06', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Paralysis Without Sedation", "severity": "High", "trigger_condition": "Administration without adequate anesthesia", "message": "STOP: Pipecuronium causes profound skeletal muscle paralysis, including respiratory muscles, but has NO effect on consciousness or pain threshold. It MUST be administered by trained personnel with adequate general anesthesia and continuous ventilatory support."}]', '**Respiratory Support:** Must be administered only by clinicians experienced in the use of neuromuscular blocking agents. Facilities for intubation, artificial respiration, and oxygen therapy must be immediately available.
INSERT INTO "drug_generic" VALUES(875, 'Silodosin', 'Silodosin', 'G04CA04', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Orthostatic Hypotension", "severity": "Moderate", "trigger_condition": "Initiation of therapy or dose escalation", "message": "Postural hypotension, with or without symptoms (e.g., dizziness), may develop when beginning treatment. Advise patients to avoid abrupt postural changes."}]', '**Orthostatic Hypotension:** Can cause a decrease in blood pressure, leading to syncope or dizziness. Use caution when co-administering with other antihypertensives or PDE5 inhibitors.
INSERT INTO "drug_generic" VALUES(876, 'Nusinersen', 'Nusinersen', 'M09AX07', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Coagulation and Renal Toxicity", "severity": "High", "trigger_condition": "Prior to each intrathecal administration", "message": "STOP: Risk of severe thrombocytopenia, coagulation abnormalities, and potentially fatal glomerulonephritis. Obtain platelet count, coagulation profile, and quantitative spot urine protein prior to every dose."}]', '**Coagulation Abnormalities and Thrombocytopenia:** Acute severe thrombocytopenia and coagulation abnormalities have been observed after administration of some antisense oligonucleotides. Obtain a platelet count and coagulation laboratory testing at baseline and prior to each administration, and as clinically needed.
INSERT INTO "drug_generic" VALUES(877, 'Aluminium Hydroxide + Magnesium Trisilicate', 'Aluminum Hydroxide and Magnesium Trisilicate', 'A02AD01', 0, 0, 1, 1, 1, 1, 0, 0, '[{"alert_type": "Drug Interactions", "severity": "Medium", "trigger_condition": "Concurrent administration with other oral medications", "message": "STOP: Antacids significantly decrease the absorption of many drugs (e.g., tetracyclines, fluoroquinolones, bisphosphonates). Administer antacids at least 2 hours before or after other medications."}]', '**Renal Impairment:** Use with caution in patients with chronic renal impairment. Magnesium and aluminum can accumulate, leading to hypermagnesemia and aluminum toxicity.
INSERT INTO "drug_generic" VALUES(878, 'Clindamycin', 'Clindamycin', 'J01FF01', 1, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Clostridioides difficile-Associated Diarrhea (CDAD)", "severity": "High", "trigger_condition": "Development of significant diarrhea or abdominal cramps during or after therapy", "message": "STOP: Clindamycin therapy has been associated with severe and potentially fatal Clostridioides difficile-associated diarrhea (CDAD) and pseudomembranous colitis. Discontinue immediately if significant diarrhea occurs."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** CDAD has been reported with use of nearly all antibacterial agents, including clindamycin, and may range in severity from mild diarrhea to fatal colitis. Hypertoxin-producing strains of *C. difficile* cause increased morbidity and mortality. If CDAD is suspected or confirmed, ongoing antibiotic use not directed against *C. difficile* may need to be discontinued.
INSERT INTO "drug_generic" VALUES(879, 'Lanthanum Carbonate', 'Lanthanum Carbonate', 'V03AE03', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Gastrointestinal Obstruction and Perforation", "severity": "High", "trigger_condition": "Patients with altered GI anatomy, hypomotility, or history of GI surgery", "message": "STOP: Severe gastrointestinal complications, including obstruction, ileus, subileus, gastrointestinal perforation, and fecal impaction, have been reported. Evaluate risk factors before initiating therapy."}]', '**Gastrointestinal Disorders:** Use with extreme caution in patients with altered GI anatomy (e.g., diverticular disease, peritonitis, history of GI surgery, GI cancer, GI ulceration), hypomotility disorders (e.g., constipation, diabetic gastroparesis), active peptic ulcer, Crohn''s disease, or ulcerative colitis due to the risk of severe GI complications.
INSERT INTO "drug_generic" VALUES(880, 'Baricitinib', 'Baricitinib', 'L04AA37', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Serious Infections and Malignancy", "severity": "High", "trigger_condition": "Initiation of therapy or concurrent immunosuppression", "message": "Increased risk of serious bacterial, fungal, viral, and opportunistic infections (including TB) leading to hospitalization or death. Higher rate of all-cause mortality, MACE, thrombosis, and malignancies compared to TNF blockers."}]', '**Serious Infections:** Increased risk of serious bacterial, fungal, viral, and opportunistic infections leading to hospitalization or death, including tuberculosis (TB). Interrupt treatment if a serious infection occurs until it is controlled. Do not initiate in patients with active TB. Test for latent TB before and during therapy (except for COVID-19); treat latent TB prior to use.
INSERT INTO "drug_generic" VALUES(881, 'Imiquimod Topical', 'Imiquimod', 'D06BB10', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Severe Local Skin Reactions", "severity": "Moderate", "trigger_condition": "Application to sensitive areas or excessive dosing", "message": "Intense local inflammatory reactions (erythema, edema, weeping) can occur. Avoid contact with eyes, lips, and nostrils. Do not use occlusive dressings."}]', '- **Local Skin Reactions:** Intense local inflammatory reactions including erythema, edema, vesicles, weeping, and crusting can occur. Treatment may need to be temporarily suspended if reactions are severe.
INSERT INTO "drug_generic" VALUES(882, 'Nirmatrelvir + Ritonavir', 'Nirmatrelvir and Ritonavir', 'J05AE30', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Drug Interactions", "severity": "High", "trigger_condition": "Coadministration with drugs highly dependent on CYP3A for clearance", "message": "STOP: Ritonavir is a potent CYP3A inhibitor. Coadministration with certain drugs (e.g., amiodarone, rivaroxaban, statins) can cause life-threatening toxicities. Review the patient''s complete medication list before prescribing."}]', '- **Hepatotoxicity:** Hepatic transaminase elevations, clinical hepatitis, and jaundice have been reported with ritonavir. Use caution in patients with preexisting liver diseases, liver enzyme abnormalities, or hepatitis.
INSERT INTO "drug_generic" VALUES(883, 'Natalizumab', 'Natalizumab', 'L04AA23', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Progressive Multifocal Leukoencephalopathy (PML)", "severity": "High", "trigger_condition": "Presence of anti-JCV antibodies, longer duration of therapy, or prior immunosuppressant use", "message": "STOP: Natalizumab increases the risk of PML, an opportunistic viral infection of the brain that usually leads to death or severe disability. Monitor for new or worsening neurological symptoms. Available only through a restricted REMS program."}]', '**Progressive Multifocal Leukoencephalopathy (PML):** Natalizumab increases the risk of PML. Risk factors include the presence of anti-JCV antibodies, longer duration of therapy (especially >2 years), and prior use of immunosuppressants. Monitor patients closely for any new or worsening neurological, cognitive, or psychiatric symptoms. Withhold dosing immediately if PML is suspected.
INSERT INTO "drug_generic" VALUES(884, 'Alefacept', 'Alefacept', 'L04AA15', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Lymphopenia and Immunosuppression", "severity": "High", "trigger_condition": "CD4+ T lymphocyte count <250 cells/mcL", "message": "STOP: Alefacept induces dose-dependent reductions in CD4+ and CD8+ T lymphocytes. Monitor CD4+ counts weekly. Withhold dosing if CD4+ count is <250 cells/mcL. Discontinue permanently if CD4+ count remains <250 cells/mcL for one month."}]', '**Lymphopenia:** Induces dose-dependent reductions in circulating CD4+ and CD8+ T lymphocyte counts. Weekly monitoring of CD4+ T lymphocyte counts is mandatory during the 12-week dosing period.
INSERT INTO "drug_generic" VALUES(885, 'Acyclovir Oral', 'Acyclovir', 'J05AB01', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Neurotoxicity in Renal Impairment", "severity": "High", "trigger_condition": "Administration to patients with renal impairment without dose adjustment", "message": "STOP: Acyclovir can cause severe neurotoxicity (lethargy, confusion, seizures, coma) and acute renal failure if doses are not appropriately reduced in patients with decreased creatinine clearance."}]', '**Renal Impairment:** Acyclovir is eliminated primarily by renal clearance. Dose adjustments are required. Precipitation of acyclovir in renal tubules can occur, leading to acute renal failure. Maintain adequate hydration during therapy.
INSERT INTO "drug_generic" VALUES(886, 'Carbamide Peroxide ear prep', 'Carbamide Peroxide Otic', 'S02DC', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Contraindicated in Tympanic Perforation", "severity": "High", "trigger_condition": "Patient has a ruptured eardrum or ear discharge", "message": "STOP: Do not use this product if the patient has a perforated tympanic membrane (ruptured eardrum), ear discharge, ear pain, or recent ear surgery, as it can cause severe inner ear damage and pain."}]', '**Duration of Use:** Do not use for more than 4 consecutive days. If excessive earwax remains after 4 days of use, consult a physician.
INSERT INTO "drug_generic" VALUES(887, 'Alendronic Acid (Alendronate)', 'Alendronate', 'M05BA04', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Esophageal Injury", "severity": "High", "trigger_condition": "Improper administration technique", "message": "STOP: Severe esophageal adverse reactions (esophagitis, ulcers, erosions) can occur. Patients MUST take with a full glass of plain water and remain fully upright (sitting or standing) for at least 30 minutes and until after their first food of the day."}]', '**Upper Gastrointestinal Adverse Reactions:** Can cause severe irritation of the upper GI mucosa. Discontinue if dysphagia, odynophagia, or retrosternal pain occurs.
INSERT INTO "drug_generic" VALUES(888, 'Linagliptin + Metformin Hydrochloride', 'Linagliptin and Metformin', 'A10BD11', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Lactic Acidosis", "severity": "High", "trigger_condition": "Renal impairment, hypoxia, or acute illness", "message": "STOP: Metformin can cause severe, potentially fatal lactic acidosis. Risk increases with renal impairment, sepsis, dehydration, excess alcohol intake, hepatic impairment, and acute congestive heart failure."}]', '**Lactic Acidosis:** Metformin accumulation can cause lactic acidosis, a rare but potentially fatal metabolic complication. Risk factors include renal impairment, advanced age, hypoxic states, excessive alcohol intake, and hepatic impairment. If lactic acidosis is suspected, discontinue immediately and institute supportive measures (hemodialysis).
INSERT INTO "drug_generic" VALUES(889, 'Mycophenolic Acid (Mycophenolate sodium)', 'Mycophenolic Acid', 'L04AA06', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Embryofetal Toxicity", "severity": "High", "trigger_condition": "Prescribing to females of reproductive potential", "message": "STOP: Use during pregnancy is associated with increased risks of first-trimester pregnancy loss and congenital malformations. Exclude pregnancy before initiation and ensure highly effective contraception is used."}, {"alert_type": "Serious Infections and Malignancies", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "WARNING: Increased susceptibility to infection and possible development of lymphoma and other neoplasms may result from immunosuppression."}]', '**Infection Risk:** Profound immunosuppression increases the risk of bacterial, viral, fungal, and protozoal infections, including opportunistic infections and viral reactivation (e.g., Hepatitis B/C, JC virus causing Progressive Multifocal Leukoencephalopathy [PML]).
INSERT INTO "drug_generic" VALUES(890, 'Chloroxylenol 4.8% topical', 'Chloroxylenol', 'D08AE05', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "High", "trigger_condition": "Application near sensitive areas", "message": "STOP: For external use only. Avoid contact with the brain, meninges, middle ear, sensitive tissues, and eyes. Do not inject or use in body cavities."}]', '**Dilution Requirement:** Must be diluted with water before use on the skin or wounds to prevent severe skin irritation or chemical burns.
INSERT INTO "drug_generic" VALUES(891, 'Paracetamol + Pseudoephedrine', 'Acetaminophen and Pseudoephedrine', 'N02BE51', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Exceeding maximum daily dose of paracetamol or concurrent alcohol use", "message": "STOP: Severe hepatotoxicity can occur if the maximum daily dose of paracetamol (4000 mg) is exceeded. Verify all concurrent medications to ensure no other paracetamol-containing products are being used."}, {"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Patients with severe hypertension or severe coronary artery disease", "message": "WARNING: Pseudoephedrine is a sympathomimetic amine. Use is contraindicated in patients with severe hypertension or severe coronary artery disease."}]', '**Cardiovascular and Endocrine Effects:** Pseudoephedrine can cause increases in blood pressure and heart rate. Use with caution in patients with cardiovascular disease, diabetes mellitus, prostatic hypertrophy, and increased intraocular pressure (glaucoma).
INSERT INTO "drug_generic" VALUES(892, 'Chloramphenicol Ear drops', 'Chloramphenicol Otic', 'S02AA01', 1, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Ototoxicity Risk", "severity": "High", "trigger_condition": "Perforated tympanic membrane", "message": "STOP: Contraindicated in patients with a perforated eardrum. Introduction of this agent into the middle ear can cause severe ototoxicity and permanent hearing loss."}]', '**Systemic Absorption:** Although rare with otic use, systemic absorption of chloramphenicol can occur, leading to severe blood dyscrasias (aplastic anemia). Avoid prolonged or repeated courses of treatment.
INSERT INTO "drug_generic" VALUES(893, 'Chlorthalidone', 'Chlorthalidone', 'C03BA04', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Electrolyte Imbalance", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "Electrolyte disturbances (hypokalemia, hyponatremia, hypochloremic alkalosis) may occur. Monitor serum electrolytes regularly. Correct hypokalemia before initiating therapy."}]', '**Metabolic Effects:** Therapy may alter glucose tolerance (hyperglycemia), raise serum levels of cholesterol and triglycerides, and reduce the clearance of uric acid, potentially precipitating gout in susceptible patients.
INSERT INTO "drug_generic" VALUES(894, 'Rimantadine', 'Rimantadine Hydrochloride', 'J05AC02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Seizure Risk", "severity": "Moderate", "trigger_condition": "Patients with a history of epilepsy or seizure disorders", "message": "May increase the risk of seizures in patients with a history of epilepsy. Discontinue treatment immediately if a seizure occurs."}]', '**CNS Effects:** Can cause dizziness, nervousness, and insomnia. Use caution when driving or operating machinery.
INSERT INTO "drug_generic" VALUES(895, 'Calcium Carbonate', 'Calcium Carbonate', 'A12AA04', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Achlorhydria:** Calcium carbonate requires an acidic environment for optimal absorption. Absorption may be impaired in patients with achlorhydria (common in the elderly) or those taking proton pump inhibitors. Taking the supplement with meals improves absorption.
INSERT INTO "drug_generic" VALUES(896, 'Indacaterol + Glycopyrronium', 'Indacaterol and Glycopyrrolate', 'R03AL04', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Asthma-Related Death Risk", "severity": "High", "trigger_condition": "Use in patients with asthma without a long-term asthma control medication", "message": "STOP: Long-acting beta2-adrenergic agonists (LABAs) increase the risk of asthma-related death. This medication is not indicated for the treatment of asthma."}]', '**Paradoxical Bronchospasm:** Life-threatening paradoxical bronchospasm can occur. If this occurs, discontinue therapy immediately and institute alternative therapy.
INSERT INTO "drug_generic" VALUES(897, 'Difelikefalin', 'Difelikefalin', 'V03AX04', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "CNS Depression", "severity": "High", "trigger_condition": "Concomitant use of centrally-acting depressants", "message": "STOP: Dizziness, somnolence, and mental status changes can occur. Use extreme caution when co-administering with sedating antihistamines, opioid analgesics, or other CNS depressants."}]', '**Central Nervous System Depression:** Dizziness, somnolence, mental status changes, and gait disturbances, including falls, have occurred. Centrally-acting depressant medications, sedating antihistamines, and opioid analgesics should be used with caution during treatment.
INSERT INTO "drug_generic" VALUES(898, 'Magaldrate + Simethicone', 'Magaldrate and Simethicone', 'A02AF02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Toxicity in Renal Impairment", "severity": "High", "trigger_condition": "Severe renal impairment (CrCl < 30 mL/min)", "message": "STOP: Magaldrate contains magnesium and aluminum. In patients with severe renal impairment, accumulation can lead to fatal hypermagnesemia and aluminum toxicity. Use is contraindicated."}]', '**Renal Impairment:** Use with extreme caution in patients with mild to moderate renal impairment due to the risk of magnesium and aluminum accumulation.
INSERT INTO "drug_generic" VALUES(899, 'Racepinephrine', 'Racepinephrine', 'R03AA01', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Patient with underlying cardiac disease or hypertension", "message": "STOP: Excessive use or large doses can cause severe cardiovascular events, including fatal ventricular fibrillation, worsened myocardial ischemia, and emergent hypertension."}]', '**Cardiovascular Disease:** Use with extreme caution in patients with angina, tachycardia, myocardial infarction, or hypertension due to the risk of emergent hypertension, stroke, or worsened ischemia.
INSERT INTO "drug_generic" VALUES(900, 'Loratadine + Pseudoephedrine Hydrochloride', 'Loratadine and Pseudoephedrine', 'R01BA52', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hypertensive Crisis", "severity": "High", "trigger_condition": "Concurrent use with Monoamine Oxidase Inhibitors (MAOIs)", "message": "STOP: Pseudoephedrine is contraindicated in patients taking MAOIs or within 14 days of stopping an MAOI due to the risk of severe, potentially fatal hypertensive crisis."}]', '**Cardiovascular Disease:** Pseudoephedrine can cause cardiovascular stimulation. Use with caution in patients with hypertension, ischemic heart disease, arrhythmias, or hyperthyroidism. Monitor blood pressure.
INSERT INTO "drug_generic" VALUES(901, 'Ramelteon', 'Ramelteon', 'N05CH02', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Anaphylaxis and Angioedema", "severity": "High", "trigger_condition": "First dose or subsequent doses of Ramelteon", "message": "STOP: Severe anaphylactic and anaphylactoid reactions, including angioedema involving the tongue, glottis, or larynx, can occur. Do not rechallenge if a reaction occurs."}]', '**Severe Hypersensitivity Reactions:** Rare cases of severe anaphylactic and anaphylactoid reactions, including angioedema of the tongue, glottis, or larynx, have been reported. Symptoms such as dyspnea, throat closing, or nausea and vomiting may occur. Emergency treatment may be required, and fatalities are possible. Do not rechallenge patients who develop these reactions.
INSERT INTO "drug_generic" VALUES(902, 'Bisoprolol  + Hydrochlorothiazide', 'Bisoprolol and Hydrochlorothiazide', 'C07BB07', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Abrupt Discontinuation", "severity": "High", "trigger_condition": "Sudden cessation of therapy", "message": "STOP: Abrupt cessation of beta-blockers can exacerbate angina pectoris and precipitate myocardial infarction or ventricular arrhythmias. Taper gradually over 1-2 weeks."}]', '**Cardiac Failure:** Beta-blockers can depress myocardial contractility and precipitate heart failure. Use with caution in compensated heart failure.
INSERT INTO "drug_generic" VALUES(903, 'Teprotumumab', 'Teprotumumab-trbw', 'S01XA29', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Infusion Reactions", "severity": "High", "trigger_condition": "During or shortly after IV infusion", "message": "STOP: Severe infusion reactions may occur. If an infusion reaction occurs, interrupt or slow the infusion rate and institute appropriate medical management immediately."}]', '**Infusion Reactions:** Infusion-related reactions may occur during or shortly after administration. Monitor patients closely. If a reaction occurs, interrupt or slow the infusion rate and use appropriate medical management (e.g., corticosteroids, antihistamines).
INSERT INTO "drug_generic" VALUES(904, 'Zonisamide', 'Zonisamide', 'N03AX15', 0, 0, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Severe Skin Reactions and Sulfonamide Allergy", "severity": "High", "trigger_condition": "Patient history of sulfonamide allergy or development of rash", "message": "STOP: Zonisamide is a sulfonamide. Fatalities have occurred due to severe reactions including Stevens-Johnson syndrome (SJS) and toxic epidermal necrolysis (TEN). Discontinue immediately at the first sign of a rash."}, {"alert_type": "Oligohidrosis and Hyperthermia", "severity": "High", "trigger_condition": "Decreased sweating and elevated body temperature, especially in pediatric patients", "message": "STOP: Can cause oligohidrosis and hyperthermia. Monitor body temperature and hydration closely, especially in warm weather or during exercise."}]', '**Sulfonamide Hypersensitivity:** Zonisamide is a sulfonamide derivative. Severe, potentially fatal reactions such as Stevens-Johnson syndrome (SJS), toxic epidermal necrolysis (TEN), fulminant hepatic necrosis, agranulocytosis, and aplastic anemia can occur. Discontinue at the first sign of rash or hypersensitivity.
INSERT INTO "drug_generic" VALUES(905, 'Benzoyl Peroxide 4% topical', 'Benzoyl Peroxide', 'D10AE01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Bleaching and Discoloration", "severity": "Low", "trigger_condition": "Contact with hair or fabrics", "message": "Avoid contact with hair and dyed fabrics (e.g., pillowcases, towels, clothing), as benzoyl peroxide will bleach or discolor them."}]', '- **Skin Irritation:** Erythema, burning, itching, peeling, and swelling may occur, especially during the first few weeks of use. If irritation is severe, decrease the frequency of application or discontinue use.
INSERT INTO "drug_generic" VALUES(906, 'Folic Acid + Zinc', 'Folic Acid and Zinc', 'B03BB51', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Neurological Risk", "severity": "High", "trigger_condition": "Administration in patients with undiagnosed or untreated Vitamin B12 deficiency", "message": "Folic acid alone is improper therapy in the treatment of pernicious anemia and other megaloblastic anemias where vitamin B12 is deficient. It may correct the hematological abnormalities while allowing irreversible neurological damage to progress."}]', 'Ensure vitamin B12 deficiency is ruled out before initiating therapy, as folic acid can mask the hematological signs of pernicious anemia while neurological damage progresses. Prolonged use of high doses of zinc may lead to copper deficiency, which can present as anemia and neutropenia. Monitor patients on long-term therapy.', '- **Nutritional Deficiency:** Prevention and treatment of Folic acid and Zinc deficiencies.
INSERT INTO "drug_generic" VALUES(907, 'Clozapine', 'Clozapine', 'N05AH02', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Severe Neutropenia (Agranulocytosis)", "severity": "High", "trigger_condition": "Absolute Neutrophil Count (ANC) drops below acceptable thresholds", "message": "WARNING: Clozapine can cause severe, life-threatening neutropenia. It is available only through a restricted REMS program. Strict, regular monitoring of ANC is mandatory before, during, and after treatment."}, {"alert_type": "Myocarditis and Cardiomyopathy", "severity": "High", "trigger_condition": "Development of unexplained fatigue, dyspnea, tachypnea, fever, chest pain, or ECG findings", "message": "WARNING: Fatal myocarditis and cardiomyopathy have occurred. Discontinue clozapine immediately and obtain a cardiac evaluation if these are suspected."}, {"alert_type": "Seizures", "severity": "High", "trigger_condition": "High doses or rapid dose escalation", "message": "WARNING: Seizures are dose-related. Initiate at a low dose, titrate gradually, and use divided doses. Use with extreme caution in patients with a history of seizures."}, {"alert_type": "Orthostatic Hypotension, Bradycardia, and Syncope", "severity": "High", "trigger_condition": "Initial titration period or rapid dose escalation", "message": "WARNING: Severe orthostatic hypotension, bradycardia, syncope, and cardiac arrest can occur. Titrate slowly starting at 12.5 mg."}]', '**Increased Mortality in Elderly Patients with Dementia-Related Psychosis:** Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Clozapine is not approved for this use.
INSERT INTO "drug_generic" VALUES(908, 'Artemether + Lumefantrine', 'Artemether and Lumefantrine', 'P01BF01', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Concurrent use with QT-prolonging drugs or in patients with hypokalemia", "message": "STOP: Lumefantrine can prolong the QT interval. Avoid in patients with known QT prolongation, uncorrected hypokalemia/hypomagnesemia, or those taking Class IA/III antiarrhythmics or other QT-prolonging drugs."}]', '**Food Requirement:** Lumefantrine absorption is highly dependent on food (specifically fat). Patients unable to eat are at a much higher risk of treatment failure and recrudescence. Monitor these patients closely.
INSERT INTO "drug_generic" VALUES(909, 'Triptorelin Acetate', 'Triptorelin', 'L02AE04', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Tumor Flare / Spinal Cord Compression", "severity": "High", "trigger_condition": "Initiation of therapy in patients with advanced prostate cancer", "message": "STOP: Initial administration causes a transient surge in testosterone, which can exacerbate bone pain, neuropathy, or cause spinal cord compression and ureteral obstruction. Monitor closely during the first few weeks."}]', '- **Tumor Flare:** In men with prostate cancer, an initial transient increase in serum testosterone occurs, potentially worsening symptoms (bone pain, neuropathy, hematuria). Consider concurrent antiandrogen therapy during the first few weeks.
INSERT INTO "drug_generic" VALUES(910, 'Cepalin + Allantoin + Panthenol topical', 'Allium cepa extract / Allantoin / Panthenol', 'D03AX', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Application Site Reactions:** Not for use on deep or puncture wounds, damaged or broken skin, animal bites, or serious burns. Apply only to intact skin.
INSERT INTO "drug_generic" VALUES(911, 'Naftidrofuryl Oxalate', 'Naftidrofuryl', 'C04AX21', 0, 0, 0, 0, 1, 0, 0, 0, '[]', '**Hydration and Renal Stones:** Patients must maintain an adequate fluid intake during treatment to ensure sufficient diuresis. The drug is an oxalate salt, and inadequate hydration can lead to the formation of calcium oxalate kidney stones.
INSERT INTO "drug_generic" VALUES(912, 'Digoxin', 'Digoxin', 'C01AA05', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Toxicity and Electrolyte Imbalance", "severity": "High", "trigger_condition": "Hypokalemia, hypomagnesemia, or hypercalcemia", "message": "STOP: Digoxin has a narrow therapeutic index. Electrolyte imbalances (especially hypokalemia) significantly increase the risk of fatal digoxin toxicity and cardiac arrhythmias. Monitor serum electrolytes and digoxin levels closely."}]', '**Electrolyte Imbalances:** Hypokalemia, hypomagnesemia, and hypercalcemia strongly predispose patients to digoxin toxicity. Correct electrolyte disturbances before and during therapy.
INSERT INTO "drug_generic" VALUES(913, 'Mafenide', 'Mafenide Acetate', 'D06BA03', 1, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Metabolic Acidosis", "severity": "High", "trigger_condition": "Application to large burn areas or renal impairment", "message": "STOP: Mafenide and its primary metabolite inhibit carbonic anhydrase, which can lead to severe metabolic acidosis, especially in patients with extensive burns or renal impairment. Monitor acid-base balance and respiratory rate closely."}]', '**Metabolic Acidosis:** Mafenide and its metabolite are carbonic anhydrase inhibitors. Systemic absorption from large burn areas can cause metabolic acidosis, often compensated by hyperventilation (tachypnea). Monitor acid-base balance closely. If acidosis becomes severe, discontinue temporarily for 24-48 hours.
INSERT INTO "drug_generic" VALUES(914, 'Bosentan', 'Bosentan', 'C02KX01', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Initiation of therapy and monthly thereafter", "message": "STOP: Bosentan causes dose-dependent elevations in AST/ALT. Liver aminotransferases must be measured prior to initiation and monthly during treatment."}, {"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Females of reproductive potential", "message": "STOP: Bosentan is highly teratogenic. Exclude pregnancy before starting. Patients must use two reliable forms of contraception during and for 1 month after treatment."}]', '**Hepatotoxicity:** Elevations of AST or ALT >3x ULN occur in about 11% of patients. Discontinue if elevations are accompanied by clinical symptoms of hepatotoxicity (nausea, vomiting, jaundice) or bilirubin >2x ULN.
INSERT INTO "drug_generic" VALUES(915, 'Metoprolol Tartrate', 'Metoprolol', 'C07AB02', 0, 1, 0, 1, 0, 1, 1, 1, '[{"alert_type": "Ischemic Heart Disease", "severity": "High", "trigger_condition": "Abrupt discontinuation of therapy", "message": "STOP: Abrupt cessation can exacerbate angina pectoris, precipitate myocardial infarction, or cause severe ventricular arrhythmias. Taper the dose gradually over 1 to 2 weeks and monitor the patient closely."}]', 'Use with caution in patients with bronchospastic disease (e.g., asthma, COPD); while metoprolol is beta-1 selective, selectivity is not absolute and diminishes at higher doses. May mask the signs and symptoms of hypoglycemia (e.g., tachycardia, tremor) in diabetic patients, though sweating is usually uninhibited. May mask clinical signs of hyperthyroidism (e.g., tachycardia); abrupt withdrawal may precipitate thyroid storm. Use with caution in patients with compensated heart failure; initiate at very low doses. May exacerbate symptoms of peripheral arterial disease. Caution in patients undergoing major surgery involving general anesthesia due to impaired ability of the heart to respond to reflex adrenergic stimuli.', '- Management of hypertension (alone or in combination).
INSERT INTO "drug_generic" VALUES(916, 'Levofloxacin', 'Levofloxacin', 'J01MA12', 1, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Adverse Reactions", "severity": "High", "trigger_condition": "Any patient prescribed systemic fluoroquinolones", "message": "STOP: Fluoroquinolones are associated with disabling and potentially irreversible serious adverse reactions, including tendinitis, tendon rupture, peripheral neuropathy, and CNS effects. Reserve for patients with no alternative treatment options for uncomplicated infections. Exacerbates muscle weakness in Myasthenia Gravis."}]', '**Tendinitis and Tendon Rupture:** Increased risk, especially in patients >60 years, those taking corticosteroids, and kidney/heart/lung transplant recipients. Discontinue immediately if tendon pain or inflammation occurs.
INSERT INTO "drug_generic" VALUES(917, 'Diethylamine Salicylate', 'Diethylamine Salicylate', 'M02AC', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '**Application Site Reactions:** Do not apply to broken skin, open wounds, mucous membranes, or near the eyes. Discontinue use if excessive skin irritation, rash, or blistering occurs.
INSERT INTO "drug_generic" VALUES(918, 'Gatifloxacin', 'Gatifloxacin', 'J01MA16', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Dysglycemia, Tendon Rupture, and QT Prolongation", "severity": "High", "trigger_condition": "Systemic administration, especially in diabetics or elderly", "message": "STOP: Systemic gatifloxacin is associated with severe, potentially fatal dysglycemia (hypoglycemia and hyperglycemia). It also carries risks for tendon rupture, QT prolongation, and severe CNS effects. Monitor blood glucose and ECG closely."}]', 'Monitor blood glucose closely; severe and potentially fatal hyperosmolar nonketotic hyperglycemic coma and hypoglycemic coma have occurred, particularly in diabetic patients.
INSERT INTO "drug_generic" VALUES(919, 'Fructose 10%', 'Fructose', 'B05BA03', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Metabolic Toxicity", "severity": "High", "trigger_condition": "Rapid intravenous infusion or administration in patients with hereditary fructose intolerance", "message": "Rapid infusion of fructose can cause severe lactic acidosis and hyperuricemia. It is strictly contraindicated in patients with hereditary fructose intolerance, where it can cause fatal hypoglycemia and liver failure."}]', 'Administer with caution to patients with impaired kidney function or severe liver damage. Monitor fluid balance, electrolyte concentrations, and acid-base balance during prolonged therapy. Infusion should be immediately discontinued if rigor, fever, or other adverse reactions arise. Do not use if the solution is cloudy, contains particles, or if the container is damaged. Rapid infusion can result in facial flushing, abdominal pain, sweating, and metabolic complications.', '- **Fluid and Caloric Replacement:** Used as a carbohydrate nutrient and fluid replenisher, particularly in diabetic patients where insulin-independent carbohydrate metabolism is desired.
INSERT INTO "drug_generic" VALUES(920, 'Tenapanor', 'Tenapanor', 'A06AX08', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Risk of Serious Dehydration in Pediatric Patients", "severity": "High", "trigger_condition": "Prescribing to children under 6 years of age", "message": "STOP: Contraindicated in children under 6 years of age. In young juvenile rats, tenapanor caused death presumed to be due to dehydration. Avoid use in patients 6 to less than 12 years of age."}]', '**Diarrhea:** Tenapanor can cause severe diarrhea. If severe diarrhea occurs, suspend dosing and rehydrate the patient appropriately.
INSERT INTO "drug_generic" VALUES(921, 'Fusidic Acid 2% + Hydrocortisone Acetate 1% Topical', 'Fusidic Acid + Hydrocortisone Topical', 'D07CA01', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Ocular Toxicity", "severity": "High", "trigger_condition": "Application near or in the eyes", "message": "STOP: Do not use in or near the eyes. Exposure can cause severe conjunctival irritation and increases the risk of elevated intraocular pressure, glaucoma, and cataracts."}]', 'Avoid prolonged use (greater than 14 days) to prevent the emergence of resistant bacterial strains and local corticosteroid-induced skin atrophy.
INSERT INTO "drug_generic" VALUES(922, 'Ribavirin', 'Ribavirin', 'J05AP01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Teratogenicity and Hemolytic Anemia", "severity": "High", "trigger_condition": "Pregnancy or pre-existing cardiac disease", "message": "STOP: Ribavirin is strictly contraindicated in pregnancy (Category X) and in male partners of pregnant women due to severe teratogenic effects. It also causes dose-dependent hemolytic anemia, which can worsen underlying cardiac disease."}]', 'Ribavirin monotherapy is not effective for the treatment of chronic hepatitis C and must be used in combination with interferon alfa or direct-acting antivirals. The primary toxicity is hemolytic anemia, which can occur within 1-2 weeks of initiation; monitor hemoglobin/hematocrit closely. Anemia may exacerbate underlying cardiac disease, leading to fatal or nonfatal myocardial infarction; use with extreme caution in patients with a history of CHF or arrhythmias. Use with caution in patients with pre-existing psychiatric disorders, COPD, asthma, or thyroid disorders. Monitor hematologic, cardiac, respiratory, and ophthalmic function. Obtain negative pregnancy tests monthly during therapy and for 6 months post-therapy.', '- **Chronic Hepatitis C (CHC):** Indicated in combination with peginterferon alfa, interferon alfa, or direct-acting antivirals (DAAs) for the treatment of chronic hepatitis C virus infection in patients with compensated liver disease.
INSERT INTO "drug_generic" VALUES(923, 'Danazol', 'Danazol', 'G03XA01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Pregnancy Contraindication", "severity": "High", "trigger_condition": "Use in women of childbearing potential", "message": "WARNING: Danazol is contraindicated in pregnancy. It can cause severe virilization (androgenic effects) of a female fetus. A negative pregnancy test is required before starting, and non-hormonal contraception must be used."}, {"alert_type": "Hepatic Toxicity and Peliosis Hepatis", "severity": "High", "trigger_condition": "Long-term therapy", "message": "WARNING: Long-term use is associated with peliosis hepatis and benign hepatic adenomas, which can rupture and cause fatal intra-abdominal hemorrhage. Monitor liver function closely."}, {"alert_type": "Thromboembolic Events", "severity": "High", "trigger_condition": "Any patient on therapy", "message": "WARNING: Thromboembolic events, including fatal strokes and myocardial infarctions, have been reported. Discontinue immediately if signs of thrombosis occur."}]', '**Benign Intracranial Hypertension (Pseudotumor Cerebri):** Cases have been reported. Screen for papilledema if patients present with headache, nausea, vomiting, or visual disturbances. Discontinue immediately if present.
INSERT INTO "drug_generic" VALUES(924, 'Lumateperone', 'Lumateperone', 'N05AX16', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Increased Mortality in Elderly Patients", "severity": "High", "trigger_condition": "Use in elderly patients with dementia-related psychosis", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Lumateperone is not approved for this use."}, {"alert_type": "Suicidal Thoughts and Behaviors", "severity": "High", "trigger_condition": "Use in young adults or patients with a history of depression", "message": "STOP: Antidepressants and antipsychotics may increase the risk of suicidal thoughts and behaviors in pediatric and young adult patients. Monitor closely for clinical worsening."}]', '**Neuroleptic Malignant Syndrome (NMS):** A potentially fatal symptom complex reported with antipsychotic drugs. Signs include hyperpyrexia, muscle rigidity, altered mental status, and autonomic instability. If NMS is suspected, immediately discontinue lumateperone and provide intensive symptomatic treatment.
INSERT INTO "drug_generic" VALUES(925, 'Erdosteine', 'Erdosteine', 'R05CB15', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Gastrointestinal Bleeding Risk", "severity": "High", "trigger_condition": "Patient with active peptic ulcer disease", "message": "STOP: Mucolytics can disrupt the gastric mucosal barrier. Use is strictly contraindicated in patients with active peptic ulcers."}]', 'Use with caution in patients with a history of peptic ulcer disease.
INSERT INTO "drug_generic" VALUES(926, 'Dextran 70 + Hypromellose Eye prep', 'Dextran 70 / Hypromellose', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Visual Disturbances:** Transient blurred vision may occur immediately after instillation; patients should be advised not to drive or operate hazardous machinery until vision clears.
INSERT INTO "drug_generic" VALUES(927, 'Telmisartan', 'Telmisartan', 'C09CA07', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected during therapy", "message": "STOP: Discontinue telmisartan immediately if pregnancy is detected. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}]', '**Fetal Toxicity:** Discontinue immediately upon detection of pregnancy. Exposure during the second and third trimesters can cause fetal renal dysfunction, oligohydramnios, and skull hypoplasia.
INSERT INTO "drug_generic" VALUES(928, 'Secukinumab', 'Secukinumab', 'L04AC10', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Infection Risk", "severity": "High", "trigger_condition": "Patient with active infection or history of recurrent infections", "message": "STOP: Secukinumab may increase the risk of infections. Do not initiate treatment in patients with any clinically important active infection until the infection resolves or is adequately treated."}]', '**Infections:** Secukinumab may increase the risk of infections. Caution should be exercised when considering the use of secukinumab in patients with a chronic infection or a history of recurrent infection. If a serious infection develops, monitor the patient closely and discontinue secukinumab until the infection resolves.
INSERT INTO "drug_generic" VALUES(929, 'Encorafenib', 'Encorafenib', 'L01EC03', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "New Primary Malignancies and Hemorrhage", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "Can cause new primary cutaneous and non-cutaneous malignancies. Severe, sometimes fatal, hemorrhagic events can occur when used with binimetinib. Monitor dermatologic and clinical status closely."}]', '**Paradoxical Activation in Wild-Type BRAF:** Confirm evidence of BRAF V600E or V600K mutation prior to initiating treatment. In vitro experiments demonstrate paradoxical activation of MAP-kinase signaling and increased cell proliferation in BRAF wild-type cells exposed to BRAF inhibitors. Not indicated for wild-type BRAF melanoma.
INSERT INTO "drug_generic" VALUES(930, 'Poliovirus vaccine inactivated', 'Poliovirus vaccine inactivated', 'J07BF03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of hypersensitivity to neomycin, streptomycin, or polymyxin B", "message": "STOP: The vaccine contains trace amounts of neomycin, streptomycin, and polymyxin B. Severe anaphylaxis can occur in allergic patients. Ensure epinephrine is readily available."}]', 'Postpone vaccination in patients suffering from an acute severe febrile illness. Use with caution in patients with bleeding disorders or thrombocytopenia, as intramuscular injection may cause bleeding; consider subcutaneous administration. Immunocompromised patients may have a diminished immune response. Syncope (fainting) can occur following, or even before, any vaccination as a psychogenic response; observe patients for 15 minutes post-vaccination.', '- **Poliomyelitis Prophylaxis:** Indicated for active immunization of infants, children, and adults against poliomyelitis caused by poliovirus types 1, 2, and 3.', '- **Hypersensitivity:** Contraindicated in individuals with a history of severe allergic reaction (e.g., anaphylaxis) to any component of the vaccine, including trace antibiotics (neomycin, streptomycin, polymyxin B) or following a previous dose of IPV.
INSERT INTO "drug_generic" VALUES(931, 'Dextrose 5% + Sodium Chloride 0.9%', 'Dextrose 5% and Sodium Chloride 0.9%', 'B05BB02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Fluid and Solute Overload", "severity": "Moderate", "trigger_condition": "Administration in patients with congestive heart failure or severe renal insufficiency", "message": "Caution: Can cause significant fluid overload, pulmonary edema, and electrolyte disturbances. Monitor fluid balance and electrolytes closely."}]', '**Fluid and Electrolyte Overload:** Administration can cause fluid and/or solute overload resulting in dilution of serum electrolyte concentrations, overhydration, congested states, or pulmonary edema. Use with caution in patients with congestive heart failure or severe renal insufficiency.
INSERT INTO "drug_generic" VALUES(932, 'Metolazone', 'Metolazone', 'C03BA08', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Profound Diuresis and Electrolyte Depletion", "severity": "High", "trigger_condition": "Concomitant use with loop diuretics (e.g., furosemide)", "message": "STOP: Combination therapy with loop diuretics can cause profound, synergistic diuresis leading to severe volume depletion, hypotension, and life-threatening electrolyte abnormalities (hypokalemia, hyponatremia). Monitor fluid status and electrolytes meticulously."}]', 'Monitor serum electrolytes (potassium, sodium, magnesium, calcium) frequently, as severe hypokalemia and hyponatremia can occur. Use with caution in patients with pre-diabetes or diabetes mellitus, as it may impair glucose tolerance and precipitate hyperglycemia. May precipitate hyperuricemia and acute gout attacks. Caution in patients with systemic lupus erythematosus (SLE), as thiazide-like diuretics may exacerbate or activate the disease. Cross-sensitivity may occur in patients with known allergies to sulfonamides, sulfonylureas, or carbonic anhydrase inhibitors. Unlike standard thiazides, metolazone remains effective in patients with severely impaired renal function (GFR <20 mL/min).', '- Treatment of edema accompanying congestive heart failure.
INSERT INTO "drug_generic" VALUES(933, 'Pyrazinamide', 'Pyrazinamide', 'J04AK01', 1, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Pre-existing liver disease or concurrent use of other hepatotoxic drugs (e.g., Rifampin, Isoniazid)", "message": "STOP: Pyrazinamide can cause severe and potentially fatal liver damage. Monitor liver function tests (ALT, AST, bilirubin) at baseline and periodically. Discontinue immediately if signs of hepatocellular damage occur."}]', 'Use with extreme caution in patients with a history of gout or hyperuricemia, as pyrazinamide decreases renal excretion of urates, frequently precipitating acute gouty attacks. Caution is required in patients with diabetes mellitus, as management may become difficult. Baseline and periodic monitoring of liver function tests (LFTs) and serum uric acid are mandatory. Discontinue if severe hepatic damage or acute gout occurs. Use cautiously in patients with mild to moderate renal impairment; dose adjustments are required.', '- **Tuberculosis (Active):** Used in combination with other antituberculosis agents (e.g., isoniazid, rifampin, ethambutol) for the initial 2-month intensive phase of treatment for active, drug-susceptible *Mycobacterium tuberculosis* infections.
INSERT INTO "drug_generic" VALUES(934, 'Carboxymethylcellulose Sodium 0.25% + Hypromellose 0.3% Eye prep', 'Carboxymethylcellulose Sodium and Hypromellose Ophthalmic', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'For external ophthalmic use only. Discontinue use and consult a physician if patients experience severe eye pain, changes in vision, or if redness and irritation of the eye worsen or persist for more than 72 hours. To avoid contamination, do not touch the tip of the container to any surface, including the eye. Remove contact lenses before application unless the specific formulation is labeled as safe for use with contacts.', '- Relief of dryness, burning, and irritation of the eye associated with reduced or abnormal tear production (dry eye syndrome).
INSERT INTO "drug_generic" VALUES(935, 'Alendronic Acid + Vitamin D3', 'Alendronate and Cholecalciferol', 'M05BB03', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Esophageal Injury", "severity": "High", "trigger_condition": "Improper administration technique", "message": "STOP: Severe esophageal adverse reactions (esophagitis, ulcers, erosions) can occur. Patients MUST take with a full glass of plain water and remain fully upright (sitting or standing) for at least 30 minutes and until after their first food of the day."}]', '**Upper Gastrointestinal Adverse Reactions:** Can cause severe irritation of the upper GI mucosa. Discontinue if dysphagia, odynophagia, or retrosternal pain occurs.
INSERT INTO "drug_generic" VALUES(936, 'Linaclotide', 'Linaclotide', 'A06AX04', 0, 0, 1, 1, 0, 0, 0, 0, '[{"alert_type": "Risk of Serious Dehydration in Pediatric Patients", "severity": "High", "trigger_condition": "Administration to pediatric patients under 18 years of age", "message": "STOP: Contraindicated in patients less than 6 years of age; in nonclinical studies, linaclotide caused deaths due to severe dehydration. Avoid use in patients 6 to 17 years of age."}]', '**Severe Diarrhea:** Can cause severe diarrhea leading to dehydration and electrolyte imbalances. Discontinue use and rehydrate if severe or prolonged (e.g., >1 week) diarrhea occurs.
INSERT INTO "drug_generic" VALUES(937, 'Fluticasone Propionate + Formoterol Fumarate', 'Fluticasone and Formoterol', 'R03AK11', 0, 0, 1, 1, 0, 1, 1, 1, '[{"alert_type": "Acute Asthma Exacerbation", "severity": "High", "trigger_condition": "Use during acute bronchospasm", "message": "STOP: This inhaler is not a rescue medication and should not be used to treat acute asthma symptoms or status asthmaticus. A short-acting beta2-agonist (e.g., salbutamol) must be used for acute relief."}, {"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediately after inhalation", "message": "Paradoxical bronchospasm may occur with an immediate increase in wheezing. Discontinue immediately, treat with a fast-acting bronchodilator, and institute alternative therapy."}]', '**Systemic Corticosteroid Effects:** May occur with high doses prescribed for long periods, including Cushing''s syndrome, adrenal suppression, growth retardation in children, decreased bone mineral density, and cataracts/glaucoma. Titrate to the lowest effective dose.
INSERT INTO "drug_generic" VALUES(938, 'Beclomethasone + Chloramphenicol + Clotrimazole + Lidocaine ear prep', 'Beclomethasone, Chloramphenicol, Clotrimazole, and Lidocaine Otic', 'S02CA', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Ototoxicity Risk", "severity": "High", "trigger_condition": "Perforated tympanic membrane", "message": "STOP: Do not use if the eardrum is perforated. Chloramphenicol can cause severe ototoxicity if it enters the middle ear."}]', '**Superinfection:** Prolonged use may result in the overgrowth of non-susceptible organisms, including resistant bacteria and fungi.
INSERT INTO "drug_generic" VALUES(939, 'Buspirone', 'Buspirone', 'N05BE01', 0, 0, 1, 0, 1, 0, 0, 0, '[{"alert_type": "Drug Interaction", "severity": "High", "trigger_condition": "Concurrent use with Monoamine Oxidase Inhibitors (MAOIs)", "message": "STOP: Concurrent administration with MAOIs may result in a severe hypertensive reaction. Do not use buspirone within 14 days of discontinuing an MAOI."}]', '**Delayed Onset of Action:** Buspirone does not exhibit immediate anxiolytic effects. It should not be used on a PRN (as-needed) basis for acute anxiety episodes. Optimal therapeutic results may take 2 to 4 weeks to manifest.
INSERT INTO "drug_generic" VALUES(940, 'Nafcillin', 'Nafcillin', 'J01CF06', 1, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}, {"alert_type": "Vesicant/Extravasation Risk", "severity": "High", "trigger_condition": "Intravenous administration", "message": "Nafcillin is a known vesicant. Severe tissue necrosis can occur with extravasation. Administer via a central line if possible and monitor the infusion site closely."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. These are more likely in individuals with a history of penicillin hypersensitivity or sensitivity to multiple allergens. Discontinue immediately if an allergic reaction occurs.
INSERT INTO "drug_generic" VALUES(941, 'Chorionic Gonadotrophin', 'Chorionic Gonadotropin', 'G03GA01', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Ovarian Hyperstimulation Syndrome (OHSS)", "severity": "High", "trigger_condition": "Significant ovarian enlargement or excessive estradiol production", "message": "STOP: Severe and potentially fatal Ovarian Hyperstimulation Syndrome (OHSS) can occur. Withhold therapy if ovaries are abnormally enlarged or if early warning signs (severe pelvic pain, nausea, vomiting, weight gain) develop."}]', '**Ovarian Hyperstimulation Syndrome (OHSS):** A serious medical event characterized by a dramatic increase in vascular permeability, resulting in rapid fluid accumulation in the peritoneal cavity, thorax, and pericardium. Early warning signs include severe pelvic pain, nausea, vomiting, and weight gain. Withhold hCG if OHSS is suspected.
INSERT INTO "drug_generic" VALUES(942, 'Terbinafine Topical', 'Terbinafine Topical', 'D01AE15', 0, 0, 1, 0, 0, 1, 0, 0, '[]', '**Local Irritation:** Discontinue use if irritation, sensitization, or worsening of the condition occurs.
INSERT INTO "drug_generic" VALUES(943, 'Ritonavir', 'Ritonavir', 'J05AE03', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Drug Interactions", "severity": "High", "trigger_condition": "Concurrent use with highly CYP3A-dependent drugs", "message": "STOP: Ritonavir is a potent CYP3A inhibitor. Co-administration with drugs highly dependent on CYP3A for clearance can result in life-threatening toxicities."}]', '**Hepatotoxicity:** Hepatic transaminase elevations exceeding 5 times the upper limit of normal, clinical hepatitis, and jaundice have occurred. Monitor liver function tests before and during therapy, especially in patients with underlying hepatic disease.
INSERT INTO "drug_generic" VALUES(944, 'Hydrous Benzoyl Peroxide 6.5%', 'Benzoyl Peroxide', 'D10AE01', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity/Anaphylaxis", "severity": "Moderate", "trigger_condition": "Initial application", "message": "Rare but serious and potentially life-threatening allergic reactions or severe irritation can occur. Advise patients to test on a small area for 3 days before full application."}]', 'Discontinue use if severe irritation, erythema, or peeling develops. Restart with lower concentrations or less frequent applications after irritation has cleared. Do not use occlusive dressings. May cause contact dermatitis in allergic patients. Apply carefully, avoiding the eyes, mouth, lips, mucous membranes, and other sensitive areas (e.g., neck). Benzoyl peroxide may bleach hair and colored fabrics.', '- **Acne Vulgaris:** Topical treatment of mild to moderate acne vulgaris.
INSERT INTO "drug_generic" VALUES(945, 'Quinapril', 'Quinapril', 'C09AA06', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: When pregnancy is detected, discontinue quinapril as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}]', '**Angioedema:** Head and neck angioedema, including fatal airway obstruction, can occur. Intestinal angioedema has also been reported. Black patients have a higher incidence of ACE inhibitor-associated angioedema.
INSERT INTO "drug_generic" VALUES(946, 'Follitropin Beta', 'Follitropin Beta', 'G03GA06', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Ovarian Hyperstimulation Syndrome (OHSS)", "severity": "High", "trigger_condition": "Excessive ovarian response during ovulation induction or ART", "message": "STOP: Severe OHSS is a potentially life-threatening medical event characterized by massive ovarian enlargement, ascites, pleural effusion, and thromboembolism. Monitor ovarian response closely via ultrasound and serum estradiol."}, {"alert_type": "Thromboembolic Events", "severity": "High", "trigger_condition": "Patients with personal or family history of thromboembolic disorders", "message": "WARNING: Serious thromboembolic events, both in association with and separate from OHSS, have been reported. Use with extreme caution in patients with recognized risk factors."}]', '**Ovarian Hyperstimulation Syndrome (OHSS):** A severe, potentially life-threatening condition characterized by ovarian enlargement, ascites, hydrothorax, and weight gain. Monitor follicular development via transvaginal ultrasound and serum estradiol levels. Withhold hCG if ovaries are abnormally enlarged or estradiol levels are excessively high.
INSERT INTO "drug_generic" VALUES(947, 'Cetirizine', 'Cetirizine', 'R06AE07', 0, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "CNS Depression", "severity": "Moderate", "trigger_condition": "Concurrent use with alcohol or other CNS depressants", "message": "Avoid concurrent use with alcohol, sedatives, or tranquilizers due to an additive risk of central nervous system depression and somnolence."}]', '**CNS Depression:** May cause somnolence and impair mental alertness. Patients should exercise caution when driving, operating heavy machinery, or performing tasks requiring mental alertness until they are accustomed to the medication''s effects.
INSERT INTO "drug_generic" VALUES(948, 'Dextrose 5% + Sodium Chloride 0.18%', 'Dextrose 5% and Sodium Chloride 0.18%', 'B05BB02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Fluid and Solute Overload", "severity": "Moderate", "trigger_condition": "Administration in patients with congestive heart failure or severe renal insufficiency", "message": "Caution: Can cause significant fluid overload, pulmonary edema, and electrolyte disturbances. Monitor fluid balance and electrolytes closely."}]', '**Fluid and Electrolyte Overload:** Administration can cause fluid and/or solute overload resulting in dilution of serum electrolyte concentrations, overhydration, congested states, or pulmonary edema. Use with caution in patients with congestive heart failure or severe renal insufficiency.
INSERT INTO "drug_generic" VALUES(949, 'Chloral Hydrate', 'Chloral Hydrate', 'N05CC01', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Fatal Arrhythmias and Respiratory Depression", "severity": "High", "trigger_condition": "Overdose or use in patients with severe cardiac disease", "message": "STOP: Chloral hydrate has a narrow therapeutic index. Overdose or use in susceptible patients can cause fatal cardiac arrhythmias and profound respiratory depression."}]', '- **Duration of Therapy:** Use is not recommended for more than 2 weeks due to the rapid development of tolerance and risk of dependence.
INSERT INTO "drug_generic" VALUES(950, 'Plazomicin', 'Plazomicin', 'J01GB14', 1, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Nephrotoxicity and Ototoxicity", "severity": "High", "trigger_condition": "Pre-existing renal impairment or concurrent use of neurotoxic/nephrotoxic drugs", "message": "Aminoglycosides can cause severe nephrotoxicity and irreversible ototoxicity. Monitor renal function daily and assess auditory function if symptoms arise."}]', '**Nephrotoxicity:** Nephrotoxicity has been reported, with most serum creatinine increases being ≥1 mg/dL above baseline and generally reversible. Assess creatinine clearance in all patients prior to initiating therapy and daily during therapy. Adjust the dose in patients with renal impairment.
INSERT INTO "drug_generic" VALUES(951, 'Glimepiride', 'Glimepiride', 'A10BB12', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hypoglycemia Risk", "severity": "High", "trigger_condition": "Use in elderly, malnourished, or renally impaired patients", "message": "Severe hypoglycemia can occur. Proper patient selection, dosage, and instructions are critical. Initiate at 1 mg daily in patients at increased risk (elderly, renal impairment) and titrate cautiously."}]', 'All sulfonylureas are capable of producing severe hypoglycemia. The risk is increased in elderly, debilitated, or malnourished patients, and those with adrenal, pituitary, renal, or hepatic insufficiency. Monitor blood glucose concentrations regularly. Epidemiological studies have suggested an increased risk of cardiovascular mortality with sulfonylureas compared to treatment with diet alone or diet plus insulin, though this remains controversial. Cases of syndrome of inappropriate antidiuretic hormone secretion (SIADH) and hyponatremia have been reported, particularly in patients with congestive heart failure or hepatic cirrhosis. Caution is advised in patients with G6PD deficiency due to the risk of hemolytic anemia.', '- **Type 2 Diabetes Mellitus:** Indicated as an adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus.
INSERT INTO "drug_generic" VALUES(952, 'Esomeprazole Sodium Injection', 'Esomeprazole Sodium Injection', 'A02BC05', 0, 0, 0, 0, 0, 0, 1, 1, '[]', '**Gastric Malignancy:** Symptomatic response to therapy does not preclude the presence of gastric malignancy; evaluate for malignancy if symptoms persist.
INSERT INTO "drug_generic" VALUES(953, 'Sodium Chloride 0.9% IV prep', 'Sodium Chloride 0.9% Injection', 'B05BB01', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Fluid Overload Risk", "severity": "High", "trigger_condition": "Rapid infusion in patients with heart failure or severe renal impairment", "message": "STOP: Rapid or excessive intravenous administration can cause severe fluid overload, leading to pulmonary edema and exacerbation of congestive heart failure."}]', 'Use with caution in patients with hypertension, congestive heart failure, peripheral or pulmonary edema, impaired renal function, liver cirrhosis, and preeclampsia. Maintain adequate water intake. Monitor fluid balance, serum electrolytes (especially sodium and chloride), and acid-base balance regularly, especially during prolonged treatment. Caution is advised when used in patients who are receiving corticosteroids or corticotropin, as these agents promote sodium retention. Hypertonic solutions (e.g., 3% or 5% sodium chloride) should be given via a large vein at a rate not exceeding 100 mL/hr to avoid osmotic demyelination syndrome.', '- **Fluid and Electrolyte Replenishment:** Indicated for the treatment of isotonic extracellular dehydration, excessive sweating, and water and electrolyte imbalance.
INSERT INTO "drug_generic" VALUES(954, 'Multivitamin [water soluble] + 5', 'Water-Soluble Multivitamin Injection', 'A11EB', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "Moderate", "trigger_condition": "Intravenous administration", "message": "Allergic reactions, including anaphylaxis, may occur in patients hypersensitive to any component of the preparation (e.g., thiamine). Monitor patients during infusion."}]', '**Light Protection:** When the lyophilized powder is diluted with water-based solutions, the admixture should be protected from light to prevent vitamin degradation. This is not necessary if diluted with a fat emulsion, which provides a protective effect.
INSERT INTO "drug_generic" VALUES(955, 'Refined Soyabean Oil + Purified Egg Lecithin + Glycerol', 'Intravenous Fat Emulsion (Soybean Oil, Egg Lecithin, Glycerin)', 'B05BA02', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fat Overload Syndrome", "severity": "High", "trigger_condition": "Rapid infusion or impaired fat metabolism", "message": "STOP: Monitor serum triglycerides closely. Rapid infusion or use in patients with impaired fat metabolism can lead to Fat Overload Syndrome, characterized by hyperlipidemia, fever, hepatosplenomegaly, coagulopathy, and coma."}]', '**Impaired Fat Metabolism:** Use with extreme caution in patients with conditions that disturb fat metabolism, such as severe renal insufficiency, uncompensated diabetes mellitus, pancreatitis, liver insufficiency, metabolic disorders, and sepsis. Monitor serum triglycerides daily.
INSERT INTO "drug_generic" VALUES(956, 'Diclofenac Potassium', 'Diclofenac Potassium', 'M01AB05', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal bleeding, ulceration, and perforation. Contraindicated for CABG perioperative pain."}]', '**Cardiovascular Risk:** May lead to new-onset hypertension or worsening of pre-existing hypertension. Use with caution in patients with heart failure or fluid retention.
INSERT INTO "drug_generic" VALUES(957, 'Lumacaftor + Ivacaftor', 'Lumacaftor and Ivacaftor', 'R07AX30', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hepatic Decompensation", "severity": "High", "trigger_condition": "Pre-existing advanced liver disease or cirrhosis", "message": "STOP: Worsening liver function, including hepatic encephalopathy and fatal liver failure, has been reported in patients with pre-existing cirrhosis and portal hypertension. Monitor liver function closely."}]', '- **Hepatic Decompensation:** Liver failure leading to death has been reported in patients with pre-existing cirrhosis. Use with extreme caution in advanced liver disease.
INSERT INTO "drug_generic" VALUES(958, 'Pitavastatin', 'Pitavastatin', 'C10AA08', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis Risk", "severity": "High", "trigger_condition": "Concomitant use with Cyclosporine, Gemfibrozil, or severe renal impairment", "message": "STOP: Increased risk of severe myopathy and rhabdomyolysis leading to acute renal failure. Co-administration with cyclosporine is strictly contraindicated."}]', '**Myopathy and Rhabdomyolysis:** Pitavastatin can cause skeletal muscle effects, including myopathy and rhabdomyolysis, which may lead to acute renal failure secondary to myoglobinuria. Risk increases with higher doses, advanced age (>65), renal impairment, and concomitant use of certain drugs (e.g., fibrates, erythromycin).
INSERT INTO "drug_generic" VALUES(959, 'Rosuvastatin + Ezetimibe', 'Rosuvastatin and Ezetimibe', 'C10BA06', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Unexplained muscle pain, tenderness, or weakness", "message": "STOP: Risk of severe myopathy and rhabdomyolysis. Discontinue immediately if markedly elevated CK levels occur or if myopathy is diagnosed or suspected."}]', 'Risk factors for myopathy and rhabdomyolysis include age ≥65 years, uncontrolled hypothyroidism, renal impairment, and concomitant use of interacting drugs. Asian patients may be at a higher risk for myopathy; consider lower starting doses.
INSERT INTO "drug_generic" VALUES(960, 'Bretylium', 'Bretylium tosylate', 'C01BD02', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Profound Hypotension", "severity": "High", "trigger_condition": "Administration of drug", "message": "STOP: Bretylium regularly causes profound postural hypotension. Patients must be kept in a supine position. Monitor blood pressure continuously."}]', '**Profound Hypotension:** Administration regularly results in postural hypotension, recognized by dizziness, vertigo, or faintness. Some degree of hypotension is present in ~50% of patients while supine. Keep patients in a supine position until tolerance develops. If supine systolic pressure falls below 75 mm Hg, dopamine or norepinephrine infusion may be used.
INSERT INTO "drug_generic" VALUES(961, 'Netarsudil + Latanoprost eye prep', 'Netarsudil and Latanoprost ophthalmic solution', 'S01EE51', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '**Pigmentation Changes:** Latanoprost can cause permanent changes to pigmented tissues, including increased brown pigmentation of the iris, periorbital tissue (eyelid), and eyelashes. Inform patients of this possibility before initiating treatment.
INSERT INTO "drug_generic" VALUES(962, 'Midostaurin', 'Midostaurin', 'L01EX10', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Pulmonary Toxicity", "severity": "High", "trigger_condition": "New or worsening pulmonary symptoms", "message": "STOP: Cases of interstitial lung disease (ILD) and pneumonitis, some fatal, have been reported. Monitor for pulmonary symptoms and discontinue if ILD/pneumonitis occurs without an infectious etiology."}]', '**Pulmonary Toxicity:** Interstitial lung disease (ILD) and pneumonitis, sometimes fatal, have occurred. Monitor patients for pulmonary symptoms (e.g., cough, dyspnea, hypoxia). Discontinue midostaurin if signs or symptoms of ILD or pneumonitis occur without an infectious etiology.
INSERT INTO "drug_generic" VALUES(963, 'Tedizolid Phosphate', 'Tedizolid Phosphate', 'J01XX11', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Clostridioides difficile-Associated Diarrhea (CDAD)", "severity": "High", "trigger_condition": "Development of severe diarrhea during or after treatment", "message": "STOP: CDAD has been reported with nearly all systemic antibacterial agents. Evaluate immediately if diarrhea occurs. Discontinue tedizolid if CDAD is suspected or confirmed."}]', '**Neutropenia:** Monitor for neutropenia (neutrophil counts <1,000 cells/mm³). The safety and efficacy of tedizolid in patients with neutropenia have not been adequately evaluated. In an animal model of infection, antibacterial activity was reduced in the absence of granulocytes. Consider alternative therapies in neutropenic patients.
INSERT INTO "drug_generic" VALUES(964, 'Tafamidis meglumine', 'Tafamidis meglumine', 'N07XX08', 0, 0, 0, 0, 0, 0, 0, 0, '[]', '**Embryo-Fetal Toxicity:** Based on animal studies, tafamidis may cause fetal harm. Consider pregnancy planning and prevention for females of reproductive potential.', '- **Transthyretin Amyloid Cardiomyopathy (ATTR-CM):** Indicated for the treatment of the cardiomyopathy of wild-type or hereditary transthyretin-mediated amyloidosis in adults to reduce cardiovascular mortality and cardiovascular-related hospitalization.', '- **Hypersensitivity:** Contraindicated in patients with known hypersensitivity to tafamidis or any of its excipients. Rationale: Risk of allergic reactions.', '**General Note:** In clinical trials, the frequency of adverse events in patients treated with tafamidis was generally similar to placebo. No specific adverse reactions occurred at a significantly higher rate (>10%) than placebo that were directly attributable to the drug.', 'C', '**Pregnancy Risk:** Based on animal studies, fetal harm may occur. Limited human data have not identified drug-associated risks, but animal studies showed embryofetal mortality and malformations at exposures 9 times the human exposure.
INSERT INTO "drug_generic" VALUES(965, 'Amlodipine + Olmesartan Medoxomil', 'Amlodipine and Olmesartan', 'C09DB02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected during therapy", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue amlodipine/olmesartan as soon as possible when pregnancy is detected."}]', '**Sprue-like Enteropathy:** Severe, chronic diarrhea with substantial weight loss has been reported with olmesartan, sometimes months to years after starting therapy. Intestinal biopsy may show villous atrophy. Discontinue if no other etiology is found; symptoms usually resolve upon discontinuation.
INSERT INTO "drug_generic" VALUES(966, 'Ceftazidime + Avibactam', 'Ceftazidime and Avibactam', 'J01DD52', 1, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}]', '**Renal Function Monitoring:** Decreased efficacy has been observed in adult patients with complicated intra-abdominal infections (cIAI) who have a baseline creatinine clearance (CrCl) of 30 to 50 mL/min. Monitor CrCl at least daily in adult and pediatric patients with changing renal function and adjust the intravenous infusion dose accordingly.
INSERT INTO "drug_generic" VALUES(967, 'Ethyl Chloride', 'Ethyl Chloride', 'N01AB01', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Flammability and Inhalation Toxicity", "severity": "High", "trigger_condition": "Use near open flames, electrocautery, or in poorly ventilated areas", "message": "STOP: Ethyl chloride is highly flammable and explosive. Do not use near open flames or electrical cautery equipment. Avoid inhalation, as it can cause severe central nervous system depression, cardiac arrhythmias, and hepatotoxicity."}]', '**Tissue Damage:** Prolonged continuous spraying can cause frostbite, tissue necrosis, and sloughing. Limit application time strictly to the recommended duration (usually 3 to 7 seconds).
INSERT INTO "drug_generic" VALUES(968, 'Sodium Nitroprusside Dihydrate', 'Sodium Nitroprusside', 'C02DD01', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Severe Hypotension and Toxicity", "severity": "High", "trigger_condition": "Rapid infusion or prolonged use without monitoring", "message": "STOP: Can cause precipitous decreases in blood pressure leading to irreversible ischemic injuries or death. Continuous blood pressure monitoring is mandatory. Prolonged use or high doses can cause fatal cyanide or thiocyanate toxicity."}]', '- **Cyanide and Thiocyanate Toxicity:** Metabolism releases cyanide, which is converted to thiocyanate. Risk of toxicity increases with doses >2 mcg/kg/min, prolonged use (>3 days), or in renal/hepatic impairment. Monitor acid-base balance (metabolic acidosis is an early sign of cyanide toxicity) and venous oxygen concentration.
INSERT INTO "drug_generic" VALUES(969, 'Flutamide', 'Flutamide', 'L02BB01', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Initiation of therapy and routine monitoring", "message": "STOP: Severe and potentially fatal hepatic injury, including acute liver failure requiring hospitalization or liver transplantation, has been reported. Measure serum transaminases prior to starting treatment and regularly thereafter."}]', '- **Hepatic Injury:** Perform liver function tests before starting treatment, monthly for the first 4 months, and periodically thereafter. Treatment is not recommended in patients whose ALT values exceed twice the upper limit of normal. Discontinue if jaundice develops or if ALT rises >2 times the upper limit of normal.
INSERT INTO "drug_generic" VALUES(970, 'Caplacizumab', 'Caplacizumab-yhdp', 'B01AX07', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Hemorrhage", "severity": "High", "trigger_condition": "Concomitant use of anticoagulants or antiplatelet agents, or underlying coagulopathy", "message": "STOP: Serious and potentially fatal bleeding can occur. Interrupt treatment if clinically significant bleeding occurs. Withhold 7 days prior to elective surgery or invasive procedures."}]', '**Hemorrhage:** Serious and fatal bleeding can occur. The risk is significantly increased in patients with underlying coagulopathies or those taking concomitant antiplatelet agents or anticoagulants. Monitor closely for signs of bleeding. If clinically significant bleeding occurs, interrupt treatment.
INSERT INTO "drug_generic" VALUES(971, 'Naftifine Topical', 'Naftifine', 'D01AE22', 0, 0, 1, 0, 0, 1, 1, 0, '[]', '**Mucous Membrane Exposure:** Avoid contact with the eyes, nose, mouth, and other mucous membranes. For external use only.
INSERT INTO "drug_generic" VALUES(972, 'Isoniazid + Thiacetazone', 'Isoniazid and Thioacetazone', 'J04AM03', 1, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fatal Cutaneous Reactions in HIV", "severity": "High", "trigger_condition": "Patient is HIV positive", "message": "STOP: Thiacetazone is associated with a high incidence of severe and fatal cutaneous hypersensitivity reactions (Stevens-Johnson syndrome, Toxic Epidermal Necrolysis), particularly in HIV-infected individuals. It is contraindicated in HIV-positive patients."}]', '**Severe Cutaneous Adverse Reactions (SCARs):** Thiacetazone can cause life-threatening skin reactions, including Stevens-Johnson syndrome (SJS) and Toxic Epidermal Necrolysis (TEN). Discontinue immediately at the first sign of a skin rash or mucosal involvement.
INSERT INTO "drug_generic" VALUES(973, 'Betamethasone 0.05% + Clotrimazole 1% Topical', 'Betamethasone and Clotrimazole', 'D01AC20', 0, 0, 1, 1, 0, 1, 0, 1, '[{"alert_type": "HPA Axis Suppression", "severity": "High", "trigger_condition": "Prolonged use, use over large surface areas, or use under occlusion", "message": "STOP: Betamethasone dipropionate is a potent corticosteroid. Systemic absorption can produce reversible HPA axis suppression and Cushing''s syndrome. Do not use for longer than 2-4 weeks."}, {"alert_type": "Diaper Dermatitis Warning", "severity": "High", "trigger_condition": "Use in infants for diaper rash", "message": "STOP: The use of this combination in the treatment of diaper dermatitis is NOT recommended. Diapers act as occlusive dressings, massively increasing systemic steroid absorption and toxicity."}]', '**Skin Atrophy:** Prolonged use can cause severe skin atrophy, striae, and telangiectasia. Avoid use on the face, axillae, and groin if possible, as these areas are highly susceptible to steroid-induced damage.
INSERT INTO "drug_generic" VALUES(974, 'Clopidogrel', 'Clopidogrel', 'B01AC04', 0, 1, 1, 0, 0, 1, 0, 0, '[{"alert_type": "Diminished Antiplatelet Effect in CYP2C19 Poor Metabolizers", "severity": "High", "trigger_condition": "Patients identified as CYP2C19 poor metabolizers", "message": "WARNING: Clopidogrel is a prodrug requiring activation by CYP2C19. Poor metabolizers exhibit higher cardiovascular event rates following ACS or PCI. Consider alternative P2Y12 inhibitors (e.g., prasugrel, ticagrelor) in these patients."}]', '**Bleeding Risk:** Clopidogrel increases the risk of bleeding, which can be fatal. Risk is increased with concomitant use of NSAIDs, warfarin, SSRIs, or SNRIs. Discontinue 5 days prior to elective surgery that has a major risk of bleeding.
INSERT INTO "drug_generic" VALUES(975, 'Dolutegravir', 'Dolutegravir', 'J05AJ03', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Development of severe rash with systemic symptoms", "message": "STOP: Hypersensitivity reactions have been reported and were characterized by rash, constitutional findings, and sometimes organ dysfunction, including liver injury. Discontinue immediately if signs occur."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Underlying Hepatitis B or C co-infection", "message": "Caution: Hepatic adverse events have been reported in patients receiving dolutegravir-containing regimens. Patients with underlying hepatitis B or C may be at increased risk. Monitor liver function tests."}]', '**Hepatotoxicity:** Hepatic toxicity, including elevated serum liver biochemistries, hepatitis, and acute liver failure, has been reported in patients receiving dolutegravir without pre-existing hepatic disease or other identifiable risk factors. Monitor LFTs.
INSERT INTO "drug_generic" VALUES(976, 'Chlorpheniramine Maleate', 'Chlorpheniramine', 'R06AB04', 0, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "CNS Depression", "severity": "Moderate", "trigger_condition": "Concurrent use with alcohol or other CNS depressants", "message": "May cause significant CNS depression and somnolence. Avoid concurrent use with alcohol, sedatives, or tranquilizers."}]', '**Anticholinergic Effects:** Use with caution in patients with angle-closure glaucoma, pyloroduodenal obstruction, symptomatic prostatic hypertrophy (BPH), or bladder neck obstruction due to its anticholinergic properties which can exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(977, 'Ibalizumab', 'Ibalizumab-uiyk', 'J05AX23', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Immune Reconstitution Inflammatory Syndrome", "severity": "Moderate", "trigger_condition": "Initiation of therapy in advanced HIV", "message": "Patients whose immune systems respond may develop an inflammatory response to indolent or residual opportunistic infections. Monitor closely during the initial phase of treatment."}]', '**Immune Reconstitution Inflammatory Syndrome (IRIS):** Reported in patients treated with ibalizumab in combination with other antiretroviral therapies. During the initial phase of combination ART, patients whose immune systems respond may develop an inflammatory response to indolent or residual opportunistic infections (e.g., Mycobacterium avium infection, cytomegalovirus, Pneumocystis jirovecii pneumonia, or tuberculosis), which may necessitate further evaluation and treatment.
INSERT INTO "drug_generic" VALUES(978, 'Lubiprostone', 'Lubiprostone', 'A06AX03', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Diarrhea and Syncope", "severity": "High", "trigger_condition": "Patient experiencing severe diarrhea or hypotension", "message": "STOP: Lubiprostone can cause severe diarrhea leading to hypovolemia and syncope. Discontinue therapy if severe diarrhea occurs and rehydrate the patient."}]', '**Severe Diarrhea:** May cause severe diarrhea resulting in hypovolemia and syncope. Do not prescribe to patients with severe diarrhea. Discontinue if severe diarrhea occurs.
INSERT INTO "drug_generic" VALUES(979, 'Teplizumab inj', 'Teplizumab-mzwv', 'L04AK03', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cytokine Release Syndrome (CRS)", "severity": "High", "trigger_condition": "During the first 5 days of treatment", "message": "STOP: Cytokine Release Syndrome (CRS) can occur, manifesting as fever, nausea, fatigue, and elevated liver enzymes. Premedicate with NSAIDs/acetaminophen, antihistamines, and antiemetics. Monitor closely during and after infusion."}]', '**Cytokine Release Syndrome (CRS):** Observed during treatment through 28 days after the last dose. Manifestations include fever, nausea, fatigue, headache, myalgia, arthralgia, and increased ALT/AST/bilirubin. Typically occurs during the first 5 days. Premedicate and monitor.
INSERT INTO "drug_generic" VALUES(980, 'Ivermectin', 'Ivermectin', 'P02CF01', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Fatal Encephalopathy Risk", "severity": "High", "trigger_condition": "Patients co-infected with Loa loa", "message": "STOP: Rare, potentially fatal encephalopathy has occurred in patients with heavy Loa loa infection treated with ivermectin. Pre-treatment screening for Loa loa is recommended in endemic areas."}, {"alert_type": "Mazzotti Reaction", "severity": "High", "trigger_condition": "Treatment of Onchocerciasis", "message": "WARNING: Treatment of onchocerciasis may cause a severe inflammatory response (Mazzotti reaction) due to the death of microfilariae, presenting as fever, rash, arthralgia, and lymphadenopathy."}]', '**Blood-Brain Barrier Impairment:** Use with caution in conditions associated with an impaired blood-brain barrier (e.g., meningitis, African trypanosomiasis) due to the potential for increased CNS toxicity.
INSERT INTO "drug_generic" VALUES(981, 'Cefepime', 'Cefepime', 'J01DE01', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Neurotoxicity", "severity": "High", "trigger_condition": "Renal impairment without dose adjustment", "message": "STOP: Severe neurotoxicity (encephalopathy, aphasia, myoclonus, seizures, nonconvulsive status epilepticus, coma) can occur, particularly in patients with renal impairment who do not receive appropriate dose adjustments. Adjust dose based on CrCl."}, {"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(982, 'Dexamethasone + Tobramycin Eye prep', 'Tobramycin and Dexamethasone Ophthalmic', 'S01CA01', 1, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Ocular Infections and Glaucoma", "severity": "High", "trigger_condition": "Prolonged use or presence of viral/fungal eye infections", "message": "STOP: Corticosteroids can mask, activate, or exacerbate ocular infections. Contraindicated in viral (herpes simplex) and fungal eye diseases. Prolonged use may cause elevated intraocular pressure (glaucoma) and cataracts."}]', '**Intraocular Pressure (IOP) Elevation:** Prolonged use may result in ocular hypertension and/or glaucoma, with damage to the optic nerve and defects in visual acuity. IOP should be monitored routinely.
INSERT INTO "drug_generic" VALUES(983, 'Secnidazole', 'Secnidazole', 'P01AB07', 1, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Disulfiram-like Reaction", "severity": "High", "trigger_condition": "Concomitant alcohol consumption", "message": "STOP: Severe disulfiram-like reactions (abdominal cramps, nausea, vomiting, headaches, flushing) can occur. Advise patients to strictly avoid alcohol during therapy and for at least 96 hours after the last dose."}]', '**Alcohol Consumption:** Avoid alcoholic beverages and preparations containing ethanol or propylene glycol during therapy and for at least 96 hours after the dose to prevent disulfiram-like reactions.
INSERT INTO "drug_generic" VALUES(984, 'Pravastatin Sodium', 'Pravastatin', 'C10AA03', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Concomitant use with fibrates, cyclosporine, or in patients with severe renal impairment", "message": "STOP: High risk of severe myopathy and rhabdomyolysis leading to acute renal failure. Monitor CK levels and discontinue if markedly elevated or if myopathy is suspected."}]', '**Myopathy and Rhabdomyolysis:** Risk factors include age ≥65 years, uncontrolled hypothyroidism, renal impairment, concomitant use with certain other drugs (e.g., fibrates, cyclosporine), and higher dosages. Discontinue if markedly elevated CK levels occur or myopathy is diagnosed/suspected. Temporarily discontinue in patients experiencing an acute or serious condition at high risk of developing renal failure secondary to rhabdomyolysis (e.g., sepsis, major surgery, trauma).
INSERT INTO "drug_generic" VALUES(985, 'Amifampridine', 'Amifampridine', 'N07XX05', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Seizure Risk", "severity": "High", "trigger_condition": "History of seizures or concomitant use of drugs that lower seizure threshold", "message": "STOP: Amifampridine can cause seizures. It is contraindicated in patients with a history of seizures. Consider dose reduction or discontinuation if a seizure occurs during treatment."}]', '**Seizures:** Amifampridine can cause seizures in a dose-dependent manner. The risk is increased in patients taking concomitant medications that lower the seizure threshold or those with comorbid conditions predisposing to seizures. Contraindicated in patients with a history of seizures. If a seizure occurs, consider discontinuation or dose reduction.
INSERT INTO "drug_generic" VALUES(986, 'Teriparatide', 'Teriparatide', 'H05AA02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Osteosarcoma Risk", "severity": "High", "trigger_condition": "Use in patients with increased baseline risk for osteosarcoma", "message": "STOP: Teriparatide caused a dose-dependent increase in the incidence of osteosarcoma in rats. Avoid use in patients with an increased baseline risk of osteosarcoma (e.g., Paget''s disease, unexplained elevated alkaline phosphatase, pediatric patients with open epiphyses, or prior skeletal radiation)."}]', '- **Orthostatic Hypotension:** Transient orthostatic hypotension may occur with initial doses. Administer the first few doses where the patient can sit or lie down if symptoms occur.
INSERT INTO "drug_generic" VALUES(987, 'Dextrose 50%', 'Dextrose 50%', 'B05BA03', 0, 1, 1, 1, 1, 0, 1, 1, '[{"alert_type": "Tissue Necrosis and Extravasation", "severity": "High", "trigger_condition": "Peripheral intravenous administration", "message": "STOP: Dextrose 50% is highly hyperosmolar. Extravasation can cause severe tissue necrosis. Ensure patency of the IV line before and during administration. Central line preferred if continuous."}]', '**Tissue Necrosis:** Dextrose 50% is extremely hypertonic. Extravasation can cause severe tissue damage, necrosis, and sloughing. Administer slowly through a large peripheral vein or central line, ensuring absolute IV patency.
INSERT INTO "drug_generic" VALUES(988, 'Minoxidil Topical', 'Minoxidil', 'D11AX01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Systemic Absorption Risk", "severity": "Moderate", "trigger_condition": "Application to damaged scalp or excessive dosing", "message": "STOP: Although rare, systemic absorption of topical minoxidil can occur, leading to cardiovascular effects such as hypotension, tachycardia, and fluid retention. Do not apply to sunburned, abraded, or inflamed scalps."}]', 'Ensure the scalp is normal and healthy before application; do not use on inflamed, infected, or irritated skin.
INSERT INTO "drug_generic" VALUES(989, 'Folinic Acid (Calcium folinate)', 'Leucovorin Calcium', 'V03AF03', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Fatal Route of Administration Error", "severity": "High", "trigger_condition": "Intrathecal or intraventricular administration", "message": "STOP: Folinic acid (leucovorin) is strictly CONTRAINDICATED for intrathecal or intraventricular administration. Administration via these routes is highly neurotoxic and frequently fatal."}]', 'Folinic acid should only be used with 5-fluorouracil or methotrexate under the direct supervision of a clinician experienced in the use of cancer chemotherapeutic agents. Monitor serum methotrexate levels and renal function closely to determine the optimal dose and duration of folinic acid rescue. Delayed methotrexate excretion may require prolonged folinic acid therapy. Monitor CBC, electrolytes, and liver function tests before and regularly during treatment. When used with 5-fluorouracil, monitor for severe gastrointestinal toxicity (stomatitis, diarrhea), which can be fatal. Do not use in undiagnosed megaloblastic anemia, as it may mask vitamin B12 deficiency.', '- **Methotrexate Toxicity Rescue:** To diminish the toxicity and counteract the effects of impaired methotrexate elimination and of inadvertent overdosages of folic acid antagonists.
INSERT INTO "drug_generic" VALUES(990, 'Multivitamin & Multimineral during Pregnancy', 'Prenatal Multivitamins and Minerals', 'A11AA03', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Accidental Overdose Risk", "severity": "High", "trigger_condition": "Accidental ingestion by children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Masking of Pernicious Anemia:** Folic acid in doses above 0.1 mg daily may obscure pernicious anemia; hematological remission can occur while neurological manifestations remain progressive. Rule out vitamin B12 deficiency before initiating high-dose folic acid.
INSERT INTO "drug_generic" VALUES(991, 'Tamsulosin Hydrochloride', 'Tamsulosin', 'G04CA02', 0, 0, 1, 0, 1, 0, 0, 0, '[{"alert_type": "Orthostatic Hypotension", "severity": "High", "trigger_condition": "Initiation of therapy or dose increases", "message": "STOP: Can cause severe orthostatic hypotension and syncope. Advise patients to sit or lie down at the first signs of dizziness or weakness."}, {"alert_type": "Intraoperative Floppy Iris Syndrome (IFIS)", "severity": "Medium", "trigger_condition": "Patients undergoing cataract or glaucoma surgery", "message": "STOP: IFIS has been observed during eye surgery in patients treated with alpha-1 blockers. Inform the ophthalmologist prior to surgery."}]', 'Rule out prostate cancer and other conditions that can cause similar symptoms before initiating therapy for BPH (perform digital rectal exam and PSA testing). Use with caution in patients with a history of orthostatic hypotension or syncope. Caution in patients with severe renal impairment (CrCl <10 mL/min) as these patients have not been adequately studied. Caution in patients with a known sulfonamide allergy, as allergic reactions to tamsulosin have been rarely reported.', '- **Benign Prostatic Hyperplasia (BPH):** Treatment of the signs and symptoms of benign prostatic hyperplasia.
INSERT INTO "drug_generic" VALUES(992, 'Aprepitant', 'Aprepitant', 'A04AD12', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Drug Interactions", "severity": "High", "trigger_condition": "Concomitant use with CYP3A4 substrates", "message": "STOP: Aprepitant is a dose-dependent inhibitor of CYP3A4. Coadministration with pimozide, terfenadine, astemizole, or cisapride is contraindicated due to the risk of life-threatening arrhythmias."}]', '**CYP3A4 Interactions:** Aprepitant is a substrate, moderate inhibitor, and inducer of CYP3A4. Use with caution in patients receiving concomitant medications primarily metabolized through CYP3A4, as their plasma concentrations may be significantly altered.
INSERT INTO "drug_generic" VALUES(993, 'Aluminium Chloride Hexahydrate 20%', 'Aluminum Chloride Hexahydrate', 'D11AA01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Low", "message": "For external use only. Do not apply to broken, irritated, or recently shaved skin. Avoid contact with eyes."}]', '**Skin Irritation:** Local irritation, burning, and stinging are common. Risk increases with higher concentrations and application to wet skin. Ensure the skin is completely dry before application.
INSERT INTO "drug_generic" VALUES(994, 'Activated Charcoal', 'Activated Charcoal', 'A07BA01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Aspiration Risk", "severity": "High", "trigger_condition": "Patient with altered mental status or unprotected airway", "message": "STOP: Do not administer to patients with a depressed level of consciousness unless the airway is protected by intubation. Aspiration of charcoal can cause severe, fatal pneumonitis."}]', '**Aspiration Pneumonitis:** Aspiration of activated charcoal can cause severe respiratory compromise and fatal pneumonitis. Ensure the patient has an intact gag reflex or a protected airway before administration.
INSERT INTO "drug_generic" VALUES(995, 'Trifluridine 1% Eye prep', 'Trifluridine Ophthalmic', 'S01AD02', 0, 0, 0, 0, 0, 1, 1, 0, '[]', 'Use under the close supervision of an ophthalmologist. Continuous administration for more than 21 days should be avoided due to the high risk of ocular toxicity (e.g., corneal epithelial dysplasia, stromal edema). If there is no improvement after 7 days of treatment, or complete re-epithelialization has not occurred after 14 days, consider alternative therapies. Do not prescribe for prophylaxis of herpes simplex virus (HSV) keratitis.', '- **Herpes Simplex Keratoconjunctivitis**: Treatment of primary keratoconjunctivitis and recurrent epithelial keratitis caused by herpes simplex virus (HSV) types 1 and 2.', '- **Hypersensitivity**: Contraindicated in patients who develop hypersensitivity reactions or chemical intolerance to trifluridine.', '- **Local Ocular Reactions**: Transient burning or stinging upon instillation (most common).
INSERT INTO "drug_generic" VALUES(996, 'Drospirenone', 'Drospirenone', 'G03AC10', 0, 0, 0, 1, 1, 0, 1, 0, '[{"alert_type": "Hyperkalemia Risk", "severity": "High", "trigger_condition": "Renal impairment, hepatic impairment, or concomitant use of potassium-sparing drugs", "message": "STOP: Drospirenone has anti-mineralocorticoid activity. It is contraindicated in renal or hepatic impairment due to the risk of severe hyperkalemia."}]', '**Hyperkalemia:** Drospirenone has anti-mineralocorticoid activity comparable to a 25 mg dose of spironolactone. Monitor serum potassium in patients at high risk for hyperkalemia (e.g., those taking ACE inhibitors, ARBs, potassium-sparing diuretics, or NSAIDs).
INSERT INTO "drug_generic" VALUES(997, 'Nesiritide', 'Nesiritide', 'C01EB10', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Severe Hypotension", "severity": "High", "trigger_condition": "Administration in patients with low blood pressure or cardiogenic shock", "message": "STOP: Nesiritide can cause severe and prolonged hypotension. It is contraindicated as primary therapy for cardiogenic shock or in patients with a systolic blood pressure <90 mmHg."}]', '**Hypotension:** May cause severe, prolonged hypotension. Monitor blood pressure closely during administration. If hypotension occurs, reduce the dose or stop the infusion and institute supportive measures.
INSERT INTO "drug_generic" VALUES(998, 'Glucarpidase', 'Glucarpidase', 'V03AF09', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Leucovorin Interaction", "severity": "High", "trigger_condition": "Administration of Leucovorin within 2 hours of Glucarpidase", "message": "STOP: Leucovorin is a substrate for glucarpidase. Do not administer leucovorin within 2 hours before or after glucarpidase, as it will be degraded and rendered ineffective."}]', '**Interference with Methotrexate Monitoring:** Glucarpidase converts methotrexate to the inactive metabolite DAMPA. DAMPA interferes with standard immunoassays used to measure methotrexate concentrations, causing falsely elevated readings. Measurement of methotrexate using immunoassays is unreliable for samples collected within 48 hours following glucarpidase administration. Use a chromatographic method (e.g., HPLC) if measurement is required within this window.
INSERT INTO "drug_generic" VALUES(999, 'Multivitamin with L-Lysine', 'Multivitamin with L-Lysine', 'A11AB', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Hypervitaminosis Risk", "severity": "Moderate", "trigger_condition": "Concomitant use of other vitamin supplements", "message": "STOP: Avoid concurrent use of other vitamin A or D containing supplements to prevent fat-soluble vitamin toxicity."}]', '**Hepatic Impairment:** Due to the glycocholic acid content (if present in specific formulations), repeated and prolonged administration in patients with jaundice of hepatic origin or severe biochemical evidence of cholestasis requires careful monitoring of liver function.
INSERT INTO "drug_generic" VALUES(1000, 'Lactic Acid', 'Lactic Acid', 'D02AX', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Moderate", "trigger_condition": "Application to compromised skin", "message": "Do not apply to open, severely abraded, raw, or deeply cut skin. Avoid contact with eyes and mucous membranes (unless specifically formulated for vaginal use)."}]', '**Sun Sensitivity:** As an alpha-hydroxy acid (AHA), it can increase skin sensitivity to the sun and the risk of sunburn. Advise patients to use sunscreen, wear protective clothing, and limit sun exposure while using topical AHA products and for a week afterward.
INSERT INTO "drug_generic" VALUES(1001, 'Streptokinase', 'Streptokinase', 'B01AD01', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Severe Hemorrhage and Anaphylaxis", "severity": "High", "trigger_condition": "Administration in patients with active bleeding, recent surgery, or previous streptokinase exposure", "message": "STOP: Streptokinase carries a high risk of fatal intracranial or internal hemorrhage. It is highly antigenic; do NOT re-administer if the patient has received streptokinase within the past 12 months due to the risk of anaphylaxis and reduced efficacy."}]', 'Use with extreme caution in the elderly, patients with diabetic retinopathy, mitral stenosis with atrial fibrillation (risk of cerebral embolism), or those who have undergone prolonged or traumatic cardiopulmonary resuscitation (CPR). Monitor closely for signs of bleeding, especially at puncture sites; minimize invasive procedures during therapy. Monitor blood pressure frequently, as hypotension is common during infusion. Because streptokinase is derived from streptococci, it is highly antigenic; allergic reactions ranging from fever to anaphylaxis can occur. Do not use if the patient has had a streptococcal infection or received streptokinase within the past 5 days to 12 months, as antistreptokinase antibodies will neutralize the drug and increase the risk of allergic reactions.', '- **Acute Myocardial Infarction (AMI):** Systemic or local administration for the lysis of intracoronary thrombi in patients with acute transmural MI (within 12 hours of symptom onset) with ST-segment elevation or new left bundle-branch block.
INSERT INTO "drug_generic" VALUES(1002, 'Letermovir', 'Letermovir', 'J05AX18', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Drug Interactions", "severity": "High", "trigger_condition": "Concomitant use with pimozide, ergot alkaloids, or specific statins (when combined with cyclosporine)", "message": "STOP: Coadministration with pimozide or ergot alkaloids is contraindicated due to the risk of life-threatening QT prolongation or ergotism. Coadministration with pitavastatin, simvastatin, atorvastatin, or rosuvastatin is contraindicated if the patient is also receiving cyclosporine due to a significantly increased risk of myopathy and rhabdomyolysis."}]', 'Monitor cytomegalovirus (CMV) DNA levels regularly during and after prophylaxis to detect breakthrough infection or reactivation. Exercise extreme caution when coadministering with medicinal products that are CYP3A substrates with narrow therapeutic indices (e.g., alfentanil, fentanyl, quinidine), as letermovir is a moderate CYP3A inhibitor and can significantly increase their plasma concentrations. Monitor therapeutic drug levels closely when used concurrently with immunosuppressants such as cyclosporine, tacrolimus, and sirolimus, adjusting doses as necessary. Caution is advised when coadministered with voriconazole, phenytoin, dabigatran, or OATP1B1/3 substrates (e.g., statins) due to potential pharmacokinetic alterations. Formulations may contain lactose; avoid use in patients with rare hereditary problems of galactose intolerance, total lactase deficiency, or glucose-galactose malabsorption. May exert a minor influence on the ability to drive or operate heavy machinery due to potential fatigue or dizziness. Not recommended for use in women of childbearing potential who are not utilizing effective contraception.', '- Prophylaxis of cytomegalovirus (CMV) infection and disease in adult CMV-seropositive recipients [R+] of an allogeneic hematopoietic stem cell transplant (HSCT).', '- **Hypersensitivity:** Contraindicated in patients with a known severe hypersensitivity reaction to letermovir or any of its excipients, due to the risk of anaphylaxis.
INSERT INTO "drug_generic" VALUES(1003, 'Potassium Citrate', 'Potassium Citrate', 'A12BA02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hyperkalemia Risk", "severity": "High", "trigger_condition": "Renal impairment or concomitant use of potassium-sparing agents", "message": "STOP: Can cause fatal hyperkalemia. Contraindicated in patients with renal insufficiency (GFR < 0.7 ml/kg/min) or those taking potassium-sparing diuretics."}, {"alert_type": "Gastrointestinal Lesions", "severity": "High", "trigger_condition": "Delayed gastric emptying or solid oral dosage forms", "message": "STOP: Solid potassium dosage forms can cause severe GI ulceration, bleeding, or perforation. Discontinue immediately if severe abdominal pain or vomiting occurs."}]', '**Hyperkalemia:** May cause hyperkalemia, which can lead to fatal cardiac arrhythmias. Monitor serum potassium regularly.
INSERT INTO "drug_generic" VALUES(1004, 'Peginterferon Alfa-2a', 'Peginterferon Alfa-2a', 'L03AB11', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Neuropsychiatric, Autoimmune, Ischemic, and Infectious Disorders", "severity": "High", "trigger_condition": "Initiation of therapy or presence of underlying psychiatric/autoimmune conditions", "message": "STOP: Alpha interferons may cause or aggravate fatal or life-threatening neuropsychiatric, autoimmune, ischemic, and infectious disorders. Monitor closely and discontinue if symptoms are persistently severe or worsening."}]', '- **Neuropsychiatric Disorders:** Severe depression, suicidal ideation, and aggressive behavior can occur. Discontinue treatment if psychiatric symptoms worsen or become severe.
INSERT INTO "drug_generic" VALUES(1005, 'Tofacitinib', 'Tofacitinib', 'L04AA29', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Serious Infections", "severity": "High", "trigger_condition": "Active infection or history of recurrent infections", "message": "STOP: Increased risk of serious, potentially fatal infections (e.g., tuberculosis, invasive fungal, viral, and opportunistic infections). Do not initiate during an active infection."}, {"alert_type": "Thrombosis Risk", "severity": "High", "trigger_condition": "Patients with cardiovascular risk factors", "message": "WARNING: Increased risk of deep vein thrombosis (DVT), pulmonary embolism (PE), and arterial thrombosis. Use with caution in patients at increased risk for thrombosis."}]', '**Serious Infections:** Patients are at increased risk for developing serious infections that may lead to hospitalization or death, including tuberculosis (TB), invasive fungal infections, and opportunistic infections. Evaluate and test for latent TB prior to initiation and monitor during treatment.
INSERT INTO "drug_generic" VALUES(1006, 'Povidone Iodine 5% Topical', 'Povidone-Iodine Topical', 'D08AG02', 1, 0, 0, 0, 1, 1, 0, 0, '[]', 'Application to large areas of denuded skin or severe burns may produce systemic adverse effects such as metabolic acidosis, hypernatremia, and impairment of renal function due to significant iodine absorption. Exercise special caution in patients with pre-existing renal insufficiency. Avoid contact with eyes.', '- **Skin Infections:** Treatment of primary or secondary topical infections, infected surgical incisions, infected decubitus or stasis ulcers, pyodermas, and secondarily infected dermatoses.
INSERT INTO "drug_generic" VALUES(1007, 'Sodium picosulfate', 'Sodium picosulfate', 'A06AB08', 0, 0, 0, 1, 1, 1, 1, 0, '[{"alert_type": "Electrolyte Imbalance", "severity": "High", "trigger_condition": "Use in patients with dehydration or concurrent use of diuretics", "message": "STOP: Sodium picosulfate can cause severe dehydration and electrolyte disturbances (e.g., hypokalemia, hyponatremia). Ensure adequate hydration and monitor electrolytes in at-risk patients."}]', 'Use with caution in the elderly, debilitated patients, and those with mild to moderate renal impairment due to the risk of severe fluid and electrolyte shifts. Ensure adequate oral hydration during treatment. Prolonged or excessive use can lead to laxative dependence, chronic diarrhea, and severe hypokalemia. Caution is advised in patients taking medications that affect electrolyte balance (e.g., diuretics, corticosteroids).', '- **Constipation:** Indicated for the short-term relief of occasional constipation.
INSERT INTO "drug_generic" VALUES(1008, 'Colistin (Colistimethate Sodium)', 'Colistimethate Sodium', 'J01XB01', 1, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Nephrotoxicity and Neurotoxicity", "severity": "High", "trigger_condition": "Administration of parenteral colistimethate sodium", "message": "STOP: Dose-dependent nephrotoxicity and neurotoxicity (including respiratory arrest) can occur. Do not exceed 5 mg/kg/day in patients with normal renal function. Adjust dose strictly in renal impairment."}]', '**Nephrotoxicity:** Dose-dependent nephrotoxicity (e.g., decreased urine output, increased BUN/creatinine, acute tubular necrosis) is a major risk. Monitor serum creatinine and BUN regularly. Discontinue or adjust dose if renal function declines.
INSERT INTO "drug_generic" VALUES(1009, 'Iodoquinol', 'Iodoquinol', 'P01AA05', 1, 0, 0, 0, 0, 0, 1, 0, '[]', 'Use with caution in patients with thyroid disease, as iodoquinol contains a significant amount of iodine and can interfere with thyroid function tests for up to 6 months after discontinuation. It is a luminal amebicide and is not effective for the treatment of extraintestinal amebiasis (e.g., amebic hepatitis or liver abscess); systemic therapy must be used concurrently for invasive disease. Avoid long-term therapy or exceeding the recommended dose, as this is strongly associated with severe neurotoxicity, including optic neuritis, optic atrophy, and peripheral neuropathy. Do not repeat a treatment course before a resting period of 2 to 3 weeks.', '- **Intestinal Amebiasis:** Indicated for the treatment of acute and chronic intestinal amebiasis caused by *Entamoeba histolytica*. It is primarily used to eradicate asymptomatic cyst passers or as an adjunct to systemic amebicides (like metronidazole) to eliminate surviving luminal cysts.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to 8-hydroxyquinolines, iodoquinol, or iodine preparations. Rationale: Risk of severe allergic reactions.
INSERT INTO "drug_generic" VALUES(1010, 'Cepalin + Hyaluronic Acid + Centella Asiatica extract topical', 'Allium cepa extract / Hyaluronic Acid / Centella Asiatica extract', 'D03AX', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Application Site Reactions:** Not for use on deep or puncture wounds, damaged or broken skin, animal bites, or serious burns. Apply only to intact skin.
INSERT INTO "drug_generic" VALUES(1011, 'Famotidine', 'Famotidine', 'A02BA03', 0, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "CNS Adverse Effects in Renal Impairment", "severity": "Moderate", "trigger_condition": "Patients with moderate to severe renal impairment (CrCl < 50 mL/min)", "message": "Caution: CNS adverse reactions, including confusion, delirium, hallucinations, and seizures, have been reported in patients with moderate to severe renal impairment. Dosage adjustment is required."}]', '**Renal Impairment:** CNS adverse effects (e.g., confusion, hallucinations, seizures) and prolonged QT intervals have been reported in patients with moderate to severe renal impairment; dosage adjustment is required.
INSERT INTO "drug_generic" VALUES(1012, 'Halcinonide 0.1% Topical', 'Halcinonide', 'D07CC03', 0, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "HPA Axis Suppression", "severity": "High", "trigger_condition": "Prolonged use, application to large surface areas, or use under occlusive dressings", "message": "STOP: Halcinonide is a high-potency topical corticosteroid. Systemic absorption can cause reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, and hyperglycemia. Limit duration of use."}]', '**Endocrine Effects:** Systemic absorption can produce reversible HPA axis suppression. Evaluate patients periodically for evidence of suppression using urinary free cortisol and ACTH stimulation tests, especially if applying to large areas or using occlusive dressings. If suppression is noted, withdraw the drug gradually, reduce frequency, or substitute a less potent steroid.
INSERT INTO "drug_generic" VALUES(1013, 'Frusemide + Spironolactone', 'Furosemide + Spironolactone', 'C03EB01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Electrolyte Imbalance", "severity": "High", "trigger_condition": "Concomitant use with ACE inhibitors or pre-existing renal impairment", "message": "STOP: Severe and potentially fatal hyperkalemia can occur. Monitor serum potassium and renal function closely."}]', 'Monitor fluid status and serum electrolytes (especially potassium and sodium) regularly to prevent dilutional hyponatremia, hypovolemia, or hyperkalemia.
INSERT INTO "drug_generic" VALUES(1014, 'Multivitamin and Multimineral A-Z Silver preparations', 'Multivitamins and Minerals', 'A11AA03', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Iron Toxicity", "severity": "High", "trigger_condition": "Accidental overdose in children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product out of reach of children."}]', '**Renal Impairment:** Use with caution in patients with mild to moderate renal failure. Accumulation of fat-soluble vitamins (A, D) and certain minerals can occur.
INSERT INTO "drug_generic" VALUES(1015, 'Lamotrigine', 'Lamotrigine', 'N03AX09', 0, 0, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Serious Skin Reactions", "severity": "High", "trigger_condition": "Rapid dose titration, concurrent valproate use, or pediatric patients", "message": "STOP: Severe, potentially life-threatening skin rashes (including Stevens-Johnson syndrome and toxic epidermal necrolysis) can occur. Discontinue immediately at the first sign of rash unless clearly not drug-related."}]', '**Skin Reactions:** High risk of severe, potentially fatal skin reactions (SJS/TEN), especially with rapid dose escalation, concurrent valproate therapy, or in pediatric patients. Discontinue at the first sign of an unexplained rash.
INSERT INTO "drug_generic" VALUES(1016, 'Rivaroxaban', 'Rivaroxaban', 'B01AF01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Premature Discontinuation and Spinal/Epidural Hematoma", "severity": "High", "trigger_condition": "Premature discontinuation or neuraxial anesthesia", "message": "STOP: Premature discontinuation increases the risk of thrombotic events. Epidural or spinal hematomas, which may result in long-term or permanent paralysis, can occur in patients receiving neuraxial anesthesia or spinal puncture. Consider timing of catheter placement/removal carefully."}]', '**Bleeding Risk:** Increases the risk of bleeding, which can be serious or fatal. Promptly evaluate any signs or symptoms of blood loss. Reversal agent (Andexanet alfa) is available but use is restricted to life-threatening bleeding.
INSERT INTO "drug_generic" VALUES(1017, 'Sulfacetamide topical', 'Sulfacetamide', 'D10AF06', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Patient history of sulfonamide allergy", "message": "STOP: Severe reactions to sulfonamides, including Stevens-Johnson syndrome and toxic epidermal necrolysis, have been reported. Verify patient allergy history before prescribing."}]', 'Avoid contact with eyes or mucous membranes. Severe reactions to sulfonamides, including Stevens-Johnson syndrome, toxic epidermal necrolysis, fulminant hepatic necrosis, agranulocytosis, and aplastic anemia, have been reported (though rare with topical use). Avoid excessive UV exposure. Formulations may contain sodium metabisulfite, which can cause allergic-type reactions, including anaphylaxis, in susceptible individuals.', '- **Acne Vulgaris:** Indicated for the topical treatment of acne vulgaris.
INSERT INTO "drug_generic" VALUES(1018, 'Anti Recurrence Emollient Balm', 'Emollient Balm', 'D02AX', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**External Use Only:** Avoid contact with eyes and mucous membranes. If contact occurs, rinse thoroughly with water.
INSERT INTO "drug_generic" VALUES(1019, 'Silver Sulphadiazine 1% Topical', 'Silver Sulfadiazine', 'D06BA01', 1, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Kernicterus Risk", "severity": "High", "trigger_condition": "Use in pregnant women at term, premature infants, or neonates under 2 months of age", "message": "STOP: Contraindicated in neonates <2 months and pregnant women at term due to the risk of sulfonamide-induced displacement of bilirubin, leading to fatal kernicterus."}]', '**Systemic Absorption:** Significant systemic absorption of sulfadiazine can occur when applied to large burn areas. Use with caution in patients with significant hepatic or renal impairment, as accumulation may occur.
INSERT INTO "drug_generic" VALUES(1020, 'Spironolactone', 'Spironolactone', 'C03DA01', 0, 0, 0, 1, 1, 0, 1, 0, '[{"alert_type": "Hyperkalemia Risk", "severity": "High", "trigger_condition": "Concurrent use with ACE inhibitors, ARBs, potassium supplements, or in patients with renal impairment", "message": "STOP: Spironolactone can cause severe, potentially fatal hyperkalemia. Monitor serum potassium and renal function closely, especially during initiation or dose adjustments."}]', 'Monitor serum electrolytes (especially potassium and sodium), BUN, and creatinine periodically. Risk of hyperkalemia is significantly increased in the elderly, patients with diabetes mellitus, renal impairment, or those taking concurrent ACE inhibitors, ARBs, or NSAIDs. Use with caution in patients with hepatic impairment; minor alterations in fluid and electrolyte balance may precipitate hepatic coma. May cause dizziness and somnolence; advise patients to use caution when driving or operating machinery. Spironolactone has been shown to be a tumorigen in chronic toxicity studies in rats; use only for approved indications.', '- **Heart Failure:** Management of severe heart failure (NYHA Class III-IV) to increase survival and reduce hospitalization.
INSERT INTO "drug_generic" VALUES(1021, 'Ephedrine Hydrochloride 0.5%', 'Ephedrine', 'R01AA03', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Concomitant use with MAOIs or severe hypertension", "message": "STOP: Severe and potentially fatal hypertensive crisis can occur if used concurrently with or within 14 days of discontinuing monoamine oxidase inhibitors (MAOIs)."}]', '**Cardiovascular Disease:** Use with extreme caution in patients with ischemic heart disease, hypertension, or arrhythmias, as sympathomimetic effects can exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1022, 'Ruxolitinib topical', 'Ruxolitinib', 'D11AH09', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Serious Infections", "severity": "High", "trigger_condition": "Development of signs or symptoms of systemic infection", "message": "STOP: Serious bacterial, mycobacterial, fungal, and viral infections have occurred with JAK inhibitors. Monitor patients closely and interrupt treatment if a serious infection develops."}]', '**Serious Infections:** Serious bacterial, mycobacterial, fungal, and viral infections have occurred. Regularly monitor patients for signs of infection and manage promptly. Avoid use in patients with active, serious infections.
INSERT INTO "drug_generic" VALUES(1023, 'Adrenaline (Epinephrine)', 'Epinephrine', 'C01CA24', 0, 1, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Extravasation and Tissue Necrosis", "severity": "High", "trigger_condition": "Intravenous administration or injection into end-arteries", "message": "STOP: Avoid extravasation, which causes severe local necrosis. NEVER inject into end-artery areas (fingers, toes, nose, ears, penis, scrotum)."}, {"alert_type": "Cardiovascular Toxicity", "severity": "High", "trigger_condition": "Administration in patients with underlying heart disease", "message": "STOP: Can induce potentially fatal cardiac arrhythmias, severe hypertension, and pulmonary edema. Monitor ECG and blood pressure continuously during IV use."}]', '**Cardiovascular Effects:** May induce severe hypertension, potentially leading to cerebral hemorrhage. Can precipitate angina, myocardial infarction, and fatal cardiac arrhythmias, especially in patients with underlying coronary artery disease or those taking arrhythmogenic drugs.
INSERT INTO "drug_generic" VALUES(1024, 'Magaldrate', 'Magaldrate', 'A02AD02', 0, 0, 1, 1, 1, 1, 0, 0, '[{"alert_type": "Toxicity in Renal Impairment", "severity": "High", "trigger_condition": "Severe renal impairment (CrCl < 30 mL/min)", "message": "STOP: Magaldrate contains magnesium and aluminum. In patients with severe renal impairment, accumulation can lead to fatal hypermagnesemia and aluminum toxicity. Use is contraindicated."}]', '**Renal Impairment:** Use with extreme caution in patients with mild to moderate renal impairment due to the risk of magnesium and aluminum accumulation.
INSERT INTO "drug_generic" VALUES(1025, 'Penciclovir', 'Penciclovir', 'D06BB06', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Immunocompromised Patients:** Efficacy has not been established in immunocompromised patients (e.g., AIDS patients, bone marrow transplant recipients). Use with caution and monitor for adequate clinical response.
INSERT INTO "drug_generic" VALUES(1026, 'Glycopyrronium bromide (Glycopyrrolate) Inj', 'Glycopyrrolate', 'A03AB02', 0, 0, 0, 0, 1, 1, 1, 0, '[]', '**Renal Impairment:** Glycopyrrolate is primarily eliminated unchanged by the kidneys. Repeated or large doses should be avoided in patients with uremia or severe renal impairment due to prolonged elimination and increased risk of anticholinergic toxicity.
INSERT INTO "drug_generic" VALUES(1027, 'Amitriptyline + Chlordiazepoxide', 'Amitriptyline and Chlordiazepoxide', 'N06CA01', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Concomitant Opioid Use & Suicidality", "severity": "High", "trigger_condition": "Co-prescription with opioids or use in young adults/pediatrics", "message": "STOP: Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death. Additionally, antidepressants increase the risk of suicidal thoughts and behaviors in pediatric and young adult patients. Monitor closely."}]', '- **Opioid Interaction:** Concomitant use with opioids increases the risk of respiratory depression. Limit dosages and durations to the minimum required.
INSERT INTO "drug_generic" VALUES(1028, 'Ranitidine', 'Ranitidine', 'A02BA02', 0, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Market Withdrawal Note", "severity": "High", "trigger_condition": "General prescribing", "message": "NOTE: Ranitidine has been withdrawn from the market in many jurisdictions (including the US FDA) due to the presence of the probable human carcinogen N-nitrosodimethylamine (NDMA). Verify local availability and regulatory status before prescribing."}]', 'The possibility of gastric malignancy should be excluded prior to therapy, as symptomatic relief with ranitidine may mask symptoms and delay the diagnosis of gastric cancer. Use with caution in patients with renal impairment; dosage adjustments are required. Use with caution in patients with hepatic impairment. Use with caution in patients with a history of acute porphyria, as ranitidine may precipitate an attack. Regular monitoring of renal and hepatic function is advised during prolonged therapy.', '- **Benign Gastric and Duodenal Ulceration:** Short-term treatment and maintenance therapy.
INSERT INTO "drug_generic" VALUES(1029, 'Albumin Human 5%', 'Albumin Human', 'B05AA01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Hypervolemia Risk", "severity": "High", "trigger_condition": "Rapid infusion or administration to patients with cardiac failure", "message": "STOP: Rapid infusion or excessive volume can cause severe hypervolemia, leading to acute pulmonary edema and cardiovascular overload. Monitor hemodynamics closely."}]', '**Hypervolemia and Hemodilution:** Use with extreme caution in conditions where hypervolemia could represent a special risk (e.g., decompensated cardiac insufficiency, hypertension, esophageal varices, pulmonary edema, hemorrhagic diathesis, severe anemia, renal and post-renal anuria).
INSERT INTO "drug_generic" VALUES(1030, 'Bacillus Clausii spores', 'Bacillus Clausii spores', 'A07FA', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Systemic Infection Risk", "severity": "High", "trigger_condition": "Use in severely immunocompromised patients", "message": "STOP: Avoid use in severely immunocompromised patients due to the theoretical risk of systemic bacteremia."}]', '**Immunocompromised Patients:** Use with caution in patients with severe immunodeficiency. Although Bacillus clausii is generally non-pathogenic, there is a theoretical risk of bacteremia in severely immunocompromised individuals.
INSERT INTO "drug_generic" VALUES(1031, 'Sipuleucel-T', 'Sipuleucel-T', 'L03AX17', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Acute Infusion Reactions", "severity": "High", "trigger_condition": "During or immediately following intravenous infusion", "message": "STOP: Severe acute infusion reactions can occur. Decrease the infusion rate or stop the infusion if severe reactions develop, and administer appropriate supportive therapy."}]', '**Autologous Use Only:** Intended solely for autologous use. Because of the autologous nature of product preparation, adhering to the personalized leukapheresis and infusion schedules is critical.
INSERT INTO "drug_generic" VALUES(1032, 'Chlorpheniramine + Paracetamol + Phenylephrine', 'Chlorpheniramine + Acetaminophen + Phenylephrine', 'R05X', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity and MAOI Interaction", "severity": "High", "trigger_condition": "Exceeding maximum paracetamol dose or concurrent MAOI use", "message": "STOP: Contains Paracetamol; exceeding the maximum daily dose can cause fatal hepatic necrosis. Contraindicated within 14 days of MAOI therapy due to the risk of hypertensive crisis from Phenylephrine."}]', '**Hepatotoxicity:** Contains paracetamol. Severe liver damage may occur if the patient takes more than the maximum daily limit, consumes 3 or more alcoholic drinks daily, or uses other paracetamol-containing products concurrently.
INSERT INTO "drug_generic" VALUES(1033, 'Isoniazid', 'Isoniazid', 'J04AC01', 1, 0, 0, 1, 1, 0, 1, 0, '[{"alert_type": "Severe Hepatotoxicity", "severity": "High", "trigger_condition": "Routine use, especially in older adults or those consuming alcohol", "message": "STOP: Severe and sometimes fatal hepatitis may occur, even after many months of treatment. Risk increases with age and daily alcohol consumption. Monitor liver function tests closely and discontinue immediately if signs of hepatic damage appear."}]', '**Hepatotoxicity:** Severe and sometimes fatal hepatitis can occur. The risk is age-related (highest in patients >50 years) and increased by daily alcohol consumption, chronic liver disease, and injection drug use. Monitor AST/ALT at baseline and periodically. Instruct patients to report anorexia, nausea, vomiting, dark urine, or jaundice immediately.
INSERT INTO "drug_generic" VALUES(1034, 'Trospium chloride', 'Trospium', 'G04BD09', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Angioedema", "severity": "High", "trigger_condition": "Swelling of the face, lips, tongue, or larynx after administration", "message": "STOP: Angioedema of the face, lips, tongue, and/or larynx has been reported, sometimes after the first dose. Discontinue immediately and ensure a patent airway."}]', '- **Anticholinergic Effects:** Use with caution in patients with clinically significant bladder outflow obstruction or gastrointestinal obstructive disorders due to the risk of urinary or gastric retention.
INSERT INTO "drug_generic" VALUES(1035, 'Saxagliptin', 'Saxagliptin', 'A10BH03', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Heart Failure Risk", "severity": "High", "trigger_condition": "Patients with a history of heart failure or renal impairment", "message": "STOP: Increased risk of heart failure hospitalization has been observed. Consider the risks and benefits in patients with known risk factors for heart failure."}]', '**Heart Failure:** An increased risk of heart failure hospitalization has been observed; monitor patients for signs and symptoms (e.g., dyspnea, edema, rapid weight gain) and consider discontinuation if heart failure develops.
INSERT INTO "drug_generic" VALUES(1036, 'Cefixime', 'Cefixime', 'J01DD08', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(1037, 'Alfuzosin', 'Alfuzosin', 'G04CA01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Postural Hypotension and Syncope", "severity": "High", "trigger_condition": "Initiation of therapy or dose increase", "message": "STOP: Can cause severe postural hypotension and syncope, especially with the first dose. Patients should be warned to avoid situations where injury could result if syncope occurs."}]', '**Intraoperative Floppy Iris Syndrome (IFIS):** Has been observed during cataract surgery in some patients on or previously treated with alpha-1 blockers. Ophthalmologists should be informed prior to surgery to modify surgical technique.
INSERT INTO "drug_generic" VALUES(1038, 'Efalizumab', 'Efalizumab', 'L04AA21', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Progressive Multifocal Leukoencephalopathy (PML)", "severity": "High", "trigger_condition": "Any patient receiving or having received efalizumab therapy", "message": "STOP: Efalizumab has been withdrawn from the market in most regions due to a severe and potentially fatal risk of Progressive Multifocal Leukoencephalopathy (PML), an opportunistic viral infection of the brain."}]', '**Market Withdrawal Note:** Efalizumab has been voluntarily withdrawn from the global market due to the risk of Progressive Multifocal Leukoencephalopathy (PML).
INSERT INTO "drug_generic" VALUES(1039, 'Mineral Oil', 'Mineral Oil', 'A06AA01', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Aspiration Risk", "severity": "High", "trigger_condition": "Administration to bedridden patients, elderly, or those with dysphagia", "message": "STOP: Aspiration of mineral oil can cause severe, potentially fatal lipid pneumonitis. Do not administer at bedtime or to patients with difficulty swallowing."}]', 'Avoid prolonged use (longer than 1 week) as it may lead to dependence for bowel movements and impair the absorption of fat-soluble vitamins (A, D, E, K). Do not administer to bedridden, debilitated, or geriatric patients due to the high risk of aspiration and subsequent lipid pneumonitis. Do not administer immediately before bedtime. Use with caution in patients with a history of esophageal strictures or hiatal hernia.', '- Relief of occasional constipation and bowel irregularity.
INSERT INTO "drug_generic" VALUES(1040, 'Pseudoephedrine Hydrochloride', 'Pseudoephedrine', 'R01BA02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hypertensive Crisis Risk", "severity": "High", "trigger_condition": "Concurrent use with Monoamine Oxidase Inhibitors (MAOIs)", "message": "STOP: Concurrent use of pseudoephedrine with MAOIs, or use within 14 days of stopping an MAOI, is strictly contraindicated due to the risk of severe, potentially fatal hypertensive crisis."}]', '- **Cardiovascular Disease:** Use with caution in patients with ischemic heart disease, arrhythmias, tachycardia, or mild-to-moderate hypertension, as it can increase blood pressure and heart rate.
INSERT INTO "drug_generic" VALUES(1041, 'Magaldrate + Simethicone Chewable', 'Magaldrate and Simethicone', 'A02AF02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Toxicity in Renal Impairment", "severity": "High", "trigger_condition": "Severe renal impairment (CrCl < 30 mL/min)", "message": "STOP: Magaldrate contains magnesium and aluminum. In patients with severe renal impairment, accumulation can lead to fatal hypermagnesemia and aluminum toxicity. Use is contraindicated."}]', '**Renal Impairment:** Use with extreme caution in patients with mild to moderate renal impairment due to the risk of magnesium and aluminum accumulation.
INSERT INTO "drug_generic" VALUES(1042, 'Atosiban', 'Atosiban', 'G02CX01', 0, 1, 1, 0, 0, 0, 0, 0, '[]', '**Premature Rupture of Membranes (PROM):** When atosiban is used in patients in whom premature rupture of membranes cannot be excluded, the benefits of delaying delivery should be carefully balanced against the potential risk of chorioamnionitis.
INSERT INTO "drug_generic" VALUES(1043, 'Insulin Lispro (25%/50%) + Insulin Lispro Protamine (75%/50%) mix', 'Insulin Lispro Protamine and Insulin Lispro', 'A10AD04', 0, 1, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Hypoglycemia Risk", "severity": "High", "trigger_condition": "Changes in meal patterns, physical activity, or co-administration with other glucose-lowering agents", "message": "Severe, life-threatening hypoglycemia can occur. Monitor blood glucose closely. Do not administer during episodes of hypoglycemia."}]', 'Use with caution in patients with renal or hepatic impairment, as insulin requirements may be reduced. Monitor serum glucose, potassium, HbA1c, and lipid profiles regularly. Hypokalemia is a potential risk; monitor potassium levels in patients at risk (e.g., those on potassium-lowering medications). Illness, emotional stress, or changes in physical activity may alter insulin requirements. Exercise extreme caution when transferring patients from other insulin types, as dosage adjustments and strict monitoring are required. Lipoatrophy or lipohypertrophy can occur; rotate injection sites systematically.', '- Management of Type 1 Diabetes Mellitus to improve glycemic control.
INSERT INTO "drug_generic" VALUES(1044, 'Olopatadine 0.6% Nasal prep', 'Olopatadine Hydrochloride', 'R01AC08', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Epistaxis and Nasal Ulceration", "severity": "Moderate", "trigger_condition": "Prolonged use or improper administration technique", "message": "Epistaxis, nasal ulceration, and nasal septal perforation can occur. Perform periodic nasal examinations for signs of adverse effects on the nasal mucosa."}]', '**Somnolence and Impaired Mental Alertness:** May cause somnolence. Patients should be cautioned against engaging in hazardous occupations requiring complete mental alertness and motor coordination, such as driving or operating machinery, after administration.
INSERT INTO "drug_generic" VALUES(1045, 'Dimethothiazine Mesylate', 'Fonazine Mesylate', 'N02CX05', 0, 0, 0, 0, 1, 0, 0, 0, '[]', '**Central Nervous System Depression:** May cause drowsiness and impair the mental or physical abilities required for the performance of potentially hazardous tasks such as driving a car or operating machinery.
INSERT INTO "drug_generic" VALUES(1046, 'Trastuzumab', 'Trastuzumab', 'L01FD01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiomyopathy and Infusion Reactions", "severity": "High", "trigger_condition": "Initiation of therapy or concurrent use with anthracyclines", "message": "STOP: Can cause subclinical and clinical cardiac failure. Evaluate left ventricular ejection fraction (LVEF) prior to and during treatment. Severe, potentially fatal infusion reactions and pulmonary toxicity can occur; monitor closely during and after infusion."}]', 'Extensive monitoring of cardiac function (LVEF) is mandatory at baseline and at regular intervals (e.g., every 3 months) during treatment, and upon completion. Discontinue for significant LVEF decline. Use with extreme caution in patients with pre-existing cardiovascular disease, pulmonary disease, or extensive pulmonary tumor involvement, as they are at higher risk for severe pulmonary toxicity and infusion reactions. Exacerbation of chemotherapy-induced neutropenia may occur. Verify pregnancy status prior to initiation; effective contraception is required during and for 7 months after the last dose.', '- **Adjuvant Breast Cancer**: Treatment of HER2-overexpressing node-positive or node-negative (ER/PR negative or with one high-risk feature) breast cancer. Used as part of a regimen with doxorubicin, cyclophosphamide, and either paclitaxel or docetaxel; with docetaxel and carboplatin; or as a single agent following multi-modality anthracycline-based therapy.
INSERT INTO "drug_generic" VALUES(1047, 'Phenylephrine + Pramoxine + Glycerin + Petrolatum (rectal prep)', 'Phenylephrine / Pramoxine / Glycerin / Petrolatum', 'C05AX', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Systemic Sympathomimetic Effects", "severity": "Low", "trigger_condition": "Excessive application or use in patients with severe cardiovascular disease", "message": "Contains phenylephrine. Systemic absorption can occur, potentially exacerbating hypertension, heart disease, or hyperthyroidism. Discontinue if symptoms worsen."}]', '**Cardiovascular and Endocrine Disease:** Contains phenylephrine, an alpha-adrenergic agonist. Use with caution in patients with heart disease, hypertension, hyperthyroidism, diabetes mellitus, or prostatic hypertrophy, as systemic absorption can exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1048, 'Menthol 10% + Methyl Salicylate 30% Topical', 'Menthol / Methyl Salicylate Topical', 'M02AC', 0, 0, 0, 1, 0, 1, 1, 0, '[]', 'For external use only. Avoid contact with the eyes, mucous membranes, and sensitive skin areas. Do not apply to wounds, damaged, or irritated skin. Do not bandage tightly, wrap, or cover the treated area with an occlusive dressing or heating pad, as this can increase systemic absorption and the risk of severe burns or salicylate toxicity. Do not use immediately before or after a bath or shower. Wash hands thoroughly after applying. Due to the higher concentration of methyl salicylate (30%), the risk of systemic absorption and local irritation is increased compared to lower strength formulations.', '- **Musculoskeletal Pain:** Symptomatic relief of minor aches and pains of muscles and joints associated with simple backache, arthritis, strains, bruises, and sprains.
INSERT INTO "drug_generic" VALUES(1049, 'Tolnaftate 1% Topical', 'Tolnaftate', 'D01AE18', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'For external use only. Avoid exposure to the eyes, mouth, and other mucous membranes. Discontinue treatment and consult a physician if the condition does not improve within 10 days (for tinea cruris/corporis) or 4 weeks (for tinea pedis), or if irritation or hypersensitivity develops.', '- **Superficial Dermatophyte Infections:** Treatment of tinea pedis (athlete''s foot), tinea cruris (jock itch), and tinea corporis (ringworm) caused by susceptible fungi (e.g., *Epidermophyton*, *Microsporum*, *Trichophyton* species).
INSERT INTO "drug_generic" VALUES(1050, 'Fenoldopam', 'Fenoldopam', 'C01CA19', 0, 1, 1, 0, 0, 1, 1, 1, '[{"alert_type": "Dose-Related Tachycardia and Hypotension", "severity": "High", "trigger_condition": "Infusion rates above 0.1 mcg/kg/min or rapid titration", "message": "STOP: Fenoldopam causes dose-related tachycardia and profound hypotension. Continuous blood pressure and heart rate monitoring are required. Titrate slowly."}]', '**Tachycardia:** Causes a dose-related tachycardia, particularly with infusion rates above 0.1 mcg/kg/min. Use with caution in patients with angina or a history of myocardial infarction.
INSERT INTO "drug_generic" VALUES(1051, 'Carbonyl Iron + Folic acid + Vitamin B complex + Vitamin C + Zinc', 'Carbonyl Iron / Folic Acid / Vitamin B Complex / Ascorbic Acid / Zinc', 'B03AE04', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Accidental Overdose in Children", "severity": "High", "trigger_condition": "Accidental ingestion by children under 6 years", "message": "Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Iron Overload:** Extreme care should be taken in patients who may develop iron overload, such as those with hemochromatosis, hemosiderosis, hemolytic anemia, or red cell aplasia.
INSERT INTO "drug_generic" VALUES(1052, 'Sertraline Hydrochloride', 'Sertraline', 'N06AB06', 0, 1, 0, 1, 0, 0, 1, 1, '[{"alert_type": "Suicidality Risk", "severity": "High", "trigger_condition": "Initiation of therapy or dose changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '**Serotonin Syndrome:** Potentially life-threatening serotonin syndrome can occur, especially with concomitant use of other serotonergic drugs (e.g., triptans, TCAs, fentanyl, lithium, tramadol, buspirone, St. John''s wort). Monitor for mental status changes, autonomic instability, and neuromuscular abnormalities.
INSERT INTO "drug_generic" VALUES(1053, 'Ketotifen', 'Ketotifen', 'R06AX17', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "CNS Depression", "severity": "Moderate", "trigger_condition": "Concurrent use of alcohol or other CNS depressants", "message": "May cause significant drowsiness and impair the ability to perform tasks requiring mental alertness, such as driving or operating heavy machinery."}]', 'Use with extreme caution in patients with a history of epilepsy, as it may lower the seizure threshold. Patients should be warned about the potential for significant drowsiness, which may impair the performance of tasks requiring mental alertness, such as driving or operating machinery. Concurrent use with other central nervous system depressants or alcohol should be avoided. Efficacy in acute asthma attacks is not established; it should not be used to abort an acute asthma exacerbation. Gradual tapering of concurrent systemic corticosteroids is required if transitioning to ketotifen for asthma prophylaxis.', '- **Allergic Conjunctivitis:** Management of signs and symptoms associated with allergic conjunctivitis.
INSERT INTO "drug_generic" VALUES(1054, 'Abacavir + Lamivudine + Zidovudine', 'Abacavir, Lamivudine, and Zidovudine', 'J05AR04', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fatal Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Presence of HLA-B*5701 allele or history of abacavir hypersensitivity", "message": "STOP: Fatal hypersensitivity reactions have occurred. Screen for HLA-B*5701 allele before initiating. Discontinue immediately if hypersensitivity is suspected and NEVER re-challenge."}, {"alert_type": "Lactic Acidosis and Hepatomegaly", "severity": "High", "trigger_condition": "Clinical signs of lactic acidosis or pronounced hepatotoxicity", "message": "STOP: Lactic acidosis and severe hepatomegaly with steatosis, including fatal cases, have been reported. Suspend treatment immediately."}, {"alert_type": "Hematologic Toxicity", "severity": "High", "trigger_condition": "Severe anemia or neutropenia", "message": "STOP: Zidovudine is associated with severe hematologic toxicity. Monitor complete blood counts frequently."}]', '**Hypersensitivity Reactions:** Severe and sometimes fatal hypersensitivity reactions (HSR) can occur. Risk is significantly higher in patients carrying the HLA-B*5701 allele. Symptoms include fever, rash, GI symptoms (nausea, vomiting, diarrhea), and respiratory symptoms. Discontinue immediately if HSR is suspected.
INSERT INTO "drug_generic" VALUES(1055, 'Sodium Alginate (Alginic acid)', 'Alginic Acid', 'A02BX13', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Aluminum/Magnesium Toxicity", "severity": "Moderate", "trigger_condition": "Use in patients with severe renal impairment", "message": "STOP: Combination products containing aluminum or magnesium can cause severe toxicity (encephalopathy, hypermagnesemia) in patients with chronic renal failure. Avoid chronic use in this population."}]', '- **Renal Impairment:** Use with caution in patients with renal failure if the formulation contains aluminum or magnesium, due to the risk of accumulation and toxicity (e.g., aluminum encephalopathy, hypermagnesemia).
INSERT INTO "drug_generic" VALUES(1056, 'Multivitamin & Multimineral prep for Nursing mother', 'Prenatal/Postnatal Multivitamins and Minerals', 'A11AA03', 0, 0, 1, 1, 0, 1, 0, 0, '[]', 'Do not exceed the recommended daily dosage, as excessive intake of fat-soluble vitamins (A, D, E) and iron can lead to toxicity.
INSERT INTO "drug_generic" VALUES(1057, 'Alprazolam', 'Alprazolam', 'N05BA12', 0, 1, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Concomitant Use with Opioids", "severity": "High", "trigger_condition": "Co-prescription with opioid analgesics or cough suppressants", "message": "STOP: Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death. Reserve prescribing for patients with inadequate alternative options."}, {"alert_type": "Abuse, Misuse, and Addiction", "severity": "High", "trigger_condition": "Prescribing to any patient", "message": "STOP: Alprazolam exposes users to risks of abuse, misuse, and addiction. Assess risk before prescribing and monitor regularly."}, {"alert_type": "Withdrawal Reactions", "severity": "High", "trigger_condition": "Abrupt discontinuation or rapid dose reduction", "message": "STOP: Abrupt discontinuation can precipitate acute, life-threatening withdrawal reactions (seizures). Use a gradual taper to discontinue."}]', '**CNS Depression:** Causes dose-related CNS depression. Caution patients against driving or operating heavy machinery. Avoid concomitant use of alcohol.
INSERT INTO "drug_generic" VALUES(1058, 'Olsalazine', 'Olsalazine', 'A07EC03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Salicylate Hypersensitivity", "severity": "High", "trigger_condition": "Patient history of allergy to salicylates (e.g., aspirin)", "message": "STOP: Contraindicated in patients with hypersensitivity to salicylates. Severe allergic reactions can occur."}]', '- **Renal Impairment:** Monitor renal function (serum creatinine, BUN, urinalysis) prior to and periodically during treatment. Mesalamine has been associated with nephrotoxicity.
INSERT INTO "drug_generic" VALUES(1059, 'Somatropin', 'Somatropin', 'H01AC01', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Intracranial Hypertension", "severity": "High", "trigger_condition": "Patient presenting with severe headache, visual changes, or nausea/vomiting during therapy", "message": "Funduscopic examination should be performed routinely before initiating treatment and periodically thereafter to monitor for papilledema and benign intracranial hypertension."}]', 'Monitor thyroid function periodically, as somatropin may unmask central hypothyroidism. Monitor for signs of glucose intolerance and new-onset diabetes mellitus; insulin doses may require adjustment in diabetic patients. Perform routine funduscopic exams to detect benign intracranial hypertension. In pediatric patients, monitor for progression of scoliosis and slipped capital femoral epiphysis (limping or hip/knee pain). Discontinue treatment immediately if there is any evidence of tumor growth or active malignancy. Use with extreme caution in patients with Prader-Willi syndrome; fatalities have been reported in severely obese patients or those with severe respiratory impairment.', '- **Pediatric Growth Hormone Deficiency (GHD):** Treatment of growth failure due to inadequate secretion of endogenous growth hormone.
INSERT INTO "drug_generic" VALUES(1060, 'Mometasone Furoate + Olopatadine Nasal prep', 'Mometasone and Olopatadine nasal spray', 'R01AD59', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Nasal Septal Perforation", "severity": "Moderate", "trigger_condition": "Prolonged use of intranasal corticosteroids", "message": "Caution: Intranasal corticosteroids can cause nasal septal perforation, epistaxis, and impaired wound healing. Examine the nasal mucosa periodically."}]', '**Local Nasal Effects:** Epistaxis, nasal ulcerations, and nasal septal perforations can occur. Because corticosteroids impair wound healing, patients who have experienced recent nasal septal ulcers, nasal surgery, or nasal trauma should not use this nasal spray until healing has occurred.
INSERT INTO "drug_generic" VALUES(1061, 'Gentamicin + Hydrocortisone Acetate Ear prep', 'Gentamicin and Hydrocortisone Acetate Otic', 'S02CA03', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Ototoxicity Risk", "severity": "High", "trigger_condition": "Tympanic membrane perforation", "message": "STOP: Do not use if the tympanic membrane (eardrum) is perforated or if perforation is suspected. Aminoglycosides like gentamicin can cause irreversible partial or total deafness if they enter the middle ear."}]', 'Verify that the tympanic membrane is intact before initiating therapy. 
INSERT INTO "drug_generic" VALUES(1062, 'Azilsartan + Chlorthalidone', 'Azilsartan and Chlorthalidone', 'C09DA09', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately upon detection of pregnancy."}]', '**Hypotension in Volume- or Salt-Depleted Patients:** Symptomatic hypotension may occur after initiation, particularly in patients with an activated renin-angiotensin system (e.g., those on high-dose diuretics). Correct volume depletion prior to administration.
INSERT INTO "drug_generic" VALUES(1063, 'Eplerenone', 'Eplerenone', 'C03DA04', 0, 0, 1, 0, 1, 0, 0, 0, '[{"alert_type": "Hyperkalemia Risk", "severity": "High", "trigger_condition": "Renal impairment, diabetes with microalbuminuria, or concurrent use of potassium supplements/sparing diuretics", "message": "STOP: Eplerenone can cause severe and potentially fatal hyperkalemia. Monitor serum potassium levels at baseline, within the first week, at one month, and periodically thereafter. Contraindicated in patients with baseline potassium >5.5 mEq/L or CrCl <30 mL/min."}]', '**Hyperkalemia:** The principal risk of eplerenone is hyperkalemia, which can cause life-threatening arrhythmias. The risk increases with declining renal function, diabetes mellitus (especially with proteinuria), and concurrent use of ACE inhibitors, ARBs, or NSAIDs. Monitor serum potassium and renal function regularly.
INSERT INTO "drug_generic" VALUES(1064, 'Methohexital', 'Methohexital', 'N01AF01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiorespiratory Depression", "severity": "High", "trigger_condition": "Rapid bolus administration or excessive dosing", "message": "STOP: Rapid bolus doses will increase cardiorespiratory effects including laryngospasm, apnea, severe hypotension, myocardial depression, and cardiovascular collapse. Must be administered by trained anesthesia personnel with resuscitative equipment available."}]', '- **Patient Populations:** Use with extreme caution in patients with severe anemia, extreme obesity, or debilitated patients.
INSERT INTO "drug_generic" VALUES(1065, 'Naldemedine', 'Naldemedine', 'A06AH05', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Gastrointestinal Perforation", "severity": "High", "trigger_condition": "Patients with known or suspected GI obstruction", "message": "STOP: Contraindicated in patients with known or suspected GI obstruction due to the risk of severe gastrointestinal perforation. Monitor for severe, persistent, or worsening abdominal pain."}]', '**Gastrointestinal Perforation:** GI perforation has been reported with the use of peripherally acting mu-opioid receptor antagonists (PAMORAs) in patients with conditions that may reduce the structural integrity of the GI tract wall (e.g., peptic ulcer disease, diverticular disease, infiltrative GI malignancies, Crohn''s disease). Monitor for severe, persistent, or worsening abdominal pain and discontinue naldemedine if this occurs.
INSERT INTO "drug_generic" VALUES(1066, 'Peginterferon Alfa-2b', 'Peginterferon alfa-2b', 'L03AB10', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fatal Neuropsychiatric and Ischemic Disorders", "severity": "High", "trigger_condition": "Development of severe depression, suicidal ideation, or ischemic symptoms", "message": "STOP: Alpha interferons cause or aggravate fatal or life-threatening neuropsychiatric, autoimmune, ischemic, and infectious disorders. Discontinue immediately in patients with persistently severe or worsening signs/symptoms of these conditions."}]', 'Monitor closely for severe depression, suicidal ideation, and aggressive behavior; psychiatric consultation may be required. Monitor complete blood counts (CBC) frequently due to the risk of severe bone marrow suppression (neutropenia, thrombocytopenia). Use with caution in patients with cardiovascular disease, pulmonary disease, diabetes mellitus, or thyroid disorders. May cause or exacerbate autoimmune disorders. Ophthalmic disorders (retinopathy, macular edema) have been reported; baseline and periodic eye exams are recommended. Do not change brands of interferon without medical supervision due to product variability.', '- **Chronic Hepatitis C (CHC):** Treatment of chronic hepatitis C in patients with compensated liver disease. It is typically used in combination with other antiviral agents (e.g., ribavirin, sofosbuvir, simeprevir) and is not recommended as monotherapy.', '**Autoimmune Hepatitis:** Contraindicated as interferons can exacerbate autoimmune diseases.
INSERT INTO "drug_generic" VALUES(1067, 'Sucralose', 'Sucralose', 'Data not available', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**General Use:** Sucralose is generally recognized as safe (GRAS) for use as a non-nutritive sweetener. No specific clinical precautions are required for the general population, including diabetics, as it does not affect carbohydrate metabolism or insulin secretion.', '- **Dietary Sweetener:** Used as a zero-calorie sugar substitute in foods, beverages, and pharmaceutical preparations.
INSERT INTO "drug_generic" VALUES(1068, 'Varenicline Tartrate', 'Varenicline', 'N07BA03', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Neuropsychiatric Symptoms", "severity": "High", "trigger_condition": "Patients with a history of psychiatric illness or those developing behavioral changes", "message": "STOP: Serious neuropsychiatric events including depression, suicidal ideation, suicide attempt, and completed suicide have been reported. Monitor closely for changes in mood or behavior."}]', '- **Neuropsychiatric Adverse Events:** Monitor for changes in behavior, hostility, agitation, depressed mood, and suicide-related events. Discontinue immediately if these occur.
INSERT INTO "drug_generic" VALUES(1069, 'Haloperidol', 'Haloperidol', 'N05AD01', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Increased Mortality in Elderly Patients with Dementia-Related Psychosis", "severity": "High", "trigger_condition": "Use in elderly patients with dementia-related psychosis", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Haloperidol is not approved for the treatment of patients with dementia-related psychosis."}, {"alert_type": "Cardiovascular Effects and QT Prolongation", "severity": "High", "trigger_condition": "Intravenous administration or use with other QT-prolonging drugs", "message": "STOP: Haloperidol can cause dose-dependent QT prolongation and Torsades de Pointes. Intravenous administration carries a higher risk. Monitor ECG and electrolytes."}]', '**Neuroleptic Malignant Syndrome (NMS):** A potentially fatal symptom complex characterized by hyperpyrexia, muscle rigidity, altered mental status, and autonomic instability. Discontinue immediately if NMS is suspected.
INSERT INTO "drug_generic" VALUES(1070, 'Phenobarbitone (Phenobarbital)', 'Phenobarbital', 'N03AA02', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Abrupt Withdrawal Risk", "severity": "High", "trigger_condition": "Discontinuation of therapy", "message": "STOP: Abrupt withdrawal may precipitate status epilepticus. Taper dosage gradually when discontinuing therapy."}]', '**Dependence and Tolerance:** Prolonged use may lead to psychological and physical dependence. Use with extreme caution in patients with a history of sedative or hypnotic addiction.
INSERT INTO "drug_generic" VALUES(1071, 'Warfarin Sodium', 'Warfarin', 'B01AA03', 0, 1, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Fatal Bleeding Risk", "severity": "High", "trigger_condition": "Supratherapeutic INR or concurrent use of NSAIDs/antiplatelets", "message": "STOP: Warfarin can cause major or fatal bleeding. Regular monitoring of INR is mandatory. Drugs, dietary changes, and patient factors severely alter pharmacokinetics."}]', 'High risk of major or fatal hemorrhage. Risk factors include high intensity of anticoagulation (INR >4.0), age ≥65, history of highly variable INRs, history of GI bleeding, hypertension, cerebrovascular disease, anemia, malignancy, trauma, and renal impairment. May cause tissue necrosis or gangrene, often associated with protein C or S deficiency. Monitor for signs of calciphylaxis. Consider genotyping for CYP2C9 and VKORC1 prior to initiation if available, as variations significantly affect dosing requirements. Maintain a consistent dietary intake of Vitamin K.', '- **Venous Thromboembolism (VTE):** Prophylaxis and treatment of deep vein thrombosis (DVT) and pulmonary embolism (PE).
INSERT INTO "drug_generic" VALUES(1072, 'Erythromycin solution', 'Erythromycin Topical', 'D10AF02', 1, 0, 1, 1, 0, 1, 1, 0, '[]', '**Local Irritation:** Topical erythromycin may cause local skin irritation, including erythema, desquamation, burning, and pruritus. If severe irritation occurs, discontinue use.
INSERT INTO "drug_generic" VALUES(1073, 'Cholecalciferol (Vit. D3)', 'Cholecalciferol', 'A11CC05', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "Moderate", "trigger_condition": "High dose supplementation or concurrent calcium use", "message": "Excessive vitamin D supplementation can lead to severe hypercalcemia and hypercalciuria, resulting in renal damage and vascular calcification. Monitor serum calcium levels periodically."}]', '**Renal Impairment:** Cholecalciferol requires hydroxylation in the kidneys to its active form (calcitriol). Patients with severe renal impairment may not respond to cholecalciferol and require active vitamin D analogs (e.g., calcitriol or alfacalcidol).
INSERT INTO "drug_generic" VALUES(1074, 'Alfacalcidol', 'Alfacalcidol', 'A11CC03', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "High", "trigger_condition": "Overdosage or concurrent use of calcium supplements", "message": "STOP: Severe hypercalcemia can occur, leading to cardiac arrhythmias, renal damage, and ectopic calcification. Monitor serum calcium and phosphate levels strictly."}]', '**Hypercalcemia and Hyperphosphatemia:** Monitor serum levels of calcium and phosphate regularly, especially in patients with renal failure, infants, and the elderly. Adjust the dose to avoid hypercalcemia.
INSERT INTO "drug_generic" VALUES(1075, 'Dinoprostone vaginal prep', 'Dinoprostone', 'G02AD02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Uterine Hyperstimulation and Rupture", "severity": "High", "trigger_condition": "Administration in patients with prior uterine surgery or concurrent oxytocin use", "message": "STOP: Dinoprostone can cause severe uterine hyperstimulation and uterine rupture. Continuous fetal and uterine monitoring is mandatory. Do not use simultaneously with intravenous oxytocin."}]', '**Hospital Use Only:** Dinoprostone must be administered by physicians in a hospital setting equipped with immediate intensive care and acute surgical facilities.
INSERT INTO "drug_generic" VALUES(1076, 'Natamycin 5% Eye prep', 'Natamycin Ophthalmic', 'S01AA10', 1, 0, 0, 1, 0, 1, 0, 0, '[{"alert_type": "Treatment Failure and Re-evaluation", "severity": "Moderate", "trigger_condition": "No improvement after 7-10 days of therapy", "message": "STOP: Failure of improvement of keratitis following 7-10 days of administration suggests that the infection may be caused by a microorganism not susceptible to natamycin. Clinical re-evaluation and additional laboratory studies are mandatory."}]', '- **Topical Use Only:** For topical ophthalmic use only. Not for injection.
INSERT INTO "drug_generic" VALUES(1077, 'Guaiphenesin + Diphenhydramine + Levomenthol', 'Guaifenesin + Diphenhydramine + Menthol', 'R05CA10', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Respiratory Depression Risk", "severity": "High", "trigger_condition": "Use in children under 12 years of age", "message": "STOP: Contraindicated in children under 12 years due to the risk of severe and potentially fatal respiratory depression and toxicity."}]', 'Use with extreme caution in patients with persistent or chronic cough, such as that occurring with asthma, emphysema, or smoking, or where cough is accompanied by excessive secretions.
INSERT INTO "drug_generic" VALUES(1078, 'Didanosine', 'Didanosine', 'J05AF02', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fatal Pancreatitis and Lactic Acidosis", "severity": "High", "trigger_condition": "Development of severe abdominal pain, nausea, vomiting, or unexplained tachypnea", "message": "STOP: Fatal and nonfatal pancreatitis have occurred. Lactic acidosis and severe hepatomegaly with steatosis, including fatal cases, have been reported. Suspend therapy immediately if suspected."}]', '**Pancreatitis:** Fatal and nonfatal pancreatitis have occurred. Suspend use in patients with suspected pancreatitis and discontinue in confirmed cases. Risk is higher in the elderly and those with a history of pancreatitis.
INSERT INTO "drug_generic" VALUES(1079, 'Brodalumab', 'Brodalumab', 'L04AC12', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Suicidal Ideation and Behavior", "severity": "High", "trigger_condition": "Patient history of depression or suicidal ideation", "message": "STOP: Suicidal ideation and behavior, including completed suicides, have occurred. Weigh risks/benefits in patients with a history of depression. Monitor for new or worsening mood changes."}]', '**Suicidal Ideation and Behavior:** Suicidal ideation and behavior, including completed suicides, have occurred in patients treated with brodalumab. Prior to prescribing, weigh the potential risks and benefits in patients with a history of depression and/or suicidal ideation or behavior. Advise patients and caregivers to seek immediate medical attention for manifestations of suicidal ideation, new-onset or worsening depression, anxiety, or other mood changes.
INSERT INTO "drug_generic" VALUES(1080, 'Oxiconazole 1% Topical', 'Oxiconazole', 'D01AC11', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Local Irritation:** Discontinue use if sensitization or severe irritation occurs during treatment.
INSERT INTO "drug_generic" VALUES(1081, 'Fluphenazine Hydrochloride + Nortriptyline', 'Fluphenazine and Nortriptyline', 'N06CA', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Suicidality Risk", "severity": "High", "trigger_condition": "Initiation of therapy or dose changes", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '- **Cardiovascular Disease:** Use with caution in patients with cardiac failure, myocardial infarction, or arrhythmias, as nortriptyline can cause significant cardiovascular toxicity.
INSERT INTO "drug_generic" VALUES(1082, 'Hydrochlorothiazide + Valsartan', 'Valsartan and Hydrochlorothiazide', 'C09DA03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Fetal Toxicity:** Can cause fetal harm when administered to a pregnant woman. Discontinue as soon as pregnancy is detected.
INSERT INTO "drug_generic" VALUES(1083, 'Aminocaproic Acid', 'Aminocaproic Acid', 'B02AA01', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Intravascular Clotting and Thrombosis", "severity": "High", "trigger_condition": "Use in patients with Disseminated Intravascular Coagulation (DIC) without heparin", "message": "STOP: Aminocaproic acid inhibits fibrinolysis. If used in patients with active intravascular clotting (like DIC), it can cause fatal, widespread thrombosis. Do not use unless hyperfibrinolysis is definitively diagnosed."}, {"alert_type": "Skeletal Muscle Toxicity", "severity": "High", "trigger_condition": "Prolonged administration", "message": "STOP: Severe myopathy, rhabdomyolysis, and acute renal failure have occurred with prolonged use. Monitor CPK levels and discontinue if muscle weakness or elevated CPK occurs."}]', '**Upper Urinary Tract Bleeding:** Use with extreme caution. Inhibition of fibrinolysis can cause clot formation in the renal pelvis and ureters, leading to intrarenal obstruction and acute renal failure.
INSERT INTO "drug_generic" VALUES(1084, 'Ketorolac Tromethamine 15.8% Nasal prep', 'Ketorolac Intranasal', 'M01AB15', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Gastrointestinal, Renal, and Bleeding Risks", "severity": "High", "trigger_condition": "Use exceeding 5 days or use in contraindicated populations", "message": "STOP: Intranasal ketorolac carries the same severe risks as systemic NSAIDs (GI bleeding, acute renal failure, cardiovascular events). The total duration of use (combined with any other route of ketorolac) MUST NOT exceed 5 days."}]', '**Cardiovascular Thrombotic Events:** NSAIDs cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke.
INSERT INTO "drug_generic" VALUES(1085, 'Prochlorperazine Maleate', 'Prochlorperazine Maleate', 'N05AB04', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Extrapyramidal Symptoms and Mortality in Elderly", "severity": "High", "trigger_condition": "Use in elderly patients with dementia-related psychosis or pediatric patients <2 years", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotics are at an increased risk of death. Do not use in children under 2 years or under 9 kg due to severe extrapyramidal symptoms and respiratory depression."}]', '- **Extrapyramidal Symptoms (EPS):** High risk of acute dystonia, akathisia, parkinsonism, and tardive dyskinesia. Monitor closely, especially in children and the elderly.
INSERT INTO "drug_generic" VALUES(1086, 'Rituximab', 'Rituximab', 'L01FA01', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Infusion Reactions", "severity": "High", "trigger_condition": "During or within 24 hours of infusion", "message": "STOP: Severe, including fatal, infusion-related reactions can occur. Premedicate patients and monitor closely during the infusion."}]', '**Severe Mucocutaneous Reactions:** Severe, including fatal, mucocutaneous reactions (e.g., Stevens-Johnson syndrome, toxic epidermal necrolysis) can occur. Discontinue rituximab if these occur.
INSERT INTO "drug_generic" VALUES(1087, 'Clofazimine', 'Clofazimine', 'J04BA01', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Gastrointestinal Toxicity", "severity": "High", "trigger_condition": "Doses >100 mg/day or prolonged therapy", "message": "STOP: Clofazimine can deposit in the intestinal mucosa, causing severe abdominal obstruction, GI bleeding, splenic infarction, and death. Discontinue if severe abdominal pain occurs."}, {"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Concomitant use with bedaquiline or other QT-prolonging drugs", "message": "Risk of Torsades de Pointes. Monitor ECGs closely. Discontinue if QTcF interval \u2265500 ms develops."}]', 'Monitor closely for severe gastrointestinal adverse reactions; clofazimine crystals can deposit in mesenteric lymph nodes and bowel mucosa. Advise patients that reversible skin and body fluid discoloration (red to brownish-black) occurs in almost all patients; monitor for psychological effects, including depression and suicidal ideation secondary to skin discoloration. Monitor ECGs for QT prolongation, especially if combined with other QT-prolonging agents. Use with caution in patients with hepatic impairment.', '- **Lepromatous Leprosy:** Used in combination with other antileprosy drugs (e.g., dapsone, rifampin) for the treatment of multibacillary leprosy, including dapsone-resistant cases.
INSERT INTO "drug_generic" VALUES(1088, 'Liquid Paraffin + White Soft Paraffin + Wool Alcohol eye prep', 'Mineral Oil, White Petrolatum, and Lanolin Ophthalmic', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Visual Disturbance", "severity": "Low", "trigger_condition": "Application of ointment", "message": "NOTE: Application will cause temporary blurred vision. Advise patients not to drive or operate machinery immediately after use."}]', 'For external ophthalmic use only.
INSERT INTO "drug_generic" VALUES(1089, 'Irinotecan Hydrochloride Trihydrate', 'Irinotecan', 'L01CE02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Diarrhea and Myelosuppression", "severity": "High", "trigger_condition": "Administration of Irinotecan", "message": "STOP: Early and late forms of severe diarrhea can occur and may be life-threatening. Severe myelosuppression (neutropenia) is common. Monitor CBC closely and initiate aggressive loperamide therapy immediately for late diarrhea."}]', '- **Early Diarrhea:** Usually transient and occurs during or within 24 hours of infusion. It is cholinergically mediated and may be accompanied by rhinitis, increased salivation, miosis, lacrimation, diaphoresis, flushing, and abdominal cramping. Consider prophylactic or therapeutic administration of intravenous atropine.
INSERT INTO "drug_generic" VALUES(1090, 'Efavirenz', 'Efavirenz', 'J05AG03', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Psychiatric and CNS Symptoms", "severity": "High", "trigger_condition": "Initiation of therapy or history of psychiatric disorders", "message": "Caution: Efavirenz frequently causes severe central nervous system symptoms (dizziness, insomnia, impaired concentration, abnormal dreams) and psychiatric symptoms (severe depression, suicidal ideation, aggressive behavior). Monitor closely."}]', '**Psychiatric Symptoms:** Serious psychiatric adverse experiences have been reported, including severe depression, suicidal ideation, and aggressive behavior. Patients with a history of psychiatric disorders are at higher risk.
INSERT INTO "drug_generic" VALUES(1091, 'Darolutamide', 'Darolutamide', 'L02BB05', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Ischemic Heart Disease", "severity": "High", "trigger_condition": "Patients with cardiovascular risk factors", "message": "Ischemic heart disease, including fatal cases, has occurred. Optimize management of cardiovascular risk factors. Discontinue for Grade 3-4 events."}]', '**Ischemic Heart Disease:** Increased risk of ischemic heart disease. Monitor for signs and symptoms of coronary artery disease. Optimize management of cardiovascular risk factors (e.g., hypertension, diabetes, dyslipidemia).
INSERT INTO "drug_generic" VALUES(1092, 'Ciprofloxacin', 'Ciprofloxacin', 'J01MA02', 1, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Disabling and Potentially Irreversible Serious Adverse Reactions", "severity": "High", "trigger_condition": "Any patient receiving systemic fluoroquinolones", "message": "Fluoroquinolones are associated with disabling and potentially irreversible serious adverse reactions including tendinitis, tendon rupture, peripheral neuropathy, and CNS effects. Discontinue immediately if these occur. Avoid in patients with myasthenia gravis."}]', '**Tendon Rupture and Tendinitis:** Increased risk, especially in patients >60 years, taking corticosteroids, or with kidney/heart/lung transplants. Discontinue at the first sign of tendon pain or inflammation.
INSERT INTO "drug_generic" VALUES(1093, 'Quinine Dihydrochloride', 'Quinine Dihydrochloride', 'P01BC01', 1, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiotoxicity and Arrhythmias", "severity": "High", "trigger_condition": "Rapid intravenous administration or overdose", "message": "STOP: Intravenous quinine must be given by SLOW infusion. Rapid IV administration can cause severe hypotension, sinus arrest, AV block, ventricular fibrillation, and sudden death. Continuous ECG and blood pressure monitoring are required."}, {"alert_type": "Severe Hypoglycemia", "severity": "High", "trigger_condition": "Pregnancy, severe infection, or prolonged fasting", "message": "Quinine stimulates pancreatic insulin secretion, leading to profound and potentially fatal hypoglycemia, especially in pregnant women and patients with severe malaria. Monitor blood glucose frequently."}]', 'Use with extreme caution in patients with cardiac conduction defects, heart block, or atrial fibrillation. Monitor for signs of cardiotoxicity (ECG monitoring is essential during IV infusion). Monitor blood glucose levels frequently due to the high risk of hyperinsulinemic hypoglycemia. Monitor CBC with platelet count (risk of thrombocytopenia), LFTs, and perform ophthalmologic exams if visual symptoms occur. Discontinue immediately if signs of hypersensitivity or severe cinchonism develop.', '- **Severe or Complicated Malaria:** Treatment of severe or complicated *Plasmodium falciparum* malaria, or when oral therapy is not feasible. (Note: Artesunate is generally preferred globally, but IV quinine remains an alternative where artesunate is unavailable).
INSERT INTO "drug_generic" VALUES(1094, 'Zolmitriptan', 'Zolmitriptan', 'N02CC03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Events", "severity": "High", "trigger_condition": "Patients with underlying cardiovascular disease or risk factors", "message": "STOP: Serious and potentially fatal cardiac events, including myocardial infarction and arrhythmias, have occurred following triptan use. Contraindicated in patients with ischemic heart disease or uncontrolled hypertension."}]', '**Cardiovascular Risk:** Evaluate patients with cardiovascular risk factors (e.g., hypertension, hypercholesterolemia, smoking, obesity, diabetes, strong family history) prior to initiation. Administer the first dose under medical supervision if risk factors are present.
INSERT INTO "drug_generic" VALUES(1095, 'Fidaxomicin', 'Fidaxomicin', 'A07AA12', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Not for Systemic Infections", "severity": "High", "trigger_condition": "Prescription for any infection other than C. difficile colitis", "message": "STOP: Fidaxomicin is minimally absorbed and is NOT effective for the treatment of systemic infections. It is indicated solely for Clostridioides difficile-associated diarrhea."}]', '**Macrolide Allergy:** Use with caution in patients with a known hypersensitivity to macrolides, as fidaxomicin is a macrocyclic antibacterial. Discontinue if a hypersensitivity reaction occurs.
INSERT INTO "drug_generic" VALUES(1096, 'Olanzapine', 'Olanzapine', 'N05AH03', 0, 0, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Increased Mortality in Elderly Patients with Dementia-Related Psychosis", "severity": "High", "trigger_condition": "Use in elderly patients with dementia-related psychosis", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Olanzapine is not approved for the treatment of patients with dementia-related psychosis."}, {"alert_type": "Neuroleptic Malignant Syndrome (NMS)", "severity": "High", "trigger_condition": "Development of hyperpyrexia, muscle rigidity, altered mental status, and autonomic instability", "message": "STOP: NMS is a potentially fatal symptom complex. Discontinue olanzapine immediately and provide intensive symptomatic treatment and medical monitoring."}]', '**Metabolic Changes:** Atypical antipsychotics have been associated with metabolic changes including hyperglycemia, dyslipidemia, and significant weight gain. Monitor blood glucose, lipid profiles, and weight regularly.
INSERT INTO "drug_generic" VALUES(1097, 'Calcium (Eggshell) + Vitamin D3 + Vitamins + Minerals', 'Calcium + Vitamin D3 + Multivitamins + Minerals', 'A11AA02', 0, 0, 1, 1, 1, 1, 0, 0, '[]', '**Hypercalcemia Risk:** Discontinuation of the drug is required if hypercalcemia occurs. Monitor serum calcium levels periodically, especially in patients taking high doses of Vitamin D or those with hypoparathyroidism.
INSERT INTO "drug_generic" VALUES(1098, 'Clotrimazole Vaginal prep', 'Clotrimazole Vaginal', 'G01AF02', 1, 0, 1, 1, 0, 1, 0, 0, '[]', '**Barrier Contraceptives:** Clotrimazole vaginal preparations may contain ingredients (like mineral oil or certain excipients) that can damage latex contraceptives (condoms and diaphragms), reducing their effectiveness. Advise patients to use alternative precautions for at least 5 days after using this product.
INSERT INTO "drug_generic" VALUES(1099, 'Darbepoetin alfa', 'Darbepoetin alfa', 'B03XA02', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cardiovascular and Thromboembolic Risk", "severity": "High", "trigger_condition": "Targeting hemoglobin levels >11 g/dL", "message": "STOP: Erythropoiesis-stimulating agents (ESAs) increase the risk of death, myocardial infarction, stroke, venous thromboembolism, and thrombosis of vascular access. Use the lowest dose sufficient to reduce the need for red blood cell transfusions."}, {"alert_type": "Tumor Progression Risk", "severity": "High", "trigger_condition": "Use in patients with active malignancy", "message": "STOP: ESAs shortened overall survival and/or increased the risk of tumor progression or recurrence in clinical studies of patients with breast, non-small cell lung, head and neck, lymphoid, and cervical cancers."}]', '**Cardiovascular Events:** Increased risk of serious cardiovascular events, myocardial infarction, stroke, and venous thromboembolism. Monitor blood pressure closely and manage hypertension aggressively.
INSERT INTO "drug_generic" VALUES(1100, 'Emicizumab', 'Emicizumab-kxwh', 'B02BX06', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Thrombotic Microangiopathy and Thromboembolism", "severity": "High", "trigger_condition": "Concomitant administration of activated prothrombin complex concentrate (aPCC)", "message": "STOP: Cases of thrombotic microangiopathy (TMA) and severe thrombotic events have been reported when on average a cumulative amount of >100 U/kg/24 hr of aPCC was administered for >24 hours to patients receiving emicizumab prophylaxis. Monitor closely if aPCC must be used."}]', 'Monitor patients closely for the development of thrombotic microangiopathy (TMA) and thromboembolism if activated prothrombin complex concentrate (aPCC) is administered concurrently. If aPCC is required for breakthrough bleeding, consider the benefits and risks carefully; the aPCC dose should not exceed 50 U/kg, and the cumulative dose should not exceed 100 U/kg/24 hours. If TMA or thromboembolism occurs, discontinue aPCC immediately and interrupt emicizumab therapy. Emicizumab alters standard coagulation tests; activated partial thromboplastin time (aPTT) and all assays based on aPTT (e.g., one-stage Factor VIII activity) will be artificially shortened and cannot be used to monitor emicizumab activity or determine the need for additional hemostatic therapy. Use chromogenic Factor VIII activity assays containing bovine coagulation factors to measure endogenous or infused Factor VIII activity.', '- Routine prophylaxis to prevent or reduce the frequency of bleeding episodes in adult and pediatric patients (newborn and older) with hemophilia A (congenital factor VIII deficiency) with or without factor VIII inhibitors.', '- **Hypersensitivity:** Contraindicated in patients with a known severe hypersensitivity reaction to emicizumab or any of its excipients, due to the risk of anaphylaxis.', '- **Injection site reactions** (Erythema, pain, pruritus; usually mild and self-limiting)
INSERT INTO "drug_generic" VALUES(1101, 'Epidoxorubicin HCl', 'Epirubicin Hydrochloride', 'L01DB03', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Cardiotoxicity and Tissue Necrosis", "severity": "High", "trigger_condition": "Cumulative dosing or extravasation during IV administration", "message": "STOP: Epidoxorubicin (Epirubicin) can cause severe, irreversible myocardial toxicity leading to congestive heart failure. Extravasation during IV administration causes severe local tissue necrosis. Administer only under the supervision of a physician experienced in cancer chemotherapy."}]', '**Cardiotoxicity:** Risk of irreversible congestive heart failure increases with cumulative doses. Assess left ventricular ejection fraction (LVEF) before, during, and after therapy. Use with extreme caution in patients with pre-existing cardiac disease or previous anthracycline exposure.
INSERT INTO "drug_generic" VALUES(1102, 'Adapalene + Clindamycin Topical', 'Adapalene + Clindamycin Topical', 'D10AD53', 1, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Pseudomembranous Colitis", "severity": "High", "trigger_condition": "Development of severe, persistent diarrhea or bloody stools", "message": "STOP: Systemic absorption of topical clindamycin can occur. Discontinue immediately if severe diarrhea, abdominal cramps, or bloody stools develop, as this may indicate Clostridioides difficile-associated diarrhea (CDAD)."}]', 'Avoid contact with eyes, lips, angles of the nose, and mucous membranes. If accidental contact occurs, rinse thoroughly with warm water.
INSERT INTO "drug_generic" VALUES(1103, 'Omega-3 Fatty Acids + Lutein + Zeaxanthin + Vitamin C + Vitamin E + Zinc + Copper', 'Ocular Vitamin and Mineral Supplement (AREDS2 Formula)', 'S01XA', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Bleeding Risk", "severity": "Moderate", "trigger_condition": "Concurrent use of anticoagulants", "message": "High doses of omega-3 fatty acids may increase the risk of bleeding. Use with caution in patients taking anticoagulants or antiplatelet agents."}]', '**Bleeding Disorders:** Omega-3 fatty acids can inhibit platelet aggregation. Use with caution in patients with bleeding disorders or those scheduled for surgery.
INSERT INTO "drug_generic" VALUES(1104, 'Lamivudine + Zidovudine', 'Lamivudine and Zidovudine', 'J05AR01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hematologic Toxicity and Lactic Acidosis", "severity": "High", "trigger_condition": "Development of severe anemia, neutropenia, or signs of lactic acidosis", "message": "Zidovudine is associated with hematologic toxicity (neutropenia and severe anemia). Both agents can cause lactic acidosis and severe hepatomegaly with steatosis, which may be fatal."}]', 'Monitor hematological parameters frequently (e.g., every 2 weeks for the first 3 months, then monthly) due to the risk of zidovudine-induced bone marrow suppression. Use with caution in patients with poor bone marrow reserve, renal impairment, or hepatic impairment. Patients with low body weight (<30 kg) should avoid the combined formulation. Withdraw treatment if symptomatic hyperlactatemia, metabolic/lactic acidosis, progressive hepatomegaly, or rapidly elevating aminotransferase levels occur. Exacerbations of Hepatitis B have been reported in co-infected patients upon discontinuation of lamivudine.', '- **HIV-1 Infection:** Treatment of HIV-1 infection in combination with other antiretroviral agents.', '- **Severe Bone Marrow Suppression:** Contraindicated in patients with abnormally low neutrophil counts (<0.75 x 10^9/L) or abnormally low hemoglobin levels (<7.5 g/dL or 4.65 mmol/L).
INSERT INTO "drug_generic" VALUES(1105, 'Tinidazole', 'Tinidazole', 'J01XD02', 1, 0, 0, 0, 1, 0, 1, 0, '[]', 'Monitor for signs of central nervous system toxicity, including seizures and peripheral neuropathy; discontinue promptly if abnormal neurologic signs develop.
INSERT INTO "drug_generic" VALUES(1106, 'Levodopa 200mg + Carbidopa 50mg + Entacapone 200mg', 'Levodopa, Carbidopa, and Entacapone', 'N04BA03', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Neuroleptic Malignant Syndrome (NMS)-like Symptoms", "severity": "High", "trigger_condition": "Abrupt withdrawal or rapid dose reduction", "message": "STOP: Abrupt discontinuation or rapid dose reduction can precipitate a symptom complex resembling Neuroleptic Malignant Syndrome (elevated temperature, muscular rigidity, altered consciousness, autonomic instability). Taper the dose gradually and monitor closely."}]', '**Somnolence and Sleep Attacks:** Patients may experience sudden onset of sleep during daily activities without warning signs. Caution patients about driving or operating machinery.
INSERT INTO "drug_generic" VALUES(1107, 'Iguratimod', 'Iguratimod', 'M01CX', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hepatotoxicity and Myelosuppression", "severity": "High", "trigger_condition": "Initiation of therapy and ongoing treatment", "message": "STOP: Regular monitoring of liver function tests and complete blood counts is mandatory. Severe hepatotoxicity and cytopenias can occur."}]', '**Hepatotoxicity:** Elevated liver enzymes are very common. Monitor liver function tests (ALT, AST, bilirubin) before starting and regularly during treatment. Discontinue if severe liver injury occurs.
INSERT INTO "drug_generic" VALUES(1108, 'Flucloxacillin', 'Floxacillin', 'J01CF05', 1, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity Risk", "severity": "High", "trigger_condition": "Prolonged use or use in elderly patients", "message": "STOP: Flucloxacillin is associated with a risk of severe hepatic dysfunction, including cholestatic jaundice, which may appear up to 2 months after treatment has stopped. Risk increases with age (>55 years) and duration of treatment (>14 days)."}, {"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}]', '- **Hepatotoxicity:** Can cause severe hepatitis and cholestatic jaundice. Monitor liver function tests if treatment exceeds 14 days. Use with extreme caution in the elderly and those with pre-existing hepatic impairment.
INSERT INTO "drug_generic" VALUES(1109, 'Misoprostol', 'Misoprostol', 'A02BB01, G02AD06', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Uterine Rupture and Abortion Risk", "severity": "High", "trigger_condition": "Use in pregnant women for gastrointestinal indications or inappropriate obstetric use", "message": "STOP: Misoprostol can cause birth defects, abortion, premature birth, or uterine rupture. Uterine rupture is highest in women with a history of prior cesarean section or uterine surgery. It is strictly contraindicated in pregnant women for ulcer prophylaxis."}]', 'Use with extreme caution in conditions where hypotension might precipitate severe complications (e.g., cerebrovascular disease, severe cardiovascular disease).
INSERT INTO "drug_generic" VALUES(1110, 'Betamethasone 0.05% + Gentamicin 0.1% E/E prep', 'Betamethasone and Gentamicin Ophthalmic/Otic', 'S01CA05', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Ophthalmic/Otic Use Only", "severity": "Low", "message": "For topical ophthalmic or otic use only. Do not inject."}, {"alert_type": "Tympanic Membrane Perforation", "severity": "High", "trigger_condition": "Otic use in patients with a perforated eardrum", "message": "STOP: Gentamicin is highly ototoxic. Do NOT use in the ear if the tympanic membrane (eardrum) is absent or perforated, as it can cause irreversible hearing loss."}]', '**Intraocular Pressure (IOP):** Prolonged ophthalmic use may increase IOP, leading to glaucoma and optic nerve damage. Monitor IOP if treatment lasts for >10 days.
INSERT INTO "drug_generic" VALUES(1111, 'Beta Carotene + Calcium + Cholecalciferol (Vit D3)', 'Beta Carotene, Calcium, and Cholecalciferol', 'A12AX', 0, 0, 1, 1, 1, 1, 0, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "Low", "message": "Excessive intake of Calcium and Vitamin D3 can lead to hypercalcemia and renal calculi. Do not exceed the recommended daily dosage."}]', '**Renal Impairment:** Use with caution in patients with mild to moderate renal failure. Calcium and fat-soluble vitamins can accumulate, leading to hypercalcemia and soft tissue calcification.
INSERT INTO "drug_generic" VALUES(1112, 'Ketotifen Eye prep', 'Ketotifen Ophthalmic', 'S01GX08', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Contact Lens Precaution", "severity": "Low", "trigger_condition": "Patient wearing soft contact lenses", "message": "Contains benzalkonium chloride. Remove contact lenses prior to instillation and wait at least 15 minutes before reinserting."}]', 'The eye drops contain benzalkonium chloride as a preservative, which can be absorbed by soft contact lenses and cause ocular irritation or discoloration of the lenses. Patients must remove contact lenses before instilling the drops and wait at least 15 minutes before reinsertion. Not indicated for the treatment of contact lens-related irritation. To prevent contamination of the dropper tip and solution, care should be taken not to touch the eyelids or surrounding areas with the dropper tip.', '- **Allergic Conjunctivitis:** Temporary prevention and relief of ocular itching associated with allergic conjunctivitis.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to ketotifen or to any of the excipients (e.g., benzalkonium chloride) in the preparation, due to the risk of localized or systemic allergic reactions.', '- **Ocular burning or stinging:** Transient discomfort immediately following instillation.
INSERT INTO "drug_generic" VALUES(1113, 'Amantadine Hydrochloride', 'Amantadine', 'N04BB01', 0, 0, 0, 0, 1, 1, 1, 1, '[{"alert_type": "Neuroleptic Malignant Syndrome (NMS)", "severity": "High", "trigger_condition": "Abrupt dosage reduction or withdrawal", "message": "STOP: Abrupt discontinuation can precipitate a fatal symptom complex resembling Neuroleptic Malignant Syndrome (hyperpyrexia, muscle rigidity, altered mental status). Taper the dose gradually."}, {"alert_type": "Suicidality and Psychosis", "severity": "High", "trigger_condition": "Patients with a history of psychiatric disorders", "message": "STOP: Amantadine can exacerbate mental problems, causing hallucinations, psychosis, and suicidal ideation. Monitor closely."}]', '**Cardiovascular Effects:** Congestive heart failure (CHF), peripheral edema, and orthostatic hypotension have been reported. Monitor patients with a history of CHF or edema.
INSERT INTO "drug_generic" VALUES(1114, 'Alteplase', 'Alteplase', 'B01AD02', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Severe Bleeding Risk", "severity": "High", "trigger_condition": "Administration in patients with active bleeding or high risk of intracranial hemorrhage", "message": "STOP: Alteplase can cause significant, sometimes fatal, internal or external bleeding. Exclude intracranial hemorrhage via imaging before treating acute ischemic stroke. Avoid intramuscular injections and unnecessary venipunctures."}]', 'Monitor closely for bleeding; discontinue therapy immediately if serious bleeding (not controllable by local pressure) occurs.
INSERT INTO "drug_generic" VALUES(1115, 'Dapsone topical', 'Dapsone topical', 'D10AX05', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Methemoglobinemia Risk", "severity": "High", "trigger_condition": "Patients presenting with cyanosis, shortness of breath, or fatigue", "message": "STOP: Cases of methemoglobinemia have been reported with topical dapsone. Discontinue immediately if signs of methemoglobinemia (blue lips/nail beds, hypoxia) occur."}]', '**Methemoglobinemia:** Cases of methemoglobinemia have been reported. Discontinue therapy immediately if signs of methemoglobinemia (e.g., cyanosis, headache, fatigue, tachycardia) occur.
INSERT INTO "drug_generic" VALUES(1116, 'Lynestrenol', 'Lynestrenol', 'G03DC03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "History of deep vein thrombosis, pulmonary embolism, or severe arterial disease", "message": "STOP: Progestogens are associated with an increased risk of venous and arterial thromboembolic events. Discontinue immediately if a thromboembolic event occurs or is suspected."}]', '**Cardiovascular and Renal Dysfunction:** May cause fluid retention; use with caution in patients with conditions that might be aggravated by fluid retention (e.g., asthma, epilepsy, migraine, hypertension, cardiac or renal dysfunction).
INSERT INTO "drug_generic" VALUES(1117, 'Immune Serum Globulin Human', 'Immune Globulin (Human)', 'J06BA01', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Renal Dysfunction and Acute Renal Failure", "severity": "High", "trigger_condition": "Patients with pre-existing renal impairment, diabetes mellitus, age >65 years, volume depletion, or concurrent nephrotoxic drug use", "message": "STOP: Immune globulin intravenous (IGIV) products have been associated with renal dysfunction, acute renal failure, osmotic nephrosis, and death. Administer at the minimum concentration available and the minimum rate of infusion practicable."}, {"alert_type": "Thrombosis", "severity": "High", "trigger_condition": "Patients with advanced age, prolonged immobilization, hypercoagulable conditions, history of venous or arterial thrombosis, use of estrogens, indwelling central vascular catheters, hyperviscosity, or cardiovascular risk factors", "message": "STOP: Thrombosis may occur with immune globulin products. For patients at risk, administer at the minimum concentration available and the minimum rate of infusion practicable. Ensure adequate hydration before administration."}]', '**Renal Dysfunction:** Increased risk of acute renal failure, particularly in patients with pre-existing renal impairment, diabetes mellitus, hypovolemia, overweight status, concomitant nephrotoxic medicinal products, or age >65 years. Ensure adequate hydration prior to IV infusion. Monitor urine output and serum creatinine levels closely during treatment. Avoid concurrent use of loop diuretics during IV infusion.
INSERT INTO "drug_generic" VALUES(1118, 'Tirzepatide', 'Tirzepatide', 'A10BX16', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Thyroid C-cell Tumors Risk", "severity": "High", "trigger_condition": "Personal or family history of Medullary Thyroid Carcinoma (MTC) or Multiple Endocrine Neoplasia syndrome type 2 (MEN 2)", "message": "STOP: Contraindicated in patients with a personal or family history of MTC or MEN 2 due to the risk of thyroid C-cell tumors."}]', '**Acute Pancreatitis:** Fatal and non-fatal hemorrhagic or necrotizing pancreatitis has been observed. Monitor for signs and symptoms (e.g., persistent severe abdominal pain radiating to the back). Discontinue if suspected and do not restart if confirmed.
INSERT INTO "drug_generic" VALUES(1119, 'Ibandronic acid+ Calcium Orotate', 'Ibandronate and Calcium Orotate', 'M05BB03', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Upper Gastrointestinal Irritation", "severity": "High", "trigger_condition": "Improper administration technique or pre-existing esophageal disease", "message": "STOP: Ibandronic acid can cause severe esophageal irritation, esophagitis, and ulcers. Patients MUST stand or sit upright for at least 60 minutes after taking the dose."}]', '**Upper Gastrointestinal Adverse Reactions:** Ibandronic acid can cause severe local irritation of the upper gastrointestinal mucosa, leading to esophagitis, esophageal ulcers, and erosions. Use with extreme caution in patients with active upper GI problems (e.g., Barrett''s esophagus, dysphagia, gastritis, ulcers). Strict adherence to administration instructions is mandatory.
INSERT INTO "drug_generic" VALUES(1120, 'Flibanserin', 'Flibanserin', 'G02CX02', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Hypotension and Syncope", "severity": "High", "trigger_condition": "Coadministration with alcohol or CYP3A4 inhibitors", "message": "STOP: Coadministration with alcohol or moderate/strong CYP3A4 inhibitors significantly increases the risk of severe hypotension and syncope. Use is contraindicated in these scenarios."}]', '**Hypotension and Syncope:** Flibanserin alone can cause significant hypotension and syncope. The risk is highly amplified when taken during waking hours, with alcohol, or with CYP3A4 inhibitors. Strict adherence to bedtime dosing is required.
INSERT INTO "drug_generic" VALUES(1121, 'Moxonidine', 'Moxonidine', 'C02AC05', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Withdrawal Risk", "severity": "High", "trigger_condition": "Abrupt discontinuation of therapy", "message": "WARNING: Avoid abrupt withdrawal. Rebound hypertension can occur. If discontinuing concurrent beta-blocker therapy, stop the beta-blocker first, then gradually taper moxonidine over several days."}]', '**Renal Impairment:** Use with caution; dosage reduction is required in moderate to severe renal impairment.
INSERT INTO "drug_generic" VALUES(1122, 'Bupivacaine', 'Bupivacaine', 'N01BB01', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiac Arrest with Obstetrical Epidural Anesthesia", "severity": "High", "trigger_condition": "Use of 0.75% concentration in obstetrical patients", "message": "WARNING: Cardiac arrest with difficult resuscitation or death has occurred during epidural anesthesia in obstetrical patients using the 0.75% concentration. The 0.75% concentration is CONTRAINDICATED for obstetrical anesthesia."}, {"alert_type": "Intravascular Injection Toxicity", "severity": "High", "trigger_condition": "Unintended intravascular injection", "message": "WARNING: Unintended intravascular injection may cause severe systemic toxicity, including seizures, cardiac arrhythmias, and cardiac arrest. Always aspirate prior to injection."}]', 'Monitor cardiovascular and respiratory vital signs and the patient''s state of consciousness continuously after injection. Have resuscitative equipment, oxygen, and drugs immediately available.
INSERT INTO "drug_generic" VALUES(1123, 'Hepatitis A Vaccine (HAV Antigen)', 'Hepatitis A Vaccine, Inactivated', 'J07BC02', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe allergic reaction to a previous dose or vaccine component", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, can occur. Ensure epinephrine and emergency equipment are immediately available."}]', '**Acute Illness:** Defer vaccination in individuals suffering from moderate to severe acute febrile illness until recovery.
INSERT INTO "drug_generic" VALUES(1124, 'Isotretinoin', 'Isotretinoin', 'D10BA01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Teratogenicity", "severity": "High", "trigger_condition": "Prescribing to females of childbearing potential", "message": "STOP: Isotretinoin is a potent teratogen. It must not be used by females who are pregnant or may become pregnant. Strict adherence to pregnancy prevention programs (e.g., iPLEDGE) is mandatory, requiring two forms of contraception and regular pregnancy testing."}]', '- **Psychiatric Disorders:** Depression, psychosis, suicidal ideation, and aggressive behavior have been reported. Monitor patients closely for psychiatric symptoms and discontinue therapy if they occur.
INSERT INTO "drug_generic" VALUES(1125, 'Ferrous Fumarate', 'Ferrous Fumarate', 'B03AA02', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Fatal Poisoning in Children", "severity": "High", "trigger_condition": "Accidental ingestion by children under 6 years of age", "message": "WARNING: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Gastrointestinal Conditions:** Use with caution in patients with intestinal strictures, diverticular disease, peptic ulcer disease, or inflammatory bowel disease, as oral iron may exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1126, 'Siponimod', 'Siponimod', 'L04AE03', 0, 1, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Cardiac Conduction Abnormalities", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "STOP: Siponimod causes a transient decrease in heart rate and AV conduction delays. Obtain a baseline ECG. Contraindicated in patients with recent cardiovascular events or severe AV blocks without a pacemaker."}]', '**Macular Edema:** Can occur, mostly within the first 4 months. Ophthalmic evaluation is recommended at baseline and if visual disturbances occur.
INSERT INTO "drug_generic" VALUES(1127, 'Obeticholic Acid', 'Obeticholic Acid', 'A05AA04', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatic Decompensation and Failure", "severity": "High", "trigger_condition": "Patients with decompensated cirrhosis or Child-Pugh Class B/C", "message": "STOP: Fatal hepatic decompensation and failure have been reported in patients with decompensated cirrhosis or Child-Pugh Class B or C hepatic impairment when dosed more frequently than the recommended starting dosage of 5 mg once weekly. Strict adherence to dosing guidelines is mandatory."}]', '**Hepatic Decompensation:** Monitor patients closely for clinical and laboratory evidence of worsening liver function (e.g., ascites, jaundice, variceal bleeding, worsening renal function). Discontinue therapy if severe hepatic injury or decompensation occurs.
INSERT INTO "drug_generic" VALUES(1128, 'Cetirizine eye prep', 'Cetirizine ophthalmic', 'S01GX12', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Contamination Risk:** To prevent contaminating the dropper tip and solution, patients must be advised not to touch the eyelids or surrounding areas with the dropper tip of the bottle or the tip of the single-use container. The bottle must be kept tightly closed when not in use.
INSERT INTO "drug_generic" VALUES(1129, 'Elvitegravir + Cobicistat + Emtricitabine +Tenofovir alafenamide', 'Elvitegravir/Cobicistat/Emtricitabine/Tenofovir alafenamide', 'J05AR18', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Post-Treatment Acute Exacerbation of Hepatitis B", "severity": "High", "trigger_condition": "Discontinuation of therapy in patients co-infected with HIV-1 and HBV", "message": "Severe acute exacerbations of hepatitis B have been reported in patients who are co-infected with HIV-1 and HBV and have discontinued products containing emtricitabine and/or tenofovir. Monitor hepatic function closely."}]', '**Post-Treatment Acute Exacerbation of Hepatitis B:** Severe acute exacerbations of hepatitis B have been reported in patients who are co-infected with HIV-1 and HBV and have discontinued products containing emtricitabine and/or tenofovir. Closely monitor hepatic function with both clinical and laboratory follow-up for at least several months in patients who are co-infected with HIV-1 and HBV and discontinue this medication. If appropriate, initiation of anti-hepatitis B therapy may be warranted.
INSERT INTO "drug_generic" VALUES(1130, 'Timolol Maleate 0.5% + Travoprost 0.004% Eye prep', 'Timolol and Travoprost Ophthalmic', 'S01ED51', 0, 0, 0, 0, 0, 1, 0, 0, '[]', 'Travoprost may gradually change eye color by increasing the amount of brown pigment in the iris; this change may be permanent.
INSERT INTO "drug_generic" VALUES(1131, 'Etoposide', 'Etoposide', 'L01CB01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Administration of etoposide", "message": "STOP: Etoposide can cause severe myelosuppression (leukopenia, neutropenia, thrombocytopenia) resulting in fatal infections and bleeding. Monitor complete blood counts frequently prior to each cycle and during therapy."}]', '**Myelosuppression:** Dose-limiting bone marrow suppression is the most significant toxicity. Do not administer if neutrophil count is <1,500/mm3 or platelet count is <100,000/mm3.
INSERT INTO "drug_generic" VALUES(1132, 'Faricimab', 'Faricimab-svoa', 'S01LA09', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Endophthalmitis and Retinal Detachment", "severity": "High", "trigger_condition": "Following intravitreal injection", "message": "STOP: Intravitreal injections have been associated with endophthalmitis and retinal detachments. Proper aseptic injection technique must always be used. Instruct patients to report any symptoms suggestive of endophthalmitis or retinal detachment without delay."}]', '**Endophthalmitis and Retinal Detachments:** Intravitreal injections, including those with faricimab, have been associated with endophthalmitis and retinal detachments. Proper aseptic injection technique must always be used when administering the drug. Patients should be instructed to report any symptoms suggestive of endophthalmitis or retinal detachment without delay to permit prompt and appropriate management.
INSERT INTO "drug_generic" VALUES(1133, 'Omega-3 fatty acids', 'Omega-3-acid ethyl esters', 'C10AX06', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Bleeding Risk", "severity": "Moderate", "trigger_condition": "Concomitant use with anticoagulants or in patients with hemorrhagic disorders", "message": "Omega-3 fatty acids can prolong bleeding time. Monitor patients receiving anticoagulants or those with hemorrhagic disorders closely."}]', '**Hepatic Impairment:** Monitor hepatic function (ALT and AST) periodically in patients with hepatic impairment, especially if receiving high doses.
INSERT INTO "drug_generic" VALUES(1134, 'Hydroxyprogesterone Caproate', 'Hydroxyprogesterone Caproate', 'G03DA03', 0, 0, 1, 0, 1, 0, 0, 0, '[{"alert_type": "Thromboembolic Disorders", "severity": "High", "trigger_condition": "History or presence of thromboembolic disease", "message": "STOP: Discontinue treatment if an arterial or deep venous thrombotic or thromboembolic event occurs. Use is contraindicated in patients with a history of these conditions."}]', '**Thromboembolic Disorders:** Discontinue if signs of deep vein thrombosis, pulmonary embolism, cerebrovascular disease, or retinal thrombosis occur.
INSERT INTO "drug_generic" VALUES(1135, 'Acitretin', 'Acitretin', 'D05BB02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Teratogenicity", "severity": "High", "trigger_condition": "Prescribing to a female of childbearing potential", "message": "STOP: Acitretin causes severe birth defects. Pregnancy must be excluded before starting. Effective contraception must be used during therapy and for AT LEAST 3 YEARS after discontinuation."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated liver enzymes or clinical signs of hepatitis", "message": "STOP: Severe hepatotoxicity, including fatal cases, has been reported. Monitor LFTs regularly."}]', '**Teratogenicity:** Extremely high risk of severe birth defects. Females of childbearing potential must participate in a strict pregnancy prevention program (e.g., Do Your P.A.R.T.). Two forms of effective contraception are required.
INSERT INTO "drug_generic" VALUES(1136, 'Capreomycin', 'Capreomycin', 'J04AB30', 1, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Nephrotoxicity and Ototoxicity", "severity": "High", "trigger_condition": "Concurrent use with other nephrotoxic/ototoxic drugs or pre-existing renal impairment", "message": "STOP: Capreomycin carries a high risk of severe renal injury and permanent cranial nerve VIII damage (hearing loss/vestibular dysfunction). Baseline and regular monitoring of renal function and audiometry are mandatory."}]', 'Reserve capreomycin for patients with multidrug-resistant tuberculosis (MDR-TB) who have limited treatment options, as its use has been associated with worse clinical outcomes (decreased effectiveness, increased mortality) compared to other parenteral therapies. Use with extreme caution in patients with pre-existing renal or auditory impairment; weigh the risk of additional cranial nerve VIII or kidney damage against the benefits. Concomitant use with other IV antituberculosis agents (e.g., streptomycin) or nephrotoxic/ototoxic drugs (e.g., aminoglycosides, polymyxins, vancomycin) is strongly discouraged. Monitor for hypokalemia, hypocalcemia, and hypomagnesemia. Perform baseline and regular audiometric, vestibular, and renal function tests (BUN, serum creatinine, urine sediment) throughout therapy. A partial neuromuscular blockade has been demonstrated; use caution during anesthesia or with neuromuscular blocking agents.', '- **Tuberculosis (MDR-TB):** Indicated as a second-line agent for the treatment of pulmonary infections caused by capreomycin-susceptible strains of *Mycobacterium tuberculosis*. It is used in combination with other antituberculosis agents when primary agents (isoniazid, rifampin, ethambutol, pyrazinamide, streptomycin) have been ineffective or cannot be used due to toxicity or resistance.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to capreomycin. Rationale: Risk of severe allergic reactions.
INSERT INTO "drug_generic" VALUES(1137, 'Iron (III)-Hydroxide Dextran Complex', 'Iron Dextran', 'B03AC06', 0, 1, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Fatal Anaphylactic Reactions", "severity": "High", "trigger_condition": "Administration of parenteral iron dextran", "message": "STOP: Severe, potentially fatal anaphylactic/anaphylactoid reactions have occurred. A test dose MUST be administered prior to the first therapeutic dose. Observe the patient for at least 1 hour after the test dose. Resuscitation equipment must be immediately available."}]', '- **Hypersensitivity:** The risk of anaphylaxis is increased in patients with a history of multiple drug allergies, severe asthma, eczema, or other atopic allergies. Reactions can occur even if previous doses were tolerated.
INSERT INTO "drug_generic" VALUES(1138, 'Benzalkonium Chloride + Chlorhexidine + Isopropyl Myristate + Liquid Paraffin topical', 'Benzalkonium Chloride, Chlorhexidine, Isopropyl Myristate, and Liquid Paraffin', 'D02AX', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "External Use Only", "severity": "Low", "trigger_condition": "Application near eyes or mucous membranes", "message": "For external use only. Avoid contact with the eyes. Do not swallow."}]', '**Application Site Reactions:** In rare cases, local skin reactions (redness, irritation, itching) may occur. Discontinue use if the skin condition worsens or if hypersensitivity develops.
INSERT INTO "drug_generic" VALUES(1139, 'Elagolix sodium', 'Elagolix', 'H01CC03', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Suicidal Ideation and Hepatic Injury", "severity": "High", "trigger_condition": "Patients with a history of depression or hepatic impairment", "message": "STOP: Suicidal ideation and behavior have occurred. Promptly evaluate patients with depressive symptoms. Dose-dependent elevations of ALT >3x ULN have also occurred; instruct patients to seek medical attention for signs of liver injury."}]', 'May reduce the amount, intensity, or duration of menstrual bleeding, which may decrease the ability to recognize the occurrence of a pregnancy in a timely manner; perform pregnancy testing if pregnancy is suspected, and discontinue the drug if pregnancy is confirmed.
INSERT INTO "drug_generic" VALUES(1140, 'Mefloquine', 'Mefloquine', 'P01BC02', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Neuropsychiatric Adverse Reactions", "severity": "High", "trigger_condition": "Prophylactic or therapeutic use", "message": "STOP: Mefloquine may cause severe neuropsychiatric adverse reactions, including suicidal ideation, paranoia, hallucinations, and depression. Discontinue immediately if psychiatric or neurologic symptoms occur during prophylaxis."}]', '**Neuropsychiatric Effects:** Can cause severe psychiatric symptoms (anxiety, paranoia, depression, hallucinations, psychosis) and neurologic symptoms (dizziness, vertigo, tinnitus, loss of balance). These symptoms may persist long after the drug is discontinued. Avoid driving or operating machinery during and up to 3 weeks after use.
INSERT INTO "drug_generic" VALUES(1141, 'Loteprednol Etabonate 0.5% + Tobramycin 0.3% Eye prep', 'Loteprednol Etabonate and Tobramycin', 'S01CA12', 1, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Ocular Toxicity and Immunosuppression", "severity": "High", "trigger_condition": "Prolonged use beyond 10 days", "message": "STOP: Prolonged use of ophthalmic corticosteroids may result in glaucoma, optic nerve damage, visual acuity defects, and secondary ocular infections. Routine monitoring of intraocular pressure (IOP) is mandatory."}]', '**Intraocular Pressure (IOP) Elevation:** Prolonged use may result in ocular hypertension or glaucoma; monitor IOP routinely if used for more than 10 days.
INSERT INTO "drug_generic" VALUES(1142, 'Trimetazidine', 'Trimetazidine', 'C01EB15', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Neurological Risk", "severity": "High", "trigger_condition": "Patients with Parkinson disease or movement disorders", "message": "STOP: Trimetazidine can cause or worsen parkinsonian symptoms (tremor, akinesia, hypertonia). Discontinue immediately if movement disorders develop."}]', '**Renal Impairment:** Use with caution and reduce dose in moderate renal impairment (CrCl 30-60 mL/min).
INSERT INTO "drug_generic" VALUES(1143, 'Alogliptin', 'Alogliptin', 'A10BH04', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Pancreatitis and Hypersensitivity", "severity": "High", "trigger_condition": "Onset of severe abdominal pain or signs of anaphylaxis/severe skin reactions", "message": "STOP: Postmarketing reports indicate risks of acute pancreatitis and severe hypersensitivity reactions (anaphylaxis, angioedema, Stevens-Johnson syndrome). Discontinue immediately if suspected."}]', '**Acute Pancreatitis:** Postmarketing reports of acute pancreatitis exist. If pancreatitis is suspected (severe, persistent abdominal pain radiating to the back), promptly discontinue therapy.
INSERT INTO "drug_generic" VALUES(1144, 'Phenylephrine 0.12% + Tetryzoline Hydrochloride 0.04% + Zinc Sulphate 0.1% Eye prep', 'Phenylephrine / Tetrahydrozoline / Zinc Sulfate Ophthalmic', 'S01GA55', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Glaucoma Risk", "severity": "High", "trigger_condition": "Patient with narrow-angle glaucoma", "message": "STOP: Sympathomimetics can induce mydriasis and precipitate an acute angle-closure glaucoma crisis. Contraindicated in narrow-angle glaucoma."}]', '**Rebound Congestion:** Overuse or prolonged use (typically >72 hours) may result in rebound conjunctival hyperemia (redness) and worsening of symptoms.
INSERT INTO "drug_generic" VALUES(1145, 'Povidone 5%  Eye prep', 'Povidone-Iodine Ophthalmic', 'S01AX18', 1, 0, 0, 0, 1, 1, 0, 0, '[]', 'Patients experiencing blurred vision after application should refrain from driving or operating machinery until vision clears. Contact lenses must be removed prior to instillation and should not be reinserted for at least 30 minutes. Prolonged use may lead to systemic iodine absorption, potentially altering thyroid function. Exercise caution in patients with pre-existing renal insufficiency or those on concurrent lithium therapy.', '- **Pre-operative Ocular Antisepsis:** Used to prep the periocular region and conjunctiva prior to ophthalmic surgery.
INSERT INTO "drug_generic" VALUES(1146, 'Dextromethorphan + Diphenhydramine + Levomenthol', 'Dextromethorphan/Diphenhydramine/Levomenthol', 'R05DA20', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Serotonin Syndrome Risk", "severity": "High", "trigger_condition": "Concomitant use with MAOIs", "message": "Contraindicated in patients taking MAOIs or within 14 days of stopping MAOIs due to the risk of severe serotonin syndrome (hyperpyrexia, hallucinations, coma)."}]', '**CNS Depression:** This product may cause drowsiness and impair cognitive function. Patients should be cautioned against driving or operating heavy machinery if affected. The effects of alcohol and other CNS depressants may be potentiated.
INSERT INTO "drug_generic" VALUES(1147, 'Tiotropium', 'Tiotropium Bromide', 'R03BB04', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Not for Acute Bronchospasm", "severity": "High", "trigger_condition": "Patient experiencing acute asthma or COPD exacerbation", "message": "STOP: Tiotropium is a maintenance medication and is NOT intended for the initial treatment of acute episodes of bronchospasm (i.e., rescue therapy). Use a short-acting beta2-agonist for acute symptoms."}]', 'Do not use as rescue therapy for acute bronchospasm.
INSERT INTO "drug_generic" VALUES(1148, 'Propofol', 'Propofol', 'N01AX10', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Propofol Infusion Syndrome (PRIS)", "severity": "High", "trigger_condition": "Prolonged infusion (>48 hours) or high doses (>4 mg/kg/hr)", "message": "WARNING: PRIS is a rare but potentially fatal complication characterized by severe metabolic acidosis, hyperkalemia, lipemia, rhabdomyolysis, hepatomegaly, and cardiac failure. Monitor closely and avoid high doses for prolonged periods."}, {"alert_type": "Respiratory and Cardiovascular Depression", "severity": "High", "trigger_condition": "Administration of propofol", "message": "STOP: Propofol must only be administered by personnel trained in the administration of general anesthesia. Facilities for maintenance of a patent airway, artificial ventilation, and oxygen enrichment must be immediately available."}]', '- **Cardiovascular/Respiratory:** Can cause profound hypotension and apnea. Use with caution in elderly, debilitated, or ASA III/IV patients; reduce induction dose and administer slowly.
INSERT INTO "drug_generic" VALUES(1149, 'Glimepiride + Metformin', 'Glimepiride and Metformin', 'A10BD02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Lactic Acidosis", "severity": "High", "trigger_condition": "Renal impairment, sepsis, hypoxia, or excessive alcohol intake", "message": "STOP: Metformin accumulation can cause fatal lactic acidosis. Discontinue immediately if metabolic acidosis is suspected."}, {"alert_type": "Severe Hypoglycemia", "severity": "High", "trigger_condition": "Skipped meals, excessive exercise, or concurrent use of other hypoglycemic agents", "message": "WARNING: Glimepiride can cause severe, prolonged hypoglycemia. Monitor blood glucose closely, especially in the elderly or renally impaired."}]', 'Assess renal function (eGFR) prior to initiation and at least annually thereafter. More frequent monitoring is required in the elderly or those at risk of renal impairment.
INSERT INTO "drug_generic" VALUES(1150, 'Osimertinib', 'Osimertinib', 'L01EB04', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Interstitial Lung Disease (ILD) / Pneumonitis", "severity": "High", "trigger_condition": "Onset of acute or worsening respiratory symptoms (dyspnea, cough, fever)", "message": "STOP: Permanently discontinue if ILD/pneumonitis is confirmed. Severe, life-threatening, and fatal cases have occurred."}, {"alert_type": "QTc Interval Prolongation", "severity": "High", "trigger_condition": "Patients with congenital long QT syndrome or taking QTc-prolonging medications", "message": "WARNING: Monitor ECG and electrolytes periodically. Withhold, reduce dose, or permanently discontinue based on severity of QTc prolongation."}]', 'Determine EGFR mutation status prior to initiating treatment using a validated test.
INSERT INTO "drug_generic" VALUES(1151, 'Aluminium Hydroxide + Magnesium Hydroxide + Simethicon', 'Aluminum Hydroxide, Magnesium Hydroxide, and Simethicone', 'A02AF02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Drug Interactions", "severity": "Medium", "trigger_condition": "Concurrent administration with other oral medications", "message": "STOP: Antacids significantly decrease the absorption of many drugs (e.g., tetracyclines, fluoroquinolones, bisphosphonates, thyroid hormones). Administer antacids at least 2 hours before or after other medications."}]', '**Renal Impairment:** Use with caution in patients with chronic renal impairment. Magnesium and aluminum can accumulate, leading to hypermagnesemia (muscle weakness, hypotension) and aluminum toxicity (encephalopathy, osteomalacia).
INSERT INTO "drug_generic" VALUES(1152, 'Lebikizumab', 'Lebrikizumab', 'L04AC23', 0, 0, 0, 0, 0, 0, 1, 0, '[]', '**Hypersensitivity Reactions:** If a systemic hypersensitivity reaction (immediate or delayed) occurs, discontinue administration of lebrikizumab immediately and initiate appropriate medical therapy.
INSERT INTO "drug_generic" VALUES(1153, 'Mepivacaine', 'Mepivacaine', 'N01BB03', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Systemic Toxicity and Methemoglobinemia", "severity": "High", "trigger_condition": "Intravascular injection, excessive dosing, or use in susceptible patients", "message": "STOP: Unintentional intravascular injection may result in severe CNS toxicity, seizures, and cardiac arrest. Use of local anesthetics may cause methemoglobinemia, a serious and potentially fatal condition requiring immediate treatment."}]', '**Systemic Toxicity:** Monitor the patient''s state of consciousness and cardiovascular status continuously following injection. Signs of central nervous system (CNS) toxicity include anxiety, dizziness, restlessness, tremors, depression, blurred vision, and seizures. Unintentional intravascular injection may result in immediate and severe toxicity, including respiratory arrest.
INSERT INTO "drug_generic" VALUES(1154, 'Guaifenesin', 'Guaifenesin', 'R05CA03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Chronic Cough Warning", "severity": "Moderate", "trigger_condition": "Use for chronic or persistent cough", "message": "Do not use for persistent or chronic cough such as occurs with smoking, asthma, chronic bronchitis, or emphysema, or where cough is accompanied by excessive phlegm, unless directed by a doctor."}]', '**Hydration:** Efficacy is highly dependent on adequate patient hydration. Advise patients to drink plenty of fluids while taking this medication to help loosen mucus.
INSERT INTO "drug_generic" VALUES(1155, 'Boric Acid 2% + Dithranol 0.1% + Salicylic Acid 1% topical', 'Anthralin / Salicylic Acid / Boric Acid', 'D05AC51', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '**Skin and Fabric Staining:** Dithranol (anthralin) permanently stains fabrics, clothing, and temporarily stains skin and hair. Use with caution and advise patients accordingly.
INSERT INTO "drug_generic" VALUES(1156, 'Clotrimazole Topical', 'Clotrimazole topical', 'D01AC01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Neonatal Toxicity", "severity": "High", "trigger_condition": "Use of formulations containing benzyl alcohol in neonates", "message": "WARNING: Some dosage forms contain benzyl alcohol. Large amounts of benzyl alcohol have been associated with potentially fatal ''gasping syndrome'' in neonates."}]', '**Ocular Exposure:** Avoid contact with the eyes. Not for ophthalmic use.
INSERT INTO "drug_generic" VALUES(1157, 'Albumin Human 25%', 'Albumin Human', 'B05AA01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Hypervolemia Risk", "severity": "High", "trigger_condition": "Rapid infusion or administration to patients with cardiac failure", "message": "STOP: 25% Albumin is highly hyperoncotic. Rapid infusion or excessive volume can cause severe hypervolemia, leading to acute pulmonary edema and cardiovascular overload. Monitor hemodynamics closely."}]', '**Hypervolemia and Hemodilution:** Use with extreme caution in patients at risk of hypervolemia. Stop infusion if signs of cardiovascular overload occur. Ensure adequate hydration of the patient when administering concentrated albumin.
INSERT INTO "drug_generic" VALUES(1158, 'Amorolfine topical', 'Amorolfine', 'D01AE16', 1, 0, 0, 0, 0, 1, 0, 0, '[]', 'Avoid contact with eyes, ears, and mucous membranes. Do not apply to the skin immediately surrounding the nail when using the nail lacquer.
INSERT INTO "drug_generic" VALUES(1159, 'Macrogol + Electrolytes (Potassium Chloride  + Sodium Bicarbonate  + Sodium Chloride)', 'Polyethylene Glycol 3350 with Electrolytes', 'A06AD65', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Fluid and Electrolyte Imbalance", "severity": "Moderate", "trigger_condition": "Patients with severe renal impairment or congestive heart failure", "message": "Monitor for signs of fluid shifts or electrolyte disturbances. Discontinue immediately if symptoms of dehydration or electrolyte imbalance occur."}]', 'Use with extreme caution in patients with an impaired gag reflex, reflux esophagitis, or impaired consciousness due to the risk of aspiration. Monitor closely for signs of fluid or electrolyte disturbances, particularly in vulnerable populations such as the elderly or those with severe renal impairment. Discontinue therapy immediately if symptoms of fluid or electrolyte shifts (e.g., edema, shortness of breath, increasing fatigue, dehydration, or cardiac arrhythmias) develop. Evaluate patients with symptoms suggestive of bowel obstruction (nausea, vomiting, abdominal pain, or distension) prior to initiating therapy to rule out structural abnormalities.', '- Treatment of acute and chronic constipation.
INSERT INTO "drug_generic" VALUES(1160, 'Hypromellose 2% Eye prep', 'Hypromellose Intraocular', 'S01KA02', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Intraocular Pressure Elevation", "severity": "Moderate", "trigger_condition": "Failure to remove viscoelastic substance post-surgery", "message": "STOP: Transient increases in intraocular pressure (IOP) may occur postoperatively. Ensure complete removal of the product by irrigation and/or aspiration at the end of the surgical procedure."}]', 'Strict aseptic technique must be maintained during use to ensure the sterility of the product.
INSERT INTO "drug_generic" VALUES(1161, 'Pilocarpine Hydrochloride 1% Eye prep', 'Pilocarpine Hydrochloride', 'S01EB01', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '**Visual Disturbances:** May cause blurred vision and difficulty with dark adaptation; advise patients to exercise caution when driving at night or performing hazardous tasks in poor illumination.
INSERT INTO "drug_generic" VALUES(1162, 'Paroxetine', 'Paroxetine', 'N06AB05', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Suicidality Risk", "severity": "High", "trigger_condition": "Initiation of therapy or dose changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults (up to age 24). Closely monitor for clinical worsening, suicidality, or unusual changes in behavior."}]', '**Clinical Worsening and Suicide Risk:** Monitor closely for clinical worsening, suicidality, and unusual changes in behavior, especially during the first few months of therapy or at times of dose changes.
INSERT INTO "drug_generic" VALUES(1163, 'Ephedrine Hydrochloride', 'Ephedrine Hydrochloride', 'R03CA02', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Cardiovascular Collapse", "severity": "High", "trigger_condition": "Overdosage or concurrent MAOI use", "message": "STOP: Severe hypertension, arrhythmias, and fatal cardiovascular collapse can occur. Do not use within 14 days of MAOI therapy."}]', '- **Cardiovascular Disease:** Use with extreme caution in patients with ischemic heart disease, hypertension, or arrhythmias, as it increases cardiac workload and oxygen demand.
INSERT INTO "drug_generic" VALUES(1164, 'Idoxuridine 0.1% Eye prep', 'Idoxuridine Ophthalmic', 'S01AD01', 1, 0, 0, 0, 0, 1, 1, 0, '[]', 'Use with extreme caution in patients with deep ulceration of the stromal layers of the cornea, as idoxuridine may delay healing and increase the risk of corneal perforation.
INSERT INTO "drug_generic" VALUES(1165, 'Roxadustat', 'Roxadustat', 'B03XA05', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Mortality and Thrombotic Events", "severity": "High", "trigger_condition": "Rapid rise in hemoglobin or target Hb >12 g/dL", "message": "STOP: Roxadustat increases the risk of cardiovascular death, myocardial infarction, stroke, and venous thromboembolism. Do not target Hb >12 g/dL. Monitor closely for signs of deep vein thrombosis or pulmonary embolism."}]', '**Thrombotic Vascular Events (TVEs):** High risk of deep vein thrombosis (DVT), pulmonary embolism (PE), and vascular access thrombosis (VAT). Weigh risks against benefits, especially in patients with pre-existing risk factors (e.g., obesity, prior TVE). Avoid Hb levels >12 g/dL and Hb rise >2 g/dL over 4 weeks.
INSERT INTO "drug_generic" VALUES(1166, 'Cefditoren', 'Cefditoren', 'J01DD16', 1, 0, 1, 1, 1, 1, 0, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}, {"alert_type": "Carnitine Deficiency", "severity": "High", "trigger_condition": "Patients with primary carnitine deficiency or inborn errors of metabolism", "message": "STOP: Cefditoren pivoxil causes renal excretion of carnitine. It is contraindicated in patients with carnitine deficiency. Prolonged use is not recommended due to the risk of clinically significant carnitine depletion."}]', '**Milk Protein Hypersensitivity:** Cefditoren tablets contain sodium caseinate, a milk protein. Patients with milk protein hypersensitivity (not lactose intolerance) may have allergic reactions and should not receive this drug.
INSERT INTO "drug_generic" VALUES(1167, 'Peppermint Oil', 'Peppermint Oil', 'A03AX15', 0, 0, 0, 0, 0, 0, 0, 0, '[]', '- **Hiatal Hernia and GERD:** Use with caution in patients with hiatal hernia or gastroesophageal reflux disease (GERD), as relaxation of the lower esophageal sphincter can exacerbate heartburn and reflux symptoms.
INSERT INTO "drug_generic" VALUES(1168, 'Sertaconazole vaginal prep', 'Sertaconazole', 'G01AF19', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Contraceptive Failure", "severity": "Medium", "trigger_condition": "Concurrent use of latex condoms or diaphragms", "message": "WARNING: Excipients may damage latex contraceptives (condoms/diaphragms), leading to failure. Avoid concurrent use."}]', '**Hygiene and Recurrence:** Upon confirmation of diagnosis, investigate etiological factors causing the infection. Counsel patients to avoid future recurrence by practicing good personal hygiene, wearing cotton underclothes, and avoiding vaginal douches. Use neutral or alkaline pH soaps for washing outer genitals, as lower pH favors candidiasis.
INSERT INTO "drug_generic" VALUES(1169, 'Paricalcitol', 'Paricalcitol', 'H05BX02', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "High", "trigger_condition": "Calcium x Phosphorus product > 75 mg2/dL2 or elevated serum calcium", "message": "STOP: Excessive administration can cause oversuppression of PTH, hypercalcemia, hypercalciuria, and hyperphosphatemia. Monitor serum calcium and phosphorus frequently. Reduce dose or interrupt therapy if the Ca x P product exceeds 75."}]', '**Hypercalcemia and Hyperphosphatemia:** Paricalcitol can cause elevated calcium and phosphorus levels. Monitor serum calcium, phosphorus, and intact PTH (iPTH) frequently during initiation and dose titration. Reduce the dose or interrupt therapy if hypercalcemia occurs or if the calcium-phosphorus (Ca x P) product exceeds 75 mg2/dL2.
INSERT INTO "drug_generic" VALUES(1170, 'Miconazole vaginal prep', 'Miconazole', 'G01AF04', 0, 0, 0, 1, 0, 1, 0, 0, '[]', 'Exercise caution in patients with a known hypersensitivity to other azole antifungals due to the potential for cross-reactivity. Vaginal preparations contain ingredients that may damage latex products, such as condoms and diaphragms, reducing their efficacy as barrier contraceptives or protection against sexually transmitted infections. Avoid contact with the eyes. If severe irritation, sensitization, or worsening of symptoms occurs, discontinue use immediately. Patients experiencing recurrent infections should be evaluated for underlying systemic conditions (e.g., diabetes, HIV).', '- **Vulvovaginal Candidiasis:** Indicated for the local treatment of vulvovaginal candidiasis. It effectively relieves vaginal itching, burning, and discharge associated with yeast infections.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to miconazole or any excipients in the formulation. Rationale: Risk of severe local or systemic allergic reactions.
INSERT INTO "drug_generic" VALUES(1171, 'Memantine Hydrochloride', 'Memantine Hydrochloride', 'N06DX01', 0, 0, 0, 0, 1, 0, 0, 0, '[]', 'Use with caution in patients with a history of seizure disorders, as memantine has not been systematically evaluated in this population. Monitor closely in patients with recent myocardial infarction, uncompensated congestive heart failure, or uncontrolled hypertension. Conditions that raise urine pH (e.g., severe urinary tract infections, use of carbonic anhydrase inhibitors, drastic dietary changes) may decrease the urinary elimination of memantine, leading to increased plasma levels and potential toxicity. Use with caution in severe hepatic impairment.', '- **Alzheimer''s Disease:** Treatment of moderate to severe dementia of the Alzheimer''s type.
INSERT INTO "drug_generic" VALUES(1172, 'Promethazine Hydrochloride', 'Promethazine', 'R06AD02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fatal Respiratory Depression", "severity": "High", "trigger_condition": "Use in pediatric patients under 2 years of age", "message": "STOP: Promethazine is CONTRAINDICATED in children younger than 2 years due to the risk of fatal respiratory depression. Use with extreme caution in older children."}, {"alert_type": "Severe Tissue Injury", "severity": "High", "trigger_condition": "Intravenous (IV) administration", "message": "WARNING: IV administration can cause severe tissue injury, including gangrene requiring amputation. Deep intramuscular (IM) injection is the preferred route. Subcutaneous and intra-arterial administration are strictly contraindicated."}]', '- **Respiratory Conditions:** Use with caution in patients with asthma, bronchitis, or bronchiectasis, as anticholinergic effects may thicken secretions and impair expectoration.
INSERT INTO "drug_generic" VALUES(1173, 'Sodium Cromoglycate +  Xylometazoline Nasal Prep', 'Cromolyn Sodium and Xylometazoline Nasal', 'R01AB06', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Rebound Congestion Risk", "severity": "Medium", "trigger_condition": "Use exceeding 7 consecutive days", "message": "STOP: Prolonged use or abuse of xylometazoline (a decongestant) can lead to rebound congestion (rhinitis medicamentosa). Do not use for more than 7 consecutive days."}]', 'Use with caution in patients with hypertension, cardiovascular disease, hyperthyroidism, diabetes mellitus, or narrow-angle glaucoma due to the sympathomimetic effects of xylometazoline. The prolonged use or abuse of decongestants may lead to rebound congestion or drug-induced rhinitis (rhinitis medicamentosa). Limit use to a maximum of 7 consecutive days. Caution is advised in patients with prostatic hypertrophy, as sympathomimetics can exacerbate urinary retention.', '- **Allergic Rhinitis with Nasal Congestion:** Indicated for the symptomatic relief and prophylaxis of allergic rhinitis (seasonal and perennial) when accompanied by significant nasal congestion.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to sodium cromoglycate, xylometazoline, or any ingredients of the preparation. *Rationale:* Can cause severe allergic reactions.
INSERT INTO "drug_generic" VALUES(1174, 'House dust mite immunotherapy', 'House dust mite allergen extract', 'V01AA03', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Administration of allergen immunotherapy", "message": "STOP: Severe, life-threatening systemic allergic reactions, including anaphylaxis, can occur. The first dose must be administered in a healthcare setting under medical supervision. Patients must be prescribed auto-injectable epinephrine."}]', '**Systemic Allergic Reactions:** Therapy may cause life-threatening systemic allergic reactions, including anaphylaxis. Observe patients in the office for at least 30 minutes after the initial dose. Prescribe auto-injectable epinephrine and train the patient on its use.
INSERT INTO "drug_generic" VALUES(1175, 'Difamilast topical', 'Difamilast', 'D11AH08', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Administration Site Restrictions**
INSERT INTO "drug_generic" VALUES(1176, 'Dolasetron', 'Dolasetron', 'A04AA04', 0, 1, 1, 0, 0, 0, 1, 0, '[{"alert_type": "QT Prolongation and Arrhythmias", "severity": "High", "trigger_condition": "Intravenous administration, especially in patients with underlying cardiac conditions", "message": "STOP: Intravenous dolasetron is no longer indicated for the prophylaxis of chemotherapy-induced nausea and vomiting (CINV) due to a dose-dependent risk of severe QT prolongation and fatal arrhythmias."}]', '**Cardiovascular Risk:** Can cause dose-dependent prolongation of the PR, QRS, and QT intervals. Use with extreme caution in patients with a history of abnormal heart rhythms, structural heart disease, sick sinus syndrome, or atrial fibrillation with slow ventricular response.
INSERT INTO "drug_generic" VALUES(1177, 'Arabinoxylan', 'Arabinoxylan', 'A08', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Immunosuppressive Therapy Interaction", "severity": "Moderate", "trigger_condition": "Concurrent use with immunosuppressants", "message": "Arabinoxylan has immunostimulatory properties. It should not be taken in conjunction with medications specifically prescribed to suppress the immune system (e.g., post-transplant drugs) without strict medical supervision."}]', '**Surgical Precaution:** Discontinue use at least 2 weeks prior to elective surgery due to potential postprandial glycemic effects and immunomodulatory actions.
INSERT INTO "drug_generic" VALUES(1178, 'Teicoplanin', 'Teicoplanin', 'J01XA02', 1, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Cross-Sensitivity", "severity": "High", "trigger_condition": "Patient history of Vancomycin hypersensitivity", "message": "STOP: Cross-reactivity between teicoplanin and vancomycin can occur. Monitor closely for hypersensitivity reactions, including \"red-man\" syndrome and anaphylaxis."}]', '**Renal Impairment:** Dosage adjustments are required in patients with preexisting renal insufficiency. Monitor renal function regularly, especially during prolonged therapy or when co-administered with other nephrotoxic agents.
INSERT INTO "drug_generic" VALUES(1179, 'Cinchocaine Hydrochloride + Esculin + Hydrocortisone + Neomycin Sulphate (Rectal prep)', 'Dibucaine + Esculin + Hydrocortisone + Neomycin (Rectal)', 'C05AA01', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Systemic Absorption Risk", "severity": "Moderate", "trigger_condition": "Prolonged use or application to extensive/damaged areas", "message": "Avoid prolonged use. Systemic absorption of hydrocortisone and neomycin can occur, leading to adrenal suppression or ototoxicity/nephrotoxicity, respectively."}]', '**Systemic Absorption:** Prolonged use or application to extensive, inflamed, or damaged mucosal areas may lead to systemic absorption of hydrocortisone (causing adrenal suppression) and neomycin (causing ototoxicity and nephrotoxicity).
INSERT INTO "drug_generic" VALUES(1180, 'Azatadine Nasal prep', 'Azatadine Nasal', 'R06AX09', 0, 0, 0, 0, 1, 0, 0, 0, '[]', '**Anticholinergic Effects:** Use with caution in patients with angle-closure glaucoma, increased intraocular pressure, stenosing peptic ulcer, pyloroduodenal obstruction, or urinary retention, as systemic absorption may exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1181, 'Trifluoperazine', 'Trifluoperazine', 'N05AB06', 0, 0, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Neuroleptic Malignant Syndrome (NMS)", "severity": "High", "trigger_condition": "Development of hyperpyrexia, muscle rigidity, altered mental status, and autonomic instability", "message": "STOP: NMS is a potentially fatal symptom complex associated with antipsychotic drugs. Discontinue immediately and provide intensive symptomatic treatment."}]', 'Use with caution in patients with cardiovascular disease, epilepsy (lowers seizure threshold), angle-closure glaucoma, benign prostatic hyperplasia, diabetes mellitus, and myasthenia gravis. Elderly patients are at increased risk for tardive dyskinesia and orthostatic hypotension. Discontinue trifluoperazine at least 48 hours before myelography and do not resume for at least 24 hours post-procedure to avoid severe neurotoxicity. Monitor for signs of blood dyscrasias (e.g., agranulocytosis) and QTc prolongation. Avoid exposure to extreme temperatures as phenothiazines impair thermoregulation.', '- **Schizophrenia and Psychotic Disorders**: Management of acute and chronic schizophrenia (catatonic, hebephrenic, and paranoid types), psychosis due to organic brain damage, toxic psychosis, and the manic phase of bipolar disorder.
INSERT INTO "drug_generic" VALUES(1182, 'Pheniramine Maleate', 'Pheniramine', 'R06AB05', 0, 0, 0, 0, 1, 1, 1, 0, '[]', '- **CNS Depression:** May cause significant drowsiness and impair the ability to drive or operate machinery. Has potential for abuse.
INSERT INTO "drug_generic" VALUES(1183, 'Moxifloxacin 0.5% Eye prep', 'Moxifloxacin Ophthalmic', 'S01AE07', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity Risk", "severity": "Moderate", "trigger_condition": "History of hypersensitivity to other quinolones", "message": "WARNING: Fatal hypersensitivity (anaphylactic) reactions have been reported in patients receiving systemic quinolones. Discontinue ophthalmic use immediately at the first sign of a rash or allergic reaction."}]', '**Superinfection:** As with other anti-infectives, prolonged use may result in the overgrowth of non-susceptible organisms, including fungi. If superinfection occurs, discontinue use and institute alternative therapy.
INSERT INTO "drug_generic" VALUES(1184, 'Norethisterone', 'Norethindrone', 'G03DC02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "Patients with a history of or current deep vein thrombosis, pulmonary embolism, or severe arterial disease", "message": "STOP: Norethisterone increases the risk of thrombotic and thromboembolic events. It is strictly contraindicated in patients with active or a history of thromboembolic disorders."}]', 'Use with caution in patients with conditions that may be aggravated by fluid retention, such as epilepsy, migraine, asthma, or cardiac/renal dysfunction. Monitor patients with a history of clinical depression and discontinue if severe depression recurs. Caution is advised in patients with hypertension, altered lipid profiles, or diabetes mellitus, as progestins can affect glucose tolerance. Discontinue medication pending examination if there is a sudden partial or complete loss of vision, proptosis, diplopia, or migraine-type headache.', '- **Dysfunctional Uterine Bleeding (Metropathia Haemorrhagica):** Arrests acute bleeding and prevents recurrence.
INSERT INTO "drug_generic" VALUES(1185, 'Glycerol 0.2% + Hypromellose 0.36% + Polyethylene Glycol 400 1%', 'Glycerin, Hypromellose, and Polyethylene Glycol 400', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Visual Disturbances:** May cause temporary blurred vision immediately after instillation. Patients should not drive or operate machinery until vision clears.
INSERT INTO "drug_generic" VALUES(1186, 'Quetiapine', 'Quetiapine Fumarate', 'N05AH04', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Increased Mortality in Elderly Patients with Dementia-Related Psychosis", "severity": "High", "trigger_condition": "Use in elderly patients with dementia", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Quetiapine is not approved for the treatment of patients with dementia-related psychosis."}, {"alert_type": "Suicidal Thoughts and Behaviors", "severity": "High", "trigger_condition": "Use in children, adolescents, and young adults", "message": "Antidepressants and some antipsychotics increase the risk of suicidal thoughts and behaviors in pediatric and young adult patients. Monitor closely for clinical worsening and emergence of suicidal thoughts."}]', 'Use with caution in patients with cardiovascular or cerebrovascular disease, or conditions predisposing to hypotension (e.g., dehydration), due to the risk of orthostatic hypotension. Caution in patients with a history of seizures, conditions that lower the seizure threshold, or conditions that increase the risk of QT prolongation. Monitor closely for metabolic changes, including hyperglycemia, dyslipidemia, and weight gain. Avoid abrupt withdrawal to prevent discontinuation symptoms. Regular eye examinations are recommended to detect cataract formation.', '- **Schizophrenia:** Treatment of schizophrenia in adults and adolescents (13-17 years).
INSERT INTO "drug_generic" VALUES(1187, 'Clarithromycin', 'Clarithromycin', 'J01FA09', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "QT Prolongation and Arrhythmia", "severity": "High", "trigger_condition": "Concomitant use with QT-prolonging drugs or history of QT prolongation", "message": "STOP: Clarithromycin can cause QT prolongation and fatal arrhythmias (Torsades de Pointes). Avoid in patients with known QT prolongation, hypokalemia, hypomagnesemia, or those taking Class IA/III antiarrhythmics, pimozide, or cisapride."}, {"alert_type": "Severe Drug Interactions", "severity": "High", "trigger_condition": "Concomitant use with statins, colchicine, or ergot alkaloids", "message": "STOP: Clarithromycin is a strong CYP3A4 inhibitor. Coadministration with lovastatin or simvastatin is contraindicated due to rhabdomyolysis risk. Coadministration with colchicine in renal/hepatic impairment is contraindicated."}]', '**QT Prolongation:** Clarithromycin has been associated with prolongation of the QT interval and infrequent cases of arrhythmia, including Torsades de Pointes. Avoid use in patients with known QT prolongation, ventricular arrhythmia, significant bradycardia, uncorrected hypokalemia or hypomagnesemia, or those taking Class IA or III antiarrhythmics.
INSERT INTO "drug_generic" VALUES(1188, 'Ranibizumab', 'Ranibizumab', 'S01LA04', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Ocular Infection Risk", "severity": "High", "trigger_condition": "Active or suspected ocular or periocular infection", "message": "STOP: Intravitreal injections are contraindicated in the presence of active or suspected ocular or periocular infections due to the risk of severe endophthalmitis."}]', '**Endophthalmitis and Retinal Detachments:** Intravitreal injections have been associated with endophthalmitis and retinal detachments. Proper aseptic injection technique must always be used. Patients should be monitored following the injection to permit early treatment should an infection occur.
INSERT INTO "drug_generic" VALUES(1189, 'Dalbavancin', 'Dalbavancin', 'J01XA04', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hypersensitivity and Infusion Reactions", "severity": "High", "trigger_condition": "Rapid IV infusion or history of glycopeptide allergy", "message": "STOP: Serious hypersensitivity reactions (anaphylaxis) and rapid infusion-related reactions (Red Man Syndrome) can occur. Infuse over at least 30 minutes."}]', '**Hypersensitivity Reactions:** Serious hypersensitivity (anaphylactic) and skin reactions have been reported with glycopeptide antibacterial agents, including dalbavancin. Exercise caution in patients with known hypersensitivity to other glycopeptides (e.g., vancomycin), as cross-reactivity may occur. Discontinue immediately if an allergic reaction occurs.
INSERT INTO "drug_generic" VALUES(1190, 'Adefovir Dipivoxil', 'Adefovir Dipivoxil', 'J05AF08', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Exacerbation of Hepatitis B", "severity": "High", "trigger_condition": "Discontinuation of adefovir therapy", "message": "STOP: Severe acute exacerbations of hepatitis have been reported in patients who have discontinued anti-Hepatitis B therapy. Hepatic function must be monitored closely for several months after stopping."}, {"alert_type": "Nephrotoxicity", "severity": "High", "trigger_condition": "Chronic use or underlying renal impairment", "message": "STOP: Chronic use may result in nephrotoxicity. Monitor renal function closely and adjust the dose in patients with renal impairment."}, {"alert_type": "Lactic Acidosis", "severity": "High", "trigger_condition": "Clinical signs of lactic acidosis or hepatomegaly", "message": "STOP: Lactic acidosis and severe hepatomegaly with steatosis, including fatal cases, have been reported with the use of nucleoside analogs."}]', '**HIV Resistance:** Resistance to HIV nucleoside reverse transcriptase inhibitors (NRTIs) may emerge in patients with unrecognized or untreated HIV infection. Offer HIV testing prior to initiating therapy.
INSERT INTO "drug_generic" VALUES(1191, 'Sodium Fusidate (Fusidic Acid)', 'Fusidic Acid', 'J01XC01', 1, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Prolonged high-dose therapy or pre-existing hepatic disease", "message": "WARNING: Systemic fusidic acid can cause reversible jaundice and liver dysfunction. Monitor liver function tests regularly, especially in patients with hepatic impairment or those on prolonged therapy."}]', '**Hepatic Impairment:** Systemic fusidic acid is metabolized in the liver and excreted in the bile. It can cause reversible jaundice and liver dysfunction. Use with caution in patients with hepatic disease or biliary anomalies. Monitor liver function tests periodically.
INSERT INTO "drug_generic" VALUES(1192, 'Lidocaine + Epinephrine', 'Lidocaine and Epinephrine', 'N01BB52', 0, 1, 0, 1, 1, 0, 1, 0, '[{"alert_type": "Inadvertent Intravascular Injection", "severity": "High", "trigger_condition": "Failure to aspirate prior to injection", "message": "STOP: Inadvertent intravascular injection can cause severe systemic toxicity, including convulsions, ventricular fibrillation, cardiovascular collapse, and respiratory arrest. Always aspirate before injecting."}]', '**Cardiovascular Disease:** Use with extreme caution in patients with impaired cardiac conduction, congestive heart failure, ischemic heart disease, or severe hypertension. Epinephrine can exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1193, 'Clarithromycin + Metronidazole + Lansoprazol', 'Clarithromycin / Metronidazole / Lansoprazole', 'A02BD', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "QT Prolongation and Severe Drug Interactions", "severity": "High", "trigger_condition": "Co-administration with CYP3A4 substrates or QT-prolonging drugs", "message": "STOP: Clarithromycin is a strong CYP3A4 inhibitor and can cause fatal arrhythmias (Torsades de Pointes) when combined with certain drugs (e.g., pimozide, ergot alkaloids). Metronidazole combined with alcohol causes a severe disulfiram-like reaction."}]', 'Use with caution in patients with severe hepatic or renal impairment. Monitor for signs of pseudomembranous colitis (Clostridioides difficile-associated diarrhea), which can occur with nearly all antibacterial agents. Caution in patients with a history of blood dyscrasias or central nervous system disorders (due to metronidazole). Monitor ECG in patients at risk for QT prolongation.', '- **Helicobacter pylori Eradication:** Indicated for the eradication of H. pylori infection to reduce the risk of duodenal ulcer recurrence.
INSERT INTO "drug_generic" VALUES(1194, 'Cyclophosphamide', 'Cyclophosphamide', 'L01AA01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Myelosuppression and Urotoxicity", "severity": "High", "trigger_condition": "Administration of Cyclophosphamide", "message": "STOP: Severe immunosuppression leading to fatal infections can occur. Hemorrhagic cystitis is a major risk; ensure vigorous hydration and consider mesna for high-dose regimens. Monitor CBC and urinalysis closely."}]', '**Myelosuppression and Immunosuppression:** Severe immunosuppression may lead to serious and sometimes fatal infections. Close hematological monitoring is required. Do not administer to patients with severe bone marrow depression or active infections.
INSERT INTO "drug_generic" VALUES(1195, 'Tobramycin Sulphate', 'Tobramycin Inhalation', 'J01GB01', 1, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Ototoxicity and Nephrotoxicity", "severity": "High", "trigger_condition": "Concurrent use with other nephrotoxic or ototoxic drugs, or preexisting renal impairment", "message": "STOP: Aminoglycosides can cause severe, irreversible ototoxicity (hearing loss, tinnitus) and nephrotoxicity. Monitor renal function and auditory status closely."}]', '- **Nephrotoxicity:** Monitor renal function (serum creatinine, BUN) prior to initiating therapy and periodically during treatment. Risk is higher in patients with preexisting renal impairment, the elderly, and those receiving concurrent nephrotoxic drugs.
INSERT INTO "drug_generic" VALUES(1196, 'Lansoprazole', 'Lansoprazole', 'A02BC03', 0, 0, 1, 0, 0, 1, 1, 0, '[{"alert_type": "Drug Interaction", "severity": "High", "trigger_condition": "Concurrent use with Rilpivirine", "message": "STOP: Co-administration with rilpivirine is contraindicated. Lansoprazole significantly reduces rilpivirine plasma concentrations, leading to loss of virologic response and potential resistance."}]', '**Gastric Malignancy:** Symptomatic response to therapy does not preclude the presence of gastric malignancy. Rule out malignancy before initiating treatment for gastric ulcers.
INSERT INTO "drug_generic" VALUES(1197, 'Esmolol Hydrochloride', 'Esmolol', 'C07AB09', 0, 1, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Hypotension and Bradycardia", "severity": "High", "trigger_condition": "During IV infusion", "message": "STOP: Can cause severe hypotension, bradycardia, and cardiac failure. Continuous monitoring of blood pressure and ECG is mandatory during infusion. Reduce dose or discontinue if severe hypotension or bradycardia occurs."}]', '**Hypotension:** Symptomatic hypotension (diaphoresis, dizziness) is the most common adverse reaction. It is dose-related and usually resolves within 30 minutes of decreasing or stopping the infusion.
INSERT INTO "drug_generic" VALUES(1198, 'Acetic Acid .469% + Calcium Chloride 1.008% + Magnessium Chloride .754% + Potassium Chloride .554% + Sodium Chloride 21.968%', 'Hemodialysis Acid Concentrate', 'B05ZA', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Dilution Requirement", "severity": "High", "trigger_condition": "Preparation for hemodialysis", "message": "STOP: This is a highly concentrated solution. It MUST be diluted with purified water and mixed with a bicarbonate concentrate before use. NEVER inject or infuse directly."}]', '**Strict Dilution Required:** Do not use Solution A (acid concentrate) or Solution B (bicarbonate concentrate) alone. They must be diluted immediately before use with water of suitable quality for hemodialysis.
INSERT INTO "drug_generic" VALUES(1199, 'Povidone Iodine 1.25% Eye prep', 'Povidone-Iodine Ophthalmic', 'S01AX18', 1, 0, 0, 0, 1, 1, 0, 0, '[]', 'Patients experiencing blurred vision after application should not drive or use machinery until their vision has cleared. Contact lenses should not be worn during instillation; wait at least 30 minutes before reinsertion. Prolonged use may lead to systemic iodine absorption. Use with caution in patients with renal impairment.', '- **Bacterial Conjunctivitis:** Treatment of superficial ocular infections caused by susceptible organisms.
INSERT INTO "drug_generic" VALUES(1200, 'Propylhexedrine', 'Propylhexedrine', 'Data not available', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Abuse and Toxicity Risk", "severity": "High", "trigger_condition": "Extraction and intravenous injection or oral ingestion", "message": "STOP: Propylhexedrine is subject to abuse. Extraction and IV injection or oral ingestion of the inhaler contents can cause severe cardiovascular toxicity, cardiomyopathy, dyspnea, ischemic complications, and sudden death."}]', '**Potential for Abuse:** Propylhexedrine may be extracted from the inhaler and injected intravenously or ingested orally as an amphetamine substitute by abusers. This practice carries a high potential for severe toxicity, including cardiomyopathy, pulmonary hypertension, dyspnea, ischemic complications, and death.
INSERT INTO "drug_generic" VALUES(1201, 'Calcitriol', 'Calcitriol', 'A11CC04', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "High", "trigger_condition": "Excessive dosage or inadequate monitoring", "message": "STOP: Calcitriol has a narrow therapeutic window. Excessive dosage induces hypercalcemia and hypercalciuria. Frequent monitoring of serum calcium, phosphorus, and creatinine is mandatory during titration."}]', '**Hypercalcemia:** Calcitriol is the most potent active metabolite of Vitamin D. Overdosage rapidly causes hypercalcemia. Monitor serum calcium twice weekly during dose adjustment. Discontinue immediately if hypercalcemia develops.
INSERT INTO "drug_generic" VALUES(1202, 'Halazone', 'Halazone', 'V07AV', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Ingestion Hazard", "severity": "High", "trigger_condition": "Direct ingestion of the un-dissolved tablet", "message": "STOP: Halazone tablets are for WATER PURIFICATION ONLY. Do not swallow the tablets directly. Direct ingestion can cause severe gastrointestinal irritation and mucosal burns."}]', '**Proper Usage:** Halazone is a water purification agent, not a systemic medication. It must be fully dissolved in water before the water is consumed.
INSERT INTO "drug_generic" VALUES(1203, 'Irrigating Solution for Eye (Purified Water 99.05%)', 'Eye Wash / Ocular Irrigating Solution', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Open Wounds:** Do not use on open wounds in or near the eyes. Seek immediate medical attention for penetrating eye injuries.
INSERT INTO "drug_generic" VALUES(1204, 'Finasteride + Tadalafil', 'Finasteride and Tadalafil', 'G04CB51', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Hypotension Risk", "severity": "High", "trigger_condition": "Concomitant use of organic nitrates or guanylate cyclase stimulators", "message": "STOP: Coadministration with nitrates or guanylate cyclase stimulators can cause profound, life-threatening hypotension. Verify patient medication history before prescribing."}]', '**Cardiovascular Risks:** Patients with left ventricular outflow obstruction (e.g., aortic stenosis, idiopathic hypertrophic subaortic stenosis) can be highly sensitive to the vasodilator actions of PDE5 inhibitors. Use is not recommended in patients with a myocardial infarction within the last 90 days, unstable angina, NYHA class II or greater heart failure in the last 6 months, uncontrolled arrhythmias, hypotension (<90/50 mm Hg), uncontrolled hypertension, or a stroke within the last 6 months.
INSERT INTO "drug_generic" VALUES(1205, 'Topiramate', 'Topiramate', 'N03AX11', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Visual Loss and Metabolic Acidosis", "severity": "High", "trigger_condition": "Patient reports acute eye pain/blurred vision or exhibits hyperventilation/fatigue", "message": "STOP: Topiramate can cause acute myopia and secondary angle-closure glaucoma; discontinue immediately if eye pain or blurred vision occurs. It also inhibits carbonic anhydrase, leading to non-anion gap metabolic acidosis; monitor serum bicarbonate."}]', 'Monitor serum bicarbonate at baseline and periodically during treatment due to the risk of hyperchloremic, non-anion gap metabolic acidosis. Maintain adequate hydration to reduce the risk of nephrolithiasis (kidney stones), especially in predisposed patients. Monitor closely for decreased sweating (oligohidrosis) and hyperthermia, particularly in pediatric patients and during exposure to hot weather. May cause cognitive dysfunction, psychiatric disturbances, and suicidal ideation; monitor for mood changes. Avoid abrupt withdrawal to prevent rebound seizures; taper the dose gradually (e.g., decrease by 50-100 mg/day at weekly intervals). Use with caution in renal or hepatic impairment.', '- **Epilepsy (Monotherapy):** Initial monotherapy in patients 2 years of age and older with partial-onset or primary generalized tonic-clonic seizures.
INSERT INTO "drug_generic" VALUES(1206, 'Ketamine', 'Ketamine', 'N01AX03', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Emergence Delirium and Respiratory Depression", "severity": "High", "trigger_condition": "Post-anesthesia recovery or rapid intravenous administration", "message": "STOP: Severe emergence reactions (hallucinations, delirium) can occur during recovery. Rapid IV administration can cause profound respiratory depression or apnea. Administer slowly and minimize stimulation during recovery."}]', '- **Emergence Reactions:** Vivid dreams, hallucinations, confusion, and irrational behavior can occur during recovery. Minimize verbal and tactile stimulation during the recovery period. Premedication with a benzodiazepine may reduce the incidence.
INSERT INTO "drug_generic" VALUES(1207, 'Cefuroxime + Clavulanic Acid', 'Cefuroxime / Clavulanate', 'J01DC52', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(1208, 'Nebivolol + Hydrochlorothiazide', 'Nebivolol + Hydrochlorothiazide', 'C07BB12', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Abrupt Cessation Risk", "severity": "High", "trigger_condition": "Sudden discontinuation of therapy", "message": "STOP: Do not abruptly discontinue beta-blocker therapy. Severe exacerbation of angina, myocardial infarction, and ventricular arrhythmias have occurred following abrupt cessation. Taper gradually over 1 to 2 weeks."}]', '- **Cardiovascular:** May mask signs of hyperthyroidism (tachycardia) and hypoglycemia. Use with caution in patients with peripheral arterial disease (may aggravate symptoms).
INSERT INTO "drug_generic" VALUES(1209, 'L-Asparginase', 'Asparaginase (or Pegaspargase)', 'L01XX02', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "During or immediately after administration", "message": "STOP: High incidence of severe allergic reactions, including fatal anaphylaxis. Administer only in a hospital setting with resuscitation equipment and medications (epinephrine, steroids) immediately available. Observe patient for at least 1 hour post-infusion."}, {"alert_type": "Acute Pancreatitis", "severity": "High", "trigger_condition": "During therapy", "message": "STOP: Can cause severe, sometimes fatal, acute pancreatitis. Monitor serum amylase and lipase. Permanently discontinue if clinical pancreatitis occurs."}]', '**Coagulopathy:** Depletes clotting factors (e.g., antithrombin III, fibrinogen, protein C/S), leading to a paradoxical risk of both severe hemorrhage and life-threatening thrombosis (e.g., sagittal sinus thrombosis). Monitor coagulation parameters (PT, aPTT, fibrinogen) closely.
INSERT INTO "drug_generic" VALUES(1210, 'Dicloxacillin', 'Dicloxacillin', 'J01CF01', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported in patients on penicillin therapy. Cross-reactivity with cephalosporins may occur.
INSERT INTO "drug_generic" VALUES(1211, 'Niacinamide + Pyridoxine + Riboflavin + Thiamine', 'Niacinamide + Pyridoxine + Riboflavin + Thiamine', 'A11EA', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Underlying Deficiencies:** Intended for mild deficiencies or supplementation. Severe specific deficiencies (e.g., Wernicke''s encephalopathy) require targeted, high-dose intravenous therapy.
INSERT INTO "drug_generic" VALUES(1212, 'Albumin Human 20%', 'Albumin Human', 'B05AA01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Hypervolemia Risk", "severity": "High", "trigger_condition": "Rapid infusion or administration to patients with cardiac failure", "message": "STOP: 20% Albumin is hyperoncotic. Rapid infusion or excessive volume can cause severe hypervolemia, leading to acute pulmonary edema and cardiovascular overload. Monitor hemodynamics closely."}]', '**Hypervolemia and Hemodilution:** Use with extreme caution in patients at risk of hypervolemia. Stop infusion if signs of cardiovascular overload occur. Ensure adequate hydration of the patient when administering concentrated albumin.
INSERT INTO "drug_generic" VALUES(1213, 'Cod Liver Oil 30.5%', 'Cod Liver Oil Liquid', 'A11CB', 0, 0, 0, 1, 0, 0, 1, 0, '[]', '**Hypervitaminosis:** Excessive intake can lead to hypervitaminosis A and D, causing hypercalcemia, hepatotoxicity, and bone pain. Do not exceed recommended doses, especially when taking other vitamin supplements.
INSERT INTO "drug_generic" VALUES(1214, 'Citric Acid Anhydrous + Magnesium Oxide + Sodium Picosulfate', 'Sodium picosulfate, magnesium oxide, and anhydrous citric acid', 'A06AB58', 0, 0, 0, 0, 1, 1, 1, 0, '[]', 'Risk of severe fluid and electrolyte abnormalities (e.g., hypokalemia, hyponatremia, hypermagnesemia); encourage adequate hydration before, during, and after use. Use with caution in patients with mild to moderate renal impairment or those taking medications that affect renal function (e.g., diuretics, ACE inhibitors, ARBs, NSAIDs), as they are at increased risk for renal injury. Consider pre-dose and post-colonoscopy ECGs in patients at increased risk of cardiac arrhythmias. Use caution in patients with a history of seizures or those taking medications that lower the seizure threshold. Rule out suspected GI obstruction or perforation before administration. Observe patients at risk for aspiration during administration. May cause mucosal ulcerations; consider this when interpreting colonoscopy findings in patients with known or suspected inflammatory bowel disease.', '- **Bowel Preparation:** Indicated for cleansing of the colon as a preparation for colonoscopy in adults and pediatric patients aged 9 years and older.', '- **Severe Renal Impairment:** Contraindicated in patients with a creatinine clearance <30 mL/minute. Rationale: Risk of severe hypermagnesemia due to impaired magnesium excretion.
INSERT INTO "drug_generic" VALUES(1215, 'Pilocarpine Hydrochloride 1.25% eye prep', 'Pilocarpine Hydrochloride Ophthalmic Solution', 'S01EB01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Retinal Detachment Risk", "severity": "High", "trigger_condition": "Sudden onset of flashing lights, floaters, or vision loss", "message": "STOP: Rare cases of retinal detachment and retinal tear have been reported with miotic agents. Instruct patients to seek immediate emergency medical care if they experience sudden vision changes, flashing lights, or floaters."}]', '**Visual Disturbances:** Miosis (pupillary constriction) causes decreased night vision and difficulty seeing in poor illumination. Patients should be cautioned against night driving or operating hazardous machinery in poor light.
INSERT INTO "drug_generic" VALUES(1216, 'Cefoxitin', 'Cefoxitin', 'J01DC01', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(1217, 'Gadoteric Acid', 'Gadoterate Meglumine', 'V08CA02', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Nephrogenic Systemic Fibrosis (NSF)", "severity": "High", "trigger_condition": "Severe renal impairment", "message": "STOP: Gadolinium-based contrast agents (GBCAs) increase the risk for NSF among patients with impaired elimination of the drugs. Avoid use in patients with acute kidney injury or chronic, severe kidney disease (GFR < 30 mL/min) unless the diagnostic information is essential."}, {"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "During or immediately after administration", "message": "Anaphylactoid/anaphylactic reactions, including fatalities, have occurred. Monitor patients closely and ensure emergency cardiorespiratory support is immediately available."}]', '**Nephrogenic Systemic Fibrosis (NSF):** Risk is highest in patients with severe renal impairment. Screen patients for acute kidney injury and other conditions that may reduce renal function. 
INSERT INTO "drug_generic" VALUES(1218, 'Chlorambucil', 'Chlorambucil', 'L01AA02', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Severe Myelosuppression and Carcinogenicity", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "STOP: Chlorambucil causes severe bone marrow suppression. It is also a known human carcinogen (can cause secondary leukemias) and is highly teratogenic and mutagenic. Administer only under the supervision of an experienced oncologist."}]', '**Myelosuppression:** Severe bone marrow suppression (neutropenia, thrombocytopenia, anemia) is the dose-limiting toxicity. Monitor CBC frequently. Reduce dose in pre-existing myelosuppression or if used within 4 weeks of radiation/cytotoxic chemotherapy.
INSERT INTO "drug_generic" VALUES(1219, 'Adrenaline + Lidocaine Hydrochloride', 'Lidocaine and Epinephrine', 'N01BB52', 0, 1, 0, 1, 1, 0, 1, 0, '[{"alert_type": "End-Artery Necrosis", "severity": "High", "trigger_condition": "Injection into appendages", "message": "STOP: NEVER inject solutions containing epinephrine into end-artery areas (digits, nose, ears, penis, scrotum). Profound vasoconstriction will cause ischemic necrosis and gangrene."}, {"alert_type": "Intravascular Injection", "severity": "High", "trigger_condition": "Accidental IV administration", "message": "STOP: Accidental intravascular injection can cause severe systemic toxicity, including seizures, cardiac arrhythmias, and cardiovascular collapse. Always aspirate before injecting."}]', '**Systemic Toxicity (LAST):** Local Anesthetic Systemic Toxicity (LAST) can occur due to accidental intravascular injection or excessive dosing. Symptoms progress from CNS excitation (tinnitus, metallic taste, perioral numbness, seizures) to CNS depression (coma, respiratory arrest) and cardiovascular collapse.
INSERT INTO "drug_generic" VALUES(1220, 'Vasopressin', 'Vasopressin', 'H01BA01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Extravasation and Ischemia", "severity": "High", "trigger_condition": "Intravenous administration", "message": "STOP: Vasopressin is a potent vasoconstrictor. Extravasation can cause severe tissue necrosis. Administer via a central venous catheter whenever possible. Monitor closely for signs of peripheral, mesenteric, or myocardial ischemia."}]', 'Use with extreme caution in patients with heart failure, coronary artery disease, asthma, epilepsy, or migraine, as fluid retention and potent vasoconstriction can severely exacerbate these conditions. Monitor hemodynamics, fluid balance, and serum electrolytes continuously to avoid fluid overload and hyponatremia. Caution is advised in patients with renal impairment or hypertension. Monitor for signs of decreased cardiac output and impaired tissue perfusion.', '- **Vasodilatory Shock:** Indicated to increase blood pressure in adults with vasodilatory shock (e.g., post-cardiotomy or septic shock) who remain hypotensive despite fluids and catecholamines.
INSERT INTO "drug_generic" VALUES(1221, 'Bicalutamide', 'Bicalutamide', 'L02BB03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated transaminases or clinical signs of liver dysfunction", "message": "STOP: Severe hepatic injury and fatal hepatic failure have been observed. Monitor serum transaminases prior to starting treatment, regularly for the first four months, and periodically thereafter. Discontinue if clinical signs of liver injury occur."}]', '**Hepatotoxicity:** Severe hepatic injury and fatal hepatic failure have been observed. Monitor serum transaminase levels prior to starting treatment, at regular intervals for the first four months, and periodically thereafter. Discontinue bicalutamide if jaundice develops or if ALT rises above two times the upper limit of normal.
INSERT INTO "drug_generic" VALUES(1222, 'White Soft Paraffin + Light Liquid Paraffin + Lanolin Anhydrous topical', 'White Petrolatum + Light Mineral Oil + Lanolin', 'D02AC', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Fire Hazard", "severity": "High", "trigger_condition": "Application to large body areas or contact with clothing/bedding", "message": "STOP: Fire hazard. Do not smoke or go near naked flames. Fabric (clothing, bedding, dressings) that has been in contact with paraffin-based products burns more easily and is a serious fire hazard. Washing clothing may not completely remove the product."}]', '**Fire Hazard:** Paraffin-based emollients are highly flammable. Advise patients not to smoke or go near naked flames. Clothing or bedding that has been in contact with the product can ignite easily.
INSERT INTO "drug_generic" VALUES(1223, 'Metformin Hydrochloride + Sitagliptin', 'Metformin and Sitagliptin', 'A10BD07', 0, 0, 1, 0, 1, 0, 0, 0, '[{"alert_type": "Lactic Acidosis Risk", "severity": "High", "trigger_condition": "Patient with severe renal impairment (eGFR < 30 mL/min) or acute hypoxic states", "message": "STOP: Metformin can cause fatal lactic acidosis. Contraindicated in severe renal impairment."}]', '**Pancreatitis:** Acute pancreatitis, including fatal and non-fatal hemorrhagic or necrotizing pancreatitis, has been reported with sitagliptin. Monitor for signs of pancreatitis (severe, persistent abdominal pain radiating to the back). Discontinue immediately if suspected.
INSERT INTO "drug_generic" VALUES(1224, 'Dexamethasone 0.1%  E/E prep', 'Dexamethasone Ophthalmic/Otic', 'S01BA01', 0, 0, 1, 1, 0, 1, 1, 1, '[{"alert_type": "Perforated Tympanic Membrane and Ocular Infections", "severity": "High", "trigger_condition": "Use in ears with perforated eardrums or eyes with viral/fungal infections", "message": "STOP: Otic use is strictly contraindicated in patients with a perforated tympanic membrane due to the risk of ototoxicity. Ophthalmic use is contraindicated in viral (herpes simplex) or fungal eye infections."}]', '**Intraocular Pressure (IOP) Elevation:** Prolonged ophthalmic use may result in ocular hypertension and/or glaucoma, with damage to the optic nerve. Monitor IOP regularly if used for >10 days.
INSERT INTO "drug_generic" VALUES(1225, 'Adalimumab', 'Adalimumab', 'L04AB04', 0, 1, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Serious Infections and Malignancy", "severity": "High", "trigger_condition": "During therapy", "message": "STOP: Increased risk of serious infections leading to hospitalization or death, including TB, bacterial sepsis, and invasive fungal infections. Lymphoma and other malignancies have been reported in children and adults treated with TNF blockers."}]', '**Serious Infections:** Increased risk of serious infections leading to hospitalization or death, including tuberculosis (TB), bacterial sepsis, invasive fungal infections (e.g., histoplasmosis), and opportunistic infections. Discontinue adalimumab if a patient develops a serious infection or sepsis. Perform a test for latent TB prior to initiation; if positive, start TB treatment before starting adalimumab. Monitor all patients for active TB during treatment.
INSERT INTO "drug_generic" VALUES(1226, 'Chlorhexidine Gluconate 0.2% Gargle', 'Chlorhexidine Gluconate Oral Rinse', 'A01AB03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Hypersensitivity to chlorhexidine", "message": "STOP: Rare but severe and potentially fatal allergic reactions (anaphylaxis) can occur. Discontinue immediately and seek emergency medical care if symptoms of an allergic reaction develop."}]', '**Tooth and Mucosal Staining:** Can cause reversible brown staining of the teeth, tongue, and tooth restorations. This is more pronounced in patients with heavy plaque accumulation or those who consume tea, coffee, or red wine.
INSERT INTO "drug_generic" VALUES(1227, 'Hydrochlorothiazide + Olmesartan Medoxomil', 'Olmesartan Medoxomil and Hydrochlorothiazide', 'C09DA08', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Fetal Toxicity:** Can cause fetal harm when administered to a pregnant woman. Discontinue as soon as pregnancy is detected.
INSERT INTO "drug_generic" VALUES(1228, 'Ferric Carboxymaltose', 'Ferric Carboxymaltose', 'B03AC', 0, 0, 0, 1, 0, 1, 0, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "Administration of intravenous iron", "message": "STOP: Serious hypersensitivity reactions, including life-threatening anaphylaxis, can occur. Monitor patients for at least 30 minutes post-infusion. Resuscitative equipment and personnel must be immediately available."}]', '**Hypersensitivity Reactions:** Serious and potentially fatal anaphylactic-type reactions have been reported. Patients may present with shock, hypotension, loss of consciousness, or collapse. Monitor patients closely during and for at least 30 minutes after administration.
INSERT INTO "drug_generic" VALUES(1229, 'Glipizide + Metformin Hydrochloride', 'Glipizide and Metformin', 'A10BD03', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Lactic Acidosis and Hypoglycemia Risk", "severity": "High", "trigger_condition": "Renal impairment, hepatic disease, or excessive alcohol intake", "message": "STOP: Metformin carries a severe risk of lactic acidosis in patients with renal or hepatic impairment. Glipizide can cause profound hypoglycemia. Monitor renal function and blood glucose closely."}]', '**Renal and Hepatic Monitoring:** Assess renal function (eGFR) prior to initiation and at least annually thereafter. Hepatic impairment increases the risk of lactic acidosis and hypoglycemia.
INSERT INTO "drug_generic" VALUES(1230, 'Metformin Hydrochloride', 'Metformin', 'A10BA02', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Lactic Acidosis Risk", "severity": "High", "trigger_condition": "Patient with severe renal impairment (eGFR < 30 mL/min), acute heart failure, or undergoing radiologic studies with iodinated contrast", "message": "STOP: Metformin can cause fatal lactic acidosis. Discontinue immediately in acute illness, hypoxia, or before intravascular radiocontrast administration."}]', '**Lactic Acidosis:** Metformin accumulation can lead to lactic acidosis, a rare but potentially fatal metabolic complication. Risk factors include renal impairment, advanced age, hypoxic states (e.g., acute heart failure, recent myocardial infarction), excessive alcohol intake, and hepatic impairment. If suspected, discontinue metformin immediately and hospitalize the patient.
INSERT INTO "drug_generic" VALUES(1231, 'Naproxen + Esomeprazole', 'Naproxen and Esomeprazole', 'M01AE52', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risks", "severity": "High", "trigger_condition": "Use in patients with cardiovascular disease or risk factors, or history of GI bleeding", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation."}]', 'Use with caution in patients with known cardiovascular disease or risk factors; NSAIDs can increase the risk of serious cardiovascular thrombotic events. May cause fluid retention and exacerbate heart failure or hypertension; monitor blood pressure closely. Renal toxicity can occur, particularly in patients with pre-existing renal impairment, heart failure, liver dysfunction, or those taking diuretics/ACE inhibitors. Esomeprazole component carries risks of C. difficile-associated diarrhea, bone fractures with long-term use, and hypomagnesemia. Monitor for signs of active GI bleeding, especially in the elderly or those with a history of peptic ulcer disease. Discontinue immediately if signs of severe skin reactions (e.g., Stevens-Johnson syndrome) or hepatotoxicity occur.', '- **Rheumatoid Arthritis:** Relief of signs and symptoms.
INSERT INTO "drug_generic" VALUES(1232, 'Certolizumab', 'Certolizumab pegol', 'L04AB05', 0, 1, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Serious Infections and Malignancy", "severity": "High", "trigger_condition": "Initiation of therapy or development of systemic symptoms", "message": "STOP: Increased risk of serious, potentially fatal infections (TB, bacterial sepsis, invasive fungal infections). Test for latent TB before starting. Lymphoma and other malignancies have been reported in patients treated with TNF blockers."}]', '**Serious Infections:** Increased risk of serious infections leading to hospitalization or death, including tuberculosis (TB), bacterial sepsis, invasive fungal infections (e.g., histoplasmosis), and opportunistic pathogens. Do not initiate in patients with an active infection. Discontinue if a serious infection or sepsis develops.
INSERT INTO "drug_generic" VALUES(1233, 'Cefpodoxime + Clavulanic Acid', 'Cefpodoxime / Clavulanate', 'J01DD13', 1, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(1234, 'Tapentadol', 'Tapentadol', 'N02AX06', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Respiratory Depression", "severity": "High", "trigger_condition": "High doses, rapid titration, or concurrent CNS depressants", "message": "STOP: Serious, life-threatening, or fatal respiratory depression may occur. Monitor closely, especially during initiation or dose escalation."}, {"alert_type": "Addiction, Abuse, and Misuse", "severity": "High", "trigger_condition": "Routine therapy", "message": "STOP: Tapentadol is a Schedule II controlled substance with a high risk of addiction, abuse, and misuse, which can lead to overdose and death."}]', 'Use with extreme caution in patients with chronic obstructive pulmonary disease (COPD), cor pulmonale, hypoxia, hypercapnia, or pre-existing respiratory depression. Caution in patients with sleep apnea syndrome, myxedema, kyphoscoliosis, or CNS depression. Co-administration with other CNS depressants (e.g., benzodiazepines, alcohol, phenothiazines) increases the risk of profound sedation, respiratory depression, coma, and death. Monitor for signs of serotonin syndrome, especially if used with other serotonergic drugs. Caution in patients with a history of seizure disorders, as tapentadol may lower the seizure threshold. Monitor for signs of hypotension.', '- **Acute Pain:** Management of moderate to severe acute pain in adults.
INSERT INTO "drug_generic" VALUES(1235, 'Phenoxybenzamine', 'Phenoxybenzamine', 'C04AX02', 0, 0, 0, 0, 1, 0, 1, 0, '[]', '**Cardiovascular Disease:** Use with extreme caution in patients with heart failure, congestive heart failure, cerebrovascular diseases, cerebral or coronary atherosclerosis, or respiratory infections. The drug can cause significant tachycardia and orthostatic hypotension, which may exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1236, 'Calcipotriene + Betamethasone topical', 'Calcipotriene and Betamethasone Dipropionate', 'D05AX52', 0, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Hypercalcemia Risk", "severity": "High", "trigger_condition": "Application to large surface areas or exceeding maximum weekly dose", "message": "STOP: Hypercalcemia and hypercalciuria can occur. Do not exceed the maximum recommended weekly dose (100 g/week for adults). Discontinue treatment if calcium metabolism parameters become abnormal."}]', '**Calcium Metabolism Disorders:** Hypercalcemia and hypercalciuria have been reported. If elevated serum calcium or urine calcium occurs, discontinue treatment immediately until parameters of calcium metabolism normalize.
INSERT INTO "drug_generic" VALUES(1237, 'Ketoconazole', 'Ketoconazole', 'J02AB02', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Systemic oral administration", "message": "STOP: Oral ketoconazole has been associated with fatal hepatotoxicity. It should only be used for endemic mycoses when other effective antifungal therapy is not available or tolerated."}, {"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Concomitant use with CYP3A4 substrates", "message": "STOP: Coadministration with specific CYP3A4 substrates (e.g., cisapride, dofetilide, pimozide, quinidine) is contraindicated due to the risk of life-threatening torsades de pointes."}]', '**Hepatic Impairment:** Regular monitoring of liver function tests (baseline and during treatment) is mandatory for systemic use. Discontinue treatment immediately if there is persistent or worsening elevation of liver enzymes, or if clinical signs of hepatitis develop.
INSERT INTO "drug_generic" VALUES(1238, 'Folic Acid', 'Folic Acid', 'B03BB01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Neurological Risk", "severity": "High", "trigger_condition": "Administration in patients with undiagnosed or untreated Vitamin B12 deficiency", "message": "Folic acid alone is improper therapy in the treatment of pernicious anemia and other megaloblastic anemias where vitamin B12 is deficient. It may correct the hematological abnormalities while allowing irreversible neurological damage to progress."}]', 'Treatment resistance may occur in patients with depressed hematopoiesis, alcoholism, or deficiencies of other vitamins. Folic acid doses above 0.1 mg daily may obscure pernicious anemia by producing hematologic remission while neurological manifestations remain progressive. Ensure vitamin B12 deficiency is ruled out before initiating high-dose folic acid therapy. Use with caution in neonates.', '- **Folic Acid Deficiency:** Treatment of documented folic acid deficiency.
INSERT INTO "drug_generic" VALUES(1239, 'Isosorbide Dinitrate + Hydralazine Hydrochloride', 'Isosorbide Dinitrate/Hydralazine', 'C01DA58', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Severe Hypotension Risk", "severity": "High", "trigger_condition": "Concomitant use with PDE-5 inhibitors or sGC stimulators", "message": "STOP: Co-administration with PDE-5 inhibitors (e.g., sildenafil) or sGC stimulators (e.g., riociguat) is strictly contraindicated due to the risk of profound, life-threatening hypotension and syncope."}]', '**Symptomatic Hypotension:** May cause severe symptomatic hypotension, particularly in volume-depleted patients or those treated with other antihypertensives. Monitor blood pressure closely during initiation and dose titration.
INSERT INTO "drug_generic" VALUES(1240, 'Acidic component [HCO3 Hemodialysis Solution]', 'Acid Concentrate for Hemodialysis', 'B05ZA', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Dilution Requirement", "severity": "High", "trigger_condition": "Preparation for hemodialysis", "message": "STOP: For hemodialysis use only. Must be diluted and proportioned by a hemodialysis machine with purified water and bicarbonate concentrate before use. Do not use Solution A (Acid) or Solution B (Bicarbonate) alone."}]', '**Electrolyte Imbalance:** Incorrect proportioning or selection of the wrong concentrate formulation can lead to severe, life-threatening electrolyte imbalances (e.g., hyperkalemia, hypocalcemia, hypernatremia). Verify the prescription matches the concentrate label.
INSERT INTO "drug_generic" VALUES(1241, 'Ledipasvir + Sofosbuvir', 'Ledipasvir and Sofosbuvir', 'J05AP51', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Hepatitis B Virus (HBV) Reactivation", "severity": "High", "trigger_condition": "Co-infection with HCV and HBV", "message": "STOP: Test all patients for evidence of current or prior HBV infection before initiating treatment. HBV reactivation has been reported in HCV/HBV coinfected patients, resulting in fulminant hepatitis, hepatic failure, and death."}, {"alert_type": "Serious Symptomatic Bradycardia", "severity": "High", "trigger_condition": "Coadministration with Amiodarone", "message": "STOP: Coadministration with amiodarone is not recommended due to the risk of severe, potentially fatal symptomatic bradycardia. If coadministration is unavoidable, continuous cardiac monitoring is required."}]', '**Bradycardia with Amiodarone:** Serious symptomatic bradycardia may occur in patients taking amiodarone, particularly those receiving beta-blockers or with underlying cardiac comorbidities. Avoid coadministration.
INSERT INTO "drug_generic" VALUES(1242, 'Resmetirom', 'Resmetirom', 'A05BA11', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated liver tests or clinical signs of liver injury", "message": "STOP: Hepatotoxicity can occur. Monitor liver tests during treatment. Discontinue resmetirom if hepatotoxicity is suspected."}, {"alert_type": "Gallbladder-Related Adverse Reactions", "severity": "Moderate", "trigger_condition": "Suspected cholelithiasis or acute cholecystitis", "message": "Caution: Increased risk of cholelithiasis and cholecystitis. Interrupt treatment if an acute gallbladder event is suspected until the event is resolved."}]', 'Monitor patients during treatment for elevations in liver tests and for the development of liver-related adverse reactions. Discontinue therapy and continue to monitor the patient if hepatotoxicity is suspected.
INSERT INTO "drug_generic" VALUES(1243, 'Sodium Bicarbonate 6.6% + Sodium Chloride 3.1% + Highly purified water (Haemodialysis solutions)', 'Hemodialysis Solutions (Sodium Bicarbonate / Sodium Chloride)', 'B05ZA', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Improper Administration Route", "severity": "High", "trigger_condition": "Direct intravenous injection", "message": "STOP: This solution is a concentrate for hemodialysis. It MUST NOT be injected or infused directly into the patient''s vein. It must be properly diluted by a hemodialysis machine before use."}]', 'Do not use Solution A or Solution B alone; they must be used in combination as directed by the hemodialysis machine protocol. The concentrate must be diluted immediately before use with water of suitable quality (e.g., reverse osmosis water) according to the manufacturer''s specifications. Discard the container if there are visible solid particles inside, if the seal is broken, or if the solution is discolored. Monitor the patient''s serum electrolytes, acid-base balance, and fluid status continuously during dialysis.', '- **Haemodialysis:** Indicated for use as a dialysate buffer and electrolyte replenisher in patients undergoing acute or chronic hemodialysis for end-stage renal disease (ESRD) or acute kidney injury.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to any of the ingredients of this preparation. *Rationale:* Can trigger allergic reactions during the dialysis procedure.
INSERT INTO "drug_generic" VALUES(1244, 'Mavacamten', 'Mavacamten', 'C01EB24', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Heart Failure Risk", "severity": "High", "trigger_condition": "LVEF <50% or clinical symptoms of heart failure", "message": "STOP: Mavacamten reduces left ventricular ejection fraction (LVEF) and can cause heart failure. Interrupt dosing immediately if LVEF drops below 50% or if the patient experiences worsening clinical status."}]', '**Risk of Heart Failure:** Mavacamten reduces left ventricular ejection fraction (LVEF) and can cause heart failure due to systolic dysfunction. Echocardiogram assessments of LVEF are required before initiating therapy and regularly during treatment. Initiation is not recommended in patients with an LVEF <55%. Interrupt dosing if LVEF falls below 50% at any visit or if the patient experiences heart failure symptoms or worsening clinical status.
INSERT INTO "drug_generic" VALUES(1245, 'Sodium Feredetate Trihydrate', 'Sodium Feredetate', 'B03AB03', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Iron Overload", "severity": "High", "trigger_condition": "Patients with hemochromatosis, hemosiderosis, or receiving repeated blood transfusions", "message": "STOP: Contraindicated in iron-overload states. Administration can lead to severe iron toxicity and organ damage."}]', '**Underlying Anemia Diagnosis**
INSERT INTO "drug_generic" VALUES(1246, 'Bacitracin Zinc + Neomycin Sulphate Topical', 'Bacitracin and Neomycin Topical', 'D06AX', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Allergic Contact Dermatitis", "severity": "Medium", "trigger_condition": "Application to the skin", "message": "STOP: Neomycin is a potent sensitizer. Allergic contact dermatitis occurs frequently (up to 60% in some populations). Discontinue if redness, itching, or worsening of the lesion occurs."}]', '**Systemic Absorption:** Avoid application in large quantities or over extensive areas of denuded skin (e.g., severe burns). Systemic absorption of neomycin can lead to severe nephrotoxicity and irreversible ototoxicity.
INSERT INTO "drug_generic" VALUES(1247, 'Insulin degludec + Insulin aspart 70/30 premixed', 'Insulin Degludec and Insulin Aspart', 'A10AD06', 0, 1, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Hypoglycemia Risk", "severity": "High", "trigger_condition": "Changes in meal patterns, physical activity, or co-administration with other glucose-lowering agents", "message": "Severe, life-threatening hypoglycemia can occur. Monitor blood glucose closely. Do not administer during episodes of hypoglycemia."}, {"alert_type": "Medication Error Risk", "severity": "High", "trigger_condition": "Dispensing or administration", "message": "Accidental mix-ups between insulin products can occur. Always verify the insulin label before each injection."}]', 'Omission of a meal or unplanned strenuous physical exercise may lead to severe hypoglycemia. Concomitant illness, especially infections and fever, usually increases the patient''s insulin requirement. Diseases affecting the kidney, liver, adrenal, pituitary, or thyroid gland may require changes in the insulin dose. Inadequate dosing or discontinuation of treatment may lead to hyperglycemia and potentially fatal diabetic ketoacidosis. Intensification of insulin therapy with abrupt improvement in glycemic control may be associated with temporary worsening of diabetic retinopathy. Monitor elderly patients closely and adjust doses on an individual basis.', '- Treatment of diabetes mellitus in adults to improve glycemic control.
INSERT INTO "drug_generic" VALUES(1248, 'Ezetimibe', 'Ezetimibe', 'C10AX09', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "Moderate", "trigger_condition": "Co-administration with statins or fibrates", "message": "STOP: Risk of myopathy and rhabdomyolysis is increased when ezetimibe is co-administered with a statin or fibrate. Discontinue immediately if myopathy is diagnosed or suspected (unexplained muscle pain, tenderness, or weakness with elevated CPK)."}]', '**Hepatic Impairment:** Not recommended in patients with moderate to severe hepatic impairment due to increased systemic exposure.
INSERT INTO "drug_generic" VALUES(1249, 'Aspirin + Dipyridamole', 'Aspirin/Dipyridamole', 'B01AC30', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Bleeding Risk", "severity": "High", "trigger_condition": "Concomitant use of anticoagulants or NSAIDs", "message": "STOP: Increases the risk of severe bleeding. Monitor closely for signs of gastrointestinal ulceration or hemorrhage."}]', '**Bleeding Risk:** Increases the risk of bleeding. Use with caution in patients with a history of peptic ulcer disease, bleeding disorders, or those taking concurrent anticoagulants or NSAIDs.
INSERT INTO "drug_generic" VALUES(1250, 'Capecitabine', 'Capecitabine', 'L01BC06', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "DPD Deficiency Toxicity", "severity": "High", "trigger_condition": "Patients with DPYD gene variants", "message": "STOP: Patients with complete or partial dihydropyrimidine dehydrogenase (DPD) deficiency are at high risk for severe, life-threatening, or fatal toxicities (e.g., severe neutropenia, neurotoxicity, diarrhea). Capecitabine is contraindicated in complete DPD deficiency."}, {"alert_type": "Warfarin Interaction", "severity": "High", "trigger_condition": "Concurrent use of Warfarin", "message": "STOP: Capecitabine significantly increases INR and bleeding risk. Monitor INR frequently and adjust warfarin dose accordingly."}]', '**Cardiotoxicity:** Myocardial infarction, angina, dysrhythmias, cardiogenic shock, and sudden death have been reported. Risk is higher in patients with a history of coronary artery disease.
INSERT INTO "drug_generic" VALUES(1251, 'Resorcinol + Sulfur topical', 'Resorcinol + Sulfur', 'D10AX02', 0, 0, 0, 0, 0, 0, 0, 0, '[]', 'For external use only. Discontinue if excessive skin irritation develops. Avoid contact with eyes, lips, and mucous membranes.', '- **Acne Vulgaris:** Indicated for the topical treatment of acne vulgaris.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to resorcinol, sulfur, or any component of the formulation.
INSERT INTO "drug_generic" VALUES(1252, 'Tagraxofusp', 'Tagraxofusp-erzs', 'L01XX67', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Capillary Leak Syndrome (CLS)", "severity": "High", "trigger_condition": "Hypoalbuminemia, rapid weight gain, edema, or hypotension", "message": "STOP: Life-threatening and fatal Capillary Leak Syndrome (CLS) can occur. Ensure serum albumin is \u22653.2 g/dL before initiating. Monitor weight, albumin, and vital signs closely. Interrupt dose and manage aggressively if CLS occurs."}]', '**Capillary Leak Syndrome (CLS):** Severe, life-threatening, and fatal CLS has been reported. Symptoms include rapid weight gain, edema, hypoalbuminemia, and hypotension. Ensure serum albumin is ≥3.2 g/dL before starting. Monitor weight daily, and check albumin and vital signs frequently. Interrupt dosing and provide supportive care (e.g., IV albumin, diuretics, corticosteroids) if CLS is suspected.
INSERT INTO "drug_generic" VALUES(1253, 'Coagulation Factor VIIa [Eptacog Alfa]', 'Coagulation Factor VIIa (Recombinant)', 'B02BD08', 0, 1, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Thrombotic Events", "severity": "High", "trigger_condition": "Patients with risk factors for thrombosis", "message": "STOP: Serious arterial and venous thrombotic events have been reported. Use with caution in patients with advanced atherosclerotic disease, crush injury, septicemia, or disseminated intravascular coagulation (DIC)."}]', '**Thromboembolic Risk:** Patients with a history of coronary heart disease, liver disease, undergoing major surgery, or at risk of thromboembolic phenomena or DIC should be monitored closely for signs of thrombosis.
INSERT INTO "drug_generic" VALUES(1254, 'Flecainide', 'Flecainide', 'C01BC04', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Proarrhythmic Effects and Mortality Risk", "severity": "High", "trigger_condition": "Use in patients with non-life-threatening arrhythmias or structural heart disease", "message": "STOP: Flecainide is associated with an increased risk of mortality and proarrhythmic events in patients with structural heart disease (e.g., history of MI) or non-life-threatening ventricular arrhythmias. Reserve use for life-threatening arrhythmias or severe, highly symptomatic supraventricular arrhythmias in patients without structural heart disease."}]', 'Use with extreme caution in patients with pacemakers, structural heart disease, or a history of atrial fibrillation following cardiac surgery. 
INSERT INTO "drug_generic" VALUES(1255, 'Cefaclor', 'Cefaclor', 'J01DC04', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(1256, 'Faropenem sodium', 'Faropenem sodium', 'J01DI03', 1, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin, Cephalosporin, or Carbapenem hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported in patients receiving beta-lactam therapy. Careful inquiry should be made concerning previous hypersensitivity reactions to penicillins, cephalosporins, or carbapenems.
INSERT INTO "drug_generic" VALUES(1257, 'Glimepiride + Pioglitazone', 'Glimepiride and Pioglitazone', 'A10BD06', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Congestive Heart Failure Risk", "severity": "High", "trigger_condition": "Patients with a history of heart failure or fluid retention", "message": "Thiazolidinediones, including pioglitazone, can cause or exacerbate congestive heart failure. Observe patients for signs of heart failure (rapid weight gain, dyspnea, edema). If heart failure develops, manage appropriately and consider discontinuation or dose reduction."}]', 'Pioglitazone can cause dose-related fluid retention, which may lead to or exacerbate congestive heart failure. Monitor patients closely for signs of heart failure. Pioglitazone has been associated with an increased risk of bone fractures in female patients; consider bone health during long-term use. There may be an increased risk of bladder cancer with prolonged pioglitazone use; avoid in patients with active bladder cancer. Glimepiride carries a risk of severe hypoglycemia, especially in the elderly or those with renal/hepatic impairment. Monitor liver enzymes prior to initiation and periodically thereafter. Macular edema has been reported with thiazolidinediones.', '- **Type 2 Diabetes Mellitus:** Indicated as an adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus who are already treated with a combination of pioglitazone and a sulfonylurea, or whose diabetes is not adequately controlled with a sulfonylurea alone, or for those who have initially responded to pioglitazone alone and require additional glycemic control.', '- **Heart Failure:** Contraindicated in patients with established New York Heart Association (NYHA) Class III or IV heart failure due to the pioglitazone component.
INSERT INTO "drug_generic" VALUES(1258, 'Sodium Cromoglycate 2%  Eye/Nasal prep', 'Cromolyn Sodium 2% Ophthalmic/Nasal', 'S01GX01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Contact Lens Precaution", "severity": "Low", "trigger_condition": "Use of eye drops containing benzalkonium chloride", "message": "This preparation contains benzalkonium chloride. Patients should not wear soft contact lenses during treatment, as the preservative can be absorbed and cause ocular irritation."}]', 'For ophthalmic use, patients should be advised not to wear soft contact lenses during treatment due to the presence of benzalkonium chloride, which can discolor lenses and cause irritation. For nasal use, regular administration is required for optimal prophylactic effect; it is not effective for the acute relief of severe nasal congestion. If symptoms do not improve after 1-2 weeks of regular use, the clinical situation should be re-evaluated.', '- **Allergic Conjunctivitis:** Indicated for the prevention and treatment of acute and chronic allergic conjunctivitis, including vernal keratoconjunctivitis.
INSERT INTO "drug_generic" VALUES(1259, 'Xylometazoline Hydrochloride 0.05% Nasal prep', 'Xylometazoline', 'R01AA07', 0, 0, 0, 0, 0, 1, 1, 0, '[]', 'Prolonged use or abuse (greater than 3 to 5 days) may lead to rebound congestion (rhinitis medicamentosa) and drug-induced rhinitis. Use with caution in patients with hypertension, cardiovascular disease, hyperthyroidism, diabetes mellitus, or narrow-angle glaucoma due to potential systemic sympathomimetic effects.', '- **Nasal Congestion:** Symptomatic relief of nasal congestion associated with the common cold, sinusitis, and seasonal or perennial allergic rhinitis.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to xylometazoline or any component of the formulation.
INSERT INTO "drug_generic" VALUES(1260, 'Dexamethasone Eye drop', 'Dexamethasone Ophthalmic', 'S01BA01', 0, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Ocular Complications", "severity": "High", "trigger_condition": "Prolonged use (>10 days)", "message": "STOP: Prolonged use of ophthalmic corticosteroids can cause elevated intraocular pressure (glaucoma), optic nerve damage, posterior subcapsular cataracts, and delayed wound healing. Routine monitoring of IOP is mandatory if used for 10 days or longer."}]', '**Intraocular Pressure (IOP) Elevation:** Prolonged use may result in ocular hypertension and/or glaucoma. Monitor IOP routinely if used for 10 days or longer, even in children and uncooperative patients.
INSERT INTO "drug_generic" VALUES(1261, 'Iloperidone', 'Iloperidone', 'N05AX14', 0, 1, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Increased Mortality in Elderly Patients with Dementia-Related Psychosis", "severity": "High", "trigger_condition": "Use in elderly patients with dementia-related psychosis", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Iloperidone is not approved for the treatment of patients with dementia-related psychosis."}]', '**QTc Prolongation:** Iloperidone prolongs the QT interval. Avoid use with other drugs that prolong QTc or in patients with congenital long QT syndrome, cardiac arrhythmias, or uncorrected hypokalemia/hypomagnesemia.
INSERT INTO "drug_generic" VALUES(1262, 'Brimonidine Tartrate + Benzalkonium Chloride eye prep', 'Brimonidine Tartrate / Benzalkonium Chloride', 'S01EA05', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hypertensive Crisis Risk", "severity": "High", "trigger_condition": "Concurrent use of Monoamine Oxidase Inhibitors (MAOIs)", "message": "STOP: Concomitant use with MAOIs can precipitate a severe hypertensive crisis. Verify patient medication history before prescribing."}]', '**Contact Lens Use:** Patients wearing soft contact lenses must wait at least 15 minutes after instillation before inserting lenses, as benzalkonium chloride can be absorbed by soft lenses.
INSERT INTO "drug_generic" VALUES(1263, 'Malathion topical', 'Malathion topical', 'P03AX03', 0, 0, 1, 0, 0, 1, 0, 0, '[{"alert_type": "Flammability Risk", "severity": "High", "trigger_condition": "Exposure to open flames or electric heat sources", "message": "STOP: Malathion lotion is highly flammable. Instruct patients to avoid smoking, open flames, and the use of hair dryers while the hair is wet with the medication."}]', '- **Flammability:** Malathion is highly flammable. Avoid the use of hair dryers (allow hair to dry naturally), smoking, or exposure to open flames during application and while the hair is wet.
INSERT INTO "drug_generic" VALUES(1264, 'Fluticasone Furoate inhalation', 'Fluticasone Furoate inhalation', 'R03BA09', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Acute Bronchospasm", "severity": "High", "trigger_condition": "Use during acute asthma attacks", "message": "STOP: Fluticasone furoate is a maintenance medication and is NOT indicated for the relief of acute bronchospasm or status asthmaticus. Use a short-acting beta2-agonist (SABA) for rescue therapy."}]', '**Oral Candidiasis:** Localized infections of the mouth and pharynx with Candida albicans can occur. Patients should rinse their mouth with water without swallowing after inhalation.
INSERT INTO "drug_generic" VALUES(1265, 'Iodine 10%', 'Povidone-Iodine 10%', 'D08AG03', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '- Avoid application over large surface areas or for prolonged periods, especially in children, the elderly (>45 years), and patients with renal impairment, due to the risk of systemic iodine absorption.
INSERT INTO "drug_generic" VALUES(1266, 'Betamethasone 0.05% + Calcipotriol 0.005% topical', 'Calcipotriene and Betamethasone Dipropionate', 'D05AX52', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Hypercalcemia", "severity": "High", "trigger_condition": "Excessive application or use over large surface areas", "message": "STOP: Calcipotriol can cause hypercalcemia and hypercalciuria. Do not exceed the maximum weekly dose (100 g/week). Monitor serum calcium levels if used extensively."}, {"alert_type": "HPA Axis Suppression", "severity": "High", "trigger_condition": "Prolonged use or use under occlusion", "message": "STOP: Betamethasone dipropionate is a potent corticosteroid. Systemic absorption can produce reversible HPA axis suppression and Cushing''s syndrome. Avoid occlusive dressings."}]', '**Application Limits:** Do not apply to more than 30% of the body surface area. Do not exceed 100 grams per week. Do not use on the face, axillae, or groin.
INSERT INTO "drug_generic" VALUES(1267, 'Oxytetracycline 0.5% + Polymixin B Sulphate E/E prep', 'Oxytetracycline 0.5% / Polymyxin B Sulfate Ophthalmic/Otic Ointment', 'S01AA30', 1, 0, 0, 1, 0, 1, 1, 0, '[]', '**Superinfection:** Prolonged use may result in the overgrowth of nonsusceptible organisms, including fungi. If superinfection occurs, discontinue use and institute appropriate therapy.
INSERT INTO "drug_generic" VALUES(1268, 'Atezolizumab', 'Atezolizumab', 'L01FF05', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Immune-Mediated Adverse Reactions", "severity": "High", "trigger_condition": "Patients presenting with new-onset respiratory, gastrointestinal, hepatic, or endocrine symptoms", "message": "STOP: Severe and fatal immune-mediated adverse reactions (pneumonitis, colitis, hepatitis, endocrinopathies, nephritis) can occur. Withhold therapy and initiate high-dose corticosteroids promptly if suspected."}]', '**Immune-Mediated Adverse Reactions:** Immune-mediated adverse reactions, which may be severe or fatal, can occur in any organ system or tissue. These include immune-mediated pneumonitis, colitis, hepatitis, endocrinopathies (e.g., adrenal insufficiency, hypophysitis, type 1 diabetes mellitus), dermatologic adverse reactions, nephritis and renal dysfunction, and solid organ transplant rejection. Withhold or permanently discontinue atezolizumab based on the severity and type of reaction and administer corticosteroids as appropriate.
INSERT INTO "drug_generic" VALUES(1269, 'Pyrantel Pamoate', 'Pyrantel Pamoate', 'P02CC01', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Intestinal Obstruction Risk", "severity": "Moderate", "trigger_condition": "Heavy helminthic worm burden", "message": "Spastic paralyzing agents may induce complete intestinal obstruction in patients with a heavy worm load due to the sudden dislodgement and impaction of paralyzed worms."}]', 'Use with caution in patients with pre-existing liver dysfunction, as transient elevations in AST (SGOT) have been reported following administration. Caution is also advised in patients with severe malnutrition or anemia. When treating enterobiasis, all close contacts and family members should be treated simultaneously to prevent reinfection, and strict hygiene measures must be instituted.', '- **Ascariasis (Roundworm):** Treatment of infections caused by *Ascaris lumbricoides*.
INSERT INTO "drug_generic" VALUES(1270, 'Formoterol Fumarate', 'Formoterol', 'R03AC13', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Asthma-Related Death Risk", "severity": "High", "trigger_condition": "Use as monotherapy in asthma without a concomitant inhaled corticosteroid", "message": "Long-acting beta2-adrenergic agonists (LABAs) increase the risk of asthma-related death. Formoterol must NEVER be used as monotherapy for asthma; it must only be used in conjunction with a long-term asthma control medication, such as an inhaled corticosteroid (ICS)."}]', 'Do not initiate or increase the dose during an acute exacerbation of asthma or COPD. Formoterol is not a rescue inhaler and should not be used to treat acute bronchospasm. May produce paradoxical bronchospasm, which can be life-threatening; if this occurs, discontinue immediately and institute alternative therapy. Use with caution in patients with cardiovascular disorders (coronary insufficiency, cardiac arrhythmias, hypertension), prolonged QT interval, thyrotoxicosis, or diabetes mellitus (due to risk of hyperglycemia). Monitor for hypokalemia, which may be transient but can increase the risk of arrhythmias.', '- **Asthma:** Maintenance treatment of asthma in patients 5 years of age and older (MUST be used concomitantly with an inhaled corticosteroid).
INSERT INTO "drug_generic" VALUES(1271, 'Pramoxine + Calamine topical', 'Pramoxine and Calamine', 'D04AB', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Skin Integrity:** Do not use on blistered, broken, or severely denuded skin to prevent excessive systemic absorption and local irritation.
INSERT INTO "drug_generic" VALUES(1272, 'Chloramphenicol', 'Chloramphenicol', 'J01BA01', 1, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fatal Blood Dyscrasias", "severity": "High", "trigger_condition": "Systemic administration", "message": "STOP: Serious and fatal blood dyscrasias (aplastic anemia, hypoplastic anemia, thrombocytopenia, and granulocytopenia) have occurred after both short-term and prolonged therapy. Monitor CBC frequently."}, {"alert_type": "Gray Baby Syndrome", "severity": "High", "trigger_condition": "Administration to premature infants and neonates", "message": "STOP: Fatal ''Gray Baby Syndrome'' (abdominal distension, pallid cyanosis, vasomotor collapse) can occur in premature infants and neonates due to drug accumulation. Monitor serum levels strictly."}]', '**Blood Dyscrasias:** Two types of bone marrow depression occur: a dose-related, reversible depression (characterized by reticulocytopenia, leukopenia, and vacuolization of erythroid cells) and an idiosyncratic, irreversible aplastic anemia that can be fatal and may appear weeks or months after therapy. Baseline and periodic blood counts are mandatory.
INSERT INTO "drug_generic" VALUES(1273, 'Trilaciclib', 'Trilaciclib', 'V03AF08', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Interstitial Lung Disease (ILD) / Pneumonitis", "severity": "High", "trigger_condition": "Development of cough, dyspnea, or hypoxia during therapy", "message": "STOP: Severe, life-threatening, or fatal interstitial lung disease (ILD) and/or pneumonitis can occur. Monitor for pulmonary symptoms and interrupt or permanently discontinue therapy if suspected or confirmed."}]', '**Interstitial Lung Disease (ILD)/Pneumonitis:** Severe, life-threatening, or fatal ILD and/or pneumonitis have been reported with CDK4/6 inhibitors, including trilaciclib. Monitor patients for pulmonary symptoms indicative of ILD/pneumonitis (e.g., cough, dyspnea, hypoxia). Interrupt and evaluate if symptoms occur; permanently discontinue if severe.
INSERT INTO "drug_generic" VALUES(1274, 'Plecanatide', 'Plecanatide', 'A06AX07', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Pediatric Contraindication", "severity": "High", "trigger_condition": "Patient age < 6 years", "message": "STOP: Contraindicated in children under 6 years of age due to the risk of severe, potentially fatal dehydration. Avoid use in patients 6 to less than 18 years of age."}]', '**Severe Diarrhea:** Diarrhea is the most common adverse reaction and can sometimes be severe. If severe diarrhea occurs, suspend dosing immediately and rehydrate the patient appropriately.
INSERT INTO "drug_generic" VALUES(1275, 'Vancomycin', 'Vancomycin', 'J01XA01', 1, 1, 0, 1, 1, 1, 1, 0, '[{"alert_type": "Infusion Reaction", "severity": "High", "trigger_condition": "Rapid intravenous administration", "message": "STOP: Rapid IV infusion can cause ''Red Man Syndrome'' (severe hypotension, flushing, erythema, urticaria, and pruritus). Infuse slowly over at least 60 minutes or at a rate no greater than 10 mg/minute."}]', '**Nephrotoxicity:** Acute kidney injury can occur, particularly in patients receiving high doses, prolonged therapy, or concurrent nephrotoxic drugs (e.g., aminoglycosides). Monitor serum creatinine and vancomycin trough levels regularly.
INSERT INTO "drug_generic" VALUES(1276, 'Ramipril', 'Ramipril', 'C09AA05', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Discontinue Ramipril immediately upon detection of pregnancy. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}]', 'Use with caution in patients with renal impairment, hypovolemia, hyperkalemia, or valvular stenosis. Correct volume and/or salt depletion prior to initiating treatment to prevent symptomatic hypotension. Use with caution before, during, or immediately after anesthesia. Exercise caution in patients with severe resistant hypertension, the elderly, peripheral vascular disease, or generalized atherosclerosis. Monitor blood pressure, serum creatinine, and potassium levels regularly, especially during the first few weeks of treatment. Inform patients to refrain from activities involving mental alertness and physical coordination if they experience dizziness or syncope.', '- **Hypertension:** Used as monotherapy or in combination with other antihypertensive agents to lower blood pressure.
INSERT INTO "drug_generic" VALUES(1277, 'Alclometasone topical', 'Alclometasone Dipropionate', 'D07AB10', 0, 0, 0, 1, 0, 1, 1, 1, '[]', '**Pediatric Growth and Development:** Chronic topical corticosteroid therapy may interfere with growth and development in children due to systemic absorption. Use the lowest effective potency for the shortest duration possible.
INSERT INTO "drug_generic" VALUES(1278, 'Diphenhydramine Hydrochloride 2% + Zinc Acetate 0.1% Topical', 'Diphenhydramine Hydrochloride and Zinc Acetate Topical', 'D04AA32', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Systemic Toxicity Risk", "severity": "High", "trigger_condition": "Application to large body surface areas or concurrent use with oral diphenhydramine", "message": "STOP: Do not use on large areas of the body, on blistered/broken skin, or concurrently with any other product containing diphenhydramine (including oral formulations) due to the risk of systemic anticholinergic toxicity and toxic psychosis."}]', '- **External Use Only:** Strictly for topical application. Avoid contact with the eyes, mouth, and mucous membranes.
INSERT INTO "drug_generic" VALUES(1279, 'Betahistine Mesilate', 'Betahistine', 'N07CA01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Pheochromocytoma", "severity": "High", "trigger_condition": "Patients with known or suspected pheochromocytoma", "message": "STOP: Betahistine is a histamine analogue and can induce the release of catecholamines from a pheochromocytoma, causing a severe hypertensive crisis. Contraindicated in these patients."}]', '**Peptic Ulcer Disease:** Use with caution in patients with a history of peptic ulcer disease, as histamine analogues can theoretically stimulate gastric acid secretion.
INSERT INTO "drug_generic" VALUES(1280, 'Carbocisteine', 'Carbocysteine', 'R05CB03', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Gastrointestinal Bleeding", "severity": "High", "trigger_condition": "Active peptic ulceration", "message": "STOP: Carbocisteine can disrupt the gastric mucosal barrier. It is contraindicated in patients with active peptic ulceration."}]', '**History of Peptic Ulcer:** Use with caution in patients with a history of peptic ulcer disease, as mucolytics may disrupt the gastric mucosal barrier and induce bleeding.
INSERT INTO "drug_generic" VALUES(1281, 'Bismuth Subcitrate', 'Bismuth Subcitrate', 'A02BX05', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Neurological Toxicity", "severity": "High", "trigger_condition": "Prolonged use or use in severe renal impairment", "message": "STOP: Possibility of bismuth poisoning and fatal encephalopathy if given over prolonged periods or in patients with moderate-to-severe renal impairment."}]', '**Bismuth Toxicity and Encephalopathy:** Prolonged use or high doses can lead to systemic bismuth accumulation, resulting in fatal encephalopathy. Do not exceed recommended doses or duration of therapy.
INSERT INTO "drug_generic" VALUES(1282, 'Lanadelumab', 'Lanadelumab', 'B06AC05', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Signs of severe hypersensitivity", "message": "STOP: Severe hypersensitivity reactions have been reported. If a severe hypersensitivity reaction occurs, discontinue lanadelumab immediately and institute appropriate treatment."}]', 'Hypersensitivity reactions have been reported; if a severe hypersensitivity reaction occurs, discontinue lanadelumab and institute appropriate treatment.
INSERT INTO "drug_generic" VALUES(1283, 'Flupenthixol (flupentixol)', 'Flupentixol', 'N05AF01', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Increased Mortality in Elderly Patients with Dementia-Related Psychosis", "severity": "High", "trigger_condition": "Use in elderly patients with dementia", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Flupenthixol is not approved for the treatment of patients with dementia-related psychosis."}]', '- **Neuroleptic Malignant Syndrome (NMS):** A potentially fatal symptom complex (hyperthermia, muscle rigidity, altered mental status, autonomic instability) has been reported. Discontinue immediately if NMS is suspected.
INSERT INTO "drug_generic" VALUES(1284, 'Nylidrin', 'Nylidrin', 'C04AA02', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '**Cardiac Disease:** Use with caution in patients with underlying cardiac disease, such as uncompensated congestive heart failure or a history of tachyarrhythmias, as the beta-adrenergic stimulating properties may exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1285, 'Dopamine Hydrochloride', 'Dopamine', 'C01CA04', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Extravasation and Tissue Necrosis", "severity": "High", "trigger_condition": "Intravenous administration outside of a central venous catheter", "message": "STOP: Extravasation of dopamine can cause severe local ischemia and tissue necrosis. Administer via a central line whenever possible. If extravasation occurs, infiltrate the area immediately with phentolamine."}]', '**Hypovolemia:** Must be corrected with adequate volume expansion (intravenous fluids/blood products) prior to initiating dopamine therapy.
INSERT INTO "drug_generic" VALUES(1286, 'Minocycline dental prep', 'Minocycline', 'A01AB23', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Tooth Discoloration", "severity": "High", "trigger_condition": "Use during tooth development (pregnancy, infancy, childhood up to 8 years)", "message": "STOP: Use of tetracycline-class drugs during tooth development may cause permanent discoloration of the teeth (yellow-gray-brown)."}]', 'May cause permanent tooth discoloration (yellow-gray-brown) if used during tooth development (last half of pregnancy, infancy, and childhood to age 8). Overgrowth of non-susceptible organisms, including fungi, may occur. Use with caution in patients with a history of oral candidiasis.', '- **Periodontitis:** Indicated as an adjunct to scaling and root planing procedures for the reduction of pocket depth in adult patients with periodontitis.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to minocycline or other tetracyclines.
INSERT INTO "drug_generic" VALUES(1287, 'Imeglimin Hydrochloride', 'Imeglimin', 'A10BX16', 0, 0, 0, 0, 1, 0, 0, 0, '[]', '**Lactic Acidosis Risk:** Caution is advised when used in combination with Metformin due to the potential increased risk of lactic acidosis. Monitor patients for symptoms such as malaise, myalgia, respiratory distress, increasing somnolence, and nonspecific abdominal distress.
INSERT INTO "drug_generic" VALUES(1288, 'Sodium Zirconium Cyclosilicate', 'Sodium Zirconium Cyclosilicate', 'V03AE09', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Fluid Overload Risk", "severity": "Moderate", "trigger_condition": "Patients with heart failure, renal disease, or those requiring sodium restriction", "message": "Each 5-g dose contains approximately 400 mg of sodium. Monitor closely for signs of edema and adjust diuretic therapy as clinically indicated."}]', '**Gastrointestinal Motility Disorders:** Avoid use in patients with severe constipation, bowel obstruction, impaction, or abnormal postoperative bowel motility disorders. Safety and efficacy have not been established in these populations, and administration may exacerbate underlying gastrointestinal conditions.
INSERT INTO "drug_generic" VALUES(1289, 'Oxacillin', 'Oxacillin', 'J01CF04', 1, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. Cross-reactivity with cephalosporins and other beta-lactams can occur. Discontinue immediately if an allergic reaction occurs.
INSERT INTO "drug_generic" VALUES(1290, 'Ceftriaxone', 'Ceftriaxone', 'J01DD04', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Fatal Neonatal Precipitates", "severity": "High", "trigger_condition": "Concurrent use with IV calcium in neonates (\u226428 days)", "message": "STOP: Co-administration of ceftriaxone and IV calcium-containing products in neonates is contraindicated due to the risk of fatal intravascular ceftriaxone-calcium precipitates. Do not use in hyperbilirubinemic neonates."}, {"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Biliary and Renal Precipitates:** Ceftriaxone-calcium precipitates can form in the gallbladder (pseudolithiasis) and urinary tract, causing biliary colic, urolithiasis, and acute renal failure. Discontinue if symptoms occur. Ensure adequate hydration.
INSERT INTO "drug_generic" VALUES(1291, 'Edoxaban', 'Edoxaban', 'B01AF03', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Bleeding Risk and Spinal Hematoma", "severity": "High", "trigger_condition": "Active bleeding or neuraxial anesthesia", "message": "STOP: Edoxaban increases the risk of fatal bleeding. Premature discontinuation increases the risk of ischemic events. Epidural or spinal hematomas may occur in patients receiving neuraxial anesthesia, leading to permanent paralysis."}]', 'Premature discontinuation of edoxaban increases the risk of ischemic events; consider alternative anticoagulation if stopped for reasons other than bleeding. Do not use in patients with nonvalvular atrial fibrillation (NVAF) who have a CrCl >95 mL/min due to an increased risk of ischemic stroke compared to warfarin. Edoxaban increases the risk of serious and potentially fatal bleeding; promptly evaluate any signs of blood loss. Not recommended for patients with mechanical heart valves or moderate-to-severe mitral stenosis. Avoid use in patients with moderate to severe hepatic impairment (Child-Pugh B or C) due to intrinsic coagulation abnormalities.', '- **Stroke Prophylaxis in Nonvalvular Atrial Fibrillation (NVAF):** Indicated to reduce the risk of stroke and systemic embolism in patients with NVAF.
INSERT INTO "drug_generic" VALUES(1292, 'Poly ethylene Glycol 3350 + Electrolytes', 'Polyethylene Glycol 3350 with Electrolytes', 'A06AD65', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Bowel Obstruction", "severity": "High", "trigger_condition": "Symptoms suggestive of bowel obstruction (nausea, vomiting, abdominal pain, distention)", "message": "STOP: Evaluate the patient to rule out bowel obstruction or perforation before initiating therapy."}]', '**Cardiovascular Impairment:** Use with caution in patients with impaired cardiovascular function. For fecal impaction, divide the dose so no more than two sachets are taken in any one hour. Monitor for signs of fluid/electrolyte shifts (e.g., edema, shortness of breath, increasing fatigue, cardiac failure).
INSERT INTO "drug_generic" VALUES(1293, 'Canagliflozin', 'Canagliflozin', 'A10BK02', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Diabetic Ketoacidosis (DKA)", "severity": "High", "trigger_condition": "Patients presenting with nausea, vomiting, abdominal pain, or malaise", "message": "STOP: Assess for ketoacidosis regardless of presenting blood glucose levels (euglycemic DKA can occur). Discontinue immediately if DKA is suspected and initiate treatment."}, {"alert_type": "Lower Limb Amputation", "severity": "High", "trigger_condition": "Patients with a history of prior amputation, peripheral vascular disease, or neuropathy", "message": "STOP: Canagliflozin increases the risk of lower limb amputations (primarily of the toe and midfoot). Monitor for new pain, tenderness, sores, or ulcers involving the lower limbs."}]', '**Volume Depletion:** Can cause intravascular volume contraction, leading to symptomatic hypotension or acute kidney injury. Assess and correct volume status before initiating, especially in the elderly, patients with renal impairment, or those on loop diuretics.
INSERT INTO "drug_generic" VALUES(1294, 'Calcium polystyrene sulfonate (Calcium Resonium)', 'Calcium polystyrene sulfonate', 'V03AE01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Intestinal Necrosis", "severity": "High", "trigger_condition": "Concomitant use with sorbitol or in patients with reduced GI motility", "message": "STOP: Cases of fatal intestinal necrosis and gastrointestinal perforation have been reported, particularly when co-administered with sorbitol. Concomitant use with sorbitol is strictly contraindicated."}]', '**Intestinal Necrosis:** Severe gastrointestinal adverse events, including intestinal necrosis, ulceration, and perforation, have occurred. Risk is highest with concomitant sorbitol use, hypovolemia, or reduced GI motility. 
INSERT INTO "drug_generic" VALUES(1295, 'Gentian Violet', 'Gentian Violet', 'D01AE02', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Tissue Necrosis and Tattooing Risk", "severity": "High", "trigger_condition": "Application to ulcerative lesions or granulation tissue", "message": "Do not apply gentian violet to ulcerative lesions of the face or other areas where aesthetic appearance is critical, as it may cause permanent tattooing of the skin. Application to granulation tissue can cause severe tissue necrosis."}]', 'Gentian violet is for external use only. Do not ingest or apply to the eyes. Discontinue use if the condition persists, worsens, or if severe irritation, redness, or swelling occurs. Prolonged use (longer than 1 to 2 weeks) is not recommended due to the risk of severe skin irritation and potential systemic toxicity. Use with caution in patients with porphyria. Gentian violet will stain skin, clothing, and mucous membranes intensely purple. Animal studies have suggested a potential carcinogenic risk with systemic exposure; therefore, limit use to short-term, localized topical application.', '- **Superficial Fungal and Bacterial Infections:** Topical antiseptic and antifungal agent used as first aid to help prevent infection in minor cuts, scrapes, and burns.
INSERT INTO "drug_generic" VALUES(1296, 'Doxylamine + Pyridoxine', 'Doxylamine and Pyridoxine', 'R06AA59', 0, 0, 1, 0, 0, 0, 0, 0, '[{"alert_type": "Severe CNS Depression", "severity": "High", "trigger_condition": "Coadministration with alcohol or other CNS depressants", "message": "STOP: Coadministration with alcohol or other CNS depressants can cause severe drowsiness, leading to falls, accidents, or respiratory depression. Avoid concurrent use."}]', '**CNS Depression:** Somnolence is the most common adverse effect. Patients should avoid activities requiring mental alertness, such as driving or operating heavy machinery.
INSERT INTO "drug_generic" VALUES(1297, 'Ketoprofen', 'Ketoprofen', 'M01AE03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation of the stomach or intestines."}]', '- **Cardiovascular Risk:** May cause fluid retention, edema, and hypertension. Use with caution in patients with heart failure or cardiovascular disease. Monitor blood pressure closely.
INSERT INTO "drug_generic" VALUES(1298, 'Chloroquine Phosphate', 'Chloroquine', 'P01BA01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Irreversible Retinopathy", "severity": "High", "trigger_condition": "Long-term or high-dose therapy", "message": "STOP: Irreversible retinal damage has been observed in some patients receiving long-term or high-dosage 4-aminoquinoline therapy. Baseline and periodic ophthalmologic examinations are mandatory."}, {"alert_type": "Cardiotoxicity", "severity": "High", "trigger_condition": "High doses or rapid intravenous administration", "message": "STOP: Fatal cardiac arrhythmias, QT prolongation, and cardiovascular collapse can occur. Avoid concurrent use with other QT-prolonging drugs."}]', '**Ocular Toxicity:** Irreversible retinal damage, macular degeneration, and visual field defects can occur. Discontinue immediately if any visual abnormalities arise.
INSERT INTO "drug_generic" VALUES(1299, 'Lofexidine', 'Lofexidine', 'N07BC04', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Hypotension and Bradycardia", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "May cause severe hypotension, bradycardia, and syncope. Monitor vital signs closely. Instruct outpatients to withhold doses if experiencing symptoms of hypotension or bradycardia."}]', '**Hypotension, Bradycardia, and Syncope:** May cause significant decreases in blood pressure and heart rate. Monitor vital signs before dosing and assess for symptoms related to bradycardia and orthostasis. Avoid use in patients with severe coronary insufficiency, recent myocardial infarction, cerebrovascular disease, chronic renal failure, and marked bradycardia.
INSERT INTO "drug_generic" VALUES(1300, 'Butoconazole vaginal prep', 'Butoconazole', 'G01AF15', 0, 0, 0, 1, 0, 1, 0, 0, '[]', 'Use with caution in patients with a history of hypersensitivity to other azole antifungals, as cross-reactivity may occur. Evaluate patients presenting with recurrent vaginal yeast infections (more than three infections in a 6-month period) or first-time infections to rule out underlying conditions such as diabetes mellitus, immunodeficiency, or HIV infection. The mineral oil base in the formulation may weaken latex or rubber products, including condoms and vaginal contraceptive diaphragms; advise patients to avoid using these barrier methods concurrently and for at least 72 hours following treatment. Avoid contact with the eyes. Discontinue use if sensitization or severe irritation occurs.', '- **Vulvovaginal Candidiasis:** Indicated for the local treatment of vulvovaginal candidiasis (moniliasis). It is effective in eradicating fungal infections localized to the vaginal mucosa and providing symptomatic relief from associated pruritus and discharge.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to butoconazole or any component of the formulation. Rationale: Re-exposure can trigger severe local or systemic allergic reactions.
INSERT INTO "drug_generic" VALUES(1301, 'Diabasic Sodium Phosphate  +  Monobasic Sodium Phosphate', 'Sodium Phosphate, Dibasic / Sodium Phosphate, Monobasic', 'A06AD17', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Acute Phosphate Nephropathy", "severity": "High", "trigger_condition": "Use of oral sodium phosphate products for colon cleansing, especially in patients >55 years, hypovolemic, or with baseline kidney disease.", "message": "STOP: Rare but severe reports of acute phosphate nephropathy, sometimes resulting in permanent renal impairment requiring long-term hemodialysis, have occurred. Ensure aggressive hydration and avoid in high-risk patients."}]', '**Renal Function:** Assess renal function before and during therapy. Renal impairment may occur; frequent monitoring of serum calcium, phosphate, sodium, and potassium is recommended.
INSERT INTO "drug_generic" VALUES(1302, 'Epinastine Hydrochloride 0.05% Eye prep', 'Epinastine', 'S01GX10', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Contact Lens Wear:** The formulation may contain benzalkonium chloride, which can be absorbed by soft contact lenses and cause discoloration or ocular irritation. Patients should be instructed to remove contact lenses prior to instillation and wait at least 10 to 15 minutes before re-inserting them. Epinastine should not be used to treat contact lens-related irritation.
INSERT INTO "drug_generic" VALUES(1303, 'Ozenoxacin topical', 'Ozenoxacin', 'D06AX14', 1, 0, 1, 1, 0, 1, 1, 0, '[]', 'Prolonged use of ozenoxacin may result in the overgrowth of nonsusceptible bacteria and fungi. If superinfection occurs, discontinue use and institute alternative appropriate antimicrobial therapy. Antagonism interactions with ozenoxacin were observed with ciprofloxacin against S. aureus in vitro; clinical significance is unknown but concurrent use on the same site should be avoided. For external use only; avoid contact with eyes, mouth, lips, inside the nose, or inside the female genital area.', '- Topical treatment of impetigo due to susceptible isolates of Staphylococcus aureus (including methicillin-resistant isolates) or Streptococcus pyogenes in adult and pediatric patients aged 2 months and older.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to ozenoxacin or any components of the formulation, due to the risk of localized or systemic allergic reactions.', '- **Rosacea** (Exacerbation or new onset at the application site)
INSERT INTO "drug_generic" VALUES(1304, 'Isoniazid + Pyrazinamide + Rifampicin', 'Isoniazid, Pyrazinamide, and Rifampin', 'J04AM05', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Hepatotoxicity", "severity": "High", "trigger_condition": "Combination therapy with multiple hepatotoxic agents", "message": "STOP: This combination contains three hepatotoxic drugs. Severe and sometimes fatal hepatitis can occur. Monitor liver function tests strictly at baseline and periodically. Discontinue immediately if clinical signs of hepatitis develop."}]', '**Hepatotoxicity:** All three components can cause liver damage. The risk is compounded when used together. Monitor AST, ALT, and bilirubin at baseline and periodically. Instruct patients to report anorexia, nausea, vomiting, dark urine, or jaundice immediately.
INSERT INTO "drug_generic" VALUES(1305, 'Calcium Citrate + Calcitriol', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Impaired calcium absorption in achlorhydria is common in the elderly. INSERT INTO "drug_generic" VALUES(1306, 'Stavudine', 'Stavudine', 'J05AF04', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Lactic Acidosis and Hepatomegaly", "severity": "High", "trigger_condition": "Concomitant use with didanosine or presence of hepatic risk factors", "message": "STOP: Fatal lactic acidosis and severe hepatomegaly with steatosis have been reported. Coadministration with didanosine is strictly contraindicated."}, {"alert_type": "Neurologic Toxicity", "severity": "High", "trigger_condition": "Patient history of peripheral neuropathy or advanced HIV disease", "message": "WARNING: Severe peripheral neuropathy can occur. Monitor closely and consider dose reduction or discontinuation if symptoms develop."}]', '**Hepatic Disease:** Use with extreme caution in patients with hepatomegaly, hepatitis, or other risk factors for liver disease (especially obese women). Fatal lactic acidosis and severe hepatomegaly with steatosis have been reported.
INSERT INTO "drug_generic" VALUES(1307, 'Droperidol', 'Droperidol', 'N05AD08', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "QT Prolongation and Torsades de Pointes", "severity": "High", "trigger_condition": "Administration of droperidol, especially in patients with underlying cardiac risk factors", "message": "STOP: Droperidol can cause dose-related prolongation of the QT interval, leading to fatal Torsades de Pointes. Perform baseline ECG and monitor continuously for 2-3 hours post-administration."}]', '**Cardiovascular Risk:** High risk of QT prolongation and fatal arrhythmias. Perform a 12-lead ECG prior to administration. Continue continuous ECG monitoring for 2 to 3 hours after administration.
INSERT INTO "drug_generic" VALUES(1308, 'Amino Acids (5%) + Sorbitol + Vitamins + Electrolytes', 'Amino Acids + Sorbitol + Vitamins + Electrolytes', 'B05BA10', 0, 1, 1, 1, 1, 0, 1, 1, '[{"alert_type": "Pulmonary Embolism Risk", "severity": "High", "trigger_condition": "Precipitate formation in the intravenous line", "message": "STOP: Pulmonary vascular precipitates causing pulmonary embolism and respiratory distress have been reported. Inspect solutions and lines visually. If signs of pulmonary distress occur, stop the infusion immediately and initiate a medical evaluation."}]', '**Pulmonary Vascular Precipitates:** Fatal pulmonary embolism has occurred due to precipitates. Inspect the solution and infusion set regularly.
INSERT INTO "drug_generic" VALUES(1309, 'Hypromellose 0.3% + Carbomer 0.22% Eye prep', 'Hypromellose / Carbomer Ophthalmic Gel', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Discontinue use and consult a physician if eye pain, changes in vision, or continued redness and irritation of the eye occur, or if the condition worsens or persists for more than 72 hours. Do not use if the gel changes color or becomes cloudy. This product is for topical ophthalmic use only; it must never be injected subconjunctivally or introduced directly into the anterior chamber of the eye. It is not intended for use during ocular surgery. Remove contact lenses prior to application unless the specific product labeling states it is safe for use with lenses.', '- **Dry Eye Syndrome:** For the relief of dry eye conditions and management of a stable tear film.
INSERT INTO "drug_generic" VALUES(1310, 'Vitamin B7 (Biotin)', 'Biotin', 'A11HA05', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Laboratory Test Interference", "severity": "Moderate", "trigger_condition": "High doses of biotin (>5 mg/day)", "message": "High doses of biotin can significantly interfere with certain laboratory tests (e.g., thyroid function tests, troponin), causing falsely high or falsely low results. Discontinue biotin several days before lab tests."}]', 'Biotin deficiency can be induced by long-term consumption of raw egg whites (which contain avidin, a biotin-binding protein), long-term antibiotic use (which alters intestinal flora), or chronic use of anti-seizure medications. Be aware of significant laboratory test interference; biotin can alter the results of immunoassays that use biotin-streptavidin technology, leading to misdiagnosis (e.g., falsely low troponin leading to missed myocardial infarction, or falsely altered thyroid panels).', '- **Biotin Deficiency:** Treatment and prevention of biotin deficiency (characterized by dermatitis, alopecia, depression, and anemia).
INSERT INTO "drug_generic" VALUES(1311, 'Domperidone', 'Domperidone', 'A03FA03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiac Arrhythmias and QT Prolongation", "severity": "High", "trigger_condition": "Concurrent use with QT-prolonging drugs, significant electrolyte disturbances, or underlying cardiac disease", "message": "STOP: Domperidone is associated with an increased risk of QT prolongation, serious ventricular arrhythmias, and sudden cardiac death. Use the lowest effective dose for the shortest possible duration."}]', '**Cardiac Risk:** Use with extreme caution in patients older than 60 years or those receiving daily doses greater than 30 mg, as the risk of serious ventricular arrhythmias and sudden cardiac death is significantly increased.
INSERT INTO "drug_generic" VALUES(1312, 'Propafenone Hydrochloride', 'Propafenone', 'C01BC03', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Proarrhythmic Effects", "severity": "High", "trigger_condition": "Patients with structural heart disease or prior myocardial infarction", "message": "WARNING: Propafenone can cause new or worsened arrhythmias. It is contraindicated in patients with structural heart disease (e.g., heart failure, prior MI) due to an increased risk of mortality. Initiate therapy in a monitored clinical setting."}]', '- **Proarrhythmia:** May provoke or worsen ventricular arrhythmias. Continuous ECG monitoring is recommended during initiation.
INSERT INTO "drug_generic" VALUES(1313, 'Brinzolamide 1%  Eye prep', 'Brinzolamide', 'S01EC04', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hypersensitivity Risk", "severity": "High", "trigger_condition": "Patient history of sulfonamide allergy", "message": "STOP: Brinzolamide is a sulfonamide. Severe hypersensitivity reactions, including Stevens-Johnson syndrome and toxic epidermal necrolysis, can occur even with topical administration."}]', '**Sulfonamide Hypersensitivity:** Brinzolamide is a sulfonamide. Systemic absorption occurs, and severe, potentially fatal reactions (e.g., Stevens-Johnson syndrome, toxic epidermal necrolysis, fulminant hepatic necrosis) have been reported with sulfonamides. Discontinue immediately if signs of serious reactions or hypersensitivity occur.
INSERT INTO "drug_generic" VALUES(1314, 'Pexidartinib', 'Pexidartinib', 'L01EX16', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Hepatotoxicity", "severity": "High", "trigger_condition": "Initiation of therapy or elevated transaminases", "message": "STOP: Can cause severe and potentially fatal hepatotoxicity, including ductopenia and cholestasis. Available only through a restricted REMS program. Monitor liver tests weekly for the first 8 weeks, then periodically."}]', '**Hepatotoxicity:** Severe liver injury, including mixed or cholestatic hepatotoxicity and ductopenia, has occurred. Monitor AST, ALT, total bilirubin, and ALP prior to initiation, weekly for the first 8 weeks, every 2 weeks for the next month, and every 3 months thereafter. Dose reduction, interruption, or permanent discontinuation may be required.
INSERT INTO "drug_generic" VALUES(1315, 'Avanafil', 'Avanafil', 'G04BE10', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Hypotension", "severity": "High", "trigger_condition": "Concomitant use of nitrates or nitric oxide donors", "message": "STOP: Coadministration with nitrates in any form is strictly contraindicated. Severe, refractory hypotension and syncope can occur."}]', '**Cardiovascular Risk:** Sexual activity carries a cardiac risk. Avanafil should not be used in men for whom sexual activity is inadvisable due to underlying cardiovascular status. Monitor patients with left ventricular outflow obstruction.
INSERT INTO "drug_generic" VALUES(1316, 'Phenobarbitone Sodium inj', 'Phenobarbital Sodium Injection', 'N03AA02', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Administration Rate Warning", "severity": "High", "trigger_condition": "Intravenous administration", "message": "STOP: Too rapid IV administration may cause severe hypotension, respiratory depression, apnea, and cardiac arrest. Do not exceed 60 mg/min in adults or 2 mg/kg/min in pediatric patients."}]', '**Respiratory and Cardiovascular Depression:** Intravenous administration can cause severe respiratory depression, apnea, laryngospasm, and hypotension. Resuscitative equipment and personnel must be immediately available.
INSERT INTO "drug_generic" VALUES(1317, 'Fluocinolone 0.1% + Neomycin Sulphate 0.5% Eye prep', 'Fluocinolone Acetonide 0.1% and Neomycin Sulfate 0.5% Ophthalmic', 'S01CA04', 1, 0, 0, 0, 0, 0, 0, 1, '[]', 'Prolonged use of ophthalmic corticosteroids may result in glaucoma with damage to the optic nerve, defects in visual acuity and fields of vision, and posterior subcapsular cataract formation. Intraocular pressure (IOP) should be routinely monitored. Corticosteroids may mask infection or enhance existing infections. Use with caution in patients with a history of herpes simplex keratitis. Neomycin may cause cutaneous sensitization.', '- **Steroid-Responsive Inflammatory Ocular Conditions:** Treatment of inflammatory conditions of the palpebral and bulbar conjunctiva, cornea, and anterior segment of the globe where the risk of superficial bacterial ocular infection exists or is expected.', '- **Viral and Fungal Eye Infections:** Contraindicated in epithelial herpes simplex keratitis (dendritic keratitis), vaccinia, varicella, and other viral diseases of the cornea and conjunctiva, as well as mycobacterial and fungal infections of the eye.
INSERT INTO "drug_generic" VALUES(1318, 'Calcium Gluconate', 'Calcium Gluconate', 'A12AA03', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Extravasation and Tissue Necrosis", "severity": "High", "trigger_condition": "Intravenous administration", "message": "STOP: Severe tissue necrosis, ulceration, and calcinosis cutis can occur with extravasation. Ensure proper IV access and monitor site continuously."}, {"alert_type": "Fatal Precipitates in Neonates", "severity": "High", "trigger_condition": "Concurrent use with Ceftriaxone in neonates (\u226428 days)", "message": "STOP: Co-administration with ceftriaxone in neonates is contraindicated due to the risk of fatal intravascular ceftriaxone-calcium precipitates."}]', '**Arrhythmias with Rapid Administration:** Rapid intravenous administration may cause severe adverse reactions including hypotension, bradycardia, cardiac arrhythmias, syncope, and cardiac arrest. Infuse slowly with careful ECG monitoring.
INSERT INTO "drug_generic" VALUES(1319, 'Lacidipine', 'Lacidipine', 'C08CA09', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Angina Exacerbation", "severity": "Moderate", "trigger_condition": "Initiation of therapy or dose escalation", "message": "Rarely, dihydropyridine calcium channel blockers can cause an increase in frequency, duration, or severity of angina or acute myocardial infarction upon initiation or dose escalation."}]', 'Use with caution in patients with poor cardiac reserve, conduction abnormalities, or congenital/acquired QT prolongation. Caution is advised in patients with hepatic impairment, as lacidipine is extensively metabolized by the liver, and its bioavailability may increase. Monitor blood pressure closely during initiation and dose adjustments.', '- **Hypertension:** Treatment of essential hypertension, either as monotherapy or in combination with other antihypertensive agents (e.g., beta-blockers, diuretics, ACE inhibitors).', '- **Cardiogenic Shock:** Contraindicated due to the risk of further hemodynamic collapse.
INSERT INTO "drug_generic" VALUES(1320, 'Eegesterone + Ethinyl estradiol vaginal prep', 'Segesterone acetate and Ethinyl estradiol', 'G02BB01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Women over 35 years old who smoke", "message": "STOP: Cigarette smoking increases the risk of serious cardiovascular events from combination hormonal contraceptives (CHCs). This risk increases with age, particularly in women over 35 years of age, and with the number of cigarettes smoked. Contraindicated in women over 35 years of age who smoke."}]', 'Acute liver test abnormalities may necessitate discontinuation of use until liver tests return to normal and causation from the vaginal system has been excluded.
INSERT INTO "drug_generic" VALUES(1321, 'Diosmin + Hesperidin', 'Diosmin and Hesperidin', 'C05CA53', 0, 0, 1, 0, 0, 1, 0, 0, '[]', '**Acute Hemorrhoidal Attacks:** Administration of this product does not preclude specific treatment for other anal disorders. The treatment must be short-term. If symptoms do not subside promptly, a proctological examination should be performed and the treatment reviewed.
INSERT INTO "drug_generic" VALUES(1322, 'Foscarnet', 'Foscarnet Sodium', 'J05AD01', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Renal Impairment and Seizures", "severity": "High", "trigger_condition": "Inadequate hydration or rapid IV infusion", "message": "STOP: Renal impairment is the major toxicity. Frequent monitoring of serum creatinine is required. Seizures related to alterations in plasma minerals and electrolytes (calcium, magnesium, potassium, phosphorus) have been associated with fatal outcomes. Do not administer by rapid IV injection."}]', '**Renal Toxicity:** Major toxicity is renal impairment. Monitor serum creatinine 2-3 times weekly during induction and at least weekly during maintenance. Adequate IV hydration is required to minimize nephrotoxicity.
INSERT INTO "drug_generic" VALUES(1323, 'Measles and Rubella Vaccine (Live, attenuated)', 'Measles and Rubella Virus Vaccine Live', 'J07BD53', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Administration of live vaccine", "message": "STOP: Epinephrine (1:1000) and other emergency equipment must be immediately available to treat potential anaphylactic reactions following vaccination."}]', '- **Route of Administration:** Do not administer intravenously.
INSERT INTO "drug_generic" VALUES(1324, 'Abametapir topical', 'Abametapir', 'P03AX07', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Neonatal Toxicity Risk", "severity": "High", "trigger_condition": "Administration to neonates or infants <6 months of age", "message": "STOP: The lotion contains benzyl alcohol. Systemic exposure to benzyl alcohol has been associated with serious and fatal adverse reactions, including ''gasping syndrome'' in neonates and low-birth-weight infants. Do not use in pediatric patients aged <6 months."}]', 'In order to prevent accidental ingestion in pediatric patients, only administer under the direct supervision of an adult. Avoid contact with the eyes; if contact occurs, flush thoroughly with water. Do not use on irritated or broken skin.', '- **Head Lice Infestation:** Indicated for the topical treatment of head lice infestation in patients 6 months of age and older.', '- **Hypersensitivity:** Contraindicated in patients with known hypersensitivity to abametapir or any of the excipients in the formulation.
INSERT INTO "drug_generic" VALUES(1325, 'Cinnarizine + Dimenhydrinate', 'Cinnarizine + Dimenhydrinate', 'N07CA52', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe CNS Depression", "severity": "High", "trigger_condition": "Concurrent use with alcohol or other CNS depressants", "message": "Potentiates severe sedative effects. Avoid alcohol and use extreme caution with other CNS depressants. Do not drive or operate machinery."}]', '**Parkinson''s Disease:** Use with caution; cinnarizine can aggravate extrapyramidal symptoms.
INSERT INTO "drug_generic" VALUES(1326, 'Mebendazole', 'Mebendazole', 'P02CA01', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Bone Marrow Suppression", "severity": "High", "trigger_condition": "Prolonged use or high-dose therapy", "message": "STOP: Potentially fatal myelosuppression, including agranulocytosis and neutropenia, has been reported. Monitor complete blood counts (CBC) periodically during prolonged therapy."}]', '**Hepatic Impairment:** Mebendazole is extensively metabolized by the liver. Use with caution in patients with hepatic impairment, as drug clearance may be delayed, leading to increased systemic exposure and toxicity.
INSERT INTO "drug_generic" VALUES(1327, 'Oxygen 99 % Gas', 'Oxygen', 'V03AN01', 0, 0, 1, 1, 0, 1, 1, 1, '[{"alert_type": "Fire Hazard", "severity": "High", "trigger_condition": "Presence of ignition sources", "message": "STOP: Oxygen vigorously accelerates combustion. Keep away from heat, sparks, open flames, and smoking materials. Do not use oil or grease on oxygen equipment."}]', '**COPD and Chronic Hypercapnia:** High concentrations of oxygen in patients with chronic obstructive pulmonary disease (COPD) can depress the hypoxic drive to breathe, leading to severe hypercapnia, respiratory acidosis, and respiratory arrest. Titrate carefully to target SpO2 (usually 88-92%).
INSERT INTO "drug_generic" VALUES(1328, 'Ritonavir + Lopinavir', 'Lopinavir and Ritonavir', 'J05AR10', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Drug Interactions", "severity": "High", "trigger_condition": "Concurrent use with highly CYP3A-dependent drugs", "message": "STOP: Lopinavir/Ritonavir is a potent CYP3A inhibitor. Co-administration with drugs highly dependent on CYP3A for clearance can result in life-threatening toxicities."}]', '**Hepatotoxicity:** Hepatic dysfunction, including fatalities, has occurred. Monitor liver function tests before and during therapy, especially in patients with underlying hepatic disease or hepatitis B/C co-infection.
INSERT INTO "drug_generic" VALUES(1329, 'Mebhydrolin', 'Mebhydrolin', 'R06AX15', 0, 0, 0, 0, 1, 0, 1, 0, '[]', '**Anticholinergic Effects:** Use with caution in patients with closed-angle glaucoma, urinary retention, prostatic hyperplasia, or pyloroduodenal obstruction, as antimuscarinic properties can exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1330, 'Axitinib', 'Axitinib', 'L01EX08', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Fatal Hemorrhage and Thromboembolism", "severity": "High", "trigger_condition": "Recent active bleeding or history of thromboembolic events", "message": "STOP: High risk of fatal hemorrhagic events and arterial/venous thromboembolism. Do not use in patients with untreated brain metastasis or recent active GI bleeding."}]', '**Hypertension:** Hypertensive crisis can occur. Blood pressure must be well-controlled prior to initiation. Monitor BP regularly and treat as needed.
INSERT INTO "drug_generic" VALUES(1331, 'Niraparib', 'Niraparib', 'L01XK02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hematologic Toxicity", "severity": "High", "trigger_condition": "Initiation of therapy or ongoing treatment", "message": "STOP: Myelodysplastic syndrome (MDS) and acute myeloid leukemia (AML) have been reported. Do not initiate until patients recover from prior chemotherapy hematological toxicities. Monitor CBC weekly for the first month."}]', '**Myelodysplastic Syndrome/Acute Myeloid Leukemia (MDS/AML):** MDS/AML, including cases with fatal outcomes, have been reported. Discontinue the drug if MDS/AML is confirmed.
INSERT INTO "drug_generic" VALUES(1332, 'Tretinoin', 'Tretinoin (Oral)', 'L01XF01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Retinoic Acid-APL Syndrome", "severity": "High", "trigger_condition": "Initiation of therapy in patients with Acute Promyelocytic Leukemia (APL)", "message": "STOP: Patients may experience a potentially fatal syndrome characterized by fever, dyspnea, acute respiratory distress, weight gain, radiographic pulmonary infiltrates, pleural/pericardial effusions, and edema. High-dose dexamethasone must be initiated immediately at the first signs."}]', '- **Retinoic Acid-APL Syndrome (Differentiation Syndrome):** Monitor closely for unexplained fever, dyspnea, weight gain, and pulmonary infiltrates. Initiate high-dose corticosteroids (e.g., dexamethasone 10 mg IV every 12 hours) immediately upon suspicion.
INSERT INTO "drug_generic" VALUES(1333, 'Thioridazine hydrochloride', 'Thioridazine', 'N05AH04', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "QT Prolongation and Sudden Death", "severity": "High", "trigger_condition": "Prescribing to any patient", "message": "Thioridazine causes dose-related prolongation of the QTc interval, which is associated with fatal arrhythmias (Torsades de Pointes) and sudden death. It is restricted to schizophrenic patients who fail to respond to other antipsychotics."}]', 'Perform baseline ECG and serum potassium levels before starting therapy and periodically thereafter. Avoid in patients with uncorrected hypokalemia or any electrolyte imbalance. Monitor for signs of Neuroleptic Malignant Syndrome (NMS) and Tardive Dyskinesia. Use with extreme caution in the elderly, particularly those with dementia-related psychosis, due to an increased risk of mortality. Monitor for anticholinergic effects, especially in patients with narrow-angle glaucoma, paralytic ileus, or prostatic hyperplasia. May lower the seizure threshold; use cautiously in patients with epilepsy. Avoid abrupt withdrawal to prevent rebound psychosis and cholinergic rebound.', '- **Schizophrenia (Refractory):** Management of schizophrenic patients who fail to show an acceptable response to adequate courses of other antipsychotic drugs, either because of insufficient effectiveness or the inability to achieve an effective dose due to intolerable adverse effects.
INSERT INTO "drug_generic" VALUES(1334, 'Typhoid polysaccharide Vaccine', 'Typhoid Vi Polysaccharide Vaccine', 'J07AP03', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Incomplete Protection:** Vaccination does not provide 100% protection against typhoid fever. Travelers must be advised to continue taking standard food and water precautions (e.g., drinking bottled water, avoiding raw foods) in endemic areas.
INSERT INTO "drug_generic" VALUES(1335, 'Iodine 2.5 %', 'Povidone-Iodine 2.5%', 'D08AG03', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '- Avoid application over large surface areas or for prolonged periods, especially in children, the elderly (>45 years), and patients with renal impairment, due to the risk of systemic iodine absorption.
INSERT INTO "drug_generic" VALUES(1336, 'Mifepristone + Misoprostol', 'Mifepristone and Misoprostol', 'G03XB51', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Bleeding and Infection Risk", "severity": "High", "trigger_condition": "Use for medical termination of pregnancy", "message": "STOP: Serious and sometimes fatal infections and bleeding can occur following use. Patients must be evaluated for ectopic pregnancy prior to use and must have access to emergency medical care."}]', '- **Ectopic Pregnancy:** This regimen is not effective for treating ectopic pregnancy. An ultrasound scan and/or measurement of Beta-hCG must be performed before administration to rule this out.
INSERT INTO "drug_generic" VALUES(1337, 'Rosiglitazone', 'Rosiglitazone', 'A10BG02', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Congestive Heart Failure Risk", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "STOP: Thiazolidinediones, including rosiglitazone, can cause or exacerbate congestive heart failure. Monitor carefully for signs of fluid retention. Contraindicated in NYHA Class III or IV heart failure."}]', '**Congestive Heart Failure:** Thiazolidinediones cause dose-related fluid retention, which can lead to or exacerbate congestive heart failure (CHF). Observe patients for signs and symptoms of heart failure (e.g., rapid weight gain, dyspnea, edema). If heart failure develops, manage according to current standards of care and consider discontinuation or dose reduction. Contraindicated in NYHA Class III and IV.
INSERT INTO "drug_generic" VALUES(1338, 'Raxibacumab', 'Raxibacumab', 'J06BC02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Infusion Reactions", "severity": "High", "trigger_condition": "Administration of Raxibacumab", "message": "STOP: Infusion reactions (rash, urticaria, pruritus) can occur. Premedicate with diphenhydramine within 1 hour before infusion. Slow or interrupt the infusion if severe reactions occur."}]', '**Infusion Reactions:** Infusion-related reactions, including rash, urticaria, and pruritus, have been reported. Premedicate all patients with diphenhydramine within 1 hour prior to administering the infusion. If an infusion reaction occurs, slow or interrupt the IV infusion and administer appropriate medical treatment based on the severity of the reaction.
INSERT INTO "drug_generic" VALUES(1339, 'Nicorandil', 'Nicorandil', 'C01DX16', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Hypotension Risk", "severity": "High", "trigger_condition": "Concomitant use with phosphodiesterase type-5 (PDE5) inhibitors", "message": "STOP: Co-administration with PDE5 inhibitors (e.g., sildenafil, tadalafil) is strictly contraindicated due to the risk of profound, potentially fatal hypotension."}]', 'Use with extreme caution in patients with hypovolemia, low systolic blood pressure, or acute pulmonary edema, as the vasodilatory effects may exacerbate hemodynamic instability. Monitor closely for signs of gastrointestinal ulceration, including stomatitis and aphthous ulcers, which may progress to severe gastrointestinal bleeding or perforation; discontinue therapy if ulcers develop. Caution is advised in patients operating hazardous machinery or driving, as the drug may cause dizziness or weakness. Use cautiously in patients with hepatic impairment, as dose reductions may be necessary.', '- **Angina Pectoris:** Indicated for the prevention and long-term treatment of chronic stable angina pectoris, particularly in patients who remain symptomatic despite optimal doses of beta-blockers, calcium channel blockers, and long-acting nitrates, or in those who cannot tolerate these agents.', '- **Cardiogenic Shock or Severe Hypotension:** Contraindicated as further vasodilation will exacerbate hemodynamic collapse and compromise organ perfusion.
INSERT INTO "drug_generic" VALUES(1340, 'Niacinamide + Pyridoxine + Riboflavin + Thiamine + Zinc', 'Niacinamide + Pyridoxine + Riboflavin + Thiamine + Zinc', 'A11EX', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Underlying Deficiencies:** While this supplement treats mild deficiencies, severe or specific vitamin deficiencies (e.g., pernicious anemia) require targeted, high-dose therapy.
INSERT INTO "drug_generic" VALUES(1341, 'Tramadol Hydrochloride', 'Tramadol', 'N02AX02', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Addiction, Abuse, Respiratory Depression, and Serotonin Syndrome", "severity": "High", "trigger_condition": "Concomitant use with CNS depressants, serotonergic drugs, or in pediatric patients", "message": "STOP: Tramadol exposes patients to risks of opioid addiction, abuse, and misuse, which can lead to overdose and death. Serious, life-threatening respiratory depression may occur. Concomitant use with serotonergic drugs increases the risk of fatal Serotonin Syndrome. Contraindicated in children under 12 years."}]', 'Use with extreme caution in patients with a history of epilepsy or those at risk for seizures; tramadol lowers the seizure threshold. Risk is increased with doses above the recommended range or with concurrent use of SSRIs, SNRIs, TCAs, or other seizure-lowering drugs. Caution in patients with head injury, increased intracranial pressure, or emotional disturbance/depression. Monitor for signs of tolerance, abuse, or suicidal ideation. May impair the ability to drive or operate machinery. Adjust dose in renal and hepatic impairment and in the elderly.', '- **Moderate to Severe Pain:** Management of moderate to severe acute and chronic pain conditions, including postoperative pain, colic, spastic pain, cancer pain, joint pain, neck/back pain, and pain associated with osteoarthritis.', '- **Pediatric Patients (<12 years):** Contraindicated due to the risk of life-threatening respiratory depression, especially in ultra-rapid CYP2D6 metabolizers.
INSERT INTO "drug_generic" VALUES(1342, 'Propranolol Hydrochloride', 'Propranolol', 'C07AA05', 0, 1, 0, 1, 1, 0, 1, 1, '[{"alert_type": "Abrupt Withdrawal Risk", "severity": "High", "trigger_condition": "Discontinuation of therapy in patients with coronary artery disease", "message": "WARNING: Abrupt withdrawal of propranolol can exacerbate angina pectoris or precipitate myocardial infarction. Discontinue gradually over 1 to 2 weeks and monitor the patient closely."}]', '- **Respiratory Disease:** Use with extreme caution or avoid in patients with a history of nonallergic bronchospasm (e.g., chronic bronchitis, emphysema) due to non-selective beta-blockade.
INSERT INTO "drug_generic" VALUES(1343, 'Glimepiride + Rosiglitazone', 'Glimepiride and Rosiglitazone', 'A10BD04', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Congestive Heart Failure and Myocardial Ischemia Risk", "severity": "High", "trigger_condition": "Patients with a history of heart failure or cardiovascular disease", "message": "Thiazolidinediones, including rosiglitazone, cause or exacerbate congestive heart failure. Rosiglitazone has also been associated with an increased risk of myocardial ischemia (angina, myocardial infarction). Observe patients closely for signs of heart failure. Contraindicated in NYHA Class III or IV heart failure."}]', 'Rosiglitazone can cause dose-related fluid retention, leading to or exacerbating congestive heart failure. Monitor for signs of heart failure (rapid weight gain, dyspnea, edema). Rosiglitazone is associated with an increased risk of myocardial infarction; use with caution in patients with underlying cardiovascular disease. Glimepiride carries a risk of severe hypoglycemia, especially in vulnerable populations (elderly, renal/hepatic impairment). Monitor liver enzymes prior to initiation and periodically thereafter. Rosiglitazone increases the risk of bone fractures, particularly in females. Macular edema has been reported.', '- **Type 2 Diabetes Mellitus:** Indicated as an adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus when treatment with both rosiglitazone and glimepiride is appropriate.', '- **Heart Failure:** Contraindicated in patients with established New York Heart Association (NYHA) Class III or IV heart failure due to the rosiglitazone component.
INSERT INTO "drug_generic" VALUES(1344, 'Glibenclamide', 'Glyburide', 'A10BB01', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Hypoglycemia Risk", "severity": "High", "trigger_condition": "Use in elderly patients or those with renal/hepatic impairment", "message": "STOP: Glibenclamide has a long half-life and active metabolites, posing a high risk of severe, prolonged, and potentially fatal hypoglycemia. It is generally not recommended in the elderly or in patients with significant renal or hepatic impairment."}]', 'Hypoglycemia is a significant risk, particularly in the elderly, debilitated, or malnourished patients, and those with adrenal, pituitary, renal, or hepatic insufficiency. The risk is exacerbated by deficient caloric intake, prolonged strenuous exercise, or concurrent alcohol consumption. Glibenclamide has a long duration of action and active metabolites, making hypoglycemic episodes potentially prolonged and severe. Monitor blood glucose concentrations regularly. During periods of metabolic stress (e.g., fever, trauma, infection, surgery), a temporary loss of glycemic control may occur, necessitating a temporary switch to insulin therapy. Avoid use in severe hepatic impairment. Caution is advised in patients with G6PD deficiency due to the risk of hemolytic anemia.', '- **Type 2 Diabetes Mellitus:** Indicated as an adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus when diet and exercise alone are inadequate.', '- **Type 1 Diabetes Mellitus:** Contraindicated as it requires functioning pancreatic beta cells to exert its effect.
INSERT INTO "drug_generic" VALUES(1345, 'Tenecteplase', 'Tenecteplase', 'B01AD11', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Bleeding Risk", "severity": "High", "trigger_condition": "Administration in patients with active bleeding or recent surgery", "message": "STOP: High Alert Medication. Can cause fatal intracranial or gastrointestinal hemorrhage. Strictly verify all contraindications (e.g., recent stroke, severe hypertension, active bleeding) before administration."}]', '**Bleeding Risks:** The most common complication is bleeding. Use with extreme caution in patients with recent major surgery, previous puncture of noncompressible vessels, recent GI/GU bleed, high risk of left heart thrombus, acute pericarditis, subacute bacterial endocarditis, or hemorrhagic ophthalmic conditions.
INSERT INTO "drug_generic" VALUES(1346, 'Insulin Aspart', 'Insulin Aspart', 'A10AB05', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypoglycemia", "severity": "High", "trigger_condition": "Changes in insulin regimen, missed meals, increased physical activity, or co-administration with other glucose-lowering agents", "message": "STOP: Severe, life-threatening hypoglycemia can occur. Monitor blood glucose closely when adjusting doses, changing diet, or altering physical activity."}, {"alert_type": "Hypokalemia", "severity": "High", "trigger_condition": "Intravenous administration or use with potassium-depleting drugs", "message": "STOP: Insulin shifts potassium intracellularly, which can lead to severe hypokalemia and fatal cardiac arrhythmias. Monitor serum potassium levels, especially in high-risk patients."}]', '**Hypoglycemia:** The most common adverse effect of insulin therapy. Risk increases with changes in meal patterns, physical activity, or co-administered medications. Early warning symptoms may be different or less pronounced in patients with long-standing diabetes, diabetic nerve disease, or those taking beta-blockers.
INSERT INTO "drug_generic" VALUES(1347, 'Valganciclovir', 'Valganciclovir', 'J05AB14', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Absolute neutrophil count <500 cells/\u03bcL, platelet count <25,000/\u03bcL, or hemoglobin <8 g/dL", "message": "STOP: Severe leukopenia, neutropenia, anemia, thrombocytopenia, pancytopenia, and bone marrow failure have occurred. Do not administer if blood counts are below critical thresholds."}]', '- **Hematologic Toxicity:** Severe myelosuppression is common. Monitor complete blood counts (CBC) with differential and platelet counts frequently, especially in patients with baseline cytopenias or those receiving other myelosuppressive drugs.
INSERT INTO "drug_generic" VALUES(1348, 'Testosterone Undecanoate', 'Testosterone Undecanoate', 'G03BA03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiovascular and Hepatic Risks", "severity": "High", "trigger_condition": "Long-term use or abuse of testosterone", "message": "Testosterone use is associated with an increased risk of cardiovascular events (MI, stroke), polycythemia, and severe hepatic adverse effects. Monitor hematocrit, lipid profile, and liver function regularly."}]', 'Monitor hematocrit periodically to detect polycythemia; withhold therapy if hematocrit becomes elevated. Monitor for signs of fluid retention, especially in patients with pre-existing heart failure, renal, or hepatic disease. Evaluate patients for benign prostatic hyperplasia (BPH) and prostate cancer prior to initiation and periodically during therapy. Monitor lipid profiles, as testosterone can decrease HDL and increase LDL cholesterol. Use with caution in patients with sleep apnea. Oral formulations bypass some first-pass metabolism via lymphatic absorption, but hepatic monitoring is still advised.', '- **Male Hypogonadism:** Replacement therapy in adult males for conditions associated with a deficiency or absence of endogenous testosterone (primary or secondary hypogonadism).', '- **Prostate or Male Breast Cancer:** Contraindicated in men with known or suspected carcinoma of the prostate or breast.
INSERT INTO "drug_generic" VALUES(1349, 'Mecobalamin', 'Methylcobalamin', 'B03BA05', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk (Parenteral)", "severity": "High", "trigger_condition": "Intramuscular or Intravenous administration", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur with parenteral administration. Observe patients closely after injection."}]', '**Lack of Efficacy:** The medicine should not be used continuously for months if there is no clinical response after a certain period of time.
INSERT INTO "drug_generic" VALUES(1350, 'Glyceryl Trinitrate (nitroglycerine)', 'Nitroglycerin', 'C01DA02', 0, 1, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Severe Hypotension Risk", "severity": "High", "trigger_condition": "Concurrent use of Phosphodiesterase type-5 (PDE-5) inhibitors", "message": "STOP: Absolute contraindication. Co-administration with PDE-5 inhibitors (e.g., sildenafil, tadalafil, vardenafil) or soluble guanylate cyclase (sGC) stimulators (e.g., riociguat) can cause profound, life-threatening hypotension and syncope."}]', '**Nitrate Tolerance:** Continuous, around-the-clock use of nitrates leads to tolerance and loss of antianginal efficacy. A nitrate-free interval of 10-12 hours per day is strictly recommended for continuous formulations (e.g., transdermal patches, sustained-release tablets).
INSERT INTO "drug_generic" VALUES(1351, 'Emtricitabine + Tenofovir disoproxil', 'Emtricitabine / Tenofovir disoproxil fumarate', 'J05AR03', 0, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Post-Treatment Acute Exacerbation of Hepatitis B", "severity": "High", "trigger_condition": "Discontinuation of therapy in patients co-infected with HIV-1 and HBV", "message": "STOP: Severe acute exacerbations of hepatitis B have been reported in HBV-infected patients who have discontinued this medication. Hepatic function should be monitored closely for several months after stopping."}]', '**Lactic Acidosis and Severe Hepatomegaly with Steatosis:** Fatal cases have been reported with the use of nucleoside analogues. Discontinue therapy if clinical or laboratory findings suggest lactic acidosis or pronounced hepatotoxicity.
INSERT INTO "drug_generic" VALUES(1352, 'Everolimus', 'Everolimus', 'L01EG02', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Non-infectious Pneumonitis", "severity": "High", "trigger_condition": "Development of cough, dyspnea, or radiological changes", "message": "STOP: Non-infectious pneumonitis is a class effect of rapamycin derivatives. Fatal cases have occurred. Monitor for clinical symptoms or radiological changes. Manage by dose reduction or discontinuation, and consider corticosteroids."}, {"alert_type": "Severe Infections", "severity": "High", "trigger_condition": "Signs of systemic infection", "message": "STOP: Everolimus has immunosuppressive properties and may predispose patients to bacterial, fungal, viral, or protozoal infections, including opportunistic infections (e.g., Pneumocystis jirovecii pneumonia). Treat infections promptly."}]', '**Stomatitis/Oral Mucositis:** Very common. Manage with mouthwashes (alcohol/peroxide-free) and topical treatments. Avoid prophylactic use of mouthwashes containing alcohol.
INSERT INTO "drug_generic" VALUES(1353, 'Zuclopenthixol', 'Zuclopenthixol', 'N05AF05', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Neuroleptic Malignant Syndrome", "severity": "High", "trigger_condition": "Development of high fever, muscle rigidity, and altered mental status", "message": "STOP: Potentially fatal Neuroleptic Malignant Syndrome (NMS) can occur. Discontinue immediately and provide intensive symptomatic treatment."}, {"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Concomitant use of QT-prolonging drugs or electrolyte imbalance", "message": "Risk of severe arrhythmias, including Torsades de Pointes. Monitor ECG and electrolytes."}]', 'Use with extreme caution in the elderly, and in patients with Parkinson''s disease, severe cardiovascular disease, recent acute myocardial infarction, significant bradycardia (<50 bpm), or a history of arrhythmias. Caution in patients with epilepsy or conditions predisposing to seizures (e.g., alcohol withdrawal, brain damage). Monitor for signs of tardive dyskinesia and extrapyramidal symptoms (EPS), especially during early treatment. Caution in patients with acute angle glaucoma, prostatic hypertrophy, myasthenia gravis, or thyroid disorders. Avoid abrupt withdrawal to prevent rebound psychosis and withdrawal symptoms. May impair the ability to drive or operate heavy machinery.', '- **Schizophrenia:** Management of acute and chronic manifestations of schizophrenia.
INSERT INTO "drug_generic" VALUES(1354, 'Vilanterol + Fluticasone furoate', 'Fluticasone Furoate and Vilanterol', 'R03AK10', 0, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediate worsening of wheezing or shortness of breath after inhalation", "message": "STOP: Can produce life-threatening paradoxical bronchospasm. Treat immediately with an inhaled, short-acting bronchodilator and discontinue therapy."}]', '- **Acute Exacerbations:** Do not use to treat acute asthma symptoms or an acute exacerbation in COPD. It is not a rescue inhaler.
INSERT INTO "drug_generic" VALUES(1355, 'Vecuronium Bromide', 'Vecuronium Bromide', 'M03AC03', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Respiratory Paralysis", "severity": "High", "trigger_condition": "Administration without ventilatory support", "message": "STOP: Vecuronium causes respiratory muscle paralysis. It must ONLY be administered by trained personnel in settings where intubation, mechanical ventilation, and oxygen therapy are immediately available."}]', '**Neuromuscular Diseases:** Patients with myasthenia gravis or myasthenic syndrome are highly sensitive to non-depolarizing agents. Profound and prolonged paralysis can occur; use small test doses and monitor with a peripheral nerve stimulator.
INSERT INTO "drug_generic" VALUES(1356, 'Snake Venom Antiserum', 'Antivenin Polyvalent', 'J06AA03', 0, 1, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "Administration of equine-derived antiserum", "message": "STOP: Severe, immediate anaphylactic reactions (shock) can occur within 30 minutes of administration. Resuscitation equipment and epinephrine (adrenaline) must be immediately available before initiating the infusion."}]', '**Hypersensitivity Reactions:** Proper precautions are necessary. Some protocols recommend premedication with subcutaneous epinephrine (0.25 mL) or antihistamines to prevent adverse reactions. Hypersensitivity skin testing has no predictive value and should not delay treatment.
INSERT INTO "drug_generic" VALUES(1357, 'Regorafenib', 'Regorafenib', 'L01EX05', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated liver transaminases or bilirubin", "message": "STOP: Severe and sometimes fatal hepatotoxicity has been observed. Monitor hepatic function prior to and during treatment. Interrupt, reduce, or discontinue therapy based on severity."}, {"alert_type": "Hemorrhage", "severity": "High", "trigger_condition": "Signs of severe bleeding or hemorrhage", "message": "STOP: Increased risk of severe or fatal hemorrhage. Discontinue therapy for severe or life-threatening bleeding events."}, {"alert_type": "Gastrointestinal Perforation", "severity": "High", "trigger_condition": "Acute abdominal pain or signs of peritonitis", "message": "STOP: Gastrointestinal perforation or fistula can occur. Discontinue permanently in patients who develop GI perforation or fistula."}]', 'Monitor liver function tests (ALT, AST, and bilirubin) before initiation, at least every 2 weeks during the first 2 months of treatment, and at least monthly thereafter. Interrupt, reduce, or discontinue treatment for hepatotoxicity.
INSERT INTO "drug_generic" VALUES(1358, 'Potassium Chloride 0.1% + Sodium Acetate 0.65% + Sodium Chloride 0.5% (Cholera Saline)', 'Potassium Chloride, Sodium Acetate, and Sodium Chloride Intravenous Solution', 'B05BB01', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Fluid Overload:** Rapid or prolonged administration can cause fluid overload, resulting in pulmonary edema and heart failure. Monitor fluid balance closely.
INSERT INTO "drug_generic" VALUES(1359, 'Avobenzone 3% + Octocrylene 10% + Oxybenzone 6% + Cepalin + Parabens topical', 'Avobenzone / Octocrylene / Oxybenzone / Allium cepa extract', 'D02BA', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Application Site Reactions:** Not for use on deep or puncture wounds, damaged or broken skin, animal bites, or serious burns. Apply only to intact skin.
INSERT INTO "drug_generic" VALUES(1360, 'Phytomenadione (Vitamin K1)', 'Phytonadione', 'B02BA01', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Severe Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Intravenous or Intramuscular administration", "message": "STOP: Severe, potentially fatal hypersensitivity reactions (anaphylaxis-like), including shock and cardiac/respiratory arrest, have occurred during or immediately after IV or IM administration. Administer IV only when other routes are not feasible, and infuse very slowly."}]', '**Administration Route Risks:** Intravenous administration carries a high risk of severe anaphylactoid reactions. The oral or subcutaneous routes are preferred whenever possible. If IV is necessary, it must be administered very slowly.
INSERT INTO "drug_generic" VALUES(1361, 'Lercanidipine Hydrochloride', 'Lercanidipine', 'C08CA13', 0, 0, 0, 0, 1, 1, 0, 1, '[]', '**Cardiac Dysfunction:** Use with caution in patients with left ventricular dysfunction, ischemic heart disease, or sick sinus syndrome (if a pacemaker is not fitted). May rarely lead to excessive hypotension and reflex tachycardia, precipitating angina or myocardial infarction.
INSERT INTO "drug_generic" VALUES(1362, 'Meningococcal polysaccharide groups A C Y and W-135 conjugate vaccine', 'Meningococcal (Groups A, C, Y and W-135) Polysaccharide Diphtheria Toxoid Conjugate Vaccine', 'J07AH08', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "Administration of vaccine", "message": "STOP: Severe allergic reactions, including anaphylaxis, can occur. Appropriate medical treatment and supervision must always be readily available in case of an anaphylactic event following administration."}]', '- **Route of Administration:** Do not inject intravascularly, intradermally, or subcutaneously. Administer strictly via intramuscular (IM) injection.
INSERT INTO "drug_generic" VALUES(1363, 'Fostamatinib', 'Fostamatinib', 'B02BX09', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hypertension and Hepatotoxicity", "severity": "Moderate", "trigger_condition": "Routine monitoring during therapy", "message": "Hypertension, including hypertensive crisis, and elevated LFTs can occur. Monitor blood pressure every 2 weeks until stable, and monitor LFTs monthly."}]', '**Hypertension:** Can occur, including hypertensive crisis. Patients with preexisting hypertension may be more susceptible. Monitor blood pressure every 2 weeks until stable, then monthly. Adjust or initiate antihypertensive therapy for control; interrupt or reduce the dose if hypertension is severe.
INSERT INTO "drug_generic" VALUES(1364, 'Phentolamine', 'Phentolamine', 'C04AB01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Hypotension and Arrhythmia", "severity": "High", "trigger_condition": "Rapid IV administration or concurrent use with PDE-5 inhibitors", "message": "STOP: May cause profound hypotension, tachycardia, and cardiac arrhythmias. Monitor blood pressure and heart rate continuously during administration. Contraindicated with PDE-5 inhibitors."}]', '**First-Dose Effect:** A sudden and drastic fall in blood pressure may occur after administering the first dose. Minimize this risk by using a small initial dose and increasing slowly.
INSERT INTO "drug_generic" VALUES(1365, 'Chlorhexidine Gluconate +/- Isopropyl Alcohol', 'Chlorhexidine Gluconate and Isopropyl Alcohol', 'D08AC52', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Flammability Risk", "severity": "High", "trigger_condition": "Use prior to electrocautery or laser procedures", "message": "STOP: Highly flammable. The solution must be allowed to dry completely (at least 3 minutes on hairless skin) before using electrocautery, lasers, or other ignition sources to prevent surgical fires."}, {"alert_type": "Application Site Warning", "severity": "High", "trigger_condition": "Application near sensitive areas", "message": "Do not use near the eyes, ears, or meninges. Chlorhexidine can cause serious and permanent eye injury and deafness if instilled into the middle ear."}]', '**Chemical Burns in Premature Infants:** Use with caution in premature infants or infants under 2 months of age. These products may cause severe irritation or chemical burns.
INSERT INTO "drug_generic" VALUES(1366, 'Lidocaine Hydrochloride + Tolperisone Hydrochloride', 'Lidocaine and Tolperisone', 'M03BX04', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hypersensitivity Risk", "severity": "High", "trigger_condition": "Patient history of hypersensitivity to tolperisone or amide local anesthetics", "message": "STOP: Severe hypersensitivity reactions, including anaphylactic shock, have been reported with tolperisone. Verify patient allergy history before administration."}]', '- **Hypersensitivity Reactions:** Tolperisone carries a risk of severe hypersensitivity reactions, ranging from mild skin reactions to severe systemic anaphylaxis. Females, older patients, and those with a history of other allergies or concurrent NSAID use may be at higher risk.
INSERT INTO "drug_generic" VALUES(1367, 'Cimetidine', 'Cimetidine', 'A02BA01', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Central Nervous System Toxicity", "severity": "Moderate", "trigger_condition": "Elderly patients or those with severe renal/hepatic impairment", "message": "Monitor for reversible central nervous system effects, including confusion, delirium, and hallucinations, particularly in elderly or critically ill patients with renal or hepatic dysfunction."}]', '**Renal Impairment:** Dosage reduction is required in patients with moderate to severe renal impairment to prevent drug accumulation and central nervous system (CNS) toxicity.
INSERT INTO "drug_generic" VALUES(1368, 'Calamine + Zinc Oxide + Glycerine', 'Calamine, Zinc Oxide, and Glycerin', 'D02AB', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Moderate", "trigger_condition": "Application to compromised skin", "message": "For external use only. Do not use on open wounds, deep punctures, or severe burns. Avoid contact with the eyes and mucous membranes."}]', '**External Use Only:** Do not ingest. Keep away from eyes and mucous membranes. If contact occurs, rinse thoroughly with water.
INSERT INTO "drug_generic" VALUES(1369, 'Bimekizumab', 'Bimekizumab-bkzx', 'L04AC21', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Suicidal Ideation and Behavior", "severity": "High", "trigger_condition": "Patient history of severe depression or suicidal ideation", "message": "STOP: Bimekizumab may increase the risk of suicidal ideation and behavior. Weigh potential risks and benefits before use in patients with a history of severe depression. Monitor closely for mood changes."}]', '**Suicidal Ideation and Behavior (SI/B):** May increase the risk of SI/B. Weigh potential risks and benefits before use in patients with a history of severe depression or suicidal ideation. Monitor for emerging or worsening depression, suicidal ideation, or mood changes. Refer to a mental health professional if symptoms occur and re-evaluate treatment.
INSERT INTO "drug_generic" VALUES(1370, 'Lanolin', 'Lanolin', 'D02AX', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Ocular Exposure:** For external use only. Avoid contact with eyes. If contact occurs, rinse thoroughly with water.
INSERT INTO "drug_generic" VALUES(1371, 'Sulconazole topical', 'Sulconazole Nitrate', 'D01AC09', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Ocular Exposure", "severity": "Low", "trigger_condition": "Application near eyes", "message": "For external use only. Avoid contact with the eyes. If contact occurs, rinse thoroughly with water."}]', '**Local Irritation:** If irritation or sensitivity develops, discontinue use and institute appropriate therapy.
INSERT INTO "drug_generic" VALUES(1372, 'Pemirolast Potassium 0.1% Eye prep', 'Pemirolast Potassium', 'S01GX02', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '- **Contact Lens Wear:** Not indicated for the treatment of contact lens-related irritation. The preservative (lauralkonium chloride or benzalkonium chloride) may be absorbed by soft contact lenses. Patients should remove contact lenses prior to instillation and wait at least 10 minutes before reinserting them.
INSERT INTO "drug_generic" VALUES(1373, 'Acyclovir 5% Topical', 'Acyclovir Topical', 'D06BB03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Low", "message": "For external use only. Do not apply to the eyes, inside the mouth, or inside the nose. Avoid application to unaffected skin."}]', '**Mucous Membrane Irritation:** The ointment base may cause irritation if applied to mucous membranes (e.g., inside the mouth, eyes, or vagina). Use strictly on the external skin/lips.
INSERT INTO "drug_generic" VALUES(1374, 'Quinidine', 'Quinidine', 'C01BA01', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Proarrhythmia and QTc Prolongation", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "STOP: Quinidine can cause severe QTc prolongation and fatal ventricular arrhythmias, including Torsades de Pointes. Continuous ECG monitoring is required during initiation. Avoid in patients with pre-existing prolonged QTc."}]', 'Use with extreme caution in patients with incomplete AV block, uncompensated heart failure, severe myocardial damage, or a history of prolonged QT interval. Quinidine has potent anticholinergic effects; use cautiously in patients with pre-existing asthma, muscle weakness (e.g., myasthenia gravis), or glaucoma. Hepatotoxicity and drug-induced lupus have been reported. Monitor cardiac function, blood pressure, and ECG continuously during IV administration and periodically during oral therapy. Assess CBC, liver, and renal function regularly during long-term use. Correct electrolyte imbalances (especially hypokalemia and hypomagnesemia) prior to initiation to reduce the risk of proarrhythmia.', '- **Arrhythmias:** Indicated for the conversion and maintenance of normal sinus rhythm in patients with atrial fibrillation/flutter, and for the treatment of documented life-threatening ventricular arrhythmias (e.g., sustained ventricular tachycardia).
INSERT INTO "drug_generic" VALUES(1375, 'Aztreonam', 'Aztreonam', 'J01DF01', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Cross-Reactivity with Ceftazidime", "severity": "Medium", "trigger_condition": "Patient history of Ceftazidime hypersensitivity", "message": "STOP: While aztreonam is generally safe in patients with penicillin or cephalosporin allergies, it shares an identical side chain with CEFTAZIDIME. Cross-reactivity can occur. Use with extreme caution in patients with a severe allergy to ceftazidime."}, {"alert_type": "Clostridioides difficile-Associated Diarrhea (CDAD)", "severity": "High", "trigger_condition": "Development of severe diarrhea during or after therapy", "message": "STOP: CDAD, ranging from mild diarrhea to fatal colitis, has been reported. If suspected, discontinue aztreonam immediately and evaluate."}]', '**Renal Impairment:** Aztreonam is excreted primarily by the kidneys. Dose adjustment is required in patients with renal impairment to prevent drug accumulation.
INSERT INTO "drug_generic" VALUES(1376, 'Tropicamide + Phenylephrine + Lidocaine inj (eye prep)', 'Tropicamide, Phenylephrine, and Lidocaine intraocular injection', 'S01FA56', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Intraocular Use Only", "severity": "High", "trigger_condition": "Administration route verification", "message": "STOP: This medication is for intracameral (intraocular) injection only. Do not administer intravenously, intramuscularly, or topically."}]', '**Ocular Risks:** Use with caution in patients with a shallow anterior chamber or a history of acute narrow-angle glaucoma, as it can increase the risk of iridocele and floppy iris syndrome. Not recommended for cataract surgery combined with vitrectomy due to the vasoconstricting effects of phenylephrine.
INSERT INTO "drug_generic" VALUES(1377, 'Vitamin B-complex + Zinc', 'Vitamin B Complex with Zinc', 'A11EX', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Underlying Deficiencies:** While this supplement treats deficiencies, underlying causes of malabsorption (e.g., pernicious anemia, inflammatory bowel disease) should be investigated and treated appropriately.
INSERT INTO "drug_generic" VALUES(1378, 'Hydrochlorothiazide + Benazepril', 'Benazepril/Hydrochlorothiazide', 'C09BA07', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy", "message": "STOP: When pregnancy is detected, discontinue benazepril/hydrochlorothiazide as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}]', '**Angioedema:** ACE inhibitors can cause angioedema of the face, extremities, lips, tongue, glottis, and larynx. Discontinue immediately if this occurs. Coadministration with mTOR inhibitors or neprilysin inhibitors increases this risk.
INSERT INTO "drug_generic" VALUES(1379, 'Sulphacetamide Sodium 20% Eye prep', 'Sulfacetamide Sodium', 'S01AB04', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Severe Hypersensitivity", "severity": "High", "trigger_condition": "History of sulfonamide allergy", "message": "Fatalities have occurred, although rarely, due to severe reactions to sulfonamides including Stevens-Johnson syndrome, toxic epidermal necrolysis, and fulminant hepatic necrosis, even with ophthalmic administration."}]', '**Hypersensitivity Reactions:** Severe allergic reactions, including Stevens-Johnson syndrome, can occur even with topical ophthalmic use due to systemic absorption. Discontinue immediately if rash or signs of hypersensitivity develop.
INSERT INTO "drug_generic" VALUES(1380, 'Calcium Chloride  + Potassium Chloride + Sodium Chloride', 'Ringer''s Injection', 'B05BB01', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Metabolic Acidosis:** IV infusion of Ringer''s Injection (without lactate) is obsolete for the treatment of metabolic acidosis and carries the risk of producing hyperchloremic metabolic acidosis, particularly in seriously ill patients with poor tissue perfusion.
INSERT INTO "drug_generic" VALUES(1381, 'Choriogonadotropin Alfa', 'Choriogonadotropin Alfa', 'G03GA08', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Ovarian Hyperstimulation Syndrome (OHSS)", "severity": "High", "trigger_condition": "Significant ovarian enlargement or excessive estradiol production", "message": "STOP: Severe and potentially fatal Ovarian Hyperstimulation Syndrome (OHSS) can occur. Withhold therapy if ovaries are abnormally enlarged or if early warning signs (severe pelvic pain, nausea, vomiting, weight gain) develop."}]', '**Ovarian Hyperstimulation Syndrome (OHSS):** Therapy can cause OHSS, a potentially fatal condition characterized by rapid fluid accumulation in the peritoneal cavity, thorax, and pericardium. Early warning signs include severe pelvic pain, nausea, vomiting, and rapid weight gain. Monitor ovarian response with serum estradiol and transvaginal ultrasound regularly. Withhold administration if ovaries are abnormally enlarged on the last day of follicle-stimulating hormone (FSH) therapy.
INSERT INTO "drug_generic" VALUES(1382, 'Dextrose 4.3% + Sodium Chloride 0.18%', 'Dextrose 4.3% and Sodium Chloride 0.18%', 'B05BB02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Fluid and Solute Overload", "severity": "Moderate", "trigger_condition": "Administration in patients with congestive heart failure or severe renal impairment", "message": "Caution: Can cause significant fluid overload, pulmonary edema, and electrolyte disturbances. Monitor fluid balance and electrolytes closely."}]', '**Fluid and Electrolyte Overload:** Administration can cause fluid and/or solute overload resulting in dilution of serum electrolyte concentrations, overhydration, congested states, or pulmonary edema. Use with caution in patients with congestive heart failure or severe renal insufficiency.
INSERT INTO "drug_generic" VALUES(1383, 'Ganirelix', 'Ganirelix', 'H01CC01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patients with active allergic conditions or a history of severe allergies", "message": "STOP: Anaphylactoid reactions have been reported. Use with caution in women with active allergic conditions. Contraindicated in patients with known hypersensitivity to ganirelix or any of its components."}]', '**Hypersensitivity Reactions:** Anaphylactoid reactions have been reported. Use with caution in women with active allergic conditions or a history of severe allergies.
INSERT INTO "drug_generic" VALUES(1384, 'Ossein Hydroxyapatite', 'Ossein Hydroxyapatite', 'A12AA', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "Moderate", "trigger_condition": "Concurrent use with high-dose calcium or vitamin D supplements", "message": "Monitor serum calcium levels to avoid hypercalcemia, especially in patients with mild to moderate renal impairment."}]', '**Hypercalcemia and Hypercalciuria:** Monitor serum and urinary calcium levels periodically, especially during prolonged treatment or when co-administered with Vitamin D, to prevent hypercalcemia and hypercalciuria.
INSERT INTO "drug_generic" VALUES(1385, 'Carbimazole', 'Carbimazole', 'H03BB01', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Agranulocytosis", "severity": "High", "trigger_condition": "Development of sore throat, fever, or mouth ulcers", "message": "STOP: Fatal agranulocytosis can occur. Instruct patients to immediately report any signs of infection (sore throat, fever, mouth ulcers). Discontinue drug and check complete blood count immediately."}]', '**Bone Marrow Depression:** Agranulocytosis, aplastic anemia, and neutropenia can occur. Routine monitoring of CBC is recommended, especially during the first few months of therapy.
INSERT INTO "drug_generic" VALUES(1386, 'Budesonide + Formoterol Fumarate', 'Budesonide and Formoterol', 'R03AK07', 0, 0, 0, 1, 0, 0, 1, 1, '[{"alert_type": "Asthma-Related Death Risk", "severity": "High", "trigger_condition": "Use of LABA without an ICS", "message": "WARNING: Long-acting beta2-adrenergic agonists (LABA), such as formoterol, increase the risk of asthma-related death when used as monotherapy. This combination product contains an ICS and is appropriate for patients requiring both therapies."}, {"alert_type": "Acute Bronchospasm", "severity": "High", "trigger_condition": "Use during acute asthma or COPD exacerbation", "message": "WARNING: Do NOT use this medication to relieve acute bronchospasm or during acutely deteriorating asthma or COPD. A short-acting beta2-agonist (SABA) must be used for acute symptoms."}]', 'Do not initiate therapy in patients with acutely deteriorating asthma or COPD.
INSERT INTO "drug_generic" VALUES(1387, 'Artemether', 'Artemether', 'P01BE02', 0, 0, 0, 1, 0, 0, 1, 0, '[{"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Concurrent use with QT-prolonging drugs", "message": "STOP: Artemether can cause QT interval prolongation. Avoid concomitant use with drugs known to prolong the QT interval (e.g., amiodarone, sotalol, macrolides, TCAs) to prevent fatal arrhythmias."}]', '**QT Prolongation:** Can prolong the QT interval. Use with extreme caution in patients with a history of congenital long QT syndrome, clinically significant bradycardia, or uncorrected hypokalemia/hypomagnesemia.
INSERT INTO "drug_generic" VALUES(1388, 'Droxidopa', 'Droxidopa', 'C01CA30', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Supine Hypertension", "severity": "High", "trigger_condition": "Patient resting or sleeping in a supine position", "message": "STOP: Droxidopa therapy may cause or exacerbate supine hypertension, increasing the risk of cardiovascular events, particularly stroke. Advise patients to elevate the head of the bed when resting or sleeping."}]', '**Supine Hypertension:** Therapy may cause or exacerbate supine hypertension in patients with neurogenic orthostatic hypotension (NOH). Advise patients to elevate the head of the bed when resting or sleeping. If supine hypertension is not well-managed, therapy may increase the risk of cardiovascular events, particularly stroke.
INSERT INTO "drug_generic" VALUES(1389, 'Physostigmine', 'Physostigmine', 'V03AB19', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cholinergic Crisis", "severity": "High", "trigger_condition": "Rapid administration or excessive dosing", "message": "STOP: Rapid IV administration or excessive dosing can cause a fatal cholinergic crisis (seizures, severe bradycardia, bronchospasm, asystole). Keep atropine immediately available as an antidote."}]', '**Cholinergic Crisis:** Overdosage or rapid administration can lead to a cholinergic crisis, characterized by severe bradycardia, hypersalivation, bronchospasm, seizures, and muscle weakness (including respiratory paralysis). Always have intravenous atropine readily available to reverse severe cholinergic symptoms.
INSERT INTO "drug_generic" VALUES(1390, 'Fluocinolone 0.01% + Hydroquinone 4% + Tretinoin 0.05% Topical', 'Fluocinolone Acetonide 0.01%, Hydroquinone 4%, Tretinoin 0.05% Topical Cream', 'D11AX11', 0, 0, 0, 0, 0, 0, 0, 0, '[]', 'This combination contains hydroquinone and tretinoin, which may cause mild to moderate irritation, including skin reddening, peeling, burning, and dryness. Discontinue if hypersensitivity or severe chemical irritation occurs. It also contains fluocinolone acetonide, a topical corticosteroid. Systemic absorption can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria. Avoid prolonged use and application over large surface areas. Patients must strictly avoid sunlight and use broad-spectrum sunscreen, as tretinoin increases photosensitivity.', '- **Melasma:** Short-term, intermittent treatment of moderate to severe melasma of the face, in the presence of measures for sun avoidance, including the use of sunscreens.', '- **Hypersensitivity:** Contraindicated in patients with a history of hypersensitivity, allergy, or intolerance to fluocinolone, hydroquinone, tretinoin, or any components of the formulation.
INSERT INTO "drug_generic" VALUES(1391, 'Pantoprazole Sodium Sesquihydrate', 'Pantoprazole', 'A02BC02', 0, 0, 1, 0, 0, 0, 1, 1, '[{"alert_type": "Drug Interaction", "severity": "High", "trigger_condition": "Concomitant use with rilpivirine-containing products", "message": "STOP: Concomitant use with rilpivirine is contraindicated due to significant reduction in rilpivirine plasma concentrations, leading to loss of virologic response and possible resistance."}]', '**Gastric Malignancy:** Symptomatic response to therapy does not preclude the presence of gastric malignancy. Consider endoscopy in patients with alarm symptoms (e.g., unintentional weight loss, dysphagia, hematemesis).
INSERT INTO "drug_generic" VALUES(1392, 'Terlipressin', 'Terlipressin', 'H01BA04', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Ischemic Events", "severity": "High", "trigger_condition": "Patients with a history of severe cardiovascular or peripheral vascular disease", "message": "STOP: Terlipressin can cause severe and potentially fatal ischemic events, including myocardial infarction, intestinal ischemia, and peripheral necrosis. Monitor closely."}]', 'Use with extreme caution in patients with uncontrolled hypertension, severe asthma or chronic obstructive pulmonary disease (COPD), underlying cardiac disease, arrhythmias, atherosclerosis, or cerebral/peripheral vascular disease due to the potent vasoconstrictive effects of the drug. Monitor closely for signs of cutaneous ischemia, intestinal ischemia, and fluid overload. Caution is advised in patients with chronic renal failure and those with significant electrolyte or fluid disturbances. Continuous monitoring of blood pressure, heart rate, electrocardiogram (ECG), and fluid balance is mandatory during therapy.', '- **Acute Esophageal Variceal Hemorrhage:** Used for the rapid control of bleeding from esophageal varices by reducing portal venous pressure.
INSERT INTO "drug_generic" VALUES(1393, 'Spinosad topical', 'Spinosad topical', 'P03AX05', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Benzyl Alcohol Toxicity", "severity": "High", "trigger_condition": "Use in neonates and infants <6 months", "message": "STOP: Contains benzyl alcohol. Systemic exposure to benzyl alcohol has been associated with fatal ''gasping syndrome'' in neonates and low birth-weight infants. Do not use in infants below 6 months of age."}]', 'Avoid contact with eyes. If the product gets in or near the eyes, rinse thoroughly with water immediately.
INSERT INTO "drug_generic" VALUES(1394, 'Betacarotene + Vitamin C + Vitamin E  (Anti-Oxidant Vitamins and Minerals)', 'Beta Carotene, Ascorbic Acid, and Alpha-Tocopherol', 'A11JA', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Hypervitaminosis", "severity": "Low", "message": "Do not exceed the recommended daily dose to prevent hypervitaminosis."}]', '**Anticoagulant Therapy:** Patients on anticoagulant therapy (e.g., warfarin) should use caution. High doses of Vitamin E can increase the risk of bleeding, and high doses of Vitamin C may interfere with prothrombin time.
INSERT INTO "drug_generic" VALUES(1395, 'Dextran 40 10% + Dextrose 5%', 'Dextran 40 in Dextrose', 'B05AA05', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Renal Failure", "severity": "High", "trigger_condition": "Administration of Dextran 40", "message": "STOP: Severe and fatal anaphylactoid reactions can occur. Observe patients closely during the first minutes of infusion. Dextran 40 can also precipitate acute renal failure; contraindicated in severe oliguria or anuria."}]', '**Anaphylactoid Reactions:** Severe and fatal anaphylactoid reactions have been reported. Discontinue use immediately at the first sign of hypersensitivity (e.g., hypotension, wheezing, tightness of chest) and administer appropriate therapy (epinephrine, steroids).
INSERT INTO "drug_generic" VALUES(1396, 'Rivastigmine', 'Rivastigmine', 'N06DA03', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Gastrointestinal Toxicity", "severity": "Moderate", "trigger_condition": "Initiation or dose escalation", "message": "CAUTION: Significant gastrointestinal adverse reactions, including nausea, vomiting, anorexia, and weight loss, may occur. Monitor weight and adjust dose if necessary."}]', '**Gastrointestinal Adverse Reactions:** Rivastigmine can cause significant nausea, vomiting, diarrhea, anorexia, and weight loss. Monitor patient weight closely. Dose titration should be slow and careful.
INSERT INTO "drug_generic" VALUES(1397, 'Typhoid Vaccine  (live attenuated)', 'Typhoid Vaccine Live Oral Ty21a', 'J07AP01', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Immunocompromised Patients", "severity": "High", "trigger_condition": "Administration to patients with congenital or acquired immunodeficiency", "message": "STOP: This is a live attenuated vaccine. It is contraindicated in immunocompromised individuals due to the risk of disseminated infection."}]', '- **Incomplete Protection:** Vaccination does not provide 100% protection. Advise travelers to continue taking standard food and water precautions (e.g., boiling water, peeling fruits) in endemic areas.
INSERT INTO "drug_generic" VALUES(1398, 'Levocetirizine Hydrochloride', 'Levocetirizine Hydrochloride', 'R06AE09', 0, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Renal Contraindication", "severity": "High", "trigger_condition": "Patients with End-Stage Renal Disease (CrCl <10 mL/min) or undergoing hemodialysis", "message": "STOP: Levocetirizine is strictly contraindicated in patients with End-Stage Renal Disease (CrCl <10 mL/min) and those undergoing hemodialysis due to the risk of severe drug accumulation."}]', '**CNS Depression:** May cause somnolence, fatigue, and asthenia. Patients should be cautioned against engaging in hazardous occupations requiring complete mental alertness, such as driving or operating machinery.
INSERT INTO "drug_generic" VALUES(1399, 'Levetiracetam', 'Levetiracetam', 'N03AX14', 0, 0, 1, 0, 1, 1, 1, 1, '[{"alert_type": "Psychiatric and Behavioral Reactions", "severity": "High", "trigger_condition": "Emergence of mood changes, agitation, or hallucinations", "message": "STOP: Can cause severe behavioral abnormalities including psychotic symptoms, suicidal ideation, hostility, and agitation. Monitor closely and reduce dose or discontinue if severe symptoms occur."}]', '**Psychiatric and Behavioral Symptoms:** May cause behavioral abnormalities (e.g., agitation, hostility, anxiety, apathy, depression) and psychotic symptoms (e.g., hallucinations). Monitor patients closely; dose reduction or discontinuation may be required.
INSERT INTO "drug_generic" VALUES(1400, 'Pneumococcal polysaccharide unconjugated Vaccine', 'Pneumococcal Vaccine Polyvalent (PPSV23)', 'J07AL01', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Immunocompromised Patients:** Patients receiving immunosuppressive therapy (e.g., chemotherapy, high-dose corticosteroids) or those with conditions like multiple myeloma, Hodgkin''s disease, or HIV may have a reduced antibody response. Administer the vaccine at least 2 weeks before starting immunosuppressive treatment or elective splenectomy.
INSERT INTO "drug_generic" VALUES(1401, 'Minocycline topical', 'Minocycline', 'D10AF07', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Flammability", "severity": "High", "trigger_condition": "Exposure to fire or smoking", "message": "STOP: The topical foam is flammable. Avoid fire, flame, and smoking during and immediately following application."}]', 'Flammable; caution patient to avoid fire, flame, and smoking during and immediately following application. Do not puncture or incinerate containers. May cause permanent discoloration of teeth if absorbed systemically during tooth development. Use with caution in patients with a history of hepatic impairment.', '- **Acne Vulgaris:** Indicated for the topical treatment of inflammatory lesions of non-nodular moderate-to-severe acne vulgaris in adults and pediatric patients 9 years of age and older.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to any tetracycline-class drug or any ingredient in the formulation.', '- Erythema
INSERT INTO "drug_generic" VALUES(1402, 'Lamivudine + Stavudine + Nevirapine', 'Lamivudine/Stavudine/Nevirapine', 'J05AR07', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hepatotoxicity and Severe Skin Reactions", "severity": "High", "trigger_condition": "Initiation of therapy or presence of hepatic impairment", "message": "STOP: Severe, life-threatening, and in some cases fatal hepatotoxicity (including fulminant and cholestatic hepatitis, hepatic necrosis, and hepatic failure) and severe skin reactions (including Stevens-Johnson Syndrome and Toxic Epidermal Necrolysis) can occur, primarily driven by the Nevirapine component. Intensive monitoring is required during the first 18 weeks of therapy."}, {"alert_type": "Lactic Acidosis and Severe Hepatomegaly", "severity": "High", "trigger_condition": "Use of nucleoside analogues", "message": "STOP: Lactic acidosis and severe hepatomegaly with steatosis, including fatal cases, have been reported with the use of nucleoside analogues (Lamivudine and Stavudine)."}]', '**Hepatic Impairment:** Patients with pre-existing liver dysfunction, including chronic active hepatitis, have an increased frequency of liver function abnormalities during combination antiretroviral therapy and should be monitored according to standard practice.
INSERT INTO "drug_generic" VALUES(1403, 'Chlordiazepoxide', 'Chlordiazepoxide', 'N05BA02', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Concomitant Use with Opioids", "severity": "High", "trigger_condition": "Co-prescription with opioid analgesics or antitussives", "message": "STOP: Concomitant use of benzodiazepines and opioids may result in profound respiratory depression, coma, and death. Limit dosages and durations to the minimum required."}, {"alert_type": "Addiction, Abuse, and Misuse", "severity": "High", "trigger_condition": "Prolonged use or history of substance abuse", "message": "STOP: Benzodiazepine use exposes patients to risks of abuse, misuse, and addiction. Abrupt discontinuation can cause life-threatening withdrawal seizures. Taper dose gradually."}]', '**Addiction, Abuse, and Misuse:** Physical and psychological dependence can occur even at recommended dosages. Assess risk prior to prescribing. Abrupt cessation or rapid dose reduction can precipitate acute withdrawal reactions, including life-threatening seizures.
INSERT INTO "drug_generic" VALUES(1404, 'Milnacipran Hydrochloride', 'Milnacipran', 'N06AX17', 0, 1, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Suicidal Thoughts and Behaviors", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes, particularly in young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}, {"alert_type": "Serotonin Syndrome", "severity": "High", "trigger_condition": "Concomitant use with MAOIs or other serotonergic drugs", "message": "STOP: Potentially fatal Serotonin Syndrome can occur. Do not use within 14 days of an MAOI. Monitor for mental status changes, autonomic instability, and neuromuscular abnormalities."}]', 'Monitor blood pressure and heart rate prior to initiating treatment and periodically thereafter, as milnacipran can cause sustained hypertension and tachycardia.
INSERT INTO "drug_generic" VALUES(1405, 'Golimumab', 'Golimumab', 'L04AB06', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Serious Infections and Malignancy", "severity": "High", "trigger_condition": "Initiation of therapy or presence of active infection", "message": "STOP: Increased risk of serious infections (e.g., active tuberculosis, invasive fungal infections, bacterial sepsis) and malignancies (e.g., lymphoma). Evaluate for latent TB and active infections prior to use."}]', '**Risk of Serious Infections:** Patients are at an increased risk for developing serious infections that may lead to hospitalization or death, including tuberculosis (TB), bacterial sepsis, invasive fungal infections, and other opportunistic infections. Interrupt therapy if a serious infection develops.
INSERT INTO "drug_generic" VALUES(1406, 'Dexamethasone + Levofloxacin eye prep', 'Dexamethasone and Levofloxacin ophthalmic', 'S01CA01', 1, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Tendon Rupture Risk", "severity": "High", "trigger_condition": "Systemic absorption or concurrent systemic fluoroquinolone/corticosteroid use", "message": "STOP: Fluoroquinolones are associated with an increased risk of tendinitis and tendon rupture, particularly in older patients and those on concurrent systemic corticosteroids. Discontinue at the first sign of tendon inflammation."}]', '**Ocular Effects:** This preparation is strictly for topical ocular use. It must not be injected sub-conjunctively or introduced directly into the anterior chamber of the eye.
INSERT INTO "drug_generic" VALUES(1407, 'Sodium Cromoglycate 3%  Nasal prep', 'Cromolyn Sodium 3% Nasal', 'R01AC01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Delayed Onset of Action", "severity": "Low", "trigger_condition": "Acute allergic symptoms", "message": "Sodium cromoglycate is a prophylactic agent. It may take 1 to 2 weeks of regular use to achieve maximum therapeutic benefit. It is not effective for immediate relief of acute symptoms."}]', 'Regular administration is required for optimal prophylactic effect. If symptoms do not improve after 1-2 weeks of regular use, the clinical situation should be re-evaluated. This preparation may contain benzalkonium chloride as a preservative, which can cause local irritation or bronchospasm in sensitive individuals.', '- **Allergic Rhinitis:** Indicated for the prevention and treatment of seasonal and perennial allergic rhinitis, accompanied by nasal congestion, sneezing, and rhinorrhea.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to sodium cromoglycate or any of the excipients in the formulation. *Rationale:* Can trigger severe local or systemic allergic reactions.', '- **Local Nasal Effects:** Transient irritation of the nasal mucosa, burning, stinging, and sneezing immediately following application.
INSERT INTO "drug_generic" VALUES(1408, 'Naphazoline + Phenylephrine eye prep', 'Naphazoline and Phenylephrine Ophthalmic', 'S01GA51', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Rebound Congestion Risk", "severity": "Moderate", "trigger_condition": "Use exceeding 72 hours", "message": "Prolonged or frequent use of ophthalmic decongestants can lead to rebound vasodilation, resulting in increased ocular redness and congestion. Do not use for more than 72 hours without medical supervision."}]', 'Use with caution in patients with cardiovascular disease, hypertension, diabetes mellitus, and hyperthyroidism, as systemic absorption of sympathomimetics can exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1409, 'Becaplermin topical', 'Becaplermin topical', 'D03AX06', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Malignancy Risk", "severity": "High", "trigger_condition": "Patients with known malignancies or prolonged use", "message": "Malignancies distant from the site of application have occurred in patients using becaplermin. Evaluate the benefits and risks before prescribing in patients with known malignancy."}]', '- **Malignancy Risk:** Increased rate of mortality secondary to malignancy has been observed in patients treated with 3 or more tubes of becaplermin. Use with caution and evaluate risks in patients with known malignancies.
INSERT INTO "drug_generic" VALUES(1410, 'Suxamethonium Chloride (Succinylcholine)', 'Succinylcholine', 'M03AB01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Malignant Hyperthermia", "severity": "High", "trigger_condition": "Genetic susceptibility", "message": "STOP: Can trigger malignant hyperthermia, a potentially fatal hypermetabolic state of skeletal muscle. Ensure dantrolene and resuscitative equipment are immediately available."}, {"alert_type": "Fatal Hyperkalemia", "severity": "High", "trigger_condition": "Patients with major burns, multiple trauma, extensive skeletal muscle denervation, or upper motor neuron injury", "message": "STOP: May cause acute rhabdomyolysis with severe hyperkalemia leading to ventricular dysrhythmias and cardiac arrest. Contraindicated in these populations."}]', 'Use with extreme caution in patients with reduced plasma cholinesterase (pseudocholinesterase) activity, as this will lead to prolonged neuromuscular blockade and apnea. Caution in patients with bone fractures (muscle fasciculations may cause additional trauma), neuromuscular disorders, cardiac or respiratory disease, electrolyte imbalances (especially hyperkalemia), and suspected cardiac glycoside toxicity. Continuous monitoring of cardiac function, oxygenation, temperature, serum potassium, and neuromuscular function (using a peripheral nerve stimulator) is mandatory.', '- **Neuromuscular Blockade:** Indicated as an adjunct to general anesthesia to facilitate tracheal intubation.
INSERT INTO "drug_generic" VALUES(1411, 'Diphtheria Toxoid 30IU + Tetanus Toxoid 60IU + Pertusis + Hepatitis B (Vaccine)', 'Diphtheria, Tetanus, Pertussis, and Hepatitis B Vaccine', 'J07CA', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Anaphylaxis and Encephalopathy", "severity": "High", "trigger_condition": "History of severe allergic reaction or encephalopathy after previous dose", "message": "STOP: Contraindicated if the patient experienced encephalopathy within 7 days of a previous pertussis vaccine or a severe allergic reaction to any component."}]', '**Neurological Events:** Caution in children with progressive neurological disorders, infantile spasms, uncontrolled epilepsy, or progressive encephalopathy. Defer vaccination until the condition is stabilized.
INSERT INTO "drug_generic" VALUES(1412, 'Isoconazole', 'Isoconazole', 'D01AC05', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Contraceptive Failure", "severity": "Medium", "trigger_condition": "Vaginal administration", "message": "Caution: Vaginal formulations may damage rubber or latex contraceptives (condoms, diaphragms). Additional contraceptive measures are necessary during local administration."}]', '**Local Irritation:** Discontinue use if sensitization or severe local irritation occurs.
INSERT INTO "drug_generic" VALUES(1413, 'Phenylephrine + Promethazine', 'Promethazine and Phenylephrine', 'R05DA20', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Fatal Respiratory Depression in Pediatrics", "severity": "High", "trigger_condition": "Administration to children under 2 years of age", "message": "STOP: Promethazine is contraindicated in children under 2 years of age due to the risk of fatal respiratory depression."}]', '**Respiratory Depression:** Promethazine may cause potentially fatal respiratory depression. Use with extreme caution in patients with compromised respiratory function (e.g., COPD, sleep apnea).
INSERT INTO "drug_generic" VALUES(1414, 'Betamethasone valerate 0.05%  Topical', 'Betamethasone valerate topical', 'D07AC01', 0, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "HPA Axis Suppression", "severity": "High", "trigger_condition": "Prolonged use, use over large surface areas, or use under occlusion", "message": "WARNING: Systemic absorption of topical corticosteroids can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, manifestations of Cushing syndrome, hyperglycemia, and glycosuria."}]', '**Endocrine Effects:** Systemic absorption can cause reversible HPA axis suppression. Risk factors include use of high-potency steroids, large surface areas, prolonged use, occlusive dressings, and altered skin barrier. Evaluate periodically for HPA suppression.
INSERT INTO "drug_generic" VALUES(1415, 'Ciprofloxacin 0.3% + Dexamethasone 0.1% E/E prep', 'Ciprofloxacin and Dexamethasone Ophthalmic/Otic', 'S01CA01', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Ocular Toxicity with Prolonged Use", "severity": "Moderate", "trigger_condition": "Prolonged ophthalmic use (>10 days)", "message": "Prolonged use of topical ocular corticosteroids may result in glaucoma with damage to the optic nerve, defects in visual acuity, and posterior subcapsular cataract formation. Monitor intraocular pressure routinely."}]', '**Superinfection:** Prolonged use may result in the overgrowth of nonsusceptible organisms, including fungi. Discontinue if superinfection occurs.
INSERT INTO "drug_generic" VALUES(1416, 'Benzydamine + Chlorhexidine gluconate mouth prep', 'Benzydamine and Chlorhexidine gluconate oral rinse', 'A01AD11', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Chlorhexidine hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur with chlorhexidine. Verify patient allergy history before prescribing. Discontinue immediately if signs of allergic reaction develop."}]', '**Hypersensitivity:** Chlorhexidine can cause rare but severe allergic reactions, including anaphylactic shock. Discontinue use immediately if any signs of hypersensitivity (rash, itching, swelling, breathing difficulties) develop.
INSERT INTO "drug_generic" VALUES(1417, 'Sevoflurane', 'Sevoflurane', 'N01AB08', 0, 1, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Malignant Hyperthermia", "severity": "High", "trigger_condition": "Patients with a history or susceptibility to malignant hyperthermia", "message": "STOP: Sevoflurane can trigger malignant hyperthermia, a potentially fatal hypermetabolic state of skeletal muscle. Ensure dantrolene is readily available."}]', '**Malignant Hyperthermia:** Can trigger a potentially fatal hypermetabolic state of skeletal muscle. Discontinue immediately if suspected and administer intravenous dantrolene.
INSERT INTO "drug_generic" VALUES(1418, 'Alfentanil', 'Alfentanil', 'N01AH02', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Respiratory Depression and Addiction Risk", "severity": "High", "trigger_condition": "Initiation of therapy or concomitant use with CNS depressants", "message": "STOP: Alfentanil exposes patients to risks of addiction, abuse, and misuse. Serious, life-threatening, or fatal respiratory depression may occur. Concomitant use with benzodiazepines or other CNS depressants can result in profound sedation, coma, and death."}]', '**Respiratory Depression:** Serious, life-threatening, or fatal respiratory depression may occur, especially during initiation or following a dosage increase. Monitor closely. Use with extreme caution in patients with chronic pulmonary disease, or in elderly, cachectic, and debilitated patients.
INSERT INTO "drug_generic" VALUES(1419, 'Hypromellose 0.5 % Eye prep', 'Hypromellose Ophthalmic', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Discontinue use and consult a physician if you experience severe eye pain, changes in vision, continued redness, or irritation of the eye.
INSERT INTO "drug_generic" VALUES(1420, 'Pyrimethamine', 'Pyrimethamine', 'P01BD01', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Bone Marrow Suppression", "severity": "High", "trigger_condition": "High doses or prolonged therapy", "message": "STOP: Pyrimethamine can cause severe, potentially fatal bone marrow suppression (megaloblastic anemia, leukopenia, thrombocytopenia). Concurrent administration of leucovorin (folinic acid) is mandatory to prevent hematologic toxicity. Monitor CBC and platelets twice weekly."}]', 'Use with extreme caution in patients with pre-existing renal or hepatic impairment, or those with folate deficiency (e.g., malnutrition, pregnancy, alcoholism). Monitor complete blood counts (CBC) and platelet counts twice weekly during therapy. Discontinue immediately if signs of severe skin reactions (e.g., Stevens-Johnson syndrome), sore throat, pallor, purpura, or glossitis occur. Always co-administer with leucovorin (folinic acid) to mitigate hematologic toxicity.', '- **Toxoplasmosis:** Treatment of toxoplasmosis (caused by *Toxoplasma gondii*), including congenital toxoplasmosis and toxoplasmic encephalitis in immunocompromised patients. Must be used in combination with a sulfonamide (e.g., sulfadiazine) and leucovorin.
INSERT INTO "drug_generic" VALUES(1421, 'Glucose 11% + Vamin 18 Novum + Intralipid 20% parental', 'Dextrose, Amino Acids, and Lipid Injectable Emulsion', 'B05BA10', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Hypersensitivity and Fat Overload", "severity": "High", "trigger_condition": "Patients with egg, soya, or peanut allergies, or severe hyperlipidemia", "message": "STOP: Contraindicated in patients with hypersensitivity to egg, soya, or peanut proteins. Monitor closely for signs of fat overload syndrome and stop infusion if abnormal signs occur."}]', '**Metabolic Disturbances:** Use with caution in conditions of impaired lipid metabolism, lactic acidosis, increased serum osmolarity, and insufficient cellular oxygen supply. Monitor serum glucose, electrolytes, osmolarity, fluid balance, acid-base status, and liver enzyme tests regularly.
INSERT INTO "drug_generic" VALUES(1422, 'Super Antioxidant Vitamins (Vitamin A + C + E + K ) & Multimineral  (Copper  + Zinc + Manganese + Selenium)', 'Antioxidant Vitamins and Minerals', 'A11AA03', 0, 0, 0, 1, 0, 1, 0, 0, '[{"alert_type": "Drug Interaction with Warfarin", "severity": "High", "trigger_condition": "Concurrent use with Warfarin", "message": "STOP: This preparation contains Vitamin K, which directly antagonizes the anticoagulant effect of Warfarin. Concurrent use can lead to subtherapeutic INR and fatal thrombosis. Avoid use or monitor INR extremely closely."}]', '**Hypervitaminosis:** Fat-soluble vitamins (A, E, K) accumulate in the body. Do not use in overdosage or continuously at high doses without medical supervision.
INSERT INTO "drug_generic" VALUES(1423, 'Follicle Stimulating Hormone', 'Follitropin', 'G03GA05', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Ovarian Hyperstimulation Syndrome (OHSS)", "severity": "High", "trigger_condition": "Rapidly rising serum estradiol levels or development of severe pelvic pain and bloating", "message": "STOP: Severe OHSS can be life-threatening. Withhold hCG administration if ovaries are abnormally enlarged or estradiol levels are excessively high."}]', '**Ovarian Hyperstimulation Syndrome (OHSS):** A potentially life-threatening condition characterized by severe pelvic pain, nausea, vomiting, rapid weight gain, and dyspnea. Monitor follicular development via ultrasound and serum estradiol levels. If OHSS occurs, discontinue FSH and withhold hCG.
INSERT INTO "drug_generic" VALUES(1424, 'Nebivolol', 'Nebivolol', 'C07AB12', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Abrupt Cessation Risk", "severity": "High", "trigger_condition": "Sudden discontinuation of therapy", "message": "STOP: Do not abruptly discontinue nebivolol therapy in patients with coronary artery disease. Severe exacerbation of angina, myocardial infarction, and ventricular arrhythmias have been reported following abrupt withdrawal of beta-blockers. Taper the dose gradually over 1 to 2 weeks."}]', '- **Ischemic Heart Disease:** Abrupt withdrawal may exacerbate angina or precipitate MI. Taper gradually over 1-2 weeks.
INSERT INTO "drug_generic" VALUES(1425, 'Testosterone Enanthate', 'Testosterone Enanthate', 'G03BA03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiovascular and Hepatic Risks", "severity": "High", "trigger_condition": "Long-term use or abuse of testosterone", "message": "Testosterone use is associated with an increased risk of cardiovascular events (MI, stroke), polycythemia, and severe hepatic adverse effects (peliosis hepatis, hepatic neoplasms). Monitor hematocrit, lipid profile, and liver function regularly."}]', 'Monitor hematocrit periodically to detect polycythemia; withhold therapy if hematocrit becomes elevated. Monitor for signs of fluid retention, especially in patients with pre-existing heart failure, renal, or hepatic disease. Evaluate patients for benign prostatic hyperplasia (BPH) and prostate cancer prior to initiation and periodically during therapy, as androgens can stimulate the growth of prostate tissue. Monitor lipid profiles, as testosterone can decrease HDL and increase LDL cholesterol. Use with caution in patients with sleep apnea, as testosterone may exacerbate the condition. In pediatric patients, monitor bone maturation to prevent premature epiphyseal closure.', '- **Male Hypogonadism:** Replacement therapy in conditions associated with a deficiency or absence of endogenous testosterone (primary or secondary hypogonadism).
INSERT INTO "drug_generic" VALUES(1426, 'Reslizumab', 'Reslizumab', 'R03DX08', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "During or within 20 minutes after completion of IV infusion", "message": "STOP: Anaphylaxis has been observed during or within 20 minutes after completion of the reslizumab infusion. Administer only in a healthcare setting by a professional prepared to manage anaphylaxis. Observe patients closely during and after the infusion."}]', '**Anaphylaxis:** Anaphylaxis has been reported during or within 20 minutes after completion of the IV infusion, and as early as the second dose. Administer in a healthcare setting equipped to manage anaphylaxis. Discontinue immediately if anaphylaxis occurs.
INSERT INTO "drug_generic" VALUES(1427, 'Sumatriptan', 'Sumatriptan', 'N02CC01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Events", "severity": "High", "trigger_condition": "Patients with underlying cardiovascular disease or risk factors", "message": "STOP: Serious and potentially fatal cardiac events, including myocardial infarction and arrhythmias, can occur. Evaluate cardiovascular risk before prescribing."}, {"alert_type": "Serotonin Syndrome", "severity": "High", "trigger_condition": "Concurrent use with SSRIs, SNRIs, or MAOIs", "message": "STOP: Co-administration with other serotonergic agents increases the risk of potentially life-threatening serotonin syndrome."}]', 'Use with extreme caution in patients with conditions predisposing to seizures, as seizure threshold may be lowered. Evaluate patients with coronary risk factors (e.g., hypertension, hypercholesterolemia, smoking, obesity, diabetes, strong family history of CAD) prior to initiating therapy. Monitor for signs of cardiac arrhythmias and ischemic events. Exercise caution in patients with mild to moderate hepatic or renal impairment, as drug clearance may be reduced. Use cautiously in the elderly due to potential for decreased hepatic, renal, or cardiac function. Monitor for medication overuse headache (MOH) if used frequently.', '- **Acute Migraine:** Indicated for the acute treatment of migraine with or without aura in adults.
INSERT INTO "drug_generic" VALUES(1428, 'Mycophenolate Mofetil', 'Mycophenolate Mofetil', 'L04AA06', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Embryofetal Toxicity and Malignancy Risk", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "STOP: Mycophenolate is associated with increased risks of first-trimester pregnancy loss, congenital malformations, and the development of lymphomas and other malignancies. Ensure negative pregnancy test and use of effective contraception."}]', 'Patients receiving immunosuppressants are at increased risk of developing lymphomas and other malignancies, particularly of the skin; advise patients to limit exposure to sunlight and UV light. Increased risk of opportunistic infections, including fatal infections and sepsis; monitor closely. Cases of Progressive Multifocal Leukoencephalopathy (PML) and BK virus-associated nephropathy have been reported. Monitor complete blood counts (CBC) weekly during the first month, twice monthly for the second and third months, then monthly through the first year, as severe neutropenia can occur. Mycophenolate mofetil and mycophenolate sodium are not interchangeable due to differences in absorption. Avoid inhalation or direct skin contact with the powder/capsule contents due to teratogenic potential.', '- **Renal Transplant:** Prophylaxis of acute organ rejection and treatment of first or refractory organ rejection in patients receiving allogeneic renal transplants (in combination with corticosteroids and ciclosporin or tacrolimus).
INSERT INTO "drug_generic" VALUES(1429, 'Hydrochlorothiazide', 'Hydrochlorothiazide', 'C03AA03', 0, 0, 0, 1, 1, 0, 1, 0, '[]', '**Electrolyte Imbalance:** Can cause hypokalemia, hyponatremia, hypochloremic alkalosis, and hypomagnesemia. Monitor serum electrolytes periodically. 
INSERT INTO "drug_generic" VALUES(1430, 'Oral Cholera Vaccine (Vibrio cholerae 01 Inaba & Ogawa strains)', 'Cholera Vaccine, Live, Oral', 'J07AE01', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '- **Incomplete Protection:** The vaccine does not provide 100% protection against cholera. Travelers must continue to adhere strictly to standard food and water hygiene precautions.
INSERT INTO "drug_generic" VALUES(1431, 'Timolol Maleate 0.25%  Eye prep', 'Timolol Ophthalmic', 'S01ED01', 0, 0, 0, 0, 0, 1, 0, 0, '[]', 'Systemic absorption can occur following topical ophthalmic administration, leading to severe respiratory and cardiac reactions, including death due to bronchospasm or cardiac failure.
INSERT INTO "drug_generic" VALUES(1432, 'Topotecan', 'Topotecan', 'L01CE01', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Baseline neutrophil count <1500 cells/mm\u00b3 or platelet count <100,000 cells/mm\u00b3", "message": "STOP: Topotecan causes severe, potentially fatal myelosuppression (neutropenia, thrombocytopenia, anemia). Do not administer unless baseline counts are adequate. Monitor blood counts frequently."}]', '- **Bone Marrow Suppression:** Grade 4 neutropenia, Grade 4 thrombocytopenia, and Grade 3-4 anemia are common. Administer only if the patient has adequate bone marrow reserves. Withhold and reduce the dose based on neutrophil counts, platelet counts, and hemoglobin levels.
INSERT INTO "drug_generic" VALUES(1433, 'Prucalopride', 'Prucalopride', 'A06AX05', 0, 0, 0, 0, 1, 0, 0, 0, '[]', '**Cardiovascular Risk:** Use with caution in patients with a history of arrhythmias or ischemic cardiovascular disease. Although prucalopride is highly selective for 5-HT4 receptors, monitor for any signs of palpitations or cardiovascular compromise.
INSERT INTO "drug_generic" VALUES(1434, 'Stanozolol', 'Stanozolol', 'A14AA02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Prolonged use or high doses", "message": "WARNING: Potentially fatal peliosis hepatis, hepatic necrosis, and hepatocellular carcinoma have been associated with prolonged use of anabolic steroids. Monitor liver function closely."}]', '**Hepatotoxicity:** Severe hepatic effects including cholestatic jaundice, peliosis hepatis, and hepatic neoplasms can occur. Discontinue immediately if signs of liver failure develop.
INSERT INTO "drug_generic" VALUES(1435, 'Pimavanserin', 'Pimavanserin', 'N05AX17', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Increased Mortality in Elderly Patients", "severity": "High", "trigger_condition": "Use in elderly patients with dementia-related psychosis", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Pimavanserin is not approved for the treatment of patients with dementia-related psychosis unrelated to the hallucinations and delusions associated with Parkinson''s disease psychosis."}]', '**Increased Mortality in Elderly Patients with Dementia-Related Psychosis:** Antipsychotic drugs increase the all-cause risk of death in elderly patients with dementia-related psychosis. Pimavanserin is not approved for dementia-related psychosis unrelated to Parkinson''s disease.
INSERT INTO "drug_generic" VALUES(1436, 'Filgrastim', 'Filgrastim', 'L03AA02', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Splenic Rupture", "severity": "High", "trigger_condition": "Patient presenting with left upper abdominal or shoulder tip pain", "message": "STOP: Fatal splenic rupture has occurred. Evaluate patients who report left upper abdominal or shoulder tip pain for an enlarged spleen or splenic rupture immediately."}, {"alert_type": "Acute Respiratory Distress Syndrome (ARDS)", "severity": "High", "trigger_condition": "Patient developing fever, lung infiltrates, or respiratory distress", "message": "STOP: ARDS has been reported. Evaluate patients who develop fever and lung infiltrates or respiratory distress. Discontinue filgrastim in patients with ARDS."}]', '**Timing of Administration:** Do not administer within 24 hours before or 24 hours after the administration of cytotoxic chemotherapy due to the potential sensitivity of rapidly dividing myeloid cells to cytotoxic agents.
INSERT INTO "drug_generic" VALUES(1437, 'Ferrous Gluconate', 'Ferrous Gluconate', 'B03AA03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Fatal Poisoning in Children", "severity": "High", "trigger_condition": "Accidental ingestion by children under 6 years of age", "message": "WARNING: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Gastrointestinal Conditions:** Avoid use or use with caution in patients with peptic ulcer disease, enteritis, or ulcerative colitis, as oral iron may exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1438, 'Tolfenamic Acid', 'Tolfenamic Acid', 'M01AG02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Prolonged use or history of cardiovascular/GI disease", "message": "NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation."}]', 'Use with caution in patients with a history of bronchial asthma, uncontrolled hypertension, congestive heart failure, established ischemic heart disease, peripheral arterial disease, or cerebrovascular disease. Exercise caution in patients with coagulation defects, systemic lupus erythematosus (SLE), connective tissue disorders, or a history of GI disease (e.g., Crohn''s disease, ulcerative colitis). Monitor renal and hepatic function periodically during prolonged therapy. May cause dizziness, drowsiness, or visual disturbances; advise patients to avoid driving or operating machinery if affected.', '- **Acute Migraine Attacks:** Symptomatic relief of acute migraine headaches.
INSERT INTO "drug_generic" VALUES(1439, 'Budesonide Oral', 'Budesonide', 'A07EA06', 0, 0, 1, 1, 0, 0, 1, 1, '[{"alert_type": "Adrenal Suppression", "severity": "High", "trigger_condition": "Transferring from systemic corticosteroids or prolonged use", "message": "STOP: Risk of impaired adrenal function when transferring from systemic glucocorticoids. Taper systemic corticosteroids slowly. Monitor for signs of hypercorticism and HPA axis suppression."}]', '**Hypercorticism and Adrenal Suppression:** Since budesonide is a glucocorticosteroid, follow general warnings concerning glucocorticoids. Prolonged use may cause hypercorticism and suppression of the hypothalamic-pituitary-adrenal (HPA) axis.
INSERT INTO "drug_generic" VALUES(1440, 'Griseofulvin', 'Griseofulvin', 'D01BA01', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity and Porphyria", "severity": "High", "trigger_condition": "Patient with severe liver disease or porphyria", "message": "STOP: Griseofulvin is contraindicated in severe liver disease and porphyria. It can cause severe hepatotoxicity and exacerbate porphyria by inducing porphyrin synthesis."}]', '**Hepatotoxicity:** Severe and potentially fatal hepatotoxicity has been reported. Regular monitoring of hepatic function (AST, ALT, bilirubin) is required during prolonged therapy. Discontinue if signs of liver failure develop.
INSERT INTO "drug_generic" VALUES(1441, 'Epoetin beta', 'Epoetin beta', 'B03XA01', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cardiovascular Events and Tumor Progression", "severity": "High", "trigger_condition": "Targeting hemoglobin levels > 11 g/dL or use in certain cancer patients", "message": "STOP: Erythropoiesis-stimulating agents (ESAs) increase the risk of death, myocardial infarction, stroke, venous thromboembolism, and tumor progression. Use the lowest dose needed to avoid red blood cell transfusions. Do not target a hemoglobin level > 11 g/dL."}]', '**Hypertension:** Blood pressure may rise significantly during therapy. Control hypertension adequately before initiation and monitor closely. Hypertensive encephalopathy and seizures have occurred.
INSERT INTO "drug_generic" VALUES(1442, 'Methylprednisolone', 'Methylprednisolone', 'H02AB04', 0, 0, 0, 1, 0, 0, 1, 1, '[{"alert_type": "Adrenal Suppression and Infection Risk", "severity": "High", "trigger_condition": "Prolonged use or abrupt withdrawal", "message": "STOP: Abrupt withdrawal can cause fatal adrenal crisis. Taper dose gradually. Corticosteroids mask signs of infection and increase susceptibility to severe infections."}]', '**Adrenal Suppression:** Prolonged use causes hypothalamic-pituitary-adrenal (HPA) axis suppression. Abrupt withdrawal can lead to acute adrenal crisis (nausea, vomiting, hypotension, death). Taper the dose gradually when discontinuing therapy.
INSERT INTO "drug_generic" VALUES(1443, 'Ramucirumab', 'Ramucirumab', 'L01FG02', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Hemorrhage and GI Perforation", "severity": "High", "trigger_condition": "During therapy", "message": "STOP: Increases the risk of severe and fatal hemorrhage and gastrointestinal perforation. Permanently discontinue if severe bleeding or GI perforation occurs."}, {"alert_type": "Impaired Wound Healing", "severity": "High", "trigger_condition": "Perioperative period", "message": "STOP: Withhold for 28 days prior to elective surgery. Do not administer for at least 2 weeks following a major surgical procedure and until adequate wound healing is achieved."}]', '**Arterial Thromboembolic Events (ATEs):** Serious and sometimes fatal ATEs (e.g., myocardial infarction, cardiac arrest, stroke) can occur. Permanently discontinue in patients who experience an ATE.
INSERT INTO "drug_generic" VALUES(1444, 'Gabapentin', 'Gabapentin', 'N03AX12', 0, 0, 0, 0, 1, 1, 1, 1, '[{"alert_type": "Withdrawal Seizures & Suicidality", "severity": "High", "trigger_condition": "Abrupt discontinuation or underlying psychiatric disorders", "message": "STOP: Do not discontinue abruptly; taper gradually over at least 1 week to prevent withdrawal seizures. Monitor all patients for emergence or worsening of depression, suicidal thoughts, or unusual changes in mood or behavior."}]', 'Use with caution in patients with renal impairment; dosage adjustments are strictly required based on creatinine clearance.
INSERT INTO "drug_generic" VALUES(1445, 'Polyethylene Glycol 400 0.4% + Propylene Glycol 0.3% Eye prep', 'Polyethylene Glycol 400 / Propylene Glycol Ophthalmic', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Contamination Risk:** Do not touch the tip of the container to any surface, including the eye or eyelid, to avoid contamination of the solution.
INSERT INTO "drug_generic" VALUES(1446, 'Omeprazole + Domperidone', 'Omeprazole and Domperidone', 'A02BC51', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiac Arrhythmia Risk", "severity": "High", "trigger_condition": "Concurrent use with QT-prolonging drugs or in patients with underlying cardiac disease", "message": "STOP: Domperidone is associated with an increased risk of QT prolongation, serious ventricular arrhythmias, and sudden cardiac death. Use the lowest effective dose for the shortest duration."}]', '**Gastric Malignancy:** Symptomatic response to therapy does not preclude the presence of gastric malignancy. Exclude malignancy prior to initiating treatment with omeprazole, as it may mask symptoms and delay diagnosis.
INSERT INTO "drug_generic" VALUES(1447, 'Dextran 70 + Sodium Chloride', 'Dextran 70 in Sodium Chloride', 'B05AA05', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Anaphylaxis and Fluid Overload", "severity": "High", "trigger_condition": "Administration of Dextran 70", "message": "STOP: Severe and fatal anaphylactoid reactions can occur. Observe patients closely during the first minutes of infusion. Dextran 70 causes significant plasma volume expansion; contraindicated in severe heart failure and severe renal disease."}]', '**Anaphylactoid Reactions:** Severe and fatal anaphylactoid reactions have been reported. Discontinue use immediately at the first sign of hypersensitivity (e.g., hypotension, wheezing, tightness of chest) and administer appropriate therapy.
INSERT INTO "drug_generic" VALUES(1448, 'Fesoterodine Fumarate', 'Fesoterodine Fumarate', 'G04BD11', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Urinary and Gastric Retention", "severity": "High", "trigger_condition": "Patients with clinically significant bladder outflow obstruction or severe gastrointestinal obstructive disorders", "message": "STOP: Fesoterodine is contraindicated in patients with urinary retention or gastric retention due to its potent antimuscarinic effects."}]', '**Angioedema:** Discontinue immediately and provide appropriate therapy if angioedema of the face, lips, tongue, or larynx occurs.
INSERT INTO "drug_generic" VALUES(1449, 'Levothyroxine Sodium', 'Levothyroxine Sodium', 'H03AA01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Not for Weight Loss", "severity": "High", "trigger_condition": "Prescription for obesity or weight loss", "message": "STOP: Thyroid hormones, including levothyroxine, should not be used for the treatment of obesity or for weight loss. Larger doses may produce serious or even life-threatening manifestations of toxicity."}]', '**Cardiovascular Disease:** Use with extreme caution in patients with cardiovascular disorders (e.g., angina, heart failure, hypertension, recent MI). Initiate at lower doses and titrate slowly. Overtreatment can cause arrhythmias or exacerbate angina.
INSERT INTO "drug_generic" VALUES(1450, 'Ibandronic Acid', 'Ibandronate', 'M05BA06', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Upper Gastrointestinal Toxicity", "severity": "High", "trigger_condition": "Oral administration without adhering to strict dosing instructions", "message": "STOP: Oral ibandronate can cause severe esophageal irritation, esophagitis, ulcers, and erosions. Patients MUST sit or stand upright for at least 60 minutes after taking the dose and take it with a full glass of plain water."}, {"alert_type": "Osteonecrosis of the Jaw (ONJ)", "severity": "Moderate", "trigger_condition": "Invasive dental procedures or poor oral hygiene", "message": "STOP: ONJ has been reported in patients receiving bisphosphonates. A dental exam is recommended prior to treatment. Avoid invasive dental procedures during therapy if possible."}]', 'Evaluate and correct hypocalcemia and other disturbances of bone and mineral metabolism before initiating therapy.
INSERT INTO "drug_generic" VALUES(1451, 'Exemestane', 'Exemestane', 'L02BG06', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Bone Mineral Density Reduction", "severity": "High", "trigger_condition": "Long-term therapy in postmenopausal women", "message": "Exemestane significantly lowers serum estrogen, leading to a reduction in bone mineral density (BMD) and an increased risk of osteoporosis and fractures. Monitor BMD regularly."}]', '**Bone Mineral Density (BMD):** Exemestane causes a reduction in BMD. Assess BMD at baseline and at regular intervals during treatment, especially in patients with or at risk for osteoporosis. Initiate appropriate treatment or prophylaxis for osteoporosis as needed.
INSERT INTO "drug_generic" VALUES(1452, 'Nalbuphine Hydrochloride', 'Nalbuphine', 'N02AF02', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Withdrawal Risk", "severity": "High", "trigger_condition": "Administration to patients physically dependent on pure opioid agonists", "message": "WARNING: Nalbuphine is a mixed agonist-antagonist. Administering it to patients physically dependent on pure opioid agonists (e.g., morphine, fentanyl) can precipitate severe withdrawal symptoms."}]', '**Respiratory Depression:** Can cause severe respiratory depression. Use with caution in patients with impaired respiration (e.g., asthma, uremia, severe infection).
INSERT INTO "drug_generic" VALUES(1453, 'Dexamethasone + Neomycin + Glacial acetic acid ear prep', 'Dexamethasone / Neomycin / Acetic Acid Otic', 'S02CA06', 1, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Ototoxicity Risk", "severity": "High", "trigger_condition": "Perforated tympanic membrane or presence of tympanostomy tubes", "message": "STOP: Do not use if the tympanic membrane is perforated or if tympanostomy tubes (grommets) are in place. Aminoglycosides (neomycin) can enter the middle/inner ear and cause irreversible deafness."}]', '**Tympanic Membrane Integrity**
INSERT INTO "drug_generic" VALUES(1454, 'Botulinum antitoxin', 'Botulinum antitoxin', 'J06AA04', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "Administration of equine-derived antitoxin", "message": "STOP: Immediate systemic reactions (allergic reactions, shock, anaphylaxis) can occur because this is an equine-derived product. Epinephrine, diphenhydramine, and intubation capabilities must be immediately available."}]', '**Hypersensitivity Reactions:** Immediate systemic reactions, including anaphylaxis and shock, can occur whenever an equine-derived product is administered. The reaction usually occurs within 30 minutes after initiating the infusion. Milder allergic reactions (e.g., mild bronchoconstriction, hypotension, hives) may be more common. Infuse slowly and monitor continuously.
INSERT INTO "drug_generic" VALUES(1455, 'Enzalutamide', 'Enzalutamide', 'L02BB04', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Seizure Risk", "severity": "High", "trigger_condition": "History of seizures, brain injury, stroke, or brain tumors", "message": "STOP: Enzalutamide lowers the seizure threshold. Seizures have occurred in patients receiving this drug. Permanently discontinue if a seizure occurs during treatment."}]', '**Seizure Risk:** Enzalutamide crosses the blood-brain barrier and can induce seizures. The risk is higher in patients with predisposing factors (e.g., prior stroke, brain metastasis, alcoholism). Permanently discontinue treatment if a seizure occurs.
INSERT INTO "drug_generic" VALUES(1456, 'Alcaftadine eye prep', 'Alcaftadine Ophthalmic', 'S01GX08', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'To prevent contamination of the dropper tip and solution, care should be taken not to touch the eyelids or surrounding areas with the dropper tip. Patients should be advised not to wear a contact lens if their eye is red. Alcaftadine should not be used to treat contact lens-related irritation. The preservative in the solution, benzalkonium chloride, may be absorbed by soft contact lenses; lenses should be removed prior to instillation and may be reinserted 15 minutes following administration.', '- Prevention of itching associated with allergic conjunctivitis.', '- **Hypersensitivity:** Contraindicated in patients who are hypersensitive to alcaftadine or any component of the formulation, as it can precipitate severe local or systemic allergic reactions.', '- Ocular irritation, burning, and stinging upon instillation
INSERT INTO "drug_generic" VALUES(1457, 'Oxymetazoline Hydrochloride .05 % Nasal prep', 'Oxymetazoline Hydrochloride 0.05% Nasal Drops/Spray', 'R01AA05', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Rebound Congestion (Rhinitis Medicamentosa)", "severity": "Moderate", "trigger_condition": "Use exceeding 3 to 5 consecutive days", "message": "Prolonged use beyond 3-5 days can cause severe rebound nasal congestion and mucosal damage. Limit therapy duration strictly."}]', '**Rebound Congestion:** Prolonged or excessive use (greater than 3 to 5 days) may lead to rhinitis medicamentosa (rebound congestion), characterized by chronic redness, swelling, and rhinitis.
INSERT INTO "drug_generic" VALUES(1458, 'Adenine .0275 % + Citric Acid Anhydrous .3 % + Dextrose', 'Anticoagulant Citrate Phosphate Dextrose Adenine Solution (CPDA-1)', 'V07AC', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Administration Route Warning", "severity": "High", "trigger_condition": "Attempted direct intravenous injection", "message": "STOP: This solution is strictly for EX VIVO use as an anticoagulant and preservative in blood collection bags. NEVER inject directly into a patient."}]', '**Massive Transfusion:** When large volumes of blood preserved with CPDA-1 are transfused rapidly, the citrate load can exceed the liver''s capacity to metabolize it, leading to severe hypocalcemia (citrate toxicity). Monitor ionized calcium levels during massive transfusions.
INSERT INTO "drug_generic" VALUES(1459, 'Vardenafil', 'Vardenafil', 'G04BE09', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Concomitant Nitrate Use", "severity": "High", "trigger_condition": "Patient taking any form of organic nitrates or nitrites", "message": "STOP: Coadministration with nitrates (e.g., nitroglycerin, isosorbide) is absolutely contraindicated. It can cause a severe, life-threatening drop in blood pressure."}]', '**Cardiovascular Risk:** Sexual activity carries a cardiac risk. Evaluate the cardiovascular status of the patient before prescribing. Avoid in patients where sexual intercourse is inadvisable due to underlying CV risk factors.
INSERT INTO "drug_generic" VALUES(1460, 'Fucidic Acid + Betamethasone Topical', 'Fusidic Acid and Betamethasone', 'D07CC01', 1, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Ophthalmic Risk", "severity": "High", "trigger_condition": "Application near the eyes", "message": "STOP: Avoid application near the eyes. Systemic absorption or local exposure to topical corticosteroids can cause glaucoma and cataracts."}]', '**Prolonged Use:** Avoid prolonged continuous treatment, especially in infants and children, due to the risk of adrenal suppression and local skin atrophy. Extended treatment may also increase the risk of contact sensitization and the development of antibiotic resistance.
INSERT INTO "drug_generic" VALUES(1461, 'Tigecycline', 'Tigecycline', 'J01AA12', 1, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Increased Mortality Risk", "severity": "High", "trigger_condition": "Prescription for any indication", "message": "STOP: An increase in all-cause mortality has been observed across Phase 3 clinical trials in patients treated with tigecycline compared to comparator drugs. Reserve tigecycline for use in situations when alternative treatments are not suitable."}]', 'Reserve for use only when alternative treatments are not suitable due to an observed increase in all-cause mortality.
INSERT INTO "drug_generic" VALUES(1462, 'Omeprazole + Metronidazole + Clarithromycin', 'Omeprazole, Metronidazole, and Clarithromycin', 'A02BD05', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "QT Prolongation and Arrhythmia Risk", "severity": "High", "trigger_condition": "Concomitant use with QT-prolonging drugs or in patients with cardiac disease", "message": "STOP: Clarithromycin can cause QT prolongation and fatal arrhythmias (Torsades de Pointes). Avoid use with other QT-prolonging agents (e.g., pimozide, cisapride) and in patients with a history of QT prolongation."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity reactions (including anaphylaxis, Stevens-Johnson syndrome, and toxic epidermal necrolysis) have been reported with clarithromycin and metronidazole. Discontinue immediately if a rash occurs.
INSERT INTO "drug_generic" VALUES(1463, 'Trabectedin', 'Trabectedin', 'L01CX01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Neutropenic Sepsis and Rhabdomyolysis", "severity": "High", "trigger_condition": "Initiation of therapy or during treatment cycles", "message": "STOP: Severe neutropenia, sepsis, and rhabdomyolysis can occur. Monitor CBC and CPK levels. Premedicate with dexamethasone to reduce hepatotoxicity and antiemetic requirements."}]', '**Neutropenic Sepsis:** Severe and fatal neutropenic sepsis has occurred. Monitor complete blood counts (CBC) prior to each dose and periodically throughout the treatment cycle. Withhold trabectedin for severe neutropenia.
INSERT INTO "drug_generic" VALUES(1464, 'Enoxaparin Sodium', 'Enoxaparin Sodium', 'B01AB05', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Spinal/Epidural Hematoma", "severity": "High", "trigger_condition": "Neuraxial anesthesia or spinal puncture", "message": "STOP: Epidural or spinal hematomas may occur in patients who are anticoagulated with low molecular weight heparins and are receiving neuraxial anesthesia or undergoing spinal puncture. These hematomas may result in long-term or permanent paralysis."}]', '- **Bleeding Risk:** Use with extreme caution in conditions with an increased potential for bleeding, such as impaired hemostasis, history of peptic ulcer, recent ischemic stroke, uncontrolled severe hypertension, or diabetic retinopathy.
INSERT INTO "drug_generic" VALUES(1465, 'Octreotide', 'Octreotide', 'H01CB02', 0, 0, 1, 0, 1, 1, 0, 0, '[{"alert_type": "Gallbladder Abnormalities", "severity": "High", "trigger_condition": "Long-term therapy", "message": "STOP: Octreotide inhibits gallbladder contractility and decreases bile secretion. Gallstones or biliary sludge occur in up to 60% of patients on long-term therapy. Monitor periodically with gallbladder ultrasound."}]', 'Monitor blood glucose closely, as octreotide alters the balance of insulin, glucagon, and growth hormone, potentially causing severe hypoglycemia or hyperglycemia. Monitor thyroid function (TSH) periodically, as suppression of TSH may lead to hypothyroidism. Monitor heart rate and ECG, as bradycardia, arrhythmias, and conduction abnormalities can occur. Monitor vitamin B12 levels during long-term therapy due to decreased absorption. Use with caution in patients with renal impairment, hepatic cirrhosis, or diabetes mellitus.', '- **Acromegaly:** To reduce blood levels of growth hormone (GH) and IGF-1 in patients who have had an inadequate response to or cannot be treated with surgical resection, pituitary irradiation, or bromocriptine.
INSERT INTO "drug_generic" VALUES(1466, 'Heparin Sodium', 'Heparin Sodium', 'B01AB01', 0, 1, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Bleeding Risk and Heparin-Induced Thrombocytopenia (HIT)", "severity": "High", "trigger_condition": "Administration of therapeutic or prophylactic doses", "message": "STOP: High risk of fatal hemorrhage and Heparin-Induced Thrombocytopenia (HIT). Monitor platelet counts and aPTT closely. Discontinue immediately if unexplained thrombocytopenia or new thrombosis occurs."}]', '**Hemorrhage Risk:** Can cause major and fatal bleeding. Use with extreme caution in conditions with increased bleeding risk (e.g., subacute bacterial endocarditis, severe hypertension, recent gastrointestinal bleeding, or recent neurosurgery).
INSERT INTO "drug_generic" VALUES(1467, 'Diphtheria toxoids + tetanus toxoids + pertussis toxoid + inactivated Poliomyelitis virus + Haemophilus influenzae type b Vaccine', 'Diphtheria, Tetanus, Pertussis, Poliovirus, and Haemophilus b Vaccine', 'J07CA06', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Anaphylaxis and Encephalopathy", "severity": "High", "trigger_condition": "History of severe allergic reaction or encephalopathy after previous dose", "message": "STOP: Contraindicated if the patient experienced encephalopathy within 7 days of a previous pertussis vaccine or a severe allergic reaction to any component."}]', '**Neurological Events:** Caution in children with progressive neurological disorders, infantile spasms, uncontrolled epilepsy, or progressive encephalopathy. Defer vaccination until the condition is stabilized.
INSERT INTO "drug_generic" VALUES(1468, 'Fulvestrant', 'Fulvestrant', 'L02BA03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Bleeding Risk", "severity": "High", "trigger_condition": "Administration in patients with bleeding diatheses or on anticoagulants", "message": "STOP: Fulvestrant is administered via deep intramuscular injection. Use with extreme caution in patients with bleeding diatheses, thrombocytopenia, or those receiving anticoagulants due to the risk of severe hematoma."}]', '**Bleeding Risk:** Because fulvestrant is administered intramuscularly, it should be used with caution in patients with bleeding diatheses, thrombocytopenia, or those receiving anticoagulant therapy.
INSERT INTO "drug_generic" VALUES(1469, 'Eptifibatide', 'Eptifibatide', 'B01AC16', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Bleeding Risk", "severity": "High", "trigger_condition": "Concomitant use of anticoagulants, recent surgery, or history of bleeding disorders", "message": "STOP: Eptifibatide significantly increases the risk of severe bleeding. Discontinue immediately if serious, uncontrolled bleeding occurs or if emergency surgery is required. Monitor coagulation parameters and platelet counts closely."}]', '**Bleeding Risk:** The most common complication is bleeding. Use with caution in patients with a high risk of bleeding, including those weighing <70 kg, elderly patients, or those receiving concomitant thrombolytics, heparin, or other antiplatelet agents. Discontinue therapy if serious uncontrolled bleeding occurs.
INSERT INTO "drug_generic" VALUES(1470, 'Dalteparin Sodium', 'Dalteparin', 'B01AB04', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Spinal/Epidural Hematoma", "severity": "High", "trigger_condition": "Neuraxial anesthesia or spinal puncture", "message": "STOP: Epidural or spinal hematomas, which may result in long-term or permanent paralysis, can occur in patients anticoagulated with LMWHs receiving neuraxial anesthesia or spinal puncture. Consider risks before intervention."}]', '**Spinal/Epidural Hematoma:** Patients receiving dalteparin who undergo neuraxial anesthesia or spinal puncture are at risk for developing an epidural or spinal hematoma, which can result in long-term or permanent paralysis. Risk increases with indwelling epidural catheters, concomitant use of NSAIDs/antiplatelets, or history of spinal deformity/surgery. Monitor frequently for neurological impairment.
INSERT INTO "drug_generic" VALUES(1471, 'Tetracycline Hydrochloride 3% Eye prep', 'Tetracycline Ophthalmic', 'S01AA09', 1, 0, 1, 1, 0, 1, 1, 0, '[]', 'Prolonged use may result in the overgrowth of nonsusceptible organisms, including fungi. If superinfection occurs, discontinue use and institute appropriate therapy. Avoid exposure to excessive sunlight during treatment. Periodic evaluation of renal, hepatic, and hematopoietic systems is recommended during prolonged therapy, although systemic absorption from ophthalmic use is minimal.', '- **Bacterial Conjunctivitis:** Indicated for the treatment of acute and severe superficial ocular infections caused by susceptible strains of microorganisms.
INSERT INTO "drug_generic" VALUES(1472, 'Lactic acid + Citric acid + Potassium bitartrate vaginal', 'Lactic acid, Citric acid, and Potassium bitartrate vaginal gel', 'G02BB', 0, 0, 0, 1, 0, 1, 0, 0, '[]', '**Urinary Tract Infections (UTIs):** Cystitis, pyelonephritis, or other upper UTIs may occur. Avoid use in females of reproductive potential with a history of recurrent UTIs or urinary tract abnormalities.
INSERT INTO "drug_generic" VALUES(1473, 'Mitomycin C (Crystalline)', 'Mitomycin', 'L01DC03', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Bone Marrow Suppression and Hemolytic Uremic Syndrome", "severity": "High", "trigger_condition": "Administration of Mitomycin", "message": "STOP: Mitomycin causes severe, cumulative myelosuppression (thrombocytopenia, leukopenia). Hemolytic Uremic Syndrome (HUS), a potentially fatal condition, can occur, especially at cumulative doses >60 mg. Monitor CBC and renal function strictly."}]', '**Bone Marrow Suppression:** Mitomycin causes severe, cumulative, and potentially fatal myelosuppression, notably thrombocytopenia and leukopenia, which may contribute to overwhelming infections or hemorrhage. Do not repeat doses until WBC >4000/mm³ and Platelets >100,000/mm³. Monitor CBC repeatedly during and for at least 8 weeks following therapy.
INSERT INTO "drug_generic" VALUES(1474, 'Fusidic Acid 1% eye prep', 'Fusidic Acid Ophthalmic', 'S01AA13', 1, 0, 1, 1, 0, 1, 1, 0, '[]', '**Contact Lenses:** Contact lenses should not be worn during the treatment of an ocular infection. The microcrystalline fusidic acid may also cause scratches to the contact lens or cornea.
INSERT INTO "drug_generic" VALUES(1475, 'Benzocaine 0.20% + Camphor 0.25% + Methanol 0.25%', 'Benzocaine, Camphor, and Menthol', 'N01BA55', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Methemoglobinemia", "severity": "High", "trigger_condition": "Use of oral benzocaine products", "message": "STOP: Benzocaine can cause fatal methemoglobinemia. The FDA strongly warns against using oral benzocaine products for teething in children under 2 years of age. Advise adults to seek immediate medical attention if cyanosis, headache, or shortness of breath occurs."}]', '**Application Site:** Do not use over deep or puncture wounds, severe infections, or lacerations. Avoid contact with the eyes.
INSERT INTO "drug_generic" VALUES(1476, 'Tafluprost', 'Tafluprost', 'S01EE05', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Ocular Pigmentation Changes", "severity": "Moderate", "trigger_condition": "Initiation of therapy", "message": "WARNING: Tafluprost can cause permanent changes to pigmented tissues, including increased brown pigmentation of the iris. It may also cause reversible darkening, thickening, and lengthening of eyelashes."}]', '**Pigmentation Changes:** May cause permanent brown pigmentation of the iris and reversible darkening of the periorbital tissue and eyelashes.
INSERT INTO "drug_generic" VALUES(1477, 'Betamethasone dipropionate Topical', 'Betamethasone dipropionate', 'D07AC01', 0, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "HPA Axis Suppression", "severity": "High", "trigger_condition": "Prolonged use, application to large surface areas, or use under occlusion", "message": "STOP: High-potency topical corticosteroids can cause reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, leading to glucocorticosteroid insufficiency. Limit use to 2 weeks and avoid occlusive dressings."}]', '**Endocrine Effects:** Can cause reversible HPA axis suppression, Cushing''s syndrome, hyperglycemia, and unmask latent diabetes. Risk factors include high-potency formulations, use over large surface areas, prolonged use, occlusive dressings, altered skin barrier, and use in pediatric patients.
INSERT INTO "drug_generic" VALUES(1478, 'Influenza vaccine inactivated (split virion)', 'Influenza Virus Vaccine, Inactivated', 'J07BB02', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe allergic reaction to egg proteins or vaccine components", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, can occur. Verify patient allergy history before administration. Epinephrine and appropriate medical equipment must be readily available."}]', '**Guillain-Barré Syndrome (GBS):** Patients with a history of GBS with an onset related in time (within 6 weeks) to a previous influenza vaccination may be at increased risk of again developing GBS if given the influenza vaccine.
INSERT INTO "drug_generic" VALUES(1479, 'Calcipotriene 0.005% topical', 'Calcipotriene topical', 'D05AX02', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "High", "trigger_condition": "Excessive application or use in patients with calcium metabolism disorders", "message": "WARNING: Systemic absorption can cause hypercalcemia. If elevation of serum calcium occurs, discontinue treatment immediately until normal calcium levels are restored."}]', '**Calcium Metabolism:** Transient, rapidly reversible elevation of serum calcium has occurred. Monitor serum calcium if used over large surface areas or exceeding recommended maximum weekly doses (100g/week).
INSERT INTO "drug_generic" VALUES(1480, 'Phentermine + Topiramate', 'Phentermine / Topiramate', 'A08AA62', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Teratogenicity", "severity": "High", "trigger_condition": "Use during pregnancy", "message": "STOP: Contraindicated in pregnancy. Can cause fetal harm, including cleft lip and cleft palate. Ensure a negative pregnancy test before initiating and use effective contraception during therapy."}]', '**Cardiovascular Effects:** May increase resting heart rate by up to 20 bpm. Use with caution in patients with a history of cardiac or cerebrovascular disease. Monitor heart rate regularly.
INSERT INTO "drug_generic" VALUES(1481, 'Docetaxel', 'Docetaxel', 'L01CD02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Toxic Death, Neutropenia, and Hypersensitivity", "severity": "High", "trigger_condition": "Hepatic impairment, baseline neutropenia, or lack of premedication", "message": "STOP: High risk of toxic death in patients with hepatic impairment. Severe, fatal neutropenia and severe hypersensitivity reactions (anaphylaxis) can occur. Premedication with corticosteroids is MANDATORY to prevent fluid retention and hypersensitivity."}]', '- **Hepatic Impairment:** Treatment-related mortality is significantly increased in patients with abnormal liver function. Avoid use in patients with severe hepatic impairment (elevated bilirubin or transaminases >1.5x ULN with alk phos >2.5x ULN).
INSERT INTO "drug_generic" VALUES(1482, 'Deflazacort', 'Deflazacort', 'H02AB13', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Immunosuppression and Infection Risk", "severity": "High", "trigger_condition": "Systemic infection or exposure to viral illnesses (e.g., chickenpox, measles)", "message": "STOP: Corticosteroids increase the risk of severe or fatal infections and can mask signs of infection. Avoid exposure to chickenpox or measles. Do not administer live vaccines to patients on immunosuppressive doses."}]', 'Monitor for Hypothalamic-Pituitary-Adrenal (HPA) axis suppression, Cushing''s syndrome, and hyperglycemia, especially with chronic use. Taper dose gradually when discontinuing.
INSERT INTO "drug_generic" VALUES(1483, 'Sulfinpyrazone', 'Sulfinpyrazone', 'M04AB02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Acute Gout Exacerbation and Urolithiasis", "severity": "High", "trigger_condition": "Initiation of therapy or inadequate hydration", "message": "May precipitate acute gouty attacks during early therapy. High risk of uric acid renal calculi if fluid intake is inadequate. Ensure high fluid intake and urine alkalinization."}]', '**Renal Calculi:** High risk of uric acid stone formation. Ensure adequate fluid intake (2-3 L/day) and consider urine alkalinization.
INSERT INTO "drug_generic" VALUES(1484, 'Rofecoxib', 'Rofecoxib', 'M01AH02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Thrombotic Events", "severity": "High", "trigger_condition": "Any use of the medication", "message": "STOP: Rofecoxib has been withdrawn from the market worldwide due to an unacceptable increased risk of severe cardiovascular thrombotic events, including myocardial infarction and stroke."}]', 'Use with extreme caution in patients with hepatic dysfunction, a history of ulcer disease, or gastrointestinal bleeding. Caution is advised in elderly or debilitated patients. Prolonged treatment, smoking, and alcoholism significantly increase the risk of gastrointestinal bleeding. Monitor closely in patients with ischemic heart disease, hypertension, or heart failure.', '- **Osteoarthritis:** For the relief of signs and symptoms of osteoarthritis.
INSERT INTO "drug_generic" VALUES(1485, 'Oxymetazoline Hydrochloride topical', 'Oxymetazoline Hydrochloride', 'D11AX27', 0, 0, 0, 0, 0, 1, 0, 0, '[]', 'Alpha-adrenergic agonists may impact blood pressure. Use with caution in patients with severe or uncontrolled cardiovascular disease, orthostatic hypotension, or uncontrolled hypertension/hypotension. Advise patients to seek medical care if their cardiovascular condition worsens. Use with caution in patients with cerebral or coronary insufficiency, Raynaud’s phenomenon, thromboangiitis obliterans, scleroderma, or Sjögren’s syndrome. Advise patients to seek immediate medical care if signs and symptoms of acute narrow-angle glaucoma develop.', '- **Rosacea:** Indicated for the topical treatment of persistent facial erythema (redness) associated with rosacea in adults.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to oxymetazoline or any of the excipients in the formulation due to the risk of allergic reactions.', '- **Frequent:** Application-site dermatitis, application-site erythema, application-site pain, application-site pruritus.
INSERT INTO "drug_generic" VALUES(1486, 'Lidocaine (lignocaine) Hydrochloride 2%, 10% Topical', 'Lidocaine Hydrochloride Topical', 'N01BB02', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Systemic Toxicity Risk", "severity": "High", "trigger_condition": "Application to large surface areas, mucous membranes, or prolonged use", "message": "STOP: Excessive application or use on denuded skin/mucous membranes can lead to rapid systemic absorption and life-threatening Local Anesthetic Systemic Toxicity (LAST), including seizures and cardiac arrest."}]', '- **Hepatic Impairment:** Use with caution; lidocaine is metabolized by the liver, and severe impairment can lead to toxic accumulation if systemically absorbed.
INSERT INTO "drug_generic" VALUES(1487, 'Prochlorperazine Mesilate', 'Prochlorperazine Mesylate', 'N05AB04', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Severe Tissue Damage and EPS", "severity": "High", "trigger_condition": "Intravenous administration or use in pediatrics", "message": "STOP: Intravenous administration can cause severe hypotension and tissue necrosis; deep IM is preferred. Do not use in children under 2 years or under 9 kg due to severe extrapyramidal symptoms and respiratory depression."}]', '- **Administration Route:** Avoid subcutaneous administration due to severe local irritation and tissue necrosis. IV administration should be slow and cautious due to the risk of severe hypotension.
INSERT INTO "drug_generic" VALUES(1488, 'Calamine 15% + Zinc Oxide 5%', 'Calamine and Zinc Oxide', 'D02AB', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**External Use Only:** This product is strictly for topical application. Do not ingest.
INSERT INTO "drug_generic" VALUES(1489, 'Mix of 5 Trace Elements', 'Pediatric Trace Elements Injection (Multiple)', 'B05XA31', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Dilution Requirement", "severity": "High", "trigger_condition": "Preparation for administration", "message": "STOP: Must be diluted prior to administration. Do not inject directly into a peripheral or central vein undiluted, as it can cause severe phlebitis and toxicity."}]', '**Hepatic Impairment / Cholestasis:** Copper and manganese are primarily excreted in the bile. In neonates and infants with cholestasis (common in prolonged PN), these elements can accumulate, leading to neurotoxicity (manganese) or hepatotoxicity (copper). Monitor blood levels and consider withholding if levels are elevated.
INSERT INTO "drug_generic" VALUES(1490, 'Salmeterol', 'Salmeterol', 'R03AC12', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Asthma-Related Death Risk", "severity": "High", "trigger_condition": "Use as monotherapy in asthma", "message": "STOP: Long-acting beta2-adrenergic agonists (LABAs) increase the risk of asthma-related death. Salmeterol must NEVER be used as monotherapy for asthma; it must only be used in conjunction with an inhaled corticosteroid (ICS)."}]', 'Do not use for the relief of acute bronchospasm (status asthmaticus); a short-acting beta2-agonist must be used for acute symptoms. Use with caution in patients with cardiovascular disease (arrhythmias, hypertension), seizure disorders, hyperthyroidism, diabetes mellitus, and hypokalemia. Monitor pulmonary function, blood pressure, heart rate, and potassium levels.', '- **Chronic Asthma:** Maintenance treatment of asthma and prevention of bronchospasm (must be used concomitantly with an inhaled corticosteroid).
INSERT INTO "drug_generic" VALUES(1491, 'Naloxone nasal prep', 'Naloxone Intranasal', 'V03AB15', 0, 1, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Recurrent Respiratory Depression", "severity": "High", "trigger_condition": "Overdose with long-acting opioids (e.g., methadone, extended-release formulations)", "message": "STOP: The duration of action of most opioids exceeds that of naloxone. Patients may relapse into respiratory depression. Continuous monitoring and repeated doses are often required. Seek immediate emergency medical assistance."}]', '**Recurrent Respiratory and CNS Depression:** The duration of action of naloxone is shorter than that of most opioids. Patients must be monitored closely, and repeated doses may be necessary. Always seek emergency medical assistance immediately after the first dose.
INSERT INTO "drug_generic" VALUES(1492, 'Fosphenytoin Sodium', 'Fosphenytoin', 'N03AB05', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Cardiovascular Risk with Rapid Infusion", "severity": "High", "trigger_condition": "Intravenous infusion exceeding recommended rates", "message": "STOP: Severe cardiovascular reactions, including fatal arrhythmias and hypotension, can occur with rapid IV administration. Do not exceed 150 mg PE/min in adults or 2-3 mg PE/kg/min in children. Continuous ECG and BP monitoring are required."}]', '**Cardiovascular Risk:** Rapid IV administration increases the risk of severe hypotension and cardiac arrhythmias. Continuous monitoring of ECG, blood pressure, and respiratory function is mandatory during and for at least 10-20 minutes after the infusion.
INSERT INTO "drug_generic" VALUES(1493, 'Clonidine Hydrochloride', 'Clonidine', 'C02AC01', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Rebound Hypertension", "severity": "High", "trigger_condition": "Abrupt discontinuation of therapy", "message": "WARNING: Abrupt withdrawal of clonidine can result in severe rebound hypertension, tachycardia, agitation, and tremor. Always taper the dose gradually over 2 to 4 days to discontinue."}]', '**Hypotension and Bradycardia:** Can cause significant hypotension, orthostatic hypotension, bradycardia, and syncope. Titrate slowly and monitor vital signs frequently, especially in patients with cardiovascular disease, conduction abnormalities, or volume depletion.
INSERT INTO "drug_generic" VALUES(1494, 'Imipramine Hydrochloride', 'Imipramine', 'N06AA02', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Suicidal Thoughts and Behaviors", "severity": "High", "trigger_condition": "Children, adolescents, and young adults (<24 years) initiating therapy", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', 'Use with extreme caution in patients with cardiovascular disease, including a history of myocardial infarction, stroke, tachycardia, or conduction abnormalities, as imipramine can induce arrhythmias and orthostatic hypotension. Caution is required in patients with a history of seizure disorders, as tricyclic antidepressants (TCAs) lower the seizure threshold. Use cautiously in patients with benign prostatic hyperplasia (BPH), urinary retention, or narrow-angle glaucoma due to potent anticholinergic effects. Monitor for the emergence of bipolar mania or hypomania in patients with depressive disorders. Avoid abrupt discontinuation to prevent withdrawal symptoms (nausea, headache, malaise). Monitor blood glucose levels in diabetic patients, as TCAs can alter glycemic control. Elderly patients are highly susceptible to anticholinergic side effects, orthostatic hypotension, and sedation; initiate at lower doses.', '- **Major Depressive Disorder:** Treatment of symptoms of depressive illness.
INSERT INTO "drug_generic" VALUES(1495, 'Perindopril + Indapamide', 'Perindopril and Indapamide', 'C09BA04', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: When pregnancy is detected, discontinue this medication as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}, {"alert_type": "Angioedema", "severity": "High", "trigger_condition": "Swelling of face, lips, tongue, or airway", "message": "STOP: Discontinue immediately if angioedema occurs. Airway compromise can be fatal. Administer epinephrine if indicated."}]', 'Regular monitoring of renal function (serum creatinine) and plasma potassium levels is mandatory, especially in patients with pre-existing renal impairment, heart failure, or those taking potassium-sparing agents. Monitor blood glucose levels closely in diabetic patients, as thiazide-like diuretics can impair glucose tolerance and hypokalemia can exacerbate this effect. Immunosuppressed patients are at an increased risk of neutropenia or agranulocytosis; monitor complete blood counts periodically. Treatment must be discontinued immediately if angioneurotic edema of the face, extremities, lips, tongue, glottis, and/or larynx occurs. Correct volume or salt depletion before initiating therapy to prevent severe symptomatic hypotension.', '- **Essential Hypertension:** Indicated for the treatment of essential hypertension in patients whose blood pressure is not adequately controlled on perindopril or indapamide monotherapy.', '- **Hypersensitivity:** Contraindicated in patients with known hypersensitivity to perindopril, indapamide, sulfonamides, or any ACE inhibitor.
INSERT INTO "drug_generic" VALUES(1496, 'Cholic acid', 'Cholic acid', 'A05AA03', 0, 0, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Concurrent elevations of GGT and ALT or worsening liver function", "message": "STOP: Exacerbation of liver impairment can occur. Monitor liver function closely. Discontinue if clinical or laboratory indicators of worsening liver function or cholestasis develop."}]', '**Hepatotoxicity:** Monitor liver function and discontinue at any time there are clinical or laboratory indicators of worsening liver function or cholestasis. Concurrent elevations of GGT and ALT may indicate overdose; discontinue therapy if this occurs. In patients with cirrhosis, cases of severe hepatotoxicity have been observed; exacerbation of liver impairment in these patients cannot be ruled out.
INSERT INTO "drug_generic" VALUES(1497, 'Diphenhydramine topical', 'Diphenhydramine', 'D04AA32', 0, 0, 1, 0, 0, 1, 1, 0, '[{"alert_type": "Systemic Toxicity Risk", "severity": "High", "trigger_condition": "Application to large areas or concurrent oral use", "message": "STOP: Do not use topical diphenhydramine on large areas of the body, on blistered/broken skin (e.g., chickenpox, measles), or concurrently with any other product containing diphenhydramine (including oral formulations). Systemic absorption can cause severe anticholinergic toxicity and toxic encephalopathy, especially in children."}]', '**Systemic Absorption:** Application to large surface areas, denuded skin, or blistering conditions (like chickenpox or measles) significantly increases systemic absorption, leading to anticholinergic toxicity (hallucinations, delirium, seizures). Use on chickenpox or measles only if strictly directed by a physician.
INSERT INTO "drug_generic" VALUES(1498, 'Ethanol + Isopropyl alcohol', 'Ethanol + Isopropyl alcohol', 'D08AX', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Flammability Hazard", "severity": "High", "trigger_condition": "Exposure to open flames or high heat", "message": "STOP: This product is highly flammable. Keep away from fire, sparks, and heated surfaces. Allow to dry completely on the skin before using any heat-generating medical devices."}]', '**Flammability:** The solution is highly flammable. Keep away from heat, sparks, open flames, and combustible materials.
INSERT INTO "drug_generic" VALUES(1499, 'Dehydroepiandrosterone', 'Dehydroepiandrosterone (DHEA)', 'G03XX', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hormone-Sensitive Conditions", "severity": "High", "trigger_condition": "Patients with a history of hormone-sensitive cancers", "message": "STOP: DHEA is a precursor to estrogens and androgens. It is contraindicated in patients with a known or suspected history of breast, prostate, ovarian, or uterine cancers."}]', '**Cardiovascular Disease:** Individuals with hypertension, heart disease, or low HDL (''good'') cholesterol should avoid this product or use it only under strict medical supervision.
INSERT INTO "drug_generic" VALUES(1500, 'Oxymetazoline Hydrochloride .025 % Nasal prep', 'Oxymetazoline Hydrochloride 0.025% Nasal Drops/Spray', 'R01AA05', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Rebound Congestion (Rhinitis Medicamentosa)", "severity": "Moderate", "trigger_condition": "Use exceeding 3 to 5 consecutive days", "message": "Prolonged use beyond 3-5 days can cause severe rebound nasal congestion and mucosal damage. Limit therapy duration strictly."}]', '**Rebound Congestion:** Prolonged or excessive use (greater than 3 to 5 days) may lead to rhinitis medicamentosa (rebound congestion), characterized by chronic redness, swelling, and rhinitis.
INSERT INTO "drug_generic" VALUES(1501, 'Petrolatum + Mineral oil topical', 'Petrolatum and Mineral Oil', 'D02AC', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**External Use Only:** For external use only. Avoid contact with eyes.
INSERT INTO "drug_generic" VALUES(1502, 'Carbetocin', 'Carbetocin', 'H01BB03', 0, 1, 0, 1, 1, 0, 0, 0, '[{"alert_type": "Administration Timing", "severity": "High", "trigger_condition": "Administration before delivery of the infant", "message": "STOP: Carbetocin must NOT be administered before delivery of the infant. It is strictly indicated for postpartum use to prevent uterine atony."}]', '**Cardiovascular Monitoring:** Monitor blood pressure closely, especially in patients with eclampsia or preeclampsia, for up to 8 hours postpartum. Carbetocin can cause transient hypotension or hypertension.
INSERT INTO "drug_generic" VALUES(1503, 'Meropenem + Vaborbactam', 'Meropenem/Vaborbactam', 'J01DH52', 1, 0, 1, 0, 1, 1, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe hypersensitivity to carbapenems, penicillins, or cephalosporins", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history to beta-lactams before prescribing."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. Inquire carefully about previous hypersensitivity reactions to penicillins, cephalosporins, other beta-lactams, and other allergens. If an allergic reaction occurs, discontinue immediately and institute appropriate emergency therapy.
INSERT INTO "drug_generic" VALUES(1504, 'Ertugliflozin', 'Ertugliflozin', 'A10BK04', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Diabetic Ketoacidosis and Fournier Gangrene", "severity": "High", "trigger_condition": "Symptoms of severe metabolic acidosis or perineal pain/swelling", "message": "STOP: Fatal cases of diabetic ketoacidosis (DKA) have occurred, sometimes with normal or only mildly elevated blood glucose. Discontinue immediately if DKA is suspected. Necrotizing fasciitis of the perineum (Fournier gangrene) is a rare but life-threatening complication; discontinue and initiate broad-spectrum antibiotics and surgical debridement if suspected."}]', 'Ertugliflozin causes intravascular volume contraction; symptomatic hypotension may occur after initiating therapy, particularly in patients with renal impairment, the elderly, those with low systolic blood pressure, or patients on diuretics. Assess and correct volume status before initiating. Ketoacidosis, a serious life-threatening condition requiring urgent hospitalization, has been reported; consider predisposing factors (pancreatic insulin deficiency, caloric restriction, alcohol abuse) before initiating. Temporarily discontinue ertugliflozin in clinical situations known to predispose to ketoacidosis (e.g., prolonged fasting due to acute illness or surgery). Renal impairment may occur due to volume contraction; consider factors predisposing to acute kidney injury (hypovolemia, CHF, concomitant NSAIDs/ACE inhibitors/ARBs). Monitor for signs of acute kidney injury and discontinue promptly if evident. Increases the risk of genital mycotic infections (especially in uncircumcised males or those with a history of infections) and serious urinary tract infections, including life-threatening urosepsis and pyelonephritis.', '- Adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus.
INSERT INTO "drug_generic" VALUES(1505, 'Ofloxacin', 'Ofloxacin', 'J01MA01', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Disabling Adverse Reactions", "severity": "High", "trigger_condition": "Any patient prescribed systemic fluoroquinolones", "message": "STOP: Fluoroquinolones are associated with disabling and potentially irreversible serious adverse reactions, including tendinitis, tendon rupture, peripheral neuropathy, and central nervous system effects. Discontinue immediately at the first sign of tendon pain, neuropathy, or CNS toxicity."}]', 'Use with extreme caution in patients with known or suspected CNS disorders (e.g., severe cerebral arteriosclerosis, epilepsy) due to the risk of seizures. Maintain adequate hydration to prevent crystalluria. Avoid excessive exposure to sunlight or artificial UV light due to the risk of severe phototoxicity. Caution in patients with myasthenia gravis, as fluoroquinolones can exacerbate muscle weakness. Monitor for signs of QT prolongation, especially in patients with hypokalemia or those taking antiarrhythmics. Risk of Clostridioides difficile-associated diarrhea (CDAD).', '- **Lower Respiratory Tract Infections:** Acute bacterial exacerbation of chronic bronchitis, community-acquired pneumonia.
INSERT INTO "drug_generic" VALUES(1506, 'Diphtheria Toxoid 30 IU + Tetanus Toxoid 40 IU', 'Diphtheria and Tetanus Toxoids Adsorbed (DT)', 'J07AM51', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "History of severe allergic reaction to previous dose", "message": "STOP: Contraindicated if the patient has a history of severe allergic reaction (e.g., anaphylaxis) to any component of the vaccine."}]', '**Febrile Illness:** Postpone vaccination in patients with acute severe febrile illness.
INSERT INTO "drug_generic" VALUES(1507, 'Pilocarpine Hydrochloride', 'Pilocarpine', 'N07AX01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Pulmonary Risk", "severity": "High", "trigger_condition": "Patients with significant cardiovascular disease or uncontrolled asthma", "message": "STOP: Pilocarpine is a systemic cholinergic agonist. It can cause severe bradycardia, hypotension, and bronchoconstriction. Use with extreme caution in patients with cardiovascular disease or asthma."}]', '**Cardiovascular Disease:** Use with caution in patients with significant cardiovascular disease. Pilocarpine can cause transient changes in hemodynamics or rhythm (e.g., bradycardia, hypotension).
INSERT INTO "drug_generic" VALUES(1508, 'Ketorolac Tromethamine 0.5% Eye prep', 'Ketorolac Ophthalmic', 'S01BC05', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Corneal Toxicity and Delayed Healing", "severity": "Medium", "trigger_condition": "Prolonged use or use in patients with complicated ocular surgeries", "message": "WARNING: Topical NSAIDs can slow or delay healing. Prolonged use may result in corneal epithelial breakdown, thinning, erosion, ulceration, or perforation. Discontinue immediately if corneal epithelial breakdown occurs."}]', '**Bleeding Tendencies:** With some NSAIDs, there exists the potential for increased bleeding time due to interference with thrombocyte aggregation. Use with caution in patients with known bleeding tendencies or who are receiving other medications that may prolong bleeding time.
INSERT INTO "drug_generic" VALUES(1509, 'Acemetacin', 'Acemetacin', 'M01AB11', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Gastrointestinal and Cardiovascular Risk", "severity": "High", "trigger_condition": "Patient with active peptic ulcer or severe heart failure", "message": "STOP: NSAIDs cause an increased risk of serious GI bleeding and cardiovascular thrombotic events. Contraindicated in active peptic ulcer disease and severe heart failure."}]', '**Gastrointestinal Effects:** High risk of GI bleeding, ulceration, and perforation. Elderly patients are at greater risk. Monitor for signs of GI distress.
INSERT INTO "drug_generic" VALUES(1510, 'Chlorpheniramine + Dextromethorphan', 'Chlorpheniramine + Dextromethorphan', 'R05DA20', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Serotonin Syndrome Risk", "severity": "High", "trigger_condition": "Concomitant use of MAOIs, SSRIs, or other serotonergic agents", "message": "STOP: Dextromethorphan can precipitate severe and potentially fatal serotonin syndrome when used with MAOIs or other serotonergic drugs. Verify medication history before prescribing."}]', 'Use with caution in children younger than 6 years; safety and efficacy are not fully established, and paradoxical excitability may occur.
INSERT INTO "drug_generic" VALUES(1511, 'Butamirate Citrate', 'Butamirate', 'R05DB13', 0, 0, 0, 0, 0, 0, 1, 0, '[]', '**Concurrent Expectorant Use:** Avoid concomitant administration with expectorants. Butamirate suppresses the cough reflex; using it with an expectorant may lead to the retention of mucus in the respiratory tract, increasing the risk of bronchospasm and secondary airway infections.
INSERT INTO "drug_generic" VALUES(1512, 'Hepatitis b immunoglobulin', 'Hepatitis B Immune Globulin (Human)', 'J06BB04', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe systemic reactions to human immunoglobulins", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, can occur, especially in patients with IgA deficiency and anti-IgA antibodies. Have epinephrine available during administration."}]', '**Thrombocytopenia and Coagulation Disorders:** Intramuscular injections can cause bleeding or hematoma formation; administer with extreme caution and consider alternative routes if available.
INSERT INTO "drug_generic" VALUES(1513, 'Chlorhexidine Gluconate 0.25% + Lidocaine Hydrochloride', 'Chlorhexidine Gluconate and Lidocaine Hydrochloride', 'A01AB03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Hypersensitivity to chlorhexidine or lidocaine", "message": "STOP: Rare but severe and potentially fatal allergic reactions (anaphylaxis) can occur. Discontinue immediately and seek emergency medical care if symptoms of an allergic reaction develop."}]', '**Numbness and Choking Hazard:** Lidocaine causes local anesthesia. Numbness of the tongue and throat can impair swallowing and increase the risk of aspiration. Avoid eating or drinking hot liquids immediately after use.
INSERT INTO "drug_generic" VALUES(1514, 'Yellow fever Virus (Live attenuated) Vaccine', 'Yellow Fever Vaccine Live', 'J07PE01', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of egg or chicken protein allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Contraindicated in patients with egg allergies."}, {"alert_type": "Neurologic Toxicity", "severity": "High", "trigger_condition": "Infants <6 months of age", "message": "STOP: Contraindicated in infants under 6 months due to a high risk of vaccine-associated encephalitis."}]', 'Exercise extreme caution in elderly patients (≥65 years) due to a significantly increased risk of Yellow Fever Vaccine-Associated Viscerotropic Disease (YEL-AVD) and Neurologic Disease (YEL-AND). Monitor all patients for adverse events 10-30 days post-vaccination. Use with caution in asymptomatic HIV patients with preserved immune function; monitor closely. Avoid use in patients who have received hematopoietic stem cell transplants within the past 24 months. Ensure epinephrine and resuscitation equipment are immediately available to manage potential anaphylaxis.', '- **Prophylaxis of Yellow Fever:** Indicated for active immunization against yellow fever in persons 9 months of age and older traveling to or living in endemic areas.
INSERT INTO "drug_generic" VALUES(1515, 'Ibrutinib', 'Ibrutinib', 'L01EA01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Hemorrhage", "severity": "High", "trigger_condition": "Concomitant use of antiplatelets/anticoagulants or upcoming surgery", "message": "STOP: Fatal bleeding events have occurred. Monitor for bleeding. Consider withholding ibrutinib for 3 to 7 days pre- and post-surgery depending on the risk of bleeding."}]', '**Hemorrhage:** Major hemorrhage (including fatal events) has occurred. Monitor for signs of bleeding. Use caution with concomitant antiplatelet or anticoagulant therapy.
INSERT INTO "drug_generic" VALUES(1516, 'Benzonatate', 'Benzonatate', 'R05DB01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Choking and Anesthesia Risk", "severity": "High", "trigger_condition": "Chewing or sucking the capsule", "message": "STOP: Capsules must be swallowed whole. Chewing or sucking the capsule can cause rapid release of the drug, leading to local anesthesia of the mouth and throat, choking, bronchospasm, and cardiovascular collapse."}]', '**Administration Hazard:** Capsules must be swallowed whole. Sucking or chewing the capsule can cause local anesthesia of the oropharynx, leading to choking, severe hypersensitivity reactions (bronchospasm, laryngospasm), and cardiovascular collapse.
INSERT INTO "drug_generic" VALUES(1517, 'Nifedipine', 'Nifedipine', 'C08CA05', 0, 0, 1, 1, 0, 0, 0, 1, '[]', 'Use with caution in patients with hypotension, poor cardiac reserve, or heart failure, as nifedipine can exacerbate these conditions. Avoid abrupt withdrawal to prevent rebound angina or severe hypertension. Extended-release tablets should be used with caution in patients with severe gastrointestinal narrowing, as obstructive symptoms or bezoars may occur. Caution is advised in the elderly and in patients with hepatic impairment, where dose reductions may be necessary. Monitor blood pressure and heart rate closely during initiation and titration.', '- **Hypertension:** Management of essential and renal hypertension. Extended-release formulations are preferred for chronic management.
INSERT INTO "drug_generic" VALUES(1518, 'L-arginie + Proanthocyanidin + Folic Acid + Zinc', 'L-Arginine, Proanthocyanidin, Folic Acid, and Zinc', 'A11JC', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Surgical Alert", "severity": "Moderate", "trigger_condition": "Pre-operative period", "message": "Discontinue use at least 2 weeks prior to elective surgery due to potential blood pressure fluctuations and vasodilatory effects from L-Arginine."}]', '**Hypotension:** L-Arginine acts as a vasodilator. Use with caution in patients with low blood pressure or those taking antihypertensive medications, as it may cause additive hypotension.
INSERT INTO "drug_generic" VALUES(1519, 'Tolperisone Hydrochloride', 'Tolperisone', 'M03BX04', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Patient history of drug allergies or female gender (higher risk)", "message": "Severe hypersensitivity reactions, including anaphylaxis, have been reported. Discontinue immediately if symptoms such as flushing, rash, severe itching, or dyspnea occur."}]', 'Use with caution in patients with a history of hypersensitivity to other medications, particularly lidocaine, due to potential cross-reactivity. In children, the prescribed dose and duration of treatment must be closely monitored. Caution should be exercised in patients with renal or hepatic impairment. May cause dizziness or somnolence; advise patients to use caution when driving or operating machinery.', '- **Spasticity and Neurological Disorders:** Treatment of increased tone of skeletal muscles due to organic neurological disorders (e.g., injury of the pyramidal tract, multiple sclerosis, myelopathy, encephalomyelitis).
INSERT INTO "drug_generic" VALUES(1520, 'Sodium Hyaluronate', 'Sodium Hyaluronate', 'M09AX01', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '- **Hypersensitivity Risk:** Use with extreme caution in patients who are allergic to avian proteins, feathers, and egg products, as some formulations are derived from avian sources.
INSERT INTO "drug_generic" VALUES(1521, 'Levocarnitine', 'Levocarnitine', 'A16AA01', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Renal Impairment (Oral Administration):** Chronic administration of high doses of oral levocarnitine in patients with severely compromised renal function or end-stage renal disease (ESRD) on dialysis may result in the accumulation of potentially toxic metabolites (trimethylamine [TMA] and trimethylamine-N-oxide[TMAO]). Intravenous administration is preferred in this population.
INSERT INTO "drug_generic" VALUES(1522, 'Moxifloxacin', 'Moxifloxacin', 'J01MA14', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Adverse Reactions", "severity": "High", "trigger_condition": "Patient experiencing tendon pain, neuropathy, or CNS symptoms", "message": "WARNING: Fluoroquinolones are associated with disabling and potentially irreversible serious adverse reactions, including tendinitis, tendon rupture, peripheral neuropathy, and CNS effects. Discontinue immediately if these occur."}]', '**Tendon Rupture:** Increased risk of tendinitis and tendon rupture, especially in patients >60 years, those taking corticosteroids, and kidney/heart/lung transplant recipients.
INSERT INTO "drug_generic" VALUES(1523, 'Rhubarb 5%  +  Salicylic Acid 1%', 'Rhubarb Extract / Salicylic Acid', 'A01AD11', 0, 0, 0, 0, 0, 1, 1, 0, '[]', 'For topical oral mucosal use only. Avoid swallowing large amounts. Each bottle of oral solution should be used by only one person to prevent cross-contamination. Discontinue use if severe irritation or hypersensitivity occurs. Temporary discoloration of teeth or oral mucosa may occur. Use with caution in patients with a history of salicylate hypersensitivity.', '- **Oral Inflammatory Conditions:** Relief of pain and irritation associated with gingivitis, aphthous ulcers (canker sores), gum sores, and periodontitis.
INSERT INTO "drug_generic" VALUES(1524, 'Coagulation Factor IX', 'Coagulation Factor IX (Recombinant)', 'B02BD04', 0, 1, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Neutralizing Antibodies (Inhibitors)", "severity": "High", "trigger_condition": "Lack of clinical response to treatment", "message": "STOP: Development of neutralizing antibodies (inhibitors) to Factor IX may occur. If expected plasma levels are not attained or bleeding is not controlled, perform an assay to measure Factor IX inhibitor concentration."}, {"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "High doses or continuous infusion", "message": "Thromboembolism (e.g., DVT, PE, MI) has occurred with Factor IX use. Monitor for signs of thrombosis, especially in patients with risk factors."}]', '**Hypersensitivity:** Anaphylaxis has occurred. Discontinue immediately if symptoms occur. Patients may also develop hypersensitivity to hamster (CHO) protein, present in trace amounts in recombinant products.
INSERT INTO "drug_generic" VALUES(1525, 'Etonogestrel', 'Etonogestrel', 'G02BA03', 0, 0, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "Patient with a history of deep vein thrombosis (DVT), pulmonary embolism (PE), or severe arterial disease", "message": "STOP: Etonogestrel is contraindicated in patients with active or a history of severe thromboembolic disorders."}]', '**Cardiovascular and Metabolic Risks:** Use with caution in patients with a history of heart disease, hypertension, or disturbances of lipid metabolism.
INSERT INTO "drug_generic" VALUES(1526, 'Trandolapril', 'Trandolapril', 'C09AA10', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Fetal Toxicity:** Use of drugs that act on the renin-angiotensin system during the second and third trimesters of pregnancy reduces fetal renal function and increases fetal and neonatal morbidity and death. Discontinue immediately upon detection of pregnancy.
INSERT INTO "drug_generic" VALUES(1527, 'Simvastatin + Ezetimibe', 'Ezetimibe and Simvastatin', 'C10BA02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Concomitant use with strong CYP3A4 inhibitors or high doses (80 mg simvastatin)", "message": "STOP: High risk of severe myopathy and rhabdomyolysis leading to acute renal failure. Concomitant use with strong CYP3A4 inhibitors is strictly contraindicated."}]', '**Myopathy/Rhabdomyolysis:** Risk increases with higher doses (especially the 80 mg simvastatin dose), advanced age (>65 years), female gender, uncontrolled hypothyroidism, and renal impairment. Temporarily withhold therapy in patients experiencing an acute, serious condition suggestive of myopathy or predisposing to the development of renal failure secondary to rhabdomyolysis (e.g., sepsis, hypotension, major surgery, trauma, severe metabolic/endocrine/electrolyte disorders, or uncontrolled seizures).
INSERT INTO "drug_generic" VALUES(1528, 'Calcium Acetate', 'Calcium Acetate', 'V03AE04', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "High", "trigger_condition": "Concurrent use of other calcium supplements or inadequate monitoring", "message": "STOP: Patients with end-stage renal disease may develop severe hypercalcemia when treated with calcium acetate. Avoid concurrent use of other calcium supplements or calcium-based antacids. Monitor serum calcium twice weekly during dose titration."}]', '**Hypercalcemia:** Excessive calcium absorption can lead to hypercalcemia, which may exacerbate vascular and soft tissue calcification in patients with chronic kidney disease. Monitor serum calcium and phosphorus levels closely.
INSERT INTO "drug_generic" VALUES(1529, 'Doxylamine + Dextromethorphan', 'Doxylamine + Dextromethorphan', 'R05DA20', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "CNS Depression and Serotonin Syndrome", "severity": "Moderate", "trigger_condition": "Concurrent use of CNS depressants or serotonergic drugs", "message": "May cause significant CNS depression. Concurrent use with MAOIs or serotonergic drugs can precipitate fatal serotonin syndrome."}]', '**CNS Depression:** Doxylamine may cause significant drowsiness. Caution when used concomitantly with another CNS depressant. Advise patients against driving or operating heavy machinery.
INSERT INTO "drug_generic" VALUES(1530, 'Anti-human T-lymphocyte (Antithymocyte) immunoglobulin (rabbits)', 'Antithymocyte Globulin (Rabbit)', 'L04AA04', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Cytokine Release Syndrome (CRS)", "severity": "High", "trigger_condition": "During or shortly after intravenous infusion", "message": "STOP: Severe, potentially fatal anaphylaxis and CRS can occur. Administer under strict medical supervision. Premedicate appropriately. If anaphylaxis occurs, stop infusion immediately and initiate emergency resuscitation."}]', '**Overimmunosuppression:** Can lead to severe, life-threatening infections (bacterial, fungal, viral, protozoal) and reactivation of latent infections (e.g., CMV, EBV). Adjust maintenance immunosuppression accordingly.
INSERT INTO "drug_generic" VALUES(1531, 'Budesonide inhaled', 'Budesonide', 'R03BA02', 0, 0, 1, 1, 0, 0, 1, 1, '[{"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediately following inhalation", "message": "WARNING: Inhaled budesonide can produce paradoxical bronchospasm, which may be life-threatening. If this occurs, treat immediately with a short-acting inhaled bronchodilator, discontinue budesonide, and institute alternative therapy."}, {"alert_type": "Adrenal Insufficiency", "severity": "High", "trigger_condition": "Transferring from systemic corticosteroids to inhaled corticosteroids", "message": "WARNING: Deaths due to adrenal insufficiency have occurred during and after transfer from systemic corticosteroids. Taper systemic steroids gradually and monitor HPA axis function closely."}]', 'Budesonide is not a bronchodilator and is not indicated for rapid relief of acute bronchospasm or status asthmaticus.
INSERT INTO "drug_generic" VALUES(1532, 'Framycetin sulfate (Dressing)', 'Framycetin sulfate', 'D09AA01', 1, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Systemic Toxicity", "severity": "High", "trigger_condition": "Application to large burn areas or open wounds", "message": "STOP: Application to large areas of denuded skin or extensive burns can lead to significant systemic absorption, resulting in irreversible ototoxicity and nephrotoxicity."}]', '**Systemic Absorption:** Caution is advised when applying to large areas of broken skin, extensive burns, or open wounds, as systemic absorption of aminoglycosides can occur, leading to ototoxicity (auditory and vestibular) and nephrotoxicity.
INSERT INTO "drug_generic" VALUES(1533, 'Irbesartan', 'Irbesartan', 'C09CA04', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected during therapy", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Hypotension in Volume- or Salt-Depleted Patients:** Symptomatic hypotension may occur after initiation of therapy in patients with an activated renin-angiotensin system, such as those who are volume- or salt-depleted (e.g., those treated with high doses of diuretics). Correct volume depletion prior to administration or initiate with a lower dose.
INSERT INTO "drug_generic" VALUES(1534, 'Metronidazole + Miconazole Nitrate Vag prep', 'Metronidazole and Miconazole', 'G01AF20', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Disulfiram-like Reaction", "severity": "High", "trigger_condition": "Concurrent alcohol consumption", "message": "STOP: Even with vaginal administration, systemic absorption of metronidazole occurs. Concurrent use of alcohol can cause a severe disulfiram-like reaction (flushing, vomiting, tachycardia). Avoid alcohol during and for 3 days after therapy."}]', 'For intravaginal use only; not for ophthalmic, dermal, or oral use. Discontinue treatment if severe local irritation, sensitization, or an allergic reaction occurs. Systemic absorption of metronidazole occurs with vaginal administration; therefore, precautions applicable to oral metronidazole (e.g., caution in severe hepatic impairment, CNS diseases, or history of blood dyscrasias) should be considered. May weaken latex condoms and diaphragms; advise alternative methods of contraception during treatment and for 72 hours after.', '- Treatment of vaginal candidiasis.
INSERT INTO "drug_generic" VALUES(1535, 'Insulin (Human) Regular + Insulin (Human) Isophane (pre mixed)', 'Insulin Regular and Insulin Isophane (NPH)', 'A10AD01', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypoglycemia", "severity": "High", "trigger_condition": "Missed meals, excessive exercise, or incorrect dosing", "message": "STOP: Severe, life-threatening hypoglycemia can occur. Ensure the patient understands proper injection technique, meal timing, and signs of hypoglycemia. Never administer intravenously or intramuscularly."}]', 'Monitor blood glucose frequently. Insulin requirements may change significantly during stress, illness, fever, trauma, infection, or surgery (requirements usually increase), or with diarrhea, nausea/vomiting, malabsorption, or hypothyroidism (requirements usually decrease). Hypokalemia may occur, especially when administered with potassium-lowering drugs; monitor serum potassium in at-risk patients. Use with caution in patients with renal or hepatic impairment, as insulin requirements may be reduced. Monitor for injection site reactions, lipoatrophy, or lipohypertrophy; rotate injection sites to prevent these. Do not administer this suspension intravenously or intramuscularly.', '- **Diabetes Mellitus:** Treatment of patients with diabetes mellitus (Type 1 and Type 2) who require insulin for the maintenance of glucose homeostasis.', '- **Hypoglycemia:** Contraindicated during episodes of hypoglycemia.
INSERT INTO "drug_generic" VALUES(1536, 'Sarilumab', 'Sarilumab', 'L04AC14', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Serious Infections", "severity": "High", "trigger_condition": "Active infection or history of recurrent infections", "message": "STOP: Increased risk of serious and potentially fatal infections (e.g., tuberculosis, bacterial, invasive fungal, viral). Evaluate for active and latent TB prior to initiation. Do not initiate in patients with an active infection."}]', '**Serious Infections:** Increased risk of serious and sometimes fatal infections due to bacterial, mycobacterial, invasive fungal, viral, or other opportunistic pathogens. Evaluate for TB prior to treatment. Monitor closely for signs of infection during and after treatment.
INSERT INTO "drug_generic" VALUES(1537, 'Ethinylestradiol + Ferrous Fumarate + Norgestrel', 'Norgestrel and Ethinyl Estradiol with Ferrous Fumarate', 'G03AA06', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk in Smokers", "severity": "High", "trigger_condition": "Patient is >35 years old and smokes cigarettes", "message": "STOP: Cigarette smoking increases the risk of serious cardiovascular events from combination oral contraceptives. This risk increases with age, particularly in women over 35 years of age, and with the number of cigarettes smoked. Contraindicated in women >35 years who smoke."}]', 'Monitor blood pressure; discontinue if clinically significant hypertension occurs. Use with caution in patients with a history of depression, migraine, or conditions exacerbated by fluid retention (e.g., heart failure, renal impairment). May alter glucose tolerance; monitor diabetic patients closely. May cause lipid alterations; use caution in patients with dyslipidemias. Discontinue at least 4 weeks before and 2 weeks after elective surgery associated with an increased risk of thromboembolism. Efficacy may be reduced by severe diarrhea, vomiting, or missed doses, requiring backup contraception. The ferrous fumarate tablets are inert regarding contraception and are included to prevent iron deficiency during withdrawal bleeding.', '- **Oral Contraception:** Prevention of pregnancy in women who elect to use oral contraceptives as a method of contraception.', '- **High Risk of Thromboembolic Diseases:** Contraindicated in patients with a history of or current DVT, PE, cerebrovascular disease, coronary artery disease, thrombogenic valvular or rhythm diseases, or inherited/acquired hypercoagulopathies.
INSERT INTO "drug_generic" VALUES(1538, 'Leflunomide', 'Leflunomide', 'L04AK01', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy or females of reproductive potential not using effective contraception", "message": "STOP: Contraindicated in pregnancy. May cause fetal death or teratogenic effects. Exclude pregnancy before starting. A strict drug elimination procedure (cholestyramine washout) is required if pregnancy is desired."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Pre-existing liver disease or elevated ALT >2x ULN", "message": "STOP: Severe liver injury, including fatal liver failure, has been reported. Contraindicated in severe hepatic impairment. Monitor ALT monthly for the first 6 months, then every 6-8 weeks."}]', '**Hepatotoxicity:** Severe liver injury, including fatal liver failure, has occurred. Monitor ALT at baseline, monthly for 6 months, and every 6-8 weeks thereafter. Avoid in patients with pre-existing liver disease or ALT >2x ULN.
INSERT INTO "drug_generic" VALUES(1539, 'Carbonyl Iron', 'Carbonyl Iron', 'B03AA04', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Fatal Pediatric Poisoning", "severity": "High", "trigger_condition": "Accidental ingestion by children under 6 years", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Iron Overload:** Care should be taken in patients who may develop iron overload, such as those with hemochromatosis, hemolytic anemia, or red cell aplasia. Not for use in patients receiving frequent blood transfusions.
INSERT INTO "drug_generic" VALUES(1540, 'Lapatinib', 'Lapatinib', 'L01EH01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity and Decreased LVEF", "severity": "High", "trigger_condition": "Initiation and continuation of Lapatinib therapy", "message": "STOP: Severe, sometimes fatal, hepatotoxicity has occurred. Monitor liver function tests before initiation and every 4-6 weeks. Lapatinib can also cause a decrease in left ventricular ejection fraction (LVEF); evaluate LVEF prior to and during treatment."}]', '- **Hepatotoxicity:** Severe hepatotoxicity (some fatal) has been observed. Monitor LFTs (transaminases, bilirubin, alkaline phosphatase) at baseline and every 4 to 6 weeks. Discontinue permanently if severe changes occur.
INSERT INTO "drug_generic" VALUES(1541, 'Multivitamin and Multimineral A-Z Syrup preparations', 'Multivitamins and Minerals', 'A11AA03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Iron Toxicity", "severity": "High", "trigger_condition": "Accidental overdose in children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product out of reach of children."}]', '**Accumulation Risk:** Fat-soluble vitamins (A, D, E, K) and certain minerals can accumulate in the body. Do not exceed the recommended daily dose to prevent toxicity.
INSERT INTO "drug_generic" VALUES(1542, 'Rabeprazole + Domperidone', 'Rabeprazole and Domperidone', 'Data not available', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiac Arrhythmia Risk", "severity": "High", "trigger_condition": "Concurrent use with QT-prolonging drugs or in patients with underlying cardiac disease", "message": "STOP: Domperidone is associated with an increased risk of QT prolongation, serious ventricular arrhythmias, and sudden cardiac death. Use the lowest effective dose for the shortest duration."}]', '**Gastric Malignancy:** Symptomatic response to therapy does not preclude the presence of gastric malignancy. Exclude malignancy prior to initiating treatment.
INSERT INTO "drug_generic" VALUES(1543, 'Vonoprazan', 'Vonoprazan', 'A02BC08', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Clostridioides difficile-Associated Diarrhea (CDAD)", "severity": "High", "trigger_condition": "Development of severe, persistent diarrhea during or after treatment", "message": "STOP: Profound acid suppression increases the risk of CDAD. Evaluate for C. difficile if severe diarrhea occurs."}]', '**Gastric Malignancy:** Symptomatic response to vonoprazan does not preclude the presence of gastric malignancy. Evaluate the type of ulcer to rule out malignancy before initiating treatment.
INSERT INTO "drug_generic" VALUES(1544, 'Desogestrel', 'Desogestrel', 'G03AC09', 0, 0, 0, 1, 0, 0, 0, 0, '[{"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "History of deep vein thrombosis, pulmonary embolism, or severe arterial disease", "message": "STOP: Hormonal contraceptives are associated with an increased risk of venous and arterial thromboembolism. Evaluate patient history before prescribing."}]', '**Cardiovascular Risk:** Use with caution in patients with a history of cardiovascular disease, hypertension, or thromboembolism. Discontinue if a thromboembolic event occurs.
INSERT INTO "drug_generic" VALUES(1545, 'Semaglutide for Diabetes', 'Semaglutide', 'A10BJ06', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Thyroid C-Cell Tumors", "severity": "High", "trigger_condition": "Personal or family history of medullary thyroid carcinoma (MTC) or Multiple Endocrine Neoplasia syndrome type 2 (MEN 2)", "message": "STOP: Semaglutide causes thyroid C-cell tumors in rodents. It is contraindicated in patients with a personal or family history of MTC or MEN 2. Counsel patients regarding the potential risk and symptoms of thyroid tumors (e.g., neck mass, dysphagia, dyspnea, persistent hoarseness)."}]', 'Monitor for signs and symptoms of acute pancreatitis (persistent severe abdominal pain, sometimes radiating to the back, with or without vomiting); if suspected, discontinue promptly and do not restart if confirmed. Patients with a history of diabetic retinopathy may experience a temporary worsening of retinopathy complications due to rapid improvement in glucose control; monitor vision closely. Postmarketing reports describe acute kidney injury and worsening of chronic renal failure, sometimes requiring hemodialysis; monitor renal function when initiating or escalating doses, especially in patients reporting severe gastrointestinal reactions (nausea, vomiting, diarrhea) that may lead to volume depletion. Epidemiological studies suggest a potential increased risk of Non-arteritic Anterior Ischemic Optic Neuropathy (NAION); advise patients to seek immediate medical attention if they experience sudden vision loss. Never share semaglutide pens between patients, even if the needle is changed, due to the risk of transmitting blood-borne pathogens.', '- Adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus.
INSERT INTO "drug_generic" VALUES(1546, 'Dimenhydrinate', 'Dimenhydrinate', 'R06AA11', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "CNS Depression", "severity": "Moderate", "trigger_condition": "Concurrent use of alcohol or other CNS depressants", "message": "May cause significant CNS depression, impairing physical and mental abilities. Advise patients against driving or operating heavy machinery."}]', '**CNS Depression:** May impair the ability to drive or operate heavy machinery due to significant sedation.
INSERT INTO "drug_generic" VALUES(1547, 'Nystatin + Chlorhexidine topical', 'Nystatin and Chlorhexidine', 'D01AC20', 1, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Chlorhexidine hypersensitivity", "message": "STOP: Chlorhexidine is known to induce severe hypersensitivity reactions, including generalized allergic reactions and anaphylactic shock. Verify allergy history before prescribing."}]', 'Avoid contact with the eyes, middle ear, and mucous membranes. If accidental contact occurs, rinse thoroughly with water.
INSERT INTO "drug_generic" VALUES(1548, 'Cyclobenzaprine Hydrochloride', 'Cyclobenzaprine', 'M03BX08', 0, 0, 1, 0, 0, 0, 0, 1, '[{"alert_type": "Serotonin Syndrome", "severity": "High", "trigger_condition": "Coadministration with other serotonergic drugs (e.g., SSRIs, SNRIs, TCAs, MAOIs, tramadol)", "message": "WARNING: Potentially life-threatening serotonin syndrome has been reported. Monitor for mental status changes, autonomic instability, and neuromuscular abnormalities. Contraindicated within 14 days of MAOIs."}]', '**CNS Depression:** May cause significant drowsiness, dizziness, and impaired motor function. Avoid alcohol and other CNS depressants. Caution patients against operating heavy machinery or driving.
INSERT INTO "drug_generic" VALUES(1549, 'Calcipotriol topical', 'Calcipotriene', 'D05AX02', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "Medium", "trigger_condition": "Application exceeding maximum recommended weekly dose", "message": "Excessive use can lead to systemic absorption and clinically significant hypercalcemia. Do not exceed the maximum recommended weekly dose (100g for adults)."}]', '**Hypercalcemia:** Systemic absorption can occur, leading to hypercalcemia. Risk increases if the maximum weekly dose is exceeded. Monitor serum calcium if using large amounts; discontinue if hypercalcemia develops until levels normalize.
INSERT INTO "drug_generic" VALUES(1550, 'Enfuvirtide', 'Enfuvirtide', 'J05AX07', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Development of systemic allergic symptoms", "message": "STOP: Systemic hypersensitivity reactions have occurred. Discontinue immediately if signs of hypersensitivity (e.g., rash, fever, nausea, vomiting, chills, rigors, hypotension) develop."}]', '**Injection Site Reactions (ISRs):** Almost all patients (98%) experience local injection site reactions, including pain, erythema, induration, nodules, and cysts. Patients must be instructed on proper injection technique and site rotation to minimize severity.
INSERT INTO "drug_generic" VALUES(1551, 'Human Anti-D Immunoglobulin (Rho(D) immune globulin)', 'Rho(D) Immune Globulin', 'J06BB01', 0, 1, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Intravascular Hemolysis", "severity": "High", "trigger_condition": "Administration for Immune Thrombocytopenic Purpura (ITP) in Rh(D)-positive patients", "message": "STOP: Fatal intravascular hemolysis can occur when used for ITP. Monitor for back pain, shaking chills, fever, and discolored urine. Can lead to ARDS, acute renal failure, and DIC."}]', '**Intravascular Hemolysis in ITP:** Severe and potentially fatal intravascular hemolysis has been reported in Rh(D)-positive patients treated for ITP. Monitor patients in a healthcare setting for at least 8 hours post-administration. Perform confirmatory laboratory tests (e.g., urinalysis, CBC, renal function) if hemolysis is suspected.
INSERT INTO "drug_generic" VALUES(1552, 'Isopropyl myristate', 'Isopropyl myristate', 'P03AX', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Eye Irritation", "severity": "Moderate", "trigger_condition": "Accidental contact with eyes", "message": "Avoid contact with eyes. Keep eyes closed tightly or protect with a towel during application and rinsing. Flush immediately with water if contact occurs."}]', '- **Eye Protection:** Do not get the product in the eyes. Keep eyes closed until the product is completely rinsed out, or protect the eyes with a towel.
INSERT INTO "drug_generic" VALUES(1553, 'Sitafloxacin', 'Sitafloxacin', 'J01MA21', 1, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Tendon Rupture and CNS Effects", "severity": "High", "trigger_condition": "Elderly patients, concomitant corticosteroid use, or history of CNS disorders", "message": "STOP: Fluoroquinolones are associated with disabling and potentially irreversible serious adverse reactions, including tendinitis, tendon rupture, peripheral neuropathy, and CNS effects (convulsions). Discontinue immediately if symptoms occur."}]', '**Tendon Disorders and Rupture**
INSERT INTO "drug_generic" VALUES(1554, 'Potassium Guaiacol Sulphonate', 'Sulfogaiacol', 'R05CA05', 0, 0, 0, 0, 1, 1, 1, 0, '[]', 'Use with caution in patients presenting with a chronic or persistent cough, such as that associated with smoking, asthma, chronic bronchitis, or emphysema, as well as coughs accompanied by excessive phlegm or mucus production. Evaluate the underlying cause of the cough if it persists for more than 7 days, tends to recur, or is accompanied by fever, rash, or persistent headache. Safety during pregnancy and breastfeeding has not been fully established; weigh potential benefits against risks.', '- **Cough and Respiratory Infections:** Used as an expectorant for the symptomatic relief of coughs associated with the common cold, influenza, hay fever, and other mild upper respiratory tract infections.
INSERT INTO "drug_generic" VALUES(1555, 'Tioconazole Vag prep', 'Tioconazole Vaginal', 'G01AF08', 0, 0, 0, 0, 0, 1, 0, 0, '[]', 'Avoid self-medication in patients with diabetes mellitus or HIV infection, as recurrent or persistent candidiasis may be an early sign of these underlying conditions; medical evaluation is required.
INSERT INTO "drug_generic" VALUES(1556, 'Tetanus Antitoxin (Equine) BP', 'Tetanus Antitoxin (Equine)', 'J06AA02', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Administration of equine-derived serum", "message": "STOP: High risk of fatal anaphylaxis. A hypersensitivity test (skin or conjunctival) MUST be performed prior to administration. Epinephrine and resuscitation equipment must be immediately available."}]', 'A trial dose (sensitivity test) must be performed before administering the full dose. Inject 0.2 mL (diluted 1:10) subcutaneously and observe for 30 minutes. If no reaction occurs, proceed with the main dose. Keep the patient under observation for at least 30 minutes post-injection. Have epinephrine (adrenaline), antihistamines, and corticosteroids readily available. Use with extreme caution in patients with a history of asthma, infantile eczema, or previous allergic reactions to equine serum. Monitor for serum sickness, which may develop 7 to 10 days post-injection.', '- **Tetanus Prophylaxis:** Passive immunization for the prevention of tetanus in non-immune or partially immune individuals who have sustained tetanus-prone wounds (e.g., contaminated with soil, feces, or crush injuries).
INSERT INTO "drug_generic" VALUES(1557, 'Hydrocortisone + Neomycin Sulphate + Polymixin B E/E prep', 'Neomycin, Polymyxin B, and Hydrocortisone', 'S02CA03', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Ototoxicity Risk", "severity": "High", "trigger_condition": "Use in patients with a perforated tympanic membrane", "message": "STOP: Do not use otic preparations containing neomycin in patients with a perforated tympanic membrane due to the high risk of irreversible ototoxicity (sensorineural hearing loss)."}]', 'Ophthalmic use: Prolonged use may result in glaucoma, with damage to the optic nerve, defects in visual acuity and fields of vision, and posterior subcapsular cataract formation. Monitor intraocular pressure regularly if used for >10 days. May delay corneal wound healing and increase the risk of secondary ocular infections. 
INSERT INTO "drug_generic" VALUES(1558, 'Diclofenac Sodium + Misoprostol', 'Diclofenac / Misoprostol', 'M01AB55', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Abortifacient and Cardiovascular Risk", "severity": "High", "trigger_condition": "Prescribing to women of childbearing potential or patients with cardiovascular disease", "message": "STOP: Misoprostol can cause abortion, premature birth, or uterine rupture; contraindicated in pregnancy. Diclofenac increases the risk of fatal cardiovascular thrombotic events and serious GI bleeding."}]', '**Pregnancy Warning:** Women of childbearing potential must be advised of the abortifacient properties, have a negative pregnancy test within 2 weeks prior to starting therapy, and use effective contraception.
INSERT INTO "drug_generic" VALUES(1559, 'Isopropyl alcohol topical', 'Isopropyl alcohol topical', 'D08AX05', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Flammability Hazard", "severity": "High", "trigger_condition": "Exposure to open flames or high heat", "message": "STOP: This product is highly flammable. Keep away from fire, sparks, and heated surfaces. Allow to dry completely on the skin before using any heat-generating medical devices."}]', '**Flammability:** Highly flammable liquid and vapor. Keep away from heat, sparks, and open flames.
INSERT INTO "drug_generic" VALUES(1560, 'Alirocumab', 'Alirocumab', 'C10AX13', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "Moderate", "trigger_condition": "History of severe allergic reactions", "message": "Severe hypersensitivity reactions, including hypersensitivity vasculitis and reactions requiring hospitalization, have occurred. Discontinue immediately if signs of severe allergy develop."}]', '- **Hypersensitivity Reactions:** Severe hypersensitivity reactions (e.g., pruritus, rash, erythema, hypersensitivity vasculitis) have been reported. Discontinue alirocumab if a serious reaction occurs and treat appropriately.
INSERT INTO "drug_generic" VALUES(1561, 'Baclofen', 'Baclofen', 'M03BX01', 0, 1, 0, 0, 1, 1, 1, 1, '[{"alert_type": "Severe Withdrawal Syndrome", "severity": "High", "trigger_condition": "Abrupt discontinuation of therapy", "message": "STOP: Abrupt discontinuation of baclofen has resulted in severe adverse reactions including hallucinations, seizures, high fever, exaggerated rebound spasticity, rhabdomyolysis, multiple organ-system failure, and death. Taper the dose slowly."}]', '**CNS Depression:** Causes dose-related drowsiness and sedation. Patients should avoid operating automobiles or dangerous machinery until they know how the drug affects them. Effects are additive with alcohol and other CNS depressants.
INSERT INTO "drug_generic" VALUES(1562, 'Gentamicin topical', 'Gentamicin', 'D06AX07', 1, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Superinfection Risk", "severity": "Moderate", "trigger_condition": "Prolonged use", "message": "Prolonged use of topical antibiotics may result in the overgrowth of nonsusceptible organisms, including fungi. Discontinue use if superinfection occurs."}]', '**Superinfection:** Prolonged use may result in bacterial or fungal superinfection. Discontinue therapy and institute appropriate alternative treatment if superinfection develops.
INSERT INTO "drug_generic" VALUES(1563, 'Multivitamin Paediatric preparations', 'Pediatric Multivitamins', 'A11BA', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Multivitamin preparations are generally non-toxic when administered at recommended daily doses. However, caution should be exercised to avoid exceeding the recommended daily allowances (RDA), particularly for fat-soluble vitamins (A, D, E, K), which can accumulate and cause toxicity. Ensure parents or caregivers are aware of other dietary supplements or fortified foods the child may be consuming to prevent hypervitaminosis.', '- **Nutritional Supplementation:** Indicated to support normal growth and development in infants and children.
INSERT INTO "drug_generic" VALUES(1564, 'Metoclopramide Hydrochloride', 'Metoclopramide', 'A03FA01', 0, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Tardive Dyskinesia", "severity": "High", "trigger_condition": "Prolonged use (typically >12 weeks) or high cumulative doses", "message": "STOP: Metoclopramide can cause tardive dyskinesia, a serious and often irreversible movement disorder. Avoid treatment exceeding 12 weeks except in rare cases where therapeutic benefit outweighs the risk."}]', 'Use with extreme caution in patients with a history of depression, as severe dysphoria and suicidal ideation may occur. Extrapyramidal symptoms (EPS), including acute dystonic reactions, occur more frequently in pediatric patients, young adults (<30 years), and at higher doses. Monitor for signs of Neuroleptic Malignant Syndrome (NMS), characterized by hyperthermia, muscle rigidity, and altered mental status. Caution in patients with Parkinson''s disease, as it may exacerbate symptoms. Intravenous administration should be given slowly (over at least 1-2 minutes for small doses, 15 minutes for large doses) to prevent transient but intense feelings of anxiety and restlessness.', '- Relief of symptoms associated with acute and recurrent diabetic gastroparesis.
INSERT INTO "drug_generic" VALUES(1565, 'Benzoyl Peroxide 5% topical', 'Benzoyl Peroxide', 'D10AE01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Bleaching and Photosensitivity", "severity": "Medium", "trigger_condition": "Application of product", "message": "STOP: Benzoyl peroxide can bleach hair and colored fabrics (towels, pillowcases, clothing). It also increases sensitivity to sunlight; strict sun protection is required."}]', '**Skin Irritation:** Erythema, scaling, dryness, and stinging/burning are very common, especially during the first few weeks of use. The 5% concentration has a higher potential for irritation than the 2.5% concentration. If severe, patients should use a non-comedogenic moisturizer, reduce the frequency of application, or temporarily discontinue use.
INSERT INTO "drug_generic" VALUES(1566, 'Calcium Dobesilate', 'Calcium Dobesilate', 'C05BX01', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Agranulocytosis Risk", "severity": "High", "trigger_condition": "Development of fever, sore throat, or flu-like symptoms", "message": "STOP: Calcium dobesilate has been associated with rare but severe cases of agranulocytosis. Instruct patients to immediately report any signs of infection, and discontinue therapy if agranulocytosis is suspected."}]', '**Agranulocytosis:** Rare but potentially fatal agranulocytosis has been reported. Patients must be instructed to immediately report any signs of infection, such as high fever, sore throat, or flu-like symptoms. If suspected, treatment must be stopped immediately and a complete blood count (CBC) evaluated.
INSERT INTO "drug_generic" VALUES(1567, 'Light Liquid Paraffin + White Soft Paraffin + Glycerin topical', 'Mineral Oil / White Petrolatum / Glycerin', 'D02AC', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Local Irritation:** Discontinue use if severe irritation, redness, or hypersensitivity occurs.
INSERT INTO "drug_generic" VALUES(1568, 'Cholera Saline', 'Intravenous Cholera Saline (Dhaka Solution)', 'B05BB01', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Fluid Overload Risk", "severity": "High", "trigger_condition": "Patients with heart failure or severe renal impairment", "message": "STOP: Aggressive volume expansion can cause fatal pulmonary edema in patients with congestive heart failure or severe renal impairment (anuria/oliguria). Monitor lung sounds and fluid balance continuously."}]', '**Electrolyte Imbalance:** Contains high levels of potassium and sodium. Infuse with caution in patients where electrolyte imbalance may cause detrimental effects (e.g., renal impairment, head injury, or patients receiving potassium-sparing diuretics).
INSERT INTO "drug_generic" VALUES(1569, 'Benralizumab', 'Benralizumab', 'R03DX10', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Administration of benralizumab", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, angioedema, urticaria, and rash, have occurred following administration. Discontinue immediately if a hypersensitivity reaction occurs and initiate appropriate medical treatment."}]', 'Monitor patients closely for hypersensitivity reactions post-administration; these can occur within hours of injection, but in some instances have a delayed onset (days). Do not discontinue systemic or inhaled corticosteroids abruptly upon initiation of benralizumab therapy; corticosteroid reductions must be gradual and performed under direct medical supervision. Benralizumab is not indicated for the treatment of acute asthma exacerbations or status asthmaticus. Eosinophils may be involved in the immunological response to some helminth infections; treat patients with pre-existing helminth infections before initiating therapy. If a patient becomes infected with a helminth while receiving benralizumab and does not respond to standard anti-helminth treatment, discontinue benralizumab until the parasitic infection resolves.', '- Add-on maintenance treatment of severe asthma in patients aged 6 years and older with an eosinophilic phenotype.', '- **Hypersensitivity:** Contraindicated in patients with a known history of severe hypersensitivity (e.g., anaphylaxis, angioedema) to benralizumab or any of its excipients, as re-exposure can trigger a life-threatening allergic reaction.', '- **Headache** (Most common; usually mild and self-limiting)
INSERT INTO "drug_generic" VALUES(1570, 'Risdiplam', 'Risdiplam', 'M09AX10', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy or potential for pregnancy", "message": "STOP: Risdiplam has shown potential for fetal harm. Females must use highly effective contraception during treatment and for 1 month after. Males must use contraception and not donate sperm for 4 months after the last dose."}]', '**Embryo-Fetal Toxicity and Reproductive Risks**
INSERT INTO "drug_generic" VALUES(1571, 'Norepinephrine (Noradrenaline)', 'Norepinephrine', 'C01CA03', 0, 1, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Extravasation Risk", "severity": "High", "trigger_condition": "Intravenous administration outside of a central line", "message": "STOP: Severe tissue necrosis and sloughing can occur with extravasation. Administer via a central venous catheter whenever possible. If extravasation occurs, infiltrate the area with phentolamine immediately."}]', 'Correct blood volume depletion, hypoxia, hypercapnia, and acidosis prior to or during administration to ensure optimal pressor response.
INSERT INTO "drug_generic" VALUES(1572, 'Paclitaxel', 'Paclitaxel', 'L01CD01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Administration without premedication or history of hypersensitivity to Cremophor EL", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. All patients must be premedicated with a corticosteroid, diphenhydramine, and an H2 antagonist prior to administration."}, {"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Baseline absolute neutrophil count (ANC) < 1,500 cells/mm3", "message": "STOP: Do not administer if baseline ANC is < 1,500 cells/mm3 (< 1,000 cells/mm3 for Kaposi''s sarcoma) due to the risk of fatal infection and severe bone marrow suppression."}]', '**Bone Marrow Suppression:** Profound neutropenia is the dose-limiting toxicity. Frequent monitoring of complete blood counts is mandatory. Do not administer if baseline ANC is < 1,500 cells/mm3.
INSERT INTO "drug_generic" VALUES(1573, 'Bacitracin Zinc + Neomycin Sulphate + Polymixin B Eye prep', 'Neomycin, Polymyxin B, and Bacitracin Ophthalmic', 'S01AA30', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity and Sensitization", "severity": "High", "trigger_condition": "Prolonged use or history of aminoglycoside allergy", "message": "STOP: Neomycin is a potent sensitizer. Prolonged use can cause severe allergic contact dermatitis. Cross-sensitivity with other aminoglycosides may occur. Discontinue immediately if worsening irritation or rash develops."}]', '**Systemic Absorption:** Excessive use of the topical preparation may lead to substantial systemic absorption, which carries a risk of nephrotoxicity (from polymyxin B and neomycin) and neurotoxicity/ototoxicity (from neomycin). Use with caution in patients with pre-existing renal impairment.
INSERT INTO "drug_generic" VALUES(1574, 'Alprostadil', 'Alprostadil', 'C01EA01', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Apnea in Neonates", "severity": "High", "trigger_condition": "IV infusion in neonates with congenital heart defects", "message": "STOP: Apnea occurs in 10-12% of neonates treated with alprostadil, most often in those weighing <2 kg at birth. Ventilatory assistance must be immediately available."}, {"alert_type": "Priapism", "severity": "High", "trigger_condition": "Intracavernosal or urethral administration for erectile dysfunction", "message": "STOP: Prolonged erection and priapism (erection lasting >4 hours) can occur. Seek immediate medical assistance if this occurs to prevent permanent penile damage."}]', '**Neonatal Apnea:** Apnea is experienced by about 10-12% of neonates with congenital heart defects treated with IV alprostadil. It usually appears during the first hour of infusion. Ventilatory assistance must be immediately available.
INSERT INTO "drug_generic" VALUES(1575, 'Lamivudine + Raltegravir', 'Lamivudine and Raltegravir', 'J05AR16', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Severe Skin Reactions", "severity": "High", "trigger_condition": "Development of severe rash with systemic symptoms", "message": "STOP: Severe, potentially life-threatening, and fatal skin reactions (e.g., Stevens-Johnson syndrome, toxic epidermal necrolysis) have been reported with raltegravir. Discontinue immediately if signs occur."}, {"alert_type": "Hepatitis B Exacerbation", "severity": "High", "trigger_condition": "Co-infection with Hepatitis B Virus (HBV)", "message": "STOP: Severe acute exacerbations of hepatitis B have been reported in patients who are co-infected with HBV and HIV-1 and have discontinued lamivudine. Monitor hepatic function closely."}]', '**Myopathy and Rhabdomyolysis:** Cases of myopathy and rhabdomyolysis have been reported with raltegravir. Use with caution in patients with a history of myopathy or those taking other medications associated with these conditions (e.g., statins).
INSERT INTO "drug_generic" VALUES(1576, 'Ceftazidime', 'Ceftazidime', 'J01DD02', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Neurotoxicity", "severity": "High", "trigger_condition": "Renal impairment without dose adjustment", "message": "STOP: Severe neurotoxicity (encephalopathy, myoclonus, seizures, coma) can occur, particularly in patients with renal impairment who do not receive appropriate dose adjustments. Adjust dose based on CrCl."}, {"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(1577, 'Human normal Immunoglobulin', 'Immune Globulin Intravenous (Human)', 'J06BA02', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Thrombosis, Renal Dysfunction, and Acute Renal Failure", "severity": "High", "trigger_condition": "Administration to patients with pre-existing renal impairment, advanced age, or hyperviscosity", "message": "STOP: Intravenous immune globulin products have been associated with renal dysfunction, acute renal failure, osmotic nephrosis, and death. Thrombosis may occur regardless of the route of administration. Ensure adequate hydration and use the minimum concentration and infusion rate practicable."}]', 'Administer via the intravenous route only. Use with extreme caution in patients with pre-existing renal insufficiency, diabetes mellitus, volume depletion, sepsis, paraproteinemia, or those over 65 years of age due to the risk of acute renal failure (especially with sucrose-containing products). Monitor for signs of thrombosis, hyperviscosity, and aseptic meningitis syndrome (AMS). Monitor blood pressure continuously during infusion.', '- **Primary Immunodeficiency (PID):** Replacement therapy in primary immunodeficiency syndromes such as agammaglobulinemia, hypogammaglobulinemia, and severe combined immunodeficiency.
INSERT INTO "drug_generic" VALUES(1578, 'Calcium Lactate', 'Calcium Lactate', 'A12AA05', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Renal Impairment and Nephrolithiasis:** Use with caution in patients with a history of kidney stones or renal impairment; frequent monitoring of serum calcium and phosphorus is recommended.
INSERT INTO "drug_generic" VALUES(1579, 'Celiprolol Hydrochloride', 'Celiprolol', 'C07AB08', 0, 1, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Abrupt Withdrawal Risk", "severity": "High", "trigger_condition": "Discontinuation of therapy", "message": "STOP: Severe exacerbation of angina, myocardial infarction, and ventricular arrhythmias have occurred following abrupt discontinuation of beta-blockers. Taper the dose gradually over 1 to 2 weeks."}]', '**Asthma and Bronchospastic Disease:** Although celiprolol is cardioselective and has partial beta-2 agonist activity, it should be used with caution in patients with bronchospastic disease. Monitor pulmonary function.
INSERT INTO "drug_generic" VALUES(1580, 'Sodium Chloride oral prep', 'Sodium Chloride (Oral)', 'A12CA01', 0, 0, 1, 1, 1, 0, 1, 0, '[]', '**Fluid Retention and Edema:** Use with extreme caution in patients with conditions exacerbated by sodium retention, including hypertension, heart failure, peripheral or pulmonary edema, and preeclampsia.
INSERT INTO "drug_generic" VALUES(1581, 'Metronidazole topical', 'Metronidazole', 'D06BX01', 1, 0, 1, 0, 0, 1, 0, 0, '[{"alert_type": "Ocular Irritation", "severity": "Moderate", "trigger_condition": "Application near the eyes", "message": "Avoid contact with the eyes. Topical metronidazole can cause tearing and severe ocular irritation. If contact occurs, flush eyes immediately with copious amounts of water."}]', '**External Use Only:** Avoid contact with eyes; tearing and irritation may occur. If contact occurs, wash out immediately with water.
INSERT INTO "drug_generic" VALUES(1582, 'Letrozole', 'Letrozole', 'L02BG04', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Embryo-Fetal Toxicity and Bone Loss", "severity": "High", "trigger_condition": "Prescribing to women of reproductive potential or prolonged use", "message": "STOP: Letrozole can cause fetal harm and is contraindicated in pregnancy. Prolonged use significantly decreases bone mineral density, increasing the risk of osteoporosis and fractures. Monitor bone health regularly."}]', '- **Bone Effects:** Decreases bone mineral density (BMD). Assess BMD at baseline and periodically thereafter. Consider calcium and vitamin D supplementation, and prophylactic bisphosphonates if indicated.
INSERT INTO "drug_generic" VALUES(1583, 'Desonide Topical', 'Desonide', 'D07AB08', 0, 0, 1, 1, 0, 1, 1, 1, '[]', '**HPA Axis Suppression:** Systemic absorption of topical corticosteroids can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and unmask latent diabetes. Risk increases with prolonged use, application over large surface areas, use under occlusion, and in pediatric patients.
INSERT INTO "drug_generic" VALUES(1584, 'Terazosin', 'Terazosin', 'G04CA03', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "First-Dose Syncope", "severity": "High", "trigger_condition": "Initiation of therapy or rapid dose escalation", "message": "STOP: Profound orthostatic hypotension and syncope can occur with the first dose or during rapid dose titration. The initial dose must be 1 mg at bedtime."}]', '**Orthostatic Hypotension and Syncope:** "First-dose" effect can cause marked hypotension and syncope within 30 to 90 minutes of administration. Initiate strictly at 1 mg at bedtime and titrate slowly. Advise patients to avoid abrupt postural changes.
INSERT INTO "drug_generic" VALUES(1585, 'Hyaluronidase', 'Hyaluronidase', 'B06AA03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Infection Spread", "severity": "High", "trigger_condition": "Injection into or around infected or cancerous areas", "message": "STOP: Do not inject into or around infected, acutely inflamed, or cancerous areas. Hyaluronidase increases tissue permeability and can cause rapid spread of localized infection or malignancy."}]', '**Infection and Malignancy:** Avoid injection into infected or cancerous areas to prevent the spread of pathogens or malignant cells.
INSERT INTO "drug_generic" VALUES(1586, 'Mifepristone', 'Mifepristone', 'G03XB01', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Serious and Sometimes Fatal Infections and Bleeding", "severity": "High", "trigger_condition": "Medical termination of pregnancy", "message": "STOP: Rare but fatal cases of atypical infection (e.g., Clostridium sordellii) and severe prolonged bleeding have occurred following mifepristone use. Patients must be closely monitored and instructed to seek immediate medical attention for sustained fever, severe abdominal pain, or heavy bleeding."}]', 'Use with extreme caution in patients with hemostatic disorders, severe anemia, or those on concurrent anticoagulant therapy due to the risk of heavy uterine bleeding.
INSERT INTO "drug_generic" VALUES(1587, 'Sodium Alginate + Sodium Bicarbonate + Calcium Carbonate', 'Sodium Alginate + Sodium Bicarbonate + Calcium Carbonate', 'A02BX13', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '- **Sodium Content:** Contains significant amounts of sodium. Use with caution in patients on a highly restricted sodium diet (e.g., severe congestive heart failure, renal impairment).
INSERT INTO "drug_generic" VALUES(1588, 'Tocilizumab', 'Tocilizumab', 'L04AC07', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Serious Infections", "severity": "High", "trigger_condition": "Patients with active infections, including localized infections", "message": "STOP: Serious and potentially fatal infections (e.g., tuberculosis, invasive fungal, viral, and opportunistic infections) have occurred. Do not initiate therapy during an active infection. Test for latent TB before starting."}]', '- **Serious Infections:** Patients are at increased risk for developing serious infections that may lead to hospitalization or death. Monitor closely for signs of infection during and after treatment. Interrupt therapy if a serious infection develops.
INSERT INTO "drug_generic" VALUES(1589, 'Thiamine Hydrochloride', 'Thiamine', 'A11DA01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Intravenous administration", "message": "Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur with intravenous administration. Administer slowly and ensure resuscitation equipment is readily available."}]', 'Use caution with parenteral administration due to the risk of hypersensitivity reactions. In patients with suspected Wernicke''s encephalopathy, thiamine must be administered *before* or *concurrently* with intravenous glucose to prevent the precipitation or exacerbation of the encephalopathy. Daily requirements are increased during pregnancy, lactation, and conditions with high carbohydrate intake.', '- **Thiamine Deficiency:** Treatment and prophylaxis of thiamine deficiency, including Beriberi (wet and dry).
INSERT INTO "drug_generic" VALUES(1590, 'Bictegravir + Emtricitabine + Tenofovir Alafenamide', 'Bictegravir / Emtricitabine / Tenofovir Alafenamide', 'J05AR20', 0, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Hepatitis B Exacerbation", "severity": "High", "trigger_condition": "Discontinuation of therapy in patients coinfected with HIV-1 and HBV", "message": "STOP: Severe acute exacerbations of hepatitis B have been reported in coinfected patients who discontinue products containing emtricitabine or tenofovir. Closely monitor hepatic function for several months after stopping."}]', '**Hepatitis B Exacerbation:** Severe acute exacerbations of hepatitis B have been reported in patients coinfected with HIV-1 and HBV who have discontinued products containing emtricitabine (FTC) and/or tenofovir. Closely monitor hepatic function with both clinical and laboratory follow-up for at least several months in these patients. If appropriate, anti-hepatitis B therapy may be warranted.
INSERT INTO "drug_generic" VALUES(1591, 'Cyclopentolate Hydrochloride Eye prep', 'Cyclopentolate Ophthalmic', 'S01FA04', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Central Nervous System Toxicity in Children", "severity": "High", "trigger_condition": "Use in infants and young children, especially with stronger solutions (1% or 2%)", "message": "WARNING: May cause severe CNS disturbances (hallucinations, ataxia, seizures, behavioral changes) and cardiopulmonary side effects in infants and children. Use the lowest effective concentration (0.5%) in this population and monitor closely."}]', '**Glaucoma Risk:** Mydriatics may produce a transient elevation of intraocular pressure. Use with extreme caution in the elderly and in patients with untreated narrow-angle glaucoma or anatomically narrow angles, as it may precipitate an acute angle-closure glaucoma attack.
INSERT INTO "drug_generic" VALUES(1592, 'Estradiol vag prep', 'Estradiol Vaginal', 'G03CA03', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Endometrial and Cardiovascular Risks", "severity": "High", "trigger_condition": "Use of unopposed estrogens in women with an intact uterus, or history of cardiovascular disease", "message": "STOP: Estrogens increase the risk of endometrial cancer in women with a uterus. Estrogen therapy is also associated with an increased risk of stroke, DVT, PE, and myocardial infarction. Prescribe at the lowest effective dose for the shortest duration."}]', 'Systemic absorption occurs with intravaginal administration; consider warnings associated with systemic estrogen therapy. Increased risk of endometrial cancer in women with an intact uterus using unopposed estrogens; consider adding a progestin. Increased risk of stroke, DVT, PE, and MI; discontinue immediately if suspected. May increase the risk of dementia in postmenopausal women. Use with caution in patients with a history of hypertriglyceridemia, as estrogen may cause elevated triglycerides leading to pancreatitis. May cause fluid retention; observe patients with cardiac or renal impairment carefully. Monitor thyroid function in women on thyroid hormone replacement, as estrogens increase thyroid-binding globulin (TBG). Discontinue if sudden loss of vision, proptosis, diplopia, or migraine occurs, pending examination for retinal vascular thrombosis.', '- **Vulvovaginal Atrophy:** Treatment of moderate to severe symptoms of vulvar and vaginal atrophy due to menopause.
INSERT INTO "drug_generic" VALUES(1593, 'Spectinomycin', 'Spectinomycin', 'J01XX04', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe hypersensitivity to spectinomycin", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before administration."}]', 'Spectinomycin is ineffective in the treatment of syphilis. Because it is used to treat gonorrhea, which may co-occur with syphilis, spectinomycin may mask or delay the symptoms of incubating syphilis. Perform serologic tests for syphilis at the time of gonorrhea diagnosis and repeat 3 months later. Use with caution in patients with severe renal impairment. Monitor for signs of hypersensitivity following administration.', '- **Uncomplicated Gonococcal Infections:** Indicated for the treatment of acute gonorrheal urethritis and proctitis in males, and acute gonorrheal cervicitis and proctitis in females caused by susceptible strains of *Neisseria gonorrhoeae*.
INSERT INTO "drug_generic" VALUES(1594, 'Methyclothiazide', 'Methyclothiazide', 'C03AA08', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Electrolyte Depletion", "severity": "High", "trigger_condition": "Prolonged use or high doses", "message": "STOP: Thiazide diuretics can cause severe hypokalemia, hyponatremia, and hypochloremic alkalosis. Monitor serum electrolytes regularly."}]', '**Electrolyte Imbalance:** May cause hypokalemia, hyponatremia, hypochloremic alkalosis, and hypomagnesemia. Monitor electrolytes regularly.
INSERT INTO "drug_generic" VALUES(1595, 'Crotamiton  + Permethrin', 'Crotamiton and Permethrin Topical', 'P03AC', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Application Site:** For external use only. Avoid contact with the eyes, mouth, and mucous membranes. If contact occurs, flush thoroughly with water.
INSERT INTO "drug_generic" VALUES(1596, 'Mirtazapine', 'Mirtazapine', 'N06AX11', 0, 1, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Suicidal Thoughts and Behaviors", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes, particularly in young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}, {"alert_type": "Agranulocytosis", "severity": "High", "trigger_condition": "Patient presenting with fever, sore throat, or other signs of infection", "message": "STOP: Mirtazapine has been associated with rare but severe agranulocytosis. If a patient develops signs of infection with a low WBC count, discontinue the drug immediately and monitor bone marrow recovery."}]', 'Use with caution in patients with a history of epilepsy or seizures; avoid completely in unstable cases.
INSERT INTO "drug_generic" VALUES(1597, 'Clindamycin Phosphate 1.2% + Tretinoin 0.025% Topical', 'Clindamycin and Tretinoin Topical', 'D10AD51', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Severe Colitis", "severity": "High", "trigger_condition": "Development of severe diarrhea or abdominal cramps during therapy", "message": "Systemic absorption of clindamycin can occur. Discontinue immediately if significant diarrhea, bloody diarrhea, or severe abdominal cramps occur, as this may indicate Clostridioides difficile-associated diarrhea (CDAD)."}]', '**Skin Irritation:** Erythema, scaling, dryness, and stinging/burning are common, especially during the first few weeks of therapy. Avoid application to eczematous, sunburned, or abraded skin.
INSERT INTO "drug_generic" VALUES(1598, 'Levocetrizine Dihydrochloride 0.1%', 'Levocetirizine Dihydrochloride', 'R06AE09', 0, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Renal Contraindication", "severity": "High", "trigger_condition": "Patients with End-Stage Renal Disease (CrCl <10 mL/min) or undergoing hemodialysis", "message": "STOP: Levocetirizine is strictly contraindicated in patients with End-Stage Renal Disease (CrCl <10 mL/min) and those undergoing hemodialysis due to the risk of severe drug accumulation."}]', '**CNS Depression:** May cause somnolence, fatigue, and asthenia. Patients should be cautioned against engaging in hazardous occupations requiring complete mental alertness, such as driving or operating machinery.
INSERT INTO "drug_generic" VALUES(1599, 'Insulin Degludec', 'Insulin Degludec', 'A10AE06', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypoglycemia Risk", "severity": "High", "trigger_condition": "Changes in insulin regimen, missed meals, or increased physical activity", "message": "STOP: Severe, life-threatening hypoglycemia can occur. Never share insulin pens between patients, even if the needle is changed, due to the risk of transmitting blood-borne pathogens."}]', '- **Hypoglycemia:** The most common adverse effect. Risk increases with changes in meal patterns, physical activity, or co-administered glucose-lowering drugs.
INSERT INTO "drug_generic" VALUES(1600, 'Fluticasone propionate + Formoterol fumarate inhaler', 'Fluticasone and Formoterol', 'R03AK11', 0, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Asthma-Related Death / Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Use during acute asthma attack or worsening asthma", "message": "STOP: Do NOT use for the relief of acute bronchospasm. Paradoxical bronchospasm can occur; if it does, treat immediately with a short-acting bronchodilator and discontinue this inhaler."}]', 'Do not initiate therapy during rapidly deteriorating or potentially life-threatening episodes of asthma.
INSERT INTO "drug_generic" VALUES(1601, 'Cefoperazone', 'Cefoperazone', 'J01DD12', 1, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Bleeding Risk and Disulfiram-like Reaction", "severity": "High", "trigger_condition": "Concurrent alcohol use or underlying coagulopathy", "message": "STOP: Cefoperazone contains an N-methylthiotetrazole (MTT) side chain, which can cause severe hypoprothrombinemia (bleeding risk) and a disulfiram-like reaction with alcohol. Monitor coagulation profiles and strictly avoid alcohol."}]', '**Hypoprothrombinemia and Bleeding:** The N-methylthiotetrazole (MTT) side chain inhibits vitamin K epoxide reductase, leading to decreased prothrombin activity. Patients with poor nutritional status, malabsorption, or hepatic impairment are at high risk. Monitor prothrombin time (PT/INR) and administer exogenous vitamin K if necessary.
INSERT INTO "drug_generic" VALUES(1602, 'Resorcinol', 'Resorcinol', 'D10AX02', 0, 0, 0, 0, 0, 0, 0, 0, '[]', 'Do not apply on broken skin or large areas of the skin for a prolonged period or in high concentrations due to the risk of systemic absorption and toxicity. Caution when used in children. May discolor light-colored hair and urine.', '- **Acne Vulgaris:** Used as a keratolytic agent for the topical treatment of acne and seborrheic skin conditions.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to resorcinol.
INSERT INTO "drug_generic" VALUES(1603, 'Pheniramine Maleate + Naphazoline HCl Eye prep', 'Pheniramine and Naphazoline Ophthalmic', 'S01GA51', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Angle-Closure Glaucoma", "severity": "High", "trigger_condition": "Patient history of narrow-angle glaucoma", "message": "STOP: Contraindicated in patients with narrow-angle glaucoma. Naphazoline can induce mydriasis and precipitate an acute angle-closure glaucoma crisis."}]', 'Use with caution in patients with hypertension, cardiovascular abnormalities, diabetes mellitus, hyperthyroidism, or ocular infection/injury. Prolonged use or overuse may lead to rebound ocular congestion (rhinitis medicamentosa of the eye). Patients should be advised to seek immediate medical attention if they experience ocular pain, changes in vision, worsening of redness or irritation, or if symptoms persist for more than 72 hours. Contact lenses must be removed prior to instillation and can be reinserted after 15 minutes, provided the eyes are not red.', '- **Allergic Conjunctivitis:** Temporary relief of ocular itching and redness associated with seasonal or perennial allergic conjunctivitis.', '- **Hypersensitivity:** Contraindicated in patients with known hypersensitivity to pheniramine, naphazoline, or any component of the formulation.
INSERT INTO "drug_generic" VALUES(1604, 'Brexpiprazole', 'Brexpiprazole', 'N05AX16', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Increased Mortality in Elderly & Suicidality", "severity": "High", "trigger_condition": "Use in elderly patients with dementia-related psychosis or young adults with depression", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotics are at an increased risk of death. Antidepressants increase the risk of suicidal thoughts and behaviors in children, adolescents, and young adults."}]', '- **Increased Mortality in Elderly:** Increased risk of death in elderly patients with dementia-related psychosis. Not approved for dementia-related psychosis without agitation associated with Alzheimer''s disease.
INSERT INTO "drug_generic" VALUES(1605, 'Carfilzomib', 'Carfilzomib', 'L01XG02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiac and Pulmonary Toxicity", "severity": "High", "trigger_condition": "Patients with baseline cardiac risk factors or presenting with dyspnea", "message": "STOP: Severe and potentially fatal cardiac failure, ischemia, and pulmonary toxicities (including ARDS and pulmonary hypertension) can occur. Monitor closely and withhold therapy if suspected."}]', '**Cardiac Toxicities:** New onset or worsening of pre-existing cardiac failure (e.g., congestive heart failure, pulmonary edema, decreased ejection fraction), myocardial ischemia, and myocardial infarction have occurred, including fatal cases. Monitor for signs and symptoms of cardiac failure or ischemia. Withhold therapy and evaluate promptly if suspected.
INSERT INTO "drug_generic" VALUES(1606, 'Menthol + Eucalyptus oil Inhalation', 'Menthol + Eucalyptus oil Inhalation', 'R05X', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Infant Apnea Risk", "severity": "High", "trigger_condition": "Application near the nostrils of infants", "message": "STOP: Do not apply menthol-containing products directly to the nostrils of infants, as it can cause instant collapse and apnea."}]', '**Hypersensitivity:** Menthol may give rise to hypersensitivity reactions, including contact dermatitis.
INSERT INTO "drug_generic" VALUES(1607, 'Arformoterol', 'Arformoterol', 'R03AC15', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Asthma-Related Death Risk", "severity": "High", "trigger_condition": "Use as monotherapy in asthma patients", "message": "STOP: Long-acting beta2-adrenergic agonists (LABA) as monotherapy (without an inhaled corticosteroid) increase the risk of asthma-related death. Arformoterol is NOT indicated for the treatment of asthma."}, {"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediately following inhalation", "message": "Life-threatening paradoxical bronchospasm can occur. If this occurs, discontinue arformoterol immediately and institute alternative therapy."}]', '- **Acute Deterioration:** Do not initiate in acutely deteriorating COPD patients or use for the relief of acute bronchospasm. A short-acting beta2-agonist (SABA) must be provided for acute symptoms.
INSERT INTO "drug_generic" VALUES(1608, 'Isoproterenol (Isoprenaline)', 'Isoproterenol', 'C01CA02', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Proarrhythmic Risk and Myocardial Ischemia", "severity": "High", "trigger_condition": "Administration in patients with underlying ischemic heart disease or tachyarrhythmias", "message": "STOP: Isoproterenol significantly increases myocardial oxygen demand and can precipitate severe angina, myocardial infarction, or fatal ventricular arrhythmias. Continuous ECG and hemodynamic monitoring are mandatory."}]', '**Cardiovascular Disease:** Use with extreme caution in patients with coronary artery disease, ischemic heart disease, hypertension, or aneurysms. The drug increases myocardial oxygen demand and can exacerbate ischemia or precipitate arrhythmias.
INSERT INTO "drug_generic" VALUES(1609, 'Nabumetone', 'Nabumetone', 'M01AX01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risks", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke, which can be fatal. They also cause an increased risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation of the stomach or intestines."}]', '**Cardiovascular Risk:** Increased risk of serious CV thrombotic events, MI, and stroke. Risk may increase with duration of use. Use with caution in patients with pre-existing CV disease or risk factors (e.g., hypertension, fluid retention, CHF).
INSERT INTO "drug_generic" VALUES(1610, 'Recombinant Somatropin', 'Somatropin', 'H01AC01', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Neoplasm Risk", "severity": "High", "trigger_condition": "Active malignancy", "message": "STOP: Somatropin is contraindicated in patients with active malignancy. Discontinue treatment if there is evidence of tumor growth."}]', '**Intracranial Hypertension:** Benign intracranial hypertension with papilledema, visual changes, headache, nausea, and/or vomiting has been reported. Funduscopic examination should be performed routinely before initiating treatment and periodically thereafter.
INSERT INTO "drug_generic" VALUES(1611, 'Hyaluronic Acid', 'Hyaluronic Acid (Sodium Hyaluronate)', 'M09AX01', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Intra-Articular Injection Precaution", "severity": "Moderate", "trigger_condition": "Post-injection period", "message": "Avoid strenuous physical activities (e.g., jogging, tennis, heavy lifting) or prolonged weight-bearing activities for 48 hours following intra-articular injection to prevent joint swelling and pain."}]', '**Avian Allergy:** Some intra-articular formulations are derived from rooster combs. Use with extreme caution or avoid in patients with known hypersensitivity to avian proteins, feathers, or egg products. (Note: Bio-fermented synthetic versions are available and safe for these patients).
INSERT INTO "drug_generic" VALUES(1612, 'Dicycloverine (Dicyclomine) Hydrochloride', 'Dicyclomine Hydrochloride', 'A03AA05', 0, 0, 1, 0, 1, 1, 0, 0, '[{"alert_type": "Pediatric Contraindication", "severity": "High", "trigger_condition": "Patient age < 6 months", "message": "STOP: Contraindicated in infants less than 6 months of age due to reports of severe respiratory reactions, seizures, syncope, asphyxia, coma, and death."}]', '**Cardiovascular Effects:** Use with caution in patients with congestive heart failure, coronary artery disease, or tachycardia secondary to cardiac insufficiency or thyrotoxicosis. Assess for tachyarrhythmias before administration.
INSERT INTO "drug_generic" VALUES(1613, 'Carvedilol', 'Carvedilol', 'C07AG02', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Abrupt Withdrawal", "severity": "High", "trigger_condition": "Sudden discontinuation of therapy", "message": "STOP: Do not abruptly discontinue carvedilol. Severe exacerbation of angina, myocardial infarction, and ventricular arrhythmias have occurred following abrupt withdrawal. Taper gradually over 1 to 2 weeks."}]', '**Heart Failure Worsening:** Fluid retention and worsening heart failure may occur during up-titration. Monitor weight and symptoms; adjust diuretics if necessary.
INSERT INTO "drug_generic" VALUES(1614, 'Metamizol', 'Dipyrone', 'N02BB02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Agranulocytosis Risk", "severity": "High", "trigger_condition": "Patient presenting with high fever, chills, sore throat, or mucosal ulcerations during therapy", "message": "STOP: Severe and potentially fatal agranulocytosis can occur. Discontinue immediately and evaluate complete blood count (CBC) if signs of infection develop."}]', '**Hematologic Toxicity:** Metamizole is associated with a risk of severe, life-threatening agranulocytosis. Patients must be monitored for signs of bone marrow suppression (e.g., fever, sore throat, stomatitis). Discontinue immediately if these occur.
INSERT INTO "drug_generic" VALUES(1615, 'Isopropamide + Trifluoperazine', 'Isopropamide and Trifluoperazine', 'A03CA', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Neuroleptic Malignant Syndrome (NMS)", "severity": "High", "trigger_condition": "Use of antipsychotic component (Trifluoperazine)", "message": "STOP: Trifluoperazine can cause Neuroleptic Malignant Syndrome, a potentially fatal symptom complex characterized by hyperpyrexia, muscle rigidity, altered mental status, and autonomic instability. Discontinue immediately if these occur."}]', '**Tardive Dyskinesia:** Trifluoperazine may cause potentially irreversible, involuntary, dyskinetic movements. The risk is highest in the elderly, especially women. Discontinue if signs appear.
INSERT INTO "drug_generic" VALUES(1616, 'Fomepizole', 'Fomepizole', 'V03AB34', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hemodialysis Requirement", "severity": "High", "trigger_condition": "Severe metabolic acidosis or renal failure in toxic alcohol poisoning", "message": "STOP: Fomepizole blocks toxic metabolite formation but does not remove parent alcohols. Hemodialysis may still be required for severe acidemia, renal failure, or very high toxic alcohol levels. Adjust fomepizole dosing during hemodialysis."}]', '**Monitoring:** Fomepizole should be used in conjunction with comprehensive management of toxic alcohol poisoning. Monitor arterial blood gases, serum electrolytes, osmolal gap, anion gap, and renal function frequently. 
INSERT INTO "drug_generic" VALUES(1617, 'Immuno booster', 'Enteral Immunonutrition Supplement', 'V06DB', 0, 0, 1, 1, 1, 0, 0, 0, '[]', '**Route of Administration:** Strictly for enteral use (oral or feeding tube). Do not administer intravenously (parenterally) under any circumstances.
INSERT INTO "drug_generic" VALUES(1618, 'Fluocinolone Acetonide 0.025% Topical', 'Fluocinolone Acetonide 0.025% Topical Cream/Ointment', 'D07AC04', 0, 0, 0, 0, 0, 0, 0, 1, '[]', 'Systemic absorption of topical corticosteroids can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, manifestations of Cushing''s syndrome, hyperglycemia, and glucosuria. Conditions that augment systemic absorption include the application of more potent steroids, use over large surface areas, prolonged use, and the addition of occlusive dressings. Use with caution in pediatric patients, as they are more susceptible to systemic toxicity. Avoid contact with eyes.', '- **Corticosteroid-Responsive Dermatoses:** Relief of the inflammatory and pruritic manifestations of corticosteroid-responsive dermatoses.
INSERT INTO "drug_generic" VALUES(1619, 'Amiodarone Hydrochloride', 'Amiodarone', 'C01BD01', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Pulmonary Toxicity", "severity": "High", "trigger_condition": "Long-term therapy", "message": "STOP: Amiodarone causes fatal pulmonary toxicity (hypersensitivity pneumonitis or interstitial/alveolar pneumonitis) in up to 17% of patients. Obtain baseline CXR and PFTs, and monitor every 3-6 months."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated liver enzymes", "message": "STOP: Fatal hepatotoxicity can occur. Obtain baseline and periodic LFTs. Discontinue if transaminases exceed 3 times normal or if clinical signs of liver injury develop."}, {"alert_type": "Proarrhythmic Effects", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "STOP: Amiodarone can exacerbate arrhythmias. Initiate therapy in a clinical setting with continuous ECG monitoring and resuscitation equipment available."}]', '**Thyroid Dysfunction:** Contains high amounts of iodine. Can cause hyperthyroidism (which may exacerbate arrhythmias) or hypothyroidism. Monitor TSH, T3, and T4 at baseline and every 6 months.
INSERT INTO "drug_generic" VALUES(1620, 'Fosamprenavir', 'Fosamprenavir calcium', 'J05AE07', 1, 0, 0, 0, 0, 0, 1, 0, '[]', '**Severe Skin Reactions:** Severe and life-threatening skin reactions, including Stevens-Johnson syndrome (SJS), have been reported. Discontinue therapy immediately if severe skin reactions occur.
INSERT INTO "drug_generic" VALUES(1621, 'Isoconazole + Diflucortolone topical', 'Isoconazole and Diflucortolone', 'D01AC20', 1, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Skin Atrophy and Systemic Absorption", "severity": "Medium", "trigger_condition": "Prolonged use, use on face, or use under occlusive dressings", "message": "Caution: Contains a potent corticosteroid (diflucortolone). Prolonged use can cause skin thinning, striae, and systemic absorption leading to HPA axis suppression, especially in children."}]', '**Skin Atrophy:** Prolonged use may lead to skin thinning, loss of elasticity, dilatation of superficial blood vessels, telangiectasia, and ecchymoses. Avoid prolonged use, especially on the face or in skin creases.
INSERT INTO "drug_generic" VALUES(1622, 'Suramin', 'Suramin sodium', 'P01CX02', 1, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Toxicity", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "STOP: Suramin is highly toxic. Severe adverse reactions including nephrotoxicity, shock, and blood dyscrasias can occur. Must be administered under strict medical supervision."}]', '**Renal Toxicity:** Proteinuria and severe renal damage have been frequently reported. Monitor urinalysis and renal function closely before and during therapy. Avoid use in patients with pre-existing renal impairment.
INSERT INTO "drug_generic" VALUES(1623, 'Miconazole Nitrate + Zinc Oxide + White Soft Paraffin', 'Miconazole, Zinc Oxide, and White Petrolatum', 'D01AC20', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Diagnosis Verification", "severity": "Moderate", "trigger_condition": "Use for standard diaper rash", "message": "Intended specifically for diaper dermatitis complicated by a fungal (Candida) infection, characterized by fiery red plaques with satellite lesions. Non-fungal diaper rash should be managed with plain barrier creams without antifungals."}]', '**External Use Only:** Do not apply to eyes, mouth, or internal mucous membranes.
INSERT INTO "drug_generic" VALUES(1624, 'Glycopyrronium tosylate topical', 'Glycopyrronium Tosylate', 'D11AA', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Anticholinergic Toxicity and Heat Stroke", "severity": "High", "trigger_condition": "High ambient temperature or concurrent anticholinergic use", "message": "STOP: Glycopyrronium inhibits sweating. In high ambient temperatures, heat illness (hyperpyrexia, heat stroke) can occur. Monitor for lack of sweating. Discontinue if signs of urinary retention or severe anticholinergic effects develop."}]', '**Urinary Retention:** Use with caution in patients with a history or presence of documented urinary retention, prostatic hypertrophy, or bladder-neck obstruction. Monitor for difficulty passing urine or a distended bladder. Discontinue immediately if symptoms develop.
INSERT INTO "drug_generic" VALUES(1625, 'Urokinase', 'Urokinase', 'B01AD04', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Severe Hemorrhage", "severity": "High", "trigger_condition": "Administration of systemic thrombolytic therapy", "message": "STOP: Urokinase can cause severe, potentially fatal internal or external bleeding. Avoid invasive procedures. Contraindicated in active bleeding, recent stroke, or recent major surgery."}]', '**Bleeding Risk:** High risk of severe hemorrhage. Avoid any unnecessary vascular punctures, IM injections, or invasive procedures during and immediately after therapy. If arterial puncture is necessary, use an upper extremity vessel, apply pressure for at least 30 minutes, and apply a pressure dressing.
INSERT INTO "drug_generic" VALUES(1626, 'Idarubicin Hydrochloride', 'Idarubicin', 'L01DB06', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Myocardial Toxicity", "severity": "High", "trigger_condition": "Cumulative dose limits approached or preexisting cardiac disease", "message": "STOP: Severe myocardial toxicity leading to congestive heart failure (CHF) can occur. Monitor cardiac function (LVEF) closely."}, {"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Administration of therapeutic doses", "message": "STOP: Profound myelosuppression is expected. Monitor complete blood counts frequently. Ensure facilities for severe infection and hemorrhage management are available."}, {"alert_type": "Tissue Necrosis (Vesicant)", "severity": "High", "trigger_condition": "Extravasation during intravenous administration", "message": "STOP: Idarubicin is a potent vesicant. Administer only via a freely flowing IV. If extravasation occurs, stop infusion immediately and apply cold compresses."}]', '**Cardiac Toxicity:** Anthracycline-induced cardiotoxicity may manifest as acute arrhythmias or delayed cardiomyopathy leading to CHF. Risk increases with prior anthracycline exposure, mediastinal radiation, or preexisting heart disease. Evaluate LVEF before and during therapy.
INSERT INTO "drug_generic" VALUES(1627, 'Dulaglutide', 'Dulaglutide', 'A10BJ05', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Thyroid C-Cell Tumors", "severity": "High", "trigger_condition": "Personal or family history of medullary thyroid carcinoma (MTC) or Multiple Endocrine Neoplasia syndrome type 2 (MEN 2)", "message": "STOP: Dulaglutide causes thyroid C-cell tumors in rodents. It is contraindicated in patients with a personal or family history of MTC or MEN 2."}]', '- **Pancreatitis:** Acute pancreatitis has been reported. Observe patients for signs and symptoms (e.g., persistent severe abdominal pain, sometimes radiating to the back). Discontinue promptly if suspected.
INSERT INTO "drug_generic" VALUES(1628, 'Zanamivir', 'Zanamivir', 'J05AH01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Bronchospasm Risk", "severity": "High", "trigger_condition": "Underlying asthma or COPD", "message": "STOP: Severe and potentially fatal bronchospasm can occur. Not recommended for patients with underlying airway disease. Ensure a fast-acting bronchodilator is readily available."}]', 'Use with extreme caution in patients with underlying respiratory diseases (e.g., asthma, COPD) due to a high risk of severe bronchospasm; if prescribed, a fast-acting inhaled bronchodilator must be readily available. If a patient is scheduled to use an inhaled bronchodilator at the same time as zanamivir, the bronchodilator should be used first. Discontinue zanamivir immediately if bronchospasm or a decline in respiratory function develops. Monitor for abnormal behavior or delirium, particularly in pediatric patients, as neuropsychiatric events have been reported with neuraminidase inhibitors.', '- **Treatment of Influenza A and B:** Indicated for the treatment of uncomplicated acute illness due to influenza A and B virus in patients who have been symptomatic for no more than 2 days.
INSERT INTO "drug_generic" VALUES(1629, 'Chlorhexidine Gluconate 1 %  Oral prep', 'Chlorhexidine Gluconate Dental Gel', 'A01AB03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Hypersensitivity to chlorhexidine", "message": "STOP: Rare but severe and potentially fatal allergic reactions (anaphylaxis) can occur. Discontinue immediately and seek emergency medical care if symptoms of an allergic reaction develop."}]', '**Tooth and Mucosal Staining:** Can cause reversible brown staining of the teeth, tongue, and tooth restorations. This is more pronounced in patients with heavy plaque accumulation.
INSERT INTO "drug_generic" VALUES(1630, 'Articaine Hydrochloride + Epinephrine', 'Articaine and Epinephrine', 'N01BB58', 0, 1, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Intravascular Injection and Systemic Toxicity", "severity": "High", "trigger_condition": "Accidental IV administration", "message": "STOP: Accidental intravascular injection can cause severe systemic toxicity, including seizures, cardiac arrhythmias, and cardiovascular collapse. Always aspirate before injecting."}, {"alert_type": "Methemoglobinemia", "severity": "High", "trigger_condition": "Cyanosis, headache, or shortness of breath post-injection", "message": "STOP: Local anesthetics can cause methemoglobinemia. If cyanosis unresponsive to oxygen occurs, suspect methemoglobinemia and treat with methylene blue."}]', '**Systemic Toxicity (LAST):** Local Anesthetic Systemic Toxicity (LAST) can occur due to accidental intravascular injection or excessive dosing. Symptoms progress from CNS excitation (tinnitus, metallic taste, perioral numbness, seizures) to CNS depression (coma, respiratory arrest) and cardiovascular collapse.
INSERT INTO "drug_generic" VALUES(1631, 'Crizotinib', 'Crizotinib', 'L01ED01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated transaminases or bilirubin during therapy", "message": "STOP: Fatal hepatotoxicity has occurred. Monitor liver function tests periodically. Temporarily suspend, dose reduce, or permanently discontinue based on severity."}, {"alert_type": "Interstitial Lung Disease (ILD) / Pneumonitis", "severity": "High", "trigger_condition": "New or worsening pulmonary symptoms (dyspnea, cough, fever)", "message": "STOP: Severe, life-threatening, or fatal ILD/pneumonitis can occur. Permanently discontinue crizotinib in patients diagnosed with treatment-related ILD/pneumonitis."}]', '**Hepatotoxicity:** Drug-induced hepatotoxicity with fatal outcome has occurred. Monitor liver function tests (ALT, AST, and total bilirubin) every 2 weeks during the first 2 months of treatment, then once a month and as clinically indicated. Dose interruption, reduction, or permanent discontinuation may be required.
INSERT INTO "drug_generic" VALUES(1632, 'Lurasidone', 'Lurasidone', 'N05AE05', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Increased Mortality in Elderly Patients with Dementia-Related Psychosis", "severity": "High", "trigger_condition": "Use in elderly patients with dementia-related psychosis", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Lurasidone is not approved for the treatment of patients with dementia-related psychosis."}, {"alert_type": "Suicidal Thoughts and Behaviors", "severity": "High", "trigger_condition": "Use in children, adolescents, and young adults", "message": "Antidepressants and atypical antipsychotics increase the risk of suicidal thoughts and behaviors in pediatric and young adult patients. Monitor closely for clinical worsening and emergence of suicidal thoughts."}]', '**Neuroleptic Malignant Syndrome (NMS):** A potentially fatal symptom complex. Manage with immediate discontinuation, intensive symptomatic treatment, and close monitoring.
INSERT INTO "drug_generic" VALUES(1633, 'Menthol', 'Menthol', 'R02AA20', 0, 0, 1, 0, 0, 0, 0, 0, '[]', 'Consult a physician if a sore throat is severe, persists for more than 2 days, or is accompanied or followed by fever, headache, rash, swelling, nausea, or vomiting. Consult a physician if a cough persists for >1 week or recurs. Consult a physician if a sore throat does not improve in 7 days.', '- **Pharyngitis and Cough:** Used as an oral anesthetic and antitussive for the temporary relief of minor sore throat and throat irritation due to cough.', '- **Hypersensitivity:** Contraindicated in patients with a known allergy to menthol, soy, or other ingredients in the formulation.', '- Local irritation
INSERT INTO "drug_generic" VALUES(1634, 'Carboprost Tromethamine', 'Carboprost Tromethamine', 'G02AD04', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Strict Hospital Administration", "severity": "High", "trigger_condition": "Administration outside of a specialized hospital setting", "message": "STOP: Carboprost tromethamine is a potent oxytocic agent. It must only be administered by medically-trained personnel in a hospital setting equipped with immediate intensive care and acute surgical facilities."}]', '- **Cardiovascular/Pulmonary Disease:** Use with extreme caution in patients with a history of asthma, hypertension, hypotension, or cardiovascular disease. Transient bronchoconstriction and blood pressure alterations can occur.
INSERT INTO "drug_generic" VALUES(1635, 'Ambroxol', 'Ambroxol', 'R05CB06', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Severe Cutaneous Adverse Reactions (SCARs)", "severity": "High", "trigger_condition": "Appearance of skin rash or mucosal lesions", "message": "STOP: Severe skin reactions such as Erythema Multiforme, Stevens-Johnson syndrome (SJS), and Toxic Epidermal Necrolysis (TEN) have been reported. Discontinue immediately if a progressive skin rash occurs."}]', '**Gastrointestinal Ulceration:** Use with caution in patients with a history of gastric or duodenal ulceration, as mucolytics may disrupt the gastric mucosal barrier.
INSERT INTO "drug_generic" VALUES(1636, 'Loperamide', 'Loperamide', 'A07DA03', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Cardiac Toxicity", "severity": "High", "trigger_condition": "Doses exceeding the maximum recommended daily dose (16 mg/day)", "message": "STOP: Taking higher than recommended doses of loperamide can cause severe cardiac arrhythmias, including QT prolongation, Torsades de Pointes, syncope, and cardiac arrest, which may be fatal."}]', '**Cardiac Toxicity:** High doses of loperamide have been associated with serious cardiac arrhythmias, including QT prolongation, Torsades de Pointes, and cardiac arrest. Do not exceed the maximum recommended daily dose.
INSERT INTO "drug_generic" VALUES(1637, 'Polatuzumab vedotin', 'Polatuzumab vedotin', 'L01FX14', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Myelosuppression and Infection", "severity": "High", "trigger_condition": "During treatment cycles", "message": "STOP: Can cause severe neutropenia, thrombocytopenia, and fatal opportunistic infections. Monitor CBC closely. Administer prophylaxis for PCP and herpes virus."}]', '**Peripheral Neuropathy:** Can cause severe, cumulative peripheral neuropathy. Monitor for symptoms (e.g., hypoesthesia, neuropathic pain, weakness) and adjust dose or discontinue as necessary.
INSERT INTO "drug_generic" VALUES(1638, 'Dexamethasone 0.05% Eye ointment', 'Dexamethasone Ophthalmic', 'S01BA01', 0, 0, 1, 1, 0, 1, 0, 1, '[{"alert_type": "Ocular Infections and Glaucoma", "severity": "High", "trigger_condition": "Prolonged use or presence of viral/fungal eye infections", "message": "STOP: Corticosteroids can mask, activate, or exacerbate ocular infections. Contraindicated in epithelial herpes simplex keratitis and fungal/mycobacterial eye diseases. Prolonged use may cause elevated intraocular pressure (glaucoma) and cataracts."}]', '**Intraocular Pressure (IOP) Elevation:** Prolonged use may result in ocular hypertension and/or glaucoma, with damage to the optic nerve and defects in visual acuity. IOP should be monitored regularly if used for 10 days or longer.
INSERT INTO "drug_generic" VALUES(1639, 'Bisacodyl', 'Bisacodyl', 'A06AB02', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Fluid and Electrolyte Imbalance:** Prolonged or excessive use may lead to severe fluid and electrolyte abnormalities, including hypokalemia, which can precipitate arrhythmias and muscle weakness.
INSERT INTO "drug_generic" VALUES(1640, 'Brinzolamide + Brimonidine Tartrate eye prep', 'Brinzolamide and Brimonidine Tartrate Ophthalmic', 'S01EC54', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Pediatric Contraindication", "severity": "High", "trigger_condition": "Prescription for a child under 2 years of age", "message": "STOP: Contraindicated in neonates and infants under 2 years of age due to the risk of severe CNS depression, apnea, bradycardia, and hypotension associated with brimonidine."}]', '**Sulfonamide Hypersensitivity:** Brinzolamide is a sulfonamide. Although administered topically, systemic absorption occurs. Severe hypersensitivity reactions (e.g., Stevens-Johnson syndrome, toxic epidermal necrolysis) can occur. Discontinue immediately if signs of serious reactions or hypersensitivity appear.
INSERT INTO "drug_generic" VALUES(1641, 'Paracetamol + Chlorpheniramine + Dextromethorphan', 'Acetaminophen, Chlorpheniramine, and Dextromethorphan', 'N02BE51', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Exceeding maximum daily dose of paracetamol or concurrent alcohol use", "message": "STOP: Severe hepatotoxicity can occur if the maximum daily dose of paracetamol (4000 mg) is exceeded. Verify all concurrent medications to ensure no other paracetamol-containing products are being used."}]', '**Hepatotoxicity:** Paracetamol can cause severe, potentially fatal liver damage. Risk is increased in chronic alcoholics, patients with underlying hepatic impairment, or when combined with other paracetamol-containing products. Do not exceed the maximum recommended daily dose.
INSERT INTO "drug_generic" VALUES(1642, 'Enasidenib', 'Enasidenib', 'L01XM01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Differentiation Syndrome", "severity": "High", "trigger_condition": "Onset of unexplained fever, dyspnea, hypoxia, pulmonary infiltrates, or pleural/pericardial effusions", "message": "STOP: Differentiation syndrome, which can be fatal, has been reported. If suspected, immediately initiate systemic corticosteroids (e.g., dexamethasone 10 mg IV every 12 hours) and hemodynamic monitoring until symptoms resolve."}]', '**Differentiation Syndrome:** Patients treated with enasidenib may develop differentiation syndrome, characterized by rapid proliferation and differentiation of myeloid cells. Symptoms include fever, dyspnea, acute respiratory distress, pulmonary infiltrates, pleural or pericardial effusions, rapid weight gain, peripheral edema, and renal or hepatic dysfunction. If suspected, initiate systemic corticosteroids immediately and monitor hemodynamics closely.
INSERT INTO "drug_generic" VALUES(1643, 'Iron + Folic Acid + Zinc + Vitamin A + Vitamin C', 'Iron, Folic Acid, Zinc, Vitamin A, and Vitamin C', 'B03AE04', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Iron Toxicity", "severity": "High", "trigger_condition": "Accidental overdose in children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Vitamin A Toxicity:** Contains Vitamin A. Do not exceed the recommended dose during pregnancy, as high doses of preformed Vitamin A are teratogenic. Avoid concurrent use of other Vitamin A supplements.
INSERT INTO "drug_generic" VALUES(1644, 'Cyproterone Acetate + Ethinylestradiol', 'Cyproterone and Ethinyl Estradiol', 'G03HB01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Venous and Arterial Thromboembolism", "severity": "High", "trigger_condition": "Use of combined hormonal contraceptives/antiandrogens", "message": "WARNING: Increases the risk of venous thromboembolism (DVT, PE) and arterial thromboembolism (MI, stroke). Risk is higher in women >35 years who smoke. Discontinue immediately if a thromboembolic event occurs."}]', '**Thromboembolic Risk Factors:** Use with extreme caution in women with risk factors for VTE/ATE (e.g., obesity, hypertension, dyslipidemia, migraines, prolonged immobilization). Smoking significantly increases cardiovascular risks; women over 35 who smoke should not use this product.
INSERT INTO "drug_generic" VALUES(1645, 'Siltuximab', 'Siltuximab', 'L04AC11', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Infections and Gastrointestinal Perforation", "severity": "High", "trigger_condition": "During therapy", "message": "STOP: Siltuximab can cause severe infections and gastrointestinal perforation. Do not administer to patients with severe active infections. Monitor closely for signs of infection or acute abdominal pain."}]', '**Concurrent Infections:** Do not administer siltuximab to patients with severe active infections. Monitor patients closely for infections during treatment. Institute prompt anti-infective therapy and withhold siltuximab until the infection resolves.
INSERT INTO "drug_generic" VALUES(1646, 'Hydrochlorothiazide + Quinapril', 'Quinapril/Hydrochlorothiazide', 'C09BA06', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy", "message": "STOP: When pregnancy is detected, discontinue quinapril/hydrochlorothiazide as soon as possible. Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus."}]', '**Angioedema:** ACE inhibitors can cause angioedema of the face, extremities, lips, tongue, glottis, and larynx. Discontinue immediately if this occurs. Coadministration with mTOR inhibitors or neprilysin inhibitors increases this risk.
INSERT INTO "drug_generic" VALUES(1647, 'Dotinurad', 'Dotinurad', 'M04AB06', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '**Renal Function Monitoring:** Monitor renal function periodically during therapy. Although dotinurad is effective without affecting other transporters, increased urinary uric acid excretion can theoretically increase the risk of nephrolithiasis.
INSERT INTO "drug_generic" VALUES(1648, 'Bleomycin', 'Bleomycin', 'L01DC01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Pulmonary Toxicity and Idiosyncratic Reactions", "severity": "High", "trigger_condition": "Cumulative doses >400 units, elderly patients, or lymphoma patients receiving first doses", "message": "STOP: Severe, potentially fatal pulmonary fibrosis can occur (risk increases with cumulative doses >400 units). A severe idiosyncratic reaction (hypotension, confusion, fever, wheezing) occurs in ~1% of lymphoma patients; administer a test dose first."}]', '- **Pulmonary Toxicity:** Pneumonitis progressing to fatal pulmonary fibrosis occurs in ~10% of patients. Risk increases significantly in patients >70 years old and with cumulative doses >400 units. Monitor with frequent chest X-rays and pulmonary function tests (DLCO).
INSERT INTO "drug_generic" VALUES(1649, 'Paracetamol + Guaifenesin', 'Acetaminophen and Guaifenesin', 'N02BE51', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Exceeding maximum daily dose or concurrent alcohol use", "message": "STOP: Paracetamol (acetaminophen) can cause severe, potentially fatal hepatotoxicity. Do not exceed 4,000 mg per day from all sources. Avoid concurrent use of other paracetamol-containing products."}]', '**Hepatotoxicity:** Paracetamol has been associated with cases of acute liver failure, at times resulting in liver transplant and death. Most cases involve the use of paracetamol at doses that exceed 4,000 mg per day. Caution is advised in chronic alcoholics or patients with underlying hepatic disease.
INSERT INTO "drug_generic" VALUES(1650, 'Trelagliptin', 'Trelagliptin', 'A10BH08', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Hypoglycemia Risk", "severity": "High", "trigger_condition": "Concomitant use with insulin or insulin secretagogues (e.g., sulfonylureas)", "message": "STOP: Co-administration with other antidiabetic agents, particularly sulfonylureas or insulin, significantly increases the risk of severe hypoglycemia. Dose reduction of the concomitant agent may be required."}]', '**Renal Impairment:** Trelagliptin is primarily excreted via the kidneys. Patients with moderate to severe renal impairment require dose adjustments and close monitoring of renal function.
INSERT INTO "drug_generic" VALUES(1651, 'COVID-19 mRNA Vaccine (Moderna)', 'COVID-19 Vaccine, mRNA (Moderna)', 'J07BN01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe allergic reaction to any component of the vaccine", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before administration."}]', '**Anaphylaxis and Hypersensitivity:** Appropriate medical treatment used to manage immediate allergic reactions must be immediately available in the event an acute anaphylactic reaction occurs following administration.
INSERT INTO "drug_generic" VALUES(1652, 'Ferrous Ascorbate', 'Ferrous Ascorbate', 'B03AA10', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Iron Overload Risk", "severity": "High", "trigger_condition": "Patients with hemochromatosis, hemosiderosis, or hemolytic anemia", "message": "Contraindicated in patients with iron overload disorders. Routine use in hemolytic anemia is not recommended unless an iron-deficient state exists."}]', '**Iron Overload:** Care should be taken in patients who may develop iron overload, such as those with hemochromatosis, hemosiderosis, or hemolytic anemia.
INSERT INTO "drug_generic" VALUES(1653, 'Betaine + Polyhexanide topical', 'Betaine and Polyhexanide topical', 'D08AC05', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Administration Error", "severity": "High", "trigger_condition": "Inappropriate route of administration", "message": "For external use only on skin wounds. Do NOT infuse, inject, or ingest."}]', '- **External Use Only:** Strictly for topical application on skin wounds. Do not infuse, inject, or ingest.
INSERT INTO "drug_generic" VALUES(1654, 'Calaspargase pegol', 'Calaspargase pegol-mknl', 'L01XX86', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "During or shortly after intravenous infusion", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, can occur. Administer in a setting with resuscitation equipment. Observe patients for 1 hour post-infusion. Discontinue permanently if a serious reaction occurs."}, {"alert_type": "Pancreatitis", "severity": "High", "trigger_condition": "Severe abdominal pain, elevated amylase/lipase", "message": "WARNING: Severe and potentially fatal pancreatitis can occur. Evaluate patients with abdominal pain. Discontinue permanently if clinical pancreatitis is confirmed."}]', '**Hypersensitivity:** Observe patients for one hour after administration in a clinical setting equipped for resuscitation. Discontinue permanently in patients with serious hypersensitivity reactions.
INSERT INTO "drug_generic" VALUES(1655, 'Tezacaftor + Iivacaftor', 'Tezacaftor / Ivacaftor', 'R07AX31', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "Moderate", "trigger_condition": "Elevated transaminases during therapy", "message": "Elevated liver transaminases have been reported. Assess ALT and AST before initiating, every 3 months during the first year, and annually thereafter. Interrupt dosing if significant elevations occur."}]', '**Hepatotoxicity:** Ivacaftor may elevate liver transaminases. Assess ALT and AST before initiating therapy, every 3 months during the first year, and annually thereafter. Monitor more frequently in patients with a history of elevated transaminases. If transaminases are significantly elevated (e.g., ALT/AST >5x ULN, or ALT/AST >3x ULN with bilirubin >2x ULN), interrupt dosing and closely monitor until the abnormalities resolve.
INSERT INTO "drug_generic" VALUES(1656, 'Triamcinolone Acetonide Inhalation', 'Triamcinolone Acetonide', 'R03BA06', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Adrenal Insufficiency Risk", "severity": "High", "trigger_condition": "Transferring from systemic corticosteroids to inhaled corticosteroids", "message": "STOP: Deaths due to adrenal insufficiency have occurred in asthmatic patients during and after transfer from systemic corticosteroids to inhaled steroids. Taper systemic steroids gradually and monitor HPA axis function."}]', 'Monitor patients transferring from systemic corticosteroids closely for signs of adrenal insufficiency, especially during periods of stress or severe asthma attacks.
INSERT INTO "drug_generic" VALUES(1657, 'Crizanlizumab', 'Crizanlizumab-tmca', 'B06AX01', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Infusion-Related Reactions", "severity": "High", "trigger_condition": "During or within 24 hours of intravenous infusion", "message": "STOP: Severe infusion-related reactions can occur. Monitor for fever, chills, dyspnea, and urticaria. Discontinue infusion for severe reactions and institute medical care."}]', '**Infusion-Related Reactions:** Infusion-related reactions, defined as occurring within 24 hours of infusion, have been observed in clinical trials. Monitor patients closely for signs and symptoms, which may include fever, chills, nausea, vomiting, fatigue, dizziness, pruritus, urticaria, sweating, shortness of breath, or wheezing. If a severe reaction occurs, immediately discontinue the infusion and institute appropriate medical care.
INSERT INTO "drug_generic" VALUES(1658, 'Cytarabine', 'Cytarabine', 'L01BC01', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Severe Myelosuppression and CNS Toxicity", "severity": "High", "trigger_condition": "Administration of Cytarabine", "message": "STOP: Cytarabine is a potent bone marrow suppressant. High-dose regimens can cause severe, potentially fatal CNS toxicity (cerebellar dysfunction), GI toxicity, and pulmonary edema. Monitor CBC daily during induction."}]', '**Bone Marrow Suppression:** Cytarabine is a potent myelosuppressant. Severe leukopenia, thrombocytopenia, and anemia will occur. Patients must be under close medical supervision with daily leukocyte and platelet counts during induction therapy. Facilities must be available for managing fatal complications of bone marrow suppression (infection, hemorrhage).
INSERT INTO "drug_generic" VALUES(1659, 'Tulobuterol Hydrochloride', 'Tulobuterol', 'R03CC11', 0, 0, 0, 0, 1, 0, 1, 0, '[]', '**Cardiovascular Disease:** Use with caution in patients with myocardial insufficiency, arrhythmias, susceptibility to QT-interval prolongation, and hypertension, as beta-agonists can cause cardiovascular stimulation.
INSERT INTO "drug_generic" VALUES(1660, 'Isatuximab', 'Isatuximab-irfc', 'L01FC02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Infusion-Related Reactions", "severity": "High", "trigger_condition": "During or shortly after IV infusion", "message": "STOP: Severe infusion-related reactions can occur. Premedicate with dexamethasone, acetaminophen, and an H2-antagonist/diphenhydramine. Interrupt or slow infusion if a reaction occurs."}]', '**Neutropenia:** Severe neutropenia has been reported. Monitor complete blood cell counts periodically during treatment. Consider antibiotics and antiviral prophylaxis. If grade 4 neutropenia occurs, delay the dose until the neutrophil count recovers to at least 1 x 10^9/L, and provide supportive care with growth factors according to institutional guidelines.
INSERT INTO "drug_generic" VALUES(1661, 'Cetrimide 0.5% + Chlorhexidine Hydrochloride 0.1% Topical', 'Cetrimide and Chlorhexidine', 'D08AC52', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Moderate", "trigger_condition": "Application near sensitive areas", "message": "Avoid contact with the eyes, middle ear, meninges, and mucous membranes. If accidental contact occurs, rinse thoroughly with water immediately."}]', '**Hypersensitivity Reactions:** Prolonged and repeated use may increase the risk of hypersensitivity reactions, including contact dermatitis. Discontinue use if severe irritation or rash develops.
INSERT INTO "drug_generic" VALUES(1662, 'Omarigliptin', 'Omarigliptin', 'A10BH08', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Hypoglycemia Risk", "severity": "High", "trigger_condition": "Concomitant use with insulin or sulfonylureas", "message": "STOP: Co-administration with insulin preparations or sulfonylureas significantly increases the risk of severe hypoglycemia. Monitor blood glucose closely and consider reducing the dose of the insulin or sulfonylurea."}]', 'Dose adjustment is required in patients with severe renal impairment, end-stage renal failure, or those undergoing hemodialysis/peritoneal dialysis. Use with caution in patients with conditions predisposing to hypoglycemia (e.g., pituitary dysfunction, adrenal insufficiency, malnutrition, intense physical exertion, excessive alcohol intake, or the elderly). Caution should be taken in patients engaged in hazardous activities, such as operating machinery or driving, due to the risk of hypoglycemia. Monitor for signs of acute pancreatitis and bowel obstruction.', '- **Type 2 Diabetes Mellitus:** Indicated as an adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus, either as monotherapy or in combination with other oral antidiabetic agents.', '- **Hypersensitivity:** Contraindicated in patients with a history of severe hypersensitivity to omarigliptin or any of its components.
INSERT INTO "drug_generic" VALUES(1663, 'Micafungin', 'Micafungin', 'J02AX05', 1, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hypersensitivity and Hepatic Toxicity", "severity": "High", "trigger_condition": "Administration of IV infusion", "message": "STOP: Anaphylaxis, including shock, has been reported. Isolated cases of severe hepatic dysfunction, hepatitis, and hepatic failure have occurred. Monitor LFTs closely."}]', '**Hepatic Effects:** Abnormalities in liver function tests, hepatitis, and hepatic failure have been reported. Monitor liver function tests (LFTs) during therapy.
INSERT INTO "drug_generic" VALUES(1664, 'Prednisolone', 'Prednisolone', 'H02AB06', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Adrenal Suppression and Infection Risk", "severity": "High", "trigger_condition": "Long-term therapy or abrupt withdrawal", "message": "STOP: Prolonged use causes HPA axis suppression. Do not discontinue abruptly; taper gradually. Corticosteroids mask signs of infection and increase susceptibility to severe, potentially fatal infections."}]', '- **HPA Axis Suppression:** Prolonged use suppresses the hypothalamic-pituitary-adrenal axis. Abrupt withdrawal can lead to acute adrenal crisis. Tapering is mandatory.
INSERT INTO "drug_generic" VALUES(1665, 'Liquid Paraffin + Magnesium Hydroxide', 'Mineral Oil and Magnesium Hydroxide', 'A06AA51', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Aspiration Risk", "severity": "High", "trigger_condition": "Use in bedridden patients, elderly, or those with dysphagia", "message": "STOP: Oral administration of liquid paraffin (mineral oil) in patients with impaired swallowing or altered mental status can lead to silent aspiration and severe, potentially fatal lipoid pneumonia."}]', '- **Aspiration Risk:** Avoid use in bedridden patients, the elderly, infants, or anyone with difficulty swallowing or impaired neurodevelopment due to the high risk of aspiration leading to lipoid pneumonia.
INSERT INTO "drug_generic" VALUES(1666, 'Ferrous Sulphate', 'Ferrous Sulfate', 'B03AA07', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Fatal Poisoning in Children", "severity": "High", "trigger_condition": "Accidental ingestion by children under 6 years of age", "message": "WARNING: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Gastrointestinal Conditions:** Use with caution in patients with existing GI diseases such as inflammatory bowel disease, intestinal strictures, diverticulae, peptic ulcer disease, enteritis, or ulcerative colitis, as oral iron may exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1667, 'Gefapixant', 'Gefapixant', 'R05DB29', 0, 0, 0, 0, 1, 1, 0, 0, '[]', 'Use with caution in patients with a known hypersensitivity to medicinal products containing active substances from the sulfonamide class, as cross-reactivity may occur. Monitor for severe taste disturbances, which may impact the patient''s appetite and nutritional intake.', '- **Chronic Cough:** Indicated for the treatment of refractory chronic cough or unexplained chronic cough in adults.', '- **Hypersensitivity:** Contraindicated in patients who are hypersensitive to gefapixant or any of its excipients.
INSERT INTO "drug_generic" VALUES(1668, 'Tapinarof topical', 'Tapinarof', 'D05AX06', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "External Use Only", "severity": "Low", "trigger_condition": "Application to eyes, mouth, or vagina", "message": "For external use only. Do not apply to the eyes, mouth, or vagina. Apply only to affected skin lesions."}]', '**Application Site Reactions:** May cause local adverse reactions, including folliculitis and contact dermatitis. Apply the medication strictly to skin lesions only, and avoid unaffected areas of skin to minimize irritation.
INSERT INTO "drug_generic" VALUES(1669, 'Polymyxin B', 'Polymyxin B', 'J01XB02', 1, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Nephrotoxicity and Neurotoxicity", "severity": "High", "trigger_condition": "Systemic administration (IV/IM) or concurrent use with other nephrotoxic/neurotoxic drugs", "message": "STOP: Systemic administration can cause severe nephrotoxicity and neurotoxicity (including potentially fatal respiratory paralysis). Monitor renal function closely and avoid concurrent use with neuromuscular blockers or other toxic agents."}]', '**Nephrotoxicity:** High risk of dose-dependent renal damage. Discontinue therapy if diminished urine output, rising serum creatinine (SCr) or blood urea nitrogen (BUN) occurs.
INSERT INTO "drug_generic" VALUES(1670, 'Olopatadine 0.7% Eye prep', 'Olopatadine Ophthalmic', 'S01GX09', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Contamination Risk", "severity": "Moderate", "trigger_condition": "Improper handling of the dropper tip", "message": "Improper handling may contaminate the solution with bacteria, leading to severe ocular infections. Do not allow the dropper tip to touch the eye, eyelids, or surrounding structures."}]', '**Contact Lens Use:** Not intended for the treatment of contact lens-related irritation. Patients should be advised to remove contact lenses prior to instillation of the eye drops. The preservative in the formulation (benzalkonium chloride) may be absorbed by soft contact lenses. Lenses may be reinserted 10 minutes following administration. Do not wear contact lenses if eyes are red.
INSERT INTO "drug_generic" VALUES(1671, 'Neomycin Sulphate 0.4% + Polymixin B Sulphate + Pramoxine 1% Topical', 'Neomycin / Polymyxin B / Pramoxine Topical', 'D06AX', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Systemic Toxicity", "severity": "Moderate", "trigger_condition": "Application to large surface areas or prolonged use", "message": "Caution: Application to large areas of denuded skin or prolonged use may result in systemic absorption of neomycin, leading to potential ototoxicity and nephrotoxicity."}]', '- **Systemic Absorption:** Possibility of ototoxicity and nephrotoxicity if used in large quantities, over large body surface areas, or for prolonged periods, especially in patients with impaired renal function.
INSERT INTO "drug_generic" VALUES(1672, 'Amikacin', 'Amikacin', 'J01GB06', 1, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Nephrotoxicity and Ototoxicity", "severity": "High", "trigger_condition": "Prolonged use, high doses, or underlying renal impairment", "message": "STOP: Aminoglycosides cause severe, potentially irreversible ototoxicity (auditory and vestibular) and nephrotoxicity. Monitor renal function and serum peak/trough levels closely."}, {"alert_type": "Neuromuscular Blockade", "severity": "High", "trigger_condition": "Concurrent use with anesthetics or muscle relaxants", "message": "STOP: Can cause severe neuromuscular blockade and respiratory paralysis. Use with extreme caution in patients with myasthenia gravis or those receiving neuromuscular blockers."}]', '**Ototoxicity:** High-frequency deafness usually occurs first and may be asymptomatic. Vertigo may indicate vestibular injury. Risk increases with prolonged therapy (>14 days), renal impairment, and concurrent use of loop diuretics.
INSERT INTO "drug_generic" VALUES(1673, 'Azelastine Hydrochloride Nasal prep', 'Azelastine Nasal', 'R01AC03', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "CNS Depression", "severity": "Medium", "trigger_condition": "Concurrent use with alcohol or other CNS depressants", "message": "STOP: Azelastine can cause significant somnolence and CNS depression. Avoid concurrent use with alcohol or other CNS depressants. Caution patients about driving or operating heavy machinery."}]', '**Somnolence:** Somnolence has been reported in some patients taking azelastine nasal spray. Patients should be cautioned against engaging in hazardous occupations requiring complete mental alertness.
INSERT INTO "drug_generic" VALUES(1674, 'Glycine 1.5% Irrigation solution', 'Glycine Irrigation', 'Data not available', 0, 0, 1, 1, 1, 0, 0, 0, '[{"alert_type": "TURP Syndrome Risk", "severity": "High", "trigger_condition": "Prolonged surgical procedures or open venous sinuses", "message": "STOP: Systemic absorption of large volumes of glycine irrigation can lead to TURP syndrome, characterized by severe fluid overload, dilutional hyponatremia, and hyperammonemia. Monitor electrolytes and fluid balance closely."}]', '**Fluid Overload and Hyponatremia:** Intravascular absorption of glycine can cause significant fluid expansion and dilutional hyponatremia, leading to pulmonary edema, cerebral edema, and cardiovascular collapse.
INSERT INTO "drug_generic" VALUES(1675, 'Betrixaban', 'Betrixaban', 'B01AF04', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Spinal/Epidural Hematoma", "severity": "High", "trigger_condition": "Neuraxial anesthesia or spinal puncture", "message": "STOP: Epidural or spinal hematomas may occur in patients receiving neuraxial anesthesia or undergoing spinal puncture, potentially resulting in long-term or permanent paralysis. Consider risks when scheduling spinal procedures."}]', '**Spinal/Epidural Hematoma:** Risk is increased by the use of indwelling epidural catheters or concomitant use of medical products affecting hemostasis (e.g., NSAIDs, platelet inhibitors, other anticoagulants). Monitor frequently for signs of neurological impairment.
INSERT INTO "drug_generic" VALUES(1676, 'Panitumumab', 'Panitumumab', 'L01FE02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Dermatologic Toxicity and Infusion Reactions", "severity": "High", "trigger_condition": "During therapy or infusion", "message": "STOP: Severe dermatologic toxicities (acneiform rash, skin fissures, severe infections) and severe infusion reactions can occur. Monitor closely and withhold or discontinue therapy for severe reactions."}]', '**Dermatologic Toxicity:** Severe dermatologic toxicities, including acneiform dermatitis, pruritus, erythema, rash, skin exfoliation, paronychia, dry skin, and skin fissures, occur frequently. Life-threatening and fatal infectious sequelae (e.g., necrotizing fasciitis, sepsis) have been reported. Monitor for dermatologic toxicities and infectious sequelae. Limit sun exposure.
INSERT INTO "drug_generic" VALUES(1677, 'Probiotic Combination', 'Probiotic Combination', 'A07FA51', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Systemic Infection Risk", "severity": "High", "trigger_condition": "Use in severely immunocompromised patients or those with central venous catheters", "message": "STOP: Avoid use in severely immunocompromised patients or premature infants due to the risk of systemic bacteremia or fungemia."}]', '**Immunocompromised Patients:** Use with extreme caution or avoid in patients with severe immunodeficiency (e.g., advanced HIV, immunosuppressive therapy, leukemia) due to the risk of opportunistic systemic infections (bacteremia or fungemia) originating from the probiotic strains.
INSERT INTO "drug_generic" VALUES(1678, 'Hydrogen Peroxide', 'Hydrogen Peroxide', 'D08AX01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "High", "trigger_condition": "Use in deep wounds or closed body cavities", "message": "STOP: Do not inject or instill into closed body cavities. The rapid release of oxygen gas can cause fatal gas embolism or tissue rupture. Do not use on deep wounds, animal bites, or serious burns."}]', '**Tissue Damage:** Prolonged or repeated use on wounds can delay healing by damaging newly formed granulation tissue and fibroblasts. Use should be limited to initial wound cleansing.
INSERT INTO "drug_generic" VALUES(1679, 'Prasugrel', 'Prasugrel', 'B01AC22', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Fatal Bleeding Risk", "severity": "High", "trigger_condition": "Active pathological bleeding or history of TIA/stroke", "message": "STOP: Prasugrel can cause significant, sometimes fatal, bleeding. Do not use in patients with active bleeding or a history of transient ischemic attack (TIA) or stroke."}]', 'Use with extreme caution in patients with a propensity to bleed (e.g., recent trauma, recent surgery, recent or recurrent gastrointestinal bleeding, or active peptic ulcer disease).
INSERT INTO "drug_generic" VALUES(1680, 'Methylphenidate Hydrochloride', 'Methylphenidate', 'N06BA04', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Abuse and Dependence", "severity": "High", "trigger_condition": "Prescription initiation and ongoing therapy", "message": "STOP: High potential for abuse and dependence. Assess risk of abuse prior to prescribing and monitor for signs of misuse and addiction during therapy."}, {"alert_type": "Cardiovascular Events", "severity": "High", "trigger_condition": "Patients with structural cardiac abnormalities", "message": "STOP: Sudden death, stroke, and myocardial infarction have been reported. Avoid use in patients with known structural cardiac abnormalities, cardiomyopathy, or serious arrhythmias."}]', 'Monitor blood pressure and heart rate at baseline and periodically during therapy, as it can cause significant elevations. Use with extreme caution in patients with pre-existing psychosis, bipolar disorder, or a history of seizures, as it may exacerbate symptoms or lower the seizure threshold. Monitor pediatric patients for growth suppression (height and weight) during prolonged therapy; treatment interruption may be necessary if growth trajectories are not met. May cause peripheral vasculopathy, including Raynaud''s phenomenon. Prolonged erection or priapism has been reported; advise immediate medical attention if an erection lasts longer than 4 hours. Taper dose gradually upon discontinuation to prevent severe withdrawal depression.', '- Treatment of Attention-Deficit/Hyperactivity Disorder (ADHD) in children, adolescents, and adults.
INSERT INTO "drug_generic" VALUES(1681, 'Mirabegron', 'Mirabegron', 'G04BD12', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Hypertension", "severity": "High", "trigger_condition": "Patient with severe uncontrolled hypertension (systolic >180 mm Hg or diastolic >110 mm Hg)", "message": "STOP: Mirabegron can increase blood pressure and is contraindicated in patients with severe uncontrolled hypertension. Monitor blood pressure periodically during treatment."}]', '- **Blood Pressure:** Can increase blood pressure. Measure blood pressure at baseline and periodically during treatment. Use with caution in patients with a history of hypertension.
INSERT INTO "drug_generic" VALUES(1682, 'Codeine sulfate', 'Codeine sulfate', 'R05DA04', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Respiratory Depression and CYP2D6 Metabolism", "severity": "High", "trigger_condition": "Use in children, post-tonsillectomy, or ultra-rapid metabolizers", "message": "STOP: Life-threatening respiratory depression and death have occurred in children who received codeine. It is contraindicated in children <12 years and for post-operative pain management in children <18 years following tonsillectomy/adenoidectomy. Ultra-rapid CYP2D6 metabolizers are at high risk of fatal toxicity."}]', '**Addiction, Abuse, and Misuse:** Risk of opioid addiction, abuse, and misuse, which can lead to overdose and death. Assess each patient’s risk prior to prescribing and monitor all patients regularly for the development of these behaviors or conditions.
INSERT INTO "drug_generic" VALUES(1683, 'Goserelin', 'Goserelin', 'L02AE03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Tumor Flare Risk", "severity": "High", "trigger_condition": "Initiation of therapy in prostate or breast cancer", "message": "STOP: Transient worsening of tumor symptoms (tumor flare) can occur during the first few weeks of treatment, potentially causing spinal cord compression or urinary tract obstruction. Monitor closely and consider concurrent antiandrogen therapy."}]', 'Monitor men at risk for urinary tract obstruction or spinal cord compression closely during the first month of therapy; transient increases in testosterone can exacerbate symptoms.
INSERT INTO "drug_generic" VALUES(1684, 'Strontium Renalate', 'Strontium Ranelate', 'M05BX03', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Cardiovascular and Thromboembolic Risk", "severity": "High", "trigger_condition": "Patients with a history of ischemic heart disease, peripheral arterial disease, cerebrovascular disease, or VTE", "message": "STOP: Strontium ranelate is contraindicated in patients with a history of cardiovascular disease or venous thromboembolism due to an increased risk of myocardial infarction and severe thromboembolic events."}]', 'Evaluate cardiovascular risk before starting treatment and regularly thereafter. Treatment should be stopped if the patient develops ischemic heart disease, peripheral arterial disease, cerebrovascular disease, or uncontrolled hypertension. Use with caution in patients at increased risk of venous thromboembolism (VTE); discontinue temporarily during periods of prolonged immobilization (e.g., post-surgical recovery, bed rest). Monitor for severe allergic reactions, including Drug Rash with Eosinophilia and Systemic Symptoms (DRESS), Stevens-Johnson syndrome (SJS), and toxic epidermal necrolysis (TEN); discontinue immediately and permanently if a severe rash occurs. Not recommended in patients with severe renal impairment (CrCl < 30 mL/min).', '- **Severe Postmenopausal Osteoporosis:** Indicated for the treatment of severe osteoporosis in postmenopausal women at high risk for fracture to reduce the risk of vertebral and hip fractures, specifically when other treatments are contraindicated or not tolerated.
INSERT INTO "drug_generic" VALUES(1685, 'Salmon Oil', 'Salmon Oil', 'C10AX06', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Use with caution in patients with liver disease or those taking anticoagulant medications, as high doses of fish oil might increase the risk of bleeding. High doses may also reduce immune system activity. Caution in patients with bipolar disorder, depression, or diabetes, as high doses may exacerbate symptoms or complicate blood sugar control.', '- **Hypertriglyceridemia:** Adjunct to diet to reduce triglyceride levels.
INSERT INTO "drug_generic" VALUES(1686, 'Saroglitazar', 'Saroglitazar', 'Data not available', 0, 0, 0, 0, 1, 0, 0, 0, '[]', '**Hepatic and Renal Function:** Initiate with caution in patients with abnormal liver or renal function, or a history of myopathies, although clinical studies have not demonstrated significant derangement.
INSERT INTO "drug_generic" VALUES(1687, 'Lutetium Lu 177 dotatate', 'Lutetium Lu 177 dotatate', 'V10XX04', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Radiation Exposure and Myelosuppression", "severity": "High", "trigger_condition": "Administration of radiopharmaceutical", "message": "STOP: Drug contributes to long-term cumulative radiation exposure. Severe myelosuppression, secondary myelodysplastic syndrome, and leukemia have been reported. Monitor blood counts closely."}]', '**Radiation Exposure:** Contributes to overall long-term cumulative radiation exposure, which is associated with an increased risk for cancer. Radiation can be detected in the urine for up to 30 days. Minimize radiation exposure to patients, medical personnel, and household contacts using institutional good radiation safety practices.
INSERT INTO "drug_generic" VALUES(1688, 'Sitagliptin', 'Sitagliptin', 'A10BH01', 0, 0, 1, 0, 1, 1, 0, 0, '[{"alert_type": "Acute Pancreatitis Risk", "severity": "High", "trigger_condition": "Patient presenting with severe, persistent abdominal pain", "message": "STOP: Cases of acute pancreatitis, including fatal and non-fatal hemorrhagic or necrotizing pancreatitis, have been reported. Discontinue immediately if pancreatitis is suspected."}]', 'Use with caution in patients with a history of pancreatitis, as it is unknown if they are at an increased risk of developing pancreatitis while on sitagliptin. Monitor for signs of hypersensitivity reactions, including anaphylaxis, angioedema, and exfoliative skin conditions (e.g., Stevens-Johnson syndrome); discontinue immediately if suspected. Severe and disabling arthralgia has been reported in patients taking DPP-4 inhibitors; consider discontinuing if severe joint pain occurs. Cases of bullous pemphigoid requiring hospitalization have been reported; advise patients to report blisters or erosions. Assess renal function prior to initiation of therapy and periodically thereafter, as dosage adjustments are required for moderate to severe renal impairment. Monitor glycosylated Hb (HbA1c) and serum glucose to assess efficacy.', '- **Type 2 Diabetes Mellitus:** Indicated as an adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus. It can be used as monotherapy or in combination with other antidiabetic agents (e.g., metformin, sulfonylureas, thiazolidinediones, or insulin) when diet, exercise, and single agents do not result in adequate glycemic control.
INSERT INTO "drug_generic" VALUES(1689, 'Dextrose 5% + Sodium Chloride 0.45%', 'Dextrose 5% and Sodium Chloride 0.45%', 'B05BB02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Fluid and Solute Overload", "severity": "Moderate", "trigger_condition": "Administration in patients with congestive heart failure or severe renal insufficiency", "message": "Caution: Can cause significant fluid overload, pulmonary edema, and electrolyte disturbances. Monitor fluid balance and electrolytes closely."}]', '**Fluid and Electrolyte Overload:** Administration can cause fluid and/or solute overload resulting in dilution of serum electrolyte concentrations, overhydration, congested states, or pulmonary edema. Use with caution in patients with congestive heart failure or severe renal insufficiency.
INSERT INTO "drug_generic" VALUES(1690, 'Aclidinium Bromide + Formoterol Fumarate', 'Aclidinium and Formoterol', 'R03AL05', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Asthma Contraindication", "severity": "High", "trigger_condition": "Use in asthma patients without an ICS", "message": "STOP: Long-acting beta2-adrenergic agonists (LABA), such as formoterol, increase the risk of asthma-related death when used as monotherapy without an inhaled corticosteroid. This product is NOT indicated for the treatment of asthma."}, {"alert_type": "Acute Bronchospasm", "severity": "High", "trigger_condition": "Use during acute COPD exacerbation", "message": "STOP: Do not initiate in acutely deteriorating COPD or use to treat acute symptoms. A short-acting rescue inhaler must be used for acute relief."}]', '**Paradoxical Bronchospasm:** Can produce paradoxical bronchospasm, which may be life-threatening. If it occurs, discontinue immediately and institute alternative therapy.
INSERT INTO "drug_generic" VALUES(1691, 'Somatostatin', 'Somatostatin', 'H01CB01', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Glycemic Fluctuations", "severity": "High", "trigger_condition": "Initiation of continuous IV infusion", "message": "Continuous infusion can cause significant hypoglycemia followed by hyperglycemia. Monitor blood glucose levels every 4-6 hours during therapy."}]', 'Monitor blood glucose levels frequently, as somatostatin inhibits the secretion of both insulin and glucagon, leading to initial hypoglycemia followed by potential hyperglycemia. Monitor cardiovascular status, as rapid intravenous administration can cause bradycardia and hypotension. Assess nutritional status; somatostatin inhibits intestinal absorption of nutrients, and concomitant parenteral nutrition may be required during prolonged use. Use with caution in patients with renal impairment, as the drug is primarily excreted by the kidneys.', '- **Acute Gastrointestinal Hemorrhage:** Management of severe acute bleeding from esophageal varices or peptic ulcers.
INSERT INTO "drug_generic" VALUES(1692, 'Methylcobalamin + Selenium + Vitamin A+E + Zinc', 'Methylcobalamin, Selenium, Vitamin A, Vitamin E, and Zinc', 'A11JC', 0, 0, 1, 1, 1, 0, 0, 0, '[{"alert_type": "Vitamin A Toxicity", "severity": "Moderate", "trigger_condition": "Concurrent use of other Vitamin A supplements or retinoids", "message": "WARNING: Avoid exceeding the recommended daily allowance of Vitamin A. Excessive intake can lead to hypervitaminosis A, characterized by hepatotoxicity and teratogenicity."}]', '**Hepatic Impairment:** Use with caution in patients with liver disease, as Vitamin A is stored in the liver and can accumulate to toxic levels.
INSERT INTO "drug_generic" VALUES(1693, 'Calcium Orotate', 'Calcium Orotate', 'A12AA', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Renal Impairment and Nephrolithiasis:** Use with caution in patients with kidney disease or a history of kidney stones; monitor serum calcium levels.
INSERT INTO "drug_generic" VALUES(1694, 'Acyclovir IV', 'Acyclovir', 'J05AB01', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Renal Toxicity", "severity": "High", "trigger_condition": "Rapid intravenous infusion or inadequate hydration", "message": "STOP: Acyclovir can precipitate in the renal tubules, causing acute renal failure. Infuse slowly over at least 1 hour and ensure adequate patient hydration before and during administration."}]', '**Renal Impairment:** Acute renal failure, sometimes resulting in death, has occurred. Risk is increased with rapid infusion, dehydration, pre-existing renal disease, or concurrent use of nephrotoxic drugs. Maintain adequate hydration and adjust dose based on creatinine clearance.
INSERT INTO "drug_generic" VALUES(1695, 'Dextromethorphan Hydrobromide', 'Dextromethorphan', 'R05DA09', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Drug Interaction", "severity": "High", "trigger_condition": "Concurrent use of MAOIs", "message": "STOP: Contraindicated in patients receiving Monoamine Oxidase Inhibitors (MAOIs) or within 14 days of stopping MAOI therapy due to the risk of fatal serotonin syndrome."}]', '**Chronic Cough:** Do not use for persistent or chronic cough associated with smoking, asthma, chronic bronchitis, or emphysema, or if the cough is accompanied by excessive phlegm, as suppression of the cough reflex can lead to retention of secretions.
INSERT INTO "drug_generic" VALUES(1696, 'Metformin Hydrochloride + Vildagliptin', 'Metformin and Vildagliptin', 'A10BD08', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Lactic Acidosis and Hepatotoxicity Risk", "severity": "High", "trigger_condition": "Patient with severe renal impairment (eGFR < 30 mL/min) or hepatic impairment (ALT/AST > 3x ULN)", "message": "STOP: Metformin can cause fatal lactic acidosis. Vildagliptin can cause hepatotoxicity. Contraindicated in severe renal impairment and hepatic impairment."}]', '**Hepatotoxicity:** Vildagliptin has been associated with rare cases of hepatic dysfunction (including hepatitis). Liver function tests (LFTs) must be monitored prior to initiation, at three-month intervals during the first year, and periodically thereafter. Discontinue if ALT or AST remains > 3x the upper limit of normal or if jaundice occurs.
INSERT INTO "drug_generic" VALUES(1697, 'Eltrombopag Olamine', 'Eltrombopag', 'B02BX05', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated ALT/AST or bilirubin during therapy", "message": "STOP: Eltrombopag can cause severe and potentially fatal hepatotoxicity. Monitor liver function tests prior to initiation, every 2 weeks during the dose adjustment phase, and monthly thereafter."}]', '**Hepatotoxicity:** Can cause severe hepatotoxicity. Measure serum ALT, AST, and bilirubin prior to initiation, every 2 weeks during the dose adjustment phase, and monthly following establishment of a stable dose. Discontinue if ALT levels increase to ≥3x ULN and are progressive, persistent, or accompanied by increased bilirubin.
INSERT INTO "drug_generic" VALUES(1698, 'Galcanezumab', 'Galcanezumab-gnlm', 'N02CD02', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Administration of the drug", "message": "Hypersensitivity reactions (e.g., rash, urticaria, dyspnea) can occur days after administration and may be prolonged. Discontinue immediately if a serious reaction occurs."}]', '**Hypersensitivity Reactions:** Serious hypersensitivity reactions, including rash, urticaria, and dyspnea, have been reported. These reactions may occur days after administration and can be prolonged due to the long half-life of the monoclonal antibody. If a serious hypersensitivity reaction occurs, discontinue administration immediately and initiate appropriate medical therapy.', '- **Migraine Prophylaxis:** Indicated for the preventive treatment of migraine in adults.
INSERT INTO "drug_generic" VALUES(1699, 'Betamethasone Dipropionate 0.05 % + Salicylic Acid 3 % topical', 'Betamethasone Dipropionate + Salicylic Acid', 'D07XC01', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Systemic Absorption Risk", "severity": "High", "trigger_condition": "Application to large surface areas, prolonged use, or use under occlusion", "message": "STOP: Systemic absorption of topical corticosteroids can produce reversible HPA axis suppression, Cushing''s syndrome, and hyperglycemia. Salicylic acid toxicity (salicylism) may also occur."}]', '- **Systemic Absorption:** Application over extensive body surface areas, prolonged use, or the use of occlusive dressings increases the systemic absorption of both betamethasone and salicylic acid, potentially leading to hypothalamic-pituitary-adrenal (HPA) axis suppression and salicylism.
INSERT INTO "drug_generic" VALUES(1700, 'Paracetamol + Doxylamine + Phenylephrine', 'Acetaminophen, Doxylamine, and Phenylephrine', 'N02BE51', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity and CNS Depression", "severity": "High", "trigger_condition": "Exceeding maximum daily dose or concurrent use with alcohol/CNS depressants", "message": "STOP: Paracetamol can cause severe, potentially fatal hepatotoxicity. Do not exceed 4,000 mg per day. Doxylamine causes profound sedation; avoid concurrent use with alcohol or other CNS depressants."}]', '**Hepatotoxicity:** Paracetamol has been associated with cases of acute liver failure, at times resulting in liver transplant and death. Most cases involve the use of paracetamol at doses that exceed 4,000 mg per day. Caution is advised in chronic alcoholics or patients with underlying hepatic disease.
INSERT INTO "drug_generic" VALUES(1701, 'Norgestrel + Ethinyl Estradiol', 'Norgestrel and Ethinyl Estradiol', 'G03AA07', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk and Smoking", "severity": "High", "trigger_condition": "Women over 35 years old who smoke", "message": "STOP: Cigarette smoking increases the risk of serious cardiovascular events from combination oral contraceptive use. This risk increases with age, particularly in women over 35 years of age, and with the number of cigarettes smoked. Contraindicated in women over 35 who smoke."}]', 'Monitor blood pressure closely; discontinue if significant elevation occurs. Use with caution in patients with a history of depression, migraine, fluid retention, or hyperlipidemias. Evaluate patients for risk factors of venous thromboembolism (VTE) prior to initiation. Discontinue therapy if jaundice, visual disturbances, or severe migraines develop. May alter glucose tolerance; monitor diabetic patients closely. Efficacy may be reduced by severe gastrointestinal upset (vomiting/diarrhea) or missed pills, requiring backup contraception.', '- **Contraception:** Prevention of pregnancy in women who elect to use oral contraceptives as a method of contraception.', '**High Risk of Arterial or Venous Thrombotic Diseases:** Contraindicated in patients with a history of DVT, PE, cerebrovascular disease, coronary artery disease, thrombogenic valvular disease, or inherited thrombophilias.
INSERT INTO "drug_generic" VALUES(1702, 'Nandrolone', 'Nandrolone', 'A14AB01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hepatotoxicity and Virilization", "severity": "High", "trigger_condition": "Prolonged use or use in females/children", "message": "STOP: Anabolic steroids can cause severe hepatic dysfunction, including peliosis hepatis and liver tumors. In females, monitor closely for signs of virilization (deepening of voice, hirsutism, clitoromegaly), which may be irreversible even after discontinuation."}]', '- **Cardiovascular/Renal Disease:** Use with extreme caution in patients with conditions influenced by fluid retention and edema (e.g., heart failure, hypertension, migraine, seizure disorders, renal impairment).
INSERT INTO "drug_generic" VALUES(1703, 'Bacillus calmette-Guerin strain (BCG vaccine)', 'BCG Vaccine', 'J07AN01', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Systemic BCG Infection", "severity": "High", "trigger_condition": "Intravesical administration in patients with traumatic catheterization, active UTI, or gross hematuria", "message": "STOP: Severe, life-threatening systemic BCG infections (BCG sepsis) can occur. Do NOT administer intravesically within 2-3 weeks of transurethral resection (TUR), bladder biopsy, or traumatic catheterization."}]', '- **Administration Route:** Ensure correct route. Use intradermal injection for TB vaccination. Use intravesical instillation for bladder cancer. NEVER administer intravenously, subcutaneously, or intramuscularly.
INSERT INTO "drug_generic" VALUES(1704, 'Basiliximab', 'Basiliximab', 'L04AC02', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hypersensitivity and Anaphylaxis", "severity": "High", "trigger_condition": "Administration of the drug", "message": "STOP: Severe acute hypersensitivity reactions, including anaphylaxis, have been reported both with initial and subsequent exposures. Medications for the treatment of severe hypersensitivity must be readily available."}]', '- **Prescriber Expertise:** Should be prescribed only by physicians experienced with immunosuppression in organ transplant recipients who can provide necessary follow-up and monitoring.
INSERT INTO "drug_generic" VALUES(1705, 'Dronabinol', 'Dronabinol', 'A04AD10', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Psychiatric and Hemodynamic Effects", "severity": "High", "trigger_condition": "Patients with a history of psychiatric disorders or cardiovascular disease", "message": "May cause significant psychiatric effects (mania, depression, schizophrenia exacerbation) and hemodynamic instability (hypotension, hypertension, syncope, tachycardia). Monitor closely."}]', '**Neurologic and Psychiatric Effects:** May cause psychiatric and cognitive effects and impair mental and/or physical abilities. Monitor patients with mania, depression, or schizophrenia, as dronabinol may exacerbate these illnesses. Avoid in patients with a psychiatric history. Reduce the dose or discontinue use if signs or symptoms of cognitive impairment develop.
INSERT INTO "drug_generic" VALUES(1706, 'Pseudoephedrine + Triprolidine', 'Pseudoephedrine and Triprolidine', 'R01BA52', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hypertensive Crisis Risk", "severity": "High", "trigger_condition": "Concurrent use with Monoamine Oxidase Inhibitors (MAOIs)", "message": "STOP: Concurrent use with MAOIs, or use within 14 days of stopping an MAOI, is strictly contraindicated due to the risk of severe, potentially fatal hypertensive crisis."}]', '- **Cardiovascular Disease:** Use with caution in patients with hypertension, ischemic heart disease, or arrhythmias due to the sympathomimetic effects of pseudoephedrine.
INSERT INTO "drug_generic" VALUES(1707, 'Ethinyl Estradiol + Levonorgestrel + Ferrous Fumarate', 'Ethinyl Estradiol, Levonorgestrel, and Ferrous Fumarate', 'G03AA07', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk and Smoking", "severity": "High", "trigger_condition": "Women over 35 years old who smoke", "message": "STOP: Cigarette smoking increases the risk of serious cardiovascular events from combination oral contraceptives (COCs). This risk increases with age, particularly in women over 35 years of age, and with the number of cigarettes smoked. COCs are contraindicated in women over 35 years of age who smoke."}]', '**Thromboembolic Disorders:** Stop this pill if a thrombotic event occurs. Discontinue at least 4 weeks before and through 2 weeks after major surgery. Start no earlier than 4 weeks after delivery in women who are not breastfeeding.
INSERT INTO "drug_generic" VALUES(1708, 'Phenylephrine nasal prep', 'Phenylephrine', 'R01AA04', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Rebound Congestion Risk", "severity": "High", "trigger_condition": "Use exceeding 3 consecutive days", "message": "STOP: Prolonged use (greater than 3 to 5 days) can cause severe rebound nasal congestion (rhinitis medicamentosa). Limit therapy duration."}]', '**Rebound Congestion:** Prolonged or excessive use (typically >3 days) may cause rebound congestion (rhinitis medicamentosa), characterized by chronic swelling of the nasal mucosa and worsening of symptoms.
INSERT INTO "drug_generic" VALUES(1709, 'Docusate Sodium', 'Docusate Sodium', 'A06AA02', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Prolonged Use:** Avoid prolonged use (>1 week) unless directed by a physician, as it may lead to dependence for bowel movements.
INSERT INTO "drug_generic" VALUES(1710, 'Methocarbamol', 'Methocarbamol', 'M03BA03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "CNS Depression", "severity": "High", "trigger_condition": "Concomitant use with alcohol or other CNS depressants", "message": "STOP: Methocarbamol causes significant CNS depression. Concurrent use with alcohol, opioids, benzodiazepines, or other sedatives can lead to profound sedation, respiratory depression, and coma."}]', '**Renal Impairment (IV Formulation):** The parenteral formulation contains polyethylene glycol (PEG) 300, which can accumulate and cause toxicity in patients with renal impairment. Do not use the IV formulation in these patients.
INSERT INTO "drug_generic" VALUES(1711, 'Brexanolone', 'Brexanolone', 'N06AX29', 0, 1, 0, 1, 1, 1, 0, 1, '[{"alert_type": "Excessive Sedation and Sudden Loss of Consciousness", "severity": "High", "trigger_condition": "During continuous IV infusion", "message": "STOP: Patients are at risk of excessive sedation or sudden loss of consciousness. Continuous pulse oximetry monitoring is mandatory. Must be administered in a certified healthcare facility under the REMS program."}]', '**Excessive Sedation and Sudden Loss of Consciousness:** Patients are at significant risk of excessive sedation or sudden loss of consciousness during administration. Continuous pulse oximetry monitoring is required. Patients must be accompanied during interactions with their children.
INSERT INTO "drug_generic" VALUES(1712, 'Ethambutol', 'Ethambutol', 'J04AK02', 1, 0, 0, 1, 1, 0, 1, 0, '[{"alert_type": "Optic Neuritis", "severity": "High", "trigger_condition": "Changes in visual acuity or color vision during therapy", "message": "STOP: Ethambutol can cause dose-related optic neuritis, resulting in decreased visual acuity and red-green color blindness. Discontinue immediately if visual changes occur to prevent irreversible blindness."}]', 'Perform baseline and periodic visual acuity and color vision testing; use with extreme caution in patients with pre-existing visual defects (e.g., cataracts, diabetic retinopathy) where changes in vision may be difficult to assess. Avoid use in young children or unconscious patients who cannot report visual disturbances, unless the benefits outweigh the risks. Monitor renal function, as ethambutol is primarily excreted by the kidneys; dose adjustment is required in renal impairment. May precipitate acute gout or hyperuricemia; monitor serum uric acid levels. Perform periodic assessment of hepatic and hematopoietic function during prolonged therapy.', '- **Pulmonary Tuberculosis:** Treatment of active pulmonary tuberculosis, always in conjunction with at least one other antituberculous drug (e.g., isoniazid, rifampin, pyrazinamide).
INSERT INTO "drug_generic" VALUES(1713, 'Inactivated Oral Cholera Vaccine', 'Cholera Vaccine, Inactivated, Oral', 'J07AE01', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Incomplete Protection:** Immunization with the cholera vaccine may not protect 100% of susceptible individuals. It is not a substitute for standard preventive measures (e.g., safe food and water practices, hygiene).
INSERT INTO "drug_generic" VALUES(1714, 'Magnesium Sulphate inj', 'Magnesium Sulfate Injection', 'B05XA05', 0, 1, 0, 1, 1, 1, 1, 0, '[{"alert_type": "Magnesium Toxicity", "severity": "High", "trigger_condition": "Rapid IV administration or renal impairment", "message": "STOP: Intravenous magnesium sulfate is a HIGH ALERT medication. Overdose or rapid infusion can cause fatal respiratory paralysis, heart block, and cardiac arrest. Monitor patellar reflexes, respiratory rate, and urine output continuously. Have IV Calcium Gluconate readily available as an antidote."}]', '**Renal Impairment:** Magnesium is excreted solely by the kidneys. Accumulation and severe toxicity can occur in renal impairment. Monitor serum magnesium levels closely.
INSERT INTO "drug_generic" VALUES(1715, 'Donepezil Hydrochloride', 'Donepezil', 'N06DA02', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Bradycardia and Heart Block", "severity": "High", "trigger_condition": "Patients with sick sinus syndrome or other supraventricular cardiac conduction conditions", "message": "STOP: Cholinesterase inhibitors can cause vagotonic effects on the sinoatrial and atrioventricular nodes, leading to severe bradycardia or heart block. Monitor heart rate closely."}]', '**Cardiovascular Conditions:** May cause bradycardia and heart block due to vagotonic effects. Syncopal episodes have been reported. Use with caution in patients with cardiac conduction abnormalities.
INSERT INTO "drug_generic" VALUES(1716, 'Azacitidine IV', 'Azacitidine', 'L01BC07', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Routine administration", "message": "STOP: Azacitidine causes severe anemia, neutropenia, and thrombocytopenia. Monitor complete blood counts prior to each cycle and as clinically indicated. Delay or reduce dose for severe hematologic toxicity."}, {"alert_type": "Product Substitution Error", "severity": "High", "trigger_condition": "Dispensing or administration", "message": "STOP: Do NOT substitute intravenous/subcutaneous azacitidine for oral azacitidine. The indications and dosing regimens are fundamentally different."}]', '**Hepatotoxicity:** Patients with extensive tumor burden due to metastatic disease have reported progressive hepatic coma and death during treatment, especially those with baseline albumin <30 g/L. Contraindicated in advanced malignant hepatic tumors.
INSERT INTO "drug_generic" VALUES(1717, 'Polytar 1.0 %', 'Coal Tar', 'D05AA', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Photosensitivity:** Coal tar increases sensitivity to sunlight. Patients must thoroughly wash off the medication before sun exposure and avoid tanning booths or sunlamps for at least 24 hours after application to prevent severe sunburn.
INSERT INTO "drug_generic" VALUES(1718, 'Ornidazole', 'Ornidazole', 'P01AB03', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Central Nervous System Toxicity", "severity": "High", "trigger_condition": "High doses or use in patients with pre-existing CNS disorders", "message": "STOP: Ornidazole can cause severe CNS toxicity, including seizures, peripheral neuropathy, tremor, and vertigo. Discontinue immediately if abnormal neurologic signs develop."}]', '**CNS Disorders:** Use with extreme caution in patients with active or chronic severe peripheral and central nervous system diseases (e.g., epilepsy, multiple sclerosis) due to the risk of neurological aggravation.
INSERT INTO "drug_generic" VALUES(1719, 'Rosuvastatin Calcium', 'Rosuvastatin', 'C10AA07', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Unexplained muscle pain, tenderness, or weakness", "message": "STOP: Risk of skeletal muscle effects including myopathy and life-threatening rhabdomyolysis. Promptly evaluate patients presenting with unexplained muscle pain, especially if accompanied by malaise or fever."}]', '**Myopathy and Rhabdomyolysis:** Rosuvastatin can cause myopathy and rhabdomyolysis with acute renal failure secondary to myoglobinuria. The risk increases with higher doses, advanced age (≥65 years), hypothyroidism, renal impairment, and concomitant use of certain drugs (e.g., cyclosporine, gemfibrozil, protease inhibitors).
INSERT INTO "drug_generic" VALUES(1720, 'Apremilast', 'Apremilast', 'L04AA32', 0, 0, 0, 0, 1, 1, 1, 1, '[{"alert_type": "Depression and Suicidality", "severity": "High", "trigger_condition": "Patients with a history of depression or suicidal thoughts", "message": "STOP: Apremilast is associated with an increase in depression and suicidal ideation. Carefully weigh the risks and benefits in patients with a history of depression. Monitor all patients for emergence or worsening of psychiatric symptoms."}]', '- **Psychiatric Effects:** Monitor for the emergence or worsening of depression, suicidal thoughts, or other mood changes. Discontinue if severe psychiatric symptoms occur.
INSERT INTO "drug_generic" VALUES(1721, 'Triclabendazole', 'Triclabendazole', 'P02BX04', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cardiac Toxicity", "severity": "High", "trigger_condition": "Concomitant use of QT-prolonging drugs or history of QT prolongation", "message": "STOP: Transient QT prolongation has been noted. Monitor ECG closely in patients with a history of QT prolongation or those receiving concurrent QT-prolonging medications."}]', '**QT Prolongation:** Transient QT prolongation has been observed. Continuous ECG monitoring is recommended in patients with a history of QT prolongation or those receiving concurrent medications known to prolong the QT interval.
INSERT INTO "drug_generic" VALUES(1722, 'Betamethasone 0.1%  E/E & Nasal prep', 'Betamethasone Ophthalmic/Otic/Nasal', 'S01BA06', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Ocular Toxicity", "severity": "High", "trigger_condition": "Prolonged ophthalmic use", "message": "STOP: Prolonged use of ophthalmic corticosteroids can cause elevated intraocular pressure (glaucoma), optic nerve damage, and posterior subcapsular cataracts. Monitor IOP if used for >10 days."}, {"alert_type": "Viral/Fungal Exacerbation", "severity": "High", "trigger_condition": "Use in undiagnosed red eye or known viral/fungal infection", "message": "STOP: Corticosteroids can mask or exacerbate ocular herpes simplex, leading to corneal perforation and blindness. Do not use in undiagnosed red eye."}]', '**Intraocular Pressure (IOP):** Prolonged use may result in ocular hypertension/glaucoma. Monitor IOP routinely if used for more than 10 days.
INSERT INTO "drug_generic" VALUES(1723, 'Hydrocortisone rectal', 'Hydrocortisone rectal', 'A07EA02', 0, 0, 1, 1, 0, 0, 0, 1, '[{"alert_type": "Systemic Absorption and Adrenal Suppression", "severity": "Moderate", "trigger_condition": "Prolonged use or high doses", "message": "Prolonged use of rectal corticosteroids can lead to systemic absorption, causing hypercorticism and hypothalamic-pituitary-adrenal (HPA) axis suppression. Taper gradually if used long-term."}]', '**Systemic Absorption:** Although administered rectally, systemic absorption can occur, leading to hypercorticism or HPA axis suppression, especially with prolonged use.
INSERT INTO "drug_generic" VALUES(1724, 'Doxorubicin Hydrochloride', 'Doxorubicin', 'L01DB01', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Cardiotoxicity, Myelosuppression, and Tissue Necrosis", "severity": "High", "trigger_condition": "Cumulative dose >300 mg/m\u00b2, baseline cardiac impairment, or extravasation", "message": "STOP: High risk of irreversible, dose-dependent cardiomyopathy and severe myelosuppression. Doxorubicin is a potent vesicant; extravasation causes severe tissue necrosis."}]', '**Cardiotoxicity:** Can cause irreversible myocardial damage leading to congestive heart failure (CHF). The risk increases significantly with cumulative doses >300 mg/m². Monitor left ventricular ejection fraction (LVEF) via ECHO or MUGA scan at baseline and regularly during therapy.
INSERT INTO "drug_generic" VALUES(1725, 'Multivitamin-Multimineral A-Z preparations for Teen Girls', 'Multivitamin with Minerals', 'A11AA03', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Masking of Pernicious Anemia:** Folic acid in doses above 0.1 mg daily may obscure pernicious anemia; hematological remission can occur while neurological manifestations remain progressive.
INSERT INTO "drug_generic" VALUES(1726, 'Oxaliplatin', 'Oxaliplatin', 'L01XA03', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Anaphylactic Reactions", "severity": "High", "trigger_condition": "Administration of oxaliplatin", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur within minutes of administration. Epinephrine, corticosteroids, and antihistamines must be readily available."}]', '**Neuropathy:** Can cause both acute, reversible sensory neuropathy (exacerbated by cold) and cumulative, dose-limiting peripheral sensory neuropathy. Monitor neurological status prior to each cycle.
INSERT INTO "drug_generic" VALUES(1727, 'Mefenamic Acid', 'Mefenamic Acid', 'M01AG01', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation of the stomach or intestines."}]', '**Cardiovascular Risk:** Use with extreme caution in patients with known cardiovascular disease or risk factors. May cause fluid retention, edema, and new-onset or worsening hypertension. Monitor blood pressure closely.
INSERT INTO "drug_generic" VALUES(1728, 'Sodium Bicarbonate', 'Sodium Bicarbonate', 'B05CB04', 0, 1, 0, 1, 1, 1, 1, 0, '[{"alert_type": "Extravasation and Tissue Necrosis", "severity": "High", "trigger_condition": "Intravenous administration of hypertonic solutions", "message": "STOP: Intravenous administration of hypertonic sodium bicarbonate can cause severe tissue necrosis, ulceration, and sloughing if extravasation occurs. Ensure secure venous access."}]', 'Use with extreme caution in patients with congestive heart failure (CHF), severe renal impairment, liver cirrhosis, hypertension, edema, eclampsia, or aldosteronism due to the risk of sodium retention and fluid overload. Monitor serum electrolyte concentrations (especially potassium and calcium) and acid-base status regularly during the treatment of acidosis to prevent metabolic alkalosis and hypokalemia. Rapid injection in neonates and children under 2 years of age may cause hypernatremia, decreased cerebrospinal fluid pressure, and possible intracranial hemorrhage. Caution is advised in patients with epilepsy as alkalosis can lower the seizure threshold.', '- **Metabolic Acidosis:** Management of severe metabolic acidosis occurring in severe renal disease, uncontrolled diabetes, circulatory insufficiency from shock or dehydration, and severe primary lactic acidosis.
INSERT INTO "drug_generic" VALUES(1729, 'Flumazenil', 'Flumazenil', 'V03AB25', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Seizure Risk", "severity": "High", "trigger_condition": "Patients with long-term benzodiazepine use or concurrent tricyclic antidepressant (TCA) overdose", "message": "STOP: Flumazenil can precipitate seizures. It is contraindicated in patients given benzodiazepines for life-threatening conditions (e.g., status epilepticus) and in cases of severe TCA overdose where benzodiazepines are protecting against TCA-induced seizures."}]', '**Resedation:** The duration of action of flumazenil is shorter than that of most benzodiazepines. Patients must be monitored for resedation, respiratory depression, or other residual benzodiazepine effects for an appropriate period (usually 2-12 hours) after administration.
INSERT INTO "drug_generic" VALUES(1730, 'Ispaghula Husk + Mebeverine Hydrochloride', 'Psyllium + Mebeverine', 'A03AC54', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Bowel Obstruction Risk", "severity": "High", "trigger_condition": "Patient history of intestinal obstruction or faecal impaction", "message": "STOP: Use is strictly contraindicated in patients with existing or impending intestinal obstruction, faecal impaction, or colonic atony."}]', 'Patients on a strictly controlled sodium or potassium diet must be monitored, as the formulation may contain significant amounts of these electrolytes.
INSERT INTO "drug_generic" VALUES(1731, 'Calcium Dobesilate 4% + Lidocaine 2% + Dexamethasone Acetate 0.025% rectal prep', 'Calcium Dobesilate/Lidocaine/Dexamethasone', 'C05AX03', 0, 0, 0, 0, 1, 1, 0, 0, '[]', '**Renal Insufficiency:** In cases of severe renal insufficiency, this ointment should not be used for prolonged periods due to the risk of systemic accumulation.
INSERT INTO "drug_generic" VALUES(1732, 'Elobixibat', 'Elobixibat', 'A06AX09', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Diarrhea Risk", "severity": "Moderate", "trigger_condition": "Initiation of therapy or dose escalation", "message": "Monitor for severe diarrhea and abdominal pain. Discontinue or reduce dose if severe gastrointestinal distress occurs."}]', '**Biliary Obstruction:** Use with caution in patients with partial biliary obstruction. The drug relies on the flow of bile acids into the intestine to exert its effect; efficacy may be reduced in these patients.
INSERT INTO "drug_generic" VALUES(1733, 'Naproxen 10% Topical', 'Naproxen Topical', 'M02AA12', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Systemic Absorption Risks", "severity": "Moderate", "trigger_condition": "Application to large areas or broken skin", "message": "STOP: Although applied topically, systemic absorption can occur. Patients with a history of severe NSAID-induced asthma, severe GI bleeding, or severe renal impairment should use this product with extreme caution."}]', '- **Systemic Absorption:** While systemic levels are lower than with oral administration, caution is advised in patients with pre-existing cardiovascular risk factors (fluid retention, CHF, hypertension), history of GI disease (bleeding or ulcers), or asthma.
INSERT INTO "drug_generic" VALUES(1734, 'Nepafenac Eye prep', 'Nepafenac Ophthalmic', 'S01BC10', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Corneal Toxicity", "severity": "High", "trigger_condition": "Prolonged use or use in patients with complicated ocular surgeries", "message": "STOP: Use of topical NSAIDs may result in keratitis. In susceptible patients, continued use may result in epithelial breakdown, corneal thinning, corneal erosion, corneal ulceration, or corneal perforation. Discontinue immediately if corneal epithelial breakdown occurs."}]', '- **Bleeding Tendencies:** Use with caution in patients with known bleeding tendencies or who are receiving medications that may prolong bleeding time. Topical NSAIDs may cause increased bleeding of ocular tissues (including hyphemas) in conjunction with ocular surgery.
INSERT INTO "drug_generic" VALUES(1735, 'Armodafinil', 'Armodafinil', 'N06BA13', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Cutaneous Reactions", "severity": "High", "trigger_condition": "Development of any unexplained rash", "message": "STOP: Serious rash, including Stevens-Johnson Syndrome (SJS) and DRESS, has been reported. Discontinue armodafinil immediately at the first sign of rash unless clearly not drug-related."}]', '**Psychiatric Symptoms:** May cause anxiety, agitation, mania, hallucinations, or suicidal ideation. Use with extreme caution in patients with a history of psychosis, depression, or mania. Discontinue if psychiatric symptoms develop.
INSERT INTO "drug_generic" VALUES(1736, 'Fludrocortisone Acetate', 'Fludrocortisone', 'H02AA02', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Adrenal Insufficiency", "severity": "High", "trigger_condition": "Abrupt discontinuation after prolonged use", "message": "STOP: Sudden withdrawal can precipitate acute adrenal crisis. Taper dosage gradually when discontinuing therapy."}]', 'Monitor blood pressure, serum electrolytes (especially potassium), and body weight regularly during therapy.
INSERT INTO "drug_generic" VALUES(1737, 'Methimazole', 'Methimazole', 'H03BB02', 0, 1, 0, 1, 0, 0, 1, 1, '[{"alert_type": "Agranulocytosis and Hepatotoxicity", "severity": "High", "trigger_condition": "Onset of fever, sore throat, mouth sores, jaundice, or dark urine", "message": "STOP: Severe and potentially fatal agranulocytosis and hepatotoxicity can occur. Instruct patients to immediately report fever, sore throat, or signs of liver dysfunction. Discontinue drug and check CBC/LFTs if suspected."}]', '**Agranulocytosis:** Significant bone marrow suppression, particularly agranulocytosis, may occur. Discontinue immediately if clinically significant agranulocytosis, leukopenia, or aplastic anemia occurs. Monitor CBC closely, especially if the patient presents with fever or sore throat.
INSERT INTO "drug_generic" VALUES(1738, 'Gilteritinib', 'Gilteritinib', 'L01EX13', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Differentiation Syndrome", "severity": "High", "trigger_condition": "Onset of fever, dyspnea, hypoxia, or pulmonary infiltrates", "message": "WARNING: Differentiation syndrome, which can be fatal, has occurred. If suspected, initiate systemic corticosteroids immediately and monitor closely."}, {"alert_type": "Posterior Reversible Encephalopathy Syndrome (PRES)", "severity": "High", "trigger_condition": "Onset of seizure, altered mental status, or visual disturbances", "message": "WARNING: PRES has been reported. Confirm with MRI and discontinue therapy immediately if PRES develops."}]', '**Differentiation Syndrome:** Can be fatal if not treated promptly. Symptoms include fever, dyspnea, hypoxia, pulmonary infiltrates, pleural or pericardial effusions, rapid weight gain, and peripheral edema. If suspected, initiate systemic corticosteroids (e.g., dexamethasone 10 mg IV BID) immediately and continue until symptoms resolve.
INSERT INTO "drug_generic" VALUES(1739, 'Citric Acid Monohydrate', 'Citric Acid', 'A09AB04', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Hereditary Fructose Intolerance:** Patients with rare hereditary problems of fructose intolerance, glucose-galactose malabsorption, or sucrase-isomaltase insufficiency should not take this medicine if the formulation contains sucrose or fructose as excipients.
INSERT INTO "drug_generic" VALUES(1740, 'Hydroxyethyl Cellulose + Glycerin', 'Hydroxyethyl Cellulose + Glycerin', NULL, 0, 0, 1, 1, 0, 1, 0, 0, '[]', '- **Condom Compatibility:** Compatible with latex condoms only. Verify compatibility if using polyurethane or polyisoprene condoms.
INSERT INTO "drug_generic" VALUES(1741, 'Maprotiline Hydrochloride', 'Maprotiline', 'N06AA21', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Suicidality and Antidepressant Drugs", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '**Seizure Risk:** Maprotiline lowers the seizure threshold. Use with extreme caution in patients with a history of seizures or those taking concurrent medications that lower the seizure threshold. The risk is dose-dependent.
INSERT INTO "drug_generic" VALUES(1742, 'Chlorpheniramine + Phenylephrine + Bromhexine', 'Chlorpheniramine + Phenylephrine + Bromhexine', 'R05X', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Patient history of severe hypertension or severe coronary artery disease", "message": "STOP: Phenylephrine can cause severe cardiovascular events. Avoid use in patients with uncontrolled hypertension or severe coronary artery disease."}]', 'Use with caution in patients with a history of peptic ulceration, as bromhexine may disrupt the gastric mucosal barrier.
INSERT INTO "drug_generic" VALUES(1743, 'Levocarnitine Syrup', 'Levocarnitine', 'A16AA01', 0, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Metabolite Accumulation", "severity": "Moderate", "trigger_condition": "Patients with severe renal impairment or End-Stage Renal Disease (ESRD)", "message": "Caution: Chronic administration of high oral doses in severe renal impairment or ESRD may result in the accumulation of potentially toxic metabolites (TMA and TMAO)."}]', '**Gastrointestinal Effects:** Rapid consumption of the oral solution can cause gastrointestinal reactions. Consume slowly and space doses evenly.
INSERT INTO "drug_generic" VALUES(1744, 'Vitamin B complex', 'Vitamin B Complex', 'A11EA', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Administer with caution to patients receiving levodopa monotherapy, as pyridoxine (Vitamin B6) can accelerate the peripheral metabolism of levodopa, reducing its efficacy. This interaction does not occur if levodopa is co-administered with a peripheral decarboxylase inhibitor (e.g., carbidopa). Monitor for signs of sensory neuropathy if high doses of pyridoxine are used for prolonged periods.', '- **Vitamin B-Complex Deficiency:** Treatment and prophylaxis of deficiency states such as beriberi, Wernicke''s encephalopathy, pellagra, cheilosis, glossitis, angular stomatitis, keratitis, and seborrheic dermatitis.
INSERT INTO "drug_generic" VALUES(1745, 'Glycerine 100 %', 'Glycerin', 'D02AX', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Ocular Exposure:** Avoid contact with eyes. If contact occurs, rinse thoroughly with water.
INSERT INTO "drug_generic" VALUES(1746, 'Gadodiamide', 'Gadodiamide', 'V08CA03', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Nephrogenic Systemic Fibrosis (NSF)", "severity": "High", "trigger_condition": "Patients with chronic, severe kidney disease (GFR < 30 mL/min/1.73m\u00b2) or acute kidney injury", "message": "STOP: Gadolinium-based contrast agents (GBCAs) increase the risk for NSF, a debilitating and potentially fatal disease. Avoid use in severe renal impairment unless diagnostic information is essential and unavailable via other modalities."}]', '**Nephrogenic Systemic Fibrosis (NSF):** GBCAs increase the risk for NSF among patients with impaired elimination of the drugs. The risk is highest in patients with chronic, severe kidney disease (GFR < 30 mL/min/1.73m²) and acute kidney injury. Screen all patients for renal dysfunction prior to administration.
INSERT INTO "drug_generic" VALUES(1747, 'Cenobamate', 'Cenobamate', 'N03AX25', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "DRESS Syndrome", "severity": "High", "trigger_condition": "Rapid dose titration (weekly or faster)", "message": "STOP: Drug Reaction with Eosinophilia and Systemic Symptoms (DRESS), including fatalities, has occurred. Strictly adhere to the recommended slow titration schedule."}]', '**DRESS Syndrome:** Drug Reaction with Eosinophilia and Systemic Symptoms (DRESS), also known as multiorgan hypersensitivity, has been reported, including fatalities. Risk is significantly increased with rapid titration. Adhere strictly to the recommended slow titration schedule. Discontinue immediately if DRESS is suspected.
INSERT INTO "drug_generic" VALUES(1748, 'Dienogest + Estradiol valerate', 'Dienogest and Estradiol valerate', 'G03AB08', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Women over 35 years old who smoke", "message": "STOP: Cigarette smoking increases the risk of serious cardiovascular events from combination oral contraceptives. This risk increases with age and number of cigarettes smoked."}]', '**Cardiovascular and Thromboembolic Risks:** Increases the risk of venous thromboembolism (VTE) and arterial thromboembolism (ATE). Discontinue therapy at least 4 weeks before and through 2 weeks after major surgery with prolonged immobilization. Initiate therapy no sooner than 4 weeks after delivery in non-breastfeeding women.
INSERT INTO "drug_generic" VALUES(1749, 'Cefetamet Pivoxil Hydrochloride', 'Cefetamet Pivoxil', 'J01DD10', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(1750, 'Betaxolol 0.25%  Eye prep', 'Betaxolol Ophthalmic', 'S01ED02', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Systemic Beta-Blocker Effects", "severity": "High", "trigger_condition": "Systemic absorption following ocular administration", "message": "STOP: Topically applied beta-blockers can be absorbed systemically. Severe respiratory reactions (bronchospasm) and cardiac reactions (bradycardia, heart block, heart failure) can occur. Use with extreme caution in patients with asthma, COPD, or severe cardiac disease."}]', '**Cardiovascular Effects:** Can cause bradycardia, heart block, and worsen heart failure. Discontinue at the first sign of cardiac failure. Use with caution in patients with cerebrovascular insufficiency.
INSERT INTO "drug_generic" VALUES(1751, 'Torasemide (Torsemide)', 'Torsemide', 'C03CA04', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Profound Diuresis and Electrolyte Depletion", "severity": "High", "trigger_condition": "High doses or inadequate fluid intake", "message": "Torsemide is a potent loop diuretic that can cause profound diuresis with water and electrolyte depletion. Monitor fluid status, serum electrolytes (especially potassium), and renal function closely."}]', 'Monitor fluid status and renal function to prevent azotemia, oliguria, and reversible increases in BUN and creatinine. Can cause potentially symptomatic hypokalemia, hyponatremia, hypomagnesemia, hypocalcemia, and hypochloremic alkalosis. Therapy can cause an increase in blood glucose levels and hyperglycemia; monitor blood glucose periodically. Asymptomatic hyperuricemia can occur, and gout may rarely be precipitated. Use with caution in patients with difficulty in micturition (e.g., prostatic hypertrophy), cardiac arrhythmias, or cardiovascular disease. Avoid use in the immediate postoperative period after bariatric surgery.', '- **Edema:** Management of edema associated with heart failure, renal disease, or hepatic cirrhosis.
INSERT INTO "drug_generic" VALUES(1752, 'Caffeine Citrate', 'Caffeine Citrate', 'N06BC01', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Toxicity and Overdose Risk", "severity": "High", "trigger_condition": "Serum caffeine levels exceeding 50 mg/L", "message": "STOP: Serious toxicity, including seizures, hypertonia, and cardiovascular collapse, is associated with serum levels greater than 50 mg/L. Monitor serum concentrations closely, especially in neonates with renal or hepatic impairment."}]', 'Use with extreme caution in infants with seizure disorders, cardiovascular disease, and impaired renal or hepatic function. Serum concentrations of caffeine should be routinely monitored, and dose administration must be adjusted to avoid toxicity in these vulnerable populations. Necrotizing enterocolitis has been reported with the use of methylxanthines; monitor closely for signs of gastrointestinal distress or feeding intolerance.', '- **Apnea of Prematurity:** Indicated for the short-term treatment of apnea of prematurity in infants between 28 and <33 weeks gestational age.', 'Contraindicated in patients who have demonstrated hypersensitivity to caffeine citrate or any of its components. Avoid use in patients with uncontrolled seizure disorders or severe cardiac arrhythmias.', '- **Cardiovascular:** Tachycardia, increased heart rate, lung edema.
INSERT INTO "drug_generic" VALUES(1753, 'L-Asparaginase', 'Asparaginase', 'L01XX02', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Anaphylaxis, Pancreatitis, and Coagulopathy", "severity": "High", "trigger_condition": "Administration of L-Asparaginase", "message": "STOP: Severe and potentially fatal anaphylaxis can occur; administer in a hospital setting with resuscitation equipment. High risk of severe acute pancreatitis, thrombosis, and hemorrhage. Monitor coagulation parameters and amylase/lipase closely."}]', '- **Hypersensitivity:** High risk of allergic reactions, including anaphylaxis. A skin test should be performed prior to the first dose. Risk increases with repeated doses.
INSERT INTO "drug_generic" VALUES(1754, 'Durvalumab', 'Durvalumab', 'L01FF03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Immune-Mediated Adverse Reactions", "severity": "High", "trigger_condition": "Patients presenting with new-onset respiratory, gastrointestinal, hepatic, or endocrine symptoms", "message": "STOP: Severe and fatal immune-mediated adverse reactions (pneumonitis, colitis, hepatitis, endocrinopathies, nephritis) can occur. Withhold therapy and initiate high-dose corticosteroids promptly if suspected."}]', '**Immune-Mediated Pneumonitis:** Severe, life-threatening, or fatal pneumonitis or interstitial lung disease (ILD) can occur. Monitor for signs and symptoms. Evaluate suspected pneumonitis with radiographic imaging. Administer corticosteroids (prednisone 1-2 mg/kg/day for Grade 2, or 1-4 mg/kg/day for Grade 3-4) followed by a taper. Interrupt or permanently discontinue therapy based on severity.
INSERT INTO "drug_generic" VALUES(1755, 'Verapamil Hydrochloride', 'Verapamil', 'C08DA01', 0, 1, 0, 1, 1, 1, 1, 1, '[{"alert_type": "Severe Cardiovascular Depression", "severity": "High", "trigger_condition": "Intravenous administration or use in severe left ventricular dysfunction", "message": "STOP: Verapamil is a potent negative inotrope and chronotrope. Intravenous use can cause severe hypotension, bradycardia, and asystole. Contraindicated in severe heart failure, 2nd/3rd degree AV block, and WPW syndrome with atrial fibrillation."}]', '**Heart Failure:** Verapamil has a negative inotropic effect. Avoid use in patients with severe left ventricular dysfunction (e.g., ejection fraction <30%) or moderate to severe symptoms of heart failure, as it may precipitate or worsen pulmonary edema.
INSERT INTO "drug_generic" VALUES(1756, 'Dexchlorpheniramine', 'Dexchlorpheniramine', 'R06AB02', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "CNS Depression", "severity": "Moderate", "trigger_condition": "Concurrent use of alcohol or other CNS depressants", "message": "May cause significant CNS depression, impairing physical and mental abilities. Advise patients against driving or operating heavy machinery."}]', '**CNS Depression:** May cause significant drowsiness and impair the mental or physical abilities required for the performance of potentially hazardous tasks such as driving a car or operating machinery.
INSERT INTO "drug_generic" VALUES(1757, 'Insulin (Human) N', 'Insulin Isophane (NPH)', 'A10AC01', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypoglycemia", "severity": "High", "trigger_condition": "Missed meals, excessive exercise, or incorrect dosing", "message": "STOP: Severe, life-threatening hypoglycemia can occur. Ensure the patient understands proper injection technique, meal timing, and signs of hypoglycemia. Never administer intravenously."}]', 'Monitor blood glucose frequently. Insulin requirements may change significantly during stress, illness, fever, trauma, infection, or surgery (requirements usually increase), or with diarrhea, nausea/vomiting, malabsorption, or hypothyroidism (requirements usually decrease). Hypokalemia may occur; monitor serum potassium in at-risk patients. Use with caution in patients with renal or hepatic impairment, as insulin requirements may be reduced. Monitor for injection site reactions, lipoatrophy, or lipohypertrophy; rotate injection sites. NPH insulin is an intermediate-acting suspension and must NEVER be administered intravenously or intramuscularly.', '- **Diabetes Mellitus:** Treatment of adult and pediatric patients with diabetes mellitus (Type 1 and Type 2) to improve glycemic control. Used as a basal insulin, often in combination with a short- or rapid-acting insulin.', '- **Hypoglycemia:** Contraindicated during episodes of hypoglycemia.
INSERT INTO "drug_generic" VALUES(1758, 'Clotrimazole Ear prep', 'Clotrimazole Otic', 'S02AA14', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Route of Administration Error", "severity": "High", "trigger_condition": "Inappropriate administration site", "message": "STOP: Clotrimazole ear drops are strictly for otic use. Do NOT use in the eyes. If local intolerance develops, withdraw the medicine."}]', '**Tympanic Membrane Integrity:** Ensure the tympanic membrane is intact before prescribing, unless specifically directed by an otolaryngologist, as the vehicle may cause middle ear irritation or ototoxicity if it crosses a perforation.
INSERT INTO "drug_generic" VALUES(1759, 'Bepotastine Besilate 1.5%  Eye prep', 'Bepotastine Ophthalmic', 'S01GX06', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Contact Lens Warning", "severity": "Low", "message": "Remove contact lenses prior to instillation. The preservative benzalkonium chloride may be absorbed by soft contact lenses. Wait at least 10 minutes before reinserting lenses."}]', '**Contamination Risk:** To minimize contaminating the dropper tip and solution, advise the patient not to touch the eyelids, surrounding areas, or any other surface with the dropper tip.
INSERT INTO "drug_generic" VALUES(1760, 'Brimonidine Tartrate + Timolol Maleate Eye prep', 'Brimonidine Tartrate and Timolol Maleate', 'S01ED51', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Systemic Beta-Blocker Effects", "severity": "High", "trigger_condition": "Patients with asthma, severe COPD, or severe cardiac disease", "message": "STOP: Timolol is systemically absorbed. Severe respiratory reactions (including death from bronchospasm) and cardiac reactions (heart failure) can occur."}]', '**Respiratory and Cardiac Reactions:** Due to the timolol component, systemic beta-adrenergic blockade can occur. Severe respiratory reactions, including death due to bronchospasm in asthmatics, and cardiac failure have been reported.
INSERT INTO "drug_generic" VALUES(1761, 'Risankizumab', 'Risankizumab', 'L04AC18', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Infection Risk", "severity": "High", "trigger_condition": "Active infection or latent tuberculosis", "message": "STOP: Risankizumab increases the risk of serious infections. Evaluate for active tuberculosis and latent TB prior to initiation. Do not administer to patients with active TB."}]', '**Infections:** May increase the risk of infections. Consider risks and benefits in patients with chronic or recurrent infections. If a serious infection develops, withhold treatment until the infection resolves.
INSERT INTO "drug_generic" VALUES(1762, 'Chloramphenicol 0.5% Eye drops', 'Chloramphenicol Ophthalmic', 'S01AA01', 1, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Systemic Absorption Risk", "severity": "Moderate", "trigger_condition": "Prolonged ocular use", "message": "Rare cases of fatal aplastic anemia and bone marrow hypoplasia have been reported following topical ophthalmic use of chloramphenicol due to systemic absorption. Avoid prolonged use."}]', '**Systemic Absorption:** Although rare, systemic absorption from ophthalmic administration can occur, leading to severe blood dyscrasias (aplastic anemia). Avoid prolonged or repeated courses of treatment.
INSERT INTO "drug_generic" VALUES(1763, 'Ibuprofen + Phenylephrine', 'Ibuprofen and Phenylephrine', 'M01AE51', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Patient with history of cardiovascular disease or peptic ulcer disease", "message": "STOP: NSAIDs increase the risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation."}]', '**Cardiovascular Risk:** NSAIDs, excluding aspirin, increase the risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke, which can be fatal. Phenylephrine may exacerbate poorly controlled hypertension; use with caution in patients with underlying cardiovascular risks.
INSERT INTO "drug_generic" VALUES(1764, 'Astaxanthin', 'Astaxanthin', 'Data not available', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Dietary Supplement", "severity": "Low", "message": "Astaxanthin is a dietary supplement. Clinical efficacy for treating specific medical conditions (e.g., Alzheimer''s, Parkinson''s, infertility) has not been definitively established by large-scale regulatory trials."}]', '**Pregnancy and Lactation:** Safety has not been established. Pregnant women and nursing mothers should avoid astaxanthin-containing supplements.
INSERT INTO "drug_generic" VALUES(1765, 'Permethrin 5% Topical', 'Permethrin', 'P03AC04', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Application Site:** Avoid contact with eyes, mucous membranes, and the mouth. If contact occurs, flush thoroughly with water.
INSERT INTO "drug_generic" VALUES(1766, 'Asciminib', 'Asciminib', 'L01EA06', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Myelosuppression", "severity": "High", "trigger_condition": "During therapy", "message": "STOP: Severe thrombocytopenia, neutropenia, and anemia can occur. Perform complete blood counts every 2 weeks for the first 3 months and monthly thereafter. Hold, reduce dose, or permanently discontinue based on severity."}, {"alert_type": "Cardiovascular Toxicity", "severity": "High", "trigger_condition": "Patients with preexisting cardiovascular conditions", "message": "STOP: Severe and fatal cardiovascular toxicity (ischemic cardiac/CNS conditions, arterial thrombotic events) and heart failure have been reported. Monitor closely and manage aggressively."}]', '**Myelosuppression:** Severe thrombocytopenia, neutropenia, and anemia have been reported. Perform complete blood counts every 2 weeks for the first 3 months and monthly thereafter, or as clinically indicated. Hold, reduce dose, or permanently discontinue based on severity.
INSERT INTO "drug_generic" VALUES(1767, 'Eprosartan + Hydrochlorothiazide', 'Eprosartan + Hydrochlorothiazide', 'C09DA02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue eprosartan/hydrochlorothiazide as soon as pregnancy is detected."}]', '**Hypotension:** Symptomatic hypotension may occur in patients who are salt or volume depleted. Correct volume depletion prior to administration, especially in patients receiving high-dose diuretics.
INSERT INTO "drug_generic" VALUES(1768, 'Vitamin A palmitate Carbomer 980 + Polyvidone + Electrolytes Eye prep', 'Vitamin A / Carbomer 980 / Povidone / Electrolytes Ophthalmic', 'S01XA', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Contact Lens Wear:** Remove contact lenses prior to administration and wait at least 15 minutes before reinsertion, as preservatives may alter lens integrity.
INSERT INTO "drug_generic" VALUES(1769, 'Calcium Carbonate + Calcium Laclate Gluconate + Vitamin-C', 'Calcium Carbonate, Calcium Lactate Gluconate, and Ascorbic Acid', 'A11GB01', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "Medium", "trigger_condition": "Prolonged use or concurrent use with thiazide diuretics", "message": "STOP: Excessive calcium intake can lead to hypercalcemia and milk-alkali syndrome. Monitor serum calcium levels in susceptible patients."}]', '**Renal Impairment and Calculi:** Use with caution in patients with mild to moderate renal failure or a history of renal stones. Monitor urinary calcium excretion; reduce or stop treatment if urinary calcium exceeds 7.5 mmol/24 hours.
INSERT INTO "drug_generic" VALUES(1770, 'Bilastine', 'Bilastine', 'R06AX29', 0, 0, 0, 0, 1, 1, 1, 0, '[]', 'Although bilastine is a non-sedating antihistamine, use caution when driving or operating heavy machinery until the individual''s response to the medication is known, as rare cases of somnolence have been reported.
INSERT INTO "drug_generic" VALUES(1771, 'Dextromethorphan + Bupropion', 'Dextromethorphan and Bupropion', 'N06AX28', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Suicidal Thoughts and Behaviors", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes in young adults", "message": "STOP: Antidepressants increase the risk of suicidal thoughts and behaviors in pediatric and young adult patients. Closely monitor for clinical worsening, unusual changes in behavior, or emergence of suicidality."}, {"alert_type": "Seizure Risk", "severity": "High", "trigger_condition": "History of seizure disorder or eating disorders", "message": "STOP: Bupropion lowers the seizure threshold in a dose-dependent manner. Contraindicated in patients with seizure disorders, bulimia, or anorexia nervosa."}]', '**Suicidality:** Monitor all patients closely for clinical worsening and emergence of suicidal thoughts and behaviors, especially during the initial months of therapy or at times of dose changes.
INSERT INTO "drug_generic" VALUES(1772, 'Flupenthixol + Melitracen', 'Flupentixol and Melitracen', 'N06CA02', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Suicidality Risk", "severity": "High", "trigger_condition": "Initiation of therapy or dose changes", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '- **Withdrawal of Sedatives:** If the patient has previously been treated with tranquilizers with a sedative effect, these should be withdrawn gradually before initiating this combination.
INSERT INTO "drug_generic" VALUES(1773, 'Calcium Acetate + Heavy Magnesium Carbonate', 'Calcium Acetate + Magnesium Carbonate', 'V03AE04', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Hypercalcemia and Hypermagnesemia", "severity": "High", "trigger_condition": "Concurrent use of Vitamin D analogs or thiazide diuretics", "message": "STOP: Continuous monitoring of serum calcium, magnesium, and phosphate is mandatory. High risk of vascular and soft tissue calcification if the calcium-phosphate product exceeds 4.5 mmol2/l2."}]', '**Electrolyte Monitoring:** Continuous monitoring of serum phosphate, magnesium, calcium, and the calcium-phosphate product is required. The risk of vascular and soft tissue calcification increases if the calcium-phosphate product exceeds 4.5 mmol2/l2.
INSERT INTO "drug_generic" VALUES(1774, 'Triprolidine', 'Triprolidine', 'R06AX07', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "CNS Depression", "severity": "Moderate", "trigger_condition": "Concurrent use of alcohol or other CNS depressants", "message": "May cause significant CNS depression, impairing physical and mental abilities. Advise patients against driving or operating heavy machinery."}]', '**CNS Depression:** May cause CNS depression, resulting in impaired physical or mental abilities. Caution patients about performing tasks that require mental alertness (e.g., driving, operating machinery).
INSERT INTO "drug_generic" VALUES(1775, 'Rocuronium Bromide', 'Rocuronium', 'M03AC09', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Respiratory Paralysis", "severity": "High", "trigger_condition": "Administration without ventilatory support", "message": "STOP: Rocuronium causes respiratory muscle paralysis. It must only be administered by trained personnel with immediate availability of facilities for intubation and mechanical ventilation."}]', '**Neuromuscular Disease:** Use with extreme caution in patients with myasthenia gravis or Eaton-Lambert syndrome, as profound effects can occur with small doses.
INSERT INTO "drug_generic" VALUES(1776, 'Tretinoin Topical', 'Tretinoin Topical', 'D10AD01', 0, 0, 0, 0, 0, 1, 1, 0, '[]', 'Avoid exposure to sunlight, UV light, and extreme weather conditions (e.g., wind, cold) as tretinoin increases photosensitivity and susceptibility to skin irritation. Use sunscreen and protective clothing daily. Keep away from eyes, mouth, angles of the nose, mucous membranes, and open wounds. Avoid concomitant use of other topical medications, medicated or abrasive soaps, cleansers, and cosmetics with a strong drying effect or high concentrations of alcohol, astringents, spices, or lime. In cases of severe local erythema, edema, blistering, or crusting, decrease the frequency of application or discontinue use temporarily until the skin recovers.', '- **Acne Vulgaris**: Topical treatment of acne vulgaris, particularly effective for comedonal acne.
INSERT INTO "drug_generic" VALUES(1777, 'Panobinostat', 'Panobinostat', 'L01XH03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Diarrhea and Cardiac Toxicities", "severity": "High", "trigger_condition": "Initiation of therapy or presence of baseline electrolyte abnormalities", "message": "STOP: Severe and fatal cardiac ischemic events, severe arrhythmias, and ECG changes have occurred. Severe diarrhea is common. Obtain baseline ECG and electrolytes; correct abnormalities before starting."}]', '**Severe Diarrhea:** Severe diarrhea occurred in 25% of patients in clinical trials. Monitor for symptoms and institute antidiarrheal treatment promptly. Interrupt panobinostat dosing, and then reduce the dose or discontinue if diarrhea is severe.
INSERT INTO "drug_generic" VALUES(1778, 'Trifarotene topical', 'Trifarotene', 'D10AD06', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Skin Irritation and Photosensitivity", "severity": "Medium", "trigger_condition": "Initiation of topical therapy", "message": "Caution: May cause significant skin irritation (erythema, scaling, dryness, stinging). Minimize unprotected exposure to ultraviolet rays (sunlight, sunlamps) and use sunscreen/protective clothing."}]', '**Skin Irritation:** Patients may experience erythema, scaling, dryness, and stinging/burning. The maximum severity of these reactions typically occurs within the first 4 weeks of treatment and decreases with continued use. Advise patients to use a moisturizer, reduce the frequency of application, or suspend use temporarily. If severe reactions persist, consider discontinuing treatment.
INSERT INTO "drug_generic" VALUES(1779, 'Camphor 2.5% + Menthol 2% + Oil Clove 2.5% + Oil Eucalyptus topical', 'Camphor / Menthol / Clove Oil / Eucalyptus Oil', 'M02AX10', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Pediatric Seizure Risk", "severity": "High", "trigger_condition": "Use in children under 3 years or patients with a history of convulsions", "message": "STOP: Camphor can cause severe neurotoxicity and seizures. Contraindicated in children under 3 years and patients with a history of convulsions."}]', '**Application Site Reactions:** Avoid contact with eyes, mucous membranes, and genitalia. Do not apply to wounds, damaged, or irritated skin.
INSERT INTO "drug_generic" VALUES(1780, 'Nefopam Hydrochloride', 'Nefopam Hydrochloride', 'N02BG06', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Seizure Risk", "severity": "High", "trigger_condition": "Patient history of convulsive disorders", "message": "STOP: Nefopam lowers the seizure threshold and is strictly contraindicated in patients with a history of epilepsy or convulsive disorders."}]', '- **Renal and Hepatic Impairment:** Use with caution; metabolism and excretion may be delayed, increasing the risk of toxicity.
INSERT INTO "drug_generic" VALUES(1781, 'Oxybutynin Hydrochloride', 'Oxybutynin', 'G04BD04', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Heat Prostration", "severity": "High", "trigger_condition": "High environmental temperatures", "message": "STOP: Oxybutynin decreases sweating. Administration in high environmental temperatures can lead to heat prostration (fever and heat stroke), which can be fatal. Advise patients to avoid overheating."}]', '**Central Nervous System Effects:** Can cause anticholinergic CNS effects (hallucinations, agitation, confusion, somnolence). Use with caution in the elderly and patients with pre-existing dementia.
INSERT INTO "drug_generic" VALUES(1782, 'Flunisolide nasal prep', 'Flunisolide', 'R01AD04', 0, 0, 0, 0, 0, 0, 0, 1, '[]', '**Adrenal Insufficiency:** Replacement of systemic corticosteroids with topical administration can be accompanied by signs of adrenal insufficiency. Some patients may experience withdrawal symptoms (e.g., joint/muscle pain, lassitude, depression). Monitor carefully during transition.
INSERT INTO "drug_generic" VALUES(1783, 'Amisulpride', 'Amisulpride', 'N05AL05', 0, 1, 0, 0, 1, 1, 0, 1, '[{"alert_type": "QT Prolongation and Arrhythmia", "severity": "High", "trigger_condition": "Coadministration with QT-prolonging drugs or presence of hypokalemia", "message": "STOP: Amisulpride causes dose-dependent QT interval prolongation, increasing the risk of Torsades de Pointes. Avoid use with other QT-prolonging agents. Correct hypokalemia before initiation."}, {"alert_type": "Neuroleptic Malignant Syndrome (NMS)", "severity": "High", "trigger_condition": "Development of hyperthermia, muscle rigidity, and autonomic instability", "message": "STOP: Potentially fatal NMS can occur. Discontinue immediately if unexplained high fever or severe muscle rigidity develops."}]', 'Use with caution in patients with cardiovascular disease, a family history of QT prolongation, or hypokalemia.
INSERT INTO "drug_generic" VALUES(1784, 'Lacosamide', 'Lacosamide', 'N03AX18', 0, 0, 0, 0, 1, 0, 1, 1, '[]', '**Cardiac Rhythm and Conduction Abnormalities:** Lacosamide prolongs the PR interval. Obtain an ECG before beginning therapy and after titrating to steady-state in patients with underlying proarrhythmic conditions (e.g., AV block, sick sinus syndrome) or those on concomitant medications that affect cardiac conduction. Monitor closely, especially if administered intravenously.
INSERT INTO "drug_generic" VALUES(1785, 'Glycerin + Hypromellose + Polyethylene glycol + Tetrahydrozoline + Zinc Sulfate eye prep', 'Glycerin + Hypromellose + Polyethylene glycol + Tetrahydrozoline + Zinc Sulfate ophthalmic', 'S01GA52', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Rebound Hyperemia and Glaucoma Risk", "severity": "Moderate", "trigger_condition": "Overuse (>72 hours) or use in patients with narrow-angle glaucoma", "message": "Caution: Overuse may cause rebound eye redness. Contraindicated in patients with narrow-angle glaucoma due to the risk of precipitating an acute angle-closure crisis."}]', '**Rebound Hyperemia:** Overuse or prolonged use (typically >72 hours) may cause rebound vasodilation, leading to increased eye redness.
INSERT INTO "drug_generic" VALUES(1786, 'Chloramphenicol 0.5% + Dexamethasone 0.1%  Eye/Ear drop', 'Chloramphenicol and Dexamethasone', 'S01CA01', 1, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Systemic Absorption and Ocular Toxicity", "severity": "High", "trigger_condition": "Prolonged use", "message": "STOP: Prolonged use of topical corticosteroids may increase intraocular pressure (IOP) leading to glaucoma and optic nerve damage. Systemic absorption of chloramphenicol can rarely cause fatal aplastic anemia."}]', '**Intraocular Pressure (IOP) Elevation:** Prolonged use of ophthalmic corticosteroids may result in glaucoma, damage to the optic nerve, and defects in visual acuity and fields of vision. Monitor IOP if used for more than 10 days.
INSERT INTO "drug_generic" VALUES(1787, 'Linezolid 0.2% Inj', 'Linezolid Injection', 'J01XX08', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Serotonin Syndrome Risk", "severity": "High", "trigger_condition": "Concomitant use with serotonergic agents (e.g., SSRIs, SNRIs, MAOIs)", "message": "STOP: Linezolid is a reversible, non-selective MAOI. Co-administration with serotonergic drugs can cause fatal Serotonin Syndrome. Discontinue serotonergic agents if possible, or monitor closely for altered mental status, autonomic instability, and neuromuscular abnormalities."}]', '- **Myelosuppression:** Reversible myelosuppression (anemia, leukopenia, pancytopenia, and thrombocytopenia) has been reported, particularly in patients receiving therapy for >14 days. Monitor complete blood counts (CBC) weekly.
INSERT INTO "drug_generic" VALUES(1788, 'Meclizine Hydrochloride + Pyridoxine Hydrochloride', 'Meclizine and Pyridoxine', 'R06AE55', 0, 0, 1, 0, 1, 0, 0, 0, '[]', '**CNS Depression:** May impair the mental and physical abilities required for driving or operating machinery. Patients should be cautioned accordingly.
INSERT INTO "drug_generic" VALUES(1789, 'Nimesulide', 'Nimesulide', 'M01AX17', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Hepatotoxicity", "severity": "High", "trigger_condition": "Any use of the medication", "message": "STOP: Nimesulide is associated with a risk of severe, potentially fatal hepatotoxicity (fulminant hepatitis). It should only be used as a second-line treatment for acute pain or primary dysmenorrhea, and the maximum duration of treatment must not exceed 15 days."}]', 'Use with extreme caution in the elderly and in patients with a history of gastrointestinal disease, edema, or hypertension. Monitor liver function tests closely. Discontinue immediately if signs or symptoms of liver damage (anorexia, nausea, vomiting, abdominal pain, fatigue, dark urine, jaundice) occur. Do not use concomitantly with other potentially hepatotoxic drugs or alcohol.', '- **Acute Pain:** Second-line treatment for the relief of acute pain.
INSERT INTO "drug_generic" VALUES(1790, 'Tafenoquine', 'Tafenoquine', 'P01BA07', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Hemolytic Anemia Risk", "severity": "High", "trigger_condition": "Glucose-6-phosphate dehydrogenase (G6PD) deficiency", "message": "STOP: Severe and potentially fatal hemolytic anemia can occur. Quantitative G6PD testing MUST be performed before prescribing. Contraindicated in patients with G6PD deficiency or unknown G6PD status."}]', 'Owing to the risk of hemolytic anemia in patients with G6PD deficiency, quantitative G6PD testing must be performed before prescribing; advise patients to seek immediate medical attention if signs of hemolysis occur.
INSERT INTO "drug_generic" VALUES(1791, 'Lisinopril', 'Lisinopril', 'C09AA03', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue lisinopril immediately as soon as pregnancy is detected."}]', '- **Hypotension:** May cause symptomatic hypotension, particularly in volume-depleted patients (e.g., those on high-dose diuretics, dialysis, or with severe heart failure). Initiate therapy under close medical supervision.
INSERT INTO "drug_generic" VALUES(1792, 'Isradipine', 'Isradipine', 'C08CA03', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Hypotension and Angina Exacerbation", "severity": "High", "trigger_condition": "Initiation of therapy or dosage titration", "message": "Severe hypotension and exacerbation of angina or myocardial infarction can occur, particularly in patients with severe obstructive coronary artery disease upon initiation or dosage increase."}]', '**Hypotension:** May cause symptomatic hypotension, particularly in patients with volume depletion or those receiving concurrent antihypertensives.
INSERT INTO "drug_generic" VALUES(1793, 'Hydrocortisone Acetate 0.5% + Neomycin Sulphate 0.5% Topical', 'Hydrocortisone and Neomycin', 'D07CA01', 1, 0, 0, 0, 0, 1, 1, 0, '[]', 'Use with caution in patients with congestive heart failure, hypertension, diabetes mellitus, and epilepsy if extensive systemic absorption is anticipated (e.g., prolonged use on large areas). Prolonged use may lead to skin atrophy, striae, and neomycin sensitization (allergic contact dermatitis). Avoid use under occlusive dressings as it significantly increases systemic absorption of both hydrocortisone and neomycin. Discontinue if irritation or sensitization occurs.', '- **Infected Dermatoses:** Treatment of corticosteroid-responsive dermatoses complicated by secondary bacterial infections susceptible to neomycin.
INSERT INTO "drug_generic" VALUES(1794, 'Dextromethorphan + Phenylephrine', 'Dextromethorphan and Phenylephrine', 'R05DA20', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Serotonergic Risk", "severity": "High", "trigger_condition": "Concurrent use or use within 14 days of Monoamine Oxidase Inhibitors (MAOIs)", "message": "STOP: Concomitant use with MAOIs can precipitate severe hypertensive crisis (due to phenylephrine) and potentially fatal serotonin syndrome (due to dextromethorphan). Verify patient medication history before prescribing."}]', '**Cardiovascular and Endocrine Conditions:** Use with extreme caution in patients with hypertension, hyperthyroidism, myocardial disease, bradycardia, partial heart block, severe arteriosclerosis, or diabetes mellitus. Phenylephrine is a potent vasoconstrictor and can exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1795, 'Amcinonide topical', 'Amcinonide', 'D07AC11', 0, 0, 0, 1, 0, 1, 0, 1, '[]', '**HPA Axis Suppression:** Amcinonide is a potent corticosteroid. Systemic absorption can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria. Risk increases with application to large surface areas, prolonged use, or use under occlusive dressings. Perform urinary free cortisol and ACTH stimulation tests to monitor for HPA axis suppression if systemic absorption is suspected.
INSERT INTO "drug_generic" VALUES(1796, 'Isavuconazonium sulfate (Isavuconazole)', 'Isavuconazonium Sulfate', 'J02AC05', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatic Toxicity and Infusion Reactions", "severity": "High", "trigger_condition": "Initiation of therapy or IV infusion", "message": "STOP: Severe hepatic reactions (hepatitis, cholestasis, hepatic failure) have been reported. Monitor LFTs. Infusion-related reactions (hypotension, dyspnea) can occur; discontinue infusion if severe."}]', '**Hepatic Adverse Reactions:** Elevations in ALT, AST, alkaline phosphatase, and total bilirubin have been reported. Cases of severe hepatic adverse drug reactions, including hepatitis, cholestasis, or hepatic failure (including death), have occurred in patients with serious underlying medical conditions. Monitor LFTs.
INSERT INTO "drug_generic" VALUES(1797, 'Pentazocine Hydrochloride', 'Pentazocine', 'N02CC01', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Respiratory Depression and Withdrawal Precipitation", "severity": "High", "trigger_condition": "Use in opioid-dependent patients or concurrent use with CNS depressants", "message": "STOP: Pentazocine is a mixed opioid agonist-antagonist. It can precipitate acute withdrawal in patients physically dependent on full opioid agonists. Severe, life-threatening respiratory depression may occur."}]', '- **Opioid Dependence:** May precipitate acute withdrawal symptoms in patients physically dependent on full opioid agonists (e.g., morphine, fentanyl).
INSERT INTO "drug_generic" VALUES(1798, 'Ciprofloxacin 0.3% E/E prep', 'Ciprofloxacin Ophthalmic/Otic', 'S01AE03', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "First appearance of skin rash or allergic signs", "message": "Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported with systemic quinolones. Discontinue topical therapy immediately at the first sign of a rash or allergic reaction."}]', '**Superinfection:** Prolonged use may result in the overgrowth of nonsusceptible organisms, including fungi. If superinfection occurs, discontinue use and institute alternative therapy.
INSERT INTO "drug_generic" VALUES(1799, 'Salbutamol', 'Albuterol', 'R03AC02', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Initiation of a new canister or vial of inhaled formulation", "message": "STOP: Life-threatening paradoxical bronchospasm can occur. If wheezing worsens immediately after dosing, discontinue immediately and institute alternative therapy."}]', 'Use with extreme caution in patients with cardiovascular disorders, including coronary insufficiency, cardiac arrhythmias, and hypertension, as beta-adrenergic agonists can produce clinically significant cardiovascular effects (changes in pulse rate, blood pressure, and ECG changes such as flattening of the T wave, prolongation of the QTc interval, and ST segment depression).
INSERT INTO "drug_generic" VALUES(1800, 'Calcium Carbonate + Vitamin D3', 'Calcium Carbonate and Cholecalciferol', 'A12AX', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Achlorhydria:** Calcium carbonate requires an acidic environment for optimal absorption. Absorption may be impaired in patients with achlorhydria (common in the elderly) or those taking proton pump inhibitors. Taking the supplement with meals improves absorption.
INSERT INTO "drug_generic" VALUES(1801, 'Immunoglobulin-G Human + Maltose', 'Immune Globulin Intravenous (Human), 10% Liquid', 'J06BA02', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Renal Dysfunction and Acute Renal Failure", "severity": "High", "trigger_condition": "Patients with pre-existing renal impairment, diabetes mellitus, age >65 years, volume depletion, or concurrent nephrotoxic drug use", "message": "STOP: Immune globulin intravenous (IGIV) products have been associated with renal dysfunction, acute renal failure, osmotic nephrosis, and death. Administer at the minimum concentration available and the minimum rate of infusion practicable."}, {"alert_type": "Thrombosis", "severity": "High", "trigger_condition": "Patients with advanced age, prolonged immobilization, hypercoagulable conditions, history of venous or arterial thrombosis, use of estrogens, indwelling central vascular catheters, hyperviscosity, or cardiovascular risk factors", "message": "STOP: Thrombosis may occur with immune globulin products. For patients at risk, administer at the minimum concentration available and the minimum rate of infusion practicable. Ensure adequate hydration before administration."}]', '**Renal Dysfunction:** Increased risk of acute renal failure, particularly in patients with pre-existing renal impairment, diabetes mellitus, hypovolemia, overweight status, concomitant nephrotoxic medicinal products, or age >65 years. Ensure adequate hydration prior to IV infusion. Monitor urine output and serum creatinine levels closely during treatment. Avoid concurrent use of loop diuretics during IV infusion.
INSERT INTO "drug_generic" VALUES(1802, 'Insulin Detemir', 'Insulin Detemir', 'A10AE05', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypoglycemia", "severity": "High", "trigger_condition": "Changes in insulin regimen, missed meals, increased physical activity, or co-administration with other glucose-lowering agents", "message": "STOP: Severe, life-threatening hypoglycemia can occur. Monitor blood glucose closely when adjusting doses, changing diet, or altering physical activity."}, {"alert_type": "Administration Error", "severity": "High", "trigger_condition": "Intravenous administration or use in insulin infusion pumps", "message": "STOP: Insulin detemir must NOT be administered intravenously, intramuscularly, or via an insulin infusion pump. Severe hypoglycemia can result."}]', '**Hypoglycemia:** The most common adverse effect of insulin therapy. Risk increases with changes in meal patterns, physical activity, or co-administered medications. Early warning symptoms may be different or less pronounced in patients with long-standing diabetes, diabetic nerve disease, or those taking beta-blockers.
INSERT INTO "drug_generic" VALUES(1803, 'Dexamethasone + Gatifloxacin eye prep', 'Dexamethasone and Gatifloxacin Ophthalmic', 'S01CA01', 1, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Ocular Infections and Glaucoma", "severity": "High", "trigger_condition": "Prolonged use or presence of viral/fungal eye infections", "message": "STOP: Corticosteroids can mask, activate, or exacerbate ocular infections. Contraindicated in viral (herpes simplex) and fungal eye diseases. Prolonged use may cause elevated intraocular pressure (glaucoma) and cataracts."}]', '**Intraocular Pressure (IOP) Elevation:** Prolonged use (10 days or more) may result in ocular hypertension and/or glaucoma, with damage to the optic nerve and defects in visual acuity. IOP should be monitored routinely.
INSERT INTO "drug_generic" VALUES(1804, 'Dexamethasone + Moxifloxacin eye prep', 'Dexamethasone + Moxifloxacin Ophthalmic', 'S01CA01', 1, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Ocular Toxicity and Superinfection", "severity": "Moderate", "trigger_condition": "Prolonged use beyond 10 days", "message": "Caution: Prolonged use of ophthalmic steroids may result in glaucoma, optic nerve damage, cataract formation, and increased risk of secondary ocular infections (fungal or viral). Monitor intraocular pressure routinely."}]', '**Intraocular Pressure (IOP):** Prolonged use may result in ocular hypertension and/or glaucoma, with damage to the optic nerve and defects in visual acuity. Monitor IOP if used for 10 days or longer.
INSERT INTO "drug_generic" VALUES(1805, 'Upadacitinib', 'Upadacitinib', 'L04AF03', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Serious Infections and Malignancy", "severity": "High", "trigger_condition": "Patients with active infections, history of malignancy, or cardiovascular risk factors", "message": "STOP: Increased risk of serious/fatal infections (e.g., TB, fungal), malignancies, major adverse cardiovascular events (MACE), and thrombosis. Evaluate risks before initiating."}]', '**Serious Infections:** Serious and sometimes fatal infections have been reported, including pneumonia, cellulitis, tuberculosis (TB), multidermatomal herpes zoster, oral/esophageal candidiasis, and cryptococcosis. Evaluate patients for active and latent TB prior to initiation. Viral reactivation (e.g., hepatitis B, herpes zoster) has occurred.
INSERT INTO "drug_generic" VALUES(1806, 'Chondroitin + Glucosamine', 'Chondroitin and Glucosamine', 'M01AX05', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Allergy Warning", "severity": "High", "trigger_condition": "Patient history of shellfish allergy", "message": "STOP: Glucosamine is often derived from the exoskeletons of shellfish. Contraindicated in patients with a known shellfish allergy due to the risk of severe hypersensitivity reactions."}]', '**Diabetes Mellitus:** Glucosamine may theoretically increase insulin resistance and affect glucose tolerance. Diabetic patients should monitor their blood glucose levels more frequently when initiating therapy.
INSERT INTO "drug_generic" VALUES(1807, 'Trihexyphenidyl Hydrochloride', 'Trihexyphenidyl', 'N04AA01', 0, 0, 0, 0, 1, 0, 0, 1, '[]', 'Use with caution in patients with cardiovascular disease (may cause tachycardia), arteriosclerosis, and a history of drug idiosyncrasy. Extreme caution is required in patients with glaucoma; perform gonioscopic evaluation prior to initiation and monitor intraocular pressure regularly. Caution in patients with gastrointestinal obstruction, benign prostatic hyperplasia, or urinary stricture due to anticholinergic effects. Elderly patients are highly susceptible to anticholinergic side effects, including delirium, confusion, and hallucinations. Avoid abrupt withdrawal to prevent exacerbation of parkinsonian symptoms. Not intended for the treatment of tardive dyskinesia (may exacerbate symptoms).', '- **Parkinson''s Disease**: Adjunctive treatment of all forms of parkinsonism (postencephalitic, arteriosclerotic, and idiopathic). Often used as adjuvant therapy with levodopa.
INSERT INTO "drug_generic" VALUES(1808, 'Bortezomib', 'Bortezomib', 'L01XG01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Fatal Intrathecal Administration", "severity": "High", "trigger_condition": "Inadvertent intrathecal administration", "message": "STOP: Bortezomib is for Intravenous (IV) or Subcutaneous (SC) use ONLY. Fatalities have occurred with inadvertent intrathecal administration. NEVER administer intrathecally."}]', '**Peripheral Neuropathy:** Manage with dose modification or discontinuation. Patients with preexisting severe neuropathy should be treated only after careful risk-benefit assessment.
INSERT INTO "drug_generic" VALUES(1809, 'Oxygenium', 'Oxygen', 'V03AN01', 0, 0, 1, 1, 0, 1, 1, 1, '[{"alert_type": "Fire Hazard", "severity": "High", "trigger_condition": "Presence of ignition sources", "message": "STOP: Oxygen vigorously accelerates combustion. Keep away from heat, sparks, open flames, and smoking materials. Do not use oil or grease on oxygen equipment."}]', '**COPD and Chronic Hypercapnia:** High concentrations of oxygen in patients with chronic obstructive pulmonary disease (COPD) can depress the hypoxic drive to breathe, leading to severe hypercapnia, respiratory acidosis, and respiratory arrest. Titrate carefully to target SpO2 (usually 88-92%).
INSERT INTO "drug_generic" VALUES(1810, 'Miconazole 2% Oral Gel', 'Miconazole Oral Gel', 'A01AB09', 0, 0, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Choking Hazard in Infants", "severity": "High", "trigger_condition": "Administration to infants and young children", "message": "STOP: Severe choking and asphyxiation have been reported in infants. Do not apply the gel to the back of the throat. Divide the dose into smaller portions and apply to the front of the mouth/gums."}]', 'Extreme caution is required when administering to infants (especially under 6 months) and young children to prevent airway obstruction; apply in small amounts to the front of the mouth and monitor closely. Systemic absorption occurs; caution in patients taking drugs metabolized by CYP3A4 or CYP2C9. Discontinue if sensitization or severe local irritation occurs.', '- Treatment of oropharyngeal candidiasis (oral thrush).
INSERT INTO "drug_generic" VALUES(1811, 'Sulphamethoxazole 200 mg +Trimethoprim 40 mg/ml', 'Sulfamethoxazole and Trimethoprim', 'J01EE01', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Cutaneous Adverse Reactions", "severity": "High", "trigger_condition": "Appearance of skin rash, mucosal lesions, or systemic symptoms (fever, malaise)", "message": "STOP therapy immediately. Fatalities associated with Stevens-Johnson syndrome (SJS), toxic epidermal necrolysis (TEN), and fulminant hepatic necrosis have occurred."}]', 'Use with extreme caution in patients with folate deficiency (e.g., elderly, alcoholics, pregnant women, patients on anticonvulsants), as it may precipitate megaloblastic anemia. Monitor complete blood counts frequently during prolonged therapy. Maintain adequate fluid intake to prevent crystalluria and stone formation. Use cautiously in patients with severe allergy or bronchial asthma. Monitor serum potassium closely, especially in the elderly or those receiving concurrent ACE inhibitors, due to the risk of severe hyperkalemia. Avoid in patients with G6PD deficiency due to the risk of hemolysis.', '- **Pneumocystis jirovecii Pneumonia (PCP):** Treatment and prophylaxis of PCP in immunocompromised patients (e.g., HIV/AIDS).
INSERT INTO "drug_generic" VALUES(1812, 'Vitamin C + Vitamin E', 'Ascorbic Acid and Alpha-Tocopherol', 'A11JA', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Avoid excessive doses (hypervitaminosis). Use with caution in patients on prolonged anticoagulant therapy, as Vitamin E can potentiate bleeding risks. Caution in patients with a history of hyperoxaluria or renal calculi due to the Vitamin C component. Avoid high doses in early pregnancy.', '- **Antioxidant Supplementation:** Dietary supplement to reduce oxidative stress and support cardiovascular health.
INSERT INTO "drug_generic" VALUES(1813, 'Iron Sucrose', 'Iron Sucrose', 'B03AC', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "During or immediately after administration", "message": "STOP: Serious hypersensitivity reactions, including anaphylactic shock and collapse, have been reported. Administer only when personnel and therapies are immediately available for the treatment of anaphylaxis. A test dose is recommended for new patients."}]', '**Hypotension:** May cause clinically significant hypotension, which may be related to the rate of administration and total dose. Administer according to recommended guidelines and monitor blood pressure during and after infusion.
INSERT INTO "drug_generic" VALUES(1814, 'Luspatercept', 'Luspatercept', 'B03XA06', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Thrombosis and Hypertension", "severity": "High", "trigger_condition": "Patients with beta thalassemia or MDS", "message": "STOP: Increased risk of thrombosis/thromboembolism, especially in patients with risk factors (e.g., splenectomy). Monitor blood pressure prior to each dose; manage new-onset or exacerbated hypertension promptly."}]', '**Thrombosis/Thromboembolism:** Increased risk of thromboembolic events (e.g., deep vein thrombosis, pulmonary embolism, portal vein thrombosis) in patients with beta thalassemia. Patients with known risk factors (e.g., splenectomy, hormone replacement therapy) are at higher risk. Consider thromboprophylaxis and monitor for signs of thromboembolism.
INSERT INTO "drug_generic" VALUES(1815, 'Golodirsen', 'Golodirsen', 'M09AX11', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Renal Toxicity", "severity": "High", "trigger_condition": "Routine monitoring during therapy", "message": "STOP: Renal toxicity, including potentially fatal glomerulonephritis, has been observed with antisense oligonucleotides. Monitor renal function regularly."}]', '**Renal Toxicity:** Renal toxicity was observed in animal studies. Although not explicitly observed in golodirsen clinical trials, renal toxicity, including potentially fatal glomerulonephritis, has been observed after administration of other antisense oligonucleotides. Monitor renal function prior to starting therapy and regularly during treatment (e.g., urine dipstick, serum cystatin C, and urine protein-to-creatinine ratio).
INSERT INTO "drug_generic" VALUES(1816, 'Insulin Glargine', 'Insulin Glargine', 'A10AE04', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypoglycemia", "severity": "High", "trigger_condition": "Changes in insulin regimen, missed meals, increased physical activity, or co-administration with other glucose-lowering agents", "message": "STOP: Severe, life-threatening hypoglycemia can occur. Monitor blood glucose closely when adjusting doses, changing diet, or altering physical activity."}, {"alert_type": "Administration Error", "severity": "High", "trigger_condition": "Intravenous administration or use in insulin infusion pumps", "message": "STOP: Insulin glargine must NOT be administered intravenously, intramuscularly, or via an insulin infusion pump. Severe hypoglycemia can result."}]', '**Hypoglycemia:** The most common adverse effect of insulin therapy. Risk increases with changes in meal patterns, physical activity, or co-administered medications. Early warning symptoms may be different or less pronounced in patients with long-standing diabetes, diabetic nerve disease, or those taking beta-blockers.
INSERT INTO "drug_generic" VALUES(1817, 'Triamcinolone Acetonide 0.1% Topical', 'Triamcinolone Acetonide Topical', 'D07AB09', 0, 0, 0, 0, 0, 1, 0, 1, '[]', 'Prolonged use, application to large surface areas, or use under occlusive dressings can lead to systemic absorption, resulting in reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria. Use with extreme caution in pediatric patients, as they are more susceptible to systemic toxicity and growth retardation from topical corticosteroids. Avoid contact with the eyes. Discontinue use if local irritation, sensitization, or secondary infection develops.', '- **Corticosteroid-Responsive Dermatoses**: Relief of the inflammatory and pruritic manifestations of corticosteroid-responsive dermatoses (e.g., eczema, atopic dermatitis, contact dermatitis, psoriasis).', '- **Hypersensitivity**: Contraindicated in patients with a history of hypersensitivity to triamcinolone or any components of the preparation.
INSERT INTO "drug_generic" VALUES(1818, 'Baloxavir marboxil', 'Baloxavir marboxil', 'J05AX25', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Administration of the drug", "message": "Anaphylaxis, angioedema, urticaria, and erythema multiforme have been reported. Initiate appropriate treatment if an allergic-like reaction occurs."}]', '**Hypersensitivity:** Anaphylaxis, angioedema, urticaria, and erythema multiforme have been reported. Initiate appropriate treatment if an allergic-like reaction occurs or is suspected.
INSERT INTO "drug_generic" VALUES(1819, 'Betahistine Dihydrochloride', 'Betahistine', 'N07CA01', 0, 0, 0, 0, 0, 0, 0, 0, '[]', '- **Peptic Ulcer Disease:** Use with caution in patients with a history of peptic ulcer disease, as betahistine is a histamine analogue and may theoretically increase gastric acid secretion.
INSERT INTO "drug_generic" VALUES(1820, 'Diloxanide Furoate', 'Diloxanide Furoate', 'P01CB01', 1, 0, 0, 0, 1, 0, 1, 0, '[]', '**Pregnancy and Lactation:** Use should be avoided during pregnancy and breastfeeding unless absolutely necessary, as safety data are limited.
INSERT INTO "drug_generic" VALUES(1821, 'Bamlanivimab (Investigational)', 'Bamlanivimab', 'J06BD03', 1, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Anaphylaxis and Infusion Reactions", "severity": "High", "trigger_condition": "During or immediately after IV infusion", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis and severe infusion-related reactions, have been reported. Immediately discontinue infusion and initiate appropriate supportive care if signs occur."}, {"alert_type": "Clinical Worsening in Severe COVID-19", "severity": "High", "trigger_condition": "Hospitalized patients requiring oxygen therapy", "message": "STOP: Monoclonal antibodies may be associated with worse clinical outcomes when administered to hospitalized patients with COVID-19 requiring high-flow oxygen or mechanical ventilation. Not authorized for this population."}]', 'Therapy must be administered in settings where healthcare providers have immediate access to medications to treat severe infusion reactions (e.g., epinephrine) and the ability to activate the emergency medical system.
INSERT INTO "drug_generic" VALUES(1822, 'Pegfilgrastim', 'Pegfilgrastim', 'L03AA13', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Splenic Rupture and ARDS", "severity": "High", "trigger_condition": "Left upper abdominal pain, shoulder tip pain, or respiratory distress", "message": "STOP: Fatal splenic rupture and Acute Respiratory Distress Syndrome (ARDS) have occurred. Evaluate immediately if the patient reports left upper abdominal/shoulder pain or develops fever, lung infiltrates, and respiratory distress."}]', 'Severe sickle cell crises, sometimes fatal, have been reported in patients with sickle cell disorders receiving pegfilgrastim; use with extreme caution. Glomerulonephritis has occurred; monitor urinalysis for hematuria/proteinuria. Capillary leak syndrome (CLS) can occur and may be life-threatening; monitor for edema and hypotension. Aortitis has been reported; monitor for fever, abdominal pain, and elevated inflammatory markers. Do not administer between 14 days before and 24 hours after cytotoxic chemotherapy due to the sensitivity of rapidly dividing myeloid cells. Monitor CBC and platelet counts regularly.', '- **Chemotherapy-Induced Neutropenia:** To decrease the incidence of infection, as manifested by febrile neutropenia, in patients with non-myeloid malignancies receiving myelosuppressive anti-cancer drugs associated with a clinically significant incidence of febrile neutropenia.
INSERT INTO "drug_generic" VALUES(1823, 'Benzylpenicillin + Procaine Penicillin', 'Penicillin G Procaine', 'J01CE30', 1, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Intravenous Administration Fatalities", "severity": "High", "trigger_condition": "Inadvertent IV administration", "message": "STOP: DO NOT ADMINISTER INTRAVENOUSLY. Inadvertent IV administration has caused severe neurovascular damage, cardiorespiratory arrest, and death. Administer by deep intramuscular (IM) injection ONLY."}, {"alert_type": "Procaine Toxicity (Hoigne''s Syndrome)", "severity": "High", "trigger_condition": "Immediately following IM injection", "message": "STOP: Accidental intravascular injection can cause acute procaine toxicity characterized by severe anxiety, confusion, agitation, combativeness, hallucinations, and seizures. Symptoms usually resolve within 15-30 minutes."}]', '**Injection Site Reactions:** Do not inject near an artery or nerve, as this may result in severe neurovascular damage, permanent paralysis, or gangrene. Quadriceps femoris fibrosis and atrophy have been reported following repeated IM injections into the anterolateral thigh.
INSERT INTO "drug_generic" VALUES(1824, 'Itraconazole', 'Itraconazole', 'J02AC02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Congestive Heart Failure Risk", "severity": "High", "trigger_condition": "Patients with evidence of ventricular dysfunction or history of CHF", "message": "STOP: Itraconazole has negative inotropic effects and can cause or exacerbate congestive heart failure. Do not use for onychomycosis in patients with ventricular dysfunction."}, {"alert_type": "Fatal Drug Interactions", "severity": "High", "trigger_condition": "Coadministration with CYP3A4 substrates", "message": "STOP: Itraconazole is a potent CYP3A4 inhibitor. Coadministration with certain drugs (e.g., methadone, disopyramide, dofetilide, dronedarone, quinidine, lovastatin, simvastatin) can lead to life-threatening QT prolongation, ventricular tachyarrhythmias (Torsades de Pointes), or severe myopathy."}]', '**Hepatotoxicity:** Serious hepatotoxicity, including liver failure and death, has been reported. Monitor liver function tests prior to therapy and periodically during treatment. Discontinue if signs of liver dysfunction occur.
INSERT INTO "drug_generic" VALUES(1825, 'Lyophilised bacterial lysates of E. coli', 'OM-89 (Escherichia coli extract)', 'G04BX', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Hypersensitivity Reactions:** Can cause hypersensitivity reactions, including skin rash, fever, or edema. If allergic reactions occur, treatment must be interrupted immediately.
INSERT INTO "drug_generic" VALUES(1826, 'Amino Acid + Calcium', 'Keto Analogues of Essential Amino Acids and Calcium', 'V06DD', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "Moderate", "trigger_condition": "Concurrent use of calcium supplements or Vitamin D", "message": "Hypercalcemia may develop. Monitor serum calcium levels regularly. If hypercalcemia persists, reduce the dosage of this medication and other sources of calcium or Vitamin D."}]', '**Hypercalcemia:** Monitor serum calcium levels regularly. Ensure sufficient calorie intake. If hypercalcemia occurs, decrease Vitamin D intake and reduce the dose of this medication if necessary.
INSERT INTO "drug_generic" VALUES(1827, 'Cisatracurium besylate', 'Cisatracurium besylate', 'M03AC11', 0, 1, 1, 0, 0, 1, 1, 0, '[{"alert_type": "Respiratory Paralysis", "severity": "High", "trigger_condition": "Administration without mechanical ventilation", "message": "STOP: Cisatracurium causes profound respiratory muscle paralysis. It must ONLY be administered by trained personnel in settings where intubation, mechanical ventilation, and oxygen therapy are immediately available."}]', '**Respiratory Paralysis:** Cisatracurium paralyzes respiratory muscles. It must be administered only by individuals trained in airway management and respiratory support. Adequate facilities for intubation and mechanical ventilation must be immediately available.
INSERT INTO "drug_generic" VALUES(1828, 'L-Lysine HCl 15% Topical', 'Lysine Hydrochloride Topical', 'D03AX', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'For external use only. Avoid contact with eyes and mucous membranes. If the condition worsens or does not improve within a reasonable timeframe, clinical re-evaluation of the wound is necessary to rule out underlying severe infection or poor vascular supply. Discontinue use if signs of local hypersensitivity or severe irritation occur.', '- **Wound Healing:** Promotion of healing in burns, cuts, wounds, abrasions, and surgical incisions.
INSERT INTO "drug_generic" VALUES(1829, 'Ketoprofen 2.5% Topical', 'Ketoprofen Topical', 'M02AA10', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Photosensitivity Reactions", "severity": "High", "trigger_condition": "Exposure of treated skin to sunlight or UV light", "message": "STOP: Severe photosensitivity reactions can occur. Patients must protect treated areas from sunlight and UV light during treatment and for 2 weeks following discontinuation."}]', '**Skin Integrity:** Do not apply to broken skin, open wounds, infected skin, eczema, or acne.
INSERT INTO "drug_generic" VALUES(1830, 'Amoxicillin + Clarithromycin + Rabeprazole Sodium kit', 'Amoxicillin, Clarithromycin, and Rabeprazole', 'A02BD04', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "QT Prolongation and Arrhythmias", "severity": "High", "trigger_condition": "Concurrent use with QT-prolonging drugs or in patients with hypokalemia", "message": "STOP: Clarithromycin is associated with QT prolongation and fatal arrhythmias (Torsades de Pointes). Avoid in patients with uncorrected hypokalemia/hypomagnesemia or those taking Class IA/III antiarrhythmics."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Development of jaundice or elevated liver enzymes", "message": "STOP: Clarithromycin can cause severe, potentially fatal hepatic failure. Discontinue immediately if signs of hepatitis occur."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with nearly all antibacterial agents, including amoxicillin and clarithromycin. Evaluate patients who develop severe diarrhea.
INSERT INTO "drug_generic" VALUES(1831, 'Mercaptopurine', 'Mercaptopurine', 'L01BB02', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Myelosuppression", "severity": "High", "trigger_condition": "Initiation of therapy or dose adjustment", "message": "Mercaptopurine causes severe myelosuppression (leukopenia, thrombocytopenia, anemia). Monitor complete blood counts frequently. Patients with TPMT or NUDT15 deficiency are at significantly increased risk of severe and fatal toxicity."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Routine monitoring", "message": "Hepatotoxicity, including cholestatic jaundice and hepatic necrosis, can occur. Monitor liver function tests periodically. Discontinue if clinically significant hepatotoxicity develops."}]', 'Monitor complete blood counts (CBC) and liver function tests (LFTs) frequently. Evaluate patients for Thiopurine S-methyltransferase (TPMT) and NUDT15 deficiency prior to initiation, as homozygous or heterozygous deficiencies require substantial dose reductions to prevent life-threatening myelosuppression. Mercaptopurine is potentially mutagenic and carcinogenic; secondary malignancies (e.g., hepatosplenic T-cell lymphoma) have been reported, particularly in patients with inflammatory bowel disease receiving concomitant immunosuppressants. Use with caution in patients with renal or hepatic dysfunction.', '- **Acute Lymphoblastic Leukemia (ALL):** Maintenance therapy of acute lymphatic (lymphocytic, lymphoblastic) leukemia as part of a combination regimen.
INSERT INTO "drug_generic" VALUES(1832, 'Pramoxine + Menthol + Dimethicone topical', 'Pramoxine, Menthol, and Dimethicone', 'D04AB', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Ocular Exposure:** Keep out of eyes. If accidental exposure occurs, flush thoroughly with water.
INSERT INTO "drug_generic" VALUES(1833, 'Atovaquone', 'Atovaquone', 'P01AX06', 1, 0, 0, 0, 0, 0, 1, 0, '[]', 'Oral absorption is highly dependent on food intake; failure to administer with a high-fat meal can significantly reduce plasma concentrations, leading to therapeutic failure. Consider alternative therapies in patients with severe gastrointestinal disorders that may limit absorption. Cases of cholestatic hepatitis, elevated liver enzymes, and fatal liver failure have been reported; monitor liver function tests closely, especially in patients with pre-existing severe hepatic impairment. Use with caution in elderly patients due to potential age-related decreases in hepatic, renal, or cardiac function.', '- **Pneumocystis jirovecii Pneumonia (PCP):** Indicated for the acute oral treatment of mild-to-moderate PCP in patients who are intolerant to trimethoprim-sulfamethoxazole (TMP-SMX). Also indicated for the prevention of PCP in patients who are intolerant to TMP-SMX.
INSERT INTO "drug_generic" VALUES(1834, 'Rosuvastatin', 'Rosuvastatin', 'C10AA07', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Concurrent use with interacting drugs (e.g., gemfibrozil, cyclosporine) or severe renal impairment", "message": "STOP: Rosuvastatin carries a risk of skeletal muscle effects, including myopathy and rhabdomyolysis, which can lead to acute renal failure. The risk increases with higher doses, advanced age, hypothyroidism, and concurrent use of certain drugs."}]', '**Skeletal Muscle Effects:** Risk of myopathy and rhabdomyolysis. Instruct patients to promptly report unexplained muscle pain, tenderness, or weakness, particularly if accompanied by malaise or fever. Discontinue if markedly elevated CK levels occur or myopathy is diagnosed.
INSERT INTO "drug_generic" VALUES(1835, 'Paracetamol IV', 'Acetaminophen Injection', 'N02BE01', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Dosing Error Risk", "severity": "High", "trigger_condition": "Prescribing in mg vs mL, or dosing in patients < 50 kg", "message": "STOP: Take care when prescribing and administering IV paracetamol to avoid dosing errors due to confusion between milligrams (mg) and milliliters (mL). Ensure the dose is weight-based for patients < 50 kg to prevent fatal hepatotoxicity."}]', '**Hepatotoxicity:** Severe liver injury, including cases of acute liver failure resulting in liver transplant and death, has been reported. The risk is highest in patients with underlying hepatic disease, chronic alcoholism, severe malnutrition, anorexia, or hypovolemia.
INSERT INTO "drug_generic" VALUES(1836, 'Halometasone 0.05% + Triclosan 1% topical', 'Halometasone / Triclosan Topical', 'D07BC03', 1, 0, 0, 0, 0, 1, 0, 1, '[]', '**Systemic Absorption:** High risk of systemic absorption of the corticosteroid leading to reversible hypothalamic-pituitary-adrenal (HPA) axis suppression when applied to large surface areas, broken skin, or under occlusive dressings.
INSERT INTO "drug_generic" VALUES(1837, 'Flurazepam', 'Flurazepam', 'N05CD01', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Concomitant Use with Opioids", "severity": "High", "trigger_condition": "Co-administration with opioid analgesics", "message": "STOP: Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death. Reserve concomitant prescribing for patients with inadequate alternative treatment options."}]', '- **Respiratory Depression:** Use with extreme caution in patients with chronic pulmonary insufficiency or sleep apnea; respiratory depression and hypotension can occur, especially with parenteral administration.
INSERT INTO "drug_generic" VALUES(1838, 'Cemiplimab', 'Cemiplimab', 'L01FF06', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Immune-Mediated Adverse Reactions", "severity": "High", "trigger_condition": "Patients presenting with new-onset respiratory, gastrointestinal, hepatic, or endocrine symptoms", "message": "STOP: Severe and fatal immune-mediated adverse reactions (pneumonitis, colitis, hepatitis, endocrinopathies, nephritis) can occur. Withhold therapy and initiate high-dose corticosteroids promptly if suspected."}]', '**Immune-Mediated Adverse Reactions:** Immune-mediated adverse reactions, which may be severe or fatal, can occur in any organ system or tissue. These include immune-mediated pneumonitis, colitis, hepatitis, endocrinopathies (e.g., adrenal insufficiency, hypophysitis, type 1 diabetes mellitus), dermatologic adverse reactions, nephritis and renal dysfunction, and solid organ transplant rejection. Withhold or permanently discontinue cemiplimab based on the severity of the reaction and administer corticosteroids as appropriate.
INSERT INTO "drug_generic" VALUES(1839, 'Aceclofenac', 'Aceclofenac', 'M01AB16', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Patient with history of ischemic heart disease or undergoing CABG", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. Contraindicated in the setting of CABG surgery."}, {"alert_type": "Gastrointestinal Risk", "severity": "High", "trigger_condition": "Patient with active peptic ulcer disease or history of GI bleeding", "message": "STOP: NSAIDs cause an increased risk of serious GI adverse events including bleeding, ulceration, and perforation, which can be fatal."}]', '**Cardiovascular Thrombotic Events:** Increased risk of serious, potentially fatal cardiovascular thrombotic events, MI, and stroke. Risk increases with duration of use and in patients with underlying CV disease.
INSERT INTO "drug_generic" VALUES(1840, 'Sennosides (Senna)', 'Sennosides', 'A06AB06', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Prolonged Use:** Avoid prolonged use (greater than 1 week) unless directed by a physician, as it may lead to laxative dependence, loss of normal bowel function, and atonic non-functioning colon (cathartic colon).
INSERT INTO "drug_generic" VALUES(1841, 'Pneumococcal Polysaccharide Conjugated Vaccine', 'Pneumococcal Conjugate Vaccine (PCV)', 'J07AL02', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "Previous severe allergic reaction to vaccine components", "message": "STOP: Contraindicated in patients with a history of severe allergic reaction (e.g., anaphylaxis) to any component of the vaccine or to diphtheria toxoid."}]', 'Postpone vaccination in individuals suffering from acute severe febrile illness. Patients with impaired immune responsiveness (e.g., due to immunosuppressive therapy, genetic defect, HIV infection) may have a reduced antibody response. If possible, administer the vaccine at least 2 weeks before initiating immunosuppressive treatment or wait at least 3 months after treatment completion. Caution in patients with severe renal, hepatic, cardiac, vascular, or pulmonary dysfunction. Apnea following intramuscular vaccination has been observed in some premature infants; consider respiratory monitoring for 48-72 hours when administering the primary immunization series to very premature infants (born ≤28 weeks of gestation).', '- **Pneumococcal Disease Prophylaxis:** Active immunization for the prevention of invasive disease, pneumonia, and acute otitis media caused by *Streptococcus pneumoniae* serotypes included in the vaccine.
INSERT INTO "drug_generic" VALUES(1842, 'Amlodipine + Atenolol', 'Amlodipine and Atenolol', 'C07FB03', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Abrupt Discontinuation", "severity": "High", "trigger_condition": "Sudden cessation of therapy", "message": "STOP: Severe exacerbation of angina, myocardial infarction, and ventricular arrhythmias have occurred following the abrupt discontinuation of beta-blockers. Taper the dose gradually over 1 to 2 weeks."}]', '**Bronchospastic Disease:** Atenolol is a cardioselective beta-blocker, but selectivity is not absolute. Use with caution in patients with asthma or COPD; use the lowest possible dose.
INSERT INTO "drug_generic" VALUES(1843, 'Cefpirome', 'Cefpirome', 'J01DE02', 1, 0, 1, 0, 1, 1, 0, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(1844, 'Delafloxacin', 'Delafloxacin', 'J01MA23', 1, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Tendon Rupture and Neuropathy", "severity": "High", "trigger_condition": "Patient reports joint pain, tendon pain, or numbness/tingling", "message": "STOP: Fluoroquinolones are associated with disabling and potentially irreversible serious adverse reactions, including tendinitis, tendon rupture, peripheral neuropathy, and CNS effects. Discontinue immediately if these occur."}, {"alert_type": "Myasthenia Gravis Exacerbation", "severity": "High", "trigger_condition": "Patient has a history of myasthenia gravis", "message": "STOP: Fluoroquinolones may exacerbate muscle weakness in patients with myasthenia gravis. Avoid use in these patients."}]', '**Tendinitis and Tendon Rupture:** Increased risk in all ages; Achilles tendon is most frequently involved. Risk is further increased in older patients (usually >60 years), those taking corticosteroids, and kidney, heart, or lung transplant recipients. Discontinue at the first sign of tendon pain or inflammation.
INSERT INTO "drug_generic" VALUES(1845, 'Diptheria + tetanus + pertussis + hepatitis B + inactivated polio vaccine + Haemophilus influenza type B (HIB) Vaccine', 'Diphtheria, Tetanus, Pertussis, Hepatitis B, Poliovirus, and Haemophilus b Vaccine', 'J07CA09', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Anaphylaxis and Encephalopathy", "severity": "High", "trigger_condition": "History of severe allergic reaction or encephalopathy after previous dose", "message": "STOP: Contraindicated if the patient experienced encephalopathy within 7 days of a previous pertussis vaccine or a severe allergic reaction to any component, including neomycin or polymyxin."}]', '**Neurological Events:** Caution in children with progressive neurological disorders, infantile spasms, uncontrolled epilepsy, or progressive encephalopathy. Defer vaccination until the condition is stabilized.
INSERT INTO "drug_generic" VALUES(1846, 'Multivitamins', 'Multivitamins', 'A11BA', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Intravenous administration", "message": "STOP: Severe allergic reactions, including anaphylaxis, can occur with intravenous multivitamin preparations (often due to thiamine). Administer slowly and monitor the patient."}]', '**Renal Impairment:** Use with caution in patients with mild to moderate renal failure. Accumulation of fat-soluble vitamins (A, D, E, K) can occur.
INSERT INTO "drug_generic" VALUES(1847, 'Roxithromycin', 'Roxithromycin', 'J01FA06', 1, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity and QT Prolongation", "severity": "High", "trigger_condition": "Prolonged use or concurrent use with QT-prolonging agents", "message": "STOP: Prolonged treatment increases the risk of hepatotoxicity. Macrolides can prolong the QT interval; avoid in patients with a history of arrhythmias or those taking other QT-prolonging drugs."}]', 'Use with caution in patients with hepatic impairment; monitor liver function tests regularly. Prolonged treatment increases the risk of hepatotoxicity. Caution is advised in patients with a history of arrhythmias or those with congenital QT prolongation, as macrolides can cause QT interval prolongation. Monitor for signs of superinfection or Clostridioides difficile-associated diarrhea (CDAD).', '- **Respiratory Tract Infections:** Treatment of community-acquired pneumonia, acute and chronic bronchitis, and bronchopneumonia caused by susceptible organisms (e.g., Mycoplasma pneumoniae, Chlamydophila pneumoniae).
INSERT INTO "drug_generic" VALUES(1848, 'Abacavir + Dolutegravir + Lamivudine', 'Abacavir, Dolutegravir, and Lamivudine', 'J05AR13', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Presence of HLA-B*5701 allele", "message": "STOP: Severe and potentially fatal hypersensitivity reactions can occur. Screen for the HLA-B*5701 allele prior to initiating therapy. Discontinue immediately if hypersensitivity is suspected."}, {"alert_type": "Hepatitis B Exacerbation", "severity": "High", "trigger_condition": "Co-infection with Hepatitis B Virus (HBV)", "message": "STOP: Severe acute exacerbations of hepatitis B have been reported in patients who are co-infected with HBV and HIV-1 and have discontinued lamivudine or abacavir. Monitor hepatic function closely."}]', '**Hepatotoxicity:** Hepatic toxicity, including elevated serum liver biochemistries, hepatitis, and acute liver failure, has been reported even in patients without pre-existing hepatic disease. Monitor liver function tests (LFTs) regularly.
INSERT INTO "drug_generic" VALUES(1849, 'Calcium Carbonate (Eggshell Source) + Vitamin D3', 'Calcium Carbonate + Cholecalciferol', 'A12AX', 0, 0, 1, 1, 1, 1, 0, 0, '[]', '**Renal Impairment:** Patients with mild to moderate renal failure or mild hypercalciuria should be supervised carefully, including periodic checks of plasma calcium levels and urinary calcium excretion.
INSERT INTO "drug_generic" VALUES(1850, 'Estradiol + Dydrogesterone', 'Estradiol and Dydrogesterone', 'G03FB08', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Cancer Risks", "severity": "High", "trigger_condition": "Long-term use of Hormone Replacement Therapy (HRT)", "message": "STOP: HRT increases the risk of venous thromboembolism (DVT, PE), stroke, and breast cancer. It should only be initiated for symptoms that adversely affect quality of life, and continued only as long as the benefit outweighs the risk. Re-evaluate at least annually."}]', '**Medical Examination:** Before initiating or reinstituting HRT, a complete personal and family medical history should be taken, along with a physical examination (including pelvic and breast). Periodic check-ups and mammography are recommended during treatment.
INSERT INTO "drug_generic" VALUES(1851, 'Estradiol valerate', 'Estradiol valerate', 'G03CA03', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Cardiovascular and Malignancy Risks", "severity": "High", "trigger_condition": "Systemic estrogen therapy", "message": "STOP: Estrogens increase the risk of deep vein thrombosis (DVT), pulmonary embolism (PE), stroke, and myocardial infarction. Estrogens also increase the risk of endometrial cancer in women with an intact uterus. Do not use for the prevention of cardiovascular disease or dementia."}]', '**Cardiovascular Disorders:** Increased risk of stroke, DVT, and PE. Discontinue immediately if a thromboembolic event occurs.
INSERT INTO "drug_generic" VALUES(1852, 'Poly (O-2-hydroxyethyl) starch 100gm + Sodium Chloride', 'Hydroxyethyl Starch in Sodium Chloride', 'B05AA07', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Boxed Warning: Mortality and Renal Injury", "severity": "High", "trigger_condition": "Critically ill adult patients, including those with sepsis", "message": "STOP: Do not use hydroxyethyl starch (HES) solutions in critically ill adult patients, including those with sepsis, due to increased risk of mortality and renal replacement therapy."}]', '**Fluid Overload and Hemodilution:** Regular assessment of fluid status and infusion rate is mandatory, particularly in patients with cardiac insufficiency or severe kidney dysfunction, to prevent hyperhydration and non-cardiac pulmonary edema.
INSERT INTO "drug_generic" VALUES(1853, 'Dutasteride', 'Dutasteride', 'G04CB02', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Teratogenicity Risk", "severity": "High", "trigger_condition": "Handling by pregnant women or women of childbearing potential", "message": "STOP: Dutasteride is highly teratogenic. Women who are pregnant or may become pregnant must not handle crushed or leaking capsules due to the risk of transdermal absorption and subsequent feminization of a male fetus."}]', '**Prostate Cancer Evaluation:** Prior to initiating therapy, evaluate patients to rule out other urological conditions, including prostate cancer. Dutasteride reduces serum prostate-specific antigen (PSA) levels by approximately 50% within 3 to 6 months; establish a new baseline PSA to monitor for prostate cancer.
INSERT INTO "drug_generic" VALUES(1854, 'Pyridoxine Hydrochloride + Riboflavin + Vitamin B1', 'Vitamin B Complex (B1, B2, B6)', 'A11EA', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Caution in patients receiving levodopa monotherapy, as pyridoxine can reverse its effects. High doses of pyridoxine over prolonged periods can cause sensory neuropathy. Riboflavin may cause a harmless yellow-orange discoloration of the urine, which patients should be informed about to prevent unnecessary alarm.', '- **Vitamin B Deficiency:** Treatment and prophylaxis of deficiencies in Thiamine (B1), Riboflavin (B2), and Pyridoxine (B6).
INSERT INTO "drug_generic" VALUES(1855, 'Sofosbuvir + Velpatasvir + Voxilaprevir', 'Sofosbuvir/Velpatasvir/Voxilaprevir', 'J05AP56', 0, 0, 1, 0, 1, 0, 0, 0, '[{"alert_type": "Hepatitis B Reactivation", "severity": "High", "trigger_condition": "HCV/HBV coinfection", "message": "STOP: Hepatitis B virus (HBV) reactivation has been reported in HCV/HBV coinfected patients receiving direct-acting antivirals, sometimes resulting in fulminant hepatitis, hepatic failure, and death. Test all patients for evidence of current or prior HBV infection before initiating treatment."}]', '**Hepatitis B Virus (HBV) Reactivation:** Test all patients for evidence of current or prior HBV infection by measuring HBsAg and anti-HBc before initiating treatment. HBV reactivation has been reported in HCV/HBV coinfected patients who were undergoing or had completed treatment with HCV direct-acting antivirals and were not receiving HBV antiviral therapy. Monitor coinfected patients for clinical and laboratory signs of hepatitis flare or HBV reactivation during and post-treatment.
INSERT INTO "drug_generic" VALUES(1856, 'Pentoxifylline', 'Pentoxifylline', 'C04AD03', 0, 0, 0, 0, 1, 0, 0, 0, '[]', '- **Cardiovascular Disease:** Use with caution in patients with severe cardiac arrhythmias, ischemic heart disease, or hypotension, as it may exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1857, 'Carbamide peroxide oral', 'Carbamide peroxide', 'D02AE01', 0, 0, 0, 1, 0, 0, 0, 0, '[]', 'Overgrowth of opportunistic infections is possible with prolonged use. Consult a dentist or physician if severe or persistent oral inflammation occurs, or if symptoms do not improve within 7 days.', '- **Canker Sores and Oral Irritation:** Used for the temporary relief of minor oral inflammation, canker sores, and gum irritation.
INSERT INTO "drug_generic" VALUES(1858, 'Ciprofloxacin 0.3% + Hydrocortisone Acetate 1% E/E prep', 'Ciprofloxacin and Hydrocortisone Otic/Ophthalmic', 'S02CA03', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Tympanic Membrane Perforation", "severity": "High", "trigger_condition": "Use in patients with perforated eardrums (for non-sterile otic suspensions)", "message": "Do not use non-sterile otic suspensions in patients with a perforated tympanic membrane due to the risk of middle/inner ear toxicity. Ensure the tympanic membrane is intact before prescribing for otitis externa."}]', '**Superinfection:** Prolonged use may result in the overgrowth of nonsusceptible organisms, including fungi. Discontinue if superinfection occurs.
INSERT INTO "drug_generic" VALUES(1859, 'Spironolactone + Hydrochlorothiazide', 'Spironolactone and Hydrochlorothiazide', 'C03EA01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hyperkalemia Risk", "severity": "High", "trigger_condition": "Renal impairment, diabetes, or concomitant use of ACE inhibitors/ARBs/potassium supplements", "message": "STOP: Spironolactone can cause severe, potentially fatal hyperkalemia. Monitor serum potassium closely, especially in patients with renal insufficiency or those taking other potassium-sparing agents."}]', '**Hyperkalemia:** Spironolactone can cause severe hyperkalemia. Risk is increased in patients with renal insufficiency, diabetes mellitus, or if coadministered with ACE inhibitors, ARBs, or potassium supplements.
INSERT INTO "drug_generic" VALUES(1860, 'Clioquinol 1% + Flumetasone Pivalate 0.02% Ear prep', 'Clioquinol and Flumethasone Otic', 'S02CA02', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Tympanic Membrane Perforation", "severity": "High", "trigger_condition": "Use in patients with a perforated eardrum", "message": "Contraindicated in patients with a perforated tympanic membrane due to the risk of ototoxicity and middle/inner ear damage. Ensure the eardrum is intact before prescribing."}]', '**Systemic Absorption:** Prolonged use or application to large areas may lead to systemic absorption of the corticosteroid (flumetasone), potentially causing hypothalamic-pituitary-adrenal (HPA) axis suppression, especially in children.
INSERT INTO "drug_generic" VALUES(1861, 'Ebastine', 'Ebastine', 'R06AX22', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "QTc Prolongation", "severity": "Moderate", "trigger_condition": "Concomitant use with CYP3A4 inhibitors or pre-existing cardiac arrhythmias", "message": "Caution: Ebastine may cause QTc interval prolongation, especially when co-administered with macrolide antibiotics or azole antifungals. Monitor ECG in high-risk patients."}]', '**Cardiac Arrhythmias and QTc Prolongation:** Use with caution in patients with known cardiac arrhythmias, hypokalemia, or those taking medications known to prolong the QTc interval. High doses or impaired metabolism can lead to clinically significant QTc prolongation.
INSERT INTO "drug_generic" VALUES(1862, 'Thalidomide', 'Thalidomide', 'L04AX02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Teratogenicity", "severity": "High", "trigger_condition": "Use in females of reproductive potential", "message": "STOP: Thalidomide is a known human teratogen causing severe, life-threatening birth defects (phocomelia). Strict adherence to a restricted distribution program (REMS) and mandatory contraception is required."}, {"alert_type": "Venous Thromboembolism", "severity": "High", "trigger_condition": "Use in patients with multiple myeloma, especially with dexamethasone", "message": "STOP: Significantly increased risk of deep vein thrombosis (DVT) and pulmonary embolism (PE). Prophylactic anticoagulation is strongly recommended."}]', '**Peripheral Neuropathy:** Can cause severe, irreversible peripheral neuropathy. Monitor for symptoms (numbness, tingling, pain) and discontinue if they occur.
INSERT INTO "drug_generic" VALUES(1863, 'Sibutramine Hydrochloride', 'Sibutramine', 'A08AA10', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Patients with a history of cardiovascular disease", "message": "STOP: Sibutramine substantially increases the risk of major adverse cardiovascular events (non-fatal myocardial infarction, non-fatal stroke, resuscitation after cardiac arrest, and cardiovascular death). It has been withdrawn from the market in many countries due to this risk."}]', '**Blood Pressure and Heart Rate:** Substantially increases blood pressure and heart rate in some patients. Regular monitoring is required. Discontinue if clinically significant, sustained increases occur.
INSERT INTO "drug_generic" VALUES(1864, 'Algae Calcium', 'Algae-Sourced Calcium', 'A12AA', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "Moderate", "trigger_condition": "High dose supplementation", "message": "Excessive calcium supplementation can lead to hypercalcemia and kidney stones. Do not exceed the recommended daily allowance unless directed by a physician."}]', '**Kidney Stones:** Patients with a history of kidney stones should be advised to increase fluid intake and monitor calcium intake to prevent recurrence.
INSERT INTO "drug_generic" VALUES(1865, 'Amifostine', 'Amifostine', 'V03AF05', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Cutaneous Reactions", "severity": "High", "trigger_condition": "Appearance of erythematous, edematous, or bullous lesions", "message": "STOP: Fatal and severe cutaneous reactions (SJS, TEN, DRESS) have been reported. Discontinue immediately for cutaneous reactions appearing outside the injection site or radiation port, or for lesions on the palms/soles."}, {"alert_type": "Severe Hypotension", "severity": "High", "trigger_condition": "Administration of IV infusion", "message": "STOP: Profound hypotension can occur. Patients must be adequately hydrated prior to infusion. Monitor blood pressure continuously. Interrupt antihypertensive therapy 24 hours before treatment."}]', 'Ensure adequate hydration prior to administration to mitigate hypotensive effects.
INSERT INTO "drug_generic" VALUES(1866, 'Lithium Carbonate', 'Lithium Carbonate', 'N05AN01', 0, 1, 0, 0, 1, 1, 1, 1, '[{"alert_type": "Lithium Toxicity", "severity": "High", "trigger_condition": "Serum lithium levels exceeding 1.5 mEq/L or conditions causing sodium depletion", "message": "STOP: Lithium toxicity is closely related to serum lithium levels and can occur at doses close to therapeutic levels. Monitor serum levels regularly and maintain adequate hydration and sodium intake."}]', '**Lithium Toxicity:** Toxicity is closely related to serum lithium concentrations and can occur at doses close to therapeutic levels. Facilities for prompt and accurate serum lithium determinations should be available before initiating therapy.
INSERT INTO "drug_generic" VALUES(1867, 'Sulphar +  salicylic acid (10%  & 3% ) Topical', 'Sulfur and Salicylic acid topical', 'D10AB', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Salicylate Toxicity", "severity": "Moderate", "trigger_condition": "Application to large body surface areas or prolonged use", "message": "WARNING: Systemic absorption of salicylic acid can occur, especially in young children or when applied to large areas, potentially leading to salicylate toxicity (salicylism)."}]', '**Systemic Absorption:** Salicylic acid can be absorbed systemically. Avoid application to large areas of the body or for prolonged periods to prevent salicylism (tinnitus, nausea, vomiting).
INSERT INTO "drug_generic" VALUES(1868, 'Gadoversetamide', 'Gadoversetamide', 'V08CA06', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Nephrogenic Systemic Fibrosis (NSF)", "severity": "High", "trigger_condition": "Patients with chronic, severe kidney disease (GFR < 30 mL/min/1.73m\u00b2) or acute kidney injury", "message": "STOP: Gadolinium-based contrast agents (GBCAs) increase the risk for NSF, a debilitating and potentially fatal disease. Avoid use in severe renal impairment unless diagnostic information is essential and unavailable via other modalities."}]', '**Nephrogenic Systemic Fibrosis (NSF):** GBCAs increase the risk for NSF among patients with impaired elimination of the drugs. The risk is highest in patients with chronic, severe kidney disease (GFR < 30 mL/min/1.73m²) and acute kidney injury. Screen all patients for renal dysfunction prior to administration.
INSERT INTO "drug_generic" VALUES(1869, 'Dobutamine', 'Dobutamine', 'C01CA07', 0, 1, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Arrhythmias and Hemodynamic Instability", "severity": "High", "trigger_condition": "Hypovolemia or unmonitored administration", "message": "STOP: Dobutamine can cause marked increases in heart rate and blood pressure, and precipitate fatal arrhythmias. Hypovolemia MUST be corrected prior to initiation. Continuous ECG and blood pressure monitoring are mandatory."}]', '- **Hypovolemia:** Must be corrected with appropriate volume expanders before initiating dobutamine therapy to ensure adequate ventricular filling and cardiac output.
INSERT INTO "drug_generic" VALUES(1870, 'Phentermine', 'Phentermine', 'A08AA01', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Cardiovascular Toxicity", "severity": "High", "trigger_condition": "Concomitant use with other weight-loss agents or in patients with underlying cardiovascular disease", "message": "STOP: Rare but fatal cases of primary pulmonary hypertension and valvular heart disease have been reported. Avoid use with other anorectic agents. Contraindicated in patients with cardiovascular disease."}]', '**Cardiovascular Disease:** Can cause an increase in blood pressure and heart rate. Use with caution in patients with mild hypertension; contraindicated in moderate-to-severe hypertension or established cardiovascular disease.
INSERT INTO "drug_generic" VALUES(1871, 'Calcium Chloride .514 % + Magnessium Chloride .356 + Potassium Chloride .521 % + Sodium Acetate 18.088 % + Sodium Chloride 19.84 % (Hemodialysis solutions)', 'Hemodialysis Concentrate', 'B05ZA', 0, 1, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Administration Route Safety", "severity": "High", "trigger_condition": "Direct intravenous injection", "message": "STOP: This is a highly concentrated solution for HEMODIALYSIS ONLY. It must be diluted with purified water via a hemodialysis machine before use. Direct intravenous injection will cause fatal electrolyte imbalances and cardiac arrest."}]', '**Dilution Required:** Must be diluted with purified water according to the manufacturer''s instructions using a hemodialysis machine. Never inject the concentrate directly into the patient.
INSERT INTO "drug_generic" VALUES(1872, 'Naloxone Hydrochloride', 'Naloxone Hydrochloride', 'V03AB15', 0, 1, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Precipitated Opioid Withdrawal", "severity": "High", "trigger_condition": "Administration to opioid-dependent patients", "message": "STOP: Abrupt reversal of opioid depression in physically dependent patients can precipitate an acute withdrawal syndrome. This may manifest as severe body aches, diarrhea, tachycardia, fever, runny nose, sneezing, piloerection, sweating, yawning, nausea or vomiting, nervousness, restlessness or irritability, shivering or trembling, abdominal cramps, weakness, and increased blood pressure."}]', '- **Opioid Dependence:** Use with extreme caution in patients physically dependent on opioids or who have recently received large doses of opioids, as rapid reversal can precipitate acute withdrawal syndrome.
INSERT INTO "drug_generic" VALUES(1873, 'Ravulizumab', 'Ravulizumab-cwvz', 'L04AJ02', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Serious Meningococcal Infections", "severity": "High", "trigger_condition": "Initiation of therapy without prior vaccination", "message": "STOP: Life-threatening and fatal meningococcal infections have occurred. Vaccinate patients according to current ACIP guidelines at least 2 weeks prior to starting therapy unless the risks of delaying therapy outweigh the risks of infection."}]', '**Meningococcal Infections:** Ravulizumab increases susceptibility to serious, life-threatening meningococcal infections (Neisseria meningitidis). Vaccinate patients at least 2 weeks prior to initiation. Monitor for early signs of infection and evaluate immediately if suspected.
INSERT INTO "drug_generic" VALUES(1874, 'Adapalene 0.1% Topical', 'Adapalene', 'D10AD03', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Photosensitivity and Skin Irritation", "severity": "Medium", "trigger_condition": "Exposure to sunlight or UV light", "message": "STOP: Adapalene increases sensitivity to UV light. Minimize sun exposure, avoid tanning beds, and use sunscreen daily. Do not apply to sunburned, cut, or eczematous skin."}]', '**Skin Irritation:** Erythema, scaling, dryness, and stinging/burning may occur, most commonly during the first 2 to 4 weeks of treatment. These effects generally subside with continued use. If severe, reduce application frequency or discontinue temporarily.
INSERT INTO "drug_generic" VALUES(1875, 'Dextrose Hydrous + Sodium Chloride + Sodium Lactate + Calcium chloride + Magnesium chloride (Peritoneal dialysis solution)', 'Peritoneal Dialysis Solution', 'B05DB', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Peritonitis and Fluid Imbalance", "severity": "High", "trigger_condition": "Cloudy effluent or improper aseptic technique", "message": "STOP: Cloudy drained fluid indicates peritonitis. Strict aseptic technique is mandatory. Monitor for severe fluid and electrolyte shifts."}]', '**Infection Risk:** Aseptic technique must be strictly employed throughout the procedure to prevent peritonitis and catheter site infections. Inspect drained fluid for fibrin or cloudiness, which strongly indicates peritonitis.
INSERT INTO "drug_generic" VALUES(1876, 'Clemastine', 'Clemastine', 'R06AA04', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "CNS Depression", "severity": "Moderate", "trigger_condition": "Concurrent use of alcohol or other CNS depressants", "message": "May cause significant CNS depression, impairing physical and mental abilities. Advise patients against driving or operating heavy machinery."}]', '**CNS Depression:** May produce marked drowsiness and impair the mental or physical abilities required for the performance of potentially hazardous tasks such as driving a car or operating machinery.
INSERT INTO "drug_generic" VALUES(1877, 'Chlorpheniramine + Pseudoepedrine', 'Chlorpheniramine + Pseudoephedrine', 'R01BA52', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "MAOI Interaction", "severity": "High", "trigger_condition": "Concurrent use of Monoamine Oxidase Inhibitors (MAOIs)", "message": "STOP: Contraindicated during or within 14 days of stopping an MAOI due to the risk of severe, life-threatening hypertensive crisis."}]', '**Cardiovascular Disease:** Pseudoephedrine is a sympathomimetic amine. Use with caution in patients with hypertension, ischemic heart disease, or arrhythmias, as it can elevate blood pressure and heart rate.
INSERT INTO "drug_generic" VALUES(1878, 'Alectinib', 'Alectinib', 'L01ED03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated transaminases or bilirubin", "message": "Severe hepatotoxicity, including drug-induced liver injury, can occur. Monitor liver function tests every 2 weeks for the first 3 months, then monthly."}, {"alert_type": "Interstitial Lung Disease (ILD)", "severity": "High", "trigger_condition": "Worsening respiratory symptoms (dyspnea, cough, fever)", "message": "Promptly investigate for ILD/pneumonitis. Immediately withhold treatment if suspected and permanently discontinue if confirmed."}]', '**Hepatotoxicity:** Severe hepatotoxicity, including drug-induced liver injury, has been reported. Monitor liver function tests (ALT, AST, and total bilirubin) every 2 weeks during the first 3 months of treatment, then once monthly and as clinically indicated. More frequent testing is required in patients who develop transaminase and bilirubin elevations. Modify or permanently discontinue the dose as recommended based on severity.
INSERT INTO "drug_generic" VALUES(1879, 'Carboxymethylcellulose Sodium Eye prep', 'Carboxymethylcellulose Sodium Ophthalmic', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Contamination Risk", "severity": "Moderate", "trigger_condition": "Touching the dropper tip to any surface", "message": "STOP: Do not touch the tip of the container to any surface, including the eye, to avoid contamination and potential severe eye infections."}]', '**Visual Disturbances:** May cause temporary blurred vision immediately after instillation. Patients should be advised not to drive or operate hazardous machinery until their vision clears.
INSERT INTO "drug_generic" VALUES(1880, 'Avapritinib', 'Avapritinib', 'L01EX18', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Intracranial Hemorrhage", "severity": "High", "trigger_condition": "Any occurrence of intracranial hemorrhage", "message": "STOP: Permanently discontinue Avapritinib for any occurrence of intracranial hemorrhage of any grade. Monitor patients closely for neurological symptoms."}]', '**Intracranial Hemorrhage:** Severe and potentially fatal intracranial hemorrhage can occur. Permanently discontinue the drug for any occurrence of any grade. Monitor for neurological symptoms such as severe headache, vision changes, or altered mental status.
INSERT INTO "drug_generic" VALUES(1881, 'Hydroxypropyl Methylcellulose', 'Hypromellose', 'S01KA02', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Increased Intraocular Pressure", "severity": "Moderate", "trigger_condition": "Postoperative period following intraocular surgery", "message": "WARNING: Transient increased intraocular pressure (IOP) may occur postoperatively. The gel MUST be thoroughly removed from the anterior chamber at the end of the surgical procedure."}]', '**Intraocular Pressure (IOP) Spikes:** There may be a transient increase in intraocular pressure following surgery due to pre-existing glaucoma, the surgery itself, or retained viscoelastic material. To minimize this risk, the gel should be meticulously removed from the anterior chamber at the end of the surgery by irrigation and aspiration. Monitor postoperative IOP closely and provide appropriate IOP-lowering therapy if it increases above expected values.
INSERT INTO "drug_generic" VALUES(1882, 'Cyanocobalamin + Elemental Iron + Folic Acid', 'Cyanocobalamin, Iron, and Folic Acid', 'B03AD', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Accidental Iron Overdose", "severity": "High", "trigger_condition": "Accidental ingestion by children", "message": "WARNING: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children. In case of accidental overdose, seek emergency medical help immediately."}]', '**Gastrointestinal Disorders:** Use oral iron preparations with caution in patients with gastritis, peptic ulcer disease, Crohn''s disease, and ulcerative colitis, as iron can exacerbate mucosal irritation.
INSERT INTO "drug_generic" VALUES(1883, 'Hydroxychloroquine Sulphate', 'Hydroxychloroquine', 'P01BA02', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Retinal Toxicity", "severity": "High", "trigger_condition": "Long-term therapy or high cumulative doses", "message": "Irreversible retinal damage has been observed in some patients. Perform baseline and periodic (annual after 5 years, or sooner if high risk) ophthalmologic exams. Discontinue immediately if ocular toxicity is suspected."}]', 'Use with caution in patients with impaired liver or renal function, severe GI disorders, porphyria, psoriasis (may precipitate severe attacks), neurological disorders (especially a history of epilepsy), and G6PD deficiency (risk of hemolysis). Monitor CBC periodically in patients receiving prolonged therapy. Perform baseline and periodic eye exams (OCT and visual fields) to monitor for retinopathy. Test periodically for muscle weakness (neuromyopathy). May cause severe hypoglycemia; monitor blood glucose in symptomatic patients.', '- **Rheumatoid Arthritis:** Treatment of acute and chronic rheumatoid arthritis in adults.
INSERT INTO "drug_generic" VALUES(1884, 'Interferon Beta 1a', 'Interferon beta-1a', 'L03AB07', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Hepatic Injury", "severity": "High", "trigger_condition": "Patients with pre-existing hepatic impairment or those developing signs of liver dysfunction", "message": "STOP: Severe hepatic injury, including cases of hepatic failure requiring liver transplantation, has been reported. Monitor liver function tests closely. Discontinue if jaundice or clinical symptoms of liver injury appear."}, {"alert_type": "Depression and Suicide", "severity": "High", "trigger_condition": "Patients with a history of depression or those developing new psychiatric symptoms", "message": "STOP: Depression, suicidal ideation, and suicide attempts have been reported. Monitor patients closely for symptoms of depression. Consider discontinuation if severe psychiatric symptoms develop."}]', '**Depression and Suicide:** Depression, suicidal ideation, and suicide attempts have been reported. Advise patients to report any symptoms of depression or suicidal ideation immediately. Consider discontinuing therapy if severe depression occurs.
INSERT INTO "drug_generic" VALUES(1885, 'Zopiclone', 'Zopiclone', 'N05CF01', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Dependence and Complex Sleep Behaviors", "severity": "High", "trigger_condition": "Prolonged use or use with other CNS depressants", "message": "STOP: Zopiclone carries a risk of dependence, tolerance, and abuse. Complex sleep behaviors (e.g., sleep-walking, sleep-driving) can occur and may result in serious injury. Limit treatment to short-term use (<4 weeks)."}]', '**CNS Depression:** Impairs cognitive and motor performance. Patients should not drive or operate machinery the day after taking zopiclone until they know how it affects them.
INSERT INTO "drug_generic" VALUES(1886, 'Deferasirox', 'Deferasirox', 'V03AC03', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Renal, Hepatic, and Gastrointestinal Toxicity", "severity": "High", "trigger_condition": "Initiation of therapy or presence of baseline organ impairment", "message": "STOP: Deferasirox can cause fatal acute kidney injury, hepatic failure, and gastrointestinal hemorrhage. Baseline and continuous monitoring of renal and hepatic function is mandatory."}]', '**Acute Kidney Injury:** May cause serious and fatal acute kidney injury, including renal failure requiring dialysis and renal tubular toxicity (e.g., Fanconi syndrome). Measure serum creatinine in duplicate before starting therapy. Monitor renal function regularly and reduce dose or interrupt therapy for toxicity.
INSERT INTO "drug_generic" VALUES(1887, 'Calcium  +  Vitamin  (D3  +  C +  E)  +  Minerals', 'Calcium, Vitamins D3, C, E, and Minerals', 'A12AX', 0, 0, 1, 1, 1, 1, 0, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "Low", "message": "Excessive intake of Calcium and Vitamin D3 can lead to hypercalcemia and renal calculi. Do not exceed the recommended daily dosage."}]', '**Renal Impairment:** Use with caution in patients with mild to moderate renal failure. Calcium and fat-soluble vitamins can accumulate, leading to hypercalcemia and soft tissue calcification.
INSERT INTO "drug_generic" VALUES(1888, 'Desloratadine + Pseudoephedrine Sulphate', 'Desloratadine and Pseudoephedrine', 'R01BA52', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hypertensive Crisis", "severity": "High", "trigger_condition": "Concurrent use with MAO Inhibitors or severe cardiovascular disease", "message": "STOP: Pseudoephedrine is a sympathomimetic. Co-administration with MAOIs (or within 14 days of stopping) can cause a fatal hypertensive crisis. Contraindicated in severe hypertension or severe coronary artery disease."}]', '**Cardiovascular Effects:** Pseudoephedrine can cause tachycardia, palpitations, and elevations in blood pressure. Use with extreme caution in patients with mild to moderate hypertension, ischemic heart disease, or arrhythmias.
INSERT INTO "drug_generic" VALUES(1889, 'Potassium Chloride', 'Potassium Chloride', 'A12BA01', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Fatal Hyperkalemia", "severity": "High", "trigger_condition": "Rapid IV infusion or use in severe renal impairment", "message": "STOP: Intravenous potassium must NEVER be given as an undiluted IV push or bolus. Rapid infusion can cause fatal cardiac arrest. Always dilute and use an infusion pump."}, {"alert_type": "Gastrointestinal Ulceration", "severity": "High", "trigger_condition": "Use of solid oral dosage forms", "message": "STOP: Solid oral dosage forms can cause severe GI ulceration, bleeding, and perforation. Discontinue immediately if severe abdominal pain or vomiting occurs."}]', '**Intravenous Administration:** Must be diluted before IV administration. Never give via IV push. Continuous cardiac monitoring is essential for high-rate infusions (>10 mEq/hr).
INSERT INTO "drug_generic" VALUES(1890, 'Elbasvir + Grazoprevir', 'Elbasvir and Grazoprevir', 'J05AP54', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hepatitis B Reactivation", "severity": "High", "trigger_condition": "HCV/HBV coinfection without concurrent HBV antiviral therapy", "message": "STOP: Hepatitis B virus (HBV) reactivation has been reported in HCV/HBV coinfected patients undergoing or completing treatment with HCV direct-acting antivirals. This can result in severe hepatitis, hepatic failure, and death. Test all patients for evidence of current or prior HBV infection before initiating treatment."}]', '**Hepatitis B Virus Reactivation:** Test all patients for evidence of current or prior HBV infection by measuring HBsAg and anti-HBc before initiating treatment. Monitor HCV/HBV coinfected patients for clinical and laboratory signs of hepatitis flare or HBV reactivation during and post-treatment.
INSERT INTO "drug_generic" VALUES(1891, 'Estradiol Hemihydrate + Progesterone Micronized', 'Estradiol and Progesterone', 'G03FA04', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiovascular and Malignancy Risks", "severity": "High", "trigger_condition": "Initiation of Hormone Replacement Therapy", "message": "STOP: Estrogen plus progestin therapy increases the risk of myocardial infarction, stroke, pulmonary embolism, deep vein thrombosis, and invasive breast cancer. Do not use for the prevention of cardiovascular disease or dementia."}]', '**Cardiovascular Disorders:** Estrogen plus progestin therapy should not be used for the prevention of cardiovascular disease. The Women’s Health Initiative (WHI) reported increased risks of myocardial infarction (MI), stroke, pulmonary embolism (PE), and deep vein thrombosis (DVT) in postmenopausal women.
INSERT INTO "drug_generic" VALUES(1892, 'Sodium Thiosulfate', 'Sodium Thiosulfate', 'V03AB06', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Diagnostic Uncertainty in Cyanide Poisoning", "severity": "High", "trigger_condition": "Administration in suspected cyanide poisoning without confirmation", "message": "Use with caution if the diagnosis of cyanide poisoning is uncertain. However, in life-threatening situations where cyanide poisoning is highly suspected, do not delay treatment pending laboratory confirmation."}]', '- **Fluid Overload:** Use with caution in patients with edematous sodium-retaining conditions (e.g., heart failure, liver cirrhosis, severe renal impairment) due to the high sodium load.
INSERT INTO "drug_generic" VALUES(1893, 'Empagliflozin + Linagliptin', 'Empagliflozin/Linagliptin', 'A10BD19', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Diabetic Ketoacidosis and Fournier''s Gangrene", "severity": "High", "trigger_condition": "Symptoms of severe abdominal pain, vomiting, fatigue, or perineal pain/erythema", "message": "STOP: Fatal cases of diabetic ketoacidosis (DKA) and necrotizing fasciitis of the perineum (Fournier''s gangrene) have occurred. Assess immediately if symptoms present. Discontinue drug if suspected."}]', '**Diabetic Ketoacidosis (DKA):** Increased risk of DKA, even with near-normal blood glucose levels. Assess for ketoacidosis if symptoms (nausea, vomiting, abdominal pain, malaise) occur. Discontinue immediately if suspected. Risk factors include low carbohydrate diet, acute illness, pancreatic disorders, or insulin dose reduction.
INSERT INTO "drug_generic" VALUES(1894, 'Cadexomer iodine', 'Cadexomer iodine', 'D09AA06', 1, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Thyroid Dysfunction Risk", "severity": "Moderate", "trigger_condition": "Prolonged use or application to large wound areas", "message": "Systemic absorption of iodine can occur, potentially leading to thyroid dysfunction. Avoid use in patients with Hashimoto''s thyroiditis, Graves'' disease, or non-toxic goiter."}]', '- **Duration of Therapy:** Limit use to a maximum of 3 months to prevent systemic iodine accumulation.
INSERT INTO "drug_generic" VALUES(1895, 'Glecaprevir + Pibrentasvir', 'Glecaprevir/Pibrentasvir', 'J05AP57', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Hepatitis B Reactivation", "severity": "High", "trigger_condition": "HCV/HBV coinfection", "message": "STOP: Hepatitis B virus (HBV) reactivation has been reported in HCV/HBV coinfected patients receiving direct-acting antivirals, sometimes resulting in fulminant hepatitis, hepatic failure, and death. Test all patients for evidence of current or prior HBV infection before initiating treatment."}]', '**Hepatitis B Virus (HBV) Reactivation:** Test all patients for evidence of current or prior HBV infection by measuring HBsAg and anti-HBc before initiating treatment. HBV reactivation has been reported in HCV/HBV coinfected patients who were undergoing or had completed treatment with HCV direct-acting antivirals and were not receiving HBV antiviral therapy. Monitor coinfected patients for clinical and laboratory signs of hepatitis flare or HBV reactivation during and post-treatment.
INSERT INTO "drug_generic" VALUES(1896, 'Glucose-1-phosphate', 'Glucose-1-phosphate', 'B05XA', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hyperphosphatemia Risk", "severity": "High", "trigger_condition": "Rapid infusion or severe renal impairment", "message": "STOP: Excessive or rapid administration can cause severe hyperphosphatemia, leading to life-threatening hypocalcemia and metastatic calcification of soft tissues. Monitor serum phosphate and calcium levels closely."}]', '**Monitoring:** Regular monitoring of serum phosphorus, calcium, and other electrolytes is necessary to avoid complications from hyperphosphatemia and reciprocal hypocalcemia.
INSERT INTO "drug_generic" VALUES(1897, 'Vitamin B1 + Vitamin B6 + Vitamin B12', 'Thiamine, Pyridoxine, and Cyanocobalamin', 'A11DB', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Masking of Pernicious Anemia:** Cyanocobalamin should not be given before a diagnosis has been fully established because of the possibility of masking symptoms of subacute degeneration of the spinal cord.
INSERT INTO "drug_generic" VALUES(1898, 'Carbidopa + Entacapone + Levodopa', 'Carbidopa / Entacapone / Levodopa', 'N04BA03', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Sudden Sleep Onset", "severity": "High", "trigger_condition": "During activities of daily living", "message": "STOP: Patients may fall asleep without warning during daily activities, including driving. Advise patients of this risk and consider dose reduction or discontinuation if it occurs."}, {"alert_type": "Withdrawal-Emergent Hyperpyrexia", "severity": "High", "trigger_condition": "Abrupt discontinuation or rapid dose reduction", "message": "STOP: Abrupt withdrawal can cause a symptom complex resembling Neuroleptic Malignant Syndrome (NMS), characterized by hyperpyrexia, muscle rigidity, and altered consciousness. Taper gradually."}]', '**Cardiovascular Effects:** May cause severe orthostatic hypotension and syncope. Monitor patients with a history of cardiovascular disease or myocardial infarction for arrhythmias.
INSERT INTO "drug_generic" VALUES(1899, 'Isosorbide Dinitrate', 'Isosorbide Dinitrate', 'C01DA08', 0, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Fatal Hypotension with PDE-5 Inhibitors", "severity": "High", "trigger_condition": "Concomitant use of PDE-5 inhibitors (e.g., sildenafil, tadalafil, vardenafil)", "message": "STOP: Co-administration with phosphodiesterase-5 (PDE-5) inhibitors is absolutely contraindicated. The combination can cause profound, refractory, and potentially fatal hypotension."}]', '**Tolerance:** Nitrate tolerance develops rapidly with continuous use. To maintain efficacy, a daily nitrate-free interval of at least 14 hours is required.
INSERT INTO "drug_generic" VALUES(1900, 'Hypochlorous Acid (Sodium Hypochlorite)', 'Hypochlorous Acid', 'D08AX07', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Vascular Compromise:** In the presence of vascular compromise, care must be taken to avoid circumferential bandage compression pressures that exceed arterial perfusion pressures.
INSERT INTO "drug_generic" VALUES(1901, 'Sodium Stibogluconate', 'Sodium Stibogluconate', 'P01CB02', 1, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiotoxicity and Arrhythmias", "severity": "High", "trigger_condition": "High doses or prolonged therapy", "message": "STOP: Can cause severe, potentially fatal cardiotoxicity including QT prolongation, T-wave inversion, and ventricular arrhythmias. Continuous or frequent ECG monitoring is required during therapy."}]', '- **Cardiotoxicity:** High risk of dose-dependent ECG changes (QT prolongation, T-wave inversion). Monitor ECG regularly; discontinue if significant arrhythmias or QT prolongation occurs.
INSERT INTO "drug_generic" VALUES(1902, 'Fluticasone Propionate 0.005% Topical', 'Fluticasone Propionate', 'D07AC17', 0, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Endocrine Toxicity", "severity": "Moderate", "trigger_condition": "Prolonged use or application over large surface areas", "message": "Systemic absorption of topical corticosteroids can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and unmask latent diabetes mellitus."}]', 'Monitor for signs of hypothalamic-pituitary-adrenal (HPA) axis suppression, especially in patients using high doses, applying to large surface areas, or using occlusive dressings. Discontinue use if local irritation, sensitization, or contact dermatitis develops. Avoid use on the face, groin, or axillae unless specifically directed. Do not use in the presence of preexisting skin atrophy. If a concomitant skin infection is present or develops, an appropriate antifungal or antibacterial agent must be instituted; if a favorable response does not occur promptly, discontinue the corticosteroid until the infection is adequately controlled. Pediatric patients may be more susceptible to systemic toxicity due to a larger skin surface-to-body mass ratio.', '- **Corticosteroid-Responsive Dermatoses:** Relief of the inflammatory and pruritic manifestations of corticosteroid-responsive dermatoses.
INSERT INTO "drug_generic" VALUES(1903, 'Coal Tar + Precipitated Sulpher + Salicylic Acid', 'Coal Tar, Sulfur, and Salicylic Acid Topical', 'D05AA', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '**Photosensitivity:** Coal tar increases sensitivity to sunlight. Avoid exposure to direct sunlight and sunlamps for at least 24 to 72 hours after application to prevent severe sunburn.
INSERT INTO "drug_generic" VALUES(1904, 'Caspofungin', 'Caspofungin', 'J02AX04', 1, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Hypersensitivity and Hepatic Toxicity", "severity": "High", "trigger_condition": "Administration of IV infusion or concomitant use with Cyclosporine", "message": "STOP: Anaphylaxis and severe skin reactions (SJS/TEN) can occur. Discontinue immediately at the first sign of hypersensitivity. Monitor LFTs closely, especially if co-administered with cyclosporine, due to the risk of hepatic dysfunction."}]', '**Hypersensitivity Reactions:** Anaphylaxis and possible histamine-mediated adverse reactions (rash, facial swelling, angioedema, pruritus, sensation of warmth, bronchospasm) have been reported. Cases of Stevens-Johnson syndrome (SJS) and toxic epidermal necrolysis (TEN) have also occurred. Discontinue immediately if signs appear.
INSERT INTO "drug_generic" VALUES(1905, 'EPA + DHA + High Protein', 'Eicosapentaenoic Acid, Docosahexaenoic Acid, and High Protein Supplement', 'V06', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Enteral Nutrition Contraindication", "severity": "High", "trigger_condition": "Acute gastrointestinal conditions", "message": "STOP: Not suitable whenever enteral nutrition is not permitted, such as in acute gastrointestinal bleeding, ileus, and shock."}]', '**Bleeding Risk:** High-dose EPA/DHA (e.g., >3 g/day) may mildly prolong bleeding times. Monitor patients on anticoagulants (e.g., Warfarin, direct oral anticoagulants) or those with bleeding disorders.
INSERT INTO "drug_generic" VALUES(1906, 'Norfloxacin', 'Norfloxacin', 'J01MA06', 1, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Tendon Rupture and CNS Effects", "severity": "High", "trigger_condition": "Concurrent corticosteroid use, advanced age, or history of CNS disorders", "message": "STOP: Fluoroquinolones are associated with disabling and potentially irreversible serious adverse reactions, including tendinitis, tendon rupture, peripheral neuropathy, and CNS effects (seizures, hallucinations). Discontinue immediately if symptoms occur."}]', 'Use with caution in patients with known prolongation of the QT interval, uncorrected hypokalemia, or concurrent use of Class IA or III antiarrhythmics. Caution is advised in patients with known or suspected CNS disorders (e.g., severe cerebral arteriosclerosis, epilepsy) that predispose to seizures. Risk of tendinitis and tendon rupture is increased in patients over 60 years of age, those taking corticosteroids, and kidney, heart, or lung transplant recipients. May exacerbate muscle weakness in patients with myasthenia gravis. Monitor for signs of peripheral neuropathy and discontinue if symptoms develop. Ensure adequate hydration to prevent crystalluria.', '- **Uncomplicated Urinary Tract Infections (Cystitis):** Treatment of infections caused by susceptible strains of *E. coli*, *K. pneumoniae*, or *P. mirabilis*. Reserve for patients who have no alternative treatment options.
INSERT INTO "drug_generic" VALUES(1907, 'Inositol nicotinate', 'Inositol Niacinate', 'C04AD02', 0, 0, 0, 0, 0, 0, 0, 0, '[]', 'Caution should be exercised in patients with angina pectoris that is not well controlled by medical treatment, as vasodilation may alter coronary perfusion. Use cautiously in patients with cerebrovascular insufficiency. Monitor for signs of excessive vasodilation, such as severe flushing or postural hypotension. Caution in patients with a history of peptic ulcer disease, as niacin derivatives can exacerbate GI irritation. Monitor liver function tests and blood glucose levels during prolonged therapy, as high doses of niacin derivatives can cause hepatotoxicity and impair glucose tolerance.', '- **Peripheral Vascular Disease:** Adjunctive treatment for conditions associated with peripheral vascular insufficiency, including intermittent claudication and Raynaud''s disease.
INSERT INTO "drug_generic" VALUES(1908, 'Orlistat', 'Orlistat', 'A08AB01', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Severe Liver Injury", "severity": "High", "trigger_condition": "Development of jaundice, dark urine, pruritus, or right upper quadrant pain", "message": "Rare cases of severe liver injury with hepatocellular necrosis or acute hepatic failure have been reported. Discontinue orlistat immediately if signs of liver injury occur."}]', '**Oxalate Nephropathy:** Cases of hyperoxaluria and calcium oxalate nephrolithiasis have been reported. Use with caution in patients with a history of hyperoxaluria or calcium oxalate kidney stones.
INSERT INTO "drug_generic" VALUES(1909, 'Podophyllin 25% in Tincture of Benzoin', 'Podophyllum Resin', 'D06BB04', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Systemic Toxicity", "severity": "High", "trigger_condition": "Application to large areas, mucous membranes, or bleeding tissue", "message": "STOP: Systemic absorption can cause fatal neurotoxicity, bone marrow suppression, and coma. Apply strictly to intact lesions and wash off after 1-4 hours."}]', 'Do not use if the wart or surrounding tissue is inflamed, irritated, or bleeding. Protect surrounding healthy tissue with petroleum jelly prior to application. To avoid severe systemic absorption, the time of contact should be the minimum necessary (1 to 4 hours) and the treated area must be washed thoroughly afterward. Do not treat large areas or numerous warts simultaneously.', '- **Genital Warts (Condylomata Acuminata):** Topical removal of external genital and perianal warts.
INSERT INTO "drug_generic" VALUES(1910, 'Procyclidine Hydrochloride', 'Procyclidine', 'N04AA04', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Anticholinergic Toxicity", "severity": "High", "trigger_condition": "Overdose or use in elderly patients", "message": "STOP: Procyclidine is a potent anticholinergic. High doses can cause severe central toxicity (hallucinations, confusion, delirium) and peripheral toxicity (urinary retention, paralytic ileus, tachycardia). Avoid abrupt withdrawal."}]', '- **Cardiovascular Disease:** Use with caution in patients with tachycardia, cardiac arrhythmias, hypertension, or hypotension, as anticholinergics can exacerbate tachycardia.
INSERT INTO "drug_generic" VALUES(1911, 'Ethinylestradiol + Lynestrenol', 'Ethinyl Estradiol and Lynestrenol', 'G03AA03', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Women over 35 years old who smoke", "message": "STOP: Cigarette smoking increases the risk of serious cardiovascular events from combination oral contraceptive use. This risk increases with age, particularly in women over 35 years of age, and with the number of cigarettes smoked."}]', '**Thromboembolic Disorders:** Increased risk of venous and arterial thromboembolism (VTE/ATE). Discontinue immediately if a thrombotic event occurs.
INSERT INTO "drug_generic" VALUES(1912, 'Nimodipine', 'Nimodipine', 'C08CA06', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Fatal Intravenous Administration Error", "severity": "High", "trigger_condition": "Administration of oral capsule contents via intravenous route", "message": "STOP: Nimodipine must NEVER be administered intravenously or by any other parenteral route. Death and severe, life-threatening cardiovascular events (cardiac arrest, profound hypotension) have occurred when the contents of nimodipine capsules were injected intravenously."}]', 'Use with caution in patients with cerebral edema or severely raised intracranial pressure. Careful monitoring of blood pressure and pulse rate is required, as nimodipine can cause significant systemic hypotension. In patients with hepatic impairment, nimodipine metabolism is decreased, leading to higher plasma concentrations; dose reduction and strict blood pressure monitoring are necessary. If the patient cannot swallow the capsule, the liquid contents may be extracted with a syringe and administered via a nasogastric or feeding tube, but extreme care must be taken to ensure the syringe is not inadvertently used for IV administration.', '- **Subarachnoid Hemorrhage (SAH):** Indicated for the improvement of neurological outcome by reducing the incidence and severity of ischemic deficits in patients with subarachnoid hemorrhage from ruptured intracranial berry aneurysms, regardless of their post-ictus neurological condition.', '- **Concomitant Strong CYP3A4 Inhibitors:** Contraindicated with potent inhibitors (e.g., clarithromycin, ritonavir, ketoconazole, nefazodone) due to the risk of significantly elevated nimodipine levels and profound, potentially fatal hypotension.
INSERT INTO "drug_generic" VALUES(1913, 'Certoparin', 'Certoparin', 'B01AB13', 0, 1, 0, 1, 1, 0, 0, 0, '[{"alert_type": "Bleeding Risk and HIT", "severity": "High", "trigger_condition": "Active bleeding, history of HIT, or neuraxial anesthesia", "message": "STOP: High risk of fatal hemorrhage. Epidural/spinal hematomas can occur in patients receiving neuraxial anesthesia, leading to permanent paralysis. Monitor for Heparin-Induced Thrombocytopenia (HIT)."}]', '**Thrombocytopenia:** Monitor platelet counts regularly. Discontinue treatment immediately if severe thrombocytopenia or Heparin-Induced Thrombocytopenia (HIT) occurs.
INSERT INTO "drug_generic" VALUES(1914, 'Diazoxide', 'Diazoxide', 'V03AH01', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Fluid Retention and Heart Failure", "severity": "High", "trigger_condition": "Patients with compromised cardiac reserve or concomitant use of fluid-retaining drugs", "message": "STOP: Diazoxide causes significant sodium and water retention, which may precipitate congestive heart failure. Monitor closely and treat with diuretics if necessary."}]', '- **Hyperglycemia and Ketoacidosis:** Diabetic ketoacidosis and hyperosmolar nonketotic coma may develop rapidly. Monitor blood glucose and urine ketones closely, especially during intercurrent illness. Prolonged surveillance is necessary due to the drug''s long half-life (~30 hours).
INSERT INTO "drug_generic" VALUES(1915, 'Follitropin Alfa + Lutropin Alfa', 'Follitropin Alfa and Lutropin Alfa', 'G03GA05', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Ovarian Hyperstimulation Syndrome (OHSS)", "severity": "High", "trigger_condition": "During or after ovarian stimulation", "message": "STOP: Can cause severe Ovarian Hyperstimulation Syndrome (OHSS), a potentially life-threatening condition characterized by massive ovarian enlargement, ascites, pleural effusion, and thromboembolism. Monitor ovarian response closely with ultrasound and serum estradiol."}]', '**Ovarian Hyperstimulation Syndrome (OHSS):** Monitor patients closely. If signs of OHSS develop (severe pelvic pain, rapid weight gain, nausea, vomiting), withhold hCG administration and advise the patient to avoid intercourse or use barrier methods.
INSERT INTO "drug_generic" VALUES(1916, 'Gentamicin 0.3% Topical', 'Gentamicin Topical', 'D06AX07', 1, 0, 0, 1, 1, 0, 1, 0, '[{"alert_type": "Systemic Toxicity Risk", "severity": "High", "trigger_condition": "Application to large areas of denuded skin or burns", "message": "STOP: Application to large areas of damaged skin (e.g., severe burns) can result in significant systemic absorption, leading to irreversible ototoxicity and nephrotoxicity. Monitor renal and auditory function closely."}]', '**Systemic Absorption:** Prolonged use or application to large areas of denuded skin, burns, or granulating wounds can lead to systemic absorption. Monitor plasma gentamicin concentrations, auditory function, and renal function in high-risk patients (infants, elderly, renal impairment, cystic fibrosis, obesity).
INSERT INTO "drug_generic" VALUES(1917, 'Sodium Chloride 5% Eye prep', 'Sodium Chloride 5% Ophthalmic', 'S01XA03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Transient Visual Disturbance", "severity": "Low", "trigger_condition": "Application of eye drops", "message": "Vision may be temporarily blurred immediately after applying the drops. Advise patients not to drive or operate machinery until vision clears."}]', 'Precaution should be taken if patients have a history of eye problems or ocular allergies. Remove contact lenses before applying the drops, as the preservatives in the preparation may be absorbed by soft contact lenses and cause ocular irritation. Wait at least 15 minutes before reinserting contact lenses. If the condition worsens or persists for more than 72 hours, discontinue use and consult a physician.', '- **Corneal Edema:** Indicated for the temporary relief of corneal edema (swelling of the cornea) following ocular surgery, trauma, or secondary to conditions like Fuchs'' endothelial dystrophy.
INSERT INTO "drug_generic" VALUES(1918, 'Gefitinib', 'Gefitinib', 'L01EB01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Interstitial Lung Disease (ILD)", "severity": "High", "trigger_condition": "Acute onset or worsening of pulmonary symptoms", "message": "STOP: Severe, life-threatening, and fatal interstitial lung disease (ILD) can occur. Withhold gefitinib immediately for acute onset or worsening of pulmonary symptoms (dyspnea, cough, fever) and permanently discontinue if ILD is confirmed."}]', '**Interstitial Lung Disease (ILD):** ILD, which may be fatal, has been reported. Withhold gefitinib and promptly investigate for ILD in any patient who presents with worsening of respiratory symptoms such as dyspnea, cough, and fever. Permanently discontinue if ILD is confirmed.
INSERT INTO "drug_generic" VALUES(1919, 'Linagliptin', 'Linagliptin', 'A10BH05', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Pancreatitis Risk", "severity": "High", "trigger_condition": "Patient presenting with severe, persistent abdominal pain", "message": "STOP: Acute pancreatitis, including fatal and non-fatal hemorrhagic or necrotizing pancreatitis, has been reported. Discontinue linagliptin immediately if pancreatitis is suspected."}]', '- **Pancreatitis:** Acute pancreatitis has been reported. Monitor for signs and symptoms (severe, persistent abdominal pain, sometimes radiating to the back). Discontinue if suspected.
INSERT INTO "drug_generic" VALUES(1920, 'Itopride Hydrochloride', 'Itopride', 'A03FA07', 0, 0, 0, 0, 1, 1, 0, 0, '[]', 'Use with caution in the elderly due to potentially decreased physiological function. Monitor for cholinergic effects. Patients with reduced hepatic or renal functions should be carefully monitored, and dose reduction or discontinuation may be necessary if adverse reactions occur.', '- **Gastrointestinal Motility Disorders:** Indicated for the management of gastrointestinal symptoms associated with chronic gastritis and non-ulcer dyspepsia, including the feeling of a swollen abdomen, early satiety, postprandial fullness, upper abdominal pain or discomfort, anorexia, heartburn, nausea, and vomiting.', '- **Mechanical Obstruction or Perforation:** Contraindicated in conditions where increased gastrointestinal motility may be harmful, such as gastrointestinal hemorrhage, mechanical obstruction, or perforation.
INSERT INTO "drug_generic" VALUES(1921, 'Dibucaine topical', 'Dibucaine', 'D04AB06', 0, 0, 0, 0, 0, 0, 0, 0, '[]', '**External Use Only:** For external use only. Avoid contact with the eyes, nose, or mouth. Do not apply to open wounds, severe burns, or broken/inflamed skin, as this significantly increases systemic absorption and the risk of toxicity.
INSERT INTO "drug_generic" VALUES(1922, 'Cephalexin', 'Cephalexin', 'J01DB01', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing. Cross-reactivity with penicillins occurs in up to 10% of patients."}]', '**Clostridium difficile-Associated Diarrhea (CDAD):** Has been reported with use of nearly all antibacterial agents, including cephalexin, and may range in severity from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(1923, 'Dexmedetomidine', 'Dexmedetomidine', 'N05CM18', 0, 1, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Bradycardia and Sinus Arrest", "severity": "High", "trigger_condition": "Patients with high vagal tone or receiving other negative chronotropic agents", "message": "STOP: Clinically significant bradycardia and sinus arrest have occurred. Monitor heart rate continuously. Be prepared to administer anticholinergics (e.g., atropine) or adjust the infusion rate."}]', '- **Bradycardia and Sinus Arrest:** Can cause significant bradycardia. Consider decreasing/stopping the infusion, administering anticholinergics, or using pressors if severe.
INSERT INTO "drug_generic" VALUES(1924, 'Deferiprone', 'Deferiprone', 'V03AC02', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Agranulocytosis and Neutropenia", "severity": "High", "trigger_condition": "Initiation of therapy or development of fever/infection", "message": "STOP: Deferiprone can cause fatal agranulocytosis. Measure Absolute Neutrophil Count (ANC) before starting and weekly during therapy. Interrupt treatment immediately if neutropenia or infection develops."}]', '**Agranulocytosis and Neutropenia:** Can cause severe agranulocytosis leading to serious infections and death. Monitor ANC weekly. Interrupt therapy if ANC drops below 1.5 x 10^9/L.
INSERT INTO "drug_generic" VALUES(1925, 'Felodipine', 'Felodipine', 'C08CA02', 0, 0, 0, 0, 0, 0, 0, 1, '[]', 'Use with caution in patients with heart failure, particularly those with compromised ventricular function, as felodipine can cause negative inotropic effects.
INSERT INTO "drug_generic" VALUES(1926, 'Hepatitis B Vaccine (rDNA) BP', 'Hepatitis B Vaccine, Recombinant', 'J07BC01', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe allergic reaction to yeast or previous vaccine dose", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, can occur. Ensure epinephrine and emergency equipment are immediately available."}]', '**Acute Illness:** Defer vaccination in individuals suffering from moderate to severe acute febrile illness until recovery.
INSERT INTO "drug_generic" VALUES(1927, 'Erythromycin', 'Erythromycin', 'J01FA01', 1, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Concurrent use with QT-prolonging drugs or CYP3A4 inhibitors", "message": "STOP: Erythromycin can cause QT interval prolongation and fatal arrhythmias (Torsades de Pointes). Contraindicated with concurrent use of strong CYP3A4 inhibitors, astemizole, cisapride, pimozide, or ergot alkaloids."}]', '**Hepatotoxicity:** Hepatic dysfunction, including increased liver enzymes and hepatocellular and/or cholestatic hepatitis, with or without jaundice, has been reported. Risk increases with treatment >10 days or previous erythromycin use. Avoid the estolate salt in patients with pre-existing liver impairment.
INSERT INTO "drug_generic" VALUES(1928, 'Carbonyl Iron + Folic Acid + Zinc', 'Carbonyl Iron / Folic Acid / Zinc', 'B03AD', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Fatal Pediatric Poisoning", "severity": "High", "trigger_condition": "Accidental ingestion by children under 6 years", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Iron Overload:** Care should be taken in patients who may develop iron overload, such as those with hemochromatosis, hemolytic anemia, or red cell aplasia.
INSERT INTO "drug_generic" VALUES(1929, 'Insulin Aspart Biphasic (Insulin Aspart + Insulin Aspart protamine)', 'Insulin Aspart Protamine and Insulin Aspart', 'A10AD05', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypoglycemia", "severity": "High", "trigger_condition": "Changes in insulin regimen, missed meals, increased physical activity, or co-administration with other glucose-lowering agents", "message": "STOP: Severe, life-threatening hypoglycemia can occur. Monitor blood glucose closely when adjusting doses, changing diet, or altering physical activity."}, {"alert_type": "Hypokalemia", "severity": "High", "trigger_condition": "Use with potassium-depleting drugs or conditions that decrease potassium", "message": "STOP: Insulin shifts potassium intracellularly, which can lead to severe hypokalemia and fatal cardiac arrhythmias. Monitor serum potassium levels, especially in high-risk patients."}]', '**Hypoglycemia:** The most common adverse effect of insulin therapy. Risk increases with changes in meal patterns, physical activity, or co-administered medications. Early warning symptoms may be different or less pronounced in patients with long-standing diabetes, diabetic nerve disease, or those taking beta-blockers.
INSERT INTO "drug_generic" VALUES(1930, 'Atenolol + Nifedipine', 'Atenolol and Nifedipine', 'C07FB03', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Abrupt Discontinuation", "severity": "High", "trigger_condition": "Sudden cessation of therapy", "message": "STOP: Severe exacerbation of angina, myocardial infarction, and ventricular arrhythmias have occurred following the abrupt discontinuation of beta-blockers. Taper the dose gradually over 1 to 2 weeks."}]', '**Heart Failure:** Use with caution in patients with poor cardiac reserve or mild heart failure (NYHA Class II). Contraindicated in overt or decompensated heart failure.
INSERT INTO "drug_generic" VALUES(1931, 'Theophylline', 'Theophylline', 'R03DA04', 0, 1, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Narrow Therapeutic Index", "severity": "High", "trigger_condition": "Initiation of therapy or dose adjustment", "message": "Theophylline has a narrow therapeutic index (target serum level 10-15 mcg/mL). Toxicity can cause fatal arrhythmias and intractable seizures. Monitor serum levels closely, especially during illness, fever, or when adding/removing interacting medications."}]', 'Use with extreme caution in patients with peptic ulcer disease, hyperthyroidism, diabetes mellitus, glaucoma, severe hypoxemia, epilepsy, hypertension, heart failure, cardiac arrhythmias, acute febrile illness, COPD, or cor pulmonale. Clearance is significantly decreased in patients with hepatic impairment, heart failure, or acute pulmonary edema, requiring dose reduction. Clearance is increased in smokers, requiring higher doses. Monitor heart rate, CNS effects, respiratory rate, and serum theophylline levels regularly.', '- **Asthma:** Control of acute asthma and management of chronic asthma (symptomatic and prophylactic treatment), including nocturnal asthma and early morning wheezing.
INSERT INTO "drug_generic" VALUES(1932, 'Fluvastatin', 'Fluvastatin', 'C10AA04', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatic Dysfunction", "severity": "High", "trigger_condition": "Active liver disease or unexplained persistent elevations of serum transaminases", "message": "STOP: Fluvastatin is contraindicated in patients with active liver disease. Monitor liver function tests before initiating therapy and as clinically indicated."}, {"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Concomitant use with interacting drugs (e.g., fibrates, niacin, cyclosporine) or unexplained muscle pain", "message": "WARNING: Risk of skeletal muscle effects, including myopathy and rhabdomyolysis. Promptly evaluate patients presenting with unexplained muscle pain, tenderness, or weakness."}]', '**Skeletal Muscle Effects:** Myopathy and rhabdomyolysis with acute renal failure secondary to myoglobinuria have been reported. Risk increases with higher doses, advanced age (>65 years), renal impairment, inadequately treated hypothyroidism, and concomitant use of certain drugs (e.g., fibrates, niacin, cyclosporine).
INSERT INTO "drug_generic" VALUES(1933, 'Thiopental Sodium', 'Thiopental', 'N01AF03', 0, 1, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Respiratory Depression and Airway Management", "severity": "High", "trigger_condition": "Administration of drug", "message": "Thiopental causes profound respiratory depression and apnea. It must only be administered by personnel trained in airway management and endotracheal intubation. Resuscitation equipment and oxygen must be immediately available."}]', 'Use with extreme caution in patients with hypovolemia, severe cardiovascular disease, severe asthma, severe anemia, hyperkalemia, toxemia, myasthenia gravis, myxedema, severe renal or hepatic disease, muscular dystrophies, adrenocortical insufficiency, and increased intracranial pressure. Avoid extravasation, as the highly alkaline solution (5%) can cause severe tissue necrosis. Intra-arterial injection is a medical emergency and can cause severe arterial spasm and gangrene. Reduce doses in the elderly.', '- **Induction of Anesthesia:** Used as the sole anesthetic agent for brief procedures (up to 15 minutes) or for induction prior to the administration of other general anesthetics.
INSERT INTO "drug_generic" VALUES(1934, 'Levosalbutamol', 'Levalbuterol', 'R03CC12', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Initiation of therapy or use of a new canister", "message": "STOP: Inhaled levosalbutamol can produce paradoxical bronchospasm, which may be life-threatening. If this occurs, discontinue immediately and institute alternative therapy."}]', '**Cardiovascular Effects:** Can produce clinically significant cardiovascular effects (changes in pulse rate, blood pressure, or ECG changes). Use with caution in patients with cardiovascular disorders, especially coronary insufficiency, cardiac arrhythmias, and hypertension.
INSERT INTO "drug_generic" VALUES(1935, 'Nintedanib', 'Nintedanib', 'L01EX09', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated transaminases or bilirubin", "message": "STOP: Severe and potentially fatal drug-induced liver injury can occur. Monitor LFTs prior to initiation, monthly for 3 months, and periodically thereafter."}]', '**Hepatic Impairment:** Severe liver injury with fatal outcomes has been reported. Conduct LFTs (ALT, AST, bilirubin) before initiating, monthly for the first 3 months, and every 3 months thereafter. Reduce dose or interrupt therapy if elevations occur.
INSERT INTO "drug_generic" VALUES(1936, 'Ethinylestradiol + Levonorgestrel', 'Ethinyl Estradiol and Levonorgestrel', 'G03AA07', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Women over 35 years old who smoke", "message": "STOP: Cigarette smoking increases the risk of serious cardiovascular events from combination oral contraceptive use. This risk increases with age, particularly in women over 35 years of age, and with the number of cigarettes smoked."}]', '**Thromboembolic Disorders:** Increased risk of venous and arterial thromboembolism (VTE/ATE), myocardial infarction, and stroke. Discontinue immediately if a thrombotic event occurs.
INSERT INTO "drug_generic" VALUES(1937, 'Beclomethasone Dipropionate', 'Beclomethasone', 'R03BA01', 0, 0, 1, 1, 0, 1, 1, 1, '[{"alert_type": "Not for Acute Bronchospasm", "severity": "High", "trigger_condition": "Acute asthma attack", "message": "STOP: Beclomethasone is a maintenance inhaler. It is NOT a bronchodilator and should NOT be used for rapid relief of acute bronchospasm or status asthmaticus."}, {"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediately after inhalation", "message": "STOP: Inhaled corticosteroids can cause life-threatening paradoxical bronchospasm. If wheezing increases immediately after dosing, treat with a short-acting bronchodilator and discontinue beclomethasone."}]', '**Oral Candidiasis:** Localized infections with Candida albicans in the mouth and throat occur frequently. Advise patients to rinse their mouth with water and spit it out after each use.
INSERT INTO "drug_generic" VALUES(1938, 'Amenamevir', 'Amenamevir', 'J05AB17', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Renal Toxicity", "severity": "High", "trigger_condition": "Severe renal impairment (eGFR < 30 mL/min/1.73 m\u00b2)", "message": "STOP: Drug exposure may significantly increase in severe renal impairment. Use with extreme caution, monitor renal function closely, and avoid in end-stage renal disease unless benefits clearly outweigh risks."}]', '**Renal and Hepatic Impairment**
INSERT INTO "drug_generic" VALUES(1939, 'Indacaterol', 'Indacaterol', 'R03AC18', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Asthma-Related Death", "severity": "High", "trigger_condition": "Use in patients with asthma without a concomitant long-term asthma control medication (e.g., inhaled corticosteroid)", "message": "STOP: Long-acting beta2-adrenergic agonists (LABA), such as indacaterol, increase the risk of asthma-related death. Indacaterol is NOT indicated for the treatment of asthma."}, {"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediately following inhalation of the drug", "message": "STOP: Inhaled medicines can cause paradoxical bronchospasm, which may be life-threatening. If this occurs, discontinue indacaterol immediately and institute alternative therapy."}]', '**Asthma-Related Death:** LABAs increase the risk of asthma-related death. Indacaterol is not indicated for the treatment of asthma and should only be used for COPD.
INSERT INTO "drug_generic" VALUES(1940, 'Doxepin 5% Topical', 'Doxepin Topical', 'D04AA22', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Systemic Absorption and Sedation", "severity": "High", "trigger_condition": "Application to >10% of body surface area or use of occlusive dressings", "message": "STOP: Significant systemic absorption can occur, leading to profound drowsiness and anticholinergic toxicity. Do not apply to more than 10% of body surface area. Do not use occlusive dressings."}]', '**Systemic Anticholinergic Effects:** Due to systemic absorption, use with caution in patients with a susceptibility to angle-closure glaucoma, urinary retention, or severe liver impairment.
INSERT INTO "drug_generic" VALUES(1941, 'Salicylic acid + Zinc Pyrithione', 'Salicylic Acid and Zinc Pyrithione', 'D05A', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Moderate", "trigger_condition": "Application to the scalp or skin", "message": "For external use only. Avoid contact with eyes and eyelids; if contact occurs, flush thoroughly with water. Do not apply to acutely inflamed, open, or broken skin."}]', '**Systemic Absorption:** Prolonged use over large body areas can increase the risk of systemic salicylate toxicity (salicylism), especially in children or patients with renal impairment.
INSERT INTO "drug_generic" VALUES(1942, 'Perampanel', 'Perampanel', 'N03AX22', 0, 0, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Psychiatric and Behavioral Reactions", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "STOP: Severe psychiatric and behavioral reactions (e.g., hostility, aggression, homicidal ideation) may emerge. Monitor patients closely for unusual mood or behavior changes."}]', '**Psychiatric and Behavioral Reactions:** Serious and potentially life-threatening psychiatric and behavioral reactions, including aggression, hostility, irritability, anger, and homicidal ideation, have been reported. These effects appear to be dose-related and can occur in patients with or without a prior psychiatric history.
INSERT INTO "drug_generic" VALUES(1943, 'Aluminum hydroxide + Magnesium carbonate', 'Aluminum hydroxide and Magnesium carbonate', 'A02AD01', 0, 0, 0, 1, 1, 1, 0, 0, '[{"alert_type": "Renal Failure Risk", "severity": "High", "trigger_condition": "Patients with severe renal impairment", "message": "STOP: Contraindicated in severe renal failure. Magnesium and aluminum can accumulate, leading to severe hypermagnesemia and aluminum toxicity (encephalopathy, osteomalacia)."}]', '- **Renal Impairment:** Use with extreme caution in patients with mild to moderate renal impairment due to the risk of magnesium and aluminum accumulation.
INSERT INTO "drug_generic" VALUES(1944, 'Ferrous Fumarate + Folic Acid', 'Ferrous Fumarate and Folic Acid', 'B03AD02', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Fatal Poisoning in Children", "severity": "High", "trigger_condition": "Accidental ingestion by children under 6 years of age", "message": "WARNING: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Gastrointestinal Conditions:** Avoid use or use with extreme caution in patients with active peptic ulcer disease, regional enteritis, and ulcerative colitis, as oral iron may exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(1945, 'Cabergoline', 'Cabergoline', 'G02CB03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiac Valvulopathy", "severity": "High", "trigger_condition": "Long-term use or high cumulative doses", "message": "STOP: Cabergoline is associated with cardiac valvulopathy. All patients must undergo a cardiovascular evaluation, including an echocardiogram, prior to initiation. Discontinue if new valvular regurgitation, restriction, or leaflet thickening occurs."}]', '**Cardiac Valvulopathy and Fibrotic Complications:** Rare cases of retroperitoneal, pleural, pericardial, and pulmonary fibrosis, as well as cardiac valvulopathy, have been reported. Baseline and periodic echocardiograms and chest X-rays are required.
INSERT INTO "drug_generic" VALUES(1946, 'Rolapitant', 'Rolapitant', 'A04AD14', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "Intravenous administration", "message": "STOP: Anaphylaxis, anaphylactic shock, and other serious hypersensitivity reactions have occurred during or soon after IV infusion. Monitor closely during and after administration."}]', '**Hypersensitivity Reactions:** Serious hypersensitivity reactions, including anaphylaxis, have been reported, particularly with the IV formulation. Most occur within the first few minutes of administration. Discontinue immediately if signs of hypersensitivity occur and initiate appropriate medical management.
INSERT INTO "drug_generic" VALUES(1947, 'Diphtheria, Tetanus, Pertussis, Poliomyelitis Vaccine', 'Diphtheria and Tetanus Toxoids and Acellular Pertussis Adsorbed and Inactivated Poliovirus Vaccine (DTaP-IPV or DTaP-IPV)', 'J07CA02', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Encephalopathy Risk", "severity": "High", "trigger_condition": "History of encephalopathy after previous pertussis vaccine", "message": "STOP: Contraindicated if the patient experienced encephalopathy (e.g., coma, decreased level of consciousness, prolonged seizures) within 7 days of a previous dose of a pertussis-containing vaccine."}]', '**Guillain-Barre Syndrome (GBS):** If GBS occurred within 6 weeks of receipt of a prior vaccine containing tetanus toxoid, the decision to give this vaccine should be based on careful consideration of potential benefits and risks.
INSERT INTO "drug_generic" VALUES(1948, 'Dantrolene Sodium', 'Dantrolene', 'M03CA01', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Doses >800 mg daily, prolonged use, female gender, age >35 years", "message": "STOP: Dantrolene has a potential for hepatotoxicity, including fatal and nonfatal hepatitis. Perform baseline and periodic liver function tests. Discontinue if benefits are not observed within 45 days."}]', '- **Hepatotoxicity:** Overt hepatitis has been most frequently observed between the third and twelfth months of therapy. Risk is higher in females, patients >35 years, and those on concurrent medications. Use only in conjunction with liver monitoring.
INSERT INTO "drug_generic" VALUES(1949, 'Aliskiren Hemifumarate + Hydrochlorothiazide', 'Aliskiren and Hydrochlorothiazide', 'C09XA52', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Discontinue immediately if pregnancy is detected. Drugs acting on the renin-angiotensin system can cause oligohydramnios, fetal injury, and death."}, {"alert_type": "Anaphylaxis and Angioedema", "severity": "High", "trigger_condition": "Development of swelling of the face, lips, tongue, or throat", "message": "STOP: Discontinue immediately and monitor until signs and symptoms resolve. Do not re-administer."}]', '**Renal Impairment:** Avoid concomitant use with ARBs or ACEIs in patients with renal impairment (GFR <60 mL/min). Monitor serum creatinine periodically.
INSERT INTO "drug_generic" VALUES(1950, 'Fedratinib', 'Fedratinib', 'L01EJ02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Encephalopathy", "severity": "High", "trigger_condition": "Patients presenting with altered mental status, ataxia, or extraocular muscle paralysis", "message": "STOP: Serious and fatal cases of Wernicke encephalopathy have occurred. Assess thiamine levels prior to initiation, periodically during treatment, and as clinically indicated. Do not start in patients with thiamine deficiency."}]', '**Wernicke Encephalopathy:** Serious and fatal cases of encephalopathy, including Wernicke encephalopathy, have been reported. Assess thiamine levels prior to initiation, periodically during treatment, and as clinically indicated. Do not start fedratinib in patients with thiamine deficiency; replete thiamine prior to treatment. If Wernicke encephalopathy is suspected, immediately discontinue therapy and initiate parenteral thiamine.
INSERT INTO "drug_generic" VALUES(1951, 'Bacitracin Zinc + Neomycin Sulphate + Polymixin B topical', 'Bacitracin, Neomycin, and Polymyxin B Topical', 'D06AX', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Allergic Contact Dermatitis", "severity": "Medium", "trigger_condition": "Application to the skin", "message": "STOP: Neomycin is a potent sensitizer. Allergic contact dermatitis occurs frequently. Discontinue if redness, itching, or worsening of the lesion occurs."}]', '**Systemic Absorption:** Avoid application in large quantities or over extensive areas of denuded skin (e.g., severe burns). Systemic absorption of neomycin and polymyxin B can lead to severe nephrotoxicity, neurotoxicity, and irreversible ototoxicity.
INSERT INTO "drug_generic" VALUES(1952, 'Indapamide + Perindopril Erbumine', 'Perindopril and Indapamide', 'C09BA04', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}, {"alert_type": "Angioedema", "severity": "High", "trigger_condition": "Swelling of face, lips, tongue, or airway", "message": "STOP: Severe, life-threatening angioedema can occur. Discontinue immediately and secure airway if laryngeal edema develops."}]', 'Monitor renal function and serum potassium regularly; the combination of an ACE inhibitor and a diuretic can cause severe hypotension, acute renal failure, and electrolyte imbalances (hypokalemia or hyperkalemia). Use with extreme caution in patients with bilateral renal artery stenosis due to the risk of acute renal failure. Monitor for signs of angioedema (swelling of the face, extremities, eyes, lips, tongue, glottis, or larynx); discontinue immediately if it occurs. Black patients may have a higher risk of angioedema and a lesser blood pressure response to ACE inhibitors. Monitor blood glucose in diabetic patients, as indapamide can impair glucose tolerance. Caution in patients with severe heart failure, ischemic heart disease, or cerebrovascular disease, where excessive hypotension could result in myocardial infarction or stroke. Monitor for neutropenia/agranulocytosis, particularly in immunosuppressed patients or those with collagen vascular disease.', '- **Essential Hypertension:** Treatment of essential hypertension in patients whose blood pressure is not adequately controlled on monotherapy, or as initial therapy in patients likely to need multiple drugs to achieve blood pressure goals.', '- **Pregnancy:** Contraindicated due to the risk of fetal toxicity, oligohydramnios, and neonatal death.
INSERT INTO "drug_generic" VALUES(1953, 'Zoledronic Acid 5mg', 'Zoledronic Acid', 'M05BA08', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Hypocalcemia and Renal Toxicity", "severity": "High", "trigger_condition": "Pre-existing hypocalcemia or severe renal impairment (CrCl <35 mL/min)", "message": "STOP: Correct hypocalcemia before initiating therapy. Contraindicated in patients with CrCl <35 mL/min due to risk of acute renal failure."}, {"alert_type": "Osteonecrosis of the Jaw (ONJ)", "severity": "High", "trigger_condition": "Invasive dental procedures", "message": "WARNING: Perform a routine dental exam prior to treatment. Avoid invasive dental procedures during therapy due to the risk of ONJ."}]', 'Ensure patients are adequately hydrated prior to administration to reduce the risk of renal toxicity.
INSERT INTO "drug_generic" VALUES(1954, 'Nanoparticle Albumin-Bound (NAB) Paclitaxel', 'Paclitaxel Protein-Bound', 'L01CD01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Baseline neutrophils <1500 cells/mm\u00b3", "message": "STOP: High Alert Chemotherapy. Do not administer if baseline absolute neutrophil count (ANC) is <1500 cells/mm\u00b3. Profound myelosuppression leading to fatal sepsis can occur. Monitor CBC frequently."}]', '**Myelosuppression:** Causes severe neutropenia, thrombocytopenia, and anemia. Monitor complete blood counts frequently. Withhold or reduce the dose as needed.
INSERT INTO "drug_generic" VALUES(1955, 'Dexamethasone oral', 'Dexamethasone', 'H02AB02', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Immunosuppression and Adrenal Suppression", "severity": "High", "trigger_condition": "Prolonged use or abrupt discontinuation", "message": "STOP: Chronic use causes profound immunosuppression and HPA axis suppression. Do not abruptly discontinue therapy; tapering is required to prevent acute adrenal crisis."}]', '**Endocrine Alterations:** Hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, and hyperglycemia can occur. Monitor blood glucose and signs of adrenal insufficiency, especially during stress or trauma.
INSERT INTO "drug_generic" VALUES(1956, 'Vonoprazan + Amoxicillin + Clarithromycin', 'Vonoprazan, Amoxicillin, and Clarithromycin', 'A02BD14', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Anaphylaxis and Severe Cutaneous Reactions", "severity": "High", "trigger_condition": "Patient history of Penicillin, Cephalosporin, or Macrolide hypersensitivity", "message": "STOP: Serious and occasionally fatal hypersensitivity reactions (anaphylaxis) and Severe Cutaneous Adverse Reactions (SCAR), including SJS, TEN, DRESS, and AGEP, have been reported. Discontinue immediately at the first sign of rash or hypersensitivity."}]', 'Clostridioides difficile-associated diarrhea (CDAD) has been reported with nearly all antibacterial agents and acid-suppressing therapies; evaluate patients who present with diarrhea up to 2 months post-treatment. Avoid use in patients with mononucleosis due to a high risk of developing an erythematous skin rash from amoxicillin. Prescribing this regimen in the absence of a proven or strongly suspected bacterial infection increases the risk of drug-resistant bacteria.', '- **Helicobacter pylori Eradication:** Indicated as a standard triple therapy regimen for the eradication of H. pylori in patients with active chronic gastritis, duodenal ulcers, and gastric ulcers.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to vonoprazan, amoxicillin (or other beta-lactams), or clarithromycin (or other macrolides).
INSERT INTO "drug_generic" VALUES(1957, 'Propantheline Bromide', 'Propantheline', 'A03AB05', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Heat Prostration Risk", "severity": "High", "trigger_condition": "Exposure to high environmental temperatures or fever", "message": "WARNING: Propantheline decreases sweating. In the presence of high environmental temperature or fever, heat prostration (fever and heat stroke) can occur rapidly. Discontinue use if signs of heat stroke develop."}]', '- **Cardiovascular Disease:** Use with caution in patients with coronary heart disease, congestive heart failure, cardiac arrhythmias, tachycardia, or hypertension, as anticholinergics can increase heart rate.
INSERT INTO "drug_generic" VALUES(1958, 'Isopropyl Alcohol + Hydrogen Peroxide + Glycerol', 'Isopropyl Alcohol, Hydrogen Peroxide, and Glycerin', 'D08AX', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Flammability Risk", "severity": "High", "trigger_condition": "Exposure to heat, sparks, or open flames", "message": "STOP: Highly flammable liquid and vapor. Keep away from heat, sparks, open flames, and hot surfaces. Allow hands to dry completely before touching any equipment or approaching ignition sources."}]', '**Flammability:** Isopropyl alcohol is highly flammable. Keep away from heat, sparks, flames, and strong oxidizers. Store in a flammable safety cabinet.
INSERT INTO "drug_generic" VALUES(1959, 'Acetylcysteine', 'Acetylcysteine', 'R05CB01', 0, 1, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Anaphylactoid Reactions", "severity": "High", "trigger_condition": "Intravenous administration for paracetamol overdose", "message": "STOP: IV administration can cause severe anaphylactoid reactions (flushing, hypotension, bronchospasm). Monitor closely and have resuscitation equipment available."}, {"alert_type": "Bronchospasm Risk", "severity": "High", "trigger_condition": "Inhalation administration in asthmatic patients", "message": "STOP: Inhalation can trigger severe bronchospasm. Use with extreme caution in asthmatics; administer a bronchodilator prior to use if necessary."}]', '**Anaphylactoid Reactions (IV Route):** Acute flushing, erythema, tachycardia, and hypotension can occur, most commonly during the initial loading dose. If severe, pause the infusion, treat with antihistamines/epinephrine, and restart at a slower rate.
INSERT INTO "drug_generic" VALUES(1960, 'Sodium Chloride 0.9% Nasal & Eye prep', 'Sodium Chloride 0.9% (Ophthalmic/Nasal)', 'R01AX10', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Infant Administration:** If a baby begins to cough after applying the nasal drops, allow them to sit up or assist them into a sitting position to prevent aspiration.
INSERT INTO "drug_generic" VALUES(1961, 'Avelumab', 'Avelumab', 'L01FF04', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Immune-Mediated Adverse Reactions", "severity": "High", "trigger_condition": "Patients presenting with new-onset respiratory, gastrointestinal, hepatic, or endocrine symptoms", "message": "STOP: Severe and fatal immune-mediated adverse reactions (pneumonitis, colitis, hepatitis, endocrinopathies, nephritis) can occur. Withhold therapy and initiate high-dose corticosteroids promptly if suspected."}]', '**Immune-Mediated Pneumonitis:** Severe, life-threatening, or fatal pneumonitis can occur. Monitor patients for signs and symptoms of pneumonitis. Evaluate suspected pneumonitis with radiographic imaging. Withhold for moderate pneumonitis; permanently discontinue for severe, life-threatening, or recurrent moderate pneumonitis.
INSERT INTO "drug_generic" VALUES(1962, 'Haemophilus Influenzae Type B Polysaccharide Vaccine', 'Haemophilus b Conjugate Vaccine', 'J07AG01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe allergic reaction to a previous dose or vaccine component", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, can occur. Ensure epinephrine and emergency equipment are immediately available."}]', '**Acute Illness:** Defer vaccination in individuals suffering from moderate to severe acute febrile illness until recovery. Minor illnesses (e.g., mild upper respiratory infections) are not contraindications.
INSERT INTO "drug_generic" VALUES(1963, 'Asenapine', 'Asenapine', 'N05AH05', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Increased Mortality in Elderly Patients with Dementia-Related Psychosis", "severity": "High", "trigger_condition": "Use in elderly patients with dementia-related psychosis", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Asenapine is not approved for the treatment of patients with dementia-related psychosis."}]', '**Cerebrovascular Adverse Reactions:** Increased incidence of cerebrovascular adverse reactions (e.g., stroke, transient ischemic attack), including fatalities, in elderly patients with dementia-related psychosis.
INSERT INTO "drug_generic" VALUES(1964, 'Doxazosin', 'Doxazosin', 'C02CA04', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "First-Dose Syncope Risk", "severity": "High", "trigger_condition": "Initiation of therapy or rapid dose escalation", "message": "STOP: Doxazosin can cause severe orthostatic hypotension and syncope, especially with the first dose or when increasing the dose. Initiate at 1 mg at bedtime and titrate slowly."}]', 'Prostatic carcinoma should be ruled out before starting therapy for benign prostatic hyperplasia (BPH), as the symptoms are similar.
INSERT INTO "drug_generic" VALUES(1965, 'Sugammadex sodium', 'Sugammadex', 'V03AB35', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Bradycardia", "severity": "High", "trigger_condition": "Administration of sugammadex", "message": "STOP: Marked bradycardia, some resulting in cardiac arrest, has been reported within minutes following sugammadex administration. Monitor hemodynamics continuously and be prepared to administer anticholinergic agents (e.g., atropine)."}]', '- **Bradycardia:** Marked bradycardia and cardiac arrest have occurred within minutes of administration. Monitor heart rate and blood pressure continuously.
INSERT INTO "drug_generic" VALUES(1966, 'Mizolastine', 'Mizolastine', 'R06AX25', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "QT Prolongation and Arrhythmia Risk", "severity": "High", "trigger_condition": "Concurrent use with macrolide antibiotics, imidazole antifungals, or in patients with cardiac disease", "message": "STOP: Mizolastine can cause QT interval prolongation. It is strictly contraindicated in patients with significant cardiac disease, hypokalemia, or when used concurrently with potent CYP inhibitors (e.g., erythromycin, ketoconazole) due to the risk of fatal arrhythmias."}]', 'Use with caution in the elderly, as they may be more susceptible to adverse effects, including sedation and cardiac events.
INSERT INTO "drug_generic" VALUES(1967, 'Crisaborole topical', 'Crisaborole', 'D11AH06', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Patient history of hypersensitivity to crisaborole or formulation components", "message": "STOP: Severe hypersensitivity reactions, including contact urticaria, severe pruritus, swelling, and erythema, can occur. Discontinue immediately if suspected."}]', '**Hypersensitivity Reactions:** Hypersensitivity reactions, including contact urticaria, have been reported. Signs and symptoms may include severe pruritus, swelling, and erythema at the application site or at a distant site. If signs or symptoms of hypersensitivity occur, discontinue the medication immediately and initiate appropriate symptomatic therapy.', '- **Atopic Dermatitis:** Indicated for the topical treatment of mild-to-moderate atopic dermatitis in adult and pediatric patients 3 months of age and older to reduce inflammation and pruritus.', '- **Hypersensitivity:** Contraindicated in patients with a known history of hypersensitivity to crisaborole or any component of the formulation. Re-exposure can trigger severe localized or systemic allergic reactions, including contact urticaria.', '- **Application site pain:** Burning or stinging sensation at the application site (4%)
INSERT INTO "drug_generic" VALUES(1968, 'Iron Polymaltose  +  Vitamin B Complex  +  Zinc', 'Iron Polymaltose / Vitamin B Complex / Zinc', 'B03AE', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Pediatric Toxicity", "severity": "High", "trigger_condition": "Accidental ingestion by children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '- **Iron Overload:** Caution should be taken in conditions where there is a risk of iron overload, such as hemochromatosis, thalassemia, hemosiderosis, or hemolytic anemia.
INSERT INTO "drug_generic" VALUES(1969, 'Fosfomycin Trometamol', 'Fosfomycin Tromethamine', 'J01XX01', 1, 0, 1, 0, 1, 1, 0, 0, '[{"alert_type": "Clostridioides difficile-Associated Diarrhea", "severity": "High", "trigger_condition": "Development of severe diarrhea during or after treatment", "message": "STOP: CDAD has been reported. If suspected, discontinue fosfomycin and initiate appropriate fluid, electrolyte, and antibiotic management."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Reported with nearly all antibacterial agents. Evaluate patients who present with diarrhea post-antibiotic treatment.
INSERT INTO "drug_generic" VALUES(1970, 'Urea Topical', 'Urea Topical', 'D02AE01', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Application Site:** Avoid application to moist, severely inflamed, or broken skin, as it may cause severe stinging and irritation.
INSERT INTO "drug_generic" VALUES(1971, 'Bremelanotide', 'Bremelanotide', 'G04BE12', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Patient with uncontrolled hypertension or known cardiovascular disease", "message": "STOP: Bremelanotide causes transient increases in blood pressure and decreases in heart rate. It is contraindicated in patients with uncontrolled hypertension or known cardiovascular disease."}]', '**Cardiovascular Effects:** Transient increases in blood pressure and reductions in heart rate frequently occur after each dose, typically returning to baseline within 12 hours. Assess cardiovascular risk and ensure blood pressure is well-controlled before initiating therapy. Advise patients not to exceed one dose per 24 hours to minimize pronounced cardiovascular effects.
INSERT INTO "drug_generic" VALUES(1972, 'Daunorubicin', 'Daunorubicin', 'L01DB02', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiotoxicity and Tissue Necrosis", "severity": "High", "trigger_condition": "Cumulative dose limits exceeded or extravasation during IV administration", "message": "STOP: Daunorubicin can cause severe, potentially fatal myocardial toxicity (CHF) at cumulative doses >400-550 mg/m2 in adults. It is a potent vesicant; extravasation causes severe tissue necrosis. Administer strictly via a freely flowing IV."}]', '**Cardiotoxicity:** Cumulative dosage exceeding 400-550 mg/m² in adults, 300 mg/m² in children >2 years, or 10 mg/kg in children <2 years may result in severe and potentially fatal congestive heart failure (CHF). This can occur during therapy or months to years later. Do not administer to patients with pre-existing myocardial lesions or those >75 years of age without extreme caution.
INSERT INTO "drug_generic" VALUES(1973, 'Brompheniramine + Dextromethorphan + Phenylephrine', 'Brompheniramine, Dextromethorphan, and Phenylephrine', 'R05DA20', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Respiratory Depression and CNS Toxicity", "severity": "High", "trigger_condition": "Use in young children or concurrent use with CNS depressants", "message": "STOP: Do not use in premature or full-term neonates. Severe CNS depression, respiratory depression, and confusional symptoms can occur. Avoid concurrent use with MAOIs due to the risk of serotonin syndrome and hypertensive crisis."}]', '**CNS Depression and Anticholinergic Effects:** Brompheniramine may cause significant confusional symptoms, drowsiness, and pronounced sedation. It has significant antimuscarinic activity. Avoid concurrent use with alcohol or other CNS depressants.
INSERT INTO "drug_generic" VALUES(1974, 'Lorlatinib', 'Lorlatinib', 'L01ED05', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Hepatotoxicity with CYP3A Inducers", "severity": "High", "trigger_condition": "Coadministration with strong CYP3A inducers (e.g., rifampin)", "message": "STOP: Severe hepatotoxicity can occur. Coadministration with strong CYP3A inducers is strictly contraindicated."}]', '**Central Nervous System (CNS) Effects:** A broad spectrum of CNS effects can occur, including seizures, hallucinations, changes in cognitive function, mood disorders (including suicidal ideation), and speech effects. Withhold and dose reduce, or permanently discontinue based on severity.
INSERT INTO "drug_generic" VALUES(1975, 'Interferon Alfa-2b', 'Interferon Alfa-2b', 'L03AB05', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Neuropsychiatric and Autoimmune Disorders", "severity": "High", "trigger_condition": "Patients with a history of severe psychiatric disorders, autoimmune diseases, or ischemic disorders", "message": "STOP: Alpha interferons cause or aggravate fatal or life-threatening neuropsychiatric, autoimmune, ischemic, and infectious disorders. Monitor closely and discontinue if severe reactions occur."}]', '**Neuropsychiatric Effects:** Severe psychiatric adverse reactions, including depression, suicidal ideation, suicide attempts, and suicide, have occurred. Monitor patients closely and discontinue therapy if severe psychiatric symptoms develop.
INSERT INTO "drug_generic" VALUES(1976, 'Chlorpheniramine + Paracetamol + Pseudoepedrine', 'Chlorpheniramine + Acetaminophen + Pseudoephedrine', 'R05X', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity Risk", "severity": "High", "trigger_condition": "Concomitant use of other paracetamol-containing products or chronic alcohol use", "message": "STOP: Severe and potentially fatal hepatotoxicity can occur with paracetamol overdose. Verify all concurrent medications to ensure total daily paracetamol dose does not exceed 4000 mg."}, {"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Patient history of severe hypertension or severe coronary artery disease", "message": "STOP: Pseudoephedrine can cause severe cardiovascular events. Avoid use in patients with uncontrolled hypertension or severe coronary artery disease."}]', 'Use with extreme caution in patients with cardiovascular disease, hypertension, or hyperthyroidism due to the sympathomimetic effects of pseudoephedrine, which can elevate blood pressure and heart rate.
INSERT INTO "drug_generic" VALUES(1977, 'Brimonidine Tartrate Eye prep', 'Brimonidine Tartrate', 'S01EA05', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Pediatric Contraindication", "severity": "High", "trigger_condition": "Use in neonates and infants under 2 years of age", "message": "STOP: Brimonidine is contraindicated in neonates and infants under 2 years due to the risk of severe CNS depression, apnea, bradycardia, and hypotension."}]', '**Cardiovascular Disease:** Although systemic effects are minimal, use with caution in patients with severe cardiovascular disease, coronary insufficiency, or Raynaud''s phenomenon.
INSERT INTO "drug_generic" VALUES(1978, 'Febuxostat', 'Febuxostat', 'M04AA03', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Cardiovascular Death Risk", "severity": "High", "trigger_condition": "Patients with established cardiovascular disease", "message": "WARNING: Patients with established cardiovascular disease treated with febuxostat had a higher rate of cardiovascular death compared to those treated with allopurinol. Reserve febuxostat for patients who have failed or do not tolerate allopurinol."}]', '**Cardiovascular Risk:** A higher rate of cardiovascular death has been observed in patients with established cardiovascular disease treated with febuxostat compared to allopurinol. Evaluate the risks and benefits carefully; consider alternative therapies in patients with a history of cardiovascular disease.
INSERT INTO "drug_generic" VALUES(1979, 'Eperisone Hydrochloride', 'Eperisone Hydrochloride', 'M03BX04', 0, 0, 0, 0, 0, 0, 0, 0, '[]', '- **Hepatic Impairment:** Use with caution in patients with hepatic impairment, as the drug is metabolized in the liver. Monitor liver function tests.
INSERT INTO "drug_generic" VALUES(1980, 'Etoricoxib', 'Etoricoxib', 'M01AH05', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Use of COX-2 inhibitors", "message": "STOP: Selective COX-2 inhibitors are associated with an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. Contraindicated in patients with ischemic heart disease, cerebrovascular disease, or NYHA class II-IV heart failure."}, {"alert_type": "Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use of NSAIDs/COX-2 inhibitors", "message": "STOP: Increased risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation. Use with extreme caution in patients with a history of GI disease."}]', '**Cardiovascular Disease:** Regular blood pressure monitoring is advisable. Fluid retention and edema may occur; use with caution in patients with compromised cardiac function or hypertension.
INSERT INTO "drug_generic" VALUES(1981, 'Tropicamide 0.5% Eye prep', 'Tropicamide', 'S01FA06', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Systemic Absorption:** To minimize systemic absorption, apply pressure to the lacrimal sac (nasolacrimal occlusion) for 1-2 minutes immediately following instillation.
INSERT INTO "drug_generic" VALUES(1982, 'Fentanyl', 'Fentanyl', 'N02AB03', 0, 1, 0, 0, 1, 1, 1, 1, '[{"alert_type": "Life-Threatening Respiratory Depression", "severity": "High", "trigger_condition": "Improper dosing, opioid-naive patients, or co-administration with CNS depressants", "message": "WARNING: Fatal respiratory depression may occur. Transdermal patches are strictly contraindicated in opioid-naive patients. Monitor closely for respiratory depression, especially during initiation or dose escalation."}]', '**Respiratory Depression:** Serious, life-threatening, or fatal respiratory depression may occur. Monitor closely, especially in the elderly, debilitated patients, and those with underlying respiratory conditions (e.g., COPD, hypoxia, hypercapnia).
INSERT INTO "drug_generic" VALUES(1983, 'Ethambutol + Isoniazid + Pyrazinamide + Rifampicin', 'Rifampin, Isoniazid, Pyrazinamide, and Ethambutol', 'J04AM06', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Hepatotoxicity", "severity": "High", "trigger_condition": "Development of jaundice, dark urine, severe fatigue, or significantly elevated transaminases", "message": "STOP: Isoniazid, Rifampicin, and Pyrazinamide can all cause severe and sometimes fatal hepatotoxicity. Discontinue immediately if clinical signs of hepatitis occur and evaluate liver function tests."}]', 'Monitor liver function tests (ALT, AST, bilirubin) at baseline and periodically, especially in patients with pre-existing liver disease, alcohol abuse, or those over 35 years of age. Monitor renal function and serum uric acid; pyrazinamide and ethambutol can cause hyperuricemia and precipitate acute gout. Perform baseline and periodic visual acuity and color vision testing due to ethambutol; use with caution in children <8 years who cannot report visual changes. Isoniazid can cause peripheral neuropathy; prophylactic pyridoxine (Vitamin B6) is recommended, especially in malnourished, diabetic, or pregnant patients. Rifampicin causes red-orange discoloration of body fluids (urine, sweat, tears) and can permanently stain soft contact lenses. Rifampicin is a potent CYP450 inducer and will significantly decrease the levels of many concomitant medications.', '- **Tuberculosis (Initial Phase):** Indicated for the initial intensive phase (first 2 months) of short-course treatment for active pulmonary and extrapulmonary tuberculosis.', '- **Hepatic Disease:** Contraindicated in patients with acute liver disease or a history of severe drug-induced hepatitis.
INSERT INTO "drug_generic" VALUES(1984, 'Trastuzumab deruxtecan', 'Fam-trastuzumab deruxtecan-nxki', 'L01FD04', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Interstitial Lung Disease (ILD) / Pneumonitis", "severity": "High", "trigger_condition": "Development of cough, dyspnea, fever, or new radiographic infiltrates", "message": "STOP: Severe, life-threatening, or fatal ILD/pneumonitis can occur. Withhold treatment for Grade 1 ILD and permanently discontinue for Grade 2 or higher. Treat with corticosteroids."}, {"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Use during pregnancy", "message": "STOP: Can cause fetal harm. Verify pregnancy status prior to initiation and advise effective contraception."}]', '**Interstitial Lung Disease (ILD) / Pneumonitis:** Severe, life-threatening, or fatal ILD, including pneumonitis, can occur. Monitor for pulmonary symptoms (cough, dyspnea, fever) and radiographic changes. Promptly investigate any new or worsening symptoms. Withhold for Grade 1 ILD and permanently discontinue for Grade 2 or higher. Administer systemic corticosteroids promptly.
INSERT INTO "drug_generic" VALUES(1985, 'Zaleplone', 'Zaleplon', 'N05CF03', 0, 1, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Complex Sleep Behaviors", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "STOP: Sedative-hypnotics can cause complex sleep behaviors (e.g., sleep-driving, sleep-cooking) which may result in serious injury or death. Discontinue immediately if a patient experiences a complex sleep behavior."}]', 'May cause severe CNS depression; caution in elderly or debilitated patients. Risk of complex sleep-related behaviors (sleep-driving, making food while asleep) with amnesia for the event. May precipitate new psychiatric abnormalities or worsen depression (risk of suicidal ideation). History of drug or alcohol dependence increases the risk of abuse. Do not take zaleplon unless there is an opportunity for at least 4 hours of uninterrupted sleep before becoming active again. Dose reduction or withdrawal should be done gradually to avoid rebound insomnia.', '- **Insomnia:** Short-term treatment of insomnia, particularly characterized by difficulty with sleep initiation.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to zaleplon or any of its components.
INSERT INTO "drug_generic" VALUES(1986, 'Medroxyprogesterone Acetate', 'Medroxyprogesterone Acetate', 'G03DA02', 0, 0, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Loss of Bone Mineral Density", "severity": "High", "trigger_condition": "Long-term use (e.g., >2 years) of the injectable contraceptive formulation", "message": "STOP: Women who use medroxyprogesterone acetate contraceptive injection may lose significant bone mineral density (BMD). Bone loss is greater with increasing duration of use and may not be completely reversible. It should be used as a long-term birth control method (longer than 2 years) only if other birth control methods are inadequate."}]', '**Thromboembolic Disorders:** Be alert to the earliest manifestations of thrombotic disorders (thrombophlebitis, pulmonary embolism, cerebrovascular disorders, and retinal thrombosis). Discontinue immediately if any of these occur or are suspected.
INSERT INTO "drug_generic" VALUES(1987, 'Calcium (Coral Source) + Vitamin D3', 'Calcium and Cholecalciferol', 'A12AX', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "Moderate", "trigger_condition": "Concomitant use of thiazide diuretics or severe renal impairment", "message": "Monitor serum calcium levels closely. Excessive calcium intake can lead to milk-alkali syndrome, severe hypercalcemia, and renal damage."}]', '- **Renal Impairment:** Patients with mild to moderate renal failure or mild hypercalciuria should be supervised carefully, including periodic checks of plasma calcium levels and urinary calcium excretion.
INSERT INTO "drug_generic" VALUES(1988, 'Atropine eye prep', 'Atropine Ophthalmic', 'S01FA01', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Systemic Absorption and Toxicity", "severity": "High", "trigger_condition": "Ophthalmic administration, especially in infants and children", "message": "STOP: Systemic absorption can occur, leading to severe anticholinergic toxicity (tachycardia, hyperthermia, delirium). Use with extreme caution in children, especially those with Down syndrome, spastic paralysis, or brain damage, as they are hyper-reactive to atropine."}]', '**Visual Impairment:** Causes profound mydriasis (pupil dilation) and cycloplegia (paralysis of accommodation) that can last up to 2 weeks. Patients will experience photophobia and blurred vision. Advise against driving or operating machinery.
INSERT INTO "drug_generic" VALUES(1989, 'Meningococcal (Groups A, C, Y and W-135) Polysaccharide Diphtheria Toxoid Conjugate Vaccine', 'Meningococcal (Groups A, C, Y and W-135) Polysaccharide Diphtheria Toxoid Conjugate Vaccine', 'J07AH08', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Anaphylaxis and Guillain-Barr\u00e9 Syndrome", "severity": "High", "trigger_condition": "History of severe allergic reaction to previous dose or history of GBS", "message": "STOP: Contraindicated if history of anaphylaxis to vaccine components. Weigh risks and benefits carefully in patients with a history of Guillain-Barr\u00e9 Syndrome."}]', '**Guillain-Barré Syndrome (GBS):** Persons previously diagnosed with GBS may be at increased risk of GBS following receipt of this vaccine. The decision to administer should take into account the potential benefits and risks. GBS has been reported in temporal relationship following administration.
INSERT INTO "drug_generic" VALUES(1990, 'Aspartame', 'Aspartame', 'V04CX', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Phenylketonuria (PKU)", "severity": "High", "trigger_condition": "Patients with Phenylketonuria", "message": "STOP: Aspartame is metabolized into phenylalanine. It is strictly contraindicated in patients with Phenylketonuria (PKU), a rare genetic disorder where phenylalanine cannot be metabolized and accumulates to toxic levels in the brain."}]', '**Phenylketonuria (PKU):** Individuals with PKU must strictly monitor their intake of phenylalanine from all sources, including aspartame. Products containing aspartame must carry a warning label for phenylketonurics.
INSERT INTO "drug_generic" VALUES(1991, 'Amisulpride IV', 'Amisulpride', 'N05AL05', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Coadministration with QT-prolonging drugs or presence of congenital long QT syndrome", "message": "STOP: Amisulpride causes dose- and concentration-dependent prolongation of the QT interval. Avoid use in patients with congenital long QT syndrome or those taking droperidol."}]', 'Use with extreme caution in patients with preexisting arrhythmias, cardiac conduction disorders, or a history of QT prolongation.
INSERT INTO "drug_generic" VALUES(1992, 'Metformin Hydrochloride + Pioglitazone', 'Metformin and Pioglitazone', 'A10BD05', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Heart Failure and Lactic Acidosis Risk", "severity": "High", "trigger_condition": "Patient with NYHA Class III/IV heart failure or severe renal impairment (eGFR < 30 mL/min)", "message": "STOP: Pioglitazone can cause or exacerbate congestive heart failure. Metformin can cause fatal lactic acidosis. Contraindicated in severe heart failure and severe renal impairment."}]', '**Congestive Heart Failure:** Pioglitazone can cause dose-related fluid retention, which may lead to or exacerbate heart failure. Monitor patients closely for signs and symptoms of heart failure (e.g., rapid weight gain, dyspnea, edema). Discontinue if heart failure develops.
INSERT INTO "drug_generic" VALUES(1993, 'Cinacalcet', 'Cinacalcet', 'H05BX01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Hypocalcemia", "severity": "High", "trigger_condition": "Initiation of therapy or dose titration", "message": "Life-threatening events and fatal outcomes associated with hypocalcemia have been reported. Monitor serum calcium closely. Do not initiate if serum calcium is below the lower limit of normal."}]', '**Hypocalcemia:** Significant lowering of serum calcium can cause paresthesias, myalgias, muscle spasms, tetany, seizures, QT interval prolongation, and ventricular arrhythmias. Monitor serum calcium within 1 week of initiation or dose adjustment.
INSERT INTO "drug_generic" VALUES(1994, 'Avatrombopag', 'Avatrombopag', 'B02BX08', 0, 1, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "Patients with chronic liver disease or known prothrombotic conditions", "message": "Thrombopoietin (TPO) receptor agonists are associated with thrombotic and thromboembolic complications, including portal vein thrombosis. Do not use to normalize platelet counts."}]', '**Thrombotic and Thromboembolic Complications:** Thrombopoietin (TPO) receptor agonists are associated with an increased risk of thrombotic and thromboembolic complications in patients with chronic liver disease or chronic immune thrombocytopenia (ITP). Portal vein thrombosis has been reported. Consider the potential increased thrombotic risk when administering to patients with known risk factors for thromboembolism, including genetic prothrombotic conditions (e.g., Factor V Leiden, prothrombin 20210A, antithrombin deficiency, or protein C or S deficiency). Do not administer in an attempt to normalize platelet counts.
INSERT INTO "drug_generic" VALUES(1995, 'Ethionamide', 'Ethionamide', 'J04AD03', 1, 0, 0, 0, 1, 0, 1, 0, '[]', 'Use with caution in patients with a history of depression or other psychiatric illnesses, as ethionamide can cause severe CNS toxicity, including psychosis. Caution is advised in patients with diabetes mellitus (risk of hypoglycemia), porphyria, or thyroid dysfunction (risk of hypothyroidism/goiter). Hepatotoxicity is a significant risk; monitor serum ALT and AST at baseline and monthly. Perform ophthalmologic examinations prior to and periodically during therapy to monitor for optic neuritis. Evaluate for peripheral neuropathy; co-administration of pyridoxine (Vitamin B6) is strongly recommended to prevent this complication.', '- **Tuberculosis (Active):** Indicated as a second-line agent for the treatment of active tuberculosis caused by *Mycobacterium tuberculosis* strains resistant to isoniazid or rifampin, or when the patient is intolerant to primary drugs. Must always be used in combination with other effective antituberculosis agents.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to ethionamide. Rationale: Risk of severe allergic reactions.
INSERT INTO "drug_generic" VALUES(1996, 'Clindamycin + Benzoyl Peroxide', 'Clindamycin and Benzoyl Peroxide', 'D10AF51', 1, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Severe Colitis Risk", "severity": "High", "trigger_condition": "Development of severe diarrhea or abdominal cramps during topical treatment", "message": "STOP: Systemic absorption of topical clindamycin can occur, leading to severe and potentially fatal pseudomembranous colitis. Discontinue immediately if significant diarrhea occurs."}]', '**Atopic Dermatitis:** Use with extreme caution in atopic individuals as they may be more susceptible to severe skin irritation and dryness.
INSERT INTO "drug_generic" VALUES(1997, 'Sulphonated Surfactant', 'Sulfonated Surfactant Cleanser', 'D11AX', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Ocular Irritation", "severity": "Low", "trigger_condition": "Accidental contact with eyes", "message": "Avoid contact with eyes. If lather enters the eyes, flush immediately and thoroughly with water to prevent severe irritation."}]', '**Ocular Exposure:** Avoid contact with eyes. Surfactants can cause significant ocular irritation and conjunctival erythema. Flush with copious amounts of water if contact occurs.
INSERT INTO "drug_generic" VALUES(1998, 'Naftopidil', 'Naftopidil', 'G04CA06', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Orthostatic Hypotension", "severity": "Moderate", "trigger_condition": "Initiation of therapy or dose escalation", "message": "Caution: May cause sudden decreases in blood pressure leading to syncope or temporary loss of consciousness. Advise patients to rise slowly from a sitting or lying position."}]', 'Use with caution in patients with a history of orthostatic hypotension, salt imbalance, or diabetes. Monitor blood pressure regularly, especially during the initiation of therapy or when adjusting the dose. Patients should be warned about the potential for dizziness or syncope and advised to avoid driving or operating hazardous machinery if these symptoms occur. Not intended for use in women.', '- Treatment of benign prostatic obstruction and benign prostatic hyperplasia (BPH) associated lower urinary tract symptoms (LUTS). Note: It does not decrease the size of the prostate.', '**Hypersensitivity:** Contraindicated in patients with a known history of hypersensitivity to naftopidil or any of its components, as it may precipitate allergic reactions.', '- **Dizziness**
INSERT INTO "drug_generic" VALUES(1999, 'Lorazepam', 'Lorazepam', 'N05BA06', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Concomitant Use with Opioids", "severity": "High", "trigger_condition": "Co-prescription or co-administration with opioid analgesics or other CNS depressants", "message": "STOP: Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death. Reserve concomitant prescribing for patients with inadequate alternative treatment options. Limit dosages and durations to the minimum required."}]', '**Respiratory Depression:** Can cause dose-dependent respiratory depression. Use with extreme caution in patients with compromised pulmonary function (e.g., COPD, sleep apnea).
INSERT INTO "drug_generic" VALUES(2000, 'Hydrochlorothiazide + Ramipril', 'Ramipril and Hydrochlorothiazide', 'C09BA05', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}, {"alert_type": "Angioedema", "severity": "High", "trigger_condition": "History of ACE inhibitor-induced angioedema", "message": "STOP: Contraindicated in patients with a history of angioedema related to previous ACE inhibitor therapy. Can cause fatal airway obstruction."}]', '**Angioedema:** Head and neck angioedema, as well as intestinal angioedema, can occur at any time during treatment. Discontinue immediately if angioedema occurs.
INSERT INTO "drug_generic" VALUES(2001, 'Valdecoxib', 'Valdecoxib', 'M01AH03', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Dermatologic Toxicity", "severity": "High", "trigger_condition": "Any use of the medication", "message": "STOP: Valdecoxib has been withdrawn from the market worldwide due to an unacceptable risk of severe cardiovascular thrombotic events (myocardial infarction, stroke) and potentially fatal skin reactions (Stevens-Johnson syndrome, toxic epidermal necrolysis)."}]', 'Use with extreme caution in patients with mild to moderate hepatic impairment, a history of peptic ulcer disease, or gastrointestinal bleeding. Monitor closely in patients with dehydration, hypertension, history of heart failure, left ventricular dysfunction, or pre-existing edema. Monitor hemoglobin and hematocrit values for signs of occult gastrointestinal bleeding or anemia.', '- **Osteoarthritis:** For the relief of signs and symptoms associated with osteoarthritis.
INSERT INTO "drug_generic" VALUES(2002, 'Cenegermin eye prep', 'Cenegermin', 'S01XA24', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Remove contact lenses before application; the presence of a contact lens (either therapeutic or corrective) could theoretically limit the distribution of cenegermin onto the area of the corneal lesion.
INSERT INTO "drug_generic" VALUES(2003, 'Hydrocortisone Acetate 2.5% + Pramoxine 1% Topical', 'Hydrocortisone and Pramoxine', 'D04AB01', 0, 0, 0, 0, 0, 1, 1, 0, '[]', 'Systemic absorption of topical corticosteroids can produce reversible HPA axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria. Conditions that augment systemic absorption include application over large surface areas, prolonged use, and the use of occlusive dressings. If HPA axis suppression is noted, attempt to withdraw the drug, reduce application frequency, or substitute a less potent steroid. Children may absorb proportionally larger amounts and are more susceptible to systemic toxicity. Discontinue if local irritation develops. In the presence of dermatological infections, institute appropriate antifungal or antibacterial therapy; if a favorable response does not occur promptly, discontinue the corticosteroid until the infection is controlled.', '- **Anorectal Disorders:** Temporary relief of pain, itching, and swelling associated with hemorrhoids, anal fissures, and pruritus ani.
INSERT INTO "drug_generic" VALUES(2004, 'Oritavancin', 'Oritavancin', 'J01XA05', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Coagulation Test Interference", "severity": "High", "trigger_condition": "Patients requiring coagulation monitoring (aPTT, PT/INR) or concurrent heparin use", "message": "STOP: Oritavancin artificially prolongs aPTT for up to 120 hours and PT/INR for up to 12 hours. Use of IV unfractionated heparin within 120 hours of oritavancin is contraindicated."}]', '**Coagulation Test Interference:** Oritavancin artificially prolongs aPTT for up to 120 hours, PT and INR for up to 12 hours, and ACT for up to 24 hours by binding to and preventing the action of the phospholipid reagents used in these tests. For patients requiring aPTT monitoring within 120 hours of dosing, consider a non-phospholipid dependent coagulation test (e.g., Factor Xa chromogenic assay) or an alternative anticoagulant.
INSERT INTO "drug_generic" VALUES(2005, 'Amlodipine + Losartan', 'Amlodipine + Losartan', 'C09DB06', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately as soon as pregnancy is detected."}]', 'Monitor serum potassium levels regularly, especially in patients with renal impairment or diabetes, due to the risk of hyperkalemia from losartan.
INSERT INTO "drug_generic" VALUES(2006, 'Conjugated Estrogens Vaginal prep', 'Conjugated Estrogens', 'G03CA57', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Endometrial Cancer and Cardiovascular Risk", "severity": "High", "trigger_condition": "Use of unopposed estrogen in women with an intact uterus", "message": "STOP: Estrogens increase the risk of endometrial cancer. Do not use estrogen-alone therapy for the prevention of cardiovascular disease or dementia due to increased risks of stroke, DVT, and probable dementia."}]', '**Endometrial Cancer:** Increased risk in women with a uterus using unopposed estrogens. Adequate diagnostic measures must be undertaken for undiagnosed persistent or recurring abnormal vaginal bleeding.
INSERT INTO "drug_generic" VALUES(2007, 'Elemental Iron (Iron Polymaltose Complex) + Folic Acid + Zinc + Vitamin B-Complex', 'Iron Polymaltose, Folic Acid, Zinc, and B-Complex Vitamins', 'B03AD', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Accidental Overdose in Children", "severity": "High", "trigger_condition": "Unsecured storage accessible to children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Iron Overload:** Care should be taken in patients who may develop iron overload, such as those with hemochromatosis, hemosiderosis, hemolytic anemia, or red cell aplasia.
INSERT INTO "drug_generic" VALUES(2008, 'Tetracycline Hydrochloride', 'Tetracycline', 'J01AA07', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Tooth Discoloration and Bone Growth Inhibition", "severity": "High", "trigger_condition": "Use in children under 8 years of age or during pregnancy", "message": "Tetracyclines can cause permanent discoloration of teeth (yellow-gray-brown) and inhibit bone growth. Avoid use during tooth development (last half of pregnancy, infancy, and childhood up to 8 years) unless other drugs are ineffective or contraindicated."}]', 'Use with caution in patients with pre-existing systemic lupus erythematosus (SLE) or myasthenia gravis, as it may exacerbate these conditions. Avoid direct exposure to sunlight or UV light due to the risk of severe photosensitivity reactions. Monitor renal, hepatic, and hematologic function periodically during prolonged therapy. Use of expired tetracycline can cause a dangerous Fanconi-like syndrome (renal tubular dysfunction). Monitor for signs of superinfection, including Clostridioides difficile-associated diarrhea (CDAD).', '- **Rickettsial Infections:** Typhus fever, Q-fever, Rocky Mountain spotted fever.
INSERT INTO "drug_generic" VALUES(2009, 'Decitabine', 'Decitabine', 'L01BC08', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "During treatment cycles", "message": "STOP: High risk of severe myelosuppression (neutropenia, thrombocytopenia, anemia) leading to fatal infections and bleeding. Perform complete blood counts (CBC) prior to each cycle and as needed."}]', '**Myelosuppression:** Fatal and serious myelosuppression occurs. Obtain complete blood counts prior to each cycle and as clinically indicated to monitor response and toxicity. Delay subsequent cycles or reduce the dose if hematologic recovery is prolonged.
INSERT INTO "drug_generic" VALUES(2010, 'Olopatadine 0.1% Eye prep', 'Olopatadine Hydrochloride', 'S01GX09', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Contact Lens Use:** Not intended for the treatment of contact lens-related irritation. Patients should be advised not to wear a contact lens if their eye is red. The preservative in the solution, benzalkonium chloride, may be absorbed by soft contact lenses. Patients who wear soft contact lenses and whose eyes are not red should be instructed to wait at least 10 minutes after instilling the drops before inserting their contact lenses.
INSERT INTO "drug_generic" VALUES(2011, 'Naproxen', 'Naproxen', 'M01AE02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Prolonged use, high doses, or pre-existing CV/GI disease", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events, including myocardial infarction and stroke, which can be fatal. They also cause an increased risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation of the stomach or intestines. Contraindicated for perioperative pain in the setting of CABG surgery."}]', '- **Cardiovascular Risk:** Use with caution in patients with known cardiovascular disease, hypertension, fluid retention, or heart failure. NSAIDs can cause new-onset hypertension or worsen existing hypertension. Monitor blood pressure closely.
INSERT INTO "drug_generic" VALUES(2012, 'Dithranol 1% Topical', 'Anthralin 1% Topical', 'D05AC01', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Severe Skin Irritation and Staining", "severity": "Medium", "trigger_condition": "Application to normal skin, face, or flexures", "message": "STOP: Dithranol causes severe burning and irritation if applied to healthy skin. It also permanently stains clothing, bedding, and temporarily stains skin and hair. Apply strictly to psoriatic plaques."}]', '- **Application Site:** Avoid use on the face, skin flexures (axillae, groin), inner thighs, upper arms, and genitals due to the high risk of severe irritation.
INSERT INTO "drug_generic" VALUES(2013, 'Multivitamins + Multiminerals', 'Multivitamins and Minerals', 'A11AA03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Iron Toxicity", "severity": "High", "trigger_condition": "Accidental overdose in children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Renal Impairment:** Use with caution in patients with mild to moderate renal failure. Accumulation of fat-soluble vitamins (A, D) and certain minerals can occur.
INSERT INTO "drug_generic" VALUES(2014, 'Celecoxib', 'Celecoxib', 'M01AH01', 0, 0, 0, 1, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Patients with existing cardiovascular disease or risk factors", "message": "STOP: NSAIDs may cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke, which can be fatal. Contraindicated for perioperative pain in the setting of CABG surgery."}, {"alert_type": "Gastrointestinal Risk", "severity": "High", "trigger_condition": "Elderly patients or those with a history of peptic ulcer disease/GI bleeding", "message": "STOP: NSAIDs cause an increased risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation of the stomach or intestines, which can be fatal."}]', '**Cardiovascular Thrombotic Events:** Continuous use may increase the risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. Risk increases with duration of use and in patients with underlying cardiovascular disease.
INSERT INTO "drug_generic" VALUES(2015, 'Favipiravir (Investigational)', 'Favipiravir', 'J05AX27', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Teratogenicity", "severity": "High", "trigger_condition": "Pregnancy or potential for pregnancy", "message": "STOP: Favipiravir is highly teratogenic and embryotoxic. It is strictly contraindicated in pregnancy. Exclude pregnancy before initiation and ensure strict contraceptive measures."}]', '**Investigational Status:** Favipiravir is an investigational drug in many regions and is approved in specific countries (e.g., Japan) only for novel or re-emerging influenza virus infections unresponsive to conventional antivirals. Its efficacy and safety profile, particularly for COVID-19, are still under investigation.
INSERT INTO "drug_generic" VALUES(2016, 'Amoxicillin + Clavulanic Acid (Clavulanate)', 'Amoxicillin and Clavulanate', 'J01CR02', 1, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Development of jaundice or elevated liver enzymes", "message": "STOP: Hepatic dysfunction, including cholestatic jaundice and severe hepatitis, can occur. It is more common in the elderly and males, and with prolonged treatment. Discontinue if signs of hepatitis occur."}, {"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with nearly all antibacterial agents. Evaluate patients who develop severe diarrhea.
INSERT INTO "drug_generic" VALUES(2017, 'Balsalazide', 'Balsalazide', 'A07EC04', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Acute Intolerance Syndrome", "severity": "High", "trigger_condition": "Worsening of ulcerative colitis symptoms shortly after initiation", "message": "STOP: Mesalamine-induced acute intolerance syndrome can occur, presenting with cramping, acute abdominal pain, bloody diarrhea, and sometimes fever, headache, and rash. Discontinue immediately if suspected."}]', '- **Renal Impairment:** Assess renal function prior to initiation and periodically during therapy. Mesalamine has been associated with renal impairment, including minimal change disease and acute/chronic interstitial nephritis.
INSERT INTO "drug_generic" VALUES(2018, 'Clobazam', 'Clobazam', 'N03AE01', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Concomitant Use with Opioids", "severity": "High", "trigger_condition": "Concurrent use of clobazam and opioid medications", "message": "WARNING: Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death. Reserve concomitant prescribing for patients with inadequate alternative options."}, {"alert_type": "Abuse, Misuse, and Addiction", "severity": "High", "trigger_condition": "Prescribing or dispensing clobazam", "message": "WARNING: Use exposes patients to risks of abuse, misuse, and addiction, which can lead to overdose or death. Assess risk before prescribing and monitor regularly."}, {"alert_type": "Dependence and Withdrawal Reactions", "severity": "High", "trigger_condition": "Abrupt discontinuation or rapid dose reduction", "message": "WARNING: Abrupt discontinuation can precipitate acute, life-threatening withdrawal reactions (e.g., seizures). Always use a gradual taper to discontinue or reduce the dosage."}]', '**Serious Dermatological Reactions:** Stevens-Johnson syndrome (SJS) and toxic epidermal necrolysis (TEN) have been reported. Discontinue immediately at the first sign of a rash.
INSERT INTO "drug_generic" VALUES(2019, 'Para-aminosalicylic acid (4-Aminosalicylic acid)', 'Aminosalicylic Acid', 'J04AA01', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity and Hypersensitivity", "severity": "High", "trigger_condition": "Onset of fever, rash, or jaundice during the first 3 months of therapy", "message": "STOP: Drug-induced hepatitis and severe hypersensitivity reactions can occur. Discontinue immediately if signs of liver injury or severe allergic reaction develop."}]', 'Monitor liver function tests (AST, ALT, bilirubin) closely, especially during the first 3 months of treatment.
INSERT INTO "drug_generic" VALUES(2020, 'Pyrethrins + Piperonyl butoxide topical', 'Pyrethrins and Piperonyl butoxide topical', 'P03AC51', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Allergic Reaction Risk", "severity": "Moderate", "trigger_condition": "Patient history of ragweed or chrysanthemum allergy", "message": "STOP: Pyrethrins are extracted from chrysanthemums. Cross-reactivity can occur in patients with ragweed (Asteraceae family) allergies, potentially causing severe respiratory or dermatologic reactions."}]', '- **External Use Only:** Avoid contact with the eyes, eyelashes, eyebrows, and mucosal tissues (oral, nasal, genitalia). If contact occurs, flush immediately with water.
INSERT INTO "drug_generic" VALUES(2021, 'Sparfloxacin', 'Sparfloxacin', 'J01MA09', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "QT Prolongation and Phototoxicity", "severity": "High", "trigger_condition": "Concurrent use of QT-prolonging drugs or exposure to sunlight", "message": "STOP: Sparfloxacin carries a high risk of significant QT prolongation and severe phototoxicity. Avoid concurrent use with other QT-prolonging agents and instruct patients to strictly avoid sunlight/UV exposure during and for 5 days after therapy."}]', 'Use with extreme caution in patients with known QT prolongation, uncorrected electrolyte disturbances (hypokalemia, hypomagnesemia), bradycardia, or pre-existing cardiac disease. Discontinue immediately if the patient experiences tendon pain, inflammation, or rupture; subsequent use of fluoroquinolones is not recommended. Severe phototoxicity can occur; patients must avoid exposure to strong sunlight or sunlamps during treatment and for 5 days following the last dose. Use with caution in patients with a history of CNS disorders, epilepsy, or conditions predisposing to seizures. Monitor for signs of pseudomembranous colitis (Clostridioides difficile-associated diarrhea). Ensure adequate fluid intake to reduce the risk of crystalluria. Avoid use in MRSA infections due to a high risk of resistance.', '- **Community-Acquired Pneumonia (CAP):** Treatment of CAP caused by susceptible strains of *C. pneumoniae*, *H. influenzae*, *M. catarrhalis*, *M. pneumoniae*, or *S. pneumoniae*.
INSERT INTO "drug_generic" VALUES(2022, 'Tolterodine Tartrate', 'Tolterodine', 'G04BD07', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Urinary Retention and QT Prolongation", "severity": "High", "trigger_condition": "Patients with bladder outflow obstruction or pre-existing QT prolongation", "message": "Use with extreme caution. Tolterodine can precipitate acute urinary retention in susceptible patients and may prolong the QT interval, increasing the risk of Torsades de Pointes."}]', 'Use with caution in patients with clinically significant bladder outflow obstruction (risk of urinary retention), gastrointestinal obstructive disorders (e.g., pyloric stenosis), autonomic neuropathy, hiatus hernia, or decreased GI motility. Exercise caution in patients at risk of QT interval prolongation (e.g., hypokalemia, hypomagnesemia, bradycardia, or concurrent use of Class IA or III antiarrhythmics). Adjust dose in renal or hepatic impairment.', '- **Overactive Bladder:** Treatment of overactive bladder with symptoms of urge urinary incontinence, urgency, and frequency.', '- **Urinary Retention:** Contraindicated as anticholinergic effects will exacerbate the condition.
INSERT INTO "drug_generic" VALUES(2023, 'Iron + Folic acid + Vitamin B Complex + Vitamin C + Zinc', 'Iron, Folic Acid, B-Complex, Vitamin C, and Zinc', 'B03AE04', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Iron Toxicity", "severity": "High", "trigger_condition": "Accidental overdose in children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Iron Overload:** Care should be taken in patients who may develop iron overload. Do not use in patients with frequent blood transfusions.
INSERT INTO "drug_generic" VALUES(2024, 'Lifitegrast eye prep', 'Lifitegrast Ophthalmic', 'S01XA25', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '**Contact Lens Wear:** Contact lenses should be removed prior to the administration of lifitegrast ophthalmic solution. The presence of contact lenses may interfere with drug distribution or exacerbate eye irritation. Lenses may be reinserted 15 minutes following administration.
INSERT INTO "drug_generic" VALUES(2025, 'Cabazitaxel accton solvate', 'Cabazitaxel', 'L01CD04', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fatal Neutropenia and Hypersensitivity", "severity": "High", "trigger_condition": "Neutrophil count <1,500 cells/mm3 or history of polysorbate 80 allergy", "message": "STOP: Cabazitaxel can cause fatal neutropenia and severe hypersensitivity reactions. Contraindicated if ANC <1,500/mm3. Premedication with corticosteroids, H2 antagonists, and antihistamines is mandatory."}]', '**Bone Marrow Suppression:** Severe neutropenia, febrile neutropenia, and fatal infections can occur. Monitor CBC frequently. Primary prophylaxis with G-CSF is recommended in high-risk patients and those receiving 25 mg/m2.
INSERT INTO "drug_generic" VALUES(2026, 'Budesonide 0.1%  Nasal spray', 'Budesonide nasal', 'R01AD05', 0, 0, 1, 1, 0, 0, 1, 0, '[]', 'Monitor patients periodically for signs of adverse effects on the nasal mucosa, including epistaxis, *Candida albicans* infections, nasal septal perforation, and impaired wound healing.
INSERT INTO "drug_generic" VALUES(2027, 'Fluconazole 0.2% IV', 'Fluconazole Injection', 'J02AC01', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Drug Interaction / Arrhythmia Risk", "severity": "High", "trigger_condition": "Concurrent use of QT-prolonging drugs metabolized by CYP3A4", "message": "STOP: Fluclonazole is a potent CYP inhibitor. Co-administration with drugs like erythromycin, pimozide, or quinidine can cause fatal QT prolongation and Torsades de Pointes."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Patients with underlying liver disease", "message": "WARNING: Fluconazole has been associated with rare cases of serious hepatic toxicity, including fatalities. Monitor liver function tests closely."}]', '- **Hepatotoxicity:** Rare cases of serious hepatic toxicity, including fatalities, have occurred. Monitor LFTs; discontinue if clinical signs of liver disease develop.
INSERT INTO "drug_generic" VALUES(2028, 'Revefenacin', 'Revefenacin', 'R03BB07', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediately following inhalation", "message": "STOP: Inhaled medicines can produce paradoxical bronchospasm that may be life-threatening. If this occurs, treat immediately with a short-acting bronchodilator and discontinue revefenacin."}]', '**Not for Acute Deterioration:** Do not initiate during acutely deteriorating or life-threatening COPD episodes. Revefenacin is intended as a daily maintenance treatment and is not a rescue medication for the relief of acute bronchospasm.
INSERT INTO "drug_generic" VALUES(2029, 'Magnesium Sulphate 4% infusion', 'Magnesium Sulfate in Water for Injection', 'B05XA05', 0, 1, 0, 1, 1, 1, 0, 0, '[{"alert_type": "Magnesium Toxicity", "severity": "High", "trigger_condition": "Rapid IV administration or renal impairment", "message": "STOP: Intravenous magnesium sulfate is a HIGH ALERT medication. Overdose or rapid infusion can cause fatal respiratory paralysis, heart block, and cardiac arrest. Monitor patellar reflexes, respiratory rate, and urine output continuously. Have IV Calcium Gluconate readily available as an antidote."}]', '**Renal Impairment:** Magnesium is excreted solely by the kidneys. Accumulation and severe toxicity can occur in renal impairment. Monitor serum magnesium levels closely.
INSERT INTO "drug_generic" VALUES(2030, 'Tenofovir Alafenamide', 'Tenofovir Alafenamide', 'J05AF13', 0, 0, 1, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Acute Exacerbation of Hepatitis B", "severity": "High", "trigger_condition": "Discontinuation of therapy", "message": "Discontinuation of anti-hepatitis B therapy may result in severe acute exacerbations of hepatitis B. Monitor hepatic function closely for at least several months after stopping treatment."}]', '**Severe Acute Exacerbation of Hepatitis B:** Discontinuation of anti-hepatitis B therapy, including tenofovir alafenamide, may result in severe acute exacerbations of hepatitis B. Hepatic function should be monitored closely with both clinical and laboratory follow-up for at least several months in patients who discontinue therapy. If appropriate, resumption of anti-hepatitis B therapy may be warranted.
INSERT INTO "drug_generic" VALUES(2031, 'Insulin Degludec + Insulin Aspart Premixed', 'Insulin Degludec and Insulin Aspart', 'A10AD06', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypoglycemia Risk", "severity": "High", "trigger_condition": "Dosing errors, skipped meals, or intense exercise", "message": "STOP: Severe, life-threatening hypoglycemia can occur. Ensure patients are educated on recognizing and treating hypoglycemia. Never share insulin pens between patients, even if the needle is changed, due to the risk of transmitting blood-borne pathogens."}]', '**Hypoglycemia:** The most common adverse effect. Risk increases with changes in meal patterns, physical activity, or co-administered glucose-lowering drugs. Monitor blood glucose closely.
INSERT INTO "drug_generic" VALUES(2032, 'Ofloxacin 0.3%  E/E drops', 'Ofloxacin Ophthalmic/Otic', 'S01AE01', 1, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Superinfection Risk", "severity": "Medium", "trigger_condition": "Prolonged use beyond the recommended duration", "message": "Prolonged use of topical antibiotics may result in the overgrowth of non-susceptible organisms, including fungi. If infection does not improve after one week, obtain cultures to guide further therapy."}]', 'If otorrhea persists after a full course of therapy, or if two or more episodes occur within six months, further evaluation is required to exclude underlying conditions such as cholesteatoma, foreign body, or tumor. Systemic administration of quinolones has caused cartilage lesions in immature animals; while systemic absorption from topical use is minimal, caution is advised. Discontinue use immediately at the first sign of a skin rash or any other sign of hypersensitivity.', '- **Bacterial Conjunctivitis:** Treatment of superficial ocular infections caused by susceptible strains.
INSERT INTO "drug_generic" VALUES(2033, 'Fexofenadine Hydrochloride', 'Fexofenadine Hydrochloride', 'R06AX26', 0, 0, 0, 0, 1, 1, 1, 0, '[]', '- **Renal Impairment:** Decreased elimination may occur; dosage adjustments are required for patients with decreased renal function.
INSERT INTO "drug_generic" VALUES(2034, 'Phospholipids', 'Poractant alfa / Beractant / Calfactant (Pulmonary Surfactant)', 'R07AA02', 0, 1, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Administration Risk", "severity": "High", "trigger_condition": "During intratracheal instillation", "message": "STOP: Administration can rapidly affect oxygenation and lung compliance. Transient bradycardia and oxygen desaturation may occur. Must be administered only by trained personnel in a highly supervised clinical setting with immediate availability of intubation and ventilatory support."}]', 'For intratracheal use only. Continuous monitoring of oxygenation (via pulse oximetry or transcutaneous monitoring) and carbon dioxide levels is mandatory during and after administration. Rapid improvements in lung compliance and oxygenation may require immediate adjustments to ventilator settings (e.g., reducing peak inspiratory pressure and FiO2) to prevent hyperoxia and barotrauma. Monitor for endotracheal tube reflux or blockage during administration; if this occurs, halt administration and clear the airway. Caution in infants <600 g birth weight as clinical data may be limited.', '- **Respiratory Distress Syndrome (RDS) Prevention:** Prophylactic administration in premature infants (typically <1250 g birth weight) or those with evidence of surfactant deficiency, administered as soon as possible, preferably within 15 minutes of birth.
INSERT INTO "drug_generic" VALUES(2035, 'Dextrose 5% + Sodium Chloride 0.25%', 'Dextrose 5% and Sodium Chloride 0.25%', 'B05BB02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Fluid and Solute Overload", "severity": "Moderate", "trigger_condition": "Administration in patients with congestive heart failure or severe renal insufficiency", "message": "Caution: Can cause significant fluid overload, pulmonary edema, and electrolyte disturbances. Monitor fluid balance and electrolytes closely."}]', '**Fluid and Electrolyte Overload:** Administration can cause fluid and/or solute overload resulting in dilution of serum electrolyte concentrations, overhydration, congested states, or pulmonary edema. Use with caution in patients with congestive heart failure or severe renal insufficiency.
INSERT INTO "drug_generic" VALUES(2036, 'Diethylcarbamazine Citrate', 'Diethylcarbamazine Citrate', 'P02CB02', 1, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Mazzotti Reaction", "severity": "High", "trigger_condition": "Treatment of Onchocerciasis or heavy microfilarial loads", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (Mazzotti reaction) can occur due to the rapid death of microfilariae. Symptoms include severe rash, fever, tachycardia, hypotension, and ocular damage. Corticosteroid premedication may be required."}]', '**Mazzotti Reaction:** Rapid death of microfilariae (especially in onchocerciasis) can trigger a severe systemic inflammatory response characterized by fever, rash, pruritus, arthralgia, tachycardia, and postural hypotension. Ocular complications (e.g., optic neuritis, retinal hemorrhage) can lead to blindness. Concomitant administration of corticosteroids or antihistamines may be necessary to mitigate this reaction.
INSERT INTO "drug_generic" VALUES(2037, 'Bedaquiline', 'Bedaquiline fumarate', 'J04AK05', 1, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Increased Mortality and QT Prolongation", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "STOP: An increased risk of death was seen in the bedaquiline treatment group compared to placebo. QT prolongation can occur. Only use when an effective treatment regimen cannot otherwise be provided."}]', '**Increased Mortality:** An increased risk of death was observed in the bedaquiline treatment group (11.4%) compared to the placebo group (2.5%) in a placebo-controlled trial. Bedaquiline should only be used in patients 5 years of age and older when an effective treatment regimen cannot otherwise be provided.
INSERT INTO "drug_generic" VALUES(2038, 'Daclatasvir', 'Daclatasvir', 'J05AP07', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Hepatitis B Virus Reactivation", "severity": "High", "trigger_condition": "HCV/HBV coinfected patients initiating direct-acting antiviral therapy", "message": "STOP: Test all patients for evidence of current or prior HBV infection before initiating treatment. HBV reactivation, including fatal cases, has been reported during or after HCV treatment."}, {"alert_type": "Severe Bradycardia", "severity": "High", "trigger_condition": "Coadministration with Amiodarone and Sofosbuvir", "message": "STOP: Serious symptomatic bradycardia, requiring pacemaker intervention, may occur when amiodarone is coadministered with sofosbuvir and daclatasvir. Coadministration is not recommended."}]', '**HBV Reactivation:** Monitor HCV/HBV coinfected patients for clinical and laboratory signs of hepatitis flare or HBV reactivation during HCV treatment and post-treatment follow-up. Initiate appropriate patient management for HBV infection as clinically indicated.
INSERT INTO "drug_generic" VALUES(2039, 'Tenofovir Disoproxil Fumarate', 'Tenofovir Disoproxil Fumarate', 'J05AF07', 0, 0, 1, 0, 1, 1, 1, 1, '[{"alert_type": "Hepatitis B Exacerbation", "severity": "High", "trigger_condition": "Discontinuation of therapy in HBV-infected patients", "message": "STOP: Severe acute exacerbations of hepatitis B have been reported in patients who are co-infected with HBV and HIV-1 and have discontinued tenofovir. Hepatic function must be monitored closely for several months after stopping treatment."}]', '**Renal Impairment:** Tenofovir is principally eliminated by the kidney. Renal impairment, including cases of acute renal failure and Fanconi syndrome, has been reported. Assess creatinine clearance, urine glucose, and urine protein prior to initiation and periodically during therapy.
INSERT INTO "drug_generic" VALUES(2040, 'Propylthiouracil', 'Propylthiouracil', 'H03BA02', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Hepatotoxicity", "severity": "High", "trigger_condition": "Initiation of therapy or ongoing treatment", "message": "STOP: Severe liver injury and acute liver failure, sometimes fatal, have been reported. Reserve use for patients who cannot tolerate methimazole. Monitor liver function tests closely."}, {"alert_type": "Agranulocytosis", "severity": "High", "trigger_condition": "Patient presenting with fever or sore throat", "message": "STOP: Agranulocytosis is a potentially fatal adverse reaction. Instruct patients to immediately report fever or sore throat. Discontinue drug and check CBC if suspected."}]', '**Hepatotoxicity:** Severe liver injury, including fatal acute liver failure, has been reported. Monitor LFTs and discontinue immediately if transaminases exceed 3 times the upper limit of normal or if clinical signs of liver injury occur.
INSERT INTO "drug_generic" VALUES(2041, 'Povidone Iodine 10% Topical', 'Povidone-Iodine Topical', 'D08AG02', 1, 0, 0, 0, 1, 1, 0, 0, '[]', 'Avoid application to large areas of broken skin or severe burns, as this may produce systemic adverse effects due to significant iodine absorption (e.g., metabolic acidosis, hypernatremia, renal impairment). Exercise special caution in patients with pre-existing renal insufficiency. Do not use under occlusive dressings unless directed by a physician.', '- **Surgical Antisepsis:** Used as an antiseptic skin cleanser for major and minor surgical procedures.
INSERT INTO "drug_generic" VALUES(2042, 'Prazosin', 'Prazosin', 'C02CA01', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "First-Dose Syncope", "severity": "High", "trigger_condition": "Initiation of therapy or rapid dose escalation", "message": "STOP: Prazosin can cause severe syncope with sudden loss of consciousness, particularly with the first dose or rapid dose increases. Initiate at the lowest dose and administer at bedtime."}]', '- **First-Dose Effect:** May cause marked hypotension and syncope. Initiate therapy with a low dose (0.5-1 mg) given at bedtime.
INSERT INTO "drug_generic" VALUES(2043, 'Zinc Orotate', 'Zinc Orotate', 'A12CB', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '- **Renal Impairment:** Patients with acute renal failure should use zinc products cautiously due to the risk of accumulation and toxicity.
INSERT INTO "drug_generic" VALUES(2044, 'Lenograstrim', 'Lenograstim', 'L03AA10', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Splenic Rupture and ARDS", "severity": "High", "trigger_condition": "Administration of G-CSF", "message": "STOP: Fatal splenic rupture can occur; evaluate patients reporting left upper abdominal or shoulder tip pain. Acute Respiratory Distress Syndrome (ARDS) has also been reported; evaluate patients who develop fever and lung infiltrates."}]', '- **Splenic Rupture:** Rare but potentially fatal splenic rupture has been reported. Monitor for left upper quadrant abdominal pain or shoulder tip pain.
INSERT INTO "drug_generic" VALUES(2045, 'Anidulafungin', 'Anidulafungin', 'J02AX06', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Infusion-Related Reactions", "severity": "High", "trigger_condition": "Rapid intravenous infusion", "message": "Risk of histamine-mediated infusion reactions, including rash, urticaria, flushing, pruritus, bronchospasm, dyspnea, and hypotension. Do not exceed an infusion rate of 1.1 mg/minute."}]', 'Monitor hepatic function during therapy. Abnormal liver tests, hepatitis, and hepatic failure have been reported. Discontinue if severe hepatic dysfunction occurs.
INSERT INTO "drug_generic" VALUES(2046, 'Eslicarbazepine', 'Eslicarbazepine Acetate', 'N03AF04', 0, 0, 0, 0, 1, 1, 1, 1, '[{"alert_type": "Suicidal Ideation and Hyponatremia", "severity": "High", "trigger_condition": "Initiation of therapy or dose adjustments", "message": "Monitor for emergence or worsening of depression, suicidal thoughts, or unusual changes in behavior. Monitor serum sodium levels, as clinically significant hyponatremia can occur."}]', '- **Suicidal Ideation:** Antiepileptic drugs increase the risk of suicidal thoughts or behavior. Monitor patients closely.
INSERT INTO "drug_generic" VALUES(2047, 'Azithromycin', 'Azithromycin', 'J01FA10', 1, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "QT Prolongation and Cardiovascular Death", "severity": "High", "trigger_condition": "Patients with known QT prolongation, hypokalemia, or taking antiarrhythmics", "message": "STOP: Azithromycin can prolong the QT interval, leading to fatal Torsades de Pointes. Avoid in patients with known QT prolongation, uncorrected hypokalemia/hypomagnesemia, or those taking Class IA/III antiarrhythmics."}, {"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Development of jaundice or elevated liver enzymes", "message": "STOP: Severe, and sometimes fatal, hepatotoxicity has been reported. Discontinue immediately if signs and symptoms of hepatitis occur."}]', '**Severe Cutaneous Adverse Reactions (SCAR):** Stevens-Johnson syndrome (SJS), toxic epidermal necrolysis (TEN), DRESS, and AGEP have been reported. Discontinue immediately if a progressive skin rash occurs.
INSERT INTO "drug_generic" VALUES(2048, 'Erdafitinib', 'Erdafitinib', 'L01EN01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Ocular Toxicity", "severity": "High", "trigger_condition": "Visual symptoms or routine monitoring", "message": "STOP: Can cause central serous retinopathy/retinal pigment epithelial detachment (CSR/RPED). Perform monthly ophthalmological exams for the first 4 months. Withhold drug if visual field defects occur."}]', '**Ocular Disorders:** Can cause central serous retinopathy/retinal pigment epithelial detachment (CSR/RPED), resulting in visual-field defects. Perform monthly ophthalmological examinations during the first 4 months of treatment, then every 3 months. Provide dry eye prophylaxis with ocular demulcents.
INSERT INTO "drug_generic" VALUES(2049, 'Vitamin B Complex + Vitamin C + Fat Emulsion', 'Intravenous Fat Emulsion with Multivitamins', 'B05BA10', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Hypersensitivity and Fat Overload", "severity": "High", "trigger_condition": "Allergy to soy/egg/peanut or rapid infusion", "message": "STOP: Contains soya oil and egg lecithin; cross-allergy with peanuts is possible. Rapid infusion or use in severe fat metabolism disorders can cause fatal Fat Overload Syndrome."}]', '**Allergic Reactions:** Contains soya oil and egg lecithin, which may rarely cause severe allergic reactions. Cross-reactivity between soybeans and peanuts has been observed.
INSERT INTO "drug_generic" VALUES(2050, 'Carboplatin', 'Carboplatin', 'L01XA02', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Bone Marrow Suppression", "severity": "High", "trigger_condition": "Dose-dependent, exacerbated by renal impairment", "message": "STOP: Severe bone marrow suppression (leukopenia, neutropenia, thrombocytopenia, anemia) can occur, leading to fatal infection or bleeding. Monitor peripheral blood counts frequently. Adjust dose in renal impairment."}, {"alert_type": "Anaphylactic Reactions", "severity": "High", "trigger_condition": "Previous exposure to platinum-containing compounds", "message": "STOP: Severe allergic reactions, including anaphylaxis, can occur within minutes of administration. Have epinephrine, corticosteroids, and antihistamines readily available."}]', '**Emetogenic Potential:** Vomiting is frequent and dose-related. Premedication with antiemetics (e.g., 5-HT3 antagonists, corticosteroids) is strongly recommended.
INSERT INTO "drug_generic" VALUES(2051, 'Calcium Chloride + Magnessium Chloride + Potassium chloride + Sodium chloride + Sodium acetate + Sodium citrate', 'Balanced Salt Solution (BSS)', 'S01ZA', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Administration Route Safety", "severity": "High", "trigger_condition": "Improper route of administration", "message": "STOP: This solution is for OCULAR IRRIGATION ONLY. It is NOT for intravenous injection or infusion."}]', '**Ocular Surgery Risks:** Use with caution in diabetic patients undergoing vitrectomy, as intraoperative lens changes have been observed. There have been reports of corneal clouding and edema following ocular surgery in which irrigating solutions were used.
INSERT INTO "drug_generic" VALUES(2052, 'Lactic acid 5% + Sodium PCA 2.5% Topical', 'Lactic acid and Sodium PCA', 'D02AX', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Photosensitivity:** Some formulations may contain ingredients (e.g., preservatives, fragrances, or alpha-hydroxy acids like lactic acid) that increase skin sensitivity to the sun. Patients should be advised to use sunscreen, wear protective clothing, and avoid prolonged sun exposure or tanning beds.
INSERT INTO "drug_generic" VALUES(2053, 'Nizatidine', 'Nizatidine', 'A02BA04', 0, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Masking of Gastric Malignancy", "severity": "High", "trigger_condition": "Initiation of therapy in patients with undiagnosed dyspepsia or gastric ulcers", "message": "STOP: Symptomatic response to nizatidine therapy does not preclude the presence of gastric malignancy. Exclude malignancy prior to initiating treatment for gastric ulcers."}]', 'Use with caution in patients with renal impairment; dosage adjustments are required based on creatinine clearance. There is an increased risk of developing community-acquired pneumonia in patients taking acid-suppressing medications. May cause dizziness or fatigue; patients should be cautioned about driving or operating heavy machinery until they know how the drug affects them. False-positive tests for urobilinogen may occur during therapy.', '- **Duodenal Ulcer:** Treatment of active duodenal ulcer and maintenance therapy for healed duodenal ulcers at a reduced dose.
INSERT INTO "drug_generic" VALUES(2054, 'Human Papillomavirus Quadrivalent (Types 6, 11, 16, and 18) Vaccine, Recombinant', 'Human Papillomavirus Quadrivalent (Types 6, 11, 16, and 18) Vaccine, Recombinant', 'J07BM01', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Syncope Risk", "severity": "High", "trigger_condition": "Post-vaccination period", "message": "STOP: Syncope (fainting), sometimes associated with tonic-clonic movements, can occur. Observe patients for 15 minutes after administration in a seated or supine position."}]', '**Syncope:** Vaccinees may develop syncope, sometimes resulting in falling with injury. Observation for 15 minutes after administration is strongly recommended. Syncope may be accompanied by transient tonic-clonic movements, which typically respond to restoring cerebral perfusion (supine or Trendelenburg position).
INSERT INTO "drug_generic" VALUES(2055, 'Avobenzone 2% + Oxybenzone 3% + Padimate O 8% + Titanium dioxide', 'Avobenzone, Oxybenzone, Padimate O, and Titanium Dioxide', 'D02BA', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Low", "message": "For external use only. Avoid contact with the eyes and mucous membranes. Do not apply to broken or severely irritated skin."}]', '**Skin Irritation:** May cause local skin irritation, erythema, or contact dermatitis in sensitive individuals. Discontinue use if a severe rash or irritation develops.
INSERT INTO "drug_generic" VALUES(2056, 'Japanese encephalitis vaccine (inactivated, adsorbed)', 'Japanese Encephalitis Vaccine, Inactivated, Adsorbed', 'J07BA02', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of severe allergic reaction to previous dose or components", "message": "STOP: Severe allergic reactions (e.g., anaphylaxis) can occur. Contraindicated in patients with a history of severe allergic reaction to a previous dose, another Japanese encephalitis virus vaccine, or any component, including protamine sulfate. Ensure epinephrine and emergency equipment are available."}]', '**Allergic Reactions:** Contains protamine sulfate, which is potentially allergenic. Appropriate medical treatment and supervision must be available to manage possible anaphylactic reactions following administration.
INSERT INTO "drug_generic" VALUES(2057, 'Lenalidomide', 'Lenalidomide', 'L04AX04', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Teratogenicity", "severity": "High", "trigger_condition": "Pregnancy or potential for pregnancy", "message": "STOP: Lenalidomide is a thalidomide analogue and a known human teratogen. It causes severe, life-threatening birth defects or embryo-fetal death. Strict adherence to a risk evaluation and mitigation strategy (REMS) program is mandatory."}, {"alert_type": "Thromboembolism Risk", "severity": "High", "trigger_condition": "Concomitant use with dexamethasone or erythropoietic agents", "message": "WARNING: Significantly increased risk of deep vein thrombosis (DVT), pulmonary embolism (PE), myocardial infarction, and stroke, especially in multiple myeloma patients receiving combination therapy."}]', '**Embryo-Fetal Toxicity:** Lenalidomide is an analogue of thalidomide, a known human teratogen. It can cause severe, life-threatening human birth defects or embryo-fetal death. A negative pregnancy test is required prior to initiation, and strict contraceptive measures must be maintained. Therapy is restricted via a specialized distribution program.
INSERT INTO "drug_generic" VALUES(2058, 'Salmon Calcitonin', 'Calcitonin Salmon', 'H05BA01', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "First dose administration", "message": "STOP: Serious hypersensitivity reactions, including fatal anaphylaxis, have been reported. Consider skin testing prior to treatment, especially in patients with suspected sensitivity."}]', '- **Hypocalcemia:** Hypocalcemia associated with tetany has been reported. Ensure adequate intake of calcium and vitamin D, and have parenteral calcium available during the first several doses.
INSERT INTO "drug_generic" VALUES(2059, 'Miglitol', 'Miglitol', 'A10BF02', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Hypoglycemia Management", "severity": "High", "trigger_condition": "Concurrent use with insulin or insulin secretagogues (e.g., sulfonylureas)", "message": "STOP: Miglitol delays the digestion of complex carbohydrates. If hypoglycemia occurs while taking miglitol in combination with insulin or a sulfonylurea, it MUST be treated with oral glucose (dextrose), NOT sucrose (table sugar), as the breakdown of sucrose will be inhibited."}]', 'Use with caution in patients exposed to physiological stress (e.g., fever, trauma, infection, surgery), as temporary loss of glycemic control may occur, necessitating temporary insulin therapy.
INSERT INTO "drug_generic" VALUES(2060, 'Moxifloxacin IV', 'Moxifloxacin', 'J01MA14', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Adverse Reactions", "severity": "High", "trigger_condition": "Patient experiencing tendon pain, neuropathy, or CNS symptoms", "message": "WARNING: Fluoroquinolones are associated with disabling and potentially irreversible serious adverse reactions, including tendinitis, tendon rupture, peripheral neuropathy, and CNS effects. Discontinue immediately if these occur."}]', '**Tendon Rupture:** Increased risk of tendinitis and tendon rupture, especially in patients >60 years, those taking corticosteroids, and kidney/heart/lung transplant recipients.
INSERT INTO "drug_generic" VALUES(2061, 'Inclisiran', 'Inclisiran', 'C10AX16', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "Moderate", "trigger_condition": "Post-administration", "message": "Hypersensitivity reactions have been reported. Instruct patients to seek medical attention promptly if signs or symptoms occur."}]', '**Hypersensitivity:** Reactions including rash, pruritus, and urticaria have occurred. Discontinue inclisiran if a severe hypersensitivity reaction occurs and treat appropriately.
INSERT INTO "drug_generic" VALUES(2062, 'Eravacycline', 'Eravacycline', 'J01AA13', 1, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of tetracycline hypersensitivity", "message": "STOP: Life-threatening hypersensitivity (anaphylaxis) has been reported. Avoid use in patients with a history of tetracycline allergy."}]', 'Life-threatening hypersensitivity (anaphylaxis) has been reported; avoid use in patients with a history of tetracycline allergy; discontinue if an allergic reaction occurs.
INSERT INTO "drug_generic" VALUES(2063, 'Pilocarpine Hydrochloride 4% Eye prep', 'Pilocarpine Hydrochloride', 'S01EB01', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '**Visual Disturbances:** May cause blurred vision and difficulty with dark adaptation; advise patients to exercise caution when driving at night or performing hazardous tasks in poor illumination.
INSERT INTO "drug_generic" VALUES(2064, 'Edaravone', 'Edaravone', 'N07XX14', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hypersensitivity Risk", "severity": "High", "trigger_condition": "Administration of intravenous infusion", "message": "STOP: Hypersensitivity reactions, including anaphylaxis, can occur. Monitor patients closely during and after the infusion. Discontinue immediately if signs of hypersensitivity develop."}]', 'Use with caution in patients with mild to moderate renal insufficiency; acute renal failure has been reported.
INSERT INTO "drug_generic" VALUES(2065, 'Enfortumab vedotin', 'Enfortumab vedotin-ejfv', 'L01FX13', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Skin Reactions", "severity": "High", "trigger_condition": "Development of severe rash, blistering, or peeling skin", "message": "STOP: Fatal and severe skin reactions, including Stevens-Johnson syndrome (SJS) and Toxic Epidermal Necrolysis (TEN), have occurred. Withhold or permanently discontinue based on severity."}, {"alert_type": "Hyperglycemia", "severity": "High", "trigger_condition": "Blood glucose >250 mg/dL", "message": "STOP: Fatal hyperglycemia and diabetic ketoacidosis (DKA) have occurred. Withhold dosing if blood glucose is elevated (>250 mg/dL) and treat appropriately."}]', '**Severe Skin Reactions:** Severe cutaneous adverse reactions, including fatal cases of Stevens-Johnson syndrome (SJS) and Toxic Epidermal Necrolysis (TEN), have occurred. Monitor closely for skin reactions. Withhold treatment for suspected severe reactions and permanently discontinue if SJS or TEN is confirmed.
INSERT INTO "drug_generic" VALUES(2066, 'Menotrophin 75 IU FSH + 75 IU LH', 'Menotropins', 'G03GA02', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Ovarian Hyperstimulation Syndrome (OHSS)", "severity": "High", "trigger_condition": "Rapid rise in serum estradiol or development of multiple large ovarian follicles", "message": "STOP: Severe and potentially fatal Ovarian Hyperstimulation Syndrome (OHSS) can occur. Withhold hCG administration if serum estradiol is excessively high or if ovaries are significantly enlarged. Monitor for severe pelvic pain, ascites, and respiratory distress."}]', 'Therapy should only be undertaken by physicians experienced in infertility management. Monitor ovarian response frequently using transvaginal ultrasound and serum estradiol levels to minimize the risk of OHSS and multiple gestations. If OHSS occurs, discontinue menotropins, withhold hCG, and provide aggressive supportive care for fluid shifts and thromboembolic risks. Use with caution in patients with a history of thromboembolic events. Exclude non-gonadal endocrinopathies (e.g., thyroid or adrenal dysfunction, hyperprolactinemia) and pituitary tumors before initiating therapy. Pelvic examinations should be performed gently to avoid rupture of enlarged ovarian cysts.', '- **Female Infertility:** Induction of ovulation and pregnancy in anovulatory infertile patients in whom the cause of infertility is functional and not due to primary ovarian failure.
INSERT INTO "drug_generic" VALUES(2067, 'Oxcarbazepine', 'Oxcarbazepine', 'N03AF02', 0, 0, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Severe Dermatologic Reactions", "severity": "High", "trigger_condition": "Presence of HLA-B*1502 allele", "message": "STOP: Serious and potentially fatal dermatologic reactions, including Stevens-Johnson syndrome (SJS) and toxic epidermal necrolysis (TEN), have been reported. Patients of Asian descent should be screened for the HLA-B*1502 allele prior to initiating therapy."}]', '**Hyponatremia:** Clinically significant hyponatremia (sodium <125 mmol/L) can occur. Monitor serum sodium levels, especially during the first 3 months of therapy or in patients with clinical symptoms of hyponatremia (nausea, malaise, headache, lethargy, confusion).
INSERT INTO "drug_generic" VALUES(2068, 'Saquinavir', 'Saquinavir', 'J05AE01', 0, 0, 1, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiac Arrhythmias", "severity": "High", "trigger_condition": "Pre-existing QT prolongation, AV block, or concomitant use of QT-prolonging drugs", "message": "STOP: Saquinavir/ritonavir can cause dose-dependent QT and PR interval prolongation. It is contraindicated in patients with congenital/acquired QT prolongation, complete AV block, or those taking other drugs that prolong the QT interval."}]', '**Cardiac Conduction Abnormalities:** Dose-dependent prolongations of QT and PR intervals have been observed. Use with extreme caution in patients with mild to moderate hepatic impairment, ischemic heart disease, or cardiomyopathy. Perform baseline and follow-up ECGs.
INSERT INTO "drug_generic" VALUES(2069, 'Lidocaine + Prilocaine topical', 'Lidocaine and Prilocaine', 'N01BB20', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Methemoglobinemia Risk", "severity": "High", "trigger_condition": "Use in infants <12 months receiving methemoglobin-inducing agents or patients with congenital methemoglobinemia", "message": "STOP: Co-administration with methemoglobin-inducing agents (e.g., sulfonamides, acetaminophen, nitrates) can cause life-threatening methemoglobinemia. Monitor for cyanosis and hypoxia."}]', 'Use with extreme caution in patients with severe hepatic impairment, as the amide local anesthetics are metabolized in the liver and toxic levels may accumulate.
INSERT INTO "drug_generic" VALUES(2070, 'Lincomycin', 'Lincomycin', 'J01FF02', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Colitis", "severity": "High", "trigger_condition": "Development of severe diarrhea during or after therapy", "message": "STOP: Lincomycin can cause severe and potentially fatal Clostridioides difficile-associated diarrhea (CDAD) and pseudomembranous colitis. Discontinue immediately if significant diarrhea occurs."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can range in severity from mild diarrhea to fatal colitis. Toxins produced by C. difficile cause pseudomembranous colitis. If CDAD is suspected or confirmed, discontinue lincomycin immediately and initiate appropriate fluid, electrolyte, and antibiotic therapy (e.g., oral vancomycin or fidaxomicin).
INSERT INTO "drug_generic" VALUES(2071, 'Moxetumomab Pasudotox', 'Moxetumomab Pasudotox', 'L01FB02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Capillary Leak Syndrome and Hemolytic Uremic Syndrome", "severity": "High", "trigger_condition": "Patients receiving moxetumomab pasudotox", "message": "STOP: Life-threatening Capillary Leak Syndrome (CLS) and Hemolytic Uremic Syndrome (HUS) have been reported. Monitor weight, blood pressure, and laboratory parameters closely. Ensure adequate hydration before and after infusion."}]', 'Capillary Leak Syndrome (CLS), including life-threatening cases, has been reported and is characterized by hypoalbuminemia, hypotension, symptoms of fluid overload, and hemoconcentration. Monitor weight and blood pressure closely.
INSERT INTO "drug_generic" VALUES(2072, 'Hydroxyzine Hydrochloride', 'Hydroxyzine', 'N05BB01', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Concomitant use with other QT-prolonging drugs or in patients with underlying cardiac disease", "message": "STOP: Hydroxyzine is associated with QT interval prolongation and Torsades de Pointes. Avoid use in patients with known QT prolongation, risk factors for QT prolongation, or those taking other arrhythmogenic medications."}]', 'Use with caution in patients with mild to moderate renal or hepatic impairment; dosage adjustments are required.
INSERT INTO "drug_generic" VALUES(2073, 'Levofloxacin 0.5% Eye prep', 'Levofloxacin Ophthalmic', 'S01AE05', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity", "severity": "High", "trigger_condition": "Patients with a history of hypersensitivity to fluoroquinolones", "message": "STOP: Contraindicated in patients with a history of hypersensitivity to levofloxacin or other quinolone antimicrobial agents. Discontinue immediately at the first sign of a rash or allergic reaction."}]', '**Superinfection:** Prolonged use may result in the overgrowth of nonsusceptible organisms, including fungi. If superinfection occurs, discontinue use and institute alternative therapy.
INSERT INTO "drug_generic" VALUES(2074, 'Omadacycline', 'Omadacycline', 'J01AA15', 1, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Mortality Imbalance in CABP", "severity": "High", "trigger_condition": "Use in patients with Community-Acquired Bacterial Pneumonia (CABP)", "message": "WARNING: A mortality imbalance was observed in CABP clinical trials (2% vs 1% with moxifloxacin). Closely monitor patients, especially those >65 years with multiple comorbidities."}]', '**Mortality Imbalance in CABP:** An unexplained mortality imbalance was observed in the CABP clinical trial (8 deaths [2%] in the omadacycline arm vs. 4 deaths [1%] in the moxifloxacin arm). All deaths occurred in patients >65 years old, mostly with multiple comorbidities. Use with caution in this population.
INSERT INTO "drug_generic" VALUES(2075, 'Meloxicam', 'Meloxicam', 'M01AC06', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "NSAIDs may cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke, which can be fatal. This risk may occur early in treatment and may increase with duration of use."}, {"alert_type": "Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use of NSAIDs", "message": "NSAIDs cause an increased risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation of the stomach or intestines, which can be fatal. These events can occur at any time during use and without warning symptoms."}]', 'Use with extreme caution in patients with a history of gastrointestinal disease (ulcers, bleeding), asthma, hypertension, cardiovascular disease, fluid retention, or heart failure. Monitor renal function closely in patients with advanced renal disease, dehydration, or those taking concomitant ACE inhibitors, ARBs, or diuretics. May impair the ability to drive or operate machinery due to potential dizziness or drowsiness. Use the lowest effective dose for the shortest duration possible to minimize cardiovascular and gastrointestinal risks. Avoid use in the third trimester of pregnancy due to the risk of premature closure of the fetal ductus arteriosus.', '- **Osteoarthritis:** Relief of signs and symptoms of osteoarthritis.
INSERT INTO "drug_generic" VALUES(2076, 'Darunavir', 'Darunavir ethanolate', 'J05AE10', 1, 0, 0, 0, 0, 0, 1, 0, '[]', '**Hepatotoxicity:** Drug-induced hepatitis (e.g., acute hepatitis, cytolytic hepatitis) has been reported. Post-marketing cases of liver injury, including fatalities, have occurred. Monitor liver function before and during therapy, especially in patients with underlying chronic hepatitis B or C, cirrhosis, or pre-treatment transaminase elevations.
INSERT INTO "drug_generic" VALUES(2077, 'Chlorpheniramine Maleate 0.5% + Dexamethasone 0.1% E/E drops', 'Chlorpheniramine and Dexamethasone Ophthalmic/Otic', 'S01CA01', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Ocular Toxicity", "severity": "High", "trigger_condition": "Prolonged use (>10 days)", "message": "STOP: Prolonged use of topical corticosteroids may increase intraocular pressure (IOP) leading to glaucoma and optic nerve damage. Must be used under strict medical supervision."}]', '**Intraocular Pressure (IOP) Elevation:** Prolonged use of ophthalmic corticosteroids may result in glaucoma, damage to the optic nerve, and defects in visual acuity and fields of vision. Monitor IOP if used for more than 10 days.
INSERT INTO "drug_generic" VALUES(2078, 'Rabies Vaccine (Human) BP', 'Rabies Vaccine', 'J07BG01', 0, 1, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Fatal Disease Warning", "severity": "High", "trigger_condition": "Post-exposure prophylaxis", "message": "STOP: Rabies is uniformly fatal once symptoms appear. There are NO absolute contraindications to post-exposure prophylaxis. Administer vaccine and Rabies Immune Globulin (RIG) immediately as indicated by wound category."}]', '**Immune Complex Reactions:** A serum sickness-like reaction (arthralgia, arthritis, nausea, malaise, angioedema, fever, vomiting) can occur 2-21 days after booster doses of cell culture rabies vaccines. Treat symptomatically.
INSERT INTO "drug_generic" VALUES(2079, 'Methyl Ergometrine Maleate', 'Methylergonovine', 'G02AB01', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Hypertension and Vasospasm", "severity": "High", "trigger_condition": "Intravenous administration or use in patients with pre-existing hypertension/preeclampsia", "message": "STOP: Intravenous administration can induce sudden hypertensive and cerebrovascular accidents. Administer IV only in life-threatening emergencies over at least 1 minute. Contraindicated in hypertension and toxemia."}]', '**Hypertensive Episodes:** Methylergonovine is a potent vasoconstrictor. Sudden hypertensive and cerebrovascular accidents have been reported. Monitor blood pressure closely. Avoid intravenous administration unless absolutely necessary as a life-saving measure.
INSERT INTO "drug_generic" VALUES(2080, 'Ivermectin topical', 'Ivermectin topical', 'D11AX22', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Accidental Ingestion Risk:** To prevent accidental ingestion, administer to children only under direct adult supervision. Ingestion can lead to systemic toxicity.
INSERT INTO "drug_generic" VALUES(2081, 'Gentamicin', 'Gentamicin', 'J01GB03', 1, 1, 0, 1, 1, 0, 1, 0, '[{"alert_type": "Nephrotoxicity and Ototoxicity", "severity": "High", "trigger_condition": "Prolonged use, high doses, or concurrent use with other nephrotoxic/ototoxic drugs", "message": "STOP: Gentamicin can cause severe, irreversible ototoxicity (vestibular and auditory) and nephrotoxicity. Monitor renal function and serum peak/trough levels closely. Avoid concurrent use with loop diuretics or other nephrotoxins."}]', 'Monitor renal function (serum creatinine, BUN, urine output) and auditory/vestibular function regularly during therapy.
INSERT INTO "drug_generic" VALUES(2082, 'Econazole Nitrate 1% + Triamcinolone Acetonide 0.1 Topical', 'Econazole and Triamcinolone', 'D01AC20', 0, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Adrenal Suppression", "severity": "Moderate", "trigger_condition": "Prolonged use, application to large surface areas, or use under occlusion (especially in children)", "message": "Caution: Contains a topical corticosteroid. Prolonged use or application under occlusive dressings (including infant diapers) can cause systemic absorption leading to reversible HPA axis suppression, Cushing''s syndrome, and skin atrophy."}]', '**Systemic Absorption of Corticosteroids:** Systemic absorption of topical corticosteroids can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, manifestations of Cushing''s syndrome, hyperglycemia, and glucosuria. Avoid prolonged use, application to large areas, and occlusive dressings.
INSERT INTO "drug_generic" VALUES(2083, 'Ixekizumab', 'Ixekizumab', 'L04AC13', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Serious Infections", "severity": "High", "trigger_condition": "Presence of active infection or latent tuberculosis", "message": "STOP: Ixekizumab may increase the risk of infections. Do not initiate treatment in patients with any clinically important active infection until the infection resolves or is adequately treated. Evaluate for tuberculosis prior to initiating treatment."}]', '**Infection Risk:** Increases the rate of infections, including upper respiratory tract infections, oral candidiasis, conjunctivitis, and tinea infections. Do not administer to patients with a clinically important active infection. If a serious infection develops, discontinue treatment until the infection resolves.
INSERT INTO "drug_generic" VALUES(2084, 'Microfine zinc oxide 15%', 'Zinc oxide topical', 'D02AB', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Ingestion Risk", "severity": "Moderate", "trigger_condition": "Accidental oral ingestion", "message": "WARNING: Harmful if swallowed. Keep out of reach of children. If ingested, seek immediate medical attention or contact a Poison Control Center."}]', '**Ocular Exposure:** Avoid contact with the eyes. If contact occurs, rinse thoroughly with water to prevent mechanical irritation.
INSERT INTO "drug_generic" VALUES(2085, 'Benzathine Penicillin G (Benzathine Benzylpenicillin)', 'Penicillin G Benzathine', 'J01CE08', 1, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Intravenous Administration Fatalities", "severity": "High", "trigger_condition": "Inadvertent IV administration", "message": "STOP: DO NOT ADMINISTER INTRAVENOUSLY. Inadvertent IV administration has caused cardiorespiratory arrest and death. Administer by deep intramuscular (IM) injection ONLY."}, {"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "Patient history of Penicillin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}]', '**Injection Site Reactions:** Do not inject near an artery or nerve, as this may result in severe neurovascular damage, permanent paralysis, or gangrene. Quadriceps femoris fibrosis and atrophy have been reported following repeated IM injections into the anterolateral thigh.
INSERT INTO "drug_generic" VALUES(2086, 'Hydrocortisone + Benzyl Benzoate + Bismuth Subgallate + Bismuth Oxide + Balsam Peru + Zinc Oxide rectal', 'Hydrocortisone, Benzyl Benzoate, Bismuth Subgallate, Bismuth Oxide, Balsam Peru, and Zinc Oxide', 'C05AX03', 0, 0, 0, 0, 0, 0, 0, 0, '[]', '**Systemic Corticosteroid Effects:** Prolonged or excessive use may produce systemic corticosteroid effects, including adrenal suppression. Use for periods longer than seven days is not recommended.
INSERT INTO "drug_generic" VALUES(2087, 'Bevacizumab', 'Bevacizumab', 'L01FG01', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Gastrointestinal Perforation and Hemorrhage", "severity": "High", "trigger_condition": "Patients with recent surgery, hemoptysis, or abdominal pain", "message": "STOP: Severe and fatal GI perforations, fistulas, and hemorrhages (including hemoptysis) can occur. Do NOT administer within 28 days of major surgery or if the surgical wound is unhealed."}]', '- **Surgery and Wound Healing:** Withhold for at least 28 days prior to elective surgery. Do not administer for at least 28 days following major surgery and until the wound is fully healed. Discontinue if necrotizing fasciitis or severe wound healing complications occur.
INSERT INTO "drug_generic" VALUES(2088, 'Doripenem', 'Doripenem', 'J01DH04', 1, 0, 1, 0, 1, 1, 0, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "Patient history of hypersensitivity to carbapenems, penicillins, or cephalosporins", "message": "STOP: Serious and occasionally fatal hypersensitivity (anaphylactic) reactions have been reported. Cross-reactivity among beta-lactam antibiotics can occur. Verify allergy history before administration."}]', '**Seizure Risk:** Carbapenems have been associated with central nervous system adverse effects, including seizures. Use with caution in patients with CNS disorders or compromised renal function. Concurrent use with valproic acid significantly reduces valproic acid levels, increasing seizure risk.
INSERT INTO "drug_generic" VALUES(2089, 'Atazanavir', 'Atazanavir', 'J05AE08', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiac Conduction Abnormalities", "severity": "High", "trigger_condition": "Pre-existing conduction disorders or concomitant use of PR-prolonging drugs", "message": "WARNING: Atazanavir can prolong the PR interval, leading to asymptomatic first-degree AV block or, rarely, second- or third-degree AV block. Use with caution in patients with underlying structural heart disease or conduction abnormalities."}, {"alert_type": "Severe Drug Interactions", "severity": "High", "trigger_condition": "Concomitant use with CYP3A4 substrates or inducers", "message": "STOP: Coadministration with drugs highly dependent on CYP3A4 for clearance (e.g., simvastatin, lovastatin, ergot derivatives) is contraindicated due to life-threatening toxicities. Coadministration with strong CYP3A4 inducers (e.g., rifampin) is contraindicated due to loss of virologic response."}]', '**Cardiac Conduction Abnormalities:** Prolongation of the PR interval has been observed. Use with caution in patients with pre-existing conduction system disease (e.g., marked first-degree AV block or second- or third-degree AV block) or when coadministered with other drugs that prolong the PR interval.
INSERT INTO "drug_generic" VALUES(2090, 'Acarbose', 'Acarbose', 'A10BF01', 0, 0, 1, 0, 1, 0, 0, 0, '[{"alert_type": "Hypoglycemia Management", "severity": "High", "trigger_condition": "Patient experiencing hypoglycemia while on combination therapy with insulin or sulfonylureas", "message": "STOP: Acarbose prevents the breakdown of complex sugars. Hypoglycemia MUST be treated with oral DEXTROSE (glucose), NOT sucrose (table sugar or juice)."}]', '**Hypoglycemia:** Acarbose alone does not cause hypoglycemia. However, when used in combination with a sulfonylurea or insulin, the risk of hypoglycemia increases. Treat hypoglycemic episodes strictly with oral glucose (dextrose), as acarbose inhibits the breakdown of sucrose (table sugar).
INSERT INTO "drug_generic" VALUES(2091, 'Bromhexine Hydrochloride', 'Bromhexine', 'R05CB02', 0, 0, 0, 0, 1, 0, 1, 0, '[]', 'Since mucolytics may disrupt the gastric mucosal barrier, bromhexine should be used with caution in patients with a history of peptic ulcer disease.
INSERT INTO "drug_generic" VALUES(2092, 'Clindamycin Topical', 'Clindamycin Topical', 'D10AF01', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Severe Colitis", "severity": "High", "trigger_condition": "Development of severe diarrhea or abdominal cramps during therapy", "message": "Systemic absorption can occur with topical use. Discontinue immediately if significant diarrhea, bloody diarrhea, or severe abdominal cramps occur, as this may indicate Clostridioides difficile-associated diarrhea (CDAD) or pseudomembranous colitis."}]', '**Systemic Absorption:** Although applied topically, clindamycin can be absorbed systemically. Cases of severe diarrhea and pseudomembranous colitis have been reported. Discontinue use if significant diarrhea occurs.
INSERT INTO "drug_generic" VALUES(2093, 'Salicylic Acid 0.5% Topical', 'Salicylic Acid 0.5% Topical', 'D02AF', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'For external use only. Avoid contact with eyes, mouth, and other mucous membranes. If contact occurs, flush thoroughly with water. Discontinue use if excessive burning, stinging, or peeling occurs. Use with caution on large areas of the body or for prolonged periods due to the theoretical risk of systemic absorption (salicylism).', '- **Acne Vulgaris:** Treatment and prevention of acne blemishes, pimples, and blackheads.
INSERT INTO "drug_generic" VALUES(2094, 'Multivitamin and Multimineral A-Z Gold preparations', 'Multivitamins and Minerals', 'A11AA03', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Iron Toxicity", "severity": "High", "trigger_condition": "Accidental overdose in children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product out of reach of children."}]', '**Renal Impairment:** Use with caution in patients with mild to moderate renal failure. Accumulation of fat-soluble vitamins (A, D) and certain minerals can occur.
INSERT INTO "drug_generic" VALUES(2095, 'Duloxetine', 'Duloxetine', 'N06AX21', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Suicidal Thoughts and Behaviors", "severity": "High", "trigger_condition": "Initiation of therapy or dose changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '**Suicidality and Antidepressant Drugs:** Increased risk of suicidal thinking and behavior in children, adolescents, and young adults taking antidepressants. Monitor closely for clinical worsening and emergence of suicidal thoughts.
INSERT INTO "drug_generic" VALUES(2096, 'Ethosuximide', 'Ethosuximide', 'N03AD01', 0, 0, 0, 1, 1, 0, 1, 1, '[{"alert_type": "Severe Cutaneous Adverse Reactions", "severity": "High", "trigger_condition": "Development of rash, mucosal lesions, or systemic symptoms", "message": "STOP: Serious dermatologic reactions, including Stevens-Johnson syndrome (SJS) and Drug Reaction with Eosinophilia and Systemic Symptoms (DRESS), have been reported. Discontinue immediately at the first sign of a rash."}, {"alert_type": "Blood Dyscrasias", "severity": "High", "trigger_condition": "Unexplained fever, sore throat, or bleeding", "message": "STOP: Blood dyscrasias, including fatal cases of aplastic anemia and agranulocytosis, have been reported. Perform periodic complete blood counts."}]', '**Blood Dyscrasias:** Complete blood cell count should be performed periodically. Discontinue if significant bone marrow depression occurs.
INSERT INTO "drug_generic" VALUES(2097, 'Citalopram Hydrobromide', 'Citalopram', 'N06AB04', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Suicidal Thoughts and Behaviors", "severity": "High", "trigger_condition": "Initiation of therapy or dose changes, especially in children, adolescents, and young adults (<24 years)", "message": "Antidepressants increase the risk of suicidal thoughts and behaviors in pediatric and young adult patients. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}, {"alert_type": "QT Prolongation and Torsades de Pointes", "severity": "High", "trigger_condition": "Doses >40 mg/day, or use in patients with risk factors (e.g., hypokalemia, concurrent QT-prolonging drugs)", "message": "Dose-dependent QT prolongation and Torsades de Pointes have occurred. Do not exceed 40 mg/day. Avoid in patients with congenital long QT syndrome or uncompensated heart failure."}]', '**QT Prolongation:** Citalopram causes dose-dependent QTc prolongation. The maximum recommended dose is 40 mg/day. In patients >60 years of age, patients with hepatic impairment, or poor CYP2C19 metabolizers, the maximum dose is 20 mg/day. Correct hypokalemia and hypomagnesemia prior to initiation.
INSERT INTO "drug_generic" VALUES(2098, 'Tolmetin', 'Tolmetin', 'M01AB03', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Prolonged use, history of cardiovascular disease, or history of peptic ulcer disease", "message": "NSAIDs cause an increased risk of serious cardiovascular thrombotic events, myocardial infarction, and stroke. They also increase the risk of serious gastrointestinal adverse events including bleeding, ulceration, and perforation."}]', 'Use with caution in the elderly and in patients with impaired renal or hepatic function. Monitor renal function regularly, especially in patients with pre-existing renal disease or dehydration. Exercise caution in patients with cardiovascular diseases, fluid retention, heart failure, or hypertension, as NSAIDs can exacerbate these conditions. Monitor for signs of gastrointestinal bleeding, especially in patients with a history of gastric ulcers.', '- **Rheumatoid Arthritis:** Relief of signs and symptoms of rheumatoid arthritis.
INSERT INTO "drug_generic" VALUES(2099, 'Roflumilast', 'Roflumilast', 'R03DX07', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Psychiatric Events and Suicidality", "severity": "High", "trigger_condition": "Patients with a history of depression or suicidal ideation", "message": "STOP: Roflumilast is associated with an increase in psychiatric adverse reactions, including suicidality. Carefully weigh the risks and benefits in patients with a history of depression or suicidal thoughts. Discontinue if new or worsening psychiatric symptoms occur."}]', '**Not a Bronchodilator:** Roflumilast is not a bronchodilator and is not indicated for the relief of acute bronchospasm. Do not use for sudden attacks of breathlessness.
INSERT INTO "drug_generic" VALUES(2100, 'Amoxicillin + Omeprazole + Rifabutin', 'Amoxicillin, Omeprazole, and Rifabutin', 'A02BD14', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing."}, {"alert_type": "Severe Cutaneous Adverse Reactions (SCAR)", "severity": "High", "trigger_condition": "Development of severe rash, blistering, or mucosal lesions", "message": "STOP: Discontinue therapy immediately if signs of Stevens-Johnson Syndrome (SJS), Toxic Epidermal Necrolysis (TEN), or Drug Reaction with Eosinophilia and Systemic Symptoms (DRESS) appear."}]', '**Hypersensitivity Reactions:** Serious and occasionally fatal hypersensitivity reactions, including anaphylaxis, have been reported with the components of this combination. Discontinue therapy immediately and institute emergency management if a reaction occurs.
INSERT INTO "drug_generic" VALUES(2101, 'Fluphenazine Decanoate', 'Fluphenazine Decanoate', 'N05AB02', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Increased Mortality in Elderly Patients with Dementia-Related Psychosis", "severity": "High", "trigger_condition": "Use in elderly patients with dementia-related psychosis", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Fluphenazine is not approved for the treatment of patients with dementia-related psychosis."}, {"alert_type": "Neuroleptic Malignant Syndrome (NMS)", "severity": "High", "trigger_condition": "Patient presenting with hyperpyrexia, muscle rigidity, altered mental status, and autonomic instability", "message": "STOP: NMS is a potentially fatal symptom complex. Discontinue fluphenazine immediately and initiate intensive symptomatic treatment and medical monitoring."}]', '**Tardive Dyskinesia:** A syndrome of potentially irreversible, involuntary, dyskinetic movements may develop. The risk increases with duration of treatment and total cumulative dose. Consider discontinuation if signs appear.
INSERT INTO "drug_generic" VALUES(2102, 'Escitalopram', 'Escitalopram', 'N06AB10', 0, 0, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Suicidality Risk", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes, particularly in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', 'Monitor closely for clinical worsening, suicidality, or unusual changes in behavior, especially during the initial months of therapy or at times of dose changes. Use with caution in patients with a history of seizure disorders; discontinue if seizures occur. May cause hyponatremia, particularly in the elderly or those volume-depleted; monitor serum sodium if symptomatic. Caution is advised in patients with severe renal impairment (CrCl <20 mL/min) or hepatic impairment, requiring dose adjustments. May impair cognitive and motor performance; caution patients about operating hazardous machinery. Gradual tapering is required upon discontinuation to avoid withdrawal symptoms (e.g., dysphoria, irritability, agitation, dizziness, sensory disturbances). Use with caution in patients with a history of mania or hypomania. May increase the risk of bleeding events, especially when used concomitantly with NSAIDs, aspirin, or other drugs affecting coagulation.', '- **Major Depressive Disorder (MDD):** Acute and maintenance treatment of major depressive episodes.
INSERT INTO "drug_generic" VALUES(2103, 'Alpha Lipoic Acid', 'Alpha Lipoic Acid', 'A16AX01', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Hypoglycemia Risk", "severity": "Moderate", "trigger_condition": "Concomitant use with antidiabetic agents", "message": "Alpha lipoic acid increases glucose utilization and may precipitate hypoglycemia in patients taking insulin or oral antidiabetic drugs. Monitor blood glucose closely."}]', '- **Hypoglycemia:** Alpha lipoic acid may decrease blood glucose concentrations by improving insulin sensitivity. Patients with diabetes mellitus should use ALA with caution and monitor their blood glucose concentrations frequently.
INSERT INTO "drug_generic" VALUES(2104, 'Human Milk Based Amino Acid', 'Amino Acids, Parenteral', 'B05BA01', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Hyperphenylalaninemia Risk", "severity": "High", "trigger_condition": "Administration to severely ill or premature infants", "message": "STOP: Hyperphenylalaninemia can occur in severely ill, premature infants. Monitor phenylalanine levels closely and adjust the infusion rate as needed."}]', '**Hyperphenylalaninemia:** Has been noted in severely ill, premature infants. Continuous monitoring of phenylalanine levels is recommended, and the infusion rate must be adjusted accordingly.
INSERT INTO "drug_generic" VALUES(2105, 'Light Liquid Paraffin + White Soft Paraffin topical', 'Mineral Oil and White Petrolatum', 'D02AC', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Ocular Exposure:** Avoid contact with the eyes. If contact occurs, rinse thoroughly with water.
INSERT INTO "drug_generic" VALUES(2106, 'Riluzole', 'Riluzole', 'N07XX02', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated baseline transaminases or signs of hepatic injury", "message": "STOP: Riluzole can cause severe hepatotoxicity. Monitor serum aminotransferases before and during therapy. Discontinue if ALT levels increase to 5 times the upper limit of normal."}]', '**Hepatic Injury:** Cases of severe drug-induced liver injury, including fatal hepatitis, have been reported. Monitor serum aminotransferases (e.g., ALT, AST) before and during therapy. Discontinue riluzole if ALT levels exceed 5 times the upper limit of normal (ULN) or if clinical signs of hepatic injury occur.
INSERT INTO "drug_generic" VALUES(2107, 'Flavoxate Hydrochloride', 'Flavoxate Hydrochloride', 'G04BD02', 0, 0, 1, 0, 1, 0, 0, 0, '[]', '- **CNS Effects:** May cause drowsiness, vertigo, and blurred vision. Patients should be cautioned regarding driving or operating heavy machinery.
INSERT INTO "drug_generic" VALUES(2108, 'Beclomethasone + Neomycin + Miconazole Topical', 'Beclomethasone, Neomycin, and Miconazole Topical', 'D07CC04', 1, 0, 0, 0, 0, 0, 0, 1, '[]', '**Systemic Absorption:** Application to large surface areas, broken skin, or under occlusive dressings can lead to systemic absorption of beclomethasone (HPA axis suppression) and neomycin (ototoxicity/nephrotoxicity).
INSERT INTO "drug_generic" VALUES(2109, 'Leucovorin', 'Leucovorin', 'V03AF03', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Fluorouracil Toxicity Enhancement", "severity": "High", "trigger_condition": "Co-administration with 5-Fluorouracil", "message": "STOP: Leucovorin enhances the toxicity of 5-fluorouracil. Monitor closely for severe gastrointestinal toxicity (stomatitis, diarrhea) and myelosuppression. Dosage adjustments of 5-FU may be required."}]', '**Undiagnosed Anemia:** Risk of severe neurological complications if used in patients with undiagnosed pernicious anemia or other vitamin B12 deficiency anemias. Leucovorin may produce a hematologic remission while neurologic manifestations continue to progress.
INSERT INTO "drug_generic" VALUES(2110, 'Sodium Chloride + Potassium Chloride + Calcium chloride + Magnesium Chloride + Sodium Acetate + Sodium Citrate + Sodium Hydroxide + Hydrochloric Acid (Balanced Salt Solution)', 'Balanced Salt Solution (BSS)', 'S01XA07', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Administration Error", "severity": "High", "trigger_condition": "Intravenous administration", "message": "STOP: This solution is for intraocular or topical surgical irrigation ONLY. It is NOT for intravenous injection or infusion."}]', '- **Corneal Endothelium:** Use with caution in patients with abnormal corneal endothelium, as irrigation or trauma may result in bullous keratopathy or corneal decompensation.
INSERT INTO "drug_generic" VALUES(2111, 'Pilocarpine Hydrochloride 2 % Eye prep', 'Pilocarpine Hydrochloride', 'S01EB01', 0, 0, 0, 0, 0, 1, 0, 0, '[]', '**Visual Disturbances:** May cause blurred vision and difficulty with dark adaptation; advise patients to exercise caution when driving at night or performing hazardous tasks in poor illumination.
INSERT INTO "drug_generic" VALUES(2112, 'Terfenadine', 'Terfenadine', 'R06AX12', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fatal Arrhythmias", "severity": "High", "trigger_condition": "Concomitant use with CYP3A4 inhibitors or in patients with hepatic impairment", "message": "STOP: Terfenadine can cause severe, potentially fatal ventricular arrhythmias, including Torsades de Pointes. It is strictly contraindicated with macrolide antibiotics, azole antifungals, and in patients with hepatic disease or pre-existing QT prolongation."}]', '**QT Prolongation:** High risk of QT interval prolongation leading to fatal ventricular arrhythmias (Torsades de Pointes). Avoid in patients with a history of prolonged QT interval, congenital long QT syndrome, or significant cardiac disease.
INSERT INTO "drug_generic" VALUES(2113, 'Diltiazem Hydrochloride', 'Diltiazem Hydrochloride', 'C08DB01', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Cardiac Conduction Abnormalities", "severity": "High", "trigger_condition": "Concomitant use with beta-blockers or underlying AV block", "message": "STOP: Diltiazem slows AV nodal conduction. Co-administration with beta-blockers or use in patients with pre-existing sick sinus syndrome or 2nd/3rd-degree AV block can cause severe bradycardia, heart block, or asystole."}]', '**Cardiac Conduction:** May cause abnormally slow heart rates or 2nd/3rd-degree AV block. Risk is increased in patients with sick sinus syndrome or those taking concomitant beta-blockers or digitalis.
INSERT INTO "drug_generic" VALUES(2114, 'Fluoxetine', 'Fluoxetine', 'N06AB03', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Suicidality Risk", "severity": "High", "trigger_condition": "Initiation of therapy or dose changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '- **Clinical Worsening and Suicide Risk:** Monitor closely for clinical worsening, suicidality, and unusual changes in behavior, especially during the first few months of therapy or at times of dose changes.
INSERT INTO "drug_generic" VALUES(2115, 'Dapoxetine', 'Dapoxetine', 'G04BX14', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Syncope and Orthostatic Hypotension", "severity": "High", "trigger_condition": "First dose or standing up quickly after dosing", "message": "STOP: Syncope, characterized by loss of consciousness, and orthostatic hypotension can occur. Advise patients to maintain adequate hydration and to sit or lie down if prodromal symptoms (nausea, dizziness, sweating) occur."}]', '**Syncope and Orthostatic Hypotension:** An orthostatic test should be performed before initiating therapy. Avoid in patients with a history of orthostatic reactions. Prodromal symptoms (nausea, dizziness, diaphoresis) often precede syncope.
INSERT INTO "drug_generic" VALUES(2116, 'Loteprednol + Gatifloxacin eye prep', 'Loteprednol Etabonate and Gatifloxacin', 'S01CA03', 1, 0, 0, 0, 0, 1, 0, 1, '[]', 'Prolonged use of ophthalmic corticosteroids may result in glaucoma with damage to the optic nerve, defects in visual acuity, and posterior subcapsular cataract formation. Intraocular pressure (IOP) should be monitored routinely if used for 10 days or longer. Fungal infections of the cornea are particularly prone to develop coincidentally with long-term local steroid application. Use with caution in patients with known bleeding tendencies. Patients should not wear contact lenses if they have signs and symptoms of bacterial conjunctivitis.', '- **Post-operative Ocular Inflammation and Infection:** Indicated for the treatment of post-operative inflammatory conditions of the eye where there is a concurrent risk of superficial bacterial ocular infection caused by gatifloxacin-susceptible strains.', '- **Viral Diseases of the Cornea/Conjunctiva:** Contraindicated in epithelial herpes simplex keratitis (dendritic keratitis), vaccinia, and varicella due to the risk of severe exacerbation by corticosteroids.
INSERT INTO "drug_generic" VALUES(2117, 'Fluorometholone 0.1% + Tetrahydrozoline Hydrochloride 0.025% Eye prep', 'Fluorometholone and Tetrahydrozoline', 'S01CB05', 0, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Ocular Toxicity", "severity": "High", "trigger_condition": "Prolonged use", "message": "STOP: Prolonged use of corticosteroids may result in glaucoma, damage to the optic nerve, defects in visual acuity, and posterior subcapsular cataract formation."}]', '- **Intraocular Pressure (IOP):** Prolonged use may result in elevated IOP and/or glaucoma. Monitor IOP frequently if used for 10 days or longer.
INSERT INTO "drug_generic" VALUES(2118, 'Pomalidomide', 'Pomalidomide', 'L04AX06', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Prescribing to females of reproductive potential", "message": "STOP: Pomalidomide is a thalidomide analogue and causes severe, life-threatening human birth defects. It is only available through a restricted distribution program (REMS). Strict contraception and pregnancy testing are mandatory."}, {"alert_type": "Venous and Arterial Thromboembolism", "severity": "High", "trigger_condition": "During therapy", "message": "Deep vein thrombosis (DVT), pulmonary embolism (PE), myocardial infarction, and stroke occur in patients treated with pomalidomide. Prophylactic antithrombotic measures are recommended."}]', '**Hematologic Toxicity:** Neutropenia is the most frequently reported Grade 3/4 adverse event. Monitor CBC weekly for the first 8 weeks and monthly thereafter. Withhold or reduce dose for severe neutropenia or thrombocytopenia.
INSERT INTO "drug_generic" VALUES(2119, 'Hydrocortisone  + Lidocaine rectal prep', 'Hydrocortisone and Lidocaine Rectal', 'C05AA01', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Systemic Absorption", "severity": "Moderate", "trigger_condition": "Prolonged use or application to extensive/damaged areas", "message": "STOP: Systemic absorption of topical corticosteroids and local anesthetics can occur. Monitor for hypothalamic-pituitary-adrenal (HPA) axis suppression and lidocaine toxicity, especially with prolonged use."}]', '**Systemic Steroid Effects:** If extensive areas are treated or if used for prolonged periods, systemic absorption of hydrocortisone can produce reversible HPA axis suppression, manifestations of Cushing''s syndrome, hyperglycemia, and glycosuria.
INSERT INTO "drug_generic" VALUES(2120, 'COVID-19 viral vector vaccine (Janssen)', 'COVID-19 Vaccine, Adjuvanted (Janssen)', 'J07BN02', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Thrombosis with Thrombocytopenia Syndrome (TTS)", "severity": "High", "trigger_condition": "Post-vaccination presentation of severe headache, abdominal pain, leg pain, or shortness of breath", "message": "STOP: Rare but potentially fatal thrombosis with thrombocytopenia syndrome (TTS) has occurred, primarily in females aged 18-49. Do NOT use heparin if TTS is suspected; use alternative anticoagulants."}]', '**Thrombosis with Thrombocytopenia Syndrome (TTS):** Cases of severe thrombosis (including cerebral venous sinus thrombosis) accompanied by thrombocytopenia have been reported following administration. The highest risk is in females aged 18 through 49 years. Clinical presentation typically occurs 1 to 2 weeks post-vaccination.
INSERT INTO "drug_generic" VALUES(2121, 'Dacarbazine', 'Dacarbazine', 'L01AX04', 0, 1, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Myelosuppression and Hepatotoxicity", "severity": "High", "trigger_condition": "Initiation of therapy or pre-existing hepatic/hematologic impairment", "message": "STOP: Severe hematopoietic depression and potentially fatal hepatocellular necrosis can occur. Administer strictly under the supervision of an experienced oncologist."}]', '**Hematopoietic Depression:** Severe bone marrow suppression is the most common toxicity; monitor complete blood counts (CBC) closely and suspend therapy if severe depression occurs.
INSERT INTO "drug_generic" VALUES(2122, 'Beclomethasone + Salicyclic Acid Topical', 'Beclomethasone and Salicylic Acid Topical', 'D07XC04', 0, 0, 0, 0, 0, 0, 0, 1, '[]', '**Systemic Absorption:** Absorption of the corticosteroid and salicylic acid through the skin is significantly increased when used with occlusive dressings, applied to large areas, or used for prolonged periods. This can lead to HPA axis suppression and salicylism.
INSERT INTO "drug_generic" VALUES(2123, 'Atorvastatin + Ezetimibe', 'Atorvastatin and Ezetimibe', 'C10BA05', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Concomitant use with CYP3A4 inhibitors, fibrates, or in patients with renal impairment", "message": "STOP: Increased risk of severe myopathy and rhabdomyolysis leading to acute renal failure. Discontinue immediately if markedly elevated CPK levels occur or if myopathy is diagnosed or suspected."}]', '**Skeletal Muscle Effects:** Rare cases of rhabdomyolysis with acute renal failure secondary to myoglobinuria have been reported. The risk of myopathy and rhabdomyolysis increases with higher doses and concomitant use of CYP3A4 inhibitors, fibric acid derivatives, and cyclosporine. Predisposing factors include advanced age (>65 years), uncontrolled hypothyroidism, and renal impairment. Discontinue therapy immediately if myopathy is diagnosed or suspected.
INSERT INTO "drug_generic" VALUES(2124, 'Tobramycin Eye prep', 'Tobramycin Ophthalmic', 'S01AA12', 1, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Hypersensitivity and Superinfection", "severity": "Moderate", "trigger_condition": "Prolonged use or known aminoglycoside allergy", "message": "Monitor for signs of localized hypersensitivity. Prolonged use may result in overgrowth of nonsusceptible organisms, including fungi."}]', 'Prolonged use may result in the overgrowth of nonsusceptible organisms, including fungi. If superinfection occurs, initiate appropriate therapy. Cross-sensitivity to other aminoglycoside antibiotics may occur; if hypersensitivity develops, discontinue use immediately. Contact lens wear is not recommended during the treatment of an ocular infection. May cause temporary blurred vision; advise patients not to drive or operate machinery until vision clears.', '- **Ocular Bacterial Infections:** Treatment of superficial ophthalmic infections caused by susceptible bacteria, including conjunctivitis, keratitis, and blepharitis.', '- **Viral and Fungal Eye Infections:** Contraindicated in epithelial herpes simplex keratitis (dendritic keratitis), vaccinia, varicella, mycobacterial infections, and fungal diseases of the eye, as antibacterial agents are ineffective and may exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(2125, 'Gemifloxacin', 'Gemifloxacin', 'J01MA15', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Tendon Rupture and CNS Effects", "severity": "High", "trigger_condition": "Use in elderly, concurrent corticosteroid use, or history of CNS disorders", "message": "STOP: Fluoroquinolones are associated with disabling and potentially irreversible serious adverse reactions, including tendinitis, tendon rupture, peripheral neuropathy, and CNS effects. Discontinue immediately if these occur."}]', 'Use with caution in patients with known or suspected CNS disorders (e.g., severe cerebral arteriosclerosis, epilepsy) or other risk factors predisposing to seizures.
INSERT INTO "drug_generic" VALUES(2126, 'Malic Acid + Benzoic acid + Salicylic acid', 'Malic Acid, Benzoic Acid, and Salicylic Acid', 'D02AF', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Moderate", "trigger_condition": "Application to large areas or mucous membranes", "message": "Do not apply over large areas of the body, especially in patients with impaired kidney function, due to the risk of systemic salicylate toxicity. Avoid contact with eyes and mucous membranes."}]', '**Renal Impairment:** If you have impaired kidney function, you should not use this ointment over a large area of your body or for long periods due to the risk of systemic absorption of salicylic acid.
INSERT INTO "drug_generic" VALUES(2127, 'Ambrisentan', 'Ambrisentan', 'C02KX02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Use in females of reproductive potential", "message": "STOP: Ambrisentan is highly teratogenic. Exclude pregnancy before starting, monitor monthly, and ensure the use of highly effective contraception during and for 1 month after treatment."}]', '**Fluid Retention:** Peripheral edema and fluid retention are common and may require intervention with diuretics. If patients develop acute pulmonary edema during initiation, consider underlying pulmonary veno-occlusive disease and discontinue treatment if necessary.
INSERT INTO "drug_generic" VALUES(2128, 'Megestrol Acetate', 'Megestrol', 'L02AB01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "Patient with a history of deep vein thrombosis (DVT) or pulmonary embolism (PE)", "message": "STOP: Megestrol acetate increases the risk of thromboembolic events, including fatal pulmonary embolism. Use with extreme caution in patients with a history of thromboembolic disease."}]', 'Exercise caution in patients with a history of thromboembolic disease, as the risk of deep vein thrombosis and pulmonary embolism is elevated. Monitor patients with pre-existing diabetes mellitus for exacerbation of hyperglycemia or new-onset diabetes, which may require adjustment of antidiabetic therapy. Use with caution in patients with mild to moderate hepatic impairment, as metabolism may be delayed. Monitor for signs of fluid retention, particularly in patients with a history of cardiovascular disease, hypertension, or renal dysfunction. Evaluate patients presenting with severe mood swings or a history of depression. Prolonged use may lead to adrenal insufficiency due to glucocorticoid-like activity; monitor for signs of hypothalamic-pituitary-adrenal (HPA) axis suppression, especially during periods of stress or abrupt discontinuation.', '- Palliative treatment of advanced, inoperable, recurrent, or metastatic carcinoma of the breast or endometrium.
INSERT INTO "drug_generic" VALUES(2129, 'Sevelamer Hydrochloride/Carbonate', 'Sevelamer', 'V03AE02', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Gastrointestinal Disorders:** Use with caution in patients with dysphagia, swallowing disorders, severe GI motility disorders, active inflammatory bowel disease, or a history of major GI tract surgery. Cases of bowel obstruction and perforation have been reported.
INSERT INTO "drug_generic" VALUES(2130, 'Eribulin Mesylate', 'Eribulin', 'L01CX01', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Severe Neutropenia", "severity": "High", "trigger_condition": "During treatment cycles", "message": "STOP: Severe neutropenia occurs frequently. Monitor peripheral blood cell counts prior to each dose. Delay administration and reduce subsequent doses for severe neutropenia."}, {"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Patients with cardiac risk factors", "message": "Can prolong the QT interval. Avoid in patients with congenital long QT syndrome. Monitor ECG and electrolytes in patients with congestive heart failure or bradyarrhythmias."}]', '**Peripheral Neuropathy:** Monitor patients closely for signs of peripheral motor and sensory neuropathy. Severe neuropathy requires dose delay and adjustment, or permanent discontinuation.
INSERT INTO "drug_generic" VALUES(2131, 'Pyridoxine Hydrochloride', 'Pyridoxine Hydrochloride (Vitamin B6)', 'A11HA02', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Prolonged administration of high doses (e.g., >200 mg/day for months) can cause severe sensory neuropathy. Monitor for signs of peripheral neuropathy (numbness, tingling, unstable gait). Caution in patients receiving levodopa without a dopa-decarboxylase inhibitor, as pyridoxine reverses the therapeutic effects of levodopa.', '- **Vitamin B6 Deficiency:** Treatment and prevention of pyridoxine deficiency states.
INSERT INTO "drug_generic" VALUES(2132, 'Ketoconazole + Zinc Pyrithione + Aleovera', 'Ketoconazole, Zinc Pyrithione, and Aloe Vera Shampoo', 'D01AC08', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Moderate", "trigger_condition": "Application to the scalp", "message": "For external use only. Keep away from eyes and mucous membranes. If contact occurs, rinse thoroughly with water."}]', '**Hair Discoloration:** May cause discoloration or altered texture in chemically treated, permed, or bleached hair.
INSERT INTO "drug_generic" VALUES(2133, 'Trimebutine Maleate', 'Trimebutine', 'A03AA05', 0, 0, 0, 0, 0, 1, 0, 0, '[]', 'Use with caution in elderly patients, as they may be more sensitive to the central nervous system side effects (e.g., dizziness, drowsiness). Caution is advised during pregnancy and lactation due to limited safety data. If symptoms of irritable bowel syndrome do not improve or worsen after a reasonable trial period, re-evaluate the clinical diagnosis.', '- **Irritable Bowel Syndrome (IBS)**: Treatment and relief of symptoms associated with IBS, including abdominal pain, cramping, bloating, and altered bowel habits (diarrhea or constipation).
INSERT INTO "drug_generic" VALUES(2134, 'Fluticasone Propionate Inhalation', 'Fluticasone Propionate', 'R03BA05', 0, 0, 0, 1, 0, 1, 1, 1, '[{"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Immediately following inhalation", "message": "WARNING: Inhaled medicines can cause paradoxical bronchospasm, which may be life-threatening. If this occurs, treat immediately with a short-acting inhaled bronchodilator, discontinue fluticasone, and institute alternative therapy."}, {"alert_type": "Not for Acute Bronchospasm", "severity": "High", "trigger_condition": "Acute asthma attack or status asthmaticus", "message": "STOP: Fluticasone is a prophylactic controller medication. It is NOT indicated for the relief of acute bronchospasm or status asthmaticus."}]', '**Immunosuppression and Infections:** Corticosteroids increase susceptibility to infections (e.g., Candida albicans, tuberculosis, viral, fungal, or parasitic infections). Localized oral candidiasis frequently occurs; patients MUST rinse their mouth with water and spit after inhalation. Avoid exposure to chickenpox or measles, as these can be fatal in susceptible patients.
INSERT INTO "drug_generic" VALUES(2135, 'Praziquantel', 'Praziquantel', 'P02BA01', 1, 0, 1, 0, 0, 0, 1, 0, '[]', '**Central Nervous System Effects:** May exacerbate symptoms in patients with a history of epilepsy or other signs of CNS involvement (e.g., subcutaneous nodules suggestive of cysticercosis). Seizures have been reported.
INSERT INTO "drug_generic" VALUES(2136, 'Testosterone 1% Topical', 'Testosterone', 'G03BA03', 0, 1, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Secondary Exposure Risk", "severity": "High", "trigger_condition": "Physical contact with application site", "message": "Virilization has been reported in children who were secondarily exposed to topical testosterone. Patients must strictly wash hands after application, cover the application site with clothing, and wash the site prior to any skin-to-skin contact with others."}]', 'Use with extreme caution in patients with cardiovascular disorders, as testosterone can increase the risk of myocardial infarction and stroke. Monitor for worsening of benign prostatic hyperplasia (BPH) and potential risk of prostate cancer; perform periodic rectal prostate examinations and PSA monitoring. May cause polycythemia; monitor hematocrit and hemoglobin periodically. Use cautiously in patients with conditions aggravated by fluid retention (e.g., heart failure, renal or hepatic impairment, epilepsy, migraine). Monitor for signs of virilization in females and priapism in males. Not indicated for use in prepubertal boys or elderly men with age-related hypogonadism.', '- **Primary Hypogonadism (Congenital or Acquired):** Indicated for replacement therapy in adult males for conditions associated with a deficiency or absence of endogenous testosterone (e.g., testicular failure due to cryptorchidism, bilateral torsion, orchitis, vanishing testis syndrome, or orchiectomy).
INSERT INTO "drug_generic" VALUES(2137, 'Ropivacaine', 'Ropivacaine', 'N01BB09', 0, 1, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Systemic Toxicity and Cardiac Arrest", "severity": "High", "trigger_condition": "Intravascular injection or excessive dosing", "message": "STOP: Unintentional intravascular injection may result in severe CNS toxicity, seizures, and cardiac arrest. Resuscitation equipment and lipid emulsion therapy must be immediately available."}]', '**Systemic Toxicity:** Monitor the patient''s state of consciousness and cardiovascular status continuously following injection. Signs of central nervous system (CNS) toxicity include anxiety, dizziness, restlessness, tremors, depression, blurred vision, and seizures. Unintentional intravascular injection may result in immediate and severe toxicity, including respiratory arrest and cardiovascular collapse.
INSERT INTO "drug_generic" VALUES(2138, 'Magnesium Glycerophosphate', 'Magnesium Glycerophosphate', 'A12CC30', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypermagnesemia Risk", "severity": "High", "trigger_condition": "Severe renal impairment", "message": "STOP: Contraindicated in patients with severe renal impairment due to the risk of toxic magnesium accumulation, which can lead to fatal arrhythmias and respiratory depression."}]', '**Renal Function:** Use with caution in patients with mild to moderate kidney disease. The kidneys primarily excrete magnesium; impaired function increases the risk of hypermagnesemia. Regular monitoring of serum magnesium levels is advised.
INSERT INTO "drug_generic" VALUES(2139, 'Olaparib', 'Olaparib', 'L01XK01', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Myelodysplastic Syndrome/Acute Myeloid Leukemia (MDS/AML)", "severity": "High", "trigger_condition": "Prolonged cytopenias during therapy", "message": "STOP: MDS/AML, including fatal cases, have occurred. Do not initiate until hematological toxicity from prior chemotherapy resolves. Monitor CBC monthly. If MDS/AML is confirmed, discontinue olaparib immediately."}, {"alert_type": "Pneumonitis", "severity": "High", "trigger_condition": "New or worsening respiratory symptoms (dyspnea, cough, fever)", "message": "STOP: Fatal cases of pneumonitis have occurred. Interrupt treatment if pneumonitis is suspected. Discontinue permanently if pneumonitis is confirmed."}]', '**Myelodysplastic Syndrome/Acute Myeloid Leukemia (MDS/AML):** Occurs in <1.5% of patients. Monitor complete blood counts (CBC) at baseline and monthly thereafter. If prolonged hematological toxicity occurs, interrupt therapy and evaluate. 
INSERT INTO "drug_generic" VALUES(2140, 'Beta Carotene + Copper + Manganese + Selenium + Vit C', 'Antioxidant Vitamins and Minerals', 'A11AA03', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Hypervitaminosis", "severity": "Low", "message": "Do not exceed the recommended daily dose to prevent hypervitaminosis and mineral toxicity."}]', '**Anticoagulant Therapy:** Patients on anticoagulant therapy (e.g., warfarin) should not use high doses of ascorbic acid (Vitamin C) for prolonged periods, as it may interfere with prothrombin time.
INSERT INTO "drug_generic" VALUES(2141, 'Vilanterol + Umeclidinium + Fluticasone Furoate', 'Fluticasone furoate/Umeclidinium/Vilanterol', 'R03AL03', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Asthma-Related Death and Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Initiation of therapy or use during acute episodes", "message": "STOP: Long-acting beta2-adrenergic agonists (LABA) increase the risk of asthma-related death. Do not initiate in acutely deteriorating COPD or asthma. Discontinue immediately if paradoxical bronchospasm occurs."}]', '**Cardiovascular Effects:** May cause clinically significant cardiovascular effects, including arrhythmias and hypertension. Monitor closely and consider discontinuation if severe.
INSERT INTO "drug_generic" VALUES(2142, 'Indinavir', 'Indinavir', 'J05AE02', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Nephrolithiasis and Urolithiasis", "severity": "High", "trigger_condition": "Inadequate fluid intake", "message": "STOP: Nephrolithiasis/urolithiasis occurs frequently (up to 29% in pediatric patients). Ensure adequate hydration (at least 1.5 liters of liquids daily) to prevent stone formation and acute renal failure."}]', '**Nephrolithiasis/Urolithiasis:** High risk of kidney stones, which may be associated with renal insufficiency or acute renal failure. Adequate hydration (at least 1.5 L/day) is mandatory. Interrupt or discontinue therapy if severe flank pain or hematuria occurs.
INSERT INTO "drug_generic" VALUES(2143, 'Entacapone', 'Entacapone', 'N04BX02', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Withdrawal Emergent Hyperpyrexia", "severity": "High", "trigger_condition": "Abrupt discontinuation", "message": "STOP: Abrupt withdrawal or rapid dose reduction may cause a symptom complex resembling neuroleptic malignant syndrome (elevated temperature, muscular rigidity, altered consciousness). Taper gradually."}]', '- **Hypotension:** Levodopa-induced orthostatic hypotension may be aggravated. Monitor blood pressure, especially during dose adjustments.
INSERT INTO "drug_generic" VALUES(2144, 'Benazepril', 'Benazepril', 'C09AA07', 0, 0, 0, 1, 1, 1, 1, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detection", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Fetal Toxicity:** Use of drugs that act on the renin-angiotensin system during the second and third trimesters of pregnancy reduces fetal renal function and increases fetal and neonatal morbidity and death. Discontinue immediately upon detection of pregnancy.
INSERT INTO "drug_generic" VALUES(2145, 'Lamivudine + Abacavir', 'Abacavir and Lamivudine', 'J05AR02', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Presence of HLA-B*5701 allele", "message": "STOP: Severe and potentially fatal hypersensitivity reactions can occur. Screen for the HLA-B*5701 allele prior to initiating therapy. Discontinue immediately if hypersensitivity is suspected."}, {"alert_type": "Hepatitis B Exacerbation", "severity": "High", "trigger_condition": "Co-infection with Hepatitis B Virus (HBV)", "message": "STOP: Severe acute exacerbations of hepatitis B have been reported in patients who are co-infected with HBV and HIV-1 and have discontinued lamivudine or abacavir. Monitor hepatic function closely."}]', '**Lactic Acidosis and Hepatomegaly:** Lactic acidosis and severe hepatomegaly with steatosis, including fatal cases, have been reported with the use of nucleoside analogs. Suspend treatment if clinical or laboratory findings suggest these conditions.
INSERT INTO "drug_generic" VALUES(2146, 'Ferrous Ascorbate + Folic Acid + Zinc', 'Ferrous Ascorbate / Folic Acid / Zinc', 'B03AE', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Pediatric Toxicity", "severity": "High", "trigger_condition": "Accidental ingestion by children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '- **Iron Overload:** Care should be taken in patients who may develop iron overload, such as those with hemochromatosis, hemolytic anemia, or red cell aplasia.
INSERT INTO "drug_generic" VALUES(2147, 'Candesartan Cilexetil + Hydrochlorothiazide', 'Candesartan Cilexetil / Hydrochlorothiazide', 'C09DA06', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Hypotension:** Symptomatic hypotension may occur, especially in volume- or salt-depleted patients. Correct volume depletion before initiating therapy.
INSERT INTO "drug_generic" VALUES(2148, 'Apixaban', 'Apixaban', 'B01AF02', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Premature Discontinuation Risk", "severity": "High", "trigger_condition": "Discontinuation of therapy without adequate alternative anticoagulation", "message": "STOP: Premature discontinuation of apixaban increases the risk of thrombotic events, including stroke. If discontinued for reasons other than pathological bleeding, ensure coverage with another anticoagulant."}, {"alert_type": "Spinal/Epidural Hematoma", "severity": "High", "trigger_condition": "Neuraxial anesthesia or spinal puncture", "message": "STOP: Increased risk of epidural or spinal hematoma, which can result in long-term or permanent paralysis. Monitor closely for neurologic impairment."}]', '**Premature Discontinuation:** Premature discontinuation of any oral anticoagulant increases the risk of thrombotic events. An increased rate of stroke was observed following discontinuation in clinical trials for nonvalvular atrial fibrillation. If anticoagulation must be discontinued for a reason other than pathological bleeding, coverage with another anticoagulant should be strongly considered.
INSERT INTO "drug_generic" VALUES(2149, 'Terbutaline Sulphate', 'Terbutaline Sulfate', 'R03CC03', 0, 1, 0, 1, 1, 1, 1, 0, '[{"alert_type": "Tocolysis Contraindication", "severity": "High", "trigger_condition": "Use for prevention or prolonged treatment of preterm labor", "message": "STOP: Oral terbutaline is contraindicated for the prevention or prolonged treatment of preterm labor. Serious maternal adverse reactions, including fatal arrhythmias, pulmonary edema, and myocardial ischemia, have been reported."}]', '**Cardiovascular Effects:** Can cause clinically significant cardiovascular effects, including tachycardia, arrhythmias, and myocardial ischemia. Use with caution in patients with ischemic heart disease, hypertension, or cardiac arrhythmias.
INSERT INTO "drug_generic" VALUES(2150, 'Methoxsalen', 'Methoxsalen', 'D05AD02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Severe Burns Risk", "severity": "High", "trigger_condition": "Overexposure to UVA or sunlight", "message": "STOP: Severe blistering and deep skin burns can occur if the UVA dose is exceeded or if the patient is exposed to sunlight after application. Strict adherence to dosing and light protection is required."}]', '**Skin Cancer Risk:** Increased risk of developing skin cancers, including melanoma and squamous cell carcinoma. Caution in patients with a history of basal cell carcinoma, previous arsenic therapy, or previous x-ray/grenz ray therapy.
INSERT INTO "drug_generic" VALUES(2151, 'Vitamin B Complex Inj', 'Vitamin B Complex Injection', 'A11EA', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "Moderate", "trigger_condition": "Intravenous administration", "message": "Severe hypersensitivity reactions, including anaphylaxis, have been reported rarely, particularly with intravenous administration of thiamine-containing products. Inject slowly and have resuscitation equipment available."}]', '**Intravenous Administration:** Must be injected slowly when given by the intravenous route to minimize the risk of hypotension and anaphylactoid reactions. High concentrations should be diluted using Normal Saline or D5W.
INSERT INTO "drug_generic" VALUES(2152, 'Calcium + Vitamin D + Multiminerals', 'Calcium, Vitamin D, and Minerals', 'A12AX', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Hypercalcemia and Hypercalciuria:** Prolonged use of high doses can lead to hypercalcemia and hypercalciuria. Monitor serum and urinary calcium levels, especially in patients with a history of renal stones.
INSERT INTO "drug_generic" VALUES(2153, 'Clove oil', 'Clove Oil (Eugenol)', 'A01AD', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Tissue Toxicity and Ingestion Risk", "severity": "High", "trigger_condition": "Undiluted application or accidental ingestion", "message": "STOP: Undiluted application directly onto gums or oral mucosa can cause severe chemical burns and tissue necrosis. Oral ingestion of concentrated clove oil can cause acute liver toxicity, seizures, and rapid organ failure, especially in young children."}]', '**Tissue Toxicity:** Always apply sparingly. When used for toothache, apply only to the cavity of the affected tooth using a cotton swab. Avoid contact with surrounding healthy gums or mucosa.
INSERT INTO "drug_generic" VALUES(2154, 'Mirogabalin', 'Mirogabalin', 'N02BF03', 0, 0, 0, 0, 1, 1, 0, 1, '[]', 'Dose adjustment is required in patients with renal dysfunction. Mirogabalin may cause dizziness, somnolence, blurred vision, or double vision; patients should avoid operating potentially hazardous machinery or driving. Elderly patients are at an increased risk of falls and fractures due to these CNS effects. Monitor for weight gain and peripheral edema.', '- **Neuropathic Pain:** Indicated for the treatment of peripheral neuropathic pain, including diabetic peripheral neuropathic pain and postherpetic neuralgia.', '- **Hypersensitivity:** Contraindicated in patients with known hypersensitivity to mirogabalin or any of its components.
INSERT INTO "drug_generic" VALUES(2155, 'Busulphan', 'Busulfan', 'L01AB01', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Severe Myelosuppression and Veno-Occlusive Disease", "severity": "High", "trigger_condition": "Initiation of therapy or high-dose conditioning regimens", "message": "STOP: Busulfan causes profound, potentially fatal myelosuppression. High doses are strongly associated with life-threatening Hepatic Veno-Occlusive Disease (VOD). Administer only under the supervision of an experienced oncologist."}]', '**Myelosuppression:** Profound bone marrow suppression (neutropenia, thrombocytopenia, anemia) is expected. Hematopoietic progenitor cell transplantation is required for high-dose regimens. Monitor CBC frequently.
INSERT INTO "drug_generic" VALUES(2156, 'Bethanechol', 'Bethanechol', 'N07AB02', 0, 0, 0, 0, 0, 1, 1, 0, '[]', '**Urinary Tract Infection Risk:** Since bethanechol contracts the bladder, there is a potential for reflux infection if the sphincter fails to relax. Use with caution in patients with bacteriuria.
INSERT INTO "drug_generic" VALUES(2157, 'Adenosine', 'Adenosine', 'C01EB10', 0, 1, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Transient Asystole and Arrhythmias", "severity": "High", "trigger_condition": "Intravenous administration", "message": "STOP: Adenosine causes a brief period of asystole (up to 15 seconds) and can induce ventricular arrhythmias. Must be administered in a monitored setting with a defibrillator and resuscitation equipment immediately available."}, {"alert_type": "Bronchospasm Risk", "severity": "High", "trigger_condition": "Patient with asthma or severe COPD", "message": "STOP: Adenosine can cause severe, potentially fatal bronchoconstriction. Contraindicated in patients with bronchospastic lung disease."}]', '**Cardiac Arrest and Arrhythmias:** Fatal cardiac events, including ventricular fibrillation, have occurred. Avoid in patients with acute myocardial ischemia. Continuous ECG monitoring is mandatory.
INSERT INTO "drug_generic" VALUES(2158, 'Fluticasone Propionate 0.05% Topical', 'Fluticasone Propionate', 'D07AC17', 0, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Endocrine Toxicity", "severity": "Moderate", "trigger_condition": "Prolonged use or application over large surface areas", "message": "Systemic absorption of topical corticosteroids can produce reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and unmask latent diabetes mellitus."}]', 'Monitor for signs of hypothalamic-pituitary-adrenal (HPA) axis suppression, especially in patients using high doses, applying to large surface areas, or using occlusive dressings. Discontinue use if local irritation, sensitization, or contact dermatitis develops. Avoid use on the face, groin, or axillae unless specifically directed. Do not use in the presence of preexisting skin atrophy. If a concomitant skin infection is present or develops, an appropriate antifungal or antibacterial agent must be instituted; if a favorable response does not occur promptly, discontinue the corticosteroid until the infection is adequately controlled. Pediatric patients may be more susceptible to systemic toxicity due to a larger skin surface-to-body mass ratio.', '- **Corticosteroid-Responsive Dermatoses:** Relief of the inflammatory and pruritic manifestations of corticosteroid-responsive dermatoses.
INSERT INTO "drug_generic" VALUES(2159, 'Docosanol 10% topical', 'Docosanol 10% Topical', 'D06BB11', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **External Use Only:** Strictly for topical use on the lips and face. Do not apply inside the mouth, near the eyes, or on the genitals.
INSERT INTO "drug_generic" VALUES(2160, 'Demeclocycline Hydrochloride', 'Demeclocycline', 'J01AA01', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Tooth Discoloration and Bone Growth Inhibition", "severity": "High", "trigger_condition": "Use in children under 8 years of age or during pregnancy", "message": "STOP: Demeclocycline causes permanent tooth discoloration (yellow-gray-brown) and reversible inhibition of bone growth. Avoid use during tooth development (last half of pregnancy through age 8) unless absolutely necessary."}]', '**Photosensitivity:** Exaggerated sunburn reactions can occur. Advise patients to avoid direct sunlight or UV light and discontinue therapy at the first sign of skin erythema.
INSERT INTO "drug_generic" VALUES(2161, 'Polyethylene Glycol', 'Polyethylene Glycol 3350', 'A06AD15', 0, 0, 1, 1, 1, 1, 1, 0, '[]', 'Evaluate patients with symptoms suggestive of bowel obstruction (e.g., severe nausea, vomiting, abdominal pain, or distension) to rule out structural abnormalities before initiating therapy. Prolonged, frequent, or excessive use may result in electrolyte imbalance and dependence on laxatives. Use with caution in elderly nursing home patients, as high doses may produce excessive diarrhea and dehydration.', '- Treatment of occasional constipation.
INSERT INTO "drug_generic" VALUES(2162, 'Cangrelor', 'Cangrelor', 'B01AC25', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Bleeding Risk", "severity": "High", "trigger_condition": "Concomitant use with other antiplatelets or anticoagulants", "message": "STOP: Cangrelor significantly increases the risk of bleeding, including severe and life-threatening hemorrhage. Contraindicated in patients with significant active bleeding."}]', '- **Bleeding Risk:** Increases the risk of bleeding, including severe and life-threatening hemorrhage. Bleeding events are more common with cangrelor than with clopidogrel. Monitor closely for signs of bleeding.
INSERT INTO "drug_generic" VALUES(2163, 'Amiloride Hydrochloride + Hydrochlorothiazide', 'Amiloride and Hydrochlorothiazide', 'C03EA01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hyperkalemia", "severity": "High", "trigger_condition": "Renal impairment, diabetes, or concurrent potassium supplements", "message": "STOP: Amiloride can cause fatal hyperkalemia (potassium >5.5 mEq/L). Do not use with potassium supplements, other potassium-sparing diuretics, or in patients with severe renal impairment."}, {"alert_type": "Acute Myopia and Secondary Angle-Closure Glaucoma", "severity": "High", "trigger_condition": "Acute decrease in visual acuity or eye pain", "message": "STOP: Hydrochlorothiazide can cause an idiosyncratic reaction resulting in acute transient myopia and acute angle-closure glaucoma. Discontinue immediately if visual symptoms occur."}]', '**Electrolyte Imbalance:** Can cause hypokalemia, hyponatremia, hypochloremic alkalosis, hypomagnesemia, and hypercalcemia. Monitor serum electrolytes regularly.
INSERT INTO "drug_generic" VALUES(2164, 'Aliskiren', 'Aliskiren', 'C09XA02', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected during therapy", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue aliskiren as soon as possible when pregnancy is detected."}]', '**Head and Neck Angioedema:** Can occur at any time during treatment. Discontinue immediately and monitor until signs resolve. Do not re-challenge.
INSERT INTO "drug_generic" VALUES(2165, 'Glasdegib', 'Glasdegib', 'L01XJ03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy or potential for pregnancy", "message": "STOP: Glasdegib can cause severe birth defects or embryo-fetal death. Verify pregnancy status prior to initiation. Advise females and males of reproductive potential to use effective contraception during and after treatment."}, {"alert_type": "QTc Prolongation", "severity": "High", "trigger_condition": "Concomitant use of QTc prolonging drugs or history of arrhythmias", "message": "WARNING: Glasdegib can cause concentration-dependent QTc prolongation and ventricular arrhythmias. Monitor ECGs and electrolytes closely."}]', '**Embryo-Fetal Toxicity:** Based on its mechanism of action and animal studies, glasdegib can cause embryo-fetal death or severe birth defects. Verify pregnancy status prior to initiation. Advise effective contraception for females and males of reproductive potential.
INSERT INTO "drug_generic" VALUES(2166, 'Metronidazole', 'Metronidazole', 'J01XD01', 1, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Carcinogenicity and Neurologic Toxicity", "severity": "High", "trigger_condition": "Systemic administration", "message": "STOP: Metronidazole has been shown to be carcinogenic in mice and rats. Unnecessary use should be avoided. Severe neurologic disturbances, including seizures, encephalopathy, and peripheral neuropathy, have been reported. Discontinue immediately if abnormal neurologic symptoms occur."}]', 'Use with caution in patients with central nervous system diseases or a history of seizures, as high doses or prolonged therapy can precipitate encephalopathy, cerebellar toxicity (ataxia, dysarthria), and peripheral neuropathy. Perform total and differential leukocyte counts before and after prolonged treatment, as mild leukopenia has been observed. Use with caution in patients with severe hepatic impairment; the drug accumulates, requiring dose reduction. Intravenous formulations contain significant sodium; use with caution in patients predisposed to edema or heart failure. Prolonged use may result in fungal (Candida) or bacterial superinfection.', '- Treatment of anaerobic bacterial infections (e.g., intra-abdominal, skin/skin structure, gynecologic, bone/joint, CNS, and lower respiratory tract infections).
INSERT INTO "drug_generic" VALUES(2167, 'Indacaterol + Glycopyrronium bromide + Mometasone', 'Indacaterol + Glycopyrrolate + Mometasone', 'R03AL08', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Acute Bronchospasm", "severity": "High", "trigger_condition": "Use during acute asthma attacks", "message": "STOP: This medication is a maintenance inhaler and is NOT indicated for the relief of acute bronchospasm or status asthmaticus. Use a short-acting beta2-agonist (SABA) for rescue."}]', '**Paradoxical Bronchospasm:** Discontinue immediately if paradoxical bronchospasm occurs and treat with a short-acting bronchodilator.
INSERT INTO "drug_generic" VALUES(2168, 'Telmisartan + Hydrochlorothiazide', 'Telmisartan and Hydrochlorothiazide', 'C09DA07', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Fetal Toxicity:** Can cause fetal harm when administered to a pregnant woman. Discontinue as soon as pregnancy is detected.
INSERT INTO "drug_generic" VALUES(2169, 'Paromomycin', 'Paromomycin', 'A07AA06', 1, 0, 0, 1, 1, 1, 1, 0, '[]', 'Use with extreme caution in patients with ulcerative bowel lesions (e.g., inflammatory bowel disease), as significant systemic absorption of this aminoglycoside can occur, leading to a risk of ototoxicity and nephrotoxicity. Prolonged use may result in the overgrowth of non-susceptible organisms, including fungi, leading to superinfection. Caution should be exercised when giving paromomycin to patients with renal impairment, as any systemically absorbed drug will accumulate. Monitor auditory and renal function if systemic absorption is suspected.', '- **Intestinal Amebiasis:** Indicated for the treatment of acute and chronic intestinal amebiasis. It is effective against luminal forms but not against extraintestinal amebiasis.
INSERT INTO "drug_generic" VALUES(2170, 'Iopanoic Acid', 'Iopanoic Acid', 'V08EE01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Renal Toxicity", "severity": "High", "trigger_condition": "Doses exceeding 3 grams or preexisting renal impairment", "message": "STOP: Doses higher than 3 grams should not be given to patients with renal impairment due to the high risk of severe, potentially fatal acute renal failure."}]', '- Avoid use in patients with severe renal or hepatic disease; monitor renal and hepatic function closely if use is necessary.
INSERT INTO "drug_generic" VALUES(2171, 'Amlodipine + Valsartan', 'Amlodipine and Valsartan', 'C09DB01', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected during therapy", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue amlodipine/valsartan as soon as possible when pregnancy is detected."}]', '**Hypotension:** Symptomatic hypotension can occur, especially in volume- or salt-depleted patients. Correct volume depletion prior to initiation.
INSERT INTO "drug_generic" VALUES(2172, 'Sulfanilamide vaginal prep', 'Sulfanilamide Vaginal', 'G01AE14', 1, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Cutaneous Reactions", "severity": "High", "trigger_condition": "Development of skin rash or mucosal lesions", "message": "STOP: Severe and potentially fatal reactions including Toxic Epidermal Necrolysis (TEN) and Stevens-Johnson Syndrome (SJS) have been reported with sulfonamides. Discontinue immediately at the first sign of a skin rash."}]', '**Hematologic Toxicity:** Severe blood reactions including aplastic anemia, agranulocytosis, and other blood dyscrasias have been reported with systemic sulfonamide absorption.
INSERT INTO "drug_generic" VALUES(2173, 'Sulphadiazine + Trimethoprim', 'Sulfadiazine and Trimethoprim', 'J01EE05', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Hypersensitivity and Blood Dyscrasias", "severity": "High", "trigger_condition": "History of sulfonamide allergy or development of rash", "message": "STOP: Fatalities associated with severe reactions (Stevens-Johnson syndrome, toxic epidermal necrolysis, fulminant hepatic necrosis, agranulocytosis, aplastic anemia) have occurred. Discontinue at the first sign of skin rash or any sign of adverse reaction."}]', '**Blood Dyscrasias:** Can cause severe hematologic toxicity. Monitor CBC regularly, especially in the elderly or those with folate deficiency.
INSERT INTO "drug_generic" VALUES(2174, 'Elemental Iron (Iron iii Hydroxide Sucrose Complex)', 'Iron Sucrose', 'B03AC', 0, 1, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Hypersensitivity and Anaphylaxis", "severity": "High", "trigger_condition": "Intravenous administration", "message": "STOP: Serious hypersensitivity reactions, including anaphylactic-type reactions, some of which have been life-threatening and fatal, have been reported. Monitor patients for signs and symptoms of hypersensitivity during and after administration for at least 30 minutes."}]', '**Hypotension:** Severe hypotension may occur during administration. Monitor blood pressure closely during the infusion. If hypotension occurs, slow the rate of infusion or discontinue immediately and provide supportive care.
INSERT INTO "drug_generic" VALUES(2175, 'Betamethasone  0.1% + Neomycin Sulphate 0.5% E/E prep', 'Betamethasone and Neomycin Ophthalmic/Otic', 'S01CA05', 1, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Ocular Toxicity", "severity": "High", "trigger_condition": "Prolonged ophthalmic use", "message": "STOP: Prolonged use of ophthalmic corticosteroids can cause elevated intraocular pressure (glaucoma), optic nerve damage, and posterior subcapsular cataracts. Monitor IOP if used for >7 days."}, {"alert_type": "Tympanic Membrane Perforation", "severity": "High", "trigger_condition": "Otic use in patients with a perforated eardrum", "message": "STOP: Do NOT use in the ear if the eardrum is perforated. Neomycin is an aminoglycoside and can cause irreversible ototoxicity (deafness) if it enters the middle ear."}]', '**Intraocular Pressure (IOP):** Prolonged use may result in ocular hypertension/glaucoma. Monitor IOP routinely if used for more than 7 days.
INSERT INTO "drug_generic" VALUES(2176, 'Lymecycline', 'Lymecycline', 'J01AA04', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Pediatric Contraindication", "severity": "High", "trigger_condition": "Prescription for a child under 12 years of age", "message": "STOP: Lymecycline is contraindicated in children under 12 years of age due to the risk of permanent dental dyschromia (yellow-grey-brown discoloration) and enamel hypoplasia."}]', '- **Photosensitivity:** Exaggerated sunburn reactions can occur. Advise patients to avoid exposure to direct sunlight or ultraviolet (UV) light and to discontinue therapy at the first sign of skin erythema.
INSERT INTO "drug_generic" VALUES(2177, 'Conjugated Estrogens', 'Conjugated Estrogens', 'G03CA57', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Endometrial Cancer", "severity": "High", "trigger_condition": "Use of unopposed estrogens in women with an intact uterus", "message": "WARNING: There is an increased risk of endometrial cancer in women with a uterus who use unopposed estrogens. Adding a progestin reduces this risk."}, {"alert_type": "Cardiovascular and Other Risks", "severity": "High", "trigger_condition": "Use of estrogen-alone or estrogen plus progestin therapy", "message": "WARNING: Estrogens should not be used for the prevention of cardiovascular disease or dementia. The WHI study reported increased risks of stroke, DVT, PE, myocardial infarction, invasive breast cancer, and probable dementia. Prescribe at the lowest effective dose for the shortest duration."}]', '**Gallbladder Disease:** Estrogens increase the risk of gallbladder disease requiring surgery in postmenopausal women.
INSERT INTO "drug_generic" VALUES(2178, 'Ipratropium Bromide', 'Ipratropium Bromide', 'R03BB01', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Paradoxical Bronchospasm", "severity": "High", "trigger_condition": "Inhalation of the drug", "message": "STOP: Inhaled medicines can cause life-threatening paradoxical bronchospasm. If this occurs, discontinue ipratropium immediately and institute alternative therapy."}]', '- Use with caution in patients with narrow-angle glaucoma or those susceptible to glaucoma; protect the patient''s eyes from nebulized drug, as inadvertent ocular exposure can precipitate acute angle-closure glaucoma.
INSERT INTO "drug_generic" VALUES(2179, 'Ioversol', 'Ioversol', 'V08AB07', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Severe Hypersensitivity and Nephrotoxicity", "severity": "High", "trigger_condition": "History of iodine allergy or pre-existing renal impairment", "message": "STOP: Life-threatening anaphylactic reactions and contrast-induced nephropathy can occur. Ensure emergency resuscitation equipment is available and assess renal function prior to administration."}]', 'Diagnostic procedures involving iodinated intravascular contrast agents must be conducted under the supervision of skilled personnel. A fully equipped emergency cart and personnel competent in recognizing and treating severe adverse reactions must be immediately available for at least 30 to 60 minutes post-administration due to the risk of delayed reactions.
INSERT INTO "drug_generic" VALUES(2180, 'Fenofibrate', 'Fenofibrate', 'C10AB05', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis Risk", "severity": "High", "trigger_condition": "Concomitant use with HMG-CoA reductase inhibitors (statins) or in patients with severe renal impairment", "message": "Caution: Increased risk of severe myopathy and rhabdomyolysis, especially when co-administered with statins, in the elderly, or in patients with diabetes, renal failure, or hypothyroidism."}]', '**Skeletal Muscle Effects:** Myopathy and rhabdomyolysis have been reported. The risk increases significantly when co-administered with statins (e.g., simvastatin, atorvastatin) or in patients with renal impairment. Monitor for unexplained muscle pain, tenderness, or weakness, particularly if accompanied by malaise or fever.
INSERT INTO "drug_generic" VALUES(2181, 'Multivitamin-Multimineral A-Z preparations for Juniors', 'Pediatric Multiple Vitamins with Minerals', 'A11AA03', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Intravenous administration of formulations containing thiamine", "message": "STOP: Rare but severe anaphylactic reactions have been reported following parenteral multivitamin administration, particularly with large intravenous doses of thiamine. Ensure resuscitation equipment is available."}]', 'Caution should be exercised when administering this multivitamin formulation to patients on warfarin sodium-type anticoagulant therapy, as the presence of Vitamin K can antagonize the anticoagulant effect.
INSERT INTO "drug_generic" VALUES(2182, 'Meningococcal polysaccharide ACWY Vaccine', 'Meningococcal Polysaccharide Vaccine, Groups A, C, Y and W-135', 'J07AH04', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "History of severe allergic reaction to previous dose or vaccine components", "message": "STOP: As with all injectable vaccines, appropriate medical treatment and supervision (e.g., epinephrine) must always be readily available in case of a rare anaphylactic event following administration."}]', '**Acute Illness:** Administration should be postponed in subjects suffering from acute severe febrile illness. The presence of a minor infection (e.g., mild upper respiratory tract infection) is not a contraindication.
INSERT INTO "drug_generic" VALUES(2183, 'Oxyphenonium Bromide', 'Oxyphenonium Bromide', 'A03AB03', 0, 0, 0, 0, 1, 1, 1, 0, '[]', '**Cardiovascular Disease:** Use with extreme caution in patients with acute myocardial infarction, cardiac failure, hypertension, or thyrotoxicosis. Anticholinergic effects can precipitate severe tachycardia and arrhythmias.
INSERT INTO "drug_generic" VALUES(2184, 'Peramivir', 'Peramivir', 'J05AH03', 0, 0, 1, 0, 1, 1, 1, 0, '[{"alert_type": "Neuropsychiatric Events", "severity": "Moderate", "trigger_condition": "Patients with influenza, particularly pediatric patients", "message": "Monitor for abnormal behavior. Influenza can be associated with neurologic and behavioral symptoms including hallucinations, delirium, and abnormal behavior, in some cases resulting in fatal outcomes."}]', '**Severe Skin Reactions:** Rare but serious skin reactions, including erythema multiforme and Stevens-Johnson syndrome, have been reported. Discontinue immediately if a severe rash develops.
INSERT INTO "drug_generic" VALUES(2185, 'Tazarotene 0.1% Topical', 'Tazarotene Topical', 'D05AX05', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Teratogenicity", "severity": "High", "trigger_condition": "Use in females of reproductive potential", "message": "STOP: Tazarotene is a teratogenic retinoid. A negative pregnancy test must be obtained within 2 weeks prior to initiation. Effective contraception is mandatory."}]', 'Avoid contact with eyes, mouth, and mucous membranes. Do not apply to abraded, eczematous, or sunburnt skin, as severe irritation may occur. Avoid excessive exposure to natural or artificial sunlight (UV light); use sunscreen and protective clothing. Do not use on more than 10% of the body surface area (BSA) for psoriasis to minimize systemic absorption. Do not use with occlusive dressings. Wash hands thoroughly after application. Caution if co-administered with other photosensitizing drugs (e.g., thiazides, tetracyclines, fluoroquinolones).', '- **Acne Vulgaris:** Topical treatment of mild to moderate facial acne vulgaris.
INSERT INTO "drug_generic" VALUES(2186, 'Ziprasidone', 'Ziprasidone', 'N05AE04', 0, 1, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Increased Mortality in Elderly Patients with Dementia-Related Psychosis", "severity": "High", "trigger_condition": "Use in elderly patients with dementia", "message": "STOP: Elderly patients with dementia-related psychosis treated with antipsychotic drugs are at an increased risk of death. Ziprasidone is not approved for the treatment of patients with dementia-related psychosis."}, {"alert_type": "QT Prolongation", "severity": "High", "trigger_condition": "Co-administration with other QT-prolonging drugs or history of arrhythmias", "message": "STOP: Ziprasidone can prolong the QT interval, increasing the risk of fatal Torsades de Pointes. Avoid use with other QT-prolonging drugs, in patients with congenital long QT syndrome, or uncompensated heart failure."}]', '**QT Prolongation:** Ziprasidone causes a dose-related prolongation of the QTc interval. Monitor ECG and serum electrolytes (potassium, magnesium) at baseline and periodically.
INSERT INTO "drug_generic" VALUES(2187, 'Vinorelbine', 'Vinorelbine', 'L01CA04', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Severe Myelosuppression and Extravasation", "severity": "High", "trigger_condition": "Administration of IV formulation", "message": "STOP: Vinorelbine causes severe myelosuppression (neutropenia) resulting in serious infection, septic shock, and death. It is also a potent vesicant; IV extravasation can cause severe tissue necrosis. Administer strictly via a free-flowing IV line."}]', '**Myelosuppression:** Severe granulocytopenia is the dose-limiting toxicity. Monitor complete blood counts (CBC) with differentials prior to each dose. Delay subsequent doses if neutrophil count is <2,000 cells/mm³ (or <1,500 cells/mm³ depending on protocol) until recovery.
INSERT INTO "drug_generic" VALUES(2188, 'Clonazepam', 'Clonazepam', 'N03AE01', 0, 1, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Concomitant Use with Opioids", "severity": "High", "trigger_condition": "Concurrent use of clonazepam and opioid medications", "message": "WARNING: Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death. Reserve concomitant prescribing for patients with inadequate alternative options."}, {"alert_type": "Abuse, Misuse, and Addiction", "severity": "High", "trigger_condition": "Prescribing or dispensing clonazepam", "message": "WARNING: Use exposes patients to risks of abuse, misuse, and addiction, which can lead to overdose or death. Assess risk before prescribing and monitor regularly."}, {"alert_type": "Dependence and Withdrawal Reactions", "severity": "High", "trigger_condition": "Abrupt discontinuation or rapid dose reduction", "message": "WARNING: Abrupt discontinuation can precipitate acute, life-threatening withdrawal reactions (e.g., status epilepticus). Always use a gradual taper to discontinue or reduce the dosage."}]', '**CNS Depression:** Causes dose-dependent CNS depression. Impairs physical and mental abilities. Caution patients against operating hazardous machinery or driving.
INSERT INTO "drug_generic" VALUES(2189, 'Zinc Oxide + Castor oil Topical', 'Zinc Oxide and Castor Oil', 'D02AB', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**External Use Only:** Avoid contact with the eyes and mucous membranes. Do not ingest.
INSERT INTO "drug_generic" VALUES(2190, 'Empagliflozin', 'Empagliflozin', 'A10BK03', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Diabetic Ketoacidosis and Fournier''s Gangrene", "severity": "High", "trigger_condition": "Symptoms of severe abdominal pain, vomiting, or perineal pain/erythema", "message": "STOP: Risk of euglycemic diabetic ketoacidosis (DKA) and necrotizing fasciitis of the perineum (Fournier''s gangrene). Assess for ketones if patient presents with nausea/vomiting, even if blood glucose is normal. Discontinue immediately if suspected."}]', '**Hypotension and Volume Depletion:** Causes intravascular volume contraction. Assess and correct volume status before initiating, especially in the elderly, patients with renal impairment, low systolic BP, or those on diuretics.
INSERT INTO "drug_generic" VALUES(2191, 'Palonosetron', 'Palonosetron', 'A04AA05', 0, 0, 1, 0, 0, 1, 1, 0, '[{"alert_type": "Serotonin Syndrome Risk", "severity": "High", "trigger_condition": "Concomitant use with other serotonergic agents (e.g., SSRIs, SNRIs, MAOIs)", "message": "STOP: Development of potentially life-threatening serotonin syndrome has been reported with 5-HT3 receptor antagonists. Monitor for mental status changes, autonomic instability, and neuromuscular symptoms."}]', '**Serotonin Syndrome:** The development of serotonin syndrome has been reported with 5-HT3 receptor antagonists. Most reports have been associated with concomitant use of serotonergic drugs (e.g., SSRIs, SNRIs, MAOIs, mirtazapine, fentanyl, lithium, tramadol). Monitor patients for emergence of serotonin syndrome.
INSERT INTO "drug_generic" VALUES(2192, 'Retapamulin 1% Topical', 'Retapamulin', 'D06AX13', 1, 0, 1, 1, 0, 1, 1, 0, '[]', 'For topical use only; not for oral, intranasal, ophthalmic, or intravaginal use. Discontinue use and wipe off the ointment if severe local irritation or sensitization occurs. Prolonged use may result in the overgrowth of non-susceptible organisms, including fungi. Re-evaluate the patient if there is no clinical response within 3 to 4 days of treatment. Safety and efficacy have not been established in pediatric patients less than 9 months of age.', '- **Impetigo:** Topical treatment of impetigo due to methicillin-susceptible *Staphylococcus aureus* or *Streptococcus pyogenes*.
INSERT INTO "drug_generic" VALUES(2193, 'Cephradine', 'Cephradine', 'J01DB09', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis Risk", "severity": "High", "trigger_condition": "Patient history of Penicillin or Cephalosporin hypersensitivity", "message": "STOP: Severe and potentially fatal hypersensitivity reactions (anaphylaxis) can occur. Verify patient allergy history before prescribing. Cross-reactivity with penicillins occurs in up to 10% of patients."}]', '**Renal Impairment:** Dosage adjustment is required in patients with impaired renal function to prevent drug accumulation and potential neurotoxicity (seizures).
INSERT INTO "drug_generic" VALUES(2194, 'Calcitriol + Calcium', 'Calcitriol and Calcium', 'A12AX', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Hypercalcemia Risk", "severity": "High", "trigger_condition": "Excessive dosage or inadequate monitoring", "message": "STOP: The combination of active Vitamin D (calcitriol) and elemental calcium significantly increases the risk of hypercalcemia. Frequent monitoring of serum calcium and phosphorus is mandatory."}]', '**Hypercalcemia and Milk-Alkali Syndrome:** Co-administration of calcium and calcitriol increases the risk of hypercalcemia. Monitor serum calcium levels closely. Prolonged hypercalcemia combined with alkalosis can lead to milk-alkali syndrome and renal failure.
INSERT INTO "drug_generic" VALUES(2195, 'Diazepam', 'Diazepam', 'N05BA01', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Concomitant Use with Opioids", "severity": "High", "trigger_condition": "Co-administration of benzodiazepines and opioids", "message": "STOP: Concomitant use of benzodiazepines and opioids may result in profound sedation, respiratory depression, coma, and death. Reserve concomitant prescribing for patients with inadequate alternative treatment options."}]', '**CNS Depression:** May cause significant CNS depression, impairing physical and mental abilities. Caution in elderly patients due to increased risk of falls and oversedation.
INSERT INTO "drug_generic" VALUES(2196, 'Ifosfamide', 'Ifosfamide', 'L01AA06', 0, 1, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Hemorrhagic Cystitis", "severity": "High", "trigger_condition": "Administration without Mesna or adequate hydration", "message": "STOP: Severe and potentially fatal hemorrhagic cystitis can occur. Ifosfamide MUST be administered with the uroprotector Mesna and extensive intravenous hydration (at least 2 L/day)."}, {"alert_type": "CNS Toxicity", "severity": "High", "trigger_condition": "High doses or renal impairment", "message": "STOP: Severe neurotoxicity (encephalopathy, confusion, coma, seizures) can occur and may be fatal. Discontinue ifosfamide immediately if severe CNS toxicity develops."}, {"alert_type": "Severe Myelosuppression", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "STOP: Severe myelosuppression (leukopenia, thrombocytopenia) can lead to fatal infections or hemorrhage. Monitor CBC frequently."}]', 'Use with extreme caution in patients with pre-existing renal or hepatic impairment, as this increases the risk of severe CNS toxicity and nephrotoxicity.
INSERT INTO "drug_generic" VALUES(2197, 'Sodium Lactate', 'Sodium Lactate', 'B05XA03', 0, 0, 0, 0, 1, 0, 1, 0, '[]', '- **Fluid and Solute Overload:** Use with caution in patients with heart failure, severe renal impairment, edema, hypertension, eclampsia, or aldosteronism due to the risk of sodium retention and fluid overload.
INSERT INTO "drug_generic" VALUES(2198, 'Sumatriptan nasal prep', 'Sumatriptan Nasal Spray', 'N02CC01', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Patient with history of ischemic heart disease, uncontrolled hypertension, or concurrent ergotamine use", "message": "STOP: Sumatriptan can cause severe, potentially fatal cardiovascular events including myocardial infarction, arrhythmias, and stroke. Contraindicated in ischemic heart disease and uncontrolled hypertension."}]', '**Cardiovascular and Cerebrovascular Events:** Serious cardiac events, including acute myocardial infarction, life-threatening arrhythmias, and death, have been reported within hours of administration. Cerebrovascular events (cerebral hemorrhage, subarachnoid hemorrhage, stroke) have also occurred. Do not use in patients with unrecognized coronary artery disease (CAD) predicted by risk factors (e.g., hypertension, hypercholesterolemia, smoking, obesity, diabetes, strong family history of CAD, postmenopausal women, men >40 years) without prior cardiovascular evaluation.
INSERT INTO "drug_generic" VALUES(2199, 'Doxylamine Succinate', 'Doxylamine', 'R06AA09', 0, 0, 1, 0, 0, 0, 0, 0, '[{"alert_type": "Severe CNS Depression and Anticholinergic Toxicity", "severity": "High", "trigger_condition": "Concurrent use with alcohol, other CNS depressants, or in elderly patients", "message": "STOP: Doxylamine causes profound sedation and potent anticholinergic effects. Avoid use in the elderly due to high risk of confusion, falls, and urinary retention. Do not combine with alcohol or other sedatives."}]', '**Anticholinergic Effects:** Use with extreme caution in patients with angle-closure glaucoma, urinary retention, prostatic hypertrophy, or pyloroduodenal obstruction due to potent muscarinic blockade.
INSERT INTO "drug_generic" VALUES(2200, 'Epoetin alfa (Recombinant Human Erythropoietin)', 'Epoetin alfa', 'B03XA01', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Cardiovascular Events and Tumor Progression", "severity": "High", "trigger_condition": "Targeting hemoglobin levels > 11 g/dL or use in certain cancer patients", "message": "STOP: Erythropoiesis-stimulating agents (ESAs) increase the risk of death, myocardial infarction, stroke, venous thromboembolism, and tumor progression. Use the lowest dose needed to avoid red blood cell transfusions. Do not target a hemoglobin level > 11 g/dL."}]', '**Hypertension:** Blood pressure may rise significantly during therapy. Control hypertension adequately before initiation and monitor closely. Hypertensive encephalopathy and seizures have occurred.
INSERT INTO "drug_generic" VALUES(2201, 'Dexketoprofen', 'Dexketoprofen', 'M01AE17', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Cardiovascular and Gastrointestinal Risk", "severity": "High", "trigger_condition": "Use in patients with cardiovascular disease or history of GI bleeding", "message": "STOP: NSAIDs cause an increased risk of serious cardiovascular thrombotic events (MI, stroke) and serious gastrointestinal adverse events (bleeding, ulceration, perforation), which can be fatal. Contraindicated in the setting of CABG surgery."}]', '**Gastrointestinal Risk:** GI bleeding, ulceration, and perforation can occur at any time during treatment, with or without warning symptoms. Risk is higher with increasing doses, history of ulcers, alcoholism, and in the elderly.
INSERT INTO "drug_generic" VALUES(2202, 'Pertuzumab', 'Pertuzumab', 'L01FD02', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Left Ventricular Dysfunction", "severity": "High", "trigger_condition": "Prior anthracycline use or pre-existing cardiac disease", "message": "STOP: Can cause severe left ventricular dysfunction and congestive heart failure. Assess LVEF prior to initiation and at regular intervals during treatment."}, {"alert_type": "Embryo-Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy", "message": "STOP: Exposure during pregnancy can result in oligohydramnios and fatal fetal developmental anomalies. Verify pregnancy status before starting."}]', '**Left Ventricular Dysfunction:** Can result in subclinical and clinical cardiac failure. Evaluate left ventricular ejection fraction (LVEF) prior to initiation and regularly during treatment (every 3 cycles in metastatic setting; every 6 weeks in neoadjuvant setting). Withhold dosing for significant LVEF decline.
INSERT INTO "drug_generic" VALUES(2203, 'Protein, fat, carbohydrate, vitamins & minerals', 'Enteral Nutritional Supplement', 'V06DB', 0, 0, 1, 1, 1, 1, 0, 0, '[{"alert_type": "Metabolic Complication", "severity": "High", "trigger_condition": "Initiation in severely malnourished patients", "message": "STOP: Risk of Refeeding Syndrome. Initiate feeding slowly and monitor serum electrolytes (potassium, magnesium, phosphate) closely in severely malnourished patients."}]', '**Refeeding Syndrome:** In severely malnourished patients, rapid initiation of nutritional support can lead to dangerous shifts in fluids and electrolytes (hypophosphatemia, hypokalemia, hypomagnesemia). Initiate slowly and monitor closely.
INSERT INTO "drug_generic" VALUES(2204, 'Diphenhydramine + Phenylephrine', 'Diphenhydramine and Phenylephrine', 'R01BA53', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "CNS Depression and Cardiovascular Risk", "severity": "High", "trigger_condition": "Concurrent use with CNS depressants or MAOIs", "message": "STOP: Diphenhydramine causes marked drowsiness; avoid concurrent use with alcohol or other sedating drugs. Contraindicated within 14 days of MAOI use due to the risk of hypertensive crisis from phenylephrine."}]', '**CNS Depression:** Diphenhydramine may cause marked drowsiness and impair physical or mental abilities. Avoid concurrent use with alcohol or other sedating drugs. A paradoxical excitability reaction may occur, especially in children.
INSERT INTO "drug_generic" VALUES(2205, 'Selexipag', 'Selexipag', 'B01AC27', 0, 1, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Pulmonary Veno-Occlusive Disease (PVOD)", "severity": "High", "trigger_condition": "Development of signs of pulmonary edema", "message": "STOP: If signs of pulmonary edema occur, consider the possibility of associated pulmonary veno-occlusive disease (PVOD). If PVOD is confirmed, discontinue selexipag immediately."}]', '- **Pulmonary Veno-Occlusive Disease (PVOD):** Should signs of pulmonary edema occur during therapy, consider the possibility of PVOD. Discontinue treatment if confirmed.
INSERT INTO "drug_generic" VALUES(2206, 'Minocycline', 'Minocycline', 'J01AA08', 1, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Pediatric and Pregnancy Contraindication", "severity": "High", "trigger_condition": "Use in children <8 years or during pregnancy", "message": "STOP: Minocycline use during tooth development (last half of pregnancy through age 8 years) can cause permanent tooth discoloration (yellow-gray-brown) and enamel hypoplasia. It may also retard skeletal development."}]', '**Tooth Discoloration and Bone Growth:** Use during the last half of pregnancy, infancy, and childhood up to age 8 years may cause permanent discoloration of teeth and reversible inhibition of bone growth.
INSERT INTO "drug_generic" VALUES(2207, 'Sofosbuvir', 'Sofosbuvir', 'J05AP08', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Severe Bradycardia", "severity": "High", "trigger_condition": "Coadministration with Amiodarone", "message": "Serious, potentially fatal symptomatic bradycardia can occur when sofosbuvir is coadministered with amiodarone and another direct-acting antiviral. Coadministration is not recommended."}, {"alert_type": "Hepatitis B Reactivation", "severity": "High", "trigger_condition": "HCV/HBV coinfection", "message": "Test all patients for evidence of current or prior HBV infection before initiating treatment. HBV reactivation has been reported, sometimes resulting in fulminant hepatitis, hepatic failure, and death."}]', 'Sofosbuvir must never be used as monotherapy; it is only indicated as part of a combination regimen. When used with ribavirin or peginterferon alfa, all warnings and precautions for those drugs apply. Extreme caution is required to prevent pregnancy in female patients and female partners of male patients due to the teratogenicity of ribavirin. Monitor for signs of depression or psychiatric illness, especially when used with peginterferon. Monitor complete blood counts regularly due to the risk of anemia and neutropenia associated with combination therapy.', '- Treatment of chronic hepatitis C virus (HCV) infection as a component of a combination antiviral regimen.
INSERT INTO "drug_generic" VALUES(2208, 'Aluminium Oxide + Magnesium Trisilicate', 'Aluminum Oxide and Magnesium Trisilicate', 'A02AD01', 0, 0, 1, 1, 1, 1, 0, 0, '[{"alert_type": "Drug Interactions", "severity": "Medium", "trigger_condition": "Concurrent administration with other oral medications", "message": "STOP: Antacids significantly decrease the absorption of many drugs (e.g., tetracyclines, fluoroquinolones, bisphosphonates). Administer antacids at least 2 hours before or after other medications."}]', '**Renal Impairment:** Use with caution in patients with chronic renal impairment. Magnesium and aluminum can accumulate, leading to hypermagnesemia and aluminum toxicity.
INSERT INTO "drug_generic" VALUES(2209, 'Progesterone inj', 'Progesterone injection', 'G03DA04', 0, 0, 1, 0, 0, 0, 0, 1, '[{"alert_type": "Thromboembolic Risk", "severity": "High", "trigger_condition": "History of or active thromboembolic disorders", "message": "STOP: Progesterone therapy increases the risk of deep vein thrombosis, pulmonary embolism, stroke, and myocardial infarction. Discontinue immediately if a thromboembolic event occurs or is suspected."}]', '**Cardiovascular and Thromboembolic Risks:** Progesterone increases the risk of venous thromboembolism (DVT, PE), stroke, and myocardial infarction. Discontinue immediately if any of these occur. Use with extreme caution in patients with a personal or family history of VTE, obesity, smokers, or those >35 years old.
INSERT INTO "drug_generic" VALUES(2210, 'Abaloparatide', 'Abaloparatide', 'H05AA04', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Risk of Osteosarcoma", "severity": "High", "trigger_condition": "Patients with increased baseline risk of osteosarcoma", "message": "STOP: Abaloparatide caused a dose-dependent increase in osteosarcoma in rats. Avoid use in patients with Paget''s disease, unexplained alkaline phosphatase elevations, open epiphyses, bone metastases, or prior skeletal radiation."}]', '**Risk of Osteosarcoma:** Caused a dose-dependent increase in the incidence of osteosarcoma in rats. Avoid use in patients at increased risk (e.g., Paget''s disease, unexplained elevated alkaline phosphatase, open epiphyses, bone metastases, hereditary disorders predisposing to osteosarcoma, prior skeletal radiation). Cumulative use of abaloparatide and parathyroid hormone analogs (e.g., teriparatide) for more than 2 years during a patient''s lifetime is not recommended.
INSERT INTO "drug_generic" VALUES(2211, 'Albendazole', 'Albendazole', 'P02CA03', 1, 0, 0, 1, 0, 0, 1, 0, '[{"alert_type": "Bone Marrow Suppression", "severity": "High", "trigger_condition": "Prolonged therapy (e.g., for Hydatid disease or Neurocysticercosis)", "message": "STOP: Fatalities associated with albendazole-induced bone marrow suppression, aplastic anemia, and agranulocytosis have been reported. Monitor CBC at the start of each 28-day cycle and every 2 weeks during therapy."}, {"alert_type": "Neurocysticercosis Complications", "severity": "High", "trigger_condition": "Treatment of neurocysticercosis or undiagnosed CNS lesions", "message": "STOP: Dying parasites in the brain can cause severe inflammatory reactions, seizures, and increased intracranial pressure. Co-administration of corticosteroids and anticonvulsants is required."}]', '**Hepatotoxicity:** Reversible elevations of liver enzymes may occur. Monitor LFTs before each treatment cycle and every 2 weeks during therapy. Discontinue if LFTs exceed 2 times the upper limit of normal.
INSERT INTO "drug_generic" VALUES(2212, 'Protamine Sulfate', 'Protamine Sulfate', 'V03AB14', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Severe Hypotension and Anaphylaxis", "severity": "High", "trigger_condition": "Rapid intravenous administration or patient history of fish allergy/vasectomy", "message": "STOP: Rapid IV administration can cause severe hypotension, cardiovascular collapse, and catastrophic pulmonary vasoconstriction. Administer slowly (max 50 mg over 10 minutes). Have resuscitation equipment ready."}]', 'Administer strictly via slow intravenous injection to prevent severe hypotension and anaphylactoid reactions. High risk of hypersensitivity exists in patients with a history of fish allergy, previous vasectomy, severe infertility (due to anti-protamine antibodies), or prior exposure to protamine-containing insulin (e.g., NPH insulin). Monitor hemodynamics continuously. Protamine sulfate can cause noncardiogenic pulmonary edema and catastrophic pulmonary hypertension. Rebound bleeding may occur as the protamine-heparin complex degrades.', '- **Heparin Overdose:** Used to neutralize the anticoagulant effect of unfractionated heparin in cases of severe bleeding or accidental overdose.
INSERT INTO "drug_generic" VALUES(2213, 'Procainamide', 'Procainamide', 'C01BA02', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "High Alert Medicine", "severity": "High", "trigger_condition": "Prescribing or administering antiarrhythmic therapy", "message": "Procainamide is a high-alert medication. It can cause severe hypotension, proarrhythmias, and a lupus-like syndrome. Continuous ECG and blood pressure monitoring are required during IV administration."}]', '**Proarrhythmia:** Like other antiarrhythmics, procainamide can worsen existing arrhythmias or precipitate new ones, including torsades de pointes. Continuous ECG monitoring is required during IV administration.
INSERT INTO "drug_generic" VALUES(2214, 'Sofosbuvir + Velpatasvir', 'Sofosbuvir + Velpatasvir', 'J05AP55', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Hepatitis B Virus Reactivation", "severity": "High", "trigger_condition": "Current or prior HBV infection", "message": "STOP: Test all patients for evidence of current or prior HBV infection before initiating treatment. HBV reactivation has occurred in HCV/HBV coinfected patients, resulting in fulminant hepatitis, hepatic failure, and death."}, {"alert_type": "Severe Bradycardia with Amiodarone", "severity": "High", "trigger_condition": "Coadministration with amiodarone", "message": "STOP: Serious symptomatic bradycardia may occur if coadministered with amiodarone. Coadministration is not recommended."}]', 'Screen all patients for evidence of current or prior Hepatitis B virus (HBV) infection by measuring HBsAg and anti-HBc before initiating treatment. Monitor for clinical and laboratory signs of hepatitis flare or HBV reactivation during and post-treatment.
INSERT INTO "drug_generic" VALUES(2215, 'Ibandronic Acid + Calcium + Vitamin D3', 'Ibandronate + Calcium + Cholecalciferol', 'M05BB04', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Upper Gastrointestinal Adverse Reactions", "severity": "High", "trigger_condition": "Improper administration technique or pre-existing esophageal disease", "message": "STOP: Ibandronic acid can cause severe esophageal irritation, esophagitis, dysphagia, and esophageal ulcers. Patients MUST be able to stand or sit upright for at least 60 minutes after taking the ibandronic acid tablet."}, {"alert_type": "Osteonecrosis of the Jaw (ONJ)", "severity": "High", "trigger_condition": "Invasive dental procedures", "message": "ONJ has been reported in patients treated with bisphosphonates. A routine dental exam is recommended prior to initiating therapy. Avoid invasive dental procedures during treatment if possible."}]', '- **Hypocalcemia:** Must be corrected before initiating therapy. Monitor calcium and mineral metabolism closely.
INSERT INTO "drug_generic" VALUES(2216, 'Sodium Bicarbonate + Citric Acid + Sodium Carbonate', 'Sodium Bicarbonate / Citric Acid / Sodium Carbonate', 'A02AH', 0, 0, 0, 1, 1, 0, 0, 0, '[{"alert_type": "Sodium Load and Fluid Retention", "severity": "Moderate", "trigger_condition": "Patients with heart failure, hypertension, or renal impairment", "message": "Contains high sodium content (575 mg/tablet). Can exacerbate fluid retention, hypertension, and heart failure."}]', '**Sodium Content:** Contains 575 mg of sodium per tablet; use with extreme caution in patients on a sodium-restricted diet, including those with hypertension, congestive heart failure, or edema.
INSERT INTO "drug_generic" VALUES(2217, 'Ondansetron', 'Ondansetron', 'A04AA01', 0, 0, 1, 0, 0, 1, 1, 0, '[{"alert_type": "QT Interval Prolongation", "severity": "High", "trigger_condition": "Concomitant use with QT-prolonging drugs, electrolyte abnormalities, or congenital long QT syndrome", "message": "STOP: Ondansetron prolongs the QT interval in a dose-dependent manner. Avoid in patients with congenital long QT syndrome. Correct hypokalemia and hypomagnesemia prior to administration."}, {"alert_type": "Serotonin Syndrome", "severity": "High", "trigger_condition": "Concomitant use with other serotonergic drugs (e.g., SSRIs, SNRIs, MAOIs)", "message": "Development of serotonin syndrome has been reported with 5-HT3 receptor antagonists. Monitor for altered mental status, autonomic instability, and neuromuscular abnormalities."}]', '**Masking of Ileus:** The use of ondansetron in patients following abdominal surgery or in patients with chemotherapy-induced nausea and vomiting may mask a progressive ileus and/or gastric distension. Monitor bowel function.
INSERT INTO "drug_generic" VALUES(2218, 'Pramoxine + Mineral oil + Zinc oxide rectal prep', 'Pramoxine, Mineral Oil, and Zinc Oxide', 'C05AD07', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Application Site:** For external and intrarectal use only. Do not use in the eyes.
INSERT INTO "drug_generic" VALUES(2219, 'Dextromethorphan + Guaiphenesin + Menthol', 'Dextromethorphan/Guaifenesin/Menthol', 'R05FA02', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Serotonin Syndrome Risk", "severity": "High", "trigger_condition": "Concomitant use of MAOIs", "message": "STOP: Do not use if the patient is taking a prescription monoamine oxidase inhibitor (MAOI) or within 14 days of stopping an MAOI, due to the risk of fatal serotonin syndrome."}]', '**Chronic Cough:** Do not use for persistent or chronic cough associated with smoking, asthma, chronic bronchitis, or emphysema, or if accompanied by excessive phlegm, unless directed by a physician.
INSERT INTO "drug_generic" VALUES(2220, 'Netupitant + Palonosetron', 'Netupitant / Palonosetron', 'A04AA55', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Serotonin Syndrome", "severity": "High", "trigger_condition": "Concomitant use with serotonergic drugs", "message": "Serotonin syndrome has been reported with 5-HT3 receptor antagonists. Monitor for mental status changes, autonomic instability, and neuromuscular symptoms, especially if used with SSRIs, SNRIs, or other serotonergic agents."}]', '**Hypersensitivity Reactions:** Hypersensitivity reactions, including anaphylaxis, have been reported in patients treated with palonosetron, with or without known hypersensitivity to other 5-HT3 receptor antagonists. Discontinue immediately if symptoms occur.
INSERT INTO "drug_generic" VALUES(2221, 'Venetoclax', 'Venetoclax', 'L01XX52', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Tumor Lysis Syndrome (TLS)", "severity": "High", "trigger_condition": "Initiation of therapy and during dose ramp-up phase", "message": "STOP: Venetoclax can cause rapid tumor reduction, leading to severe and potentially fatal Tumor Lysis Syndrome (TLS). Strict adherence to the dose ramp-up schedule, prophylactic hydration, anti-hyperuricemic agents, and frequent blood chemistry monitoring are mandatory."}]', '- **Tumor Lysis Syndrome (TLS):** Fatal cases and renal failure requiring dialysis have occurred. Risk depends on tumor burden, renal function, and splenomegaly. Assess risk prior to initiation. Administer prophylactic hydration and anti-hyperuricemic agents. Monitor blood chemistries (potassium, uric acid, phosphorus, calcium, creatinine) closely during the ramp-up phase.
INSERT INTO "drug_generic" VALUES(2222, 'Sotrovimab (Investigational)', 'Sotrovimab', 'J06BD05', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Severe COVID-19 Worsening", "severity": "High", "trigger_condition": "Administration to patients hospitalized with COVID-19 or requiring oxygen therapy", "message": "STOP: Monoclonal antibodies may be associated with worse clinical outcomes when administered to hospitalized patients requiring high-flow oxygen or mechanical ventilation. Do not use in these populations."}, {"alert_type": "Anaphylaxis and Infusion Reactions", "severity": "High", "trigger_condition": "During or up to 24 hours post-infusion", "message": "STOP: Severe hypersensitivity reactions, including anaphylaxis, have been reported. Discontinue infusion immediately if signs occur and initiate appropriate medical management."}]', '- **Hypersensitivity:** Monitor patients during the infusion and observe for at least 1 hour after the infusion is complete for signs of hypersensitivity or infusion-related reactions (e.g., fever, chills, nausea, headache, bronchospasm, hypotension, angioedema).
INSERT INTO "drug_generic" VALUES(2223, 'Osilodrostat', 'Osilodrostat', 'H02CA02', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Hypocortisolism", "severity": "High", "trigger_condition": "Signs of adrenal insufficiency (nausea, vomiting, fatigue, hypotension)", "message": "STOP: Osilodrostat can cause severe, life-threatening hypocortisolism (adrenal insufficiency). Monitor cortisol levels closely. If hypocortisolism occurs, reduce the dose, interrupt treatment, and/or administer exogenous glucocorticoids."}]', '**Hypocortisolism:** Lowers cortisol levels and can lead to hypocortisolism and life-threatening adrenal insufficiency. Symptoms include nausea, vomiting, fatigue, abdominal pain, dizziness, hypotension, and hypoglycemia. Monitor 24-hour urine free cortisol (UFC), serum/plasma cortisol, and clinical signs. Evaluate for precipitating causes (e.g., infection, stress).
INSERT INTO "drug_generic" VALUES(2224, 'Fremanezumab', 'Fremanezumab', 'N02CD03', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Signs of hypersensitivity", "message": "STOP: Hypersensitivity reactions (e.g., rash, pruritus, urticaria) have been reported within hours to 1 month following administration. Consider discontinuing therapy if a severe reaction occurs."}]', 'Hypersensitivity reactions (e.g., rash, pruritus, drug hypersensitivity, urticaria) have been reported within hours to 1 month following administration in clinical trials; some reactions led to discontinuation or required corticosteroid treatment. Consider discontinuing therapy, and institute appropriate therapy if a hypersensitivity reaction occurs.', '- **Migraine Prophylaxis:** Indicated for the preventive treatment of migraine in adults.', '**Hypersensitivity:** Contraindicated in patients with a history of serious hypersensitivity reactions to fremanezumab or any of its excipients.', '- **Injection site reactions** (pain, induration, erythema) (43-45%)
INSERT INTO "drug_generic" VALUES(2225, 'Salicylic acid + Coal tar Topical', 'Salicylic Acid and Coal Tar', 'D05AA', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Photosensitivity Risk", "severity": "Moderate", "trigger_condition": "Exposure to sunlight or UV radiation after application", "message": "Coal tar significantly increases sensitivity to sunlight. Avoid exposure to direct sunlight and sunlamps for at least 24 to 72 hours after application to prevent severe sunburn."}]', 'Use with extreme caution on the face, and strictly avoid contact with the eyes and mucous membranes. If contact occurs, rinse thoroughly with water.
INSERT INTO "drug_generic" VALUES(2226, 'Anhydrous Glucose + Citric Acid + Potassium Chloride', 'Oral Rehydration Salts', 'A07CA', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Reconstitution Error", "severity": "High", "trigger_condition": "Improper dilution of powder or tablets", "message": "STOP: Use fresh drinking water ONLY to mix the formula. Never dilute with milk, soft drinks, or cordials. A stronger solution than recommended can cause fatal hypernatremia."}]', '**Severe Dehydration:** Oral rehydration is not sufficient for patients with severe dehydration, shock, very large stool losses (>10 mL/kg/hour), or severe vomiting. Intravenous fluid replacement is required in these cases.
INSERT INTO "drug_generic" VALUES(2227, 'Ipilimumab', 'Ipilimumab', 'L01FX04', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Severe and Fatal Immune-Mediated Adverse Reactions", "severity": "High", "trigger_condition": "Patients presenting with severe diarrhea, abdominal pain, jaundice, or severe rash", "message": "STOP: Severe and fatal immune-mediated adverse reactions (enterocolitis, hepatitis, dermatitis, neuropathies, endocrinopathies) can occur. Withhold therapy and initiate high-dose corticosteroids promptly if suspected."}]', '**Immune-Mediated Enterocolitis:** Severe, life-threatening, or fatal immune-mediated enterocolitis can occur. Monitor for diarrhea, abdominal pain, blood or mucus in stool. Administer systemic corticosteroids for severe cases.
INSERT INTO "drug_generic" VALUES(2228, 'Betamethasone 0.05% + Lidocaine Hydrochloride 2.5%+ Phenylephrine Hydrochloride 0.1% (Rectal prep)', 'Betamethasone, Lidocaine, and Phenylephrine', 'C05AD', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Systemic Absorption", "severity": "Medium", "trigger_condition": "Prolonged use or application to severely damaged mucosa", "message": "STOP: Prolonged use or application to bleeding/damaged rectal mucosa can lead to significant systemic absorption of corticosteroids (HPA axis suppression), lidocaine (CNS/cardiac toxicity), and phenylephrine (hypertension)."}]', '**Systemic Corticosteroid Effects:** Prolonged use may lead to systemic absorption, causing reversible hypothalamic-pituitary-adrenal (HPA) axis suppression, Cushing''s syndrome, hyperglycemia, and osteoporosis. Withdraw gradually after long-term therapy.
INSERT INTO "drug_generic" VALUES(2229, 'Tavaborole topical', 'Tavaborole', 'D01AE22', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Flammability", "severity": "Moderate", "trigger_condition": "Use near heat or open flame", "message": "Tavaborole topical solution is flammable. Avoid use near heat or open flame until the solution has completely dried on the nail."}]', '**Application Site Reactions:** Local irritation, erythema, and exfoliation may occur. If severe irritation develops, consider interrupting therapy.
INSERT INTO "drug_generic" VALUES(2230, 'Bromfenac Sodium eye prep', 'Bromfenac ophthalmic', 'S01BC11', 0, 0, 0, 1, 0, 1, 0, 0, '[{"alert_type": "Corneal Healing and Melting", "severity": "High", "trigger_condition": "Prolonged use or use in patients with complicated ocular surgeries/corneal defects", "message": "WARNING: Use of topical NSAIDs may result in keratitis. Continued use in susceptible patients may lead to epithelial breakdown, corneal thinning, erosion, ulceration, or perforation, which may be sight-threatening. Discontinue immediately if corneal epithelial breakdown occurs."}]', 'Topical NSAIDs can slow or delay healing. Concomitant use of topical NSAIDs and topical steroids may increase the potential for healing problems.
INSERT INTO "drug_generic" VALUES(2231, 'Guselkumab', 'Guselkumab', 'L04AC16', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Serious Infections and Tuberculosis", "severity": "High", "trigger_condition": "Active infection or latent TB", "message": "STOP: May increase the risk of infection. Evaluate for tuberculosis (TB) prior to initiating treatment. Do not administer to patients with clinically important active infections."}]', '**Infections:** May increase the risk of infections. Treatment should not be initiated in patients with any clinically important active infection until the infection resolves or is adequately treated. Consider the risks and benefits prior to prescribing in patients with a chronic infection or a history of recurrent infection.
INSERT INTO "drug_generic" VALUES(2232, 'Voglibose', 'Voglibose', 'A10BF03', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hypoglycemia Management", "severity": "High", "trigger_condition": "Hypoglycemic episode while on concurrent antidiabetic therapy", "message": "STOP: If hypoglycemia occurs, it MUST be treated with oral glucose (dextrose), NOT sucrose (table sugar). Voglibose prevents the breakdown of sucrose into absorbable monosaccharides."}]', '**Gastrointestinal Disorders:** Use with caution in patients with a history of laparotomy, ileus, or Roemheld''s syndrome, as increased intestinal gas can exacerbate these conditions.
INSERT INTO "drug_generic" VALUES(2233, 'Patiromer', 'Patiromer', 'V03AE09', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Drug Interactions", "severity": "Moderate", "trigger_condition": "Concomitant administration of other oral medications", "message": "STOP: Patiromer binds many orally administered medications. Administer other oral medications at least 3 hours before or 3 hours after patiromer."}]', '**Drug Interactions:** Patiromer binds many orally administered medications, which could decrease their gastrointestinal absorption and lead to reduced efficacy. Administer other oral medications at least 3 hours before or 3 hours after patiromer.
INSERT INTO "drug_generic" VALUES(2234, 'Purified Soybean Oil', 'Soybean Oil, Lipid Emulsion', 'B05BA02', 0, 1, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Fat Overload Syndrome", "severity": "High", "trigger_condition": "Rapid infusion or impaired lipid clearance", "message": "STOP: Monitor serum triglycerides closely. Rapid infusion or impaired clearance can lead to Fat Overload Syndrome, characterized by hyperlipidemia, fever, hepatosplenomegaly, coagulopathy, and coma."}]', '**Impaired Lipid Metabolism:** Administer with extreme caution in patients with conditions that impair lipid clearance, such as renal insufficiency, uncompensated diabetes mellitus, pancreatitis, hypothyroidism (if hypertriglyceridemic), and sepsis. Close monitoring of serum triglycerides is obligatory.
INSERT INTO "drug_generic" VALUES(2235, 'Multivitamin & Multimineral Prenatal', 'Prenatal Multivitamins and Minerals', 'A11AA03', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Iron Toxicity", "severity": "High", "trigger_condition": "Accidental overdose in children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '**Pernicious Anemia:** Folic acid in doses above 0.1 mg daily may obscure pernicious anemia; hematological remission can occur while neurological manifestations remain progressive. Ensure proper diagnosis if anemia is severe.
INSERT INTO "drug_generic" VALUES(2236, 'Simvastatin', 'Simvastatin', 'C10AA01', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis Risk", "severity": "High", "trigger_condition": "Concurrent use with strong CYP3A4 inhibitors or high-dose therapy (80 mg)", "message": "STOP: Simvastatin is associated with a dose-dependent risk of myopathy and rhabdomyolysis. Concurrent use with strong CYP3A4 inhibitors is strictly contraindicated."}]', 'Use with extreme caution in patients with a history of liver disease or heavy alcohol consumption. Discontinue treatment if there is a marked or persistent increase in serum aminotransferase concentrations (greater than 3 times the upper limit of normal). There is an increased risk of rhabdomyolysis in patients experiencing severe infection, hypotension, major surgical trauma, uncontrolled seizures, or severe metabolic, endocrine, and electrolyte disorders. Temporarily withhold therapy in any patient experiencing an acute or serious condition predisposing to the development of renal failure secondary to rhabdomyolysis. Monitor creatine kinase (CK) periodically and liver function tests (LFTs) at baseline and as clinically indicated. Discontinue therapy immediately if there is a significant or persistent increase in CK levels, serum aminotransferase levels, or clinical evidence of myopathy (unexplained muscle pain, tenderness, or weakness).', '- **Primary Hypercholesterolemia (Type IIa and IIb):** Used as an adjunct to diet to reduce elevated total cholesterol, LDL-C, apolipoprotein B, and triglycerides, and to increase HDL-C in patients who have not responded adequately to dietary modifications.
INSERT INTO "drug_generic" VALUES(2237, 'Cinchocaine Hydrochloride Topical', 'Dibucaine Topical', 'D04AB04', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Systemic Toxicity", "severity": "High", "trigger_condition": "Application to large surface areas, broken skin, or under occlusive dressings", "message": "Excessive systemic absorption can lead to severe central nervous system toxicity (seizures) and cardiovascular collapse. Use the lowest effective dose."}]', '**Systemic Absorption:** Avoid application for prolonged periods, to extensive areas of the body, or under occlusive dressings, as this significantly increases systemic absorption and the risk of toxicity.
INSERT INTO "drug_generic" VALUES(2238, 'Benzocaine + Oxytetracycline + Polymyxin B Eye prep', 'Benzocaine, Oxytetracycline, and Polymyxin B Ophthalmic', 'S01AA30', 1, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Ophthalmic Use Only", "severity": "Low", "message": "For topical ophthalmic use only. Do not inject into the eye or use systemically."}]', '**Visual Disturbances:** Ophthalmic preparations may cause temporary blurred vision immediately after application. Patients should be cautioned against driving or operating machinery until vision clears.
INSERT INTO "drug_generic" VALUES(2239, 'Elexacaftor + Tezacaftor + Ivacaftor', 'Elexacaftor, Tezacaftor, and Ivacaftor', 'R07AX32', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Elevated transaminases or bilirubin", "message": "STOP: Elevated liver transaminases and bilirubin levels have been observed. Measure LFTs before initiating, every 3 months during the first year, and annually thereafter. Interrupt dosing for significant elevations."}]', '**Hepatotoxicity:** Elevated transaminases (ALT/AST) and bilirubin have been observed. Assess liver function tests (ALT, AST, and bilirubin) prior to initiating therapy, every 3 months during the first year of treatment, and annually thereafter. Consider more frequent monitoring in patients with a history of hepatobiliary disease. Interrupt dosing if ALT or AST is >5x ULN, or if ALT or AST is >3x ULN with bilirubin >2x ULN.
INSERT INTO "drug_generic" VALUES(2240, 'Empagliflozin + Metformin', 'Empagliflozin + Metformin', 'A10BD20', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Lactic Acidosis Risk", "severity": "High", "trigger_condition": "Renal impairment, sepsis, hypoxia, or radiologic studies with iodinated contrast", "message": "STOP: Metformin can cause severe, potentially fatal lactic acidosis. Discontinue immediately if signs of severe metabolic acidosis occur. Temporarily withhold prior to iodinated contrast imaging procedures in patients with eGFR <60 mL/min/1.73 m2."}, {"alert_type": "Diabetic Ketoacidosis (DKA)", "severity": "High", "trigger_condition": "Acute illness, surgery, or caloric restriction", "message": "STOP: SGLT2 inhibitors can cause euglycemic diabetic ketoacidosis. Assess for ketoacidosis if patient presents with nausea, vomiting, or abdominal pain, regardless of blood glucose level."}]', '**Lactic Acidosis:** Metformin accumulation can cause lactic acidosis. Risk factors include renal impairment, sepsis, dehydration, excess alcohol intake, hepatic impairment, and acute congestive heart failure. 
INSERT INTO "drug_generic" VALUES(2241, 'Sotorasib', 'Sotorasib', 'L01XX73', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Initiation of therapy and during treatment", "message": "STOP: Can cause severe hepatotoxicity. Monitor liver function tests (ALT, AST, bilirubin) before initiation, every 3 weeks for the first 3 months, then monthly or as clinically indicated."}, {"alert_type": "Interstitial Lung Disease (ILD)/Pneumonitis", "severity": "High", "trigger_condition": "New or worsening pulmonary symptoms", "message": "STOP: Severe and fatal ILD/pneumonitis has been reported. Withhold treatment for suspected ILD/pneumonitis and permanently discontinue if confirmed."}]', 'Monitor liver function tests (LFTs) prior to initiation, every 3 weeks for the first 3 months of treatment, and then monthly or as clinically indicated. Increase the frequency of monitoring in patients who develop transaminase or bilirubin elevations. Based on the severity of hepatotoxicity, withhold, dose-reduce, or permanently discontinue the drug, and consider treatment with systemic corticosteroids.
INSERT INTO "drug_generic" VALUES(2242, 'Amino Acids (5 % & 10%) + Dextrose + Electrolytes', 'Amino Acids, Dextrose, and Electrolytes', 'B05BA10', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Pulmonary Embolism Risk", "severity": "High", "trigger_condition": "Formation of pulmonary vascular precipitates", "message": "STOP: Fatal pulmonary embolism due to precipitates has occurred. Inspect solutions visually. If signs of pulmonary distress occur, stop the infusion immediately and initiate a medical evaluation."}]', '**Refeeding Syndrome:** Refeeding severely undernourished patients may result in the refeeding syndrome, characterized by intracellular shift of potassium, phosphorus, and magnesium as the patient becomes anabolic. Monitor electrolytes closely.
INSERT INTO "drug_generic" VALUES(2243, 'Prilocaine', 'Prilocaine', 'N01BB04', 0, 1, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Methemoglobinemia Risk", "severity": "High", "trigger_condition": "Doses exceeding 600 mg or use in susceptible patients", "message": "STOP: Prilocaine metabolism yields o-toluidine, which can cause severe methemoglobinemia. Monitor for cyanosis and hypoxia. Have methylene blue available."}]', '**Methemoglobinemia:** Prilocaine is metabolized to o-toluidine, a known inducer of methemoglobinemia. Administration of doses greater than 600 mg to adults significantly increases the risk. Patients with glucose-6-phosphate dehydrogenase (G6PD) deficiency, congenital or idiopathic methemoglobinemia, cardiac or pulmonary compromise, and those exposed to concurrent oxidizing agents are highly susceptible. Monitor for cyanosis, headache, tachycardia, and fatigue.
INSERT INTO "drug_generic" VALUES(2244, 'Finasteride', 'Finasteride', 'G04CB01', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Teratogenicity Risk", "severity": "High", "trigger_condition": "Handling by pregnant women", "message": "STOP: Women who are or may potentially be pregnant must not handle crushed or broken finasteride tablets due to the risk of percutaneous absorption and subsequent teratogenic effects on a male fetus."}]', '- **Prostate Cancer Evaluation:** Finasteride causes a decrease in serum prostate-specific antigen (PSA) levels by approximately 50%. Establish a new baseline PSA after 6 months of therapy. Any confirmed increase in PSA while on finasteride should be carefully evaluated for prostate cancer.
INSERT INTO "drug_generic" VALUES(2245, 'Beclomethasone + Miconazole Topical', 'Beclomethasone and Miconazole Topical', 'D07BC04', 0, 0, 0, 0, 0, 0, 0, 1, '[]', '**Systemic Absorption:** Prolonged use, application to large surface areas, or use under occlusive dressings can lead to systemic absorption of beclomethasone, resulting in reversible HPA axis suppression, Cushing''s syndrome, hyperglycemia, and glucosuria.
INSERT INTO "drug_generic" VALUES(2246, 'Nimotuzumab', 'Nimotuzumab', 'L01XC', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Infusion Reactions", "severity": "High", "trigger_condition": "During or shortly after intravenous infusion", "message": "STOP: Severe infusion-related reactions, including anaphylaxis, chills, pyrexia, and fluctuations in blood pressure, can occur. Resuscitation equipment and medications must be immediately available during administration."}]', '**Decompensated Chronic Diseases:** Use with extreme caution in patients with chronic diseases in a decompensated phase, such as severe cardiac dysfunction, uncontrolled diabetes mellitus, or severe arterial hypertension.
INSERT INTO "drug_generic" VALUES(2247, 'Lodoxamide', 'Lodoxamide tromethamine', 'S01GX05', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Contact Lens Precaution", "severity": "Low", "trigger_condition": "Patient wears soft contact lenses", "message": "Contains benzalkonium chloride, which may be absorbed by soft contact lenses. Instruct patients to remove contact lenses prior to administration and wait at least 15 minutes before reinserting them."}]', '**Contact Lens Use:** The ophthalmic solution contains the preservative benzalkonium chloride, which can discolor soft contact lenses. Patients should be instructed to remove contact lenses prior to administration and wait at least 15 minutes before reinserting them. Furthermore, contact lenses should not be worn if the eyes are red or actively inflamed.
INSERT INTO "drug_generic" VALUES(2248, 'Cetrimide + Chlorhexidine Gluconate Topical', 'Cetrimide and Chlorhexidine Gluconate', 'D08AC52', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Moderate", "trigger_condition": "Application near sensitive areas", "message": "Avoid contact with the eyes, middle ear, meninges, and mucous membranes. If accidental contact occurs, rinse thoroughly with water immediately."}]', '**Hypersensitivity Reactions:** Prolonged and repeated use may increase the risk of hypersensitivity reactions, including contact dermatitis. Discontinue use if severe irritation or rash develops.
INSERT INTO "drug_generic" VALUES(2249, 'Tetrabenazine', 'Tetrabenazine', 'N05CB02', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Depression and Suicidality", "severity": "High", "trigger_condition": "Patients with Huntington''s disease or a history of depression", "message": "STOP: Tetrabenazine can increase the risk of depression and suicidal thoughts and behavior. Contraindicated in patients who are actively suicidal or have untreated/inadequately treated depression. Monitor closely for clinical worsening."}]', '- **Depression and Suicidality:** High risk of exacerbating or precipitating depression and suicidal ideation, particularly in patients with Huntington''s disease. Monitor closely.
INSERT INTO "drug_generic" VALUES(2250, 'Liposome + Perilla + Sodium Hyaluronate', 'Liposome, Perilla Extract, and Sodium Hyaluronate Ophthalmic', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Ocular Irritation", "severity": "Low", "trigger_condition": "Persistent symptoms after application", "message": "If eye pain, changes in vision, or continued redness and irritation occur, discontinue use immediately and consult an ophthalmologist."}]', '**Contact Lenses:** If the preparation contains preservatives, contact lenses should be removed prior to application and reinserted no earlier than 15 minutes afterward. (Check specific product labeling, as many liposomal sprays are safe to use over contact lenses).
INSERT INTO "drug_generic" VALUES(2251, 'Atorvastatin', 'Atorvastatin', 'C10AA05', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Myopathy and Rhabdomyolysis", "severity": "High", "trigger_condition": "Unexplained muscle pain, tenderness, or weakness", "message": "STOP: Atorvastatin can cause severe myopathy and rhabdomyolysis, leading to acute renal failure. Discontinue immediately if markedly elevated CPK levels occur or myopathy is diagnosed/suspected."}]', '**Hepatic Dysfunction:** Increases in serum transaminases have occurred. Rare reports of fatal and non-fatal hepatic failure exist. Test liver enzymes before initiating therapy and as clinically indicated. Discontinue if serious hepatic injury occurs.
INSERT INTO "drug_generic" VALUES(2252, 'Butorphanol', 'Butorphanol', 'N02AF01', 0, 1, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Addiction, Abuse, and Misuse", "severity": "High", "trigger_condition": "Prescription of opioid analgesic", "message": "STOP: Butorphanol exposes patients and other users to the risks of opioid addiction, abuse, and misuse, which can lead to overdose and death. Assess each patient''s risk prior to prescribing."}, {"alert_type": "Life-Threatening Respiratory Depression", "severity": "High", "trigger_condition": "Concomitant use with CNS depressants or high doses", "message": "STOP: Serious, life-threatening, or fatal respiratory depression may occur. Monitor for respiratory depression, especially during initiation or following a dose increase."}]', '**Respiratory Depression:** Significant respiratory depression can occur; use with extreme caution in patients with chronic obstructive pulmonary disease (COPD), cor pulmonale, or pre-existing respiratory compromise.
INSERT INTO "drug_generic" VALUES(2253, 'Midodrine', 'Midodrine', 'C01CA17', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Supine Hypertension", "severity": "High", "trigger_condition": "Patient resting or sleeping in a supine position", "message": "STOP: Midodrine can cause severe supine hypertension. Do not administer the last dose later than 6 PM or less than 4 hours before bedtime. Monitor supine and sitting blood pressure regularly."}]', '**Supine Hypertension:** Can cause marked elevation of supine blood pressure. Monitor supine and sitting blood pressure regularly. Avoid dosing within 4 hours of bedtime.
INSERT INTO "drug_generic" VALUES(2254, 'Ospemifene', 'Ospemifene', 'G03XC05', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Endometrial Cancer and Cardiovascular Risk", "severity": "High", "trigger_condition": "Use in postmenopausal women", "message": "STOP: Ospemifene acts as an estrogen agonist in the endometrium, increasing the risk of endometrial hyperplasia and cancer. It also increases the risk of DVT, stroke, and MI. Investigate any abnormal vaginal bleeding immediately."}]', '**Endometrial Hyperplasia and Cancer:** Ospemifene has an agonistic effect on the endometrium. Monitor for any undiagnosed persistent or recurring abnormal genital bleeding to rule out malignancy. Concomitant use of a progestin may be considered in women with a uterus, though safety data are limited.
INSERT INTO "drug_generic" VALUES(2255, 'Alpelisib', 'Alpelisib', 'L01EM03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Hypersensitivity and Cutaneous Reactions", "severity": "High", "trigger_condition": "Onset of rash, fever, or mucosal lesions", "message": "STOP: Severe hypersensitivity (anaphylaxis) and severe cutaneous adverse reactions (SCARs), including Stevens-Johnson syndrome (SJS), can occur. Permanently discontinue if confirmed."}]', '**Severe Hypersensitivity:** Anaphylaxis and anaphylactic shock have been reported. Discontinue permanently if severe hypersensitivity occurs.
INSERT INTO "drug_generic" VALUES(2256, 'Sodium Chloride 3%', 'Hypertonic Saline (3% Sodium Chloride)', 'B05BB01', 0, 1, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Osmotic Demyelination Syndrome", "severity": "High", "trigger_condition": "Rapid correction of chronic hyponatremia", "message": "STOP: High Alert Medication. Rapid correction of hyponatremia (>8-12 mEq/L in 24 hours) can cause irreversible osmotic demyelination syndrome (central pontine myelinolysis). Monitor serum sodium frequently."}]', '**Fluid Overload:** Use with extreme caution in patients with heart failure, severe renal impairment, liver cirrhosis, peripheral or pulmonary edema, or preeclampsia, as it can precipitate acute volume overload and pulmonary edema.
INSERT INTO "drug_generic" VALUES(2257, 'Glipizide', 'Glipizide', 'A10BB07', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hypoglycemia Risk", "severity": "High", "trigger_condition": "Use in elderly, malnourished, or renally/hepatically impaired patients", "message": "Severe hypoglycemia can occur. Proper patient selection, dosage, and instructions are critical. Initiate at lower doses in vulnerable populations and titrate cautiously."}]', 'All sulfonylureas are capable of producing severe hypoglycemia. The risk is increased in elderly, debilitated, or malnourished patients, and those with adrenal, pituitary, renal, or hepatic insufficiency. Monitor blood glucose concentrations regularly. During periods of metabolic stress (e.g., fever, trauma, infection, surgery), a temporary loss of glycemic control may occur, necessitating a temporary switch to insulin therapy. Caution is advised in patients with G6PD deficiency due to the risk of hemolytic anemia. Glipizide has a shorter half-life than glibenclamide, which may reduce the risk of prolonged hypoglycemia, but severe episodes can still occur.', '- **Type 2 Diabetes Mellitus:** Indicated as an adjunct to diet and exercise to improve glycemic control in adults with type 2 diabetes mellitus.
INSERT INTO "drug_generic" VALUES(2258, 'Magnesium Oxide', 'Magnesium Oxide', 'A12CC10', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Hypermagnesemia Risk", "severity": "High", "trigger_condition": "Severe renal impairment (CrCl < 30 mL/min)", "message": "STOP: High risk of fatal hypermagnesemia. Avoid use or monitor serum magnesium levels strictly."}]', 'Use with extreme caution in patients with renal impairment due to the risk of hypermagnesemia and subsequent toxicity.
INSERT INTO "drug_generic" VALUES(2259, 'Glucagon', 'Glucagon', 'H04AA01', 0, 0, 1, 1, 0, 0, 1, 0, '[]', '**Depleted Glycogen Stores:** Glucagon is effective in treating hypoglycemia only if sufficient hepatic glycogen is present. It is ineffective in states of starvation, adrenal insufficiency, or chronic hypoglycemia.
INSERT INTO "drug_generic" VALUES(2260, 'Vildagliptin', 'Vildagliptin', 'A10BH02', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hepatic Dysfunction", "severity": "High", "trigger_condition": "Pre-treatment ALT or AST >3 times the upper limit of normal (ULN)", "message": "STOP: Vildagliptin is contraindicated in patients with hepatic impairment or elevated transaminases (>3x ULN). Monitor liver function tests prior to initiation, every 3 months for the first year, and periodically thereafter."}]', '**Heart Failure:** Use with caution in patients with heart failure. It is not recommended in patients with NYHA functional class IV heart failure due to lack of clinical experience.
INSERT INTO "drug_generic" VALUES(2261, 'Infliximab', 'Infliximab', 'L04AB02', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Serious Infections and Malignancy", "severity": "High", "trigger_condition": "Initiation of therapy or presence of chronic/recurrent infection", "message": "STOP: Increased risk of serious, potentially fatal infections (e.g., active tuberculosis, invasive fungal infections, bacterial sepsis). Lymphoma and other malignancies have also been reported. Evaluate for active or latent TB prior to initiation."}]', '**Infection Risk:** Patients are at increased risk for developing serious infections that may lead to hospitalization or death. Discontinue if a patient develops a serious infection or sepsis.
INSERT INTO "drug_generic" VALUES(2262, 'Prednisolone 1%  Eye prep', 'Prednisolone Acetate Ophthalmic', 'S01BA04', 0, 0, 0, 0, 0, 1, 1, 1, '[{"alert_type": "Ocular Toxicity and Infection Risk", "severity": "High", "trigger_condition": "Prolonged use (>10 days)", "message": "STOP: Prolonged use of ophthalmic corticosteroids can cause elevated intraocular pressure (glaucoma), optic nerve damage, cataract formation, and severe secondary ocular infections. Routine IOP monitoring is mandatory."}]', '- **Intraocular Pressure (IOP):** Prolonged use may result in ocular hypertension/glaucoma, damage to the optic nerve, and defects in visual acuity and fields. Monitor IOP routinely if used for 10 days or longer.
INSERT INTO "drug_generic" VALUES(2263, 'Esomeprazole Magnesium Trihydrate', 'Esomeprazole', 'A02BC05', 0, 0, 1, 0, 0, 0, 1, 1, '[{"alert_type": "Clostridioides difficile-Associated Diarrhea", "severity": "High", "trigger_condition": "Development of severe, persistent diarrhea during or after therapy", "message": "STOP: Proton pump inhibitors increase the risk of C. difficile-associated diarrhea. Evaluate patients presenting with persistent diarrhea and discontinue therapy if confirmed."}]', 'Symptomatic response to therapy does not preclude the presence of gastric malignancy; consider additional follow-up and diagnostic testing in adult patients who have a suboptimal response or an early symptomatic relapse. Prolonged use (typically >1 year) may increase the risk of osteoporosis-related fractures of the hip, wrist, or spine; use the lowest effective dose for the shortest duration. Hypomagnesemia, symptomatic and asymptomatic, has been reported rarely in patients treated with PPIs for at least 3 months, and in most cases after a year of therapy; monitor magnesium levels prior to initiation and periodically thereafter if prolonged treatment is expected. Daily treatment with any acid-suppressing medications over a long period (e.g., longer than 3 years) may lead to malabsorption of cyanocobalamin (Vitamin B12). Cutaneous and systemic lupus erythematosus have been reported as adverse events in patients receiving PPIs; discontinue if signs or symptoms occur. Acute tubulointerstitial nephritis has been observed in patients taking PPIs.', '- **Gastroesophageal Reflux Disease (GERD):** Healing of erosive esophagitis and maintenance of healing; treatment of symptomatic GERD.
INSERT INTO "drug_generic" VALUES(2264, 'Sulphadimidine', 'Sulfamethazine', 'J01EB03', 1, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Severe Hypersensitivity and Blood Dyscrasias", "severity": "High", "trigger_condition": "History of sulfonamide allergy or development of rash", "message": "STOP: Fatalities associated with severe reactions (Stevens-Johnson syndrome, toxic epidermal necrolysis, fulminant hepatic necrosis, agranulocytosis, aplastic anemia) have occurred. Discontinue at the first sign of skin rash."}]', '**Crystalluria:** High risk of crystalluria and renal damage. Ensure adequate fluid intake to maintain high urine output; alkalinization of urine may be necessary.
INSERT INTO "drug_generic" VALUES(2265, 'Azelastine + Fluticasone Propionate Nasal  prep', 'Azelastine and Fluticasone Nasal', 'R01AD58', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "CNS Depression", "severity": "Moderate", "trigger_condition": "Concomitant use of alcohol or CNS depressants", "message": "WARNING: May cause somnolence. Avoid operating heavy machinery or driving until the effect is known. Avoid concurrent use with alcohol or other CNS depressants."}]', '**Somnolence:** Azelastine may cause somnolence. Patients should avoid engaging in hazardous occupations requiring complete mental alertness and motor coordination (e.g., driving, operating machinery) until they know how the drug affects them.
INSERT INTO "drug_generic" VALUES(2266, 'Ibutilide', 'Ibutilide', 'C01BD04', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Proarrhythmic Risk", "severity": "High", "trigger_condition": "Administration without continuous ECG monitoring or in patients with prolonged QTc", "message": "STOP: Ibutilide can cause potentially fatal arrhythmias, including sustained polymorphic ventricular tachycardia (Torsades de Pointes). Must be administered in a setting with continuous ECG monitoring and personnel trained in arrhythmia management."}]', '**Arrhythmia Risk:** Can induce potentially fatal arrhythmias, particularly polymorphic ventricular tachycardia (Torsades de Pointes). Continuous ECG monitoring is mandatory during infusion and for at least 4 to 6 hours post-infusion, or until the QTc interval returns to baseline.
INSERT INTO "drug_generic" VALUES(2267, 'Pethidine Hydrochloride', 'Meperidine', 'N02AB02', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Fatal Serotonin Syndrome and Neurotoxicity", "severity": "High", "trigger_condition": "Concurrent use with MAOIs or use in renal impairment", "message": "STOP: Pethidine is strictly contraindicated with MAOIs (fatal serotonin syndrome). Avoid use in renal impairment or for prolonged periods due to accumulation of the toxic metabolite normeperidine, which causes severe seizures."}]', '- **Neurotoxicity (Normeperidine Accumulation):** Pethidine is metabolized to normeperidine, a neurotoxic metabolite. Accumulation causes tremors, myoclonus, and seizures. Avoid prolonged use (>48 hours) or doses >600 mg/day.
INSERT INTO "drug_generic" VALUES(2268, 'Light kaolin + Silver sulfadiazine (Cutaneous Spray)', 'Kaolin and Silver Sulfadiazine', 'D06BA51', 1, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Sulfonamide Hypersensitivity", "severity": "High", "trigger_condition": "Patient history of severe allergy to sulfonamides", "message": "STOP: Silver sulfadiazine is a sulfonamide derivative. Severe allergic reactions, including Stevens-Johnson syndrome, can occur. Verify allergy history before application."}]', '**Prolonged Use:** It is recommended not to use the product for more than 4 weeks to prevent potential systemic absorption of silver or sulfadiazine, which could lead to argyria or systemic sulfonamide toxicity.
INSERT INTO "drug_generic" VALUES(2269, 'Lixisenatide', 'Lixisenatide', 'A10BJ03', 0, 0, 0, 0, 1, 1, 0, 0, '[{"alert_type": "Acute Pancreatitis", "severity": "High", "trigger_condition": "Severe, persistent abdominal pain", "message": "STOP: Acute pancreatitis, including fatal and non-fatal hemorrhagic or necrotizing pancreatitis, has been observed in patients treated with GLP-1 receptor agonists. Discontinue promptly if pancreatitis is suspected. Do not restart if confirmed."}]', '**Pancreatitis:** Acute pancreatitis has been reported. Observe patients carefully for signs and symptoms of pancreatitis (persistent severe abdominal pain, sometimes radiating to the back, with or without vomiting). If suspected, discontinue lixisenatide promptly.
INSERT INTO "drug_generic" VALUES(2270, 'Fluticasone Propionate Nasal prep', 'Fluticasone Propionate', 'R01AD08', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Local Nasal Effects:** Epistaxis, nasal ulceration, and nasal septal perforation have been reported. Monitor patients periodically for signs of adverse effects on the nasal mucosa.
INSERT INTO "drug_generic" VALUES(2271, '5 Aminosalicylic Acid (Mesalamine/Mesalazine)', 'Mesalamine', 'A07EC02', 0, 0, 1, 0, 1, 0, 1, 0, '[{"alert_type": "Mesalamine-Induced Acute Intolerance Syndrome", "severity": "High", "trigger_condition": "New onset of cramping, acute abdominal pain, bloody diarrhea, fever, headache, and rash after initiation", "message": "STOP: Symptoms may resemble an exacerbation of inflammatory bowel disease. Discontinue immediately if acute intolerance syndrome is suspected."}]', '**Renal Impairment:** Renal impairment, including minimal change disease, acute and chronic interstitial nephritis, and renal failure, has been reported. Evaluate renal function prior to initiation and periodically during therapy.
INSERT INTO "drug_generic" VALUES(2272, 'Ketoconazole 2% shampoo/bar/lotion', 'Ketoconazole Topical', 'D01AC08', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Ocular Irritation", "severity": "Low", "trigger_condition": "Application near the eyes", "message": "Avoid contact with the eyes. If the shampoo or lotion enters the eyes, rinse immediately and thoroughly with plenty of water."}]', '**Topical Corticosteroid Withdrawal:** In patients who have been on prolonged treatment with topical corticosteroids, abruptly stopping the steroid can cause a rebound flare. It is recommended to gradually withdraw the steroid therapy over 2 to 3 weeks while initiating ketoconazole therapy.
INSERT INTO "drug_generic" VALUES(2273, 'Methenamine + Hyoscyamine', 'Methenamine and Hyoscyamine', 'G04BD', 1, 0, 0, 0, 1, 0, 0, 0, '[]', '**Methenamine Component:**
INSERT INTO "drug_generic" VALUES(2274, 'Fosinopril Sodium', 'Fosinopril', 'C09AA09', 0, 0, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected during therapy", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue fosinopril as soon as pregnancy is detected."}, {"alert_type": "Angioedema", "severity": "High", "trigger_condition": "Swelling of the face, extremities, eyes, lips, tongue, glottis, or larynx", "message": "STOP: Angioedema associated with laryngeal edema may be fatal. Discontinue immediately and provide appropriate therapy to ensure airway patency."}]', '**Angioedema:** Head and neck angioedema, as well as intestinal angioedema, can occur at any time during treatment. Discontinue immediately if suspected.
INSERT INTO "drug_generic" VALUES(2275, 'Acalabrutinib', 'Acalabrutinib', 'L01EL02', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Severe Hemorrhage", "severity": "High", "trigger_condition": "Concurrent use of antiplatelet or anticoagulant therapies, or upcoming surgery", "message": "WARNING: Serious and fatal hemorrhagic events have occurred. Monitor for bleeding. Consider withholding acalabrutinib for 3-7 days pre- and post-surgery depending on bleeding risk."}, {"alert_type": "Serious Infections", "severity": "High", "trigger_condition": "Development of fever or signs of infection", "message": "WARNING: Serious and fatal infections (bacterial, viral, fungal) have occurred. Monitor closely and consider prophylaxis in patients at increased risk for opportunistic infections."}]', '**Hemorrhage:** Serious hemorrhagic events, including fatal events, have been reported. The risk may be increased in patients receiving antiplatelet or anticoagulant therapies. Monitor for signs of bleeding. Consider the benefit-risk of withholding therapy for 3-7 days pre- and post-surgery.
INSERT INTO "drug_generic" VALUES(2276, 'Cholestyramine', 'Cholestyramine resin', 'C10AC01', 0, 0, 1, 1, 1, 0, 1, 0, '[{"alert_type": "Administration Error", "severity": "High", "trigger_condition": "Ingestion of dry powder", "message": "WARNING: Never ingest the dry powder. Always mix thoroughly with water or other fluids before administration to prevent esophageal distress or severe impaction."}]', '**Hypertriglyceridemia:** Not for use as monotherapy in patients with baseline fasting triglycerides ≥300 mg/dL. Discontinue if triglycerides exceed 400 mg/dL, as bile acid sequestrants can further elevate triglyceride levels.
INSERT INTO "drug_generic" VALUES(2277, 'Bivalirudin', 'Bivalirudin', 'B01AE06', 0, 1, 1, 0, 1, 1, 0, 0, '[{"alert_type": "High Alert Medicine", "severity": "High", "trigger_condition": "Prescribing or administering anticoagulant therapy", "message": "Bivalirudin is a high-alert medication. Errors in dosing or administration can lead to severe, life-threatening bleeding. Strict monitoring of ACT or aPTT is required."}]', '**Bleeding Events:** Bivalirudin increases the risk of bleeding. Hemorrhage can occur at any site. Unexplained falls in hematocrit or blood pressure should lead to a search for a bleeding site. Use with caution in disease states associated with an increased risk of bleeding.
INSERT INTO "drug_generic" VALUES(2278, 'Calcium Pantothenate', 'Calcium Pantothenate', 'A11HA31', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Renal Impairment:** Use with caution; impaired excretion may lead to accumulation.
INSERT INTO "drug_generic" VALUES(2279, 'Mometasone Furoate nasal prep', 'Mometasone Furoate', 'R01AD09', 0, 0, 1, 1, 0, 0, 1, 0, '[{"alert_type": "Adrenal Suppression and Growth Retardation", "severity": "Moderate", "trigger_condition": "Prolonged use of high doses, especially in children", "message": "STOP: Excessive use of intranasal corticosteroids can lead to systemic absorption, causing hypothalamic-pituitary-adrenal (HPA) axis suppression and potential growth retardation in children. Monitor growth routinely in pediatric patients."}]', 'Use with caution in patients with active or quiescent tuberculous infections of the respiratory tract, or untreated fungal, bacterial, systemic viral infections, or ocular herpes simplex.
INSERT INTO "drug_generic" VALUES(2280, 'Factor VIII', 'Antihemophilic Factor (Recombinant or Human)', 'B02BD02', 0, 1, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Neutralizing Antibodies (Inhibitors)", "severity": "High", "trigger_condition": "Lack of clinical response to standard doses", "message": "STOP: Patients may develop neutralizing antibodies (inhibitors) to Factor VIII. If expected plasma factor VIII activity levels are not attained, or if bleeding is not controlled, perform an assay that measures Factor VIII inhibitor concentration."}]', '**Hypersensitivity Reactions:** Allergic-type hypersensitivity reactions, including anaphylaxis, have been reported. Discontinue immediately if symptoms occur.
INSERT INTO "drug_generic" VALUES(2281, 'Bromelain + Trypsin', 'Bromelain and Trypsin', 'M09AB', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Bleeding Risk", "severity": "High", "trigger_condition": "Concurrent use of anticoagulants or upcoming surgery", "message": "STOP: Bromelain has antiplatelet and fibrinolytic properties. It may increase the risk of bleeding during and after surgery, or when used concurrently with anticoagulants/antiplatelets. Discontinue at least 2 weeks prior to elective surgery."}]', 'Use with caution in patients with severe hepatic or renal impairment, as the metabolism and excretion of these enzymes may be altered.
INSERT INTO "drug_generic" VALUES(2282, 'Zinc Oxide + Benzyl Alcohol + Benzyl Benzoate + Benzyl Cinnamate + Lanolin', 'Zinc Oxide + Benzyl Alcohol + Benzyl Benzoate + Benzyl Cinnamate + Lanolin', 'D02AB', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '**Ocular and Mucosal Exposure:** For external use only. Do not allow the product to come into contact with the eyes or mucous membranes. If contact occurs, rinse thoroughly with water.
INSERT INTO "drug_generic" VALUES(2283, 'Ergometrine Maleate', 'Ergonovine', 'G02AB03', 0, 1, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Cardiovascular Risk", "severity": "High", "trigger_condition": "Intravenous administration or use in patients with hypertension", "message": "STOP: Intravenous administration can induce sudden, severe hypertensive and cerebrovascular accidents. Give IV only in life-threatening emergencies over at least 1 minute, with continuous blood pressure monitoring. Contraindicated in pregnancy and prior to delivery of the placenta."}]', '**Cardiovascular Disease:** Use with extreme caution in patients with hypertension, ischemic heart disease, or valvular heart disease. Ergometrine causes potent vasoconstriction and can precipitate angina, myocardial infarction, or hypertensive crisis.
INSERT INTO "drug_generic" VALUES(2284, 'Carbamazepine', 'Carbamazepine', 'N03AF01', 0, 1, 0, 0, 1, 0, 1, 1, '[{"alert_type": "Severe Dermatologic Reactions", "severity": "High", "trigger_condition": "Presence of HLA-B*1502 allele (common in Asian ancestry)", "message": "STOP: Serious and fatal dermatologic reactions (SJS/TEN) can occur. Screen patients of Asian ancestry for the HLA-B*1502 allele prior to initiation."}, {"alert_type": "Aplastic Anemia and Agranulocytosis", "severity": "High", "trigger_condition": "Initiation of therapy or unexplained fever/infection", "message": "STOP: Rare but fatal aplastic anemia and agranulocytosis have been reported. Obtain baseline CBC and monitor closely. Discontinue if significant bone marrow depression develops."}]', '**Suicidal Behavior and Ideation:** Antiepileptic drugs increase the risk of suicidal thoughts or behavior. Monitor for emergence or worsening of depression, suicidal thoughts, or unusual changes in mood or behavior.
INSERT INTO "drug_generic" VALUES(2285, 'Zinc Pyrithione 1% + Polytar 1%', 'Pyrithione Zinc and Coal Tar', 'D05AA', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Application Site Reaction", "severity": "Moderate", "trigger_condition": "Contact with eyes or broken skin", "message": "Avoid contact with eyes, mucous membranes, and inflamed or broken skin. If contact occurs, rinse thoroughly with water."}]', 'Avoid exposure to direct sunlight immediately after application due to the risk of photosensitivity induced by coal tar. Do not apply to acutely inflamed, broken, or infected skin. Discontinue use if severe irritation, worsening of the condition, or allergic reactions occur. Use with caution in patients with impaired peripheral circulation.', '- **Psoriasis:** Relief of scaling, itching, and erythema associated with plaque psoriasis of the scalp or skin.
INSERT INTO "drug_generic" VALUES(2286, 'Calcium Carbonate + Calcium Lactate Gluconate +  Vitamin-C + Vitamin D3', 'Calcium Carbonate, Calcium Lactate Gluconate, Ascorbic Acid, and Cholecalciferol', 'A12AX', 0, 0, 1, 1, 1, 1, 1, 0, '[]', '**Renal Impairment and Hypercalciuria:** Patients with mild to moderate renal failure or mild hypercalciuria should be supervised carefully. Periodic checks of plasma calcium levels and urinary calcium excretion are required. Reduce or stop treatment temporarily if urinary calcium exceeds 7.5 mmol/24 hours.
INSERT INTO "drug_generic" VALUES(2287, 'Salbutamol + Theophylline', 'Albuterol and Theophylline', 'R03AK04', 0, 1, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Theophylline Toxicity", "severity": "High", "trigger_condition": "Serum theophylline levels >20 mcg/mL or concurrent use of CYP1A2 inhibitors", "message": "STOP: Theophylline has a narrow therapeutic index. Toxicity can cause intractable seizures and fatal arrhythmias. Monitor serum levels closely."}, {"alert_type": "Cardiovascular Effects", "severity": "High", "trigger_condition": "Pre-existing arrhythmias or severe ischemic heart disease", "message": "WARNING: Both agents stimulate the cardiovascular system. Can precipitate severe tachycardia, arrhythmias, and hypokalemia."}]', 'Monitor serum theophylline levels routinely; therapeutic range is generally 10-15 mcg/mL. Toxicity risk increases significantly above 20 mcg/mL.
INSERT INTO "drug_generic" VALUES(2288, 'Monosulfiram 25%', 'Monosulfiram', 'P03AA05', 0, 0, 0, 0, 0, 1, 1, 0, '[{"alert_type": "Drug Interaction Risk", "severity": "High", "trigger_condition": "Concurrent alcohol consumption", "message": "STOP: Monosulfiram is structurally related to disulfiram. Concurrent ingestion of alcohol can cause a severe disulfiram-like reaction (flushing, nausea, vomiting, tachycardia)."}]', '**Alcohol Avoidance:** Patients must strictly avoid alcohol consumption during treatment and for at least 48 hours after application due to the risk of a disulfiram-like reaction.
INSERT INTO "drug_generic" VALUES(2289, 'Dofetilide', 'Dofetilide', 'C01BD04', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Proarrhythmic Risk", "severity": "High", "trigger_condition": "Initiation of therapy", "message": "STOP: Dofetilide can cause life-threatening ventricular arrhythmias, particularly Torsades de Pointes. Must be initiated in a facility with continuous ECG monitoring and cardiac resuscitation capabilities for a minimum of 3 days."}]', '**Proarrhythmic Events:** Dofetilide can cause serious ventricular arrhythmias, primarily Torsades de Pointes (TdP), which is dose- and concentration-dependent. Initiation or re-initiation must occur in a setting with continuous ECG monitoring and personnel trained in the management of serious arrhythmias for a minimum of 3 days.
INSERT INTO "drug_generic" VALUES(2290, 'Loratadine', 'Loratadine', 'R06AX13', 0, 0, 1, 1, 1, 0, 1, 0, '[]', '**Hepatic Impairment:** Clearance of loratadine is significantly decreased in patients with severe liver impairment. A lower initial dose is recommended in these patients.
INSERT INTO "drug_generic" VALUES(2291, 'Rifamycin', 'Rifamycin SV', 'A07AA13', 1, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Ineffective for Invasive Diarrhea", "severity": "High", "trigger_condition": "Presence of fever or bloody stool", "message": "STOP: Rifamycin is not effective for diarrhea complicated by fever and/or bloody stool. Discontinue and use alternative therapy if these symptoms are present."}]', '**Not for Invasive Diarrhea:** Rifamycin is not effective in diarrhea complicated by fever and/or bloody stool (indicative of invasive pathogens like *Campylobacter*, *Salmonella*, or *Shigella*). Discontinue use if diarrhea gets worse or persists >48 hours, and consider alternative antibacterial therapy.
INSERT INTO "drug_generic" VALUES(2292, 'Aluminium Hydroxide + Magnesium Hydroxide', 'Aluminum Hydroxide and Magnesium Hydroxide', 'A02AD01', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Drug Interactions", "severity": "Medium", "trigger_condition": "Concurrent administration with other oral medications", "message": "STOP: Antacids significantly decrease the absorption of many drugs (e.g., tetracyclines, fluoroquinolones, bisphosphonates, thyroid hormones). Administer antacids at least 2 hours before or after other medications."}]', '**Renal Impairment:** Use with caution in patients with chronic renal impairment. Magnesium and aluminum can accumulate, leading to hypermagnesemia (muscle weakness, hypotension) and aluminum toxicity (encephalopathy, osteomalacia).
INSERT INTO "drug_generic" VALUES(2293, 'Memantine + Donepezil', 'Memantine and Donepezil', 'N06DX30', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Cardiovascular Effects", "severity": "High", "trigger_condition": "History of cardiac conduction abnormalities", "message": "STOP: Cholinesterase inhibitors may have vagotonic effects on the sinoatrial and atrioventricular nodes, manifesting as severe bradycardia or heart block."}]', '**Gastrointestinal Bleeding:** Increased risk of GI bleed, especially in patients with a history of gastric ulcers or those taking concurrent NSAIDs.
INSERT INTO "drug_generic" VALUES(2294, 'Dextrose 10% + Sodium Chloride 0.9%', 'Dextrose 10% and 0.9% Sodium Chloride', 'B05BB02', 0, 1, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Fluid and Solute Overload", "severity": "High", "trigger_condition": "Rapid infusion or use in heart failure/renal failure", "message": "STOP: High risk of hypernatremia, fluid overload, and pulmonary edema. Monitor electrolytes, fluid balance, and clinical status closely."}]', '**Cardiovascular & Renal Disease:** Use with extreme caution in patients with congestive heart failure, severe renal insufficiency, or edema. High sodium content can exacerbate fluid retention and cardiac decompensation.
INSERT INTO "drug_generic" VALUES(2295, 'Omalizumab', 'Omalizumab', 'R03DX05', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Anaphylaxis", "severity": "High", "trigger_condition": "Administration of omalizumab", "message": "STOP: Anaphylaxis, presenting as bronchospasm, hypotension, syncope, urticaria, and/or angioedema, has been reported after administration. It can occur after the first dose or beyond 1 year of treatment. Administer only in a healthcare setting prepared to manage anaphylaxis."}]', 'Omalizumab is not indicated for the treatment of acute asthma exacerbations, acute bronchospasm, or status asthmaticus. Do not abruptly discontinue systemic or inhaled corticosteroids upon initiating omalizumab; taper gradually under medical supervision. Patients may be at an increased risk of helminthic (parasitic) infections; monitor and treat appropriately. There is a potential increased risk of malignancy, though causality is not definitively established. Eosinophilic conditions, including Churg-Strauss syndrome, may unmask upon reduction of oral corticosteroids. Serum total IgE levels remain elevated for up to 1 year after discontinuation; do not use IgE levels to reassess dosing during this period.', '- **Moderate to Severe Persistent Asthma:** Indicated for adults and pediatric patients 6 years of age and older with a positive skin test or in vitro reactivity to a perennial aeroallergen and whose symptoms are inadequately controlled with inhaled corticosteroids.
INSERT INTO "drug_generic" VALUES(2296, 'Adrenochrome Monosemicarbazone', 'Carbazochrome', 'B02BX02', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Pediatric Dosing Restriction", "severity": "Medium", "trigger_condition": "Administration to premature babies, infants, or young children", "message": "STOP: Because of the diprophylline content (90 mg/mL) in some injectable formulations, the dosage for premature babies, infants, and young children MUST NOT exceed 0.3 mL to avoid toxicity."}]', '**Hypersensitivity:** Allergic reactions, including dyspnea, bronchospasm, and skin rashes, may occur. Discontinue use if hypersensitivity develops.
INSERT INTO "drug_generic" VALUES(2297, 'Sodium Bicarbonate Powder (Haemodialysis solutions)', 'Sodium Bicarbonate (Hemodialysis)', 'B05ZA', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Preparation Error Risk", "severity": "High", "trigger_condition": "Improper mixing or dilution of hemodialysis concentrates", "message": "STOP: Must be properly diluted with purified water and acid concentrate before use. Direct infusion of concentrated solutions will cause fatal electrolyte and acid-base imbalances."}]', '**Acid-Base and Electrolyte Monitoring:** Continuous monitoring of patient fluid balance, serum electrolytes (especially potassium, calcium, and sodium), and acid-base balance is mandatory during hemodialysis.
INSERT INTO "drug_generic" VALUES(2298, 'Ulipristal Acetate', 'Ulipristal Acetate', 'G03AD02', 0, 0, 0, 0, 0, 0, 1, 0, '[{"alert_type": "Pregnancy Exclusion", "severity": "High", "trigger_condition": "Prior to prescribing for uterine fibroids or emergency contraception", "message": "STOP: Ulipristal acetate is contraindicated in known or suspected pregnancy. Exclude pregnancy before initiating treatment."}]', '**Existing Pregnancy:** Not indicated for termination of an existing pregnancy. Pregnancy must be excluded before prescribing.
INSERT INTO "drug_generic" VALUES(2299, 'Isosorbide Mononitrate', 'Isosorbide Mononitrate', 'C01DA14', 0, 0, 0, 0, 0, 0, 0, 1, '[{"alert_type": "Severe Hypotension Risk", "severity": "High", "trigger_condition": "Concomitant use with phosphodiesterase-5 (PDE-5) inhibitors", "message": "STOP: Coadministration with PDE-5 inhibitors (e.g., sildenafil, tadalafil) is strictly contraindicated due to the risk of profound, potentially fatal hypotension."}]', '**Tolerance Development:** Nitrate tolerance may develop after long-term, continuous treatment; an asymmetric dosing schedule providing a 10-14 hour nitrate-free interval is required to maintain efficacy.
INSERT INTO "drug_generic" VALUES(2300, 'Carbinoxamine', 'Carbinoxamine', 'R06AA08', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Pediatric Mortality Risk", "severity": "High", "trigger_condition": "Prescribing for children under 2 years of age", "message": "STOP: Deaths have been reported in children 2 years of age and younger treated with carbinoxamine-containing medications. It is strictly contraindicated in this age group."}]', '**Pediatric Mortality:** Deaths have been reported in children 2 years of age and younger treated with carbinoxamine-containing medications; therefore, it is strictly contraindicated in children aged <2 years.
INSERT INTO "drug_generic" VALUES(2301, 'Eptinezumab', 'Eptinezumab-jjmr', 'N02CD03', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hypersensitivity Reactions", "severity": "High", "trigger_condition": "Signs of angioedema, urticaria, or severe rash during or after infusion", "message": "STOP: Hypersensitivity reactions, including angioedema, urticaria, facial flushing, and rash, have occurred. If a hypersensitivity reaction occurs, discontinue the infusion immediately and institute appropriate therapy."}]', '**Hypersensitivity Reactions:** Serious hypersensitivity reactions, including angioedema, urticaria, facial flushing, and rash, have been reported. These reactions can occur during the infusion or days later. If a hypersensitivity reaction occurs, consider discontinuing treatment and institute appropriate medical therapy.', '- **Migraine Prevention:** Indicated for the preventive treatment of migraine in adults.', '- **Hypersensitivity:** Contraindicated in patients with a known serious hypersensitivity to eptinezumab-jjmr or to any of the excipients. Reactions have included angioedema and severe urticaria.', '- Nasopharyngitis
INSERT INTO "drug_generic" VALUES(2302, 'Glucosamine', 'Glucosamine', 'M01AX05', 0, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Hypersensitivity Risk", "severity": "High", "trigger_condition": "Patient history of shellfish allergy", "message": "STOP: Glucosamine is frequently derived from the exoskeletons of crustaceans. Severe allergic reactions can occur in patients with shellfish allergies."}]', '**Diabetic Patients:** Glucosamine may theoretically impair insulin secretion or induce insulin resistance. Monitor blood glucose levels closely, especially upon initiation or dose adjustment.
INSERT INTO "drug_generic" VALUES(2303, 'Pizotifen', 'Pizotifen', 'N02CX01', 0, 0, 0, 0, 1, 0, 1, 1, '[]', '**Anticholinergic Effects:** Pizotifen possesses weak anticholinergic properties. Use with caution in patients with angle-closure glaucoma, urinary retention, or prostatic hypertrophy.
INSERT INTO "drug_generic" VALUES(2304, 'Tetracaine', 'Tetracaine', 'N01BA03', 0, 1, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Local Anesthetic Systemic Toxicity (LAST)", "severity": "High", "trigger_condition": "Intravascular injection, excessive dosing, or rapid absorption", "message": "STOP: Unintended intravascular injection or excessive dosing can lead to severe central nervous system (seizures, coma) and cardiovascular (arrhythmias, cardiac arrest) toxicity. Resuscitative equipment and lipid emulsion therapy must be immediately available."}]', '- **Preservative-Free Requirement:** Strictly use preservative-free preparations for spinal or epidural anesthesia to prevent neurotoxicity.
INSERT INTO "drug_generic" VALUES(2305, 'Ethinylestradiol + Gestodene', 'Gestodene and Ethinyl Estradiol', 'G03AA10', 0, 0, 0, 0, 1, 0, 1, 0, '[{"alert_type": "Cardiovascular Risk in Smokers", "severity": "High", "trigger_condition": "Patient is >35 years old and smokes cigarettes", "message": "STOP: Cigarette smoking increases the risk of serious cardiovascular events from combination oral contraceptives. This risk increases with age, particularly in women over 35 years of age, and with the number of cigarettes smoked. Contraindicated in women >35 years who smoke."}]', 'Increases the risk of arterial and venous thrombotic diseases (e.g., MI, stroke, DVT, PE). Use with extreme caution in patients who are obese (BMI >30 kg/m2), have hypertension, dyslipoproteinemia, valvular heart disease, or atrial fibrillation. Discontinue use at least 6 weeks before and for 2 weeks after elective surgery involving prolonged immobilization. May increase the severity and frequency of migraines; discontinue if migraines with focal aura develop. May affect glucose tolerance; monitor diabetic patients. Efficacy may be reduced in the event of severe diarrhea or vomiting; backup contraception is required.', '- **Oral Contraception:** Prevention of pregnancy in women who elect to use oral contraceptives as a method of contraception.', '- **High Risk of Thromboembolic Diseases:** Contraindicated in patients with a history of or current DVT, PE, cerebrovascular disease, coronary artery disease, or inherited/acquired hypercoagulopathies.
INSERT INTO "drug_generic" VALUES(2306, 'Saccharin Sodium', 'Saccharin Sodium', 'Data not available', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Possibility of allergic reactions, particularly in individuals with a known sulfonamide allergy, as saccharin is a sulfonamide derivative. Use in moderation as part of a balanced diet.', '- **Sweetening Agent:** Used as a non-caloric artificial sweetener in foods, drinks, candies, cookies, and pharmaceutical formulations to improve palatability.', '- **Hypersensitivity:** Contraindicated in patients with a known severe hypersensitivity to saccharin or sulfonamides.', '- **Common:** Bitter or metallic aftertaste, especially at high concentrations.
INSERT INTO "drug_generic" VALUES(2307, 'Vinpocetine', 'Vinpocetine', 'N06BX18', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Bleeding Risk", "severity": "Moderate", "trigger_condition": "Concurrent use with anticoagulants or antiplatelets", "message": "Caution: Vinpocetine inhibits platelet aggregation. Concurrent use with warfarin, aspirin, or other anticoagulants may increase the risk of bleeding."}]', '**Cardiovascular Disorders:** Use with caution in patients with hypertension, cardiac dysfunction, or arrhythmias. Vinpocetine can cause transient hypotension and tachycardia. Parenteral treatment is contraindicated in severe ischemic heart disease and severe rhythm disorders.
INSERT INTO "drug_generic" VALUES(2308, 'Cefotaxime', 'Cefotaxime', 'J01DD01', 1, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Anaphylaxis and Hypersensitivity", "severity": "High", "trigger_condition": "History of Penicillin or Cephalosporin allergy", "message": "STOP: Severe and potentially fatal hypersensitivity reactions, including anaphylaxis, can occur. Cross-reactivity with penicillins occurs in up to 10% of patients. Verify allergy history before prescribing."}]', '**Clostridioides difficile-Associated Diarrhea (CDAD):** Can occur with use of nearly all antibacterial agents and may range from mild diarrhea to fatal colitis. Evaluate patients who present with diarrhea during or after therapy.
INSERT INTO "drug_generic" VALUES(2309, 'Streptomycin', 'Streptomycin', 'J01GA01', 1, 0, 0, 1, 1, 0, 1, 0, '[{"alert_type": "Ototoxicity, Nephrotoxicity, and Neuromuscular Blockade", "severity": "High", "trigger_condition": "Prolonged use, high doses, renal impairment, or concurrent use with other oto/nephrotoxic drugs", "message": "STOP: Streptomycin can cause severe, irreversible vestibular and auditory ototoxicity, nephrotoxicity, and potentially fatal neuromuscular blockade (respiratory paralysis). Monitor renal and auditory function closely."}]', 'Baseline and periodic assessment of auditory, vestibular, and renal function is mandatory. Use with extreme caution in patients with pre-existing renal impairment, hearing loss, or vestibular dysfunction. Adjust dose carefully in renal impairment to avoid toxic accumulation. Use with caution in patients with neuromuscular disorders such as myasthenia gravis or Parkinson''s disease, as aminoglycosides can exacerbate muscle weakness due to their neuromuscular blocking properties. Ensure adequate hydration to reduce the risk of nephrotoxicity. Use with caution in the elderly and children.', '- **Tuberculosis (TB):** Used as part of a multi-drug regimen for the treatment of active tuberculosis, particularly in severe or resistant cases.
INSERT INTO "drug_generic" VALUES(2310, 'Ciprofibrate', 'Ciprofibrate', 'C10AB08', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Rhabdomyolysis Risk", "severity": "High", "trigger_condition": "Concurrent use with statins or other fibrates, or in patients presenting with unexplained muscle pain", "message": "STOP: Increased risk of severe myopathy and rhabdomyolysis, especially when combined with HMG-CoA reductase inhibitors (statins) or other fibrates. Discontinue if CPK levels are markedly elevated or if myopathy is diagnosed."}]', '**Muscle Toxicity:** Risk of myotoxicity, including rhabdomyolysis. Monitor serum creatine phosphokinase (CPK) levels in patients reporting unexplained muscle pain, tenderness, or weakness. Consider monitoring liver function and CPK when used in combination with a statin.
INSERT INTO "drug_generic" VALUES(2311, 'Vilazodone', 'Vilazodone', 'N06AX24', 0, 0, 0, 0, 0, 1, 0, 1, '[{"alert_type": "Suicidal Thoughts and Behaviors", "severity": "High", "trigger_condition": "Initiation of therapy or dosage changes in children, adolescents, and young adults", "message": "STOP: Antidepressants increase the risk of suicidal thinking and behavior in children, adolescents, and young adults. Monitor all patients closely for clinical worsening, suicidality, or unusual changes in behavior."}]', '- **Serotonin Syndrome:** Potentially life-threatening serotonin syndrome can occur, especially when co-administered with other serotonergic agents (e.g., SSRIs, SNRIs, triptans, amphetamines, MAOIs). Monitor for mental status changes, autonomic instability, and neuromuscular abnormalities.
INSERT INTO "drug_generic" VALUES(2312, 'Bisoprolol + Amlodipine', 'Bisoprolol/Amlodipine', 'C07FB07', 0, 0, 0, 0, 1, 1, 0, 1, '[{"alert_type": "Abrupt Discontinuation", "severity": "High", "trigger_condition": "Sudden cessation of therapy", "message": "STOP: Do not stop therapy abruptly, especially in patients with ischemic heart disease. Severe exacerbation of angina, myocardial infarction, and ventricular arrhythmias can occur. Taper gradually."}]', '**Ischemic Heart Disease:** Avoid abrupt discontinuation. Taper the dose gradually over 1 to 2 weeks to prevent rebound angina or myocardial infarction.
INSERT INTO "drug_generic" VALUES(2313, 'Pramoxine + Allantoin topical', 'Pramoxine and Allantoin', 'D04AB', 0, 0, 1, 1, 0, 1, 1, 0, '[]', '- **Ocular Exposure:** For external use only. Do not use in the eyes.
INSERT INTO "drug_generic" VALUES(2314, 'Diacerein + Glucosamine Sulphate', 'Diacerein / Glucosamine Sulfate', 'M01AX21', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Hepatotoxicity and Severe Diarrhea", "severity": "High", "trigger_condition": "Patients presenting with elevated liver enzymes or severe gastrointestinal distress.", "message": "STOP: Diacerein is associated with severe diarrhea and hepatotoxicity. Monitor liver function tests regularly and discontinue if significant elevations or severe diarrhea occur."}]', '**Hepatic Monitoring:** Regular monitoring of liver function tests (LFTs) is required due to the risk of diacerein-induced hepatotoxicity. Avoid in patients with pre-existing liver disease.
INSERT INTO "drug_generic" VALUES(2315, 'Neomycin Sulphate Topical', 'Neomycin Sulfate Topical', 'D06AX04', 1, 0, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Sensitization Risk", "severity": "Moderate", "trigger_condition": "Prolonged topical application", "message": "Caution: Neomycin is a known contact sensitizer. Prolonged use increases the risk of allergic contact dermatitis. Discontinue if irritation or hypersensitivity develops."}]', '- **Prolonged Therapy:** Long-term continuous topical therapy should be avoided where possible, particularly in infants and children, due to the risk of systemic absorption and sensitization.
INSERT INTO "drug_generic" VALUES(2316, 'Dexrabeprazole Sodium', 'Dexrabeprazole Sodium', 'A02BC04', 0, 0, 0, 0, 0, 0, 0, 0, '[]', '**Gastric Malignancy:** Symptomatic response to therapy with dexrabeprazole does not preclude the presence of gastric malignancy. Evaluate for malignancy in patients presenting with alarm symptoms (e.g., unintentional weight loss, dysphagia, hematemesis).
INSERT INTO "drug_generic" VALUES(2317, 'Hypromellose 0.3 % Eye prep', 'Hypromellose Ophthalmic', 'S01XA20', 0, 0, 1, 1, 0, 1, 1, 0, '[]', 'Discontinue use and consult a physician if you experience severe eye pain, changes in vision, continued redness, or irritation of the eye.
INSERT INTO "drug_generic" VALUES(2318, 'Miscellaneous Topical Agents', 'Miscellaneous Topical Agents', 'D11AX', 0, 0, 1, 1, 0, 1, 1, 0, '[{"alert_type": "Application Site Warning", "severity": "Low", "trigger_condition": "Application to compromised skin", "message": "For external use only. Discontinue immediately if localized severe hypersensitivity, burning, or contact dermatitis occurs. Prolonged occlusive dressing increases systemic exposure and risk of adverse effects."}]', '**Systemic Absorption:** While topical agents are designed for local effect, application over large surface areas, on broken skin, or under occlusive dressings can lead to significant systemic absorption and potential toxicity (depending on the active ingredient).
INSERT INTO "drug_generic" VALUES(2319, 'Elemental Iron + Folic Acid + Vitamin C + Zinc', 'Iron / Folic Acid / Ascorbic Acid / Zinc', 'B03AE', 0, 0, 1, 1, 0, 1, 0, 0, '[{"alert_type": "Pediatric Toxicity", "severity": "High", "trigger_condition": "Accidental ingestion by children", "message": "STOP: Accidental overdose of iron-containing products is a leading cause of fatal poisoning in children under 6. Keep this product strictly out of reach of children."}]', '- **Iron Overload:** Caution should be exercised in conditions where there is a high risk of iron overload, such as hemochromatosis, thalassemia, hemosiderosis, or hemolytic anemia. Monitor iron indices periodically.
INSERT INTO "drug_generic" VALUES(2320, 'Fondaparinux', 'Fondaparinux Sodium', 'B01AX05', 0, 1, 1, 0, 1, 0, 0, 0, '[{"alert_type": "Spinal/Epidural Hematoma", "severity": "High", "trigger_condition": "Neuraxial anesthesia or spinal puncture", "message": "STOP: Patients receiving fondaparinux who undergo spinal/epidural anesthesia or spinal puncture are at risk for developing an epidural or spinal hematoma, which can result in long-term or permanent paralysis."}]', '**Bleeding Risk:** Use with extreme caution in conditions with increased risk of hemorrhage, such as congenital or acquired bleeding disorders, active GI ulceration, recent intracranial hemorrhage, or recent brain, spinal, or ophthalmic surgery.
INSERT INTO "drug_generic" VALUES(2321, 'Estriol', 'Estriol', 'G03CA04', 0, 0, 0, 0, 1, 0, 0, 1, '[{"alert_type": "Endometrial Hyperplasia Risk", "severity": "High", "trigger_condition": "Prolonged use of high doses without progestogen opposition", "message": "STOP: To prevent endometrial stimulation, the daily oral dose should not exceed 8 mg, and maximum doses should not be used for longer than several weeks. Monitor for abnormal bleeding."}]', 'Monitor patients with a history of thrombosis, severe liver disorders, porphyria, or a history of severe pruritus, cholestatic jaundice, herpes gestationis, or otosclerosis during pregnancy. Estrogens may cause fluid retention; use with caution in patients with cardiac or renal dysfunction. Yearly medical examinations are advisable for all patients on hormone replacement therapy. Concomitant specific treatment is recommended if vaginal infections are present. Ensure adequate diagnostic measures are taken to rule out malignancy in cases of undiagnosed persistent or recurring abnormal vaginal bleeding.', '- **Menopausal Atrophic Vaginitis:** Treatment of dryness, itching, and dyspareunia due to estrogen deficiency.
INSERT INTO "drug_generic" VALUES(2322, 'Hydrochlorothiazide + Irbesartan', 'Irbesartan and Hydrochlorothiazide', 'C09DA04', 0, 0, 0, 0, 1, 0, 0, 0, '[{"alert_type": "Fetal Toxicity", "severity": "High", "trigger_condition": "Pregnancy detected", "message": "STOP: Drugs that act directly on the renin-angiotensin system can cause injury and death to the developing fetus. Discontinue immediately if pregnancy is detected."}]', '**Fetal Toxicity:** Can cause fetal harm when administered to a pregnant woman. Discontinue as soon as pregnancy is detected.
INSERT INTO "drug_generic" VALUES(2323, 'Temozolomide Hydrochloride', 'Temozolomide', 'L01AX03', 0, 1, 0, 0, 1, 1, 1, 0, '[{"alert_type": "Myelosuppression", "severity": "High", "trigger_condition": "Initiation of therapy or dose escalation", "message": "STOP: Severe myelosuppression (thrombocytopenia and neutropenia) can occur. Monitor complete blood counts (CBC) prior to dosing, on Day 22, and weekly until recovery. Do not initiate if ANC <1,500/mm3 or platelets <100,000/mm3."}]', '**Myelosuppression:** Severe and prolonged myelosuppression, including fatal cases of aplastic anemia, can occur. Monitor CBC strictly. Dose reductions or interruptions are required based on nadir counts.
INSERT INTO "drug_generic" VALUES(2324, 'Epalrestat', 'Epalrestat', NULL, 0, 0, 0, 0, 0, 1, 0, 0, '[]', '- **Urine Discoloration:** Urine may turn yellowish-brown or reddish after taking the medicine; this is a harmless effect attributed to the drug''s components.
INSERT INTO "drug_generic" VALUES(2325, 'Sucralfate', 'Sucralfate', 'A02BX02', 0, 0, 1, 1, 1, 1, 1, 0, '[{"alert_type": "Aluminum Toxicity", "severity": "High", "trigger_condition": "Patients with chronic renal failure", "message": "Systemic aluminum toxicity may occur in patients with chronic renal failure due to the absorption of small amounts of aluminum from sucralfate. Avoid prolonged use in severe renal impairment."}]', '**Renal Impairment:** Use with caution in patients with chronic renal failure due to the risk of systemic aluminum accumulation and toxicity.
INSERT INTO "drug_generic" VALUES(2326, 'Paracetamol + Pseudoephedrine + Guaifenesin', 'Acetaminophen, Pseudoephedrine, and Guaifenesin', 'N02BE51', 0, 0, 0, 0, 0, 0, 0, 0, '[{"alert_type": "Hepatotoxicity", "severity": "High", "trigger_condition": "Exceeding maximum daily dose or concurrent alcohol use", "message": "STOP: Paracetamol (acetaminophen) can cause severe, potentially fatal hepatotoxicity. Do not exceed 4,000 mg per day from all sources. Avoid concurrent use of other paracetamol-containing products."}]', '**Hepatotoxicity:** Paracetamol has been associated with cases of acute liver failure, at times resulting in liver transplant and death. Most cases involve the use of paracetamol at doses that exceed 4,000 mg per day. Caution is advised in chronic alcoholics or patients with underlying hepatic disease.
INSERT INTO "drug_generic" VALUES(2327, 'Triamcinolone Acetonide Nasal prep', 'Triamcinolone Acetonide Nasal Spray', 'R01AD11', 0, 0, 0, 1, 0, 1, 1, 0, '[{"alert_type": "Nasal Septum Perforation and Wound Healing", "severity": "High", "trigger_condition": "Recent nasal surgery, trauma, or septal ulcers", "message": "STOP: Corticosteroids impair wound healing. Delay initiation of treatment in patients with recent nasal septal ulcers, nasal surgery, or nasal trauma until complete healing has occurred."}]', '**Infections:** Corticosteroids can suppress the immune system. Use with extreme caution in patients with untreated localized infections involving the nasal mucosa, active or quiescent tuberculosis, untreated fungal, bacterial, or systemic viral infections, or ocular herpes simplex. Susceptible patients may experience a more serious or fatal course of chickenpox or measles.
INSERT INTO "drug_generic" VALUES(2328, 'Brolucizumab Intravitreal Inj', 'Brolucizumab', 'S01LA06', 0, 1, 0, 0, 0, 1, 0, 0, '[{"alert_type": "Ocular Toxicity and Thromboembolic Events", "severity": "High", "trigger_condition": "Post-intravitreal injection", "message": "STOP: Risk of endophthalmitis, retinal detachment, and severe retinal vasculitis/vascular occlusion. Monitor for vision changes. Potential risk of arterial thromboembolic events (ATE) following intravitreal VEGF inhibitors."}]', '**Endophthalmitis and Retinal Detachment:** Intravitreal injections have been associated with endophthalmitis and retinal detachment. Proper aseptic injection technique must always be used. Instruct patients to report any symptoms suggestive of these conditions without delay.
INSERT INTO "drug_generic" VALUES(2329, 'Dipyridamole', 'Dipyridamole', 'B01AC07', 0, 0, 1, 0, 0, 0, 1, 0, '[{"alert_type": "Coronary Steal Syndrome", "severity": "High", "trigger_condition": "Use in patients with severe coronary artery disease or unstable angina", "message": "STOP: Dipyridamole possesses vasodilatory properties that may cause ''coronary steal,'' exacerbating angina or inducing myocardial ischemia in patients with severe coronary artery disease."}]', '- **Cardiovascular Disease:** Use with extreme caution in patients with rapidly worsening angina, subvalvular aortic stenosis, or hemodynamic instability associated with a recent myocardial infarction. Dipyridamole can cause peripheral vasodilation, leading to hypotension and compensatory tachycardia.
INSERT INTO "drug_generic" VALUES(2330, 'Cannabidiol', 'Cannabidiol', 'N03AX24', 0, 0, 0, 0, 0, 0, 1, 1, '[{"alert_type": "Hepatotoxicity Risk", "severity": "High", "trigger_condition": "Concomitant use with valproate or pre-existing hepatic impairment", "message": "Dose-related elevations in liver transaminases and bilirubin can occur. Monitor liver function tests at baseline and periodically. Risk is significantly increased when co-administered with valproate."}]', '**Hepatotoxicity:** Dose-related elevations in liver transaminases (ALT and AST) and bilirubin have been reported. Monitor liver function at baseline, at 1, 3, and 6 months of treatment, and periodically thereafter. Restart the monitoring schedule if the dose increases above 10 mg/kg/day. Withhold or discontinue treatment if transaminase levels increase significantly or symptoms of hepatic dysfunction occur.
INSERT INTO "drug_generic" VALUES(2331, 'Xylometazoline Hydrochloride 0.1% Nasal prep', 'Xylometazoline', 'R01AA07', 0, 0, 0, 0, 0, 1, 0, 0, '[]', 'Prolonged use or abuse (greater than 3 to 5 days) may lead to rebound congestion (rhinitis medicamentosa) and drug-induced rhinitis. Use with caution in patients with hypertension, cardiovascular disease, hyperthyroidism, diabetes mellitus, prostatic hypertrophy, or narrow-angle glaucoma due to potential systemic sympathomimetic effects.', '- **Nasal Congestion:** Symptomatic relief of nasal congestion associated with the common cold, sinusitis, and seasonal or perennial allergic rhinitis.', '- **Hypersensitivity:** Contraindicated in patients with a known hypersensitivity to xylometazoline or any component of the formulation.
